# ================== REGEX PATTERN CACHING UTILITIES ===================
# ======================================================================
# LRU-cached regex compilation to reduce redundant re.compile() calls
_REGEX_CACHE_SIZE = 2048


@lru_cache(maxsize=_REGEX_CACHE_SIZE)
def compile_pattern(pattern: str, flags: int = 0) -> Pattern[str]:
    """LRU-cached regex pattern compilation."""
    return re.compile(pattern, flags)


def cached_search(pattern: str, string: str, flags: int = 0) -> Optional[re.Match[str]]:
    """Regex search with cached pattern compilation."""
    return compile_pattern(pattern, flags).search(string)


def cached_match(pattern: str, string: str, flags: int = 0) -> Optional[re.Match[str]]:
    """Regex match with cached pattern compilation."""
    return compile_pattern(pattern, flags).match(string)


def _question_has_grouping_intent(question: str) -> bool:
    """
    Shared lexical grouping cue detector used by lightweight guardrails.

    Keep this generic and paraphrase-friendly so helpers can reason about
    grouped/iterative intent without hardcoding one wording family such as
    only "for each".
    """
    q = (question or "").strip().lower()
    if not q:
        return False
    return any(re.search(pat, q, flags=re.I) for pat in HELPERS_GROUPING_INTENT_PATTERNS)


def _question_has_count_intent(question: str) -> bool:
    """
    Shared count-intent detector for helper-level guardrails.

    Count requests are intentionally narrower than generic metric cues like
    "total", because COUNT(*) rewrites should only trigger for explicit
    counting language.
    """
    q = (question or "").strip().lower()
    if not q:
        return False
    if any(term in q for term in HELPERS_COUNT_INTENT_TERMS):
        return True
    return bool(re.search(r"\bcount(?:ing)?\b", q, flags=re.I))


def cached_sub(pattern: str, repl: str, string: str, count: int = 0, flags: int = 0) -> str:
    """Regex substitution with cached pattern compilation."""
    return compile_pattern(pattern, flags).sub(repl, string, count=count)


def cached_findall(pattern: str, string: str, flags: int = 0) -> list:
    """Regex findall with cached pattern compilation."""
    return compile_pattern(pattern, flags).findall(string)


def cached_split(pattern: str, string: str, maxsplit: int = 0, flags: int = 0) -> list[str]:
    """Regex split with cached pattern compilation."""
    return compile_pattern(pattern, flags).split(string, maxsplit=maxsplit)


def _semantic_question_tokens(text: str) -> Set[str]:
    raw = re.sub(
        r"([a-z0-9])([A-Z])",
        r"\1 \2",
        str(text or "").replace("_", " ").replace("-", " ").lower(),
    )
    stopwords = semantic_question_token_stopwords()
    return {
        tok
        for tok in re.findall(r"[a-z0-9]+", raw)
        if len(tok) >= 3 and tok not in stopwords
    }


def _question_mentions_phrase(text: str, phrase: str) -> bool:
    q = str(text or "").strip().lower()
    p = re.sub(r"\s+", " ", str(phrase or "").strip().lower())
    if not q or not p:
        return False
    pattern = re.escape(p).replace(r"\ ", r"\s+")
    return bool(re.search(rf"\b{pattern}\b", q, flags=re.I))


def _question_mentions_any_phrase(text: str, phrases: Sequence[str]) -> bool:
    q = str(text or "").strip().lower()
    if not q:
        return False
    return any(_question_mentions_phrase(q, phrase) for phrase in (phrases or ()))


@lru_cache(maxsize=1)
def _winner_row_schema_temporal_phrases() -> Tuple[str, ...]:
    phrases: Set[str] = set()
    for table in sorted(get_all_tables()):
        try:
            date_cols = get_columns_by_role(table, "date") or []
        except Exception:
            date_cols = []
        for col in date_cols:
            try:
                variants = get_column_entity_variants(table, col) or set()
            except Exception:
                variants = {str(col or "").strip().lower()}
            for variant in variants:
                phrase = re.sub(r"\s+", " ", str(variant or "").replace("_", " ").strip().lower())
                if phrase and len(phrase) >= 3:
                    phrases.add(phrase)
    return tuple(sorted(phrases, key=lambda item: (-len(item), item)))


@lru_cache(maxsize=1)
def _latest_year_metric_question_terms() -> Set[str]:
    metric_terms: Set[str] = {
        str(term or "").strip().lower()
        for term in latest_year_scope_aggregate_terms()
        if str(term or "").strip()
    }
    for table in sorted(get_all_tables()):
        try:
            numeric_cols = get_columns_by_role(table, "numeric") or []
        except Exception:
            numeric_cols = []
        for col in numeric_cols:
            role = str(get_column_role(table, col) or "").strip().lower()
            if role in {"metric", "measure", "amount", "quantity"}:
                metric_terms.add(role)
            try:
                variants = get_column_entity_variants(table, col) or set()
            except Exception:
                variants = {str(col or "").strip().lower()}
            for variant in variants:
                metric_terms.update(_semantic_question_tokens(variant))
            try:
                metric_terms.update(_semantic_question_tokens(get_column_description(table, col)))
            except Exception:
                pass
    return {term for term in metric_terms if term}

# ======================================================================
# ===================== SQL ALIAS & KEYWORD CONSTANTS ==================
# ======================================================================
_RESERVED_ALIASES = {
    "or", "and", "on", "as", "in", "is", "by", "from", "join", "where",
    "group", "order", "limit", "select", "left", "right", "inner", "outer",
    "having", "union", "cross", "natural",
    # MySQL 8.0+ window function keywords (reserved)
    "rank", "dense_rank", "row_number", "ntile", "lead", "lag",
    "first_value", "last_value", "nth_value", "cume_dist", "percent_rank"
}
_SQL_KEYWORDS = {
    "select","from","where","group","by","order","limit","join","left","right","inner",
    "on","and","or","not","as","distinct","count","sum","avg","min","max","having",
    "asc","desc","like","in","between","is","null","case","when","then","else","end",
    "regexp","rlike","over","partition","row_number",
    "union","all","except","intersect"
}
_JOIN_KW = r"(?:inner\s+join|left\s+join|right\s+join|full\s+join|join)"
# =======================================================================
# ================= Phase 0 — Syntax & Canonicalization =================
# =============== Normalize tokens and table naming early ===============
# =======================================================================
# - should_use_backtick
# - smart_badtick
# - split_qualified
# - fix_bad_backticks
# - parse_allowed_identifiers
# - canonicalize_table_names
# - alias_for_table
# - split_outside_quotes
# - has_join

def _should_use_backtick(identifier: str) -> bool:
    if not identifier: return False
    clean = identifier.strip('`"')
    if not clean: return False
    first_char = clean[0]
    if first_char.isupper() or first_char.isdigit():
        return True
    if not re.match(r'^[a-z_][a-z0-9_]*$', clean, re.I):
        return True
    return False

def _smart_backtick(identifier: str) -> str:
    clean = identifier.strip('`"')
    return f"`{clean}`" if _should_use_backtick(clean) else clean

def _split_qualified(name: str) -> List[str]:
    return [p.strip('`" ') for p in name.split(".") if p.strip("\"` ")]

def _fix_bad_backticks(sql: str) -> str:
    quoted_ident_part = r"[A-Za-z_][A-Za-z0-9_]*"
    quoted_ident_path = rf"{quoted_ident_part}(?:\.{quoted_ident_part})+"

    def repl_fqn(m: re.Match) -> str:
        inside = m.group(1)
        if "." not in inside:
            return _smart_backtick(inside)
        parts = _split_qualified(inside)
        if len(parts) == 0:
            return inside
        return ".".join(_smart_backtick(p) for p in parts)

    # Only rewrite contiguous identifier paths. Do not span across SELECT
    # aliases like `full name`, which are valid output labels, not qualified
    # identifiers.
    sql = re.sub(rf"`({quoted_ident_path})`", repl_fqn, sql)
    sql = re.sub(rf"(\b[A-Za-z_][\w]*)\.`({quoted_ident_part}(?:\.{quoted_ident_part})*)`",
                 lambda m: f"{_smart_backtick(m.group(1))}."
                           + ".".join(_smart_backtick(p) for p in _split_qualified(m.group(2))), sql)
    sql = re.sub(rf"`({quoted_ident_part}(?:\.{quoted_ident_part})*)`\.(\b[A-Za-z_][\w]*)",
                 lambda m: ".".join(_smart_backtick(p) for p in _split_qualified(m.group(1)))
                           + f".{_smart_backtick(m.group(2))}", sql)
    sql = re.sub(r'`([^`]+?)`(?!\s*\.)', lambda m: _smart_backtick(m.group(1)), sql, flags=re.I)
    return sql

def _escape_reserved_column_aliases(sql: str) -> str:
    """
    Escape column aliases that are MySQL reserved keywords.
    E.g.: AS rank -> AS `rank`
    
    Pattern: ... AS <alias> (where alias is NOT already backticked)
    Only applies to SELECT clause column aliases, not table aliases.
    """
    if not sql:
        return sql
    
    # Pattern to find: ) AS alias or expr AS alias (column alias in SELECT)
    # Must NOT match table aliases (FROM/JOIN table AS alias)
    # Focus on common patterns: aggregate/window function result aliases
    
    def escape_alias(m: re.Match) -> str:
        prefix = m.group(1)  # ") AS " or similar
        alias = m.group(2)
        
        # Skip if already backticked
        if alias.startswith('`'):
            return m.group(0)
        
        # Check if alias is reserved
        if alias.lower() in _RESERVED_ALIASES:
            return f"{prefix}`{alias}`"
        return m.group(0)
    
    # Match: ) AS alias or , expr AS alias (typical SELECT alias patterns)
    # Negative lookbehind to skip FROM/JOIN table aliases
    sql = re.sub(
        r'(\)\s+AS\s+)([A-Za-z_][A-Za-z0-9_]*)\b(?!\s*\.)',
        escape_alias,
        sql,
        flags=re.I
    )
    return sql


def _canonicalize_unsafe_output_aliases(sql: str) -> str:
    """
    Canonicalize unsafe top-level SELECT output aliases into valid MySQL aliases.

    Scope is intentionally conservative:
    - flat top-level SELECT ... FROM ... shapes only
    - skip subqueries / derived tables entirely
    - preserve already-valid identifier aliases

    This prevents natural-language aliases such as:
      AS subordinate's employee number
    from cascading into malformed backtick repairs and parse errors.
    """
    text = str(sql or "").strip()
    if not text or " as " not in text.lower():
        return sql
    if re.search(r"(?is)\(\s*select\b", text) or re.search(r"(?is)\b(?:from|join)\s*\(", text):
        return sql

    m = re.match(r"(?is)^(?P<prefix>\s*select\s+)(?P<select>.+?)(?P<suffix>\s+from\b.*)$", text)
    if not m:
        return sql

    select_clause = str(m.group("select") or "")

    def _split_items_top_level(segment: str) -> List[str]:
        items: List[str] = []
        depth = 0
        start = 0
        for idx, ch in enumerate(segment):
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif ch == "," and depth == 0:
                items.append(segment[start:idx].strip())
                start = idx + 1
        tail = segment[start:].strip()
        if tail:
            items.append(tail)
        return items

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        depth = 0
        in_sq = False
        in_dq = False
        in_bt = False
        last_as = -1
        low = item.lower()
        i = 0
        while i < len(item):
            ch = item[i]
            if ch == "\\" and (in_sq or in_dq) and i + 1 < len(item):
                i += 2
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(item) and item[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                if in_dq and i + 1 < len(item) and item[i + 1] == '"':
                    i += 2
                    continue
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and low.startswith(" as ", i):
                last_as = i
            i += 1

        if last_as < 0:
            return item.strip(), None
        expr = item[:last_as].strip()
        alias = item[last_as + 4:].strip()
        return expr, alias or None

    def _safe_identifier_alias(alias_text: str) -> str:
        raw = re.sub(r"\\([`'\"])", r"\1", str(alias_text or ""))
        raw = re.sub(r"\s+", " ", raw).strip()
        if not raw:
            return ""
        normalized = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", raw)
        normalized = normalized.replace("&", " and ")
        normalized = re.sub(r"[^A-Za-z0-9]+", "_", normalized).strip("_").lower()
        normalized = re.sub(r"_+", "_", normalized)
        if not normalized:
            return ""
        if normalized[0].isdigit():
            normalized = f"col_{normalized}"
        if normalized in _RESERVED_ALIASES:
            normalized = f"{normalized}_value"
        return normalized

    def _alias_sql(alias_text: str) -> Optional[str]:
        raw = str(alias_text or "").strip()
        if not raw:
            return None
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", raw) and raw.lower() not in _RESERVED_ALIASES:
            return raw

        if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {"`", "'", '"'}:
            raw = raw[1:-1].strip()
        else:
            raw = raw.strip("`'\" ")

        raw = re.sub(r"\s+", " ", raw).strip()
        if not raw:
            return None
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", raw) and raw.lower() not in _RESERVED_ALIASES:
            return raw
        if raw.lower() in _RESERVED_ALIASES:
            return f"`{raw}`"
        safe_alias = _safe_identifier_alias(raw)
        if safe_alias:
            return safe_alias
        return _smart_backtick(raw)

    new_items: List[str] = []
    changed = False
    for item in _split_items_top_level(select_clause):
        expr, alias = _split_expr_alias(item)
        if not alias:
            new_items.append(item)
            continue
        alias_sql = _alias_sql(alias)
        if not alias_sql:
            new_items.append(expr)
            changed = True
            continue
        rebuilt = f"{expr} AS {alias_sql}"
        if rebuilt != item:
            changed = True
        new_items.append(rebuilt)

    if not changed:
        return sql
    return f"{m.group('prefix')}{', '.join(new_items)}{m.group('suffix')}"


def _rewrite_derived_self_join_lookup_subquery(sql: str, question: str, ctx: str = "") -> str:
    """
    Flatten a malformed hierarchy lookup draft shaped like:

      SELECT ...
      FROM (
        SELECT ...
        FROM base child
        JOIN base parent ON child.self_fk = parent.id
      ) AS d
      JOIN lookup l ON d.<wrong_col> = l.<key>

    into a flat same-table self-join lookup query. This is intentionally narrow:
    - lookup-style questions only
    - exactly one same-table self-join inside the derived table
    - no GROUP BY / HAVING / UNION / WINDOW shapes
    - at most one outer lookup/reference table is reattached
    """
    s = str(sql or "").strip()
    q = str(question or "").strip()
    q_l = q.lower()
    if not s or not q:
        return sql
    if re.search(r"\b(?:group\s+by|having|union|intersect|except|with)\b", s, flags=re.I):
        return sql
    if re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql
    if "from (" not in s.lower():
        return sql
    if not any(tok in q_l for tok in ("manager", "supervisor", "reports to", "reporting", "subordinate", "boss", "parent")):
        return sql

    trailing_semicolon = ";" if s.endswith(";") else ""
    s_core = s[:-1].rstrip() if trailing_semicolon else s
    m_outer = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+\bFROM\b\s+(?P<rest>.+)$", s_core)
    if not m_outer:
        return sql

    outer_select = str(m_outer.group("select") or "").strip()
    outer_rest = str(m_outer.group("rest") or "").strip()
    if not outer_select or not outer_rest.startswith("("):
        return sql

    depth = 0
    in_sq = False
    in_dq = False
    close_idx = -1
    for i, ch in enumerate(outer_rest):
        if ch == "'" and not in_dq:
            if in_sq and i + 1 < len(outer_rest) and outer_rest[i + 1] == "'":
                continue
            in_sq = not in_sq
            continue
        if ch == '"' and not in_sq:
            in_dq = not in_dq
            continue
        if in_sq or in_dq:
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                close_idx = i
                break
    if close_idx < 0:
        return sql

    inner_sql = outer_rest[1:close_idx].strip()
    after_inner = outer_rest[close_idx + 1:].strip()
    if not inner_sql or not after_inner:
        return sql

    m_after = re.match(r"(?is)^(?:AS\s+)?(?P<derived_alias>[A-Za-z_][A-Za-z0-9_]*)(?P<tail>.*)$", after_inner)
    if not m_after:
        return sql
    derived_alias = str(m_after.group("derived_alias") or "").strip()
    outer_tail = str(m_after.group("tail") or "").strip()
    if not derived_alias:
        return sql

    m_inner = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+\bFROM\b\s+(?P<rest>.+)$", inner_sql)
    if not m_inner:
        return sql
    inner_select = str(m_inner.group("select") or "").strip()
    inner_rest = str(m_inner.group("rest") or "").strip()
    if not inner_select or not inner_rest:
        return sql

    def _find_kw(text: str, keyword: str, start: int = 0) -> int:
        t = str(text or "")
        kw = str(keyword or "").upper()
        if not t or not kw:
            return -1
        up = t.upper()
        depth = 0
        in_sq = False
        in_dq = False
        i = max(0, int(start))
        while i < len(t):
            ch = t[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(t) and t[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and up.startswith(kw, i):
                left_ok = i == 0 or not (up[i - 1].isalnum() or up[i - 1] == "_")
                right_idx = i + len(kw)
                right_ok = right_idx >= len(up) or not (up[right_idx].isalnum() or up[right_idx] == "_")
                if left_ok and right_ok:
                    return i
            i += 1
        return -1

    inner_where_pos = _find_kw(inner_rest, "WHERE")
    inner_order_pos = _find_kw(inner_rest, "ORDER BY")
    inner_group_pos = _find_kw(inner_rest, "GROUP BY")
    if inner_where_pos >= 0 or inner_group_pos >= 0:
        return sql
    inner_from_core = inner_rest[:inner_order_pos].strip() if inner_order_pos >= 0 else inner_rest
    if not inner_from_core:
        return sql

    inner_alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {inner_from_core}")
    if len(inner_alias_map) < 2:
        return sql

    source_pairs: List[Tuple[str, str]] = []
    seen_aliases: Set[str] = set()
    for m_tbl in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?""",
        f"FROM {inner_from_core}",
    ):
        raw_tbl = (m_tbl.group(1) or "").replace("`", "").strip()
        table_l = raw_tbl.split(".")[-1].lower()
        if not table_l:
            continue
        alias_raw = (m_tbl.group(2) or "").strip()
        alias = (alias_raw or table_l).strip()
        alias_l = alias.lower()
        if not alias_l or alias_l in seen_aliases:
            continue
        seen_aliases.add(alias_l)
        source_pairs.append((alias, table_l))
    if len(source_pairs) < 2:
        return sql

    base_table = source_pairs[0][1]
    if source_pairs[1][1] != base_table:
        return sql

    try:
        base_id_col = str(get_id_column(base_table) or "").strip("`")
    except Exception:
        base_id_col = ""
    if not base_id_col:
        return sql
    base_id_l = base_id_col.lower()

    child_alias = ""
    parent_alias = ""
    self_fk_col = ""
    self_join_on = ""
    for m_eq in re.finditer(
        r"""(?is)`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
        inner_from_core,
    ):
        left_a, left_c = str(m_eq.group(1) or "").strip(), str(m_eq.group(2) or "").strip()
        right_a, right_c = str(m_eq.group(3) or "").strip(), str(m_eq.group(4) or "").strip()
        left_t = str(inner_alias_map.get(left_a) or inner_alias_map.get(left_a.lower()) or "").strip().lower()
        right_t = str(inner_alias_map.get(right_a) or inner_alias_map.get(right_a.lower()) or "").strip().lower()
        if not left_t or left_t != right_t or left_t != base_table:
            continue
        if left_c.lower() != base_id_l and right_c.lower() == base_id_l:
            child_alias, parent_alias, self_fk_col = left_a, right_a, left_c
            self_join_on = m_eq.group(0)
            break
        if right_c.lower() != base_id_l and left_c.lower() == base_id_l:
            child_alias, parent_alias, self_fk_col = right_a, left_a, right_c
            self_join_on = m_eq.group(0)
            break
    if not child_alias or not parent_alias or not self_fk_col or not self_join_on:
        return sql

    def _split_top_level_csv(text: str) -> List[str]:
        items: List[str] = []
        buf: List[str] = []
        depth = 0
        in_sq = False
        in_dq = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    buf.append(ch)
                    buf.append(text[i + 1])
                    i += 2
                    continue
                in_sq = not in_sq
                buf.append(ch)
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                buf.append(ch)
                i += 1
                continue
            if not in_sq and not in_dq:
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth = max(0, depth - 1)
                elif ch == "," and depth == 0:
                    item = "".join(buf).strip()
                    if item:
                        items.append(item)
                    buf = []
                    i += 1
                    continue
            buf.append(ch)
            i += 1
        tail = "".join(buf).strip()
        if tail:
            items.append(tail)
        return items

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            str(item or "").strip(),
        )
        if not m:
            return str(item or "").strip(), None
        return str(m.group(1) or "").strip(), str(m.group(2) or "").strip()

    def _clean_alias(a: Optional[str]) -> str:
        if not a:
            return ""
        out = str(a).strip()
        if (out.startswith("`") and out.endswith("`")) or (out.startswith("'") and out.endswith("'")) or (out.startswith('"') and out.endswith('"')):
            out = out[1:-1]
        return out.strip()

    def _identifier_terms(text: str) -> Set[str]:
        split = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or ""))
        return {
            tok
            for tok in re.findall(r"[a-z0-9]+", split.replace("_", " ").replace("-", " ").lower())
            if tok
        }

    def _table_cols_lower(table_name: str) -> Set[str]:
        t_l = str(table_name or "").strip("`").lower()
        if not t_l:
            return set()
        try:
            analyzer = get_schema_analyzer()
            return {
                str(c).strip("`").lower()
                for c in analyzer.get_table_columns(t_l)
                if str(c or "").strip()
            }
        except Exception:
            return set()

    def _original_case_col(table_name: str, col_name: str) -> str:
        t_l = str(table_name or "").strip("`").lower()
        c_l = str(col_name or "").strip("`").lower()
        if not t_l or not c_l:
            return str(col_name or "").strip("`")
        try:
            analyzer = get_schema_analyzer()
            return str(getattr(analyzer, "_column_original_case", {}).get(f"{t_l}.{c_l}", col_name))
        except Exception:
            return str(col_name or "").strip("`")

    def _question_requests_phrase(*phrases: str) -> bool:
        for phrase in phrases:
            p = str(phrase or "").strip().lower()
            if not p:
                continue
            p_pat = re.escape(p).replace(r"\ ", r"\s+")
            if re.search(rf"\b{p_pat}\b", q_l, flags=re.I):
                return True
        return False

    def _role_wants_full_name(role_terms: Sequence[str]) -> bool:
        role_alt = "|".join(
            re.escape(str(t)).replace(r"\ ", r"\s+")
            for t in role_terms
            if str(t or "").strip()
        )
        if not role_alt:
            return False
        return bool(
            re.search(rf"\b(?:{role_alt})\b.{{0,48}}\b(?:full\s+name|name)\b", q_l, flags=re.I | re.S)
        )

    def _role_wants_title(role_terms: Sequence[str]) -> bool:
        role_alt = "|".join(
            re.escape(str(t)).replace(r"\ ", r"\s+")
            for t in role_terms
            if str(t or "").strip()
        )
        if not role_alt:
            return False
        return bool(
            re.search(rf"\b(?:{role_alt})\b.{{0,48}}\b(?:job\s+title|title|position|role)\b", q_l, flags=re.I | re.S)
        )

    def _name_component_cols_for_table(table_name: str) -> List[str]:
        cols = _table_cols_lower(table_name)
        if not cols:
            return []
        ordered = [c for c in ("firstName", "lastName", "firstname", "lastname") if c.lower() in cols]
        if len(ordered) >= 2:
            return ordered[:2]
        first_col = next((c for c in cols if "first" in c or "given" in c), "")
        last_col = next((c for c in cols if "last" in c or "surname" in c or "family" in c), "")
        out = [c for c in (first_col, last_col) if c]
        return out[:2]

    def _full_name_expr(table_name: str, alias: str) -> str:
        cols = _name_component_cols_for_table(table_name)
        if len(cols) >= 2:
            return (
                f"CONCAT({alias}.{_original_case_col(table_name, cols[0])}, "
                f"' ', {alias}.{_original_case_col(table_name, cols[1])})"
            )
        name_col = str(get_name_column(table_name) or "").strip("`")
        if name_col:
            return f"{alias}.{_original_case_col(table_name, name_col)}"
        return ""

    def _title_col_for_table(table_name: str) -> str:
        cols = _table_cols_lower(table_name)
        if not cols:
            return ""
        for cand in ("jobTitle", "title", "position", "role"):
            if cand.lower() in cols:
                return cand
        for col in cols:
            if "title" in col or "position" in col or "role" in col:
                return col
        return ""

    inner_alias_items: Dict[str, Tuple[str, str]] = {}
    for item in _split_top_level_csv(inner_select):
        expr, alias = _split_expr_alias(item)
        alias_clean = _clean_alias(alias)
        if alias_clean:
            inner_alias_items[alias_clean.lower()] = (expr, alias_clean)

    child_role_terms = ["subordinate", "employee", "child", "report"]
    parent_role_terms = ["manager", "supervisor", "parent", "boss"]
    rebuilt_items: List[str] = []
    seen_norm: Set[str] = set()

    def _append_item(expr: str, alias: Optional[str] = None) -> None:
        expr_s = str(expr or "").strip()
        alias_s = _clean_alias(alias)
        if not expr_s:
            return
        item = f"{expr_s} AS {alias_s}" if alias_s else expr_s
        norm = re.sub(r"\s+", " ", item).strip().lower()
        if norm in seen_norm:
            return
        seen_norm.add(norm)
        rebuilt_items.append(item)

    # Child identifier
    child_id_alias = next(
        (alias for alias, (expr, _a) in inner_alias_items.items() if re.search(rf"(?is)\b{re.escape(child_alias)}\s*\.\s*`?{re.escape(base_id_col)}`?\b", expr)),
        "",
    )
    if child_id_alias:
        expr, alias = inner_alias_items[child_id_alias]
        _append_item(expr, alias)
    else:
        _append_item(f"{child_alias}.{_original_case_col(base_table, base_id_col)}")

    # Child full name
    if _role_wants_full_name(child_role_terms):
        child_name_alias = next((alias for alias in inner_alias_items if alias.startswith("subordinate_") and "name" in alias), "")
        if child_name_alias:
            expr, alias = inner_alias_items[child_name_alias]
            _append_item(expr, alias)
        else:
            child_name_expr = _full_name_expr(base_table, child_alias)
            if child_name_expr:
                _append_item(child_name_expr, "employee_name")

    # Child title
    if _role_wants_title(child_role_terms):
        child_title_alias = next((alias for alias in inner_alias_items if alias.startswith("subordinate_") and ("title" in alias or "role" in alias or "position" in alias)), "")
        if child_title_alias:
            expr, alias = inner_alias_items[child_title_alias]
            _append_item(expr, alias)
        else:
            title_col = _title_col_for_table(base_table)
            if title_col:
                _append_item(f"{child_alias}.{_original_case_col(base_table, title_col)}")

    # Parent full name
    if _role_wants_full_name(parent_role_terms):
        parent_name_expr = _full_name_expr(base_table, parent_alias)
        if parent_name_expr:
            _append_item(parent_name_expr, "manager_name")

    # Parent title
    if _role_wants_title(parent_role_terms):
        parent_title_alias = next((alias for alias in inner_alias_items if alias.startswith("manager_") and ("title" in alias or "role" in alias or "position" in alias)), "")
        if parent_title_alias:
            expr, alias = inner_alias_items[parent_title_alias]
            _append_item(expr, alias)
        else:
            title_col = _title_col_for_table(base_table)
            if title_col:
                _append_item(f"{parent_alias}.{_original_case_col(base_table, title_col)}", "manager_job_title")

    fk_raw = get_fk_relationships() or {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, mapping in (fk_raw or {}).items():
        src_l = str(src or "").strip("`").lower()
        if not src_l:
            continue
        fk_map[src_l] = {}
        for fk_col, tgt in (mapping or {}).items():
            fk_l = str(fk_col or "").strip("`").lower()
            tgt_l = str(tgt or "").strip("`").lower()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    outer_lookup_match = re.search(
        r"""(?is)\b(?:INNER|LEFT|RIGHT|CROSS)?\s*JOIN\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?\s+ON\b""",
        outer_tail,
    )
    lookup_join_sql = ""
    order_items: List[str] = []
    if outer_lookup_match:
        lookup_table = str(outer_lookup_match.group("table") or "").strip().lower()
        lookup_alias = str(outer_lookup_match.group("alias") or "").strip() or lookup_table
        child_fk_col = ""
        for fk_col, tgt in (fk_map.get(base_table, {}) or {}).items():
            if tgt == lookup_table:
                child_fk_col = fk_col
                break
        if child_fk_col:
            lookup_cols = _table_cols_lower(lookup_table)
            requested_lookup_cols: List[str] = []
            for col in sorted(lookup_cols):
                col_terms = _identifier_terms(col)
                if not col_terms:
                    continue
                if all(re.search(rf"\b{re.escape(term)}\b", q_l) for term in sorted(col_terms) if len(term) >= 3):
                    requested_lookup_cols.append(col)
            if not requested_lookup_cols:
                for col in sorted(lookup_cols):
                    if col in {"city", "country", "state", "territory", "name"} and re.search(rf"\b{re.escape(col)}\b", q_l):
                        requested_lookup_cols.append(col)
            lookup_join_sql = (
                f" INNER JOIN {lookup_table} AS {lookup_alias}"
                f" ON {child_alias}.{_original_case_col(base_table, child_fk_col)} = {lookup_alias}.{_original_case_col(lookup_table, get_id_column(lookup_table) or child_fk_col)}"
            )
            for col in requested_lookup_cols:
                _append_item(
                    f"{lookup_alias}.{_original_case_col(lookup_table, col)}",
                    f"{lookup_table.rstrip('s')}_{col}",
                )
            sort_segment = ""
            m_sort = re.search(r"(?is)\b(?:sort(?:ed)?|order(?:ed)?)\s+by\s+(.+)$", q_l)
            if m_sort:
                sort_segment = str(m_sort.group(1) or "").strip()
            for col in requested_lookup_cols:
                if col and col in sort_segment:
                    direction = "DESC" if re.search(rf"\b{re.escape(col)}\b.{{0,24}}\bdesc", sort_segment, flags=re.I | re.S) else "ASC"
                    order_items.append(f"{lookup_alias}.{_original_case_col(lookup_table, col)} {direction}")
                    break
            id_terms = _identifier_terms(base_id_col) | {"employee", "number", "id", "code"}
            if sort_segment and any(term in sort_segment for term in id_terms):
                direction = "DESC" if re.search(r"\b(?:employee\s+number|employee\s+id|id|number|code)\b.{0,24}\bdesc", sort_segment, flags=re.I | re.S) else "ASC"
                order_items.append(f"{child_alias}.{_original_case_col(base_table, base_id_col)} {direction}")

    if not rebuilt_items:
        return sql

    order_clause = f" ORDER BY {', '.join(order_items)}" if order_items else ""
    rebuilt = (
        f"SELECT {', '.join(rebuilt_items)} "
        f"FROM {base_table} AS {child_alias} "
        f"INNER JOIN {base_table} AS {parent_alias} ON {self_join_on}"
        f"{lookup_join_sql}"
        f"{order_clause}"
    ).strip()
    if trailing_semicolon and not rebuilt.endswith(";"):
        rebuilt += ";"
    return rebuilt


def _rewrite_missing_ordered_lookup_join(sql: str, question: str, ctx: str = "") -> str:
    """
    Deterministically add a one-hop lookup join when ORDER BY references a
    schema table that is not currently joined.

    Conservative scope:
    - flat top-level SELECT ... FROM ... [JOIN ...]
    - no GROUP BY/HAVING/UNION/WINDOW/subquery shapes
    - adds at most one hop through the FK graph

    This lets the refiner repair common lookup misses such as ordering by a
    dimension column (`offices.city`) when the drafter forgot the lookup join.
    """
    s = str(sql or "").strip()
    q = str(question or "").strip()
    if not s or not q or not has_join(s):
        return sql
    flattened_self_join = _rewrite_derived_self_join_lookup_subquery(s, question, ctx)
    if flattened_self_join != s:
        return _rewrite_missing_ordered_lookup_join(flattened_self_join, question, ctx)
    if re.search(r"\b(?:group\s+by|having|union|intersect|except|with)\b", s, flags=re.I):
        return sql
    if re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql
    if re.search(r"(?is)\b(?:from|exists|in)\s*\(\s*select\b", s):
        return sql

    trailing_semicolon = ";" if s.endswith(";") else ""
    s_core = s[:-1].rstrip() if trailing_semicolon else s
    m = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+\bFROM\b\s+(?P<rest>.+)$", s_core)
    if not m:
        return sql

    def _find_top_level_keyword(text: str, keyword: str, start: int = 0) -> int:
        t = str(text or "")
        kw = str(keyword or "").upper()
        if not t or not kw:
            return -1
        up = t.upper()
        depth = 0
        in_sq = False
        in_dq = False
        i = max(0, int(start))
        while i < len(t):
            ch = t[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(t) and t[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and up.startswith(kw, i):
                left_ok = i == 0 or not (up[i - 1].isalnum() or up[i - 1] == "_")
                right_idx = i + len(kw)
                right_ok = right_idx >= len(up) or not (up[right_idx].isalnum() or up[right_idx] == "_")
                if left_ok and right_ok:
                    return i
            i += 1
        return -1

    def _split_top_level_csv(text: str) -> List[str]:
        items: List[str] = []
        buf: List[str] = []
        depth = 0
        in_sq = False
        in_dq = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    buf.append(ch)
                    buf.append(text[i + 1])
                    i += 2
                    continue
                in_sq = not in_sq
                buf.append(ch)
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                buf.append(ch)
                i += 1
                continue
            if not in_sq and not in_dq:
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth = max(0, depth - 1)
                elif ch == "," and depth == 0:
                    item = "".join(buf).strip()
                    if item:
                        items.append(item)
                    buf = []
                    i += 1
                    continue
            buf.append(ch)
            i += 1
        tail = "".join(buf).strip()
        if tail:
            items.append(tail)
        return items

    select_part = str(m.group("select") or "").strip()
    rest = str(m.group("rest") or "").strip()
    if not select_part or not rest:
        return sql

    clause_positions: List[Tuple[int, str]] = []
    for kw in ("WHERE", "GROUP BY", "HAVING", "ORDER BY", "LIMIT"):
        pos = _find_top_level_keyword(rest, kw)
        if pos >= 0:
            clause_positions.append((pos, kw))
    clause_positions.sort(key=lambda x: x[0])

    if clause_positions:
        first_pos = clause_positions[0][0]
        from_core = rest[:first_pos].strip()
        tail = rest[first_pos:].strip()
    else:
        from_core = rest
        tail = ""
    if not from_core or not tail:
        return sql

    order_pos = _find_top_level_keyword(tail, "ORDER BY")
    if order_pos < 0:
        return sql
    limit_pos = _find_top_level_keyword(tail, "LIMIT", order_pos + len("ORDER BY"))
    order_segment = tail[order_pos + len("ORDER BY"):limit_pos if limit_pos >= 0 else len(tail)].strip()
    if not order_segment:
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if not alias_to_table:
        return sql

    reserved_alias_tokens = {
        "left", "right", "inner", "outer", "full", "cross", "join",
        "on", "where", "group", "order", "having", "limit",
    }
    source_pairs: List[Tuple[str, str]] = []
    seen_aliases: Set[str] = set()
    for m_tbl in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?""",
        f"FROM {from_core}",
    ):
        raw_tbl = (m_tbl.group(1) or "").replace("`", "").strip()
        table_l = raw_tbl.split(".")[-1].lower()
        if not table_l:
            continue
        alias_raw = (m_tbl.group(2) or "").strip()
        if alias_raw.lower() in reserved_alias_tokens:
            alias_raw = ""
        alias = (alias_raw or table_l).strip()
        alias_l = alias.lower()
        if not alias_l or alias_l in seen_aliases:
            continue
        seen_aliases.add(alias_l)
        source_pairs.append((alias, table_l))
    if not source_pairs:
        return sql

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    allowed_identifiers = _parse_allowed_identifiers(ctx or "")

    def _table_cols_lower(table_name: str) -> Set[str]:
        t_l = str(table_name or "").strip().lower()
        if not t_l:
            return set()
        if analyzer is not None:
            try:
                return {
                    str(c).strip("`").lower()
                    for c in analyzer.get_table_columns(t_l)
                    if str(c or "").strip()
                }
            except Exception:
                pass
        for t_ctx, cols_ctx in (allowed_identifiers or {}).items():
            if str(t_ctx or "").strip().lower() != t_l:
                continue
            return {
                str(c).strip("`").lower()
                for c in (cols_ctx or set())
                if str(c or "").strip()
            }
        return set()

    try:
        all_tables = {
            str(t).strip().lower()
            for t in (get_all_tables() or [])
            if str(t).strip()
        }
    except Exception:
        all_tables = {
            str(t).strip().lower()
            for t in (allowed_identifiers or {}).keys()
            if str(t).strip()
        }

    alias_keys = {
        str(k or "").strip().lower()
        for k in alias_to_table.keys()
        if str(k or "").strip()
    }
    joined_tables = {tbl for _alias, tbl in source_pairs}

    requested_output_segment = _extract_requested_output_segment(question)

    def _question_requests_column(col_name: str) -> bool:
        clean = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_name or ""))
        clean = clean.replace("_", " ").strip().lower()
        if not clean:
            return False
        pat = re.escape(clean).replace(r"\ ", r"\s+")
        return bool(re.search(rf"\b{pat}\b", requested_output_segment, flags=re.I))

    def _preferred_output_alias(table_name: str, col_name: str) -> str:
        table_l = str(table_name or "").strip().lower()
        col_case = _original_case_col(table_l, col_name)
        if not table_l:
            return col_case
        try:
            singular = str(get_singular_form(table_l) or "").strip().lower()
        except Exception:
            singular = ""
        base = singular or re.sub(r"s$", "", table_l)
        base = re.sub(r"[^a-z0-9_]+", "_", base).strip("_")
        if not base or base == str(col_name or "").strip().lower():
            return col_case
        return f"{base}_{col_case}"

    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, mapping in (fk_map_raw or {}).items():
        src_l = str(src or "").strip().lower()
        if not src_l:
            continue
        fk_map[src_l] = {}
        for fk_col, tgt in (mapping or {}).items():
            fk_l = str(fk_col or "").strip().lower()
            tgt_l = str(tgt or "").strip().lower()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    used_aliases: Set[str] = {a.lower() for a, _t in source_pairs}
    used_aliases.update(alias_keys)

    def _next_alias_for_table(table_name: str) -> str:
        table_l = str(table_name or "").strip().lower() or "t"
        if table_l not in used_aliases:
            used_aliases.add(table_l)
            return table_l
        base = re.sub(r"[^a-z0-9_]", "", table_l) or "t"
        if base[0] not in used_aliases:
            used_aliases.add(base[0])
            return base[0]
        for idx in range(2, 200):
            cand = f"{base[0]}{idx}"
            if cand not in used_aliases:
                used_aliases.add(cand)
                return cand
        fallback = f"{base[0]}_x"
        used_aliases.add(fallback)
        return fallback

    def _find_join_plan(target_table: str) -> Optional[Tuple[str, str, str, str]]:
        target_l = str(target_table or "").strip().lower()
        if not target_l:
            return None
        target_cols = _table_cols_lower(target_l)
        for conn_alias, conn_table in source_pairs:
            conn_l = str(conn_table or "").strip().lower()
            conn_cols = _table_cols_lower(conn_l)
            for fk_col, tgt in (fk_map.get(conn_l, {}) or {}).items():
                if tgt != target_l or fk_col not in conn_cols:
                    continue
                try:
                    target_key = str(get_id_column(target_l) or "").strip().lower()
                except Exception:
                    target_key = ""
                if not target_key or target_key not in target_cols:
                    target_key = fk_col if fk_col in target_cols else ""
                if target_key:
                    return ("conn_to_target", conn_alias, fk_col, target_key)
            for fk_col, tgt in (fk_map.get(target_l, {}) or {}).items():
                if tgt != conn_l or fk_col not in target_cols:
                    continue
                try:
                    conn_key = str(get_id_column(conn_l) or "").strip().lower()
                except Exception:
                    conn_key = ""
                if not conn_key or conn_key not in conn_cols:
                    conn_key = fk_col if fk_col in conn_cols else ""
                if conn_key:
                    return ("target_to_conn", conn_alias, fk_col, conn_key)
        return None

    def _original_case_col(table_name: str, col_name: str) -> str:
        t_l = str(table_name or "").strip("`").lower()
        c_l = str(col_name or "").strip("`").lower()
        if not t_l or not c_l:
            return str(col_name or "").strip("`")
        if analyzer is not None:
            try:
                return str(getattr(analyzer, "_column_original_case", {}).get(f"{t_l}.{c_l}", col_name))
            except Exception:
                pass
        return str(col_name or "").strip("`")

    def _identifier_terms(text: str) -> Set[str]:
        split = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or ""))
        return {
            tok
            for tok in re.findall(r"[a-z0-9]+", split.replace("_", " ").replace("-", " ").lower())
            if tok
        }

    name_component_token_hints = set(name_component_lexical_tokens())
    name_priority_groups = name_component_priority_groups()
    first_name_hints = set(name_priority_groups.get("first", set()))
    middle_name_hints = set(name_priority_groups.get("middle", set()))
    last_name_hints = set(name_priority_groups.get("last", set()))
    generic_name_hints = set(name_priority_groups.get("generic", set()))

    def _name_component_cols_for_table(table_name: str) -> List[str]:
        t_l = str(table_name or "").strip("`").lower()
        cols = _table_cols_lower(t_l)
        if not t_l or not cols:
            return []
        ordered_cols: List[str] = []
        if analyzer is not None:
            try:
                ordered_cols = [
                    str(c).strip("`").lower()
                    for c in analyzer.get_table_columns(t_l)
                    if str(c).strip()
                ]
            except Exception:
                ordered_cols = []
        if not ordered_cols:
            ordered_cols = sorted(cols)

        candidates: List[str] = []
        for col_l in ordered_cols:
            if col_l not in cols:
                continue
            col_case = _original_case_col(t_l, col_l)
            terms = _identifier_terms(col_case or col_l)
            col_norm = re.sub(r"[^a-z0-9]+", "", str(col_case or col_l).lower())
            if terms & name_component_token_hints or any(h and h in col_norm for h in name_component_token_hints):
                candidates.append(col_l)
                continue
            try:
                role_l = str(get_column_role(t_l, col_l) or "").strip().lower()
            except Exception:
                role_l = ""
            if role_l == "name":
                candidates.append(col_l)

        if len(candidates) >= 2:
            col_pos = {c: idx for idx, c in enumerate(ordered_cols)}

            def _name_priority(col_l: str) -> int:
                raw = _original_case_col(t_l, col_l) or col_l
                terms = _identifier_terms(raw)
                norm = re.sub(r"[^a-z0-9]+", "", str(raw).lower())
                if terms & first_name_hints or any(h and h in norm for h in first_name_hints):
                    return 0
                if terms & middle_name_hints or any(h and h in norm for h in middle_name_hints):
                    return 1
                if terms & last_name_hints or any(h and h in norm for h in last_name_hints):
                    return 2
                if terms & generic_name_hints or any(h and h in norm for h in generic_name_hints):
                    return 3
                return 4

            return sorted(candidates, key=lambda c: (_name_priority(c), col_pos.get(c, 10_000), c))

        name_col = str(get_name_column(t_l) or "").strip("`").lower()
        if name_col and name_col in cols:
            return [name_col]
        return candidates

    def _full_name_expr(table_name: str, alias: str) -> str:
        cols = _name_component_cols_for_table(table_name)
        alias_s = str(alias or "").strip()
        if not cols or not alias_s:
            return ""
        if len(cols) >= 2:
            first_col = _original_case_col(table_name, cols[0])
            second_col = _original_case_col(table_name, cols[1])
            return f"CONCAT({alias_s}.{first_col}, ' ', {alias_s}.{second_col})"
        return f"{alias_s}.{_original_case_col(table_name, cols[0])}"

    def _self_fk_role_terms(table_name: str, fk_col: str) -> Set[str]:
        terms = _identifier_terms(fk_col)
        table_terms = _identifier_terms(table_name)
        id_like = {"id", "ids", "identifier", "identifiers", "number", "numbers", "code", "codes", "key", "keys"}
        terms -= table_terms | id_like | {"to", "by"}
        if analyzer is not None:
            try:
                for syn in analyzer.get_column_synonyms(table_name, fk_col) or []:
                    terms.update(_identifier_terms(syn))
            except Exception:
                pass
            try:
                terms.update(_identifier_terms(get_column_description(table_name, fk_col)))
            except Exception:
                pass
        filtered_terms = {t for t in terms if len(t) >= 3}
        if not any(
            term in {"manager", "supervisor", "parent", "leader", "mentor", "boss", "owner", "child", "subordinate"}
            or term.startswith("report")
            for term in filtered_terms
        ):
            filtered_terms.update({"manager", "supervisor", "parent", "leader", "report", "reports"})
        return filtered_terms

    def _self_join_role_aliases() -> Tuple[Dict[str, str], Set[str]]:
        roles: Dict[str, str] = {}
        parent_terms: Set[str] = set()
        id_cache: Dict[str, str] = {}

        def _id_col(table_name: str) -> str:
            table_l = str(table_name or "").strip("`").lower()
            if table_l not in id_cache:
                id_cache[table_l] = str(get_id_column(table_l) or "").strip("`").lower()
            return id_cache.get(table_l, "")

        for m_on in re.finditer(
            r"(?is)\bON\s+(.+?)(?=\b(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|JOIN|WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b|$)",
            f"{from_core} {tail}",
        ):
            on_txt = m_on.group(1) or ""
            for m_eq in re.finditer(
                r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
                on_txt,
                flags=re.I,
            ):
                left_a, left_c = m_eq.group(1).lower(), m_eq.group(2).lower()
                right_a, right_c = m_eq.group(3).lower(), m_eq.group(4).lower()
                left_t = alias_to_table.get(left_a, "").lower()
                right_t = alias_to_table.get(right_a, "").lower()
                if not left_t or left_t != right_t:
                    continue
                table_id = _id_col(left_t)
                if not table_id:
                    continue
                if left_c != table_id and right_c == table_id:
                    roles["child"] = left_a
                    roles["parent"] = right_a
                    parent_terms.update(_self_fk_role_terms(left_t, left_c))
                elif right_c != table_id and left_c == table_id:
                    roles["child"] = right_a
                    roles["parent"] = left_a
                    parent_terms.update(_self_fk_role_terms(right_t, right_c))
        return roles, parent_terms

    def _role_terms_alt(role_terms: Set[str]) -> str:
        return "|".join(
            re.escape(term).replace(r"\ ", r"\s+")
            for term in sorted((t for t in role_terms if t), key=len, reverse=True)
        )

    def _title_like_cols_for_table(table_name: str) -> List[str]:
        t_l = str(table_name or "").strip("`").lower()
        cols = _table_cols_lower(t_l)
        if not t_l or not cols:
            return []
        ordered_cols: List[str] = []
        if analyzer is not None:
            try:
                ordered_cols = [
                    str(c).strip("`").lower()
                    for c in analyzer.get_table_columns(t_l)
                    if str(c).strip()
                ]
            except Exception:
                ordered_cols = []
        if not ordered_cols:
            ordered_cols = sorted(cols)

        candidates: List[str] = []
        seen: Set[str] = set()
        for col_l in ordered_cols:
            if col_l not in cols or col_l in seen:
                continue
            seen.add(col_l)
            col_case = _original_case_col(t_l, col_l)
            terms = _identifier_terms(col_case or col_l)
            norm = re.sub(r"[^a-z0-9]+", "", str(col_case or col_l).lower())
            try:
                role_l = str(get_column_role(t_l, col_l) or "").strip().lower()
            except Exception:
                role_l = ""
            if role_l in {"title", "position", "role"}:
                candidates.append(col_l)
                continue
            if (
                "title" in terms
                or "position" in terms
                or "designation" in terms
                or ("role" in terms and role_l not in {"fk", "pk", "id", "identifier"})
                or "jobtitle" in norm
            ):
                candidates.append(col_l)
        return candidates

    def _requested_role_attribute(role_terms: Set[str], attr_terms: Set[str], *, window: int = 64) -> bool:
        scope = requested_output_segment or q
        role_alt = _role_terms_alt(role_terms)
        attr_alt = "|".join(
            re.escape(term).replace(r"\ ", r"\s+")
            for term in sorted((t for t in attr_terms if t), key=len, reverse=True)
        )
        if not scope or not role_alt or not attr_alt:
            return False
        return bool(
            re.search(
                rf"\b(?:{role_alt})\b.{{0,{window}}}\b(?:{attr_alt})\b|\b(?:{attr_alt})\b.{{0,{window}}}\b(?:{role_alt})\b",
                scope,
                flags=re.I | re.S,
            )
        )

    def _role_label_terms_from_projection(role_alias: str, table_name: str) -> Set[str]:
        role_alias_l = str(role_alias or "").strip().lower()
        table_l = str(table_name or "").strip("`").lower()
        if not role_alias_l or not table_l:
            return set()

        table_terms = _identifier_terms(table_l)
        stop_terms = table_terms | {
            "id", "code", "number", "name", "full", "job", "title",
            "role", "position", "city", "office", "employee", "employees",
            "firstname", "lastname", "first", "last",
        }
        out: Set[str] = set()
        for item in rebuilt_select_items:
            if not re.search(rf"(?is)\b{re.escape(role_alias_l)}\s*\.", item):
                continue
            m_alias = re.search(r"(?is)\bAS\s+`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$", item)
            if not m_alias:
                continue
            alias_txt = str(m_alias.group(1) or "").strip().lower()
            parts = [p for p in re.split(r"[_\s]+", alias_txt) if p]
            if not parts:
                continue
            lead = parts[0]
            if len(lead) >= 4 and lead not in stop_terms:
                out.add(lead)
        return out

    select_items = _split_top_level_csv(select_part)
    select_low = select_part.lower()
    rebuilt_select_items = list(select_items)
    rebuilt_from = from_core
    rebuilt_tail = tail
    changed = False

    role_aliases, parent_role_terms = _self_join_role_aliases()
    child_alias = role_aliases.get("child", "")
    child_role_terms = _role_label_terms_from_projection(child_alias, alias_to_table.get(str(child_alias or "").strip().lower(), ""))

    def _needs_role_full_name(role_alias: str, role_terms: Set[str]) -> bool:
        role_alias_l = str(role_alias or "").strip().lower()
        if not role_alias_l:
            return False
        scope = requested_output_segment or q
        role_alt = "|".join(re.escape(term).replace(r"\ ", r"\s+") for term in sorted(role_terms, key=len, reverse=True))
        if not role_alt:
            return False
        if not re.search(rf"\b(?:{role_alt})\b.{0,48}\b(?:full\s+name|name)\b", scope, flags=re.I | re.S):
            return False
        if re.search(rf"(?is)\bCONCAT\s*\([\s\S]*?\b{re.escape(role_alias_l)}\s*\.", select_part):
            return False
        if re.search(
            rf"(?is)\b{re.escape(role_alias_l)}_(?:full_?name|name)\b|\b(?:{role_alt})_(?:full_?name|name)\b",
            select_part,
        ):
            return False
        return True

    parent_alias = role_aliases.get("parent", "")
    if parent_alias and _needs_role_full_name(parent_alias, parent_role_terms):
        parent_table = alias_to_table.get(parent_alias.lower(), "")
        name_expr = _full_name_expr(parent_table, parent_alias)
        if not name_expr and parent_table:
            cols = _table_cols_lower(parent_table)
            first_col = next(
                (c for c in cols if any(tok in c for tok in ("firstname", "first", "givenname", "given"))),
                "",
            )
            last_col = next(
                (c for c in cols if any(tok in c for tok in ("lastname", "last", "surname", "familyname", "family"))),
                "",
            )
            if first_col and last_col:
                name_expr = (
                    f"CONCAT({parent_alias}.{_original_case_col(parent_table, first_col)}, "
                    f"' ', {parent_alias}.{_original_case_col(parent_table, last_col)})"
                )
        if name_expr:
            insert_idx = len(rebuilt_select_items)
            for idx, item in enumerate(rebuilt_select_items):
                if re.search(rf"(?is)\b{re.escape(parent_alias)}\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?", item):
                    insert_idx = idx
                    break
            rebuilt_select_items.insert(insert_idx, f"{name_expr} AS manager_name")
            select_low += " manager_name"
            changed = True

    def _ensure_parent_role_scalar_projection() -> None:
        nonlocal select_low, changed, rebuilt_select_items
        parent_alias_l = str(parent_alias or "").strip().lower()
        child_alias_l = str(child_alias or "").strip().lower()
        if not parent_alias_l or not child_alias_l:
            return
        parent_table = alias_to_table.get(parent_alias_l, "")
        child_table = alias_to_table.get(child_alias_l, "")
        if not parent_table or not child_table or parent_table.lower() != child_table.lower():
            return

        title_cols = _title_like_cols_for_table(child_table)
        if not title_cols:
            return

        requested_title_terms = {"job title", "title", "position", "designation", "role"}
        if not _requested_role_attribute(parent_role_terms, requested_title_terms):
            return

        child_title_col = ""
        for item in rebuilt_select_items:
            for title_col in title_cols:
                if re.search(
                    rf"(?is)\b{re.escape(child_alias_l)}\s*\.\s*`?{re.escape(title_col)}`?\b",
                    item,
                ):
                    child_title_col = title_col
                    break
            if child_title_col:
                break
        if not child_title_col:
            child_title_col = title_cols[0]

        if re.search(
            rf"(?is)\b{re.escape(parent_alias_l)}\s*\.\s*`?{re.escape(child_title_col)}`?\b",
            ", ".join(rebuilt_select_items),
        ):
            return

        parent_title_case = _original_case_col(parent_table, child_title_col)
        insert_idx = len(rebuilt_select_items)
        for idx, item in enumerate(rebuilt_select_items):
            if re.search(rf"(?is)\b{re.escape(parent_alias_l)}\s*\.", item):
                insert_idx = idx + 1
        rebuilt_select_items.insert(insert_idx, f"{parent_alias}.{parent_title_case} AS parent_{parent_title_case}")
        select_low += f" {parent_title_case.lower()} parent_{parent_title_case.lower()}"
        changed = True

    def _prefer_child_anchor_for_self_fk_lookup_joins() -> None:
        nonlocal rebuilt_from, changed
        parent_alias_l = str(parent_alias or "").strip().lower()
        child_alias_l = str(child_alias or "").strip().lower()
        if not parent_alias_l or not child_alias_l:
            return
        parent_table = alias_to_table.get(parent_alias_l, "")
        child_table = alias_to_table.get(child_alias_l, "")
        if not parent_table or not child_table or parent_table.lower() != child_table.lower():
            return

        child_cols = _table_cols_lower(child_table)
        if not child_cols:
            return

        lookup_requested_cols: Dict[str, Set[str]] = {}
        for segment in list(rebuilt_select_items) + [order_segment]:
            for m_ref in re.finditer(
                r"(?is)\b([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\b",
                segment,
            ):
                alias_l = str(m_ref.group(1) or "").strip().lower()
                col_l = str(m_ref.group(2) or "").strip().lower()
                if alias_l and col_l:
                    lookup_requested_cols.setdefault(alias_l, set()).add(col_l)

        for lookup_alias, lookup_table in list(source_pairs):
            lookup_alias_l = str(lookup_alias or "").strip().lower()
            lookup_table_l = str(lookup_table or "").strip().lower()
            if not lookup_alias_l or lookup_table_l in {parent_table.lower(), child_table.lower()}:
                continue
            requested_cols = lookup_requested_cols.get(lookup_alias_l, set())
            if not requested_cols:
                continue

            attr_terms = set(_identifier_terms(lookup_table_l))
            for req_col in requested_cols:
                attr_terms.update(_identifier_terms(req_col))
            if not attr_terms:
                continue
            child_role_requested = _requested_role_attribute(child_role_terms, attr_terms, window=48)
            if not child_role_requested and _requested_role_attribute(parent_role_terms, attr_terms, window=24):
                continue

            join_pat = re.compile(
                rf"(?is)(\b(?:INNER|LEFT|RIGHT|CROSS)?\s*JOIN\s+`?{re.escape(lookup_table_l)}`?"
                rf"(?:\s+(?:AS\s+)?{re.escape(lookup_alias_l)})?\s+ON\s+)(.+?)(?=\b(?:INNER|LEFT|RIGHT|CROSS)?\s*JOIN\b|$)"
            )
            m_join = join_pat.search(rebuilt_from)
            if not m_join:
                continue

            join_prefix = m_join.group(1) or ""
            on_txt = m_join.group(2) or ""
            rewritten_on = on_txt
            local_changed = False
            for m_eq in re.finditer(
                r"""(?is)`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
                on_txt,
            ):
                left_a, left_c = str(m_eq.group(1) or "").strip().lower(), str(m_eq.group(2) or "").strip().lower()
                right_a, right_c = str(m_eq.group(3) or "").strip().lower(), str(m_eq.group(4) or "").strip().lower()
                replace_col = ""
                if left_a == parent_alias_l and right_a == lookup_alias_l and left_c in child_cols:
                    replace_col = left_c
                elif right_a == parent_alias_l and left_a == lookup_alias_l and right_c in child_cols:
                    replace_col = right_c
                if not replace_col:
                    continue
                rewritten_on = re.sub(
                    rf"(?is)\b{re.escape(parent_alias_l)}\s*\.\s*`?{re.escape(replace_col)}`?\b",
                    f"{child_alias}.{_original_case_col(child_table, replace_col)}",
                    rewritten_on,
                )
                local_changed = True
            if local_changed and rewritten_on != on_txt:
                rebuilt_from = f"{rebuilt_from[:m_join.start()]}{join_prefix}{rewritten_on}{rebuilt_from[m_join.end():]}"
                changed = True

    _ensure_parent_role_scalar_projection()
    _prefer_child_anchor_for_self_fk_lookup_joins()

    if (
        "manager_name" not in select_low
        and len(source_pairs) >= 2
        and source_pairs[1][1] == source_pairs[0][1]
    ):
        parent_role_alt = "|".join(
            re.escape(term).replace(r"\ ", r"\s+")
            for term in sorted(parent_role_terms, key=len, reverse=True)
            if term
        )
        parent_name_requested = bool(
            parent_role_alt
            and re.search(
                rf"\b(?:{parent_role_alt})\b"
                r".{0,48}\b(?:full\s+name|name)\b",
                requested_output_segment or q,
                flags=re.I | re.S,
            )
        )
        has_parent_name_alias = bool(
            parent_role_alt
            and re.search(
                rf"(?is)\b(?:{parent_role_alt})_(?:full_?name|name)\b",
                select_low,
            )
        )
        if parent_name_requested and not has_parent_name_alias:
            fallback_alias, fallback_table = source_pairs[1]
            cols = _table_cols_lower(fallback_table)
            first_col = next((c for c in cols if any(tok in c for tok in ("firstname", "first", "givenname", "given"))), "")
            last_col = next((c for c in cols if any(tok in c for tok in ("lastname", "last", "surname", "familyname", "family"))), "")
            if first_col and last_col:
                fallback_expr = (
                    f"CONCAT({fallback_alias}.{_original_case_col(fallback_table, first_col)}, "
                    f"' ', {fallback_alias}.{_original_case_col(fallback_table, last_col)})"
                )
                insert_idx = len(rebuilt_select_items)
                for idx, item in enumerate(rebuilt_select_items):
                    if re.search(rf"(?is)\b{re.escape(fallback_alias)}\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?", item):
                        insert_idx = idx
                        break
                rebuilt_select_items.insert(insert_idx, f"{fallback_expr} AS manager_name")
                select_low += " manager_name"
                changed = True

    for m_ref in re.finditer(
        r"(?is)\b([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\b",
        order_segment,
    ):
        qual = str(m_ref.group(1) or "").strip().lower()
        col = str(m_ref.group(2) or "").strip().lower()
        if not qual or not col:
            continue
        if qual in alias_keys or qual in joined_tables:
            continue
        if qual not in all_tables:
            continue
        if col not in _table_cols_lower(qual):
            continue

        join_plan = _find_join_plan(qual)
        if join_plan is None:
            continue

        join_alias = qual if qual not in used_aliases else _next_alias_for_table(qual)
        join_mode, conn_alias, lhs_col, rhs_col = join_plan
        if join_mode == "conn_to_target":
            on_clause = f"{conn_alias}.{lhs_col} = {join_alias}.{rhs_col}"
        else:
            on_clause = f"{join_alias}.{lhs_col} = {conn_alias}.{rhs_col}"

        rebuilt_from = f"{rebuilt_from} LEFT JOIN {qual} AS {join_alias} ON {on_clause}"
        joined_tables.add(qual)
        alias_keys.add(join_alias.lower())
        source_pairs.append((join_alias, qual))
        changed = True

        if _question_requests_column(col) and not re.search(rf"(?is)\b{re.escape(col)}\b", select_low):
            rebuilt_select_items.append(f"{join_alias}.{col}")
            select_low += f" {col}"

        if join_alias.lower() != qual:
            rebuilt_tail = re.sub(
                rf"(?is)\b{re.escape(qual)}\s*\.\s*{re.escape(col)}\b",
                f"{join_alias}.{col}",
                rebuilt_tail,
            )

        break

    for m_ref in re.finditer(
        r"(?is)\b([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\b",
        order_segment,
    ):
        qual = str(m_ref.group(1) or "").strip().lower()
        col = str(m_ref.group(2) or "").strip().lower()
        if not qual or not col:
            continue
        source_table = alias_to_table.get(qual, "").lower()
        if not source_table and qual in joined_tables:
            source_table = qual
        if not source_table or col not in _table_cols_lower(source_table):
            continue
        if not _question_requests_column(col):
            continue
        if re.search(rf"(?is)\b{re.escape(col)}\b", select_low):
            continue

        qual_out = qual
        if qual_out not in alias_to_table:
            qual_out = next(
                (
                    alias_name
                    for alias_name, table_name in source_pairs
                    if str(table_name or "").strip().lower() == source_table
                ),
                qual,
            )
        col_case = _original_case_col(source_table, col)
        alias_out = _preferred_output_alias(source_table, col)
        if alias_out and alias_out.lower() != col_case.lower():
            rebuilt_select_items.append(f"{qual_out}.{col_case} AS {alias_out}")
            select_low += f" {col} {alias_out.lower()}"
        else:
            rebuilt_select_items.append(f"{qual_out}.{col_case}")
            select_low += f" {col}"
        changed = True
        break

    for m_ref in re.finditer(
        r"(?is)\b([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\b",
        order_segment,
    ):
        qual = str(m_ref.group(1) or "").strip().lower()
        col = str(m_ref.group(2) or "").strip().lower()
        if not qual or not col:
            continue
        source_table = alias_to_table.get(qual, "").lower()
        if not source_table:
            continue
        if col in _table_cols_lower(source_table):
            continue

        candidates = [
            table_l for table_l in sorted(all_tables)
            if table_l not in joined_tables
            and col in _table_cols_lower(table_l)
            and _find_join_plan(table_l) is not None
        ]
        if not candidates:
            continue

        q_terms = _identifier_terms(q)

        def _base_table_terms(table_l: str) -> Set[str]:
            terms = _identifier_terms(table_l)
            try:
                terms.update(_identifier_terms(get_singular_form(table_l)))
            except Exception:
                pass
            return terms

        def _table_terms(table_l: str) -> Set[str]:
            terms = _base_table_terms(table_l)
            try:
                for syn in get_table_synonyms(table_l) or []:
                    terms.update(_identifier_terms(syn))
            except Exception:
                pass
            return terms

        def _table_score(table_l: str) -> int:
            base_terms = _base_table_terms(table_l)
            all_terms = _table_terms(table_l)
            score = 20 * len(base_terms & q_terms)
            score += 2 * len((all_terms - base_terms) & q_terms)
            if _question_requests_column(col):
                score += 3
            return score

        mentioned_candidates = [table_l for table_l in candidates if _base_table_terms(table_l) & q_terms]
        target_table = max(mentioned_candidates or candidates, key=_table_score)
        join_plan = _find_join_plan(target_table)
        if join_plan is None:
            continue

        join_alias = target_table if target_table not in used_aliases else _next_alias_for_table(target_table)
        join_mode, conn_alias, lhs_col, rhs_col = join_plan
        lhs_col_case = _original_case_col(alias_to_table.get(conn_alias.lower(), ""), lhs_col)
        rhs_col_case = _original_case_col(target_table, rhs_col)
        if join_mode == "conn_to_target":
            on_clause = f"{conn_alias}.{lhs_col_case} = {join_alias}.{rhs_col_case}"
        else:
            target_fk_case = _original_case_col(target_table, lhs_col)
            conn_key_case = _original_case_col(alias_to_table.get(conn_alias.lower(), ""), rhs_col)
            on_clause = f"{join_alias}.{target_fk_case} = {conn_alias}.{conn_key_case}"

        rebuilt_from = f"{rebuilt_from} LEFT JOIN {target_table} AS {join_alias} ON {on_clause}"
        joined_tables.add(target_table)
        alias_keys.add(join_alias.lower())
        source_pairs.append((join_alias, target_table))
        changed = True

        col_case = _original_case_col(target_table, col)
        if _question_requests_column(col) and not re.search(rf"(?is)\b{re.escape(col)}\b", select_low):
            rebuilt_select_items.append(f"{join_alias}.{col_case} AS {target_table.rstrip('s')}_{col}")
            select_low += f" {col}"

        rebuilt_tail = re.sub(
            rf"(?is)\b{re.escape(qual)}\s*\.\s*`?{re.escape(col)}`?\b",
            f"{join_alias}.{col_case}",
            rebuilt_tail,
        )
        break

    if not changed:
        return sql

    rebuilt = f"SELECT {', '.join(rebuilt_select_items)} FROM {rebuilt_from}"
    if rebuilt_tail:
        rebuilt += f" {rebuilt_tail}"
    rebuilt = rebuilt.strip()
    if trailing_semicolon and not rebuilt.endswith(";"):
        rebuilt += ";"
    return rebuilt


def _drop_unrequested_secondary_self_join_identifier_columns(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop unrequested identifier columns projected from secondary aliases in
    flat same-table self-join lookup queries.

    Typical near-miss:
      - base alias id is requested
      - secondary self-join alias id is included "for completeness"
      - question only asks for the secondary alias descriptive fields

    Keep this narrow so it does not disturb valid multi-table logic:
    - only top-level flat SELECT ... FROM ... JOIN ...
    - no GROUP BY/HAVING/UNION/WINDOW/subquery shapes
    - only drops simple id-like projections from non-primary aliases of the
      same base table, and only when the question does not explicitly request
      a role-specific identifier.
    """
    s = str(sql or "").strip()
    q = str(question or "").strip().lower()
    if not s or not q or not has_join(s):
        return sql
    if re.search(r"\b(?:group\s+by|having|union|intersect|except|with)\b", s, flags=re.I):
        return sql
    if re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql
    if re.search(r"(?is)\b(?:from|exists|in)\s*\(\s*select\b", s):
        return sql

    m_sel = re.match(
        r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<from>.+?)"
        r"(?:\s+WHERE\s+(?P<where>.+?))?"
        r"(?:\s+ORDER\s+BY\s+(?P<order>.+?))?"
        r"(?:\s+LIMIT\s+(?P<limit>.+?))?\s*;?\s*$",
        s,
    )
    if not m_sel:
        return sql

    select_part = str(m_sel.group("select") or "").strip()
    from_core = str(m_sel.group("from") or "").strip()
    where_part = str(m_sel.group("where") or "").strip()
    order_part = str(m_sel.group("order") or "").strip()
    limit_part = str(m_sel.group("limit") or "").strip()
    if not select_part or not from_core:
        return sql

    reserved_alias_tokens = {
        "left", "right", "inner", "outer", "full", "cross", "join",
        "on", "where", "group", "order", "having", "limit",
    }
    source_pairs: List[Tuple[str, str]] = []
    seen_aliases: Set[str] = set()
    for m_tbl in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?""",
        f"FROM {from_core}",
    ):
        raw_tbl = (m_tbl.group(1) or "").replace("`", "").strip()
        table_l = raw_tbl.split(".")[-1].lower()
        if not table_l:
            continue
        alias_raw = (m_tbl.group(2) or "").strip()
        if alias_raw.lower() in reserved_alias_tokens:
            alias_raw = ""
        alias = (alias_raw or table_l).strip()
        alias_l = alias.lower()
        if not alias_l or alias_l in seen_aliases:
            continue
        seen_aliases.add(alias_l)
        source_pairs.append((alias, table_l))
    if len(source_pairs) < 2:
        return sql

    base_alias, base_table = source_pairs[0]
    same_table_secondary_aliases = {
        alias.lower()
        for alias, table_l in source_pairs[1:]
        if table_l == base_table and alias.lower() != base_alias.lower()
    }
    if not same_table_secondary_aliases:
        return sql

    base_id_col = str(get_id_column(base_table) or "").strip("`")
    if not base_id_col:
        return sql
    base_id_col_l = base_id_col.lower()

    requested_segment = _extract_requested_output_segment(question)
    scope_text = requested_segment if requested_segment else q

    def _identifier_phrase_candidates(id_col_name: str) -> List[str]:
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(id_col_name or ""))
        raw = raw.replace("_", " ").strip().lower()
        parts = [p for p in re.findall(r"[a-z0-9]+", raw) if p]
        if not parts:
            return []

        suffixes = {"id", "ids", "identifier", "identifiers", "number", "numbers", "code", "codes"}
        core_parts = list(parts)
        if core_parts and core_parts[-1] in suffixes:
            core_parts = core_parts[:-1]
        entity_phrase = " ".join(core_parts).strip()

        candidates: List[str] = []
        if raw:
            candidates.append(raw)
        if entity_phrase:
            for suffix in sorted(suffixes):
                candidates.append(f"{entity_phrase} {suffix}")

        deduped: List[str] = []
        seen: Set[str] = set()
        for cand in candidates:
            c = str(cand or "").strip().lower()
            if not c or c in seen:
                continue
            seen.add(c)
            deduped.append(c)
        return deduped

    requested_id_mentions = 0
    for phrase in _identifier_phrase_candidates(base_id_col):
        pat = re.escape(phrase).replace(r"\ ", r"\s+")
        requested_id_mentions += len(re.findall(rf"\b{pat}\b", scope_text, flags=re.I))
    if requested_id_mentions <= 0:
        requested_id_mentions = 1

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            str(item or "").strip(),
        )
        if not m:
            return str(item or "").strip(), None
        return str(m.group(1) or "").strip(), str(m.group(2) or "").strip()

    def _parse_simple_col(expr: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            str(expr or "").strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    if requested_id_mentions == 1:
        for secondary_alias in sorted(same_table_secondary_aliases):
            secondary_id_ref = f"{secondary_alias}.{base_id_col}"
            base_id_ref = f"{base_alias}.{base_id_col}"
            if re.search(rf"(?is)\b{re.escape(secondary_id_ref)}\b", order_part):
                order_part = re.sub(
                    rf"(?is)\b{re.escape(secondary_id_ref)}\b",
                    base_id_ref,
                    order_part,
                )

    order_where_text = " ".join(part for part in (where_part, order_part) if part).lower()
    rewritten_items: List[str] = []
    changed = False
    kept_same_table_id_count = 0
    seen_secondary_exprs: Set[Tuple[str, str]] = set()
    for item in _split_top_level_commas(select_part):
        expr, out_alias = _split_expr_alias(item)
        expr_norm = re.sub(r"[\s`]+", "", expr.lower())
        out_alias_l = str(out_alias or "").strip("`'\"").lower()
        expr_alias_refs = {
            m.group(1).lower()
            for m in re.finditer(
                r"(?is)\b([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?",
                expr,
            )
        }
        secondary_refs = expr_alias_refs.intersection(same_table_secondary_aliases)
        if len(secondary_refs) == 1:
            secondary_alias = next(iter(secondary_refs))
            dup_key = (secondary_alias, expr_norm)
            if dup_key in seen_secondary_exprs and not (
                out_alias_l and re.search(rf"(?is)\b{re.escape(out_alias_l)}\b", order_where_text)
            ):
                changed = True
                continue
            seen_secondary_exprs.add(dup_key)

        parsed = _parse_simple_col(expr)
        if not parsed:
            rewritten_items.append(item.strip())
            continue
        qual, col = parsed
        qual_l = str(qual or "").strip().lower()
        col_l = str(col or "").strip().lower()
        if (
            col_l == base_id_col_l
            and (qual_l == base_alias.lower() or qual_l in same_table_secondary_aliases)
        ):
            if kept_same_table_id_count < requested_id_mentions:
                kept_same_table_id_count += 1
                rewritten_items.append(item.strip())
                continue
            qualifier_ref_in_order_where = bool(
                qual_l
                and re.search(
                    rf"(?is)\b{re.escape(qual_l)}\s*\.\s*{re.escape(col_l)}\b",
                    order_where_text,
                )
            )
            if qual_l in same_table_secondary_aliases and not qualifier_ref_in_order_where:
                changed = True
                continue
        rewritten_items.append(item.strip())

    if not changed or not rewritten_items:
        return sql

    out_lines = [f"SELECT {', '.join(rewritten_items)}", f"FROM {from_core}"]
    if where_part:
        out_lines.append(f"WHERE {where_part}")
    if order_part:
        out_lines.append(f"ORDER BY {order_part}")
    if limit_part:
        out_lines.append(f"LIMIT {limit_part}")
    fixed = "\n".join(out_lines).strip()
    if s.endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed

def _parse_allowed_identifiers(ctx: str) -> Dict[str, Set[str]]:
    tables: Dict[str, Set[str]] = {}
    m = re.search(r"### ALLOWED IDENTIFIERS(.*?)(?:\n### |\Z)", ctx, flags=re.S)
    if not m:
        return tables
    block = m.group(1)
    for line in block.splitlines():
        line = line.strip()
        if not line.startswith("- "):
            continue
        parts = line[2:].split(":", 1)
        if len(parts) != 2:
            continue
        table = parts[0].strip().strip("`")
        cols = [c.strip().strip("`") for c in parts[1].split(",") if c.strip()]
        if table:
            tables.setdefault(table, set()).update(cols)
    return tables


def _extract_requested_output_segment(question: str) -> str:
    """
    Extract requested output/projection phrase from NL question.

    Prioritizes explicit trailing directives (e.g. ", and show ...") so
    filter clauses ("find ... where ...") do not hide output fields.
    """
    q = str(question or "").strip().lower()
    if not q:
        return ""

    def _normalize_segment(seg: str) -> str:
        text = str(seg or "").strip(" .;")
        if not text:
            return ""
        stop_m = re.search(
            r"(?is)(?:,\s*|\.\s*|\s+)"
            r"(?:sort(?:ed)?(?:\s+by|\s+(?:ascending|descending|asc|desc))?|"
            r"order(?:ed)?(?:\s+by|\s+(?:ascending|descending|asc|desc))|"
            r"starting|beginning|ranked|grouped|"
            r"only\s+include|include\s+only|keep\s+only|only\s+keep|retain\s+only|"
            r"within|among|across|inside)\b",
            text,
        )
        if not stop_m:
            stop_m = re.search(r"(?is)\s+\bwhere\b\s+", text)
        if stop_m:
            text = text[:stop_m.start()].strip(" ,.;")
        return text

    # Priority 1: explicit trailing output directive.
    tail_pattern = re.compile(
        r"(?is)(?:,|[.?!;]|\band\b|\bthen\b)\s*"
        r"(?:please\s+)?(?:just\s+)?"
        r"(?:return|show|display|get|list|include|including|provide)\s+"
        r"(?P<seg>.+)$"
    )
    tail_hits = list(tail_pattern.finditer(q))
    for hit in reversed(tail_hits):
        seg = _normalize_segment(hit.group("seg") or "")
        if seg:
            return seg

    # Priority 2: projection before filter connector.
    head_patterns = [
        r"\b(?:return|show|display|get|list|find|identify|retrieve|extract)\s+(?:the\s+)?(?P<seg>.+?)\s+\bfor\b",
        r"\b(?:return|show|display|get|list|find|identify|retrieve|extract)\s+(?:the\s+)?(?P<seg>.+?)\s+\bwhere\b",
    ]
    for pat in head_patterns:
        m = re.search(pat, q, flags=re.I)
        if not m:
            continue
        seg = _normalize_segment(m.group("seg") or "")
        if seg:
            return seg

    # Priority 3: generic trailing projection cues.
    # Choose the earliest cue in the question so leading directives like
    # "List first and last names ..., but display ..." keep the base fields.
    best_seg = ""
    best_pos: Optional[int] = None
    for pat in [
        r"\breturn\b\s+(?P<seg>.+)$",
        r"\bshow\b\s+(?P<seg>.+)$",
        r"\bdisplay\b\s+(?P<seg>.+)$",
        r"\bget\b\s+(?P<seg>.+)$",
        r"\blist\b\s+(?P<seg>.+)$",
        r"\bincluding\b\s+(?P<seg>.+)$",
        r"\binclude\b\s+(?P<seg>.+)$",
        r"\bwith\b\s+(?P<seg>.+)$",
    ]:
        m = re.search(pat, q, flags=re.I)
        if not m:
            continue
        seg = _normalize_segment(m.group("seg") or "")
        if not seg:
            continue
        pos = m.start()
        if best_pos is None or pos < best_pos:
            best_pos = pos
            best_seg = seg
    if best_seg:
        return best_seg

    return ""


def _to_singular(term: str) -> str:
    t = (term or "").lower().strip()
    if t.endswith("ies") and len(t) > 3:
        return t[:-3] + "y"
    if t.endswith("s") and not t.endswith("ss") and len(t) > 1:
        return t[:-1]
    return t

def _entity_terms_from_ctx(ctx: str = "") -> Set[str]:
    """
    Build dynamic entity lexicon from schema context.
    Priority:
    1) ALLOWED IDENTIFIERS block (request-scoped schema)
    2) Global schema analyzer tables (fallback)
    """
    terms: Set[str] = set()

    allowed = _parse_allowed_identifiers(ctx)
    if allowed:
        source_tables = list(allowed.keys())
    else:
        try:
            source_tables = list(get_all_tables())
        except Exception:
            source_tables = []

    for table in source_tables:
        t = (table or "").lower().strip().strip("`")
        if not t:
            continue

        singular = _to_singular(t)
        variants = {t, singular}

        # Support table names with underscores in natural-language questions
        if "_" in t:
            variants.add(t.replace("_", " "))
        if "_" in singular:
            variants.add(singular.replace("_", " "))

        terms.update(v for v in variants if v)

    return terms


def _ctx_metric_terms(ctx: str = "") -> Set[str]:
    allowed = _parse_allowed_identifiers(ctx)
    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    source_tables = list(allowed.keys()) if allowed else list(get_all_tables() or [])
    terms: Set[str] = set()
    generic_metric_terms = set(HELPERS_CTX_GENERIC_METRIC_FALLBACK_TERMS)
    numeric_roles = {"metric", "measure", "amount", "quantity"}

    for table in source_tables:
        t = str(table or "").strip().lower().strip("`")
        if not t:
            continue
        if allowed:
            cols = list(allowed.get(table, set()) or [])
        else:
            try:
                cols = list(analyzer.get_table_columns(t)) if analyzer is not None else []
            except Exception:
                cols = []

        for col in cols:
            c = str(col or "").strip().strip("`")
            if not c:
                continue
            c_low = c.lower()
            if c_low.endswith(("id", "number", "code", "key")):
                continue
            role = str(get_column_role(t, c) or "").strip().lower()
            candidate_texts = [c]
            try:
                if analyzer is not None:
                    candidate_texts.extend(analyzer.get_column_synonyms(t, c) or [])
            except Exception:
                pass
            col_terms: Set[str] = set()
            for text in candidate_texts:
                col_terms.update(
                    tok
                    for tok in re.findall(
                        r"[a-z0-9]+",
                        re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or "")).replace("_", " ").lower(),
                    )
                    if tok
                )
            if role in numeric_roles or col_terms.intersection(generic_metric_terms):
                terms.update(col_terms)

    if not terms:
        terms.update(generic_metric_terms)
    return terms

def _build_entity_kw(ctx: str = "") -> str:
    """
    Return regex alternation for entity nouns (schema-driven).
    Keeps a conservative fallback if schema context is unavailable.
    """
    terms = _entity_terms_from_ctx(ctx)
    if not terms:
        terms = set(HELPERS_ENTITY_GENERIC_FALLBACK_TERMS)

    escaped = sorted((re.escape(t) for t in terms), key=len, reverse=True)
    return f"(?:{'|'.join(escaped)})"


def _regex_alt_from_terms(terms: Set[str], default: str) -> str:
    escaped: List[str] = []
    for term in sorted((t for t in terms if t), key=len, reverse=True):
        pattern = re.escape(term)
        pattern = pattern.replace(r"\ ", r"\s+")
        escaped.append(pattern)
    return f"(?:{'|'.join(escaped)})" if escaped else default


def _configured_metric_terms(*term_sets: Any) -> Set[str]:
    terms: Set[str] = set()
    for term_set in term_sets:
        for term in term_set or []:
            normalized = str(term or "").strip().lower()
            if normalized:
                terms.add(normalized)
    return terms


def _configured_metric_alt(*term_sets: Any, default: str = r"$^") -> str:
    return _regex_alt_from_terms(_configured_metric_terms(*term_sets), default)


def _winner_row_metric_terms() -> Set[str]:
    temporal_terms = _configured_metric_terms(
        HELPERS_TEMPORAL_EVENT_COLUMN_TERMS,
        HELPERS_TEMPORAL_FALLBACK_META_TOKENS,
    )
    terms = _configured_metric_terms(
        HELPERS_CTX_GENERIC_METRIC_FALLBACK_TERMS,
        HELPERS_DUAL_FACT_GENERIC_METRIC_TERMS,
        HELPERS_METRIC_AGG_INTENT_TERMS,
        HELPERS_ROLLUP_LEGACY_METRIC_TERMS,
        HELPERS_WINNER_ROW_RANKING_SIGNAL_TERMS,
        winner_row_aggregate_metric_terms(),
        winner_row_grouped_report_metric_terms(),
    )
    return {term for term in terms if term not in temporal_terms}


def _winner_row_metric_alt(default: str = r"$^") -> str:
    return _regex_alt_from_terms(_winner_row_metric_terms(), default)


def _verb_stem_pattern(stem: str) -> str:
    s = str(stem or "").strip().lower()
    if not s:
        return ""
    if s.endswith("e"):
        base = re.escape(s[:-1])
        return rf"{base}(?:e|es|ed|ing)"
    base = re.escape(s)
    return rf"{base}(?:s|ed|ing)?"


def _hierarchical_collection_pattern(ctx: str = "") -> str:
    verb_patterns = [
        _verb_stem_pattern(stem)
        for stem in sorted(HELPERS_HIERARCHICAL_COLLECTION_VERB_STEMS)
        if str(stem or "").strip()
    ]
    verb_alt = f"(?:{'|'.join(v for v in verb_patterns if v)})" if verb_patterns else r"(?:collected|handled|managed|owned)"
    possessive_alt = _regex_alt_from_terms(
        {
            str(term).strip().lower()
            for term in HELPERS_HIERARCHICAL_COLLECTION_POSSESSIVES
            if str(term).strip()
        },
        r"(?:their|its|his|her)",
    )
    entity_alt = _regex_alt_from_terms(
        _entity_terms_from_ctx(ctx),
        r"(?:[A-Za-z_][A-Za-z0-9_]*(?:\s+[A-Za-z_][A-Za-z0-9_]*)*)",
    )
    return (
        rf"\b(?:{verb_alt})\s+by\b"
        rf"|"
        rf"\bby\s+{possessive_alt}(?:\s+{entity_alt})?\b"
    )


def _table_object_terms(table: str) -> Set[str]:
    t = (table or "").strip().lower().strip("`")
    if not t:
        return set()

    terms: Set[str] = set()
    singular = _to_singular(t)
    for base in {t, singular}:
        if not base:
            continue
        terms.add(base)
        if "_" in base:
            terms.add(base.replace("_", " "))

    try:
        synonyms = get_table_synonyms(t)
    except Exception:
        synonyms = []

    for syn in synonyms:
        s = str(syn or "").strip().lower()
        if not s:
            continue
        singular_syn = _to_singular(s)
        for base in {s, singular_syn}:
            if not base:
                continue
            terms.add(base)
            if "_" in base:
                terms.add(base.replace("_", " "))

    return {term for term in terms if term}


def _table_support_action_terms(table: str) -> Set[str]:
    stems: Set[str] = set()
    for term in _table_object_terms(table):
        compact = re.sub(r"[^a-z]", "", str(term or "").lower())
        if not compact or len(compact) < 3:
            continue
        stems.add(compact)
        if compact.endswith("s") and len(compact) >= 4:
            stems.add(compact[:-1])
        if compact.endswith("ment") and len(compact) >= 6:
            stems.add(compact[:-4])

    actions: Set[str] = set()
    for stem in list(stems):
        if not stem or len(stem) < 3:
            continue
        if stem.endswith("e"):
            actions.add(f"{stem}d")
            if len(stem) > 1:
                actions.add(f"{stem[:-1]}ing")
        else:
            actions.add(f"{stem}ed")
            actions.add(f"{stem}ing")
        if stem.endswith("y") and len(stem) > 3:
            actions.add(f"{stem[:-1]}ied")

    if "pay" in stems:
        actions.add("paid")

    return {action for action in actions if action and len(action) >= 4}


def _inner_join_object_tables(ctx: str = "") -> Set[str]:
    allowed = _parse_allowed_identifiers(ctx)
    scoped_tables = {t.lower() for t in allowed.keys()} if allowed else set()
    try:
        tx_tables = {t.lower() for t in get_transaction_tables()}
    except Exception:
        tx_tables = set()

    if scoped_tables and tx_tables:
        return scoped_tables.intersection(tx_tables)
    if tx_tables:
        return tx_tables
    return set()


def _question_compat_inner_join_terms(question: str, terms: Set[str]) -> Set[str]:
    q = (question or "").lower().strip()
    if not q:
        return set()

    q_tokens = set(re.findall(r"[a-z0-9]+", q))
    matched: Set[str] = set()
    for term in terms:
        t = str(term or "").strip().lower()
        if not t:
            continue
        if " " in t:
            pat = re.escape(t).replace(r"\ ", r"\s+")
            if re.search(rf"\b{pat}\b", q, flags=re.I):
                matched.add(t)
            continue
        if t in q_tokens:
            matched.add(t)
    return matched


def _question_compat_metric_terms(question: str, terms: Set[str]) -> Set[str]:
    q = (question or "").lower().strip()
    if not q:
        return set()

    q_tokens = set(re.findall(r"[a-z0-9]+", q))
    matched: Set[str] = set()
    for term in terms:
        t = str(term or "").strip().lower()
        if not t:
            continue
        term_tokens = [tok for tok in re.findall(r"[a-z0-9]+", t) if tok]
        if not term_tokens:
            continue
        if all(tok in q_tokens for tok in term_tokens):
            matched.add(t)
    return matched


def _inner_join_specific_object_terms(ctx: str = "", question: str = "") -> Set[str]:
    obj_terms: Set[str] = set()
    for table in _inner_join_object_tables(ctx):
        obj_terms.update(_table_object_terms(table))
    if not obj_terms and DOMAIN_HEURISTICS_ENABLED:
        compat_terms = _question_compat_inner_join_terms(question, HELPERS_INNER_JOIN_COMPAT_OBJECT_TERMS)
        obj_terms.update(compat_terms)
    return {term for term in obj_terms if term}


def _inner_join_action_terms(ctx: str = "", question: str = "") -> Set[str]:
    verbs: Set[str] = set()
    for table in _inner_join_object_tables(ctx):
        verbs.update(_table_support_action_terms(table))
    if not verbs and DOMAIN_HEURISTICS_ENABLED:
        compat_verbs = _question_compat_inner_join_terms(question, HELPERS_EXISTENCE_COMPAT_VERBS)
        verbs.update(compat_verbs)
    return {verb for verb in verbs if verb and verb not in HELPERS_EXISTENCE_SUPPORT_VERBS_GENERIC}


def _dual_fact_normalize_family(raw: str) -> str:
    tokens = [
        tok for tok in re.findall(r"[a-z0-9]+", str(raw or "").lower())
        if tok and tok not in HELPERS_DUAL_FACT_FAMILY_STOPWORDS
    ]
    if not tokens:
        return ""

    normalized = [_to_singular(tok) for tok in tokens[:3]]
    return " ".join(tok for tok in normalized if tok).strip()


def _dual_fact_collect_families(pattern: str, text: str) -> Set[str]:
    families: Set[str] = set()
    for match in re.finditer(pattern, text or "", flags=re.I):
        fam = _dual_fact_normalize_family(match.group(1))
        if fam:
            families.add(fam)
    return families


def _dual_fact_metric_terms_for_table(table_name: str, analyzer: Any = None) -> Set[str]:
    metric_terms: Set[str] = set()
    compat_terms = set(HELPERS_DUAL_FACT_GENERIC_METRIC_TERMS)
    if analyzer is None:
        return metric_terms

    try:
        table_columns = analyzer.get_table_columns(table_name)
    except Exception:
        table_columns = []

    noise_terms = {
        "id", "ids", "code", "codes", "key", "keys", "name", "names",
        "number", "numbers", "date", "dates", "year", "years",
        "month", "months", "day", "days", "type", "types",
        "status", "record", "records", "row", "rows",
    }

    for col in table_columns:
        role = ""
        try:
            role = str(get_column_role(table_name, col) or "").strip().lower()
        except Exception:
            role = ""

        candidate_texts = [str(col or "")]
        try:
            candidate_texts.extend(analyzer.get_column_synonyms(table_name, col) or [])
        except Exception:
            pass

        col_tokens: Set[str] = set()
        for text in candidate_texts:
            normalized = re.sub(
                r"([a-z0-9])([A-Z])",
                r"\1 \2",
                str(text or "").replace("_", " ").lower(),
            )
            col_tokens.update(
                tok for tok in re.findall(r"[a-z0-9]+", normalized)
                if tok and tok not in noise_terms
            )

        if role in {"metric", "measure", "amount", "quantity"}:
            metric_terms.add("total")
            metric_terms.update(tok for tok in col_tokens if len(tok) >= 3)

        metric_terms.update(col_tokens.intersection(compat_terms))

    return metric_terms


def _dual_fact_metric_term_universe(
    table_names: Set[str],
    analyzer: Any = None,
    question: str = "",
) -> Set[str]:
    metric_words: Set[str] = set()
    for table_name in sorted(table_names):
        metric_words.update(_dual_fact_metric_terms_for_table(table_name, analyzer=analyzer))
    active_compat_terms: Set[str] = set(HELPERS_DUAL_FACT_GENERIC_METRIC_TERMS)
    if DOMAIN_HEURISTICS_ENABLED and question:
        active_compat_terms.update(
            _question_compat_metric_terms(question, HELPERS_DUAL_FACT_DOMAIN_METRIC_TERMS)
        )
    if not metric_words:
        metric_words.update(active_compat_terms)
    else:
        metric_words.update(active_compat_terms)
    return metric_words


def _status_request_for_table_question(question: str, table_name: str) -> bool:
    """
    Detect generic "<entity> status" style requests from question text.

    Kept module-level so dual-fact detectors and rewriters can share the same
    schema-driven logic without relying on a nested helper scope.
    """
    q = (question or "").lower().strip()
    if not q:
        return False

    entity_terms = [
        str(term or "").strip().lower()
        for term in _entity_words_for_table(table_name)
        if str(term or "").strip()
    ]
    if not entity_terms:
        return False

    entity_alt = "|".join(
        re.escape(term).replace(r"\ ", r"\s+")
        for term in sorted(set(entity_terms), key=len, reverse=True)
    )
    if not entity_alt:
        return False

    return bool(
        re.search(
            rf"\b(?:{entity_alt})[_\s-]*status\b",
            q,
            flags=re.I,
        )
    )

def _canonicalize_table_names(sql: str, ctx: str) -> str:
    """
    Rewrite nama table di FROM/JOIN agar sesuai persis dengan ALLOWED IDENTIFIERS (termasuk casing).
    Ini mengatasi kasus LLM menulis Orders padahal tabelnya orders.
    """
    if not sql or not ctx:
        return sql

    allowed = _parse_allowed_identifiers(ctx)
    if not allowed:
        return sql

    def _normalize_table_token(name: str) -> str:
        return re.sub(r"[^a-z0-9]+", "", str(name or "").strip().lower())

    # lower(table) -> canonical table name dari ALLOWED
    canon_by_lower = {t.lower(): t for t in allowed.keys()}
    canon_forms: Dict[str, Set[str]] = {}
    for canon in allowed.keys():
        canon_l = str(canon or "").strip().lower()
        if not canon_l:
            continue
        forms = {canon_l}
        singular = str(get_singular_form(canon_l) or "").strip().lower()
        if singular:
            forms.add(singular)
        for form in forms:
            form_norm = _normalize_table_token(form)
            if form_norm:
                canon_forms.setdefault(str(canon).strip(), set()).add(form_norm)

    def _resolve_table_candidate(raw_table: str) -> Optional[str]:
        raw = str(raw_table or "").strip()
        if not raw:
            return None
        exact = canon_by_lower.get(raw.lower())
        if exact:
            return exact

        raw_norm = _normalize_table_token(raw)
        if len(raw_norm) < 5:
            return None

        scored: List[Tuple[int, int, str]] = []
        for canon, form_set in canon_forms.items():
            best_score = None
            best_gap = None
            for form_norm in form_set:
                if not form_norm:
                    continue
                if form_norm == raw_norm:
                    return canon
                if form_norm.startswith(raw_norm):
                    gap = len(form_norm) - len(raw_norm)
                    if gap > 4:
                        continue
                    score = len(raw_norm)
                elif raw_norm.startswith(form_norm):
                    gap = len(raw_norm) - len(form_norm)
                    if gap > 2:
                        continue
                    score = len(form_norm) - gap
                else:
                    continue
                if best_score is None or score > best_score or (score == best_score and gap < (best_gap or 999)):
                    best_score = score
                    best_gap = gap
            if best_score is not None and best_gap is not None:
                scored.append((best_score, -best_gap, canon))

        if not scored:
            return None
        scored.sort(reverse=True)
        top_score, top_gap_neg, top_canon = scored[0]
        tied = [
            canon for score, gap_neg, canon in scored
            if score == top_score and gap_neg == top_gap_neg
        ]
        if len(tied) == 1:
            return top_canon
        return None

    # Match FROM/JOIN <db.?>table <alias?>
    pat = re.compile(
        r"(\bFROM\s+|\bJOIN\s+)"
        r"((?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*)"
        r"(\s+(?:AS\s+)?[A-Za-z_][A-Za-z0-9_]*\b)?",
        flags=re.IGNORECASE,
    )

    def repl(m: re.Match) -> str:
        kw = m.group(1)
        full = m.group(2)
        alias = m.group(3) or ""

        if "." in full:
            db, tbl = full.split(".", 1)
            canon = _resolve_table_candidate(tbl)
            if not canon:
                return m.group(0)
            return f"{kw}{db}.{canon}{alias}"

        canon = _resolve_table_candidate(full)
        if not canon:
            return m.group(0)
        return f"{kw}{canon}{alias}"

    return pat.sub(repl, sql)

def _alias_for_table(table: str, used: set[str]) -> str:
    """
    Deterministic alias WITHOUT hardcoded overrides.
    LLM is free to generate its own aliases - this function is only
    used when aliases need to be auto-generated (e.g., in heuristic fixes).

    Strategy: 1-2 letters from table name, increasing until unique
    """
    t = (table or "").strip("`").split(".")[-1]  # drop schema if any
    tl = t.lower()

    # generic fallback
    # e.g. products -> pr, productlines -> pl, etc.
    # keep it short but avoid collisions
    for k in range(1, min(4, len(tl)) + 1):
        cand = tl[:k]
        if cand not in used:
            used.add(cand)
            return cand

    # last resort
    i = 2
    while f"{tl[0]}{i}" in used:
        i += 1
    cand = f"{tl[0]}{i}"
    used.add(cand)
    return cand

def _split_outside_quotes(sql: str) -> List[str]:
    # reuse your existing approach (same regex style you already use)
    return re.split(r"('(?:''|[^'])*'|\"(?:\"\"|[^\"])*\"|`[^`]*`)", sql)

def has_join(sql: str) -> bool:
    return re.search(rf"\b{_JOIN_KW}\b", sql, flags=re.I) is not None

