def join_count(sql: str) -> int:
    if not sql:
        return 0
    return len(re.findall(r"\bjoin\b", sql, flags=re.I))

def _self_fk_columns_by_table(ctx: str = "") -> Dict[str, List[Tuple[str, str]]]:
    """
    Derive self-referential FK-like columns in a schema-driven way.
    Prefer explicit FK graph self-edges, then fallback to metadata hints where
    a FK-hinted column references the same table identifier column in its
    description/synonyms.
    """
    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}

    allowed_tables: Set[str] = set()
    if ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx) or {}
        except Exception:
            allowed = {}
        allowed_tables = {
            str(t or "").strip().strip("`").lower()
            for t in (allowed or {}).keys()
            if str(t or "").strip()
        }

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    def _dtype_family(dtype: str) -> str:
        d = str(dtype or "").upper()
        if any(tok in d for tok in ("INT", "DECIMAL", "NUMERIC", "FLOAT", "DOUBLE", "REAL")):
            return "numeric"
        if any(tok in d for tok in ("CHAR", "TEXT", "CLOB", "STRING")):
            return "text"
        if any(tok in d for tok in ("DATE", "TIME", "YEAR")):
            return "temporal"
        return d.strip().lower()

    def _compatible_identifier_datatype(table_name: str, left_col: str, right_col: str) -> bool:
        try:
            left_family = _dtype_family(get_column_datatype(table_name, left_col))
            right_family = _dtype_family(get_column_datatype(table_name, right_col))
        except Exception:
            return False
        return bool(left_family and right_family and left_family == right_family)

    out: Dict[str, List[Tuple[str, str]]] = {}

    # 1) Explicit self-edge from FK graph.
    for src_table, rels in (fk_raw or {}).items():
        src_l = str(src_table or "").strip().strip("`").lower()
        if not src_l:
            continue
        if allowed_tables and src_l not in allowed_tables:
            continue
        id_col_l = str(get_id_column(src_l) or "").strip().strip("`").lower()
        if not id_col_l:
            continue
        for fk_col, target_table in (rels or {}).items():
            fk_l = str(fk_col or "").strip().strip("`").lower()
            target_l = str(target_table or "").strip().strip("`").lower()
            if fk_l and target_l == src_l:
                bucket = out.setdefault(src_l, [])
                if (fk_l, id_col_l) not in bucket:
                    bucket.append((fk_l, id_col_l))

    # 2) Conservative fallback from metadata hints (for profiles that omit
    # explicit self-edge in get_fk_relationships).
    if analyzer is not None:
        try:
            source_tables = list(allowed_tables) if allowed_tables else list(get_all_tables() or [])
        except Exception:
            source_tables = list(allowed_tables)

        fk_hints = getattr(analyzer, "_column_foreign_key_hints", {}) or {}
        for table_name in source_tables:
            table_l = str(table_name or "").strip().strip("`").lower()
            if not table_l:
                continue
            id_col_l = str(get_id_column(table_l) or "").strip().strip("`").lower()
            if not id_col_l:
                continue
            try:
                columns = [str(c or "").strip().strip("`").lower() for c in analyzer.get_table_columns(table_l) or []]
            except Exception:
                columns = []
            for col_l in columns:
                if not col_l or col_l == id_col_l:
                    continue
                key = f"{table_l}.{col_l}"
                if not fk_hints.get(key):
                    continue
                if not _compatible_identifier_datatype(table_l, col_l, id_col_l):
                    continue

                candidate_texts: List[str] = [col_l]
                try:
                    candidate_texts.extend(analyzer.get_column_synonyms(table_l, col_l) or [])
                except Exception:
                    pass
                try:
                    desc = analyzer.get_column_description(table_l, col_l)
                except Exception:
                    desc = ""
                if desc:
                    candidate_texts.append(str(desc))

                # Require explicit mention of the same-table identifier token to
                # keep this fallback conservative.
                joined_tokens = re.sub(
                    r"[^a-z0-9]+",
                    "",
                    " ".join(str(x or "") for x in candidate_texts).lower(),
                )
                if not joined_tokens or id_col_l not in joined_tokens:
                    continue

                bucket = out.setdefault(table_l, [])
                if (col_l, id_col_l) not in bucket:
                    bucket.append((col_l, id_col_l))

    return out

def _self_fk_role_terms_from_schema(ctx: str = "") -> Set[str]:
    """
    Build hierarchy-role lexicon from schema self-FK metadata, agnostically.
    """
    self_fk_by_table = _self_fk_columns_by_table(ctx)
    if not self_fk_by_table:
        return set()

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    def _identifier_tokens(text: str) -> List[str]:
        split = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or ""))
        return [
            tok
            for tok in re.findall(r"[a-z0-9]+", split.replace("_", " ").replace("-", " ").lower())
            if tok
        ]

    terms: Set[str] = set()
    for table_l, pairs in self_fk_by_table.items():
        for fk_col_l, _ in pairs:
            candidate_texts = [fk_col_l]
            if analyzer is not None:
                try:
                    candidate_texts.extend(analyzer.get_column_synonyms(table_l, fk_col_l) or [])
                except Exception:
                    pass
                try:
                    desc = analyzer.get_column_description(table_l, fk_col_l)
                except Exception:
                    desc = ""
                if desc:
                    candidate_texts.append(str(desc))

            for raw in candidate_texts:
                toks = _identifier_tokens(raw)
                if not toks:
                    continue
                phrase = " ".join(toks).strip()
                if len(phrase) >= 3:
                    terms.add(phrase)
                for tok in toks:
                    if len(tok) >= 4:
                        terms.add(tok)

    return terms

def _question_requires_self_fk_parent_presence(question: str, ctx: str = "") -> bool:
    """
    Detect parent-presence filtering intent for self-referential relations using
    schema-derived hierarchy terms (no table/question hardcoding).
    """
    q = (question or "").lower()
    if not q:
        return False

    entity_terms = _entity_terms_from_ctx(ctx)
    if not entity_terms:
        return False

    # Require repeated same-entity mention (e.g., "employee ... another employee")
    # to avoid over-triggering on simple lookup phrasing.
    entity_mentions = 0
    for ent in entity_terms:
        ent_pat = re.escape(str(ent or "").strip().lower()).replace(r"\ ", r"\s+")
        if not ent_pat:
            continue
        entity_mentions += len(re.findall(rf"\b{ent_pat}\b", q, flags=re.I))
        if entity_mentions >= 2:
            break
    if entity_mentions < 2:
        return False

    role_terms = _self_fk_role_terms_from_schema(ctx)
    if not role_terms:
        return False

    for term in sorted((t for t in role_terms if t), key=len, reverse=True):
        pat = re.escape(term.lower()).replace(r"\ ", r"\s+")
        if re.search(rf"\b{pat}\b", q, flags=re.I):
            return True
    return False

def _question_requires_inner_join(question: str, ctx: str = "") -> bool:
    """
    Detect explicit filtering intent that should EXCLUDE non-matching parent rows.
    This implies INNER JOIN semantics for multi-table queries.
    """
    q = (question or "").lower()
    if not q:
        return False

    entity_kw = _build_entity_kw(ctx)
    entity_terms = _entity_terms_from_ctx(ctx)

    # include-zero intent should win over inner-join filtering
    if any(s in q for s in HELPERS_INNER_JOIN_INCLUDE_ZERO_OVERRIDES):
        if re.search(rf"\b{entity_kw}\b", q, flags=re.I):
            return False

    for ent in entity_terms:
        if (
            f"including {ent} with no" in q
            or f"{ent} with no" in q
        ):
            return False

    has_entity_mention = re.search(rf"\b{entity_kw}\b", q, flags=re.I) is not None

    # Hierarchical self-FK parent-presence intent:
    # derive role terms from schema metadata (column name/synonyms), then
    # require repeated entity mention to infer same-entity relationship filtering.
    if has_entity_mention and _question_requires_self_fk_parent_presence(question, ctx):
        return True

    # Explicit existence filters (without requiring "only"), schema-driven:
    # - "customers with payments"
    # - "authors with books"
    # - "users who have sessions"
    #
    # Build candidate "existence object" terms from transaction-like tables
    # in schema metadata, narrowed by ALLOWED IDENTIFIERS when available.
    specific_obj_terms = _inner_join_specific_object_terms(ctx, question)
    obj_terms = set(specific_obj_terms)
    obj_terms.update(HELPERS_INNER_JOIN_GENERIC_OBJECT_TERMS)
    existence_object = _regex_alt_from_terms(obj_terms, r"(?:records?|rows?)")
    specific_existence_object = _regex_alt_from_terms(
        specific_obj_terms,
        r"(?:records?|rows?)",
    )
    support_action = _regex_alt_from_terms(
        _inner_join_action_terms(ctx, question),
        r"(?:made)",
    )
    has_existence_object = re.search(rf"\b{existence_object}\b", q, flags=re.I) is not None
    has_existence_connector = (
        re.search(r"\b(?:with|having)\b", q, flags=re.I) is not None
        or re.search(r"\b(?:who|that|which)\b.{0,80}\b(?:have|has|had)\b", q, flags=re.I) is not None
        or re.search(r"\b(?:have|has|had)\b.{0,80}\b(?:at\s+least\s+one|any)\b", q, flags=re.I) is not None
    )
    if has_entity_mention and has_existence_object and has_existence_connector:
        return True

    # Generic quantified existence intent:
    # "X that have at least one Y ...", "X with any Y ..."
    # Keep this schema-driven and avoid table-name hardcoding.
    has_quantified_existence = re.search(
        r"\b(?:at\s+least\s+one|one\s+or\s+more|any)\b",
        q,
        flags=re.I,
    ) is not None
    if has_entity_mention and has_existence_connector and has_quantified_existence:
        mentioned_entity_roots: Set[str] = set()
        for ent in entity_terms:
            e = (ent or "").lower().strip()
            if not e:
                continue
            if re.search(rf"\b{re.escape(e)}\b", q, flags=re.I):
                mentioned_entity_roots.add(_to_singular(e))
        has_multi_entity_mentions = len(mentioned_entity_roots) >= 2
        if has_existence_object or has_multi_entity_mentions:
            return True

    # Aggregate comparison across related entities implies filtering intent.
    # Example: "offices where average credit limit of customers assigned to employees
    # in that office is higher than overall average ..."
    mentioned_entity_roots: Set[str] = set()
    for ent in entity_terms:
        e = (ent or "").lower().strip()
        if not e:
            continue
        if re.search(rf"\b{re.escape(e)}\b", q, flags=re.I):
            mentioned_entity_roots.add(_to_singular(e))

    has_multi_entity_mentions = len(mentioned_entity_roots) >= 2
    has_aggregate_intent = re.search(
        r"\b(?:avg|average|mean|sum|total|count|min|max)\b",
        q,
        flags=re.I,
    ) is not None
    has_comparison_intent = re.search(
        r"\b(?:higher|greater|more|above|over|lower|less|below|under)\s+than\b|[<>]=?",
        q,
        flags=re.I,
    ) is not None
    has_relation_intent = re.search(
        r"\b(?:of|from|assigned\s+to|linked\s+to|related\s+to|belongs?\s+to)\b",
        q,
        flags=re.I,
    ) is not None
    if has_multi_entity_mentions and has_aggregate_intent and has_comparison_intent and has_relation_intent:
        return True

    if not re.search(r"\bonly\b", q):
        return False

    # "only products that have been ordered", "only customers who have placed orders"
    pat_relative_clause = rf"""
        \bonly\s+{entity_kw}\b
        .*?
        \b(?:who|that|which)\b
        .*?
        \b(?:have|has|had)\b
        (?:\s+\w+){{0,4}}
        \s+
        \b(?:{support_action}|{specific_existence_object})\b
    """
    if re.search(pat_relative_clause, q, flags=re.I | re.X):
        return True

    # "only customers with orders", "only products having transactions"
    pat_with_having = rf"""
        \bonly\s+{entity_kw}\b
        .*?
        \b(?:with|having)\b
        (?:\s+\w+){{0,4}}
        \b{specific_existence_object}\b
    """
    if re.search(pat_with_having, q, flags=re.I | re.X):
        return True

    return False

def _question_wants_include_zero(question: str, ctx: str = "") -> bool:
    q = (question or "").lower()
    if not q:
        return False

    # Offset-window NULL fallback phrasing (e.g., "if there is no next payment,
    # show NULL") is not include-zero parent-row intent.
    if re.search(
        r"\b(?:no|without(?:\s+any)?)\b(?:[\s,;:()'\"-]+\w+){0,3}[\s,;:()'\"-]+"
        r"\b(?:next|previous|prior|following)\b",
        q,
        flags=re.I,
    ) and re.search(
        r"\b(?:next|previous|prior|following)\b",
        q,
        flags=re.I,
    ):
        return False

    entity_kw = _build_entity_kw(ctx)
    entity_terms = _entity_terms_from_ctx(ctx)

    # Existence-filter intent must take precedence over broad "for each" wording.
    # Example: "customers with payments, and for each customer ..."
    if _question_requires_inner_join(question, ctx):
        return False

    if any(re.search(pat, q, flags=re.I | re.S) for pat in HELPERS_ZERO_FILL_OUTPUT_PATTERNS if pat):
        return True

    # --- LOGIKA SIGNALS (Tetap sama) ---
    if any(s in q for s in HELPERS_INNER_JOIN_INCLUDE_ZERO_OVERRIDES):
        # Require at least one entity mention for generic terms
        if re.search(rf"\b{entity_kw}\b", q, flags=re.I):
            return True

    # Dynamic include-zero phrasing should stay conservative.
    # "all/every/for each" alone is not enough to imply preserve-zero semantics.
    for ent in entity_terms:
        if (
            f"including {ent} with no" in q
            or f"{ent} with no" in q
        ):
            return True

    if re.search(rf"\b{entity_kw}\b.*\b(without|with\s+no|no)\b", q, flags=re.I):
        return True
    
    return False

def _rewrite_left_join_to_inner_if_not_needed(sql: str, question: str, ctx: str = "") -> str:
    if not sql or _question_wants_include_zero(question, ctx):
        return sql
    if join_count(sql) != 1:
        return sql
    if not re.search(r"\bleft\s+join\b", sql, flags=re.I):
        return sql

    # Preserve anti-join semantics:
    # LEFT JOIN ... WHERE rhs.col IS NULL is a valid exclusion pattern and
    # must not be weakened to INNER JOIN.
    if _single_left_join_has_rhs_is_null_filter(sql):
        return sql

    # Kalau ada referensi RHS alias/table di SELECT/GROUP/ORDER/HAVING,
    # itu biasanya artinya user memang ingin baris RHS (bukan preserve-zeros).
    # Maka LEFT JOIN tidak diperlukan.
    m = re.search(
        r"\bFROM\b.*?\bLEFT\s+JOIN\b\s+(?P<t2>`?[A-Za-z_]\w*`?)(?:\s+(?:AS\s+)?(?P<a2>[A-Za-z_]\w*))?",
        sql,
        flags=re.I | re.S,
    )
    if not m:
        return sql

    t2 = (m.group("t2") or "").strip("`")
    a2 = (m.group("a2") or "").strip()
    rhs = a2 or t2
    if not rhs:
        return sql

    # cek penggunaan rhs.<col> di luar ON
    masked = re.sub(r"\bON\b\s+.*?(?=(\bWHERE\b|\bGROUP\s+BY\b|\bORDER\s+BY\b|\bHAVING\b|\bLIMIT\b|;|$))",
                    " ", sql, flags=re.I | re.S)
    if re.search(rf"\b{re.escape(rhs)}\s*\.", masked, flags=re.I):
        return re.sub(r"\bLEFT\s+JOIN\b", "JOIN", sql, count=1, flags=re.I)

    return sql

def _rewrite_required_self_fk_left_join_to_inner(sql: str, ctx: str = "") -> str:
    """
    Convert LEFT JOIN -> JOIN only for schema-backed self-FK parent lookups.

    Conservative rewrite target:
      child_alias.self_fk = parent_alias.id
    where the joined table is the same base table and parent_alias is on the
    identifier side. This keeps the fix agnostic (schema-driven, no table names).
    """
    if not sql or not re.search(r"\bleft\s+join\b", sql, flags=re.I):
        return sql

    self_fk_by_table = _self_fk_columns_by_table(ctx)
    if not self_fk_by_table:
        return sql

    join_pat = re.compile(
        r"""
        \bLEFT\s+JOIN\s+(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?)
        (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
        \s+\bON\b\s+(?P<on>.*?)
        (?=
            \s+\b(?:LEFT|RIGHT|INNER|FULL|CROSS)?\s*JOIN\b
            |\s+\bWHERE\b
            |\s+\bGROUP\s+BY\b
            |\s+\bORDER\s+BY\b
            |\s+\bHAVING\b
            |\s+\bLIMIT\b
            |;
            |$
        )
        """,
        flags=re.I | re.S | re.X,
    )

    def _segment_needs_inner(joined_table: str, joined_alias: str, on_clause: str) -> bool:
        table_l = str(joined_table or "").strip().strip("`").lower()
        if table_l not in self_fk_by_table:
            return False
        rhs_alias = str(joined_alias or table_l).strip().strip("`")
        if not rhs_alias:
            return False

        rhs_alias_l = rhs_alias.lower()
        for fk_col_l, id_col_l in self_fk_by_table.get(table_l, []):
            fk_pat = rf"`?{re.escape(fk_col_l)}`?"
            id_pat = rf"`?{re.escape(id_col_l)}`?"

            lhs_fk_eq_rhs_id = re.search(
                rf"\b(?P<lhs>[A-Za-z_][A-Za-z0-9_]*)\s*\.\s*{fk_pat}\s*=\s*"
                rf"{re.escape(rhs_alias)}\s*\.\s*{id_pat}\b",
                on_clause,
                flags=re.I,
            )
            if lhs_fk_eq_rhs_id and str(lhs_fk_eq_rhs_id.group("lhs") or "").lower() != rhs_alias_l:
                return True

            rhs_id_eq_lhs_fk = re.search(
                rf"\b{re.escape(rhs_alias)}\s*\.\s*{id_pat}\s*=\s*"
                rf"(?P<lhs>[A-Za-z_][A-Za-z0-9_]*)\s*\.\s*{fk_pat}\b",
                on_clause,
                flags=re.I,
            )
            if rhs_id_eq_lhs_fk and str(rhs_id_eq_lhs_fk.group("lhs") or "").lower() != rhs_alias_l:
                return True

        return False

    changed = False

    def _convert_if_needed(m: re.Match) -> str:
        nonlocal changed
        table_raw = m.group("table") or ""
        alias_raw = m.group("alias") or ""
        on_clause = m.group("on") or ""
        if _segment_needs_inner(table_raw, alias_raw, on_clause):
            changed = True
            return re.sub(r"\bLEFT\s+JOIN\b", "JOIN", m.group(0), count=1, flags=re.I)
        return m.group(0)

    rewritten = join_pat.sub(_convert_if_needed, sql)
    if changed:
        print("[Logic] Converted required self-FK parent LEFT JOIN to INNER JOIN")
    return rewritten

def _rewrite_left_join_to_inner_if_rhs_filtered(sql: str, question: str, ctx: str = "") -> str:
    """
    Generic Fix 2:
    If a LEFT JOIN's RHS is filtered in WHERE, it is semantically an INNER JOIN.
    Convert LEFT JOIN -> JOIN, unless the question explicitly wants include-zero rows.
    Works with or without aliases.
    """
    if not sql:
        return sql
    if _question_wants_include_zero(question, ctx):
        return sql
    if _single_left_join_has_rhs_is_null_filter(sql):
        return sql

    # Existence/filtering intent should use INNER semantics even when RHS filters
    # were already pushed into ON (so WHERE-based detection would miss it).
    # Keep this conservative: only auto-convert for single-join queries.
    if _question_requires_inner_join(question, ctx):
        sql = _rewrite_required_self_fk_left_join_to_inner(sql, ctx)
        if join_count(sql) == 1 and re.search(r"\bleft\s+join\b", sql, flags=re.I):
            return re.sub(r"\bLEFT\s+JOIN\b", "JOIN", sql, count=1, flags=re.I)

    # Only handle the simplest, safest case: exactly one JOIN, and it's a LEFT JOIN.
    if join_count(sql) != 1:
        return sql
    if not re.search(r"\bleft\s+join\b", sql, flags=re.I):
        return sql

    # Capture: FROM <t1> [a1] LEFT JOIN <t2> [a2] ON ... (tail includes WHERE/etc.)
    pat = re.compile(
        r"""
        ^(?P<prefix>.*?)
        \bFROM\s+(?P<t1>`?[A-Za-z_][A-Za-z0-9_]*`?)
        (?:\s+(?:AS\s+)?(?P<a1>[A-Za-z_][A-Za-z0-9_]*))?
        \s+LEFT\s+JOIN\s+(?P<t2>`?[A-Za-z_][A-Za-z0-9_]*`?)
        (?:\s+(?:AS\s+)?(?P<a2>[A-Za-z_][A-Za-z0-9_]*))?
        \s+\bON\s+(?P<on>.*?)
        (?P<tail>\s+(?:WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b.*?|;?\s*)$
        """,
        flags=re.IGNORECASE | re.DOTALL | re.VERBOSE,
    )
    m = pat.match(sql.strip())
    if not m:
        return sql

    t2 = (m.group("t2") or "").strip().strip("`")
    a2 = (m.group("a2") or "").strip()
    tail = m.group("tail") or ""

    # Determine RHS qualifier candidates: alias if exists, else table name.
    rhs_qualifiers = []
    if a2:
        rhs_qualifiers.append(a2)
    if t2:
        rhs_qualifiers.append(t2)

    # Must have WHERE, and WHERE must reference RHS (alias/table). Otherwise keep LEFT JOIN.
    where_m = re.search(r"\bWHERE\b", tail, flags=re.I)
    if not where_m:
        return sql

    # Check RHS usage in WHERE (e.g., "p.paymentDate", "payments.paymentDate")
    rhs_referenced = any(
        re.search(rf"\b{re.escape(q)}\s*\.", tail, flags=re.I) for q in rhs_qualifiers
    )
    if not rhs_referenced:
        return sql

    # Safe rewrite: LEFT JOIN -> JOIN (results preserved due to WHERE filtering RHS)
    prefix = m.group("prefix")
    t1_raw = m.group("t1")
    a1 = m.group("a1")
    t2_raw = m.group("t2")
    on_clause = m.group("on").strip()

    from_part = f"FROM {t1_raw}" + (f" {a1}" if a1 else "")
    join_part = f" JOIN {t2_raw}" + (f" {a2}" if a2 else "")

    return f"{prefix}{from_part}{join_part} ON {on_clause}{tail}"

def _single_left_join_has_rhs_is_null_filter(sql: str) -> bool:
    """
    Detect the anti-join shape in a simple single LEFT JOIN query:
      ... LEFT JOIN rhs ... WHERE rhs.some_col IS NULL ...

    This pattern is semantically exclusion-oriented and should keep LEFT JOIN.
    """
    s = str(sql or "").strip()
    if not s:
        return False
    if join_count(s) != 1:
        return False
    if not re.search(r"\bleft\s+join\b", s, flags=re.I):
        return False

    pat = re.compile(
        r"""
        ^(?P<prefix>.*?)
        \bFROM\s+(?P<t1>`?[A-Za-z_][A-Za-z0-9_]*`?)
        (?:\s+(?:AS\s+)?(?P<a1>[A-Za-z_][A-Za-z0-9_]*))?
        \s+LEFT\s+JOIN\s+(?P<t2>`?[A-Za-z_][A-Za-z0-9_]*`?)
        (?:\s+(?:AS\s+)?(?P<a2>[A-Za-z_][A-Za-z0-9_]*))?
        \s+\bON\s+(?P<on>.*?)
        (?P<tail>\s+(?:WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b.*?|;?\s*)$
        """,
        flags=re.IGNORECASE | re.DOTALL | re.VERBOSE,
    )
    m = pat.match(s)
    if not m:
        return False

    tail = str(m.group("tail") or "")
    where_m = re.search(r"\bWHERE\b(?P<body>.*)", tail, flags=re.I | re.S)
    if not where_m:
        return False
    where_body = str(where_m.group("body") or "")
    cut_m = re.search(r"\b(GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b", where_body, flags=re.I)
    if cut_m:
        where_body = where_body[:cut_m.start()]
    if not where_body.strip():
        return False

    t2 = str(m.group("t2") or "").strip().strip("`")
    a2 = str(m.group("a2") or "").strip()
    rhs_qualifiers = []
    if a2:
        rhs_qualifiers.append(a2)
    if t2:
        rhs_qualifiers.append(t2)
    if not rhs_qualifiers:
        return False

    return any(
        re.search(
            rf"\b{re.escape(q)}\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?\s+IS\s+NULL\b",
            where_body,
            flags=re.I,
        )
        for q in rhs_qualifiers
    )

def _question_wants_all_entities(question: str, ctx: str = "") -> bool:
    """
    Detect if question explicitly wants ALL entities (including those with no matching RHS).
    E.g., "show ALL customers", "list every customer", "for each customer"
    
    This is more strict than _question_wants_include_zero - only triggers on explicit "all/every/each".
    """
    q = (question or "").lower()
    if not q:
        return False

    # Existence-filter intent (e.g., "have/with at least one ...") must NOT be
    # treated as "all entities"; those queries should prefer INNER semantics.
    if _question_requires_inner_join(question, ctx):
        return False

    entity_kw = _build_entity_kw(ctx)
    
    # Pattern: "all/every/each <entity>"
    # E.g., "all customers", "every customer", "each customer"
    all_patterns = [
        rf"\ball\s+{entity_kw}\b",             # "all customers"
        rf"\bevery\s+{entity_kw}\b",           # "every customer"
        rf"\beach\s+{entity_kw}\b",            # "each customer"
        rf"\bfor\s+each\s+{entity_kw}\b",      # "for each customer"
        rf"\bsemua\s+{entity_kw}\b",           # "semua customers" (Indonesian)
        rf"\bsetiap\s+{entity_kw}\b",          # "setiap customer" (Indonesian)
    ]
    
    return any(re.search(pat, q, flags=re.I) for pat in all_patterns)

def _move_rhs_filter_from_where_to_on(sql: str, question: str, ctx: str = "") -> str:
    """
    For LEFT JOIN queries: Move RHS-only filters from WHERE to ON clause.
    This preserves LEFT JOIN semantics (include rows with no match).
    
    ONLY triggers when question explicitly asks for "ALL" entities.
    
    Example:
    "Show ALL customers and their total payment in 2004"
    FROM customers c LEFT JOIN payments p ON c.id = p.cid WHERE YEAR(p.date) = 2004
    →
    FROM customers c LEFT JOIN payments p ON c.id = p.cid AND YEAR(p.date) = 2004
    """
    if not sql:
        return sql
    
    # SAFETY: Only trigger when question explicitly wants ALL entities
    if not _question_wants_all_entities(question, ctx):
        return sql
    
    # Only handle single LEFT JOIN
    if join_count(sql) != 1:
        return sql
    if not re.search(r"\bleft\s+join\b", sql, flags=re.I):
        return sql
    
    # Parse the query structure
    pat = re.compile(
        r"""
        ^(?P<prefix>.*?)
        \bFROM\s+(?P<t1>`?[A-Za-z_][A-Za-z0-9_]*`?)
        (?:\s+(?:AS\s+)?(?P<a1>[A-Za-z_][A-Za-z0-9_]*))?
        \s+LEFT\s+JOIN\s+(?P<t2>`?[A-Za-z_][A-Za-z0-9_]*`?)
        (?:\s+(?:AS\s+)?(?P<a2>[A-Za-z_][A-Za-z0-9_]*))?
        \s+\bON\s+(?P<on>.*?)
        (?P<tail>\s+(?:WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b.*?|;?\s*)$
        """,
        flags=re.IGNORECASE | re.DOTALL | re.VERBOSE,
    )
    m = pat.match(sql.strip())
    if not m:
        return sql
    
    t1 = (m.group("t1") or "").strip().strip("`")
    a1 = (m.group("a1") or "").strip()
    t2 = (m.group("t2") or "").strip().strip("`")
    a2 = (m.group("a2") or "").strip()
    on_clause = m.group("on").strip()
    tail = m.group("tail") or ""
    prefix = m.group("prefix")
    
    # Get qualifiers for LHS and RHS
    lhs_qualifiers = [q for q in [a1, t1] if q]
    rhs_qualifiers = [q for q in [a2, t2] if q]
    
    if not rhs_qualifiers:
        return sql
    
    # Parse WHERE clause
    where_body, rest_after_where = _split_where_and_rest(tail)
    if not where_body:
        return sql
    
    # Check for OR (too complex, skip)
    if _has_top_level_or(where_body):
        return sql
    
    # Split WHERE conditions by AND
    conditions = _split_top_level_and(where_body)
    if not conditions:
        return sql
    
    # Categorize conditions: RHS-only vs others
    rhs_only_conditions = []
    other_conditions = []
    
    for cond in conditions:
        cond_stripped = cond.strip()
        if not cond_stripped:
            continue
        
        # Check if condition references RHS
        refs_rhs = any(
            re.search(rf"\b{re.escape(q)}\s*\.", cond_stripped, flags=re.I) 
            for q in rhs_qualifiers
        )
        # Check if condition references LHS
        refs_lhs = any(
            re.search(rf"\b{re.escape(q)}\s*\.", cond_stripped, flags=re.I) 
            for q in lhs_qualifiers
        )
        
        # Only move if it ONLY references RHS (not LHS)
        if refs_rhs and not refs_lhs:
            rhs_only_conditions.append(cond_stripped)
        else:
            other_conditions.append(cond_stripped)
    
    # If no RHS-only conditions found, nothing to move
    if not rhs_only_conditions:
        return sql
    
    # Build new ON clause with moved conditions
    new_on_clause = on_clause
    for cond in rhs_only_conditions:
        new_on_clause += f" AND {cond}"
    
    # Build new WHERE clause (if any conditions remain)
    if other_conditions:
        new_where = " WHERE " + " AND ".join(other_conditions)
    else:
        new_where = ""
    
    # Reconstruct query
    t1_raw = m.group("t1")
    t2_raw = m.group("t2")
    from_part = f"FROM {t1_raw}" + (f" {a1}" if a1 else "")
    join_part = f" LEFT JOIN {t2_raw}" + (f" {a2}" if a2 else "")
    
    result = f"{prefix}{from_part}{join_part} ON {new_on_clause}{new_where}{rest_after_where}"
    
    if result != sql:
        print(f"[Logic] Moved RHS filter to ON clause (preserving LEFT JOIN for 'ALL' query)")
    
    return result

def _split_where_and_rest(tail: str) -> tuple[Optional[str], str]:
    """
    tail mulai dari WHERE/GROUP/ORDER/HAVING/LIMIT atau kosong.
    Return: (where_body_or_None, rest_after_where)
    """
    if not tail:
        return None, ""
    m = re.search(r"\bWHERE\b\s+(.*)$", tail, flags=re.I | re.S)
    if not m:
        return None, tail

    after_where = m.group(1)

    # potong saat ketemu clause berikutnya (GROUP BY/ORDER BY/HAVING/LIMIT)
    m2 = re.search(r"\b(GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b", after_where, flags=re.I)
    if not m2:
        return after_where.strip(), ""

    where_body = after_where[:m2.start()].strip()
    rest = after_where[m2.start():]  # include keyword
    return where_body, " " + rest.strip()

def _split_top_level_and(expr: str) -> List[str]:
    """
    Split expr by AND di level top (tidak di dalam tanda kutip / kurung).
    Kalau ada OR top-level, kita abort di caller (biar safe).
    """
    if not expr:
        return []

    s = expr.strip()
    parts = []
    buf = []
    depth = 0
    in_sq = False
    in_dq = False
    i = 0
    while i < len(s):
        ch = s[i]

        # handle quotes
        if ch == "'" and not in_dq:
            # handle escaped '' (double single quote)
            if in_sq and i + 1 < len(s) and s[i + 1] == "'":
                buf.append("''")
                i += 2
                continue
            in_sq = not in_sq
            buf.append(ch)
            i += 1
            continue
        if ch == '"' and not in_sq:
            in_dq = not in_dq
            buf.append(ch)
            i += 1
            continue

        if in_sq or in_dq:
            buf.append(ch)
            i += 1
            continue

        # parentheses nesting
        if ch == "(":
            depth += 1
            buf.append(ch)
            i += 1
            continue
        if ch == ")":
            depth = max(0, depth - 1)
            buf.append(ch)
            i += 1
            continue

        # detect AND at top-level
        if depth == 0 and s[i:i+3].lower() == "and":
            # boundary check
            left_ok = (i == 0) or not s[i-1].isalnum()
            right_ok = (i+3 >= len(s)) or not s[i+3].isalnum()
            if left_ok and right_ok:
                parts.append("".join(buf).strip())
                buf = []
                i += 3
                continue

        buf.append(ch)
        i += 1

    last = "".join(buf).strip()
    if last:
        parts.append(last)
    return [p for p in parts if p]

def _has_top_level_or(expr: str) -> bool:
    # konservatif: jika ada OR di luar quote/paren, kita tidak rewrite
    s = expr.strip()
    depth = 0
    in_sq = False
    in_dq = False
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == "'" and not in_dq:
            if in_sq and i + 1 < len(s) and s[i + 1] == "'":
                i += 2
                continue
            in_sq = not in_sq
            i += 1
            continue
        if ch == '"' and not in_sq:
            in_dq = not in_dq
            i += 1
            continue
        if in_sq or in_dq:
            i += 1
            continue
        if ch == "(":
            depth += 1
            i += 1
            continue
        if ch == ")":
            depth = max(0, depth - 1)
            i += 1
            continue
        if depth == 0 and s[i:i+2].lower() == "or":
            left_ok = (i == 0) or not s[i-1].isalnum()
            right_ok = (i+2 >= len(s)) or not s[i+2].isalnum()
            if left_ok and right_ok:
                return True
        i += 1
    return False

def _on_clause_has_rhs_filter(on_clause: str, rhs_alias: str) -> bool:
    if not on_clause or not rhs_alias:
        return False

    oc = _strip_string_literals(on_clause)

    # 1) operator non-equality yang jelas filter-like
    if re.search(rf"\b{re.escape(rhs_alias)}\.\w+\s*(>=|<=|<>|!=|>|<)\s*", oc, flags=re.I):
        return True
    if re.search(rf"\b{re.escape(rhs_alias)}\.\w+\s+\b(BETWEEN|LIKE|IN|REGEXP|RLIKE)\b", oc, flags=re.I):
        return True
    if re.search(rf"\b{re.escape(rhs_alias)}\.\w+\s+IS\s+(NOT\s+)?NULL\b", oc, flags=re.I):
        return True

    # 2) equality ke literal/angka/param/fungsi juga filter-like
    # rhs.col = 'X' / 123 / (subexpr) / func(...)
    if re.search(rf"\b{re.escape(rhs_alias)}\.\w+\s*=\s*('|\d|\(|\bNULL\b)", oc, flags=re.I):
        return True
    if re.search(rf"\b{re.escape(rhs_alias)}\.\w+\s*=\s*\w+\s*\(", oc, flags=re.I):
        return True

    return False

def _rewrite_inner_join_filter_to_exists(sql: str) -> str:
    """
    Rewrite filter-only INNER JOIN -> EXISTS.
    Syarat aman:
    - exactly 1 JOIN
    - join inner/join (bukan LEFT/RIGHT/FULL)
    - RHS alias tidak dipakai di SELECT/GROUP/ORDER/HAVING (boleh dipakai di WHERE)
    - WHERE tidak punya top-level OR (hanya AND)
    - ada minimal 1 predicate RHS-only di WHERE yang bisa dipindah
    """
    if not sql:
        return sql
    if join_count(sql) != 1:
        return sql
    if re.search(r"\b(left|right|full)\s+join\b", sql, flags=re.I):
        return sql
    # Derived-table joins are too risky for this regex rewrite.
    if re.search(r"\b(?:from|join)\s*\(", sql, flags=re.I):
        return sql

    s0 = sql.strip()

    pat = re.compile(
        r"""
        ^(?P<prefix_select>.*?)
        \bFROM\s+(?P<t1>`?[A-Za-z_][A-Za-z0-9_]*`?)\s+(?:AS\s+)?(?P<a1>[A-Za-z_][A-Za-z0-9_]*)
        \s+\b(?:INNER\s+)?JOIN\s+(?P<t2>`?[A-Za-z_][A-Za-z0-9_]*`?)\s+(?:AS\s+)?(?P<a2>[A-Za-z_][A-Za-z0-9_]*)
        \s+\bON\s+(?P<on>.*?)
        (?P<tail>\s+(?:WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b.*?|;?\s*)$
        """,
        flags=re.I | re.S | re.VERBOSE,
    )
    m = pat.match(s0)
    if not m:
        return sql

    prefix_select = m.group("prefix_select")
    t1, a1 = m.group("t1"), m.group("a1")
    t2, a2 = m.group("t2"), m.group("a2")
    on_clause = (m.group("on") or "").strip()
    tail = m.group("tail") or ""

    where_body, rest_after_where = _split_where_and_rest(tail)

    # kalau tidak ada WHERE, berarti bukan filter-only join -> skip
    if not where_body:
        return sql

    # jangan rewrite kalau ada OR top-level (biar tidak salah distribusi)
    if _has_top_level_or(where_body):
        return sql

    # Pastikan RHS alias tidak dipakai di SELECT/GROUP/ORDER/HAVING
    # Cek bagian SELECT (prefix_select) dan rest_after_where
    if re.search(rf"\b{re.escape(a2)}\s*\.", prefix_select, flags=re.I):
        return sql
    if re.search(rf"\b{re.escape(a2)}\s*\.", rest_after_where, flags=re.I):
        return sql

    # Ambil conjunct AND top-level
    conjuncts = _split_top_level_and(where_body)

    rhs_only = []
    keep = []
    for c in conjuncts:
        c0 = c.strip()
        has_rhs = re.search(rf"\b{re.escape(a2)}\s*\.", c0, flags=re.I) is not None
        has_lhs = re.search(rf"\b{re.escape(a1)}\s*\.", c0, flags=re.I) is not None

        # rhs-only: refer RHS, tidak refer LHS, dan bukan subquery SELECT (konservatif)
        if has_rhs and (not has_lhs) and (re.search(r"\bselect\b", c0, flags=re.I) is None):
            rhs_only.append(c0)
        else:
            keep.append(c0)

    on_has_rhs_filter = _on_clause_has_rhs_filter(on_clause, a2)

    # kalau tidak ada rhs_only dari WHERE dan ON juga tidak filter-like → bukan filter-only join
    if (not rhs_only) and (not on_has_rhs_filter):
        return sql

    rhs_filters = " AND ".join(rhs_only) if rhs_only else ""

    exists_where = on_clause
    if rhs_filters:
        exists_where = f"{on_clause} AND {rhs_filters}"
        
    if rhs_filters:
        exists_expr = f"EXISTS (SELECT 1 FROM {t2} {a2} WHERE {on_clause} AND {rhs_filters})"
    else:
        exists_expr = f"EXISTS (SELECT 1 FROM {t2} {a2} WHERE {on_clause})"

    new_where_parts = []
    if keep:
        new_where_parts.append(" AND ".join(keep))
    new_where_parts.append(exists_expr)

    new_where = " WHERE " + " AND ".join(new_where_parts)

    return f"{prefix_select}FROM {t1} {a1}{new_where}{(' ' + rest_after_where.strip()) if rest_after_where.strip() else ''}"

def _question_wants_anti_existence(question: str, ctx: str = "") -> bool:
    q = (question or "").lower()
    entity_kw = _build_entity_kw(ctx)

    if any_phrase_in_text(q, existence_anti_phrases()):
        return True

    if re.search(rf"\bno\s+{entity_kw}\b", q, flags=re.I):
        return True
    if re.search(rf"\bwithout\s+(?:any\s+)?{entity_kw}\b", q, flags=re.I):
        return True
    if re.search(rf"\btanpa\s+{entity_kw}\b", q, flags=re.I):
        return True

    return False

def _question_wants_existence(question: str) -> bool:
    q = (question or "").lower()
    return any_phrase_in_text(q, existence_positive_phrases())

def _rewrite_inner_join_existence_to_exists(sql: str, question: str, ctx: str = "") -> str:
    if not sql:
        return sql
    if join_count(sql) != 1:
        return sql
    if re.search(r"\b(left|right|full)\s+join\b", sql, flags=re.I):
        return sql
    # Derived-table joins are too risky for this regex rewrite.
    if re.search(r"\b(?:from|join)\s*\(", sql, flags=re.I):
        return sql
    if _question_wants_anti_existence(question, ctx):
        return sql
    if not _question_wants_existence(question):
        return sql

    s0 = sql.strip()

    pat = re.compile(
        r"""
        ^(?P<prefix>.*?)
        \bFROM\s+(?P<t1>`?[A-Za-z_][A-Za-z0-9_]*`?)\s+(?:AS\s+)?(?P<a1>[A-Za-z_][A-Za-z0-9_]*)
        \s+\b(?:INNER\s+)?JOIN\s+(?P<t2>`?[A-Za-z_][A-Za-z0-9_]*`?)\s+(?:AS\s+)?(?P<a2>[A-Za-z_][A-Za-z0-9_]*)
        \s+\bON\s+(?P<on>.*?)
        (?P<tail>\s+(?:WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b.*?|;?\s*)$
        """,
        flags=re.I | re.S | re.VERBOSE,
    )
    m = pat.match(s0)
    if not m:
        return sql

    prefix = m.group("prefix")
    t1, a1 = m.group("t1"), m.group("a1")
    t2, a2 = m.group("t2"), m.group("a2")
    on_clause = (m.group("on") or "").strip()
    tail = m.group("tail") or ""

    # RHS alias must not be used outside ON (mask ON on s0, not sql)
    start_on = m.start("on")
    end_on = m.end("on")
    masked = s0[:start_on] + (" " * (end_on - start_on)) + s0[end_on:]
    if re.search(rf"\b{re.escape(a2)}\s*\.", masked, flags=re.I):
        return sql

    exists_expr = f"EXISTS (SELECT 1 FROM {t2} {a2} WHERE {on_clause})"

    if re.search(r"\bWHERE\b", tail, flags=re.I):
        tail2 = re.sub(r"\bWHERE\b", f"WHERE {exists_expr} AND ", tail, count=1, flags=re.I)
        return f"{prefix}FROM {t1} {a1}{tail2}"
    else:
        return f"{prefix}FROM {t1} {a1} WHERE {exists_expr}{tail}"

def has_non_inner_join(sql: str) -> bool:
    if not sql:
        return False
    return re.search(r"\b(left|right|full)\s+join\b", sql, flags=re.I) is not None

def _strip_string_literals(s: str) -> str:
    s = re.sub(r"'(?:''|[^'])*'", "''", s)
    s = re.sub(r'"(?:""|[^"])*"', '""', s)
    return s


def _is_unique_join_key_for_table(table_name: str, column_name: str) -> bool:
    """
    Conservative uniqueness check for a table join key.
    Treat only the table identity column as unique to avoid unsafe row-count
    changes when pruning joins.
    """
    table_l = str(table_name or "").replace("`", "").split(".")[-1].strip().lower()
    col_l = str(column_name or "").replace("`", "").strip().lower()
    if not table_l or not col_l:
        return False
    try:
        id_col = get_id_column(table_l)
    except Exception:
        id_col = None
    if not id_col:
        return False
    return str(id_col).replace("`", "").strip().lower() == col_l


def _remove_redundant_and_ornamental_joins(sql: str) -> str:
    """
    Gabungan logic:
    - Hapus JOIN yang tidak dipakai di hasil query (ornamental)
    - Jika JOIN adalah equi-join dan referensi kolom RHS hanya join key, hapus JOIN dan rewrite referensi kolom ke LHS
    - Tetap konservatif untuk query agregasi/GROUP BY
    """
    if not sql:
        return sql
    # CROSS JOIN with an ON predicate is semantically an ordinary constrained
    # join in MySQL-like dialects. Canonicalize it before other join reasoning
    # so later FK/ornamental-join checks do not treat it as a Cartesian join.
    sql = re.sub(
        r"""(?is)\bCROSS\s+JOIN\b(?=\s+`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?(?:\s+(?:AS\s+)?[A-Za-z_][A-Za-z0-9_]*)?\s+\bON\b)""",
        "JOIN",
        sql,
    )
    parent_key_pruned = _prune_parent_key_only_joins(sql)
    if parent_key_pruned != sql:
        return _dedupe_join_on_conjuncts(parent_key_pruned)
    sql = _dedupe_join_on_conjuncts(sql)
    # Try the stricter single-join parent prune first. This helper can safely
    # collapse non-aggregate GROUP BY shapes that are otherwise skipped below.
    pre_pruned = _prune_redundant_from_parent_inner_join(sql)
    if pre_pruned != sql:
        return pre_pruned
    # Skip jika ada GROUP BY atau fungsi agregat
    if "GROUP BY" in sql.upper():
        return sql
    if re.search(r"\b(SUM|COUNT|AVG|MIN|MAX|GROUP_CONCAT)\s*\(", sql, flags=re.I):
        return sql
    # Skip derived-table joins to avoid accidental cross-subquery rewrites.
    if re.search(r"\b(?:from|join)\s*\(", sql, flags=re.I):
        return sql

    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, rels in (fk_raw or {}).items():
        src_l = str(src or "").replace("`", "").split(".")[-1].strip().lower()
        if not src_l:
            continue
        fk_map.setdefault(src_l, {})
        for fk_col, tgt in (rels or {}).items():
            fk_l = str(fk_col or "").replace("`", "").strip().lower()
            tgt_l = str(tgt or "").replace("`", "").split(".")[-1].strip().lower()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    def _rhs_equi_join_mapping(current_sql: str, rhs_alias: str, rhs_table: str, on_expr: str) -> Optional[Tuple[str, str, str, str]]:
        on_clean = _strip_string_literals(on_expr).replace("`", "").strip()
        on_eq = re.fullmatch(
            r"([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)",
            on_clean,
            flags=re.I,
        )
        if not on_eq:
            return None

        a1, c1, a2, c2 = on_eq.group(1), on_eq.group(2), on_eq.group(3), on_eq.group(4)
        rhs_alias_l = str(rhs_alias or "").strip().lower()
        lhs_alias = ""
        lhs_col = ""
        rhs_col = ""
        if a1.lower() == rhs_alias_l and a2.lower() != rhs_alias_l:
            lhs_alias, lhs_col, rhs_col = a2, c2, c1
        elif a2.lower() == rhs_alias_l and a1.lower() != rhs_alias_l:
            lhs_alias, lhs_col, rhs_col = a1, c1, c2
        else:
            return None

        alias_map = _parse_from_join_aliases(current_sql)
        lhs_table = (alias_map.get(lhs_alias) or alias_map.get(lhs_alias.lower()) or lhs_alias or "")
        lhs_table_l = str(lhs_table).replace("`", "").split(".")[-1].strip().lower()
        rhs_table_l = str(rhs_table or "").replace("`", "").split(".")[-1].strip().lower()
        lhs_col_l = str(lhs_col or "").replace("`", "").strip().lower()
        rhs_col_l = str(rhs_col or "").replace("`", "").strip().lower()
        if not lhs_table_l or not rhs_table_l or not lhs_col_l or not rhs_col_l:
            return None

        if fk_map.get(lhs_table_l, {}).get(lhs_col_l) != rhs_table_l:
            return None
        if not _is_unique_join_key_for_table(rhs_table_l, rhs_col_l):
            return None

        return (lhs_alias, lhs_col, rhs_alias, rhs_col)

    out = sql
    join_pat = re.compile(
        r"""
        (?P<full>
            \s*
            (?P<jtype>(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|FULL\s+JOIN|JOIN))
            \s+
            (?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?)
            (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
            \s+\bON\b\s+(?P<on>.*?)
        )
        (?=
            \b(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|FULL\s+JOIN|JOIN)\b
            |\bWHERE\b|\bGROUP\s+BY\b|\bORDER\s+BY\b|\bHAVING\b|\bLIMIT\b
            |;|$
        )
        """,
        flags=re.IGNORECASE | re.DOTALL | re.VERBOSE,
    )
    matches = list(join_pat.finditer(out))
    for m in reversed(matches):
        alias = m.group("alias") or (m.group("table") or "").strip("`")
        alias_l = str(alias).lower()
        jtype = (m.group("jtype") or "").upper()
        on_txt = m.group("on") or ""
        start_on = m.start("on")
        end_on = m.end("on")
        masked = out[:start_on] + (" " * (end_on - start_on)) + out[end_on:]
        outside_on = out[:m.start("full")] + out[m.end("full"):]
        outside_on_clean = _strip_string_literals(outside_on).replace("`", "")

        # Jika alias tidak dipakai di luar ON, drop hanya untuk redundant
        # parent-lookup INNER JOIN (schema-validated FK direction).
        if not re.search(rf"\b{re.escape(alias)}\s*\.", masked, flags=re.I):
            is_inner = ("LEFT" not in jtype and "RIGHT" not in jtype and "FULL" not in jtype)
            if is_inner:
                rhs_table = m.group("table") or ""
                mapped = _rhs_equi_join_mapping(out, alias, rhs_table, on_txt)
                if mapped is not None:
                    out = out[:m.start("full")] + " " + out[m.end("full"):]
                    continue
            continue

        # INNER JOIN only: if RHS is used only on join-key and key is unique,
        # rewrite RHS key references to LHS and drop redundant JOIN.
        is_inner = ("LEFT" not in jtype and "RIGHT" not in jtype and "FULL" not in jtype)
        if not is_inner:
            continue

        rhs_table = m.group("table") or ""
        mapped = _rhs_equi_join_mapping(out, alias, rhs_table, on_txt)
        if mapped is None:
            continue
        lhs_alias, lhs_col, _rhs_alias, rhs_col = mapped

        rhs_refs = re.findall(
            rf"\b{re.escape(alias)}\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\b",
            outside_on_clean,
            flags=re.I,
        )
        if not rhs_refs:
            out = out[:m.start("full")] + " " + out[m.end("full"):]
            continue
        if any(str(col).lower() != str(rhs_col).lower() for col in rhs_refs):
            continue

        def _rewrite_rhs_key_to_lhs(text: str) -> str:
            parts = re.split(r"('(?:''|[^'])*'|\"(?:\"\"|[^\"])*\"|`[^`]*`)", text)
            for i in range(0, len(parts), 2):
                parts[i] = re.sub(
                    rf"\b{re.escape(alias)}\s*\.\s*{re.escape(rhs_col)}\b",
                    f"{lhs_alias}.{lhs_col}",
                    parts[i],
                    flags=re.I,
                )
            return "".join(parts)

        prefix_raw = out[:m.start("full")]
        tail_raw = out[m.end("full"):]
        out = _rewrite_rhs_key_to_lhs(prefix_raw) + " " + _rewrite_rhs_key_to_lhs(tail_raw)
    out = _prune_redundant_from_parent_inner_join(out)
    return _dedupe_join_on_conjuncts(out)


def _dedupe_join_on_conjuncts(sql: str) -> str:
    """
    Remove duplicate top-level ON conjuncts within each JOIN.

    This is purely structural cleanup: it does not infer new predicates or drop
    non-duplicate conditions.
    """
    if not sql or not has_join(sql):
        return sql

    join_pat = re.compile(
        r"""
        (?P<full>
            \s*
            (?P<jtype>(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|FULL\s+JOIN|CROSS\s+JOIN|JOIN))
            \s+
            (?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
            (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
            \s+\bON\b\s+(?P<on>.*?)
        )
        (?=
            \b(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|FULL\s+JOIN|CROSS\s+JOIN|JOIN)\b
            |\bWHERE\b|\bGROUP\s+BY\b|\bORDER\s+BY\b|\bHAVING\b|\bLIMIT\b
            |;|$
        )
        """,
        flags=re.I | re.S | re.X,
    )

    out = sql
    changed = False
    for m_join in reversed(list(join_pat.finditer(out))):
        on_txt = m_join.group("on") or ""
        parts = _split_top_level_and(on_txt)
        if len(parts) <= 1:
            continue

        seen: Set[str] = set()
        kept: List[str] = []
        local_changed = False
        for part in parts:
            norm = re.sub(r"\s+", " ", part.replace("`", "").strip().lower())
            if norm in seen:
                local_changed = True
                continue
            seen.add(norm)
            kept.append(part.strip())

        if not local_changed or len(kept) == len(parts):
            continue
        changed = True
        replacement = out[m_join.start("full"):m_join.start("on")] + " AND ".join(kept)
        out = out[:m_join.start("full")] + replacement + out[m_join.end("full"):]

    return out if changed else sql


def _prune_parent_key_only_joins(sql: str) -> str:
    """
    Drop FK parent joins when the parent alias is used only for its identity key.

    This is safe for grouped/aggregate queries because the parent key is
    functionally equivalent to the child FK column confirmed by schema metadata.
    It avoids unnecessary dimension joins such as selecting parent.id when the
    child row already carries parent_id.
    """
    if not sql or not has_join(sql):
        return sql
    if re.search(r"\b(?:from|join)\s*\(", sql, flags=re.I):
        return sql

    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}
    if not fk_raw:
        return sql

    fk_map: Dict[str, Dict[str, str]] = {}
    for src, rels in (fk_raw or {}).items():
        src_l = str(src or "").replace("`", "").split(".")[-1].strip().lower()
        if not src_l:
            continue
        for fk_col, tgt in (rels or {}).items():
            fk_l = str(fk_col or "").replace("`", "").strip().lower()
            tgt_l = str(tgt or "").replace("`", "").split(".")[-1].strip().lower()
            if fk_l and tgt_l:
                fk_map.setdefault(src_l, {})[fk_l] = tgt_l

    alias_to_table = _parse_from_join_aliases(sql)
    if not alias_to_table:
        return sql

    def _table_for(alias: str) -> str:
        key = str(alias or "").strip()
        return str(alias_to_table.get(key) or alias_to_table.get(key.lower()) or "").strip().lower()

    def _replace_parent_key_refs(text: str, parent_alias: str, parent_key: str, child_alias: str, child_fk: str) -> str:
        parts = re.split(r"('(?:''|[^'])*'|\"(?:\"\"|[^\"])*\"|`[^`]*`)", text)
        pat = re.compile(
            rf"""(?is)\b`?{re.escape(parent_alias)}`?\s*\.\s*`?{re.escape(parent_key)}`?\b"""
        )
        for idx in range(0, len(parts), 2):
            parts[idx] = pat.sub(f"{child_alias}.{child_fk}", parts[idx])
        return "".join(parts)

    join_pat = re.compile(
        r"""
        (?P<full>
            \s*
            (?P<jtype>(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|FULL\s+JOIN|CROSS\s+JOIN|JOIN))
            \s+
            (?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
            (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
            \s+\bON\b\s+(?P<on>.*?)
        )
        (?=
            \b(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|FULL\s+JOIN|CROSS\s+JOIN|JOIN)\b
            |\bWHERE\b|\bGROUP\s+BY\b|\bORDER\s+BY\b|\bHAVING\b|\bLIMIT\b
            |;|$
        )
        """,
        flags=re.I | re.S | re.X,
    )
    eq_pat = re.compile(
        r"""(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$"""
    )

    out = sql
    changed = False
    for m_join in reversed(list(join_pat.finditer(out))):
        join_type = (m_join.group("jtype") or "").upper()
        if "LEFT" in join_type or "RIGHT" in join_type or "FULL" in join_type:
            continue
        table_raw = (m_join.group("table") or "").replace("`", "")
        parent_table = table_raw.split(".")[-1].strip().lower()
        parent_alias = (m_join.group("alias") or parent_table).strip()
        if not parent_table or not parent_alias:
            continue

        on_parts = _split_top_level_and(m_join.group("on") or "")
        if len(on_parts) != 1:
            continue
        m_eq = eq_pat.match(on_parts[0])
        if not m_eq:
            continue

        a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
        parent_key = str(get_id_column(parent_table) or "").strip("`")
        if not parent_key:
            continue

        child_alias = ""
        child_fk = ""
        if a1.lower() == parent_alias.lower() and c1.lower() == parent_key.lower():
            child_alias, child_fk = a2, c2
        elif a2.lower() == parent_alias.lower() and c2.lower() == parent_key.lower():
            child_alias, child_fk = a1, c1
        else:
            continue

        child_table = _table_for(child_alias)
        if not child_table:
            continue
        if fk_map.get(child_table, {}).get(child_fk.lower()) != parent_table:
            continue

        outside = out[:m_join.start("full")] + out[m_join.end("full"):]
        outside_clean = _strip_string_literals(outside).replace("`", "")
        parent_refs = re.findall(
            rf"\b{re.escape(parent_alias)}\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\b",
            outside_clean,
            flags=re.I,
        )
        if not parent_refs:
            out = out[:m_join.start("full")] + " " + out[m_join.end("full"):]
            changed = True
            continue
        if any(ref.lower() != parent_key.lower() for ref in parent_refs):
            continue

        prefix = _replace_parent_key_refs(out[:m_join.start("full")], parent_alias, parent_key, child_alias, child_fk)
        tail = _replace_parent_key_refs(out[m_join.end("full"):], parent_alias, parent_key, child_alias, child_fk)
        out = prefix + " " + tail
        changed = True

    return re.sub(r"\s{2,}", " ", out).strip() if changed else sql


def _prune_redundant_from_parent_inner_join(sql: str) -> str:
    """
    Remove a redundant parent table in a single INNER/JOIN shape when:
    - query has exactly one join and no aggregation/grouping/subquery
    - ON is a simple equi-key predicate
    - schema FK confirms joined table references the FROM table
    - FROM-side references outside ON use only the join key

    Example (schema-agnostic):
      SELECT p.id, c.x FROM parent p
      JOIN child c ON p.id = c.parent_id
      WHERE c.x > 0
    ->
      SELECT c.parent_id, c.x FROM child c WHERE c.x > 0
    """
    if not sql:
        return sql
    if join_count(sql) != 1:
        return sql
    if re.search(r"\b(left|right|full)\s+join\b", sql, flags=re.I):
        return sql
    if re.search(r"\b(?:from|join)\s*\(", sql, flags=re.I):
        return sql
    has_group_by = bool(re.search(r"\bGROUP\s+BY\b", sql, flags=re.I))
    if re.search(r"\b(SUM|COUNT|AVG|MIN|MAX|GROUP_CONCAT)\s*\(", sql, flags=re.I):
        return sql
    if has_group_by:
        # Keep grouped aggregate/window queries out of this rewrite.
        if re.search(r"\bHAVING\b", sql, flags=re.I):
            return sql
        if re.search(r"\bOVER\s*\(", sql, flags=re.I):
            return sql

    s = sql.strip()
    pat = re.compile(
        r"""
        ^(?P<head>.*?\bFROM\s+)
        (?P<l_table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
        (?P<l_alias_clause>\s+(?:AS\s+)?(?P<l_alias>[A-Za-z_][A-Za-z0-9_]*))?
        \s+(?P<jtype>(?:INNER\s+JOIN|JOIN))\s+
        (?P<r_table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
        (?P<r_alias_clause>\s+(?:AS\s+)?(?P<r_alias>[A-Za-z_][A-Za-z0-9_]*))?
        \s+\bON\b\s+(?P<on>.*?)
        (?P<tail>\s+(?:WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b.*?|;?\s*)$
        """,
        flags=re.I | re.S | re.X,
    )
    m = pat.match(s)
    if not m:
        return sql

    on_txt = (m.group("on") or "").strip()
    if not on_txt:
        return sql
    if re.search(r"\b(?:AND|OR)\b", on_txt, flags=re.I):
        return sql

    eq_m = re.match(
        r"""
        ^\s*`?(?P<a1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<c1>[A-Za-z_][A-Za-z0-9_]*)`?
        \s*=\s*
        `?(?P<a2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<c2>[A-Za-z_][A-Za-z0-9_]*)`?\s*$
        """,
        on_txt,
        flags=re.I | re.X,
    )
    if not eq_m:
        return sql

    l_table_raw = m.group("l_table") or ""
    r_table_raw = m.group("r_table") or ""
    l_table = l_table_raw.replace("`", "").split(".")[-1].strip().lower()
    r_table = r_table_raw.replace("`", "").split(".")[-1].strip().lower()
    if not l_table or not r_table:
        return sql

    l_alias = (m.group("l_alias") or "").strip()
    r_alias = (m.group("r_alias") or "").strip()
    l_ref = (l_alias or l_table_raw.replace("`", "").split(".")[-1]).strip()
    r_ref = (r_alias or r_table_raw.replace("`", "").split(".")[-1]).strip()
    if not l_ref or not r_ref:
        return sql

    a1 = (eq_m.group("a1") or "").strip().lower()
    c1 = (eq_m.group("c1") or "").strip()
    a2 = (eq_m.group("a2") or "").strip().lower()
    c2 = (eq_m.group("c2") or "").strip()
    if not a1 or not a2 or not c1 or not c2:
        return sql

    l_ref_l = l_ref.lower()
    r_ref_l = r_ref.lower()
    if a1 == l_ref_l and a2 == r_ref_l:
        l_col, r_col = c1, c2
    elif a1 == r_ref_l and a2 == l_ref_l:
        l_col, r_col = c2, c1
    else:
        return sql

    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}
    child_fks = {
        str(k or "").strip().lower(): str(v or "").strip().lower()
        for k, v in (fk_raw.get(r_table, {}) or {}).items()
        if str(k or "").strip() and str(v or "").strip()
    }
    if child_fks.get(str(r_col).strip().lower()) != l_table:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    if analyzer is not None:
        try:
            l_cols = {str(c).strip().lower() for c in analyzer.get_table_columns(l_table) or []}
            r_cols = {str(c).strip().lower() for c in analyzer.get_table_columns(r_table) or []}
            if str(l_col).strip().lower() not in l_cols:
                return sql
            if str(r_col).strip().lower() not in r_cols:
                return sql
        except Exception:
            pass

    start_on = m.start("on")
    end_on = m.end("on")
    masked = s[:start_on] + (" " * (end_on - start_on)) + s[end_on:]
    masked = _strip_string_literals(masked).replace("`", "")
    lhs_refs = re.findall(
        rf"\b{re.escape(l_ref)}\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\b",
        masked,
        flags=re.I,
    )
    if any(str(col).strip().lower() != str(l_col).strip().lower() for col in lhs_refs):
        return sql

    lhs_key_pat = re.compile(
        rf"\b`?{re.escape(l_ref)}`?\s*\.\s*`?{re.escape(str(l_col).strip())}`?\b",
        flags=re.I,
    )
    rhs_key_ref = f"{r_ref}.{str(r_col).strip()}"

    def _rewrite_non_literal(text: str) -> str:
        parts = re.split(r"('(?:''|[^'])*'|\"(?:\"\"|[^\"])*\")", text)
        for i in range(0, len(parts), 2):
            parts[i] = lhs_key_pat.sub(rhs_key_ref, parts[i])
        return "".join(parts)

    new_head = _rewrite_non_literal(m.group("head") or "")
    new_tail = _rewrite_non_literal(m.group("tail") or "")
    right_from = (m.group("r_table") or "") + (m.group("r_alias_clause") or "")
    if not right_from.strip():
        return sql

    return f"{new_head}{right_from}{new_tail}"


def _rewrite_invalid_fk_join_conditions(sql: str, ctx: str = "") -> str:
    """
    Repair invalid ON-equijoin predicates using schema FK metadata.

    Conservative behavior:
    - only considers direct table-to-table joins (skips JOIN (...subquery...))
    - only rewrites simple qualified equi-predicates (a.col = b.col)
    - rewrites only when there is exactly one FK relationship between the two
      joined tables and the current predicate is a near-miss (shares at least
      one expected FK/id column).
    """
    if not sql or not has_join(sql):
        return sql

    # If query contains derived-table joins/subqueries, do a recursive pass on
    # inner SELECT blocks first, then return (outer scope is too ambiguous for
    # direct regex surgery).
    if re.search(r"\b(?:from|join)\s*\(", sql, flags=re.I):
        def _rewrite_inner_select_blocks(text: str) -> str:
            if not text or "(" not in text:
                return text

            out_parts: List[str] = []
            i = 0
            n = len(text)
            while i < n:
                ch = text[i]
                if ch != "(":
                    out_parts.append(ch)
                    i += 1
                    continue

                # Find matching ')' with quote/backtick awareness.
                depth = 0
                in_sq = False
                in_dq = False
                in_bt = False
                j = i
                while j < n:
                    cj = text[j]
                    if cj == "'" and not in_dq and not in_bt:
                        if in_sq and j + 1 < n and text[j + 1] == "'":
                            j += 2
                            continue
                        in_sq = not in_sq
                        j += 1
                        continue
                    if cj == '"' and not in_sq and not in_bt:
                        if in_dq and j + 1 < n and text[j + 1] == '"':
                            j += 2
                            continue
                        in_dq = not in_dq
                        j += 1
                        continue
                    if cj == "`" and not in_sq and not in_dq:
                        in_bt = not in_bt
                        j += 1
                        continue
                    if in_sq or in_dq or in_bt:
                        j += 1
                        continue
                    if cj == "(":
                        depth += 1
                    elif cj == ")":
                        depth -= 1
                        if depth == 0:
                            break
                    j += 1

                if j >= n or text[j] != ")":
                    # Unbalanced fallback: keep remaining text untouched.
                    out_parts.append(text[i:])
                    return "".join(out_parts)

                inner = text[i + 1:j]
                inner_stripped = inner.lstrip()
                if re.match(r"(?is)^select\b", inner_stripped):
                    fixed_inner = _rewrite_invalid_fk_join_conditions(inner, ctx)
                    out_parts.append("(" + fixed_inner + ")")
                else:
                    out_parts.append("(" + inner + ")")
                i = j + 1

            return "".join(out_parts)

        fixed_with_inner = _rewrite_inner_select_blocks(sql)
        return fixed_with_inner

    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    if not fk_map_raw:
        return sql

    fk_map: Dict[str, Dict[str, str]] = {}
    for src, mapping in fk_map_raw.items():
        src_l = str(src or "").lower()
        if not src_l:
            continue
        fk_map[src_l] = {}
        for fk_col, tgt in (mapping or {}).items():
            fk_col_l = str(fk_col or "").lower()
            tgt_l = str(tgt or "").lower()
            if fk_col_l and tgt_l:
                fk_map[src_l][fk_col_l] = tgt_l

    alias_to_table = _parse_from_join_aliases(sql)
    table_token_pat = re.compile(
        r"\b(?:from|join)\s+"
        r"(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)"
        r"(?:\s+(?:as\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?",
        flags=re.I,
    )
    for m_tbl in table_token_pat.finditer(sql):
        raw = (m_tbl.group("table") or "").replace("`", "")
        tbl = raw.split(".")[-1].lower()
        if not tbl:
            continue
        alias = m_tbl.group("alias")
        alias_to_table.setdefault(tbl, tbl)
        if alias:
            alias_to_table.setdefault(alias, tbl)
            alias_to_table.setdefault(alias.lower(), tbl)

    if not alias_to_table:
        return sql

    def _get_table(alias_or_table: str) -> str:
        key = (alias_or_table or "").strip()
        return (alias_to_table.get(key) or alias_to_table.get(key.lower()) or key).lower()

    def _target_join_col(target_table: str, fk_col: str) -> str:
        id_col = get_id_column(target_table)
        if id_col:
            return str(id_col)
        return fk_col

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    table_cols_cache: Dict[str, Set[str]] = {}

    def _table_cols(table_name: str) -> Set[str]:
        t = (table_name or "").lower().strip()
        if not t:
            return set()
        if t in table_cols_cache:
            return table_cols_cache[t]
        cols: Set[str] = set()
        if analyzer is not None:
            try:
                cols.update(c.lower() for c in analyzer.get_table_columns(t))
            except Exception:
                pass
        table_cols_cache[t] = cols
        return cols

    def _fk_pairs_between(left_table: str, right_table: str) -> List[Tuple[str, str, str, str]]:
        pairs: List[Tuple[str, str, str, str]] = []
        lt = (left_table or "").lower()
        rt = (right_table or "").lower()
        if not lt or not rt or lt == rt:
            return pairs

        for fk_col, tgt in fk_map.get(lt, {}).items():
            if tgt == rt:
                pairs.append((lt, fk_col, rt, _target_join_col(rt, fk_col)))
        for fk_col, tgt in fk_map.get(rt, {}).items():
            if tgt == lt:
                pairs.append((rt, fk_col, lt, _target_join_col(lt, fk_col)))
        return pairs

    def _pick_bridge_rewrite(
        valid_table: str,
        invalid_table: str,
        missing_fk_col: str,
    ) -> Optional[Tuple[str, str, str, str]]:
        """
        Find bridge table C such that:
          - C.<missing_fk_col> references valid_table
          - invalid_table has FK to C via some column
        Returns (bridge_table, bridge_fk_to_valid, invalid_fk_to_bridge, bridge_target_col).
        """
        vt = (valid_table or "").lower().strip()
        it = (invalid_table or "").lower().strip()
        miss = (missing_fk_col or "").lower().strip()
        if not vt or not it or not miss or vt == it:
            return None

        candidates: List[Tuple[str, str, str, str]] = []
        for bridge_table, bridge_fk_map in fk_map.items():
            bt = (bridge_table or "").lower().strip()
            if not bt:
                continue

            # Bridge must reference valid table using the missing FK name.
            if (bridge_fk_map or {}).get(miss) != vt:
                continue

            # Invalid table must reference bridge table.
            inv_fk_candidates = [
                fk_col
                for fk_col, tgt in (fk_map.get(it, {}) or {}).items()
                if (tgt or "").lower() == bt
            ]
            if not inv_fk_candidates:
                continue

            def _fk_score(fk_col: str) -> int:
                f = (fk_col or "").lower()
                s = 0
                if f.endswith("id") or f.endswith("number") or f.endswith("code"):
                    s += 4
                if bt.rstrip("s") in f:
                    s += 2
                return s

            invalid_fk_to_bridge = sorted(inv_fk_candidates, key=_fk_score, reverse=True)[0]
            bridge_target_col = str(get_id_column(bt) or invalid_fk_to_bridge)

            bt_cols = _table_cols(bt)
            it_cols = _table_cols(it)
            if bt_cols and miss not in bt_cols:
                continue
            if it_cols and invalid_fk_to_bridge not in it_cols:
                continue
            if bt_cols and bridge_target_col.lower() not in bt_cols:
                if invalid_fk_to_bridge in bt_cols:
                    bridge_target_col = invalid_fk_to_bridge
                else:
                    continue

            candidates.append((bt, miss, invalid_fk_to_bridge, bridge_target_col))

        if not candidates:
            return None
        return candidates[0]

    def _pick_unique_alias(base_table: str) -> str:
        used_aliases = {k.lower() for k in alias_to_table.keys() if k}
        base = (get_singular_form(base_table) or base_table or "b").strip().lower()
        base = re.sub(r"[^a-z0-9_]", "", base) or "b"
        if not re.match(r"[a-z_]", base[0]):
            base = f"b_{base}"
        cand = base
        idx = 2
        while cand.lower() in used_aliases:
            cand = f"{base}_{idx}"
            idx += 1
        return cand

    join_pat = re.compile(
        r"""
        (?P<full>
            \s+
            (?P<jtype>(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|FULL\s+JOIN|JOIN))
            \s+
            (?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
            (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
            \s+\bON\b\s+(?P<on>.*?)
        )
        (?=
            \b(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|FULL\s+JOIN|JOIN)\b
            |\bWHERE\b|\bGROUP\s+BY\b|\bORDER\s+BY\b|\bHAVING\b|\bLIMIT\b
            |;|$
        )
        """,
        flags=re.IGNORECASE | re.DOTALL | re.VERBOSE,
    )
    eq_pat = re.compile(
        r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*([A-Za-z_][A-Za-z0-9_]*)\b",
        flags=re.I,
    )

    out = sql
    matches = list(join_pat.finditer(out))
    for m_join in reversed(matches):
        on_txt = m_join.group("on") or ""
        eq_matches = list(eq_pat.finditer(on_txt))
        if not eq_matches:
            continue

        # Bridge-table repair for invalid direct joins (single simple equijoin).
        # Example:
        #   employees e LEFT JOIN payments p ON e.employeeNumber = p.salesRepEmployeeNumber
        # ->
        #   employees e LEFT JOIN customers c ON c.salesRepEmployeeNumber = e.employeeNumber
        #               LEFT JOIN payments p ON p.customerNumber = c.customerNumber
        if len(eq_matches) == 1:
            m_eq_only = eq_matches[0]
            on_residual = (on_txt[:m_eq_only.start()] + on_txt[m_eq_only.end():]).strip()
            on_residual = re.sub(r"[()\s]+", "", on_residual)
            if not on_residual:
                lhs_alias, lhs_col = m_eq_only.group(1), m_eq_only.group(2)
                rhs_alias, rhs_col = m_eq_only.group(3), m_eq_only.group(4)
                lt = _get_table(lhs_alias)
                rt = _get_table(rhs_alias)

                left_cols = _table_cols(lt)
                right_cols = _table_cols(rt)
                lhs_missing = bool(left_cols) and (lhs_col.lower() not in left_cols)
                rhs_missing = bool(right_cols) and (rhs_col.lower() not in right_cols)

                if lhs_missing ^ rhs_missing:
                    # Only rewrite when the invalid side belongs to the joined table alias.
                    joined_table_raw = (m_join.group("table") or "").replace("`", "")
                    joined_table_name = joined_table_raw.split(".")[-1].lower()
                    joined_alias = (m_join.group("alias") or "").strip()
                    joined_symbol = (joined_alias or joined_table_name).lower()

                    if lhs_missing:
                        invalid_alias, invalid_col, invalid_table = lhs_alias, lhs_col, lt
                        valid_alias, valid_col, valid_table = rhs_alias, rhs_col, rt
                    else:
                        invalid_alias, invalid_col, invalid_table = rhs_alias, rhs_col, rt
                        valid_alias, valid_col, valid_table = lhs_alias, lhs_col, lt

                    if invalid_alias.lower() == joined_symbol:
                        bridge = _pick_bridge_rewrite(valid_table, invalid_table, invalid_col)
                        if bridge:
                            bridge_table, bridge_fk_to_valid, invalid_fk_to_bridge, bridge_target_col = bridge
                            bridge_alias = _pick_unique_alias(bridge_table)
                            jtype = (m_join.group("jtype") or "JOIN").strip()
                            join_table_token = (m_join.group("table") or "").strip()
                            join_alias_token = f" {joined_alias}" if joined_alias else ""

                            # Preserve original missing-FK column casing when possible.
                            bridge_fk_out = invalid_col if invalid_col.lower() == bridge_fk_to_valid.lower() else bridge_fk_to_valid

                            replacement = (
                                f" {jtype} {bridge_table} {bridge_alias}"
                                f" ON {bridge_alias}.{bridge_fk_out} = {valid_alias}.{valid_col}"
                                f" {jtype} {join_table_token}{join_alias_token}"
                                f" ON {invalid_alias}.{invalid_fk_to_bridge} = {bridge_alias}.{bridge_target_col}"
                            )
                            out = out[:m_join.start("full")] + replacement + out[m_join.end("full"):]
                            alias_to_table[bridge_alias] = bridge_table
                            alias_to_table[bridge_alias.lower()] = bridge_table
                            alias_to_table.setdefault(bridge_table, bridge_table)
                            continue

        rebuilt = []
        last = 0
        changed = False

        for m_eq in eq_matches:
            rebuilt.append(on_txt[last:m_eq.start()])
            lhs_alias, lhs_col = m_eq.group(1), m_eq.group(2)
            rhs_alias, rhs_col = m_eq.group(3), m_eq.group(4)

            lt = _get_table(lhs_alias)
            rt = _get_table(rhs_alias)
            pairs = _fk_pairs_between(lt, rt)
            new_eq = m_eq.group(0)

            if len(pairs) == 1:
                fk_tbl, fk_col, tgt_tbl, tgt_col = pairs[0]
                lhs_col_l = lhs_col.lower()
                rhs_col_l = rhs_col.lower()
                fk_col_l = fk_col.lower()
                tgt_col_l = str(tgt_col).lower()

                valid = (
                    (lt == fk_tbl and rt == tgt_tbl and lhs_col_l == fk_col_l and rhs_col_l == tgt_col_l)
                    or (rt == fk_tbl and lt == tgt_tbl and rhs_col_l == fk_col_l and lhs_col_l == tgt_col_l)
                )

                if not valid:
                    near_miss = ({lhs_col_l, rhs_col_l} & {fk_col_l, tgt_col_l})
                    left_cols = _table_cols(lt)
                    right_cols = _table_cols(rt)
                    lhs_missing = bool(left_cols) and (lhs_col_l not in left_cols)
                    rhs_missing = bool(right_cols) and (rhs_col_l not in right_cols)
                    invalid_column_side = lhs_missing or rhs_missing

                    if near_miss or invalid_column_side:
                        # Preserve original column casing when one side already
                        # uses the intended FK or target key.
                        fk_col_out = fk_col
                        tgt_col_out = str(tgt_col)
                        if lhs_col_l == fk_col_l:
                            fk_col_out = lhs_col
                        elif rhs_col_l == fk_col_l:
                            fk_col_out = rhs_col
                        if lhs_col_l == tgt_col_l:
                            tgt_col_out = lhs_col
                        elif rhs_col_l == tgt_col_l:
                            tgt_col_out = rhs_col

                        if lt == fk_tbl and rt == tgt_tbl:
                            new_eq = f"{lhs_alias}.{fk_col_out} = {rhs_alias}.{tgt_col_out}"
                            changed = True
                        elif lt == tgt_tbl and rt == fk_tbl:
                            new_eq = f"{lhs_alias}.{tgt_col_out} = {rhs_alias}.{fk_col_out}"
                            changed = True

            rebuilt.append(new_eq)
            last = m_eq.end()

        if not changed:
            continue

        rebuilt.append(on_txt[last:])
        new_on = "".join(rebuilt)
        out = out[:m_join.start("on")] + new_on + out[m_join.end("on"):]

    return out
# =======================================================================
# ================= Phase 2 — Syntax & Canonicalization =================
# =============== Normalize tokens and table naming early ===============
# =======================================================================
# - is_simple_column_expr
# - drop_redundant_column_aliases
# - drop_unused_from_table_aliases
# - strip_alias_if_single_table
# - repair_invalid_qualified_columns
# - repair_simple_single_table_column_names

def _repair_invalid_qualified_columns(sql: str, ctx: str = "") -> str:
    """
    Schema-aware repair for malformed qualified references (alias.column).

    Example fixed:
      MAX(od.orderDate)  -> MAX(o.orderDate)
    when `od` maps to a table that has no `orderDate`, and exactly one
    other visible alias maps to a table that has `orderDate`.

    Safety constraints:
    - No hardcoded table/column names.
    - Only rewrite when target alias is unique.
    - Skip ambiguous alias scopes (same alias used for different tables).
    - Ignore quoted string/backtick literal segments.
    """
    if not sql:
        return sql
    # Derived-table aliases can shadow base-table aliases across scopes.
    # Keep this repair conservative by skipping shapes with FROM (SELECT ...).
    if re.search(r"\b(?:FROM|JOIN)\s*\(", sql, flags=re.I):
        return sql

    analyzer = None
    allowed_cols: Dict[str, Set[str]] = {}
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    # Fallback source for columns if global analyzer is unavailable.
    if not analyzer and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                t.lower(): {c.lower() for c in cols}
                for t, cols in allowed.items()
            }
        except Exception:
            allowed_cols = {}

    # Build symbol -> table map from FROM/JOIN (alias optional).
    # Keep alias and bare table symbol, but drop ambiguous symbols.
    # Derived-table aliases are intentionally excluded (unknown columns).
    tbl_pat = re.compile(
        r"""
        \b(?:from|join)\s+
        (?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
        (?:\s+(?:as\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
        """,
        flags=re.I | re.X,
    )

    symbol_map: Dict[str, tuple] = {}  # symbol(lower) -> (table_lower, is_alias_symbol)
    ambiguous: Set[str] = set()

    def _add_symbol(sym: str, table_l: str, is_alias_symbol: bool) -> None:
        if not sym:
            return
        k = sym.lower()
        if k in ambiguous:
            return
        prev = symbol_map.get(k)
        if prev is None:
            symbol_map[k] = (table_l, is_alias_symbol)
            return
        if prev[0] != table_l:
            ambiguous.add(k)
            symbol_map.pop(k, None)

    for m in tbl_pat.finditer(sql):
        table_raw = (m.group("table") or "").replace("`", "")
        table_l = table_raw.split(".")[-1].strip().lower()
        if not table_l:
            continue
        alias = (m.group("alias") or "").strip()
        if alias and alias.lower() in _RESERVED_ALIASES:
            alias = ""
        _add_symbol(table_l, table_l, False)
        if alias:
            _add_symbol(alias, table_l, True)

    if not symbol_map:
        return sql

    def _norm_ident(text: str) -> str:
        return re.sub(r"[^a-z0-9]+", "", (text or "").strip().lower())

    # Cache table columns once.
    table_cols: Dict[str, Set[str]] = {}
    for _sym, (tbl_l, _is_alias) in symbol_map.items():
        if tbl_l in table_cols:
            continue
        cols: Set[str] = set()
        if analyzer:
            try:
                cols = {c.lower() for c in analyzer.get_table_columns(tbl_l)}
            except Exception:
                cols = set()
        if not cols and allowed_cols:
            cols = set(allowed_cols.get(tbl_l, set()))
        table_cols[tbl_l] = cols

    if not table_cols:
        return sql

    projection_alias_cols_by_symbol: Dict[str, Dict[str, str]] = {}

    m_select = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+\bFROM\b\s+", sql)
    if m_select:
        for item in _split_top_level_commas(m_select.group("select") or ""):
            expr, out_alias = _split_select_expr_alias(item)
            if not expr or not out_alias:
                continue
            m_simple = re.match(
                r"""(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
                expr.strip(),
            )
            if not m_simple:
                continue
            expr_symbol = str(m_simple.group(1) or "").strip().lower()
            expr_col = str(m_simple.group(2) or "").strip().lower()
            symbol_entry = symbol_map.get(expr_symbol)
            if not symbol_entry:
                continue
            src_tbl = symbol_entry[0]
            if expr_col not in table_cols.get(src_tbl, set()):
                continue
            out_alias_norm = _norm_ident(str(out_alias or "").strip().strip("`'\""))
            if not out_alias_norm:
                continue
            projection_alias_cols_by_symbol.setdefault(expr_symbol, {})
            projection_alias_cols_by_symbol[expr_symbol].setdefault(out_alias_norm, expr_col)

    def _original_case_col(tbl_l: str, col_l: str) -> str:
        if analyzer is not None:
            try:
                return str(analyzer._column_original_case.get(f"{tbl_l}.{col_l}", col_l))
            except Exception:
                pass
        return str(col_l)

    name_component_token_hints = set(name_component_lexical_tokens())
    name_priority_groups = name_component_priority_groups()
    first_name_hints = set(name_priority_groups.get("first", set()))
    middle_name_hints = set(name_priority_groups.get("middle", set()))
    last_name_hints = set(name_priority_groups.get("last", set()))
    generic_name_hints = set(name_priority_groups.get("generic", set()))

    def _name_component_cols_for_table(tbl_l: str) -> List[str]:
        src_cols = table_cols.get(tbl_l, set())
        if not src_cols:
            return []

        ordered_cols: List[str] = []
        if analyzer is not None:
            try:
                ordered_cols = [
                    str(c).strip("`").lower()
                    for c in analyzer.get_table_columns(tbl_l)
                    if str(c).strip()
                ]
            except Exception:
                ordered_cols = []

        if not ordered_cols:
            ordered_cols = sorted(src_cols)

        candidates: List[str] = []
        for col_l in ordered_cols:
            if col_l not in src_cols:
                continue
            col_case = _original_case_col(tbl_l, col_l)
            split_camel = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_case or col_l or ""))
            col_tokens = {
                tok
                for tok in re.findall(r"[a-z0-9]+", split_camel.replace("_", " ").lower())
                if tok
            }
            if col_tokens.intersection(name_component_token_hints):
                candidates.append(col_l)
                continue
            try:
                role_l = str(get_column_role(tbl_l, col_l) or "").strip().lower()
            except Exception:
                role_l = ""
            if role_l == "name":
                candidates.append(col_l)

        if len(candidates) >= 2:
            col_pos = {c: idx for idx, c in enumerate(ordered_cols)}

            def _name_priority(col_l: str) -> int:
                col_case = _original_case_col(tbl_l, col_l)
                split_camel = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_case or col_l or ""))
                tokens = {
                    tok
                    for tok in re.findall(r"[a-z0-9]+", split_camel.replace("_", " ").lower())
                    if tok
                }
                if tokens.intersection(first_name_hints):
                    return 0
                if tokens.intersection(middle_name_hints):
                    return 1
                if tokens.intersection(last_name_hints):
                    return 2
                if tokens.intersection(generic_name_hints):
                    return 3
                return 4

            return sorted(candidates, key=lambda c: (_name_priority(c), col_pos.get(c, 10_000), c))

        name_col = str(get_name_column(tbl_l) or "").strip("`").lower()
        if name_col and name_col in src_cols:
            return [name_col]
        return candidates

    # Qualified ref pattern that also supports optional backticks.
    qcol_pat = re.compile(
        r"""
        (?P<aq>`?)
        (?P<alias>[A-Za-z_][A-Za-z0-9_]*)
        (?P=aq)\s*\.\s*
        (?P<cq>`?)
        (?P<col>[A-Za-z_][A-Za-z0-9_]*)
        (?P=cq)
        """,
        flags=re.X,
    )

    # Alias symbols grouped by table, for unique-candidate resolution.
    alias_syms_by_table: Dict[str, List[str]] = {}
    table_syms_by_table: Dict[str, List[str]] = {}
    for sym, (tbl_l, is_alias_symbol) in symbol_map.items():
        if is_alias_symbol:
            alias_syms_by_table.setdefault(tbl_l, []).append(sym)
        else:
            table_syms_by_table.setdefault(tbl_l, []).append(sym)

    def _pick_replacement_symbol(src_alias_l: str, col_l: str) -> Optional[str]:
        # 1) Prefer real aliases.
        alias_candidates: List[str] = []
        seen_tbl = set()
        for tbl_l, syms in alias_syms_by_table.items():
            if col_l not in table_cols.get(tbl_l, set()):
                continue
            if tbl_l in seen_tbl:
                continue
            seen_tbl.add(tbl_l)
            alias_candidates.append(sorted(syms, key=len)[0])

        alias_candidates = [a for a in alias_candidates if a.lower() != src_alias_l]
        if len(alias_candidates) == 1:
            return alias_candidates[0]
        if len(alias_candidates) > 1:
            return None

        # 2) Fallback to bare table symbols if no alias candidate exists.
        table_candidates: List[str] = []
        seen_tbl = set()
        for tbl_l, syms in table_syms_by_table.items():
            if col_l not in table_cols.get(tbl_l, set()):
                continue
            if tbl_l in seen_tbl:
                continue
            seen_tbl.add(tbl_l)
            table_candidates.append(sorted(syms, key=len)[0])

        table_candidates = [t for t in table_candidates if t.lower() != src_alias_l]
        if len(table_candidates) == 1:
            return table_candidates[0]
        return None

    def _resolve_same_table_column(src_tbl: str, raw_col: str, symbol_l: str = "") -> Optional[str]:
        src_cols = table_cols.get(src_tbl, set())
        if not src_cols:
            return None
        target_norm = _norm_ident(raw_col)
        if not target_norm:
            return None

        if symbol_l:
            alias_projection_map = projection_alias_cols_by_symbol.get(symbol_l, {})
            mapped_projection_col = alias_projection_map.get(target_norm)
            if mapped_projection_col and mapped_projection_col in src_cols:
                return mapped_projection_col

        normalized_candidates: List[str] = [target_norm]
        raw_col_txt = str(raw_col or "").strip().strip("`")

        # Recover common role-prefixed projections (e.g. subordinate_employeeNumber)
        # to their base schema columns (employeeNumber) without table hardcoding.
        if raw_col_txt:
            parts = [p for p in re.split(r"[_\s]+", raw_col_txt) if p]
            if len(parts) >= 2:
                for idx in range(1, len(parts)):
                    suffix_norm = _norm_ident("".join(parts[idx:]))
                    if suffix_norm and suffix_norm not in normalized_candidates:
                        normalized_candidates.append(suffix_norm)

        role_prefixes = (
            "subordinate", "manager", "supervisor", "parent",
            "child", "owner", "member", "employee", "staff",
        )
        for pref in role_prefixes:
            if target_norm.startswith(pref) and len(target_norm) > len(pref) + 2:
                stripped = target_norm[len(pref):]
                if stripped and stripped not in normalized_candidates:
                    normalized_candidates.append(stripped)

        for cand_norm in normalized_candidates:
            matches = [c for c in src_cols if _norm_ident(c) == cand_norm]
            if len(matches) == 1:
                return matches[0]
            if len(matches) > 1:
                return None

        def _ident_tokens(text: str) -> List[str]:
            split_camel = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or ""))
            return re.findall(r"[a-z0-9]+", split_camel.lower())

        def _tokens_semantically_close(raw_tokens: List[str], cand_tokens: List[str]) -> bool:
            if not raw_tokens or not cand_tokens:
                return False
            if len(raw_tokens) != len(cand_tokens):
                return False
            saw_non_exact = False
            for raw_tok, cand_tok in zip(raw_tokens, cand_tokens):
                if raw_tok == cand_tok:
                    continue
                if len(raw_tok) < 3 and len(cand_tok) < 3:
                    return False
                if cand_tok.startswith(raw_tok) or raw_tok.startswith(cand_tok):
                    saw_non_exact = True
                    continue
                return False
            return saw_non_exact

        raw_tokens = _ident_tokens(raw_col)
        close_matches = [
            c for c in src_cols
            if _tokens_semantically_close(raw_tokens, _ident_tokens(_original_case_col(src_tbl, c)))
        ]
        if len(close_matches) == 1:
            return close_matches[0]
        return None

    def _resolve_same_table_full_name_expr(src_tbl: str, qualifier: str, raw_col: str) -> Optional[str]:
        raw_norm = _norm_ident(raw_col)
        if "fullname" not in raw_norm:
            return None
        name_cols = _name_component_cols_for_table(src_tbl)
        if not name_cols:
            return None
        qualifier_expr = str(qualifier or "").strip()
        if not qualifier_expr:
            return None

        if len(name_cols) >= 2:
            first_col = _original_case_col(src_tbl, name_cols[0])
            second_col = _original_case_col(src_tbl, name_cols[1])
            return f"CONCAT({qualifier_expr}.{first_col}, ' ', {qualifier_expr}.{second_col})"

        single_col = _original_case_col(src_tbl, name_cols[0])
        return f"{qualifier_expr}.{single_col}"

    on_clause_pat = re.compile(
        r"""
        \bON\b\s+.*?
        (?=
            \b(?:INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN|FULL\s+JOIN|JOIN)\b
            |\bWHERE\b|\bGROUP\s+BY\b|\bORDER\s+BY\b|\bHAVING\b|\bLIMIT\b
            |;|$
        )
        """,
        flags=re.I | re.S | re.X,
    )

    parts = _split_outside_quotes(sql)
    for i in range(0, len(parts), 2):
        seg = parts[i]
        protected_on_segments: List[str] = []

        def _protect_on(m: re.Match) -> str:
            protected_on_segments.append(m.group(0))
            return f" __ON_CLAUSE_PROTECTED_{len(protected_on_segments) - 1}__ "

        seg_masked = on_clause_pat.sub(_protect_on, seg)

        def _repl(m: re.Match) -> str:
            alias = m.group("alias")
            col = m.group("col")
            aq = m.group("aq") or ""
            cq = m.group("cq") or ""

            alias_l = alias.lower()
            col_l = col.lower()

            entry = symbol_map.get(alias_l)
            if not entry:
                return m.group(0)

            src_tbl = entry[0]
            src_cols = table_cols.get(src_tbl, set())
            if col_l in src_cols:
                return m.group(0)

            same_table_col = _resolve_same_table_column(src_tbl, col, alias_l)
            if same_table_col and same_table_col.lower() != col_l:
                same_table_col_case = _original_case_col(src_tbl, same_table_col)
                return f"{aq}{alias}{aq}.{cq}{same_table_col_case}{cq}"

            qualifier_expr = f"{aq}{alias}{aq}" if aq else alias
            full_name_expr = _resolve_same_table_full_name_expr(src_tbl, qualifier_expr, col)
            if full_name_expr:
                return full_name_expr

            replacement = _pick_replacement_symbol(alias_l, col_l)
            if not replacement:
                return m.group(0)

            return f"{aq}{replacement}{aq}.{cq}{col}{cq}"

        seg_rewritten = qcol_pat.sub(_repl, seg_masked)
        for idx, original_on in enumerate(protected_on_segments):
            seg_rewritten = seg_rewritten.replace(f" __ON_CLAUSE_PROTECTED_{idx}__ ", original_on)
        parts[i] = seg_rewritten

    return "".join(parts)


def _repair_simple_single_table_column_names(sql: str, ctx: str = "") -> str:
    """
    Schema-aware repair for simple single-table queries where the model uses
    naturalized snake_case identifiers instead of the actual schema column names.

    Example:
      customer_number -> customerNumber
      payment_date    -> paymentDate

    Conservative guardrails:
    - only for a single base table with no JOIN
    - only when normalized identifier maps uniquely to one real column
    - skips aliases after AS and function names
    """
    if not sql:
        return sql
    if has_join(sql):
        return sql
    if re.search(r"\bfrom\s*\(", sql, flags=re.I):
        return sql

    m_from = re.search(
        r"""
        \bFROM\s+
        (?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
        (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
        """,
        sql,
        flags=re.I | re.X,
    )
    if not m_from:
        return sql

    table_raw = (m_from.group("table") or "").replace("`", "")
    table_l = table_raw.split(".")[-1].strip().lower()
    alias = (m_from.group("alias") or "").strip()
    if alias and alias.lower() in _RESERVED_ALIASES:
        alias = ""
    if not table_l:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    actual_cols: List[str] = []
    if analyzer:
        try:
            actual_cols = [str(c) for c in analyzer.get_table_columns(table_l) if str(c)]
        except Exception:
            actual_cols = []
    if not actual_cols and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            actual_cols = [str(c) for c in (allowed.get(table_l, set()) or []) if str(c)]
        except Exception:
            actual_cols = []
    if not actual_cols:
        return sql

    actual_cols_lower = {c.lower() for c in actual_cols}

    def _norm_ident(text: str) -> str:
        return re.sub(r"[^a-z0-9]+", "", (text or "").strip().lower())

    norm_map: Dict[str, List[str]] = {}
    for c in actual_cols:
        norm_map.setdefault(_norm_ident(c), []).append(c)

    def _identifier_tokens(text: str) -> Set[str]:
        raw = str(text or "").strip()
        if not raw:
            return set()
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ").replace("-", " ")
        return {tok for tok in re.findall(r"[a-z0-9]+", raw.lower()) if tok}

    semantic_noise_tokens = {
        "id", "ids", "code", "codes", "number", "numbers",
        "name", "names", "date", "dates", "time", "times",
        "value", "values", "data", "info", "detail", "details",
        "description", "descriptions", "text", "type", "types",
        "status", "flag", "flags",
    }
    col_name_tokens: Dict[str, Set[str]] = {}
    col_syn_tokens: Dict[str, Set[str]] = {}
    col_desc_tokens: Dict[str, Set[str]] = {}
    col_role_tokens: Dict[str, Set[str]] = {}
    for c in actual_cols:
        c_l = str(c or "").strip().lower()
        if not c_l:
            continue
        col_name_tokens[c_l] = _identifier_tokens(c)

        syn_tokens: Set[str] = set()
        desc_tokens: Set[str] = set()
        role_tokens: Set[str] = set()

        if analyzer is not None:
            try:
                for syn in analyzer.get_column_synonyms(table_l, c_l) or []:
                    syn_tokens.update(_identifier_tokens(str(syn or "")))
            except Exception:
                pass
            try:
                desc_txt = str(analyzer.get_column_description(table_l, c_l) or "").strip()
                if desc_txt:
                    desc_tokens.update(_identifier_tokens(desc_txt))
            except Exception:
                pass
        else:
            try:
                desc_txt = str(get_column_description(table_l, c_l) or "").strip()
                if desc_txt:
                    desc_tokens.update(_identifier_tokens(desc_txt))
            except Exception:
                pass

        try:
            role_txt = str(get_column_role(table_l, c_l) or "").strip()
        except Exception:
            role_txt = ""
        if role_txt:
            role_tokens.update(_identifier_tokens(role_txt))

        col_syn_tokens[c_l] = syn_tokens
        col_desc_tokens[c_l] = desc_tokens
        col_role_tokens[c_l] = role_tokens

    actual_case_by_lower = {str(c).strip().lower(): str(c) for c in actual_cols if str(c).strip()}

    def _canonical_output_col(col_l: str) -> str:
        key_l = str(col_l or "").strip().lower()
        if not key_l:
            return str(col_l or "")
        if analyzer is not None:
            try:
                canon = str(analyzer._column_original_case.get(f"{table_l}.{key_l}", "")).strip()
                if canon:
                    return canon
            except Exception:
                pass
        return actual_case_by_lower.get(key_l, key_l)

    def _resolve_semantic_col(token: str) -> Optional[str]:
        tok = str(token or "").strip().lower()
        if not tok:
            return None
        if tok in actual_cols_lower:
            return None

        best_col_l = ""
        best_score = 0
        tied = False
        for c_l in actual_case_by_lower.keys():
            score = 0
            if tok in col_name_tokens.get(c_l, set()):
                score += 3
            if tok in col_syn_tokens.get(c_l, set()):
                score += 2
            if tok in col_role_tokens.get(c_l, set()):
                score += 2
            if tok in col_desc_tokens.get(c_l, set()):
                score += 1
            if score <= 0:
                continue
            if score > best_score:
                best_col_l = c_l
                best_score = score
                tied = False
            elif score == best_score:
                tied = True

        # Guardrail: avoid weak/noisy rewrites.
        if best_score < 2:
            return None
        if tok in semantic_noise_tokens and best_score < 3:
            return None
        if tied or not best_col_l:
            return None
        return _canonical_output_col(best_col_l)

    def _resolve_col(token: str) -> Optional[str]:
        tl = (token or "").strip().lower()
        if not tl:
            return None
        if tl in actual_cols_lower:
            return None
        cands = norm_map.get(_norm_ident(token), [])
        if len(cands) == 1:
            return _canonical_output_col(str(cands[0]).strip().lower())
        return _resolve_semantic_col(token)

    valid_symbols = {table_l}
    if alias:
        valid_symbols.add(alias.lower())

    qcol_pat = re.compile(
        r"""
        (?P<aq>`?)
        (?P<sym>[A-Za-z_][A-Za-z0-9_]*)
        (?P=aq)\s*\.\s*
        (?P<cq>`?)
        (?P<col>[A-Za-z_][A-Za-z0-9_]*)
        (?P=cq)
        """,
        flags=re.X,
    )

    parts = _split_outside_quotes(sql)
    for i in range(0, len(parts), 2):
        seg = parts[i]

        def _qual_repl(m: re.Match) -> str:
            sym = (m.group("sym") or "").lower()
            col = m.group("col") or ""
            if sym not in valid_symbols:
                return m.group(0)
            replacement = _resolve_col(col)
            if not replacement:
                return m.group(0)
            aq = m.group("aq") or ""
            cq = m.group("cq") or ""
            return f"{aq}{m.group('sym')}{aq}.{cq}{replacement}{cq}"

        seg = qcol_pat.sub(_qual_repl, seg)

        token_pat = re.compile(r"\b([A-Za-z_][A-Za-z0-9_]*)\b")

        def _unqual_repl(m: re.Match) -> str:
            token = m.group(1)
            low = token.lower()
            if low in _SQL_KEYWORDS or low in valid_symbols or low in actual_cols_lower:
                return token

            left = seg[:m.start()]
            right = seg[m.end():]
            if left.rstrip().endswith("."):
                return token
            if re.search(r"\bAS\s*$", left, flags=re.I):
                return token
            if right.lstrip().startswith("("):
                return token

            replacement = _resolve_col(token)
            return replacement or token

        parts[i] = token_pat.sub(_unqual_repl, seg)

    return "".join(parts)

def _is_simple_column_expr(x: str) -> bool:
    """
    Hanya izinkan bentuk kolom sederhana:
      - col
      - alias.col
      - `alias`.`col` atau `col`
    Tidak izinkan fungsi/aritmetika kompleks (konservatif).
    """
    if not x:
        return False
    t = x.strip()
    # buang alias AS ... kalau ada (caller biasanya sudah pisah, tapi aman)
    t = re.sub(r"\s+AS\s+\w+\s*$", "", t, flags=re.I).strip()
    # match: `a`.`b` | a.b | `b` | b
    return re.fullmatch(
        r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?",
        t
    ) is not None

def _drop_redundant_column_aliases(sql: str) -> str:
    """
    Hapus alias yang redundant untuk kolom sederhana:
      - customerNumber AS customerNumber  -> customerNumber
      - p.amount AS amount                -> p.amount
    TIDAK menyentuh:
      - fungsi/window/expr (harus tetap ber-alias jika butuh nama output stabil)
      - alias yang beda nama
    """
    if not sql:
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        # Fallback regex konservatif (hanya untuk bentuk kolom sederhana)
        # alias.col AS col  / col AS col
        def _repl(m: re.Match) -> str:
            expr = m.group("expr").strip()
            al = m.group("al").strip()
            # hanya drop jika expr adalah kolom sederhana dan nama akhirnya sama dgn alias
            if not _is_simple_column_expr(expr):
                return m.group(0)
            last = expr.replace("`", "").split(".")[-1].strip()
            return expr if last.lower() == al.lower() else m.group(0)

        return re.sub(
            r"(?P<expr>(?:`?[A-Za-z_]\w*`?\s*\.\s*)?`?[A-Za-z_]\w*`?)\s+AS\s+(?P<al>[A-Za-z_]\w*)\b",
            _repl,
            sql,
            flags=re.I,
        )

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    changed = False

    def transform(node: "exp.Expression") -> "exp.Expression":
        nonlocal changed
        # Drop only: Alias(Column, alias_name) where alias_name == column.name
        if isinstance(node, exp.Alias) and isinstance(node.this, exp.Column):
            alias = (node.alias or "").strip()
            colname = (node.this.name or "").strip()
            if alias and colname and alias.lower() == colname.lower():
                changed = True
                return node.this
        return node

    ast2 = ast.transform(transform)
    return ast2.sql(dialect="mysql") if changed else sql


def _ast_normalize_from_aliases(sql: str) -> Tuple[str, Dict[str, Any]]:
    """
    AST-first cleanup for unused base-table aliases.

    Scope for this batch:
    - parseable query roots handled in AST-first mode
    - actual alias removal remains narrow: top-level SELECT with one real table
      in FROM and no JOINs

    Within that scope, removing an unused base-table alias is structurally safe
    because all alias references are inspected directly from the AST.
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
    }
    s = str(sql or "").strip()
    if not s:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    setop_types = tuple(
        cls for cls in (
            getattr(exp, "SetOperation", None),
            getattr(exp, "Union", None),
            getattr(exp, "Intersect", None),
            getattr(exp, "Except", None),
        )
        if cls is not None
    )
    if not isinstance(ast, (exp.Select,) + setop_types):
        meta["warnings"].append("unsupported_root")
        return sql, meta

    meta["handled_scope"] = True
    if not isinstance(ast, exp.Select):
        return sql, meta

    sel = ast
    from_arg = sel.args.get("from") or sel.args.get("from_")
    if from_arg is None:
        return sql, meta

    base_table_expr = getattr(from_arg, "this", None)
    if not isinstance(base_table_expr, exp.Table):
        return sql, meta

    join_exprs = [j for j in (sel.args.get("joins") or []) if isinstance(j, exp.Join)]
    if join_exprs:
        return sql, meta

    table_alias_expr = getattr(base_table_expr, "args", {}).get("alias")
    if table_alias_expr is None:
        return sql, meta

    alias_name = str(base_table_expr.alias or "").strip("`")
    if not alias_name:
        return sql, meta
    if alias_name.lower() in _RESERVED_ALIASES:
        meta["warnings"].append("reserved_alias_skipped")
        return sql, meta

    for col in sel.find_all(exp.Column):
        table_name = str(col.table or "").strip("`").lower()
        if table_name and table_name == alias_name.lower():
            return sql, meta

    changed = False

    def _drop_base_alias(node: "exp.Expression") -> "exp.Expression":
        nonlocal changed
        if node is base_table_expr:
            new_node = node.copy()
            new_node.set("alias", None)
            changed = True
            return new_node
        return node

    ast2 = ast.transform(_drop_base_alias)
    if not changed:
        return sql, meta

    meta["fixes"].append("drop_unused_from_alias_ast")
    out_sql = ast2.sql(dialect=SQL_PARSE_DIALECT or "mysql")
    if sql.strip().endswith(";"):
        out_sql = out_sql.rstrip(";") + ";"
    return out_sql, meta


def _drop_unused_from_table_aliases(sql: str) -> str:
    """
    Hapus alias di FROM <table> [AS] <alias> jika alias itu tidak pernah dipakai sebagai qualifier (alias.col)
    di sisa query.

    Sangat konservatif:
    - hanya jalan kalau query TIDAK punya JOIN (biar tidak ganggu join semantics)
    - tidak menyentuh derived table: FROM (SELECT ...) t  (karena MySQL butuh alias derived table)
    - tidak menyentuh alias reserved
    """
    if not sql:
        return sql
    # FIX 1: Kalau ada JOIN di mana pun, jangan sentuh (biar aman).
    if has_join(sql):
        return sql

    # FIX 2: Kalau ada GROUP BY, jangan sentuh (kemungkinan besar ada aggregasi multi-table)
    if "GROUP BY" in sql.upper():
        return sql

    # FIX 3: Kalau ada aggregate functions, jangan sentuh
    if re.search(r"\b(SUM|COUNT|AVG|MIN|MAX|GROUP_CONCAT)\s*\(", sql, flags=re.I):
        return sql

    # Build versi "scan" yang aman dari string literal + backticks untuk deteksi alias.col
    scan = _strip_string_literals(sql).replace("`", "")

    pat = re.compile(
        r"""
        \bFROM\s+
        (?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.[A-Za-z_][A-Za-z0-9_]*)?)
        \s+
        (?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)\b
        """,
        flags=re.IGNORECASE | re.VERBOSE,
    )

    def repl(m: re.Match) -> str:
        table_raw = m.group("table")
        alias = m.group("alias")

        # derived table tidak match di sini (karena table token bukan '('), jadi aman
        if not alias or alias.lower() in _RESERVED_ALIASES:
            return m.group(0)

        # FIX 4: Cek apakah alias dipakai di SELURUH query (bukan hanya setelah FROM)
        # SEBELUMNYA: scan[m.end():] → hanya cek setelah FROM
        # SEKARANG: scan → cek di seluruh query (termasuk SELECT clause)
        if re.search(rf"\b{re.escape(alias)}\s*\.", scan, flags=re.I):
            return m.group(0)

        # alias tidak dipakai -> drop alias
        return f"FROM {table_raw}"

    return pat.sub(repl, sql)

def _strip_alias_if_single_table(sql: str) -> str:
    """
    If query has only one base table in FROM and no JOIN,
    strip alias prefixes like e.col -> col.
    DO NOT touch queries with GROUP BY or subqueries.
    """
    if not sql:
        return sql

    s = sql.lower()

    # ULTRA SAFE GUARDS
    if re.search(r"\bjoin\b", s):
        print(f"[REFINER - STRIP ALIAS] SKIP: has join")
        return sql
    
    if re.search(r"\bgroup\s+by\b", s):
        print(f"[REFINER - STRIP ALIAS] SKIP: has GROUP BY")
        return sql
    
    if re.search(r"\bfrom\s*\(", s):
        print(f"[REFINER - STRIP ALIAS] SKIP: has subquery")
        return sql
    
    if re.search(r"\brow_number\b", s):
        print(f"[REFINER - STRIP ALIAS] SKIP: has ROW_NUMBER")
        return sql
    
    if re.search(r"\b(sum|count|avg|min|max)\s*\(", s):
        print(f"[REFINER - STRIP ALIAS] SKIP: has aggregate")
        return sql

    print(f"[REFINER - STRIP ALIAS] Processing simple single-table query...")

    m = re.search(r"\bfrom\s+([a-zA-Z_][a-zA-Z0-9_]*)\b", s)
    if not m:
        return sql

    parts = re.split(r"('(?:''|[^'])*')", sql)

    for i in range(0, len(parts), 2):
        parts[i] = re.sub(
            r"\b([a-zA-Z_][a-zA-Z0-9_]*)\.",
            "",
            parts[i],
        )

    result = "".join(parts)
    print(f"[REFINER - STRIP ALIAS] Output: {result[:100]}")
    return result


def _ast_normalize_cosmetic_aliases(sql: str) -> Tuple[str, Dict[str, Any]]:
    """
    AST-first cosmetic alias normalization.

    Scope for this batch:
    - parseable query roots handled in AST-first mode
    - always safe to drop same-name plain-column aliases
    - only strip table qualifiers for simple single-table non-aggregate,
      non-grouped, non-window queries
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
    }
    s = str(sql or "").strip()
    if not s:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    setop_types = tuple(
        cls for cls in (
            getattr(exp, "SetOperation", None),
            getattr(exp, "Union", None),
            getattr(exp, "Intersect", None),
            getattr(exp, "Except", None),
        )
        if cls is not None
    )
    if not isinstance(ast, (exp.Select,) + setop_types):
        meta["warnings"].append("unsupported_root")
        return sql, meta

    meta["handled_scope"] = True
    changed = False

    def _drop_same_name_alias(node: "exp.Expression") -> "exp.Expression":
        nonlocal changed
        if isinstance(node, exp.Alias) and isinstance(node.this, exp.Column):
            alias_name = str(node.alias or "").strip("`")
            col_name = str(node.this.name or "").strip("`")
            if alias_name and col_name and alias_name.lower() == col_name.lower():
                changed = True
                return node.this.copy()
        return node

    ast = ast.transform(_drop_same_name_alias)
    if changed and "drop_redundant_column_alias_ast" not in meta["fixes"]:
        meta["fixes"].append("drop_redundant_column_alias_ast")

    if isinstance(ast, exp.Select):
        sel = ast
        from_arg = sel.args.get("from") or sel.args.get("from_")
        base_table_expr = getattr(from_arg, "this", None) if from_arg is not None else None
        join_exprs = [j for j in (sel.args.get("joins") or []) if isinstance(j, exp.Join)]
        has_group = sel.args.get("group") is not None
        has_window = any(True for _ in sel.find_all(exp.Window))
        has_aggregate = any(True for _ in sel.find_all(exp.AggFunc))
        has_subquery = any(True for _ in sel.find_all(exp.Subquery))

        if (
            isinstance(base_table_expr, exp.Table)
            and not join_exprs
            and not has_group
            and not has_window
            and not has_aggregate
            and not has_subquery
        ):
            base_name = str(base_table_expr.name or "").strip("`").lower()
            alias_name = str(base_table_expr.alias_or_name or "").strip("`").lower()
            allowed_qualifiers = {q for q in {base_name, alias_name} if q}

            def _strip_simple_qualifier(node: "exp.Expression") -> "exp.Expression":
                nonlocal changed
                if isinstance(node, exp.Column):
                    table_name = str(node.table or "").strip("`").lower()
                    if table_name and table_name in allowed_qualifiers:
                        changed = True
                        return exp.column(str(node.name or "").strip("`"))
                return node

            ast = ast.transform(_strip_simple_qualifier)
            if changed and "strip_single_table_qualifier_ast" not in meta["fixes"]:
                meta["fixes"].append("strip_single_table_qualifier_ast")

    if not changed:
        return sql, meta

    out_sql = ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
    if sql.strip().endswith(";"):
        out_sql = out_sql.rstrip(";") + ";"
    return out_sql, meta
# =======================================================================
# ============ Phase 3 — Column Naming & GROUP BY Consistency ===========
# ================== Operate on final column identities =================
# =======================================================================
# - _prefer_name_over_id_generic
# - prefer_friendly_names
# - expand_group_by_aliases_regex
# - is_potential_winner_row
# - enforce_explicit_group_by

def _prefer_name_over_id_generic(
    sql: str,
    question: str,
    wants_name_fn,
    name_column: str,
    id_columns: List[str],
    entity_words: Optional[List[str]] = None,
) -> str:
    """
    Ganti penggunaan kolom ID menjadi kolom nama yang lebih 'friendly'
    untuk SELECT & GROUP BY, kalau pertanyaan memang prefer 'name'.
    Contoh:
      - customerNumber -> customerName
      - productCode    -> productName
    """
    if not wants_name_fn(question):
        return sql

    q = str(question or "").strip().lower()

    id_terms = [
        str(term or "").strip().lower()
        for term in identifier_id_like_terms()
        if str(term or "").strip()
    ] or ["id", "ids", "number", "numbers", "code", "codes", "key", "keys"]
    entity_forms = [
        str(word or "").strip().lower()
        for word in (entity_words or [])
        if str(word or "").strip()
    ]

    explicit_identifier_request = bool(
        re.search(r"\b(?:ids?|identifiers?|numbers?|nomors?|nos?|codes?|kodes?|keys?)\b", q, flags=re.I)
    )
    if not explicit_identifier_request and entity_forms and id_terms:
        id_alt = "|".join(
            re.escape(term).replace(r"\ ", r"\s+")
            for term in sorted(set(id_terms), key=len, reverse=True)
        )
        for entity in entity_forms:
            entity_pat = re.escape(entity).replace(r"\ ", r"\s+")
            if re.search(rf"\b{entity_pat}\b\s+(?:{id_alt})\b", q, flags=re.I):
                explicit_identifier_request = True
                break
            if re.search(rf"\b(?:{id_alt})\b\s+(?:of|for)\s+\b{entity_pat}\b", q, flags=re.I):
                explicit_identifier_request = True
                break
            compact = re.sub(r"[^a-z0-9]+", "_", entity).strip("_")
            if compact and any(f"{compact}_{term.replace(' ', '_')}" in q.replace("-", "_").replace(" ", "_") for term in id_terms):
                explicit_identifier_request = True
                break

    # If the question explicitly asks for an identifier form, never rewrite it
    # away into the friendly display-name column.
    if explicit_identifier_request:
        return sql

    # contoh: "customerNumber|customer_id|..."
    id_pattern = "|".join(re.escape(c) for c in id_columns)

    # -------------------------------------------------------------
    # CASE 1: SELECT alias.idCol → SELECT alias.nameCol AS nameCol
    # -------------------------------------------------------------
    sql = re.sub(
        rf"SELECT\s+([A-Za-z_][A-Za-z0-9_]*)\.({id_pattern})(\s+AS\s+\2)?",
        rf"SELECT \1.{name_column} AS {name_column}",
        sql,
        flags=re.I,
    )
    # -------------------------------------------------------------
    # CASE 2: SELECT alias.idCol, ... → SELECT alias.nameCol, .....
    # -------------------------------------------------------------
    sql = re.sub(
        rf"SELECT\s+([A-Za-z_][A-Za-z0-9_]*)\.({id_pattern})\s*,",
        rf"SELECT \1.{name_column},",
        sql,
        flags=re.I,
    )
    # -------------------------------------------------------------
    # CASE 3: GROUP BY alias.idCol → GROUP BY alias.nameCol
    # -------------------------------------------------------------
    sql = re.sub(
        rf"GROUP BY\s+([A-Za-z_][A-Za-z0-9_]*)\.({id_pattern})\b",
        rf"GROUP BY \1.{name_column}",
        sql,
        flags=re.I,
    )

    return sql


def _rewrite_invalid_grouped_existence_subquery_to_join(sql: str, question: str, ctx: str = "") -> str:
    """
    Rewrite a narrow invalid grouped-existence pattern into a direct JOIN.

    Target anti-pattern:
      SELECT group_col, COUNT(DISTINCT outer_id)
      FROM outer_table
      WHERE group_col IN (SELECT DISTINCT group_col FROM child_table)
      GROUP BY group_col

    when `child_table` does NOT actually have `group_col`, but it has a unique
    direct FK to `outer_table`. In that case, the intended meaning is usually:
      - keep only outer rows that have at least one child row
      - aggregate over those qualifying outer rows

    This helper is intentionally conservative:
    - only for single-table outer queries (no JOIN yet)
    - only when question asks for COUNT(DISTINCT ...)
    - only when include-zero is NOT requested
    - only when the child table has exactly one direct FK path to the outer table
    - only when the DISTINCT target is the outer table's ID column
    """
    if not sql:
        return sql
    if has_join(sql):
        return sql
    if not _question_wants_count_distinct(question):
        return sql
    if _question_wants_include_zero(question, ctx):
        return sql

    s = (sql or "").strip().rstrip(";").strip()
    if not s:
        return sql

    outer_pat = re.compile(
        r"""
        (?is)^\s*
        SELECT\s+(?P<select>.+?)
        \s+FROM\s+
        (?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
        (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
        \s+WHERE\s+(?P<where>.+?)
        \s+GROUP\s+BY\s+(?P<groupby>.+?)
        (?P<tail>\s+(?:HAVING|ORDER\s+BY|LIMIT)\b.*)?$
        """,
        flags=re.X,
    )
    m = outer_pat.match(s)
    if not m:
        return sql

    select_clause = (m.group("select") or "").strip()
    outer_table_raw = (m.group("table") or "").replace("`", "")
    outer_table = outer_table_raw.split(".")[-1].strip()
    outer_alias = (m.group("alias") or "").strip()
    where_clause = (m.group("where") or "").strip()
    group_by_clause = (m.group("groupby") or "").strip()
    tail = (m.group("tail") or "").strip()

    if not outer_table:
        return sql

    select_items = _split_top_level_commas(select_clause)
    group_items = _split_top_level_commas(group_by_clause)
    if not select_items or not group_items:
        return sql

    count_distinct_pat = re.compile(
        r"""(?is)^COUNT\s*\(\s*DISTINCT\s+(?P<expr>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)(?:\s+AS\s+(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?$"""
    )
    count_distinct_expr = None
    for item in select_items:
        m_count = count_distinct_pat.match(item.strip())
        if m_count:
            count_distinct_expr = (m_count.group("expr") or "").strip()
            break
    if not count_distinct_expr:
        return sql

    def _base_col(expr: str) -> str:
        e = (expr or "").strip().replace("`", "")
        if "." in e:
            return e.split(".")[-1].strip()
        return e.strip()

    group_expr = group_items[0].strip()
    group_col = _base_col(group_expr)
    distinct_col = _base_col(count_distinct_expr)
    outer_id = get_id_column(outer_table)
    if not outer_id or distinct_col.lower() != str(outer_id).lower():
        return sql

    where_pat = re.compile(
        r"""
        (?is)^\s*
        (?P<lhs>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)
        \s+IN\s*\(
            \s*SELECT\s+DISTINCT\s+
            (?P<rhs>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)
            \s+FROM\s+
            (?P<inner_table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
            (?:\s+(?:AS\s+)?(?P<inner_alias>[A-Za-z_][A-Za-z0-9_]*))?
            \s*
        \)\s*$
        """,
        flags=re.X,
    )
    w = where_pat.match(where_clause)
    if not w:
        return sql

    lhs_col = _base_col(w.group("lhs") or "")
    rhs_col = _base_col(w.group("rhs") or "")
    inner_table_raw = (w.group("inner_table") or "").replace("`", "")
    inner_table = inner_table_raw.split(".")[-1].strip()
    if not inner_table:
        return sql

    # We only rewrite the clearly invalid case: same logical column name in the
    # subquery, but the inner table does not actually have that column.
    if lhs_col.lower() != rhs_col.lower():
        return sql

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    inner_cols: Set[str] = set()
    if analyzer is not None:
        try:
            inner_cols.update(c.lower() for c in analyzer.get_table_columns(inner_table))
        except Exception:
            pass
    if not inner_cols and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            inner_cols.update(str(c).strip("`").lower() for c in allowed.get(inner_table, set()))
        except Exception:
            pass

    if lhs_col.lower() in inner_cols:
        return sql

    fk_map = get_fk_relationships() or {}
    direct_fk_cols = [
        str(fk_col)
        for fk_col, tgt in (fk_map.get(inner_table.lower(), {}) or {}).items()
        if str(tgt or "").lower() == outer_table.lower()
    ]
    if len(direct_fk_cols) != 1:
        return sql

    fk_col = direct_fk_cols[0]
    outer_ref = outer_alias or outer_table
    inner_ref = inner_table

    # Qualify COUNT(DISTINCT outer_id) so the new JOIN cannot make it ambiguous.
    qualified_count_expr = count_distinct_expr
    if "." not in count_distinct_expr.replace("`", ""):
        qualified_count_expr = f"{outer_ref}.{outer_id}"
    new_select_clause = re.sub(
        r"""(?is)COUNT\s*\(\s*DISTINCT\s+(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?\s*\)""",
        f"COUNT(DISTINCT {qualified_count_expr})",
        select_clause,
        count=1,
    )

    join_clause = (
        f"FROM {outer_table_raw}"
        f"{(' ' + outer_alias) if outer_alias else ''} "
        f"JOIN {inner_table_raw} ON {inner_ref}.{fk_col} = {outer_ref}.{outer_id}"
    )

    rebuilt = (
        f"SELECT {new_select_clause} "
        f"{join_clause} "
        f"GROUP BY {group_by_clause}"
    )
    if tail:
        rebuilt += f" {tail}"
    if sql.strip().endswith(";"):
        rebuilt += ";"
    return rebuilt

def _wants_name_only(question: str, entity_words: List[str]) -> bool:
    """
    Return True when the question refers to an entity but does not
    explicitly ask for an id/number/code form.
    """
    q = (question or "").lower()
    # buang "number of" supaya tidak dianggap id-like
    q = re.sub(r"\b(total\s+)?number\s+of\b", "", q)

    def _phrase_mentioned(text: str, phrase: str) -> bool:
        p = str(phrase or "").strip().lower()
        if not p:
            return False
        pattern = re.escape(p).replace(r"\ ", r"\s+")
        return re.search(rf"\b{pattern}\b", text) is not None

    mention_entity = any(_phrase_mentioned(q, w) for w in entity_words)
    mention_id_like = (
        re.search(r"\b(ids?|numbers?|nomors?|nos?|codes?|kodes?)\b", q)
        or any(_phrase_mentioned(q, f"{w} code") for w in entity_words)
        or any(_phrase_mentioned(q, f"{w} codes") for w in entity_words)
    )
    return mention_entity and not mention_id_like

def _entity_words_for_table(table: str) -> List[str]:
    """
    Build entity words dynamically from schema metadata.
    Includes table name, singular form, and table synonyms.
    """
    words: Set[str] = set()
    t = (table or "").strip().lower()
    if not t:
        return []

    words.add(t)
    try:
        s = get_singular_form(t)
        if s:
            words.add(s.lower())
    except Exception:
        if t.endswith("s") and len(t) > 1:
            words.add(t[:-1])

    generic_terms = {
        "name", "names", "id", "ids", "code", "codes", "number", "numbers",
        "date", "dates", "status", "type", "types", "value", "values",
        "amount", "amounts", "total", "totals", "count", "counts",
        "description", "descriptions", "detail", "details", "record", "records",
        "row", "rows", "entry", "entries", "unit", "units",
    }

    try:
        for syn in get_table_synonyms(t):
            syn_low = str(syn).strip().lower()
            if not syn_low:
                continue
            syn_tokens = [tok for tok in re.findall(r"[a-z0-9]+", syn_low) if tok]
            if not syn_tokens:
                continue
            # Skip generic synonyms that cause false entity hits (e.g., "name", "unit").
            if all(tok in generic_terms for tok in syn_tokens):
                continue
            if len(syn_tokens) == 1 and len(syn_tokens[0]) < 4:
                continue
            syn_norm = " ".join(syn_tokens)
            if syn_norm:
                words.add(syn_norm)
            # Also include compact form for underscore/space variations.
            compact = syn_norm.replace(" ", "")
            if compact and len(compact) >= 5:
                words.add(compact)
    except Exception:
        pass

    return sorted(words)


def _display_name_column_for_table(table: str) -> Optional[str]:
    """
    Return a table's single-column display name only when it looks like a
    true entity label, not a split name component such as lastName.
    """
    table_l = (table or "").strip().lower()
    if not table_l:
        return None

    name_col = get_name_column(table_l)
    id_col = get_id_column(table_l)
    if not name_col or not id_col:
        return None
    if str(name_col).strip().lower() == str(id_col).strip().lower():
        return None

    component_terms = {
        str(tok).strip().lower()
        for tok in name_component_lexical_tokens()
        if str(tok).strip().lower() not in {"name", "fullname", "full_name"}
    }
    component_phrase_hints = {
        str(phrase).strip().lower()
        for phrase in name_component_synonym_hints()
        if str(phrase).strip().lower() != "full name"
    }

    def _identifier_tokens(val: str) -> Set[str]:
        s = str(val or "").strip()
        if not s:
            return set()
        s = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", s)
        s = s.replace("_", " ")
        return {tok.lower() for tok in re.findall(r"[a-z0-9]+", s)}

    col_l = str(name_col).strip().lower()
    col_tokens = _identifier_tokens(col_l)
    if col_tokens.intersection(component_terms):
        return None

    col_compact = re.sub(r"[^a-z0-9]", "", col_l)
    for term in component_terms:
        compact_term = re.sub(r"[^a-z0-9]", "", term)
        if len(compact_term) >= 4 and compact_term in col_compact:
            return None

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    if analyzer is not None:
        try:
            syns = (analyzer._column_synonyms.get(f"{table_l}.{col_l}", []) or [])
        except Exception:
            syns = []
        syn_blob = " ".join(str(x).lower() for x in syns)
        if any_phrase_in_text(syn_blob, component_phrase_hints):
            return None

    return name_col

def _prefer_friendly_names(sql: str, question: str) -> str:
    """
    Prefer display-name columns over identifier columns when the question
    asks for names but not ids/codes, using schema metadata.
    """
    try:
        schema_tables = list(get_all_tables())
    except Exception:
        schema_tables = []

    for table in schema_tables:
        display_name_col = _display_name_column_for_table(table)
        id_col = get_id_column(table)
        if not display_name_col or not id_col:
            continue
        entity_words = _entity_words_for_table(table)
        if not entity_words:
            continue
        sql = _prefer_name_over_id_generic(
            sql=sql,
            question=question,
            wants_name_fn=lambda q, words=entity_words: _wants_name_only(q, words),
            name_column=display_name_col,
            id_columns=[id_col],
            entity_words=entity_words,
        )

    return sql

def _ensure_entity_id_and_name_if_requested(sql: str, question: str) -> str:
    """
    If question explicitly asks for both entity identifier and entity name,
    ensure both columns are present in SELECT (and GROUP BY for grouped queries).

    Dynamic and schema-driven:
    - entity detection from table synonyms / singular names
    - id/name columns from metadata (get_id_column/get_name_column)
    """
    if not sql or not question:
        return sql

    q = (question or "").lower()
    q_norm = re.sub(r"\b(total\s+)?number\s+of\b", "", q)
    q_snake = re.sub(r"[^a-z0-9_]+", "_", q_norm).strip("_")
    wants_split_name_components = question_wants_split_name_components(question)
    name_component_token_hints = name_component_lexical_tokens()
    name_component_synonym_hint_phrases = name_component_synonym_hints()
    name_priority_groups = name_component_priority_groups()

    def _terms_to_regex_alternation(terms: List[str]) -> str:
        pats: List[str] = []
        for t in terms:
            s = str(t or "").strip().lower()
            if not s:
                continue
            pats.append(re.escape(s).replace(r"\ ", r"\s+"))
        if not pats:
            return ""
        pats = sorted(set(pats), key=len, reverse=True)
        return f"(?:{'|'.join(pats)})"

    id_terms = _terms_to_regex_alternation(identifier_id_like_terms()) or r"(?:ids?|numbers?|nomors?|nos?|codes?|kodes?)"
    name_terms = _terms_to_regex_alternation(name_request_terms()) or r"(?:full\s+names?|names?)"

    def _entity_wants_id_like(entity_words: List[str], table_name: str) -> bool:
        forms: Set[str] = {table_name.lower(), (get_singular_form(table_name) or table_name).lower()}
        for w in entity_words:
            ww = (w or "").strip().lower()
            if ww:
                forms.add(ww)
                forms.add(ww.replace(" ", "_"))

        for f in forms:
            if not f:
                continue
            if any(
                token in q_snake
                for token in (
                    f"{f}_id",
                    f"{f}_ids",
                    f"{f}_number",
                    f"{f}_numbers",
                    f"{f}_code",
                    f"{f}_codes",
                )
            ):
                return True

        for f in forms:
            p = re.escape((f or "").strip().lower()).replace(r"\ ", r"\s+")
            if not p:
                continue
            # Direct forms: "customer id", "id of customer"
            if re.search(rf"\b{p}\b\s+{id_terms}\b", q_norm, flags=re.I):
                return True
            if re.search(rf"\b{id_terms}\b\s+(?:of|for)\s+\b{p}\b", q_norm, flags=re.I):
                return True
            # Shorthand list style: "customer name, id" / "customer name and id"
            if re.search(rf"\b{p}\b\s+{name_terms}\b\s*(?:,|\band\b)\s*(?:their\s+)?{id_terms}\b", q_norm, flags=re.I):
                return True

        return False

    def _entity_wants_name_like(entity_words: List[str], table_name: str) -> bool:
        forms: Set[str] = {table_name.lower(), (get_singular_form(table_name) or table_name).lower()}
        for w in entity_words:
            ww = (w or "").strip().lower()
            if ww:
                forms.add(ww)
                forms.add(ww.replace(" ", "_"))

        for f in forms:
            if not f:
                continue
            if f"{f}_name" in q_snake or f"{f}_names" in q_snake:
                return True

        for f in forms:
            p = re.escape((f or "").strip().lower()).replace(r"\ ", r"\s+")
            if not p:
                continue
            # Direct forms: "customer name", "name of customer"
            if re.search(rf"\b{p}\b\s+{name_terms}\b", q_norm, flags=re.I):
                return True
            if re.search(rf"\b{name_terms}\b\s+(?:of|for)\s+\b{p}\b", q_norm, flags=re.I):
                return True

        return False

    s_top = (sql or "").strip().rstrip(";").strip()
    top_level_group_pos = _find_top_level_clause(s_top, "group by")
    parsed = _parse_select_from_groupby(sql)
    if parsed and top_level_group_pos < 0:
        return sql
    if not parsed:
        # Safety: do not apply relaxed fallback parser on queries with subqueries.
        # It can misinterpret inner GROUP BY as top-level and corrupt FROM/JOIN.
        if re.search(r"\b(?:FROM|JOIN)\s*\(", sql, flags=re.I):
            return sql
        # Relaxed fallback parser for GROUP BY queries with HAVING.
        s = s_top
        m_sel = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<after>.+)$", s)
        if not m_sel:
            return sql
        select_part = (m_sel.group("select") or "").strip()
        after_from = (m_sel.group("after") or "").strip()

        if top_level_group_pos < 0:
            return sql
        after_from_start = m_sel.start("after")
        if top_level_group_pos < after_from_start:
            return sql
        group_start = top_level_group_pos - after_from_start
        group_end = group_start + len("group by")
        from_and_maybe_where = after_from[:group_start].strip()
        after_gb = after_from[group_end:].strip()
        if not from_and_maybe_where or not after_gb:
            return sql

        next_kw = re.search(r"\b(HAVING|ORDER\s+BY|LIMIT)\b", after_gb, flags=re.I)
        if next_kw:
            groupby_part = after_gb[:next_kw.start()].strip()
            rem = after_gb[next_kw.start():].strip()
        else:
            groupby_part = after_gb.strip()
            rem = ""
        if not groupby_part:
            return sql

        having_part = ""
        tail_part = ""
        if rem:
            if re.match(r"(?is)^HAVING\b", rem):
                h_body = re.sub(r"(?is)^HAVING\s+", "", rem).strip()
                h_next = re.search(r"\b(ORDER\s+BY|LIMIT)\b", h_body, flags=re.I)
                if h_next:
                    having_part = h_body[:h_next.start()].strip()
                    tail_part = h_body[h_next.start():].strip()
                else:
                    having_part = h_body
            else:
                tail_part = rem

        where_match = re.search(r"\bWHERE\b", from_and_maybe_where, flags=re.I)
        if where_match:
            from_core = from_and_maybe_where[:where_match.start()].strip()
            where_part = from_and_maybe_where[where_match.start():].strip()
        else:
            from_core = from_and_maybe_where
            where_part = ""

        parsed = {
            "select": select_part,
            "from_core": from_core,
            "where": where_part,
            "groupby": groupby_part,
            "having": having_part,
            "tail": tail_part,
        }

    if not parsed:
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if not from_core:
        return sql

    # Build alias -> table map, plus table self-qualifier fallback.
    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if not alias_to_table:
        # fallback for no-alias FROM base table
        m_base = re.match(r"(?is)^`?([A-Za-z_][A-Za-z0-9_]*)`?", from_core)
        if m_base:
            t = m_base.group(1)
            alias_to_table = {t: t, t.lower(): t}

    if not alias_to_table:
        return sql

    table_to_aliases: Dict[str, List[str]] = {}
    for a, t in alias_to_table.items():
        if not a or not t:
            continue
        # skip convenience lower duplicates
        if a.lower() != a and a.lower() in alias_to_table:
            pass
        table_to_aliases.setdefault(t.lower(), [])
        if a not in table_to_aliases[t.lower()]:
            table_to_aliases[t.lower()].append(a)

    def _phrase_mentioned(text: str, phrase: str) -> bool:
        p = str(phrase or "").strip().lower()
        if not p:
            return False
        pattern = re.escape(p).replace(r"\ ", r"\s+")
        return re.search(rf"\b{pattern}\b", text) is not None

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_simple_col(expr: str) -> Optional[tuple]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    select_items = _split_top_level_commas(parsed["select"])
    group_items = _split_top_level_commas(parsed.get("groupby", ""))

    # Gather selected simple columns by (qualifier?, column) and output aliases.
    selected_cols: List[tuple] = []
    selected_aliases: Set[str] = set()
    selected_exprs: List[str] = []
    for it in select_items:
        expr, out_alias = _split_expr_alias(it)
        selected_exprs.append(expr.strip())
        if out_alias:
            selected_aliases.add(out_alias.strip().strip("`'\"").lower())
        pcol = _parse_simple_col(expr)
        if pcol:
            qf, col = pcol
            selected_cols.append((qf.lower() if qf else None, col.lower()))

    grouped_cols: Set[tuple] = set()
    for g in group_items:
        pcol = _parse_simple_col(g)
        if pcol:
            qf, col = pcol
            grouped_cols.add((qf.lower() if qf else None, col.lower()))

    changed = False
    prepended_cols: List[str] = []

    for table in get_all_tables():
        t = (table or "").strip().lower()
        if t not in table_to_aliases:
            continue

        # only enforce when the question actually mentions this entity
        entity_words = _entity_words_for_table(table)
        if not any(_phrase_mentioned(q_norm, w) for w in entity_words):
            continue
        if not (_entity_wants_id_like(entity_words, table) and _entity_wants_name_like(entity_words, table)):
            continue

        id_col = get_id_column(table)
        name_col = get_name_column(table)
        if not id_col or not name_col:
            continue
        id_col_l = id_col.lower()
        name_col_l = name_col.lower()

        aliases = table_to_aliases.get(t) or [table]
        # Prefer first non-lowercase convenience alias
        qual = aliases[0]
        qual_l = qual.lower()
        singular = (get_singular_form(table) or table).lower()
        table_name_aliases = {
            f"{singular}_name",
            f"{table.lower()}_name",
            f"{qual_l}_name",
            f"{singular}name",
            f"{table.lower()}name",
            f"{qual_l}name",
            "name",
        }

        # Build schema-driven name component candidates for this table.
        try:
            analyzer = get_schema_analyzer()
            table_cols = {
                str(c).strip("`").lower()
                for c in analyzer.get_table_columns(t)
                if str(c).strip()
            }
        except Exception:
            analyzer = None
            table_cols = set()

        def _identifier_tokens(val: str) -> Set[str]:
            s = str(val or "").strip()
            if not s:
                return set()
            s = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", s)
            s = s.replace("_", " ")
            return {tok.lower() for tok in re.findall(r"[a-z0-9]+", s)}

        def _matches_name_token_hint(col_name: str, toks: Set[str], hints: Set[str]) -> bool:
            if not hints:
                return False
            norm_toks = {str(t).strip().replace(" ", "_").lower() for t in toks if str(t).strip()}
            if norm_toks.intersection(hints):
                return True
            col_compact = re.sub(r"[^a-z0-9]", "", str(col_name or "").lower())
            for hint in hints:
                h = re.sub(r"[^a-z0-9]", "", str(hint or "").lower())
                if len(h) >= 4 and h in col_compact:
                    return True
            return False

        def _is_name_component_column(col: str) -> bool:
            c = str(col or "").strip().lower()
            if not c:
                return False
            if c == name_col_l:
                return True
            toks = _identifier_tokens(c)
            norm_toks = {tok.replace(" ", "_").lower() for tok in toks if tok}
            if norm_toks.intersection(name_component_token_hints):
                return True
            col_compact = re.sub(r"[^a-z0-9]", "", c)
            for hint in name_component_token_hints:
                h = re.sub(r"[^a-z0-9]", "", str(hint or "").lower())
                if len(h) >= 4 and h in col_compact:
                    return True
            if analyzer is not None:
                try:
                    role = str((analyzer._column_roles.get(t, {}) or {}).get(c, "")).strip().lower()
                except Exception:
                    role = ""
                if role == "name":
                    return True
                try:
                    syns = (analyzer._column_synonyms.get(f"{t}.{c}", []) or [])
                except Exception:
                    syns = []
                syn_blob = " ".join(str(x).lower() for x in syns)
                if any_phrase_in_text(syn_blob, name_component_synonym_hint_phrases):
                    return True
            return False

        name_component_cols = {c for c in table_cols if _is_name_component_column(c)}
        if not name_component_cols:
            name_component_cols = {name_col_l}

        display_name_col = _display_name_column_for_table(table) or ""
        display_name_col_l = display_name_col.lower() if display_name_col else ""

        def _column_original_case(col_name: str) -> str:
            c_l = str(col_name or "").strip().lower()
            if not c_l:
                return str(col_name or "")
            if analyzer is not None:
                try:
                    return str(analyzer._column_original_case.get(f"{t}.{c_l}", c_l))
                except Exception:
                    pass
            return c_l

        def _ordered_name_components(cols: Set[str]) -> List[str]:
            cols_l = {str(c).strip().lower() for c in cols if str(c).strip()}
            if not cols_l:
                return []

            col_order: Dict[str, int] = {}
            if analyzer is not None:
                try:
                    ordered_cols = [
                        str(c).strip("`").lower()
                        for c in analyzer.get_table_columns(t)
                        if str(c).strip()
                    ]
                except Exception:
                    ordered_cols = []
                col_order = {c: i for i, c in enumerate(ordered_cols)}

            first_hints = set(name_priority_groups.get("first", set()))
            middle_hints = set(name_priority_groups.get("middle", set()))
            last_hints = set(name_priority_groups.get("last", set()))
            generic_hints = set(name_priority_groups.get("generic", set()))

            def _name_priority(col_name: str) -> int:
                toks = _identifier_tokens(col_name)
                if _matches_name_token_hint(col_name, toks, first_hints):
                    return 0
                if _matches_name_token_hint(col_name, toks, middle_hints):
                    return 1
                if _matches_name_token_hint(col_name, toks, last_hints):
                    return 2
                if _matches_name_token_hint(col_name, toks, generic_hints):
                    return 3
                return 4

            return sorted(
                cols_l,
                key=lambda c: (_name_priority(c), col_order.get(c, 10_000), c),
            )

        composite_name_expr = ""
        composite_group_items: List[str] = []
        if not wants_split_name_components and not display_name_col and len(name_component_cols) >= 2:
            ordered_name_cols = _ordered_name_components(name_component_cols)
            if len(ordered_name_cols) >= 2:
                qualified_parts: List[str] = []
                for c in ordered_name_cols:
                    c_out = _column_original_case(c)
                    qualified = f"{qual}.{c_out}"
                    qualified_parts.append(qualified)
                    composite_group_items.append(qualified)
                concat_args: List[str] = []
                for idx_part, part in enumerate(qualified_parts):
                    if idx_part:
                        concat_args.append("' '")
                    concat_args.append(part)
                composite_alias = f"{singular}_name" if singular else "entity_name"
                composite_name_expr = f"CONCAT({', '.join(concat_args)}) AS {composite_alias}"

        accepted_quals = {x.lower() for x in aliases}
        accepted_quals.add(t)

        def _entity_expr_refs(expr: str) -> Set[str]:
            e = str(expr or "")
            if not e:
                return set()
            refs: Set[str] = set()
            qual_refs = list(
                re.finditer(
                    r"(?is)\b`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\b",
                    e,
                )
            )
            for m_ref in qual_refs:
                a_l = m_ref.group(1).lower()
                c_l = m_ref.group(2).lower()
                if a_l in accepted_quals:
                    refs.add(c_l)
            if refs:
                return refs
            # Fallback for unqualified expressions on single-entity projections.
            if not qual_refs and table_cols:
                toks = {tok.lower() for tok in re.findall(r"[A-Za-z_][A-Za-z0-9_]*", e)}
                refs = {tok for tok in toks if tok in table_cols}
            return refs

        has_id = any(
            c == id_col_l and (qf is None or qf == qual_l or qf == t)
            for qf, c in selected_cols
        )
        effective_name_col_l = display_name_col_l or ("" if composite_name_expr else name_col_l)
        has_name_simple = bool(effective_name_col_l) and any(
            c == effective_name_col_l and (qf is None or qf == qual_l or qf == t)
            for qf, c in selected_cols
        )
        has_name_alias = any(a in table_name_aliases for a in selected_aliases)
        def _is_composite_name_expression(expr: str) -> bool:
            e = str(expr or "")
            if not e:
                return False
            # Composite-name expressions are usually string concatenations.
            if not (re.search(r"(?is)\bconcat\s*\(", e) or "||" in e):
                return False
            refs = _entity_expr_refs(e)
            if len(refs) < 2:
                return False
            name_refs = refs.intersection(name_component_cols)
            if len(name_refs) >= 2:
                return True
            # Fallback: treat as name-like when it combines >=2 entity columns
            # and includes the canonical name column.
            return name_col_l in refs and len(refs) >= 2

        has_composite_name_expr = any(_is_composite_name_expression(expr) for expr in selected_exprs)
        has_name = has_name_simple or has_name_alias or has_composite_name_expr

        if not has_id:
            prepended_cols.append(f"{qual}.{id_col}")
            selected_cols.append((qual_l, id_col_l))
            changed = True

        if not has_name:
            if composite_name_expr:
                prepended_cols.append(composite_name_expr)
            else:
                target_name_col = display_name_col or name_col
                prepended_cols.append(f"{qual}.{target_name_col}")
                selected_cols.append((qual_l, str(target_name_col).lower()))
            changed = True

        # For grouped queries, ensure GROUP BY contains missing non-aggregate cols.
        if group_items:
            need_g_id = not any(
                c == id_col_l and (qf is None or qf == qual_l or qf == t)
                for qf, c in grouped_cols
            )
            # If name is already satisfied via alias/expression (e.g., employee_name/CONCAT),
            # do not force-add raw name column to GROUP BY.
            if has_name_simple:
                need_g_name = not any(
                    c == name_col_l and (qf is None or qf == qual_l or qf == t)
                    for qf, c in grouped_cols
                )
            else:
                need_g_name = False
            if need_g_id:
                group_items.append(f"{qual}.{id_col}")
                grouped_cols.add((qual_l, id_col_l))
                changed = True
            if need_g_name:
                target_name_col = display_name_col or name_col
                group_items.append(f"{qual}.{target_name_col}")
                grouped_cols.add((qual_l, str(target_name_col).lower()))
                changed = True
            if composite_name_expr and not has_name:
                for group_item in composite_group_items:
                    parsed_group = _parse_simple_col(group_item)
                    if parsed_group:
                        gqf, gc = parsed_group
                        key = (gqf.lower() if gqf else None, gc.lower())
                        if key in grouped_cols:
                            continue
                        grouped_cols.add(key)
                    if group_item.strip().lower() in {g.strip().lower() for g in group_items}:
                        continue
                    group_items.append(group_item)
                    changed = True

    if not changed:
        return sql

    # Preserve existing SELECT order; prepend only truly missing columns.
    new_select_items = prepended_cols + select_items
    # Deduplicate simple duplicates while preserving order.
    dedup_select: List[str] = []
    seen_sel = set()
    for it in new_select_items:
        k = it.strip().lower()
        if k in seen_sel:
            continue
        seen_sel.add(k)
        dedup_select.append(it.strip())

    # Deduplicate GROUP BY too.
    dedup_group: List[str] = []
    seen_grp = set()
    for g in group_items:
        k = g.strip().lower()
        if k in seen_grp:
            continue
        seen_grp.add(k)
        dedup_group.append(g.strip())

    out_lines = []
    out_lines.append("SELECT " + ", ".join(dedup_select))
    out_lines.append("FROM " + from_core)
    if parsed.get("where"):
        out_lines.append(parsed["where"].strip())
    out_lines.append("GROUP BY " + ", ".join(dedup_group))
    if parsed.get("having"):
        out_lines.append("HAVING " + parsed["having"].strip())
    if parsed.get("tail"):
        out_lines.append(parsed["tail"].strip())

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _choose_preferred_description_column(
    base_table: str,
    columns: List[str],
    question: str,
    requested_segment: str = "",
    analyzer: Any = None,
) -> Optional[str]:
    """
    Pick preferred description-like column with schema-driven scoring.

    Signals are derived from metadata JSONL via analyzer:
    - column name tokens
    - column synonyms
    - column description text
    - column role

    Preference policy:
    - if request implies markup/html, prefer markup-like description
    - if request implies text/plain, prefer plain text-like description
    - if request is generic "description", default to non-markup text
    """
    table_l = str(base_table or "").strip().lower()
    q = str(question or "").strip().lower()
    seg = str(requested_segment or "").strip().lower()
    if not table_l or not columns:
        return None
    if not q and not seg:
        return None

    def _tokens(text: str) -> Set[str]:
        raw = str(text or "").strip()
        if not raw:
            return set()
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ").lower()
        return {tok for tok in re.findall(r"[a-z0-9]+", raw) if tok}

    desc_hint_pat = re.compile(r"\b(?:description|descriptions|detail|details|desc)\b", flags=re.I)
    source_text = seg if (seg and desc_hint_pat.search(seg)) else q
    request_tokens = _tokens(source_text or q)
    if not request_tokens:
        return None

    stop_tokens = {
        "the", "a", "an", "and", "or", "to", "of", "for", "with", "by", "from",
        "show", "list", "return", "display", "get", "find", "include", "including",
        "where", "which", "that", "whose", "is", "are", "was", "were", "be",
        "missing", "null", "empty", "not", "only", "all",
    }
    request_tokens = {t for t in request_tokens if t and t not in stop_tokens}
    if not request_tokens:
        return None

    desc_terms = {"description", "descriptions", "detail", "details", "desc", "info", "information"}
    markup_terms = {"html", "xml", "xhtml", "markup", "web", "richtext", "tag"}
    plain_terms = {"text", "plain", "plaintext", "raw", "readable"}

    asks_desc = bool(request_tokens & desc_terms)
    wants_markup = bool(request_tokens & markup_terms)
    wants_plain = bool(request_tokens & plain_terms)
    if not (asks_desc or wants_markup or wants_plain):
        return None

    # If output segment explicitly asks both variants, avoid forcing one.
    if seg and wants_markup and wants_plain:
        return None

    request_variant_tokens = request_tokens - desc_terms
    candidates: List[Tuple[int, int, str]] = []
    for idx, col in enumerate(columns):
        col_raw = str(col or "").strip("`")
        col_l = col_raw.lower()
        if not col_l:
            continue

        tokens = set(_tokens(col_raw))
        if analyzer is not None:
            try:
                for syn in analyzer.get_column_synonyms(table_l, col_l) or []:
                    tokens.update(_tokens(str(syn or "")))
            except Exception:
                pass

            try:
                desc_txt = str(analyzer.get_column_description(table_l, col_l) or "").strip()
                if desc_txt:
                    tokens.update(_tokens(desc_txt))
            except Exception:
                pass
        else:
            try:
                desc_txt = str(get_column_description(table_l, col_l) or "").strip()
                if desc_txt:
                    tokens.update(_tokens(desc_txt))
            except Exception:
                pass

        try:
            role_l = str(get_column_role(table_l, col_l) or "").strip().lower()
        except Exception:
            role_l = ""
        if role_l:
            tokens.update(_tokens(role_l))

        has_desc_signal = (
            any(tok.startswith("descript") for tok in tokens)
            or any(tok in {"detail", "details"} for tok in tokens)
            or ("description" in col_l)
            or (role_l in {"description", "text"})
        )
        if not has_desc_signal:
            continue

        is_markup = bool(tokens & markup_terms)
        is_plain = bool(tokens & plain_terms) or role_l == "text"
        variant_overlap = len(request_variant_tokens & tokens)

        score = 0
        score += 100 * variant_overlap
        if has_desc_signal:
            score += 20
        if asks_desc:
            if is_plain:
                score += 8
            if not is_markup:
                score += 4
            if is_markup:
                score -= 4
        if wants_markup and not wants_plain:
            if is_markup:
                score += 40
            if is_plain:
                score -= 6
        if wants_plain and not wants_markup:
            if is_plain:
                score += 40
            if is_markup:
                score -= 8
        if _tokens(col_raw) & request_tokens:
            score += 5

        candidates.append((score, -idx, col_raw))

    if not candidates:
        return None

    candidates.sort(reverse=True)
    return candidates[0][2]


def _ensure_explicit_simple_projection_columns(sql: str, question: str, ctx: str = "") -> str:
    """
    For flat single-table lookup/list queries, preserve explicitly requested
    output columns from question phrasing like:
      - "with customer number, check number, and amount"
      - "including order number and order date"

    This is intentionally narrow:
    - single table only
    - no JOIN / GROUP BY / HAVING / UNION / window functions / subqueries
    - only columns from the base table
    """
    if not sql or not question:
        return sql

    s = str(sql or "").strip().rstrip(";").strip()
    q = str(question or "").strip().lower()
    if not s or not q:
        return sql

    if re.search(r"\b(?:join|group\s+by|having|union|intersect|except|with)\b", s, flags=re.I):
        return sql
    # Window queries have their own projection-shape repairs. Letting this
    # flat lookup helper run on OVER(...) queries can leak partition/group
    # columns like productLine into the final SELECT even when the question
    # only requests the base row columns plus the derived window metric.
    if re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql
    if re.search(r"\b(?:row_number|rank|dense_rank)\s*\(", s, flags=re.I):
        return sql
    if (
        re.search(r"\b(?:from|exists)\s*\(", s, flags=re.I)
        or re.search(r"\bin\s*\(\s*select\b", s, flags=re.I)
    ):
        return sql

    m_sel = re.match(
        r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<from>.+?)"
        r"(?:\s+WHERE\s+(?P<where>.+?))?"
        r"(?:\s+ORDER\s+BY\s+(?P<order>.+?))?"
        r"(?:\s+LIMIT\s+(?P<limit>.+?))?\s*$",
        s,
    )
    if not m_sel:
        return sql

    select_part = (m_sel.group("select") or "").strip()
    from_core = (m_sel.group("from") or "").strip()
    where_part = (m_sel.group("where") or "").strip()
    order_part = (m_sel.group("order") or "").strip()
    limit_part = (m_sel.group("limit") or "").strip()
    if not select_part or not from_core:
        return sql

    has_select_distinct = bool(re.match(r"(?is)^DISTINCT\b", select_part))
    if has_select_distinct:
        select_part = re.sub(r"(?is)^DISTINCT\s+", "", select_part, count=1).strip()
    if not select_part:
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    unique_tables = sorted(
        {
            str(t or "").strip().lower()
            for a, t in alias_to_table.items()
            if a and a.lower() == a and t
        }
    )
    if not unique_tables:
        m_base = re.match(
            r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?\s*$",
            from_core,
        )
        if not m_base:
            return sql
        base_table = str(m_base.group(1) or "").strip().lower()
        base_alias = str(m_base.group(2) or "").strip() or base_table
        alias_to_table = {base_alias: base_table, base_alias.lower(): base_table}
        unique_tables = [base_table]
    if len(unique_tables) != 1:
        return sql

    base_table = unique_tables[0]
    base_alias = next(
        (
            a for a, t in alias_to_table.items()
            if a and a.lower() == a and str(t or "").strip().lower() == base_table
        ),
        base_table,
    )

    allowed_identifiers = _parse_allowed_identifiers(ctx)
    allowed_table_cols = [
        str(c).strip("`")
        for c in allowed_identifiers.get(base_table, set())
        if str(c).strip()
    ]

    analyzer = None
    table_cols: List[str] = []
    try:
        analyzer = get_schema_analyzer()
        table_cols = [
            str(c).strip("`")
            for c in analyzer.get_table_columns(base_table)
            if str(c).strip()
        ]
    except Exception:
        try:
            analyzer = get_schema_analyzer()
            table_cols = [
                str(c).strip("`")
                for c in analyzer.get_table_columns(base_table)
                if str(c).strip()
            ]
        except Exception:
            analyzer = None
            table_cols = []

    merged_cols: List[str] = []
    seen_cols: Set[str] = set()
    for col in table_cols + allowed_table_cols:
        raw = str(col).strip("`")
        if not raw:
            continue
        low = raw.lower()
        if low in seen_cols:
            continue
        seen_cols.add(low)
        merged_cols.append(raw)
    table_cols = merged_cols
    if not table_cols:
        return sql

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_simple_col(expr: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _identifier_parts(text: str) -> List[str]:
        raw = str(text or "").strip()
        if not raw:
            return []
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ")
        raw = raw.lower()
        return [tok for tok in re.findall(r"[a-z0-9]+", raw)]

    def _identifier_variants(parts: List[str]) -> Set[str]:
        if not parts:
            return set()
        variants: Set[str] = {" ".join(parts)}
        suffix_terms = {str(x or "").strip().lower() for x in identifier_id_like_terms() if str(x or "").strip()}
        if parts[-1] in suffix_terms and len(parts) >= 2:
            prefix = parts[:-1]
            for suffix in sorted(suffix_terms):
                variants.add(" ".join(prefix + [suffix]))
        return {v.strip() for v in variants if v.strip()}

    def _column_original_case(col_name: str) -> str:
        c_l = str(col_name or "").strip().lower()
        if not c_l:
            return str(col_name or "")
        if analyzer is not None:
            try:
                return str(analyzer._column_original_case.get(f"{base_table}.{c_l}", c_l))
            except Exception:
                pass
        return c_l

    requested_segment = _extract_requested_output_segment(q)
    if not requested_segment:
        return sql
    preferred_desc_col = _choose_preferred_description_column(
        base_table=base_table,
        columns=table_cols,
        question=q,
        requested_segment=requested_segment,
        analyzer=analyzer,
    )
    preferred_desc_l = str(preferred_desc_col or "").strip().lower()

    def _column_phrase_candidates(col_name: str) -> Set[str]:
        col_l = str(col_name or "").strip().lower()
        if not col_l:
            return set()
        parts = _identifier_parts(_column_original_case(col_l))
        phrases: Set[str] = set(_identifier_variants(parts))
        if analyzer is not None:
            try:
                for syn in analyzer.get_column_synonyms(base_table, col_l) or []:
                    syn_parts = _identifier_parts(str(syn or ""))
                    if syn_parts:
                        phrases.add(" ".join(syn_parts))
            except Exception:
                pass
        if preferred_desc_l and col_l == preferred_desc_l:
            phrases.update({"description", "details"})
        return {p.strip() for p in phrases if p and p.strip()}

    select_items = _split_top_level_commas(select_part)
    if not select_items:
        return sql

    selected_cols: Set[str] = set()
    select_item_analysis: List[Tuple[str, Optional[str], Set[str]]] = []
    prefer_qualified = False
    for item in select_items:
        expr, out_alias = _split_expr_alias(item)
        item_simple_col: Optional[str] = None
        parsed_col = _parse_simple_col(expr)
        if parsed_col:
            qual, col = parsed_col
            qual_l = str(qual or "").strip().lower()
            col_l = str(col or "").strip().lower()
            if not qual_l or qual_l == base_alias.lower() or qual_l == base_table:
                selected_cols.add(col_l)
                item_simple_col = col_l
                prefer_qualified = prefer_qualified or bool(qual_l)
        alias_label = str(out_alias or "").strip("`'\"")
        alias_tokens = set(_identifier_parts(alias_label)) if alias_label else set()
        select_item_analysis.append((item.strip(), item_simple_col, alias_tokens))

    def _alias_tokens_cover(alias_tokens: Set[str], parts: List[str]) -> bool:
        if not parts or not alias_tokens:
            return False
        part_set = set(parts)
        identifier_terms = {str(x or "").strip().lower() for x in identifier_id_like_terms() if str(x or "").strip()}

        def _equiv(a: str, b: str) -> bool:
            a0 = str(a or "").strip().lower()
            b0 = str(b or "").strip().lower()
            if not a0 or not b0:
                return False
            if a0 == b0:
                return True
            if a0 in identifier_terms and b0 in identifier_terms:
                return True
            short, long = (a0, b0) if len(a0) <= len(b0) else (b0, a0)
            return len(short) >= 3 and len(long) >= 5 and long.startswith(short)

        return all(any(_equiv(req, tok) for tok in alias_tokens) for req in part_set)

    def _alias_covers(parts: List[str]) -> bool:
        if not parts:
            return False
        return any(_alias_tokens_cover(alias_tokens, parts) for _, _, alias_tokens in select_item_analysis)

    requested_cols: List[Tuple[int, str]] = []
    segment_generic_tokens = {
        "id", "ids", "code", "codes", "number", "numbers",
        "name", "names", "date", "dates", "time", "times",
        "status", "statuses", "type", "types", "value", "values",
    }
    for col in table_cols:
        col_l = str(col or "").strip().lower()
        if not col_l:
            continue
        parts = _identifier_parts(_column_original_case(col_l))
        if not parts:
            continue
        best_pos: Optional[int] = None
        for phrase in _column_phrase_candidates(col_l):
            phrase_regex = re.escape(phrase).replace(r"\ ", r"\s+")
            phrase_pat = re.compile(rf"\b{phrase_regex}\b", flags=re.I)
            m_phrase = phrase_pat.search(requested_segment)
            if m_phrase:
                pos = m_phrase.start()
                if best_pos is None or pos < best_pos:
                    best_pos = pos
        # Fallback: coordinated/plural phrasing such as
        # "first and last names" should still map to firstName/lastName.
        if best_pos is None and parts:
            token_pos: List[int] = []
            has_specific_token = False
            cursor = 0
            prev_end = 0
            matched = True
            for p in parts:
                p_l = str(p or "").strip().lower()
                if not p_l:
                    matched = False
                    break
                m_tok = re.search(
                    rf"\b{re.escape(p_l)}(?:s|es)?\b",
                    requested_segment[cursor:],
                    flags=re.I,
                )
                if not m_tok:
                    matched = False
                    break
                abs_start = cursor + m_tok.start()
                abs_end = cursor + m_tok.end()

                if token_pos:
                    gap = requested_segment[prev_end:abs_start]
                    # Keep coordinated close phrases ("first and last names"),
                    # but reject cross-item matches that jump across commas.
                    if len(gap) > 20 or re.search(r"[,;:.]", gap):
                        matched = False
                        break

                token_pos.append(abs_start)
                if p_l not in segment_generic_tokens:
                    has_specific_token = True
                cursor = abs_end
                prev_end = abs_end

            if matched and token_pos and has_specific_token:
                best_pos = min(token_pos)
        if best_pos is not None:
            requested_cols.append((best_pos, col_l))

    # Even when other columns already match (e.g., productLine), keep a requested
    # generic/explicit description projection by mapping to preferred variant.
    if preferred_desc_l:
        mentions_desc = bool(
            re.search(r"\b(?:description|descriptions|detail|details)\b", requested_segment, flags=re.I)
        )
        if mentions_desc and not any(col_l == preferred_desc_l for _, col_l in requested_cols):
            m_desc = re.search(r"\b(?:text|html)?\s*(?:description|descriptions|detail|details)\b", requested_segment, flags=re.I)
            desc_pos = m_desc.start() if m_desc else max(0, len(requested_segment) - 1)
            requested_cols.append((desc_pos, preferred_desc_l))

    if not requested_cols:
        return sql

    requested_cols.sort(key=lambda x: (x[0], x[1]))
    requested_parts_by_col: Dict[str, List[str]] = {}
    missing_cols: List[str] = []
    seen_missing: Set[str] = set()
    for _, col_l in requested_cols:
        parts = _identifier_parts(_column_original_case(col_l))
        requested_parts_by_col[col_l] = parts
        if col_l in selected_cols or _alias_covers(parts):
            continue
        if col_l in seen_missing:
            continue
        seen_missing.add(col_l)
        missing_cols.append(col_l)

    if not missing_cols:
        return sql

    used_item_indexes: Set[int] = set()
    ordered_select_items: List[str] = []
    for _, col_l in requested_cols:
        parts = requested_parts_by_col.get(col_l) or _identifier_parts(_column_original_case(col_l))
        matched_index: Optional[int] = None
        for idx, (item_text, item_simple_col, alias_tokens) in enumerate(select_item_analysis):
            if idx in used_item_indexes:
                continue
            if item_simple_col == col_l or _alias_tokens_cover(alias_tokens, parts):
                matched_index = idx
                break
        if matched_index is not None:
            used_item_indexes.add(matched_index)
            ordered_select_items.append(select_item_analysis[matched_index][0])
            continue
        col_out = _column_original_case(col_l)
        ordered_select_items.append(f"{base_alias}.{col_out}" if prefer_qualified else col_out)

    for idx, (item_text, _, _) in enumerate(select_item_analysis):
        if idx in used_item_indexes:
            continue
        ordered_select_items.append(item_text)

    def _select_item_semantic_key(item: str) -> str:
        raw_item = str(item or "").strip()
        if not raw_item:
            return ""

        expr_part, out_alias = _split_expr_alias(raw_item)
        parsed_simple = _parse_simple_col(expr_part)
        if parsed_simple:
            _, col = parsed_simple
            return str(col or "").strip().lower()

        alias_label = str(out_alias or "").strip("`'\"")
        alias_parts = _identifier_parts(alias_label)
        alias_parts = [p for p in alias_parts if p not in {"the", "a", "an"}]
        if alias_parts:
            return "".join(alias_parts)

        bare_label = str(expr_part or "").strip().strip("`'\"")
        bare_parts = _identifier_parts(bare_label)
        bare_parts = [p for p in bare_parts if p not in {"the", "a", "an"}]
        if bare_parts:
            return "".join(bare_parts)

        return raw_item.lower()

    new_select_items = ordered_select_items
    dedup_select: List[str] = []
    seen_keys: Set[str] = set()
    for item in new_select_items:
        raw_key = item.strip().lower()
        semantic_key = _select_item_semantic_key(item)
        key = semantic_key or raw_key
        if key in seen_keys or raw_key in seen_keys:
            continue
        seen_keys.add(key)
        seen_keys.add(raw_key)
        dedup_select.append(item.strip())

    select_keyword = "SELECT DISTINCT" if has_select_distinct else "SELECT"
    out_lines = [f"{select_keyword} {', '.join(dedup_select)}", f"FROM {from_core}"]
    if where_part:
        out_lines.append(f"WHERE {where_part}")
    if order_part:
        out_lines.append(f"ORDER BY {order_part}")
    if limit_part:
        out_lines.append(f"LIMIT {limit_part}")

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _repair_misplaced_select_distinct(sql: str) -> str:
    """
    Repair malformed SELECT lists where DISTINCT appears mid-projection, e.g.:
      SELECT a, b, DISTINCT c, d FROM t
    -> SELECT DISTINCT a, b, c, d FROM t

    Conservative scope:
    - top-level single SELECT only
    - no UNION/INTERSECT/EXCEPT
    - only rewrites top-level projection items
    """
    s = str(sql or "").strip()
    if not s:
        return sql
    if re.search(r"\b(?:UNION|INTERSECT|EXCEPT)\b", s, flags=re.I):
        return sql

    m = re.match(
        r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<tail>.+?)\s*;?\s*$",
        s,
    )
    if not m:
        return sql

    select_part = str(m.group("select") or "").strip()
    tail_part = str(m.group("tail") or "").strip()
    if not select_part or not tail_part:
        return sql
    if re.match(r"(?is)^DISTINCT\b", select_part):
        return sql
    if not re.search(r"(?is)(?:^|,)\s*DISTINCT\b", select_part):
        return sql

    items = [item.strip() for item in _split_top_level_commas(select_part) if item.strip()]
    if not items:
        return sql

    saw_distinct = False
    repaired_items: List[str] = []
    for item in items:
        if re.match(r"(?is)^DISTINCT\b", item):
            item = re.sub(r"(?is)^DISTINCT\s+", "", item).strip()
            saw_distinct = True
        if item:
            repaired_items.append(item)

    if not saw_distinct or not repaired_items:
        return sql

    dedup_items: List[str] = []
    seen: Set[str] = set()
    for item in repaired_items:
        key = item.strip().lower()
        if key in seen:
            continue
        seen.add(key)
        dedup_items.append(item.strip())

    fixed = f"SELECT DISTINCT {', '.join(dedup_items)} FROM {tail_part}"
    if str(sql).strip().endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_missing_filter_columns(sql: str, question: str, ctx: str = "") -> str:
    """
    For flat single-table lookup queries, drop columns from SELECT when they are
    used only as missing/null filter predicates and are not explicitly requested
    in the output.

    Example:
      SELECT productLine, textDescription, htmlDescription
      FROM productlines
      WHERE (htmlDescription IS NULL OR htmlDescription = '')
    -> drop htmlDescription from SELECT when the question only asks for
       "product line name and text description".
    """
    if not sql or not question:
        return sql

    s = str(sql or "").strip().rstrip(";").strip()
    q = str(question or "").strip().lower()
    if not s or not q:
        return sql

    if re.search(r"\b(?:join|group\s+by|having|union|intersect|except|with)\b", s, flags=re.I):
        return sql
    # Window queries have dedicated shape/contract repairs elsewhere.
    # Treating window SELECTs as flat lookup projections can incorrectly drop
    # requested base columns merely because they also appear in a NULL filter.
    if re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql
    if re.search(r"\b(?:row_number|rank|dense_rank)\s*\(", s, flags=re.I):
        return sql
    if (
        re.search(r"\b(?:from|exists)\s*\(", s, flags=re.I)
        or re.search(r"\bin\s*\(\s*select\b", s, flags=re.I)
    ):
        return sql

    m_sel = re.match(
        r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<from>.+?)"
        r"(?:\s+WHERE\s+(?P<where>.+?))?"
        r"(?:\s+ORDER\s+BY\s+(?P<order>.+?))?"
        r"(?:\s+LIMIT\s+(?P<limit>.+?))?\s*$",
        s,
    )
    if not m_sel:
        return sql

    select_part = (m_sel.group("select") or "").strip()
    from_core = (m_sel.group("from") or "").strip()
    where_part = (m_sel.group("where") or "").strip()
    order_part = (m_sel.group("order") or "").strip()
    limit_part = (m_sel.group("limit") or "").strip()
    if not select_part or not from_core or not where_part:
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    unique_tables = sorted(
        {
            str(t or "").strip().lower()
            for a, t in alias_to_table.items()
            if a and a.lower() == a and t
        }
    )
    if not unique_tables:
        m_base = re.match(
            r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?\s*$",
            from_core,
        )
        if not m_base:
            return sql
        base_table = str(m_base.group(1) or "").strip().lower()
        base_alias = str(m_base.group(2) or "").strip() or base_table
        alias_to_table = {base_alias: base_table, base_alias.lower(): base_table}
        unique_tables = [base_table]
    if len(unique_tables) != 1:
        return sql
    base_table = unique_tables[0]
    base_alias = next(
        (
            a for a, t in alias_to_table.items()
            if a and a.lower() == a and str(t or "").strip().lower() == base_table
        ),
        base_table,
    )

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_simple_col(expr: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _identifier_parts(text: str) -> List[str]:
        raw = str(text or "").strip()
        if not raw:
            return []
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ")
        raw = raw.lower()
        return [tok for tok in re.findall(r"[a-z0-9]+", raw)]

    requested_segment = _extract_requested_output_segment(q)

    def _question_explicitly_requests_column(col_name: str) -> bool:
        seg = str(requested_segment or "").strip().lower()
        if not seg:
            return False
        clean = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_name or ""))
        clean = clean.replace("_", " ").lower().strip()
        if not clean:
            return False

        phrase_candidates: List[str] = []
        phrase_candidates.append(clean)
        compact = re.sub(r"\s+", "", clean)
        # Heuristic split for already-lowercased concatenations such as
        # "htmldescription" / "textdescription".
        suffixes = ["description", "name", "number", "date", "amount", "price", "code", "id"]
        for suffix in suffixes:
            if compact.endswith(suffix) and len(compact) > len(suffix):
                prefix = compact[: -len(suffix)].strip()
                if prefix:
                    phrase_candidates.append(f"{prefix} {suffix}")
        # Deduplicate while preserving order.
        dedup_phrase_candidates: List[str] = []
        seen_phrases: Set[str] = set()
        for phr in phrase_candidates:
            p = str(phr or "").strip()
            if not p or p in seen_phrases:
                continue
            seen_phrases.add(p)
            dedup_phrase_candidates.append(p)

        schema_phrase_candidates: List[str] = []
        try:
            for variant in get_column_entity_variants(base_table, col_name) or set():
                phrase = re.sub(r"\s+", " ", str(variant or "").replace("_", " ").strip().lower())
                if phrase:
                    schema_phrase_candidates.append(phrase)
        except Exception:
            pass
        try:
            analyzer = get_schema_analyzer()
        except Exception:
            analyzer = None
        if analyzer is not None:
            try:
                for syn in analyzer.get_column_synonyms(base_table, col_name) or []:
                    phrase = re.sub(r"\s+", " ", str(syn or "").replace("_", " ").strip().lower())
                    if phrase:
                        schema_phrase_candidates.append(phrase)
            except Exception:
                pass
        try:
            desc = str(get_column_description(base_table, col_name) or "").strip()
        except Exception:
            desc = ""
        if desc:
            for raw_part in re.split(r"[;,.()]+", desc):
                phrase = re.sub(
                    r"\s+",
                    " ",
                    re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(raw_part or "").replace("_", " ")).strip().lower(),
                )
                if not phrase:
                    continue
                schema_phrase_candidates.append(phrase)
                toks = [tok for tok in phrase.split() if tok]
                if len(toks) >= 3:
                    for start in range(1, len(toks) - 1):
                        tail = " ".join(toks[start:])
                        if len(tail.split()) >= 3:
                            schema_phrase_candidates.append(tail)
        for phr in schema_phrase_candidates:
            p = str(phr or "").strip()
            if not p or p in seen_phrases:
                continue
            seen_phrases.add(p)
            dedup_phrase_candidates.append(p)

        condition_before = re.compile(
            r"\b(?:with|where|having|who|that|whose|average|avg|mean|overall|global)\s*$",
            flags=re.I,
        )
        condition_after = re.compile(
            r"^\s*(?:"
            r"greater(?:\s+than)?|less(?:\s+than)?|higher(?:\s+than)?|lower(?:\s+than)?|"
            r"above|below|over|under|between|before|after|than|"
            r"equal(?:s|(?:\s+to)?)|not\s+null|is\s+null|is\s+not\s+null|"
            r"like|regexp|matches?|matching|condition\b"
            r")",
            flags=re.I,
        )
        for phr in dedup_phrase_candidates:
            clean_pat = re.escape(phr).replace(r"\ ", r"\s+")
            for m in re.finditer(rf"\b(?:the\s+)?{clean_pat}\b", seg, flags=re.I):
                before = seg[max(0, m.start() - 24):m.start()]
                after = seg[m.end():m.end() + 48]
                if condition_before.search(before) or condition_after.search(after):
                    continue
                return True
        return False

    missing_filter_cols: Set[str] = set()
    for m in re.finditer(
        r"(?is)(?:^|[\s(])(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s+IS\s+NULL\b",
        where_part,
    ):
        qual = str(m.group(1) or "").strip().lower()
        col = str(m.group(2) or "").strip().lower()
        if not col:
            continue
        if qual and qual not in {base_alias.lower(), base_table}:
            continue
        missing_filter_cols.add(col)
    for m in re.finditer(
        r"""(?is)(?:^|[\s(])(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*(['"])\s*\3""",
        where_part,
    ):
        qual = str(m.group(1) or "").strip().lower()
        col = str(m.group(2) or "").strip().lower()
        if not col:
            continue
        if qual and qual not in {base_alias.lower(), base_table}:
            continue
        missing_filter_cols.add(col)

    if not missing_filter_cols:
        return sql

    select_items = _split_top_level_commas(select_part)
    if not select_items:
        return sql

    kept_items: List[str] = []
    changed = False
    for item in select_items:
        expr, _ = _split_expr_alias(item)
        parsed = _parse_simple_col(expr)
        if not parsed:
            kept_items.append(item.strip())
            continue
        qual, col = parsed
        qual_l = str(qual or "").strip().lower()
        col_l = str(col or "").strip().lower()
        if qual_l and qual_l not in {base_alias.lower(), base_table}:
            kept_items.append(item.strip())
            continue
        if col_l in missing_filter_cols and not _question_explicitly_requests_column(col_l):
            changed = True
            continue
        kept_items.append(item.strip())

    if not changed or not kept_items:
        return sql

    out_lines = [f"SELECT {', '.join(kept_items)}", f"FROM {from_core}"]
    if where_part:
        out_lines.append(f"WHERE {where_part}")
    if order_part:
        out_lines.append(f"ORDER BY {order_part}")
    if limit_part:
        out_lines.append(f"LIMIT {limit_part}")

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_difference_operand_columns(sql: str, question: str, ctx: str = "") -> str:
    """
    For flat single-table lookup projections, drop raw operand columns when
    question asks for a computed difference and SELECT already contains X - Y.

    Conservative behavior:
    - no JOIN/GROUP/WINDOW/subquery/set-op SQL
    - only simple base-table column projections are dropped
    - keep operands if mentioned outside "difference between ..." span
    """
    if not sql or not question:
        return sql

    s = str(sql or "").strip().rstrip(";").strip()
    q = str(question or "").strip().lower()
    if not s or not q:
        return sql

    if not re.search(r"\b(?:difference\s+between|difference\s+of|minus|selisih)\b", q, flags=re.I):
        return sql
    if re.search(r"\b(?:join|group\s+by|having|union|intersect|except|with)\b", s, flags=re.I):
        return sql
    if re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql
    if re.search(r"\b(?:row_number|rank|dense_rank)\s*\(", s, flags=re.I):
        return sql
    if (
        re.search(r"\b(?:from|exists)\s*\(", s, flags=re.I)
        or re.search(r"\bin\s*\(\s*select\b", s, flags=re.I)
    ):
        return sql

    m_sel = re.match(
        r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<from>.+?)"
        r"(?:\s+WHERE\s+(?P<where>.+?))?"
        r"(?:\s+ORDER\s+BY\s+(?P<order>.+?))?"
        r"(?:\s+LIMIT\s+(?P<limit>.+?))?\s*$",
        s,
    )
    if not m_sel:
        return sql

    select_part = (m_sel.group("select") or "").strip()
    from_core = (m_sel.group("from") or "").strip()
    where_part = (m_sel.group("where") or "").strip()
    order_part = (m_sel.group("order") or "").strip()
    limit_part = (m_sel.group("limit") or "").strip()
    if not select_part or not from_core:
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    unique_tables = sorted(
        {
            str(t or "").strip().lower()
            for a, t in alias_to_table.items()
            if a and a.lower() == a and t
        }
    )
    if not unique_tables:
        m_base = re.match(
            r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?\s*$",
            from_core,
        )
        if not m_base:
            return sql
        base_table = str(m_base.group(1) or "").strip().lower()
        base_alias = str(m_base.group(2) or "").strip() or base_table
        alias_to_table = {base_alias: base_table, base_alias.lower(): base_table}
        unique_tables = [base_table]
    if len(unique_tables) != 1:
        return sql
    base_table = unique_tables[0]
    base_alias = next(
        (
            a for a, t in alias_to_table.items()
            if a and a.lower() == a and str(t or "").strip().lower() == base_table
        ),
        base_table,
    )

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_simple_col(expr: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _identifier_parts(text: str) -> List[str]:
        raw = str(text or "").strip()
        if not raw:
            return []
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ").lower()
        return [tok for tok in re.findall(r"[a-z0-9]+", raw)]

    diff_spans: List[Tuple[int, int]] = []
    for m in re.finditer(r"\bdifference\s+between\b", q, flags=re.I):
        tail = q[m.end():]
        stop = re.search(r"[.;!?]", tail)
        end = m.end() + (stop.start() if stop else min(len(tail), 160))
        diff_spans.append((m.start(), end))

    def _col_mentioned_outside_difference(col_name: str) -> bool:
        parts = _identifier_parts(col_name)
        if not parts:
            return False
        phrase = re.escape(" ".join(parts)).replace(r"\ ", r"\s+")
        for hit in re.finditer(rf"\b{phrase}\b", q, flags=re.I):
            pos = hit.start()
            inside_diff = any(lo <= pos <= hi for lo, hi in diff_spans)
            if not inside_diff:
                return True
        return False

    select_items = _split_top_level_commas(select_part)
    if not select_items:
        return sql

    operand_cols: Set[str] = set()
    sub_expr_pat = re.compile(
        r"(?is)^\s*"
        r"(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?"
        r"\s*-\s*"
        r"(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?"
        r"\s*$"
    )
    for item in select_items:
        expr, _ = _split_expr_alias(item)
        expr_core = str(expr or "").strip()
        while expr_core.startswith("(") and expr_core.endswith(")"):
            inner = expr_core[1:-1].strip()
            if not inner:
                break
            expr_core = inner
        m_sub = sub_expr_pat.match(expr_core)
        if not m_sub:
            continue
        q1 = str(m_sub.group(1) or "").strip().lower()
        c1 = str(m_sub.group(2) or "").strip().lower()
        q2 = str(m_sub.group(3) or "").strip().lower()
        c2 = str(m_sub.group(4) or "").strip().lower()
        if q1 and q1 not in {base_alias.lower(), base_table}:
            continue
        if q2 and q2 not in {base_alias.lower(), base_table}:
            continue
        if c1:
            operand_cols.add(c1)
        if c2:
            operand_cols.add(c2)

    if not operand_cols:
        return sql

    drop_cols = {c for c in operand_cols if not _col_mentioned_outside_difference(c)}
    if not drop_cols:
        return sql

    kept_items: List[str] = []
    changed = False
    for item in select_items:
        expr, _ = _split_expr_alias(item)
        parsed = _parse_simple_col(expr)
        if not parsed:
            kept_items.append(item.strip())
            continue
        qual, col = parsed
        qual_l = str(qual or "").strip().lower()
        col_l = str(col or "").strip().lower()
        if qual_l and qual_l not in {base_alias.lower(), base_table}:
            kept_items.append(item.strip())
            continue
        if col_l in drop_cols:
            changed = True
            continue
        kept_items.append(item.strip())

    if not changed or not kept_items:
        return sql

    out_lines = [f"SELECT {', '.join(kept_items)}", f"FROM {from_core}"]
    if where_part:
        out_lines.append(f"WHERE {where_part}")
    if order_part:
        out_lines.append(f"ORDER BY {order_part}")
    if limit_part:
        out_lines.append(f"LIMIT {limit_part}")

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _align_requested_description_variant(sql: str, question: str, ctx: str = "") -> str:
    """
    Schema-driven alignment for description-like projection columns in simple
    single-table lookups.

    Rules:
    - explicit "text/plain description" -> prefer text-like description column
    - explicit "html description" -> prefer html-like description column
    - generic "description" -> default to non-html/text-like description
    - keep WHERE predicates intact (rewrite SELECT projection only)
    - append missing requested description column when projection asks for it
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql

    s = str(sql or "").strip().rstrip(";").strip()
    if not s:
        return sql
    if re.search(r"\b(?:join|group\s+by|having|union|intersect|except|with)\b", s, flags=re.I):
        return sql
    if re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql
    if (
        re.search(r"\b(?:from|exists)\s*\(", s, flags=re.I)
        or re.search(r"\bin\s*\(\s*select\b", s, flags=re.I)
    ):
        return sql

    m_sel = re.match(
        r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<from>.+?)"
        r"(?:\s+WHERE\s+(?P<where>.+?))?"
        r"(?:\s+ORDER\s+BY\s+(?P<order>.+?))?"
        r"(?:\s+LIMIT\s+(?P<limit>.+?))?\s*$",
        s,
    )
    if not m_sel:
        return sql

    select_part = (m_sel.group("select") or "").strip()
    from_core = (m_sel.group("from") or "").strip()
    where_part = (m_sel.group("where") or "").strip()
    order_part = (m_sel.group("order") or "").strip()
    limit_part = (m_sel.group("limit") or "").strip()
    if not select_part or not from_core:
        return sql

    has_select_distinct = bool(re.match(r"(?is)^DISTINCT\b", select_part))
    if has_select_distinct:
        select_part = re.sub(r"(?is)^DISTINCT\s+", "", select_part, count=1).strip()
    if not select_part:
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    unique_tables = sorted(
        {
            str(t or "").strip().lower()
            for a, t in alias_to_table.items()
            if a and a.lower() == a and t
        }
    )
    if not unique_tables:
        m_base = re.match(
            r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?\s*$",
            from_core,
        )
        if not m_base:
            return sql
        base_table = str(m_base.group(1) or "").strip().lower()
        base_alias = str(m_base.group(2) or "").strip() or base_table
        alias_to_table = {base_alias: base_table, base_alias.lower(): base_table}
    else:
        if len(unique_tables) != 1:
            return sql
        base_table = unique_tables[0]
        base_alias = next(
            (
                a for a, t in alias_to_table.items()
                if a and a.lower() == a and str(t or "").strip().lower() == base_table
            ),
            base_table,
        )

    requested_segment = _extract_requested_output_segment(q)
    if requested_segment and re.search(r"\b(?:description|descriptions|detail|details|desc)\b", requested_segment, flags=re.I):
        focus_text = requested_segment
    else:
        focus_text = q
    def _nl_tokens(text: str) -> Set[str]:
        raw = str(text or "").strip().lower()
        if not raw:
            return set()
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ")
        return {tok for tok in re.findall(r"[a-z0-9]+", raw) if tok}

    desc_terms = {"description", "descriptions", "detail", "details", "desc"}
    markup_terms = {"html", "xml", "xhtml", "markup", "web", "richtext", "tag"}
    plain_terms = {"text", "plain", "plaintext", "raw"}

    q_tokens = _nl_tokens(q)
    seg_tokens = _nl_tokens(requested_segment)
    focus_tokens = _nl_tokens(focus_text)

    full_wants_text_desc = bool((q_tokens & desc_terms) and (q_tokens & plain_terms))
    full_wants_html_desc = bool((q_tokens & desc_terms) and (q_tokens & markup_terms))
    out_wants_text_desc = bool(requested_segment and (seg_tokens & desc_terms) and (seg_tokens & plain_terms))
    out_wants_html_desc = bool(requested_segment and (seg_tokens & desc_terms) and (seg_tokens & markup_terms))
    wants_text_desc = bool((focus_tokens & desc_terms) and (focus_tokens & plain_terms))
    wants_html_desc = bool((focus_tokens & desc_terms) and (focus_tokens & markup_terms))
    asks_generic_desc = bool(focus_tokens & desc_terms)

    # If extracted output segment explicitly asks both variants, keep unchanged.
    # When no segment is extracted (ambiguous phrasing), we still allow fallback
    # generic handling so projection can remain schema-driven.
    if wants_text_desc and wants_html_desc and requested_segment:
        return sql

    has_output_cue = bool(
        re.search(
            r"\b(?:return|show|display|get|list|include|including|provide|output)\b",
            q,
            flags=re.I,
        )
    )
    # Prefer extracted output segment; fallback to explicit output cue wording.
    can_append_target = bool(
        (requested_segment or has_output_cue)
        and (wants_text_desc or wants_html_desc or asks_generic_desc)
    )
    if not (wants_text_desc or wants_html_desc or can_append_target):
        return sql

    def _identifier_tokens(text: str) -> List[str]:
        raw = str(text or "").strip()
        if not raw:
            return []
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ").lower()
        return [tok for tok in re.findall(r"[a-z0-9]+", raw) if tok]

    cols: List[str] = []
    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    if analyzer is None:
        try:
            analyzer = get_schema_analyzer()
        except Exception:
            analyzer = None
    if analyzer is not None:
        try:
            cols = [
                str(c).strip("`")
                for c in analyzer.get_table_columns(base_table)
                if str(c).strip()
            ]
        except Exception:
            cols = []
    if not cols and ctx:
        allowed = _parse_allowed_identifiers(ctx)
        cols = [
            str(c).strip("`")
            for c in (allowed.get(base_table, set()) or set())
            if str(c).strip()
        ]
    if not cols:
        return sql

    def _column_original_case(col_name: str) -> str:
        c_l = str(col_name or "").strip().lower()
        if not c_l:
            return str(col_name or "")
        if analyzer is not None:
            try:
                return str(analyzer._column_original_case.get(f"{base_table}.{c_l}", c_l))
            except Exception:
                pass
        return c_l

    desc_terms = {"description", "descriptions", "detail", "details", "desc"}
    html_terms = {"html", "xml", "xhtml", "markup"}
    text_terms = {"text", "plain", "plaintext"}

    desc_candidates: List[Dict[str, Any]] = []
    for col in cols:
        col_clean = str(col or "").strip("`")
        if not col_clean:
            continue
        name_tokens = set(_identifier_tokens(col_clean))
        syn_tokens: Set[str] = set()
        desc_text_tokens: Set[str] = set()
        role_tokens: Set[str] = set()
        if analyzer is not None:
            try:
                for syn in analyzer.get_column_synonyms(base_table, col_clean):
                    syn_tokens.update(_identifier_tokens(syn))
            except Exception:
                pass
            try:
                desc_text_tokens.update(_identifier_tokens(analyzer.get_column_description(base_table, col_clean)))
            except Exception:
                pass
        try:
            role_l = str(get_column_role(base_table, col_clean) or "").strip().lower()
        except Exception:
            role_l = ""
        if role_l:
            role_tokens.update(_identifier_tokens(role_l))

        all_tokens = name_tokens | syn_tokens | desc_text_tokens | role_tokens
        is_desc = bool(all_tokens & desc_terms) or ("description" in col_clean.lower())
        if not is_desc:
            continue
        desc_candidates.append(
            {
                "name": _column_original_case(col_clean),
                "is_text": bool(all_tokens & text_terms),
                "is_html": bool(all_tokens & html_terms),
                "tokens": all_tokens,
            }
        )
    if not desc_candidates:
        return sql

    target = _choose_preferred_description_column(
        base_table=base_table,
        columns=cols,
        question=q,
        requested_segment=requested_segment,
        analyzer=analyzer,
    )
    if not target:
        return sql

    target_out = _column_original_case(target)
    source_cols = [
        str(c.get("name") or "").strip()
        for c in desc_candidates
        if str(c.get("name") or "").strip().lower() != target_out.lower()
    ]

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_simple_col(expr: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    select_items = [
        str(it).strip()
        for it in _split_top_level_commas(select_part)
        if str(it or "").strip()
    ]
    if not select_items:
        return sql

    changed = False
    rewritten_items: List[str] = []
    for item in select_items:
        item_new = item
        parts = _split_outside_quotes(item_new)
        for i in range(0, len(parts), 2):
            seg = parts[i]
            for src in source_cols:
                src_pat = re.escape(str(src).strip("`"))
                seg_new = re.sub(
                    rf"(?is)\b((?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?)`?{src_pat}`?\b",
                    rf"\1{target_out}",
                    seg,
                )
                if seg_new != seg:
                    changed = True
                    seg = seg_new
            parts[i] = seg
        item_new = "".join(parts).strip()
        rewritten_items.append(item_new)

    target_pat = re.compile(
        rf"(?is)\b(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?{re.escape(str(target_out).strip('`'))}`?\b"
    )
    has_target_projection = any(target_pat.search(str(it or "")) for it in rewritten_items)
    if can_append_target and not has_target_projection:
        qualifier = ""
        for it in rewritten_items:
            expr, _out_alias = _split_expr_alias(it)
            parsed = _parse_simple_col(expr)
            if not parsed:
                continue
            qual, _col = parsed
            qual_l = str(qual or "").strip().lower()
            if qual_l and qual_l in {base_alias.lower(), base_table}:
                qualifier = str(qual).strip("`")
                break
        col_expr = f"{qualifier}.{target_out}" if qualifier else target_out
        rewritten_items.append(col_expr)
        changed = True

    dedup_items: List[str] = []
    seen_keys: Set[str] = set()
    for it in rewritten_items:
        expr, _out_alias = _split_expr_alias(it)
        parsed = _parse_simple_col(expr)
        if parsed:
            qual, col = parsed
            qual_l = str(qual or "").strip().lower()
            col_l = str(col or "").strip().lower()
            if col_l and (not qual_l or qual_l in {base_alias.lower(), base_table}):
                key = f"basecol::{col_l}"
            else:
                key = f"expr::{str(it or '').strip().lower()}"
        else:
            key = f"expr::{str(it or '').strip().lower()}"
        if key in seen_keys:
            changed = True
            continue
        seen_keys.add(key)
        dedup_items.append(str(it).strip())
    if not dedup_items:
        return sql

    fixed_select = ", ".join(dedup_items)
    if has_select_distinct:
        fixed_select = f"DISTINCT {fixed_select}"

    def _replace_desc_refs(clause: str) -> Tuple[str, bool]:
        txt = str(clause or "").strip()
        if not txt or not source_cols:
            return txt, False
        local_changed = False
        parts = _split_outside_quotes(txt)
        for i in range(0, len(parts), 2):
            seg = parts[i]
            for src in source_cols:
                src_pat = re.escape(str(src).strip("`"))
                seg_new = re.sub(
                    rf"(?is)\b((?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?)`?{src_pat}`?\b",
                    rf"\1{target_out}",
                    seg,
                )
                if seg_new != seg:
                    local_changed = True
                    seg = seg_new
            parts[i] = seg
        return "".join(parts).strip(), local_changed

    target_meta = next(
        (
            c for c in desc_candidates
            if str(c.get("name") or "").strip().lower() == str(target_out).strip().lower()
        ),
        None,
    )
    target_is_html = bool(target_meta and target_meta.get("is_html"))
    preserve_filter_variant = False
    if full_wants_text_desc and full_wants_html_desc:
        preserve_filter_variant = True
    elif full_wants_html_desc and not full_wants_text_desc and not out_wants_html_desc and not target_is_html:
        preserve_filter_variant = True
    elif full_wants_text_desc and not full_wants_html_desc and not out_wants_text_desc and target_is_html:
        preserve_filter_variant = True

    fixed_where = where_part
    fixed_order = order_part
    if not preserve_filter_variant:
        fixed_where, where_changed = _replace_desc_refs(where_part)
        fixed_order, order_changed = _replace_desc_refs(order_part)
        if where_changed or order_changed:
            changed = True

    out_lines = [f"SELECT {fixed_select}", f"FROM {from_core}"]
    if fixed_where:
        out_lines.append(f"WHERE {fixed_where}")
    if fixed_order:
        out_lines.append(f"ORDER BY {fixed_order}")
    if limit_part:
        out_lines.append(f"LIMIT {limit_part}")
    fixed_sql = "\n".join(out_lines).strip()

    # If question asks for preview-only text (first N chars), keep preview
    # expression and drop full raw description column when both are selected.
    if re.search(r"\bfirst\s+\d+\s+(?:characters?|chars?)\b", q, flags=re.I):
        m_fixed = re.match(
            r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<from>.+?)"
            r"(?:\s+WHERE\s+(?P<where>.+?))?"
            r"(?:\s+ORDER\s+BY\s+(?P<order>.+?))?"
            r"(?:\s+LIMIT\s+(?P<limit>.+?))?\s*$",
            fixed_sql,
        )
        if m_fixed:
            s_sel = (m_fixed.group("select") or "").strip()
            s_from = (m_fixed.group("from") or "").strip()
            s_where = (m_fixed.group("where") or "").strip()
            s_order = (m_fixed.group("order") or "").strip()
            s_limit = (m_fixed.group("limit") or "").strip()
            items = _split_top_level_commas(s_sel)
            if items:
                preview_pat = re.compile(
                    rf"(?is)\b(?:LEFT|SUBSTRING|SUBSTR)\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?{re.escape(target_out)}`?\b"
                )

                def _is_simple_target_column(item_text: str) -> bool:
                    expr = re.sub(
                        r"""(?is)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
                        "",
                        str(item_text or "").strip(),
                    ).strip()
                    m_col = re.match(
                        rf"(?is)^(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?{re.escape(target_out)}`?$",
                        expr,
                    )
                    return bool(m_col)

                has_preview = any(preview_pat.search(str(it or "")) for it in items)
                if has_preview:
                    kept = [it.strip() for it in items if not _is_simple_target_column(it)]
                    if kept and len(kept) < len(items):
                        changed = True
                        out_lines = [f"SELECT {', '.join(kept)}", f"FROM {s_from}"]
                        if s_where:
                            out_lines.append(f"WHERE {s_where}")
                        if s_order:
                            out_lines.append(f"ORDER BY {s_order}")
                        if s_limit:
                            out_lines.append(f"LIMIT {s_limit}")
                        fixed_sql = "\n".join(out_lines).strip()

    if not changed:
        return sql
    if not fixed_sql.endswith(";"):
        fixed_sql += ";"
    return fixed_sql


def _align_requested_joined_description_variant(sql: str, question: str, ctx: str = "") -> str:
    """
    Schema-driven description variant alignment for simple JOIN lookups.

    This complements `_align_requested_description_variant` (single-table path)
    by handling JOIN projections conservatively:
    - rewrite only simple projected description-like columns
    - keep FROM/JOIN/WHERE/ORDER logic intact
    - use schema-driven preferred variant (text/html/generic)
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql

    s = str(sql or "").strip().rstrip(";").strip()
    if not s:
        return sql
    if not re.search(r"\bjoin\b", s, flags=re.I):
        return sql
    if re.search(r"\b(?:group\s+by|having|union|intersect|except|with)\b", s, flags=re.I):
        return sql
    # Safe on correlated/non-correlated subqueries because this helper only
    # rewrites top-level SELECT projection items.

    m_sel = re.match(
        r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<from>.+?)"
        r"(?:\s+WHERE\s+(?P<where>.+?))?"
        r"(?:\s+ORDER\s+BY\s+(?P<order>.+?))?"
        r"(?:\s+LIMIT\s+(?P<limit>.+?))?\s*$",
        s,
    )
    if not m_sel:
        return sql

    select_part = (m_sel.group("select") or "").strip()
    from_core = (m_sel.group("from") or "").strip()
    where_part = (m_sel.group("where") or "").strip()
    order_part = (m_sel.group("order") or "").strip()
    limit_part = (m_sel.group("limit") or "").strip()
    if not select_part or not from_core:
        return sql

    has_select_distinct = bool(re.match(r"(?is)^DISTINCT\b", select_part))
    if has_select_distinct:
        select_part = re.sub(r"(?is)^DISTINCT\s+", "", select_part, count=1).strip()
    if not select_part:
        return sql

    alias_to_table_raw = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    alias_to_table: Dict[str, str] = {}
    for alias, table in (alias_to_table_raw or {}).items():
        a = str(alias or "").strip().strip("`").lower()
        t = str(table or "").strip().strip("`").lower()
        if a and t:
            alias_to_table[a] = t
            if t not in alias_to_table:
                alias_to_table[t] = t
    if not alias_to_table:
        return sql

    unique_tables = sorted(
        {
            str(t or "").strip().lower()
            for a, t in alias_to_table.items()
            if a and a.lower() == a and t
        }
    )
    if not unique_tables:
        return sql

    requested_segment = _extract_requested_output_segment(q)
    focus_text = (
        requested_segment
        if requested_segment
        and re.search(r"\b(?:description|descriptions|detail|details|desc)\b", requested_segment, flags=re.I)
        else q
    )

    def _nl_tokens(text: str) -> Set[str]:
        raw = str(text or "").strip().lower()
        if not raw:
            return set()
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ")
        return {tok for tok in re.findall(r"[a-z0-9]+", raw) if tok}

    desc_terms = {"description", "descriptions", "detail", "details", "desc"}
    markup_terms = {"html", "xml", "xhtml", "markup", "web", "richtext", "tag"}
    plain_terms = {"text", "plain", "plaintext", "raw"}

    focus_tokens = _nl_tokens(focus_text)

    wants_text_desc = bool((focus_tokens & desc_terms) and (focus_tokens & plain_terms))
    wants_html_desc = bool((focus_tokens & desc_terms) and (focus_tokens & markup_terms))
    asks_generic_desc = bool(focus_tokens & desc_terms)
    if wants_text_desc and wants_html_desc and requested_segment:
        return sql

    has_output_cue = bool(
        re.search(
            r"\b(?:return|show|display|get|list|include|including|provide|output)\b",
            q,
            flags=re.I,
        )
    )
    can_align = bool(
        (requested_segment or has_output_cue)
        and (wants_text_desc or wants_html_desc or asks_generic_desc)
    )
    if not can_align:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    if analyzer is None:
        try:
            analyzer = get_schema_analyzer()
        except Exception:
            analyzer = None

    table_cols_cache: Dict[str, List[str]] = {}
    table_target_cache: Dict[str, str] = {}

    def _table_columns(table_name: str) -> List[str]:
        table_l = str(table_name or "").strip().lower()
        if not table_l:
            return []
        if table_l in table_cols_cache:
            return table_cols_cache[table_l]
        cols: List[str] = []
        if analyzer is not None:
            try:
                cols = [
                    str(c).strip("`")
                    for c in analyzer.get_table_columns(table_l)
                    if str(c).strip()
                ]
            except Exception:
                cols = []
        if not cols and ctx:
            allowed = _parse_allowed_identifiers(ctx)
            cols = [
                str(c).strip("`")
                for c in (allowed.get(table_l, set()) or set())
                if str(c).strip()
            ]
        table_cols_cache[table_l] = cols
        return cols

    def _column_original_case(table_name: str, col_name: str) -> str:
        table_l = str(table_name or "").strip().lower()
        c_l = str(col_name or "").strip().lower()
        if not table_l or not c_l or analyzer is None:
            return c_l or str(col_name or "")
        try:
            return str(analyzer._column_original_case.get(f"{table_l}.{c_l}", c_l))
        except Exception:
            return c_l

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_simple_col(expr: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _resolve_table(qualifier: Optional[str]) -> str:
        q_l = str(qualifier or "").strip().strip("`").lower()
        if q_l:
            return str(alias_to_table.get(q_l) or (q_l if q_l in unique_tables else "")).strip().lower()
        return ""

    def _is_description_like(table_name: str, col_name: str) -> bool:
        c_l = str(col_name or "").strip().lower()
        if not c_l:
            return False
        if "description" in c_l or "detail" in c_l:
            return True
        try:
            role_l = str(get_column_role(table_name, c_l) or "").strip().lower()
        except Exception:
            role_l = ""
        return role_l in {"description", "text"}

    select_items = [
        str(it).strip()
        for it in _split_top_level_commas(select_part)
        if str(it or "").strip()
    ]
    if not select_items:
        return sql

    changed = False
    rewritten_items: List[str] = []
    for item in select_items:
        expr, out_alias = _split_expr_alias(item)
        parsed = _parse_simple_col(expr)
        if not parsed:
            rewritten_items.append(item)
            continue

        qual, col = parsed
        col_l = str(col or "").strip().lower()
        table_l = _resolve_table(qual)
        if not table_l and len(unique_tables) == 1:
            table_l = unique_tables[0]
        if not table_l or not _is_description_like(table_l, col_l):
            rewritten_items.append(item)
            continue

        cols = _table_columns(table_l)
        if not cols:
            rewritten_items.append(item)
            continue

        if table_l not in table_target_cache:
            target = _choose_preferred_description_column(
                base_table=table_l,
                columns=cols,
                question=q,
                requested_segment=requested_segment,
                analyzer=analyzer,
            )
            table_target_cache[table_l] = str(target or "").strip()
        target = str(table_target_cache.get(table_l) or "").strip()
        if not target:
            rewritten_items.append(item)
            continue

        target_out = _column_original_case(table_l, target)
        if str(target_out or "").strip().lower() == col_l:
            rewritten_items.append(item)
            continue

        qualifier = str(qual or "").strip().strip("`")
        new_expr = f"{qualifier}.{target_out}" if qualifier else target_out
        if out_alias:
            rewritten_items.append(f"{new_expr} AS {out_alias}")
        else:
            rewritten_items.append(new_expr)
        changed = True

    if not changed:
        return sql

    fixed_select = ", ".join(rewritten_items)
    if has_select_distinct:
        fixed_select = f"DISTINCT {fixed_select}"

    out_lines = [f"SELECT {fixed_select}", f"FROM {from_core}"]
    if where_part:
        out_lines.append(f"WHERE {where_part}")
    if order_part:
        out_lines.append(f"ORDER BY {order_part}")
    if limit_part:
        out_lines.append(f"LIMIT {limit_part}")

    fixed_sql = "\n".join(out_lines).strip()
    if not fixed_sql.endswith(";"):
        fixed_sql += ";"
    return fixed_sql


def _rewrite_in_list_null_literal_as_is_null(sql: str) -> str:
    """
    SQL correctness normalization:
      col IN ('A', NULL) -> (col IN ('A') OR col IS NULL)
      col IN (NULL)      -> col IS NULL

    Only rewrites literal IN-lists (never subqueries).
    """
    if not sql:
        return sql

    pat = re.compile(
        r"(?is)\b(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+IN\s*\((?P<vals>[^()]*)\)"
    )

    def _repl(m: re.Match) -> str:
        col = str(m.group("col") or "").strip()
        vals = str(m.group("vals") or "").strip()
        if not vals or re.search(r"\bselect\b", vals, flags=re.I):
            return m.group(0)
        items = [x.strip() for x in _split_top_level_commas(vals) if str(x or "").strip()]
        if not items:
            return m.group(0)
        has_null = any(re.fullmatch(r"(?is)null", it) for it in items)
        if not has_null:
            return m.group(0)
        non_null_items = [it for it in items if not re.fullmatch(r"(?is)null", it)]
        if non_null_items:
            return f"({col} IN ({', '.join(non_null_items)}) OR {col} IS NULL)"
        return f"{col} IS NULL"

    return pat.sub(_repl, sql)


def _prune_non_primary_dimensions_for_primary_aggregate(sql: str, question: str, ctx: str = "") -> str:
    """
    For include-zero "for each <primary entity>" aggregate questions, keep one row per
    primary entity by removing non-primary simple dimensions from SELECT/GROUP BY.

    Example fixed:
      For each employee ... total payment from their customers ...
      DROP: customerNumber/customerName from SELECT/GROUP BY.
    """
    if not sql or not question:
        return sql

    # Windowed aggregate queries often need non-primary grouping dimensions
    # (e.g., PARTITION BY product line) to satisfy requested output semantics.
    # Do not prune joined dimensions in this shape.
    if re.search(r"\bOVER\s*\(", sql, flags=re.I):
        return sql

    q = (question or "").lower()
    # Only activate on conservative signals to avoid over-pruning.
    has_for_each = bool(re.search(r"\b(for\s+each|each|per|every)\b", q))
    has_agg = bool(re.search(r"\b(sum|count|avg|average|min|max|total|jumlah)\b", q))
    include_zero = _question_wants_include_zero(question, ctx)
    if not (has_for_each and has_agg and include_zero):
        return sql

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        return sql
    from_core = (parsed.get("from_core") or "").strip()
    if not from_core or not re.search(r"\bjoin\b", from_core, flags=re.I):
        return sql
    if not parsed.get("groupby"):
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if not alias_to_table:
        return sql

    # Build term->table mapping dynamically from schema metadata.
    term_to_table: Dict[str, str] = {}
    for t in get_all_tables():
        tt = (t or "").strip().lower()
        if not tt:
            continue
        terms: Set[str] = {tt}
        sg = get_singular_form(tt) if tt else tt
        if sg:
            terms.add(str(sg).lower())
        if "_" in tt:
            terms.add(tt.replace("_", " "))
        if sg and "_" in str(sg):
            terms.add(str(sg).replace("_", " ").lower())
        try:
            for syn in get_table_synonyms(tt):
                s = (syn or "").strip().lower()
                if s:
                    terms.add(s)
        except Exception:
            pass
        for term in terms:
            if not term:
                continue
            term_to_table[term] = tt

    # Infer primary table from "for each <entity>" phrase.
    primary_table: Optional[str] = None
    # Sort longer terms first to avoid partial matches.
    for term in sorted(term_to_table.keys(), key=len, reverse=True):
        pat = rf"\b(?:for\s+each|each|per|every)\s+{re.escape(term)}\b"
        if re.search(pat, q, flags=re.I):
            primary_table = term_to_table[term]
            break
    if not primary_table:
        return sql

    primary_aliases: Set[str] = set()
    for a, t in alias_to_table.items():
        if not a or not t:
            continue
        if t.lower() == primary_table:
            primary_aliases.add(a.lower())
    # fallback without explicit alias
    primary_aliases.add(primary_table)
    primary_aliases.add(get_singular_form(primary_table).lower())

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _alias_refs(expr: str) -> Set[str]:
        refs = re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\.", expr or "", flags=re.I)
        return {r.lower() for r in refs}

    def _is_agg_or_window(expr: str) -> bool:
        e = (expr or "")
        if re.search(r"\b(SUM|COUNT|AVG|MIN|MAX|GROUP_CONCAT|STDDEV|VARIANCE)\s*\(", e, flags=re.I):
            return True
        if re.search(r"\bOVER\s*\(", e, flags=re.I):
            return True
        return False

    select_items = _split_top_level_commas(parsed["select"])
    group_items = _split_top_level_commas(parsed["groupby"])

    new_select: List[str] = []
    for it in select_items:
        expr, _alias = _split_expr_alias(it)
        refs = _alias_refs(expr)
        if _is_agg_or_window(expr):
            new_select.append(it.strip())
            continue
        if not refs:
            new_select.append(it.strip())
            continue
        # Keep non-aggregate expression only when it depends exclusively on primary alias/table.
        if refs.issubset(primary_aliases):
            new_select.append(it.strip())
            continue
        # else: drop non-primary dimension

    if not new_select:
        return sql

    new_group: List[str] = []
    for g in group_items:
        refs = _alias_refs(g)
        if not refs or refs.issubset(primary_aliases):
            new_group.append(g.strip())

    if not new_group:
        # do not produce invalid aggregate query
        return sql

    # Rebuild query with same tail/having.
    out_lines = []
    out_lines.append("SELECT " + ", ".join(new_select))
    out_lines.append("FROM " + from_core)
    if parsed.get("where"):
        out_lines.append(parsed["where"].strip())
    out_lines.append("GROUP BY " + ", ".join(new_group))
    if parsed.get("having"):
        out_lines.append("HAVING " + parsed["having"].strip())
    if parsed.get("tail"):
        out_lines.append(parsed["tail"].strip())

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_nonprimary_identifier_group_keys(
    sql: str,
    question: str,
    ctx: str = "",
) -> str:
    """
    Drop leaked child/support identifier dimensions from grouped JOIN queries
    when the question clearly asks for one row per primary entity.

    Conservative scope:
    - grouped flat JOIN query only
    - question expresses "for each/per/every <entity>" and aggregate intent
    - only removes simple non-primary columns that look identifier-like
    - only when that child/support identifier is not requested in the question
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql
    has_for_each = bool(re.search(r"\b(?:for\s+each|each|per|every)\b", q, flags=re.I))
    has_agg = bool(re.search(r"\b(?:sum|count|avg|average|min|max|total)\b", q, flags=re.I))
    if not (has_for_each and has_agg):
        return sql

    parsed = _parse_flat_groupby_clauses(sql) or _parse_select_from_groupby(sql)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    if not from_core or not re.search(r"(?is)\bjoin\b", from_core):
        return sql
    if not str(parsed.get("groupby") or "").strip():
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}") or {}
    alias_to_table_l = {
        str(alias or "").strip("`").lower(): str(table or "").strip("`").lower()
        for alias, table in alias_to_table.items()
        if str(alias or "").strip() and str(table or "").strip()
    }
    if not alias_to_table_l:
        return sql

    term_to_table: Dict[str, str] = {}
    for table_name in get_all_tables():
        table_l = str(table_name or "").strip().lower()
        if not table_l:
            continue
        terms: Set[str] = {table_l}
        singular = get_singular_form(table_l) if table_l else table_l
        if singular:
            terms.add(str(singular).lower())
        if "_" in table_l:
            terms.add(table_l.replace("_", " "))
        if singular and "_" in str(singular):
            terms.add(str(singular).replace("_", " ").lower())
        try:
            for syn in get_table_synonyms(table_l):
                syn_l = str(syn or "").strip().lower()
                if syn_l:
                    terms.add(syn_l)
        except Exception:
            pass
        for term in terms:
            if term:
                term_to_table[term] = table_l

    primary_table = ""
    best_primary_pos: Optional[int] = None
    best_primary_span_len = -1
    for term in sorted(term_to_table.keys(), key=len, reverse=True):
        pattern = rf"\b(?:for\s+each|for\s+every|each|per|every)\s+(?:such\s+|the\s+|those\s+|these\s+)?{re.escape(term)}\b"
        match = re.search(pattern, q, flags=re.I)
        if not match:
            continue
        match_pos = match.start()
        term_len = len(str(term or ""))
        if (
            best_primary_pos is None
            or match_pos < best_primary_pos
            or (match_pos == best_primary_pos and term_len > best_primary_span_len)
        ):
            primary_table = term_to_table[term]
            best_primary_pos = match_pos
            best_primary_span_len = term_len
    if not primary_table:
        return sql

    primary_aliases: Set[str] = {
        alias_l
        for alias_l, table_l in alias_to_table_l.items()
        if table_l == primary_table
    }
    primary_aliases.add(primary_table)
    singular_primary = str(get_singular_form(primary_table) or "").strip().lower()
    if singular_primary:
        primary_aliases.add(singular_primary)

    requested_output_segment = _extract_requested_output_segment(question) or q
    whole_question = str(question or "").strip().lower()
    scope_text = f"{requested_output_segment} {whole_question}".strip()
    q_tokens = set(re.findall(r"[a-z0-9]+", scope_text))

    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}

    simple_col_pat = re.compile(
        r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$"""
    )

    def _simple_col_ref(expr: str) -> Tuple[str, str]:
        m = simple_col_pat.match(str(expr or "").strip())
        if not m:
            return ("", "")
        return (
            str(m.group(1) or "").strip("`").lower(),
            str(m.group(2) or "").strip("`").lower(),
        )

    def _column_mentioned(table_l: str, col_l: str, out_alias: Optional[str]) -> bool:
        variants: Set[str] = set()

        def _add_variant(text: str) -> None:
            raw = str(text or "").strip()
            if not raw:
                return
            spaced = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw).replace("_", " ").strip().lower()
            compact = re.sub(r"\s+", " ", spaced).strip()
            if compact:
                variants.add(compact)

        _add_variant(col_l)
        _add_variant(out_alias or "")
        try:
            for variant in get_column_entity_variants(table_l, col_l) or set():
                _add_variant(str(variant or ""))
        except Exception:
            pass
        try:
            for variant in get_column_synonyms(table_l, col_l) or []:
                _add_variant(str(variant or ""))
        except Exception:
            pass

        for variant in variants:
            pat = re.escape(variant).replace(r"\ ", r"\s+")
            if pat and re.search(rf"\b{pat}\b", scope_text, flags=re.I):
                return True

        token_hints: Set[str] = set()
        for variant in variants:
            token_hints.update(
                tok for tok in re.findall(r"[a-z0-9]+", variant)
                if len(tok) >= 3 and tok not in {"the", "and", "with"}
            )
        return bool(token_hints) and token_hints.issubset(q_tokens)

    def _looks_like_identifier_col(table_l: str, col_l: str) -> bool:
        if not table_l or not col_l:
            return False
        try:
            id_col = str(get_id_column(table_l) or "").strip("`").lower()
        except Exception:
            id_col = ""
        if id_col and col_l == id_col:
            return True
        if col_l in {
            str(fk_col or "").strip("`").lower()
            for fk_col in (fk_raw.get(table_l, {}) or {})
            if str(fk_col or "").strip()
        }:
            return True
        try:
            role_l = str(get_column_role(table_l, col_l) or "").strip().lower()
        except Exception:
            role_l = ""
        if role_l in {"pk", "fk", "id", "identifier"}:
            return True
        tokens = re.findall(
            r"[a-z0-9]+",
            re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", col_l).replace("_", " ").lower(),
        )
        if any(tok in {"line", "sequence", "position", "reference"} for tok in tokens):
            return True
        return bool(tokens) and tokens[-1] in {"id", "number", "code", "key"}

    having_text = str(parsed.get("having") or "").strip()
    tail_text = str(parsed.get("tail") or "").strip()

    def _referenced_elsewhere(alias_l: str, col_l: str, out_alias: Optional[str]) -> bool:
        qual_pat = rf"(?is)\b{re.escape(alias_l)}\s*\.\s*`?{re.escape(col_l)}`?\b"
        if re.search(qual_pat, having_text, flags=re.I) or re.search(qual_pat, tail_text, flags=re.I):
            return True
        alias_txt = str(out_alias or "").strip().strip("`'\"")
        if alias_txt and (
            re.search(rf"(?is)\b{re.escape(alias_txt)}\b", having_text)
            or re.search(rf"(?is)\b{re.escape(alias_txt)}\b", tail_text)
        ):
            return True
        return False

    select_items = [str(it).strip() for it in _split_top_level_commas(parsed.get("select") or "") if str(it or "").strip()]
    group_items = [str(it).strip() for it in _split_top_level_commas(parsed.get("groupby") or "") if str(it or "").strip()]
    if not select_items or not group_items:
        return sql

    drop_keys: Set[Tuple[str, str]] = set()
    new_select_items: List[str] = []
    removed_any = False
    for item in select_items:
        expr, out_alias = _split_select_expr_alias(item)
        expr_txt = str(expr or "").strip()
        if not expr_txt:
            continue
        if re.search(r"(?is)\b(?:SUM|COUNT|AVG|MIN|MAX|GROUP_CONCAT|STDDEV|VARIANCE)\s*\(", expr_txt):
            new_select_items.append(item)
            continue
        if re.search(r"(?is)\bOVER\s*\(", expr_txt):
            new_select_items.append(item)
            continue

        alias_l, col_l = _simple_col_ref(expr_txt)
        if not alias_l or not col_l:
            new_select_items.append(item)
            continue
        if alias_l in primary_aliases:
            new_select_items.append(item)
            continue

        table_l = alias_to_table_l.get(alias_l, "")
        if not table_l or table_l == primary_table:
            new_select_items.append(item)
            continue
        if _column_mentioned(table_l, col_l, out_alias):
            new_select_items.append(item)
            continue
        if _referenced_elsewhere(alias_l, col_l, out_alias):
            new_select_items.append(item)
            continue
        if not _looks_like_identifier_col(table_l, col_l):
            new_select_items.append(item)
            continue

        drop_keys.add((alias_l, col_l))
        removed_any = True

    if not removed_any or not new_select_items:
        return sql

    new_group_items: List[str] = []
    for item in group_items:
        alias_l, col_l = _simple_col_ref(item)
        if alias_l and col_l and (alias_l, col_l) in drop_keys:
            continue
        new_group_items.append(item)

    if not new_group_items:
        return sql

    out_lines = [
        "SELECT " + ", ".join(new_select_items),
        "FROM " + from_core,
    ]
    if str(parsed.get("where") or "").strip():
        out_lines.append(str(parsed.get("where") or "").strip())
    out_lines.append("GROUP BY " + ", ".join(new_group_items))
    if having_text:
        if not having_text.lower().startswith("having "):
            having_text = f"HAVING {having_text}"
        out_lines.append(having_text)
    if tail_text:
        out_lines.append(tail_text)

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_redundant_raw_name_columns_when_concat_present(sql: str, question: str) -> str:
    """
    If SELECT already contains a composite-name expression (e.g., CONCAT of
    multiple name-part columns), drop redundant raw name-part columns for the
    same alias unless the question explicitly asks for component names.
    """
    if not sql or not question:
        return sql

    wants_split_name_components = question_wants_split_name_components(question)
    wants_combined_name = question_wants_combined_full_name(question)
    name_component_token_hints = name_component_lexical_tokens()
    name_component_synonym_hint_phrases = name_component_synonym_hints()
    name_priority_groups = name_component_priority_groups()
    q_name = str(question or "").strip().lower()

    def _has_phrase(phrases: Set[str]) -> bool:
        for p in sorted((str(x).strip().lower() for x in phrases if str(x).strip()), key=len, reverse=True):
            pat = re.escape(p).replace(r"\ ", r"\s+")
            if re.search(rf"\b{pat}\b", q_name, flags=re.I):
                return True
        return False

    explicit_first_hint = _has_phrase(set(name_priority_groups.get("first", set())))
    explicit_last_hint = _has_phrase(set(name_priority_groups.get("last", set())))
    explicit_name_term = any_phrase_in_text(q_name, name_request_terms())
    explicit_component_request = bool(explicit_name_term and explicit_first_hint and explicit_last_hint)

    wants_split_effective = bool(wants_split_name_components or explicit_component_request)
    wants_both_name_forms = bool(wants_combined_name and wants_split_effective)
    wants_combined_only = bool(wants_combined_name and not wants_split_effective)
    wants_split_only = bool(wants_split_effective and not wants_combined_name)

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        if not (wants_split_only or wants_combined_only or wants_both_name_forms):
            return sql
        # Minimal fallback parser for non-GROUP BY SELECT queries.
        s0 = (sql or "").strip().rstrip(";").strip()
        m_sel = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<after>.+)$", s0)
        if not m_sel:
            return sql
        select_part = (m_sel.group("select") or "").strip()
        after_from = (m_sel.group("after") or "").strip()
        if not select_part or not after_from:
            return sql

        kw_match = re.search(r"\b(ORDER\s+BY|LIMIT)\b", after_from, flags=re.I)
        if kw_match:
            core_part = after_from[:kw_match.start()].strip()
            tail_part = after_from[kw_match.start():].strip()
        else:
            core_part = after_from
            tail_part = ""
        if not core_part:
            return sql

        where_match = re.search(r"\bWHERE\b", core_part, flags=re.I)
        if where_match:
            from_core = core_part[:where_match.start()].strip()
            where_part = core_part[where_match.start():].strip()
        else:
            from_core = core_part
            where_part = ""
        if not from_core:
            return sql

        parsed = {
            "select": select_part,
            "from_core": from_core,
            "where": where_part,
            "groupby": "",
            "having": "",
            "tail": tail_part,
        }
    has_groupby = bool((parsed.get("groupby") or "").strip())
    if not has_groupby and not (wants_split_only or wants_combined_only or wants_both_name_forms):
        return sql

    select_items = _split_top_level_commas(parsed["select"])
    group_items = _split_top_level_commas(parsed.get("groupby", ""))
    if not select_items:
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    alias_to_table: Dict[str, str] = {}
    if from_core:
        try:
            parsed_aliases = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
        except Exception:
            parsed_aliases = {}
        for a, t in (parsed_aliases or {}).items():
            if a and t:
                alias_to_table[a.lower()] = t.lower()
        if not alias_to_table:
            m_base = re.match(r"(?is)^`?([A-Za-z_][A-Za-z0-9_]*)`?", from_core)
            if m_base:
                t0 = m_base.group(1).lower()
                alias_to_table[t0] = t0

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_simple_col(expr: str) -> Optional[tuple]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return (m.group(1) or "").lower(), m.group(2).lower()

    def _identifier_tokens(val: str) -> Set[str]:
        s = str(val or "").strip()
        if not s:
            return set()
        s = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", s)
        s = s.replace("_", " ")
        return {tok.lower() for tok in re.findall(r"[a-z0-9]+", s)}

    def _matches_name_token_hint(col_name: str, toks: Set[str], hints: Set[str]) -> bool:
        if not hints:
            return False
        norm_toks = {str(t).strip().replace(" ", "_").lower() for t in toks if str(t).strip()}
        if norm_toks.intersection(hints):
            return True
        col_compact = re.sub(r"[^a-z0-9]", "", str(col_name or "").lower())
        for hint in hints:
            h = re.sub(r"[^a-z0-9]", "", str(hint or "").lower())
            if len(h) >= 4 and h in col_compact:
                return True
        return False

    name_cols_cache: Dict[str, Set[str]] = {}

    def _table_name_component_cols(table_l: str) -> Set[str]:
        t_l = str(table_l or "").strip().lower()
        if not t_l:
            return set()
        if t_l in name_cols_cache:
            return name_cols_cache[t_l]
        table_cols: Set[str] = set()
        if analyzer is not None:
            try:
                table_cols = {
                    str(c).strip("`").lower()
                    for c in analyzer.get_table_columns(t_l)
                    if str(c).strip()
                }
            except Exception:
                table_cols = set()
        out: Set[str] = set()
        for c in table_cols:
            toks = _identifier_tokens(c)
            if _matches_name_token_hint(c, toks, name_component_token_hints):
                out.add(c)
                continue
            if analyzer is not None:
                try:
                    role = str((analyzer._column_roles.get(t_l, {}) or {}).get(c, "")).strip().lower()
                except Exception:
                    role = ""
                if role == "name":
                    out.add(c)
                    continue
                try:
                    syns = (analyzer._column_synonyms.get(f"{t_l}.{c}", []) or [])
                except Exception:
                    syns = []
                syn_blob = " ".join(str(x).lower() for x in syns)
                if any_phrase_in_text(syn_blob, name_component_synonym_hint_phrases):
                    out.add(c)
        name_cols_cache[t_l] = out
        return out

    def _expr_alias_col_refs(expr: str) -> Dict[str, Set[str]]:
        refs: Dict[str, Set[str]] = {}
        for m_ref in re.finditer(
            r"(?is)\b`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\b",
            str(expr or ""),
        ):
            a_l = m_ref.group(1).lower()
            c_l = m_ref.group(2).lower()
            refs.setdefault(a_l, set()).add(c_l)
        return refs

    def _ordered_name_components(table_l: str, cols: Set[str]) -> List[str]:
        t_l = str(table_l or "").strip().lower()
        cols_l = {str(c).strip().lower() for c in cols if str(c).strip()}
        if not cols_l:
            return []

        col_order: Dict[str, int] = {}
        if analyzer is not None:
            try:
                table_cols = [str(c).strip("`").lower() for c in analyzer.get_table_columns(t_l) if str(c).strip()]
            except Exception:
                table_cols = []
            col_order = {c: i for i, c in enumerate(table_cols)}

        first_hints = set(name_priority_groups.get("first", set()))
        middle_hints = set(name_priority_groups.get("middle", set()))
        last_hints = set(name_priority_groups.get("last", set()))
        generic_hints = set(name_priority_groups.get("generic", set()))

        def _name_priority(col_name: str) -> int:
            toks = _identifier_tokens(col_name)
            if _matches_name_token_hint(col_name, toks, first_hints):
                return 0
            if _matches_name_token_hint(col_name, toks, middle_hints):
                return 1
            if _matches_name_token_hint(col_name, toks, last_hints):
                return 2
            if _matches_name_token_hint(col_name, toks, generic_hints):
                return 3
            return 4

        return sorted(
            cols_l,
            key=lambda c: (_name_priority(c), col_order.get(c, 10_000), c),
        )

    # If question explicitly asks both combined full name and split components,
    # ensure both forms are present for each alias in non-grouped projections.
    if wants_both_name_forms and not has_groupby:
        existing_simple_cols: Set[Tuple[str, str]] = set()
        alias_to_selected_name_cols: Dict[str, Set[str]] = {}
        alias_to_concat_name_cols: Dict[str, Set[str]] = {}

        for it in select_items:
            expr_i, _ = _split_expr_alias(it)
            p_i = _parse_simple_col(expr_i)
            if p_i:
                a_l, c_l = p_i
                existing_simple_cols.add((a_l, c_l))
                if a_l:
                    table_l = alias_to_table.get(a_l, a_l)
                    name_candidates = _table_name_component_cols(table_l)
                    if c_l in name_candidates:
                        alias_to_selected_name_cols.setdefault(a_l, set()).add(c_l)

            e_i = str(expr_i or "")
            if re.search(r"(?is)\bconcat\s*\(", e_i) or "||" in e_i:
                alias_refs = _expr_alias_col_refs(e_i)
                for a_l, cols in alias_refs.items():
                    table_l = alias_to_table.get(a_l, a_l)
                    name_candidates = _table_name_component_cols(table_l)
                    matched = cols.intersection(name_candidates)
                    if len(matched) >= 2:
                        alias_to_concat_name_cols.setdefault(a_l, set()).update(matched)

        aliases = sorted(
            set(alias_to_selected_name_cols.keys()) | set(alias_to_concat_name_cols.keys())
        )
        if aliases:
            items_out: List[str] = [it.strip() for it in select_items]
            changed_both = False

            for a_l in aliases:
                table_l = alias_to_table.get(a_l, a_l)
                selected_name_cols = set(alias_to_selected_name_cols.get(a_l, set()))
                concat_name_cols = set(alias_to_concat_name_cols.get(a_l, set()))

                # Recover split components from metadata if only CONCAT exists.
                if len(selected_name_cols) < 2 and len(concat_name_cols) >= 2:
                    ordered_from_concat = _ordered_name_components(table_l, concat_name_cols)
                    for c_l in ordered_from_concat:
                        key = (a_l, c_l)
                        if key in existing_simple_cols:
                            continue
                        c_out = c_l
                        if analyzer is not None:
                            try:
                                c_out = str(analyzer._column_original_case.get(f"{table_l}.{c_l}", c_l))
                            except Exception:
                                c_out = c_l
                        items_out.append(f"{a_l}.{c_out}")
                        existing_simple_cols.add(key)
                        selected_name_cols.add(c_l)
                        changed_both = True

                # Add combined form when split components are present but CONCAT is missing.
                if len(selected_name_cols) >= 2 and len(concat_name_cols) < 2:
                    ordered_for_concat = _ordered_name_components(table_l, selected_name_cols)
                    if len(ordered_for_concat) >= 2:
                        concat_parts: List[str] = []
                        for idx_c, c_l in enumerate(ordered_for_concat):
                            c_out = c_l
                            if analyzer is not None:
                                try:
                                    c_out = str(analyzer._column_original_case.get(f"{table_l}.{c_l}", c_l))
                                except Exception:
                                    c_out = c_l
                            if idx_c > 0:
                                concat_parts.append("' '")
                            concat_parts.append(f"{a_l}.{c_out}")
                        items_out.append(f"CONCAT({', '.join(concat_parts)}) AS {a_l}_name")
                        changed_both = True

            if changed_both and items_out:
                out_lines = []
                out_lines.append("SELECT " + ", ".join(items_out))
                out_lines.append("FROM " + (parsed.get("from_core") or "").strip())
                if parsed.get("where"):
                    out_lines.append(parsed["where"].strip())
                if parsed.get("tail"):
                    out_lines.append(parsed["tail"].strip())

                fixed_both = "\n".join(out_lines).strip()
                if not fixed_both.endswith(";"):
                    fixed_both += ";"
                return fixed_both

    # If the question asks first/given + last/surname components (not full/combine),
    # keep them as separate columns instead of a single CONCAT projection.
    if wants_split_only:
        existing_simple_cols: Set[Tuple[str, str]] = set()
        for it in select_items:
            expr_i, _ = _split_expr_alias(it)
            p_i = _parse_simple_col(expr_i)
            if p_i:
                existing_simple_cols.add((p_i[0], p_i[1]))

        new_select_split: List[str] = []
        inserted_for_group: List[str] = []
        changed_split = False

        for it in select_items:
            expr, _a = _split_expr_alias(it)
            e = str(expr or "")
            if not (re.search(r"(?is)\bconcat\s*\(", e) or "||" in e):
                new_select_split.append(it.strip())
                continue

            alias_refs = _expr_alias_col_refs(e)
            replaced = False
            for a_l, cols in alias_refs.items():
                table_l = alias_to_table.get(a_l, a_l)
                name_candidates = _table_name_component_cols(table_l)
                matched = cols.intersection(name_candidates)
                if len(matched) < 2:
                    continue

                ordered_parts = _ordered_name_components(table_l, matched)
                emitted_cols: List[str] = []
                for c in ordered_parts:
                    key = (a_l, c)
                    if key in existing_simple_cols:
                        continue
                    c_out = c
                    if analyzer is not None:
                        try:
                            c_out = str(analyzer._column_original_case.get(f"{table_l}.{c}", c))
                        except Exception:
                            c_out = c
                    emitted = f"{a_l}.{c_out}"
                    emitted_cols.append(emitted)
                    inserted_for_group.append(emitted)
                    existing_simple_cols.add(key)

                # Remove CONCAT projection even if parts already exist.
                if emitted_cols:
                    new_select_split.extend(emitted_cols)
                changed_split = True
                replaced = True
                break

            if not replaced:
                new_select_split.append(it.strip())

        if changed_split and new_select_split:
            new_group_split = [g.strip() for g in group_items]
            if new_group_split and inserted_for_group:
                seen_group = {g.lower() for g in new_group_split}
                for gc in inserted_for_group:
                    if gc.lower() in seen_group:
                        continue
                    new_group_split.append(gc)
                    seen_group.add(gc.lower())

            out_lines = []
            out_lines.append("SELECT " + ", ".join(new_select_split))
            out_lines.append("FROM " + (parsed.get("from_core") or "").strip())
            if parsed.get("where"):
                out_lines.append(parsed["where"].strip())
            if new_group_split:
                out_lines.append("GROUP BY " + ", ".join(new_group_split))
            if parsed.get("having"):
                out_lines.append("HAVING " + parsed["having"].strip())
            if parsed.get("tail"):
                out_lines.append(parsed["tail"].strip())

            fixed_split = "\n".join(out_lines).strip()
            if not fixed_split.endswith(";"):
                fixed_split += ";"
            return fixed_split

    # If question requests combined full names, ensure aliases that currently
    # project split name parts are collapsed into one CONCAT projection.
    if wants_combined_only and not has_groupby:
        alias_to_name_items: Dict[str, List[Tuple[int, str, str]]] = {}
        alias_to_name_cols: Dict[str, Set[str]] = {}
        alias_with_composite: Set[str] = set()

        for idx, it in enumerate(select_items):
            expr, _a = _split_expr_alias(it)
            e = str(expr or "")
            if re.search(r"(?is)\bconcat\s*\(", e) or "||" in e:
                alias_refs = _expr_alias_col_refs(e)
                for a_l, cols in alias_refs.items():
                    table_l = alias_to_table.get(a_l, a_l)
                    name_candidates = _table_name_component_cols(table_l)
                    matched = cols.intersection(name_candidates)
                    if len(matched) >= 2:
                        alias_with_composite.add(a_l)

            p = _parse_simple_col(expr)
            if not p:
                continue
            a_l, c_l = p
            if not a_l:
                continue
            table_l = alias_to_table.get(a_l, a_l)
            name_candidates = _table_name_component_cols(table_l)
            if c_l not in name_candidates:
                continue
            alias_to_name_items.setdefault(a_l, []).append((idx, it.strip(), c_l))
            alias_to_name_cols.setdefault(a_l, set()).add(c_l)

        replace_by_index: Dict[int, str] = {}
        drop_indices: Set[int] = set()

        for a_l, cols in alias_to_name_cols.items():
            if a_l in alias_with_composite:
                continue
            if len(cols) < 2:
                continue
            ordered = _ordered_name_components(alias_to_table.get(a_l, a_l), cols)
            ordered = [c for c in ordered if c in cols]
            if len(ordered) < 2:
                continue

            idx_by_col: Dict[str, int] = {}
            for idx, _item, col_l in alias_to_name_items.get(a_l, []):
                if col_l not in idx_by_col:
                    idx_by_col[col_l] = idx
            first_idx = min(idx_by_col[c] for c in ordered if c in idx_by_col)

            concat_parts: List[str] = []
            for i, c_l in enumerate(ordered):
                c_out = c_l
                if analyzer is not None:
                    try:
                        table_l = alias_to_table.get(a_l, a_l)
                        c_out = str(analyzer._column_original_case.get(f"{table_l}.{c_l}", c_l))
                    except Exception:
                        c_out = c_l
                if i > 0:
                    concat_parts.append("' '")
                concat_parts.append(f"{a_l}.{c_out}")

            replace_by_index[first_idx] = f"CONCAT({', '.join(concat_parts)}) AS {a_l}_name"
            for c_l in ordered:
                idx = idx_by_col.get(c_l)
                if idx is not None and idx != first_idx:
                    drop_indices.add(idx)

        if replace_by_index or drop_indices:
            new_select_combined: List[str] = []
            for idx, it in enumerate(select_items):
                if idx in drop_indices:
                    continue
                if idx in replace_by_index:
                    new_select_combined.append(replace_by_index[idx])
                else:
                    new_select_combined.append(it.strip())

            if new_select_combined and new_select_combined != [it.strip() for it in select_items]:
                out_lines = []
                out_lines.append("SELECT " + ", ".join(new_select_combined))
                out_lines.append("FROM " + (parsed.get("from_core") or "").strip())
                if parsed.get("where"):
                    out_lines.append(parsed["where"].strip())
                if parsed.get("tail"):
                    out_lines.append(parsed["tail"].strip())

                fixed_combined = "\n".join(out_lines).strip()
                if not fixed_combined.endswith(";"):
                    fixed_combined += ";"
                return fixed_combined

    # Detect aliases that already project composite-name expressions.
    concat_alias_name_parts: Dict[str, Set[str]] = {}
    for it in select_items:
        expr, _a = _split_expr_alias(it)
        e = str(expr or "")
        if not (re.search(r"(?is)\bconcat\s*\(", e) or "||" in e):
            continue
        alias_refs = _expr_alias_col_refs(e)
        if not alias_refs:
            continue
        for a_l, cols in alias_refs.items():
            table_l = alias_to_table.get(a_l, a_l)
            name_candidates = _table_name_component_cols(table_l)
            if not name_candidates:
                continue
            matched = cols.intersection(name_candidates)
            if len(matched) >= 2:
                concat_alias_name_parts.setdefault(a_l, set()).update(matched)

    if not concat_alias_name_parts:
        return sql

    def _is_raw_name_col(item: str) -> bool:
        expr, _a = _split_expr_alias(item)
        p = _parse_simple_col(expr)
        if not p:
            return False
        a, c = p
        if a in concat_alias_name_parts:
            return c in concat_alias_name_parts.get(a, set())

        # Unqualified projection fallback for single-alias cases.
        if a:
            return False
        if len(concat_alias_name_parts) != 1:
            return False
        only_alias = next(iter(concat_alias_name_parts.keys()))
        return c in concat_alias_name_parts.get(only_alias, set())

    new_select = [it.strip() for it in select_items if not _is_raw_name_col(it)]
    if len(new_select) == len(select_items):
        return sql

    out_lines = []
    out_lines.append("SELECT " + ", ".join(new_select))
    out_lines.append("FROM " + (parsed.get("from_core") or "").strip())
    if parsed.get("where"):
        out_lines.append(parsed["where"].strip())
    if has_groupby:
        # Keep original GROUP BY as-is for safety (prevents 1055 regressions).
        new_group = [g.strip() for g in group_items]
        out_lines.append("GROUP BY " + ", ".join(new_group))
    if parsed.get("having"):
        out_lines.append("HAVING " + parsed["having"].strip())
    if parsed.get("tail"):
        out_lines.append(parsed["tail"].strip())

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed

def _ensure_unique_output_column_labels(sql: str) -> str:
    """
    Ensure top-level SELECT output labels are unique.

    Some execution/evaluation adapters materialize rows as dicts keyed by
    column labels. Duplicate labels (e.g., e.jobTitle and m.jobTitle) can cause
    one column to be dropped. This helper disambiguates only output labels and
    keeps row values/query semantics unchanged.
    """
    s = str(sql or "").strip()
    if not s:
        return sql
    if re.search(r"\b(?:union|intersect|except)\b", s, flags=re.I):
        return sql
    if re.search(r"(?is)\b(?:from|join)\s*\(\s*select\b", s):
        return sql

    parsed = _parse_flat_groupby_clauses(s) or _parse_select_from_groupby(s)
    if not parsed:
        # Fallback parser for flat non-grouped SELECT queries.
        m_sel = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<after>.+)$", s.rstrip(";").strip())
        if not m_sel:
            return sql
        select_part_fb = str(m_sel.group("select") or "").strip()
        after_from = str(m_sel.group("after") or "").strip()
        if not select_part_fb or not after_from:
            return sql

        kw_match = re.search(r"\b(ORDER\s+BY|LIMIT)\b", after_from, flags=re.I)
        if kw_match:
            core_part = after_from[:kw_match.start()].strip()
            tail_part = after_from[kw_match.start():].strip()
        else:
            core_part = after_from
            tail_part = ""
        if not core_part:
            return sql

        where_match = re.search(r"\bWHERE\b", core_part, flags=re.I)
        if where_match:
            from_core_fb = core_part[:where_match.start()].strip()
            where_part_fb = core_part[where_match.start():].strip()
        else:
            from_core_fb = core_part
            where_part_fb = ""
        if not from_core_fb:
            return sql

        parsed = {
            "select": select_part_fb,
            "from_core": from_core_fb,
            "where": where_part_fb,
            "groupby": "",
            "having": "",
            "tail": tail_part,
        }

    select_part = str(parsed.get("select") or "").strip()
    from_core = str(parsed.get("from_core") or "").strip()
    if not select_part or not from_core:
        return sql

    has_select_distinct = bool(re.match(r"(?is)^DISTINCT\b", select_part))
    if has_select_distinct:
        select_part = re.sub(r"(?is)^DISTINCT\s+", "", select_part, count=1).strip()
    if not select_part:
        return sql

    select_items = [str(it).strip() for it in _split_top_level_commas(select_part) if str(it or "").strip()]
    if len(select_items) < 2:
        return sql

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            str(item or "").strip(),
        )
        if not m:
            return str(item or "").strip(), None
        return str(m.group(1) or "").strip(), str(m.group(2) or "").strip()

    def _unquote_alias(alias_text: Optional[str]) -> str:
        a = str(alias_text or "").strip()
        if not a:
            return ""
        if len(a) >= 2 and a[0] == a[-1] and a[0] in {"`", "'", '"'}:
            a = a[1:-1].strip()
        return a

    def _parse_simple_col(expr: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            str(expr or "").strip(),
        )
        if not m:
            return None
        qual = str(m.group(1) or "").strip()
        col = str(m.group(2) or "").strip()
        return (qual or None, col)

    def _norm_label(label: str) -> str:
        return re.sub(r"\s+", " ", str(label or "").strip().lower())

    def _safe_alias_base(text: str, fallback_idx: int) -> str:
        base = re.sub(r"[^A-Za-z0-9_]+", "_", str(text or "").strip()).strip("_")
        if not base:
            base = f"col_{fallback_idx}"
        if re.match(r"^\d", base):
            base = f"col_{base}"
        return base

    seen_label_counts: Dict[str, int] = {}
    used_alias_labels: Set[str] = set()
    new_items: List[str] = []
    changed = False

    for idx, item in enumerate(select_items, start=1):
        expr, out_alias = _split_expr_alias(item)
        parsed_col = _parse_simple_col(expr)

        if out_alias:
            display_label = _unquote_alias(out_alias)
        elif parsed_col:
            _q, col_name = parsed_col
            display_label = col_name
        else:
            display_label = f"col_{idx}"

        key = _norm_label(display_label)
        seen = seen_label_counts.get(key, 0) + 1
        seen_label_counts[key] = seen

        if seen == 1:
            used_alias_labels.add(key)
            new_items.append(item.strip())
            continue

        changed = True
        if parsed_col:
            qual_name, col_name = parsed_col
            alias_base = f"{qual_name}_{col_name}" if qual_name else col_name
        elif out_alias:
            alias_base = _unquote_alias(out_alias)
        else:
            alias_base = display_label
        alias_base = _safe_alias_base(alias_base, idx)

        cand = alias_base
        bump = 1
        while _norm_label(cand) in used_alias_labels:
            bump += 1
            cand = f"{alias_base}_{bump}"
        used_alias_labels.add(_norm_label(cand))

        cand_sql = _smart_backtick(cand)
        new_items.append(f"{expr} AS {cand_sql}")

    if not changed:
        return sql

    fixed_select = ", ".join(new_items)
    if has_select_distinct:
        fixed_select = f"DISTINCT {fixed_select}"

    out_lines = [f"SELECT {fixed_select}", f"FROM {from_core}"]
    if parsed.get("where"):
        out_lines.append(str(parsed.get("where") or "").strip())
    if parsed.get("groupby"):
        out_lines.append("GROUP BY " + str(parsed.get("groupby") or "").strip())
    if parsed.get("having"):
        out_lines.append("HAVING " + str(parsed.get("having") or "").strip())
    if parsed.get("tail"):
        out_lines.append(str(parsed.get("tail") or "").strip())

    rebuilt = "\n".join(out_lines).strip()
    if not rebuilt.endswith(";"):
        rebuilt += ";"
    return rebuilt

def _expand_group_by_aliases_regex(sql: str) -> str:
    """
    Regex-based GROUP BY alias expansion (simpler but less robust).
    """
    if not sql or "group by" not in sql.lower():
        return sql

    # Only operate when GROUP BY exists at top level (not inside subqueries).
    def _find_top_level_group_by(s: str) -> int:
        s_up = s.upper()
        depth = 0
        in_sq = False
        in_dq = False
        i = 0
        while i < len(s):
            ch = s[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(s) and s[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and s_up[i:i + 8] == "GROUP BY":
                left_ok = (i == 0 or not s[i - 1].isalnum())
                right_ok = (i + 8 >= len(s) or not s[i + 8].isalnum())
                if left_ok and right_ok:
                    return i
            i += 1
        return -1

    group_pos_top = _find_top_level_group_by(sql)
    if group_pos_top < 0:
        return sql

    # Extract SELECT ... FROM
    m_select = re.search(
        r"\bSELECT\b(.*?)\bFROM\b",
        sql,
        flags=re.I | re.S
    )
    if not m_select:
        return sql

    select_part = m_select.group(1)

    # Build alias -> expression map conservatively from top-level SELECT items.
    # Important: only use explicit "AS alias" and never rewrite partial tokens
    # inside qualified refs (e.g., do NOT turn p.amount into p.MAX(...)).
    alias_map: Dict[str, str] = {}
    select_items = _split_top_level_commas(select_part)
    for item in select_items:
        m_as = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m_as:
            continue
        expr = (m_as.group(1) or "").strip()
        alias = (m_as.group(2) or "").strip().strip("`'\"")
        if not expr or not alias:
            continue
        alias_map[alias.lower()] = expr

    if not alias_map:
        return sql

    # Extract top-level GROUP BY clause (search from top-level GROUP BY position).
    m_group = re.search(
        r"\bGROUP\s+BY\b\s+(.*?)(?=(\bORDER\s+BY\b|\bHAVING\b|\bLIMIT\b|;|$))",
        sql[group_pos_top:],
        flags=re.I | re.S
    )
    if not m_group:
        return sql

    abs_group_start = group_pos_top + m_group.start(1)
    abs_group_end = group_pos_top + m_group.end(1)
    group_clause = m_group.group(1).strip()
    group_items = _split_top_level_commas(group_clause)

    def _unquote_identifier(x: str) -> str:
        t = (x or "").strip()
        if len(t) >= 2 and t[0] == t[-1] and t[0] in {"`", "'", '"'}:
            return t[1:-1].strip()
        return t

    # Replace only when a GROUP BY item is exactly an alias token.
    new_group_items: List[str] = []
    for item in group_items:
        raw = item.strip()
        key = _unquote_identifier(raw).lower()
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", _unquote_identifier(raw)) and key in alias_map:
            new_group_items.append(alias_map[key])
        else:
            new_group_items.append(raw)
    new_group = ", ".join(new_group_items)

    # Replace in original SQL, preserving clause boundaries.
    suffix = sql[abs_group_end:]
    if suffix and not suffix.startswith((" ", "\n", "\t", "\r")):
        if re.match(r"(?is)^(ORDER\s+BY|HAVING|LIMIT|;)", suffix):
            suffix = " " + suffix
    return sql[:abs_group_start] + new_group + suffix

def _is_potential_winner_row(sql: str, question: str, force: bool = False) -> bool:
    """
    Detect whether a query *should* be treated as a winner-row query.

    force=True → skip intent filter (used when guardrail already confirmed pattern)
    """

    if not sql:
        return False

    # intent-aware mode unless forced
    if not _question_wants_winner_row(question) and not force:
        return False

    s = sql.lower()

    # must mention GROUP BY or an aggregate candidate
    if "group by" not in s and "max(" not in s and "min(" not in s:
        return False

    # Winner-row patterns (robust, no hardcoded column names)
    # Pattern 1: MAX()/MIN() on date/timestamp columns (e.g., orderDate, paymentDate, createdAt)
    # These indicate "most recent" or "earliest" queries → winner-row pattern
    has_max_min = ("max(" in s or "min(" in s)
    if has_max_min:
        # Check for date/timestamp column patterns: *date, *time, *at
        has_date_col = bool(re.search(r'\b\w*date\b', s)) or bool(re.search(r'\b\w*time\b', s))
        if has_date_col:
            return True

    # Pattern 2: HAVING clause with aggregate → likely filtering for max/min value
    if "having" in s and ("max(" in s or "min(" in s):
        return True

    # If no specific winner-row pattern matched, it's NOT a winner-row query
    return False


def _fix_order_by_group_by_consistency(sql: str) -> str:
    """
    Fix ORDER BY items that reference columns not in GROUP BY (causes Error 1055).

    Two fix modes:
    1. When ORDER BY has simple column and GROUP BY has expression → replace ORDER BY with GROUP BY expr
    2. When ORDER BY has expression not in GROUP BY → add ORDER BY expr to GROUP BY

    Example 1 (replace ORDER BY):
        GROUP BY MONTH(o.orderDate)
        ORDER BY o.orderDate DESC
    →   ORDER BY MONTH(o.orderDate) DESC

    Example 2 (add to GROUP BY):
        GROUP BY DATE_FORMAT(o.orderDate, '%M')
        ORDER BY MONTH(o.orderDate) DESC
    →   GROUP BY DATE_FORMAT(o.orderDate, '%M'), MONTH(o.orderDate)
        ORDER BY MONTH(o.orderDate) DESC
    """
    if not sql:
        return sql

    if "GROUP BY" not in sql.upper() or "ORDER BY" not in sql.upper():
        return sql

    # IMPORTANT: only consider TOP-LEVEL ORDER BY/GROUP BY (outside subqueries/window functions).
    # Otherwise ORDER BY inside OVER(...) will corrupt GROUP BY rewrites.
    def _find_top_level_order_by(s: str) -> Optional[int]:
        s_upper = s.upper()
        depth = 0
        i = 0
        while i < len(s):
            ch = s[i]
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth = max(0, depth - 1)
            elif depth == 0 and s_upper[i:i+8] == 'ORDER BY':
                left_ok = (i == 0 or not s[i-1].isalnum())
                right_ok = (i + 8 >= len(s) or not s[i+8].isalnum())
                if left_ok and right_ok:
                    return i
            i += 1
        return None

    def _find_top_level_group_by(s: str) -> Optional[int]:
        s_upper = s.upper()
        depth = 0
        i = 0
        while i < len(s):
            ch = s[i]
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth = max(0, depth - 1)
            elif depth == 0 and s_upper[i:i+8] == 'GROUP BY':
                left_ok = (i == 0 or not s[i-1].isalnum())
                right_ok = (i + 8 >= len(s) or not s[i+8].isalnum())
                if left_ok and right_ok:
                    return i
            i += 1
        return None

    order_pos = _find_top_level_order_by(sql)
    if order_pos is None:
        return sql
    group_pos_top = _find_top_level_group_by(sql)
    if group_pos_top is None:
        return sql

    # Extract top-level GROUP BY clause
    gb_match = re.search(
        r'\bGROUP\s+BY\s+(.*?)(?=\s*(?:ORDER\s+BY|HAVING|LIMIT|;|$))',
        sql[group_pos_top:],
        re.IGNORECASE | re.DOTALL
    )
    if not gb_match:
        return sql

    gb_abs_start = group_pos_top + gb_match.start(1)
    gb_abs_end = group_pos_top + gb_match.end(1)
    group_clause = gb_match.group(1).strip()
    group_items = _split_top_level_commas(group_clause)

    def _unquote_identifier(text: str) -> str:
        raw = str(text or "").strip()
        if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {"`", "'", '"'}:
            return raw[1:-1].strip()
        return raw

    def _normalize_alias_lookup_key(text: str) -> str:
        raw = _unquote_identifier(text)
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", raw)
        raw = re.sub(r"[^A-Za-z0-9]+", "_", raw).strip("_").lower()
        raw = re.sub(r"_+", "_", raw)
        return raw

    select_alias_map: Dict[str, str] = {}
    select_alias_ref_map: Dict[str, str] = {}
    select_pos = _find_top_level_clause(sql, "select")
    from_pos = _find_top_level_clause(sql, "from", max(0, select_pos + len("select")))
    if select_pos == 0 and from_pos > 0:
        select_part = sql[select_pos + len("select"):from_pos].strip()
        for item in _split_top_level_commas(select_part):
            expr, alias = _split_select_expr_alias(item)
            alias_key = _unquote_identifier(alias or "").lower()
            if alias_key and expr:
                select_alias_map[alias_key] = str(expr).strip()
                select_alias_ref_map[alias_key] = _unquote_identifier(alias or "").strip()
                norm_key = _normalize_alias_lookup_key(alias or "")
                if norm_key and norm_key not in select_alias_ref_map:
                    select_alias_ref_map[norm_key] = _unquote_identifier(alias or "").strip()

    # Normalize GROUP BY items for comparison (strip whitespace, lowercase)
    group_items_normalized = [item.strip().lower() for item in group_items]

    # Build a mapping: column_name → group_by_expression
    # e.g., "orderdate" → "MONTH(o.orderDate)"
    col_to_gb_expr = {}
    for item in group_items:
        # Extract column names referenced in this GROUP BY expression
        # Pattern: matches table.column or column names
        cols_in_expr = re.findall(r'\b(\w+(?:\.\w+)?)\b', item)
        for col in cols_in_expr:
            col_lower = col.lower()
            # Skip function names and common keywords
            if col_lower.upper() in {'MONTH', 'YEAR', 'DAY', 'DATE', 'COUNT', 'SUM', 'AVG', 'MIN', 'MAX',
                                     'DATE_FORMAT', 'STR_TO_DATE', 'IF', 'IFNULL', 'COALESCE', 'CONCAT'}:
                continue
            # Map this column to the GROUP BY expression
            if col_lower not in col_to_gb_expr:
                col_to_gb_expr[col_lower] = item

    # Extract and fix ORDER BY clause
    ob_match = re.search(r'\bORDER\s+BY\s+(.*?)(?=\s*(?:LIMIT|;|$))', sql[order_pos:], re.IGNORECASE | re.DOTALL)
    if not ob_match:
        return sql

    order_clause = ob_match.group(1).strip()
    order_items = _split_top_level_commas(order_clause)

    new_order_items = []
    items_to_add_to_group_by = []

    # Aggregate expressions in ORDER BY must never be pushed into GROUP BY
    # (e.g., ORDER BY COUNT(*) DESC is valid and should stay as-is).
    aggregate_func_pattern = re.compile(
        r"\b(COUNT|SUM|AVG|MIN|MAX|STDDEV|STD|VARIANCE|VAR_POP|VAR_SAMP|GROUP_CONCAT|BIT_AND|BIT_OR|BIT_XOR|JSON_ARRAYAGG|JSON_OBJECTAGG)\s*\(",
        re.IGNORECASE,
    )

    for item in order_items:
        # Extract the base column/expression (before ASC/DESC)
        base_match = re.match(r'(.*?)\s+(ASC|DESC)\s*$', item, re.IGNORECASE)
        if base_match:
            base = base_match.group(1).strip()
            direction = base_match.group(2).strip()
        else:
            base = item.strip()
            direction = ""

        base_alias_key = _unquote_identifier(base).lower()
        base_alias_norm_key = _normalize_alias_lookup_key(base)
        alias_ref = (
            select_alias_ref_map.get(base_alias_key)
            or select_alias_ref_map.get(base_alias_norm_key)
        )
        if alias_ref:
            base = alias_ref
            if direction:
                new_order_items.append(f"{base} {direction}")
            else:
                new_order_items.append(base)
            continue

        # Check if this is a simple column reference (not a function)
        is_simple_col = bool(re.match(r'^\w+(?:\.\w+)?$', base))

        if is_simple_col:
            base_lower = base.lower()
            # Check if this column appears in GROUP BY expressions
            if base_lower in col_to_gb_expr:
                # Replace with the GROUP BY expression
                base = col_to_gb_expr[base_lower]
        else:
            # ORDER BY item is a function expression (e.g., MONTH(o.orderDate))
            # Check if this expression is already in GROUP BY
            base_normalized = base.lower().replace(" ", "")  # Normalize for comparison

            # Also check without table alias prefix for flexibility
            # MONTH(o.orderDate) should match MONTH(orderDate) in GROUP BY
            base_no_space = base.replace(" ", "").lower()
            is_in_group_by = any(
                base_no_space in gi.replace(" ", "").lower()
                for gi in group_items_normalized
            )

            has_aggregate = bool(aggregate_func_pattern.search(base))
            has_window = bool(re.search(r"\bOVER\s*\(", base, re.IGNORECASE))

            if not is_in_group_by and not has_aggregate and not has_window:
                # Add this ORDER BY expression to GROUP BY
                items_to_add_to_group_by.append(base)

        # Reconstruct with direction
        if direction:
            new_order_items.append(f"{base} {direction}")
        else:
            new_order_items.append(base)

    # Update ORDER BY clause
    if new_order_items:
        new_order = ', '.join(new_order_items)
        abs_start = order_pos + ob_match.start(1)
        abs_end = order_pos + ob_match.end(1)
        sql = sql[:abs_start] + new_order + sql[abs_end:]

    # Add missing items to GROUP BY clause
    if items_to_add_to_group_by:
        # Find GROUP BY clause again (position may have changed)
        group_pos_top = _find_top_level_group_by(sql)
        if group_pos_top is None:
            return _drop_aggregate_or_window_items_from_group_by(sql)
        gb_match = re.search(
            r'\bGROUP\s+BY\s+(.*?)(?=\s*(?:ORDER\s+BY|HAVING|LIMIT|;|$))',
            sql[group_pos_top:],
            re.IGNORECASE | re.DOTALL
        )
        if gb_match:
            new_group_items = group_items + items_to_add_to_group_by
            new_group_clause = ', '.join(new_group_items)
            gb_abs_start = group_pos_top + gb_match.start(1)
            gb_abs_end = group_pos_top + gb_match.end(1)
            sql = sql[:gb_abs_start] + new_group_clause + sql[gb_abs_end:]

    # Final safety: GROUP BY must not contain aggregate/window expressions.
    return _drop_aggregate_or_window_items_from_group_by(sql)


def _drop_aggregate_or_window_items_from_group_by(sql: str) -> str:
    """
    Remove malformed GROUP BY items that are aggregate/window expressions.

    Example malformed:
      GROUP BY customerNumber, COUNT(*)
    """
    if not sql or "GROUP BY" not in sql.upper():
        return sql

    s = sql
    low = s.lower()

    def _is_word_boundary(text: str, i: int, n: int) -> bool:
        left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
        right_ok = i + n >= len(text) or not (text[i + n].isalnum() or text[i + n] == "_")
        return left_ok and right_ok

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        kw_l = kw.lower()
        n = len(kw_l)
        depth = 0
        in_sq = False
        in_dq = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i >= start and i + n <= len(text):
                if text[i:i + n].lower() == kw_l and _is_word_boundary(text, i, n):
                    return i
            i += 1
        return -1

    group_pos = _find_top_level_kw(low, "group by", 0)
    if group_pos < 0:
        return sql

    group_start = group_pos + len("group by")

    end_candidates = []
    for kw in ("having", "order by", "limit"):
        p = _find_top_level_kw(low, kw, group_start)
        if p >= 0:
            end_candidates.append(p)
    semicolon_pos = _find_top_level_kw(low, ";", group_start)
    if semicolon_pos >= 0:
        end_candidates.append(semicolon_pos)
    group_end = min(end_candidates) if end_candidates else len(s)

    group_clause = s[group_start:group_end].strip()
    if not group_clause:
        return sql

    group_items = _split_top_level_commas(group_clause)
    if not group_items:
        return sql

    window_aliases: Set[str] = set()
    aggregate_aliases: Set[str] = set()
    select_pos = _find_top_level_kw(low, "select", 0)
    from_pos = _find_top_level_kw(low, "from", max(0, select_pos + len("select")))
    if select_pos >= 0 and from_pos > select_pos:
        select_clause = s[select_pos + len("select"):from_pos].strip()
        for item in _split_top_level_commas(select_clause):
            item_s = (item or "").strip()
            if not item_s:
                continue
            m_alias = re.search(
                r"""(?is)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
                item_s,
            )
            if not m_alias:
                continue
            alias_name = str(m_alias.group(1) or "").strip().strip("`'\"").lower()
            if alias_name and re.search(r"\bOVER\s*\(", item_s, flags=re.I):
                window_aliases.add(alias_name)
            if alias_name and re.search(
                r"\b(COUNT|SUM|AVG|MIN|MAX|STDDEV|STD|VARIANCE|VAR_POP|VAR_SAMP|GROUP_CONCAT|BIT_AND|BIT_OR|BIT_XOR|JSON_ARRAYAGG|JSON_OBJECTAGG)\s*\(",
                item_s,
                flags=re.I,
            ):
                aggregate_aliases.add(alias_name)

    aggregate_func_pattern = re.compile(
        r"\b(COUNT|SUM|AVG|MIN|MAX|STDDEV|STD|VARIANCE|VAR_POP|VAR_SAMP|GROUP_CONCAT|BIT_AND|BIT_OR|BIT_XOR|JSON_ARRAYAGG|JSON_OBJECTAGG)\s*\(",
        re.IGNORECASE,
    )
    window_pattern = re.compile(r"\bOVER\s*\(", re.IGNORECASE)

    cleaned_items: List[str] = []
    for item in group_items:
        raw = (item or "").strip()
        if not raw:
            continue
        if aggregate_func_pattern.search(raw):
            continue
        if window_pattern.search(raw):
            continue
        raw_alias_key = raw.strip("`'\"").lower()
        if raw_alias_key in aggregate_aliases:
            continue
        if window_aliases and re.match(r"(?is)^`?[A-Za-z_][A-Za-z0-9_]*`?$", raw):
            if raw_alias_key in window_aliases:
                continue
        cleaned_items.append(raw)

    if len(cleaned_items) == len(group_items) or not cleaned_items:
        return sql

    new_group = ", ".join(cleaned_items)
    prefix = s[:group_start]
    suffix = s[group_end:]
    if suffix and not suffix[0].isspace():
        suffix = " " + suffix
    return f"{prefix} {new_group}{suffix}"


def _normalize_alias_lengths(sql: str) -> str:
    """
    Soft alias guard:
    - Preserve LLM-defined aliases by default.
    - Only shorten aliases that are excessively long.

    This keeps model creativity for normal aliases while preventing unwieldy
    output names that hurt readability.
    """
    if not sql:
        return sql

    # Don't process if no AS clause
    if " AS " not in sql.upper():
        return sql

    max_alias_len = ALIAS_MAX_LEN if ALIAS_MAX_LEN >= 8 else 8

    def replace_alias(match):
        """Shorten only if alias is too long; otherwise keep original."""
        # Extract the alias from whichever group matched
        # groups[0] = content inside single quotes
        # groups[1] = content inside double quotes
        # groups[2] = content inside backticks
        # groups[3] = unquoted alias

        groups = match.groups()

        if groups[0] is not None:
            # Single-quoted alias
            alias = groups[0]
            quote_char = "'"
        elif groups[1] is not None:
            # Double-quoted alias
            alias = groups[1]
            quote_char = '"'
        elif groups[2] is not None:
            # Backtick-quoted alias
            alias = groups[2]
            quote_char = '`'
        elif groups[3] is not None:
            # Unquoted alias
            alias = groups[3]
            quote_char = None
        else:
            # No match, return original
            return match.group(0)

        # Keep exactly what LLM produced if alias is already reasonable.
        if len(alias) <= max_alias_len:
            return match.group(0)

        # If too long, compact to snake_case + max length.
        shortened = alias.lower().replace(" ", "_").replace("-", "_")
        shortened = re.sub(r"[^\w]", "_", shortened)
        shortened = re.sub(r"_+", "_", shortened).strip("_")
        if not shortened:
            shortened = "alias"
        if len(shortened) > max_alias_len:
            shortened = shortened[:max_alias_len].rstrip("_")
        if not shortened:
            shortened = "alias"

        if quote_char:
            return f" AS {quote_char}{shortened}{quote_char}"
        else:
            return f" AS {shortened}"

    # Match AS followed by quoted or unquoted alias
    # Pattern handles: AS 'name', AS "name", AS `name`, AS identifier
    pattern = r"\s+AS\s+(?:'([^']*)'|"          # Single quoted
    pattern += r'"([^"]*)"'                     # Double quoted
    pattern += r'|`([^`]*)`'                    # Backtick quoted
    pattern += r'|([a-zA-Z_][a-zA-Z0-9_]*))'    # Unquoted identifier

    result = re.sub(pattern, replace_alias, sql, flags=re.IGNORECASE)

    return result

def _enforce_explicit_group_by(sql: str) -> str:
    """
    Benchmark style:
    If query has GROUP BY, every SELECT expression that is NOT:
      - aggregate (SUM/COUNT/AVG/MIN/MAX/...),
      - window (... OVER ...),
      - literal,
      - star
    must appear explicitly in GROUP BY.
    """
    if not sql:
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not sel:
        return sql

    grp = sel.args.get("group")
    # SAFETY: do nothing if no GROUP BY exists
    if not grp or not grp.expressions:
        return sql

    group_set = {g.sql(dialect="mysql").strip().lower() for g in grp.expressions}
    missing = []

    for item in sel.expressions:
        base = item.this if isinstance(item, exp.Alias) else item

        if base.find(exp.AggFunc):
            continue
        if base.find(exp.Window):
            continue
        if isinstance(base, (exp.Literal, exp.Star)):
            continue

        base_sql = base.sql(dialect="mysql").strip().lower()
        if base_sql not in group_set:
            missing.append(base)
            group_set.add(base_sql)

    if missing:
        grp.set("expressions", grp.expressions + missing)

    return ast.sql(dialect="mysql")

def _remove_invalid_select_columns_with_group_by(sql: str) -> str:
    """
    When GROUP BY is present, remove SELECT columns that are:
    - NOT aggregate functions (COUNT, SUM, AVG, MIN, MAX, etc.)
    - NOT in GROUP BY
    - NOT window functions (OVER)
    - NOT literals/stars

    This prevents Error 1055: "not functionally dependent on columns in GROUP BY clause"

    Safe for all correct queries - only removes hallucinated columns.
    """
    if not sql:
        return sql

    # Only apply when GROUP BY is top-level (not inside subqueries).
    def _has_top_level_group_by(s: str) -> bool:
        s_up = s.upper()
        depth = 0
        in_sq = False
        in_dq = False
        i = 0
        while i < len(s):
            ch = s[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(s) and s[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and s_up[i:i + 8] == "GROUP BY":
                left_ok = (i == 0 or not s[i - 1].isalnum())
                right_ok = (i + 8 >= len(s) or not s[i + 8].isalnum())
                if left_ok and right_ok:
                    return True
            i += 1
        return False

    if not _has_top_level_group_by(sql):
        return sql

    group_pos = _find_top_level_clause(sql, "group by")
    if group_pos >= 0:
        order_pos = _find_top_level_clause(sql, "order by", group_pos + len("group by"))
        limit_pos = _find_top_level_clause(sql, "limit", group_pos + len("group by"))
        having_pos = _find_top_level_clause(sql, "having", group_pos + len("group by"))
        group_end = min([p for p in (having_pos, order_pos, limit_pos, len(sql)) if p >= 0])
        group_clause = sql[group_pos + len("group by"):group_end].strip()
        if re.search(r"\bOVER\s*\(", group_clause, flags=re.I):
            return sql

    # Try sqlglot first (more accurate)
    try:
        import sqlglot
        from sqlglot import exp
        ast = sqlglot.parse_one(sql, read="mysql")
        sel = ast.find(exp.Select)
        if not sel:
            return sql

        grp = sel.args.get("group")
        if not grp or not grp.expressions:
            return sql

        def _normalize_table_name(name: str) -> str:
            t = (name or "").strip("`").lower()
            if not t:
                return ""
            if t.endswith("ies") and len(t) > 3:
                return t[:-3] + "y"
            if t.endswith("s") and len(t) > 1:
                return t[:-1]
            return t

        def _column_entity_stem(col_name: str) -> str:
            c = (col_name or "").strip("`").lower()
            if not c:
                return ""
            c = re.sub(r"(?:_)?(?:number|id|code|key)$", "", c).strip("_")
            return c

        def _looks_like_entity_identifier(col_name: str, table_name: str) -> bool:
            c = (col_name or "").strip("`").lower()
            if not c or not re.search(r"(?:number|id|code|key)$", c):
                return False
            col_stem = _column_entity_stem(c)
            if not col_stem:
                return False
            table_norm = _normalize_table_name(table_name)
            return bool(table_norm) and col_stem == table_norm

        alias_to_table: Dict[str, str] = {}
        table_names: Set[str] = set()
        for src in ast.find_all(exp.Table):
            table_name = str(src.name or "").strip("`").lower()
            alias_name = str(src.alias_or_name or table_name).strip("`").lower()
            if not table_name:
                continue
            table_names.add(table_name)
            if alias_name:
                alias_to_table[alias_name] = table_name
            alias_to_table[table_name] = table_name

        # Keep descriptive columns from the same table when GROUP BY already uses
        # that table's own entity key (e.g., offices.officeCode -> offices.city).
        entity_key_sources: Set[str] = set()
        for gexpr in grp.expressions:
            if not isinstance(gexpr, exp.Column):
                continue
            g_table = str(gexpr.table or "").strip("`").lower()
            g_name = str(gexpr.name or "").strip("`").lower()
            resolved_table = alias_to_table.get(g_table, g_table)
            if not resolved_table and len(table_names) == 1:
                resolved_table = next(iter(table_names))
            if _looks_like_entity_identifier(g_name, resolved_table):
                if g_table:
                    entity_key_sources.add(g_table)
                if resolved_table:
                    entity_key_sources.add(resolved_table)

        # Get GROUP BY columns
        group_sql = grp.sql(dialect="mysql")
        group_set = {g.strip().lower() for g in re.findall(r'(\w+(?:\.\w+)?)', group_sql, re.IGNORECASE)}

        only_table = next(iter(table_names)) if len(table_names) == 1 else ""
        has_join = any(True for _ in ast.find_all(exp.Join))
        has_subquery = any(True for _ in sel.find_all(exp.Subquery))
        if only_table and entity_key_sources and not has_join and not has_subquery and not sel.args.get("having"):
            has_agg_or_window = False
            same_row_projection = True
            for item in sel.expressions:
                base = item.this if isinstance(item, exp.Alias) else item
                if base.find(exp.AggFunc) or base.find(exp.Window):
                    has_agg_or_window = True
                    break
                for rc in base.find_all(exp.Column):
                    rc_table = str(rc.table or "").strip("`").lower()
                    resolved_rc_table = alias_to_table.get(rc_table, rc_table) if rc_table else only_table
                    if resolved_rc_table and resolved_rc_table != only_table:
                        same_row_projection = False
                        break
                if not same_row_projection:
                    break
            if not has_agg_or_window and same_row_projection:
                sel.set("group", None)
                return ast.sql(dialect="mysql")

        # Check SELECT expressions
        expressions_to_remove = []
        for item in sel.expressions:
            base = item.this if isinstance(item, exp.Alias) else item
            alias = item.alias if isinstance(item, exp.Alias) else None

            # Skip if aggregate, window, literal, or star
            if base.find(exp.AggFunc):
                continue
            if base.find(exp.Window):
                continue
            if isinstance(base, (exp.Literal, exp.Star)):
                continue

            # Skip CASE expressions (they define computed columns used in GROUP BY)
            if isinstance(base, exp.Case):
                continue

            base_sql = base.sql(dialect="mysql").strip().lower()

            # Also check if alias is in GROUP BY (MySQL compatibility)
            alias_in_groupby = False
            if alias:
                alias_sql = alias.sql(dialect="mysql").strip().lower()
                alias_in_groupby = alias_sql in group_set

            preserve_via_entity_key = False
            ref_cols = [c for c in base.find_all(exp.Column)]
            if isinstance(base, exp.Column):
                base_table = str(base.table or "").strip("`").lower()
                resolved_base_table = alias_to_table.get(base_table, base_table)
                if base_table and (
                    base_table in entity_key_sources or resolved_base_table in entity_key_sources
                ):
                    preserve_via_entity_key = True
                elif (
                    not base_table
                    and len(table_names) == 1
                    and entity_key_sources
                ):
                    # Conservative support for unqualified columns in single-table queries.
                    preserve_via_entity_key = True
            elif ref_cols:
                # Preserve deterministic same-row expressions when GROUP BY
                # already uses the table's own entity key.
                ref_source_tables: Set[str] = set()
                unresolved_ref_scope = False
                only_table = next(iter(table_names)) if len(table_names) == 1 else ""
                for rc in ref_cols:
                    rc_table = str(rc.table or "").strip("`").lower()
                    if rc_table:
                        resolved_rc_table = alias_to_table.get(rc_table, rc_table)
                        if not resolved_rc_table:
                            unresolved_ref_scope = True
                            break
                        ref_source_tables.add(resolved_rc_table)
                    elif only_table:
                        ref_source_tables.add(only_table)
                    else:
                        unresolved_ref_scope = True
                        break
                if not unresolved_ref_scope and len(ref_source_tables) == 1:
                    only_ref_table = next(iter(ref_source_tables))
                    if only_ref_table in entity_key_sources:
                        preserve_via_entity_key = True

            # Preserve deterministic computed expressions when ALL referenced
            # columns are already covered by GROUP BY.
            refs_all_in_group = False
            if ref_cols:
                all_grouped = True
                for rc in ref_cols:
                    rc_name = str(rc.name or "").strip("`").lower()
                    rc_table = str(rc.table or "").strip("`").lower()
                    if not rc_name:
                        all_grouped = False
                        break
                    cands = {rc_name}
                    if rc_table:
                        cands.add(f"{rc_table}.{rc_name}")
                        resolved_rc_table = alias_to_table.get(rc_table, rc_table)
                        if resolved_rc_table:
                            cands.add(f"{resolved_rc_table}.{rc_name}")
                    if len(table_names) == 1:
                        only_table = next(iter(table_names))
                        cands.add(f"{only_table}.{rc_name}")
                    if not any(c in group_set for c in cands):
                        all_grouped = False
                        break
                refs_all_in_group = all_grouped

            if (
                base_sql not in group_set
                and not alias_in_groupby
                and not preserve_via_entity_key
                and not refs_all_in_group
            ):
                expressions_to_remove.append(item)

        if expressions_to_remove:
            new_expressions = [e for e in sel.expressions if e not in expressions_to_remove]
            sel.set("expressions", new_expressions)
            return ast.sql(dialect="mysql")
        return sql

    except Exception:
        # FALLBACK: Use regex when sqlglot fails (syntax errors, etc.)
        # This handles cases where SQL has minor syntax issues
        if "GROUP BY" not in sql.upper():
            return sql
        # Safety: for queries with subqueries, regex fallback can grab inner GROUP BY
        # and corrupt top-level SELECT. Skip fallback in that case.
        if re.search(r"\b(?:FROM|JOIN)\s*\(", sql, flags=re.I):
            return sql

        # Extract GROUP BY clause
        gb_match = re.search(r'\bGROUP\s+BY\s+(.*?)(?=\s*(?:ORDER\s+BY|HAVING|LIMIT|;|$))', sql, re.IGNORECASE | re.DOTALL)
        if not gb_match:
            return sql

        group_clause = gb_match.group(1).strip()

        # Helper: split by top-level commas (not inside parentheses)
        def split_top_level_commas(clause):
            items = []
            current = []
            depth = 0
            for char in clause:
                if char == '(':
                    depth += 1
                    current.append(char)
                elif char == ')':
                    depth -= 1
                    current.append(char)
                elif char == ',' and depth == 0:
                    items.append(''.join(current).strip())
                    current = []
                else:
                    current.append(char)
            if current:
                items.append(''.join(current).strip())
            return [i for i in items if i]

        group_items = split_top_level_commas(group_clause)
        # For each GROUP BY item, extract the base expression (before AS, if any)
        group_base_expressions = []
        for item in group_items:
            # Remove AS alias if present
            as_match = re.search(r'\s+AS\s+(?:[\w"]+|"[^"]*"|\'[^\']*\'|`[^`]*`)\s*$', item, re.IGNORECASE)
            if as_match:
                base = item[:as_match.start()].strip()
            else:
                base = item.strip()
            group_base_expressions.append(base.lower())

        group_set = set(group_base_expressions)

        # Extract SELECT clause
        select_match = re.search(r'\bSELECT\s+(.*?)\s+FROM', sql, re.IGNORECASE | re.DOTALL)
        if not select_match:
            return sql

        select_clause = select_match.group(1).strip()
        select_items = split_top_level_commas(select_clause)
        agg_funcs = {'COUNT', 'SUM', 'AVG', 'MIN', 'MAX', 'DATEDIFF', 'DATE_ADD', 'TIMESTAMPDIFF',
                     'DATE_FORMAT', 'YEAR', 'MONTH', 'DAY', 'CONCAT', 'IF', 'IFNULL', 'COALESCE'}

        from_match = re.search(
            r"\bFROM\s+(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?)(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?\s+GROUP\s+BY\b",
            sql,
            flags=re.I | re.S,
        )
        base_table = ""
        base_alias = ""
        entity_key_grouped = False
        if from_match:
            base_table = str(from_match.group("table") or "").strip("`").lower()
            base_alias = str(from_match.group("alias") or "").strip("`").lower() or base_table
            try:
                id_col = str(get_id_column(base_table) or "").strip("`").lower()
            except Exception:
                id_col = ""
            if id_col:
                norm_group = {g.replace("`", "").replace(" ", "").lower() for g in group_set}
                entity_key_grouped = any(
                    cand in norm_group
                            for cand in {
                                id_col,
                                f"{base_table}.{id_col}",
                                f"{base_alias}.{id_col}",
                            }
                        )

        if entity_key_grouped and base_table and "HAVING" not in sql.upper():
            has_agg_or_window = False
            same_row_projection = True
            for item in select_items:
                as_match = re.search(r'\s+AS\s+(?:[\w"]+|"[^"]*"|\'[^\']*\'|`[^`]*`)\s*$', item, re.IGNORECASE)
                if as_match:
                    base = item[:as_match.start()].strip()
                else:
                    base = item.strip()

                func_match = re.match(r'(\w+)\s*\(', base)
                if func_match and func_match.group(1).upper() in agg_funcs:
                    has_agg_or_window = True
                    break
                if re.search(r'\bOVER\s*\(', base, re.IGNORECASE):
                    has_agg_or_window = True
                    break

                ref_cols = [
                    ref.lower()
                    for ref in re.findall(
                        r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?",
                        base,
                        flags=re.I,
                    )
                    if ref and not re.fullmatch(r"`?(?:as|case|when|then|else|end)`?", ref.strip(), flags=re.I)
                ]
                for ref in ref_cols:
                    ref_n = ref.replace("`", "").replace(" ", "").lower()
                    if "." in ref_n:
                        ref_table = ref_n.split(".", 1)[0]
                        if ref_table not in {base_table, base_alias}:
                            same_row_projection = False
                            break
                if not same_row_projection:
                    break

            if not has_agg_or_window and same_row_projection:
                fixed = (sql[:gb_match.start()] + sql[gb_match.end():]).strip()
                fixed = re.sub(r"\s{2,}", " ", fixed)
                return fixed

        # Rebuild SELECT, removing items that are NOT in GROUP BY (except aggregates/windows)
        new_select_parts = []

        for item in select_items:
            # Extract base expression (before AS)
            as_match = re.search(r'\s+AS\s+(?:[\w"]+|"[^"]*"|\'[^\']*\'|`[^`]*`)\s*$', item, re.IGNORECASE)
            if as_match:
                base = item[:as_match.start()].strip()
                alias = as_match.group(0).replace('AS', '').strip().strip('"\'`')
            else:
                base = item.strip()
                alias = None

            base_lower = base.lower()

            # Check if it's an aggregate or window function
            is_aggregate = False
            func_match = re.match(r'(\w+)\s*\(', base)
            if func_match:
                func_name = func_match.group(1).upper()
                if func_name in agg_funcs:
                    is_aggregate = True

            is_window = bool(re.search(r'\bOVER\s*\(', base, re.IGNORECASE))
            # Check if it's a CASE expression (should always be kept)
            is_case = bool(re.search(r'\bCASE\s+WHEN\b', base, re.IGNORECASE))

            # Preserve deterministic computed expressions when all referenced
            # columns are covered by GROUP BY.
            refs_all_in_group = False
            preserve_via_entity_key = False
            ref_cols = [
                ref.lower()
                for ref in re.findall(
                    r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?",
                    base,
                    flags=re.I,
                )
                if ref and not re.fullmatch(r"`?(?:as|case|when|then|else|end)`?", ref.strip(), flags=re.I)
            ]
            if ref_cols:
                norm_group = {g.replace("`", "").replace(" ", "").lower() for g in group_set}
                all_grouped = True
                for ref in ref_cols:
                    ref_n = ref.replace("`", "").replace(" ", "").lower()
                    if "." in ref_n:
                        cands = {ref_n, ref_n.split(".")[-1]}
                    else:
                        cands = {ref_n}
                    if not any(c in norm_group for c in cands):
                        all_grouped = False
                        break
                refs_all_in_group = all_grouped
                if not refs_all_in_group and entity_key_grouped:
                    same_table_refs = True
                    for ref in ref_cols:
                        ref_n = ref.replace("`", "").replace(" ", "").lower()
                        if "." in ref_n:
                            ref_table = ref_n.split(".", 1)[0]
                            if ref_table not in {base_table, base_alias}:
                                same_table_refs = False
                                break
                    preserve_via_entity_key = same_table_refs

            # Keep if: aggregate, window, CASE, base in GROUP BY, alias in GROUP BY,
            # or all referenced columns are grouped.
            # MySQL allows GROUP BY alias, so check both base expression and alias.
            alias_in_groupby = alias and alias.lower() in group_set if alias else False
            if (
                is_aggregate
                or is_window
                or is_case
                or base_lower in group_set
                or alias_in_groupby
                or refs_all_in_group
                or preserve_via_entity_key
            ):
                new_select_parts.append(item)
            # Otherwise, remove it (hallucinated column)

        if new_select_parts:
            new_select = ', '.join(new_select_parts)
            sql = sql[:select_match.start(1)] + new_select + sql[select_match.end(1):]

        return sql
# =======================================================================
# ============ Phase 4 — Winner-Row & Aggregate Guardrails ==============
# ======= Ensure semantic correctness for ranking-style queries =========
# =======================================================================
# - winner_row_sanity_date_in_groupby
# - strip_having_max_self_subquery
# - looks_like_max_date_tiebreaker
# - question_wants_winner_row
# - split_top_level_commas
# - extract_alias_or_colname
# - maybe_keep_or_alias_simple
# - parse_select_from_groupby
# - to_raw_expr
# - looks_like_winner_row_multi_agg
# - strip_table_prefix
# - rewrite_winner_row_guardrail
# - rewrite_having_alias_to_expr
# - winner_row_final_sanity
# - force_restore_groupby_if_aggregate_without_groupby

def _winner_row_sanity_date_in_groupby(sql: str, question: str) -> str:
    if not sql or not _question_wants_winner_row(question):
        return sql

    if re.search(r"\bROW_NUMBER\s*\(", sql, flags=re.I):
        return sql

    s = sql.lower()

    # only flag suspicious — do NOT modify query
    if "group by" not in s:
        return sql

    if not re.search(r"\b(max|min)\s*\(", s):
        return sql

    # if GROUP BY contains date column → risky aggregate misuse
    gb = re.search(
        r"\bgroup\s+by\s+(.*?)(?=(\border\s+by\b|\bhaving\b|\blimit\b|;|$))",
        sql,
        flags=re.I | re.S,
    )

    if gb and re.search(r"\b\w*date\w*\b", gb.group(1), flags=re.I):
        # do NOT rewrite — only let guardrail force rewrite later
        return sql

    return sql

def _strip_having_max_self_subquery(sql: str) -> str:
    """
    Remove HAVING MAX(x) = (SELECT MAX(x) ...) pattern.
    Two-pass: first normalize spacing, then remove.
    """
    if not sql:
        return sql
    
    # Pass 1: Normalize spacing around HAVING
    sql = re.sub(r"\s*\bHAVING\b\s*", " HAVING ", sql, flags=re.I)
    
    # Pass 2: Remove the HAVING clause if it matches winner-row hack pattern
    # Pattern: HAVING MAX(...) = (SELECT MAX(...) ...)
    pat = re.compile(
        r"\s+HAVING\s+MAX\s*\([^)]+\)\s*=\s*\(\s*SELECT\s+MAX\s*\([^)]+\)[^)]+\)",
        flags=re.I | re.S
    )
    
    if pat.search(sql):
        # Remove the HAVING clause
        sql = pat.sub(" ", sql)
        
        # Clean up multiple spaces
        sql = re.sub(r"\s{2,}", " ", sql)
    
    return sql

def _looks_like_max_date_tiebreaker(sql: str) -> bool:
    """
    Deteksi pattern sangat spesifik yang PASTI winner-row misuse:
    - Multiple MAX() dimana salah satunya adalah date-like
    - ATAU: HAVING dengan MAX = subquery self-join hack
    
    Ini dipakai untuk FORCE MODE, jadi harus sangat konservatif.
    """
    s = sql.lower()

    # must be aggregate query
    if "group by" not in s:
        return False

    # must involve MAX() 
    if "max(" not in s:
        return False

    # Count berapa banyak MAX()
    max_count = len(re.findall(r"\bmax\s*\(", s, flags=re.I))

    # ===== SIGNAL 1: Multiple MAX() with date-like (very suspicious) =====
    if max_count >= 2:
        date_like = re.compile(
            r"max\s*\([^)]*date[^)]*\)",
            re.I,
        )
        if date_like.search(s):
            return True

    # ===== SIGNAL 2: HAVING with MAX = subquery (classic hack) =====
    if re.search(r"\bhaving\s+max\s*\(", s):
        return True

    # ===== SIGNAL 3: Multiple MAX() on different semantic types =====
    # e.g., MAX(amount), MAX(paymentDate) - clearly trying to get row attributes
    if max_count >= 2:
        # Check if we have value-like and date-like columns
        metric_alt = _winner_row_metric_alt()
        has_value = bool(
            metric_alt != r"$^"
            and re.search(rf"max\s*\([^)]*{metric_alt}[^)]*\)", s, flags=re.I)
        )
        has_date = bool(re.search(
            r"max\s*\([^)]*date[^)]*\)",
            s, flags=re.I
        ))
        if has_value and has_date:
            return True

    return False

def _question_wants_winner_row(question: str) -> bool:
    """
    True jika pertanyaan meminta nilai terbesar/terkecil dan juga meminta atribut lain
    yang harus berasal dari baris yang sama (mis. tanggal kejadian).
    
    Contoh POSITIF (winner-row):
      - "largest payment and its payment date"
      - "highest amount and when it occurred"
      - "pembayaran terbesar dan tanggalnya"
      - "customer with highest payment and when they paid"
    
    Contoh NEGATIF (true aggregation):
      - "largest payment per customer" (hanya minta nilai, bukan atribut baris)
      - "total pembayaran terbesar" (aggregate, bukan row selection)
      - "berapa pembayaran tertinggi" (hanya minta nilai max)
    """
    q = (question or "").lower()
    # Ignore trailing output-order instructions so phrases like
    # "ordered by amount from highest to lowest" do not get misread as a
    # winner-row intent. Winner-row should come from the main ask, not from
    # display ordering.
    q_core = re.sub(
        r"\b(?:sort(?:ed)?|order(?:ed)?)\s+"
        r"(?:the\s+results?|the\s+result|results?|result|output|rows)?\s*"
        r"(?:by|from)\b.*$",
        "",
        q,
        flags=re.I,
    ).strip()
    q_core = re.sub(
        r"\b(?:starting|beginning|going)\s+from\s+the\s+"
        r"(?:highest|lowest|latest|earliest|newest|oldest)\b.*$",
        "",
        q_core,
        flags=re.I,
    ).strip()
    if not q_core:
        q_core = q

    # Quantifier phrases like "at least one" / "at most ten" are threshold
    # cues, not ranking cues. Remove them before scanning rank terms so
    # aggregate/report questions are not misclassified as winner-row asks just
    # because they contain the token "least" or "most".
    q_rank_scope = re.sub(
        r"\bat\s+(?:least|most)\b",
        "",
        q_core,
        flags=re.I,
    ).strip()
    if not q_rank_scope:
        q_rank_scope = q_core

    explicit_rank_sig = bool(
        re.search(r"\b(?:rank|ranking|ranked)\b", q_rank_scope, flags=re.I)
    )
    # Keep single-pick detection narrow.
    # Generic verbs like "keep" or "select" frequently appear in grouped
    # aggregate/report questions ("keep only job titles with at least 2 employees")
    # and should not by themselves force winner-row behavior.
    explicit_single_pick_sig = bool(
        re.search(
            r"\b(?:pick|choose|winner|top\s*1|bottom\s*1|single)\b",
            q_rank_scope,
            flags=re.I,
        )
        or re.search(
            r"\bselect\s+(?:the\s+)?(?:one|single|winner|top\s*1|bottom\s*1)\b",
            q_rank_scope,
            flags=re.I,
        )
        or re.search(
            r"\bkeep\s+(?:only\s+)?(?:the\s+)?"
            r"(?:one|single|winner|top\s*1|bottom\s*1|latest|newest|earliest|oldest|highest|lowest|largest|smallest|best|worst)\b",
            q_rank_scope,
            flags=re.I,
        )
    )
    # Pure ranking asks like "rank employees ..." or "return product code, name,
    # and rank them by total sales value" are not winner-row asks. They want a
    # full ranking window, not ROW_NUMBER()/rn=1 filtering.
    if explicit_rank_sig and not explicit_single_pick_sig:
        return False

    winner_rank_term_alt = _regex_alt_from_terms(
        {str(term).strip().lower() for term in winner_row_rank_terms() if str(term).strip()},
        r"$^",
    )
    rank_sig = bool(
        winner_rank_term_alt != r"$^"
        and re.search(rf"\b(?:{winner_rank_term_alt})\b", q_rank_scope, flags=re.I)
    )

    if not rank_sig:
        return False

    grouped_report_term_alt = _regex_alt_from_terms(
        {str(term).strip().lower() for term in winner_row_grouped_report_terms() if str(term).strip()},
        r"$^",
    )
    grouped_report_sig = bool(
        grouped_report_term_alt != r"$^"
        and re.search(
            rf"\b(?:{grouped_report_term_alt})\b.{{0,100}}\bby\b",
            q_rank_scope,
            flags=re.I | re.S,
        )
    )
    row_object_term_alt = _regex_alt_from_terms(
        {str(term).strip().lower() for term in winner_row_row_object_terms() if str(term).strip()},
        r"$^",
    )
    row_object_after_rank_sig = bool(
        winner_rank_term_alt != r"$^"
        and row_object_term_alt != r"$^"
        and re.search(
            rf"\b(?:{winner_rank_term_alt})\b.{{0,80}}\b(?:{row_object_term_alt})\b",
            q_rank_scope,
            flags=re.I | re.S,
        )
    )

    reporting_verb_alt = _regex_alt_from_terms(
        {str(term).strip().lower() for term in winner_row_reporting_verbs() if str(term).strip()},
        r"$^",
    )
    explicit_multirow_rank_sig = bool(
        reporting_verb_alt != r"$^"
        and re.search(
            rf"\b(?:{reporting_verb_alt})\s+(?:the\s+)?(?:top\s+)?(?:[2-9]|\d{{2,}})\b",
            q_rank_scope,
        )
    )
    # Also treat bare global top/bottom-N asks as multi-row ranking, even when
    # they do not start with a reporting verb.
    explicit_multirow_rank_sig = explicit_multirow_rank_sig or bool(
        re.search(r"^\s*(?:the\s+)?(?:top|bottom)\s+\d+\b", q_rank_scope, flags=re.I)
        or re.search(
            r"^\s*\d+\s+(?:highest|lowest|largest|smallest|newest|latest|earliest|oldest|most|least)\b",
            q_rank_scope,
            flags=re.I,
        )
    )

    # Sinyal 1: eksplisit minta atribut dari "baris yang sama"
    same_row_sig = any_phrase_in_text(q_rank_scope, winner_row_same_row_terms())

    # Sinyal 2: minta informasi temporal/kontekstual
    generic_context_sig = any_phrase_in_text(q_rank_scope, winner_row_context_terms())
    schema_temporal_context_sig = _question_mentions_any_phrase(
        q_rank_scope,
        _winner_row_schema_temporal_phrases(),
    )
    context_sig = generic_context_sig or schema_temporal_context_sig

    # Sinyal 3: pola "X and Y" atau "X with Y" (multi-attribute request)
    multi_attr_connector_alt = _regex_alt_from_terms(
        {str(term).strip().lower() for term in winner_row_multi_attr_connectors() if str(term).strip()},
        r"$^",
    )
    multi_attr_sig = bool(
        winner_rank_term_alt != r"$^"
        and multi_attr_connector_alt != r"$^"
        and re.search(
            rf"\b(?:{winner_rank_term_alt})\b\s+\w+\s+\b(?:{multi_attr_connector_alt})\b\s+",
            q_rank_scope,
            flags=re.I,
        )
    )

    tie_sig = any_phrase_in_text(q_rank_scope, winner_row_tie_terms())

    # Guard: comparative grouped-aggregate phrasing like
    # "for every X ... highest ... within the same Y" is usually a full-population
    # report (window/baseline comparison), not winner-row filtering.
    comparative_group_aggregate_sig = bool(
        re.search(r"\bfor\s+(?:every|each)\b", q_rank_scope, flags=re.I)
        and re.search(r"\bwithin\s+the\s+same\b", q_rank_scope, flags=re.I)
        and any_phrase_in_text(q_rank_scope, winner_row_aggregate_metric_terms())
    )
    if comparative_group_aggregate_sig and not explicit_single_pick_sig and not tie_sig:
        return False

    per_group_sig = bool(
        rank_sig
        and re.search(r"\b(?:for\s+each|per|each)\b", q_rank_scope)
    )

    # Display-order phrasing should stay as ORDER BY semantics, not winner-row.
    # Example: "put the largest scale at the top".
    display_order_only_sig = bool(
        re.search(r"\b(?:at|on)\s+the\s+(?:top|bottom)\b", q_rank_scope, flags=re.I)
        or re.search(
            r"\b(?:starting|beginning)\s+from\s+the\s+"
            r"(?:highest|lowest|largest|smallest|greatest|least|latest|earliest)\b",
            q_rank_scope,
            flags=re.I,
        )
    )
    if (
        display_order_only_sig
        and not per_group_sig
        and not tie_sig
        and not explicit_single_pick_sig
        and not row_object_after_rank_sig
    ):
        return False

    # Guard: explicit top-N / multi-row ranking asks are not winner-row asks.
    # Example: "Show the 10 products with the highest stock levels".
    # These should stay as ORDER BY ... LIMIT N, not ROW_NUMBER() winner-row.
    if explicit_multirow_rank_sig and not tie_sig and not per_group_sig:
        return False

    # Grouped summary/report questions can mention "largest" / "smallest"
    # simply as MAX/MIN aggregate outputs. Do not classify them as winner-row
    # unless the question asks for a concrete row/object attribute after the
    # superlative (for example date, code, name, row, or record).
    if grouped_report_sig and not explicit_single_pick_sig and not tie_sig and not row_object_after_rank_sig:
        return False

    strong_winner_sig = rank_sig and (same_row_sig or context_sig or multi_attr_sig or tie_sig or per_group_sig)

    # Guard: "total"/"count" usually means pure aggregation, but do not suppress
    # clear winner-row asks like "best-selling product for each product line"
    # or tie-break questions.
    if (
        any(str(k).strip().lower() in q_rank_scope for k in winner_row_aggregate_guard_terms())
        and not strong_winner_sig
    ):
        return False

    # Guard: group-by reports listing multiple aggregate metrics (COUNT, MAX, MIN, AVG …)
    # are NOT winner-row queries.  E.g. "For each vendor, show how many products
    # they have, the highest MSRP, and the lowest buy price" → GROUP BY + COUNT/MAX/MIN.
    # A genuine winner-row ask typically names one superlative metric + row attributes,
    # not a full report with 3+ aggregate keywords.
    if per_group_sig and not tie_sig and not explicit_single_pick_sig:
        _metric_keys = winner_row_grouped_report_metric_terms()
        _metric_count = sum(1 for k in _metric_keys if k in q_rank_scope)
        if _metric_count >= 3:
            return False

    # Winner-row jika ada rank + (same_row ATAU context ATAU multi_attr)
    return strong_winner_sig


def _rewrite_explicit_rank_aggregate_window(sql: str, question: str) -> str:
    """
    Repair malformed explicit ranking queries that rank raw joined rows when the
    question actually asks to rank grouped entities by an aggregate metric.

    Example target family:
      - "rank products by total sales value"
      - "return employee, department, and rank them by total amount"

    Conservative trigger:
    - question explicitly asks for rank/ranking
    - SQL uses RANK()/DENSE_RANK() OVER (ORDER BY ...) with no PARTITION BY
    - SQL does not already contain GROUP BY
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not re.search(r"\b(?:rank|ranking|ranked)\b", q, flags=re.I):
        return sql

    s = sql.strip().rstrip(";").strip()
    if not s or re.search(r"\bGROUP\s+BY\b", s, flags=re.I):
        return sql

    rank_match = re.search(
        r"""(?is)\b(?P<fn>RANK|DENSE_RANK)\s*\(\s*\)\s*OVER\s*\(\s*(?P<window>.*?)\s*\)\s+AS\s+(?P<alias>`[^`]+`|[A-Za-z_][A-Za-z0-9_]*)""",
        s,
    )
    if not rank_match:
        return sql

    window_part = (rank_match.group("window") or "").strip()
    if not window_part or re.search(r"\bPARTITION\s+BY\b", window_part, flags=re.I):
        return sql

    order_match = re.match(
        r"""(?is)^\s*ORDER\s+BY\s+(?P<expr>.*?)\s*$""",
        window_part,
    )
    if not order_match:
        return sql

    order_expr_full = (order_match.group("expr") or "").strip()
    if not order_expr_full:
        return sql

    select_from_match = re.match(
        r"""(?is)^\s*SELECT\s+(?P<select>.*?)\s+FROM\s+(?P<from>.*?)(?:\s+WHERE\s+(?P<where>.*?))?\s*$""",
        s,
    )
    if not select_from_match:
        return sql

    select_part = (select_from_match.group("select") or "").strip()
    from_part = (select_from_match.group("from") or "").strip()
    where_part = (select_from_match.group("where") or "").strip()
    if not select_part or not from_part:
        return sql

    select_items = _split_top_level_commas(select_part)
    if len(select_items) < 2:
        return sql

    rank_alias = (rank_match.group("alias") or "").strip().strip("`")
    dim_items: List[str] = []
    seen_dim_norms: Set[str] = set()
    for item in select_items:
        item_clean = (item or "").strip()
        if not item_clean:
            continue
        if re.search(r"\b(?:RANK|DENSE_RANK)\s*\(", item_clean, flags=re.I):
            continue
        item_norm = re.sub(r"\s+", " ", item_clean).strip().lower()
        if item_norm in seen_dim_norms:
            continue
        seen_dim_norms.add(item_norm)
        dim_items.append(item_clean)

    if not dim_items:
        return sql

    desc = bool(re.search(r"\bDESC\s*$", order_expr_full, flags=re.I))
    bare_order_expr = re.sub(r"\s+(?:ASC|DESC)\s*$", "", order_expr_full, flags=re.I).strip()
    if not bare_order_expr:
        return sql
    if re.search(r"\b(?:SUM|COUNT|AVG|MIN|MAX)\s*\(", bare_order_expr, flags=re.I):
        agg_order_expr = bare_order_expr
    elif re.search(r"\b(?:average|avg|mean)\b", q, flags=re.I):
        agg_order_expr = f"AVG({bare_order_expr})"
    elif re.search(r"\b(?:count|how many|number of)\b", q, flags=re.I):
        agg_order_expr = f"COUNT({bare_order_expr})"
    else:
        sum_metric_alt = _configured_metric_alt(
            HELPERS_METRIC_AGG_INTENT_TERMS,
            HELPERS_DUAL_FACT_GENERIC_METRIC_TERMS,
            HELPERS_ROLLUP_LEGACY_METRIC_TERMS,
        )
        if sum_metric_alt != r"$^" and re.search(rf"\b{sum_metric_alt}\b", q, flags=re.I):
            agg_order_expr = f"SUM({bare_order_expr})"
        else:
            return sql

    rank_alias_sql = re.search(r"\bAS\s+(.+)$", rank_match.group(0) or "", flags=re.I)
    rank_alias_sql = (rank_alias_sql.group(1).strip() if rank_alias_sql else f"`{rank_alias}`")
    rebuilt = (
        f"SELECT {', '.join(dim_items)}, "
        f"{rank_match.group('fn').upper()}() OVER (ORDER BY {agg_order_expr} {'DESC' if desc else 'ASC'}) AS {rank_alias_sql} "
        f"FROM {from_part}"
    )
    if where_part:
        rebuilt += f" WHERE {where_part}"
    rebuilt += f" GROUP BY {', '.join(dim_items)};"
    return rebuilt


def _fix_grouped_aggregate_rank_direction(sql: str, question: str) -> str:
    """
    For grouped aggregate ranking, rank 1 conventionally means the largest
    aggregate metric unless the question explicitly asks for the lowest side.
    Final output sorting such as "sort by rank ascending" must not flip the
    metric direction inside DENSE_RANK()/RANK().
    """
    if not sql or not question:
        return sql
    if not re.search(r"\b(?:RANK|DENSE_RANK)\s*\(", sql, flags=re.I):
        return sql
    if not re.search(r"\bGROUP\s+BY\b", sql, flags=re.I):
        return sql

    q = str(question or "").strip().lower()
    if not re.search(r"\b(?:rank|ranking|ranked)\b", q, flags=re.I):
        return sql

    # Remove final-output rank sorting cues before inferring the metric
    # direction. "Sort by rank ascending" orders the result rows, not revenue.
    q_metric = re.sub(
        r"\b(?:sort|sorted|order|ordered|arrange|arranged)\s+(?:the\s+)?"
        r"(?:final\s+)?(?:result|results|output|rows?)?\s*by\s+"
        r"(?:dense\s+)?rank\b[^.?!;]*",
        " ",
        q,
        flags=re.I,
    )
    q_metric = re.sub(
        r"\b(?:sort|order|arrange)\s+by\s+(?:dense\s+)?rank\b[^.?!;]*",
        " ",
        q_metric,
        flags=re.I,
    )

    low_side_cue = bool(
        re.search(r"\b(?:lowest|smallest|minimum|min|fewest|ascending)\b", q_metric, flags=re.I)
        or re.search(r"(?<!\bat\s)\bleast\b", q_metric, flags=re.I)
    )
    wants_low_rank = bool(
        low_side_cue
        and (
            (
                metric_alt := _winner_row_metric_alt()
            ) != r"$^"
            and re.search(rf"\b{metric_alt}\b", q_metric, flags=re.I)
        )
    )
    target_dir = "ASC" if wants_low_rank else "DESC"

    rank_window_pat = re.compile(
        r"""(?is)
        \b(?P<fn>RANK|DENSE_RANK)\s*\(\s*\)\s*
        OVER\s*\(\s*ORDER\s+BY\s+
        (?P<expr>(?:SUM|COUNT|AVG|MIN|MAX)\s*\((?:[^()]|\([^()]*\))*\))
        (?:\s+(?P<dir>ASC|DESC))?
        \s*\)
        """,
        flags=re.X,
    )

    def _repl(m: re.Match) -> str:
        expr = (m.group("expr") or "").strip()
        current_dir = (m.group("dir") or "").strip().upper()
        if not expr:
            return m.group(0)
        if current_dir == target_dir:
            return m.group(0)
        return f"{m.group('fn').upper()}() OVER (ORDER BY {expr} {target_dir})"

    return rank_window_pat.sub(_repl, sql)


def _rewrite_no_skip_rank_to_dense_rank(sql: str, question: str) -> str:
    """
    Convert RANK() to DENSE_RANK() only when the question explicitly says the
    next rank should not skip after ties. This keeps normal competition-rank
    semantics untouched.
    """
    if not sql or not question:
        return sql
    q = str(question or "").lower()
    if not re.search(r"\brank", q, flags=re.I):
        return sql
    no_skip_rank = bool(
        re.search(r"\bwithout\s+skipping\b", q, flags=re.I)
        or re.search(r"\b(?:does\s+not|doesn't|do\s+not|don't|not)\s+skip\b", q, flags=re.I)
        or re.search(r"\bno\s+skipp?ing\b", q, flags=re.I)
        or re.search(r"\bdense\s+rank\b", q, flags=re.I)
    )
    if not no_skip_rank:
        return sql
    return re.sub(r"\b(?:ROW_NUMBER|RANK)\s*\(\s*\)", "DENSE_RANK()", sql, flags=re.I)


def _repair_rank_window_partition_from_question(sql: str, question: str) -> str:
    """
    Add a missing PARTITION BY to ranking windows when the question explicitly
    scopes the rank/position "inside/within each <group>" and the group column
    is already projected by the query.
    """
    if not sql or not question:
        return sql
    if not re.search(r"\b(?:ROW_NUMBER|RANK|DENSE_RANK)\s*\(", sql, flags=re.I):
        return sql
    q = str(question or "").lower()
    if not re.search(r"\b(?:rank|ranking|position|number)\b", q, flags=re.I):
        return sql

    group_terms = _extract_rank_partition_terms_from_question(q)
    if not group_terms:
        return sql

    select_part = _extract_top_level_select_list(sql)
    if not select_part:
        return sql
    candidates = _rank_partition_candidates_from_select(select_part)
    if not candidates:
        return sql

    partition_expr = _choose_rank_partition_expr(candidates, group_terms)
    if not partition_expr:
        return sql

    def _rewrite_window(match: re.Match[str]) -> str:
        fn = match.group("fn")
        body = (match.group("body") or "").strip()
        if re.search(r"\bPARTITION\s+BY\b", body, flags=re.I):
            return match.group(0)
        if not re.search(r"\bORDER\s+BY\b", body, flags=re.I):
            return match.group(0)
        return f"{fn}() OVER (PARTITION BY {partition_expr} {body})"

    return re.sub(
        r"(?is)\b(?P<fn>ROW_NUMBER|RANK|DENSE_RANK)\s*\(\s*\)\s*OVER\s*\(\s*(?P<body>[^()]*)\)",
        _rewrite_window,
        sql,
    )


def _repair_rank_window_metric_from_question(sql: str, question: str) -> str:
    """
    Repair the metric used inside a non-winner-row RANK/DENSE_RANK window when
    the question explicitly says to rank "by <metric>".

    Conservative scope:
    - only for RANK()/DENSE_RANK() windows
    - only when the question explicitly contains a rank-by metric phrase
    - only uses simple projected columns already visible in the SELECT list
    - never changes the partition key itself
    """
    if not sql or not question:
        return sql
    if not re.search(r"\b(?:RANK|DENSE_RANK)\s*\(", sql, flags=re.I):
        return sql

    q = str(question or "").strip().lower()
    if not q or not re.search(r"\b(?:rank|ranking|ranked)\b", q, flags=re.I):
        return sql
    if _question_wants_winner_row(question):
        return sql

    metric_terms: Set[str] = set()
    metric_patterns = [
        r"\b(?:rank|ranking|ranked)\b[\s\S]{0,120}?\bby\s+(?P<seg>[a-z0-9_\s-]{1,64}?)(?=\s+(?:from|highest|lowest|descending|ascending|if|where|when|return|show|list|final|output|result|sort|order)\b|[,.;]|$)",
        r"\bby\s+(?P<seg>[a-z0-9_\s-]{1,64}?)\s+(?:from\s+highest\s+to\s+lowest|from\s+lowest\s+to\s+highest|descending|ascending)\b",
    ]
    for pat in metric_patterns:
        m = re.search(pat, q, flags=re.I | re.S)
        if not m:
            continue
        metric_terms = _rank_text_terms(m.group("seg") or "")
        if metric_terms:
            break
    if not metric_terms:
        return sql

    select_part = _extract_top_level_select_list(sql)
    if not select_part:
        return sql
    candidates = _rank_partition_candidates_from_select(select_part)
    if not candidates:
        return sql

    partition_terms = _extract_rank_partition_terms_from_question(q)
    partition_expr = _choose_rank_partition_expr(candidates, partition_terms) if partition_terms else ""
    order_candidates = [
        (expr, terms)
        for expr, terms in candidates
        if not partition_expr or _normalize_sql_expr_for_match(expr) != _normalize_sql_expr_for_match(partition_expr)
    ]
    if not order_candidates:
        return sql

    scored: List[Tuple[int, int, str]] = []
    for expr, terms in order_candidates:
        overlap = terms & metric_terms
        if not overlap:
            continue
        extra_penalty = len(terms - metric_terms)
        scored.append((len(overlap), -extra_penalty, expr))
    if not scored:
        return sql
    scored.sort(key=lambda item: (item[0], item[1]), reverse=True)
    target_expr = scored[0][2]

    wants_desc = None
    if re.search(r"\b(?:highest|largest|greatest|descending|high\s+to\s+low)\b", q, flags=re.I) or re.search(r"\bfrom\s+highest\s+to\s+lowest\b", q, flags=re.I):
        wants_desc = True
    if re.search(r"\b(?:lowest|smallest|least|ascending|low\s+to\s+high)\b", q, flags=re.I) or re.search(r"\bfrom\s+lowest\s+to\s+highest\b", q, flags=re.I):
        wants_desc = False if wants_desc is None else wants_desc

    window_pat = re.compile(
        r"(?is)\b(?P<fn>RANK|DENSE_RANK)\s*\(\s*\)\s*OVER\s*\(\s*(?P<body>[^()]*)\)"
    )

    def _rewrite_window(match: re.Match[str]) -> str:
        body = str(match.group("body") or "").strip()
        if not body or not re.search(r"\bORDER\s+BY\b", body, flags=re.I):
            return match.group(0)

        part_match = re.search(r"(?is)\bPARTITION\s+BY\s+(?P<part>.+?)\s+ORDER\s+BY\s+(?P<order>.+?)\s*$", body)
        if part_match:
            part_expr = str(part_match.group("part") or "").strip()
            order_expr = str(part_match.group("order") or "").strip()
            head = f"PARTITION BY {part_expr} ORDER BY "
        else:
            order_match = re.search(r"(?is)\bORDER\s+BY\s+(?P<order>.+?)\s*$", body)
            if not order_match:
                return match.group(0)
            order_expr = str(order_match.group("order") or "").strip()
            head = "ORDER BY "

        current_items = [x.strip() for x in _split_top_level_commas(order_expr) if x.strip()]
        current_dir = ""
        if current_items:
            m_dir = re.search(r"\b(ASC|DESC)\b\s*$", current_items[0], flags=re.I)
            if m_dir:
                current_dir = m_dir.group(1).upper()
        target_dir = "DESC" if wants_desc is True else "ASC" if wants_desc is False else current_dir

        current_norms = {
            _normalize_sql_expr_for_match(re.sub(r"\s+\b(?:ASC|DESC)\b\s*$", "", item, flags=re.I))
            for item in current_items
        }
        target_norm = _normalize_sql_expr_for_match(target_expr)
        if target_norm in current_norms and ((not target_dir) or any(re.search(rf"\b{target_dir}\b\s*$", item, flags=re.I) for item in current_items)):
            return match.group(0)

        rebuilt_order = target_expr + (f" {target_dir}" if target_dir else "")
        return f"{match.group('fn').upper()}() OVER ({head}{rebuilt_order})"

    return window_pat.sub(_rewrite_window, sql)


def _add_rank_value_nonnull_filter_from_question(sql: str, question: str) -> str:
    """
    Add an IS NOT NULL filter for ranking questions phrased as
    "rows with a <value column>" when the LLM ranks all rows and omits the
    existence filter. Limited to window-rank queries to avoid broad filter
    insertion in ordinary lookups.
    """
    if not sql or not question:
        return sql
    if not re.search(r"\b(?:ROW_NUMBER|RANK|DENSE_RANK)\s*\(", sql, flags=re.I):
        return sql

    q = str(question or "").lower()
    phrase_terms = _extract_rank_nonnull_value_terms(q)
    if not phrase_terms:
        return sql

    top_level_candidates = _rank_partition_candidates_from_select(_extract_top_level_select_list(sql))
    value_expr = _choose_rank_partition_expr(top_level_candidates, phrase_terms)
    if not value_expr:
        candidates = _rank_nonnull_candidates(sql)
        if not candidates:
            return sql
        value_expr = _choose_rank_partition_expr(candidates, phrase_terms)
    if not value_expr:
        return sql

    bare_value = value_expr.split(".")[-1].strip("`")
    existing_filter_pat = (
        rf"(?:\b{re.escape(value_expr)}\b|\b{re.escape(bare_value)}\b)\s+IS\s+NOT\s+NULL"
        rf"|NOT\s+(?:\b{re.escape(value_expr)}\b|\b{re.escape(bare_value)}\b)\s+IS\s+NULL"
    )
    if re.search(existing_filter_pat, sql, flags=re.I):
        return sql

    return _insert_top_level_filter_condition(sql, f"{value_expr} IS NOT NULL")


def _rank_text_terms(text: str) -> Set[str]:
    normalized = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or ""))
    normalized = re.sub(r"[^a-z0-9]+", " ", normalized).strip().lower()
    raw_terms = [tok for tok in normalized.split() if tok]
    stop = {
        "a", "an", "the", "same", "each", "every", "inside", "within",
        "by", "when", "where", "with", "who", "that", "has", "have",
        "having", "for", "of", "in", "on", "and", "or", "rank", "ranks",
        "ranking", "number", "numbers", "sorted", "sort", "from", "to",
        "highest", "lowest", "descending", "ascending",
    }
    terms = {tok for tok in raw_terms if tok not in stop}
    for tok in list(terms):
        singular = get_singular_form(tok)
        if singular:
            terms.add(str(singular).lower())
        elif tok.endswith("s") and len(tok) > 3:
            terms.add(tok[:-1])
    return terms


def _extract_rank_partition_terms_from_question(q: str) -> Set[str]:
    patterns = [
        r"\binside\s+(?:each|every|the|a|an)?\s*(?P<seg>[a-z0-9_\s-]{1,64}?)(?=\s+(?:when|by|after|before|sorted|ordered|from|return)\b|[,.;]|$)",
        r"\bwithin\s+(?:each|every|the\s+same|same|the|a|an)?\s*(?P<seg>[a-z0-9_\s-]{1,64}?)(?=\s+(?:when|by|after|before|sorted|ordered|from|return)\b|[,.;]|$)",
        r"\bper\s+(?P<seg>[a-z0-9_\s-]{1,48}?)(?=\s+(?:when|by|after|before|sorted|ordered|from|return)\b|[,.;]|$)",
    ]
    for pat in patterns:
        m = re.search(pat, q, flags=re.I)
        if m:
            terms = _rank_text_terms(m.group("seg") or "")
            if terms:
                return terms
    return set()


def _extract_rank_nonnull_value_terms(q: str) -> Set[str]:
    patterns = [
        r"\bwith\s+(?:a|an|any|non[-\s]?null)?\s*(?P<seg>[a-z0-9_\s-]{1,48}?)(?=[,.;]|\s+(?:rank|return|show|list|order|sort)\b|$)",
        r"\b(?:who|that)\s+(?:have|has)\s+(?:a|an|any|non[-\s]?null)?\s*(?P<seg>[a-z0-9_\s-]{1,48}?)(?=[,.;]|\s+(?:rank|return|show|list|order|sort)\b|$)",
        r"\bhaving\s+(?:a|an|any|non[-\s]?null)?\s*(?P<seg>[a-z0-9_\s-]{1,48}?)(?=[,.;]|\s+(?:rank|return|show|list|order|sort)\b|$)",
    ]
    for pat in patterns:
        m = re.search(pat, q, flags=re.I)
        if m:
            seg = str(m.group("seg") or "").strip()
            # Negative phrasing ("have no ...", "without ...", "missing ...")
            # is exclusion/include-zero semantics, not an IS NOT NULL request.
            if re.search(r"\b(?:no|without|lacking|missing|none|null)\b", seg, flags=re.I):
                continue
            terms = _rank_text_terms(seg)
            if terms:
                return terms
    return set()


def _extract_top_level_select_list(sql: str) -> str:
    s = str(sql or "")
    m = re.match(r"(?is)^\s*SELECT\s+", s)
    if not m:
        return ""
    start = m.end()
    depth = 0
    quote = ""
    i = start
    while i < len(s):
        ch = s[i]
        if quote:
            if ch == quote and (i == 0 or s[i - 1] != "\\"):
                quote = ""
            i += 1
            continue
        if ch in {"'", '"', "`"}:
            quote = ch
            i += 1
            continue
        if ch == "(":
            depth += 1
            i += 1
            continue
        if ch == ")":
            depth = max(0, depth - 1)
            i += 1
            continue
        if depth == 0 and s[i:i + 4].lower() == "from":
            left_ok = i == 0 or not (s[i - 1].isalnum() or s[i - 1] == "_")
            right_idx = i + 4
            right_ok = right_idx >= len(s) or not (s[right_idx].isalnum() or s[right_idx] == "_")
            if left_ok and right_ok:
                return s[start:i].strip()
        i += 1
    return ""


def _parse_simple_rank_column_expr(expr: str) -> Optional[str]:
    raw = str(expr or "").strip()
    raw = re.sub(r"(?is)\s+AS\s+`?[A-Za-z_][A-Za-z0-9_]*`?\s*$", "", raw).strip()
    m = re.match(
        r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
        raw,
    )
    if not m:
        return None
    table_alias = str(m.group(1) or "").strip()
    col = str(m.group(2) or "").strip()
    if not col:
        return None
    return f"{table_alias}.{col}" if table_alias else col


def _rank_partition_candidates_from_select(select_part: str) -> List[Tuple[str, Set[str]]]:
    candidates: List[Tuple[str, Set[str]]] = []
    seen: Set[str] = set()
    for item in _split_top_level_commas(select_part):
        item_clean = (item or "").strip()
        if not item_clean or re.search(r"\b(?:ROW_NUMBER|RANK|DENSE_RANK)\s*\(", item_clean, flags=re.I):
            continue
        expr = _parse_simple_rank_column_expr(item_clean)
        if not expr:
            continue
        key = expr.lower()
        if key in seen:
            continue
        seen.add(key)
        candidates.append((expr, _rank_text_terms(expr)))
    return candidates


def _rank_nonnull_candidates(sql: str) -> List[Tuple[str, Set[str]]]:
    candidates = _rank_partition_candidates_from_select(_extract_top_level_select_list(sql))
    seen = {expr.lower() for expr, _ in candidates}
    for body in re.findall(r"(?is)\b(?:ROW_NUMBER|RANK|DENSE_RANK)\s*\(\s*\)\s*OVER\s*\(([^()]*)\)", sql or ""):
        m = re.search(r"\bORDER\s+BY\s+(.*?)(?:\s+(?:ASC|DESC))?\s*$", body.strip(), flags=re.I | re.S)
        if not m:
            continue
        for item in _split_top_level_commas(m.group(1) or ""):
            item_clean = re.sub(r"\s+\b(?:ASC|DESC)\b\s*$", "", item.strip(), flags=re.I)
            expr = _parse_simple_rank_column_expr(item_clean)
            if not expr or expr.lower() in seen:
                continue
            seen.add(expr.lower())
            candidates.append((expr, _rank_text_terms(expr)))
    return candidates


def _choose_rank_partition_expr(candidates: List[Tuple[str, Set[str]]], target_terms: Set[str]) -> str:
    if not candidates or not target_terms:
        return ""
    scored: List[Tuple[int, int, str]] = []
    for idx, (expr, terms) in enumerate(candidates):
        overlap = terms & target_terms
        if not overlap:
            continue
        # Prefer concise exact-ish matches such as country/officeCode over
        # broader identifiers that merely contain one overlapping token.
        extra_penalty = len(terms - target_terms)
        scored.append((len(overlap), -extra_penalty, expr))
    if not scored:
        return ""
    scored.sort(key=lambda item: (item[0], item[1]), reverse=True)
    return scored[0][2]


def _insert_top_level_filter_condition(sql: str, condition: str) -> str:
    s = str(sql or "").strip()
    if not s or not condition:
        return sql
    trailing = ";" if s.endswith(";") else ""
    if trailing:
        s = s[:-1].rstrip()

    def _find_kw(text: str, kw: str, start: int = 0) -> int:
        target = kw.lower()
        depth = 0
        quote = ""
        i = start
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and text[i:i + len(target)].lower() == target:
                left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
                right_idx = i + len(target)
                right_ok = right_idx >= len(text) or not (text[right_idx].isalnum() or text[right_idx] == "_")
                if left_ok and right_ok:
                    return i
            i += 1
        return -1

    where_pos = _find_kw(s, "where")
    group_pos = _find_kw(s, "group by")
    order_pos = _find_kw(s, "order by")
    limit_pos = _find_kw(s, "limit")
    end_candidates = [p for p in (group_pos, order_pos, limit_pos) if p >= 0]
    insert_pos = min(end_candidates) if end_candidates else len(s)

    if where_pos >= 0:
        where_end_candidates = [p for p in (group_pos, order_pos, limit_pos) if p > where_pos]
        where_end = min(where_end_candidates) if where_end_candidates else len(s)
        return (
            s[:where_end].rstrip()
            + f" AND {condition} "
            + s[where_end:].lstrip()
            + trailing
        ).strip()

    return (
        s[:insert_pos].rstrip()
        + f" WHERE {condition} "
        + s[insert_pos:].lstrip()
        + trailing
    ).strip()


def _fix_mixed_max_groupby_rownumber(sql: str) -> Optional[str]:
    """
    Detect and fix malformed SQL where LLM mixed MAX()/GROUP BY with ROW_NUMBER().

    Example malformed:
    SELECT ... FROM (SELECT customerNumber, MAX(amount), paymentDate
                     FROM payments GROUP BY customerNumber
                     ROW_NUMBER() OVER (PARTITION BY customerNumber ORDER BY amount DESC) = 1) p;

    Correct:
    SELECT t.customerNumber, t.amount, t.paymentDate
    FROM (SELECT customerNumber, amount, paymentDate,
          ROW_NUMBER() OVER (PARTITION BY customerNumber ORDER BY amount DESC) AS rn
          FROM payments) t
    WHERE t.rn = 1;

    Returns fixed SQL or None if pattern not detected.
    """
    if not sql:
        return None

    s = sql.lower()

    # Detect broad mixed-pattern signal.
    has_agg = bool(re.search(r"\b(max|min|sum|count|avg)\s*\(", s))
    has_group_by = "group by" in s
    has_row_number = "row_number() over" in s
    if not (has_agg and has_group_by and has_row_number):
        return None

    # ------------------------------------------------------------------
    # CASE 1: Legacy malformed pattern (ROW_NUMBER ... = 1 inside subquery)
    # ------------------------------------------------------------------
    malformed_pattern = re.search(
        r"row_number\s*\(\s*\)\s+over\s*\([^)]+\)\s*[=<>\s]*1\s*\)",
        sql,
        re.IGNORECASE
    )
    if malformed_pattern:
        outer_select_match = re.search(
            r"select\s+(.*?)\s+from\s*\(",
            sql,
            re.IGNORECASE | re.DOTALL
        )
        if not outer_select_match:
            return None
        outer_cols = outer_select_match.group(1).strip()

        from_table_match = re.search(
            r"from\s+.*?\)\s*(?:as\s+)?(\w+)",
            sql,
            re.IGNORECASE
        )
        outer_alias = from_table_match.group(1) if from_table_match else "t"

        base_table_match = re.search(
            r"from\s+(\w+)\s+(?:(?!group\s+by|row_number).)*?(?=group\s+by|row_number|\))",
            sql,
            re.IGNORECASE
        )
        if not base_table_match:
            return None
        base_table = base_table_match.group(1)

        partition_match = re.search(
            r"partition\s+by\s+([^)]+)",
            sql,
            re.IGNORECASE
        )
        partition_by = partition_match.group(1).strip() if partition_match else ""

        order_match = re.search(
            r"order\s+by\s+([^)]+?)(?:\)|desc|asc)",
            sql,
            re.IGNORECASE
        )
        order_by = order_match.group(1).strip() if order_match else ""

        select_cols = []
        for col in re.split(r",\s*", outer_cols):
            col = col.strip()
            col = re.sub(r"^\w+\.", "", col)
            col = re.sub(
                r"^(max|min|sum|count|avg)\s*\(([^)]+)\)\s*(?:as\s+\w+)?$",
                r"\2",
                col,
                flags=re.IGNORECASE
            )
            select_cols.append(col)

        inner_select = ", ".join(select_cols)
        outer_select = ", ".join([f"{outer_alias}.{col.strip()}" for col in select_cols])
        fixed_sql = (
            f"SELECT {outer_select} "
            f"FROM (SELECT {inner_select}, "
            f"ROW_NUMBER() OVER (PARTITION BY {partition_by} ORDER BY {order_by}) AS rn "
            f"FROM {base_table}) {outer_alias} "
            f"WHERE {outer_alias}.rn = 1"
        )
        return fixed_sql

    # ------------------------------------------------------------------
    # CASE 2: Semantic mixed pattern:
    # outer MAX()+GROUP BY but inner derived-table already uses ROW_NUMBER rn=1.
    # Rewrite to one consistent winner-row query at the parent grain.
    # ------------------------------------------------------------------
    s0 = sql.strip().rstrip(";").strip()
    if not s0:
        return None

    def _is_word_boundary(text: str, start: int, n: int) -> bool:
        left_ok = (start == 0) or not (text[start - 1].isalnum() or text[start - 1] == "_")
        end = start + n
        right_ok = (end >= len(text)) or not (text[end].isalnum() or text[end] == "_")
        return left_ok and right_ok

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        w = kw.lower()
        n = len(w)
        depth = 0
        in_sq = False
        in_dq = False
        in_bt = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i >= start and i + n <= len(text):
                if text[i:i + n].lower() == w and _is_word_boundary(text, i, n):
                    return i
            i += 1
        return -1

    sel_pos = _find_top_level_kw(s0, "select", 0)
    from_pos = _find_top_level_kw(s0, "from", max(0, sel_pos + 6))
    group_pos = _find_top_level_kw(s0, "group by", max(0, from_pos + 4))
    if sel_pos < 0 or from_pos < 0 or group_pos < 0:
        return None

    order_pos = _find_top_level_kw(s0, "order by", group_pos + 8)
    limit_pos = _find_top_level_kw(s0, "limit", group_pos + 8)
    tail_pos_candidates = [p for p in [order_pos, limit_pos] if p >= 0]
    group_end = min(tail_pos_candidates) if tail_pos_candidates else len(s0)

    select_part = s0[sel_pos + len("select"):from_pos].strip()
    from_part = s0[from_pos + len("from"):group_pos].strip()
    group_part = s0[group_pos + len("group by"):group_end].strip()
    tail_part = s0[group_end:].strip() if group_end < len(s0) else ""

    if not select_part or not from_part or not group_part:
        return None

    select_items = _split_top_level_commas(select_part)
    group_items = _split_top_level_commas(group_part)
    if not select_items or not group_items:
        return None

    # Find exactly one MAX/MIN in outer SELECT.
    agg_idx = -1
    agg_kind = ""
    agg_expr = ""

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip().strip("`'\"")

    def _simple_col_name(expr: str) -> Optional[str]:
        m = re.match(
            r"""(?is)^\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            (expr or "").strip(),
        )
        if not m:
            return None
        return m.group(1)

    def _norm_expr(expr: str) -> str:
        return re.sub(r"\s+", "", (expr or "").replace("`", "").lower())

    for i, it in enumerate(select_items):
        expr_i, _al_i = _split_expr_alias(it)
        m_agg = re.match(r"(?is)^\s*(MAX|MIN)\s*\(\s*(.+?)\s*\)\s*$", expr_i)
        if not m_agg:
            continue
        if agg_idx != -1:
            return None
        agg_idx = i
        agg_kind = (m_agg.group(1) or "").upper()
        agg_expr = (m_agg.group(2) or "").strip()

    if agg_idx < 0 or not agg_expr or agg_kind not in {"MAX", "MIN"}:
        return None

    # Select a parent partition key from GROUP BY.
    id_like = [g for g in group_items if re.search(r"(id|number|code)\b", g, flags=re.I)]
    partition_expr = (id_like[0] if id_like else group_items[0]).strip()

    # Rewrite derived join "(SELECT ... ROW_NUMBER ... ) alias ON ... alias.rn=1"
    # into direct join to base table while preserving join key condition.
    derived_pat = re.compile(
        r"""(?is)
        (?P<join_kw>\b(?:LEFT|INNER|RIGHT|FULL)?\s*JOIN)\s*
        \(\s*SELECT\s+(?P<inner_select>[\s\S]*?)\s+FROM\s+
        (?P<base_table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
        (?P<inner_rest>[\s\S]*?)\)\s*
        (?:AS\s+)?(?P<d_alias>[A-Za-z_][A-Za-z0-9_]*)\s+
        ON\s+(?P<on_clause>[\s\S]*?)
        (?=(?:\b(?:LEFT|INNER|RIGHT|FULL)\s+JOIN\b|\bJOIN\b|$))
        """,
        flags=re.IGNORECASE | re.VERBOSE,
    )

    d_match = None
    inner_block = ""
    for m in derived_pat.finditer(from_part):
        d_alias = m.group("d_alias")
        inner_block = (m.group("inner_select") or "") + " " + (m.group("inner_rest") or "")
        on_clause = m.group("on_clause") or ""
        if "row_number" not in inner_block.lower():
            continue
        if not re.search(rf"\b{re.escape(d_alias)}\.rn\s*=\s*1\b", on_clause, flags=re.I):
            continue
        d_match = m
        break

    if not d_match:
        return None

    join_kw = re.sub(r"\s+", " ", (d_match.group("join_kw") or "").strip())
    base_table = (d_match.group("base_table") or "").strip()
    d_alias = (d_match.group("d_alias") or "").strip()
    on_clause = (d_match.group("on_clause") or "").strip()
    if not join_kw or not base_table or not d_alias or not on_clause:
        return None

    conds = _split_top_level_and(on_clause)
    if not conds:
        return None

    join_key_found = False
    new_conds: List[str] = []
    for cond in conds:
        c = (cond or "").strip()
        if not c:
            continue
        if re.search(rf"\b{re.escape(d_alias)}\.rn\s*=\s*1\b", c, flags=re.I):
            continue

        m_eq = re.match(r"(?is)^\s*(.+?)\s*=\s*(.+?)\s*$", c)
        if m_eq:
            lhs = (m_eq.group(1) or "").strip()
            rhs = (m_eq.group(2) or "").strip()
            lhs_is_d = bool(re.match(rf"(?is)^\s*`?{re.escape(d_alias)}`?\.", lhs))
            rhs_is_d = bool(re.match(rf"(?is)^\s*`?{re.escape(d_alias)}`?\.", rhs))
            if lhs_is_d ^ rhs_is_d:
                d_side = lhs if lhs_is_d else rhs
                other_side = rhs if lhs_is_d else lhs
                d_col = re.match(
                    rf"(?is)^\s*`?{re.escape(d_alias)}`?\.`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
                    d_side,
                )
                if d_col:
                    join_key_found = True
                    new_conds.append(f"{d_alias}.{d_col.group(1)} = {other_side}")
                    continue

        new_conds.append(c)

    if not join_key_found:
        return None

    new_on = " AND ".join([c for c in new_conds if c.strip()])
    if not new_on:
        return None

    new_join = f"{join_kw} {base_table} {d_alias} ON {new_on}"
    new_from = from_part[:d_match.start()] + new_join + from_part[d_match.end():]
    new_from = re.sub(r"\s{2,}", " ", new_from).strip()

    # Build rewritten SELECT list and stable output names.
    inner_items: List[str] = []
    outer_items: List[str] = []
    seen_names: Set[str] = set()
    expr_to_out: Dict[str, str] = {}

    metric_expr = agg_expr.strip()
    metric_dir = "DESC" if agg_kind == "MAX" else "ASC"

    date_expr = ""
    id_tie_expr = ""

    for i, it in enumerate(select_items):
        expr_i, alias_i = _split_expr_alias(it)
        use_expr = metric_expr if i == agg_idx else expr_i.strip()

        out_name = alias_i or _simple_col_name(use_expr) or f"col_{i+1}"
        out_name = re.sub(r"[^A-Za-z0-9_]", "_", out_name).strip("_") or f"col_{i+1}"
        if re.match(r"^\d", out_name):
            out_name = f"c_{out_name}"

        base_name = out_name
        suffix = 2
        while out_name.lower() in seen_names:
            out_name = f"{base_name}_{suffix}"
            suffix += 1
        seen_names.add(out_name.lower())

        inner_items.append(f"{use_expr} AS {out_name}")
        outer_items.append(f"t.{out_name}")
        expr_to_out[_norm_expr(use_expr)] = out_name

        if i != agg_idx:
            use_low = use_expr.lower()
            if not date_expr and any(k in use_low for k in ["date", "time", "timestamp"]):
                date_expr = use_expr
            if not id_tie_expr and re.search(r"(id|number|code)\b", use_low):
                if _norm_expr(use_expr) != _norm_expr(partition_expr):
                    id_tie_expr = use_expr

    if not inner_items or not outer_items:
        return None

    # Prefer the ORDER BY sequence already present inside the derived ROW_NUMBER().
    inner_order_parts: List[str] = []
    m_inner_order = re.search(
        r"""(?is)\bROW_NUMBER\s*\(\s*\)\s*OVER\s*\(\s*PARTITION\s+BY\s+.*?\bORDER\s+BY\s+([^)]+)\)""",
        inner_block or "",
    )
    if m_inner_order:
        raw_inner_order = (m_inner_order.group(1) or "").strip()
        for part in _split_top_level_commas(raw_inner_order):
            p = (part or "").strip()
            if not p:
                continue
            m_dir = re.match(r"(?is)^(.*?)\s+(ASC|DESC)\s*$", p)
            if m_dir:
                expr0 = (m_dir.group(1) or "").strip()
                dir0 = (m_dir.group(2) or "").upper()
            else:
                expr0 = p
                dir0 = "DESC"
            if _simple_col_name(expr0) and "." not in expr0:
                expr0 = f"{d_alias}.{expr0}"
            inner_order_parts.append(f"{expr0} {dir0}")

    if inner_order_parts:
        order_parts = inner_order_parts
        if id_tie_expr:
            present = any(_norm_expr(id_tie_expr) in _norm_expr(p) for p in inner_order_parts)
            if not present:
                order_parts.append(f"{id_tie_expr} ASC")
    else:
        # Fallback heuristic when inner order is unavailable.
        order_parts = []
        if date_expr:
            order_parts.append(f"{date_expr} DESC")
        order_parts.append(f"{metric_expr} {metric_dir}")
        if id_tie_expr and _norm_expr(id_tie_expr) not in {_norm_expr(metric_expr), _norm_expr(date_expr)}:
            order_parts.append(f"{id_tie_expr} ASC")
    order_window = ", ".join(order_parts)

    partition_out = expr_to_out.get(_norm_expr(partition_expr))
    date_out = expr_to_out.get(_norm_expr(date_expr)) if date_expr else None

    if date_out and partition_out:
        outer_tail = f" ORDER BY t.{date_out} DESC, t.{partition_out} ASC"
    elif tail_part:
        tail_no_qual = re.sub(r"\b[A-Za-z_][A-Za-z0-9_]*\.", "", tail_part)
        outer_tail = " " + tail_no_qual.strip()
    else:
        outer_tail = ""

    inner_sql = (
        f"SELECT {', '.join(inner_items)}, "
        f"ROW_NUMBER() OVER (PARTITION BY {partition_expr} ORDER BY {order_window}) AS rn "
        f"FROM {new_from}"
    )
    fixed_sql = (
        f"SELECT {', '.join(outer_items)} "
        f"FROM ({inner_sql}) t "
        f"WHERE t.rn = 1"
        f"{outer_tail}"
    )

    fixed_sql = re.sub(r"\s{2,}", " ", fixed_sql).strip()
    if not fixed_sql.endswith(";"):
        fixed_sql += ";"
    return fixed_sql


def _fix_redundant_groupby_with_rn_filter(sql: str) -> Optional[str]:
    """
    Fix redundant GROUP BY + MAX(CASE WHEN rn = N...) when WHERE rn = N is already present.

    Anti-pattern (WRONG):
        SELECT t.customer, MAX(CASE WHEN rn = 2 THEN amount END) AS amount
        FROM (... ROW_NUMBER() OVER (...) AS rn ...) t
        WHERE t.rn = 2
        GROUP BY t.customer;

    Correct:
        SELECT t.customer, t.amount
        FROM (... ROW_NUMBER() OVER (...) AS rn ...) t
        WHERE t.rn = 2;

    When WHERE rn = N is present, each group already has exactly ONE row,
    so GROUP BY is redundant and MAX(CASE WHEN rn = N...) is unnecessary.

    Returns fixed SQL or None if pattern not detected.
    """
    if not sql:
        return None

    s_upper = sql.upper()

    # Must have: ROW_NUMBER, WHERE rn = N, GROUP BY, MAX(CASE WHEN...)
    if "ROW_NUMBER" not in s_upper:
        return None
    if "GROUP BY" not in s_upper:
        return None

    # Detect WHERE rn = N pattern (N is 1-9 for ordinal)
    where_rn_match = re.search(r"\bWHERE\s+(\w+\.)?rn\s*=\s*(\d)", sql, re.IGNORECASE)
    if not where_rn_match:
        return None

    rn_value = where_rn_match.group(2)

    # Detect MAX(CASE WHEN rn = N THEN col END) pattern
    # Pattern: MAX(CASE WHEN [alias.]rn [=<>] N THEN column END)
    max_case_pattern = re.compile(
        r"\b(MAX|MIN)\s*\(\s*CASE\s+WHEN\s+(?:\w+\.)?rn\s*=\s*" + rn_value + r"\s+THEN\s+(\w+(?:\.\w+)?)\s+END\s*\)",
        re.IGNORECASE
    )

    has_max_case = max_case_pattern.search(sql)
    if not has_max_case:
        return None

    # ===== FIX: Remove GROUP BY and simplify MAX(CASE WHEN...) =====
    fixed = sql

    # 1. Replace MAX(CASE WHEN rn = N THEN col END) with just the column
    def replace_max_case(match):
        # group(2) is the column (may include alias like "pmt.amount")
        return match.group(2)

    fixed = max_case_pattern.sub(replace_max_case, fixed)

    # 2. Remove GROUP BY clause from outer query (not subquery)
    # We need to remove GROUP BY that comes after the closing paren of subquery
    # Pattern: ) alias WHERE ... GROUP BY ...
    # Use careful regex to only match GROUP BY in outer query

    # Find the outer GROUP BY position (after subquery closing paren)
    # First, find WHERE rn = N position
    where_pos = fixed.upper().find("WHERE")
    if where_pos == -1:
        return None

    # Look for GROUP BY after WHERE (in the outer query)
    group_by_after_where = re.search(
        r"\bGROUP\s+BY\s+[^;)]+(?:;|$|\s*HAVING|\s*ORDER|\s*LIMIT)",
        fixed[where_pos:],
        re.IGNORECASE
    )

    if group_by_after_where:
        # Remove the GROUP BY clause
        # Find exact position
        start = where_pos + group_by_after_where.start()
        end = where_pos + group_by_after_where.end()

        # Trim trailing keywords that might have been captured
        fixed_group = fixed[start:end].rstrip()
        # Don't remove trailing semicolon, ORDER BY, LIMIT, HAVING
        for kw in ["ORDER", "LIMIT", "HAVING", ";"]:
            if fixed_group.upper().endswith(kw):
                fixed_group = fixed_group[:-len(kw)].rstrip()

        fixed = fixed[:start] + fixed[end:]

    # Clean up extra spaces
    fixed = re.sub(r"\s+", " ", fixed).strip()

    # Ensure semicolon at end if original had one
    if sql.rstrip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"

    return fixed


def _fix_inconsistent_subquery_alias(sql: str) -> Optional[str]:
    """
    Fix LLM hallucination where outer SELECT uses a different alias than the subquery.

    Example WRONG:
        SELECT p.customerNumber, t.amount FROM (...) t WHERE t.rn = 2
        -- 'p' is undefined! Only 't' is valid.

    Example CORRECT:
        SELECT t.customerNumber, t.amount FROM (...) t WHERE t.rn = 2
        -- Consistent alias 't' everywhere.

    Returns fixed SQL or None if pattern not detected.
    """
    if not sql:
        return None

    s_upper = sql.upper()

    # Only process queries with subqueries
    if "ROW_NUMBER" not in s_upper:
        return None

    def _find_top_level_from_idx(raw: str) -> int:
        low = raw.lower()
        depth = 0
        i = 0
        in_sq = False
        in_dq = False
        while i < len(raw):
            ch = raw[i]
            if ch == "'" and not in_dq:
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and low.startswith("from", i):
                prev_ok = (i == 0) or (not low[i - 1].isalnum() and low[i - 1] != "_")
                j = i + 4
                next_ok = (j >= len(low)) or (not low[j].isalnum() and low[j] != "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    from_idx = _find_top_level_from_idx(sql)
    if from_idx < 0:
        return None
    after_from = sql[from_idx + 4:].lstrip()
    if not after_from.startswith("("):
        return None
    lparen_idx = from_idx + 4 + (len(sql[from_idx + 4:]) - len(after_from))

    depth = 0
    close_idx = -1
    for i in range(lparen_idx, len(sql)):
        ch = sql[i]
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                close_idx = i
                break
    if close_idx < 0:
        return None

    alias_tail = sql[close_idx + 1:]
    alias_match = re.match(r"\s*(?:AS\s+)?([a-zA-Z_][a-zA-Z0-9_]*)\b", alias_tail, re.IGNORECASE)
    if not alias_match:
        return None
    correct_alias = alias_match.group(1)

    if not re.match(r"(?is)^\s*SELECT\b", sql):
        return None
    outer_cols = sql[sql.upper().find("SELECT") + len("SELECT"):from_idx].strip()
    if not outer_cols:
        return None

    # Find all aliases used in the outer SELECT
    alias_refs = set(re.findall(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\.\w+', outer_cols))

    # Build the set of valid top-level aliases after the derived-table alias.
    # Only aliases that are truly undefined at the outer scope should be
    # rewritten. This avoids corrupting queries that legitimately join the
    # ranked subquery with other top-level tables.
    valid_outer_aliases: Set[str] = {correct_alias.lower()}
    tail_after_alias = alias_tail[alias_match.end():]
    for m_tbl in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?""",
        f"FROM ({sql[lparen_idx:close_idx+1]}) {correct_alias} {tail_after_alias}",
    ):
        table_expr = (m_tbl.group(1) or "").strip()
        if not table_expr:
            continue
        table_name = table_expr.replace("`", "").split(".")[-1].strip()
        alias_name = (m_tbl.group(2) or "").strip() or table_name
        if alias_name:
            valid_outer_aliases.add(alias_name.lower())

    # Check if any alias is different from the correct one *and* not valid in
    # the outer scope.
    inconsistent_aliases = {
        a for a in alias_refs
        if a.lower() not in valid_outer_aliases
    }

    if not inconsistent_aliases:
        return None  # All aliases are consistent

    # Fix: Replace all inconsistent aliases with the correct one
    fixed = sql

    old_select = sql[:from_idx]
    new_select = old_select
    for wrong_alias in inconsistent_aliases:
        new_select = re.sub(
            rf'\b{re.escape(wrong_alias)}\.',
            f"{correct_alias}.",
            new_select
        )
    fixed = new_select + sql[from_idx:]

    # Debug output
    # print(f"[ALIAS FIX] Fixed inconsistent alias: {inconsistent_aliases} -> {correct_alias}")

    return fixed


def _drop_tuple_in_filter_from_include_zero_ranked_winner(sql: str, question: str, ctx: str = "") -> str:
    """
    For include-zero winner-row queries that already rank at the preserved
    parent grain, drop an inner tuple-IN filter that narrows the nullable LEFT
    JOIN side before ROW_NUMBER() is applied.

    Why this is safe:
    - only runs for clear include-zero winner-row asks
    - only when the outer query already filters `rn = 1`
    - only when the inner query is built from a preserved base table with
      LEFT JOIN chain
    - only removes tuple-IN predicates from the inner WHERE; all other
      predicates stay intact
    """
    if not sql or not question:
        return sql
    if "ROW_NUMBER" not in (sql or "").upper():
        return sql
    if not _question_wants_winner_row(question):
        return sql
    include_zero_like = _question_wants_include_zero(question, ctx) or bool(
        re.search(r"(?is)\bincluding\b.{0,120}\bwithout\b", question or "")
    )
    if not include_zero_like:
        return sql
    if not re.search(r"\bWHERE\b[^;]*\brn\s*=\s*1\b", sql, flags=re.I | re.S):
        return sql

    s = sql.strip()
    if not re.match(r"(?is)^\s*SELECT\b", s):
        return sql
    if not re.search(r"(?is)\bLEFT\s+JOIN\b", s):
        return sql

    def _find_top_level_from_idx(raw: str) -> int:
        low = raw.lower()
        depth = 0
        i = 0
        in_sq = False
        in_dq = False
        in_bt = False
        while i < len(raw):
            ch = raw[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(raw) and raw[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                if in_dq and i + 1 < len(raw) and raw[i + 1] == '"':
                    i += 2
                    continue
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and low.startswith("from", i):
                prev_ok = (i == 0) or (not low[i - 1].isalnum() and low[i - 1] != "_")
                j = i + 4
                next_ok = (j >= len(low)) or (not low[j].isalnum() and low[j] != "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    from_idx = _find_top_level_from_idx(s)
    if from_idx < 0:
        return sql
    after_from = s[from_idx + 4:].lstrip()
    if not after_from.startswith("("):
        return sql
    lparen_idx = from_idx + 4 + (len(s[from_idx + 4:]) - len(after_from))

    depth = 0
    close_idx = -1
    for i in range(lparen_idx, len(s)):
        ch = s[i]
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                close_idx = i
                break
    if close_idx < 0:
        return sql

    inner_sql = s[lparen_idx + 1:close_idx].strip()
    if "ROW_NUMBER" not in inner_sql.upper():
        return sql
    if not re.search(r"(?is)\bLEFT\s+JOIN\b", inner_sql):
        return sql

    where_m = re.search(r"\bWHERE\b", inner_sql, flags=re.I)
    if not where_m:
        return sql

    inner_before_where = inner_sql[:where_m.start()].rstrip()
    inner_after_where = inner_sql[where_m.end():].lstrip()
    boundary_m = re.search(r"(?is)\bORDER\s+BY\b|\bGROUP\s+BY\b|\bHAVING\b|\bLIMIT\b$", "")
    # Find the next top-level clause after WHERE manually.
    depth = 0
    end_where_idx = len(inner_after_where)
    in_sq = in_dq = in_bt = False
    low_after = inner_after_where.lower()
    i = 0
    while i < len(inner_after_where):
        ch = inner_after_where[i]
        if ch == "'" and not in_dq and not in_bt:
            if in_sq and i + 1 < len(inner_after_where) and inner_after_where[i + 1] == "'":
                i += 2
                continue
            in_sq = not in_sq
            i += 1
            continue
        if ch == '"' and not in_sq and not in_bt:
            if in_dq and i + 1 < len(inner_after_where) and inner_after_where[i + 1] == '"':
                i += 2
                continue
            in_dq = not in_dq
            i += 1
            continue
        if ch == "`" and not in_sq and not in_dq:
            in_bt = not in_bt
            i += 1
            continue
        if in_sq or in_dq or in_bt:
            i += 1
            continue
        if ch == "(":
            depth += 1
            i += 1
            continue
        if ch == ")":
            depth = max(0, depth - 1)
            i += 1
            continue
        if depth == 0:
            for kw in (" order by", " group by", " having", " limit"):
                if low_after.startswith(kw, i):
                    end_where_idx = i
                    i = len(inner_after_where)
                    break
        i += 1

    where_body = inner_after_where[:end_where_idx].strip()
    inner_tail = inner_after_where[end_where_idx:].strip()
    if not where_body or _has_top_level_or(where_body):
        return sql

    conjuncts = _split_top_level_and(where_body)
    remaining = []
    removed = False
    for cond in conjuncts:
        c = cond.strip()
        if re.match(r"(?is)^\(\s*[^()]+,\s*[^()]+\s*\)\s+IN\s*\(\s*SELECT\b", c):
            removed = True
            continue
        remaining.append(c)
    if not removed and re.match(r"(?is)^\(\s*[^()]+,\s*[^()]+\s*\)\s+IN\s*\(\s*SELECT\b.*\)\s*$", where_body):
        removed = True
        remaining = []
    if not removed:
        return sql

    rebuilt_inner = inner_before_where
    if remaining:
        rebuilt_inner += " WHERE " + " AND ".join(remaining)
    if inner_tail:
        rebuilt_inner += " " + inner_tail

    out = s[:lparen_idx + 1] + rebuilt_inner + s[close_idx:]
    out = re.sub(r"\s{2,}", " ", out).strip()
    if out and not out.endswith(";"):
        out += ";"
    return out or sql


def _drop_tuple_in_filter_from_single_table_ranked_winner(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop a redundant tuple-IN latest-row prefilter inside a single-table
    winner-row ranked subquery when ROW_NUMBER() already determines the winner.

    Typical bad shape:
      FROM (
        SELECT ..., ROW_NUMBER() OVER (PARTITION BY key ORDER BY metric DESC, tiebreak DESC) AS rn
        FROM base_table
        WHERE (key, tiebreak) IN (
          SELECT key, MAX(tiebreak) FROM base_table GROUP BY key
        )
      ) t
      WHERE t.rn = 1

    This prefilter is not needed and can change the semantics by forcing the
    latest row before ranking by the primary metric.
    """
    if not sql or not question:
        return sql
    if "ROW_NUMBER" not in (sql or "").upper():
        return sql
    if not _question_wants_winner_row(question):
        return sql

    s = str(sql or "").strip()
    if not re.search(r"\bWHERE\b[^;]*\brn\s*=\s*1\b", s, flags=re.I | re.S):
        return sql

    outer_pat = re.compile(
        r"""(?is)
        ^\s*SELECT\s+(?P<outer_select>.+?)\s+
        FROM\s*\(\s*
        SELECT\s+(?P<inner_select>.+?)\s+
        FROM\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<table_alias>[A-Za-z_][A-Za-z0-9_]*))?
        (?:\s+WHERE\s+(?P<inner_where>.+?))?
        \s*\)\s+AS\s+(?P<outer_alias>[A-Za-z_][A-Za-z0-9_]*)
        \s+WHERE\s+(?P<outer_where>.+?)
        (?P<tail>\s+ORDER\s+BY\b.*|\s+LIMIT\b.*|)\s*$
        """,
        flags=re.X,
    )
    m_outer = outer_pat.match(s.rstrip(";"))
    if not m_outer:
        return sql

    inner_select = str(m_outer.group("inner_select") or "").strip()
    inner_where = str(m_outer.group("inner_where") or "").strip()
    table_name = str(m_outer.group("table") or "").strip("`")
    table_alias = str(m_outer.group("table_alias") or "").strip() or table_name
    outer_alias = str(m_outer.group("outer_alias") or "").strip()
    outer_where = str(m_outer.group("outer_where") or "").strip()
    tail = str(m_outer.group("tail") or "").strip()

    if not inner_where or not table_name or not outer_alias:
        return sql
    if re.search(r"\bJOIN\b", inner_select, flags=re.I):
        return sql

    rownum_pat = re.compile(
        r"""(?is)\bROW_NUMBER\s*\(\s*\)\s*OVER\s*\(
        \s*PARTITION\s+BY\s+(?P<part>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)
        \s+ORDER\s+BY\s+(?P<order>.+?)
        \)\s+AS\s+`?rn`?\b""",
        flags=re.X,
    )
    m_rownum = rownum_pat.search(inner_select)
    if not m_rownum:
        return sql

    def _bare_col(expr: str) -> str:
        return str(expr or "").strip().split(".")[-1].strip("`").lower()

    partition_col = _bare_col(m_rownum.group("part") or "")
    order_clause = str(m_rownum.group("order") or "")
    if not partition_col or not order_clause:
        return sql

    tuple_pat = re.compile(
        rf"""(?is)^\s*
        \(\s*(?P<left1>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?{re.escape(partition_col)}`?)\s*,\s*
              (?P<left2>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<tiebreak>[A-Za-z_][A-Za-z0-9_]*)`?)\s*\)
        \s+IN\s*\(\s*
        SELECT\s+(?P<right1>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?{re.escape(partition_col)}`?)\s*,\s*
               MAX\s*\(\s*(?P<right2>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<tiebreak2>[A-Za-z_][A-Za-z0-9_]*)`?)\s*\)
        \s+FROM\s+`?{re.escape(table_name)}`?(?:\s+(?:AS\s+)?[A-Za-z_][A-Za-z0-9_]*)?
        \s+GROUP\s+BY\s+(?P<group_key>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?{re.escape(partition_col)}`?)
        \s*\)\s*$
        """,
        flags=re.X,
    )

    conds = _split_top_level_and(inner_where)
    if not conds:
        return sql

    kept_conds: List[str] = []
    removed_any = False
    for cond in conds:
        cond_s = str(cond or "").strip()
        if not cond_s:
            continue
        m_tuple = tuple_pat.match(cond_s)
        if not m_tuple:
            kept_conds.append(cond_s)
            continue
        tiebreak_col = _bare_col(m_tuple.group("tiebreak") or "")
        tiebreak_col2 = _bare_col(m_tuple.group("tiebreak2") or "")
        if not tiebreak_col or tiebreak_col != tiebreak_col2:
            kept_conds.append(cond_s)
            continue
        if not re.search(
            rf"\b(?:`?{re.escape(table_alias)}`?\.)?`?{re.escape(tiebreak_col)}`?\b\s+DESC\b",
            order_clause,
            flags=re.I,
        ):
            kept_conds.append(cond_s)
            continue
        removed_any = True

    if not removed_any:
        return sql

    inner_lines = [
        f"SELECT {inner_select}",
        f"FROM {table_name}" + (f" AS {table_alias}" if table_alias and table_alias != table_name else ""),
    ]
    if kept_conds:
        inner_lines.append("WHERE " + " AND ".join(kept_conds))
    inner_sql = " ".join(part.strip() for part in inner_lines if part.strip())

    rebuilt = (
        f"SELECT {str(m_outer.group('outer_select') or '').strip()} "
        f"FROM ({inner_sql}) AS {outer_alias} "
        f"WHERE {outer_where}"
    ).strip()
    if tail:
        rebuilt += f" {tail}"
    if str(sql).strip().endswith(";") and not rebuilt.endswith(";"):
        rebuilt += ";"
    return rebuilt


def _fix_inner_rn_filter_scope(sql: str) -> Optional[str]:
    """
    Fix malformed ordinal-ranking SQL where WHERE rn = N is placed inside the
    same SELECT block that defines ROW_NUMBER().

    Wrong:
      SELECT customerNumber, amount
      FROM (
        SELECT customerNumber, amount,
               ROW_NUMBER() OVER (...) AS rn
        FROM payments
        WHERE rn = 2
      ) AS t;

    Correct:
      SELECT customerNumber, amount
      FROM (
        SELECT customerNumber, amount,
               ROW_NUMBER() OVER (...) AS rn
        FROM payments
      ) AS t
      WHERE t.rn = 2;
    """
    if not sql:
        return None

    s = sql.strip()
    if "ROW_NUMBER" not in s.upper():
        return None

    from_match = re.search(r"\bFROM\s*\(", s, re.I)
    if not from_match:
        return None

    open_idx = s.find("(", from_match.start())
    if open_idx < 0:
        return None

    depth = 0
    in_sq = False
    in_dq = False
    close_idx = -1
    for i in range(open_idx, len(s)):
        ch = s[i]
        if ch == "'" and not in_dq:
            in_sq = not in_sq
        elif ch == '"' and not in_sq:
            in_dq = not in_dq
        elif not in_sq and not in_dq:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    close_idx = i
                    break

    if close_idx < 0:
        return None

    inner_sql = s[open_idx + 1:close_idx].strip()
    if not re.match(r"(?is)^select\b", inner_sql):
        return None
    if "ROW_NUMBER" not in inner_sql.upper():
        return None

    inner_where_match = re.search(r"\bWHERE\b", inner_sql, re.I)
    if not inner_where_match:
        return None

    where_idx = inner_where_match.start()
    select_body = inner_sql[:where_idx].rstrip()
    where_body = inner_sql[inner_where_match.end():].strip()
    if not where_body:
        return None

    def _split_top_level_and(expr: str) -> List[str]:
        parts: List[str] = []
        if not expr:
            return parts
        depth = 0
        in_sq = False
        in_dq = False
        in_bt = False
        start = 0
        i = 0
        low = expr.lower()
        while i < len(expr):
            ch = expr[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(expr) and expr[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                if in_dq and i + 1 < len(expr) and expr[i + 1] == '"':
                    i += 2
                    continue
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and low.startswith("and", i):
                left_ok = i == 0 or not (low[i - 1].isalnum() or low[i - 1] == "_")
                right_ok = i + 3 >= len(low) or not (low[i + 3].isalnum() or low[i + 3] == "_")
                if left_ok and right_ok:
                    part = expr[start:i].strip()
                    if part:
                        parts.append(part)
                    i += 3
                    start = i
                    continue
            i += 1
        tail = expr[start:].strip()
        if tail:
            parts.append(tail)
        return parts

    conjuncts = _split_top_level_and(where_body)
    if not conjuncts:
        return None

    rn_value = ""
    kept_conjuncts: List[str] = []
    for conj in conjuncts:
        m_rn = re.fullmatch(r"\(?\s*(?:\w+\.)?rn\s*=\s*(\d+)\s*\)?", conj, re.I)
        if m_rn:
            if rn_value and rn_value != m_rn.group(1):
                return None
            rn_value = m_rn.group(1)
            continue
        kept_conjuncts.append(conj)

    if not rn_value:
        return None

    outer_tail = s[close_idx + 1:].strip()
    if re.search(r"\bWHERE\s+(\w+\.)?rn\s*=\s*" + re.escape(rn_value) + r"\b", outer_tail, re.I):
        return None

    inner_fixed = select_body
    if kept_conjuncts:
        inner_fixed += " WHERE " + " AND ".join(kept_conjuncts)
    inner_fixed = re.sub(r"\s{2,}", " ", inner_fixed).strip()

    alias_match = re.match(r"(?is)^(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)\b(.*)$", outer_tail)
    if not alias_match:
        return None

    alias = alias_match.group(1)
    tail_rest = (alias_match.group(2) or "").strip()

    fixed = (
        s[:open_idx + 1]
        + inner_fixed
        + s[close_idx]
        + f" AS {alias} WHERE {alias}.rn = {rn_value}"
    )
    if tail_rest:
        fixed += " " + tail_rest

    fixed = re.sub(r"\)\s+AS\s+AS\b", ") AS", fixed, flags=re.I)
    fixed = re.sub(r"\s{2,}", " ", fixed).strip()
    if sql.rstrip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _fix_outer_order_by_for_derived_alias(sql: str) -> str:
    """
    For outer queries over a derived table:
      SELECT ... FROM ( ... ) t ... ORDER BY ...
    normalize ORDER BY references to valid outer output names.

    Typical repairs:
      - wrong qualifier alias (e.g., e.customerNumber -> customerNumber)
      - snake/camel mismatch (payment_date -> paymentDate)
      - number->id alias drift (employeeNumber -> employee_id when projected as alias)
    """
    if not sql:
        return sql

    s = sql.strip()
    if not s or "ORDER BY" not in s.upper() or "FROM (" not in s.upper():
        return sql

    # Detect derived-table alias used in outer scope.
    m_sub_alias = re.search(r"\)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)\s+WHERE\b", s, flags=re.I)
    if not m_sub_alias:
        return sql
    sub_alias = m_sub_alias.group(1)

    m_select = re.search(r"(?is)^\s*SELECT\s+(.*?)\s+FROM\s*\(", s)
    if not m_select:
        return sql
    outer_select = (m_select.group(1) or "").strip()

    def _is_word_boundary(text: str, i: int, n: int) -> bool:
        left_ok = (i == 0) or not (text[i - 1].isalnum() or text[i - 1] == "_")
        right_ok = (i + n >= len(text)) or not (text[i + n].isalnum() or text[i + n] == "_")
        return left_ok and right_ok

    def _find_top_level_order_by(text: str) -> int:
        low = text.lower()
        i = 0
        depth = 0
        in_sq = False
        in_dq = False
        in_bt = False
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                if in_dq and i + 1 < len(text) and text[i + 1] == '"':
                    i += 2
                    continue
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and low[i:i + 8] == "order by" and _is_word_boundary(text, i, 8):
                return i
            i += 1
        return -1

    def _find_top_level_limit_after(text: str, start: int) -> int:
        low = text.lower()
        i = max(0, start)
        depth = 0
        in_sq = False
        in_dq = False
        in_bt = False
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                if in_dq and i + 1 < len(text) and text[i + 1] == '"':
                    i += 2
                    continue
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and low[i:i + 5] == "limit" and _is_word_boundary(text, i, 5):
                return i
            if depth == 0 and ch == ";":
                return i
            i += 1
        return -1

    order_pos = _find_top_level_order_by(s)
    if order_pos < 0:
        return sql
    order_clause_start = order_pos + len("ORDER BY")
    order_clause_end = _find_top_level_limit_after(s, order_clause_start)
    if order_clause_end < 0:
        order_clause_end = len(s)

    order_clause = s[order_clause_start:order_clause_end].strip()
    if not order_clause:
        return sql

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m:
            return (item or "").strip(), None
        return (m.group(1) or "").strip(), (m.group(2) or "").strip()

    def _output_name_from_expr(expr: str, alias_raw: Optional[str]) -> Optional[str]:
        if alias_raw:
            a = alias_raw.strip()
            if (
                (a.startswith("`") and a.endswith("`"))
                or (a.startswith("'") and a.endswith("'"))
                or (a.startswith('"') and a.endswith('"'))
            ):
                a = a[1:-1]
            return a.strip() or None
        m_col = re.match(
            r"(?is)^\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            (expr or "").strip(),
        )
        if m_col:
            return (m_col.group(1) or "").strip() or None
        return None

    def _norm_token(x: str) -> str:
        return re.sub(r"[^a-z0-9]", "", (x or "").lower())

    output_names: List[str] = []
    qualified_simple_outputs: Set[str] = set()
    for it in _split_top_level_commas(outer_select):
        expr, a0 = _split_expr_alias(it)
        out_name = _output_name_from_expr(expr, a0)
        if out_name:
            output_names.append(out_name)
            m_direct = re.match(
                r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
                expr,
            )
            src_col = (m_direct.group(2) or "").strip() if m_direct else ""
            alias_name = (
                a0.strip("`'\" ").strip()
                if a0 and a0.strip("`'\" ").strip()
                else ""
            )
            if (
                m_direct
                and (m_direct.group(1) or "").strip().lower() == sub_alias.lower()
                and (
                    not alias_name
                    or alias_name.lower() == src_col.lower()
                )
                and out_name.lower() == src_col.lower()
            ):
                qualified_simple_outputs.add(out_name)
    if not output_names:
        return sql

    out_by_norm: Dict[str, List[str]] = {}
    for name in output_names:
        out_by_norm.setdefault(_norm_token(name), []).append(name)

    def _resolve_to_output_name(raw_base: str) -> Optional[str]:
        b = (raw_base or "").strip()
        if not b:
            return None

        keep_sub_alias_qualifier = False
        qualified_col = ""

        # Strip qualifier if any: alias.col -> col
        m_q = re.match(
            r"(?is)^`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?$",
            b,
        )
        if m_q:
            q = (m_q.group(1) or "").strip()
            c = (m_q.group(2) or "").strip()
            if q.lower() == sub_alias.lower():
                keep_sub_alias_qualifier = True
                qualified_col = c
            b = c

        norm_b = _norm_token(b)
        if not norm_b:
            return None

        # Exact/normalized match first.
        norm_hits = out_by_norm.get(norm_b, [])
        if len(norm_hits) == 1:
            chosen = norm_hits[0]
            if (
                keep_sub_alias_qualifier
                and qualified_col
                and chosen in qualified_simple_outputs
                and chosen.lower() == qualified_col.lower()
            ):
                return f"{sub_alias}.{chosen}"
            return chosen

        # Heuristic: employeeNumber -> employee_id if projected alias uses *_id.
        if norm_b.endswith("number"):
            pref_norm = norm_b[:-6] + "id"
            pref_hits = out_by_norm.get(pref_norm, [])
            if len(pref_hits) == 1:
                return pref_hits[0]

        # If already an output name (case-insensitive), keep canonical casing from SELECT.
        for name in output_names:
            if name.lower() == b.lower():
                if (
                    keep_sub_alias_qualifier
                    and qualified_col
                    and name in qualified_simple_outputs
                    and name.lower() == qualified_col.lower()
                ):
                    return f"{sub_alias}.{name}"
                return name
        return None

    rebuilt_order_items: List[str] = []
    changed = False
    for item in _split_top_level_commas(order_clause):
        raw = (item or "").strip()
        if not raw:
            continue

        m_dir = re.match(r"(?is)^(.*?)(\s+(?:ASC|DESC))\s*$", raw)
        if m_dir:
            base = (m_dir.group(1) or "").strip()
            dir_part = (m_dir.group(2) or "").strip()
        else:
            base = raw
            dir_part = ""

        replacement = _resolve_to_output_name(base)
        if replacement and replacement != base:
            changed = True
            base = replacement

        rebuilt_order_items.append((base + (" " + dir_part if dir_part else "")).strip())

    if not changed or not rebuilt_order_items:
        return sql

    new_order_clause = ", ".join(rebuilt_order_items)
    fixed = s[:order_clause_start] + " " + new_order_clause + s[order_clause_end:]
    return fixed


def _drop_redundant_top_groupby_after_rn_filter(sql: str) -> Optional[str]:
    """
    Drop top-level GROUP BY when query already filters to a single winner row via WHERE rn = N.

    Pattern:
      SELECT ... FROM (...) t WHERE t.rn = 1 GROUP BY ... [ORDER BY ...]

    This GROUP BY is usually redundant and can distort semantics.
    Conservative guards:
    - requires ROW_NUMBER and top-level WHERE rn = N
    - only applies when top-level SELECT has no aggregate functions
    """
    if not sql:
        return None

    s0 = sql.strip().rstrip(";").strip()
    if not s0:
        return None
    s_up = s0.upper()

    if "ROW_NUMBER" not in s_up or "GROUP BY" not in s_up or "WHERE" not in s_up:
        return None
    if not re.search(r"\bWHERE\s+(?:[A-Za-z_][A-Za-z0-9_]*\.)?rn\s*=\s*\d+\b", s0, flags=re.I):
        return None

    def _is_word_boundary(text: str, start: int, n: int) -> bool:
        left_ok = (start == 0) or not (text[start - 1].isalnum() or text[start - 1] == "_")
        end = start + n
        right_ok = (end >= len(text)) or not (text[end].isalnum() or text[end] == "_")
        return left_ok and right_ok

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        w = kw.lower()
        n = len(w)
        depth = 0
        in_sq = False
        in_dq = False
        in_bt = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i >= start and i + n <= len(text):
                if text[i:i + n].lower() == w and _is_word_boundary(text, i, n):
                    return i
            i += 1
        return -1

    sel_pos = _find_top_level_kw(s0, "select", 0)
    from_pos = _find_top_level_kw(s0, "from", max(0, sel_pos + 6))
    group_pos = _find_top_level_kw(s0, "group by", max(0, from_pos + 4))
    if sel_pos < 0 or from_pos < 0 or group_pos < 0:
        return None

    select_part = s0[sel_pos + len("select"):from_pos].strip()
    if re.search(r"\b(MAX|MIN|SUM|AVG|COUNT)\s*\(", select_part, flags=re.I):
        return None

    order_pos = _find_top_level_kw(s0, "order by", group_pos + 8)
    limit_pos = _find_top_level_kw(s0, "limit", group_pos + 8)
    tail_candidates = [p for p in [order_pos, limit_pos] if p >= 0]
    group_end = min(tail_candidates) if tail_candidates else len(s0)

    out = (s0[:group_pos].rstrip() + " " + s0[group_end:].lstrip()).strip()
    out = re.sub(r"\s{2,}", " ", out)
    if not out:
        return None
    if not out.endswith(";"):
        out += ";"

    return out if out != sql else None


def _enforce_all_other_group_avg_self_exclusion(sql: str, question: str) -> str:
    """
    Enforce "all other ... in the same ..." semantics for grouped-average filters.

    When the question explicitly asks for "all other" peers, a window-average
    predicate in WHERE is both invalid in MySQL and semantically incomplete.
    This guardrail rewrites:
      lhs > AVG(lhs) OVER (PARTITION BY group_key)
    into:
      lhs > (
        SELECT AVG(x2.metric)
        FROM <base_table> AS x2
        WHERE x2.group_key = outer.group_key
          AND x2.<id_col> <> outer.<id_col>
      )
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql
    if not any(re.search(pat, q, flags=re.I) for pat in HELPERS_ALL_OTHER_INTENT_PATTERNS):
        return sql
    if not any(re.search(pat, q, flags=re.I) for pat in HELPERS_AVERAGE_INTENT_PATTERNS):
        return sql
    if not any(re.search(pat, q, flags=re.I) for pat in HELPERS_SAME_GROUP_INTENT_PATTERNS):
        return sql

    s = str(sql or "").strip().rstrip(";").strip()
    if not s or "where" not in s.lower():
        return sql
    # Keep this repair for top-level SELECT queries only.
    if re.search(r"\b(?:union|intersect|except|with)\b", s, flags=re.I):
        return sql

    m_sel = re.match(
        r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<from>.+?)"
        r"(?:\s+WHERE\s+(?P<where>.+?))?"
        r"(?:\s+ORDER\s+BY\s+(?P<order>.+?))?"
        r"(?:\s+LIMIT\s+(?P<limit>.+?))?\s*$",
        s,
    )
    if not m_sel:
        return sql

    select_part = (m_sel.group("select") or "").strip()
    from_core = (m_sel.group("from") or "").strip()
    where_part = (m_sel.group("where") or "").strip()
    order_part = (m_sel.group("order") or "").strip()
    limit_part = (m_sel.group("limit") or "").strip()
    if not select_part or not from_core or not where_part:
        return sql
    from_core = re.sub(
        r"(?is),\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?\s*$",
        "",
        from_core,
    ).strip()
    if not from_core:
        return sql

    alias_to_table_raw = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    alias_to_table: Dict[str, str] = {}
    for alias, table in (alias_to_table_raw or {}).items():
        a = str(alias or "").strip().strip("`").lower()
        t = str(table or "").strip().strip("`").lower()
        if a and t:
            alias_to_table[a] = t
            if t not in alias_to_table:
                alias_to_table[t] = t
    if not alias_to_table:
        return sql

    unique_tables = sorted(
        {
            str(t or "").strip().lower()
            for a, t in alias_to_table.items()
            if a and a.lower() == a and t
        }
    )
    if not unique_tables:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    if analyzer is None:
        try:
            analyzer = get_schema_analyzer()
        except Exception:
            analyzer = None

    table_cols_cache: Dict[str, List[str]] = {}

    def _table_columns(table_name: str) -> List[str]:
        table_l = str(table_name or "").strip().lower()
        if not table_l:
            return []
        if table_l in table_cols_cache:
            return table_cols_cache[table_l]
        cols: List[str] = []
        if analyzer is not None:
            try:
                for c in analyzer.get_table_columns(table_l):
                    col_l = str(c).strip("`").strip().lower()
                    if not col_l:
                        continue
                    try:
                        col_out = str(analyzer._column_original_case.get(f"{table_l}.{col_l}", col_l))
                    except Exception:
                        col_out = col_l
                    if str(col_out or "").strip():
                        cols.append(str(col_out).strip("`").strip())
            except Exception:
                cols = []
        table_cols_cache[table_l] = cols
        return cols

    def _parse_simple_ref(ref: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            str(ref or "").strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _resolve_table(qualifier: Optional[str]) -> str:
        q_l = str(qualifier or "").strip().strip("`").lower()
        if q_l:
            return str(alias_to_table.get(q_l) or (q_l if q_l in unique_tables else "")).strip().lower()
        if len(unique_tables) == 1:
            return unique_tables[0]
        return ""

    def _pick_outer_alias(table_name: str, preferred: Optional[str]) -> str:
        pref = str(preferred or "").strip().strip("`")
        pref_l = pref.lower()
        table_l = str(table_name or "").strip().lower()
        if pref and alias_to_table.get(pref_l) == table_l:
            return pref
        for a, t in alias_to_table.items():
            if a and a.lower() == a and t == table_l and a != table_l:
                return a
        return table_l

    def _identifier_tokens(text: str) -> Set[str]:
        raw = str(text or "").strip()
        if not raw:
            return set()
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ").lower()
        return {tok for tok in re.findall(r"[a-z0-9]+", raw) if tok}

    def _extract_same_group_hint(text: str) -> str:
        txt = str(text or "").strip().lower()
        if not txt:
            return ""
        boundary_terms = (
            r"when|where|after|before|ordered|sorted|with|and|then|that|"
            r"which|who|whose|including|excluding|counting|except"
        )
        patterns = [
            rf"\b(?:within|in)\s+the\s+same\s+([a-z][a-z0-9_ ]{{1,40}}?)(?=\s+\b(?:{boundary_terms})\b|[.,;]|$)",
            rf"\b(?:that|the)\s+same\s+([a-z][a-z0-9_ ]{{1,40}}?)(?=\s+\b(?:{boundary_terms})\b|[.,;]|$)",
            rf"\bsame\s+([a-z][a-z0-9_ ]{{1,40}}?)(?=\s+\b(?:{boundary_terms})\b|[.,;]|$)",
        ]
        for pat in patterns:
            m = re.search(pat, txt, flags=re.I)
            if m:
                return re.sub(r"\s+", " ", str(m.group(1) or "").strip())
        return ""

    def _infer_partition_col(metric_table: str, hint_text: str, metric_col: str, id_col: str) -> str:
        cols = [str(c).strip("`") for c in _table_columns(metric_table) if str(c).strip()]
        if not cols:
            return ""
        hint_tokens = _identifier_tokens(hint_text)
        if not hint_tokens:
            return ""
        metric_l = str(metric_col or "").strip().lower()
        id_l = str(id_col or "").strip().lower()
        best_col = ""
        best_score = 0
        for col in cols:
            col_l = str(col).strip().lower()
            if not col_l or col_l in {metric_l, id_l}:
                continue
            col_tokens = _identifier_tokens(col)
            if not col_tokens:
                continue
            overlap = hint_tokens & col_tokens
            if not overlap:
                continue
            score = (10 * len(overlap))
            if hint_tokens.issubset(col_tokens):
                score += 50
            if col_tokens.issubset(hint_tokens):
                score += 25
            if score > best_score:
                best_score = score
                best_col = col
        return best_col if best_score > 0 else ""

    def _column_with_case(table_name: str, column_name: str) -> str:
        col_l = str(column_name or "").strip("`").strip().lower()
        if not col_l:
            return ""
        for col in _table_columns(table_name):
            if str(col or "").strip("`").strip().lower() == col_l:
                return str(col).strip("`")
        return ""

    fk_map: Dict[str, Dict[str, str]] = {}
    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}
    for src, mapping in (fk_raw or {}).items():
        src_l = str(src or "").strip().lower()
        if not src_l:
            continue
        for fk_col, tgt in (mapping or {}).items():
            fk_col_l = str(fk_col or "").strip("`").strip().lower()
            tgt_l = str(tgt or "").strip().lower()
            if fk_col_l and tgt_l:
                fk_map.setdefault(src_l, {})[fk_col_l] = tgt_l

    def _resolve_metric_partition_col(metric_table: str, partition_table: str, partition_col: str) -> str:
        metric_l = str(metric_table or "").strip().lower()
        part_table_l = str(partition_table or "").strip().lower()
        part_col_l = str(partition_col or "").strip("`").strip().lower()
        if not metric_l or not part_col_l:
            return ""

        direct_col = _column_with_case(metric_l, part_col_l)
        if direct_col:
            return direct_col

        for fk_col_l, target_l in (fk_map.get(metric_l, {}) or {}).items():
            if target_l != part_table_l:
                continue
            target_id_l = str(get_id_column(target_l) or "").strip("`").strip().lower()
            if part_col_l in {fk_col_l, target_id_l}:
                return _column_with_case(metric_l, fk_col_l) or fk_col_l

        return ""

    window_pred_pat = re.compile(
        r"(?is)"
        r"(?P<lhs>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*"
        r"(?P<op>>=|<=|>|<)\s*"
        r"AVG\s*\(\s*(?P<avg>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)\s*"
        r"OVER\s*\(\s*PARTITION\s+BY\s+(?P<part>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)"
    )
    scalar_subq_pred_pat = re.compile(
        r"(?is)"
        r"(?P<lhs>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*"
        r"(?P<op>>=|<=|>|<)\s*"
        r"\(\s*SELECT\s+AVG\s*\(\s*(?P<avg>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)"
        r"\s+FROM\s+(?P<inner>.+?)\)",
    )

    m_pred = window_pred_pat.search(where_part)
    m_scalar = None if m_pred else scalar_subq_pred_pat.search(where_part)
    if not m_pred and not m_scalar:
        return sql

    lhs_ref = str((m_pred or m_scalar).group("lhs") or "").strip()
    avg_ref = str((m_pred or m_scalar).group("avg") or "").strip()
    op = str((m_pred or m_scalar).group("op") or ">").strip()

    parsed_lhs = _parse_simple_ref(lhs_ref)
    parsed_avg = _parse_simple_ref(avg_ref)
    if not parsed_lhs or not parsed_avg:
        return sql

    lhs_qual, lhs_col = parsed_lhs
    avg_qual, avg_col = parsed_avg
    if str(lhs_col).strip().lower() != str(avg_col).strip().lower():
        return sql

    metric_table = _resolve_table(lhs_qual or avg_qual)
    if not metric_table:
        return sql

    id_col = str(get_id_column(metric_table) or "").strip()
    if not id_col:
        return sql

    outer_alias = _pick_outer_alias(metric_table, lhs_qual or avg_qual)
    if not outer_alias:
        return sql

    metric_col = str(lhs_col).strip("`")
    lhs_expr = f"{lhs_qual}.{metric_col}" if lhs_qual else f"{outer_alias}.{metric_col}"
    part_qual = str(lhs_qual or avg_qual or outer_alias).strip().strip("`")
    partition_col = ""

    if m_pred:
        part_ref = str(m_pred.group("part") or "").strip()
        parsed_part = _parse_simple_ref(part_ref)
        if not parsed_part:
            return sql
        part_qual, part_col = parsed_part
        part_table = _resolve_table(part_qual)
        if part_table and part_table != metric_table:
            partition_col = _resolve_metric_partition_col(metric_table, part_table, part_col)
            if not partition_col:
                return sql
            part_qual = outer_alias
        else:
            partition_col = _resolve_metric_partition_col(metric_table, metric_table, part_col)
            if not partition_col:
                partition_col = str(part_col).strip("`")
    else:
        inner_body = str(m_scalar.group("inner") or "")
        outer_qualifiers = {
            str(x or "").strip().strip("`").lower()
            for x in [outer_alias, lhs_qual, avg_qual, metric_table]
            if str(x or "").strip()
        }
        eq_pat = re.compile(
            r"(?is)"
            r"(?P<a>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*=\s*"
            r"(?P<b>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)"
        )
        for eq in eq_pat.finditer(inner_body):
            pa = _parse_simple_ref(eq.group("a"))
            pb = _parse_simple_ref(eq.group("b"))
            if not pa or not pb:
                continue
            qa, ca = pa
            qb, cb = pb
            qa_l = str(qa or "").strip().strip("`").lower()
            qb_l = str(qb or "").strip().strip("`").lower()
            if qa_l in outer_qualifiers and _resolve_table(qa) == metric_table:
                partition_col = str(ca).strip("`")
                part_qual = str(qa or part_qual).strip().strip("`")
                break
            if qb_l in outer_qualifiers and _resolve_table(qb) == metric_table:
                partition_col = str(cb).strip("`")
                part_qual = str(qb or part_qual).strip().strip("`")
                break

        if not partition_col:
            hint = _extract_same_group_hint(q)
            partition_col = _infer_partition_col(metric_table, hint, metric_col, id_col)
            if not partition_col:
                return sql

    part_expr = f"{part_qual}.{partition_col}" if part_qual else f"{outer_alias}.{partition_col}"
    outer_id_ref = f"{outer_alias}.{id_col}"

    used_aliases = {
        str(a or "").strip().lower()
        for a in alias_to_table.keys()
        if str(a or "").strip()
    }
    alias_candidates = [f"{outer_alias}2", "x2", "t2", "sub2"]
    inner_alias = "x2"
    for cand in alias_candidates:
        cand_l = str(cand or "").strip().lower()
        if cand_l and cand_l not in used_aliases:
            inner_alias = cand
            break

    replacement = (
        f"{lhs_expr} {op} (SELECT AVG({inner_alias}.{metric_col}) "
        f"FROM {metric_table} AS {inner_alias} "
        f"WHERE {inner_alias}.{partition_col} = {part_expr} "
        f"AND {inner_alias}.{id_col} <> {outer_id_ref})"
    )
    pred_match = m_pred or m_scalar
    new_where = where_part[:pred_match.start()] + replacement + where_part[pred_match.end():]
    if new_where == where_part:
        return sql

    out_lines = [f"SELECT {select_part}", f"FROM {from_core}", f"WHERE {new_where}"]
    if order_part:
        out_lines.append(f"ORDER BY {order_part}")
    if limit_part:
        out_lines.append(f"LIMIT {limit_part}")
    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _preexecute_sql_safety_pass(sql: str, question: str = "") -> str:
    """
    Final defensive safety pass before execution.
    Applies conservative rewrites for high-risk anti-patterns and repeats until stable.
    """
    if not sql:
        return sql

    s = sql.strip()
    if not s:
        return sql
    if not s.endswith(";"):
        s += ";"

    for _ in range(3):
        prev = s

        s = _drop_aggregate_or_window_items_from_group_by(s)

        fixed = _fix_mixed_max_groupby_rownumber(s)
        if fixed:
            s = fixed

        fixed = _fix_redundant_groupby_with_rn_filter(s)
        if fixed:
            s = fixed

        fixed = _drop_redundant_top_groupby_after_rn_filter(s)
        if fixed:
            s = fixed

        fixed = _fix_inconsistent_subquery_alias(s)
        if fixed:
            s = fixed

        s = _fix_outer_order_by_for_derived_alias(s)
        s = _rewrite_missing_overall_avg_having(s, question)
        s = _enforce_all_other_group_avg_self_exclusion(s, question)
        s = _rewrite_include_zero_winner_row_identifier_source(s, question)

        # Winner-row fallback: force rewrite if query still looks like MAX-date misuse.
        # IMPORTANT: skip for "latest year + aggregate amount" intent, where MAX(date)
        # is legitimately combined with SUM(amount) under year-scoped grouping.
        latest_year_agg_intent = _question_wants_latest_year_scope_with_aggregate(question)
        if _question_wants_winner_row(question) and not latest_year_agg_intent:
            looks_like_agg_winner = bool(
                re.search(r"\bGROUP\s+BY\b", s, flags=re.I)
                and re.search(r"\b(MAX|MIN)\s*\(", s, flags=re.I)
                and not re.search(r"\bROW_NUMBER\s*\(", s, flags=re.I)
            )
            if looks_like_agg_winner or _looks_like_max_date_tiebreaker(s):
                forced = _rewrite_winner_row_guardrail(s, question, force=True)
                if forced and not (
                    "GROUP BY" in forced.upper() and "ROW_NUMBER" in forced.upper()
                ):
                    s = forced
                    s = _rewrite_include_zero_winner_row_identifier_source(s, question)

        s = _drop_aggregate_or_window_items_from_group_by(s)

        if s == prev:
            break

    s = re.sub(r"\s{2,}", " ", s).strip()
    if s and not s.endswith(";"):
        s += ";"
    return s


def _split_top_level_commas(expr: str) -> List[str]:
    """
    Split string by comma pada level top (tidak di dalam quote/paren).
    Dipakai untuk memecah SELECT list dan GROUP BY list.
    """
    if not expr:
        return []

    s = expr.strip()
    parts: List[str] = []
    buf: List[str] = []
    depth = 0
    in_sq = False
    in_dq = False
    i = 0

    while i < len(s):
        ch = s[i]

        # single quotes
        if ch == "'" and not in_dq:
            if in_sq and i + 1 < len(s) and s[i + 1] == "'":
                buf.append("''")
                i += 2
                continue
            in_sq = not in_sq
            buf.append(ch)
            i += 1
            continue

        # double quotes
        if ch == '"' and not in_sq:
            in_dq = not in_dq
            buf.append(ch)
            i += 1
            continue

        if in_sq or in_dq:
            buf.append(ch)
            i += 1
            continue

        if ch == "(":
            depth += 1
            buf.append(ch)
            i += 1
            continue
        if ch == ")":
            depth = max(0, depth - 1)
            buf.append(ch)
            i += 1
            continue

        if depth == 0 and ch == ",":
            part = "".join(buf).strip()
            if part:
                parts.append(part)
            buf = []
            i += 1
            continue

        buf.append(ch)
        i += 1

    last = "".join(buf).strip()
    if last:
        parts.append(last)

    return parts

def _extract_alias_or_colname(select_item: str) -> Optional[str]:
    """
    Ambil output column name yang bisa dipakai outer select.
    Prefer:
      1) alias dari 'AS xxx'
      2) kalau bentuk alias.col => col
      3) selain itu: None (caller boleh abort)
    """
    if not select_item:
        return None
    s = select_item.strip()

    m_as = re.search(r"\bAS\s+([A-Za-z_][A-Za-z0-9_]*)\s*$", s, flags=re.I)
    if m_as:
        return m_as.group(1)

    # kalau "t.col" tanpa AS
    m_col = re.fullmatch(
        r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
        s
    )
    if m_col:
        return m_col.group(1)

    return None

def _maybe_keep_or_alias_simple(expr: str, out_name: Optional[str]) -> str:
    """
    Kalau expr itu kolom sederhana dan nama output natural-nya sudah sama dengan out_name,
    jangan bikin 'expr AS out_name' (menghindari: customerNumber AS customerNumber).

    Alias hanya dipasang kalau:
    - out_name berbeda dari nama natural kolom, atau
    - expr bukan kolom sederhana (mis. fungsi/aritmetika), atau
    - memang perlu stabilisasi nama.
    """
    e = (expr or "").strip()
    if not e or not out_name:
        return e

    # kalau sudah ada AS, jangan ganggu
    if re.search(r"\bAS\b", e, flags=re.I):
        return e

    # nama natural yang akan keluar (mis. p.customerNumber -> customerNumber)
    natural = _extract_alias_or_colname(e)

    # kalau kolom sederhana dan natural == out_name -> jangan alias
    if natural and natural.lower() == out_name.lower() and _is_simple_column_expr(e):
        return e

    return f"{e} AS {out_name}"

def _parse_select_from_groupby(sql: str) -> Optional[dict]:
    """
    Parse sangat konservatif untuk pola:
      SELECT ... FROM ... [WHERE ...] GROUP BY ... [ORDER BY/LIMIT/HAVING...]

    Return dict berisi potongan string mentah.
    Abort jika:
      - WITH
      - subquery FROM ( ... )
      - HAVING (karena semantik aggregate sulit dipertahankan aman)
      - ROW_NUMBER (already windowed)
      - Malformed syntax (spacing issues detected)
    """
    if not sql:
        return None

    s = sql.strip().rstrip(";").strip()
    
    # SAFETY: Detect malformed syntax and abort early
    # Pattern: clause keywords stuck together without space
    if re.search(r"\b[A-Za-z0-9_]+(?:WHERE|GROUP|ORDER|HAVING|LIMIT)\b", s, flags=re.I):
        # Try one normalization pass
        s = re.sub(r"(?<=[A-Za-z0-9_)])(?=\b(?:WHERE|GROUP|ORDER|HAVING|LIMIT)\b)", " ", s, flags=re.I)
        # If still malformed, abort
        if re.search(r"\b[A-Za-z0-9_]+(?:WHERE|GROUP|ORDER|HAVING|LIMIT)\b", s, flags=re.I):
            return None

    # PRE-NORMALIZE: Fix common spacing issues
    s = re.sub(r"(\b[A-Za-z_][A-Za-z0-9_]*)\s*(?=\b(?:HAVING|ORDER|LIMIT|WHERE|GROUP)\b)", r"\1 ", s, flags=re.I)
    s = re.sub(r"\s{2,}", " ", s)  # collapse multiple spaces

    if re.match(r"^\s*with\b", s, flags=re.I):
        return None
    # This parser is intentionally for flat queries only.
    # Any derived table in FROM/JOIN can make regex clause capture unsafe
    # (inner GROUP BY/HAVING/ORDER BY may be mistaken as top-level clauses).
    if re.search(r"\b(?:from|join)\s*\(", s, flags=re.I):
        return None
    if re.search(r"\bhaving\b", s, flags=re.I):
        return None
    if re.search(r"\bROW_NUMBER\s*\(", s, flags=re.I):
        return None

    # tangkap SELECT ... FROM ... GROUP BY ... (sisanya optional)
    pat = re.compile(
        r"""
        ^\s*SELECT\s+(?P<select>.*?)
        \s+FROM\s+(?P<from>.*?)
        \s+GROUP\s+BY\s+(?P<groupby>.*?)
        (?:\s+HAVING\s+(?P<having>.*?))?
        (?P<tail>\s+(?:ORDER\s+BY|LIMIT)\b.*?|)\s*$
        """,
        flags=re.I | re.S | re.VERBOSE
    )
    m = pat.match(s)
    if not m:
        return None

    select_part = m.group("select").strip()
    from_part = m.group("from").strip()
    groupby_part = m.group("groupby").strip()
    having_part = (m.group("having") or "").strip()
    tail = (m.group("tail") or "").strip()

    # Split FROM menjadi: from_core + where_clause (optional)
    # Kita cari WHERE yang top-level (konservatif: pakai regex pertama, karena FROM (subquery) sudah di-abort).
    where_m = re.search(r"\bWHERE\b", from_part, flags=re.I)
    if where_m:
        from_core = from_part[:where_m.start()].strip()
        where_clause = from_part[where_m.start():].strip()  # include WHERE
    else:
        from_core = from_part
        where_clause = ""

    return {
        "select": select_part,
        "from_core": from_core,
        "where": where_clause,
        "groupby": groupby_part,
        "having": having_part,
        "tail": tail,
    }

def _to_raw_expr(expr: str) -> str:
    # remove AS <alias>
    expr = re.sub(r"\s+AS\s+\w+$", "", expr, flags=re.I).strip()
    # take inner of MAX(x) / MIN(x)
    m = re.match(r"\b(MAX|MIN)\s*\((.+)\)", expr, flags=re.I)
    return m.group(2).strip() if m else expr

def _looks_like_winner_row_multi_agg(select_items):
    """
    Detect patterns like:
      MAX(amount), MAX(paymentDate)
    which strongly indicate 'pick row with max value + its attributes'
    rather than true aggregation.
    """
    cols = []

    for it in select_items:
        # extract column inside MAX(...)
        m = re.search(r"max\s*\(\s*([A-Za-z0-9_.`]+)\s*\)",
                      it, flags=re.I)
        if not m:
            continue

        col = m.group(1).lower()
        cols.append(col)

    # only suspicious if there are ≥2 MAX()
    if len(cols) < 2:
        return False

    # Very strong signal of winner-row intent
    # e.g. MAX(amount) + MAX(paymentDate)
    if any("date" in c for c in cols):
        return True

    # allow more conservative fallback later
    return False

def _strip_table_prefix(expr: str) -> str:
    """
    Remove leading table aliases like  p.col -> col
    Only when expression is simple column form.
    """
    if not expr:
        return expr

    # do not touch function calls / expressions
    if "(" in expr or ")" in expr:
        return expr

    # p.customerNumber  -> customerNumber
    return re.sub(
        r"\b[A-Za-z_][A-Za-z0-9_]*\.",
        "",
        expr
    )

def _rewrite_winner_row_guardrail(sql: str, question: str, force: bool = False) -> str:
    """
    Guardrail untuk pola salah:

      SELECT k, MAX(metric), attr_from_same_row
      FROM t
      GROUP BY k

    → rewrite menjadi winner-row via ROW_NUMBER()
    """

    import re
    from typing import List

    if not sql:
        return sql

    s0 = sql.strip()

    def _has_top_level_group_by(text: str) -> bool:
        up = text.upper()
        depth = 0
        in_sq = False
        in_dq = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and up[i:i + 8] == "GROUP BY":
                left_ok = (i == 0 or not text[i - 1].isalnum())
                right_ok = (i + 8 >= len(text) or not text[i + 8].isalnum())
                if left_ok and right_ok:
                    return True
            i += 1
        return False

    # This guardrail is only for GROUP BY winner-row misuse patterns.
    # If GROUP BY exists only inside subqueries, skip and let other rewrites handle it.
    if not _has_top_level_group_by(s0):
        return sql

    # CRITICAL: Detect truly malformed queries (not false positives from subqueries)
    # Pattern: ROW_NUMBER appears BEFORE GROUP BY (malformed window)
    if re.search(r"\bROW_NUMBER\s*\([^)]*\)\s+[^;]*\bGROUP\s+BY\b", s0, flags=re.I):
        return sql  # Already corrupted window + group mix
    
    # Pattern: Multiple FROM at same nesting level (structural corruption)
    # Count top-level FROM (excluding those in subqueries)
    s_no_sub = re.sub(r"\([^)]*\)", "", s0)  # Remove all subqueries
    from_count = len(re.findall(r"\bFROM\b", s_no_sub, flags=re.I))
    if from_count > 1:
        return sql  # Multiple FROM without proper nesting = broken

    # 🚧 intent-level filter — boleh dilewati saat FORCE MODE
    if not _question_wants_winner_row(question) and not force:
        return sql

    # 🚫 jangan rewrite kalau sudah windowed
    if re.search(r"\bROW_NUMBER\s*\(", s0, flags=re.I):
        return sql

    if "GROUP BY" in s0.upper() and "ORDER BY" in s0.upper():
        # Check if GROUP BY comes AFTER ORDER BY (invalid/corrupted)
        group_pos = s0.upper().find("GROUP BY")
        order_pos = s0.upper().find("ORDER BY")
        if group_pos > order_pos and order_pos > 0:
            return sql  # SQL already corrupted, don't make it worse

    parsed = _parse_select_from_groupby(s0)
    if not parsed:
        return sql   # parsing fail = hard stop

    # Preserve qualified column references for multi-table sources.
    # Stripping prefixes in JOIN queries can create ambiguous columns
    # (e.g., customerNumber exists in both customers and payments).
    preserve_qualified = has_join(parsed.get("from_core", ""))

    select_items = _split_top_level_commas(parsed["select"])
    group_items  = _split_top_level_commas(parsed["groupby"])

    if not select_items or not group_items:
        return sql   # struktur rusak → jangan rewrite

    # GROUP BY harus kolom sederhana (kecuali FORCE MODE)
    if any(not _is_simple_column_expr(g) for g in group_items):
        if not force:
            return sql

    # =====================================================
    # PARTITION KEY (entity key)
    # =====================================================
    q_low = (question or "").lower()
    # Focus "requested output columns" detection on the projection phrase,
    # not on sorting-only phrases (e.g., "sort by customer id").
    q_low_output = re.split(r"\b(?:sort(?:ed)?\s+by|order\s+by)\b", q_low, maxsplit=1, flags=re.I)[0]
    q_tokens = set(re.findall(r"[a-z0-9]+", q_low))
    stop_tokens = set(HELPERS_WINNER_ROW_PARTITION_STOP_TOKENS)
    q_tokens -= stop_tokens

    def _group_item_score(g: str) -> int:
        gn = g.replace("`", "").lower()
        gn = re.sub(r"[^\w]+", " ", gn)
        g_tokens = set(re.findall(r"[a-z0-9]+", gn))
        g_tokens -= stop_tokens
        if not g_tokens:
            return 0
        return len(g_tokens & q_tokens)

    best_group = max(group_items, key=_group_item_score)
    if _group_item_score(best_group) > 0:
        partition_items = [best_group]
    else:
        # fallback — tetap harus ada PARTITION
        partition_items = [group_items[0]]

    # =====================================================
    # DETECT AGGREGATES
    # =====================================================

    agg_pat = re.compile(
        r"^(?P<prefix>.*?)\b(?P<fn>MAX|MIN)\s*\(\s*(?P<expr>.*?)\s*\)"
        r"\s*(?P<alias>\bAS\s+(?:`[^`]+`|\"[^\"]+\"|'[^']+'|[A-Za-z_][A-Za-z0-9_]*)\s*)?$",
        flags=re.I | re.S
    )

    agg_idx = -1
    agg_kind = None
    agg_expr = None
    agg_out_name = None
    all_aggs = []

    for i, item in enumerate(select_items):
        it = item.strip()
        m = agg_pat.match(it)
        if not m:
            continue

        if (m.group("prefix") or "").strip():
            if not force:
                return sql

        fn = (m.group("fn") or "").upper()
        expr = (m.group("expr") or "").strip()
        if not expr:
            return sql

        all_aggs.append(expr)

        # multiple aggregates → treat as misuse candidate
        if agg_idx != -1:
            agg_idx = -2
            break

        agg_idx = i
        agg_kind = fn
        agg_expr = expr

        m_as = re.search(r"\bAS\s+([A-Za-z_][A-Za-z0-9_]*)\s*$", it, flags=re.I)
        agg_out_name = m_as.group(1) if m_as else _extract_alias_or_colname(expr)

    # =====================================================
    # CASE A — multiple MAX/MIN → likely winner-row misuse
    # =====================================================
    if agg_idx == -2:

        if not force and not _looks_like_winner_row_multi_agg(select_items):
            return sql

        # pilih metric = aggregate yang paling "nilai"
        metric_terms = _winner_row_metric_terms()
        metric_candidates = [
            x for x in all_aggs
            if any(tok in x.lower() for tok in metric_terms)
        ]

        agg_expr = metric_candidates[0] if metric_candidates else all_aggs[0]
        agg_kind = "MAX"
        agg_out_name = _extract_alias_or_colname(agg_expr)

        # semua kolom lain = kandidat row attributes
        non_agg_items = [x for x in select_items]

    # =====================================================
    # CASE B — single aggregate (normal)
    # =====================================================
    else:
        if agg_idx == -1 or not agg_kind or not agg_expr:
            if not force:
                return sql

        # pilih metric yang paling masuk akal
        metric_terms = _winner_row_metric_terms()
        metric_candidates = [
            x for x in all_aggs
            if any(tok in x.lower() for tok in metric_terms)
        ]
        if metric_candidates:
            agg_expr = metric_candidates[0]

        if not _is_simple_column_expr(agg_expr):
            if not force:
                return sql

        # ambil kolom non-aggregate lain
        non_agg_items = [x for j,x in enumerate(select_items) if j != agg_idx]

        if not non_agg_items and not force:
            return sql

    # =====================================================
    # TIE BREAKER SELECTION - ROBUST VERSION
    # =====================================================

    def norm_col(z: str) -> str:
        z2 = re.sub(r"\s+","", z.replace("`","").lower())
        z2 = re.sub(r"\bas\b.*$","", z2, flags=re.I)
        return z2

    group_norm = {norm_col(g) for g in group_items}

    # Collect all candidate tie-breakers (not in GROUP BY)
    candidates = []
    for x in non_agg_items:
        base = re.sub(r"\s+AS\s+\w+\s*$","", x, flags=re.I).strip()
        
        # Extract from MAX/MIN wrapper
        agg_match = re.match(r"^(MAX|MIN)\s*\(\s*(.+?)\s*\)$", base, flags=re.I)
        if agg_match:
            base = agg_match.group(2)
        
        if norm_col(base) not in group_norm and _is_simple_column_expr(base):
            candidates.append(base)

    # Strategy: collect ALL date/time columns as tie-breakers
    tie_exprs: List[str] = []
    
    # Priority 1: Date columns (most common tie-breaker)
    for c in candidates:
        c_low = c.lower()
        if any(k in c_low for k in ["date", "time", "timestamp", "created", "updated"]):
            tie_exprs.append(_to_raw_expr(c))
    
    # Priority 2: If no date found, use first non-date candidate
    if not tie_exprs and candidates:
        tie_exprs.append(_to_raw_expr(candidates[0]))

    # =====================================================
    # ORDERING - ROBUST VERSION
    # =====================================================

    metric_dir = "DESC" if agg_kind == "MAX" else "ASC"

    # Detect tie-breaker direction from question
    ql = (question or "").lower()
    
    # Explicit signals
    if any(k in ql for k in ["latest", "most recent", "newest", "terbaru", "paling baru", "terakhir"]):
        tie_dir = "DESC"
    elif any(k in ql for k in ["earliest", "oldest", "first", "terlama", "paling lama", "pertama"]):
        tie_dir = "ASC"
    else:
        # Smart default based on context
        # For date/time columns: default DESC (latest is usually desired)
        # For other columns: ASC
        if tie_exprs and any(k in tie_exprs[0].lower() for k in ["date", "time", "timestamp"]):
            tie_dir = "DESC"
        else:
            tie_dir = "ASC"

    # Strip table prefixes only for single-table sources.
    if not preserve_qualified:
        agg_expr = _strip_table_prefix(agg_expr)
        tie_exprs = [_strip_table_prefix(t) for t in tie_exprs]

    # Build ORDER BY: metric first, then tie-breakers (limit to 2 for stability)
    order_parts = [f"{agg_expr} {metric_dir}"]
    for tie in tie_exprs[:2]:  # Take up to 2 tie-breakers
        order_parts.append(f"{tie} {tie_dir}")

    order_window = ", ".join(order_parts)

    # =====================================================
    # BUILD INNER + OUTER QUERY
    # =====================================================

    inner_items = []
    outer_items = []

    for j, x in enumerate(select_items):
        orig_alias = _extract_alias_or_colname(x)

        # --- untuk kolom aggregate: GANTI MAX(...) -> raw metric expr ---
        if j == agg_idx:
            base = agg_expr
            # Use natural column name, not the aggregate alias
            out_name = base  # "amount" instead of "max_amount"
            
        else:
            base = re.sub(
                r"\s+AS\s+[A-Za-z_][A-Za-z0-9_]*\s*$",
                "",
                x,
                flags=re.I
            ).strip()
            
            # Extract from aggregate functions for other items
            agg_match = re.match(r"^(MAX|MIN)\s*\(\s*(.+?)\s*\)$", base, flags=re.I)
            if agg_match:
                base = agg_match.group(2)
                # Use natural column name for extracted aggregates
                out_name = _strip_table_prefix(base)
            else:
                # Keep original alias for true non-aggregate columns
                out_name = orig_alias if orig_alias else _strip_table_prefix(base)
            
            if not preserve_qualified:
                base = _strip_table_prefix(base)

        inner_items.append(
            _maybe_keep_or_alias_simple(base, out_name)
        )
        outer_items.append(out_name)

    if preserve_qualified:
        partition_clean = partition_items
    else:
        partition_clean = [_strip_table_prefix(p) for p in partition_items]

    inner_items.append(
        f"ROW_NUMBER() OVER "
        f"(PARTITION BY {', '.join(partition_clean)} "
        f"ORDER BY {order_window}) AS rn"
    )

    from_core = parsed["from_core"]
    where_clause = parsed["where"]
    tail = parsed["tail"]

    inner_sql = "SELECT " + ", ".join(inner_items) + " FROM " + from_core
    if where_clause:
        inner_sql += " " + where_clause

    inner_sql = _strip_alias_if_single_table(inner_sql)

    out_sql = (
        "SELECT " + ", ".join(outer_items) +
        " FROM (" + inner_sql + ") t WHERE rn = 1"
    )

    if tail:
        out_sql += " " + tail

    return out_sql

def _rewrite_having_alias_to_expr(sql: str) -> str:
    """
    Benchmark style:
    Avoid using SELECT aliases in HAVING (e.g. HAVING totalPaymentAmount > 50000).
    Rewrite HAVING to use the original aggregate expression (e.g. HAVING SUM(p.amount) > 50000)
    when the alias maps to a SELECT expression.
    """
    if not sql:
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not sel:
        return sql

    having = sel.args.get("having")
    if not having:
        return ast.sql(dialect="mysql")

    # Build alias -> expression map from SELECT list
    alias_map = {}
    for item in sel.expressions:
        if isinstance(item, exp.Alias):
            alias = item.alias
            if alias:
                # Keep the raw expression (not the alias wrapper)
                alias_map[alias.lower()] = item.this

    if not alias_map:
        return ast.sql(dialect="mysql")

    # Replace column references in HAVING that match aliases
    def transform(node: exp.Expression) -> exp.Expression:
        # We only rewrite simple identifier references: HAVING totalPaymentAmount > 50000
        if isinstance(node, exp.Column):
            # exp.Column can be qualified; alias usually appears unqualified
            if node.table:
                return node
            name = (node.name or "").lower()
            if name in alias_map:
                return alias_map[name].copy()
        return node

    new_having = having.transform(transform)
    sel.set("having", new_having)

    return ast.sql(dialect="mysql")

def _rewrite_single_table_tuple_in_winner_row(sql: str, question: str) -> str:
    """
    Rewrite a malformed single-table winner-row tuple-IN filter into a
    canonical ROW_NUMBER() winner-row selection.

    Typical bad shape:
      SELECT key_col, metric_col, date_col
      FROM base_table t
      WHERE (t.key_col, t.date_col) IN (
        SELECT key_col, MAX(date_col)
        FROM base_table
        GROUP BY key_col, date_col
      );

    Canonical rewrite:
      SELECT t.key_col, t.metric_col, t.date_col
      FROM (
        SELECT key_col, metric_col, date_col,
               ROW_NUMBER() OVER (
                 PARTITION BY key_col
                 ORDER BY metric_col DESC, date_col DESC
               ) AS rn
        FROM base_table
      ) AS t
      WHERE t.rn = 1;

    Intentionally narrow:
    - winner-row questions only
    - single-table queries only
    - no existing ROW_NUMBER
    - tuple-IN predicate with MAX(date)-style inner subquery
    - projected key/date/metric columns must be identified safely
    """
    if not sql or not _question_wants_winner_row(question):
        return sql
    if re.search(r"\bROW_NUMBER\s*\(", sql or "", flags=re.I):
        return sql

    s0 = (sql or "").strip().rstrip(";").strip()
    if not s0:
        return sql

    def _find_top_level_kw(text: str, keyword: str, start: int = 0) -> int:
        w = keyword.lower()
        n = len(w)
        depth = 0
        in_sq = in_dq = in_bt = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i >= start and i + n <= len(text):
                left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
                right_ok = (i + n) >= len(text) or not (text[i + n].isalnum() or text[i + n] == "_")
                if left_ok and right_ok and text[i:i + n].lower() == w:
                    return i
            i += 1
        return -1

    def _split_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m:
            return (item or "").strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_qualified_col(expr: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            (expr or "").strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _expr_norm(expr: str) -> str:
        return re.sub(r"[\s`]+", "", str(expr or "").lower())

    def _safe_alias(name: str, fallback: str) -> str:
        raw = str(name or "").strip().strip("`'\"")
        raw = re.sub(r"\s+", "_", raw)
        raw = re.sub(r"[^A-Za-z0-9_]", "", raw)
        if not raw or not re.match(r"[A-Za-z_]", raw[0]):
            raw = fallback
        return raw

    sel_pos = _find_top_level_kw(s0, "select", 0)
    from_pos = _find_top_level_kw(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos < 0 or from_pos < 0:
        return sql

    where_pos = _find_top_level_kw(s0, "where", from_pos + len("from"))
    if where_pos < 0:
        return sql

    group_pos = _find_top_level_kw(s0, "group by", where_pos + len("where"))
    having_pos = _find_top_level_kw(s0, "having", where_pos + len("where"))
    if group_pos >= 0 or having_pos >= 0:
        return sql

    order_pos = _find_top_level_kw(s0, "order by", where_pos + len("where"))
    limit_pos = _find_top_level_kw(s0, "limit", where_pos + len("where"))
    tail_candidates = [p for p in [order_pos, limit_pos] if p >= 0]
    body_end = min(tail_candidates) if tail_candidates else len(s0)

    select_part = s0[sel_pos + len("select"):from_pos].strip()
    from_core = s0[from_pos + len("from"):where_pos].strip()
    where_body = s0[where_pos + len("where"):body_end].strip()
    tail_part = s0[body_end:].strip() if body_end < len(s0) else ""

    if not select_part or not from_core or not where_body:
        return sql
    if re.search(r"\bJOIN\b", from_core, flags=re.I) or "," in from_core:
        return sql
    if _has_top_level_or(where_body):
        return sql

    m_from = re.match(
        r"""(?is)^\s*`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?)?\s*$""",
        from_core,
    )
    if not m_from:
        return sql
    base_table = (m_from.group("table") or "").strip()
    base_alias = (m_from.group("alias") or base_table).strip()
    if not base_table or not base_alias:
        return sql

    tuple_pat = re.compile(
        r"(?is)^\s*"
        r"\(\s*(?P<lhs_key>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)"
        r"\s*,\s*(?P<lhs_date>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)"
        r"\s+IN\s*\(\s*SELECT\s+"
        r"(?P<rhs_key>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*,"
        r"\s*MAX\s*\(\s*(?P<rhs_date>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)"
        r"\s+FROM\s+`?(?P<sub_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?[A-Za-z_][A-Za-z0-9_]*`?)?"
        r"\s+GROUP\s+BY\s+(?P<group_items>.+?)\s*\)\s*$",
        flags=re.I | re.S,
    )

    tuple_idx = None
    tuple_match = None
    conjuncts = _split_top_level_and(where_body)
    for idx, cond in enumerate(conjuncts):
        m = tuple_pat.match((cond or "").strip())
        if m:
            tuple_idx = idx
            tuple_match = m
            break
    if tuple_match is None or tuple_idx is None:
        return sql

    lhs_key_q = _parse_qualified_col(tuple_match.group("lhs_key") or "")
    lhs_date_q = _parse_qualified_col(tuple_match.group("lhs_date") or "")
    rhs_key_q = _parse_qualified_col(tuple_match.group("rhs_key") or "")
    rhs_date_q = _parse_qualified_col(tuple_match.group("rhs_date") or "")
    if not lhs_key_q or not lhs_date_q or not rhs_key_q or not rhs_date_q:
        return sql

    lhs_key_alias, lhs_key_col = lhs_key_q
    lhs_date_alias, lhs_date_col = lhs_date_q
    _rhs_key_alias, rhs_key_col = rhs_key_q
    _rhs_date_alias, rhs_date_col = rhs_date_q
    sub_table = (tuple_match.group("sub_table") or "").strip()

    if (lhs_key_alias or base_alias).lower() != base_alias.lower():
        return sql
    if (lhs_date_alias or base_alias).lower() != base_alias.lower():
        return sql
    if lhs_key_col.lower() != rhs_key_col.lower():
        return sql
    if lhs_date_col.lower() != rhs_date_col.lower():
        return sql
    if sub_table.lower() != base_table.lower():
        return sql

    group_items = [g.strip() for g in _split_top_level_commas(tuple_match.group("group_items") or "") if g.strip()]
    if not group_items:
        return sql
    group_norms = {_expr_norm(g) for g in group_items}
    lhs_key_norm = _expr_norm(lhs_key_col)
    lhs_date_norm = _expr_norm(lhs_date_col)
    if lhs_key_norm not in group_norms and _expr_norm(tuple_match.group("rhs_key") or "") not in group_norms:
        return sql

    select_items = _split_top_level_commas(select_part)
    if not select_items:
        return sql

    projected: List[Tuple[str, str, str]] = []
    used_aliases: Set[str] = set()
    key_expr = None
    key_pair: Optional[Tuple[str, str]] = None
    date_expr = None
    date_pair: Optional[Tuple[str, str]] = None
    metric_candidates: List[Tuple[str, str]] = []

    for idx, item in enumerate(select_items):
        expr_raw, alias_raw = _split_alias(item)
        parsed_col = _parse_qualified_col(expr_raw)
        if not parsed_col:
            return sql
        qual, col = parsed_col
        if qual and qual.lower() != base_alias.lower():
            return sql

        alias_name = _safe_alias(alias_raw or col, f"col_{idx + 1}")
        if alias_name.lower() in used_aliases:
            return sql
        used_aliases.add(alias_name.lower())

        col_norm = _expr_norm(col)
        projected.append((expr_raw, alias_name, col_norm))
        if col_norm == lhs_key_norm:
            key_expr = expr_raw
            key_pair = (expr_raw, alias_name)
            continue
        if col_norm == lhs_date_norm:
            date_expr = expr_raw
            date_pair = (expr_raw, alias_name)
            continue
        metric_candidates.append((expr_raw, alias_name))

    if key_expr is None:
        key_expr = (tuple_match.group("lhs_key") or lhs_key_col).strip()
        key_pair = (key_expr, _safe_alias(lhs_key_col, "partition_key"))
    if date_expr is None:
        date_expr = (tuple_match.group("lhs_date") or lhs_date_col).strip()
        date_pair = (date_expr, _safe_alias(lhs_date_col, "tie_value"))
    if date_pair is None:
        date_pair = (date_expr, _safe_alias(lhs_date_col, "tie_value"))
    if key_pair is None:
        key_pair = (key_expr, _safe_alias(lhs_key_col, "partition_key"))

    if not metric_candidates:
        return sql

    q_low = (question or "").lower()
    metric_terms = _winner_row_metric_terms()
    metric_alt = _regex_alt_from_terms(metric_terms, r"$^")

    def _candidate_score(expr_raw: str) -> int:
        parsed = _parse_qualified_col(expr_raw)
        col_name = (parsed[1] if parsed else expr_raw).lower()
        score = 0
        if any(term in col_name for term in metric_terms):
            score += 5
        if any(term in q_low for term in metric_terms) and any(term in col_name for term in metric_terms):
            score += 5
        if re.search(r"\b(?:largest|highest|biggest|greatest|max(?:imum)?|top|best)\b", q_low):
            score += 1
        if re.search(r"\b(?:smallest|lowest|least|min(?:imum)?)\b", q_low):
            score += 1
        return score

    metric_expr, _metric_alias = max(
        metric_candidates,
        key=lambda item: (_candidate_score(item[0]), -len(item[0])),
    )
    metric_pair = (metric_expr, _metric_alias)

    metric_desc = not bool(re.search(r"\b(?:smallest|lowest|least|min(?:imum)?)\b", q_low))
    date_desc = not bool(re.search(r"\b(?:earliest|oldest|first)\b", q_low))

    latest_date_primary = bool(
        re.search(r"\b(?:latest|most\s+recent|newest)\b", q_low)
        and re.search(r"\b(?:date|time)\b", q_low)
    )
    metric_primary = bool(
        re.search(r"\b(?:largest|highest|biggest|greatest|max(?:imum)?|top|best|smallest|lowest|least|min(?:imum)?)\b", q_low)
        and metric_alt != r"$^"
        and re.search(rf"\b{metric_alt}\b", q_low)
    )
    if latest_date_primary and not metric_primary:
        rank_items = [
            f"{date_expr} {'DESC' if date_desc else 'ASC'}",
            f"{metric_expr} {'DESC' if metric_desc else 'ASC'}",
        ]
    else:
        rank_items = [
            f"{metric_expr} {'DESC' if metric_desc else 'ASC'}",
            f"{date_expr} {'DESC' if date_desc else 'ASC'}",
        ]

    requested_segment = _extract_requested_output_segment(question)

    def _question_explicitly_requests_column(col_name: str) -> bool:
        seg = str(requested_segment or "").strip().lower()
        if not seg:
            return False
        variants: Set[str] = set()
        clean = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_name or ""))
        clean = clean.replace("_", " ").strip().lower()
        if clean:
            variants.add(clean)
        try:
            variants.update(
                str(v or "").replace("_", " ").strip().lower()
                for v in (get_column_entity_variants(base_table, col_name) or set())
                if str(v or "").strip()
            )
        except Exception:
            pass
        for variant in variants:
            pat = re.escape(variant).replace(r"\ ", r"\s+")
            if pat and re.search(rf"\b{pat}\b", seg, flags=re.I):
                return True
        return False

    output_pairs: List[Tuple[str, str]] = []
    output_aliases: Set[str] = set()
    output_exprs: Set[str] = set()

    def _add_output(pair: Tuple[str, str]) -> None:
        expr, alias = pair
        expr_norm = _expr_norm(expr)
        alias_norm = str(alias or "").strip().lower()
        if not expr_norm or not alias_norm:
            return
        if expr_norm in output_exprs or alias_norm in output_aliases:
            return
        output_exprs.add(expr_norm)
        output_aliases.add(alias_norm)
        output_pairs.append((expr, alias))

    _add_output(key_pair)
    _add_output(metric_pair)
    _add_output(date_pair)

    core_exprs = {_expr_norm(key_pair[0]), _expr_norm(metric_pair[0]), _expr_norm(date_pair[0])}
    for expr_raw, alias_name, col_norm in projected:
        if _expr_norm(expr_raw) in core_exprs:
            continue
        if _question_explicitly_requests_column(col_norm):
            _add_output((expr_raw, alias_name))

    inner_select = [f"{expr} AS {alias}" for expr, alias in output_pairs]
    inner_select.append(
        f"ROW_NUMBER() OVER (PARTITION BY {key_expr} ORDER BY {', '.join(rank_items)}) AS rn"
    )

    remaining_conj = [c.strip() for i, c in enumerate(conjuncts) if i != tuple_idx and c.strip()]
    inner_where = f"\n  WHERE {' AND '.join(remaining_conj)}" if remaining_conj else ""
    outer_select = ", ".join(f"t.{alias}" for _, alias in output_pairs)
    tail_clause = f"\n{tail_part}" if tail_part else ""

    return (
        f"SELECT {outer_select}\n"
        f"FROM (\n"
        f"  SELECT {', '.join(inner_select)}\n"
        f"  FROM {from_core}"
        f"{inner_where}\n"
        f") AS t\n"
        f"WHERE t.rn = 1"
        f"{tail_clause};"
    )


def _winner_row_final_sanity(sql: str, question: str) -> str:
    if not sql or not _question_wants_winner_row(question):
        return sql
    if re.search(r"\bROW_NUMBER\s*\(", sql, flags=re.I):
        return sql

    # Kalau query sudah masuk pola HAVING-subquery, kita anggap "suspect"
    # dan kita coba tetap rewrite, bukan abort.
    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    sel = ast if isinstance(ast, exp.Select) else ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql

    from_expr = sel.args.get("from") or sel.args.get("from_")
    if not from_expr:
        return sql

    grp = sel.args.get("group")
    if not grp or not grp.expressions:
        return sql

    # Cari tepat 1 MAX/MIN aggregate di SELECT list
    agg_items = []
    nonagg_items = []
    for item in sel.expressions:
        base = item.this if isinstance(item, exp.Alias) else item
        if base.find(exp.Max) or base.find(exp.Min):
            agg_items.append(item)
        else:
            nonagg_items.append(item)

    if len(agg_items) != 1:
        return sql

    agg_item = agg_items[0]
    agg_base = agg_item.this if isinstance(agg_item, exp.Alias) else agg_item

    # Ambil expr metric di dalam MAX/MIN
    metric_expr = None
    agg_kind = None
    if isinstance(agg_base, exp.Max):
        metric_expr = agg_base.this
        agg_kind = "MAX"
    elif isinstance(agg_base, exp.Min):
        metric_expr = agg_base.this
        agg_kind = "MIN"
    else:
        # bisa juga Max/Min nested; fallback
        m = agg_base.find(exp.Max) or agg_base.find(exp.Min)
        if isinstance(m, exp.Max):
            metric_expr = m.this
            agg_kind = "MAX"
        elif isinstance(m, exp.Min):
            metric_expr = m.this
            agg_kind = "MIN"

    if metric_expr is None:
        return sql

    # group-by set (string normalize)
    def norm(e: exp.Expression) -> str:
        return e.sql(dialect="mysql").strip().lower()

    group_set = {norm(g) for g in grp.expressions}

    # Deteksi ada non-agg select yang bukan group-by => winner-row misuse
    nonagg_not_in_group = []
    for item in nonagg_items:
        base = item.this if isinstance(item, exp.Alias) else item
        # skip literal/star
        if isinstance(base, (exp.Literal, exp.Star)):
            continue
        if norm(base) not in group_set:
            nonagg_not_in_group.append(item)

    if not nonagg_not_in_group:
        return sql  # bukan winner-row misuse

    # Tentukan partition columns: pilih group-by yang nampak "key"
    key_like = []
    for g in grp.expressions:
        s = norm(g)
        if any(k in s for k in ["id", "number", "code"]):
            key_like.append(g)

    partition_exprs = key_like or [grp.expressions[0]]

    # Tie-breaker: cari kolom non-agg yang mengandung 'date'
    tie_expr = None
    for item in nonagg_not_in_group:
        base = item.this if isinstance(item, exp.Alias) else item
        if "date" in norm(base):
            tie_expr = base
            break
    if tie_expr is None:
        # fallback: pakai nonagg pertama yang "not in group"
        base = nonagg_not_in_group[0].this if isinstance(nonagg_not_in_group[0], exp.Alias) else nonagg_not_in_group[0]
        tie_expr = base

    # Build ORDER BY window
    metric_dir = "DESC" if agg_kind == "MAX" else "ASC"

    order_by = exp.Order(expressions=[
        exp.Ordered(this=metric_expr.copy(), desc=(metric_dir == "DESC")),
        exp.Ordered(this=tie_expr.copy(), desc=False),
    ])

    rn = exp.Window(
        this=exp.RowNumber(),
        partition_by=exp.Partition(expressions=[p.copy() for p in partition_exprs]),
        order=order_by,
    )

    # Inner select: semua output yang diminta, tapi MAX/MIN diganti jadi metric_expr
    inner_select_exprs = []
    outer_select_exprs = []

    for item in sel.expressions:
        if item is agg_item:
            alias = item.alias_or_name or "value"
            inner_select_exprs.append(exp.alias_(metric_expr.copy(), alias, quoted=False))
            outer_select_exprs.append(exp.column(alias, table="t"))
        else:
            # pastikan tiap item punya alias supaya outer stabil
            if isinstance(item, exp.Alias):
                alias = item.alias
                inner_select_exprs.append(item.copy())
                outer_select_exprs.append(exp.column(alias, table="t"))
            else:
                # derive alias dari column name kalau memungkinkan
                name = item.name if isinstance(item, exp.Column) else None
                if not name:
                    return sql  # konservatif: abort jika kompleks
                inner_select_exprs.append(exp.alias_(item.copy(), name, quoted=False))
                outer_select_exprs.append(exp.column(name, table="t"))

    inner_select_exprs.append(exp.alias_(rn, "rn", quoted=False))

    # Rebuild query: SELECT outer FROM (SELECT inner FROM ... WHERE ...) t WHERE rn=1
    inner = exp.Select(expressions=inner_select_exprs).from_(from_expr.copy())
    joins = sel.args.get("joins")
    if joins:
        inner.set("joins", [j.copy() for j in joins])
    if sel.args.get("where"):
        inner.set("where", sel.args["where"].copy())

    outer = exp.Select(expressions=outer_select_exprs).from_(
        exp.Subquery(this=inner, alias=exp.TableAlias(this=exp.to_identifier("t")))
    ).where(exp.EQ(this=exp.column("rn", table="t"), expression=exp.Literal.number(1)))

    out_sql = outer.sql(dialect="mysql")

    # sqlglot's MySQL serializer expands ascending ORDER BY on plain columns into:
    #   CASE WHEN alias.col IS NULL THEN 1 ELSE 0 END, alias.col ASC
    # For this winner-row rewrite, those wrappers are only serializer noise on the
    # synthetic ranked aliases we just created. Collapse them back to the direct
    # column ORDER BY form so the final SQL stays readable.
    ordered_aliases = list(dict.fromkeys([partition_alias] + rank_aliases))
    for rel_alias in ("c", "t"):
        for alias in ordered_aliases:
            pat = re.compile(
                rf"CASE\s+WHEN\s+{re.escape(rel_alias)}\.`?{re.escape(alias)}`?\s+IS\s+NULL\s+THEN\s+1\s+ELSE\s+0\s+END\s*,\s*"
                rf"{re.escape(rel_alias)}\.`?{re.escape(alias)}`?\s+ASC",
                flags=re.IGNORECASE,
            )
            out_sql = pat.sub(f"{rel_alias}.{alias} ASC", out_sql)

    return out_sql


def _rewrite_grouped_winner_row_ranked_aggregate(sql: str, question: str) -> str:
    """
    Repair grouped aggregate near-misses for winner-row questions.

    Typical bad shape:
      SELECT group_key, candidate_cols, metric_aliases...
      FROM ...
      GROUP BY ...
      ORDER BY group_key ASC, metric1 DESC, metric2 DESC, stable_key ASC

    The query already computes the candidate grain correctly, but it still
    returns every candidate row. Wrap it into:
      1) aggregated candidate subquery
      2) ROW_NUMBER() OVER (PARTITION BY group_key ORDER BY metric/tiebreakers)
      3) outer WHERE rn = 1

    Conservative guardrails:
    - only for clear winner-row questions
    - only if SQL has GROUP BY + ORDER BY and no ROW_NUMBER yet
    - only if every SELECT expression has a stable outer alias
    - only if ORDER BY items can be mapped back to projected columns
    """
    if not sql or not _question_wants_winner_row(question):
        return sql
    if re.search(r"\bROW_NUMBER\s*\(", sql, flags=re.I):
        return sql

    def _fallback_simple_wrapper(sql_text: str) -> str:
        parsed = _parse_select_from_groupby(sql_text)
        if not parsed:
            return sql_text
        if (parsed.get("where") or "").strip():
            return sql_text
        if (parsed.get("having") or "").strip():
            return sql_text

        groupby = (parsed.get("groupby") or "").strip()
        tail = (parsed.get("tail") or "").strip()
        if not groupby or not tail:
            return sql_text

        m_order = re.match(r"(?is)^ORDER\s+BY\s+(.+)$", tail)
        if not m_order:
            return sql_text
        order_items = _split_top_level_commas(m_order.group(1) or "")
        if len(order_items) < 2:
            return sql_text

        def _split_expr_alias(item: str) -> tuple[str, Optional[str]]:
            m = re.match(
                r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
                (item or "").strip(),
            )
            if not m:
                return (item or "").strip(), None
            return (m.group(1) or "").strip(), (m.group(2) or "").strip()

        def _parse_simple_col(expr: str) -> Optional[tuple[str, str]]:
            m = re.match(
                r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
                (expr or "").strip(),
            )
            if not m:
                return None
            return str(m.group(1) or "").strip(), str(m.group(2) or "").strip()

        def _norm_expr(expr: str) -> str:
            return re.sub(r"[\s`]+", "", str(expr or "").lower())

        def _strip_order_dir(item: str) -> tuple[str, bool]:
            text = (item or "").strip()
            m = re.match(r"(?is)^(.*?)(?:\s+(ASC|DESC))?$", text)
            core = (m.group(1) or "").strip() if m else text
            desc = bool(m and (m.group(2) or "").strip().upper() == "DESC")
            return core, desc

        select_items = _split_top_level_commas(parsed.get("select", ""))
        if not select_items:
            return sql_text

        projected_items: List[str] = []
        projected_nonagg_exprs: List[str] = []
        alias_names: List[str] = []
        alias_to_expr: Dict[str, str] = {}
        alias_is_agg: Dict[str, bool] = {}
        group_aliases: Set[str] = set()
        seen_aliases: Set[str] = set()

        for raw_item in select_items:
            expr, out_alias = _split_expr_alias(raw_item)
            expr_clean = (expr or "").strip()
            parsed_col = _parse_simple_col(expr_clean)
            is_agg = bool(re.search(r"(?is)\b(?:SUM|COUNT|AVG|MIN|MAX)\s*\(", expr_clean))
            if out_alias:
                alias_name = out_alias.strip("`'\"")
            elif parsed_col:
                alias_name = parsed_col[1]
            else:
                return sql_text

            if not alias_name:
                return sql_text
            alias_key = alias_name.lower()
            if alias_key in seen_aliases:
                return sql_text
            seen_aliases.add(alias_key)
            projected_items.append((raw_item or "").strip())
            alias_names.append(alias_name)
            alias_to_expr[alias_key] = expr_clean
            alias_is_agg[alias_key] = is_agg
            if not is_agg:
                projected_nonagg_exprs.append(expr_clean)
            if parsed_col and not is_agg:
                group_aliases.add(alias_key)

        order_aliases: List[str] = []
        order_dirs: List[bool] = []
        for raw_item in order_items:
            core, desc = _strip_order_dir(raw_item)
            core_l = core.strip("`'\"").lower()
            chosen: Optional[str] = None
            if core_l in alias_to_expr:
                chosen = next((a for a in alias_names if a.lower() == core_l), None)
            else:
                parsed_col = _parse_simple_col(core)
                if parsed_col:
                    col_name = parsed_col[1].lower()
                    chosen = next((a for a in alias_names if a.lower() == col_name), None)
                if not chosen:
                    norm_core = _norm_expr(core)
                    for alias_name in alias_names:
                        if _norm_expr(alias_to_expr.get(alias_name.lower(), "")) == norm_core:
                            chosen = alias_name
                            break
            if not chosen or chosen in order_aliases:
                continue
            order_aliases.append(chosen)
            order_dirs.append(desc)

        if len(order_aliases) < 2:
            return sql_text

        partition_alias = order_aliases[0]
        if alias_is_agg.get(partition_alias.lower(), False):
            return sql_text
        if partition_alias.lower() not in group_aliases:
            return sql_text

        candidate_identity_aliases = [
            alias for alias in alias_names
            if alias.lower() != partition_alias.lower()
            and not alias_is_agg.get(alias.lower(), False)
        ]
        if not candidate_identity_aliases:
            return sql_text

        rank_aliases = order_aliases[1:]
        rank_dirs = order_dirs[1:]
        if not rank_aliases:
            return sql_text

        candidate_groupby = ", ".join(dict.fromkeys(projected_nonagg_exprs))
        if not candidate_groupby:
            return sql_text
        candidate_select = ", ".join(projected_items)
        candidate_sql = (
            f"SELECT {candidate_select} FROM {parsed['from_core'].strip()} "
            f"GROUP BY {candidate_groupby}"
        )
        candidate_sub = f"({candidate_sql}) AS c"
        ranked_order = ", ".join(
            f"c.{alias} {'DESC' if desc else 'ASC'}"
            for alias, desc in zip(rank_aliases, rank_dirs)
        )
        ranked_sql = (
            "SELECT "
            + ", ".join(f"c.{alias}" for alias in alias_names)
            + f", ROW_NUMBER() OVER (PARTITION BY c.{partition_alias} ORDER BY {ranked_order}) AS rn "
            + f"FROM {candidate_sub}"
        )
        outer_sql = (
            "SELECT "
            + ", ".join(f"t.{alias}" for alias in alias_names)
            + f" FROM ({ranked_sql}) AS t WHERE t.rn = 1 "
            + f"ORDER BY t.{partition_alias} {'DESC' if order_dirs[0] else 'ASC'}"
        )
        return outer_sql + ";"

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return _fallback_simple_wrapper(sql)

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return _fallback_simple_wrapper(sql)

    sel = ast if isinstance(ast, exp.Select) else ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql

    grp = sel.args.get("group")
    if not grp or not getattr(grp, "expressions", None):
        return sql
    if sel.args.get("limit"):
        return sql

    def _norm_expr(e: exp.Expression) -> str:
        return re.sub(r"\s+", " ", e.sql(dialect="mysql").strip().lower())

    candidate_ast = ast.copy()
    candidate_sel = candidate_ast if isinstance(candidate_ast, exp.Select) else candidate_ast.find(exp.Select)
    if not isinstance(candidate_sel, exp.Select):
        return sql

    # Drop exact duplicate projected columns before building the ranked wrapper.
    # Model retries sometimes echo the same visible identifier columns twice,
    # which makes outer aliasing ambiguous but does not add semantics.
    dedup_projection_items: List["exp.Expression"] = []
    seen_projection_keys: Set[Tuple[str, str]] = set()
    alias_to_expr_norm: Dict[str, str] = {}
    for item in candidate_sel.expressions or []:
        base = item.this if isinstance(item, exp.Alias) else item
        alias_name = ""
        if isinstance(item, exp.Alias):
            alias_name = str(item.alias or "").strip()
        elif isinstance(base, exp.Column):
            alias_name = str(base.name or "").strip()

        expr_norm = _norm_expr(base)
        alias_norm = alias_name.lower()
        proj_key = (expr_norm, alias_norm)
        if proj_key in seen_projection_keys:
            continue
        if alias_norm and alias_norm in alias_to_expr_norm and alias_to_expr_norm[alias_norm] != expr_norm:
            return sql
        seen_projection_keys.add(proj_key)
        if alias_norm:
            alias_to_expr_norm[alias_norm] = expr_norm
        dedup_projection_items.append(item.copy())

    if not dedup_projection_items:
        return sql
    candidate_sel.set("expressions", dedup_projection_items)

    # Rebuild the grouped candidate layer from the visible non-aggregate
    # projection only. This avoids carrying malformed or stale GROUP BY terms
    # (for example aliases from an earlier draft shape) into the ranked wrapper.
    rebuilt_group_exprs: List[exp.Expression] = []
    rebuilt_group_norms: Set[str] = set()
    for item in candidate_sel.expressions:
        base = item.this if isinstance(item, exp.Alias) else item
        contains_aggregate = isinstance(base, exp.AggFunc) or any(True for _ in base.find_all(exp.AggFunc))
        if contains_aggregate:
            continue
        base_norm = _norm_expr(base)
        if not base_norm or base_norm in rebuilt_group_norms:
            continue
        rebuilt_group_exprs.append(base.copy())
        rebuilt_group_norms.add(base_norm)
    if not rebuilt_group_exprs:
        return sql
    candidate_sel.set("group", exp.Group(expressions=rebuilt_group_exprs))

    group_expr_norms = {
        _norm_expr(g)
        for g in (candidate_sel.args.get("group").expressions or [])
        if isinstance(g, exp.Expression)
    }

    alias_names: List[str] = []
    expr_to_alias: Dict[str, str] = {}
    alias_by_lower: Dict[str, str] = {}
    alias_expr_sql: Dict[str, str] = {}
    alias_is_agg: Dict[str, bool] = {}
    alias_explicit: Dict[str, bool] = {}
    alias_simple_col: Dict[str, Tuple[str, str]] = {}
    group_alias_candidates: List[str] = []

    for idx, item in enumerate(candidate_sel.expressions):
        if isinstance(item, exp.Star):
            return sql

        if isinstance(item, exp.Alias):
            alias = item.alias
            base = item.this
            explicit_alias = True
        else:
            base = item
            if isinstance(base, exp.Column):
                alias = base.name
            else:
                # Complex expressions need explicit aliases so the ranked layer
                # can reference them safely.
                return sql
            explicit_alias = False

        alias = (alias or f"col_{idx + 1}").strip()
        if not alias or alias.lower() == "rn" or alias.lower() in alias_by_lower:
            return sql

        alias_names.append(alias)
        alias_by_lower[alias.lower()] = alias
        expr_norm = _norm_expr(base)
        expr_to_alias[expr_norm] = alias
        alias_expr_sql[alias] = base.sql(dialect="mysql")
        alias_is_agg[alias] = isinstance(base, exp.AggFunc) or any(True for _ in base.find_all(exp.AggFunc))
        alias_explicit[alias] = explicit_alias
        if isinstance(base, exp.Column):
            alias_simple_col[alias] = (
                (base.table or "").strip().lower(),
                (base.name or "").strip().lower(),
            )
        if expr_norm in group_expr_norms:
            group_alias_candidates.append(alias)

    def _text_terms(text: str) -> Set[str]:
        normalized = re.sub(
            r"([a-z0-9])([A-Z])",
            r"\1 \2",
            str(text or "").replace("_", " "),
        ).lower()
        return {tok for tok in re.findall(r"[a-z0-9]+", normalized) if tok}

    def _alias_terms(alias_name: str) -> Set[str]:
        return _text_terms(alias_name) | _text_terms(alias_expr_sql.get(alias_name, ""))

    def _term_tokens(terms: Sequence[str]) -> Set[str]:
        out: Set[str] = set()
        for term in terms or []:
            out.update(_text_terms(str(term or "")))
        return out

    quantity_alias_terms = _term_tokens(ordered_quantity_repair_quantity_terms())
    quantity_question_terms = quantity_alias_terms | _term_tokens(ordered_quantity_repair_order_terms())
    count_family_terms = (
        _term_tokens(HELPERS_COUNT_INTENT_TERMS)
        - _term_tokens(HELPERS_METRIC_AGG_INTENT_TERMS)
        - set(semantic_question_token_stopwords())
    )
    value_family_terms = _winner_row_metric_terms() - quantity_alias_terms - count_family_terms
    quantity_question_alt = _regex_alt_from_terms(quantity_question_terms, r"$^")
    value_question_alt = _regex_alt_from_terms(value_family_terms, r"$^")
    count_question_alt = _regex_alt_from_terms(count_family_terms, r"$^")

    def _alias_family(alias_name: str) -> Optional[str]:
        terms = _alias_terms(alias_name)
        if terms & quantity_alias_terms:
            return "quantity"
        if terms & value_family_terms:
            return "value"
        if terms & count_family_terms:
            return "count"
        return None

    order = sel.args.get("order")
    order_aliases: List[str] = []
    order_dirs: List[bool] = []
    if isinstance(order, exp.Order) and getattr(order, "expressions", None):
        for ordered in order.expressions:
            expr = ordered.this
            desc = bool(ordered.args.get("desc"))
            alias = None

            expr_norm = _norm_expr(expr)
            alias = expr_to_alias.get(expr_norm)

            if alias is None and isinstance(expr, exp.Column):
                alias = alias_by_lower.get((expr.name or "").lower())
                if alias is None:
                    bare_name = (expr.name or "").lower()
                    matches = [a for low, a in alias_by_lower.items() if low == bare_name]
                    if len(matches) == 1:
                        alias = matches[0]

            if alias is None:
                continue

            if alias in order_aliases:
                continue
            order_aliases.append(alias)
            order_dirs.append(desc)

    partition_alias = order_aliases[0] if order_aliases else ""
    partition_dir = order_dirs[0] if order_dirs else False
    rank_aliases = order_aliases[1:]
    rank_dirs = order_dirs[1:]

    if not partition_alias:
        q_low = (question or "").lower()
        group_hint_terms: Set[str] = set()
        m_group = re.search(
            r"\b(?:within|for\s+each|for\s+every|per|each)\s+(?P<seg>[a-z0-9_\s-]{1,64})",
            q_low,
            flags=re.I,
        )
        if m_group:
            group_hint_terms = _text_terms(m_group.group("seg") or "")
            group_hint_terms -= {
                "the", "a", "an", "and", "or", "with", "without", "of",
                "pick", "keep", "show", "return", "greatest", "highest",
                "largest", "smallest", "least", "most", "latest", "product",
            }
        candidate_groups = list(dict.fromkeys(group_alias_candidates))
        if not candidate_groups:
            candidate_groups = [
                alias for alias in alias_names
                if not alias_is_agg.get(alias, False)
            ]
        if candidate_groups:
            if group_hint_terms:
                scored_groups = [
                    (len(_alias_terms(alias) & group_hint_terms), alias)
                    for alias in candidate_groups
                ]
                best_score, best_alias = max(scored_groups, key=lambda kv: kv[0])
                if best_score > 0:
                    partition_alias = best_alias
            if not partition_alias:
                non_identifier_groups = [
                    alias for alias in candidate_groups
                    if not (_alias_terms(alias) & {"id", "identifier", "code", "number", "key"})
                ]
                partition_alias = non_identifier_groups[0] if non_identifier_groups else candidate_groups[0]

    if not rank_aliases:
        q_low = (question or "").lower()
        aggregate_aliases = [
            alias for alias in alias_names
            if alias_is_agg.get(alias, False)
        ]
        identifier_aliases = [
            alias for alias in alias_names
            if alias != partition_alias and (_alias_terms(alias) & {"id", "identifier", "code", "number", "key"})
        ]
        primary_family: Optional[str] = None
        if (
            quantity_question_alt != r"$^"
            and re.search(
                rf"\b(?:greatest|largest|highest|most|best[-\s]?selling|top)\b.{{0,80}}\b{quantity_question_alt}\b",
                q_low,
                flags=re.I | re.S,
            )
        ):
            primary_family = "quantity"
        elif (
            value_question_alt != r"$^"
            and re.search(
                rf"\b(?:greatest|largest|highest|most|best|top)\b.{{0,80}}\b{value_question_alt}\b",
                q_low,
                flags=re.I | re.S,
            )
        ):
            primary_family = "value"
        elif (
            count_question_alt != r"$^"
            and re.search(
                rf"\b(?:greatest|largest|highest|most)\b.{{0,80}}\b{count_question_alt}\b",
                q_low,
                flags=re.I | re.S,
            )
        ):
            primary_family = "count"

        tie_family: Optional[str] = None
        if (
            value_question_alt != r"$^"
            and re.search(
                rf"\b(?:if\s+(?:there\s+are\s+)?multiple|if\s+multiple|tie|ties|tied|break)\b.{{0,120}}\b{value_question_alt}\b",
                q_low,
                flags=re.I | re.S,
            )
        ):
            tie_family = "value"
        elif (
            quantity_question_alt != r"$^"
            and re.search(
                rf"\b(?:if\s+(?:there\s+are\s+)?multiple|if\s+multiple|tie|ties|tied|break)\b.{{0,120}}\b{quantity_question_alt}\b",
                q_low,
                flags=re.I | re.S,
            )
        ):
            tie_family = "quantity"

        seen_rank_aliases: Set[str] = set()

        def _append_rank(alias_name: Optional[str], desc: bool) -> None:
            alias_name = str(alias_name or "").strip()
            if not alias_name or alias_name == partition_alias or alias_name in seen_rank_aliases:
                return
            rank_aliases.append(alias_name)
            rank_dirs.append(desc)
            seen_rank_aliases.add(alias_name)

        if primary_family:
            for alias_name in aggregate_aliases:
                if _alias_family(alias_name) == primary_family:
                    _append_rank(alias_name, True)
        if tie_family and tie_family != primary_family:
            for alias_name in aggregate_aliases:
                if _alias_family(alias_name) == tie_family:
                    _append_rank(alias_name, True)
        for alias_name in aggregate_aliases:
            _append_rank(alias_name, True)

        wants_smaller_identifier = bool(
            re.search(
                r"\b(?:smaller|lowest|smallest|lower)\b.{0,32}\b(?:code|id|number|key)\b",
                q_low,
                flags=re.I | re.S,
            )
        )
        if wants_smaller_identifier:
            for alias_name in identifier_aliases:
                _append_rank(alias_name, False)

    if not partition_alias:
        return sql

    candidate_identity_aliases = [
        alias for alias in alias_names
        if alias != partition_alias and not alias_is_agg.get(alias, False)
    ]
    if not candidate_identity_aliases:
        return sql

    if not rank_aliases:
        return sql
    if not order_aliases:
        order_aliases = [partition_alias] + rank_aliases
        order_dirs = [partition_dir] + rank_dirs
    else:
        order_aliases = [partition_alias] + rank_aliases
        order_dirs = [partition_dir] + rank_dirs
    candidate_sel.set("order", None)

    output_alias_names = list(alias_names)
    if len(alias_simple_col) >= 2:
        alias_to_table = {
            str(k or "").strip().lower(): str(v or "").strip().lower()
            for k, v in (_parse_from_join_aliases(sql) or {}).items()
            if str(k or "").strip() and str(v or "").strip()
        }
        eq_pat = re.compile(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            flags=re.I,
        )
        equivalent_pairs: Set[Tuple[Tuple[str, str], Tuple[str, str]]] = set()
        for m_eq in eq_pat.finditer(sql):
            left = (m_eq.group(1).lower(), m_eq.group(2).lower())
            right = (m_eq.group(3).lower(), m_eq.group(4).lower())
            equivalent_pairs.add((left, right))
            equivalent_pairs.add((right, left))

        try:
            transaction_tables = {str(t).strip().lower() for t in get_transaction_tables() if str(t).strip()}
        except Exception:
            transaction_tables = set()

        q_terms = _text_terms(question or "")

        def _visible_identity_score(alias_name: str) -> int:
            qualifier, col_name = alias_simple_col.get(alias_name, ("", ""))
            table_name = alias_to_table.get(qualifier, qualifier)
            terms = _alias_terms(alias_name)
            score = 0
            score += 3 * len(terms & q_terms)
            if table_name and table_name not in transaction_tables:
                score += 4
            if not alias_explicit.get(alias_name, False):
                score += 3
            if qualifier and alias_name.lower().startswith(f"{qualifier}_"):
                score -= 5
            if col_name and col_name.replace("_", "").lower() == alias_name.replace("_", "").lower():
                score += 2
            if alias_name == partition_alias:
                score += 6
            return score

        drop_output_aliases: Set[str] = set()
        simple_aliases = [a for a in alias_names if a in alias_simple_col]
        for idx, left_alias in enumerate(simple_aliases):
            left_ref = alias_simple_col[left_alias]
            if not left_ref[0] or not left_ref[1]:
                continue
            for right_alias in simple_aliases[idx + 1:]:
                right_ref = alias_simple_col[right_alias]
                if not right_ref[0] or not right_ref[1]:
                    continue
                if left_ref[1] != right_ref[1]:
                    continue
                if (left_ref, right_ref) not in equivalent_pairs:
                    continue
                left_score = _visible_identity_score(left_alias)
                right_score = _visible_identity_score(right_alias)
                if left_score == right_score:
                    keep_alias, drop_alias = sorted([left_alias, right_alias], key=lambda a: alias_names.index(a))
                elif left_score > right_score:
                    keep_alias, drop_alias = left_alias, right_alias
                else:
                    keep_alias, drop_alias = right_alias, left_alias
                if drop_alias == partition_alias:
                    continue
                if keep_alias:
                    drop_output_aliases.add(drop_alias)

        if drop_output_aliases:
            output_alias_names = [a for a in alias_names if a not in drop_output_aliases]

    # Trim redundant GROUP BY columns in the aggregated candidate layer.
    #
    # Common failure mode:
    # the model groups by extra descriptive/detail columns that fragment the
    # candidate grain before ROW_NUMBER() ranking is applied.
    #
    # Two conservative trims are allowed here:
    # 1) same-table descriptive extras on the key table
    #    e.g. productCode + productName are visible, but MSRP/vendor/scale are
    #    also grouped even though they are not projected.
    # 2) child-fact detail columns from tables that appear only inside
    #    aggregate metrics and are not part of the visible non-aggregate
    #    projection
    #    e.g. orderLineNumber / priceEach from orderdetails in a grouped
    #    product-level winner-row candidate.
    #
    # This keeps the visible candidate grain intact while removing detail-level
    # grouping that would otherwise leak multiple candidates per logical entity.
    candidate_group = candidate_sel.args.get("group")
    if candidate_group and getattr(candidate_group, "expressions", None):
        current_group_exprs = list(candidate_group.expressions or [])
        current_group_norms = {_norm_expr(g) for g in current_group_exprs}

        visible_group_columns: List[exp.Column] = []
        visible_group_norms: Set[str] = set()
        visible_nonagg_tables: Set[str] = set()
        aggregate_only_tables: Set[str] = set()
        for item in candidate_sel.expressions:
            base = item.this if isinstance(item, exp.Alias) else item
            base_norm = _norm_expr(base)
            contains_aggregate = any(True for _ in base.find_all(exp.AggFunc))

            if contains_aggregate:
                for col in base.find_all(exp.Column):
                    tbl = (col.table or "").strip().lower()
                    if tbl:
                        aggregate_only_tables.add(tbl)
                continue

            if base_norm in current_group_norms:
                visible_group_norms.add(base_norm)
                if isinstance(base, exp.Column):
                    visible_group_columns.append(base)

            for col in base.find_all(exp.Column):
                tbl = (col.table or "").strip().lower()
                if tbl:
                    visible_nonagg_tables.add(tbl)

        if len(current_group_exprs) > len(visible_group_norms) and visible_group_columns:
            extras = [
                g for g in current_group_exprs
                if _norm_expr(g) not in visible_group_norms
            ]
            trim_group_norms: Set[str] = set()

            key_like_cols = [
                c for c in visible_group_columns
                if any(tok in (c.name or "").lower() for tok in ["id", "code", "number", "key"])
            ]
            key_tables = {
                (c.table or "").lower()
                for c in key_like_cols
                if (c.table or "").strip()
            }

            if key_like_cols and key_tables:
                same_table_extras = [
                    g for g in extras
                    if isinstance(g, exp.Column) and ((g.table or "").lower() in key_tables)
                ]
                trim_group_norms.update(_norm_expr(g) for g in same_table_extras)

            child_fact_detail_extras = [
                g for g in extras
                if isinstance(g, exp.Column)
                and (g.table or "").strip().lower() in aggregate_only_tables
                and (g.table or "").strip().lower() not in visible_nonagg_tables
            ]
            trim_group_norms.update(_norm_expr(g) for g in child_fact_detail_extras)

            if trim_group_norms:
                trimmed_group_exprs: List[exp.Expression] = []
                seen_group_norms: Set[str] = set()
                for g in current_group_exprs:
                    g_norm = _norm_expr(g)
                    if g_norm in trim_group_norms:
                        continue
                    if g_norm in seen_group_norms:
                        continue
                    trimmed_group_exprs.append(g.copy())
                    seen_group_norms.add(g_norm)
                if trimmed_group_exprs:
                    candidate_sel.set("group", exp.Group(expressions=trimmed_group_exprs))

    candidate_sub = exp.Subquery(
        this=candidate_ast,
        alias=exp.TableAlias(this=exp.to_identifier("c")),
    )

    ranked_order = exp.Order(
        expressions=[
            exp.Ordered(this=exp.column(alias, table="c"), desc=desc)
            for alias, desc in zip(rank_aliases, rank_dirs)
        ]
    )
    rn_expr = exp.alias_(
        exp.Window(
            this=exp.RowNumber(),
            partition_by=exp.Partition(expressions=[exp.column(partition_alias, table="c")]),
            order=ranked_order,
        ),
        "rn",
        quoted=False,
    )

    ranked_select = exp.Select(
        expressions=[exp.column(alias, table="c") for alias in alias_names] + [rn_expr]
    ).from_(candidate_sub)

    ranked_sub = exp.Subquery(
        this=ranked_select,
        alias=exp.TableAlias(this=exp.to_identifier("t")),
    )

    outer = exp.Select(
        expressions=[exp.column(alias, table="t") for alias in output_alias_names]
    ).from_(ranked_sub).where(
        exp.EQ(this=exp.column("rn", table="t"), expression=exp.Literal.number(1))
    )
    outer.set(
        "order",
        exp.Order(
            expressions=[
                exp.Ordered(this=exp.column(partition_alias, table="t"), desc=order_dirs[0])
            ]
        ),
    )

    out_sql = outer.sql(dialect="mysql")

    # Drop sqlglot's null-order wrappers for the synthetic aliases created by
    # this rewrite; these keys are non-null in the narrowed winner-row shape.
    ordered_aliases = list(dict.fromkeys([partition_alias] + rank_aliases))
    for rel_alias in ("c", "t"):
        for alias in ordered_aliases:
            pat = re.compile(
                rf"CASE\s+WHEN\s+{re.escape(rel_alias)}\.`?{re.escape(alias)}`?\s+IS\s+NULL\s+THEN\s+1\s+ELSE\s+0\s+END\s*,\s*"
                rf"{re.escape(rel_alias)}\.`?{re.escape(alias)}`?\s+ASC",
                flags=re.IGNORECASE,
            )
            out_sql = pat.sub(f"{rel_alias}.{alias} ASC", out_sql)

    if out_sql == sql:
        return _fallback_simple_wrapper(sql)
    return out_sql


def _rewrite_dual_fact_rollup_exists_shape(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair base-entity grouped dual-fact rollups that degraded into:
      base_table
      WHERE EXISTS (count_fact ...)
      COUNT(unqualified_count_col), SUM(unqualified_metric_col)

    Example family:
      "customers with at least one order ... total number of orders, total payment amount"

    Conservative guardrails:
    - clear dual-fact rollup intent
    - FROM has only the base entity table
    - WHERE is a single EXISTS subquery
    - grouped SELECT contains one COUNT and one SUM
    """
    if not sql or not question:
        return sql
    if not _question_wants_dual_fact_rollup(question):
        return sql

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        return sql
    if (parsed.get("having") or "").strip():
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    where_clause = (parsed.get("where") or "").strip()
    groupby = (parsed.get("groupby") or "").strip()
    if not from_core or not where_clause or not groupby:
        return sql
    if " join " in f" {from_core.lower()} ":
        return sql

    reserved_alias_tokens = {
        "left", "right", "inner", "outer", "full", "cross", "join",
        "on", "where", "group", "order", "having", "limit",
    }
    m_base = re.match(
        r"""(?is)^\s*(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?\s*$""",
        from_core,
    )
    if not m_base:
        return sql
    base_table_expr = (m_base.group(1) or "").strip()
    base_table = base_table_expr.replace("`", "").split(".")[-1].strip()
    if not base_table:
        return sql
    base_alias_raw = (m_base.group(2) or "").strip()
    if base_alias_raw.lower() in reserved_alias_tokens:
        base_alias_raw = ""
    base_alias = (base_alias_raw or base_table).strip()
    base_alias_l = base_alias.lower()

    m_exists = re.match(
        r"""(?is)^\s*WHERE\s+EXISTS\s*\(\s*SELECT\s+1\s+FROM\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?\s+WHERE\s+(.+?)\s*\)\s*$""",
        where_clause,
    )
    if not m_exists:
        return sql
    count_table_expr = (m_exists.group(1) or "").strip()
    count_table = count_table_expr.replace("`", "").split(".")[-1].strip()
    if not count_table:
        return sql
    count_alias_raw = (m_exists.group(2) or "").strip()
    if count_alias_raw.lower() in reserved_alias_tokens:
        count_alias_raw = ""
    count_alias = (count_alias_raw or count_table).strip()
    count_alias_l = count_alias.lower()
    exists_pred = (m_exists.group(3) or "").strip()

    eq_match = re.search(
        rf"""(?is)\b(?:`?{re.escape(base_alias)}`?\s*\.\s*`?(?P<base_col_a>[A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?{re.escape(count_alias)}`?\s*\.\s*`?(?P<count_col_a>[A-Za-z_][A-Za-z0-9_]*)`?|`?{re.escape(count_alias)}`?\s*\.\s*`?(?P<count_col_b>[A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?{re.escape(base_alias)}`?\s*\.\s*`?(?P<base_col_b>[A-Za-z_][A-Za-z0-9_]*)`?)\b""",
        exists_pred,
    )
    if not eq_match:
        return sql
    base_count_key = (eq_match.group("base_col_a") or eq_match.group("base_col_b") or "").strip()
    count_key = (eq_match.group("count_col_a") or eq_match.group("count_col_b") or "").strip()
    if not base_count_key or not count_key:
        return sql

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    allowed_identifiers = _parse_allowed_identifiers(ctx)

    def _table_cols_lower(table: str) -> Set[str]:
        table_l = str(table or "").strip().lower()
        if not table_l:
            return set()
        if analyzer is not None:
            try:
                return {
                    str(c).strip("`").lower()
                    for c in analyzer.get_table_columns(table_l)
                }
            except Exception:
                pass
        for tbl, cols in (allowed_identifiers or {}).items():
            if str(tbl or "").strip().lower() != table_l:
                continue
            return {
                str(c).strip("`").lower()
                for c in (cols or set())
                if str(c or "").strip()
            }
        return set()

    def _split_expr_alias(item: str) -> tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m:
            return (item or "").strip(), None
        return (m.group(1) or "").strip(), (m.group(2) or "").strip()

    def _parse_simple_col(expr: str) -> Optional[Tuple[str, str]]:
        m = re.match(
            r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            (expr or "").strip(),
        )
        if not m:
            return None
        return str(m.group(1) or "").strip(), str(m.group(2) or "").strip()

    select_items = _split_top_level_commas(parsed.get("select", ""))
    if not select_items:
        return sql

    base_select_items: List[str] = []
    count_alias_out: Optional[str] = None
    count_inner_clean: Optional[str] = None
    sum_alias_out: Optional[str] = None
    sum_inner_clean: Optional[str] = None
    case_items: List[tuple[str, Optional[str]]] = []

    count_table_cols = _table_cols_lower(count_table)

    for raw_item in select_items:
        expr, out_alias = _split_expr_alias(raw_item)
        expr_clean = (expr or "").strip()

        m_count = re.match(r"(?is)^COUNT\s*\(\s*(DISTINCT\s+)?(.+?)\s*\)$", expr_clean)
        if m_count:
            inner = (m_count.group(2) or "").strip()
            if inner == "*":
                count_inner_clean = "*"
            else:
                parsed_col = _parse_simple_col(inner)
                if parsed_col:
                    qualifier, col_name = parsed_col
                    if qualifier and qualifier.lower() not in {count_alias_l, count_table.lower()}:
                        return sql
                    if col_name.lower() not in count_table_cols:
                        return sql
                    count_inner_clean = col_name
                else:
                    if inner.lower() not in count_table_cols:
                        return sql
                    count_inner_clean = inner
            count_alias_out = (out_alias or "").strip("`'\"") or None
            continue

        m_sum = re.match(r"(?is)^SUM\s*\(\s*(.+?)\s*\)$", expr_clean)
        if m_sum:
            inner = (m_sum.group(1) or "").strip()
            parsed_col = _parse_simple_col(inner)
            if parsed_col:
                qualifier, col_name = parsed_col
                if qualifier and qualifier.lower() == base_alias_l:
                    return sql
                sum_inner_clean = col_name
            else:
                sum_inner_clean = inner
            sum_alias_out = (out_alias or "").strip("`'\"") or None
            continue

        if expr_clean.lower().startswith("case") and re.search(r"\bSUM\s*\(", expr_clean, flags=re.I):
            case_items.append((expr_clean, out_alias))
            continue

        parsed_col = _parse_simple_col(expr_clean)
        if not parsed_col:
            return sql
        qualifier, col_name = parsed_col
        if qualifier and qualifier.lower() not in {base_alias_l, base_table.lower()}:
            return sql
        rewritten = f"{base_alias}.{col_name}"
        if out_alias:
            rewritten += f" AS {out_alias.strip()}"
        base_select_items.append(rewritten)

    if not base_select_items or not count_inner_clean or not sum_inner_clean:
        return sql

    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, mapping in fk_map_raw.items():
        src_l = str(src or "").strip().lower()
        if not src_l:
            continue
        fk_map[src_l] = {}
        for fk_col, tgt in (mapping or {}).items():
            fk_s = str(fk_col or "").strip()
            tgt_l = str(tgt or "").strip().lower()
            if fk_s and tgt_l:
                fk_map[src_l][fk_s] = tgt_l

    def _safe_id_col(table_name: str) -> str:
        try:
            return str(get_id_column(table_name) or "").strip()
        except Exception:
            return ""

    def _direct_pairs_to_base(child_table: str) -> List[tuple[str, str]]:
        out: List[tuple[str, str]] = []
        child_l = str(child_table or "").strip().lower()
        base_l = base_table.lower()
        for fk_col, tgt in (fk_map.get(child_l, {}) or {}).items():
            if str(tgt).lower() == base_l:
                out.append((_safe_id_col(base_table) or base_count_key, str(fk_col).strip()))
        for fk_col, tgt in (fk_map.get(base_l, {}) or {}).items():
            if str(tgt).lower() == child_l:
                out.append((str(fk_col).strip(), _safe_id_col(child_table) or str(fk_col).strip()))
        if not out:
            base_cols = _table_cols_lower(base_table)
            child_cols = _table_cols_lower(child_table)
            shared_keys = [
                c for c in sorted(base_cols & child_cols)
                if c.endswith(("id", "number", "code", "key"))
            ]
            for key_col in shared_keys:
                out.append((key_col, key_col))
        return out

    sum_candidates: List[tuple[int, str, tuple[str, str]]] = []
    try:
        all_tables = sorted(str(t).strip().lower() for t in get_all_tables() if str(t).strip())
    except Exception:
        all_tables = sorted(str(t).strip().lower() for t in (allowed_identifiers or {}).keys() if str(t).strip())
    try:
        txn_tables = {str(t).strip().lower() for t in get_transaction_tables() if str(t).strip()}
    except Exception:
        txn_tables = set()

    q_low = (question or "").lower()
    for table_name in all_tables:
        if table_name == base_table.lower():
            continue
        cols_l = _table_cols_lower(table_name)
        if sum_inner_clean.lower() not in cols_l:
            continue
        pairs = _direct_pairs_to_base(table_name)
        if not pairs:
            continue
        base_sum_key, sum_key = pairs[0]
        score = 0
        if table_name != count_table.lower():
            score += 4
        if table_name in txn_tables:
            score += 2
        for word in _entity_words_for_table(table_name):
            ww = (word or "").strip().lower()
            if not ww:
                continue
            w_pat = re.escape(ww).replace(r"\ ", r"\s+")
            if re.search(rf"\b{w_pat}\b", q_low, flags=re.I):
                score += 3
                break
        sum_candidates.append((score, table_name, (base_sum_key, sum_key)))

    if not sum_candidates:
        return sql
    sum_candidates.sort(key=lambda item: (-item[0], item[1]))
    _sum_score, sum_table, sum_pair = sum_candidates[0]
    base_sum_key, sum_key = sum_pair
    if not sum_table or sum_table == base_table.lower():
        return sql

    count_alias_out = count_alias_out or "total_count"
    sum_alias_out = sum_alias_out or "total_amount"

    used_aliases = {base_alias_l, count_alias_l}
    reserved_alias_tokens = {
        "left", "right", "inner", "outer", "full", "cross", "join",
        "on", "where", "group", "order", "having", "limit", "or", "and",
    }

    def _safe_alias(base_name: str) -> str:
        raw = re.sub(r"[^A-Za-z0-9_]+", "_", str(base_name or "").strip()).strip("_").lower()
        if not raw:
            raw = "agg"
        if not re.match(r"[a-z_]", raw):
            raw = f"a_{raw}"
        if raw in reserved_alias_tokens:
            raw = f"{raw}_alias"
        candidate = raw
        idx = 2
        while candidate.lower() in used_aliases or candidate.lower() in reserved_alias_tokens:
            candidate = f"{raw}_{idx}"
            idx += 1
        used_aliases.add(candidate.lower())
        return candidate

    count_agg_alias = _safe_alias(f"{count_table}_agg")
    sum_agg_alias = _safe_alias(f"{sum_table}_agg")
    count_metric_alias = re.sub(r"[^A-Za-z0-9_]+", "_", count_alias_out).strip("_") or "count_metric"
    sum_metric_alias = re.sub(r"[^A-Za-z0-9_]+", "_", sum_alias_out).strip("_") or "sum_metric"

    projected_items = list(base_select_items)
    projected_items.append(f"{count_agg_alias}.{count_metric_alias} AS {_smart_backtick(count_alias_out)}")
    projected_items.append(f"COALESCE({sum_agg_alias}.{sum_metric_alias}, 0) AS {_smart_backtick(sum_alias_out)}")

    sum_case_pat = re.compile(r"(?is)SUM\s*\(\s*(.+?)\s*\)")
    for case_expr, case_alias in case_items:
        rewritten_case = sum_case_pat.sub(
            f"COALESCE({sum_agg_alias}.{sum_metric_alias}, 0)",
            case_expr,
        )
        if case_alias:
            projected_items.append(f"{rewritten_case} AS {case_alias}")
        else:
            projected_items.append(rewritten_case)

    tail_clause = (parsed.get("tail") or "").strip()
    tail_block = f"\n{tail_clause}" if tail_clause else ""
    select_block = ",\n  ".join(projected_items)
    count_expr = "COUNT(*)" if count_inner_clean == "*" else f"COUNT({count_inner_clean})"
    fixed = (
        "SELECT\n"
        f"  {select_block}\n"
        f"FROM {base_table_expr} {base_alias}\n"
        "JOIN (\n"
        f"  SELECT {count_key}, {count_expr} AS {count_metric_alias}\n"
        f"  FROM {count_table}\n"
        f"  GROUP BY {count_key}\n"
        f") AS {count_agg_alias}\n"
        f"  ON {count_agg_alias}.{count_key} = {base_alias}.{base_count_key}\n"
        "LEFT JOIN (\n"
        f"  SELECT {sum_key}, SUM({sum_inner_clean}) AS {sum_metric_alias}\n"
        f"  FROM {sum_table}\n"
        f"  GROUP BY {sum_key}\n"
        f") AS {sum_agg_alias}\n"
        f"  ON {sum_agg_alias}.{sum_key} = {base_alias}.{base_sum_key}"
        f"{tail_block};"
    )
    return fixed


def _fix_winner_row_window_order_priority(sql: str, question: str) -> str:
    """
    Normalize ROW_NUMBER() window ORDER BY priority for winner-row questions
    that ask:
      - latest/most recent date as primary criterion
      - largest/highest amount as tie-breaker

    Example fix:
      ORDER BY amount DESC, paymentDate DESC
    -> ORDER BY paymentDate DESC, amount DESC
    """
    if not sql or "ROW_NUMBER" not in (sql or "").upper():
        return sql
    q = (question or "").lower()

    alias_to_table = _parse_from_join_aliases(sql)
    for m_tbl in re.finditer(
        r"\b(?:from|join)\s+(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)",
        sql or "",
        flags=re.I,
    ):
        table_raw = str(m_tbl.group("table") or "").replace("`", "")
        table_name = table_raw.split(".")[-1].strip()
        if not table_name:
            continue
        alias_to_table.setdefault(table_name, table_name)
        alias_to_table.setdefault(table_name.lower(), table_name)

    table_universe = {
        str(table or "").strip().lower()
        for table in alias_to_table.values()
        if str(table or "").strip()
    }
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    entity_noise_terms: Set[str] = set()
    for table_name in table_universe:
        base_terms = {table_name, _to_singular(table_name)}
        for base_term in base_terms:
            if not base_term:
                continue
            entity_noise_terms.update(
                tok for tok in re.findall(r"[a-z0-9]+", base_term.replace("_", " ").lower()) if tok
            )

    metric_term_universe = _dual_fact_metric_term_universe(
        table_universe,
        analyzer=analyzer,
        question=question,
    )
    # Keep legacy/domain metric terms as a compatibility fallback for business-style
    # phrasing when schema-derived evidence is sparse.
    legacy_metric_terms: Set[str] = set()
    if DOMAIN_HEURISTICS_ENABLED:
        legacy_metric_terms = _question_compat_metric_terms(question, HELPERS_ROLLUP_LEGACY_METRIC_TERMS)
        if not legacy_metric_terms and not metric_term_universe:
            legacy_metric_terms = set(HELPERS_ROLLUP_LEGACY_METRIC_TERMS)
    active_metric_terms = set(metric_term_universe) if metric_term_universe else set(legacy_metric_terms)
    metric_candidate_terms = {
        term
        for term in active_metric_terms
        if term and term not in entity_noise_terms and term not in HELPERS_METRIC_AGG_IDLIKE_TOKENS
    }
    if not metric_candidate_terms and DOMAIN_HEURISTICS_ENABLED:
        metric_candidate_terms = set(legacy_metric_terms or HELPERS_ROLLUP_LEGACY_METRIC_TERMS)

    metric_query_alt = _regex_alt_from_terms(
        metric_candidate_terms,
        _winner_row_metric_alt(),
    )
    date_semantic_terms = {
        "date", "dates", "time", "times", "timestamp", "timestamps",
        "year", "years", "month", "months", "day", "days",
        "tanggal", "waktu",
    }
    identifier_terms = {"id", "identifier", "code", "number", "key"}

    column_term_cache: Dict[Tuple[str, str], Set[str]] = {}

    def _column_semantic_terms(table_l: str, col_l: str) -> Set[str]:
        key = (table_l, col_l)
        if key in column_term_cache:
            return column_term_cache[key]

        terms: Set[str] = set()
        candidate_texts = [col_l]
        try:
            if analyzer is not None:
                candidate_texts.extend(analyzer.get_column_synonyms(table_l, col_l) or [])
        except Exception:
            pass

        for text in candidate_texts:
            normalized = re.sub(
                r"([a-z0-9])([A-Z])",
                r"\1 \2",
                str(text or "").replace("_", " ").lower(),
            )
            terms.update(tok for tok in re.findall(r"[a-z0-9]+", normalized) if tok)

        try:
            role = str(get_column_role(table_l, col_l) or "").strip().lower()
        except Exception:
            role = ""
        if role:
            terms.add(role)

        column_term_cache[key] = {term for term in terms if term}
        return column_term_cache[key]

    def _expr_terms(item: str) -> Set[str]:
        item_l = str(item or "").strip().lower()
        terms: Set[str] = set(re.findall(r"[a-z0-9]+", item_l))
        for qual, col in re.findall(
            r"\b([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)\b",
            item or "",
            flags=re.I,
        ):
            table_l = str(alias_to_table.get(qual) or alias_to_table.get(qual.lower()) or qual).strip().lower()
            col_l = str(col or "").strip().lower()
            if not table_l or not col_l:
                continue
            terms.update(_column_semantic_terms(table_l, col_l))
            try:
                id_col = str(get_id_column(table_l) or "").strip().lower()
            except Exception:
                id_col = ""
            if id_col and col_l == id_col:
                terms.add("id")
                terms.add("identifier")
        return {term for term in terms if term}

    wants_latest_date = bool(
        re.search(r"\b(?:latest|most\s+recent|newest|terbaru|terakhir)\b", q)
        and re.search(r"\b(?:date|time|tanggal)\b", q)
    )
    if not wants_latest_date:
        return sql

    # Intent disambiguation:
    # - amount-first: "largest/highest amount ... if same amount then latest date"
    # - date-first:   "most recent/latest date ... if same date then largest amount"
    same_amount_tie = bool(
        re.search(r"\b(?:if\s+there\s+are\s+multiple|if\s+multiple|tie|tied|same)\b", q)
        and re.search(rf"\b(?:same|equal)\b.{0,40}\b{metric_query_alt}\b", q, flags=re.I | re.S)
    )
    same_date_tie = bool(
        re.search(r"\b(?:if\s+there\s+are\s+multiple|if\s+multiple|tie|tied|same)\b", q)
        and re.search(r"\bsame\s+(?:most\s+recent\s+)?(?:date|payment\s+date|order\s+date|time)\b", q)
    )
    amount_superlative = bool(
        re.search(r"\b(?:largest|highest|max(?:imum)?|biggest|top)\b", q)
        and re.search(rf"\b{metric_query_alt}\b", q, flags=re.I)
    )

    # Conservative rule:
    # rewrite only when date is clearly primary, never when amount-primary tie logic is explicit.
    date_primary_intent = bool(
        same_date_tie
        or (wants_latest_date and not same_amount_tie and not amount_superlative)
    )
    if not date_primary_intent:
        return sql

    wants_amount_tiebreak = bool(
        re.search(r"\b(?:if\s+there\s+are\s+multiple|if\s+multiple|same\s+most\s+recent\s+date|tie)\b", q)
        and re.search(r"\b(?:largest|highest|max|terbesar|tertinggi)\b", q)
        and re.search(rf"\b{metric_query_alt}\b", q, flags=re.I)
    )

    # NOTE:
    # Keep this pattern as a compact regex (no verbose spacing) so it
    # reliably matches one-line SQL emitted by the model.
    rownum_pat = re.compile(
        r"(?is)ROW_NUMBER\s*\(\s*\)\s*OVER\s*\(\s*(?:PARTITION\s+BY\s+.*?\b)?ORDER\s+BY\s+(?P<ob>[^)]*?)\)"
    )

    # Fallback candidates (used when window ORDER BY misses required fields).
    qualified_refs = list(dict.fromkeys(re.findall(
        r"\b([A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*)\b",
        sql or "",
        flags=re.I,
    )))

    date_fallbacks = [ref for ref in qualified_refs if _expr_terms(ref) & date_semantic_terms]
    amount_fallbacks = [ref for ref in qualified_refs if _expr_terms(ref) & metric_candidate_terms]
    identifier_fallbacks = [ref for ref in qualified_refs if _expr_terms(ref) & identifier_terms]

    def _is_date_expr(item: str) -> bool:
        return bool(_expr_terms(item) & date_semantic_terms)

    def _is_amount_expr(item: str) -> bool:
        return bool(_expr_terms(item) & metric_candidate_terms)

    def _force_dir(item: str, desc: bool) -> str:
        base = re.sub(r"(?is)\s+(ASC|DESC)\s*$", "", (item or "").strip()).strip()
        if not base:
            return item
        return f"{base} {'DESC' if desc else 'ASC'}"

    def _norm_expr(item: str) -> str:
        x = re.sub(r"(?is)\s+(ASC|DESC)\s*$", "", (item or "").strip())
        return re.sub(r"[\s`]+", "", x.lower())

    def _pick_fallback(
        cands: List[str],
        seen_norm: Set[str],
        preferred_aliases: Optional[Set[str]] = None,
        prefer_functions: bool = False,
    ) -> Optional[str]:
        if preferred_aliases:
            for c in cands:
                c0 = (c or "").strip()
                if not c0:
                    continue
                if _norm_expr(c0) in seen_norm:
                    continue
                m_alias = re.match(r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.", c0)
                alias_name = (m_alias.group(1) if m_alias else "").lower()
                if alias_name and alias_name in preferred_aliases:
                    return c0
        if prefer_functions:
            for c in cands:
                c0 = (c or "").strip()
                if not c0:
                    continue
                if _norm_expr(c0) in seen_norm:
                    continue
                if preferred_aliases:
                    qual_aliases = {
                        str(a).strip().lower()
                        for a in re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\.", c0)
                        if str(a).strip()
                    }
                    if qual_aliases and not qual_aliases.issubset(preferred_aliases):
                        continue
                if "(" in c0:
                    return c0
        preferred_hits: List[str] = []
        for c in cands:
            c0 = (c or "").strip()
            if not c0:
                continue
            if _norm_expr(c0) in seen_norm:
                continue
            if preferred_aliases:
                m_alias = re.match(r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.", c0)
                alias_name = (m_alias.group(1) if m_alias else "").lower()
                if alias_name and alias_name in preferred_aliases:
                    preferred_hits.append(c0)
                    continue
            if not preferred_aliases:
                return c0
        if preferred_hits:
            return preferred_hits[0]
        if preferred_aliases:
            for c in cands:
                c0 = (c or "").strip()
                if not c0:
                    continue
                if _norm_expr(c0) in seen_norm:
                    continue
                qual_aliases = {
                    str(a).strip().lower()
                    for a in re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\.", c0)
                    if str(a).strip()
                }
                # When rewriting a specific ROW_NUMBER window, do not pull in a
                # fallback reference from an outer/inner alias that is not valid
                # in the current window scope.
                if qual_aliases and not qual_aliases.issubset(preferred_aliases):
                    continue
                return c0
        return None

    def _repl(m: re.Match) -> str:
        ob = (m.group("ob") or "").strip()
        if not ob:
            return m.group(0)

        items = _split_top_level_commas(ob)
        if not items:
            return m.group(0)

        window_sql = m.group(0) or ""
        window_aliases = {
            str(alias).lower()
            for alias in re.findall(
                r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\.",
                window_sql,
                flags=re.I,
            )
            if str(alias).strip()
        }

        has_date_any = any(_is_date_expr(it) for it in items)
        has_amount_any = any(_is_amount_expr(it) for it in items)
        first = (items[0] or "").strip()
        # Rewrite when:
        # 1) amount appears before date, or
        # 2) date-primary intent but date is missing from window ORDER BY.
        should_rewrite = bool((_is_amount_expr(first) and has_date_any) or (not has_date_any))
        if not should_rewrite and not (wants_amount_tiebreak and has_date_any and not has_amount_any):
            return m.group(0)

        date_items = []
        amount_items = []
        other_items = []
        for it in items:
            it0 = (it or "").strip()
            if _is_date_expr(it0):
                date_items.append(_force_dir(it0, desc=True))
            elif _is_amount_expr(it0):
                if wants_amount_tiebreak:
                    amount_items.append(_force_dir(it0, desc=True))
                else:
                    amount_items.append(it0)
            else:
                other_items.append(it0)

        seen_norm = {_norm_expr(x) for x in items if (x or "").strip()}
        if not date_items:
            fb_date = _pick_fallback(date_fallbacks, seen_norm)
            if fb_date:
                date_items.append(_force_dir(fb_date, desc=True))
                seen_norm.add(_norm_expr(fb_date))
            else:
                return m.group(0)

        if wants_amount_tiebreak and not amount_items:
            fb_amount = _pick_fallback(amount_fallbacks, seen_norm)
            if fb_amount:
                amount_items.append(_force_dir(fb_amount, desc=True))
                seen_norm.add(_norm_expr(fb_amount))

        new_items = date_items + amount_items + other_items
        # Add a deterministic tertiary identifier tie-break when the
        # question explicitly asks for an id/number/code/key field.
        wants_identifier_tiebreak = bool(
            re.search(r"\b(?:id|number|code|key)\b", q, flags=re.I)
        )
        if wants_identifier_tiebreak:
            fb_identifier = _pick_fallback(
                identifier_fallbacks,
                {_norm_expr(x) for x in new_items},
                preferred_aliases=window_aliases or None,
            )
            if fb_identifier:
                new_items.append(_force_dir(fb_identifier, desc=False))

        dedup_items = []
        dedup_seen = set()
        for it in new_items:
            k = _norm_expr(it)
            if not k or k in dedup_seen:
                continue
            dedup_seen.add(k)
            dedup_items.append(it)
        if not dedup_items:
            return m.group(0)

        if [_norm_expr(x) for x in dedup_items] == [_norm_expr(x) for x in items]:
            return m.group(0)
        new_ob = ", ".join(dedup_items)
        full = m.group(0)
        return full.replace(ob, new_ob, 1)

    fixed = rownum_pat.sub(_repl, sql)
    return fixed


def _fix_winner_row_metric_order_priority(sql: str, question: str) -> str:
    """
    Normalize ROW_NUMBER() metric priority for winner-row questions that specify
    a primary aggregate metric plus an explicit tie-break metric.

    Example:
      "best-selling product based on total quantity ordered; if tied, choose
      the higher total sales value"

    Generic repair:
      ORDER BY total_sales_value DESC, productCode ASC
    -> ORDER BY total_quantity_ordered DESC, total_sales_value DESC, productCode ASC
    """
    if not sql or "ROW_NUMBER" not in (sql or "").upper():
        return sql
    if not _question_wants_winner_row(question):
        return sql

    q = (question or "").lower()
    date_primary_same_date_tie = bool(
        re.search(r"\b(?:latest|most\s+recent|newest|earliest|oldest)\b", q, flags=re.I)
        and re.search(r"\b(?:date|time|timestamp)\b", q, flags=re.I)
        and re.search(
            r"\b(?:if\s+(?:there\s+are\s+)?multiple|if\s+multiple|tie|tied|same)\b",
            q,
            flags=re.I,
        )
        and re.search(
            r"\bsame\s+(?:(?:most\s+recent|latest|newest|earliest|oldest)\s+)?"
            r"(?:date|payment\s+date|order\s+date|time)\b",
            q,
            flags=re.I,
        )
    )
    if date_primary_same_date_tie:
        return sql

    alias_to_table = _parse_from_join_aliases(sql)
    for m_tbl in re.finditer(
        r"\b(?:from|join)\s+(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)",
        sql or "",
        flags=re.I,
    ):
        table_raw = str(m_tbl.group("table") or "").replace("`", "")
        table_name = table_raw.split(".")[-1].strip()
        if not table_name:
            continue
        alias_to_table.setdefault(table_name, table_name)
        alias_to_table.setdefault(table_name.lower(), table_name)

    table_universe = {
        str(table or "").strip().lower()
        for table in alias_to_table.values()
        if str(table or "").strip()
    }
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    entity_noise_terms: Set[str] = set()
    for table_name in table_universe:
        base_terms = {table_name, _to_singular(table_name)}
        for base_term in base_terms:
            if not base_term:
                continue
            entity_noise_terms.update(
                tok for tok in re.findall(r"[a-z0-9]+", base_term.replace("_", " ").lower()) if tok
            )

    column_term_cache: Dict[Tuple[str, str], Set[str]] = {}

    def _text_semantic_terms(text: str) -> Set[str]:
        normalized = re.sub(
            r"([a-z0-9])([A-Z])",
            r"\1 \2",
            str(text or "").replace("_", " "),
        ).lower()
        return {tok for tok in re.findall(r"[a-z0-9]+", normalized) if tok}

    def _column_semantic_terms(table_l: str, col_l: str) -> Set[str]:
        key = (table_l, col_l)
        if key in column_term_cache:
            return column_term_cache[key]

        terms: Set[str] = set()
        candidate_texts = [col_l]
        try:
            if analyzer is not None:
                candidate_texts.extend(analyzer.get_column_synonyms(table_l, col_l) or [])
        except Exception:
            pass

        for text in candidate_texts:
            terms.update(_text_semantic_terms(text))

        try:
            role = str(get_column_role(table_l, col_l) or "").strip().lower()
        except Exception:
            role = ""
        if role:
            terms.add(role)

        column_term_cache[key] = {term for term in terms if term}
        return column_term_cache[key]

    def _expr_terms(item: str) -> Set[str]:
        terms: Set[str] = set(_text_semantic_terms(item))
        for qual, col in re.findall(
            r"\b([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)\b",
            item or "",
            flags=re.I,
        ):
            table_l = str(alias_to_table.get(qual) or alias_to_table.get(qual.lower()) or qual).strip().lower()
            col_l = str(col or "").strip().lower()
            if not table_l or not col_l:
                continue
            terms.update(_column_semantic_terms(table_l, col_l))
            try:
                id_col = str(get_id_column(table_l) or "").strip().lower()
            except Exception:
                id_col = ""
            if id_col and col_l == id_col:
                terms.add("id")
                terms.add("identifier")
        return {term for term in terms if term}

    def _term_tokens(terms: Sequence[str]) -> Set[str]:
        out: Set[str] = set()
        for term in terms or []:
            out.update(_text_semantic_terms(str(term or "")))
        return out

    quantity_family_terms = _term_tokens(ordered_quantity_repair_quantity_terms())
    count_family_terms = (
        _term_tokens(HELPERS_COUNT_INTENT_TERMS)
        - _term_tokens(HELPERS_METRIC_AGG_INTENT_TERMS)
        - set(semantic_question_token_stopwords())
    )
    family_terms: Dict[str, Set[str]] = {
        "quantity": set(quantity_family_terms),
        "value": _winner_row_metric_terms() - quantity_family_terms - count_family_terms,
        "count": set(count_family_terms),
    }
    metric_term_universe = _dual_fact_metric_term_universe(
        table_universe,
        analyzer=analyzer,
        question=question,
    )
    legacy_metric_terms: Set[str] = set()
    if DOMAIN_HEURISTICS_ENABLED:
        legacy_metric_terms = _question_compat_metric_terms(question, HELPERS_ROLLUP_LEGACY_METRIC_TERMS)
        if not legacy_metric_terms and not metric_term_universe:
            legacy_metric_terms = set(HELPERS_ROLLUP_LEGACY_METRIC_TERMS)
    active_metric_terms = set(metric_term_universe) if metric_term_universe else set(legacy_metric_terms)
    for term in active_metric_terms:
        tokenized = _text_semantic_terms(term)
        tokenized = {
            tok for tok in tokenized
            if tok and tok not in entity_noise_terms and tok not in HELPERS_METRIC_AGG_IDLIKE_TOKENS
        }
        if not tokenized:
            continue
        if tokenized & family_terms["quantity"]:
            family_terms["quantity"].update(tokenized)
        elif tokenized & family_terms["count"]:
            family_terms["count"].update(tokenized)
        else:
            # Schema-derived metric terms that are neither quantity nor count
            # are treated as value-like metrics by default.
            family_terms["value"].update(tokenized)

    identifier_terms = {"id", "identifier", "code", "number", "numbers", "key"}

    def _family_from_terms(item: str, terms: Set[str]) -> Optional[str]:
        item_l = str(item or "").lower()
        if "*" in item_l and (terms & family_terms["value"]) and (terms & family_terms["quantity"]):
            return "value"
        scores = {
            family_name: len(terms & term_set)
            for family_name, term_set in family_terms.items()
        }
        best_family, best_score = max(scores.items(), key=lambda kv: kv[1])
        if best_score <= 0:
            return None
        if sum(1 for score in scores.values() if score == best_score) > 1:
            if (terms & family_terms["value"]) and re.search(r"[*\/+-]", item_l):
                return "value"
            return None
        return best_family

    tie_clause_pat = re.compile(
        r"\b(?:if\s+(?:there\s+are\s+)?multiple|if\s+multiple|if\s+there\s+is\s+(?:still\s+)?a\s+tie|tie|ties|tied|break(?:\s+\w+)?)\b",
        flags=re.I,
    )
    tie_match = tie_clause_pat.search(q)
    q_primary_scope = q[:tie_match.start()].strip() if tie_match else q
    q_tie_scope = q[tie_match.start():].strip() if tie_match else q

    def _family_from_question(prefix_pat: str, source_text: Optional[str] = None) -> Optional[str]:
        scope = str(source_text or q).strip()
        if not scope:
            return None
        m = re.search(prefix_pat + r"(?P<seg>.{0,96})", scope, flags=re.I | re.S)
        if not m:
            return None
        segment_terms = _text_semantic_terms(m.group("seg") or "")
        return _family_from_terms(m.group("seg") or "", segment_terms)

    def _family_from_superlative(segment: str) -> Optional[str]:
        seg = str(segment or "")
        if not seg:
            return None
        return _family_from_terms(seg, _text_semantic_terms(seg))

    def _family_pattern(term_set: Set[str], default: str) -> str:
        return _regex_alt_from_terms(term_set, default)

    quantity_alt = _family_pattern(family_terms["quantity"], r"$^")
    value_alt = _family_pattern(family_terms["value"], r"$^")
    count_alt = _family_pattern(family_terms["count"], r"$^")

    def _qualified_refs() -> List[str]:
        return list(dict.fromkeys(re.findall(
            r"\b([A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*)\b",
            sql or "",
            flags=re.I,
        )))

    qualified_refs = _qualified_refs()
    aggregate_exprs = list(dict.fromkeys(re.findall(
        r"\b(?:SUM|COUNT|AVG|MIN|MAX)\s*\([^)]*\)",
        sql or "",
        flags=re.I,
    )))
    metric_fallbacks = {
        family_name: (
            [
                expr for expr in aggregate_exprs
                if _family_from_terms(expr, _expr_terms(expr)) == family_name
            ]
            + [
                ref for ref in qualified_refs
                if _family_from_terms(ref, _expr_terms(ref)) == family_name
            ]
        )
        for family_name in ("quantity", "value", "count")
    }
    identifier_fallbacks = [
        ref for ref in qualified_refs
        if _expr_terms(ref) & identifier_terms
    ]

    def _metric_family(item: str) -> Optional[str]:
        return _family_from_terms(item, _expr_terms(item))

    def _is_identifier_expr(item: str) -> bool:
        return bool(_expr_terms(item) & identifier_terms)

    explicit_primary_family: Optional[str] = None
    explicit_quantity_primary = bool(
        quantity_alt != r"$^"
        and re.search(
            rf"\b(?:based\s+on|according\s+to)\b.{{0,96}}\b{quantity_alt}\b",
            q_primary_scope,
            flags=re.I | re.S,
        )
    )
    if explicit_quantity_primary:
        explicit_primary_family = "quantity"

    primary_family = explicit_primary_family or _family_from_question(
        r"\b(?:based\s+on|according\s+to|ranked\s+by|sorted\s+by)\b",
        q_primary_scope,
    )
    if primary_family is None:
        if re.search(rf"\b(?:best[-\s]?selling|top|highest|largest|greatest|most)\b.{0,64}\b{quantity_alt}\b", q_primary_scope, flags=re.I | re.S):
            primary_family = "quantity"
        elif re.search(rf"\b(?:best|top|highest|largest|greatest|most)\b.{0,64}\b{value_alt}\b", q_primary_scope, flags=re.I | re.S):
            primary_family = "value"
        elif re.search(rf"\b(?:most|highest|largest|greatest)\b.{0,64}\b{count_alt}\b", q_primary_scope, flags=re.I | re.S):
            primary_family = "count"
        else:
            primary_family = _family_from_superlative(q_primary_scope)
    if primary_family is None:
        return sql

    tie_family = _family_from_question(
        r"\b(?:if\s+(?:there\s+are\s+)?multiple|if\s+multiple|if\s+there\s+is\s+still\s+a\s+tie|if\s+there\s+is\s+a\s+tie|tie|tied|same)\b",
        q_tie_scope,
    )
    explicit_quantity_tie_value = bool(
        explicit_quantity_primary and tie_family == "value"
    )
    wants_smaller_identifier = bool(
        re.search(r"\b(?:smaller|lowest|smallest|lower)\b.{0,32}\b(?:code|id|number|key)\b", q, flags=re.I | re.S)
    )

    def _force_dir(item: str, desc: bool) -> str:
        base = re.sub(r"(?is)\s+(ASC|DESC)\s*$", "", (item or "").strip()).strip()
        if not base:
            return item
        return f"{base} {'DESC' if desc else 'ASC'}"

    def _norm_expr(item: str) -> str:
        x = re.sub(r"(?is)\s+(ASC|DESC)\s*$", "", (item or "").strip())
        return re.sub(r"[\s`]+", "", x.lower())

    def _pick_fallback(
        cands: List[str],
        seen_norm: Set[str],
        preferred_aliases: Optional[Set[str]] = None,
        prefer_functions: bool = False,
    ) -> Optional[str]:
        if preferred_aliases:
            for c in cands:
                c0 = (c or "").strip()
                if not c0:
                    continue
                if _norm_expr(c0) in seen_norm:
                    continue
                m_alias = re.match(r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.", c0)
                alias_name = (m_alias.group(1) if m_alias else "").lower()
                if alias_name and alias_name in preferred_aliases:
                    return c0
        if prefer_functions:
            for c in cands:
                c0 = (c or "").strip()
                if not c0:
                    continue
                if _norm_expr(c0) in seen_norm:
                    continue
                if preferred_aliases:
                    qual_aliases = {
                        str(a).strip().lower()
                        for a in re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\.", c0)
                        if str(a).strip()
                    }
                    if qual_aliases and not qual_aliases.issubset(preferred_aliases):
                        continue
                if "(" in c0:
                    return c0
        preferred_hits: List[str] = []
        for c in cands:
            c0 = (c or "").strip()
            if not c0:
                continue
            if _norm_expr(c0) in seen_norm:
                continue
            if preferred_aliases:
                m_alias = re.match(r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.", c0)
                alias_name = (m_alias.group(1) if m_alias else "").lower()
                if alias_name and alias_name in preferred_aliases:
                    preferred_hits.append(c0)
                    continue
            if not preferred_aliases:
                return c0
        if preferred_hits:
            return preferred_hits[0]
        if preferred_aliases:
            for c in cands:
                c0 = (c or "").strip()
                if not c0:
                    continue
                if _norm_expr(c0) in seen_norm:
                    continue
                return c0
        return None

    def _rewrite_order_by(ob: str, window_sql: str) -> Optional[str]:
        ob = (ob or "").strip()
        if not ob:
            return None

        items = _split_top_level_commas(ob)
        if not items:
            return None

        if len(items) >= 2:
            first_item = str(items[0] or "")
            second_item = str(items[1] or "")
            first_terms = _text_semantic_terms(first_item)
            second_terms = _text_semantic_terms(second_item)
            first_is_quantity = bool(first_terms & family_terms["quantity"])
            second_is_value = bool(second_terms & family_terms["value"])
            if first_is_quantity and second_is_value and (
                explicit_quantity_primary or primary_family == "quantity" or explicit_quantity_tie_value
            ):
                # Preserve already-correct quantity-primary tie-break order.
                return None

        current_families = [_metric_family(it) for it in items]
        needs_rewrite = False
        if current_families[0] != primary_family:
            needs_rewrite = True
        elif tie_family and tie_family != primary_family:
            secondary_present = any(fam == tie_family for fam in current_families[1:])
            if not secondary_present:
                needs_rewrite = True
            else:
                first_secondary = next((idx for idx, fam in enumerate(current_families[1:], start=1) if fam == tie_family), None)
                if first_secondary is not None:
                    first_other_metric = next((idx for idx, fam in enumerate(current_families[1:], start=1) if fam and fam != primary_family and fam != tie_family), None)
                    if first_other_metric is not None and first_other_metric < first_secondary:
                        needs_rewrite = True
        elif current_families[0] != primary_family:
            needs_rewrite = True

        if not needs_rewrite:
            return None

        current_aliases = {
            alias.lower()
            for alias in re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\.", window_sql, flags=re.I)
            if alias
        }
        qualified_ref_norms = {_norm_expr(ref) for ref in qualified_refs}
        scope_metric_fallbacks = {
            family_name: [
                ref for ref in qualified_refs
                if (
                    (m := re.match(r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.", str(ref or "").strip()))
                    and str(m.group(1) or "").strip().lower() in current_aliases
                    and (_text_semantic_terms(ref) & family_terms[family_name])
                )
            ]
            for family_name in ("quantity", "value", "count")
        }

        def _coerce_identifier_scope(ref: Optional[str]) -> Optional[str]:
            if not ref:
                return None
            if not current_aliases:
                return ref
            m_ref = re.match(
                r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
                str(ref or "").strip(),
            )
            if not m_ref:
                return ref
            alias_name = str(m_ref.group(1) or "").strip().lower()
            col_name = str(m_ref.group(2) or "").strip()
            if not col_name:
                return ref
            if alias_name in current_aliases:
                return ref
            for alias in sorted(current_aliases):
                candidate = f"{alias}.{col_name}"
                if _norm_expr(candidate) in qualified_ref_norms:
                    return candidate
            return None

        def _raw_identifier_terms(ref: str) -> Set[str]:
            m_col = re.match(
                r"(?is)^\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
                str(ref or "").strip(),
            )
            if not m_col:
                return set()
            col_name = str(m_col.group(1) or "").strip()
            if not col_name:
                return set()
            base_terms = set(_text_semantic_terms(col_name))
            col_l = col_name.lower()
            if col_l.endswith("code") or "code" in col_l:
                base_terms.add("code")
            if col_l.endswith("id") or "id" in col_l:
                base_terms.add("id")
            if col_l.endswith("key") or "key" in col_l:
                base_terms.add("key")
            return base_terms

        scope_identifier_fallbacks = [
            ref for ref in qualified_refs
            if (
                (m := re.match(r"(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.", str(ref or "").strip()))
                and str(m.group(1) or "").strip().lower() in current_aliases
                and (
                    (_expr_terms(ref) & identifier_terms)
                    or (_raw_identifier_terms(ref) & identifier_terms)
                )
            )
        ]

        primary_items: List[str] = []
        secondary_items: List[str] = []
        other_items: List[str] = []
        id_items: List[str] = []

        for it in items:
            it0 = (it or "").strip()
            fam = _metric_family(it0)
            if fam == primary_family:
                primary_items.append(_force_dir(it0, desc=True))
            elif tie_family and fam == tie_family:
                secondary_items.append(_force_dir(it0, desc=True))
            elif _is_identifier_expr(it0):
                id_items.append(_force_dir(it0, desc=False if wants_smaller_identifier else False))
            else:
                other_items.append(it0)

        seen_norm = {_norm_expr(x) for x in items if (x or "").strip()}
        if not primary_items:
            fb_primary = _pick_fallback(
                scope_metric_fallbacks.get(primary_family, []) + metric_fallbacks.get(primary_family, []),
                seen_norm,
                current_aliases,
                prefer_functions=True,
            )
            if not fb_primary:
                return None
            primary_items.append(_force_dir(fb_primary, desc=True))
            seen_norm.add(_norm_expr(fb_primary))

        if tie_family and tie_family != primary_family and not secondary_items:
            fb_secondary = _pick_fallback(
                scope_metric_fallbacks.get(tie_family, []) + metric_fallbacks.get(tie_family, []),
                seen_norm,
                current_aliases,
                prefer_functions=True,
            )
            if fb_secondary:
                secondary_items.append(_force_dir(fb_secondary, desc=True))
                seen_norm.add(_norm_expr(fb_secondary))

        if wants_smaller_identifier and not id_items:
            fb_id = _pick_fallback(scope_identifier_fallbacks, seen_norm, current_aliases)
            if not fb_id:
                fb_id = _pick_fallback(identifier_fallbacks, seen_norm, current_aliases)
                fb_id = _coerce_identifier_scope(fb_id)
            if fb_id:
                id_items.append(_force_dir(fb_id, desc=False))

        new_items = primary_items + secondary_items + other_items + id_items
        dedup_items: List[str] = []
        dedup_seen: Set[str] = set()
        for it in new_items:
            k = _norm_expr(it)
            if not k or k in dedup_seen:
                continue
            dedup_seen.add(k)
            dedup_items.append(it)
        if not dedup_items:
            return None
        if [_norm_expr(x) for x in dedup_items] == [_norm_expr(x) for x in items]:
            return None

        return ", ".join(dedup_items)

    rownum_start_pat = re.compile(r"(?is)ROW_NUMBER\s*\(\s*\)\s*OVER\s*\(")

    def _find_matching_paren(text: str, open_idx: int) -> Optional[int]:
        depth = 0
        for idx in range(open_idx, len(text)):
            ch = text[idx]
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return idx
        return None

    def _find_top_level_order_by(inner: str) -> Optional[Tuple[int, int]]:
        lower_inner = inner.lower()
        depth = 0
        idx = 0
        while idx < len(inner):
            ch = inner[idx]
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            elif depth == 0 and lower_inner.startswith("order by", idx):
                return idx, idx + len("order by")
            idx += 1
        return None

    parts: List[str] = []
    cursor = 0
    while True:
        m = rownum_start_pat.search(sql, cursor)
        if not m:
            parts.append(sql[cursor:])
            break

        over_open_idx = m.end() - 1
        over_close_idx = _find_matching_paren(sql, over_open_idx)
        if over_close_idx is None:
            parts.append(sql[cursor:])
            break

        window_sql = sql[m.start():over_close_idx + 1]
        inner_sql = sql[over_open_idx + 1:over_close_idx]
        order_bounds = _find_top_level_order_by(inner_sql)
        rewritten_window = window_sql
        if order_bounds is not None:
            order_start, order_kw_end = order_bounds
            ob = inner_sql[order_kw_end:].strip()
            new_ob = _rewrite_order_by(ob, window_sql)
            if new_ob:
                new_inner = inner_sql[:order_kw_end] + " " + new_ob
                rewritten_window = sql[m.start():over_open_idx + 1] + new_inner + ")"

        parts.append(sql[cursor:m.start()])
        parts.append(rewritten_window)
        cursor = over_close_idx + 1

    return "".join(parts)

def _force_restore_groupby_if_aggregate_without_groupby(sql_before, sql_after):
    """
    Fail-safe untuk ONLY_FULL_GROUP_BY:
    jika setelah rewrite GROUP BY hilang,
    tetapi masih ada aggregate non-window,
    kembalikan sql_before (jangan eksekusi sql_after).
    """
    if not sql_after:
        return sql_after

    low = sql_after.lower()

    # sudah aman / windowed
    if "row_number(" in low:
        return sql_after

    # tidak ada aggregate → aman
    if not re.search(r"\b(max|min|sum|avg|count)\s*\(", sql_after, flags=re.I):
        return sql_after

    def _has_top_level_non_window_aggregate(text: str) -> bool:
        quote = ""
        depth = 0
        i = 0
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote:
                    if quote == "'" and i + 1 < len(text) and text[i + 1] == "'":
                        i += 2
                        continue
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0:
                m = re.match(r"(?is)\b(max|min|sum|avg|count)\s*\(", text[i:])
                if m:
                    open_idx = i + m.group(0).rfind("(")
                    inner_depth = 1
                    j = open_idx + 1
                    inner_quote = ""
                    while j < len(text):
                        cj = text[j]
                        if inner_quote:
                            if cj == inner_quote:
                                if inner_quote == "'" and j + 1 < len(text) and text[j + 1] == "'":
                                    j += 2
                                    continue
                                inner_quote = ""
                            j += 1
                            continue
                        if cj in {"'", '"', "`"}:
                            inner_quote = cj
                            j += 1
                            continue
                        if cj == "(":
                            inner_depth += 1
                        elif cj == ")":
                            inner_depth -= 1
                            if inner_depth == 0:
                                break
                        j += 1
                    tail = text[j + 1:j + 40] if j < len(text) else ""
                    if not re.match(r"(?is)^\s*OVER\s*\(", tail):
                        return True
                    i = max(j + 1, i + 1)
                    continue
            i += 1
        return False

    # ada aggregate top-level tapi tidak ada GROUP BY → rollback.
    # Aggregate scalar subqueries are safe without an outer GROUP BY.
    if "group by" not in low and _has_top_level_non_window_aggregate(sql_after):
        return sql_before

    return sql_after


def _question_wants_group_avg_vs_overall_avg(question: str) -> bool:
    """
    Dynamic detector for intent:
    group average compared against an overall/global average baseline.
    """
    q = (question or "").lower().strip()
    if not q:
        return False

    has_avg = bool(re.search(r"\b(?:avg|average|mean)\b", q, flags=re.I))
    has_overall = bool(
        re.search(
            r"\b(?:overall|global|across\s+all|entire)\b|\bacross\s+the\s+(?:whole|entire)\b",
            q,
            flags=re.I,
        )
    )
    has_cmp = bool(
        re.search(
            r"\b(?:higher|greater|more|above|over|lower|less|below|under)\s+than\b",
            q,
            flags=re.I,
        )
        or re.search(
            r"\b(?:higher|greater|more|above|over|lower|less|below|under)\b"
            r"[^.]{0,96}\b(?:overall|global|average|mean)\b",
            q,
            flags=re.I,
        )
    )
    return has_avg and has_overall and has_cmp


def _parse_aggregate_threshold_number(text: str) -> Optional[float]:
    raw = str(text or "").strip().lower()
    if not raw:
        return None
    try:
        return float(raw.replace(",", ""))
    except Exception:
        pass

    units = {
        "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
        "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
        "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14,
        "fifteen": 15, "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19,
    }
    tens = {
        "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50,
        "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90,
    }
    tokens = [tok for tok in re.findall(r"[a-z]+", raw) if tok != "and"]
    if not tokens:
        return None

    total = 0
    current = 0
    seen = False
    for tok in tokens:
        if tok in units:
            current += units[tok]
            seen = True
        elif tok in tens:
            current += tens[tok]
            seen = True
        elif tok == "hundred":
            current = max(1, current) * 100
            seen = True
        elif tok == "thousand":
            current = max(1, current) * 1000
            total += current
            current = 0
            seen = True
        else:
            return None
    if not seen:
        return None
    return float(total + current)


def _extract_numeric_aggregate_threshold(
    question: str,
    *,
    require_filter_intent: bool = False,
) -> Optional[Tuple[str, float]]:
    q = str(question or "").strip().lower()
    if not q:
        return None

    has_agg_cue = bool(
        re.search(
            r"\b(?:avg|average|mean|sum|total|count|number\s+of|max|min|maximum|minimum)\b",
            q,
            flags=re.I,
        )
    )
    if not has_agg_cue:
        return None

    if require_filter_intent:
        has_filter_intent = bool(
            re.search(r"\b(?:return|show|find|list|keep)\s+only\b", q, flags=re.I)
            or re.search(r"\b(?:whose|where)\b", q, flags=re.I)
        )
        if not has_filter_intent:
            return None
        if re.search(r"\b(?:when|if)\b[^.]{0,96}\b(?:otherwise|else)\b", q, flags=re.I):
            return None

    num_pat = r"(\d[\d,]*(?:\.\d+)?|[a-z]+(?:[\s-]+[a-z]+){0,4})"
    patterns = [
        (r"\bmore\s+than\s+" + num_pat + r"\b", "gt"),
        (r"\bover\s+" + num_pat + r"\b", "gt"),
        (r"\bgreater\s+than\s+" + num_pat + r"\b", "gt"),
        (r"\babove\s+" + num_pat + r"\b", "gt"),
        (r"\bexceeds?\s+" + num_pat + r"\b", "gt"),
        (r"\bat\s+least\s+" + num_pat + r"\b", "gte"),
        (r"\bno\s+fewer\s+than\s+" + num_pat + r"\b", "gte"),
        (r"\bless\s+than\s+" + num_pat + r"\b", "lt"),
        (r"\bfewer\s+than\s+" + num_pat + r"\b", "lt"),
        (r"\bunder\s+" + num_pat + r"\b", "lt"),
        (r"\bbelow\s+" + num_pat + r"\b", "lt"),
        (r"\bat\s+most\s+" + num_pat + r"\b", "lte"),
        (r"\bno\s+more\s+than\s+" + num_pat + r"\b", "lte"),
        (r"\bexactly\s+" + num_pat + r"\b", "eq"),
    ]
    for pat, op in patterns:
        m = re.search(pat, q, flags=re.I)
        if not m:
            continue
        parsed = _parse_aggregate_threshold_number(m.group(1))
        if parsed is not None:
            return op, parsed
    return None


def _extract_question_threshold_matches(question: str) -> List[Tuple[int, int, str, float]]:
    q = str(question or "").strip().lower()
    if not q:
        return []

    num_pat = r"(\d[\d,]*(?:\.\d+)?|[a-z]+(?:[\s-]+[a-z]+){0,4})"
    patterns = [
        (r"\bmore\s+than\s+" + num_pat + r"\b", "gt"),
        (r"\bover\s+" + num_pat + r"\b", "gt"),
        (r"\bgreater\s+than\s+" + num_pat + r"\b", "gt"),
        (r"\babove\s+" + num_pat + r"\b", "gt"),
        (r"\bexceeds?\s+" + num_pat + r"\b", "gt"),
        (r"\bat\s+least\s+" + num_pat + r"\b", "gte"),
        (r"\bno\s+fewer\s+than\s+" + num_pat + r"\b", "gte"),
        (r"\bless\s+than\s+" + num_pat + r"\b", "lt"),
        (r"\bfewer\s+than\s+" + num_pat + r"\b", "lt"),
        (r"\bunder\s+" + num_pat + r"\b", "lt"),
        (r"\bbelow\s+" + num_pat + r"\b", "lt"),
        (r"\bat\s+most\s+" + num_pat + r"\b", "lte"),
        (r"\bno\s+more\s+than\s+" + num_pat + r"\b", "lte"),
        (r"\bexactly\s+" + num_pat + r"\b", "eq"),
    ]

    seen: Set[Tuple[int, int, str, float]] = set()
    matches: List[Tuple[int, int, str, float]] = []
    for pat, op in patterns:
        for m in re.finditer(pat, q, flags=re.I):
            parsed = _parse_aggregate_threshold_number(m.group(1))
            if parsed is None:
                continue
            key = (m.start(), m.end(), op, float(parsed))
            if key in seen:
                continue
            seen.add(key)
            matches.append(key)
    matches.sort(key=lambda item: (item[0], item[1], item[2], item[3]))
    return matches


def _add_missing_grouped_metric_threshold_having(sql: str, question: str, ctx: str = "") -> str:
    """
    Add missing HAVING predicates for grouped metrics when the question
    explicitly states count/average thresholds but the grouped query forgets to
    apply them.

    Conservative scope:
    - top-level grouped query only
    - works from projected metric expressions already present in SELECT
    - currently supports count-like and average-like grouped metrics
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q or "group by" not in q and " for each " not in f" {q} " and " per " not in f" {q} ":
        # Keep this focused on grouped-output questions.
        if not re.search(r"\b(?:average|avg|mean|count|number\s+of|total\s+number\s+of)\b", q, flags=re.I):
            return sql

    parsed = _parse_flat_groupby_clauses(sql) or _parse_select_from_groupby(sql)
    if not parsed:
        return sql
    if not str(parsed.get("groupby") or "").strip():
        return sql

    select_items = [
        str(item).strip()
        for item in _split_top_level_commas(parsed.get("select") or "")
        if str(item or "").strip()
    ]
    if not select_items:
        return sql

    metric_exprs: Dict[str, List[Tuple[str, str]]] = {"count": [], "avg": []}
    ratio_avg_question = _question_defines_average_as_total_over_count(question)
    seen_metric_exprs: Dict[str, Set[str]] = {"count": set(), "avg": set()}

    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        expr_txt = str(expr or "").strip()
        alias_txt = str(alias or "").strip().strip("`'\"")
        if not expr_txt:
            continue
        if re.search(r"\bOVER\s*\(", expr_txt, flags=re.I):
            continue

        expr_norm = _normalize_sql_expr_for_match(expr_txt)
        alias_l = alias_txt.lower()
        alias_tokens = set(re.findall(r"[a-z0-9]+", alias_l.replace("_", " ")))

        count_alias_cue = bool(alias_tokens & {"count", "counts", "number", "numbers", "num", "total"})
        count_expr_cue = bool(
            re.match(r"(?is)^\s*COUNT\s*\(", expr_txt)
            or (
                count_alias_cue
                and re.search(r"\bCOUNT\s*\(", expr_txt, flags=re.I)
                and not re.search(r"[+\-/*]", expr_txt)
            )
        )
        if count_expr_cue:
            if expr_norm not in seen_metric_exprs["count"]:
                seen_metric_exprs["count"].add(expr_norm)
                metric_exprs["count"].append((expr_txt, alias_txt))

        avg_alias_cue = bool(alias_tokens & {"avg", "average", "mean"})
        avg_expr_cue = bool(re.match(r"(?is)^\s*AVG\s*\(", expr_txt))
        avg_ratio_cue = bool(
            ratio_avg_question
            and "/" in expr_txt
            and re.search(r"\bCOUNT\s*\(", expr_txt, flags=re.I)
            and (avg_alias_cue or re.search(r"\bSUM\s*\(", expr_txt, flags=re.I))
        )
        if avg_alias_cue or avg_expr_cue or avg_ratio_cue:
            if expr_norm not in seen_metric_exprs["avg"]:
                seen_metric_exprs["avg"].add(expr_norm)
                metric_exprs["avg"].append((expr_txt, alias_txt))

    threshold_matches = _extract_question_threshold_matches(question)
    if not threshold_matches:
        return sql

    select_text = " ".join(select_items)

    def _threshold_literal_sql(value: float) -> str:
        return str(int(value)) if float(value).is_integer() else str(value)

    def _question_prefix_has_row_level_property_cue(prefix: str) -> bool:
        prefix_tail = str(prefix or "")[-96:]
        if not prefix_tail:
            return False
        return bool(
            re.search(
                r"\b(?:have|has|had|having|with)\s+(?:(?:a|an|the|their|its)\s+)?[a-z][a-z0-9_ ]{1,48}(?:\s+of)?\s*$",
                prefix_tail,
                flags=re.I,
            )
            or re.search(
                r"\bwhose\s+[a-z][a-z0-9_ ]{1,48}(?:\s+(?:is|are))?(?:\s+of)?\s*$",
                prefix_tail,
                flags=re.I,
            )
        )

    def _select_has_matching_case_threshold(value: float) -> bool:
        value_sql = _threshold_literal_sql(value)
        if not value_sql:
            return False
        value_pat = re.escape(value_sql)
        return bool(
            re.search(
                rf"\bCASE\s+WHEN\b(?:(?!END).){{0,320}}(?:>=|<=|>|<|=)\s*{value_pat}\b",
                select_text,
                flags=re.I | re.S,
            )
            or re.search(
                rf"\bCASE\s+WHEN\b(?:(?!END).){{0,320}}\b{value_pat}\s*(?:>=|<=|>|<|=)",
                select_text,
                flags=re.I | re.S,
            )
        )

    count_object_terms: Set[str] = {
        "row", "rows", "record", "records", "entry", "entries",
        "item", "items", "line", "lines", "group", "groups",
    }
    try:
        for table_name in get_all_tables() or []:
            table_l = str(table_name or "").strip().lower()
            if not table_l:
                continue
            count_object_terms.add(table_l)
            singular = str(get_singular_form(table_l) or "").strip().lower()
            if singular:
                count_object_terms.add(singular)
            for syn in get_table_synonyms(table_l) or []:
                syn_l = str(syn or "").strip().lower()
                if syn_l:
                    count_object_terms.add(syn_l)
    except Exception:
        pass

    count_term_alt = "|".join(
        re.escape(term).replace(r"\ ", r"\s+")
        for term in sorted((term for term in count_object_terms if term), key=len, reverse=True)
    )
    count_prefix_pat = re.compile(
        r"\b(?:count|counts|number\s+of|total\s+number\s+of|how\s+many)\b",
        flags=re.I,
    )
    count_verb_pat = re.compile(
        r"\b(?:placed|place|made|make|have|has|had|with|received|bought|sold|ordered|contain|contains)\b",
        flags=re.I,
    )
    avg_cue_pat = re.compile(r"\b(?:avg|average|mean)\b", flags=re.I)

    count_threshold: Optional[Tuple[str, float]] = None
    avg_threshold: Optional[Tuple[str, float]] = None
    for start, end, op, val in threshold_matches:
        prefix = q[max(0, start - 96):start]
        suffix = q[end:end + 96]
        if (
            _question_prefix_has_row_level_property_cue(prefix)
            and _select_has_matching_case_threshold(val)
        ):
            continue
        suffix_has_count_object = bool(
            count_term_alt
            and re.search(
                rf"^\s+(?:\w+\s+){{0,4}}?(?:{count_term_alt})\b",
                suffix,
                flags=re.I,
            )
        )
        matched_count_here = bool(
            count_prefix_pat.search(prefix)
            or (suffix_has_count_object and count_verb_pat.search(prefix))
        )
        if count_threshold is None:
            if matched_count_here:
                count_threshold = (op, val)
        if avg_threshold is None:
            avg_prefix = prefix[-64:]
            avg_suffix = suffix[:24]
            if not matched_count_here and (
                avg_cue_pat.search(avg_prefix) or avg_cue_pat.search(avg_suffix)
            ):
                avg_threshold = (op, val)
        if count_threshold is not None and avg_threshold is not None:
            break

    def _cmp_symbol(op_key: str) -> str:
        return {
            "gt": ">",
            "gte": ">=",
            "lt": "<",
            "lte": "<=",
            "eq": "=",
        }.get(op_key, "")

    def _threshold_sql(value: float) -> str:
        return str(int(value)) if float(value).is_integer() else str(value)

    def _unique_metric(metric_key: str) -> Optional[Tuple[str, str]]:
        candidates = metric_exprs.get(metric_key, [])
        return candidates[0] if len(candidates) == 1 else None

    existing_having = str(parsed.get("having") or "").strip()
    if existing_having.lower().startswith("having "):
        existing_having = existing_having[7:].strip()
    existing_having_norm = _normalize_sql_expr_for_match(existing_having)

    new_conditions: List[str] = []

    count_metric = _unique_metric("count")
    if count_metric and count_threshold is not None:
        count_expr, count_alias = count_metric
        cmp = _cmp_symbol(count_threshold[0])
        value_sql = _threshold_sql(count_threshold[1])
        if cmp and value_sql:
            count_expr_norm = _normalize_sql_expr_for_match(count_expr)
            count_alias_norm = _normalize_sql_expr_for_match(count_alias)
            already_present = bool(
                count_expr_norm and count_expr_norm in existing_having_norm and value_sql in existing_having
            ) or bool(
                count_alias_norm and count_alias_norm in existing_having_norm and value_sql in existing_having
            )
            if not already_present:
                new_conditions.append(f"{count_expr} {cmp} {value_sql}")

    avg_metric = _unique_metric("avg")
    if avg_metric and avg_threshold is not None:
        avg_expr, avg_alias = avg_metric
        cmp = _cmp_symbol(avg_threshold[0])
        value_sql = _threshold_sql(avg_threshold[1])
        if cmp and value_sql:
            avg_expr_norm = _normalize_sql_expr_for_match(avg_expr)
            avg_alias_norm = _normalize_sql_expr_for_match(avg_alias)
            already_present = bool(
                avg_expr_norm and avg_expr_norm in existing_having_norm and value_sql in existing_having
            ) or bool(
                avg_alias_norm and avg_alias_norm in existing_having_norm and value_sql in existing_having
            )
            if not already_present:
                new_conditions.append(f"{avg_expr} {cmp} {value_sql}")

    if not new_conditions:
        return sql

    merged_having_parts: List[str] = []
    if existing_having:
        merged_having_parts.append(existing_having)
    merged_having_parts.extend(new_conditions)

    def _fmt_having_part(part: str) -> str:
        text = str(part or "").strip()
        if not text:
            return ""
        if re.search(r"\bOR\b", text, flags=re.I):
            return f"({text})"
        return text

    out_lines = [
        f"SELECT {str(parsed.get('select') or '').strip()}",
        f"FROM {str(parsed.get('from_core') or '').strip()}",
    ]
    if str(parsed.get("where") or "").strip():
        out_lines.append(str(parsed.get("where") or "").strip())
    out_lines.append(f"GROUP BY {str(parsed.get('groupby') or '').strip()}")
    out_lines.append("HAVING " + " AND ".join(_fmt_having_part(part) for part in merged_having_parts if _fmt_having_part(part)))
    if str(parsed.get("tail") or "").strip():
        out_lines.append(str(parsed.get("tail") or "").strip())

    fixed = "\n".join(out_lines).strip()
    if str(sql).strip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _fix_misplaced_entity_count_threshold(sql: str, question: str) -> str:
    """Fix WHERE col >= N → HAVING COUNT(*) >= N when the LLM misinterprets
    'at least N entities' as a raw column filter instead of a group-count
    threshold.

    Example:  "Keep only vendors with at least 3 products"
              LLM generates:  WHERE quantityInStock >= 3
              Correct:        HAVING COUNT(*) >= 3

    Guardrails (all must hold):
      - GROUP BY present, no existing HAVING
      - Question has a threshold phrase ("at least N", "N or more")
      - WHERE contains a comparison with that exact N value
      - The threshold phrase targets row/entity count, not a raw value filter
    """
    s = (sql or "").strip()
    if not s or not question:
        return s

    sl = s.lower()
    if "group by" not in sl:
        return s

    # --- extract row/entity-count threshold from question ---
    q = question.lower()
    threshold_matches = list(re.finditer(r"\bat\s+least\s+(\d+)\b", q, flags=re.I))
    threshold_matches.extend(re.finditer(r"\b(\d+)\s+or\s+more\b", q, flags=re.I))

    schema_count_terms: Set[str] = {
        "row", "rows", "record", "records", "line", "lines", "entry", "entries",
        "item", "items", "group", "groups",
    }
    try:
        for table_name in get_all_tables() or []:
            table_l = str(table_name or "").strip().lower()
            if not table_l:
                continue
            schema_count_terms.add(table_l)
            singular = get_singular_form(table_l)
            if singular:
                schema_count_terms.add(str(singular).strip().lower())
            for syn in get_table_synonyms(table_l) or []:
                syn_l = str(syn or "").strip().lower()
                if syn_l:
                    schema_count_terms.add(syn_l)
    except Exception:
        pass

    # Keep this repair independent of schema singleton warmup.  During isolated
    # normalization, the SQL itself still tells us the entity being grouped.
    for table_name in re.findall(r"\b(?:FROM|JOIN)\s+`?([A-Za-z_][A-Za-z0-9_]*)`?", s, flags=re.I):
        table_l = str(table_name or "").strip().lower()
        if not table_l:
            continue
        schema_count_terms.add(table_l)
        singular = _to_singular(table_l)
        if singular:
            schema_count_terms.add(singular)

    count_term_alt = "|".join(
        re.escape(term).replace(r"\ ", r"\s+")
        for term in sorted(schema_count_terms, key=len, reverse=True)
        if term
    )
    local_stop_terms = [
        str(term or "").strip().lower()
        for term in threshold_count_object_stop_terms()
        if str(term or "").strip()
    ]
    local_stop_alt = "|".join(
        re.escape(term).replace(r"\ ", r"\s+")
        for term in sorted(local_stop_terms, key=len, reverse=True)
        if term
    )
    tm = None
    count_object_cue = False
    frequency_tail_pat = re.compile(r"^\s+times?\b", flags=re.I)
    frequency_prefix_pat = re.compile(
        r"\b(?:appear|appears|appearing|occur|occurs|occurring|repeat|repeats?|show\s+up|shows\s+up)\b",
        flags=re.I,
    )
    for cand in sorted(threshold_matches, key=lambda m: m.start()):
        threshold_tail = q[cand.end():cand.end() + 96]
        threshold_prefix = q[max(0, cand.start() - 64):cand.start()]
        if local_stop_alt:
            threshold_tail = re.split(
                rf"\b(?:{local_stop_alt})\b",
                threshold_tail,
                maxsplit=1,
                flags=re.I,
            )[0]
        if count_term_alt and re.search(
            rf"^\s+(?:\w+\s+){{0,4}}?(?:{count_term_alt})\b",
            threshold_tail,
            flags=re.I,
        ):
            tm = cand
            count_object_cue = True
            break
        if frequency_tail_pat.search(threshold_tail) and frequency_prefix_pat.search(threshold_prefix):
            tm = cand
            count_object_cue = True
            break
    if not tm:
        return s
    threshold_n = int(tm.group(1))
    if threshold_n < 2:
        return s

    if not count_object_cue:
        return s

    # --- locate top-level WHERE/GROUP BY.  Regex lookaheads can stop at an
    # inner GROUP BY inside a subquery, which is exactly the bad shape this
    # repair needs to remove.
    where_pos = _find_top_level_clause(s, "where")
    if where_pos >= 0:
        group_pos = _find_top_level_clause(s, "group by", max(0, where_pos + len("where")))
    else:
        group_pos = _find_top_level_clause(s, "group by")
    if group_pos < 0:
        return s

    having_pos = _find_top_level_clause(s, "having", group_pos + len("group by"))
    order_pos = _find_top_level_clause(s, "order by", group_pos + len("group by"))
    limit_pos = _find_top_level_clause(s, "limit", group_pos + len("group by"))
    group_end = min([p for p in (having_pos, order_pos, limit_pos, len(s)) if p >= 0])
    group_text = s[group_pos + len("group by"):group_end].lower()

    def _has_count_threshold(text: str) -> bool:
        return bool(re.search(
            rf"\bCOUNT\s*\([^)]*\)\s*(?:>=|>)\s*{threshold_n}\b",
            text,
            flags=re.I,
        ))

    def _insert_count_having(text: str, op: str = ">=") -> str:
        if _has_count_threshold(text):
            return text
        having_condition = f"COUNT(*) {op} {threshold_n}"
        having_m = re.search(r"\bHAVING\b", text, flags=re.I)
        if having_m:
            after_having = text[having_m.end():]
            end_m = re.search(r"\b(?:ORDER\s+BY|LIMIT)\b|;|$", after_having, flags=re.I)
            if end_m:
                insert_pos = having_m.end() + end_m.start()
                return text[:insert_pos].rstrip() + f" AND {having_condition} " + text[insert_pos:].lstrip()
            return text
        gb_m = re.search(r"\bGROUP\s+BY\b", text, flags=re.I)
        if not gb_m:
            return text
        after_gb = text[gb_m.end():]
        end_m = re.search(r"\b(?:ORDER\s+BY|LIMIT)\b|;|$", after_gb, flags=re.I)
        if not end_m:
            return text
        insert_pos = gb_m.end() + end_m.start()
        return text[:insert_pos] + f" HAVING {having_condition} " + text[insert_pos:]

    if where_pos < 0:
        if _has_count_threshold(s):
            return s
        return re.sub(r"\s{2,}", " ", _insert_count_having(s)).strip()

    where_text = s[where_pos + len("where"):group_pos]
    where_start = where_pos
    where_end = group_pos

    # --- split WHERE by AND, look for misplaced threshold ---
    parts = re.split(r"\bAND\b", where_text, flags=re.I)
    keep_parts: list[str] = []
    replaced = False
    having_op = ">="

    def _identifier_phrase(identifier: str) -> str:
        raw = str(identifier or "").split(".")[-1].strip("`")
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = re.sub(r"[_\W]+", " ", raw).strip().lower()
        return raw

    def _has_existence_cue_for_column(col_name: str, text: str) -> bool:
        phrase = _identifier_phrase(col_name)
        if not phrase:
            return False
        phrase_pat = r"\s+".join(re.escape(tok) for tok in phrase.split())
        # "at least 3 customers who have a credit limit" means the threshold is
        # on customers, while the metric column should remain an existence filter.
        return bool(re.search(
            rf"\b(?:who|that)?\s*(?:have|has|with)\s+(?:(?:a|an|any)\s+|non[-\s]?null\s+)?{phrase_pat}\b",
            text,
            flags=re.I,
        ))

    for part in parts:
        part_s = part.strip()
        cmp_m = re.match(
            r"^([\w.]+)\s*(>=|>|<=|<|=)\s*(\d+(?:\.\d+)?)\s*$",
            part_s,
            flags=re.I,
        )
        if cmp_m and not replaced:
            col_raw = cmp_m.group(1)
            op_raw = cmp_m.group(2)
            val_raw = float(cmp_m.group(3))
            col_bare = col_raw.split(".")[-1].lower()
            q_near_threshold = q[max(0, tm.start() - 40):tm.end() + 80]
            column_named_near_threshold = bool(
                col_bare
                and re.search(rf"\b{re.escape(col_bare)}\b", q_near_threshold, flags=re.I)
            )
            existence_cue_near_threshold = _has_existence_cue_for_column(col_raw, q_near_threshold)
            col_is_group_key = bool(
                col_bare
                and re.search(rf"(?:^|[\s,.])(?:`?\w+`?\.)?`?{re.escape(col_bare)}`?(?:$|[\s,.])", group_text, flags=re.I)
            )
            # Row-count thresholds ("at least 10 lines") should become HAVING
            # even if the misplaced column is also aggregated in SELECT. Keep
            # true value filters when the question locally names that column,
            # unless the local wording uses it as an existence cue.
            if (
                int(val_raw) == threshold_n
                and (not column_named_near_threshold or existence_cue_near_threshold)
                and not col_is_group_key
            ):
                having_op = ">=" if op_raw in (">=", ">") else op_raw
                replaced = True
                if existence_cue_near_threshold:
                    keep_parts.append(f"{col_raw} IS NOT NULL")
                continue

        in_count_subquery_m = re.match(
            r"""(?is)^
                (?P<outer_col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)
                \s+IN\s*\(\s*
                SELECT\s+(?P<select_col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)
                \s+FROM\s+`?[A-Za-z_][A-Za-z0-9_]*`?
                \s+GROUP\s+BY\s+(?P<group_col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)
                \s+HAVING\s+COUNT\s*\(\s*(?P<count_col>[^)]*)\)\s*(?:>=|>)\s*(?P<n>\d+)
                \s*\)\s*$
            """,
            part_s,
            flags=re.X,
        )
        if in_count_subquery_m and not replaced:
            def _clean_col_name(expr: str) -> str:
                return str(expr or "").replace("`", "").split(".")[-1].strip().lower()

            outer_col = _clean_col_name(in_count_subquery_m.group("outer_col"))
            select_col = _clean_col_name(in_count_subquery_m.group("select_col"))
            group_col = _clean_col_name(in_count_subquery_m.group("group_col"))
            count_n = int(in_count_subquery_m.group("n") or "0")
            if outer_col and outer_col == select_col == group_col and count_n == threshold_n:
                having_op = ">="
                replaced = True
                continue
        keep_parts.append(part_s)

    if not replaced:
        if _has_count_threshold(s):
            return s
        return re.sub(r"\s{2,}", " ", _insert_count_having(s)).strip()

    # --- rebuild: strip WHERE, then insert HAVING after GROUP BY clause ---
    if keep_parts:
        new_where = " AND ".join(keep_parts)
        s = s[:where_start] + "WHERE " + new_where + " " + s[where_end:]
    else:
        s = s[:where_start] + s[where_end:]

    s = _insert_count_having(s, having_op)

    s = re.sub(r"\s{2,}", " ", s)
    return s


def _find_top_level_clause(sql: str, keyword: str, start: int = 0) -> int:
    """Find a top-level SQL keyword while ignoring quoted text and parentheses."""
    text = str(sql or "")
    kw = str(keyword or "").lower()
    if not text or not kw:
        return -1
    depth = 0
    in_sq = False
    in_dq = False
    i = max(0, start)
    low = text.lower()
    n = len(kw)
    while i < len(text):
        ch = text[i]
        if ch == "'" and not in_dq:
            if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                i += 2
                continue
            in_sq = not in_sq
            i += 1
            continue
        if ch == '"' and not in_sq:
            in_dq = not in_dq
            i += 1
            continue
        if in_sq or in_dq:
            i += 1
            continue
        if ch == "(":
            depth += 1
            i += 1
            continue
        if ch == ")":
            depth = max(0, depth - 1)
            i += 1
            continue
        if depth == 0 and low.startswith(kw, i):
            left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
            right_idx = i + n
            right_ok = right_idx >= len(text) or not (text[right_idx].isalnum() or text[right_idx] == "_")
            if left_ok and right_ok:
                return i
        i += 1
    return -1


def _split_select_expr_alias(item: str) -> tuple[str, Optional[str]]:
    raw = (item or "").strip()
    m = re.match(
        r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
        raw,
    )
    if not m:
        return raw, None
    alias = (m.group(2) or "").strip().strip("`'\"")
    return (m.group(1) or "").strip(), alias or None


def _normalize_sql_expr_for_match(expr: str) -> str:
    text = re.sub(r"`", "", str(expr or ""))
    text = re.sub(r"\bSUBSTR\s*\(", "SUBSTRING(", text, flags=re.I)
    text = re.sub(r"\bCHAR_LENGTH\s*\(", "LENGTH(", text, flags=re.I)
    text = re.sub(r"\s+", "", text).lower()
    return text


def _referenced_column_tokens(expr: str) -> Set[str]:
    no_strings = re.sub(r"'(?:''|[^'])*'|\"(?:\"\"|[^\"])*\"", " ", str(expr or ""))
    tokens = {
        tok.lower()
        for tok in re.findall(r"[A-Za-z_][A-Za-z0-9_]*", no_strings)
    }
    stop = {
        "select", "from", "where", "group", "by", "having", "order", "limit",
        "as", "and", "or", "case", "when", "then", "else", "end", "is", "not",
        "null", "in", "between", "distinct",
        "count", "sum", "avg", "min", "max", "length", "char_length",
        "substring", "substr", "left", "right", "concat", "concat_ws",
        "year", "month", "quarter", "date_format", "datediff",
    }
    return {tok for tok in tokens if tok not in stop}


def _canonicalize_single_computed_group_by_expression(sql: str) -> str:
    """
    If a flat aggregate projects one computed dimension, ensure GROUP BY uses
    that exact expression. This avoids ONLY_FULL_GROUP_BY failures caused by
    alias expansion or function-argument drift.
    """
    s = (sql or "").strip()
    if not s or "group by" not in s.lower():
        return sql
    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s

    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    group_pos = _find_top_level_clause(s0, "group by", max(0, from_pos + len("from")))
    if sel_pos != 0 or from_pos < 0 or group_pos < 0:
        return sql

    having_pos = _find_top_level_clause(s0, "having", group_pos + len("group by"))
    order_pos = _find_top_level_clause(s0, "order by", group_pos + len("group by"))
    limit_pos = _find_top_level_clause(s0, "limit", group_pos + len("group by"))
    group_end = min([p for p in (having_pos, order_pos, limit_pos, len(s0)) if p >= 0])

    select_items = _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip())
    group_items = _split_top_level_commas(s0[group_pos + len("group by"):group_end].strip())
    if len(group_items) != 1:
        return sql

    computed_dims: List[tuple[str, Optional[str]]] = []
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        if not expr:
            continue
        if re.search(r"\b(?:COUNT|SUM|AVG|MIN|MAX|STDDEV|VARIANCE|GROUP_CONCAT)\s*\(", expr, flags=re.I):
            continue
        if re.search(r"\bOVER\s*\(", expr, flags=re.I):
            continue
        if _is_simple_column_expr(expr):
            continue
        computed_dims.append((expr, alias))

    if len(computed_dims) != 1:
        return sql

    expr, alias = computed_dims[0]
    group_item = group_items[0].strip()
    alias_l = (alias or "").strip("`").lower()
    group_l = group_item.strip("`").lower()
    if _normalize_sql_expr_for_match(group_item) == _normalize_sql_expr_for_match(expr):
        return sql

    expr_refs = _referenced_column_tokens(expr)
    group_refs = _referenced_column_tokens(group_item)
    alias_match = bool(alias_l and group_l == alias_l)
    same_refs = bool(expr_refs and group_refs and expr_refs == group_refs)
    if not (alias_match or same_refs):
        return sql

    suffix = s0[group_end:].lstrip()
    rebuilt = s0[:group_pos + len("group by")] + " " + expr
    if suffix:
        rebuilt += " " + suffix
    return rebuilt + trailing


def _simplify_same_expression_group_threshold_subquery(sql: str) -> str:
    """
    Collapse redundant filters of the form:
      WHERE expr IN (SELECT expr FROM same_table GROUP BY expr HAVING ...)
      GROUP BY expr
    into a direct outer HAVING. This is equivalent for grouped expression
    thresholds and avoids dialect-sensitive ONLY_FULL_GROUP_BY behavior.
    """
    s = (sql or "").strip()
    if not s or " where " not in f" {s.lower()} " or " group by " not in f" {s.lower()} ":
        return sql
    if _find_top_level_clause(s, "having") >= 0:
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    where_pos = _find_top_level_clause(s0, "where")
    group_pos = _find_top_level_clause(s0, "group by", max(0, where_pos + len("where")))
    if where_pos < 0 or group_pos < 0:
        return sql

    where_body = s0[where_pos + len("where"):group_pos].strip()
    if re.search(r"\b(?:AND|OR)\b", where_body, flags=re.I):
        return sql

    order_pos = _find_top_level_clause(s0, "order by", group_pos + len("group by"))
    limit_pos = _find_top_level_clause(s0, "limit", group_pos + len("group by"))
    group_end = min([p for p in (order_pos, limit_pos, len(s0)) if p >= 0])
    outer_group = s0[group_pos + len("group by"):group_end].strip()

    pattern = re.compile(
        r"""(?is)^\s*(?P<outer>.+?)\s+IN\s*\(\s*
            SELECT\s+(?P<inner_select>.+?)\s+
            FROM\s+(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?)\s+
            GROUP\s+BY\s+(?P<inner_group>.+?)\s+
            HAVING\s+(?P<having>.+?)\s*
            \)\s*$""",
        re.X,
    )
    m = pattern.match(where_body)
    if not m:
        return sql

    outer_expr = (m.group("outer") or "").strip()
    inner_select = (m.group("inner_select") or "").strip()
    inner_group = (m.group("inner_group") or "").strip()
    having = (m.group("having") or "").strip()
    if not having:
        return sql

    outer_norm = _normalize_sql_expr_for_match(outer_expr)
    if not outer_norm:
        return sql
    if outer_norm != _normalize_sql_expr_for_match(inner_select):
        return sql
    if outer_norm != _normalize_sql_expr_for_match(inner_group):
        return sql
    if outer_norm != _normalize_sql_expr_for_match(outer_group):
        return sql

    suffix = s0[group_end:].lstrip()
    rebuilt = (
        s0[:where_pos].rstrip()
        + " "
        + s0[group_pos:group_end].strip()
        + f" HAVING {having}"
    )
    if suffix:
        rebuilt += " " + suffix
    rebuilt += trailing
    return re.sub(r"\s{2,}", " ", rebuilt).strip()


def _simplify_group_key_count_threshold_subquery(sql: str) -> str:
    """
    Collapse invalid same-table row-id IN subqueries used for grouped count
    thresholds into an outer HAVING.

    Example:
      WHERE row_id IN (
        SELECT row_id FROM t GROUP BY group_key HAVING COUNT(row_id) >= 2
      )
      GROUP BY group_key

    becomes:
      GROUP BY group_key HAVING COUNT(row_id) >= 2

    This only runs for a single top-level IN predicate and same-table GROUP BY
    threshold shape, so it does not reinterpret arbitrary subqueries.
    """
    s = (sql or "").strip()
    if not s or " where " not in f" {s.lower()} " or " group by " not in f" {s.lower()} ":
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    where_pos = _find_top_level_clause(s0, "where")
    group_pos = _find_top_level_clause(s0, "group by", max(0, where_pos + len("where")))
    if where_pos < 0 or group_pos < 0:
        return sql

    from_pos = _find_top_level_clause(s0, "from")
    if from_pos < 0 or from_pos > where_pos:
        return sql
    from_body = s0[from_pos + len("from"):where_pos].strip()
    outer_table_m = re.match(
        r"(?is)^`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?\s*$",
        from_body,
    )
    if not outer_table_m:
        return sql
    outer_table = (outer_table_m.group("table") or "").strip("`").lower()

    where_body = s0[where_pos + len("where"):group_pos].strip()
    if re.search(r"\b(?:AND|OR)\b", where_body, flags=re.I):
        return sql

    order_pos = _find_top_level_clause(s0, "order by", group_pos + len("group by"))
    limit_pos = _find_top_level_clause(s0, "limit", group_pos + len("group by"))
    having_pos = _find_top_level_clause(s0, "having", group_pos + len("group by"))
    group_end = min([p for p in (having_pos, order_pos, limit_pos, len(s0)) if p >= 0])
    outer_group = s0[group_pos + len("group by"):group_end].strip()
    if not outer_group:
        return sql

    # The HAVING expression is intentionally validated separately below; this
    # regex only scopes the top-level shape.
    m = re.match(
        r"""(?is)^\s*(?P<outer_key>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+
            IN\s*\(\s*
            SELECT\s+(?P<inner_key>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+
            FROM\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?
            (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
            \s+GROUP\s+BY\s+(?P<inner_group>.+?)\s+
            HAVING\s+(?P<having>.+?)\s*
            \)\s*$""",
        where_body,
        flags=re.I | re.S | re.X,
    )
    if not m:
        return sql

    inner_table = (m.group("table") or "").strip("`").lower()
    if inner_table != outer_table:
        return sql

    outer_key = (m.group("outer_key") or "").strip()
    inner_key = (m.group("inner_key") or "").strip()
    inner_group = (m.group("inner_group") or "").strip()
    having = (m.group("having") or "").strip()
    if not outer_key or not inner_key or not inner_group or not having:
        return sql
    outer_key_norm = _normalize_sql_expr_for_match(outer_key)
    inner_key_norm = _normalize_sql_expr_for_match(inner_key)
    outer_group_norm = _normalize_sql_expr_for_match(outer_group)
    inner_group_norm = _normalize_sql_expr_for_match(inner_group)
    if not outer_key_norm or not inner_key_norm or not outer_group_norm or not inner_group_norm:
        return sql
    # Canonical path: same key projected/filtered/grouped in both scopes.
    if outer_key_norm != inner_key_norm or outer_group_norm != inner_group_norm:
        # Fallback path:
        #   WHERE group_key IN (
        #     SELECT row_id FROM same_table GROUP BY row_id HAVING COUNT(row_id) >= N
        #   )
        # with outer GROUP BY group_key.
        #
        # This shape is a common hallucinated threshold rewrite (group key
        # compared to row-id domain). For same-table grouped summaries, the
        # intended semantics are the outer HAVING threshold.
        if outer_key_norm != outer_group_norm:
            return sql
    if not re.search(r"\bCOUNT\s*\(\s*(?:\*|(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)\s*(?:>=|>|=|<=|<)\s*\d+\b", having, flags=re.I):
        return sql

    suffix = s0[group_end:].lstrip()
    existing_having = ""
    if having_pos >= 0 and having_pos == group_end:
        next_after_having = min([p for p in (order_pos, limit_pos, len(s0)) if p >= 0 and p > having_pos])
        existing_having = s0[having_pos + len("having"):next_after_having].strip()
        suffix = s0[next_after_having:].lstrip()

    rebuilt = s0[:where_pos].rstrip() + " " + s0[group_pos:group_end].strip()
    if existing_having:
        rebuilt += f" HAVING ({existing_having}) AND ({having})"
    else:
        rebuilt += f" HAVING {having}"
    if suffix:
        rebuilt += " " + suffix
    rebuilt += trailing
    return re.sub(r"\s{2,}", " ", rebuilt).strip()


def _rewrite_grouped_count_rank_to_window_rank(sql: str, question: str) -> str:
    """
    Rewrite malformed grouped COUNT-as-rank queries into window rank queries.

    Target anti-pattern:
      SELECT dim_a, dim_b, COUNT(*) AS rank
      FROM t
      GROUP BY dim_a, dim_b
    for questions that explicitly ask ranking "inside/within each <group>".
    """
    s = (sql or "").strip()
    q = (question or "").strip().lower()
    if not s or not q:
        return sql
    if re.search(r"\b(?:row_number|rank|dense_rank)\s*\(", s, flags=re.I):
        return sql
    if not re.search(r"\b(?:rank|ranking|ranked)\b", q, flags=re.I):
        return sql
    if not re.search(r"\b(?:inside|within|per|each)\b", q, flags=re.I):
        return sql
    if not re.search(r"\b(?:sorted|sort|ordered|order)\b", q, flags=re.I):
        return sql

    parsed = _parse_flat_groupby_clauses(s) or _parse_select_from_groupby(s)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    if not from_core or re.search(r"\bjoin\b", from_core, flags=re.I):
        return sql

    group_text = str(parsed.get("groupby") or "").strip()
    if not group_text:
        return sql
    group_items = [x.strip() for x in _split_top_level_commas(group_text) if x.strip()]
    if len(group_items) < 2:
        return sql

    select_text = str(parsed.get("select") or "").strip()
    select_items = [x.strip() for x in _split_top_level_commas(select_text) if x.strip()]
    if len(select_items) < 3:
        return sql

    rank_alias = ""
    projected_dims: List[str] = []
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        expr_s = str(expr or "").strip()
        alias_s = str(alias or "").strip().strip("`").lower()
        if (
            re.match(r"(?is)^count\s*\(", expr_s)
            and (
                alias_s == "rank"
                or bool(re.search(r"(?:^|_)(?:rank|ranking|position)(?:$|_)", alias_s, flags=re.I))
                or bool(re.search(r"(?:^|_)row_?number(?:$|_)", alias_s, flags=re.I))
            )
        ):
            rank_alias = str(alias or "rank").strip("`") or "rank"
            continue
        if re.search(r"\b(?:count|sum|avg|min|max)\s*\(", expr_s, flags=re.I):
            return sql
        simple_expr = _parse_simple_rank_column_expr(expr_s)
        if not simple_expr:
            return sql
        projected_dims.append(simple_expr)

    if not rank_alias or len(projected_dims) < 2:
        return sql

    # Rank partition target from question cues ("inside each office", etc.).
    partition_terms = _extract_rank_partition_terms_from_question(q)
    partition_expr = _choose_rank_partition_expr(
        [(expr, _rank_text_terms(expr)) for expr in projected_dims],
        partition_terms,
    )
    if not partition_expr:
        return sql

    order_candidates = [expr for expr in projected_dims if expr.lower() != partition_expr.lower()]
    if not order_candidates:
        return sql

    # Prefer numeric/id-like dimension as rank order metric.
    def _score_order(expr: str) -> tuple:
        base = expr.split(".")[-1].strip("`").lower()
        id_like = int(bool(re.search(r"(?:id|number|code)$", base)))
        return (id_like, len(base))

    order_expr = sorted(order_candidates, key=_score_order, reverse=True)[0]
    high_to_low = bool(
        re.search(r"\bfrom\s+high(?:est)?\s+to\s+low(?:est)?\b", q, flags=re.I)
        or re.search(r"\bdescending\b|\bdesc\b", q, flags=re.I)
    )
    low_to_high = bool(
        re.search(r"\bfrom\s+low(?:est)?\s+to\s+high(?:est)?\b", q, flags=re.I)
        or re.search(r"\bascending\b|\basc\b", q, flags=re.I)
    )
    if high_to_low and not low_to_high:
        wants_desc = True
    elif low_to_high and not high_to_low:
        wants_desc = False
    else:
        wants_desc = bool(
            re.search(r"\b(?:highest|largest|greatest|latest)\b", q, flags=re.I)
        )
        if re.search(r"\b(?:lowest|smallest|least|earliest)\b", q, flags=re.I):
            wants_desc = False
    rank_dir = "DESC" if wants_desc else "ASC"

    where_block = f"\n{parsed['where'].strip()}" if str(parsed.get("where") or "").strip() else ""
    # Drop cross-table IN/EXISTS filters for this single-table rank rewrite.
    if where_block and re.search(r"\b(?:IN|EXISTS)\s*\(\s*SELECT\b", where_block, flags=re.I):
        where_block = ""

    tail = str(parsed.get("tail") or "").strip()
    # Preserve ORDER BY/LIMIT tail after removing GROUP BY semantics.
    rebuilt_tail = ""
    if tail:
        rebuilt_tail = f"\n{tail}"

    fixed = (
        f"SELECT {', '.join(projected_dims)}, "
        f"RANK() OVER (PARTITION BY {partition_expr} ORDER BY {order_expr} {rank_dir}) AS `{rank_alias}`\n"
        f"FROM {from_core}"
        f"{where_block}"
        f"{rebuilt_tail}"
    ).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _rewrite_scalar_window_subquery_to_correlated_aggregate(sql: str) -> str:
    """
    Repair scalar same-table subqueries that return one aggregate per group.

    Two equivalent malformed shapes are handled:
    - SELECT AVG(x) OVER (PARTITION BY group_col) FROM same_table
    - SELECT AVG(x) FROM same_table GROUP BY group_col
    - SELECT AVG(x) FROM same_table WHERE group_col = same_table.group_col

    Both produce multiple rows as scalar subqueries.  The safe repair is a
    correlated aggregate constrained by the outer row's group key.
    """
    s = (sql or "").strip()
    if not s:
        return sql
    if "select" not in s.lower():
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql
    where_pos = _find_top_level_clause(s0, "where", from_pos + len("from"))
    if where_pos < 0:
        return sql
    group_pos = _find_top_level_clause(s0, "group by", where_pos + len("where"))
    if group_pos >= 0:
        return sql
    order_pos = _find_top_level_clause(s0, "order by", where_pos + len("where"))
    limit_pos = _find_top_level_clause(s0, "limit", where_pos + len("where"))

    from_end_candidates = [p for p in (where_pos, order_pos, limit_pos, len(s0)) if p >= 0]
    from_end = min(from_end_candidates)
    from_core = s0[from_pos + len("from"):from_end].strip()
    if not from_core or re.search(r"\bjoin\b", from_core, flags=re.I):
        return sql

    from_m = re.match(
        r"(?is)^`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?\s*$",
        from_core,
    )
    if not from_m:
        return sql
    outer_table = (from_m.group("table") or "").strip("`")
    outer_alias = (from_m.group("alias") or "").strip("`") or outer_table

    where_end_candidates = [p for p in (order_pos, limit_pos, len(s0)) if p > where_pos]
    where_end = min(where_end_candidates) if where_end_candidates else len(s0)
    where_body = s0[where_pos + len("where"):where_end].strip()
    if not where_body:
        return sql

    grouped_cmp_pat = re.compile(
        r"""(?is)
        (?P<lhs>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*
        (?P<op>>=|<=|=|>|<)\s*
        \(\s*SELECT\s+
        (?P<agg>(?:AVG|SUM|MIN|MAX|COUNT))\s*\(\s*(?P<metric>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)\s*
        FROM\s+\(?\s*`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<sub_alias>[A-Za-z_][A-Za-z0-9_]*))?\s*\)?\s*
        (?:WHERE\s+.+?\s+)?
        GROUP\s+BY\s+(?P<partition>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*
        \)
        """,
        flags=re.X,
    )
    m = grouped_cmp_pat.search(where_body)
    if not m:
        cmp_pat = re.compile(
            r"""(?is)
            (?P<lhs>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*
            (?P<op>>=|<=|=|>|<)\s*
            \(\s*SELECT\s+
            (?P<agg>(?:AVG|SUM|MIN|MAX|COUNT))\s*\(\s*(?P<metric>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)\s*
            OVER\s*\(\s*PARTITION\s+BY\s+(?P<partition>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)\s*
            FROM\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<sub_alias>[A-Za-z_][A-Za-z0-9_]*))?
            \s*\)
            """,
            flags=re.X,
        )
        m = cmp_pat.search(where_body)
    if not m:
        # Ambiguous same-table scalar aggregate:
        #   ... WHERE lhs > (SELECT AVG(metric) FROM t WHERE k = t.k)
        # When the inner table is unaliased and matches the outer table name,
        # `t.k` binds to the inner scope in MySQL, collapsing the intended
        # correlation into a tautology. Rewrite by introducing a distinct inner
        # alias and wiring the equality explicitly to the outer row.
        ambiguous_pat = re.compile(
            r"""(?is)
            (?P<lhs>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*
            (?P<op>>=|<=|=|>|<)\s*
            \(\s*SELECT\s+
            (?P<agg>(?:AVG|SUM|MIN|MAX|COUNT))\s*\(\s*(?P<metric>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)\s*
            FROM\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?\s*
            WHERE\s+
            (?P<eq_left>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*=\s*
            (?P<eq_right>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*
            \)
            """,
            flags=re.X,
        )
        m_amb = ambiguous_pat.search(where_body)
        if not m_amb:
            return sql

        sub_table = (m_amb.group("table") or "").strip("`")
        if sub_table.lower() != outer_table.lower():
            return sql
        if outer_alias.lower() != outer_table.lower():
            return sql

        def _split_ref(expr: str) -> tuple[str, str]:
            raw = str(expr or "").strip().replace("`", "")
            if "." in raw:
                qual, col = raw.split(".", 1)
                return qual.strip(), col.strip()
            return "", raw.strip()

        left_qual, left_col = _split_ref(m_amb.group("eq_left") or "")
        right_qual, right_col = _split_ref(m_amb.group("eq_right") or "")
        if not left_col or not right_col or left_col.lower() != right_col.lower():
            return sql

        if left_qual.lower() == outer_table.lower() and not right_qual:
            inner_col = right_col
            outer_col = left_col
        elif right_qual.lower() == outer_table.lower() and not left_qual:
            inner_col = left_col
            outer_col = right_col
        else:
            return sql

        agg = (m_amb.group("agg") or "").upper()
        metric = (m_amb.group("metric") or "").strip()
        lhs = (m_amb.group("lhs") or "").strip()
        sub_alias_safe = "sq"
        metric_col = metric.split(".")[-1].strip("`")
        lhs_col = lhs.split(".")[-1].strip("`")
        lhs_expr = f"{outer_alias}.{lhs_col}" if "." not in lhs else lhs
        part_expr_outer = f"{outer_alias}.{outer_col}"
        replacement = (
            f"{lhs_expr} {m_amb.group('op').strip()} (SELECT {agg}({sub_alias_safe}.{metric_col}) "
            f"FROM {sub_table} AS {sub_alias_safe} "
            f"WHERE {sub_alias_safe}.{inner_col} = {part_expr_outer})"
        )
        where_fixed = where_body[: m_amb.start()] + replacement + where_body[m_amb.end() :]
    else:
        sub_table = (m.group("table") or "").strip("`")
        if sub_table.lower() != outer_table.lower():
            return sql

        agg = (m.group("agg") or "").upper()
        metric = (m.group("metric") or "").strip()
        partition = (m.group("partition") or "").strip()
        lhs = (m.group("lhs") or "").strip()
        op = (m.group("op") or "").strip()
        sub_alias = (m.group("sub_alias") or "").strip() or "sq"
        sub_alias_safe = re.sub(r"[^A-Za-z0-9_]", "", sub_alias) or "sq"
        if not re.match(r"[A-Za-z_]", sub_alias_safe):
            sub_alias_safe = f"sq_{sub_alias_safe}"
        if sub_alias_safe.lower() == outer_alias.lower():
            sub_alias_safe = "sq"

        metric_col = metric.split(".")[-1].strip("`")
        part_col = partition.split(".")[-1].strip("`")
        lhs_col = lhs.split(".")[-1].strip("`")
        lhs_expr = f"{outer_alias}.{lhs_col}" if "." not in lhs else lhs
        part_expr_outer = f"{outer_alias}.{part_col}"

        replacement = (
            f"{lhs_expr} {op} (SELECT {agg}({sub_alias_safe}.{metric_col}) "
            f"FROM {sub_table} AS {sub_alias_safe} "
            f"WHERE {sub_alias_safe}.{part_col} = {part_expr_outer})"
        )
        where_fixed = where_body[: m.start()] + replacement + where_body[m.end() :]

    head = s0[:where_pos].rstrip()
    tail = s0[where_end:].strip()
    fixed = f"{head} WHERE {where_fixed}"
    if tail:
        fixed += f" {tail}"
    if trailing and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _ast_normalize_scalar_subquery(sql: str) -> Tuple[str, Dict[str, Any]]:
    """
    AST-first normalization for simple same-table scalar aggregate subqueries.

    Scope for this batch:
    - top-level WHERE comparisons against a scalar subquery
    - same outer/inner base table only
    - grouped aggregate subquery with one grouping key
    - window aggregate subquery with one PARTITION BY key
    - ambiguous same-table self-correlation where the inner alias shadows the
      outer table name and collapses intended correlation

    Out of scope for this batch:
    - multi-table subqueries
    - nested subquery trees
    - latest-year / extrema-date subqueries
    - winner-row / top-N shapes
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
    }
    s = str(sql or "").strip()
    if not s:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    sel = ast if isinstance(ast, exp.Select) else ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        meta["warnings"].append("unsupported_root")
        return sql, meta
    if any(True for _ in sel.find_all(exp.Join)):
        meta["warnings"].append("join_skipped")
        return sql, meta

    from_arg = sel.args.get("from") or sel.args.get("from_")
    if from_arg is None:
        meta["warnings"].append("missing_from")
        return sql, meta

    outer_tables = [t for t in from_arg.find_all(exp.Table)]
    if len(outer_tables) != 1:
        meta["warnings"].append("outer_single_table_only")
        return sql, meta

    outer_table = outer_tables[0]
    outer_table_name = str(outer_table.name or "").strip("`")
    outer_alias_name = str(outer_table.alias_or_name or outer_table_name).strip("`")
    if not outer_table_name or not outer_alias_name:
        meta["warnings"].append("missing_outer_table")
        return sql, meta

    where = sel.args.get("where")
    if where is None:
        return sql, meta

    cmp_types = tuple(
        cls for cls in (
            getattr(exp, "EQ", None),
            getattr(exp, "GT", None),
            getattr(exp, "GTE", None),
            getattr(exp, "LT", None),
            getattr(exp, "LTE", None),
        )
        if cls is not None
    )
    if not cmp_types:
        meta["warnings"].append("comparison_types_unavailable")
        return sql, meta

    def _column_name(node: Optional["exp.Expression"]) -> str:
        if not isinstance(node, exp.Column):
            return ""
        return str(node.name or "").strip("`")

    def _single_inner_table(inner_sel: "exp.Select") -> Optional["exp.Table"]:
        inner_from = inner_sel.args.get("from") or inner_sel.args.get("from_")
        if inner_from is None:
            return None
        tables = [t for t in inner_from.find_all(exp.Table)]
        if len(tables) != 1:
            return None
        if any(True for _ in inner_sel.find_all(exp.Join)):
            return None
        return tables[0]

    def _expr_sql(node: Optional["exp.Expression"]) -> str:
        if not isinstance(node, exp.Expression):
            return ""
        try:
            return node.sql(dialect=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            return ""

    def _safe_inner_alias() -> str:
        alias = "sq"
        if alias.lower() == outer_alias_name.lower():
            alias = "sq_inner"
        return alias

    def _parse_select_expr(inner_sel: "exp.Select") -> Tuple[Optional[str], Optional[str], str, str]:
        exprs = list(inner_sel.expressions or [])
        if len(exprs) != 1:
            return None, None, "", ""
        item = exprs[0]
        base = item.this if isinstance(item, exp.Alias) else item
        alias_name = str(item.alias or "").strip("`") if isinstance(item, exp.Alias) else ""

        if isinstance(base, exp.AggFunc):
            metric = getattr(base, "this", None)
            metric_col = _column_name(metric)
            agg_name = str(getattr(base, "key", "") or base.__class__.__name__).replace("Func", "").upper()
            return agg_name, metric_col, "", alias_name

        if isinstance(base, exp.Window) and isinstance(getattr(base, "this", None), exp.AggFunc):
            win_agg = base.this
            metric = getattr(win_agg, "this", None)
            metric_col = _column_name(metric)
            agg_name = str(getattr(win_agg, "key", "") or win_agg.__class__.__name__).replace("Func", "").upper()
            raw_part = base.args.get("partition_by")
            if raw_part is None:
                raw_part = base.args.get("partition")
            part_exprs: List["exp.Expression"] = []
            if isinstance(raw_part, list):
                part_exprs = [x for x in raw_part if isinstance(x, exp.Expression)]
            elif isinstance(raw_part, exp.Partition):
                part_exprs = [x for x in (raw_part.expressions or []) if isinstance(x, exp.Expression)]
            elif isinstance(raw_part, exp.Expression):
                expr_list = getattr(raw_part, "expressions", None)
                if isinstance(expr_list, list) and expr_list:
                    part_exprs = [x for x in expr_list if isinstance(x, exp.Expression)]
                else:
                    part_exprs = [raw_part]
            partition_col = _column_name(part_exprs[0]) if len(part_exprs) == 1 else ""
            if base.args.get("order") is not None or base.args.get("spec") is not None:
                return agg_name, metric_col, "", alias_name
            return agg_name, metric_col, partition_col, alias_name

        return None, None, "", alias_name

    def _replace_subquery(comp: "exp.Expression", sub_sql: str, fix_name: str) -> bool:
        try:
            new_inner = sqlglot.parse_one(sub_sql, read=SQL_PARSE_DIALECT or "mysql")
            new_outer = sqlglot.parse_one(
                re.sub(r";+\s*$", "", ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")).strip(),
                read=SQL_PARSE_DIALECT or "mysql",
            )
        except Exception:
            meta["warnings"].append(f"{fix_name}_parse_rejected")
            return False

        target_outer_sel = new_outer if isinstance(new_outer, exp.Select) else new_outer.find(exp.Select)
        if not isinstance(target_outer_sel, exp.Select):
            meta["warnings"].append(f"{fix_name}_unsupported_root")
            return False

        where_new = target_outer_sel.args.get("where")
        if where_new is None:
            meta["warnings"].append(f"{fix_name}_missing_where")
            return False

        new_comparisons = [node for node in where_new.find_all(cmp_types)]
        old_comparisons = [node for node in where.find_all(cmp_types)]
        if len(new_comparisons) != len(old_comparisons):
            meta["warnings"].append(f"{fix_name}_comparison_mismatch")
            return False

        idx = old_comparisons.index(comp)
        target_comp = new_comparisons[idx]
        target_comp.set("expression", exp.Subquery(this=new_inner))
        rendered = new_outer.sql(dialect=SQL_PARSE_DIALECT or "mysql")
        if s.endswith(";"):
            rendered = rendered.rstrip(";") + ";"
        try:
            sqlglot.parse_one(re.sub(r";+\s*$", "", rendered).strip(), read=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            meta["warnings"].append(f"{fix_name}_render_parse_failed")
            return False
        meta["fixes"].append(fix_name)
        meta["rendered_sql"] = rendered
        return True

    def _validate_candidate(candidate_sql: str) -> Optional[str]:
        candidate = str(candidate_sql or "").strip()
        if not candidate:
            return None
        trailing = ";" if s.endswith(";") or candidate.endswith(";") else ""
        candidate_parse = re.sub(r";+\s*$", "", candidate).strip()
        try:
            sqlglot.parse_one(candidate_parse, read=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            return None
        if trailing and not candidate_parse.endswith(";"):
            return candidate_parse + trailing
        return candidate if candidate.endswith(";") or not trailing else candidate + trailing

    def _apply_text_fix(current_sql: str, fixer, fix_name: str) -> Optional[str]:
        try:
            candidate = fixer(current_sql)
        except TypeError:
            return None
        except Exception:
            return None
        if not candidate or candidate == current_sql:
            return None
        validated = _validate_candidate(candidate)
        if not validated:
            meta["warnings"].append(f"{fix_name}_parse_rejected")
            return None
        meta["fixes"].append(fix_name)
        return validated

    comparisons = [node for node in where.find_all(cmp_types)]
    for comp in comparisons:
        rhs = getattr(comp, "expression", None)
        if not isinstance(rhs, exp.Subquery):
            continue
        inner_sel = rhs.this if isinstance(rhs.this, exp.Select) else rhs.find(exp.Select)
        if not isinstance(inner_sel, exp.Select):
            continue
        if any(True for _ in inner_sel.find_all(exp.Subquery)):
            meta["warnings"].append("nested_subquery_skipped")
            continue

        inner_table = _single_inner_table(inner_sel)
        if inner_table is None:
            continue
        inner_table_name = str(inner_table.name or "").strip("`")
        inner_alias_name = str(inner_table.alias_or_name or inner_table_name).strip("`")
        if not inner_table_name or inner_table_name.lower() != outer_table_name.lower():
            continue

        meta["handled_scope"] = True
        agg_name, metric_col, partition_col, _alias_name = _parse_select_expr(inner_sel)
        if not agg_name or not metric_col:
            meta["warnings"].append("unsupported_scalar_projection")
            continue

        inner_where = inner_sel.args.get("where")
        inner_group = inner_sel.args.get("group")
        has_group = isinstance(inner_group, exp.Group) and bool(inner_group.expressions or [])
        has_window = any(True for _ in inner_sel.find_all(exp.Window))

        # Case 1: grouped same-table scalar aggregate subquery.
        if has_group and not has_window:
            group_exprs = list(inner_group.expressions or [])
            if len(group_exprs) != 1 or inner_where is not None:
                if inner_where is not None:
                    meta["warnings"].append("grouped_inner_where_skipped")
                continue
            group_col = _column_name(group_exprs[0])
            if not group_col:
                continue
            inner_alias_safe = _safe_inner_alias()
            sub_sql = (
                f"SELECT {agg_name}({inner_alias_safe}.{metric_col}) "
                f"FROM {inner_table_name} AS {inner_alias_safe} "
                f"WHERE {inner_alias_safe}.{group_col} = {outer_alias_name}.{group_col}"
            )
            if _replace_subquery(comp, sub_sql, "grouped_scalar_subquery_to_correlated_aggregate_ast"):
                break
            continue

        # Case 2: window aggregate same-table scalar subquery.
        if has_window and partition_col:
            if inner_where is not None:
                meta["warnings"].append("window_inner_where_skipped")
                continue
            inner_alias_safe = _safe_inner_alias()
            sub_sql = (
                f"SELECT {agg_name}({inner_alias_safe}.{metric_col}) "
                f"FROM {inner_table_name} AS {inner_alias_safe} "
                f"WHERE {inner_alias_safe}.{partition_col} = {outer_alias_name}.{partition_col}"
            )
            if _replace_subquery(comp, sub_sql, "window_scalar_subquery_to_correlated_aggregate_ast"):
                break
            continue

        # Case 3: ambiguous same-table self-correlation without distinct inner alias.
        if has_group or has_window or inner_where is None:
            continue
        if outer_alias_name.lower() != outer_table_name.lower():
            meta["warnings"].append("ambiguous_outer_alias_skipped")
            continue

        inner_cmp = inner_where.this if isinstance(inner_where, exp.Where) else inner_where
        if not isinstance(inner_cmp, getattr(exp, "EQ", ())):
            continue
        left = getattr(inner_cmp, "this", None)
        right = getattr(inner_cmp, "expression", None)
        if not isinstance(left, exp.Column) or not isinstance(right, exp.Column):
            continue
        left_col = _column_name(left)
        right_col = _column_name(right)
        if not left_col or left_col.lower() != right_col.lower():
            continue

        left_table = str(left.table or "").strip("`")
        right_table = str(right.table or "").strip("`")
        if left_table.lower() == outer_table_name.lower() and not right_table:
            inner_col = right_col
            outer_col = left_col
        elif right_table.lower() == outer_table_name.lower() and not left_table:
            inner_col = left_col
            outer_col = right_col
        else:
            continue

        inner_alias_safe = _safe_inner_alias()
        sub_sql = (
            f"SELECT {agg_name}({inner_alias_safe}.{metric_col}) "
            f"FROM {inner_table_name} AS {inner_alias_safe} "
            f"WHERE {inner_alias_safe}.{inner_col} = {outer_alias_name}.{outer_col}"
        )
        if _replace_subquery(comp, sub_sql, "ambiguous_scalar_subquery_to_correlated_aggregate_ast"):
            break

    rendered_sql = str(meta.pop("rendered_sql", "") or "")
    if not rendered_sql and meta.get("handled_scope") and not meta.get("fixes"):
        fallback_sql = _apply_text_fix(
            s,
            _rewrite_scalar_window_subquery_to_correlated_aggregate,
            "scalar_window_subquery_to_correlated_aggregate_ast",
        )
        if fallback_sql:
            rendered_sql = fallback_sql
    meta["warnings"] = list(dict.fromkeys(meta["warnings"]))
    if rendered_sql and meta.get("fixes"):
        return rendered_sql, meta
    return sql, meta


def _ast_normalize_ranked_selection(sql: str, question: str, ctx: str = "") -> Tuple[str, Dict[str, Any]]:
    """
    AST-first normalization for winner-row / top-N ranked selection shapes.

    Scope for this batch:
    - parseable queries that already project ROW_NUMBER/RANK/DENSE_RANK and
      filter on that rank in the same SELECT block
    - parseable grouped winner-row near-misses that should be wrapped into a
      ranked outer selection
    - parseable same-table malformed winner-row near-misses that can be
      rewritten into canonical ROW_NUMBER winner-row selection
    - parseable include-zero / multi-table winner-row near-misses that already
      contain a child-ranked LEFT JOIN subquery and should rank at the
      preserved parent grain instead

    Out of scope for this batch:
    - arbitrary multi-stage winner-row planning from scratch
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
    }
    s = str(sql or "").strip()
    if not s:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    sel = ast if isinstance(ast, exp.Select) else ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        meta["warnings"].append("unsupported_root")
        return sql, meta

    rank_func_types = tuple(
        cls for cls in (
            getattr(exp, "RowNumber", None),
            getattr(exp, "Rank", None),
            getattr(exp, "DenseRank", None),
        )
        if cls is not None
    )
    cmp_types = tuple(
        cls for cls in (
            getattr(exp, "EQ", None),
            getattr(exp, "GT", None),
            getattr(exp, "GTE", None),
            getattr(exp, "LT", None),
            getattr(exp, "LTE", None),
        )
        if cls is not None
    )

    def _validate_candidate(candidate_sql: str, fix_name: str) -> Optional[str]:
        candidate = str(candidate_sql or "").strip()
        if not candidate or candidate == s:
            return None
        candidate_parse = re.sub(r";+\s*$", "", candidate).strip()
        try:
            sqlglot.parse_one(candidate_parse, read=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            meta["warnings"].append(f"{fix_name}_parse_rejected")
            return None
        if s.endswith(";") and not candidate.endswith(";"):
            candidate = candidate_parse + ";"
        return candidate

    def _flatten_and(node: Optional["exp.Expression"]) -> List["exp.Expression"]:
        if node is None:
            return []
        if isinstance(node, exp.And):
            return _flatten_and(node.this) + _flatten_and(node.expression)
        return [node]

    def _rank_aliases(select_exprs: List["exp.Expression"]) -> Set[str]:
        aliases: Set[str] = set()
        for idx, item in enumerate(select_exprs or []):
            base = item.this if isinstance(item, exp.Alias) else item
            found = base if isinstance(base, exp.Window) else base.find(exp.Window)
            if not isinstance(found, exp.Window):
                continue
            win_func = getattr(found, "this", None)
            if not rank_func_types or not isinstance(win_func, rank_func_types):
                continue
            alias_name = ""
            if isinstance(item, exp.Alias):
                alias_name = str(item.alias or "").strip("`")
            elif isinstance(base, exp.Column):
                alias_name = str(base.name or "").strip("`")
            else:
                alias_name = f"rank_col_{idx + 1}"
            if alias_name:
                aliases.add(alias_name.lower())
        return aliases

    def _has_same_level_rank_filter(clause: Optional["exp.Expression"], rank_aliases: Set[str]) -> bool:
        if clause is None or not rank_aliases or not cmp_types:
            return False
        for pred in _flatten_and(clause.this if isinstance(clause, (exp.Where, exp.Having)) else clause):
            if not isinstance(pred, cmp_types):
                continue
            left = getattr(pred, "this", None)
            right = getattr(pred, "expression", None)
            left_alias = str(left.name or "").strip("`").lower() if isinstance(left, exp.Column) and not left.table else ""
            right_alias = str(right.name or "").strip("`").lower() if isinstance(right, exp.Column) and not right.table else ""
            left_lit = isinstance(left, exp.Literal) and bool(re.match(r"^\d+$", str(left.this or "")))
            right_lit = isinstance(right, exp.Literal) and bool(re.match(r"^\d+$", str(right.this or "")))
            if left_alias in rank_aliases and right_lit:
                return True
            if right_alias in rank_aliases and left_lit:
                return True
        return False

    rank_alias_names = _rank_aliases(list(sel.expressions or []))
    has_group = bool(getattr(sel.args.get("group"), "expressions", None))
    has_order = sel.args.get("order") is not None
    top_level_joins = bool(sel.args.get("joins"))
    from_arg = sel.args.get("from") or sel.args.get("from_")
    outer_tables = [t for t in from_arg.find_all(exp.Table)] if from_arg is not None else []

    same_level_rank_filter = _has_same_level_rank_filter(sel.args.get("where"), rank_alias_names) or _has_same_level_rank_filter(sel.args.get("having"), rank_alias_names)
    if rank_alias_names and same_level_rank_filter:
        meta["handled_scope"] = True
        candidate = _wrap_same_level_window_rank_filter(s, question, ctx)
        validated = _validate_candidate(candidate, "same_level_rank_filter_wrap_ast")
        if validated:
            meta["fixes"].append("same_level_rank_filter_wrap_ast")
            return validated, meta
        return sql, meta

    include_zero_ranked_near_miss = bool(
        _question_wants_winner_row(question)
        and _question_wants_include_zero(question, ctx)
        and re.search(r"\bROW_NUMBER\s*\(", s, flags=re.I)
        and (
            top_level_joins
            or re.search(r"\bLEFT\s+JOIN\b", s, flags=re.I)
            or re.search(
                r"(?is)\bJOIN\s*\(\s*SELECT\b[\s\S]{0,1200}\bROW_NUMBER\s*\(",
                s,
            )
        )
    )

    if include_zero_ranked_near_miss:
        meta["handled_scope"] = True
        candidate = _rewrite_joined_ranked_subquery_to_outer_winner(s, question, ctx)
        validated = _validate_candidate(candidate, "joined_ranked_subquery_outer_winner_ast")
        if validated:
            meta["fixes"].append("joined_ranked_subquery_outer_winner_ast")

        if not validated:
            candidate = s
            candidate_fixes: List[str] = []

            if re.search(r"\b(MAX|MIN)\s*\(", candidate, flags=re.I):
                next_candidate = _rewrite_winner_row_aggregate_misuse(candidate, question, ctx)
                if str(next_candidate or "").strip() != str(candidate or "").strip():
                    candidate = next_candidate
                    candidate_fixes.append("joined_ranked_aggregate_misuse_ast")

            next_candidate = _rewrite_winner_row_guardrail(candidate, question)
            if str(next_candidate or "").strip() != str(candidate or "").strip():
                candidate = next_candidate
                candidate_fixes.append("include_zero_winner_row_guardrail_ast")

            next_candidate = _rewrite_include_zero_winner_row_identifier_source(candidate, question, ctx)
            if str(next_candidate or "").strip() != str(candidate or "").strip():
                candidate = next_candidate
                candidate_fixes.append("include_zero_identifier_source_ast")

            next_candidate = _drop_tuple_in_filter_from_include_zero_ranked_winner(candidate, question, ctx)
            if str(next_candidate or "").strip() != str(candidate or "").strip():
                candidate = next_candidate
                candidate_fixes.append("include_zero_ranked_tuple_drop_ast")

            next_candidate = _fix_winner_row_window_order_priority(candidate, question)
            if str(next_candidate or "").strip() != str(candidate or "").strip():
                candidate = next_candidate
                candidate_fixes.append("winner_row_rank_order_normalized_ast")

            next_candidate = _fix_winner_row_metric_order_priority(candidate, question)
            if str(next_candidate or "").strip() != str(candidate or "").strip():
                candidate = next_candidate
                if "winner_row_rank_order_normalized_ast" not in candidate_fixes:
                    candidate_fixes.append("winner_row_rank_order_normalized_ast")

            validated = _validate_candidate(candidate, "include_zero_ranked_repair_sequence_ast")
            if validated:
                meta["fixes"].extend(candidate_fixes)
        if validated:
            normalized = _rewrite_include_zero_winner_row_identifier_source(validated, question, ctx)
            final_sql = _validate_candidate(normalized, "include_zero_identifier_source_ast") or validated
            if final_sql != validated:
                if "include_zero_identifier_source_ast" not in meta["fixes"]:
                    meta["fixes"].append("include_zero_identifier_source_ast")

            normalized_2 = _drop_tuple_in_filter_from_include_zero_ranked_winner(final_sql, question, ctx)
            final_sql_2 = _validate_candidate(normalized_2, "include_zero_ranked_tuple_drop_ast") or final_sql
            if final_sql_2 != final_sql:
                if "include_zero_ranked_tuple_drop_ast" not in meta["fixes"]:
                    meta["fixes"].append("include_zero_ranked_tuple_drop_ast")

            return final_sql_2, meta
        return sql, meta

    if (
        _question_wants_winner_row(question)
        and not top_level_joins
        and len(outer_tables) == 1
        and not rank_alias_names
        and re.search(r"\b(MAX|MIN)\s*\(", s, flags=re.I)
    ):
        meta["handled_scope"] = True
        candidate = _rewrite_winner_row_aggregate_misuse(s, question, ctx)
        validated = _validate_candidate(candidate, "winner_row_aggregate_misuse_ast")
        if not validated:
            candidate = _rewrite_single_table_tuple_in_winner_row(s, question)
            validated = _validate_candidate(candidate, "single_table_tuple_winner_row_ast")
            if validated:
                meta["fixes"].append("single_table_tuple_winner_row_ast")
                normalized = _winner_row_final_sanity(validated, question)
                final_sql = _validate_candidate(normalized, "winner_row_final_sanity_ast") or validated
                if final_sql != validated:
                    meta["fixes"].append("winner_row_final_sanity_ast")
                return final_sql, meta
            return sql, meta

        meta["fixes"].append("winner_row_aggregate_misuse_ast")
        normalized = _winner_row_final_sanity(validated, question)
        final_sql = _validate_candidate(normalized, "winner_row_final_sanity_ast") or validated
        if final_sql != validated:
            meta["fixes"].append("winner_row_final_sanity_ast")
        return final_sql, meta

    if _question_wants_winner_row(question) and has_group and has_order and not rank_alias_names:
        meta["handled_scope"] = True
        candidate = _rewrite_grouped_winner_row_ranked_aggregate(s, question)
        validated = _validate_candidate(candidate, "grouped_winner_row_ranked_aggregate_ast")
        if not validated:
            return sql, meta
        normalized = _fix_winner_row_window_order_priority(validated, question)
        normalized = _fix_winner_row_metric_order_priority(normalized, question)
        normalized = _winner_row_final_sanity(normalized, question)
        final_sql = _validate_candidate(normalized, "grouped_winner_row_post_normalize_ast") or validated
        meta["fixes"].append("grouped_winner_row_ranked_aggregate_ast")
        if final_sql != validated:
            meta["fixes"].append("winner_row_rank_order_normalized_ast")
        return final_sql, meta

    if rank_alias_names:
        meta["handled_scope"] = True
    return sql, meta

def _drop_unrequested_fixed_year_filter_for_yearly_rollup(sql: str, question: str) -> str:
    """
    Drop hallucinated fixed YEAR(...) filters when the question asks a yearly
    breakdown but does not request a specific year or latest-year scope.
    """
    s = (sql or "").strip()
    q = (question or "").strip().lower()
    if not s or not q:
        return sql

    if re.search(r"\b(?:19|20)\d{2}\b", q):
        return sql
    if re.search(r"\b(?:latest|most\s+recent|newest|earliest|oldest)\b", q, flags=re.I):
        return sql
    if not re.search(r"\bby\b[^.]{0,40}\byear\b|\border\s+year\b|\bpayment\s+year\b", q, flags=re.I):
        return sql

    parsed = _parse_flat_groupby_clauses(s) or _parse_select_from_groupby(s)
    if not parsed:
        return sql
    group_text = str(parsed.get("groupby") or "")
    select_text = str(parsed.get("select") or "")
    if "year(" not in group_text.lower() or "year(" not in select_text.lower():
        return sql

    where_clause = str(parsed.get("where") or "").strip()
    if not where_clause:
        return sql
    where_body = re.sub(r"(?is)^\s*where\s+", "", where_clause).strip()
    year_between_same_pat = re.compile(
        r"(?is)^\s*YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?\s*\)\s*BETWEEN\s*(?P<y1>(?:19|20)\d{2})\s+AND\s+(?P<y2>(?:19|20)\d{2})\s*$"
    )
    if year_between_same_pat.match(where_body):
        m_between = year_between_same_pat.match(where_body)
        if m_between and str(m_between.group("y1") or "") == str(m_between.group("y2") or ""):
            out_lines = [
                f"SELECT {parsed['select'].strip()}",
                f"FROM {parsed['from_core'].strip()}",
                f"GROUP BY {parsed['groupby'].strip()}",
            ]
            having_clause = str(parsed.get("having") or "").strip()
            if having_clause:
                out_lines.append(having_clause)
            tail = str(parsed.get("tail") or "").strip()
            if tail:
                out_lines.append(tail)
            fixed = "\n".join(out_lines).strip()
            if s.endswith(";") and not fixed.endswith(";"):
                fixed += ";"
            return fixed
    conjuncts = [c.strip() for c in _split_top_level_and(where_body) if c.strip()]
    if not conjuncts:
        return sql

    year_cmp_pat = re.compile(
        r"(?is)^\s*YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?\s*\)\s*=\s*(?:19|20)\d{2}\s*$"
    )
    kept: List[str] = []
    for conjunct in conjuncts:
        if year_cmp_pat.match(conjunct):
            continue
        m_between = year_between_same_pat.match(conjunct)
        if m_between and str(m_between.group("y1") or "") == str(m_between.group("y2") or ""):
            continue
        kept.append(conjunct)
    if len(kept) == len(conjuncts):
        return sql

    out_lines = [
        f"SELECT {parsed['select'].strip()}",
        f"FROM {parsed['from_core'].strip()}",
    ]
    if kept:
        out_lines.append("WHERE " + " AND ".join(kept))
    out_lines.append(f"GROUP BY {parsed['groupby'].strip()}")
    having_clause = str(parsed.get("having") or "").strip()
    if having_clause:
        out_lines.append(having_clause)
    tail = str(parsed.get("tail") or "").strip()
    if tail:
        out_lines.append(tail)
    fixed = "\n".join(out_lines).strip()
    if s.endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _project_requested_comparison_count_from_having(
    sql: str,
    question: str,
    ctx: str = "",
) -> str:
    """
    Convert a misused HAVING conditional-count filter into a projected grouped
    metric when the question asks to return that comparison count rather than
    filter groups by it.
    """
    s = (sql or "").strip()
    q = str(question or "").strip().lower()
    if not s or not q:
        return sql
    if "group by" not in s.lower() or "having" not in s.lower():
        return sql
    if not re.search(r"\b(?:how\s+many|number\s+of|count)\b", q, flags=re.I):
        return sql
    if not re.search(r"\b(?:rows?|records?|entries|items)\b[^.]{0,80}\bhave\b", q, flags=re.I):
        return sql
    if not re.search(r"\b(?:earlier|before|later|after|greater\s+than|less\s+than|above|below)\b", q, flags=re.I):
        return sql
    if re.search(r"\b(?:at\s+least|at\s+most|more\s+than|less\s+than)\s+\d+\b", q, flags=re.I):
        return sql

    parsed = _parse_flat_groupby_clauses(s) or _parse_select_from_groupby(s)
    if not parsed:
        return sql

    having_clause = str(parsed.get("having") or "").strip()
    if not having_clause.lower().startswith("having "):
        return sql
    having_body = having_clause[7:].strip()
    if not having_body:
        return sql

    select_items = _split_top_level_commas(str(parsed.get("select") or "").strip())
    if not select_items:
        return sql

    cond_pat = re.compile(
        r"""(?is)^\s*
        (?P<expr>
            SUM\s*\(\s*CASE\s+WHEN\s+(?P<sum_cond>.+?)\s+THEN\s+1\s+ELSE\s+0\s+END\s*\)
            |
            COUNT\s*\(\s*CASE\s+WHEN\s+(?P<count_cond>.+?)\s+THEN\s+1(?:\s+ELSE\s+NULL)?\s+END\s*\)
        )
        \s*(?:>\s*0|>=\s*1)\s*$
        """,
        flags=re.X,
    )

    def _norm(text: str) -> str:
        return re.sub(r"[\s`]+", "", str(text or "").lower())

    existing_metric_norms: Set[str] = set()
    for item in select_items:
        expr, _alias = _split_select_expr_alias(item)
        expr_s = str(expr or "").strip()
        m = re.match(
            r"""(?is)^\s*
            (?:SUM\s*\(\s*CASE\s+WHEN\s+(?P<sum_cond>.+?)\s+THEN\s+1\s+ELSE\s+0\s+END\s*\)
            |COUNT\s*\(\s*CASE\s+WHEN\s+(?P<count_cond>.+?)\s+THEN\s+1(?:\s+ELSE\s+NULL)?\s+END\s*\))
            \s*$
            """,
            expr_s,
            flags=re.X,
        )
        if not m:
            continue
        cond = (m.group("sum_cond") or m.group("count_cond") or "").strip()
        if cond:
            existing_metric_norms.add(_norm(cond))

    kept_having: List[str] = []
    projected_exprs: List[str] = []
    removed = False
    alias_idx = 1
    existing_aliases = {
        str((_split_select_expr_alias(item)[1] or _extract_alias_or_colname(_split_select_expr_alias(item)[0]) or "")).strip("`").lower()
        for item in select_items
        if str(item or "").strip()
    }
    for cond in _split_top_level_and(having_body):
        cond_s = str(cond or "").strip()
        if not cond_s:
            continue
        m = cond_pat.match(cond_s)
        if not m:
            kept_having.append(cond_s)
            continue
        inner_cond = (m.group("sum_cond") or m.group("count_cond") or "").strip()
        if not inner_cond or _norm(inner_cond) in existing_metric_norms:
            kept_having.append(cond_s)
            continue
        alias = "comparison_count"
        while alias.lower() in existing_aliases:
            alias_idx += 1
            alias = f"comparison_count_{alias_idx}"
        existing_aliases.add(alias.lower())
        projected_exprs.append(f"SUM(CASE WHEN {inner_cond} THEN 1 ELSE 0 END) AS {alias}")
        existing_metric_norms.add(_norm(inner_cond))
        removed = True

    if not removed or not projected_exprs:
        return sql

    rebuilt_select = list(select_items) + projected_exprs
    out_lines = [
        "SELECT " + ", ".join(str(item or "").strip() for item in rebuilt_select if str(item or "").strip()),
        "FROM " + str(parsed.get("from_core") or "").strip(),
    ]
    if (parsed.get("where") or "").strip():
        out_lines.append(str(parsed["where"]).strip())
    out_lines.append("GROUP BY " + str(parsed.get("groupby") or "").strip())
    if kept_having:
        out_lines.append("HAVING " + " AND ".join(kept_having))
    if (parsed.get("tail") or "").strip():
        out_lines.append(str(parsed["tail"]).strip())
    fixed = "\n".join(out_lines).strip()
    if s.endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _repair_missing_fixed_year_filter_on_unique_temporal_alias(
    sql: str,
    question: str,
    ctx: str = "",
) -> str:
    """
    Add a missing fixed-year filter when the question clearly scopes the query
    to one explicit year and the joined query exposes exactly one plausible
    temporal alias for that scope.

    Conservative scope:
    - exactly one explicit year in the question,
    - no existing YEAR/date-literal filter already present,
    - no latest-year or multi-year intent,
    - only when a unique visible alias has a unique preferred temporal column.
    """
    s = str(sql or "").strip()
    q = str(question or "").strip().lower()
    if not s or not q:
        return sql

    if re.search(r"\b(?:latest|most\s+recent|newest|earliest|oldest)\b", q, flags=re.I):
        return sql

    year_tokens = [m.group(0) for m in re.finditer(r"\b(?:19|20)\d{2}\b", q)]
    ordered_years: List[str] = []
    seen_years: Set[str] = set()
    for token in year_tokens:
        if token in seen_years:
            continue
        seen_years.add(token)
        ordered_years.append(token)
    if len(ordered_years) != 1:
        return sql

    target_year = ordered_years[0]
    if not re.search(
        rf"\b(?:in|during|for|within|throughout)\s+{re.escape(target_year)}\b",
        q,
        flags=re.I,
    ):
        return sql

    if re.search(r"(?is)\bYEAR\s*\(", s) or re.search(r"'(?:19|20)\d{2}-\d{2}-\d{2}'", s):
        return sql

    parsed = _parse_select_from_groupby(s)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    if not from_core:
        return sql

    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}") or {}
    if not alias_map:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(t or "").strip().lower(): {
                    str(c or "").strip().lower()
                    for c in (cols or set())
                    if str(c or "").strip()
                }
                for t, cols in (allowed or {}).items()
                if str(t or "").strip()
            }
        except Exception:
            allowed_cols = {}

    def _table_cols(table_name: str) -> Set[str]:
        table_l = str(table_name or "").strip("`").lower()
        cols = set(allowed_cols.get(table_l, set()))
        if analyzer is not None and table_l:
            try:
                cols.update(
                    str(col or "").strip("`").lower()
                    for col in analyzer.get_table_columns(table_l)
                    if str(col or "").strip()
                )
            except Exception:
                pass
        return cols

    candidate_rows: List[Tuple[str, str, str]] = []
    seen_candidate_keys: Set[Tuple[str, str]] = set()
    for alias_name, table_name in alias_map.items():
        alias_l = str(alias_name or "").strip("`").lower()
        table_l = str(table_name or "").strip("`").lower()
        if not alias_l or not table_l:
            continue

        date_cols = {
            str(col or "").strip("`")
            for col in (get_filterable_date_columns(table_l) or [])
            if str(col or "").strip()
        }
        if not date_cols:
            cols = _table_cols(table_l)
            date_cols = {
                str(col or "").strip("`")
                for col in cols
                if any(token in str(col or "").lower() for token in ("date", "time", "timestamp"))
            }
        if not date_cols:
            continue

        preferred_col = _choose_preferred_temporal_column(
            table_l,
            sorted(date_cols),
            hint_columns=sorted(date_cols),
            question=question,
        )
        if not preferred_col:
            continue

        key = (alias_l, preferred_col.lower())
        if key in seen_candidate_keys:
            continue
        seen_candidate_keys.add(key)
        candidate_rows.append((alias_name, table_name, preferred_col))

    if len(candidate_rows) != 1:
        return sql

    alias_name, _table_name, date_col = candidate_rows[0]
    year_pred = f"YEAR({alias_name}.{date_col}) = {target_year}"

    out_lines = [
        f"SELECT {str(parsed.get('select') or '').strip()}",
        f"FROM {from_core}",
    ]
    where_clause = str(parsed.get("where") or "").strip()
    if where_clause:
        where_body = re.sub(r"(?is)^\s*where\s+", "", where_clause).strip()
        if where_body:
            out_lines.append(f"WHERE {where_body} AND {year_pred}")
        else:
            out_lines.append(f"WHERE {year_pred}")
    else:
        out_lines.append(f"WHERE {year_pred}")
    out_lines.append(f"GROUP BY {str(parsed.get('groupby') or '').strip()}")
    having_clause = str(parsed.get("having") or "").strip()
    if having_clause:
        if not having_clause.lower().startswith("having "):
            having_clause = f"HAVING {having_clause}"
        out_lines.append(having_clause)
    if str(parsed.get("tail") or "").strip():
        out_lines.append(str(parsed.get("tail") or "").strip())

    fixed = "\n".join(out_lines).strip()
    if s.endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_length_filter_for_prefix_grouping(sql: str, question: str) -> str:
    """
    Drop hallucinated row-level filters when the question asks to group by the
    first N characters of a value, not to restrict rows to one concrete prefix
    or exact string length.

    Conservative scope:
    - flat grouped query only
    - top-level AND-only WHERE
    - only removes simple exact-length predicates or prefix-literal filters on
      the same source column used by the derived prefix grouping
    - only when the question explicitly asks for first N characters/prefix
      grouping and does not ask for exact length filtering
    """
    s = (sql or "").strip()
    q = (question or "").strip().lower()
    if not s or not q:
        return sql

    if re.search(
        r"\b(?:length|char(?:acter)?\s+length)\b.*\b(?:equal|equals|exactly|same|at\s+least|at\s+most|greater|less|longer|shorter)\b"
        r"|\bexact(?:ly)?\s+\d+\s+(?:characters?|chars?|letters?|digits?)\b",
        q,
        flags=re.I,
    ):
        return sql

    m_prefix_group = re.search(
        r"\bfirst\s+(?P<num>\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\s+"
        r"(?:characters?|chars?|letters?|digits?)\s+of\s+(?P<target>.+?)"
        r"(?:(?:\s*,\s*|\s+)(?:return|show|list|find|give|include|keep|only|order|sort)\b|[.?!]|$)",
        q,
        flags=re.I,
    )
    if not m_prefix_group:
        return sql
    number_word_values = {
        "one": 1,
        "two": 2,
        "three": 3,
        "four": 4,
        "five": 5,
        "six": 6,
        "seven": 7,
        "eight": 8,
        "nine": 9,
        "ten": 10,
        "eleven": 11,
        "twelve": 12,
    }
    raw_requested_n = str(m_prefix_group.group("num") or "").strip().lower()
    requested_n = int(raw_requested_n) if raw_requested_n.isdigit() else number_word_values.get(raw_requested_n, 0)
    if requested_n <= 0:
        return sql
    target_span = str(m_prefix_group.group("target") or "").strip().lower()
    target_tokens = {
        tok for tok in re.findall(r"[a-z0-9]+", target_span)
        if tok
    }

    parsed = _parse_select_from_groupby(s) or _parse_flat_groupby_clauses(s)
    if not parsed:
        return sql

    where_clause = str(parsed.get("where") or "").strip()
    if not where_clause or not where_clause.lower().startswith("where "):
        return sql
    where_body = where_clause[6:].strip()
    if not where_body or _has_top_level_or(where_body):
        return sql

    group_items = _split_top_level_commas(parsed.get("groupby") or "")

    length_cmp_pat = re.compile(
        r"""(?is)^\s*(?:CHAR_LENGTH|CHARACTER_LENGTH|LENGTH)\s*\(\s*
            (?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*
            \)\s*(?P<op>=|>=|>)\s*(?P<num>\d+)\s*$""",
        flags=re.X,
    )
    simple_col_pat = re.compile(
        r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$"""
    )
    derived_prefix_col_pat = re.compile(
        r"""(?is)\b(?:LEFT|SUBSTRING|SUBSTR)\s*\(\s*
            (?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*
            ,\s*(?:1\s*,\s*)?(?P<num>\d+)\s*\)""",
        flags=re.X,
    )
    like_prefix_pat = re.compile(
        r"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+
            LIKE\s+(?P<lit>'[^']*'|"[^"]*")\s*$""",
        flags=re.X,
    )
    derived_prefix_eq_pat = re.compile(
        r"""(?is)^\s*(?:LEFT|SUBSTRING|SUBSTR)\s*\(\s*
            (?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*
            ,\s*(?:1\s*,\s*)?(?P<num>\d+)\s*\)\s*
            =\s*(?P<lit>'[^']*'|"[^"]*")\s*$""",
        flags=re.X,
    )

    def _col_name_raw(expr: str) -> str:
        m = simple_col_pat.match(str(expr or "").strip())
        if not m:
            return ""
        return (m.group(2) or "").strip()

    def _col_name(expr: str) -> str:
        return _col_name_raw(expr).lower()

    def _literal_text(token: str) -> str:
        raw = str(token or "").strip()
        if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {"'", '"'}:
            raw = raw[1:-1]
        return raw.strip().lower()

    def _literal_mentioned(token: str) -> bool:
        lit = _literal_text(token)
        if not lit:
            return False
        lit_pat = re.escape(lit).replace(r"\ ", r"\s+")
        return re.search(rf"\b{lit_pat}\b", q, flags=re.I) is not None

    def _question_targets_column(col_name: str) -> bool:
        phrase = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_name or ""))
        phrase = re.sub(r"[_\W]+", " ", phrase).strip().lower()
        if not phrase or not target_span:
            return False
        phrase_pat = re.escape(phrase).replace(r"\ ", r"\s+")
        if re.search(rf"\b{phrase_pat}\b", target_span, flags=re.I):
            return True
        col_tokens = [tok for tok in re.findall(r"[a-z0-9]+", phrase) if len(tok) >= 3]
        return bool(col_tokens) and set(col_tokens).issubset(target_tokens)

    prefix_group_cols: Set[str] = set()
    for item in group_items:
        for match in derived_prefix_col_pat.finditer(str(item or "")):
            col_l = _col_name(match.group("col") or "")
            if col_l:
                prefix_group_cols.add(col_l)

    conds = _split_top_level_and(where_body)
    if not conds:
        return sql

    keep_conds: List[str] = []
    removed_any = False
    for cond in conds:
        c0 = str(cond or "").strip()
        if not c0:
            continue
        m_len = length_cmp_pat.match(c0)
        if m_len:
            col_raw = _col_name_raw(m_len.group("col") or "")
            col_l = col_raw.lower()
            op = str(m_len.group("op") or "").strip()
            try:
                num = int(m_len.group("num") or "0")
            except Exception:
                num = -1
            is_common_prefix_length_shape = (
                (op == "=" and num == requested_n)
                or (op == ">=" and num == requested_n)
                or (op == ">" and num == requested_n - 1)
            )
            if is_common_prefix_length_shape and (
                col_l in prefix_group_cols or _question_targets_column(col_raw)
            ):
                removed_any = True
                continue

        m_like = like_prefix_pat.match(c0)
        if m_like:
            col_raw = _col_name_raw(m_like.group("col") or "")
            col_l = col_raw.lower()
            lit = m_like.group("lit") or ""
            lit_text = _literal_text(lit)
            is_prefix_literal = lit_text.endswith("%") and "%" not in lit_text[:-1] and "_" not in lit_text
            if (
                is_prefix_literal
                and (col_l in prefix_group_cols or _question_targets_column(col_raw))
                and not _literal_mentioned(lit_text[:-1])
            ):
                removed_any = True
                continue

        m_derived = derived_prefix_eq_pat.match(c0)
        if m_derived:
            col_raw = _col_name_raw(m_derived.group("col") or "")
            col_l = col_raw.lower()
            lit = m_derived.group("lit") or ""
            if (
                (col_l in prefix_group_cols or _question_targets_column(col_raw))
                and not _literal_mentioned(lit)
            ):
                removed_any = True
                continue

        keep_conds.append(c0)

    if not removed_any:
        return sql

    out_lines = [
        f"SELECT {parsed['select'].strip()}",
        f"FROM {parsed['from_core'].strip()}",
    ]
    if keep_conds:
        out_lines.append(f"WHERE {' AND '.join(keep_conds)}")
    out_lines.append(f"GROUP BY {parsed['groupby'].strip()}")
    if parsed.get("having"):
        out_lines.append(str(parsed["having"]).strip())
    if parsed.get("tail"):
        out_lines.append(str(parsed["tail"]).strip())

    fixed = "\n".join(out_lines).strip()
    if s.endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _rewrite_conditional_sum_value_to_count(sql: str, question: str) -> str:
    """
    Convert SUM(CASE WHEN condition THEN value ELSE 0 END) into a conditional
    count when the question asks "how many / number of / count" rows satisfy
    that condition. This preserves genuine conditional sums by requiring a
    count-like question and avoiding aliases that ask for totals/amounts/value.
    """
    s = (sql or "").strip()
    if not s or not question or "sum" not in s.lower() or "case" not in s.lower():
        return sql
    q = str(question or "").lower()
    if not re.search(r"\b(?:how\s+many|number\s+of|count)\b", q, flags=re.I):
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql

    select_items = _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip())
    if not select_items:
        return sql

    def _alias_blocks_count_rewrite(alias: Optional[str]) -> bool:
        a = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(alias or ""))
        a = a.replace("_", " ").lower()
        value_alias_terms = _configured_metric_terms(
            HELPERS_DUAL_FACT_GENERIC_METRIC_TERMS,
            HELPERS_ROLLUP_LEGACY_METRIC_TERMS,
        )
        value_alias_terms.update(
            term
            for term in HELPERS_METRIC_AGG_INTENT_TERMS
            if str(term or "").strip().lower() in {"sum", "total"}
        )
        value_alias_alt = _regex_alt_from_terms(value_alias_terms, r"$^")
        return bool(
            value_alias_alt != r"$^"
            and re.search(rf"\b{value_alias_alt}\b", a, flags=re.I)
        )

    changed = False
    rebuilt_items: List[str] = []
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        if _alias_blocks_count_rewrite(alias):
            rebuilt_items.append(item.strip())
            continue
        m = re.match(
            r"""(?is)^\s*SUM\s*\(\s*CASE\s+WHEN\s+(?P<cond>.+?)\s+
                THEN\s+(?P<then>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+
                ELSE\s+0\s+END\s*\)\s*$""",
            expr,
            flags=re.X,
        )
        if not m:
            rebuilt_items.append(item.strip())
            continue
        cond = (m.group("cond") or "").strip()
        then_expr = (m.group("then") or "").strip()
        then_bare = then_expr.split(".")[-1].strip("`").lower()
        cond_l = cond.lower()
        if then_bare not in cond_l:
            rebuilt_items.append(item.strip())
            continue
        threshold_numbers = re.findall(r"\b\d+(?:\.\d+)?\b", cond)
        if threshold_numbers and not any(num in q for num in threshold_numbers):
            rebuilt_items.append(item.strip())
            continue
        new_expr = f"SUM(CASE WHEN {cond} THEN 1 ELSE 0 END)"
        rebuilt_items.append(f"{new_expr} AS {alias}" if alias else new_expr)
        changed = True

    if not changed:
        return sql
    return "SELECT " + ", ".join(rebuilt_items) + " " + s0[from_pos:].lstrip() + trailing


def _rewrite_conditional_avg_to_count_with_overall_avg(sql: str, question: str) -> str:
    """
    Repair a grouped near-miss where the SQL uses AVG(CASE WHEN cond THEN value
    ELSE NULL END) even though the question asks for:
    - how many rows satisfy the condition, and
    - the overall average of that same value.

    Conservative scope:
    - flat grouped SELECT
    - question has both count-like and average intent
    - exactly one conditional AVG(value) projection
    - no unconditional AVG(value) projection already present
    """
    s = (sql or "").strip()
    q = str(question or "").strip().lower()
    if not s or not q:
        return sql
    if "group by" not in s.lower():
        return sql
    if not re.search(r"\b(?:how\s+many|number\s+of|count)\b", q, flags=re.I):
        return sql
    if not re.search(r"\b(?:avg|average|mean)\b", q, flags=re.I):
        return sql

    parsed = _parse_flat_groupby_clauses(s) or _parse_select_from_groupby(s)
    if not parsed:
        return sql

    select_items = _split_top_level_commas(str(parsed.get("select") or "").strip())
    if not select_items:
        return sql

    conditional_avg_pattern = re.compile(
        r"""(?is)^\s*
        AVG\s*\(\s*CASE\s+WHEN\s+(?P<cond>.+?)\s+
        THEN\s+(?P<then>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<then_col>[A-Za-z_][A-Za-z0-9_]*)`?)\s+
        ELSE\s+NULL\s+END\s*\)\s*$
        """,
        flags=re.X,
    )
    plain_avg_pattern = re.compile(
        r"""(?is)^\s*AVG\s*\(\s*(?P<expr>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)\s*$"""
    )

    conditional_idx: Optional[int] = None
    conditional_cond = ""
    conditional_then = ""
    conditional_then_col = ""
    original_alias = ""
    existing_aliases: Set[str] = set()

    for idx, item in enumerate(select_items):
        expr, alias = _split_select_expr_alias(item)
        alias_name = str(alias or _extract_alias_or_colname(expr) or "").strip("`")
        if alias_name:
            existing_aliases.add(alias_name.lower())

        m_cond_avg = conditional_avg_pattern.match(str(expr or "").strip())
        if not m_cond_avg:
            continue
        if conditional_idx is not None:
            return sql
        conditional_idx = idx
        conditional_cond = (m_cond_avg.group("cond") or "").strip()
        conditional_then = (m_cond_avg.group("then") or "").strip()
        conditional_then_col = (m_cond_avg.group("then_col") or "").strip("`").lower()
        original_alias = alias_name

    if conditional_idx is None or not conditional_cond or not conditional_then:
        return sql

    threshold_numbers = re.findall(r"\b\d+(?:\.\d+)?\b", conditional_cond)
    if threshold_numbers and not all(num in q for num in threshold_numbers):
        return sql

    if conditional_then_col and conditional_then_col not in conditional_cond.lower():
        return sql

    for idx, item in enumerate(select_items):
        if idx == conditional_idx:
            continue
        expr, _alias = _split_select_expr_alias(item)
        m_plain_avg = plain_avg_pattern.match(str(expr or "").strip())
        if not m_plain_avg:
            continue
        plain_expr = (m_plain_avg.group("expr") or "").strip()
        if re.sub(r"[\s`]+", "", plain_expr).lower() == re.sub(r"[\s`]+", "", conditional_then).lower():
            return sql

    count_alias = "comparison_count"
    alias_idx = 1
    while count_alias.lower() in existing_aliases:
        alias_idx += 1
        count_alias = f"comparison_count_{alias_idx}"
    existing_aliases.add(count_alias.lower())

    avg_alias = original_alias or "average_value"
    if avg_alias.lower() == count_alias.lower():
        avg_alias = f"{avg_alias}_avg"
    while avg_alias.lower() in {count_alias.lower()}:
        alias_idx += 1
        avg_alias = f"average_value_{alias_idx}"

    rebuilt_items = list(select_items)
    rebuilt_items[conditional_idx] = f"SUM(CASE WHEN {conditional_cond} THEN 1 ELSE 0 END) AS {count_alias}"
    rebuilt_items.insert(conditional_idx + 1, f"AVG({conditional_then}) AS {avg_alias}")

    out_lines = [
        "SELECT " + ", ".join(str(item or "").strip() for item in rebuilt_items if str(item or "").strip()),
        "FROM " + str(parsed.get("from_core") or "").strip(),
    ]
    if (parsed.get("where") or "").strip():
        out_lines.append(str(parsed["where"]).strip())
    if (parsed.get("groupby") or "").strip():
        out_lines.append("GROUP BY " + str(parsed.get("groupby") or "").strip())
    if (parsed.get("having") or "").strip():
        out_lines.append(str(parsed["having"]).strip())
    if (parsed.get("tail") or "").strip():
        out_lines.append(str(parsed["tail"]).strip())

    fixed = "\n".join(out_lines).strip()
    if s.endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _rewrite_conditional_null_breakdown_metrics(
    sql: str,
    question: str,
    ctx: str = "",
) -> str:
    """
    Normalize grouped present/missing breakdown metrics for a single target
    column when the question explicitly asks for both sides.

    Example family:
      - "how many have comments filled in and how many have comments missing"

    Conservative scope:
    - grouped SELECT only
    - question clearly asks both present and missing counts
    - rewrites only CASE/count expressions whose aliases or conditions already
      look like the paired present/missing metrics for the same column
    """
    s = (sql or "").strip()
    q = str(question or "").strip().lower()
    if not s or not q:
        return sql
    if "group by" not in s.lower():
        return sql
    if not re.search(r"\b(?:filled(?:\s+in)?|present|non[-\s]?null|commented)\b", q, flags=re.I):
        return sql
    if not re.search(r"\b(?:missing|null|blank|empty)\b", q, flags=re.I):
        return sql

    has_count_shape = bool(
        re.search(
            r"\b(?:for\s+each|per|by|group|summari[sz]e|show|return|how\s+many|count)\b",
            q,
            flags=re.I,
        )
        and (
            re.search(
                r"\bhow\s+many\b.*\b(?:filled(?:\s+in)?|present|commented)\b.*\bhow\s+many\b.*\b(?:missing|null|blank|empty)\b",
                q,
                flags=re.I,
            )
            or re.search(
                r"\b(?:filled(?:\s+in)?|present|commented)\b.*\b(?:and|as\s+well\s+as)\b.*\b(?:missing|null|blank|empty)\b",
                q,
                flags=re.I,
            )
        )
    )
    if not has_count_shape:
        return sql

    parsed = _parse_select_from_groupby(s)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    if not from_core:
        return sql
    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}") or {}
    alias_to_table = {
        str(alias or "").strip("`").lower(): str(table or "").strip("`").lower()
        for alias, table in alias_map.items()
        if str(alias or "").strip() and str(table or "").strip()
    }
    table_names = list(dict.fromkeys(table_l for table_l in alias_to_table.values() if table_l))
    base_table = table_names[0] if len(table_names) == 1 else ""

    select_items = _split_top_level_commas(str(parsed.get("select") or "").strip())
    if not select_items:
        return sql

    def _expr_ref_norm(ref: str) -> str:
        return re.sub(r"[\s`]+", "", str(ref or "").lower())

    def _resolve_ref_table_col(ref: str) -> Tuple[str, str]:
        raw = str(ref or "").strip().replace("`", "")
        if not raw:
            return "", ""
        if "." in raw:
            alias, col = [part.strip() for part in raw.split(".", 1)]
            table_l = alias_to_table.get(alias.lower(), alias.lower())
            return table_l, col
        return base_table, raw

    def _is_string_like_ref(ref: str) -> bool:
        table_l, col = _resolve_ref_table_col(ref)
        if not table_l or not col:
            return True
        try:
            dtype = str(get_column_datatype(table_l, col) or "").upper()
        except Exception:
            dtype = ""
        if any(tok in dtype for tok in ("CHAR", "TEXT", "CLOB", "ENUM", "SET")):
            return True
        try:
            role = str(get_column_role(table_l, col) or "").strip().lower()
        except Exception:
            role = ""
        return role in {"text", "name", "description", "status"}

    simple_ref_pat = r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?"

    def _build_missing_pred(ref: str) -> str:
        if _is_string_like_ref(ref):
            return f"({ref} IS NULL OR {ref} = '')"
        return f"{ref} IS NULL"

    def _build_present_pred(ref: str) -> str:
        if _is_string_like_ref(ref):
            return f"({ref} IS NOT NULL AND {ref} <> '')"
        return f"{ref} IS NOT NULL"

    def _extract_case_ref(expr: str) -> Optional[str]:
        text = str(expr or "").strip()
        if not text:
            return None
        patterns = [
            rf"(?is)\bCASE\s+WHEN\s+(?P<ref>{simple_ref_pat})\s*=\s*''\s+THEN\s+0\s+ELSE\s+1\s+END\b",
            rf"(?is)\bCASE\s+WHEN\s+(?P<ref>{simple_ref_pat})\s+IS\s+NULL\s+THEN\s+0\s+ELSE\s+1\s+END\b",
            rf"(?is)\bCASE\s+WHEN\s+(?P<ref>{simple_ref_pat})\s+IS\s+NOT\s+NULL\s+THEN\s+1\s+ELSE\s+0\s+END\b",
            rf"(?is)\bCASE\s+WHEN\s+(?P<ref>{simple_ref_pat})\s*=\s*''\s+THEN\s+1\s+ELSE\s+0\s+END\b",
            rf"(?is)\bCASE\s+WHEN\s+(?P<ref>{simple_ref_pat})\s+IS\s+NULL\s+THEN\s+1\s+ELSE\s+0\s+END\b",
            rf"(?is)\bCASE\s+WHEN\s+\(?\s*(?P<ref1>{simple_ref_pat})\s+IS\s+NULL\s*\)?\s+OR\s+\(?\s*(?P<ref2>{simple_ref_pat})\s*=\s*''\s*\)?\s+THEN\s+1\s+ELSE\s+0\s+END\b",
            rf"(?is)\bCASE\s+WHEN\s+\(?\s*(?P<ref1>{simple_ref_pat})\s+IS\s+NOT\s+NULL\s*\)?\s+AND\s+\(?\s*(?P<ref2>{simple_ref_pat})\s*<>\s*''\s*\)?\s+THEN\s+1\s+ELSE\s+0\s+END\b",
        ]
        for pat in patterns:
            m = re.search(pat, text, flags=re.I)
            if not m:
                continue
            ref = (m.groupdict().get("ref") or m.groupdict().get("ref1") or "").strip()
            ref2 = (m.groupdict().get("ref2") or "").strip()
            if ref and ref2 and _expr_ref_norm(ref) != _expr_ref_norm(ref2):
                continue
            if ref:
                return ref
        return None

    def _alias_text(item_alias: Optional[str], expr: str) -> str:
        alias_text = str(item_alias or "").strip("`")
        if alias_text:
            return re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", alias_text).replace("_", " ").lower()
        return str(expr or "").lower()

    def _looks_present_metric(alias_text: str, expr: str) -> bool:
        text = f"{alias_text} {expr}".lower()
        if re.search(r"\b(?:missing|null|blank|empty)\b", alias_text, flags=re.I):
            return False
        return bool(re.search(r"\b(?:filled(?:\s+in)?|present|non[-\s]?null|commented)\b", text, flags=re.I))

    def _looks_missing_metric(alias_text: str, expr: str) -> bool:
        text = f"{alias_text} {expr}".lower()
        return bool(re.search(r"\b(?:missing|null|blank|empty)\b", text, flags=re.I))

    def _simple_count_total_aliases() -> Set[str]:
        totals: Set[str] = set()
        for item in select_items:
            expr, alias = _split_select_expr_alias(item)
            if re.match(r"(?is)^\s*COUNT\s*\(", str(expr or "").strip()):
                alias_name = str(alias or _extract_alias_or_colname(expr) or "").strip("`")
                if alias_name:
                    totals.add(alias_name.lower())
        return totals

    ref_candidates: Dict[str, int] = {}
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        ref = _extract_case_ref(expr)
        if not ref:
            continue
        alias_text = _alias_text(alias, expr)
        weight = 2 if (_looks_present_metric(alias_text, expr) or _looks_missing_metric(alias_text, expr)) else 1
        key = _expr_ref_norm(ref)
        ref_candidates[key] = ref_candidates.get(key, 0) + weight
    if not ref_candidates:
        return sql

    target_ref_norm = max(ref_candidates.items(), key=lambda item: item[1])[0]
    target_ref = ""
    for item in select_items:
        expr, _alias = _split_select_expr_alias(item)
        ref = _extract_case_ref(expr)
        if ref and _expr_ref_norm(ref) == target_ref_norm:
            target_ref = ref
            break
    if not target_ref:
        return sql

    total_aliases = _simple_count_total_aliases()
    present_expr = f"SUM(CASE WHEN {_build_present_pred(target_ref)} THEN 1 ELSE 0 END)"
    missing_expr = f"SUM(CASE WHEN {_build_missing_pred(target_ref)} THEN 1 ELSE 0 END)"

    changed = False
    rebuilt_items: List[str] = []
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        expr_s = str(expr or "").strip()
        alias_s = str(alias or "").strip()
        alias_text = _alias_text(alias, expr_s)

        if _expr_ref_norm(_extract_case_ref(expr_s) or "") == target_ref_norm:
            if _looks_present_metric(alias_text, expr_s):
                rebuilt_items.append(f"{present_expr} AS {alias_s}" if alias_s else present_expr)
                changed = True
                continue
            if _looks_missing_metric(alias_text, expr_s):
                rebuilt_items.append(f"{missing_expr} AS {alias_s}" if alias_s else missing_expr)
                changed = True
                continue

        if alias_s and alias_s.strip("`").lower() in total_aliases:
            rebuilt_items.append(item.strip())
            continue

        if _looks_missing_metric(alias_text, expr_s) and re.search(r"\bCOUNT\s*\(\s*\*\s*\)\s*-\s*", expr_s, flags=re.I):
            rebuilt_items.append(f"{missing_expr} AS {alias_s}" if alias_s else missing_expr)
            changed = True
            continue

        rebuilt_items.append(item.strip())

    if not changed:
        return sql

    out_lines = [
        "SELECT " + ", ".join(rebuilt_items),
        "FROM " + from_core,
    ]
    if (parsed.get("where") or "").strip():
        out_lines.append(str(parsed["where"]).strip())
    out_lines.append("GROUP BY " + str(parsed.get("groupby") or "").strip())
    if (parsed.get("having") or "").strip():
        out_lines.append(str(parsed["having"]).strip())
    if (parsed.get("tail") or "").strip():
        out_lines.append(str(parsed["tail"]).strip())
    fixed = "\n".join(out_lines).strip()
    if s.endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _coalesce_zero_fill_conditional_sums(sql: str, question: str, ctx: str = "") -> str:
    """
    Make explicit zero-fill projection semantics for SUM metrics.

    When the question says missing/no bucket values should be treated as zero,
    bare SUM(...) expressions are semantically close but do not expose the
    requested NULL-to-zero contract. Wrap those totals, and any arithmetic or
    window ordering using them, in COALESCE(..., 0).
    """
    s = (sql or "").strip()
    if not s or not question or "sum" not in s.lower():
        return sql

    q = str(question or "")
    if not any(re.search(pat, q, flags=re.I) for pat in HELPERS_ZERO_FILL_OUTPUT_PATTERNS if pat):
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql

    select_part = s0[sel_pos + len("select"):from_pos].strip()
    select_items = _split_top_level_commas(select_part)
    if not select_items:
        return sql

    sum_case_pat = re.compile(
        r"""(?is)SUM\s*\(\s*CASE\s+WHEN\s+.+?\s+THEN\s+.+?\s+ELSE\s+0(?:\.0+)?\s+END\s*\)"""
    )
    simple_sum_pat = re.compile(
        r"""(?is)SUM\s*\(\s*(?!CASE\b).+?\)"""
    )

    def _already_coalesced(text: str, start: int) -> bool:
        prefix = text[:start]
        return bool(re.search(r"COALESCE\s*\(\s*$", prefix, flags=re.I))

    def _wrap_in_expr(expr: str) -> tuple[str, bool]:
        changed_inner = False

        def repl(match: re.Match[str]) -> str:
            nonlocal changed_inner
            if _already_coalesced(expr, match.start()):
                return match.group(0)
            changed_inner = True
            return f"COALESCE({match.group(0)}, 0)"

        out_expr = sum_case_pat.sub(repl, expr)
        out_expr = simple_sum_pat.sub(repl, out_expr)
        return out_expr, changed_inner

    rebuilt: List[str] = []
    changed = False
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        expr_stripped = (expr or "").strip()
        new_expr = expr_stripped
        item_changed = False

        if (
            (sum_case_pat.fullmatch(expr_stripped) or simple_sum_pat.fullmatch(expr_stripped))
            and not re.match(r"(?is)^\s*COALESCE\s*\(", expr_stripped)
        ):
            new_expr = f"COALESCE({expr_stripped}, 0)"
            item_changed = True
        elif sum_case_pat.search(expr_stripped) or simple_sum_pat.search(expr_stripped):
            new_expr, item_changed = _wrap_in_expr(expr_stripped)

        if item_changed:
            changed = True
            rebuilt.append(f"{new_expr} AS {alias}" if alias else new_expr)
        else:
            rebuilt.append(item.strip())

    if not changed:
        return sql

    return "SELECT " + ", ".join(rebuilt) + " " + s0[from_pos:].lstrip() + trailing


def _wrap_same_level_window_rank_filter(sql: str, question: str, ctx: str = "") -> str:
    """
    Move top-level filters on a window-rank alias to an outer query.

    MySQL cannot evaluate a SELECT-list window alias in the same block's WHERE.
    When a draft has a grouped/windowed top-N-per-group shape like:

      SELECT ..., ROW_NUMBER() OVER (...) AS rn
      FROM ...
      WHERE rn <= 2
      GROUP BY ...

    wrap the grouped/windowed query and apply rn <= 2 outside. The repair is
    intentionally generic and only relies on the query shape plus alias/FK
    equivalence, not on any specific table names.
    """
    s = str(sql or "").strip()
    if not s or not re.search(r"\b(?:ROW_NUMBER|RANK|DENSE_RANK)\s*\(", s, flags=re.I):
        return sql
    if re.search(r"(?is)^\s*WITH\b|\b(?:FROM|JOIN)\s*\(\s*SELECT\b", s):
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql

    where_pos = _find_top_level_clause(s0, "where", from_pos + len("from"))
    group_pos = _find_top_level_clause(s0, "group by", from_pos + len("from"))
    having_pos = _find_top_level_clause(s0, "having", from_pos + len("from"))
    order_pos = _find_top_level_clause(s0, "order by", from_pos + len("from"))
    limit_pos = _find_top_level_clause(s0, "limit", from_pos + len("from"))

    tail_positions = [p for p in [group_pos, having_pos, order_pos, limit_pos] if p >= 0]
    where_part = ""
    if where_pos >= 0:
        where_tail_positions = [p for p in tail_positions if p > where_pos]
        where_end = min(where_tail_positions) if where_tail_positions else len(s0)
        where_part = s0[where_pos + len("where"):where_end].strip()

    select_part = s0[sel_pos + len("select"):from_pos].strip()
    select_items = _split_top_level_commas(select_part)
    if not select_items:
        return sql

    alias_names: List[str] = []
    window_aliases: Set[str] = set()
    alias_expr_sql: Dict[str, str] = {}
    alias_simple_col: Dict[str, Tuple[str, str]] = {}
    alias_explicit: Dict[str, bool] = {}
    expr_to_alias: Dict[str, str] = {}

    def _clean_alias(alias_name: str) -> str:
        return str(alias_name or "").strip().strip("`'\"")

    def _column_alias_from_expr(expr: str) -> str:
        m_col = re.match(
            r"""(?is)^\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            expr,
        )
        return _clean_alias(m_col.group(1)) if m_col else ""

    for idx, item in enumerate(select_items):
        expr, alias = _split_select_expr_alias(item)
        explicit_alias = bool(alias)
        out_alias = _clean_alias(alias or _column_alias_from_expr(expr) or f"col_{idx + 1}")
        if not out_alias:
            return sql
        out_alias_l = out_alias.lower()
        if out_alias_l in {a.lower() for a in alias_names}:
            return sql
        alias_names.append(out_alias)
        alias_expr_sql[out_alias] = expr.strip()
        alias_explicit[out_alias] = explicit_alias
        expr_to_alias[_normalize_sql_expr_for_match(expr)] = out_alias
        if re.search(r"\b(?:ROW_NUMBER|RANK|DENSE_RANK)\s*\(", expr, flags=re.I):
            window_aliases.add(out_alias_l)
        m_col = re.match(
            r"""(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            expr,
        )
        if m_col:
            alias_simple_col[out_alias] = (m_col.group(1).lower(), m_col.group(2).lower())

    if not window_aliases:
        return sql

    def _top_n_per_group_from_question(question_text: str) -> str:
        q_text = str(question_text or "")
        if not q_text.strip():
            return ""
        word_to_num = {
            "one": "1",
            "two": "2",
            "three": "3",
            "four": "4",
            "five": "5",
            "six": "6",
            "seven": "7",
            "eight": "8",
            "nine": "9",
            "ten": "10",
        }
        for pat in HELPERS_TOP_N_PER_GROUP_PATTERNS:
            if not pat:
                continue
            m_top = re.search(pat, q_text, flags=re.I | re.S)
            if not m_top:
                continue
            matched = m_top.group(0)
            m_num = re.search(
                r"\b(\d+|one|two|three|four|five|six|seven|eight|nine|ten)\b",
                matched,
                flags=re.I,
            )
            if not m_num:
                continue
            raw_n = (m_num.group(1) or "").strip().lower()
            return word_to_num.get(raw_n, raw_n if raw_n.isdigit() else "")
        return ""

    rank_predicates: List[str] = []
    pred_pat = re.compile(
        r"""(?is)^\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*(?P<op><=|>=|=|<|>)\s*(?P<num>\d+)\s*$"""
    )

    def _partition_rank_predicates(clause_body: str) -> Tuple[List[str], List[str]]:
        kept: List[str] = []
        extracted: List[str] = []
        for pred in _split_top_level_and(clause_body) if clause_body else []:
            pred_s = str(pred or "").strip()
            m_pred = pred_pat.match(pred_s)
            if m_pred and (m_pred.group("alias") or "").strip().lower() in window_aliases:
                extracted.append(
                    f"{_clean_alias(m_pred.group('alias'))} {m_pred.group('op')} {m_pred.group('num')}"
                )
            elif pred_s:
                kept.append(pred_s)
        return kept, extracted

    remaining_predicates, extracted_where_rank_predicates = _partition_rank_predicates(where_part)
    rank_predicates.extend(extracted_where_rank_predicates)

    limit_n = ""
    if limit_pos >= 0:
        m_limit = re.match(r"(?is)\s*LIMIT\s+(\d+)\b", s0[limit_pos:].strip())
        if m_limit:
            limit_n = m_limit.group(1)

    has_partitioned_window = bool(
        re.search(r"\b(?:ROW_NUMBER|RANK|DENSE_RANK)\s*\(\s*\)\s*OVER\s*\([^)]*\bPARTITION\s+BY\b", select_part, flags=re.I)
    )
    top_n_match = re.search(
        r"\b(?:top|first)\s+(\d+)\b|\b(\d+)\s+(?:top|highest|largest|best)\b",
        question or "",
        flags=re.I,
    )
    top_n = (top_n_match.group(1) or top_n_match.group(2)) if top_n_match else ""
    top_n_per_group = _top_n_per_group_from_question(question)
    partitioned_top_n = bool(
        has_partitioned_window
        and (
            (
                limit_n
                and (
                    top_n == limit_n
                    or top_n_per_group == limit_n
                    or (not top_n and re.search(r"\b(?:within|per|for\s+each|each)\b", question or "", flags=re.I))
                )
            )
            or bool(top_n_per_group)
        )
    )
    if not rank_predicates and partitioned_top_n:
        first_rank_alias = next(iter(window_aliases))
        alias_original = next((a for a in alias_names if a.lower() == first_rank_alias), first_rank_alias)
        rank_predicates.append(f"{alias_original} <= {top_n_per_group or limit_n}")

    if not rank_predicates:
        return sql

    from_part = s0[from_pos:where_pos].strip()
    from_end_candidates = [p for p in [where_pos, group_pos, having_pos, order_pos, limit_pos] if p >= 0]
    from_end = min(from_end_candidates) if from_end_candidates else len(s0)
    from_part = s0[from_pos:from_end].strip()
    group_part = s0[group_pos:having_pos if having_pos >= 0 else order_pos if order_pos >= 0 else limit_pos if limit_pos >= 0 else len(s0)].strip() if group_pos >= 0 else ""
    having_part = s0[having_pos:order_pos if order_pos >= 0 else limit_pos if limit_pos >= 0 else len(s0)].strip() if having_pos >= 0 else ""
    order_part = s0[order_pos + len("order by"):limit_pos if limit_pos >= 0 else len(s0)].strip() if order_pos >= 0 else ""

    if having_part:
        having_body = re.sub(r"(?is)^\s*HAVING\b", "", having_part).strip()
        remaining_having_predicates, extracted_having_rank_predicates = _partition_rank_predicates(having_body)
        rank_predicates.extend(extracted_having_rank_predicates)
        having_part = f"HAVING {' AND '.join(remaining_having_predicates)}" if remaining_having_predicates else ""
    rank_predicates = list(dict.fromkeys(rank_predicates))

    output_alias_names = list(alias_names)
    if len(alias_simple_col) >= 2:
        alias_to_table = {
            str(k or "").strip().lower(): str(v or "").strip().lower()
            for k, v in (_parse_from_join_aliases(s0) or {}).items()
            if str(k or "").strip() and str(v or "").strip()
        }
        eq_pat = re.compile(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            flags=re.I,
        )
        equivalent_pairs: Set[Tuple[Tuple[str, str], Tuple[str, str]]] = set()
        for m_eq in eq_pat.finditer(s0):
            left = (m_eq.group(1).lower(), m_eq.group(2).lower())
            right = (m_eq.group(3).lower(), m_eq.group(4).lower())
            equivalent_pairs.add((left, right))
            equivalent_pairs.add((right, left))

        try:
            transaction_tables = {str(t).strip().lower() for t in get_transaction_tables() if str(t).strip()}
        except Exception:
            transaction_tables = set()
        q_terms = {
            tok for tok in re.findall(r"[a-z0-9]+", re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", question or "").lower())
        }

        def _alias_terms(alias_name: str) -> Set[str]:
            raw = f"{alias_name} {alias_expr_sql.get(alias_name, '')}"
            split = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
            return {tok for tok in re.findall(r"[a-z0-9]+", split.replace("_", " ").lower()) if tok}

        def _visible_identity_score(alias_name: str) -> int:
            qualifier, col_name = alias_simple_col.get(alias_name, ("", ""))
            table_name = alias_to_table.get(qualifier, qualifier)
            score = 0
            score += 3 * len(_alias_terms(alias_name) & q_terms)
            if table_name and table_name not in transaction_tables:
                score += 4
            if not alias_explicit.get(alias_name, False):
                score += 3
            if qualifier and alias_name.lower().startswith(f"{qualifier}_"):
                score -= 5
            if col_name and col_name.replace("_", "") == alias_name.replace("_", "").lower():
                score += 2
            return score

        drop_aliases: Set[str] = set()
        simple_aliases = [a for a in alias_names if a in alias_simple_col]
        for idx, left_alias in enumerate(simple_aliases):
            left_ref = alias_simple_col[left_alias]
            for right_alias in simple_aliases[idx + 1:]:
                right_ref = alias_simple_col[right_alias]
                if not left_ref[0] or not right_ref[0] or left_ref[1] != right_ref[1]:
                    continue
                if (left_ref, right_ref) not in equivalent_pairs:
                    continue
                left_score = _visible_identity_score(left_alias)
                right_score = _visible_identity_score(right_alias)
                if left_score == right_score:
                    keep_alias, drop_alias = sorted([left_alias, right_alias], key=lambda a: alias_names.index(a))
                elif left_score > right_score:
                    keep_alias, drop_alias = left_alias, right_alias
                else:
                    keep_alias, drop_alias = right_alias, left_alias
                if keep_alias:
                    drop_aliases.add(drop_alias)
        if drop_aliases:
            output_alias_names = [a for a in alias_names if a not in drop_aliases]

    inner_sql = f"SELECT {select_part} {from_part}"
    if remaining_predicates:
        inner_sql += " WHERE " + " AND ".join(remaining_predicates)
    if group_part:
        inner_sql += f" {group_part}"
    if having_part:
        inner_sql += f" {having_part}"

    def _outer_ref(alias_name: str) -> str:
        alias_clean = _clean_alias(alias_name)
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", alias_clean) and alias_clean.lower() not in {"rank"}:
            return f"ranked.{alias_clean}"
        return f"ranked.`{alias_clean}`"

    outer_select = ", ".join(_outer_ref(alias_name) for alias_name in output_alias_names)
    outer_where = " AND ".join(
        re.sub(
            r"""^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*(<=|>=|=|<|>)\s*(\d+)\s*$""",
            lambda m: f"{_outer_ref(m.group(1))} {m.group(2)} {m.group(3)}",
            pred,
            flags=re.I,
        )
        for pred in rank_predicates
    )

    def _split_order_dir(order_item: str) -> Tuple[str, str]:
        m_dir = re.match(r"(?is)^\s*(.*?)\s+(ASC|DESC)\s*$", order_item.strip())
        if m_dir:
            return (m_dir.group(1).strip(), m_dir.group(2).upper())
        return (order_item.strip(), "")

    outer_order_items: List[str] = []
    for order_item in _split_top_level_commas(order_part):
        expr, direction = _split_order_dir(order_item)
        expr_clean = expr.strip().strip("`")
        mapped_alias = ""
        for alias_name in alias_names:
            if expr_clean.lower() == alias_name.lower():
                mapped_alias = alias_name
                break
        if not mapped_alias:
            norm = _normalize_sql_expr_for_match(expr)
            mapped_alias = expr_to_alias.get(norm, "")
        if not mapped_alias:
            m_order_col = re.match(
                r"""(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
                expr,
            )
            if m_order_col:
                ref = (m_order_col.group(1).lower(), m_order_col.group(2).lower())
                for alias_name, simple_ref in alias_simple_col.items():
                    if simple_ref == ref:
                        mapped_alias = alias_name
                        break
        if mapped_alias and mapped_alias in output_alias_names:
            outer_order_items.append(f"{_outer_ref(mapped_alias)}{(' ' + direction) if direction else ''}")

    out = f"SELECT {outer_select} FROM ({inner_sql}) AS ranked WHERE {outer_where}"
    if outer_order_items:
        out += " ORDER BY " + ", ".join(outer_order_items)
    if trailing:
        out += trailing
    return out


def _repair_malformed_fk_join_path(sql: str, question: str, ctx: str = "") -> str:
    """
    Rebuild a flat malformed FK join path when the draft references an alias
    whose table is missing but inferable from schema columns.

    Scope is intentionally narrow: flat outer SELECT with JOIN present. It
    handles corruption like duplicate ON clauses or omitted connector/entity
    tables by using metadata FK edges and the columns referenced by the missing
    alias. Aliases inside scalar/IN/EXISTS subqueries are deliberately ignored:
    they belong to a nested scope and must not cause new outer joins.
    """
    s = str(sql or "").strip()
    if not s or not has_join(s):
        return sql
    if re.search(r"(?is)^\s*WITH\b|\b(?:FROM|JOIN)\s*\(\s*SELECT\b|\bUNION\b|\bINTERSECT\b|\bEXCEPT\b", s):
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql

    clause_positions = [
        p for p in [
            _find_top_level_clause(s0, "where", from_pos + len("from")),
            _find_top_level_clause(s0, "group by", from_pos + len("from")),
            _find_top_level_clause(s0, "having", from_pos + len("from")),
            _find_top_level_clause(s0, "order by", from_pos + len("from")),
            _find_top_level_clause(s0, "limit", from_pos + len("from")),
        ]
        if p >= 0
    ]
    from_end = min(clause_positions) if clause_positions else len(s0)
    from_core = s0[from_pos + len("from"):from_end].strip()
    if not from_core:
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if not alias_to_table:
        return sql

    def _mask_nested_select_scopes(text: str) -> str:
        chars = list(text)
        stack: List[int] = []
        quote = ""
        i = 0
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote:
                    if quote == "'" and i + 1 < len(text) and text[i + 1] == "'":
                        i += 2
                        continue
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                stack.append(i)
            elif ch == ")" and stack:
                open_idx = stack.pop()
                inner = text[open_idx + 1:i].lstrip()
                if re.match(r"(?is)^SELECT\b", inner):
                    for j in range(open_idx, i + 1):
                        if chars[j] not in "\r\n":
                            chars[j] = " "
            i += 1
        return "".join(chars)

    ref_pat = re.compile(r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""")
    refs_by_alias: Dict[str, Set[str]] = {}
    outer_scope_sql = _mask_nested_select_scopes(s0)
    for m_ref in ref_pat.finditer(outer_scope_sql):
        alias_l = (m_ref.group(1) or "").lower()
        col_l = (m_ref.group(2) or "").lower()
        if alias_l and col_l:
            refs_by_alias.setdefault(alias_l, set()).add(col_l)

    undefined_aliases = {
        alias_l for alias_l in refs_by_alias
        if alias_l not in alias_to_table
        and alias_l not in {"select", "from", "where", "group", "order", "having", "limit", "on", "and", "or"}
    }
    malformed_on_chain = bool(re.search(r"(?is)\bON\b(?:(?!\bJOIN\b).)*\bON\b", from_core))
    undefined_in_from_core = any(
        re.search(rf"""(?is)\b`?{re.escape(alias_l)}`?\s*\.""", from_core)
        for alias_l in undefined_aliases
    )

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    if analyzer is None:
        return sql

    try:
        all_tables = [str(t).strip().lower() for t in get_all_tables() if str(t).strip()]
    except Exception:
        all_tables = []
    if not all_tables:
        return sql

    def _table_cols(table_l: str) -> Set[str]:
        try:
            return {str(c).strip("`").lower() for c in analyzer.get_table_columns(table_l) if str(c).strip()}
        except Exception:
            return set()

    def _case_col(table_l: str, col_l: str) -> str:
        return str(getattr(analyzer, "_column_original_case", {}).get(f"{table_l}.{col_l}", col_l))

    inferred_aliases: Dict[str, str] = {}
    used_tables = {str(t).strip().lower() for t in alias_to_table.values() if str(t).strip()}
    for alias_l in sorted(undefined_aliases):
        cols = refs_by_alias.get(alias_l, set())
        if not cols:
            continue
        scored: List[Tuple[int, str]] = []
        for table_l in all_tables:
            table_cols = _table_cols(table_l)
            overlap = cols & table_cols
            if not overlap:
                continue
            score = 10 * len(overlap)
            if cols.issubset(table_cols):
                score += 100
            if table_l not in used_tables:
                score += 5
            scored.append((score, table_l))
        if not scored:
            continue
        scored.sort(key=lambda item: (-item[0], item[1]))
        best_score = scored[0][0]
        best = [table_l for score, table_l in scored if score == best_score]
        if len(best) == 1:
            inferred_aliases[alias_l] = best[0]
            used_tables.add(best[0])

    if undefined_aliases and set(inferred_aliases) != undefined_aliases:
        return sql

    reserved_alias_tokens = {
        "left", "right", "inner", "outer", "full", "cross", "join",
        "on", "where", "group", "order", "having", "limit",
    }
    source_pairs: List[Tuple[str, str]] = []
    seen_aliases: Set[str] = set()
    for m_tbl in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?""",
        f"FROM {from_core}",
    ):
        raw_tbl = (m_tbl.group(1) or "").replace("`", "").strip()
        table_l = raw_tbl.split(".")[-1].lower()
        alias_raw = (m_tbl.group(2) or "").strip()
        if alias_raw.lower() in reserved_alias_tokens:
            alias_raw = ""
        alias = (alias_raw or table_l).strip()
        alias_l = alias.lower()
        if table_l and alias_l and alias_l not in seen_aliases:
            seen_aliases.add(alias_l)
            source_pairs.append((alias, table_l))

    for alias_l, table_l in inferred_aliases.items():
        if alias_l not in seen_aliases:
            source_pairs.append((alias_l, table_l))
            seen_aliases.add(alias_l)
    if len(source_pairs) < 2:
        return sql

    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, mapping in (fk_raw or {}).items():
        src_l = str(src or "").strip().lower()
        fk_map[src_l] = {
            str(fk_col or "").strip().lower(): str(tgt or "").strip().lower()
            for fk_col, tgt in (mapping or {}).items()
            if str(fk_col or "").strip() and str(tgt or "").strip()
        }

    def _edge(left: Tuple[str, str], right: Tuple[str, str]) -> str:
        left_alias, left_table = left
        right_alias, right_table = right
        for fk_col, target in (fk_map.get(left_table, {}) or {}).items():
            if target == right_table:
                target_id = str(get_id_column(right_table) or "").strip("`").lower()
                if target_id and fk_col in _table_cols(left_table) and target_id in _table_cols(right_table):
                    return f"{left_alias}.{_case_col(left_table, fk_col)} = {right_alias}.{_case_col(right_table, target_id)}"
        for fk_col, target in (fk_map.get(right_table, {}) or {}).items():
            if target == left_table:
                target_id = str(get_id_column(left_table) or "").strip("`").lower()
                if target_id and fk_col in _table_cols(right_table) and target_id in _table_cols(left_table):
                    return f"{right_alias}.{_case_col(right_table, fk_col)} = {left_alias}.{_case_col(left_table, target_id)}"
        return ""

    def _fk_table_path(start_table: str, end_table: str, max_edges: int = 3) -> List[str]:
        start_l = str(start_table or "").strip().lower()
        end_l = str(end_table or "").strip().lower()
        if not start_l or not end_l or start_l == end_l:
            return []
        neighbors: Dict[str, Set[str]] = {}
        for src_l, mapping in (fk_map or {}).items():
            for target_l in (mapping or {}).values():
                if not src_l or not target_l:
                    continue
                neighbors.setdefault(src_l, set()).add(target_l)
                neighbors.setdefault(target_l, set()).add(src_l)
        queue: List[List[str]] = [[start_l]]
        seen: Set[str] = {start_l}
        while queue:
            path = queue.pop(0)
            if len(path) - 1 >= max_edges:
                continue
            for nxt in sorted(neighbors.get(path[-1], set())):
                if nxt in seen:
                    continue
                new_path = path + [nxt]
                if nxt == end_l:
                    return new_path
                seen.add(nxt)
                queue.append(new_path)
        return []

    if not undefined_aliases and not malformed_on_chain:
        # Repair a flat direct join that skips a required connector table,
        # e.g. child.order_id = grandparent.id where child -> parent -> grandparent.
        if len(source_pairs) == 2 and not _edge(source_pairs[0], source_pairs[1]):
            path = _fk_table_path(source_pairs[0][1], source_pairs[1][1])
            if len(path) > 2:
                used_aliases = {source_pairs[0][0].lower(), source_pairs[1][0].lower()}

                def _connector_alias(table_l: str) -> str:
                    base = re.sub(r"[^A-Za-z0-9_]+", "_", table_l).strip("_") or "t"
                    alias = base
                    idx = 2
                    while alias.lower() in used_aliases:
                        alias = f"{base}_{idx}"
                        idx += 1
                    used_aliases.add(alias.lower())
                    return alias

                path_pairs: List[Tuple[str, str]] = [source_pairs[0]]
                for table_l in path[1:-1]:
                    path_pairs.append((_connector_alias(table_l), table_l))
                path_pairs.append(source_pairs[1])

                rebuilt_from = f"{path_pairs[0][1]} AS {path_pairs[0][0]}"
                for prev, curr in zip(path_pairs, path_pairs[1:]):
                    on_clause = _edge(prev, curr)
                    if not on_clause:
                        return sql
                    rebuilt_from += f" JOIN {curr[1]} AS {curr[0]} ON {on_clause}"

                rebuilt = s0[:from_pos + len("from")] + " " + rebuilt_from
                if from_end < len(s0):
                    rebuilt += " " + s0[from_end:].lstrip()
                rebuilt = re.sub(r"\s{2,}", " ", rebuilt).strip()
                if trailing and not rebuilt.endswith(";"):
                    rebuilt += ";"
                return rebuilt
        return sql

    if undefined_aliases and not malformed_on_chain and not undefined_in_from_core:
        connected = [pair for pair in source_pairs if pair[0].strip().lower() not in inferred_aliases]
        missing = [pair for pair in source_pairs if pair[0].strip().lower() in inferred_aliases]
        if not connected or not missing:
            return sql
        rebuilt_from = from_core
        for candidate in missing:
            chosen_on = ""
            for existing in connected:
                chosen_on = _edge(existing, candidate)
                if chosen_on:
                    break
            if not chosen_on:
                return sql
            alias, table_l = candidate
            rebuilt_from += f" JOIN {table_l} AS {alias} ON {chosen_on}"
            connected.append(candidate)

        rebuilt = s0[:from_pos + len("from")] + " " + rebuilt_from
        if from_end < len(s0):
            rebuilt += " " + s0[from_end:].lstrip()
        rebuilt = re.sub(r"\s{2,}", " ", rebuilt).strip()
        if trailing and not rebuilt.endswith(";"):
            rebuilt += ";"
        return rebuilt

    connected = [source_pairs[0]]
    remaining = source_pairs[1:]
    joins: List[Tuple[Tuple[str, str], str]] = []
    while remaining:
        chosen_idx = -1
        chosen_on = ""
        for idx, candidate in enumerate(remaining):
            for existing in connected:
                on_clause = _edge(existing, candidate)
                if on_clause:
                    chosen_idx = idx
                    chosen_on = on_clause
                    break
            if chosen_idx >= 0:
                break
        if chosen_idx < 0:
            return sql
        candidate = remaining.pop(chosen_idx)
        connected.append(candidate)
        joins.append((candidate, chosen_on))

    base_alias, base_table = connected[0]
    rebuilt_from = f"{base_table} AS {base_alias}"
    for (alias, table_l), on_clause in joins:
        rebuilt_from += f" JOIN {table_l} AS {alias} ON {on_clause}"

    rebuilt = s0[:from_pos + len("from")] + " " + rebuilt_from
    if from_end < len(s0):
        rebuilt += " " + s0[from_end:].lstrip()
    rebuilt = re.sub(r"\s{2,}", " ", rebuilt).strip()
    if trailing and not rebuilt.endswith(";"):
        rebuilt += ";"
    return rebuilt


def _ast_validate_join_logic(sql: str, question: str = "", ctx: str = "") -> Tuple[str, Dict[str, Any]]:
    """
    AST-first validation/routing for malformed FK join-path repairs.

    Scope for this batch:
    - parseable top-level SELECT queries with real table JOINs
    - invalid direct FK ON predicates that are close to one schema-backed edge
    - direct two-table joins that skip a required FK connector path
    - outer-scope references to an alias whose backing table is missing but
      inferable from schema columns

    Guardrails:
    - skip derived-table join graphs and set-operation roots
    - reuse the existing conservative join repair helpers
    - accept a rewrite only when the candidate remains sqlglot-parseable
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
        "scope_kinds": [],
    }
    s = str(sql or "").strip()
    if not s:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    sel = ast if isinstance(ast, exp.Select) else ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        meta["warnings"].append("unsupported_root")
        return sql, meta
    if any(True for _ in sel.find_all(exp.SetOperation)):
        meta["warnings"].append("setop_skipped")
        return sql, meta

    from_arg = sel.args.get("from") or sel.args.get("from_")
    if from_arg is None:
        meta["warnings"].append("missing_from")
        return sql, meta

    base_table_expr = getattr(from_arg, "this", None)
    if not isinstance(base_table_expr, exp.Table):
        meta["warnings"].append("derived_from_skipped")
        return sql, meta

    join_exprs = [j for j in (sel.args.get("joins") or []) if isinstance(j, exp.Join)]
    if not join_exprs:
        return sql, meta
    if any(not isinstance(getattr(j, "this", None), exp.Table) for j in join_exprs):
        meta["warnings"].append("derived_join_skipped")
        return sql, meta

    try:
        analyzer = get_schema_analyzer()
        all_tables = [str(t).strip().lower() for t in get_all_tables() if str(t).strip()]
        fk_raw = get_fk_relationships() or {}
    except Exception:
        analyzer = None
        all_tables = []
        fk_raw = {}
    if analyzer is None or not all_tables or not fk_raw:
        meta["warnings"].append("schema_unavailable")
        return sql, meta

    fk_map: Dict[str, Dict[str, str]] = {}
    for src, mapping in (fk_raw or {}).items():
        src_l = str(src or "").strip().lower()
        if not src_l:
            continue
        fk_map[src_l] = {
            str(fk_col or "").strip().lower(): str(tgt or "").strip().lower()
            for fk_col, tgt in (mapping or {}).items()
            if str(fk_col or "").strip() and str(tgt or "").strip()
        }

    def _table_cols(table_l: str) -> Set[str]:
        try:
            return {str(c).strip("`").lower() for c in analyzer.get_table_columns(table_l) if str(c).strip()}
        except Exception:
            return set()

    alias_to_table: Dict[str, str] = {}
    source_pairs: List[Tuple[str, str]] = []

    base_table = str(base_table_expr.name or "").strip("`").lower()
    base_alias = str(base_table_expr.alias_or_name or base_table).strip("`").lower()
    if not base_table or not base_alias:
        meta["warnings"].append("missing_base_alias")
        return sql, meta
    alias_to_table[base_alias] = base_table
    alias_to_table[base_table] = base_table
    source_pairs.append((base_alias, base_table))

    for join_expr in join_exprs:
        table_expr = getattr(join_expr, "this", None)
        if not isinstance(table_expr, exp.Table):
            continue
        table_l = str(table_expr.name or "").strip("`").lower()
        alias_l = str(table_expr.alias_or_name or table_l).strip("`").lower()
        if not table_l or not alias_l:
            continue
        alias_to_table[alias_l] = table_l
        alias_to_table.setdefault(table_l, table_l)
        source_pairs.append((alias_l, table_l))

    def _nearest_select(node: "exp.Expression") -> Optional["exp.Select"]:
        anc = getattr(node, "parent", None)
        while anc is not None:
            if isinstance(anc, exp.Select):
                return anc
            anc = getattr(anc, "parent", None)
        return None

    refs_by_alias: Dict[str, Set[str]] = {}
    for col in sel.find_all(exp.Column):
        if _nearest_select(col) is not sel:
            continue
        alias_l = str(col.table or "").strip("`").lower()
        col_l = str(col.name or "").strip("`").lower()
        if alias_l and col_l:
            refs_by_alias.setdefault(alias_l, set()).add(col_l)

    reserved_alias_tokens = {
        "select", "from", "where", "group", "order", "having", "limit",
        "join", "left", "right", "inner", "outer", "full", "cross", "on",
        "and", "or",
    }
    undefined_aliases = {
        alias_l for alias_l in refs_by_alias
        if alias_l not in alias_to_table and alias_l not in reserved_alias_tokens
    }

    inferred_aliases: Dict[str, str] = {}
    used_tables = {table_l for _alias_l, table_l in source_pairs}
    for alias_l in sorted(undefined_aliases):
        cols = refs_by_alias.get(alias_l, set())
        if not cols:
            continue
        scored: List[Tuple[int, str]] = []
        for table_l in all_tables:
            table_cols = _table_cols(table_l)
            overlap = cols & table_cols
            if not overlap:
                continue
            score = 10 * len(overlap)
            if cols.issubset(table_cols):
                score += 100
            if table_l not in used_tables:
                score += 5
            scored.append((score, table_l))
        if not scored:
            continue
        scored.sort(key=lambda item: (-item[0], item[1]))
        best_score = scored[0][0]
        best = [table_l for score, table_l in scored if score == best_score]
        if len(best) == 1:
            inferred_aliases[alias_l] = best[0]

    scope_kinds: List[str] = []
    if undefined_aliases and set(inferred_aliases) == undefined_aliases:
        scope_kinds.append("missing_alias_table")

    def _fk_table_path(start_table: str, end_table: str, max_edges: int = 3) -> List[str]:
        start_l = str(start_table or "").strip().lower()
        end_l = str(end_table or "").strip().lower()
        if not start_l or not end_l or start_l == end_l:
            return []
        neighbors: Dict[str, Set[str]] = {}
        for src_l, mapping in (fk_map or {}).items():
            for tgt_l in (mapping or {}).values():
                if not src_l or not tgt_l:
                    continue
                neighbors.setdefault(src_l, set()).add(tgt_l)
                neighbors.setdefault(tgt_l, set()).add(src_l)
        queue: List[List[str]] = [[start_l]]
        seen: Set[str] = {start_l}
        while queue:
            path = queue.pop(0)
            if len(path) - 1 >= max_edges:
                continue
            for nxt in sorted(neighbors.get(path[-1], set())):
                if nxt in seen:
                    continue
                new_path = path + [nxt]
                if nxt == end_l:
                    return new_path
                seen.add(nxt)
                queue.append(new_path)
        return []

    def _expected_edge_specs(left_table: str, right_table: str) -> List[Tuple[str, str, str, str]]:
        specs: List[Tuple[str, str, str, str]] = []
        for fk_col, target in (fk_map.get(left_table, {}) or {}).items():
            if target != right_table:
                continue
            right_id = str(get_id_column(right_table) or "").strip("`").lower()
            if right_id and fk_col in _table_cols(left_table) and right_id in _table_cols(right_table):
                specs.append((left_table, fk_col, right_table, right_id))
        for fk_col, target in (fk_map.get(right_table, {}) or {}).items():
            if target != left_table:
                continue
            left_id = str(get_id_column(left_table) or "").strip("`").lower()
            if left_id and fk_col in _table_cols(right_table) and left_id in _table_cols(left_table):
                specs.append((right_table, fk_col, left_table, left_id))
        return specs

    def _join_side(join_expr: "exp.Join") -> str:
        side = join_expr.args.get("side")
        return str(side or "").strip().upper()

    def _flatten_top_and(node: Optional["exp.Expression"]) -> List["exp.Expression"]:
        if node is None:
            return []
        if isinstance(node, exp.And):
            return _flatten_top_and(node.this) + _flatten_top_and(node.expression)
        return [node]

    def _is_alias_null_check(
        cond: Optional["exp.Expression"],
        alias_l: str,
    ) -> bool:
        if not isinstance(cond, exp.Is):
            return False
        left = getattr(cond, "this", None)
        right = getattr(cond, "expression", None)
        if isinstance(left, exp.Column) and isinstance(right, exp.Null):
            return str(left.table or "").strip("`").lower() == alias_l
        if isinstance(right, exp.Column) and isinstance(left, exp.Null):
            return str(right.table or "").strip("`").lower() == alias_l
        return False

    connected_aliases: List[Tuple[str, str]] = [source_pairs[0]]
    for join_expr in join_exprs:
        table_expr = getattr(join_expr, "this", None)
        on_expr = join_expr.args.get("on")
        if not isinstance(table_expr, exp.Table):
            continue
        join_alias = str(table_expr.alias_or_name or table_expr.name or "").strip("`").lower()
        join_table = str(table_expr.name or "").strip("`").lower()
        if not join_alias or not join_table:
            continue

        if len(source_pairs) == 2:
            has_direct_edge = any(
                _expected_edge_specs(existing_table, join_table)
                for _existing_alias, existing_table in connected_aliases
            )
            if not has_direct_edge:
                path = _fk_table_path(connected_aliases[0][1], join_table)
                if len(path) > 2 and "missing_connector_path" not in scope_kinds:
                    scope_kinds.append("missing_connector_path")

        if on_expr is None:
            connected_aliases.append((join_alias, join_table))
            continue

        conds: List["exp.Expression"] = []

        def _flatten_and(node: Optional["exp.Expression"]) -> List["exp.Expression"]:
            if node is None:
                return []
            if isinstance(node, exp.And):
                return _flatten_and(node.this) + _flatten_and(node.expression)
            return [node]

        conds = _flatten_and(on_expr)
        joined_pair_found = False
        valid_pair_found = False
        near_miss_found = False

        for cond in conds:
            if not isinstance(cond, exp.EQ):
                continue
            left = getattr(cond, "this", None)
            right = getattr(cond, "expression", None)
            if not isinstance(left, exp.Column) or not isinstance(right, exp.Column):
                continue
            left_alias = str(left.table or "").strip("`").lower()
            right_alias = str(right.table or "").strip("`").lower()
            left_col = str(left.name or "").strip("`").lower()
            right_col = str(right.name or "").strip("`").lower()
            if not left_alias or not right_alias or not left_col or not right_col:
                continue

            other_alias = ""
            other_table = ""
            joined_col = ""
            other_col = ""
            if left_alias == join_alias and right_alias in {alias for alias, _table in connected_aliases}:
                other_alias = right_alias
                other_table = alias_to_table.get(right_alias, "")
                joined_col = left_col
                other_col = right_col
            elif right_alias == join_alias and left_alias in {alias for alias, _table in connected_aliases}:
                other_alias = left_alias
                other_table = alias_to_table.get(left_alias, "")
                joined_col = right_col
                other_col = left_col
            if not other_alias or not other_table:
                continue

            joined_pair_found = True
            specs = _expected_edge_specs(other_table, join_table)
            if len(specs) != 1:
                continue
            spec = specs[0]
            expected_pairs = {
                (spec[0], spec[1]),
                (spec[2], spec[3]),
            }
            actual_pairs = {
                (join_table, joined_col),
                (other_table, other_col),
            }
            if actual_pairs == expected_pairs:
                valid_pair_found = True
                break
            expected_cols = {spec[1], spec[3]}
            if joined_col in expected_cols or other_col in expected_cols:
                near_miss_found = True

        if joined_pair_found and not valid_pair_found and near_miss_found:
            if "invalid_fk_condition" not in scope_kinds:
                scope_kinds.append("invalid_fk_condition")

        connected_aliases.append((join_alias, join_table))

    left_join_aliases: Dict[str, "exp.Join"] = {}
    for join_expr in join_exprs:
        table_expr = getattr(join_expr, "this", None)
        if not isinstance(table_expr, exp.Table):
            continue
        if "LEFT" not in _join_side(join_expr):
            continue
        join_alias = str(table_expr.alias_or_name or table_expr.name or "").strip("`").lower()
        if join_alias:
            left_join_aliases[join_alias] = join_expr

    left_join_aliases_for_scope = set(left_join_aliases)
    where_arg = sel.args.get("where")
    rhs_filtered_outer_join_aliases: Set[str] = set()
    if (
        left_join_aliases_for_scope
        and isinstance(where_arg, exp.Where)
        and where_arg.this is not None
        and not _question_wants_include_zero(question, ctx)
    ):
        conjuncts = _flatten_top_and(where_arg.this)
        conjunction_only = bool(conjuncts) and all(
            not isinstance(cond, exp.Or) and cond.find(exp.Or) is None
            for cond in conjuncts
        )
        if conjunction_only:
            anti_aliases: Set[str] = set()
            positive_aliases: Set[str] = set()
            ambiguous_aliases: Set[str] = set()

            for cond in conjuncts:
                referenced_left_aliases = {
                    str(col.table or "").strip("`").lower()
                    for col in cond.find_all(exp.Column)
                    if str(col.table or "").strip("`").lower() in left_join_aliases_for_scope
                }
                if not referenced_left_aliases:
                    continue
                anti_here = {
                    alias_l for alias_l in referenced_left_aliases
                    if _is_alias_null_check(cond, alias_l)
                }
                anti_aliases.update(anti_here)
                if len(referenced_left_aliases) == 1 and not anti_here:
                    positive_aliases.update(referenced_left_aliases)
                elif len(referenced_left_aliases) > 1:
                    ambiguous_aliases.update(referenced_left_aliases)

            rhs_filtered_outer_join_aliases = {
                alias_l for alias_l in positive_aliases
                if alias_l not in anti_aliases and alias_l not in ambiguous_aliases
            }

            if rhs_filtered_outer_join_aliases and "rhs_filtered_outer_join" not in scope_kinds:
                scope_kinds.append("rhs_filtered_outer_join")

    if not scope_kinds:
        return sql, meta

    meta["handled_scope"] = True
    meta["scope_kinds"] = list(dict.fromkeys(scope_kinds))

    def _validate_candidate(candidate_sql: str, fix_name: str) -> Optional[str]:
        candidate = str(candidate_sql or "").strip()
        if not candidate or candidate == s:
            return None
        parse_target = re.sub(r";+\s*$", "", candidate).strip()
        try:
            sqlglot.parse_one(parse_target, read=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            meta["warnings"].append(f"{fix_name}_parse_rejected")
            return None
        if s.endswith(";") and not candidate.endswith(";"):
            candidate = parse_target + ";"
        return candidate

    current_sql = s
    if "rhs_filtered_outer_join" in meta["scope_kinds"]:
        try:
            rewrite_ast = sqlglot.parse_one(current_sql, read=SQL_PARSE_DIALECT or "mysql")
            rewrite_sel = rewrite_ast if isinstance(rewrite_ast, exp.Select) else rewrite_ast.find(exp.Select)
        except Exception:
            rewrite_ast = None
            rewrite_sel = None

        if isinstance(rewrite_sel, exp.Select):
            join_exprs_for_rewrite = [j for j in (rewrite_sel.args.get("joins") or []) if isinstance(j, exp.Join)]
            changed_outer_join = False
            for join_expr in join_exprs_for_rewrite:
                table_expr = getattr(join_expr, "this", None)
                if not isinstance(table_expr, exp.Table):
                    continue
                if "LEFT" not in _join_side(join_expr):
                    continue
                join_alias = str(table_expr.alias_or_name or table_expr.name or "").strip("`").lower()
                if join_alias not in rhs_filtered_outer_join_aliases:
                    continue
                join_expr.set("side", None)
                join_expr.set("kind", None)
                changed_outer_join = True
            if changed_outer_join:
                rendered = rewrite_ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
                if s.endswith(";"):
                    rendered = rendered.rstrip(";") + ";"
                validated = _validate_candidate(rendered, "rhs_filtered_outer_join_ast")
                if validated:
                    current_sql = validated
                    meta["fixes"].append("rhs_filtered_outer_join_ast")

    rewrite_steps: List[Tuple[str, Any]] = []
    if "invalid_fk_condition" in scope_kinds:
        rewrite_steps.append(("invalid_fk_join_conditions_ast", lambda text: _rewrite_invalid_fk_join_conditions(text, ctx)))
    if "missing_alias_table" in scope_kinds or "missing_connector_path" in scope_kinds:
        rewrite_steps.append(("malformed_fk_join_path_ast", lambda text: _repair_malformed_fk_join_path(text, question, ctx)))
    if "invalid_fk_condition" in scope_kinds or "missing_alias_table" in scope_kinds or "missing_connector_path" in scope_kinds:
        rewrite_steps.append(("post_path_fk_join_conditions_ast", lambda text: _rewrite_invalid_fk_join_conditions(text, ctx)))

    for fix_name, fixer in rewrite_steps:
        try:
            candidate = fixer(current_sql)
        except Exception:
            meta["warnings"].append(f"{fix_name}_error")
            continue
        if not candidate or candidate == current_sql:
            continue
        validated = _validate_candidate(candidate, fix_name)
        if not validated:
            continue
        current_sql = validated
        meta["fixes"].append(fix_name)

    meta["warnings"] = list(dict.fromkeys(meta["warnings"]))
    if meta["fixes"]:
        return current_sql, meta
    return sql, meta


def _rewrite_ordered_quantity_stock_aggregate(
    sql: str,
    question: str,
    ctx: str = "",
) -> str:
    """
    Repair aggregate queries that ask for ordered quantity but use an inventory
    stock column from the entity table instead of the child transaction table.

    The rewrite is schema-driven:
    - base table must be a single table aggregate;
    - a child table must FK to the base table;
    - the child table must expose a quantity/ordered metric column.
    """
    s = str(sql or "").strip()
    q = str(question or "").lower()
    if not s or not q:
        return sql
    if "join" in s.lower() or "group by" not in s.lower():
        return sql
    has_ordered_quantity_intent = bool(
        any_phrase_in_text(q, ordered_quantity_repair_order_terms())
        and any_phrase_in_text(q, ordered_quantity_repair_quantity_terms())
    )
    if not has_ordered_quantity_intent:
        return sql

    parsed = _parse_select_from_groupby(s)
    if not parsed:
        m_flat = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<rest>.+?)\s*;?\s*$", s)
        if not m_flat:
            return sql
        select_part_fallback = str(m_flat.group("select") or "").strip()
        rest_fallback = str(m_flat.group("rest") or "").strip()
        if not select_part_fallback or not rest_fallback:
            return sql

        clause_positions: List[Tuple[int, str]] = []
        for kw in ("WHERE", "GROUP BY", "HAVING", "ORDER BY", "LIMIT"):
            pos = _find_top_level_clause(rest_fallback, kw.lower())
            if pos >= 0:
                clause_positions.append((pos, kw))
        clause_positions.sort(key=lambda item: item[0])

        if clause_positions:
            first_pos = clause_positions[0][0]
            from_core_fallback = rest_fallback[:first_pos].strip()
            trailing_fallback = rest_fallback[first_pos:].strip()
        else:
            from_core_fallback = rest_fallback
            trailing_fallback = ""

        where_fallback = ""
        tail_fallback = trailing_fallback
        if trailing_fallback:
            where_pos = _find_top_level_clause(trailing_fallback, "where")
            if where_pos >= 0:
                next_pos = len(trailing_fallback)
                for kw in ("GROUP BY", "HAVING", "ORDER BY", "LIMIT"):
                    pos = _find_top_level_clause(
                        trailing_fallback,
                        kw.lower(),
                        where_pos + len("where"),
                    )
                    if pos >= 0:
                        next_pos = min(next_pos, pos)
                where_fallback = trailing_fallback[where_pos:next_pos].strip()
                tail_fallback = trailing_fallback[next_pos:].strip()

        parsed = {
            "select": select_part_fallback,
            "from_core": from_core_fallback,
            "where": where_fallback,
            "groupby": "",
            "having": "",
            "tail": tail_fallback,
        }
    from_core = (parsed.get("from_core") or "").strip()
    m_from = re.match(
        r"""(?is)^`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?\s*$""",
        from_core,
    )
    if not m_from:
        return sql
    base_table = (m_from.group("table") or "").strip().lower()
    base_alias = (m_from.group("alias") or m_from.group("table") or "").strip()
    if not base_table or not base_alias:
        return sql

    try:
        analyzer = get_schema_analyzer()
        fk_raw = get_fk_relationships() or {}
    except Exception:
        return sql

    def _table_cols(table_l: str) -> Set[str]:
        try:
            return {str(c).strip("`").lower() for c in analyzer.get_table_columns(table_l) if str(c).strip()}
        except Exception:
            return set()

    def _case_col(table_l: str, col_l: str) -> str:
        return str(getattr(analyzer, "_column_original_case", {}).get(f"{table_l}.{col_l}", col_l))

    def _normalize_terms_text(text: str) -> str:
        return re.sub(
            r"([a-z0-9])([A-Z])",
            r"\1 \2",
            str(text or "").replace("_", " "),
        ).lower()

    def _terms(text: str) -> Set[str]:
        return {tok for tok in re.split(r"[^a-z0-9]+", _normalize_terms_text(text)) if tok}

    def _configured_signal(raw_terms: Sequence[str]) -> Tuple[Set[str], Set[str]]:
        stop = {"a", "an", "the", "of", "for", "with", "in", "on", "at", "by"}
        tokens: Set[str] = set()
        compacts: Set[str] = set()
        for raw in raw_terms or []:
            raw_s = str(raw or "").strip()
            if not raw_s:
                continue
            normalized = _normalize_terms_text(raw_s)
            toks = {tok for tok in re.split(r"[^a-z0-9]+", normalized) if tok and tok not in stop}
            tokens.update(toks)
            compact = re.sub(r"[^a-z0-9]+", "", normalized)
            if compact:
                compacts.add(compact)
        return tokens, compacts

    quantity_tokens, quantity_compacts = _configured_signal(ordered_quantity_repair_quantity_terms())
    order_tokens, order_compacts = _configured_signal(ordered_quantity_repair_order_terms())
    inventory_tokens, inventory_compacts = _configured_signal(ordered_quantity_repair_inventory_terms())
    non_quantity_tokens, non_quantity_compacts = _configured_signal(
        ordered_quantity_repair_non_quantity_metric_terms()
    )

    def _column_semantics(table_l: str, col_l: str) -> Tuple[Set[str], str]:
        texts = [col_l, _case_col(table_l, col_l)]
        try:
            texts.append(str(get_column_description(table_l, col_l) or ""))
        except Exception:
            pass
        try:
            texts.append(str(get_column_role(table_l, col_l) or ""))
        except Exception:
            pass
        try:
            texts.extend(str(syn or "") for syn in analyzer.get_column_synonyms(table_l, col_l) or [])
        except Exception:
            pass
        normalized = " ".join(_normalize_terms_text(text) for text in texts if str(text or "").strip())
        return _terms(normalized), re.sub(r"[^a-z0-9]+", "", normalized)

    def _has_signal(terms: Set[str], compact: str, tokens: Set[str], compacts: Set[str]) -> bool:
        return bool(
            (terms & tokens)
            or any(signal and signal in compact for signal in compacts)
        )

    sum_col_pat = re.compile(
        r"""(?is)\bSUM\s*\(\s*
            (?:(?P<qual>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?
            (?P<col>`?[A-Za-z_][A-Za-z0-9_]*`?)
            \s*\)""",
        flags=re.X,
    )
    base_cols = _table_cols(base_table)
    inventory_sum_sql = ""
    for m_sum in sum_col_pat.finditer(s):
        qualifier = str(m_sum.group("qual") or "").strip("`").lower()
        col_l = str(m_sum.group("col") or "").strip("`").lower()
        if qualifier and qualifier not in {base_alias.lower(), base_table}:
            continue
        if base_cols and col_l not in base_cols:
            continue
        col_terms, col_compact = _column_semantics(base_table, col_l)
        if _has_signal(col_terms, col_compact, inventory_tokens, inventory_compacts):
            inventory_sum_sql = m_sum.group(0)
            break
    if not inventory_sum_sql:
        return sql

    child_candidates: List[Tuple[int, str, str, str]] = []
    for child_table_raw, mapping in (fk_raw or {}).items():
        child_table = str(child_table_raw or "").strip().lower()
        for fk_col_raw, target_raw in (mapping or {}).items():
            fk_col = str(fk_col_raw or "").strip().lower()
            target = str(target_raw or "").strip().lower()
            if target != base_table or not fk_col:
                continue
            for col_l in _table_cols(child_table):
                col_terms, col_compact = _column_semantics(child_table, col_l)
                has_quantity_signal = _has_signal(
                    col_terms,
                    col_compact,
                    quantity_tokens,
                    quantity_compacts,
                )
                if not has_quantity_signal:
                    continue
                score = 10
                if _has_signal(col_terms, col_compact, quantity_tokens, quantity_compacts):
                    score += 12
                if _has_signal(col_terms, col_compact, order_tokens, order_compacts):
                    score += 8
                if _has_signal(col_terms, col_compact, non_quantity_tokens, non_quantity_compacts):
                    score -= 10
                if _has_signal(col_terms, col_compact, inventory_tokens, inventory_compacts):
                    score -= 6
                child_candidates.append((score, child_table, fk_col, col_l))
    if not child_candidates:
        return sql
    child_candidates.sort(key=lambda item: (-item[0], item[1], item[3]))
    _score, child_table, child_fk_col, qty_col = child_candidates[0]

    base_id = str(get_id_column(base_table) or "").strip("`").lower()
    if not base_id:
        return sql
    child_alias = child_table
    if child_alias.lower() == base_alias.lower():
        child_alias = f"{child_table}_detail"

    new_from = (
        f"{m_from.group('table')} JOIN {child_table} AS {child_alias} "
        f"ON {child_alias}.{_case_col(child_table, child_fk_col)} = {base_alias}.{_case_col(base_table, base_id)}"
    )
    rebuilt = re.sub(
        rf"(?is)\bFROM\s+{re.escape(from_core)}\b",
        f"FROM {new_from}",
        s,
        count=1,
    )
    rebuilt = rebuilt.replace(
        inventory_sum_sql,
        f"SUM({child_alias}.{_case_col(child_table, qty_col)})",
        1,
    )
    rebuilt = re.sub(
        rf"(?is)\bCOUNT\s*\(\s*DISTINCT\s+`?{re.escape(base_id)}`?\s*\)",
        f"COUNT(DISTINCT {base_alias}.{_case_col(base_table, base_id)})",
        rebuilt,
    )
    return rebuilt


def _rewrite_existence_sum_to_distinct_entity_count(
    sql: str,
    question: str,
    ctx: str = "",
) -> str:
    """
    Repair grouped existence metrics that are written as SUM(boolean joined
    row predicates), which can overcount because of join fanout.

    Example near-miss shape:
      COUNT(base.entity_id) AS total_entities,
      SUM(joined.metric_col IS NOT NULL) AS entities_with_related_rows
      SUM(joined.metric_col > 0) AS entities_with_related_rows

    Rewritten shape:
      COUNT(DISTINCT CASE WHEN joined.metric_col IS NOT NULL
                          THEN base.entity_id END)
      COUNT(DISTINCT CASE WHEN joined.metric_col > 0
                          THEN base.entity_id END)

    This rewrite stays conservative:
    - grouped SELECT only
    - requires count intent + existence phrasing in question
    - requires one countable base entity key from SELECT
    - rewrites only SUM(boolean existence) terms that reference a different joined alias
    """
    s = (sql or "").strip()
    if not s or not question:
        return sql
    if "group by" not in s.lower() or "sum" not in s.lower() or "count" not in s.lower():
        return sql

    q = str(question or "").lower()
    has_count_intent = bool(
        re.search(r"\b(?:how\s+many|number\s+of|count)\b", q, flags=re.I)
    )
    has_existence_phrase = bool(
        re.search(r"\b(?:ever|at\s+least\s+once|at\s+least\s+one(?:\s+time)?)\b", q, flags=re.I)
        or re.search(r"\b(?:who|that|which)\s+(?:have|has)\s+(?:ever\s+)?(?:been\s+)?[a-z_]+\b", q, flags=re.I)
    )
    has_existence_count_metric_phrase = any_phrase_in_text(q, existence_count_metric_phrases())
    has_reference_phrase = bool(
        re.search(r"\b(?:of|among)\s+(?:those|the)\b", q, flags=re.I)
    )
    if not has_count_intent or not has_existence_phrase:
        return sql
    if not (has_reference_phrase or _question_wants_include_zero(question, ctx)):
        return sql

    parsed = _parse_select_from_groupby(s)
    if not parsed:
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if not from_core or "join" not in from_core.lower():
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if not alias_to_table:
        return sql
    alias_to_table_l = {
        str(k or "").strip("`").lower(): str(v or "").strip("`").lower()
        for k, v in alias_to_table.items()
        if str(k or "").strip() and str(v or "").strip()
    }
    if len(alias_to_table_l) < 2:
        return sql

    select_items = _split_top_level_commas(parsed.get("select", ""))
    if not select_items:
        return sql

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m:
            return (item or "").strip(), None
        return (m.group(1) or "").strip(), (m.group(2) or "").strip()

    count_ref_pat = re.compile(
        r"""(?is)\bCOUNT\s*\(\s*(?:DISTINCT\s+)?(?:(?P<alias>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<col>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)"""
    )

    count_candidates: List[Tuple[int, str, str]] = []
    for item in select_items:
        expr, _out_alias = _split_expr_alias(item)
        for m_cnt in count_ref_pat.finditer(expr):
            alias_raw = (m_cnt.group("alias") or "").strip("`").lower()
            col_raw = (m_cnt.group("col") or "").strip("`")
            col_l = col_raw.lower()
            if not col_l:
                continue
            if not alias_raw:
                continue
            if alias_raw not in alias_to_table_l:
                continue
            table_l = alias_to_table_l.get(alias_raw, "")
            score = 0
            try:
                id_col = str(get_id_column(table_l) or "").strip("`").lower()
            except Exception:
                id_col = ""
            if id_col and id_col == col_l:
                score += 4
            if col_l.endswith(("id", "number", "code", "key")):
                score += 2
            if table_l:
                score += 1
            count_candidates.append((score, alias_raw, col_raw))

    if not count_candidates:
        return sql
    count_candidates.sort(key=lambda x: (-x[0], x[1], x[2]))
    base_alias, base_col = count_candidates[0][1], count_candidates[0][2]

    nonnull_inline_pat = re.compile(
        r"""(?is)^\s*(?:(?P<a1>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<c1>`?[A-Za-z_][A-Za-z0-9_]*`?)\s+IS\s+NOT\s+NULL\s*$"""
    )
    nonnull_not_pat = re.compile(
        r"""(?is)^\s*NOT\s+(?:(?P<a2>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<c2>`?[A-Za-z_][A-Za-z0-9_]*`?)\s+IS\s+NULL\s*$"""
    )
    sum_case_pat = re.compile(
        r"""(?is)^\s*SUM\s*\(\s*CASE\s+WHEN\s+(?P<cond>.+?)\s+THEN\s+1\s+ELSE\s+0\s+END\s*\)\s*$"""
    )
    sum_direct_pat = re.compile(
        r"""(?is)^\s*SUM\s*\(\s*(?P<body>.+?)\s*\)\s*$"""
    )
    simple_qualified_col_pat = re.compile(
        r"""(?is)^\s*(?:(?P<alias>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<col>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*$"""
    )

    comparison_token_pat = re.compile(
        r"""(?is)(?:>=|<=|<>|!=|=|<|>|\bLIKE\b|\bREGEXP\b|\bRLIKE\b|\bBETWEEN\b|\bIN\s*\()"""
    )
    qualified_alias_pat = re.compile(
        r"""(?is)\b(`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?"""
    )

    join_eq_pat = re.compile(
        r"""(?is)\b`?(?P<a1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<c1>[A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?(?P<a2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<c2>[A-Za-z_][A-Za-z0-9_]*)`?"""
    )

    def _support_presence_condition(support_alias: str) -> str:
        support_l = str(support_alias or "").strip("`").lower()
        if not support_l:
            return ""
        for m_eq in join_eq_pat.finditer(from_core):
            a1 = (m_eq.group("a1") or "").lower()
            a2 = (m_eq.group("a2") or "").lower()
            c1 = (m_eq.group("c1") or "").strip("`")
            c2 = (m_eq.group("c2") or "").strip("`")
            if a1 == support_l and a2 == base_alias:
                return f"{support_alias}.{c1} IS NOT NULL"
            if a2 == support_l and a1 == base_alias:
                return f"{support_alias}.{c2} IS NOT NULL"
        return ""

    def _condition_has_requested_literal(cond: str) -> bool:
        cond_s = str(cond or "")
        numbers = re.findall(r"\b\d+(?:\.\d+)?\b", cond_s)
        quoted = re.findall(r"'([^']*)'|\"([^\"]*)\"", cond_s)
        literals = list(numbers)
        literals.extend(next((part for part in pair if part), "") for pair in quoted)
        literals = [lit for lit in literals if str(lit).strip()]
        if not literals:
            return False
        q_l = str(question or "").lower()
        return all(str(lit).strip().lower() in q_l for lit in literals)

    def _extract_support_condition(sum_expr: str) -> Optional[Tuple[str, str]]:
        text = (sum_expr or "").strip()
        m_case = sum_case_pat.match(text)
        if m_case:
            cond = (m_case.group("cond") or "").strip()
            m_inline = nonnull_inline_pat.match(cond)
            if m_inline:
                alias = (m_inline.group("a1") or "").strip("`").lower()
                col = (m_inline.group("c1") or "").strip("`")
                if alias and col:
                    return alias, f"{alias}.{col} IS NOT NULL"
            m_not = nonnull_not_pat.match(cond)
            if m_not:
                alias = (m_not.group("a2") or "").strip("`").lower()
                col = (m_not.group("c2") or "").strip("`")
                if alias and col:
                    return alias, f"{alias}.{col} IS NOT NULL"
            aliases = {
                str(a or "").strip("`").lower()
                for a in qualified_alias_pat.findall(cond)
                if str(a or "").strip()
            }
            if len(aliases) == 1:
                alias = next(iter(aliases))
                if alias in alias_to_table_l and comparison_token_pat.search(cond):
                    return alias, cond
            return None

        m_direct = sum_direct_pat.match(text)
        if not m_direct:
            return None
        body = (m_direct.group("body") or "").strip()
        m_inline = nonnull_inline_pat.match(body)
        if m_inline:
            alias = (m_inline.group("a1") or "").strip("`").lower()
            col = (m_inline.group("c1") or "").strip("`")
            if alias and col:
                return alias, f"{alias}.{col} IS NOT NULL"
            return None
        m_not = nonnull_not_pat.match(body)
        if m_not:
            alias = (m_not.group("a2") or "").strip("`").lower()
            col = (m_not.group("c2") or "").strip("`")
            if alias and col:
                return alias, f"{alias}.{col} IS NOT NULL"
        m_simple = simple_qualified_col_pat.match(body)
        if m_simple and has_existence_count_metric_phrase:
            alias = (m_simple.group("alias") or "").strip("`").lower()
            col = (m_simple.group("col") or "").strip("`")
            if alias and col and alias in alias_to_table_l and alias != base_alias:
                table_l = alias_to_table_l.get(alias, "")
                role = str(get_column_role(table_l, col) or "").strip().lower() if table_l else ""
                if role in {"measure", "metric", "amount", "quantity", "price", "value"}:
                    return alias, f"{alias}.{col} IS NOT NULL"
        aliases = {
            str(a or "").strip("`").lower()
            for a in qualified_alias_pat.findall(body)
            if str(a or "").strip()
        }
        if len(aliases) == 1:
            alias = next(iter(aliases))
            if alias in alias_to_table_l and comparison_token_pat.search(body):
                return alias, body
        return None

    changed = False
    existence_metric_rewritten = False
    rebuilt_items: List[str] = []
    for item in select_items:
        expr, out_alias = _split_expr_alias(item)
        support = _extract_support_condition(expr)
        if not support:
            rebuilt_items.append(item.strip())
            continue

        support_alias, cond = support
        if support_alias == base_alias:
            rebuilt_items.append(item.strip())
            continue
        if support_alias not in alias_to_table_l:
            rebuilt_items.append(item.strip())
            continue

        presence_cond = _support_presence_condition(support_alias)
        if presence_cond and not _condition_has_requested_literal(cond):
            cond = presence_cond

        new_expr = (
            f"COUNT(DISTINCT CASE WHEN {cond} THEN {base_alias}.{base_col} END)"
        )
        rebuilt_items.append(f"{new_expr} AS {out_alias}" if out_alias else new_expr)
        changed = True
        existence_metric_rewritten = True

    if not changed:
        return sql

    # If the question asks for the total number of the same entities and then
    # "the number of those entities" that satisfy an existence condition,
    # plain COUNT(base_id) over the supporting join will overcount on fanout.
    if existence_metric_rewritten and (has_reference_phrase or _question_wants_include_zero(question, ctx)):
        count_expr_pat = re.compile(
            r"""(?is)^\s*COUNT\s*\(\s*(?P<distinct>DISTINCT\s+)?(?:(?P<alias>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<col>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)\s*$"""
        )
        deduped_items: List[str] = []
        count_changed = False
        for item in rebuilt_items:
            expr, out_alias = _split_expr_alias(item)
            m_count = count_expr_pat.match(expr)
            if not m_count:
                deduped_items.append(item.strip())
                continue
            if (m_count.group("distinct") or "").strip():
                deduped_items.append(item.strip())
                continue
            count_alias = (m_count.group("alias") or "").strip("`").lower()
            count_col = (m_count.group("col") or "").strip("`")
            if count_alias != base_alias or count_col.lower() != base_col.lower():
                deduped_items.append(item.strip())
                continue
            new_expr = f"COUNT(DISTINCT {base_alias}.{base_col})"
            deduped_items.append(f"{new_expr} AS {out_alias}" if out_alias else new_expr)
            count_changed = True
        if count_changed:
            rebuilt_items = deduped_items
            changed = True

    rebuilt = f"SELECT {', '.join(rebuilt_items)} FROM {from_core}"
    if (parsed.get("where") or "").strip():
        rebuilt += f" {parsed['where'].strip()}"
    rebuilt += f" GROUP BY {parsed['groupby'].strip()}"
    if (parsed.get("having") or "").strip():
        rebuilt += f" {parsed['having'].strip()}"
    if (parsed.get("tail") or "").strip():
        rebuilt += f" {parsed['tail'].strip()}"
    if s.endswith(";"):
        rebuilt += ";"
    return rebuilt


def _prefer_conditional_count_final_order(sql: str, question: str) -> str:
    """
    If the question explicitly asks to sort by a conditional count, but the SQL
    sorts by the overall row count, prefer the conditional-count alias.

    Conservative shape:
    - flat grouped SELECT with exactly one conditional count metric
    - at least one plain COUNT projection
    - existing top-level ORDER BY starts with the plain count alias
    - question's sort/order phrase mentions "count"
    """
    s = (sql or "").strip()
    if not s or not question or "order by" not in s.lower():
        return sql
    q = str(question or "")
    sort_m = re.search(r"\b(?:sort|order|arrange)\s+(?:by\s+)?(?P<body>[^.]+)", q, flags=re.I)
    if not sort_m:
        return sql
    sort_body = (sort_m.group("body") or "").strip()
    if not re.search(r"\bcount\b", sort_body, flags=re.I):
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    order_pos = _find_top_level_clause(s0, "order by", max(0, from_pos + len("from")))
    if sel_pos != 0 or from_pos < 0 or order_pos < 0:
        return sql

    select_items = _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip())
    if not select_items:
        return sql

    conditional_aliases: List[str] = []
    total_count_aliases: List[str] = []
    dimension_aliases: List[str] = []

    def _is_conditional_count_expr(expr: str) -> bool:
        text = str(expr or "")
        if re.search(
            r"\bSUM\s*\(\s*CASE\s+WHEN\b.+?\bTHEN\s+1\s+ELSE\s+0\s+END\s*\)",
            text,
            flags=re.I | re.S,
        ):
            return True
        return bool(
            re.search(
                r"\bCOUNT\s*\(\s*CASE\s+WHEN\b.+?\bTHEN\s+1(?:\s+ELSE\s+NULL)?\s+END\s*\)",
                text,
                flags=re.I | re.S,
            )
        )

    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        alias_name = (alias or _extract_alias_or_colname(expr) or "").strip("`")
        if not alias_name:
            continue
        if _is_conditional_count_expr(expr):
            conditional_aliases.append(alias_name)
        elif re.match(r"(?is)^\s*COUNT\s*\(", expr):
            total_count_aliases.append(alias_name)
        elif not re.search(r"\b(?:SUM|COUNT|AVG|MIN|MAX)\s*\(", expr, flags=re.I):
            dimension_aliases.append(alias_name)

    if len(conditional_aliases) != 1 or not total_count_aliases:
        return sql

    limit_pos = _find_top_level_clause(s0, "limit", order_pos + len("order by"))
    order_end = limit_pos if limit_pos >= 0 else len(s0)
    order_body = s0[order_pos + len("order by"):order_end].strip()
    order_items = _split_top_level_commas(order_body)
    if not order_items:
        return sql

    def _strip_dir(item: str) -> tuple[str, str]:
        text = (item or "").strip()
        m = re.match(r"(?is)^(.*?)(?:\s+(ASC|DESC))?\s*$", text)
        if not m:
            return text, ""
        return (m.group(1) or "").strip(), (m.group(2) or "").upper()

    first_expr, first_dir = _strip_dir(order_items[0])
    first_key = first_expr.strip("`").split(".")[-1].lower()
    if first_key not in {a.lower() for a in total_count_aliases}:
        return sql

    cond_alias = conditional_aliases[0]
    direction = first_dir or ("DESC" if re.search(r"\b(?:descending|desc|highest|largest|most|reverse\s+alphabetical|reversed\s+alphabetical|reverse)\b", sort_body, flags=re.I) else "ASC")
    new_items = [f"{cond_alias} {direction}"]

    # Preserve or add the requested secondary dimension order when it is
    # already projected, e.g. "then country".
    existing_tail = order_items[1:]
    if existing_tail:
        new_items.extend(item.strip() for item in existing_tail if item.strip())
    else:
        for dim in dimension_aliases:
            dim_phrase = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", dim).replace("_", " ").lower()
            dim_tokens = [tok for tok in re.findall(r"[a-z0-9]+", dim_phrase) if len(tok) > 1]
            if dim_tokens and all(re.search(rf"\b{re.escape(tok)}s?\b", sort_body, flags=re.I) for tok in dim_tokens):
                new_items.append(f"{dim} ASC")
                break

    rebuilt = s0[:order_pos].rstrip() + " ORDER BY " + ", ".join(new_items)
    if limit_pos >= 0:
        rebuilt += " " + s0[limit_pos:].lstrip()
    return rebuilt + trailing


def _prefer_requested_count_desc_final_order(sql: str, question: str) -> str:
    """
    When the prompt asks for groups with more of the counted entity first,
    make the projected count metric the primary DESC order key while keeping
    existing ORDER BY items as tie-breakers.
    """
    s = (sql or "").strip()
    if not s or not question:
        return sql
    if not re.search(r"\bGROUP\s+BY\b", s, flags=re.I) or not re.search(r"\bORDER\s+BY\b", s, flags=re.I):
        return sql
    if not re.search(r"\bCOUNT\s*\(", s, flags=re.I):
        return sql

    q = str(question or "").strip().lower()
    if not re.search(r"\b(?:sort|sorted|order|ordered|arrange|arranged)\b", q, flags=re.I):
        return sql
    cue_terms = [str(t).strip().lower() for t in final_order_metric_desc_cues() if str(t).strip()]
    first_terms = [str(t).strip().lower() for t in final_order_first_position_terms() if str(t).strip()]
    if not cue_terms or not first_terms:
        return sql
    cue_alt = "|".join(re.escape(t).replace(r"\ ", r"\s+") for t in sorted(cue_terms, key=len, reverse=True))
    first_alt = "|".join(re.escape(t).replace(r"\ ", r"\s+") for t in sorted(first_terms, key=len, reverse=True))
    if not re.search(rf"\b(?:{cue_alt})\b(?:[\s,;:()'\"-]+\w+){{0,8}}[\s,;:()'\"-]+\b(?:{first_alt})\b", q, flags=re.I):
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    order_pos = _find_top_level_clause(s0, "order by", max(0, from_pos + len("from")))
    if sel_pos != 0 or from_pos < 0 or order_pos < 0:
        return sql

    select_items = _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip())
    count_refs: List[str] = []
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        if not re.match(r"(?is)^\s*COUNT\s*\(", expr or ""):
            continue
        count_refs.append((alias or expr).strip().strip("`"))
    count_refs = list(dict.fromkeys(ref for ref in count_refs if ref))
    if len(count_refs) != 1:
        return sql

    limit_pos = _find_top_level_clause(s0, "limit", order_pos + len("order by"))
    order_end = limit_pos if limit_pos >= 0 else len(s0)
    order_items = _split_top_level_commas(s0[order_pos + len("order by"):order_end].strip())
    if not order_items:
        return sql

    count_ref = count_refs[0]
    count_key = count_ref.strip("`").split(".")[-1].lower()

    def _strip_order_key(item: str) -> str:
        m = re.match(r"(?is)^(.*?)(?:\s+(?:ASC|DESC))?\s*$", (item or "").strip())
        return ((m.group(1) if m else item) or "").strip().strip("`").split(".")[-1].lower()

    if _strip_order_key(order_items[0]) == count_key:
        first_rewritten = re.sub(r"\s+\b(?:ASC|DESC)\b\s*$", "", order_items[0].strip(), flags=re.I).rstrip()
        first_rewritten = f"{first_rewritten} DESC"
        if first_rewritten == order_items[0].strip():
            return sql
        rebuilt = s0[:order_pos].rstrip() + " ORDER BY " + ", ".join([first_rewritten] + [item.strip() for item in order_items[1:]])
        if limit_pos >= 0:
            rebuilt += " " + s0[limit_pos:].lstrip()
        return rebuilt.rstrip() + trailing

    def _order_ref(ref: str) -> str:
        raw = str(ref or "").strip().strip("`")
        if re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", raw):
            return raw
        return ref

    new_items = [f"{_order_ref(count_ref)} DESC"]
    new_items.extend(item.strip() for item in order_items if _strip_order_key(item) != count_key)
    rebuilt = s0[:order_pos].rstrip() + " ORDER BY " + ", ".join(new_items)
    if limit_pos >= 0:
        rebuilt += " " + s0[limit_pos:].lstrip()
    return rebuilt.rstrip() + trailing


def _drop_unrequested_schema_named_count_outputs(sql: str, question: str, ctx: str = "") -> str:
    """
    Remove count projections aliased as a real schema column when the question
    did not ask to count that column. This catches hallucinated helper metrics
    such as COUNT(*) AS requiredDate while preserving legitimate total counts.
    """
    s = (sql or "").strip()
    if not s or "group by" not in s.lower() or "count" not in s.lower():
        return sql

    allowed = _parse_allowed_identifiers(ctx or "")
    schema_cols = {
        str(col or "").strip().lower()
        for cols in allowed.values()
        for col in cols
        if str(col or "").strip()
    }
    if not schema_cols:
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql

    select_part = s0[sel_pos + len("select"):from_pos].strip()
    select_items = _split_top_level_commas(select_part)
    if len(select_items) < 2:
        return sql

    count_aliases: List[tuple[str, str, str]] = []
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        if not alias or not re.search(r"\bCOUNT\s*\(", expr, flags=re.I):
            continue
        count_aliases.append((item, expr, alias))

    if len(count_aliases) < 2:
        return sql

    def _alias_metric_like(alias: str) -> bool:
        a = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(alias or "")).replace("_", " ").lower()
        return bool(re.search(r"\b(?:count|total|number|num|rows?|records?)\b", a, flags=re.I))

    if not any(_alias_metric_like(alias) for _, _, alias in count_aliases):
        return sql

    def _question_explicitly_counts_alias(alias: str) -> bool:
        phrase = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(alias or ""))
        phrase = re.sub(r"[_`]+", " ", phrase).strip().lower()
        if not phrase:
            return False
        phrase_pat = re.escape(phrase).replace(r"\ ", r"\s+")
        q = str(question or "").lower()
        return bool(
            re.search(rf"\b(?:count|counts|counting|number\s+of|how\s+many)\s+(?:rows?\s+with\s+|records?\s+with\s+)?{phrase_pat}\b", q, flags=re.I)
            or re.search(rf"\b{phrase_pat}\s+(?:count|counts|total)\b", q, flags=re.I)
        )

    drop_items: Set[str] = set()
    for item, _expr, alias in count_aliases:
        alias_l = alias.strip("`").lower()
        if alias_l in schema_cols and not _alias_metric_like(alias) and not _question_explicitly_counts_alias(alias):
            drop_items.add(item)

    if not drop_items:
        return sql

    kept = [item for item in select_items if item not in drop_items]
    if len(kept) == len(select_items) or not kept:
        return sql
    return "SELECT " + ", ".join(kept) + " " + s0[from_pos:].lstrip() + trailing


def _normalize_timestampdiff_day_to_datediff(sql: str) -> str:
    """Use DATEDIFF(end, start) for day gaps to avoid dialect/validator noise."""
    if not sql or "timestampdiff" not in sql.lower():
        return sql

    simple_ref = r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?"
    return re.sub(
        rf"\bTIMESTAMPDIFF\s*\(\s*DAY\s*,\s*(?P<start>{simple_ref})\s*,\s*(?P<end>{simple_ref})\s*\)",
        lambda m: f"DATEDIFF({m.group('end').strip()}, {m.group('start').strip()})",
        sql,
        flags=re.I,
    )


def _drop_unrequested_current_date_filters(sql: str, question: str) -> str:
    """Remove CURRENT_DATE/CURDATE/NOW filters unless the question asks for current-time scope."""
    s = (sql or "").strip()
    if not s or not re.search(r"\b(?:CURRENT_DATE|CURRENT_TIMESTAMP|CURDATE|NOW)\s*(?:\(\s*\))?", s, flags=re.I):
        return sql

    q = str(question or "").lower()
    if re.search(r"\b(?:current|today|now|this\s+(?:year|month|day|week)|latest|most\s+recent|newest|recent)\b", q, flags=re.I):
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    m = re.match(r"(?is)^(?P<head>.*?\bFROM\b.*?)(?P<tail>\s+WHERE\b.*)$", s0)
    if not m:
        return sql

    head = (m.group("head") or "").rstrip()
    tail = (m.group("tail") or "").strip()
    where_body, rest = _split_where_and_rest(" " + tail)
    if not where_body or _has_top_level_or(where_body):
        return sql

    conds = _split_top_level_and(where_body)
    if not conds:
        return sql
    keep = [
        cond.strip()
        for cond in conds
        if not re.search(r"\b(?:CURRENT_DATE|CURRENT_TIMESTAMP|CURDATE|NOW)\s*(?:\(\s*\))?", cond, flags=re.I)
    ]
    if len(keep) == len(conds):
        return sql

    rebuilt = head
    if keep:
        rebuilt += " WHERE " + " AND ".join(keep)
    if rest:
        rebuilt += " " + rest.strip()
    rebuilt = re.sub(r"\s{2,}", " ", rebuilt).strip()
    return rebuilt + trailing


def _rewrite_null_conditional_count_to_date_comparison(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair conditional counts where the question asks how many rows have one
    date later/earlier than another date, but the draft counts a NULL/non-NULL
    check on only one side.

    This is schema-driven:
    - candidate columns come from request-scoped schema context, with schema
      analyzer fallback for active SQL tables
    - only date/time columns are considered
    - the comparison direction comes from the question text
    - no table, column, literal, or question-id is encoded
    """
    s = (sql or "").strip()
    if not s or not question or "case" not in s.lower() or " null" not in s.lower():
        return sql

    q = str(question or "").lower()
    if not re.search(r"\b(?:how\s+many|number\s+of|count)\b", q, flags=re.I):
        return sql
    if not re.search(r"\b(?:earlier|before|later|after)\b", q, flags=re.I):
        return sql

    def _active_table_columns() -> Dict[str, Set[str]]:
        allowed = _parse_allowed_identifiers(ctx or "")
        if allowed:
            return {
                str(t or "").strip("`").lower(): {str(c or "").strip("`") for c in cols if str(c or "").strip()}
                for t, cols in allowed.items()
                if str(t or "").strip()
            }

        tables = {
            str(m.group(1) or "").strip("`").split(".")[-1].lower()
            for m in re.finditer(r"\b(?:FROM|JOIN)\s+`?([A-Za-z_][A-Za-z0-9_]*)`?", s, flags=re.I)
        }
        if not tables:
            return {}
        try:
            analyzer = get_schema_analyzer()
        except Exception:
            analyzer = None
        if analyzer is None:
            return {}
        out: Dict[str, Set[str]] = {}
        for table_l in tables:
            try:
                out[table_l] = {str(c or "").strip("`") for c in analyzer.get_table_columns(table_l) or [] if str(c or "").strip()}
            except Exception:
                continue
        return out

    def _is_temporal_column(table_name: str, col_name: str) -> bool:
        try:
            dtype = str(get_column_datatype(table_name, col_name) or "").upper()
        except Exception:
            dtype = ""
        if any(tok in dtype for tok in ("DATE", "TIME", "YEAR", "TIMESTAMP")):
            return True
        c = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_name or "")).replace("_", " ").lower()
        return bool(re.search(r"\b(?:date|time|timestamp|year)\b", c))

    table_cols = _active_table_columns()
    date_cols: List[Tuple[str, str]] = []
    for table_l, cols in table_cols.items():
        for col in cols:
            if _is_temporal_column(table_l, col):
                date_cols.append((table_l, col))
    if len(date_cols) < 2:
        return sql

    def _col_variants(col: str) -> List[str]:
        raw = str(col or "").strip("`")
        spaced = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw).replace("_", " ").replace("-", " ").lower()
        spaced = re.sub(r"\s+", " ", spaced).strip()
        compact = re.sub(r"[^a-z0-9]+", "", spaced)
        variants = {raw.lower(), spaced, compact}
        for suffix in (" date", " time", " timestamp", " year"):
            if spaced.endswith(suffix):
                base = spaced[: -len(suffix)].strip()
                if len(base) >= 3:
                    variants.add(base)
        return [v for v in variants if v]

    variant_cache = {col: _col_variants(col) for _table, col in date_cols}

    def _variant_pat(variant: str) -> str:
        pat = re.escape(variant)
        return pat.replace(r"\ ", r"\s+")

    direct_hits: List[Tuple[int, str, str, str]] = []
    for _t1, c1 in date_cols:
        for _t2, c2 in date_cols:
            if c1.lower() == c2.lower():
                continue
            for v1 in variant_cache.get(c1, []):
                for v2 in variant_cache.get(c2, []):
                    pattern = (
                        rf"\b{_variant_pat(v1)}\b\s+"
                        rf"(?:is\s+|was\s+|were\s+|being\s+)?"
                        rf"(?P<cmp>earlier|before|later|after)\s+"
                        rf"(?:than\s+)?(?:the\s+)?\b{_variant_pat(v2)}\b"
                    )
                    for m in re.finditer(pattern, q, flags=re.I):
                        prefix = q[max(0, m.start() - 128):m.start()]
                        if not re.search(r"\b(?:how\s+many|number\s+of|count)\b", prefix, flags=re.I):
                            continue
                        cmp_text = m.group("cmp").lower()
                        op = "<" if cmp_text in {"earlier", "before"} else ">"
                        direct_hits.append((m.start(), c1, op, c2))
    if not direct_hits:
        return sql

    direct_hits.sort(key=lambda item: item[0])
    _pos, left_col, op, right_col = direct_hits[0]

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql

    select_items = _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip())
    if not select_items:
        return sql

    simple_ref = r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?"
    case_re = re.compile(
        rf"""(?is)^\s*SUM\s*\(\s*CASE\s+WHEN\s+(?P<cond>.+?)\s+
            THEN\s+1\s+ELSE\s+0\s+END\s*\)\s*$""",
        flags=re.X,
    )

    def _expr_for_col(cond: str, col: str) -> Optional[str]:
        col_pat = re.escape(str(col or "").strip("`"))
        m = re.search(rf"(?P<expr>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?{col_pat}`?)\b", cond, flags=re.I)
        return (m.group("expr") or "").strip() if m else None

    def _with_matching_qualifier(left_expr: str, right_col_name: str) -> str:
        m = re.match(r"(?is)^\s*(?P<prefix>`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)", left_expr or "")
        prefix = m.group("prefix") if m else ""
        return f"{prefix}{right_col_name}" if prefix else right_col_name

    changed = False
    rebuilt_items: List[str] = []
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        m_case = case_re.match(expr)
        if not m_case:
            rebuilt_items.append(item.strip())
            continue

        cond = (m_case.group("cond") or "").strip()
        left_expr = _expr_for_col(cond, left_col)
        if not left_expr:
            rebuilt_items.append(item.strip())
            continue
        right_expr = _expr_for_col(cond, right_col) or _with_matching_qualifier(left_expr, right_col)

        left_col_pat = re.escape(left_col)
        null_check_pat = (
            rf"(?:{simple_ref}\s+IS\s+(?:NOT\s+)?NULL|NOT\s+{simple_ref}\s+IS\s+NULL)"
        )
        if not re.search(left_col_pat, cond, flags=re.I) or not re.search(null_check_pat, cond, flags=re.I):
            rebuilt_items.append(item.strip())
            continue
        if re.search(rf"{re.escape(left_col)}\s*(?:<|>)\s*{re.escape(right_col)}", cond, flags=re.I):
            rebuilt_items.append(item.strip())
            continue

        new_expr = f"SUM(CASE WHEN {left_expr} {op} {right_expr} THEN 1 ELSE 0 END)"
        rebuilt_items.append(f"{new_expr} AS {alias}" if alias else new_expr)
        changed = True

    if not changed:
        return sql
    return "SELECT " + ", ".join(rebuilt_items) + " " + s0[from_pos:].lstrip() + trailing


def _rewrite_comparison_count_metrics(sql: str, question: str, ctx: str = "") -> str:
    """
    Convert a hallucinated plain COUNT into a conditional count when the
    question explicitly asks how many rows satisfy colA <op> colB.
    """
    s = (sql or "").strip()
    if not s or "count" not in s.lower() or not question:
        return sql

    q = str(question or "").lower()
    if not re.search(r"\b(?:how\s+many|number\s+of|count)\b", q, flags=re.I):
        return sql
    if not re.search(r"\b(?:earlier|before|later|after|greater\s+than|less\s+than|above|below)\b", q, flags=re.I):
        return sql

    allowed = _parse_allowed_identifiers(ctx or "")
    cols = sorted({str(c or "").strip() for cs in allowed.values() for c in cs if str(c or "").strip()}, key=len, reverse=True)
    if len(cols) < 2:
        return sql

    def _name_variants(col: str) -> List[str]:
        raw = str(col or "").strip("`")
        spaced = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw).replace("_", " ").lower()
        compact = re.sub(r"[^a-z0-9]+", "", spaced)
        return [v for v in {raw.lower(), spaced, compact} if v]

    variant_cache = {col: _name_variants(col) for col in cols}
    chosen: Optional[tuple[str, str, str]] = None

    # Prefer an explicit local comparison pattern over global mention distance.
    # This avoids confusing "number of days between A and B" with the actual
    # conditional-count phrase, e.g. "how many rows have C earlier than D".
    direct_hits: List[tuple[int, str, str, str]] = []
    for c1 in cols:
        for c2 in cols:
            if c1 == c2:
                continue
            for v1 in variant_cache.get(c1, []):
                v1_pat = re.escape(v1)
                if " " in v1:
                    v1_pat = v1_pat.replace(r"\ ", r"\s+")
                for v2 in variant_cache.get(c2, []):
                    v2_pat = re.escape(v2)
                    if " " in v2:
                        v2_pat = v2_pat.replace(r"\ ", r"\s+")
                    pattern = (
                        rf"\b{v1_pat}\b\s+(?:is\s+)?"
                        rf"(?P<cmp>earlier|before|later|after|greater\s+than|less\s+than|above|below)"
                        rf"\s+(?:than\s+)?\b{v2_pat}\b"
                    )
                    for m in re.finditer(pattern, q, flags=re.I):
                        prefix = q[max(0, m.start() - 128):m.start()]
                        if not re.search(r"\b(?:how\s+many|number\s+of|count)\b", prefix, flags=re.I):
                            continue
                        cmp_text = m.group("cmp").lower()
                        op = "<" if re.search(r"\b(?:earlier|before|less\s+than|below)\b", cmp_text, flags=re.I) else ">"
                        direct_hits.append((m.start(), c1, op, c2))
    if direct_hits:
        direct_hits.sort(key=lambda item: item[0])
        _, left_direct, op_direct, right_direct = direct_hits[0]
        chosen = (left_direct, op_direct, right_direct)

    mentions: List[tuple[int, int, str]] = []
    for col in cols:
        for variant in variant_cache.get(col, []):
            pat = re.escape(variant)
            if " " in variant:
                pat = pat.replace(r"\ ", r"\s+")
            for m in re.finditer(rf"\b{pat}\b", q, flags=re.I):
                mentions.append((m.start(), m.end(), col))
                break
            if any(item[2] == col for item in mentions):
                break
    mentions.sort()
    if chosen is None:
        if len(mentions) < 2:
            return sql

        for i, (s1, e1, c1) in enumerate(mentions):
            prefix = q[max(0, s1 - 96):s1]
            if not re.search(r"\b(?:how\s+many|number\s+of|count)\b", prefix, flags=re.I):
                continue
            for s2, _e2, c2 in mentions[i + 1:]:
                if c1 == c2:
                    continue
                between = q[e1:s2]
                if re.search(r"\b(?:earlier|before|less\s+than|below)\b", between, flags=re.I):
                    chosen = (c1, "<", c2)
                    break
                if re.search(r"\b(?:later|after|greater\s+than|above)\b", between, flags=re.I):
                    chosen = (c1, ">", c2)
                    break
            if chosen:
                break
    if not chosen:
        return sql

    left_col, op, right_col = chosen
    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql
    select_items = _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip())
    if not select_items:
        return sql

    def _alias_metric_like(alias: str) -> bool:
        a = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(alias or "")).replace("_", " ").lower()
        return bool(re.search(r"\b(?:total|overall|all)\b", a, flags=re.I))

    changed = False
    rebuilt: List[str] = []
    condition_expr = f"{left_col} {op} {right_col}"
    conditional_count = f"SUM(CASE WHEN {condition_expr} THEN 1 ELSE 0 END)"
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        if not alias or not re.match(r"(?is)^\s*COUNT\s*\(\s*(?:\*|`?[A-Za-z_][A-Za-z0-9_]*`?(?:\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`)?)\s*\)\s*$", expr):
            rebuilt.append(item.strip())
            continue
        alias_l = alias.strip("`").lower()
        if _alias_metric_like(alias_l):
            rebuilt.append(item.strip())
            continue
        alias_text = alias_l.replace("_", " ")
        if not (
            any(tok in alias_text for tok in ("earlier", "before", "later", "after", "greater", "less", "above", "below"))
            or left_col.lower().replace("_", "") in alias_l.replace("_", "")
            or right_col.lower().replace("_", "") in alias_l.replace("_", "")
        ):
            rebuilt.append(item.strip())
            continue
        rebuilt.append(f"{conditional_count} AS {alias}")
        changed = True

    if not changed:
        return sql
    return "SELECT " + ", ".join(rebuilt) + " " + s0[from_pos:].lstrip() + trailing


def _rewrite_missing_joined_agg_threshold_filter(sql: str, question: str, ctx: str = "") -> str:
    """
    Add a missing outer filter when the question asks to keep only rows whose
    joined aggregate metric satisfies a numeric threshold, but the SQL already
    computes that metric in a grouped derived table and forgets the final filter.
    """
    if not sql or not question:
        return sql

    threshold_spec = _extract_numeric_aggregate_threshold(
        question,
        require_filter_intent=True,
    )
    if threshold_spec is None:
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql
    if sel.args.get("group") is not None:
        return sql
    if sel.args.get("having") is not None:
        return sql
    if isinstance(sel.args.get("where"), exp.Where):
        return sql

    derived_metric_refs: Set[Tuple[str, str]] = set()
    for join in sel.args.get("joins") or []:
        src = getattr(join, "this", None)
        if not isinstance(src, exp.Subquery):
            continue
        sub_alias = str(src.alias_or_name or "").strip("`").lower()
        sub_sel = getattr(src, "this", None)
        if not sub_alias or not isinstance(sub_sel, exp.Select):
            continue
        if sub_sel.args.get("group") is None:
            continue
        for item in sub_sel.expressions or []:
            if not isinstance(item, exp.Alias):
                continue
            alias_name = str(item.alias_or_name or "").strip("`").lower()
            base = item.this
            if not alias_name or base is None:
                continue
            if base.find(exp.Window):
                continue
            if isinstance(base, exp.AggFunc):
                derived_metric_refs.add((sub_alias, alias_name))

    if not derived_metric_refs:
        return sql

    top_metric_refs: Set[Tuple[str, str]] = set()
    for item in sel.expressions or []:
        base = item.this if isinstance(item, exp.Alias) else item
        if base is None:
            continue
        for col in base.find_all(exp.Column):
            alias_name = str(col.table or "").strip("`").lower()
            col_name = str(col.name or "").strip("`").lower()
            if (alias_name, col_name) in derived_metric_refs:
                top_metric_refs.add((alias_name, col_name))

    if len(top_metric_refs) != 1:
        return sql

    target_alias, target_col = next(iter(top_metric_refs))
    cmp_symbol = {
        "gt": ">",
        "gte": ">=",
        "lt": "<",
        "lte": "<=",
        "eq": "=",
    }.get(threshold_spec[0])
    if not cmp_symbol:
        return sql

    threshold_val = threshold_spec[1]
    threshold_sql = (
        str(int(threshold_val))
        if float(threshold_val).is_integer()
        else str(threshold_val)
    )
    metric_sql = f"{target_alias}.{target_col}"
    try:
        cmp_ast = sqlglot.parse_one(
            f"SELECT 1 WHERE {metric_sql} {cmp_symbol} {threshold_sql}",
            read="mysql",
        )
    except Exception:
        return sql
    cmp_where = cmp_ast.args.get("where")
    if not isinstance(cmp_where, exp.Where):
        return sql

    sel.set("where", exp.Where(this=cmp_where.this))
    out = ast.sql(dialect="mysql")
    out = re.sub(r"\s{2,}", " ", out).strip()
    if out and not out.endswith(";"):
        out += ";"
    return out or sql


def _question_defines_average_as_total_over_count(question: str) -> bool:
    """
    Detect questions that explicitly define an average as:
    total/sum divided by number/count of entities.
    """
    q = (question or "").strip().lower()
    if not q:
        return False

    has_average = any(re.search(pat, q, flags=re.I) for pat in HELPERS_AVERAGE_INTENT_PATTERNS) or bool(
        re.search(r"\b(?:avg|average|mean)\b", q, flags=re.I)
    )
    if not has_average:
        return False

    has_count_denominator = bool(
        re.search(
            r"\b(?:number|count|total\s+number)\s+of\b",
            q,
            flags=re.I,
        )
    )
    if not has_count_denominator:
        return False

    has_ratio_definition = bool(
        re.search(
            r"\b(?:defined\s+as|where)\b[^.]{0,140}\b(?:divided\s+by|over|per)\b",
            q,
            flags=re.I,
        )
        or re.search(
            r"\b(?:divided\s+by|over|per)\s+(?:the\s+)?(?:number|count|total\s+number)\s+of\b",
            q,
            flags=re.I,
        )
    )
    return has_ratio_definition


def _rewrite_average_ratio_to_sum_over_distinct_count(sql: str, question: str, ctx: str = "") -> str:
    """
    Rewrite grouped AVG(child_metric) into SUM(child_metric)/COUNT(DISTINCT parent_id)
    when the question explicitly defines average as total divided by count.

    This is schema/FK driven:
    - finds parent-child relationship from FK joins
    - keeps rewrite conservative to top-level grouped aggregates only
    """
    if not sql or not question:
        return sql
    if not _question_defines_average_as_total_over_count(question):
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql
    if sel.args.get("group") is None:
        return sql
    if len(sel.args.get("joins") or []) < 1:
        return sql

    alias_to_table: Dict[str, str] = {}

    def _register_source(src: Optional["exp.Expression"]) -> None:
        if isinstance(src, exp.Table):
            table_name = str(src.name or "").strip("`").lower()
            if not table_name:
                return
            alias_name = str(src.alias_or_name or table_name).strip("`").lower()
            if alias_name:
                alias_to_table.setdefault(alias_name, table_name)
            alias_to_table.setdefault(table_name, table_name)
        elif isinstance(src, exp.Subquery):
            alias_name = str(src.alias_or_name or "").strip("`").lower()
            if alias_name:
                alias_to_table.setdefault(alias_name, f"__derived__:{alias_name}")

    from_arg = sel.args.get("from") or sel.args.get("from_")
    if from_arg is not None:
        _register_source(getattr(from_arg, "this", None))
    for join in sel.args.get("joins") or []:
        _register_source(getattr(join, "this", None))

    if not alias_to_table:
        return sql

    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, rels in (fk_map_raw or {}).items():
        src_l = str(src or "").strip("`").lower()
        if not src_l:
            continue
        fk_map.setdefault(src_l, {})
        for fk_col, tgt in (rels or {}).items():
            fk_l = str(fk_col or "").strip("`").lower()
            tgt_l = str(tgt or "").strip("`").lower()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    def _is_nested_subquery_expr(node: Optional["exp.Expression"]) -> bool:
        anc = getattr(node, "parent", None)
        while anc is not None:
            if anc is sel:
                return False
            if isinstance(anc, exp.Subquery):
                return True
            anc = getattr(anc, "parent", None)
        return False

    def _is_top_level_expr(node: Optional["exp.Expression"]) -> bool:
        if node is None:
            return False
        return not _is_nested_subquery_expr(node)

    child_to_parents: Dict[str, Set[str]] = {}
    for join in sel.args.get("joins") or []:
        on_expr = join.args.get("on")
        if on_expr is None:
            continue
        for eq in on_expr.find_all(exp.EQ):
            left = getattr(eq, "left", None)
            right = getattr(eq, "right", None)
            if not isinstance(left, exp.Column) or not isinstance(right, exp.Column):
                continue
            lt_alias = str(left.table or "").strip("`").lower()
            rt_alias = str(right.table or "").strip("`").lower()
            lc = str(left.name or "").strip("`").lower()
            rc = str(right.name or "").strip("`").lower()
            if not lt_alias or not rt_alias or not lc or not rc:
                continue
            lt_table = str(alias_to_table.get(lt_alias, lt_alias)).lower()
            rt_table = str(alias_to_table.get(rt_alias, rt_alias)).lower()
            if lt_table.startswith("__derived__:") or rt_table.startswith("__derived__:"):
                continue

            if fk_map.get(lt_table, {}).get(lc) == rt_table:
                child_to_parents.setdefault(lt_alias, set()).add(rt_alias)
            if fk_map.get(rt_table, {}).get(rc) == lt_table:
                child_to_parents.setdefault(rt_alias, set()).add(lt_alias)

    if not child_to_parents:
        return sql

    def _has_parent_path(child_alias: str, parent_alias: str) -> bool:
        child_l = str(child_alias or "").strip().lower()
        parent_l = str(parent_alias or "").strip().lower()
        if not child_l or not parent_l:
            return False
        if child_l == parent_l:
            return True
        seen = {child_l}
        queue = [child_l]
        q_idx = 0
        while q_idx < len(queue):
            cur = queue[q_idx]
            q_idx += 1
            for nxt in child_to_parents.get(cur, set()):
                if nxt == parent_l:
                    return True
                if nxt in seen:
                    continue
                seen.add(nxt)
                queue.append(nxt)
        return False

    def _column_aliases(expr_node: Optional["exp.Expression"]) -> Set[str]:
        aliases: Set[str] = set()
        if expr_node is None:
            return aliases
        for col in expr_node.find_all(exp.Column):
            if _is_nested_subquery_expr(col):
                continue
            alias_name = str(col.table or "").strip("`").lower()
            if alias_name:
                aliases.add(alias_name)
        return aliases

    top_level_avg_nodes: List["exp.Avg"] = [
        avg for avg in sel.find_all(exp.Avg)
        if _is_top_level_expr(avg)
    ]
    top_level_count_nodes: List["exp.Count"] = [
        cnt for cnt in sel.find_all(exp.Count)
        if _is_top_level_expr(cnt)
    ]
    if not top_level_avg_nodes or not top_level_count_nodes:
        return sql

    chosen_avg_alias: Optional[str] = None
    chosen_count_alias: Optional[str] = None
    chosen_count_col: Optional[str] = None
    chosen_avg_nodes: List["exp.Avg"] = []

    for avg_node in top_level_avg_nodes:
        avg_aliases = sorted(_column_aliases(avg_node.this))
        if len(avg_aliases) != 1:
            continue
        avg_alias = avg_aliases[0]
        if avg_alias not in alias_to_table:
            continue

        for count_node in top_level_count_nodes:
            count_cols = [
                col for col in count_node.find_all(exp.Column)
                if not _is_nested_subquery_expr(col)
            ]
            if len(count_cols) != 1:
                continue
            count_col_expr = count_cols[0]
            count_alias = str(count_col_expr.table or "").strip("`").lower()
            count_col = str(count_col_expr.name or "").strip("`")
            if not count_alias or not count_col:
                continue
            if count_alias not in alias_to_table:
                continue
            if avg_alias == count_alias:
                continue
            if not _has_parent_path(avg_alias, count_alias):
                continue

            chosen_avg_alias = avg_alias
            chosen_count_alias = count_alias
            chosen_count_col = count_col
            chosen_avg_nodes = [
                n for n in top_level_avg_nodes
                if _column_aliases(n.this) == {avg_alias}
            ]
            break
        if chosen_avg_alias and chosen_count_alias and chosen_count_col:
            break

    if not chosen_avg_alias or not chosen_count_alias:
        return sql

    count_table = str(alias_to_table.get(chosen_count_alias, "")).lower()
    if not chosen_count_col:
        try:
            chosen_count_col = str(get_id_column(count_table) or "").strip("`")
        except Exception:
            chosen_count_col = ""
    if not chosen_count_col:
        return sql

    def _distinct_count_expr() -> "exp.Count":
        try:
            probe = sqlglot.parse_one(
                f"SELECT COUNT(DISTINCT {chosen_count_alias}.{chosen_count_col})",
                read="mysql",
            )
            parsed_count = probe.find(exp.Count)
            if isinstance(parsed_count, exp.Count):
                return parsed_count.copy()
        except Exception:
            pass
        return exp.Count(
            this=exp.Distinct(
                expressions=[
                    exp.Column(
                        this=exp.Identifier(this=chosen_count_col),
                        table=exp.Identifier(this=chosen_count_alias),
                    )
                ]
            )
        )

    changed = False

    for avg_node in chosen_avg_nodes:
        avg_inner = getattr(avg_node, "this", None)
        if avg_inner is None:
            continue
        ratio_expr = exp.Div(
            this=exp.Sum(this=avg_inner.copy()),
            expression=_distinct_count_expr(),
        )
        avg_node.replace(ratio_expr)
        changed = True

    for count_node in top_level_count_nodes:
        count_aliases = _column_aliases(count_node)
        if count_aliases != {chosen_count_alias}:
            continue
        count_node.replace(_distinct_count_expr())
        changed = True

    if not changed:
        return sql

    out = ast.sql(dialect="mysql")
    out = re.sub(r"\s{2,}", " ", out).strip()
    if sql.strip().endswith(";") and out and not out.endswith(";"):
        out += ";"
    return out or sql


def _rewrite_missing_overall_avg_having(sql: str, question: str, ctx: str = "") -> str:
    """
    Add missing HAVING clause for aggregate-vs-overall-average intent.

    Generic shape repaired:
      SELECT ..., AVG(t.col) ...
      FROM ...
      GROUP BY ...
    ->
      ... HAVING AVG(t.col) >/< (SELECT AVG(x.col) FROM <same-source-table> x ...)
    """
    if not sql or not question:
        return sql
    if not _question_wants_group_avg_vs_overall_avg(question):
        return sql
    if not re.search(r"\bGROUP\s+BY\b", sql, flags=re.I):
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql
    if sel.args.get("group") is None:
        return sql
    existing_having = sel.args.get("having")
    if isinstance(existing_having, exp.Having):
        having_sql = existing_having.sql(dialect="mysql")
        if re.search(r"\bAVG\s*\(", having_sql, flags=re.I) and re.search(r"\bSELECT\s+AVG\s*\(", having_sql, flags=re.I):
            return sql

    # Build top-level alias -> table map.
    alias_to_table: Dict[str, str] = {}

    def _register_source(src: Optional["exp.Expression"]) -> None:
        if isinstance(src, exp.Table):
            table_name = (src.name or "").strip("`").lower()
            if not table_name:
                return
            alias_raw = (src.alias_or_name or src.name or "").strip("`").lower()
            if alias_raw and alias_raw not in alias_to_table:
                alias_to_table[alias_raw] = table_name
            if table_name and table_name not in alias_to_table:
                alias_to_table[table_name] = table_name

    from_arg = sel.args.get("from") or sel.args.get("from_")
    if from_arg is not None and getattr(from_arg, "this", None) is not None:
        _register_source(from_arg.this)
    for j in sel.args.get("joins") or []:
        _register_source(getattr(j, "this", None))

    # Pick aggregate candidate from SELECT projection (prefer AVG(column)).
    avg_candidates: List[Tuple["exp.AggFunc", "exp.Column"]] = []
    for item in sel.expressions or []:
        base = item.this if isinstance(item, exp.Alias) else item
        if base is None:
            continue
        for avg_node in base.find_all(exp.Avg):
            cols = list(avg_node.find_all(exp.Column))
            if len(cols) == 1:
                avg_candidates.append((avg_node, cols[0]))

    avg_node = None
    avg_col = None
    if avg_candidates:
        avg_node, avg_col = avg_candidates[0]

    col_name = str(getattr(avg_col, "name", "") or "").strip("`")
    avg_col_table_alias = str(getattr(avg_col, "table", "") or "").strip("`").lower()
    avg_expr_sql = avg_node.sql(dialect="mysql") if avg_node is not None else ""

    if not avg_node or not col_name:
        avg_match = re.search(
            r"\bAVG\s*\(\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)",
            sql,
            flags=re.I,
        )
        if not avg_match:
            return sql
        avg_col_table_alias = str(avg_match.group(1) or "").strip("`").lower()
        col_name = str(avg_match.group(2) or "").strip("`")
        avg_expr_sql = avg_match.group(0)

    if not col_name:
        return sql

    if avg_col_table_alias:
        baseline_table = alias_to_table.get(avg_col_table_alias, "")
    else:
        # Conservative fallback only when a single real base table can be inferred.
        unique_tables = sorted(set(alias_to_table.values()))
        baseline_table = unique_tables[0] if len(unique_tables) == 1 else ""
    if not baseline_table and avg_col_table_alias:
        alias_map = _parse_from_join_aliases(sql)
        baseline_table = str(
            alias_map.get(avg_col_table_alias)
            or alias_map.get(avg_col_table_alias.lower())
            or ""
        ).strip()
    if not baseline_table:
        return sql

    q = (question or "").lower()
    is_lower = bool(re.search(r"\b(?:lower|less|below|under)\s+than\b", q, flags=re.I))
    is_higher = bool(re.search(r"\b(?:higher|greater|more|above|over)\s+than\b", q, flags=re.I))
    op = "<" if (is_lower and not is_higher) else ">"

    # Preserve explicit null-ignore intent when present in question or WHERE.
    ignore_null = bool(
        re.search(r"\b(?:ignore|excluding?|without)\s+null\b", q, flags=re.I)
        or re.search(r"\bnon[-\s]?null\b", q, flags=re.I)
    )
    where_arg = sel.args.get("where")
    if isinstance(where_arg, exp.Where):
        where_sql = where_arg.sql(dialect="mysql")
        if re.search(
            rf"\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?`?{re.escape(col_name)}`?\s+IS\s+NOT\s+NULL\b",
            where_sql,
            flags=re.I,
        ):
            ignore_null = True

    baseline_sql = f"SELECT AVG(c2.{col_name}) FROM {baseline_table} AS c2"
    if ignore_null:
        baseline_sql += f" WHERE c2.{col_name} IS NOT NULL"
    try:
        baseline_select = sqlglot.parse_one(baseline_sql, read="mysql")
    except Exception:
        return sql
    if not isinstance(baseline_select, exp.Select):
        return sql

    try:
        left_expr = sqlglot.parse_one(
            f"SELECT {avg_expr_sql}",
            read="mysql",
        ).expressions[0]
    except Exception:
        left_expr = avg_node.copy() if avg_node is not None else None
    if left_expr is None:
        return sql
    right_expr = exp.Subquery(this=baseline_select)
    if op == "<":
        cmp_expr = exp.LT(this=left_expr, expression=right_expr)
    else:
        cmp_expr = exp.GT(this=left_expr, expression=right_expr)
    if isinstance(existing_having, exp.Having) and existing_having.this is not None:
        sel.set("having", exp.Having(this=exp.And(this=existing_having.this.copy(), expression=cmp_expr)))
    else:
        sel.set("having", exp.Having(this=cmp_expr))

    out = ast.sql(dialect="mysql")
    out = re.sub(r"\s{2,}", " ", out).strip()
    if out and not out.endswith(";"):
        out += ";"
    return out or sql


def _rewrite_include_zero_winner_row_identifier_source(sql: str, question: str, ctx: str = "") -> str:
    """
    Dynamic include-zero winner-row repair.

    If ROW_NUMBER winner-row query uses LEFT JOIN chain and selects/tie-breaks
    on identifier from nullable joined side, rewrite identifier source to the
    preserved side of the LEFT JOIN equality.
    """
    if not sql or not question:
        return sql
    if "ROW_NUMBER" not in (sql or "").upper():
        return sql
    if not _question_wants_winner_row(question):
        return sql
    if not _question_wants_include_zero(question, ctx):
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    def _norm_key_name(name: str) -> str:
        return re.sub(r"[^a-z0-9]", "", (name or "").lower())

    def _is_identifier_col(name: str) -> bool:
        n = _norm_key_name(name)
        return bool(
            n.endswith("id")
            or n.endswith("number")
            or n.endswith("code")
            or n.endswith("key")
        )

    def _register_sources(sel: "exp.Select") -> Dict[str, str]:
        alias_to_table: Dict[str, str] = {}

        def _register(src: Optional["exp.Expression"]) -> None:
            if isinstance(src, exp.Table):
                table_name = (src.name or "").strip("`").lower()
                if not table_name:
                    return
                alias_raw = (src.alias_or_name or src.name or "").strip("`").lower()
                if alias_raw and alias_raw not in alias_to_table:
                    alias_to_table[alias_raw] = table_name
                if table_name and table_name not in alias_to_table:
                    alias_to_table[table_name] = table_name

        from_arg = sel.args.get("from") or sel.args.get("from_")
        if from_arg is not None and getattr(from_arg, "this", None) is not None:
            _register(from_arg.this)
        for j in sel.args.get("joins") or []:
            _register(getattr(j, "this", None))
        return alias_to_table

    changed = False

    for sel in ast.find_all(exp.Select):
        has_rownum = any(
            isinstance(w.this, exp.RowNumber)
            for w in sel.find_all(exp.Window)
            if isinstance(w, exp.Window)
        )
        if not has_rownum:
            continue

        # Map nullable-side identifier -> preserved-side identifier for LEFT JOIN keys.
        replacement_map: Dict[Tuple[str, str], Tuple[str, str]] = {}

        joins = sel.args.get("joins") or []
        for j in joins:
            side = str(j.args.get("side") or "").upper()
            if side != "LEFT":
                continue
            right_src = getattr(j, "this", None)
            if not isinstance(right_src, exp.Table):
                continue

            right_alias = (right_src.alias_or_name or right_src.name or "").strip("`").lower()
            if not right_alias:
                continue

            on_expr = j.args.get("on")
            if on_expr is None:
                continue

            for eq in on_expr.find_all(exp.EQ):
                left_col = getattr(eq, "left", None)
                right_col = getattr(eq, "right", None)
                if not isinstance(left_col, exp.Column) or not isinstance(right_col, exp.Column):
                    continue

                l_alias = str(left_col.table or "").strip("`").lower()
                r_alias = str(right_col.table or "").strip("`").lower()
                l_name = str(left_col.name or "").strip("`")
                r_name = str(right_col.name or "").strip("`")
                if not l_alias or not r_alias or not l_name or not r_name:
                    continue

                nullable_alias = ""
                nullable_name = ""
                preserved_alias = ""
                preserved_name = ""

                if l_alias == right_alias and r_alias != right_alias:
                    nullable_alias, nullable_name = l_alias, l_name
                    preserved_alias, preserved_name = r_alias, r_name
                elif r_alias == right_alias and l_alias != right_alias:
                    nullable_alias, nullable_name = r_alias, r_name
                    preserved_alias, preserved_name = l_alias, l_name
                else:
                    continue

                if not (_is_identifier_col(nullable_name) and _is_identifier_col(preserved_name)):
                    continue
                if _norm_key_name(nullable_name) != _norm_key_name(preserved_name):
                    continue

                replacement_map[(nullable_alias, nullable_name.lower())] = (
                    preserved_alias,
                    preserved_name,
                )

        if not replacement_map:
            continue

        # Replace projected columns in this SELECT block.
        for item in sel.expressions or []:
            base = item.this if isinstance(item, exp.Alias) else item
            if not isinstance(base, exp.Column):
                continue
            key = (str(base.table or "").strip("`").lower(), str(base.name or "").strip("`").lower())
            repl = replacement_map.get(key)
            if repl is None:
                continue
            new_alias, new_col = repl
            base.set("table", exp.to_identifier(new_alias))
            base.set("this", exp.to_identifier(new_col))
            changed = True

        # Replace ROW_NUMBER ORDER BY identifier source.
        for win in sel.find_all(exp.Window):
            if not isinstance(win.this, exp.RowNumber):
                continue
            order = win.args.get("order")
            if not isinstance(order, exp.Order):
                continue
            for ordered in order.expressions or []:
                c = getattr(ordered, "this", None)
                if not isinstance(c, exp.Column):
                    continue
                key = (str(c.table or "").strip("`").lower(), str(c.name or "").strip("`").lower())
                repl = replacement_map.get(key)
                if repl is None:
                    continue
                new_alias, new_col = repl
                c.set("table", exp.to_identifier(new_alias))
                c.set("this", exp.to_identifier(new_col))
                changed = True

    if not changed:
        return sql

    out = ast.sql(dialect="mysql")
    out = re.sub(r"\s{2,}", " ", out).strip()
    if out and not out.endswith(";"):
        out += ";"
    return out or sql


def _rewrite_joined_ranked_subquery_to_outer_winner(sql: str, question: str, ctx: str = "") -> str:
    """
    Lift a child-ranked LEFT JOIN subquery into a proper outer winner-row shape.

    Near-miss repaired:
      parent
      LEFT JOIN bridge
      LEFT JOIN (
        SELECT child_fk, ..., ROW_NUMBER() OVER (PARTITION BY child_fk ORDER BY ...) AS rn
        FROM child
      ) child_ranked
        ON child_ranked.child_fk = bridge.child_fk
       AND child_ranked.rn = 1

    This shape picks one child row per child key, not one winning row per
    preserved parent entity. The repair inlines the child table back into the
    LEFT JOIN chain and ranks at the parent grain instead.
    """
    if not sql or not question:
        return sql
    if not _question_wants_winner_row(question):
        return sql
    if not _question_wants_include_zero(question, ctx):
        return sql
    if re.search(r"\bWHERE\b[^;]*\brn\s*=\s*\d+\b", sql, flags=re.I | re.S):
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    sel = ast if isinstance(ast, exp.Select) else ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql
    if sel.args.get("group") is not None or sel.args.get("having") is not None:
        return sql
    if sel.args.get("limit") is not None:
        return sql

    from_arg = sel.args.get("from") or sel.args.get("from_")
    base_src = getattr(from_arg, "this", None) if from_arg is not None else None
    if not isinstance(base_src, exp.Table):
        return sql

    base_table = (base_src.name or "").strip("`").lower()
    base_alias = (base_src.alias_or_name or base_src.name or "").strip("`")
    base_id_col = (get_id_column(base_table) or "").strip()
    if not base_table or not base_alias or not base_id_col:
        return sql

    def _flatten_and(node):
        if isinstance(node, exp.And):
            return _flatten_and(node.this) + _flatten_and(node.expression)
        return [node]

    def _combine_and(nodes):
        if not nodes:
            return None
        cur = nodes[0]
        for nxt in nodes[1:]:
            cur = exp.And(this=cur, expression=nxt)
        return cur

    def _norm_expr(expr_node: "exp.Expression") -> str:
        return re.sub(r"\s+", " ", expr_node.sql(dialect="mysql").strip().lower())

    def _norm_key_name(name: str) -> str:
        return re.sub(r"[^a-z0-9]", "", (name or "").lower())

    def _is_identifier_col(name: str) -> bool:
        n = _norm_key_name(name)
        return bool(
            n.endswith("id")
            or n.endswith("number")
            or n.endswith("code")
            or n.endswith("key")
        )

    def _expr_output_alias(item: "exp.Expression") -> Optional[str]:
        if isinstance(item, exp.Alias):
            alias = str(item.alias or "").strip("`")
            return alias or None
        if isinstance(item, exp.Column):
            name = str(item.name or "").strip("`")
            return name or None
        return None

    joins = list(sel.args.get("joins") or [])
    if not joins:
        return sql

    for join_idx, join_node in enumerate(joins):
        side = str(join_node.args.get("side") or "").upper()
        right_src = getattr(join_node, "this", None)
        if side != "LEFT" or not isinstance(right_src, exp.Subquery):
            continue
        if not isinstance(right_src.this, exp.Select):
            continue

        sub_sel = right_src.this
        if sub_sel.args.get("group") is not None or sub_sel.args.get("having") is not None:
            continue
        if sub_sel.args.get("limit") is not None:
            continue
        if sub_sel.args.get("joins"):
            continue

        sub_alias = (right_src.alias_or_name or "").strip("`")
        if not sub_alias:
            continue

        sub_from = sub_sel.args.get("from") or sub_sel.args.get("from_")
        child_src = getattr(sub_from, "this", None) if sub_from is not None else None
        if not isinstance(child_src, exp.Table):
            continue

        child_table = (child_src.name or "").strip("`")
        child_inner_alias = (child_src.alias_or_name or child_src.name or "").strip("`")
        if not child_table or not child_inner_alias:
            continue

        windows = [
            w for w in sub_sel.find_all(exp.Window)
            if isinstance(getattr(w, "this", None), exp.RowNumber)
        ]
        if len(windows) != 1:
            continue
        window = windows[0]
        order = window.args.get("order")
        partition_by = list(window.args.get("partition_by") or [])
        if not isinstance(order, exp.Order) or not order.expressions or not partition_by:
            continue

        on_expr = join_node.args.get("on")
        if on_expr is None:
            continue

        saw_rn_filter = False
        filtered_conds: List["exp.Expression"] = []
        join_key_name = ""
        preserved_key_col = None
        replacement_map: Dict[Tuple[str, str], Tuple[str, str]] = {}

        for cond in _flatten_and(on_expr):
            if isinstance(cond, exp.EQ):
                left = getattr(cond, "left", None)
                right = getattr(cond, "right", None)

                # Remove subquery rn = 1 from the JOIN condition.
                if isinstance(left, exp.Column) and isinstance(right, exp.Literal):
                    if (
                        str(left.table or "").strip("`").lower() == sub_alias.lower()
                        and str(left.name or "").strip("`").lower() == "rn"
                        and str(right.this or "").strip() == "1"
                    ):
                        saw_rn_filter = True
                        continue
                if isinstance(right, exp.Column) and isinstance(left, exp.Literal):
                    if (
                        str(right.table or "").strip("`").lower() == sub_alias.lower()
                        and str(right.name or "").strip("`").lower() == "rn"
                        and str(left.this or "").strip() == "1"
                    ):
                        saw_rn_filter = True
                        continue

                # Capture child-join key equality.
                if isinstance(left, exp.Column) and isinstance(right, exp.Column):
                    l_alias = str(left.table or "").strip("`")
                    r_alias = str(right.table or "").strip("`")
                    if l_alias.lower() == sub_alias.lower() and r_alias:
                        join_key_name = str(left.name or "").strip("`")
                        preserved_key_col = right.copy()
                    elif r_alias.lower() == sub_alias.lower() and l_alias:
                        join_key_name = str(right.name or "").strip("`")
                        preserved_key_col = left.copy()

            filtered_conds.append(cond.copy())

        if not saw_rn_filter or not join_key_name or preserved_key_col is None or not filtered_conds:
            continue

        if (
            _is_identifier_col(join_key_name)
            and isinstance(preserved_key_col, exp.Column)
            and _norm_key_name(join_key_name) == _norm_key_name(str(preserved_key_col.name or ""))
        ):
            replacement_map[(sub_alias.lower(), join_key_name.lower())] = (
                str(preserved_key_col.table or "").strip("`"),
                str(preserved_key_col.name or "").strip("`"),
            )

        new_joins: List["exp.Join"] = []
        for idx, old_join in enumerate(joins):
            if idx != join_idx:
                new_joins.append(old_join.copy())
                continue

            rewritten_join = old_join.copy()
            rewritten_join.set(
                "this",
                exp.Table(
                    this=exp.to_identifier(child_table),
                    alias=exp.TableAlias(this=exp.to_identifier(sub_alias)),
                ),
            )
            rewritten_join.set("on", _combine_and(filtered_conds))
            new_joins.append(rewritten_join)

        inner_exprs: List["exp.Expression"] = []
        alias_names: List[str] = []
        expr_to_alias: Dict[str, str] = {}
        alias_by_lower: Dict[str, str] = {}

        def _rewrite_projection_node(node: "exp.Expression") -> "exp.Expression":
            if not isinstance(node, exp.Column):
                return node
            key = (
                str(node.table or "").strip("`").lower(),
                str(node.name or "").strip("`").lower(),
            )
            repl = replacement_map.get(key)
            if repl is None:
                return node
            new_alias, new_col = repl
            new_node = node.copy()
            if new_alias:
                new_node.set("table", exp.to_identifier(new_alias))
            new_node.set("this", exp.to_identifier(new_col))
            return new_node

        for item in sel.expressions or []:
            if isinstance(item, exp.Star):
                return sql
            alias_name = _expr_output_alias(item)
            if not alias_name:
                return sql
            alias_name = alias_name.strip()
            if not alias_name or alias_name.lower() == "rn" or alias_name.lower() in alias_by_lower:
                return sql

            base_expr = item.this.copy() if isinstance(item, exp.Alias) else item.copy()
            rewritten_base = base_expr.transform(_rewrite_projection_node)
            inner_exprs.append(exp.alias_(rewritten_base, alias_name, quoted=False))
            alias_names.append(alias_name)
            expr_to_alias[_norm_expr(rewritten_base)] = alias_name
            alias_by_lower[alias_name.lower()] = alias_name
            if isinstance(rewritten_base, exp.Column):
                alias_by_lower.setdefault(str(rewritten_base.name or "").strip("`").lower(), alias_name)

        if not alias_names:
            return sql

        def _rewrite_window_node(node: "exp.Expression") -> "exp.Expression":
            if not isinstance(node, exp.Column):
                return node
            new_node = node.copy()
            if not str(new_node.table or "").strip():
                new_node.set("table", exp.to_identifier(sub_alias))
            key = (
                str(new_node.table or "").strip("`").lower(),
                str(new_node.name or "").strip("`").lower(),
            )
            repl = replacement_map.get(key)
            if repl is not None:
                new_alias, new_col = repl
                if new_alias:
                    new_node.set("table", exp.to_identifier(new_alias))
                new_node.set("this", exp.to_identifier(new_col))
            return new_node

        rank_order_items: List["exp.Ordered"] = []
        seen_rank_keys: Set[str] = set()
        for ordered in order.expressions or []:
            expr = ordered.this.copy().transform(_rewrite_window_node)
            expr_key = _norm_expr(expr)
            if not expr_key or expr_key in seen_rank_keys:
                continue
            seen_rank_keys.add(expr_key)
            rank_order_items.append(
                exp.Ordered(this=expr, desc=bool(ordered.args.get("desc")))
            )

        if isinstance(preserved_key_col, exp.Column):
            pk_key = _norm_expr(preserved_key_col)
            if pk_key and pk_key not in seen_rank_keys and _is_identifier_col(str(preserved_key_col.name or "")):
                rank_order_items.append(exp.Ordered(this=preserved_key_col.copy(), desc=False))

        if not rank_order_items:
            continue

        rn_expr = exp.alias_(
            exp.Window(
                this=exp.RowNumber(),
                partition_by=[exp.column(base_id_col, table=base_alias)],
                order=exp.Order(expressions=rank_order_items),
            ),
            "rn",
            quoted=False,
        )

        inner_select = exp.Select(expressions=inner_exprs + [rn_expr]).from_(base_src.copy())
        inner_select.set("joins", new_joins)
        if sel.args.get("where") is not None:
            inner_select.set("where", sel.args["where"].copy())

        ranked_sub = exp.Subquery(
            this=inner_select,
            alias=exp.TableAlias(this=exp.to_identifier("t")),
        )
        outer = exp.Select(
            expressions=[exp.column(alias_name, table="t") for alias_name in alias_names]
        ).from_(ranked_sub).where(
            exp.EQ(this=exp.column("rn", table="t"), expression=exp.Literal.number(1))
        )

        top_order = sel.args.get("order")
        outer_order_items: List["exp.Ordered"] = []
        if isinstance(top_order, exp.Order):
            for ordered in top_order.expressions or []:
                base_expr = ordered.this.copy().transform(_rewrite_projection_node)
                alias_name = expr_to_alias.get(_norm_expr(base_expr))
                if alias_name is None and isinstance(base_expr, exp.Column):
                    alias_name = alias_by_lower.get(str(base_expr.name or "").strip("`").lower())
                if alias_name is None:
                    continue
                outer_order_items.append(
                    exp.Ordered(this=exp.column(alias_name, table="t"), desc=bool(ordered.args.get("desc")))
                )
        if outer_order_items:
            outer.set("order", exp.Order(expressions=outer_order_items))

        out_sql = outer.sql(dialect="mysql")
        out_sql = _fix_outer_order_by_for_derived_alias(out_sql)
        out_sql = re.sub(r"\s{2,}", " ", out_sql).strip()
        if out_sql and not out_sql.endswith(";"):
            out_sql += ";"
        return out_sql or sql

    return sql


def _sanitize_order_by_alias_assignment(sql: str) -> str:
    """
    Remove malformed alias-assignment fragments that sometimes leak into
    ORDER BY, e.g.:
      ORDER BY total_orders DESC, customer_id AS C
    -> ORDER BY total_orders DESC, customer_id ASC

    Conservative:
    - only touches ORDER BY tail
    - only repairs identifier + AS + single token direction-like garbage
    """
    if not sql or "order by" not in (sql or "").lower():
        return sql

    def _fix_item(item: str) -> str:
        text = (item or "").strip()
        m = re.match(
            r"""(?is)^
            (`?[A-Za-z_][A-Za-z0-9_]*`?(?:\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?)?)
            \s+AS\s+([A-Za-z_][A-Za-z0-9_]*)\s*$
            """,
            text,
            flags=re.X,
        )
        if not m:
            return text
        return f"{m.group(1).strip()} ASC"

    m_order = re.search(r"(?is)\bORDER\s+BY\s+(.+?)(;?\s*)$", sql)
    if not m_order:
        return sql
    order_body = (m_order.group(1) or "").strip()
    items = _split_top_level_commas(order_body)
    if not items:
        return sql
    fixed_items = [_fix_item(item) for item in items]
    fixed_order = ", ".join(fixed_items)
    return sql[:m_order.start(1)] + fixed_order + sql[m_order.end(1):]


def _preserve_order_by_projection_alias_quotes(sql: str) -> str:
    """
    Restore quoting for top-level ORDER BY items when they exactly reference a
    projected alias containing spaces or other non-word characters.

    This is intentionally clause-local: it does not rewrite semantics, only
    preserves valid alias references that may have lost quoting after an AST or
    formatting pass.
    """
    s = (sql or "").strip()
    if not s or "order by" not in s.lower():
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s

    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    order_pos = _find_top_level_clause(s0, "order by", max(0, from_pos + len("from")))
    if sel_pos != 0 or from_pos < 0 or order_pos < 0:
        return sql

    limit_pos = _find_top_level_clause(s0, "limit", order_pos + len("order by"))
    order_end = min([p for p in (limit_pos, len(s0)) if p >= 0])

    alias_map: Dict[str, str] = {}
    select_items = _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip())
    for item in select_items:
        _, alias = _split_select_expr_alias(item)
        alias_clean = str(alias or "").strip().strip("`'\"")
        if not alias_clean or not re.search(r"\W", alias_clean):
            continue
        alias_key = re.sub(r"\s+", " ", alias_clean).strip().lower()
        if alias_key and alias_key not in alias_map:
            alias_map[alias_key] = f"`{alias_clean.replace('`', '')}`"

    if not alias_map:
        return sql

    order_body = s0[order_pos + len("order by"):order_end].strip()
    order_items = _split_top_level_commas(order_body)
    if not order_items:
        return sql

    fixed_items: List[str] = []
    changed = False
    for item in order_items:
        text = (item or "").strip()
        m_dir = re.match(r"(?is)^(.*?)(\s+(?:ASC|DESC))?\s*$", text)
        if not m_dir:
            fixed_items.append(text)
            continue

        base = (m_dir.group(1) or "").strip()
        direction = (m_dir.group(2) or "").upper()
        if not base or re.search(r"[()./*+\-<>=%]", base):
            fixed_items.append(text)
            continue

        alias_key = re.sub(r"\s+", " ", base.strip().strip("`'\"")).strip().lower()
        alias_ref = alias_map.get(alias_key)
        if not alias_ref:
            fixed_items.append(text)
            continue

        rebuilt = f"{alias_ref}{direction}".strip()
        fixed_items.append(rebuilt)
        if rebuilt != text:
            changed = True

    if not changed:
        return sql

    fixed_order = ", ".join(fixed_items)
    return s0[:order_pos + len("order by")] + " " + fixed_order + s0[order_end:] + trailing


def _ast_simplify_redundant_dedupe(sql: str) -> Tuple[str, Dict[str, Any]]:
    """
    AST-first simplification for clearly safe dedupe structures.

    Covered in this batch:
    - DROP redundant GROUP BY when a flat non-aggregate query already behaves as
      a pure dedupe over the projected expressions
    - DROP redundant DISTINCT when GROUP BY already defines the visible groups

    Guardrails:
    - top-level SELECT only
    - skip nested subqueries, window expressions, and QUALIFY
    - flat GROUP BY rewrite only when projected expressions exactly match the
      top-level GROUP BY expressions
    """
    meta: Dict[str, Any] = {"parse_ok": False, "fixes": [], "warnings": []}
    s = str(sql or "").strip()
    if not s:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    if not isinstance(ast, exp.Select):
        meta["warnings"].append("unsupported_root")
        return sql, meta

    sel = ast
    group = sel.args.get("group")
    if not isinstance(group, exp.Group) or not (group.expressions or []):
        return sql, meta

    if sel.args.get("qualify") is not None:
        meta["warnings"].append("qualify_skipped")
        return sql, meta
    if any(True for _ in sel.find_all(exp.Subquery)):
        meta["warnings"].append("nested_subquery_skipped")
        return sql, meta
    if any(True for _ in sel.find_all(exp.Window)):
        meta["warnings"].append("window_skipped")
        return sql, meta

    def _base_expr(item: "exp.Expression") -> "exp.Expression":
        return item.this if isinstance(item, exp.Alias) else item

    def _expr_norm(node: "exp.Expression") -> str:
        try:
            return _normalize_sql_expr_for_match(node.sql(dialect=SQL_PARSE_DIALECT or "mysql"))
        except Exception:
            return ""

    def _contains_agg(node: "exp.Expression") -> bool:
        return isinstance(node, exp.AggFunc) or any(True for _ in node.find_all(exp.AggFunc))

    alias_to_base_norm: Dict[str, str] = {}
    select_norms: List[str] = []
    select_nonagg_norms: List[str] = []
    has_agg = False
    for item in sel.expressions or []:
        base = _base_expr(item)
        norm = _expr_norm(base)
        if not norm:
            continue
        if isinstance(item, exp.Alias) and str(item.alias or "").strip():
            alias_to_base_norm[str(item.alias).strip("`").lower()] = norm
        select_norms.append(norm)
        if _contains_agg(base):
            has_agg = True
        else:
            select_nonagg_norms.append(norm)

    if not select_norms or not select_nonagg_norms:
        return sql, meta

    resolved_group_norms: List[str] = []
    for group_expr in group.expressions or []:
        if isinstance(group_expr, exp.Column) and not str(group_expr.table or "").strip():
            alias_norm = alias_to_base_norm.get(str(group_expr.name or "").strip("`").lower())
            if alias_norm:
                resolved_group_norms.append(alias_norm)
                continue
        norm = _expr_norm(group_expr)
        if norm:
            resolved_group_norms.append(norm)

    if not resolved_group_norms:
        return sql, meta

    select_norms_sorted = sorted(select_norms)
    nonagg_norms_sorted = sorted(select_nonagg_norms)
    group_norms_sorted = sorted(resolved_group_norms)
    has_having = sel.args.get("having") is not None
    has_distinct = sel.args.get("distinct") is not None

    # Safe flat dedupe case:
    # SELECT expr1, expr2 FROM ... GROUP BY expr1, expr2
    #   -> SELECT DISTINCT expr1, expr2 FROM ...
    if not has_agg and not has_having and select_norms_sorted == group_norms_sorted:
        sel.set("group", None)
        if not has_distinct:
            sel.set("distinct", exp.Distinct())
            meta["fixes"].append("flat_group_by_to_distinct")
        else:
            meta["fixes"].append("drop_redundant_group_by_with_distinct")
    # Safe grouped aggregate dedupe case:
    # SELECT DISTINCT key, SUM(x) FROM ... GROUP BY key
    #   -> SELECT key, SUM(x) FROM ... GROUP BY key
    elif has_distinct and nonagg_norms_sorted == group_norms_sorted:
        sel.set("distinct", None)
        meta["fixes"].append("drop_redundant_distinct_with_group_by")

    if not meta["fixes"]:
        return sql, meta

    out_sql = ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
    if sql.strip().endswith(";"):
        out_sql = out_sql.rstrip(";") + ";"
    return out_sql, meta


def _ast_repair_group_by_projection_validity(sql: str) -> Tuple[str, Dict[str, Any]]:
    """
    AST-first GROUP BY projection validity repair for flat and simple real-table join queries.

    Scope for this batch:
    - top-level SELECT only
    - one or more real tables from FROM/JOIN, but no derived tables
    - allow narrow WHERE/HAVING subqueries, but skip subqueries inside the
      projected/grouped expressions themselves
    - skip windows, QUALIFY, and set operations

    Preservation rules:
    - keep aggregates, literals, stars
    - keep expressions explicitly covered by GROUP BY
    - keep expressions whose referenced columns are all covered by GROUP BY
    - keep same-table expressions when GROUP BY includes that table's primary
      identifier column, because those projections are functionally dependent
      in this narrow real-table scope
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
    }
    s = str(sql or "").strip()
    if not s:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    if not isinstance(ast, exp.Select):
        meta["warnings"].append("unsupported_root")
        return sql, meta

    sel = ast
    group = sel.args.get("group")
    if not isinstance(group, exp.Group) or not (group.expressions or []):
        return sql, meta

    if sel.args.get("qualify") is not None:
        meta["warnings"].append("qualify_skipped")
        return sql, meta
    for item in sel.expressions or []:
        base_item = item.this if isinstance(item, exp.Alias) else item
        if any(True for _ in base_item.find_all(exp.Subquery)):
            meta["warnings"].append("projection_subquery_skipped")
            return sql, meta
    for group_expr in group.expressions or []:
        if any(True for _ in group_expr.find_all(exp.Subquery)):
            meta["warnings"].append("group_subquery_skipped")
            return sql, meta
    if any(True for _ in sel.find_all(exp.Window)):
        meta["warnings"].append("window_skipped")
        return sql, meta
    from_arg = sel.args.get("from") or sel.args.get("from_")
    if from_arg is None:
        meta["warnings"].append("missing_from")
        return sql, meta

    base_table_expr = getattr(from_arg, "this", None)
    if not isinstance(base_table_expr, exp.Table):
        meta["warnings"].append("derived_from_skipped")
        return sql, meta

    alias_to_table: Dict[str, str] = {}
    table_aliases: Dict[str, Set[str]] = {}

    def _register_table(table_expr: "exp.Table") -> bool:
        table_name = str(table_expr.name or "").strip("`").lower()
        alias_name = str(table_expr.alias_or_name or table_name).strip("`").lower()
        if not table_name or not alias_name:
            return False
        alias_to_table[alias_name] = table_name
        alias_to_table.setdefault(table_name, table_name)
        table_aliases.setdefault(table_name, set()).add(alias_name)
        table_aliases[table_name].add(table_name)
        return True

    if not _register_table(base_table_expr):
        meta["warnings"].append("missing_table_name")
        return sql, meta

    join_exprs = [j for j in (sel.args.get("joins") or []) if isinstance(j, exp.Join)]
    for join_expr in join_exprs:
        join_table_expr = getattr(join_expr, "this", None)
        if not isinstance(join_table_expr, exp.Table):
            meta["warnings"].append("derived_join_skipped")
            return sql, meta
        if not _register_table(join_table_expr):
            meta["warnings"].append("missing_join_table_name")
            return sql, meta

    meta["handled_scope"] = True

    def _base_expr(item: "exp.Expression") -> "exp.Expression":
        return item.this if isinstance(item, exp.Alias) else item

    def _expr_norm(node: "exp.Expression") -> str:
        try:
            return _normalize_sql_expr_for_match(node.sql(dialect=SQL_PARSE_DIALECT or "mysql"))
        except Exception:
            return ""

    def _contains_agg(node: "exp.Expression") -> bool:
        return isinstance(node, exp.AggFunc) or any(True for _ in node.find_all(exp.AggFunc))

    def _column_variants(col: "exp.Column") -> Set[str]:
        variants: Set[str] = set()
        col_name = str(col.name or "").strip("`")
        if not col_name:
            return variants

        col_norm = _normalize_sql_expr_for_match(col_name)
        if col_norm:
            variants.add(col_norm)

        col_table = str(col.table or "").strip("`").lower()
        table_variants: Set[str] = set()
        if col_table:
            mapped_table = alias_to_table.get(col_table, col_table)
            table_variants.add(col_table)
            table_variants.add(mapped_table)
            table_variants.update(table_aliases.get(mapped_table, set()))
        else:
            for table_name, aliases in table_aliases.items():
                table_variants.add(table_name)
                table_variants.update(aliases)
        for table_name in table_variants:
            if not table_name:
                continue
            qualified_norm = _normalize_sql_expr_for_match(f"{table_name}.{col_name}")
            if qualified_norm:
                variants.add(qualified_norm)
        return variants

    alias_to_base_norm: Dict[str, str] = {}
    for item in sel.expressions or []:
        if isinstance(item, exp.Alias) and str(item.alias or "").strip():
            alias_name = str(item.alias).strip("`").lower()
            base_norm = _expr_norm(item.this)
            if alias_name and base_norm:
                alias_to_base_norm[alias_name] = base_norm

    group_norms: Set[str] = set()
    for group_expr in group.expressions or []:
        if isinstance(group_expr, exp.Column):
            alias_name = str(group_expr.name or "").strip("`").lower()
            col_table = str(group_expr.table or "").strip("`").lower()
            if not col_table:
                alias_norm = alias_to_base_norm.get(alias_name)
                if alias_norm:
                    group_norms.add(alias_norm)
            group_norms.update(_column_variants(group_expr))
            continue
        norm = _expr_norm(group_expr)
        if norm:
            group_norms.add(norm)

    if not group_norms:
        meta["warnings"].append("empty_group_norms")
        return sql, meta

    grouped_identifier_tables: Set[str] = set()
    real_tables_in_scope: Set[str] = set(table_aliases.keys())
    for table_name, aliases in table_aliases.items():
        grouped_id = str(get_id_column(table_name) or "").strip("`").lower()
        if not grouped_id:
            continue
        candidate_qualifiers = set(aliases)
        candidate_qualifiers.add(table_name)
        if any(
            _normalize_sql_expr_for_match(f"{qualifier}.{grouped_id}") in group_norms
            for qualifier in candidate_qualifiers
            if qualifier
        ) or _normalize_sql_expr_for_match(grouped_id) in group_norms:
            grouped_identifier_tables.add(table_name)

    expressions_to_remove = []
    for item in sel.expressions or []:
        base = _base_expr(item)

        if _contains_agg(base):
            continue
        if isinstance(base, (exp.Literal, exp.Star)):
            continue

        base_norm = _expr_norm(base)
        if base_norm and base_norm in group_norms:
            continue

        ref_cols = [c for c in base.find_all(exp.Column)]
        if ref_cols:
            refs_all_grouped = all(
                bool(_column_variants(ref_col).intersection(group_norms))
                for ref_col in ref_cols
            )
            if refs_all_grouped:
                continue

            ref_tables: Set[str] = set()
            for ref_col in ref_cols:
                ref_table = str(ref_col.table or "").strip("`").lower()
                if ref_table:
                    ref_tables.add(alias_to_table.get(ref_table, ref_table))
                elif len(real_tables_in_scope) == 1:
                    # In a true single-table grouped query, unqualified columns
                    # still belong to that sole table and can be functionally
                    # dependent on its grouped identifier.
                    ref_tables.update(real_tables_in_scope)
            if len(ref_tables) == 1:
                only_ref_table = next(iter(ref_tables))
                if only_ref_table in grouped_identifier_tables:
                    continue
        else:
            # No column references means the expression is constant in this
            # scope, so it does not violate grouped projection validity.
            continue

        expressions_to_remove.append(item)

    if not expressions_to_remove:
        return sql, meta

    new_expressions = [expr for expr in sel.expressions if expr not in expressions_to_remove]
    if not new_expressions:
        meta["warnings"].append("drop_would_empty_select")
        return sql, meta

    sel.set("expressions", new_expressions)
    meta["fixes"].append("repair_group_by_projection_validity_ast")

    out_sql = ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
    if sql.strip().endswith(";"):
        out_sql = out_sql.rstrip(";") + ";"
    return out_sql, meta


def _ast_validate_window_structure(sql: str, question: str = "") -> Tuple[str, Dict[str, Any]]:
    """
    AST-first window structure validation for parseable SQL.

    Scope for this batch:
    - validate top-level/window AST shape conservatively
    - surface missing ORDER BY / malformed frame warnings
    - normalize only the explicit default running frame shape when safe

    Out of scope for this batch:
    - adding semantic PARTITION BY / ORDER BY choices
    - ranking metric rewrites
    - winner-row/window semantic correction
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
        "window_count": 0,
        "window_kinds": [],
    }
    s = str(sql or "").strip()
    if not s:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    sel = ast if isinstance(ast, exp.Select) else ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        meta["warnings"].append("unsupported_root")
        return sql, meta

    windows = [w for w in sel.find_all(exp.Window) if isinstance(w, exp.Window)]
    meta["window_count"] = len(windows)
    if not windows:
        return sql, meta

    meta["handled_scope"] = True
    q = str(question or "").strip().lower()
    running_terms = ("running", "cumulative", "kumulatif", "akumulatif")
    has_running_intent = any(term in q for term in running_terms)

    rank_types = tuple(
        cls for cls in (
            getattr(exp, "RowNumber", None),
            getattr(exp, "Rank", None),
            getattr(exp, "DenseRank", None),
        )
        if cls is not None
    )
    offset_types = tuple(
        cls for cls in (
            getattr(exp, "Lag", None),
            getattr(exp, "Lead", None),
            getattr(exp, "FirstValue", None),
            getattr(exp, "LastValue", None),
        )
        if cls is not None
    )

    default_frame_pat = re.compile(
        r"\b(?:ROWS|RANGE)\s+BETWEEN\s+UNBOUNDED\s+PRECEDING\s+AND\s+CURRENT\s+ROW\b",
        flags=re.I,
    )

    def _window_partition_exprs(win: "exp.Window") -> List["exp.Expression"]:
        raw = win.args.get("partition_by")
        if raw is None:
            raw = win.args.get("partition")
        if raw is None:
            return []
        if isinstance(raw, list):
            return [x for x in raw if isinstance(x, exp.Expression)]
        if isinstance(raw, exp.Partition):
            return [x for x in (raw.expressions or []) if isinstance(x, exp.Expression)]
        if isinstance(raw, exp.Expression):
            exprs = getattr(raw, "expressions", None)
            if isinstance(exprs, list) and exprs:
                return [x for x in exprs if isinstance(x, exp.Expression)]
            return [raw]
        return []

    def _kind_name(win_func: Optional["exp.Expression"]) -> str:
        if win_func is None:
            return "unknown"
        if rank_types and isinstance(win_func, rank_types):
            return "rank"
        if offset_types and isinstance(win_func, offset_types):
            return "offset"
        if isinstance(win_func, exp.AggFunc):
            return "aggregate"
        return "other"

    def _validate_candidate(candidate_sql: str) -> Optional[str]:
        candidate = str(candidate_sql or "").strip()
        if not candidate:
            return None
        trailing = ";" if s.endswith(";") or candidate.endswith(";") else ""
        candidate_parse = re.sub(r";+\s*$", "", candidate).strip()
        try:
            sqlglot.parse_one(candidate_parse, read=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            return None
        if trailing and not candidate_parse.endswith(";"):
            return candidate_parse + trailing
        return candidate if candidate.endswith(";") or not trailing else candidate + trailing

    def _apply_text_fix(current_sql: str, fixer, fix_name: str) -> str:
        try:
            candidate = fixer(current_sql, question)
        except TypeError:
            candidate = fixer(current_sql)
        except Exception:
            return current_sql
        if not candidate or candidate == current_sql:
            return current_sql
        validated = _validate_candidate(candidate)
        if not validated:
            meta["warnings"].append(f"{fix_name}_parse_rejected")
            return current_sql
        if fix_name not in meta["fixes"]:
            meta["fixes"].append(fix_name)
        return validated

    kinds_seen: List[str] = []
    should_drop_default_frame = False
    for win in windows:
        win_func = getattr(win, "this", None)
        kind = _kind_name(win_func)
        if kind not in kinds_seen:
            kinds_seen.append(kind)

        order = win.args.get("order")
        order_items = list(order.expressions or []) if isinstance(order, exp.Order) else []
        partition_exprs = _window_partition_exprs(win)
        rendered = ""
        try:
            rendered = win.sql(dialect=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            rendered = ""

        if win_func is None:
            meta["warnings"].append("window_missing_function")
            continue

        if kind in {"rank", "offset"} and not order_items:
            meta["warnings"].append(f"{kind}_window_missing_order_by")

        if rendered and default_frame_pat.search(rendered) and not order_items:
            meta["warnings"].append("window_frame_without_order_by")

        if (
            kind == "aggregate"
            and has_running_intent
            and rendered
            and default_frame_pat.search(rendered)
            and order_items
        ):
            spec = win.args.get("spec")
            if spec is not None:
                win.set("spec", None)
                should_drop_default_frame = True

        if kind == "aggregate" and has_running_intent and order_items and not partition_exprs:
            meta["warnings"].append("running_window_missing_partition_by")

    meta["window_kinds"] = kinds_seen
    current_sql = s
    if should_drop_default_frame:
        out_sql = ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
        if sql.strip().endswith(";"):
            out_sql = out_sql.rstrip(";") + ";"
        if out_sql.strip() != s:
            current_sql = out_sql
            meta["fixes"].append("simplify_default_window_frame_ast")

    current_sql = _apply_text_fix(
        current_sql,
        _repair_running_window_missing_partition,
        "running_window_partition_inference_ast",
    )

    meta["warnings"] = list(dict.fromkeys(meta["warnings"]))
    if current_sql.strip() == s:
        return sql, meta
    return current_sql, meta


def _ast_rewrite_window_semantics(sql: str, question: str = "") -> Tuple[str, Dict[str, Any]]:
    """
    AST-first semantic rewrites for non-winner-row window queries.

    This extends the earlier narrow slice with deeper, still scoped semantics:
    - no-skip rank intent -> DENSE_RANK
    - grouped count-window near-misses -> ranking windows
    - rank partition inference from the question
    - rank metric replacement/direction alignment from the question
    - running-window partition inference
    - LAG/LEAD sequence direction alignment from the question
    - same-group average gap conversion / partition-only AVG windows

    Still out of scope:
    - winner-row semantics
    - top-N-per-group rewrites
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
        "window_count": 0,
        "window_kinds": [],
    }
    s = str(sql or "").strip()
    if not s or not question:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    sel = ast if isinstance(ast, exp.Select) else ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        meta["warnings"].append("unsupported_root")
        return sql, meta

    windows = [w for w in sel.find_all(exp.Window) if isinstance(w, exp.Window)]
    has_window_text = bool(re.search(r"\bOVER\s*\(", s, flags=re.I))
    meta["window_count"] = len(windows)
    if not windows and not has_window_text:
        return sql, meta

    meta["handled_scope"] = True
    if not windows and has_window_text:
        meta["warnings"].append("window_ast_enumeration_empty")
    q = str(question or "").strip().lower()

    rank_types = tuple(
        cls for cls in (
            getattr(exp, "RowNumber", None),
            getattr(exp, "Rank", None),
            getattr(exp, "DenseRank", None),
        )
        if cls is not None
    )
    offset_types = tuple(
        cls for cls in (
            getattr(exp, "Lag", None),
            getattr(exp, "Lead", None),
        )
        if cls is not None
    )

    no_skip_rank = bool(
        re.search(r"\brank", q, flags=re.I)
        and (
            re.search(r"\bwithout\s+skipping\b", q, flags=re.I)
            or re.search(r"\b(?:does\s+not|doesn't|do\s+not|don't|not)\s+skip\b", q, flags=re.I)
            or re.search(r"\bno\s+skipp?ing\b", q, flags=re.I)
            or re.search(r"\bdense\s+rank\b", q, flags=re.I)
        )
    )

    wants_same_group_avg_gap = (
        not any(t in q for t in ("running", "cumulative", "kumulatif", "akumulatif"))
        and any(re.search(pat, q, flags=re.I) for pat in HELPERS_AVERAGE_INTENT_PATTERNS)
        and any(re.search(pat, q, flags=re.I) for pat in HELPERS_SAME_GROUP_INTENT_PATTERNS)
        and any_phrase_in_text(q, group_average_difference_window_phrases())
    )

    desired_offset_desc: Optional[bool] = None
    if re.search(r"\b(?:previous|prior|next|following)\b", q, flags=re.I):
        sequence_cue = re.search(
            r"\bordered\s+by\b|\bbased\s+on\b[^.]{0,80}\border\b|\b(?:date|time|timestamp)[-\s]+order\b",
            q,
            flags=re.I,
        )
        ordered_tail = ""
        if sequence_cue:
            ordered_idx = sequence_cue.start()
            ordered_tail = q[ordered_idx:] if ordered_idx >= 0 else q
            stop_positions: List[int] = []
            for pat in (
                r"[.;!?]",
                r",",
                r"\band\s+(?:sort|order|arrange)\b",
                r"\bthen\s+(?:sort|order|arrange)\b",
                r"\b(?:sort|order|arrange)\s+the\s+(?:final\s+)?(?:result|results|output|rows?)\s+by\b",
            ):
                m = re.search(pat, ordered_tail, flags=re.I)
                if m:
                    stop_positions.append(m.start())
            if stop_positions:
                ordered_tail = ordered_tail[:min(stop_positions)]

        if re.search(r"\b(?:descending|desc|reverse)\b", ordered_tail, flags=re.I):
            desired_offset_desc = True
        elif re.search(r"\b(?:ascending|asc|chronological|earliest\s+first|oldest\s+first)\b", ordered_tail, flags=re.I):
            desired_offset_desc = False
        elif sequence_cue:
            desired_offset_desc = False

    def _mark_fix(name: str) -> None:
        if name not in meta["fixes"]:
            meta["fixes"].append(name)

    def _window_partition_exprs(win: "exp.Window") -> List["exp.Expression"]:
        raw = win.args.get("partition_by")
        if raw is None:
            raw = win.args.get("partition")
        if raw is None:
            return []
        if isinstance(raw, list):
            return [x for x in raw if isinstance(x, exp.Expression)]
        if isinstance(raw, exp.Partition):
            return [x for x in (raw.expressions or []) if isinstance(x, exp.Expression)]
        if isinstance(raw, exp.Expression):
            exprs = getattr(raw, "expressions", None)
            if isinstance(exprs, list) and exprs:
                return [x for x in exprs if isinstance(x, exp.Expression)]
            return [raw]
        return []

    def _kind_name(win_func: Optional["exp.Expression"]) -> str:
        if win_func is None:
            return "unknown"
        if rank_types and isinstance(win_func, rank_types):
            return "rank"
        if offset_types and isinstance(win_func, offset_types):
            return "offset"
        if isinstance(win_func, exp.AggFunc):
            return "aggregate"
        return "other"

    def _validate_candidate(candidate_sql: str) -> Optional[str]:
        candidate = str(candidate_sql or "").strip()
        if not candidate:
            return None
        trailing = ";" if s.endswith(";") or candidate.endswith(";") else ""
        candidate_parse = re.sub(r";+\s*$", "", candidate).strip()
        try:
            sqlglot.parse_one(candidate_parse, read=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            return None
        if trailing and not candidate_parse.endswith(";"):
            return candidate_parse + trailing
        return candidate if candidate.endswith(";") or not trailing else candidate + trailing

    def _apply_text_fix(current_sql: str, fixer, fix_name: str) -> str:
        try:
            candidate = fixer(current_sql)
        except TypeError:
            candidate = fixer(current_sql, question)
        except Exception:
            return current_sql
        if not candidate or candidate == current_sql:
            return current_sql
        validated = _validate_candidate(candidate)
        if not validated:
            meta["warnings"].append(f"{fix_name}_parse_rejected")
            return current_sql
        _mark_fix(fix_name)
        return validated

    def _rank_metric_target(select_sql: str, partition_expr: str) -> Tuple[str, Optional[bool]]:
        metric_terms: Set[str] = set()
        metric_patterns = [
            r"\b(?:rank|ranking|ranked)\b[\s\S]{0,120}?\bby\s+(?P<seg>[a-z0-9_\s-]{1,64}?)(?=\s+(?:from|highest|lowest|descending|ascending|if|where|when|return|show|list|final|output|result|sort|order)\b|[,.;]|$)",
            r"\bby\s+(?P<seg>[a-z0-9_\s-]{1,64}?)\s+(?:from\s+highest\s+to\s+lowest|from\s+lowest\s+to\s+highest|descending|ascending)\b",
        ]
        for pat in metric_patterns:
            m = re.search(pat, q, flags=re.I | re.S)
            if not m:
                continue
            metric_terms = _rank_text_terms(m.group("seg") or "")
            if metric_terms:
                break

        candidates = _rank_partition_candidates_from_select(select_sql)
        if not candidates:
            return "", None

        part_norm = _normalize_sql_expr_for_match(partition_expr or "")
        order_candidates = [
            (expr, terms)
            for expr, terms in candidates
            if not part_norm or _normalize_sql_expr_for_match(expr) != part_norm
        ]
        if not order_candidates:
            return "", None

        target_expr = ""
        if metric_terms:
            scored: List[Tuple[int, int, str]] = []
            for expr, terms in order_candidates:
                overlap = terms & metric_terms
                if not overlap:
                    continue
                extra_penalty = len(terms - metric_terms)
                scored.append((len(overlap), -extra_penalty, expr))
            if scored:
                scored.sort(key=lambda item: (item[0], item[1]), reverse=True)
                target_expr = scored[0][2]

        if not target_expr:
            def _score_order(expr: str) -> Tuple[int, int]:
                base = expr.split(".")[-1].strip("`").lower()
                id_like = int(bool(re.search(r"(?:id|number|code)$", base)))
                return (id_like, len(base))
            target_expr = sorted((expr for expr, _terms in order_candidates), key=_score_order, reverse=True)[0]

        wants_desc = None
        if re.search(r"\b(?:highest|largest|greatest|descending|high\s+to\s+low)\b", q, flags=re.I) or re.search(r"\bfrom\s+highest\s+to\s+lowest\b", q, flags=re.I):
            wants_desc = True
        if re.search(r"\b(?:lowest|smallest|least|ascending|low\s+to\s+high)\b", q, flags=re.I) or re.search(r"\bfrom\s+lowest\s+to\s+highest\b", q, flags=re.I):
            wants_desc = False if wants_desc is None else wants_desc
        return target_expr, wants_desc

    def _rewrite_count_window_rank_semantics(text: str) -> str:
        if not text or _question_wants_winner_row(question):
            return text
        if not re.search(r"\b(?:rank|ranking|ranked)\b", q, flags=re.I):
            return text
        if not re.search(r"\bCOUNT\s*\(\s*(?:\*|1)\s*\)\s*OVER\s*\(", text, flags=re.I):
            return text
        if not re.search(r"\bGROUP\s+BY\b", text, flags=re.I):
            return text

        select_part = _extract_top_level_select_list(text)
        if not select_part:
            return text
        candidates = _rank_partition_candidates_from_select(select_part)
        partition_terms = _extract_rank_partition_terms_from_question(q)
        partition_expr = _choose_rank_partition_expr(candidates, partition_terms) if partition_terms else ""
        if not partition_expr:
            m_part = re.search(
                r"\bCOUNT\s*\(\s*(?:\*|1)\s*\)\s*OVER\s*\(\s*PARTITION\s+BY\s+(?P<part>[^)]+?)\s*\)",
                text,
                flags=re.I | re.S,
            )
            partition_expr = str(m_part.group("part") or "").strip() if m_part else ""
        if not partition_expr:
            return text

        target_expr, wants_desc = _rank_metric_target(select_part, partition_expr)
        if not target_expr:
            return text

        rank_fn = "DENSE_RANK" if no_skip_rank else "RANK"
        rank_dir = "DESC" if wants_desc is not False else "ASC"

        count_window_pat = re.compile(
            r"(?is)\bCOUNT\s*\(\s*(?:\*|1)\s*\)\s*OVER\s*\((?P<body>.*?)\)\s+AS\s+(?P<alias>`[^`]+`|[A-Za-z_][A-Za-z0-9_]*)"
        )
        replaced = count_window_pat.sub(
            lambda m: (
                f"{rank_fn}() OVER (PARTITION BY {partition_expr} ORDER BY {target_expr} {rank_dir}) "
                f"AS {m.group('alias')}"
            ),
            text,
            count=1,
        )
        if replaced == text:
            return text

        try:
            rebuilt_ast = sqlglot.parse_one(re.sub(r";+\s*$", "", replaced).strip(), read=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            return text
        rebuilt_sel = rebuilt_ast if isinstance(rebuilt_ast, exp.Select) else rebuilt_ast.find(exp.Select)
        if isinstance(rebuilt_sel, exp.Select) and rebuilt_sel.args.get("group") is not None:
            rebuilt_sel.set("group", None)
        out_sql = rebuilt_ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
        if text.strip().endswith(";"):
            out_sql = out_sql.rstrip(";") + ";"
        return out_sql

    def _rewrite_offset_gap_to_same_group_avg(text: str) -> str:
        if not wants_same_group_avg_gap:
            return text
        try:
            parsed = sqlglot.parse_one(re.sub(r";+\s*$", "", text).strip(), read=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            return text
        parsed_sel = parsed if isinstance(parsed, exp.Select) else parsed.find(exp.Select)
        if not isinstance(parsed_sel, exp.Select):
            return text
        if parsed_sel.args.get("joins") or parsed_sel.args.get("group") or parsed_sel.args.get("having"):
            return text

        updated = False
        laglead_types = tuple(cls for cls in (getattr(exp, "Lag", None), getattr(exp, "Lead", None)) if cls is not None)
        new_exprs: List["exp.Expression"] = []
        for item in parsed_sel.expressions or []:
            base = item.this if isinstance(item, exp.Alias) else item
            found = base if isinstance(base, exp.Window) else base.find(exp.Window)
            if not isinstance(found, exp.Window) or not laglead_types or not isinstance(getattr(found, "this", None), laglead_types):
                new_exprs.append(item.copy())
                continue

            part_exprs = _window_partition_exprs(found)
            metric_expr = getattr(found.this, "this", None)
            if not part_exprs or not isinstance(metric_expr, exp.Expression):
                new_exprs.append(item.copy())
                continue

            avg_window = exp.Window(
                this=exp.Avg(this=metric_expr.copy()),
                partition_by=exp.Partition(expressions=[p.copy() for p in part_exprs]),
            )
            rewritten_expr = exp.Sub(this=metric_expr.copy(), expression=avg_window)
            if isinstance(item, exp.Alias) and item.alias:
                new_exprs.append(exp.alias_(rewritten_expr, str(item.alias), quoted=False))
            else:
                new_exprs.append(rewritten_expr)
            updated = True

        if not updated:
            return text
        parsed_sel.set("expressions", new_exprs)
        out_sql = parsed.sql(dialect=SQL_PARSE_DIALECT or "mysql")
        if text.strip().endswith(";"):
            out_sql = out_sql.rstrip(";") + ";"
        return out_sql

    kinds_seen: List[str] = []
    changed = False
    for win in windows:
        win_func = getattr(win, "this", None)
        kind = _kind_name(win_func)
        if kind not in kinds_seen:
            kinds_seen.append(kind)

        if no_skip_rank and rank_types and isinstance(win_func, rank_types):
            if not isinstance(win_func, getattr(exp, "DenseRank", ())):
                if isinstance(win_func, tuple(cls for cls in (getattr(exp, "RowNumber", None), getattr(exp, "Rank", None)) if cls is not None)):
                    win.set("this", exp.DenseRank())
                    changed = True
                    _mark_fix("no_skip_rank_to_dense_rank_ast")

        if desired_offset_desc is not None and offset_types and isinstance(win_func, offset_types):
            order = win.args.get("order")
            order_items = list(order.expressions or []) if isinstance(order, exp.Order) else []
            if order_items:
                first = order_items[0]
                if isinstance(first, exp.Ordered):
                    current_desc = bool(first.args.get("desc"))
                    if current_desc != desired_offset_desc:
                        first.set("desc", desired_offset_desc)
                        changed = True
                        _mark_fix("offset_window_sequence_direction_ast")

        if wants_same_group_avg_gap and isinstance(win_func, exp.Avg):
            if _window_partition_exprs(win) and win.args.get("order") is not None:
                win.set("order", None)
                if win.args.get("spec") is not None:
                    win.set("spec", None)
                changed = True
                _mark_fix("same_group_avg_partition_only_ast")

    meta["window_kinds"] = kinds_seen
    current_sql = s
    if changed:
        current_sql = ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
        if sql.strip().endswith(";"):
            current_sql = current_sql.rstrip(";") + ";"

    current_sql = _apply_text_fix(current_sql, _rewrite_count_window_rank_semantics, "count_window_rank_semantics_ast")
    current_sql = _apply_text_fix(current_sql, _rewrite_offset_gap_to_same_group_avg, "offset_to_same_group_avg_gap_ast")
    current_sql = _apply_text_fix(current_sql, _rewrite_no_skip_rank_to_dense_rank, "no_skip_rank_to_dense_rank_ast")
    current_sql = _apply_text_fix(current_sql, _repair_rank_window_partition_from_question, "rank_partition_inference_ast")
    current_sql = _apply_text_fix(current_sql, _repair_rank_window_metric_from_question, "rank_metric_replacement_ast")
    current_sql = _apply_text_fix(current_sql, _add_rank_value_nonnull_filter_from_question, "rank_value_nonnull_filter_ast")
    current_sql = _apply_text_fix(current_sql, _fix_grouped_aggregate_rank_direction, "grouped_rank_direction_ast")
    current_sql = _apply_text_fix(current_sql, _repair_running_window_missing_partition, "running_window_partition_inference_ast")
    current_sql = _apply_text_fix(current_sql, _rewrite_same_group_avg_gap_window_to_partition_only, "same_group_avg_partition_only_ast")
    current_sql = _apply_text_fix(current_sql, _enforce_window_sequence_direction, "offset_window_sequence_direction_ast")

    if current_sql.strip() == s:
        meta["fixes"] = []
        meta["warnings"] = list(dict.fromkeys(meta["warnings"]))
        return sql, meta

    meta["warnings"] = list(dict.fromkeys(meta["warnings"]))
    return current_sql, meta


def _rewrite_malformed_window_winner_clause(sql: str, question: str) -> str:
    """
    Repair malformed winner-row drafts that use a named WINDOW clause plus an
    invalid `... ON ROW_NUMBER() OVER window_alias = 1` tail.

    The repair is conservative and only runs when:
    - the question clearly wants one winning row per group
    - the SELECT list already exposes a candidate grain
    - the WINDOW clause provides partition/order semantics
    """
    if not sql or not question:
        return sql
    if not _question_wants_winner_row(question):
        return sql
    if re.search(r"\bWHERE\b[^;]*\brn\s*=\s*\d+\b", sql, flags=re.I | re.S):
        return sql

    s = sql.strip().rstrip(";").strip()
    if not s:
        return sql

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m_alias = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m_alias:
            return (item or "").strip(), None
        alias = (m_alias.group(2) or "").strip().strip("`'\"")
        return (m_alias.group(1) or "").strip(), alias or None

    def _norm_sql_text(text: str) -> str:
        return re.sub(r"\s+", " ", (text or "").strip().lower())

    def _find_balanced_close(text: str, open_idx: int) -> int:
        if open_idx < 0 or open_idx >= len(text) or text[open_idx] != "(":
            return -1
        depth = 0
        in_sq = False
        in_dq = False
        i = open_idx
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return -1

    def _parse_partition_order(window_sql: str) -> Optional[Tuple[str, str]]:
        body = (window_sql or "").strip()
        part_m = re.match(r"(?is)^\s*PARTITION\s+BY\s+", body)
        if not part_m:
            return None
        order_pos = _find_top_level_clause(body, "order by", part_m.end())
        if order_pos < 0:
            return None
        partition_expr = body[part_m.end():order_pos].strip()
        order_part = body[order_pos + len("order by"):].strip()
        if not partition_expr or not order_part:
            return None
        return partition_expr, order_part

    def _parse_named_window_on_row_number(text: str) -> Optional[Tuple[str, str, str, str]]:
        """
        Parse:
          SELECT ... FROM ... WINDOW w AS (<balanced window spec>)
          ON ROW_NUMBER() OVER w = 1

        Regex alone is brittle here because aggregate ORDER BY items often
        contain nested parentheses, e.g. SUM(a * b).
        """
        sel_pos = _find_top_level_clause(text, "select")
        if sel_pos != 0:
            return None
        from_pos = _find_top_level_clause(text, "from", sel_pos + len("select"))
        if from_pos < 0:
            return None
        window_pos = _find_top_level_clause(text, "window", from_pos + len("from"))
        if window_pos < 0:
            return None

        select_part = text[sel_pos + len("select"):from_pos].strip()
        from_part = text[from_pos + len("from"):window_pos].strip()
        after_window = text[window_pos + len("window"):].strip()
        if not select_part or not from_part or not after_window:
            return None

        alias_m = re.match(
            r"(?is)^([A-Za-z_][A-Za-z0-9_]*)\s+AS\s*\(",
            after_window,
        )
        if not alias_m:
            return None
        win_alias = alias_m.group(1)
        open_idx = alias_m.end() - 1
        close_idx = _find_balanced_close(after_window, open_idx)
        if close_idx < 0:
            return None

        window_part = after_window[open_idx + 1:close_idx].strip()
        tail = after_window[close_idx + 1:].strip()
        if not window_part or not re.match(
            rf"(?is)^ON\s+ROW_NUMBER\s*\(\s*\)\s*OVER\s+{re.escape(win_alias)}\s*=\s*1\s*$",
            tail,
        ):
            return None

        return select_part, from_part, win_alias, window_part

    def _build_grouped_ranked_winner_sql(
        *,
        select_part: str,
        from_part: str,
        partition_expr: str,
        order_part: str,
        group_part: str = "",
        where_part: str = "",
        outer_order_part: str = "",
    ) -> str:
        select_items = _split_top_level_commas(select_part)
        if not select_items:
            return sql

        projected: List[Tuple[str, str, bool]] = []
        expr_to_alias: Dict[str, str] = {}
        alias_by_lower: Dict[str, str] = {}
        fallback_group_exprs: List[str] = []

        for raw_item in select_items:
            expr_sql, alias_name = _split_expr_alias(raw_item)
            if not expr_sql:
                return sql
            out_name = alias_name or _extract_alias_or_colname(expr_sql)
            if not out_name:
                return sql
            out_name = out_name.strip()
            if not out_name or out_name.lower() == "rn" or out_name.lower() in alias_by_lower:
                return sql

            is_agg = bool(re.search(r"\b(?:SUM|COUNT|AVG|MIN|MAX)\s*\(", expr_sql, flags=re.I))
            projected.append((expr_sql, out_name, is_agg))
            expr_to_alias[_norm_sql_text(expr_sql)] = out_name
            alias_by_lower[out_name.lower()] = out_name
            if not is_agg:
                fallback_group_exprs.append(expr_sql)

        if not fallback_group_exprs or not any(is_agg for _, _, is_agg in projected):
            return sql

        part_norm = _norm_sql_text(partition_expr)
        partition_alias = expr_to_alias.get(part_norm)
        if partition_alias is None:
            part_col = _extract_alias_or_colname(partition_expr)
            if part_col:
                partition_alias = alias_by_lower.get(part_col.lower())
        if partition_alias is None:
            return sql

        order_specs: List[Tuple[str, bool]] = []
        for raw_order in _split_top_level_commas(order_part):
            order_item = (raw_order or "").strip()
            if not order_item:
                continue
            desc = bool(re.search(r"\bDESC\s*$", order_item, flags=re.I))
            order_expr = re.sub(r"\s+(?:ASC|DESC)\s*$", "", order_item, flags=re.I).strip()
            order_alias = expr_to_alias.get(_norm_sql_text(order_expr))
            if order_alias is None:
                order_col = _extract_alias_or_colname(order_expr)
                if order_col:
                    order_alias = alias_by_lower.get(order_col.lower())
            if order_alias is None:
                return sql
            order_specs.append((order_alias, desc))

        if not order_specs:
            return sql

        agg_aliases = {
            alias_name.lower()
            for _, alias_name, is_agg in projected
            if is_agg
        }
        raw_group_items = _split_top_level_commas(group_part) if group_part else []
        unique_group_exprs: List[str] = []
        seen_group_norms: Set[str] = set()
        for expr_sql in raw_group_items:
            expr_clean = (expr_sql or "").strip()
            if not expr_clean:
                continue
            bare_label = (_extract_alias_or_colname(expr_clean) or "").strip().lower()
            if bare_label in agg_aliases and re.match(
                r"(?is)^\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?\s*$",
                expr_clean,
            ):
                continue
            expr_norm = _norm_sql_text(expr_clean)
            if not expr_norm or expr_norm in seen_group_norms:
                continue
            seen_group_norms.add(expr_norm)
            unique_group_exprs.append(expr_clean)

        if not unique_group_exprs:
            for expr_sql in fallback_group_exprs:
                expr_norm = _norm_sql_text(expr_sql)
                if not expr_norm or expr_norm in seen_group_norms:
                    continue
                seen_group_norms.add(expr_norm)
                unique_group_exprs.append(expr_sql)

        if not unique_group_exprs:
            return sql

        candidate_items = [
            _maybe_keep_or_alias_simple(expr_sql, alias_name)
            for expr_sql, alias_name, _ in projected
        ]
        candidate_sql = f"SELECT {', '.join(candidate_items)} FROM {from_part}"
        if where_part:
            candidate_sql += f" WHERE {where_part}"
        candidate_sql += f" GROUP BY {', '.join(unique_group_exprs)}"

        rank_order_sql = ", ".join(
            f"c.{alias_name} {'DESC' if desc else 'ASC'}"
            for alias_name, desc in order_specs
        )
        ranked_sql = (
            f"SELECT {', '.join(f'c.{alias_name}' for _, alias_name, _ in projected)}, "
            f"ROW_NUMBER() OVER (PARTITION BY c.{partition_alias} ORDER BY {rank_order_sql}) AS rn "
            f"FROM ({candidate_sql}) AS c"
        )
        outer_sql = (
            f"SELECT {', '.join(f't.{alias_name}' for _, alias_name, _ in projected)} "
            f"FROM ({ranked_sql}) AS t "
            f"WHERE t.rn = 1"
        )

        outer_order_specs: List[Tuple[str, bool]] = []
        if outer_order_part:
            for raw_order in _split_top_level_commas(outer_order_part):
                order_item = (raw_order or "").strip()
                if not order_item:
                    continue
                desc = bool(re.search(r"\bDESC\s*$", order_item, flags=re.I))
                order_expr = re.sub(r"\s+(?:ASC|DESC)\s*$", "", order_item, flags=re.I).strip()
                order_alias = expr_to_alias.get(_norm_sql_text(order_expr))
                if order_alias is None:
                    order_col = _extract_alias_or_colname(order_expr)
                    if order_col:
                        order_alias = alias_by_lower.get(order_col.lower())
                if order_alias is None:
                    continue
                outer_order_specs.append((order_alias, desc))
        if outer_order_specs:
            outer_sql += " ORDER BY " + ", ".join(
                f"t.{alias_name} {'DESC' if desc else 'ASC'}"
                for alias_name, desc in outer_order_specs
            )
        elif _question_requests_ordering(question):
            outer_sql += f" ORDER BY t.{partition_alias} ASC"

        outer_sql += ";"
        fixed_sql = _fix_outer_order_by_for_derived_alias(outer_sql)
        return fixed_sql or sql

    parsed_named_window = _parse_named_window_on_row_number(s)
    if parsed_named_window:
        select_part, from_part, _win_alias, window_part = parsed_named_window
        parsed_window = _parse_partition_order(window_part)
        if not parsed_window:
            return sql
        partition_expr, order_part = parsed_window
        return _build_grouped_ranked_winner_sql(
            select_part=select_part,
            from_part=from_part,
            partition_expr=partition_expr,
            order_part=order_part,
        )

    bad_window_pat = re.compile(
        r"""(?is)^\s*SELECT\s+(?P<select>.*?)\s+FROM\s+(?P<from>.*?)\s+WINDOW\s+(?P<win_alias>[A-Za-z_][A-Za-z0-9_]*)\s+AS\s*\((?P<window>.*?)\)\s+ON\s+ROW_NUMBER\s*\(\s*\)\s*OVER\s+(?P=win_alias)\s*=\s*1\s*$"""
    )
    m = bad_window_pat.match(s)
    if m:
        select_part = (m.group("select") or "").strip()
        from_part = (m.group("from") or "").strip()
        window_part = (m.group("window") or "").strip()
        if not select_part or not from_part or not window_part:
            return sql

        parsed_window = _parse_partition_order(window_part)
        if not parsed_window:
            return sql

        partition_expr, order_part = parsed_window

        return _build_grouped_ranked_winner_sql(
            select_part=select_part,
            from_part=from_part,
            partition_expr=partition_expr,
            order_part=order_part,
        )

    bad_having_pat = re.compile(
        r"""(?is)^\s*SELECT\s+(?P<select>.*?)\s+FROM\s+(?P<from>.*?)
        (?:\s+WHERE\s+(?P<where>.*?))?
        \s+GROUP\s+BY\s+(?P<group>.*?)
        \s+HAVING\s+ROW_NUMBER\s*\(\s*\)\s*OVER\s*\((?P<window>.*?)\)\s*=\s*1
        (?:\s+ORDER\s+BY\s+(?P<outer_order>.*?))?
        \s*$""",
        re.I | re.S | re.X,
    )
    m = bad_having_pat.match(s)
    if not m:
        return sql

    select_part = (m.group("select") or "").strip()
    from_part = (m.group("from") or "").strip()
    where_part = (m.group("where") or "").strip()
    group_part = (m.group("group") or "").strip()
    window_part = (m.group("window") or "").strip()
    outer_order_part = (m.group("outer_order") or "").strip()
    if not select_part or not from_part or not group_part or not window_part:
        return sql

    parsed_window = _parse_partition_order(window_part)
    if not parsed_window:
        return sql

    partition_expr, order_part = parsed_window

    return _build_grouped_ranked_winner_sql(
        select_part=select_part,
        from_part=from_part,
        where_part=where_part,
        group_part=group_part,
        partition_expr=partition_expr,
        order_part=order_part,
        outer_order_part=outer_order_part,
    )


def _rewrite_winner_row_aggregate_misuse(sql: str, question: str, ctx: str = "") -> str:
    """
    Catch winner-row questions where the SQL still uses MAX/MIN (often with
    HAVING/subquery hacks) and rewrite to ROW_NUMBER winner-row selection.

    This handles cases WITHOUT GROUP BY (your current guardrail requires GROUP BY).
    Very conservative:
    - triggers only if _question_wants_winner_row(question)
    - triggers only if query contains exactly one MAX/MIN in SELECT
    - aborts if query already has ROW_NUMBER
    """
    if not sql or not _question_wants_winner_row(question):
        return sql
    if re.search(r"\bROW_NUMBER\s*\(", sql, flags=re.I):
        return sql
    if not re.search(r"\b(MAX|MIN)\s*\(", sql, flags=re.I):
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not sel:
        return sql

    # Special-case rescue:
    # Winner-row tie-break questions sometimes produce malformed window MAX/MIN SQL
    # (no ROW_NUMBER filter), returning all rows. Rewrite to canonical rn=1 shape.
    q_low = (question or "").lower()
    metric_terms = _winner_row_metric_terms()
    metric_alt = _regex_alt_from_terms(metric_terms, r"$^")
    has_tie_phrase = bool(re.search(r"\b(?:if\s+there\s+are\s+multiple|if\s+multiple|tie|tied|same)\b", q_low))
    same_metric_tie = bool(
        has_tie_phrase
        and metric_alt != r"$^"
        and re.search(rf"\b(?:same|equal)\s+(?:[a-z0-9_]+\s+)?{metric_alt}\b", q_low)
    )
    wants_latest_date = bool(
        re.search(r"\b(?:latest|most\s+recent|newest)\b", q_low)
        and re.search(r"\b(?:date|time)\b", q_low)
    )
    wants_metric_superlative = bool(
        re.search(r"\b(?:largest|highest|max(?:imum)?|top)\b", q_low)
        and metric_alt != r"$^"
        and re.search(rf"\b{metric_alt}\b", q_low)
    )
    if wants_latest_date and wants_metric_superlative and not sel.args.get("group"):
        def _base_expr(it: exp.Expression) -> exp.Expression:
            return it.this if isinstance(it, exp.Alias) else it

        def _expr_norm(e: exp.Expression) -> str:
            try:
                return re.sub(r"[\s`]+", "", e.sql(dialect="mysql").lower())
            except Exception:
                return ""

        window_entries: List[Tuple[exp.Expression, exp.Expression, exp.Window, exp.Expression]] = []
        for item in sel.expressions:
            base = _base_expr(item)
            w = base if isinstance(base, exp.Window) else base.find(exp.Window)
            if not isinstance(w, exp.Window) or not isinstance(w.this, (exp.Max, exp.Min)):
                continue
            window_entries.append((item, base, w, w.this))

        if window_entries:
            def _window_partition_exprs(win: exp.Window) -> List[exp.Expression]:
                """
                sqlglot Window.partition_by can be represented as:
                - exp.Partition(expressions=[...])
                - list[Expression]
                - single Expression
                Keep extraction tolerant to all forms.
                """
                raw = win.args.get("partition_by")
                if raw is None:
                    # compatibility: some versions may use different key
                    raw = win.args.get("partition")
                if raw is None:
                    return []
                if isinstance(raw, list):
                    return [x for x in raw if isinstance(x, exp.Expression)]
                if isinstance(raw, exp.Partition):
                    return [x for x in (raw.expressions or []) if isinstance(x, exp.Expression)]
                if isinstance(raw, exp.Expression):
                    exprs = getattr(raw, "expressions", None)
                    if isinstance(exprs, list) and exprs:
                        return [x for x in exprs if isinstance(x, exp.Expression)]
                    return [raw]
                return []

            partition_expr = None
            for _item, _base, w, _agg in window_entries:
                part_exprs = _window_partition_exprs(w)
                if part_exprs:
                    partition_expr = part_exprs[0].copy()
                    break

            # Date expression from MAX/MIN window input (prefer date/time-like column).
            date_expr = None
            for _item, _base, _w, agg in window_entries:
                inner = agg.this
                inner_sql = (inner.sql(dialect="mysql") if inner is not None else "").lower()
                if any(k in inner_sql for k in ("date", "time", "timestamp")):
                    date_expr = inner.copy()
                    break
            if date_expr is None and window_entries:
                date_expr = window_entries[0][3].this.copy()

            # Metric expression from non-date MAX/MIN window inputs.  Prefer the
            # aggregate input over projected identifiers so hallucinated/id-like
            # columns cannot outrank the actual measured value.
            metric_expr = None
            for _item, _base, _w, agg in window_entries:
                inner = agg.this
                inner_sql = (inner.sql(dialect="mysql") if inner is not None else "").lower()
                if (
                    inner is not None
                    and metric_alt != r"$^"
                    and re.search(rf"\b{metric_alt}\b", inner_sql)
                    and not any(k in inner_sql for k in ("date", "time", "timestamp"))
                ):
                    metric_expr = inner.copy()
                    break

            # Fallback to non-window simple columns only when no aggregate metric
            # input is available.
            for item in sel.expressions:
                if metric_expr is not None:
                    break
                base = _base_expr(item)
                if base.find(exp.Window):
                    continue
                col = base if isinstance(base, exp.Column) else (base.this if isinstance(base, exp.Alias) and isinstance(base.this, exp.Column) else None)
                if not isinstance(col, exp.Column):
                    continue
                col_sql = col.sql(dialect="mysql").lower()
                if any(k in col_sql for k in metric_terms):
                    metric_expr = col.copy()
                    break

            # Fallback: derive metric directly from window MAX/MIN inputs.
            if metric_expr is None:
                for _item, _base, _w, agg in window_entries:
                    inner = agg.this
                    inner_sql = (inner.sql(dialect="mysql") if inner is not None else "").lower()
                    if any(k in inner_sql for k in metric_terms):
                        metric_expr = inner.copy()
                        break
            if metric_expr is None and window_entries:
                metric_expr = window_entries[0][3].this.copy()

            if partition_expr is not None and date_expr is not None and metric_expr is not None:
                def _infer_alias(expr_obj: exp.Expression, fallback: str) -> str:
                    norm = _expr_norm(expr_obj)
                    for it in sel.expressions:
                        b = _base_expr(it)
                        if _expr_norm(b) == norm:
                            if isinstance(it, exp.Alias) and it.alias:
                                return it.alias
                            if isinstance(b, exp.Column) and b.name:
                                return b.name
                    if isinstance(expr_obj, exp.Column) and expr_obj.name:
                        return expr_obj.name
                    return fallback

                part_alias = _infer_alias(partition_expr, "group_key")
                metric_alias = _infer_alias(metric_expr, "value")
                date_alias = _infer_alias(date_expr, "event_date")

                used_aliases: Set[str] = set()
                def _uniq_alias(a: str) -> str:
                    base = re.sub(r"[^A-Za-z0-9_]", "", (a or "").strip()) or "col"
                    if not re.match(r"[A-Za-z_]", base):
                        base = f"c_{base}"
                    cand = base
                    i = 2
                    while cand.lower() in used_aliases:
                        cand = f"{base}_{i}"
                        i += 1
                    used_aliases.add(cand.lower())
                    return cand

                part_alias_u = _uniq_alias(part_alias)
                metric_alias_u = _uniq_alias(metric_alias)
                date_alias_u = _uniq_alias(date_alias)

                metric_desc = not bool(re.search(r"\b(?:lowest|smallest|min(?:imum)?)\b", q_low))
                date_desc = bool(re.search(r"\b(?:latest|most\s+recent|newest)\b", q_low))

                rn = exp.Window(
                    this=exp.RowNumber(),
                    partition_by=exp.Partition(expressions=[partition_expr.copy()]),
                    order=exp.Order(
                        expressions=[
                            exp.Ordered(this=metric_expr.copy(), desc=metric_desc),
                            exp.Ordered(this=date_expr.copy(), desc=date_desc),
                        ]
                    ),
                )

                inner_exprs = [
                    exp.alias_(partition_expr.copy(), part_alias_u, quoted=False),
                    exp.alias_(metric_expr.copy(), metric_alias_u, quoted=False),
                    exp.alias_(date_expr.copy(), date_alias_u, quoted=False),
                    exp.alias_(rn, "rn", quoted=False),
                ]

                from_expr = sel.args.get("from") or sel.args.get("from_")
                if from_expr is None:
                    return sql
                inner = exp.Select(expressions=inner_exprs)
                inner.set("from_", from_expr.copy())
                joins = sel.args.get("joins")
                if joins:
                    inner.set("joins", [j.copy() for j in joins])
                where_expr = sel.args.get("where")
                def _has_top_level_aggregate(node: "exp.Expression") -> bool:
                    for agg in node.find_all(exp.AggFunc):
                        anc = getattr(agg, "parent", None)
                        nested = False
                        while anc is not None and anc is not node:
                            if isinstance(anc, exp.Subquery):
                                nested = True
                                break
                            anc = getattr(anc, "parent", None)
                        if not nested:
                            return True
                    return False

                if where_expr is not None and not _has_top_level_aggregate(where_expr):
                    inner.set("where", where_expr.copy())

                outer = (
                    exp.Select(
                        expressions=[
                            exp.column(part_alias_u, table="t"),
                            exp.column(metric_alias_u, table="t"),
                            exp.column(date_alias_u, table="t"),
                        ]
                    )
                    .from_(exp.Subquery(this=inner, alias=exp.TableAlias(this=exp.to_identifier("t"))))
                    .where(exp.EQ(this=exp.column("rn", table="t"), expression=exp.Literal.number(1)))
                )
                return outer.sql(dialect="mysql")

    # Identify exactly one MAX/MIN in SELECT list
    agg_item = None
    agg_kind = None
    metric_expr = None

    def find_maxmin(e: exp.Expression):
        m = e.find(exp.Max) or e.find(exp.Min)
        return m

    for item in sel.expressions:
        base = item.this if isinstance(item, exp.Alias) else item
        m = find_maxmin(base)
        if not m:
            continue
        if agg_item is not None:
            return sql  # >1 aggregate => abort (conservative)
        agg_item = item
        if isinstance(m, exp.Max):
            agg_kind = "MAX"
            metric_expr = m.this
        elif isinstance(m, exp.Min):
            agg_kind = "MIN"
            metric_expr = m.this

    if agg_item is None or metric_expr is None or agg_kind is None:
        return sql

    # Collect non-aggregate SELECT expressions (potential partition/tie/output)
    nonagg_items = []
    for item in sel.expressions:
        if item is agg_item:
            continue
        base = item.this if isinstance(item, exp.Alias) else item
        # skip literals/stars
        if isinstance(base, (exp.Literal, exp.Star)):
            continue
        # if it contains an agg function, abort
        if base.find(exp.AggFunc):
            return sql
        nonagg_items.append(item)

    if not nonagg_items:
        return sql

    q_low = (question or "").lower()
    include_zero_intent = _question_wants_include_zero(question, ctx)

    def norm_name(e: exp.Expression) -> str:
        try:
            return e.sql(dialect="mysql").lower()
        except Exception:
            return ""

    # Partition columns:
    # Prefer expressions with lexical overlap to question entities.
    q_tokens = set(re.findall(r"[a-z0-9]+", q_low))
    stop_tokens = set(HELPERS_WINNER_ROW_PARTITION_STOP_TOKENS)
    q_tokens -= stop_tokens

    partition_exprs = []
    partition_candidates: List[Tuple[int, exp.Expression]] = []
    for item in nonagg_items:
        base = item.this if isinstance(item, exp.Alias) else item
        s = norm_name(base)
        expr_tokens = set(re.findall(r"[a-z0-9]+", s)) - stop_tokens
        if expr_tokens and (expr_tokens & q_tokens):
            score = len(expr_tokens & q_tokens)
            if any(k in s for k in ["id", "number", "code"]):
                score += 2
            partition_candidates.append((score, base))

    if partition_candidates:
        partition_exprs = [max(partition_candidates, key=lambda x: x[0])[1]]

    # Fallback: id/number/code-like
    if not partition_exprs:
        for item in nonagg_items:
            base = item.this if isinstance(item, exp.Alias) else item
            s = norm_name(base)
            if any(k in s for k in ["id", "number", "code"]):
                partition_exprs.append(base)
                break

    # Final fallback: first non-agg expression
    if not partition_exprs:
        base0 = nonagg_items[0].this if isinstance(nonagg_items[0], exp.Alias) else nonagg_items[0]
        partition_exprs = [base0]

    # Tie-breaker: prefer a date-like column among non-agg outputs (excluding partition)
    tie_exprs = []
    for item in nonagg_items:
        base = item.this if isinstance(item, exp.Alias) else item
        s = norm_name(base)
        if base in partition_exprs:
            continue
        if "date" in s:
            tie_exprs.append(base)

    # ORDER BY for window
    metric_desc = (agg_kind == "MAX")
    wants_latest_date = bool(
        re.search(r"\b(?:latest|most\s+recent|newest)\b", q_low, flags=re.I)
        and re.search(r"\b(?:date|time|payment\s+date|order\s+date)\b", q_low, flags=re.I)
    )
    wants_amount_tiebreak = bool(
        re.search(r"\b(?:if\s+there\s+are\s+multiple|if\s+multiple|same|tie)\b", q_low, flags=re.I)
        and re.search(r"\bdate\b", q_low, flags=re.I)
        and re.search(r"\b(?:largest|highest|max(?:imum)?)\b", q_low, flags=re.I)
        and metric_alt != r"$^"
        and re.search(rf"\b{metric_alt}\b", q_low, flags=re.I)
    )

    order_exprs = []
    if wants_latest_date and tie_exprs:
        date_expr = tie_exprs[0]
        order_exprs.append(exp.Ordered(this=date_expr.copy(), desc=True))
        if wants_amount_tiebreak:
            order_exprs.append(exp.Ordered(this=metric_expr.copy(), desc=True))
            # Stable deterministic tie-break when same date and amount.
            for item in nonagg_items:
                base = item.this if isinstance(item, exp.Alias) else item
                s = norm_name(base)
                if norm_name(base) in {norm_name(partition_exprs[0]), norm_name(date_expr)}:
                    continue
                if any(k in s for k in ["id", "number", "code"]):
                    order_exprs.append(exp.Ordered(this=base.copy(), desc=False))
                    break
        else:
            order_exprs.append(exp.Ordered(this=metric_expr.copy(), desc=metric_desc))
    else:
        order_exprs = [exp.Ordered(this=metric_expr.copy(), desc=metric_desc)]
        for te in tie_exprs[:2]:  # keep it short/conservative
            order_exprs.append(exp.Ordered(this=te.copy(), desc=False))

    rn = exp.Window(
        this=exp.RowNumber(),
        partition_by=exp.Partition(expressions=[p.copy() for p in partition_exprs]),
        order=exp.Order(expressions=order_exprs),
    )

    # Determine output alias for metric
    metric_alias = "value"
    if isinstance(agg_item, exp.Alias) and agg_item.alias:
        metric_alias = agg_item.alias
    else:
        # If it's MAX(amount) with no alias, try to name it reasonably
        metric_alias = "amount" if "amount" in norm_name(metric_expr) else "value"

    # Build inner select with stable aliases
    inner_exprs = []
    outer_exprs = []
    alias_by_norm: Dict[str, str] = {}

    for item in nonagg_items:
        if isinstance(item, exp.Alias):
            inner_exprs.append(item.copy())
            outer_exprs.append(exp.column(item.alias, table="t"))
            base_norm = norm_name(item.this if isinstance(item.this, exp.Expression) else item)
            if base_norm:
                alias_by_norm[base_norm] = item.alias
        else:
            # Require it to be a Column for safety; otherwise abort
            if not isinstance(item, exp.Column):
                return sql
            name = item.name
            inner_exprs.append(exp.alias_(item.copy(), name, quoted=False))
            outer_exprs.append(exp.column(name, table="t"))
            base_norm = norm_name(item)
            if base_norm:
                alias_by_norm[base_norm] = name

    # Add metric
    inner_exprs.append(exp.alias_(metric_expr.copy(), metric_alias, quoted=False))
    outer_exprs.append(exp.column(metric_alias, table="t"))
    metric_norm = norm_name(metric_expr)
    if metric_norm:
        alias_by_norm[metric_norm] = metric_alias

    # Add rn
    inner_exprs.append(exp.alias_(rn, "rn", quoted=False))

    # Rebuild inner FROM/WHERE from original query
    from_expr = sel.args.get("from") or sel.args.get("from_")
    if not from_expr:
        return sql
    inner = exp.Select(expressions=inner_exprs)
    inner.set("from_", from_expr.copy())
    joins = sel.args.get("joins")
    if joins:
        inner.set("joins", [j.copy() for j in joins])

    where_expr = sel.args.get("where")
    if where_expr is not None and include_zero_intent:
        where_sql = where_expr.sql(dialect="mysql").lower()
        ranking_signal_terms: Set[str] = {
            str(tok or "").strip().lower()
            for tok in HELPERS_WINNER_ROW_RANKING_SIGNAL_TERMS
            if str(tok or "").strip()
        }
        # Add schema-driven temporal columns from active query tables so this
        # ranking filter check is not tied to domain-specific date names.
        try:
            analyzer = get_schema_analyzer()
        except Exception:
            analyzer = None
        if analyzer is not None:
            alias_to_table = _parse_from_join_aliases(sql)
            query_tables = {
                str(t or "").strip().lower()
                for t in alias_to_table.values()
                if str(t or "").strip()
            }
            for table_l in sorted(query_tables):
                try:
                    table_cols = analyzer.get_table_columns(table_l) or []
                except Exception:
                    table_cols = []
                for col in table_cols:
                    col_l = str(col or "").strip().lower()
                    if not col_l:
                        continue
                    try:
                        role_l = str(get_column_role(table_l, col) or "").strip().lower()
                    except Exception:
                        role_l = ""
                    temporal_like = (
                        role_l in {"date", "datetime", "timestamp", "time", "temporal"}
                        or any(tok in col_l for tok in ("date", "time", "timestamp", "year", "month", "day"))
                    )
                    if temporal_like:
                        ranking_signal_terms.add(col_l)
                        ranking_signal_terms.add(col_l.replace("_", ""))
        has_ranking_signal = bool(
            where_sql
            and ranking_signal_terms
            and any(
                re.search(rf"\b{re.escape(tok)}\b", where_sql, flags=re.I)
                for tok in ranking_signal_terms
                if tok
            )
        )
        has_year_signal = bool(HELPERS_WINNER_ROW_RANKING_YEAR_PATTERN) and bool(
            re.search(HELPERS_WINNER_ROW_RANKING_YEAR_PATTERN, where_sql, flags=re.I)
        )
        ranking_like_filter = bool(
            re.search(r"\bselect\s+max\s*\(", where_sql, flags=re.I)
            and (has_ranking_signal or has_year_signal)
        )
        if ranking_like_filter:
            where_expr = None

    if where_expr is not None:
        inner.set("where", where_expr.copy())

    # Outer query
    outer = exp.Select(expressions=outer_exprs).from_(
        exp.Subquery(this=inner, alias=exp.TableAlias(this=exp.to_identifier("t")))
    ).where(exp.EQ(this=exp.column("rn", table="t"), expression=exp.Literal.number(1)))

    # Re-introduce deterministic outer ordering when the question explicitly asks sorting.
    if re.search(r"\b(?:sort(?:ed)?\s+by|order\s+by)\b", q_low, flags=re.I):
        outer_order_exprs = []
        if tie_exprs:
            tie_alias = alias_by_norm.get(norm_name(tie_exprs[0]))
            if tie_alias:
                outer_order_exprs.append(exp.Ordered(this=exp.column(tie_alias, table="t"), desc=True))
        part_alias = alias_by_norm.get(norm_name(partition_exprs[0]))
        if part_alias:
            outer_order_exprs.append(exp.Ordered(this=exp.column(part_alias, table="t"), desc=False))
        if outer_order_exprs:
            outer.set("order", exp.Order(expressions=outer_order_exprs))

    return outer.sql(dialect="mysql")


def _rewrite_metric_aggregate_column_mismatch(sql: str, question: str, ctx: str = "") -> str:
    """
    Fix SUM/AVG on non-metric columns (e.g., code/number/date/name) when
    question intent is metric total/average.

    Dynamic behavior:
    - resolve source table from SQL alias map
    - pick replacement metric column from same table using schema anchors
      + lexical metric signals
    """
    if not sql or not question:
        return sql

    q = question.lower()

    m = re.match(r"(?is)^\s*select\s+(?P<select>.*?)\s+from\s+(?P<after>.*)$", sql.strip())
    if not m:
        return sql

    select_part = (m.group("select") or "").strip()
    after_part = (m.group("after") or "").strip()
    if not select_part or not after_part:
        return sql

    m_from = re.match(
        r"(?is)^(?P<from_core>.*?)(?P<tail>\s+(?:where|group\s+by|having|order\s+by|limit)\b.*|;?\s*)$",
        after_part,
    )
    from_core = (m_from.group("from_core") or "").strip() if m_from else after_part.rstrip(";").strip()
    if not from_core:
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    for m_tbl in re.finditer(
        r"\b(?:from|join)\s+(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)",
        f"SELECT 1 FROM {from_core}",
        flags=re.I,
    ):
        table_raw = str(m_tbl.group("table") or "").replace("`", "")
        table_name = table_raw.split(".")[-1].strip()
        if not table_name:
            continue
        alias_to_table.setdefault(table_name, table_name)
        alias_to_table.setdefault(table_name.lower(), table_name)
    if not alias_to_table:
        m_base = re.match(r"(?is)^`?([A-Za-z_][A-Za-z0-9_]*)`?", from_core)
        if m_base:
            t = m_base.group(1)
            alias_to_table = {t: t, t.lower(): t}
    if not alias_to_table:
        return sql

    table_universe = {str(t).lower() for t in alias_to_table.values() if t}

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        return sql
    metric_term_universe = _dual_fact_metric_term_universe(
        table_universe,
        analyzer=analyzer,
        question=question,
    )
    query_tokens = {tok for tok in re.findall(r"[a-z0-9]+", q) if tok}
    generic_metric_terms = set(HELPERS_CTX_GENERIC_METRIC_FALLBACK_TERMS)
    legacy_metric_terms: Set[str] = set()
    if DOMAIN_HEURISTICS_ENABLED:
        legacy_metric_terms = _question_compat_metric_terms(question, HELPERS_ROLLUP_LEGACY_METRIC_TERMS)
    if not metric_term_universe:
        metric_term_universe.update(legacy_metric_terms or generic_metric_terms)
    entity_noise_terms: Set[str] = set()
    for table_name in table_universe:
        table_l = str(table_name or "").strip().lower()
        base_terms = {table_l, _to_singular(table_l)}
        for base_term in base_terms:
            if not base_term:
                continue
            entity_noise_terms.update(
                tok for tok in re.findall(r"[a-z0-9]+", base_term.replace("_", " ").lower()) if tok
            )
    metric_candidate_seed = set(metric_term_universe)
    if not metric_term_universe:
        metric_candidate_seed.update(legacy_metric_terms)
    metric_candidate_seed.update(query_tokens.intersection(generic_metric_terms))
    if not metric_candidate_seed:
        metric_candidate_seed.update(generic_metric_terms)
    metric_candidate_terms = {
        term
        for term in metric_candidate_seed
        if term and term not in entity_noise_terms and term not in HELPERS_METRIC_AGG_IDLIKE_TOKENS
    }
    has_metric_intent = bool(
        query_tokens & (metric_term_universe | legacy_metric_terms | generic_metric_terms | HELPERS_METRIC_AGG_INTENT_TERMS)
    )
    if not has_metric_intent:
        return sql

    metric_query_terms = query_tokens & metric_candidate_terms
    strong_metric_intent = bool(query_tokens & (metric_term_universe | legacy_metric_terms | generic_metric_terms))

    role_cache: Dict[Tuple[str, str], str] = {}
    term_cache: Dict[Tuple[str, str], Set[str]] = {}
    identity_cache: Dict[str, Set[str]] = {}
    original_cols_cache: Dict[str, Dict[str, str]] = {}

    def _clean_ident(s: str) -> str:
        return (s or "").replace("`", "").strip().lower()

    def _column_role_cached(table_l: str, col_l: str) -> str:
        key = (table_l, col_l)
        if key not in role_cache:
            try:
                role_cache[key] = str(get_column_role(table_l, col_l) or "").strip().lower()
            except Exception:
                role_cache[key] = ""
        return role_cache[key]

    def _identity_columns(table_l: str) -> Set[str]:
        if table_l not in identity_cache:
            ids: Set[str] = set()
            try:
                id_col = str(get_id_column(table_l) or "").strip().lower()
            except Exception:
                id_col = ""
            try:
                name_col = str(get_name_column(table_l) or "").strip().lower()
            except Exception:
                name_col = ""
            if id_col:
                ids.add(id_col)
            if name_col:
                ids.add(name_col)
            identity_cache[table_l] = ids
        return identity_cache[table_l]

    def _original_column_names(table_l: str) -> Dict[str, str]:
        table_l = str(table_l or "").strip().lower()
        if not table_l:
            return {}
        if table_l in original_cols_cache:
            return original_cols_cache[table_l]
        mapping: Dict[str, str] = {}
        try:
            for raw_col in analyzer.get_table_columns(table_l):
                raw = str(raw_col or "").strip("`")
                if raw:
                    mapping.setdefault(raw.lower(), raw)
        except Exception:
            pass
        original_cols_cache[table_l] = mapping
        return mapping

    def _column_semantic_terms(table_l: str, col_l: str) -> Set[str]:
        key = (table_l, col_l)
        if key in term_cache:
            return term_cache[key]

        terms: Set[str] = set()
        original_name = _original_column_names(table_l).get(col_l, col_l)
        candidate_texts = [original_name, col_l]
        for synonym_key in (original_name, col_l):
            try:
                candidate_texts.extend(analyzer.get_column_synonyms(table_l, synonym_key) or [])
            except Exception:
                pass

        for text in candidate_texts:
            raw_text = str(text or "").replace("_", " ")
            normalized = re.sub(
                r"([a-z0-9])([A-Z])",
                r"\1 \2",
                raw_text,
            )
            terms.update(tok for tok in re.findall(r"[a-z0-9]+", normalized.lower()) if tok)
            # Recover question-grounded subterms from fused schema identifiers
            # like "quantityordered" when metadata casing/separators are absent.
            compact = re.sub(r"[^a-z0-9]+", "", str(normalized or "").lower())
            if compact:
                for tok in query_tokens:
                    if len(tok) >= 4 and tok in compact:
                        terms.add(tok)

        role = _column_role_cached(table_l, col_l)
        if role in {"metric", "measure", "amount", "quantity"}:
            terms.add("total")
        if role:
            terms.add(role)

        term_cache[key] = {term for term in terms if term}
        return term_cache[key]

    def _is_metric_like(table_l: str, col_l: str) -> bool:
        role = _column_role_cached(table_l, col_l)
        if role in {"metric", "measure", "amount", "quantity"}:
            return True
        return bool(_column_semantic_terms(table_l, col_l) & metric_candidate_terms)

    def _is_id_like(table_l: str, col_l: str) -> bool:
        if col_l in _identity_columns(table_l):
            return True
        role = _column_role_cached(table_l, col_l)
        if role in {"date", "datetime", "timestamp", "time", "identifier", "id", "name"}:
            return True
        return bool(_column_semantic_terms(table_l, col_l) & HELPERS_METRIC_AGG_IDLIKE_TOKENS)

    def _pick_metric_col(
        table_l: str,
        current_col_l: str,
        preferred_terms: Optional[Set[str]] = None,
    ) -> Optional[str]:
        try:
            cols = [c.lower() for c in analyzer.get_table_columns(table_l)]
        except Exception:
            cols = []
        if not cols:
            return None

        try:
            anchor_cols = {c.lower() for c in analyzer.get_anchor_columns(table_l)}
        except Exception:
            anchor_cols = set()

        candidates = [c for c in cols if c != current_col_l and (_is_metric_like(table_l, c) or c in anchor_cols)]
        if not candidates:
            return None

        preferred = {
            str(term or "").strip().lower()
            for term in (preferred_terms or set())
            if str(term or "").strip()
        }

        def _score(c: str) -> int:
            score = 0
            candidate_terms = _column_semantic_terms(table_l, c)
            term_overlap = candidate_terms & metric_query_terms
            preferred_overlap = candidate_terms & preferred
            if c in anchor_cols:
                score += 20
            if _is_metric_like(table_l, c):
                score += 8
            if term_overlap:
                score += 10 + (4 * len(term_overlap))
            if preferred_overlap:
                score += 24 + (8 * len(preferred_overlap))
            if _is_id_like(table_l, c):
                score -= 8
            return score

        best = max(candidates, key=_score)
        return best if _score(best) >= 8 else None

    table_cols_cache: Dict[str, Set[str]] = {}

    def _table_columns_lower(table_l: str) -> Set[str]:
        table_l = str(table_l or "").strip().lower()
        if not table_l:
            return set()
        if table_l in table_cols_cache:
            return table_cols_cache[table_l]
        cols: Set[str] = set()
        try:
            cols.update(
                str(c or "").strip("`").lower()
                for c in analyzer.get_table_columns(table_l)
                if str(c or "").strip()
            )
        except Exception:
            pass
        table_cols_cache[table_l] = cols
        return cols

    def _resolve_unqualified_table_for_column(col_l: str) -> Optional[str]:
        owners = [
            table_l for table_l in sorted(table_universe)
            if col_l in _table_columns_lower(table_l)
        ]
        if len(owners) == 1:
            return owners[0]
        if len(table_universe) == 1:
            return next(iter(table_universe))
        return None

    agg_pat = re.compile(
        r"""(?is)\b(?P<func>SUM|AVG|MIN|MAX)\s*\(\s*(?P<distinct>DISTINCT\s+)?(?:(?P<q>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<c>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)"""
    )
    bool_agg_pat = re.compile(
        r"""(?is)\b(?P<func>SUM|AVG)\s*\(\s*(?:(?P<q>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<c>`?[A-Za-z_][A-Za-z0-9_]*`?)\s+IS\s+NOT\s+NULL\s*\)"""
    )
    count_agg_pat = re.compile(
        r"""(?is)^\s*COUNT\s*\(\s*(?:(?P<q>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<c>`?[A-Za-z_][A-Za-z0-9_]*`?|\*)\s*\)\s*$"""
    )

    changed = False

    def _rewrite_item(item: str) -> str:
        nonlocal changed
        expr_part, alias_part = _split_select_expr_alias(item)

        def _repl(m_agg: re.Match) -> str:
            nonlocal changed
            func = (m_agg.group("func") or "").upper()
            distinct_kw = m_agg.group("distinct") or ""
            qual_raw = m_agg.group("q")
            col_raw = m_agg.group("c") or ""
            alias_tokens = {
                tok
                for tok in re.findall(
                    r"[a-z0-9]+",
                    re.sub(
                        r"([a-z0-9])([A-Z])",
                        r"\1 \2",
                        str(alias_part or "").replace("_", " ").lower(),
                    ),
                )
                if tok
            }

            alias_l = str(alias_part or "").replace("_", " ").lower()
            if func in {"MIN", "MAX"} and re.search(
                r"\b(?:latest|newest|most\s+recent|earliest|oldest)\b", q, flags=re.I
            ) and re.search(r"\b(?:date|time|day|month|year)\b", f"{q} {alias_l}", flags=re.I):
                return m_agg.group(0)

            col_l = _clean_ident(col_raw)
            table_l = None
            if qual_raw:
                q_clean = _clean_ident(qual_raw)
                table_l = _clean_ident(alias_to_table.get(qual_raw) or alias_to_table.get(q_clean) or "")
            else:
                table_l = _resolve_unqualified_table_for_column(col_l)

            if not table_l:
                return m_agg.group(0)

            try:
                table_cols = {str(c or "").strip("`").lower() for c in analyzer.get_table_columns(table_l)}
            except Exception:
                table_cols = set()
            if table_cols and col_l not in table_cols:
                replacement = _pick_metric_col(table_l, col_l, preferred_terms=alias_tokens)
                if not replacement:
                    return m_agg.group(0)
                changed = True
                if qual_raw:
                    return f"{func}({distinct_kw}{qual_raw}.{replacement})"
                return f"{func}({distinct_kw}{replacement})"

            if _is_metric_like(table_l, col_l) or not _is_id_like(table_l, col_l):
                return m_agg.group(0)

            replacement = _pick_metric_col(table_l, col_l, preferred_terms=alias_tokens)
            if not replacement:
                return m_agg.group(0)

            changed = True
            if qual_raw:
                return f"{func}({distinct_kw}{qual_raw}.{replacement})"
            return f"{func}({distinct_kw}{replacement})"

        item2 = agg_pat.sub(_repl, item)

        # Handle anti-pattern like SUM(pay.paymentDate IS NOT NULL) when metric intent
        # clearly asks for amount/quantity/price/revenue style totals.
        if strong_metric_intent:
            def _repl_bool(m_bool: re.Match) -> str:
                nonlocal changed
                func = (m_bool.group("func") or "").upper()
                qual_raw = m_bool.group("q")
                col_raw = m_bool.group("c") or ""
                col_l = _clean_ident(col_raw)
                alias_tokens = {
                    tok
                    for tok in re.findall(
                        r"[a-z0-9]+",
                        re.sub(
                            r"([a-z0-9])([A-Z])",
                            r"\1 \2",
                            str(alias_part or "").replace("_", " ").lower(),
                        ),
                    )
                    if tok
                }

                table_l = None
                if qual_raw:
                    q_clean = _clean_ident(qual_raw)
                    table_l = _clean_ident(alias_to_table.get(qual_raw) or alias_to_table.get(q_clean) or "")
                elif len(table_universe) == 1:
                    table_l = next(iter(table_universe))

                if not table_l:
                    return m_bool.group(0)

                replacement = _pick_metric_col(table_l, col_l, preferred_terms=alias_tokens)
                if not replacement:
                    return m_bool.group(0)

                changed = True
                if qual_raw:
                    return f"{func}({qual_raw}.{replacement})"
                return f"{func}({replacement})"

            item2 = bool_agg_pat.sub(_repl_bool, item2)

        # Metric-intent drafts sometimes put COUNT(id) behind a metric alias
        # such as "total_amount".  If the alias/question points to a same-table
        # numeric metric, rewrite the projection to SUM(metric) while leaving
        # any COUNT-based HAVING threshold intact.
        alias_terms: Set[str] = set()
        if alias_part:
            alias_text = re.sub(
                r"([a-z0-9])([A-Z])",
                r"\1 \2",
                str(alias_part or "").replace("_", " ").lower(),
            )
            alias_terms = {tok for tok in re.findall(r"[a-z0-9]+", alias_text) if tok}
        count_match = count_agg_pat.match(expr_part or "")
        generic_total_terms = {
            str(t).strip().lower()
            for t in rule_list(
                ("heuristic_repairs", "count_metric_alias", "generic_total_terms"),
                [],
            )
            if str(t).strip()
        }
        alias_metric_terms = alias_terms & (metric_candidate_terms - generic_total_terms)
        entity_alias_terms: Set[str] = set()
        for table_name in table_universe:
            table_l = str(table_name or "").strip().lower()
            if not table_l:
                continue
            entity_alias_terms.update(re.findall(r"[a-z0-9]+", table_l.replace("_", " ")))
            try:
                singular = get_singular_form(table_l)
                entity_alias_terms.update(re.findall(r"[a-z0-9]+", str(singular or "").replace("_", " ").lower()))
            except Exception:
                pass
        alias_has_metric_signal = bool(alias_metric_terms)
        count_like_alias_terms = {
            str(t).strip().lower()
            for t in rule_list(
                ("heuristic_repairs", "count_metric_alias", "count_like_alias_terms"),
                [],
            )
            if str(t).strip()
        }
        alias_is_count_like = bool(
            alias_terms & (set(HELPERS_COUNT_INTENT_TERMS) | count_like_alias_terms | entity_alias_terms)
        )
        if count_match and alias_part and alias_has_metric_signal and not alias_is_count_like:
            qual_raw = count_match.group("q")
            col_raw = count_match.group("c") or ""
            col_l = _clean_ident(col_raw)
            if col_l != "*":
                table_l = None
                if qual_raw:
                    q_clean = _clean_ident(qual_raw)
                    table_l = _clean_ident(alias_to_table.get(qual_raw) or alias_to_table.get(q_clean) or "")
                elif len(table_universe) == 1:
                    table_l = next(iter(table_universe))
                if table_l and _is_id_like(table_l, col_l):
                    preferred_alias_terms = {
                        term
                        for term in alias_metric_terms
                        if term not in generic_total_terms
                    }
                    replacement = _pick_metric_col(
                        table_l,
                        col_l,
                        preferred_terms=preferred_alias_terms,
                    )
                    if replacement:
                        changed = True
                        prefix = f"{qual_raw}." if qual_raw else ""
                        item2 = re.sub(
                            r"(?is)^\s*COUNT\s*\(.*?\)",
                            f"SUM({prefix}{replacement})",
                            item2,
                            count=1,
                        )

        return item2

    select_items = _split_top_level_commas(select_part)
    rebuilt_items = [_rewrite_item(it) for it in select_items]
    if not changed:
        return sql

    new_select = ", ".join(rebuilt_items)
    return re.sub(
        r"(?is)^\s*select\s+.*?\s+from\s+",
        f"SELECT {new_select} FROM ",
        sql.strip(),
        count=1,
    )


def _question_wants_dual_fact_rollup(question: str) -> bool:
    """
    Detect dual-fact rollup intent dynamically from schema metadata.

    Target semantic shape:
    - a base entity table is explicitly mentioned
    - at least two directly connected transaction tables are also mentioned
    - one transaction family is requested as a count
    - another transaction family is requested as a total / summed metric
      or a status derived from that transaction family
    """
    q = (question or "").lower().strip()
    if not q:
        return False

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    try:
        all_tables = sorted(str(t).strip().lower() for t in (get_all_tables() or []) if str(t).strip())
    except Exception:
        all_tables = []
    try:
        transaction_tables = {
            str(t).strip().lower()
            for t in (get_transaction_tables() or [])
            if str(t).strip()
        }
    except Exception:
        transaction_tables = set()
    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}

    def _fallback_dual_fact_rollup_from_question() -> bool:
        """
        Conservative question-only fallback for environments where schema
        metadata is unavailable. This stays generic by extracting lexical
        families from the question instead of relying on specific table names.
        """
        metric_words = _dual_fact_metric_term_universe(
            transaction_tables,
            analyzer=analyzer,
            question=question,
        )

        def _collect(pattern: str, text: str = q) -> Set[str]:
            return _dual_fact_collect_families(pattern, text)

        base_families = set()
        base_families |= _collect(
            r"\b(?:for\s+each|for\s+every|per|each\s+such)\s+([a-z_][a-z0-9_]*(?:\s+[a-z_][a-z0-9_]*){0,2})\b"
        )
        base_families |= _collect(
            r"\b([a-z_][a-z0-9_]*(?:\s+[a-z_][a-z0-9_]*){0,2})\s+(?:id|name|number|code)\b"
        )

        count_families = _collect(
            r"\b(?:total\s+number\s+of|number\s+of|count\s+of|count|how\s+many)\s+(?:the\s+)?([a-z_][a-z0-9_]*(?:\s+[a-z_][a-z0-9_]*){0,2})\b"
        )
        count_families |= _collect(
            r"\btotal[_\s-]+([a-z_][a-z0-9_]*(?:\s+[a-z_][a-z0-9_]*){0,2})\b"
        )
        # "total payment amount" is a metric SUM, not a count.  Remove
        # count_families entries that contain a metric word in any position
        # so that a single metric phrase (even with trailing sort words like
        # "descending") is not double-counted as both count and metric.
        count_families -= {
            fam for fam in count_families
            if metric_words & set(fam.split())
        }

        metric_families = set()
        for metric_word in metric_words:
            metric_families |= _collect(
                rf"\b(?:total|sum(?:\s+of)?|combined|aggregate(?:d)?)\s+([a-z_][a-z0-9_]*(?:\s+[a-z_][a-z0-9_]*){{0,2}})\s+{metric_word}\b"
            )
            metric_families |= _collect(
                rf"\b{metric_word}\s+(?:for|of)\s+(?:the\s+)?([a-z_][a-z0-9_]*(?:\s+[a-z_][a-z0-9_]*){{0,2}})\b"
            )
        metric_families |= _collect(
            r"\b([a-z_][a-z0-9_]*(?:\s+[a-z_][a-z0-9_]*){0,2})[_\s-]*status\b"
        )

        if not base_families or not count_families or not metric_families:
            return False

        for base_family in base_families:
            for count_family in count_families:
                if count_family == base_family:
                    continue
                for metric_family in metric_families:
                    if metric_family in {base_family, count_family}:
                        continue
                    return True
        return False

    if not all_tables or len(transaction_tables) < 2:
        return _fallback_dual_fact_rollup_from_question()

    direct_txn_children: Dict[str, Set[str]] = {}
    for child_table, fk_targets in fk_map_raw.items():
        child_l = str(child_table or "").strip().lower()
        if child_l not in transaction_tables:
            continue
        for target_table in (fk_targets or {}).values():
            target_l = str(target_table or "").strip().lower()
            if not target_l:
                continue
            direct_txn_children.setdefault(target_l, set()).add(child_l)

    def _entity_alt(table_name: str) -> str:
        words = _entity_words_for_table(table_name)
        escaped = []
        for w in words:
            ww = (w or "").strip().lower()
            if not ww:
                continue
            escaped.append(re.escape(ww).replace(r"\ ", r"\s+"))
        escaped = sorted(set(escaped), key=len, reverse=True)
        return "|".join(escaped)

    def _has_alt(alt: str) -> bool:
        return bool(alt and re.search(rf"\b(?:{alt})\b", q, flags=re.I))

    def _table_has_entity_identity(table_name: str) -> bool:
        try:
            if get_id_column(table_name) or get_name_column(table_name):
                return True
        except Exception:
            pass
        if analyzer is not None:
            try:
                return analyzer.get_table_type(table_name) in {"dimension", "reference"}
            except Exception:
                return False
        return False

    def _count_request_for(table_name: str) -> bool:
        alt = _entity_alt(table_name)
        if not alt:
            return False
        return bool(
            re.search(
                rf"\b(?:total\s+number\s+of|number\s+of|count\s+of|count|how\s+many|jumlah)\s+(?:the\s+)?(?:{alt})\b",
                q,
                flags=re.I,
            )
        ) or bool(
            re.search(
                rf"\btotal[_\s-]+(?:{alt})\b",
                q,
                flags=re.I,
            )
        )

    def _metric_total_request_for(table_name: str) -> bool:
        alt = _entity_alt(table_name)
        metric_terms = sorted(
            _dual_fact_metric_terms_for_table(table_name, analyzer=analyzer),
            key=len,
            reverse=True,
        )
        if not alt or not metric_terms:
            return False
        metric_alt = "|".join(re.escape(t).replace(r"\ ", r"\s+") for t in metric_terms if t)
        if not metric_alt:
            return False

        has_total_phrase = bool(
            re.search(
                rf"\b(?:total|sum(?:\s+of)?|combined|aggregate(?:d)?)\s+(?:the\s+)?(?:{alt})\b",
                q,
                flags=re.I,
            )
        )
        has_metric_phrase = bool(
            re.search(
                rf"\b(?:{alt})\s+(?:{metric_alt})\b",
                q,
                flags=re.I,
            )
            or re.search(
                rf"\b(?:{metric_alt})\s+(?:for|of)\s+(?:the\s+)?(?:{alt})\b",
                q,
                flags=re.I,
            )
            or re.search(
                rf"\b(?:total|sum(?:\s+of)?|combined|aggregate(?:d)?)\s+(?:{metric_alt})\b",
                q,
                flags=re.I,
            )
        )
        has_specific_metric_hint = any(term != "total" for term in metric_terms)
        return has_total_phrase and (has_metric_phrase or has_specific_metric_hint)

    for base_table in all_tables:
        if base_table in transaction_tables:
            continue
        if not _table_has_entity_identity(base_table):
            continue
        if not _has_alt(_entity_alt(base_table)):
            continue

        child_txn_tables = sorted(direct_txn_children.get(base_table, set()))
        if len(child_txn_tables) < 2:
            continue

        mentioned_child_txns = [t for t in child_txn_tables if _has_alt(_entity_alt(t))]
        if len(mentioned_child_txns) < 2:
            continue

        count_tables = [t for t in mentioned_child_txns if _count_request_for(t)]
        metric_tables = [
            t for t in mentioned_child_txns
            if _metric_total_request_for(t) or _status_request_for_table_question(question, t)
        ]
        if any(ct != mt for ct in count_tables for mt in metric_tables):
            return True

    return _fallback_dual_fact_rollup_from_question()


def _question_wants_hierarchical_metric_rollup(question: str, ctx: str = "") -> bool:
    """
    Dynamic detector for hierarchical rollup intent:
    - "for each/per/every <entity>"
    - aggregate total/sum of a metric (amount/value/revenue/etc.)
    - multi-entity question (at least two schema entities mentioned)
    - not winner-row/latest/ranking intent
    """
    q = (question or "").lower().strip()
    if not q:
        return False

    # Exclude winner-row/latest/ranking style intents.
    if re.search(
        r"\b(latest|most\s+recent|newest|earliest|row_number|rank|dense_rank|if\s+multiple|if\s+there\s+are\s+ties)\b",
        q,
        flags=re.I,
    ):
        return False

    asks_for_each = bool(
        re.search(r"\b(?:for\s+each|per|every)\b", q, flags=re.I)
    )
    metric_terms = sorted(_ctx_metric_terms(ctx), key=len, reverse=True)
    asks_total_metric = False
    if re.search(r"\b(?:total|sum|jumlah)\b", q, flags=re.I):
        for term in metric_terms:
            tt = str(term or "").strip()
            if not tt:
                continue
            pat = re.escape(tt).replace(r"\ ", r"\s+")
            if re.search(rf"\b{pat}\b", q, flags=re.I):
                asks_total_metric = True
                break
    if not (asks_for_each and asks_total_metric):
        return False

    # Require at least two schema entities mentioned in the question.
    # This keeps the detector conservative for single-table aggregates.
    terms = sorted(_entity_terms_from_ctx(ctx), key=len, reverse=True)
    if terms:
        mentioned = 0
        for t in terms:
            tt = (t or "").strip().lower()
            if not tt:
                continue
            pat = re.escape(tt).replace(r"\ ", r"\s+")
            if re.search(rf"\b{pat}\b", q, flags=re.I):
                mentioned += 1
                if mentioned >= 2:
                    break
        if mentioned < 2:
            return False

    # Prefer include-zero style, but allow collection phrasing too.
    include_zero = _question_wants_include_zero(question, ctx)
    collection_phrase = bool(
        re.search(_hierarchical_collection_pattern(ctx), q, flags=re.I)
    )
    return include_zero or collection_phrase


def _rewrite_missing_metric_join_in_rollup(sql: str, question: str, ctx: str = "") -> str:
    """
    Schema-agnostic repair for hierarchical rollup queries where aggregate
    metric alias/table is missing.

    Typical near-miss:
      SELECT ..., SUM(p.amount) ...
      FROM A ... JOIN B ...
      GROUP BY ...
    where `p` alias/table is never joined.

    Repair strategy:
    1) If a joined table already has the metric column, remap SUM alias to that table alias.
    2) Otherwise infer a metric table (schema metadata + FK graph) and add LEFT JOIN.
    """
    if not sql or not question:
        return sql
    if not _question_wants_hierarchical_metric_rollup(question, ctx):
        return sql

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        return sql

    # Conservative: skip complex shapes.
    if (parsed.get("where") or "").strip():
        return sql
    if (parsed.get("having") or "").strip():
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if not from_core or "join" not in from_core.lower():
        return sql
    if re.search(r"\brow_number\s*\(", sql, flags=re.I):
        return sql

    # Ordered source list (alias -> table), including aliasless table refs.
    source_pairs: List[Tuple[str, str]] = []
    seen_aliases: Set[str] = set()
    reserved_alias_tokens = {
        "left", "right", "inner", "outer", "full", "cross", "join",
        "on", "where", "group", "order", "having", "limit",
    }
    for m_tbl in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?""",
        f"FROM {from_core}",
    ):
        raw_tbl = (m_tbl.group(1) or "").replace("`", "").strip()
        tbl = raw_tbl.split(".")[-1].lower()
        if not tbl:
            continue
        alias_raw = (m_tbl.group(2) or "").strip()
        if alias_raw.lower() in reserved_alias_tokens:
            alias_raw = ""
        alias = (alias_raw or tbl).strip()
        alias_l = alias.lower()
        if not alias_l or alias_l in seen_aliases:
            continue
        seen_aliases.add(alias_l)
        source_pairs.append((alias, tbl))

    if len(source_pairs) < 2:
        return sql
    alias_to_table: Dict[str, str] = {a.lower(): t for a, t in source_pairs}

    # Parse SELECT items to find SUM(alias.metric_col) references.
    select_items = _split_top_level_commas(parsed["select"])
    if not select_items:
        return sql

    def _split_expr_alias(item: str) -> tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m:
            return (item or "").strip(), None
        return (m.group(1) or "").strip(), (m.group(2) or "").strip()

    sum_ref_pat = re.compile(
        r"""(?is)\bSUM\s*\(\s*(?:DISTINCT\s+)?`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)"""
    )

    missing_ref = None
    for idx, raw_item in enumerate(select_items):
        expr, _out_alias = _split_expr_alias(raw_item)
        for m_sum in sum_ref_pat.finditer(expr):
            ref_alias = str(m_sum.group("alias") or "").strip()
            ref_col = str(m_sum.group("col") or "").strip()
            if not ref_alias or not ref_col:
                continue
            if ref_alias.lower() not in alias_to_table:
                missing_ref = {
                    "item_idx": idx,
                    "old_alias": ref_alias,
                    "metric_col": ref_col,
                }
                break
        if missing_ref:
            break

    if not missing_ref:
        return sql

    metric_col = str(missing_ref["metric_col"]).strip()
    metric_col_l = metric_col.lower()
    old_alias = str(missing_ref["old_alias"]).strip()
    item_idx = int(missing_ref["item_idx"])

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    allowed_identifiers = _parse_allowed_identifiers(ctx)

    def _table_cols_lower(table: str) -> Set[str]:
        table_l = str(table or "").lower().strip()
        if not table_l:
            return set()
        if analyzer is not None:
            try:
                return {
                    str(c).strip("`").lower()
                    for c in analyzer.get_table_columns(table_l)
                }
            except Exception:
                pass
        for t, cols in (allowed_identifiers or {}).items():
            if str(t or "").lower().strip() != table_l:
                continue
            return {
                str(c).strip("`").lower()
                for c in (cols or set())
                if str(c or "").strip()
            }
        return set()

    # Case A: table with metric already joined -> remap alias only.
    joined_metric_aliases = [
        a for a, t in source_pairs
        if metric_col_l in _table_cols_lower(t)
    ]
    if joined_metric_aliases:
        new_alias = joined_metric_aliases[0]
        pat_ref = re.compile(
            rf"""(?is)\b`?{re.escape(old_alias)}`?\s*\.\s*`?{re.escape(metric_col)}`?\b"""
        )
        select_items[item_idx] = pat_ref.sub(
            f"{new_alias}.{metric_col}",
            select_items[item_idx],
        )
        new_select = ", ".join(select_items)
        rebuilt = f"SELECT {new_select} FROM {from_core}"
        if (parsed.get("where") or "").strip():
            rebuilt += f" {parsed['where'].strip()}"
        rebuilt += f" GROUP BY {parsed['groupby'].strip()}"
        if (parsed.get("tail") or "").strip():
            rebuilt += f" {parsed['tail'].strip()}"
        if sql.strip().endswith(";"):
            rebuilt += ";"
        return rebuilt

    # Case B: infer missing metric table using schema + FK graph.
    if analyzer is not None:
        try:
            all_tables = sorted(str(t).lower() for t in get_all_tables())
        except Exception:
            all_tables = []
    else:
        all_tables = sorted(str(t).lower() for t in (allowed_identifiers or {}).keys())
    if not all_tables:
        return sql
    metric_tables = [
        t for t in all_tables
        if metric_col_l in _table_cols_lower(t) and t not in {tbl for _, tbl in source_pairs}
    ]
    if not metric_tables:
        return sql

    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, mapping in fk_map_raw.items():
        src_l = str(src or "").lower().strip()
        if not src_l:
            continue
        fk_map[src_l] = {}
        for fk_col, tgt in (mapping or {}).items():
            fk_l = str(fk_col or "").lower().strip()
            tgt_l = str(tgt or "").lower().strip()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    def _safe_id_col(table_name: str) -> str:
        try:
            return (get_id_column(table_name) or "").strip()
        except Exception:
            return ""

    def _find_join_plan(metric_table: str) -> Optional[Tuple[str, str, str, str, str]]:
        # returns:
        # ("conn_to_metric", conn_alias, conn_fk_col, metric_table, metric_key_col)
        # or ("metric_to_conn", conn_alias, metric_fk_col, metric_table, conn_key_col)
        for conn_alias, conn_table in source_pairs:
            for fk_col, tgt in (fk_map.get(conn_table, {}) or {}).items():
                if tgt == metric_table:
                    metric_key = (_safe_id_col(metric_table) or fk_col or "").strip()
                    if metric_key:
                        return ("conn_to_metric", conn_alias, fk_col, metric_table, metric_key)
            for fk_col, tgt in (fk_map.get(metric_table, {}) or {}).items():
                if tgt == conn_table:
                    conn_key = (_safe_id_col(conn_table) or fk_col or "").strip()
                    if conn_key:
                        return ("metric_to_conn", conn_alias, fk_col, metric_table, conn_key)

            # Fallback when FK metadata is unavailable:
            # join by shared key-like column names between connector and metric tables.
            metric_cols = _table_cols_lower(metric_table)
            conn_cols = _table_cols_lower(conn_table)
            shared_key_cols = sorted(
                c for c in (metric_cols & conn_cols)
                if c.endswith(("id", "number", "code", "key"))
            )
            if shared_key_cols:
                best = shared_key_cols[0]
                metric_id = (_safe_id_col(metric_table) or "").lower()
                conn_id = (_safe_id_col(conn_table) or "").lower()
                if metric_id and metric_id in shared_key_cols:
                    best = metric_id
                elif conn_id and conn_id in shared_key_cols:
                    best = conn_id
                return ("shared_key", conn_alias, best, metric_table, best)
        return None

    try:
        transaction_tables = {str(t).lower() for t in get_transaction_tables()}
    except Exception:
        transaction_tables = set()

    candidates: List[Tuple[int, str, Tuple[str, str, str, str, str]]] = []
    q = (question or "").lower()
    for mt in metric_tables:
        plan = _find_join_plan(mt)
        if plan is None:
            continue
        score = 0
        if mt in transaction_tables:
            score += 3
        # Small intent boost when table name/synonym appears in question.
        words = _entity_words_for_table(mt)
        mentioned_metric_table = False
        for w in words:
            ww = (w or "").strip()
            if not ww:
                continue
            w_pat = re.escape(ww).replace(r"\ ", r"\s+")
            if re.search(rf"\b{w_pat}\b", q, flags=re.I):
                mentioned_metric_table = True
                break
        if mentioned_metric_table:
            score += 1
        if plan[0] == "metric_to_conn":
            score += 1
        candidates.append((score, mt, plan))

    if not candidates:
        return sql
    candidates.sort(key=lambda x: (-x[0], x[1]))
    _score, metric_table, plan = candidates[0]

    used_aliases = {a.lower() for a, _t in source_pairs}
    metric_alias = _alias_for_table(metric_table, used_aliases)

    join_mode, conn_alias, lhs_fk_col, _mt, rhs_key_col = plan
    if join_mode == "conn_to_metric":
        on_clause = f"{conn_alias}.{lhs_fk_col} = {metric_alias}.{rhs_key_col}"
    elif join_mode == "shared_key":
        on_clause = f"{metric_alias}.{lhs_fk_col} = {conn_alias}.{rhs_key_col}"
    else:
        on_clause = f"{metric_alias}.{lhs_fk_col} = {conn_alias}.{rhs_key_col}"

    from_core_new = f"{from_core} LEFT JOIN {metric_table} AS {metric_alias} ON {on_clause}"
    pat_ref = re.compile(
        rf"""(?is)\b`?{re.escape(old_alias)}`?\s*\.\s*`?{re.escape(metric_col)}`?\b"""
    )
    select_items[item_idx] = pat_ref.sub(
        f"{metric_alias}.{metric_col}",
        select_items[item_idx],
    )

    new_select = ", ".join(select_items)
    rebuilt = f"SELECT {new_select} FROM {from_core_new}"
    if (parsed.get("where") or "").strip():
        rebuilt += f" {parsed['where'].strip()}"
    rebuilt += f" GROUP BY {parsed['groupby'].strip()}"
    if (parsed.get("tail") or "").strip():
        rebuilt += f" {parsed['tail'].strip()}"
    if sql.strip().endswith(";"):
        rebuilt += ";"
    return rebuilt


def _rewrite_missing_metric_join_for_unqualified_rollup(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair grouped single-source rollups that aggregate a metric column which
    is not present in the base table (unqualified reference).

    Example near-miss:
      SELECT ..., SUM(quantityOrdered) ...
      FROM products
      GROUP BY ...

    where `quantityOrdered` belongs to another FK-related table.
    """
    if not sql:
        return sql

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if not from_core or "join" in from_core.lower():
        return sql
    if re.search(r"\brow_number\s*\(", sql, flags=re.I):
        return sql

    reserved_alias_tokens = {
        "left", "right", "inner", "outer", "full", "cross", "join",
        "on", "where", "group", "order", "having", "limit",
    }
    source_pairs: List[Tuple[str, str]] = []
    seen_aliases: Set[str] = set()
    for m_tbl in re.finditer(
        r"""(?is)\bFROM\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?""",
        f"FROM {from_core}",
    ):
        raw_tbl = (m_tbl.group(1) or "").replace("`", "").strip()
        tbl = raw_tbl.split(".")[-1].lower()
        if not tbl:
            continue
        alias_raw = (m_tbl.group(2) or "").strip()
        if alias_raw.lower() in reserved_alias_tokens:
            alias_raw = ""
        alias = (alias_raw or tbl).strip()
        alias_l = alias.lower()
        if not alias_l or alias_l in seen_aliases:
            continue
        seen_aliases.add(alias_l)
        source_pairs.append((alias, tbl))

    if len(source_pairs) != 1:
        return sql
    base_alias, base_table = source_pairs[0]
    base_alias_l = base_alias.lower()
    base_table_l = base_table.lower()

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    allowed_identifiers = _parse_allowed_identifiers(ctx)

    def _table_cols_lower(table: str) -> Set[str]:
        table_l = str(table or "").lower().strip()
        if not table_l:
            return set()
        if analyzer is not None:
            try:
                return {
                    str(c).strip("`").lower()
                    for c in analyzer.get_table_columns(table_l)
                }
            except Exception:
                pass
        for t, cols in (allowed_identifiers or {}).items():
            if str(t or "").lower().strip() != table_l:
                continue
            return {
                str(c).strip("`").lower()
                for c in (cols or set())
                if str(c or "").strip()
            }
        return set()

    base_cols = _table_cols_lower(base_table_l)
    if not base_cols:
        return sql

    select_items = _split_top_level_commas(parsed.get("select", ""))
    if not select_items:
        return sql

    agg_ref_pat = re.compile(
        r"""(?is)\b(?P<func>SUM|AVG|MIN|MAX)\s*\(\s*(?P<distinct>DISTINCT\s+)?(?:(?P<alias>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<col>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)"""
    )

    missing_metric_cols: Set[str] = set()
    saw_candidate_agg = False
    for item in select_items:
        for m_agg in agg_ref_pat.finditer(item):
            saw_candidate_agg = True
            qual_alias = str(m_agg.group("alias") or "").strip("`").lower()
            col_name = str(m_agg.group("col") or "").strip("`").lower()
            if not col_name:
                continue
            if qual_alias and qual_alias not in {base_alias_l, base_table_l}:
                continue
            if col_name in base_cols:
                continue
            missing_metric_cols.add(col_name)

    if not saw_candidate_agg or not missing_metric_cols:
        return sql

    if analyzer is not None:
        try:
            all_tables = sorted(str(t).lower() for t in get_all_tables())
        except Exception:
            all_tables = []
    else:
        all_tables = sorted(str(t).lower() for t in (allowed_identifiers or {}).keys())
    if not all_tables:
        return sql

    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, mapping in fk_map_raw.items():
        src_l = str(src or "").lower().strip()
        if not src_l:
            continue
        fk_map[src_l] = {}
        for fk_col, tgt in (mapping or {}).items():
            fk_l = str(fk_col or "").lower().strip()
            tgt_l = str(tgt or "").lower().strip()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    def _safe_id_col(table_name: str) -> str:
        try:
            return (get_id_column(table_name) or "").strip()
        except Exception:
            return ""

    def _find_join_plan(metric_table: str) -> Optional[Tuple[str, str, str]]:
        # returns:
        # ("base_to_metric", base_fk_col, metric_key_col)
        # or ("metric_to_base", metric_fk_col, base_key_col)
        # or ("shared_key", key_col, key_col)
        for fk_col, tgt in (fk_map.get(base_table_l, {}) or {}).items():
            if tgt == metric_table:
                metric_key = (_safe_id_col(metric_table) or fk_col or "").strip()
                if metric_key:
                    return ("base_to_metric", fk_col, metric_key)
        for fk_col, tgt in (fk_map.get(metric_table, {}) or {}).items():
            if tgt == base_table_l:
                base_key = (_safe_id_col(base_table_l) or fk_col or "").strip()
                if base_key:
                    return ("metric_to_base", fk_col, base_key)

        metric_cols = _table_cols_lower(metric_table)
        shared_key_cols = sorted(
            c for c in (metric_cols & base_cols)
            if c.endswith(("id", "number", "code", "key"))
        )
        if not shared_key_cols:
            return None
        best = shared_key_cols[0]
        metric_id = (_safe_id_col(metric_table) or "").lower()
        base_id = (_safe_id_col(base_table_l) or "").lower()
        if metric_id and metric_id in shared_key_cols:
            best = metric_id
        elif base_id and base_id in shared_key_cols:
            best = base_id
        return ("shared_key", best, best)

    try:
        transaction_tables = {str(t).lower() for t in get_transaction_tables()}
    except Exception:
        transaction_tables = set()

    candidates: List[Tuple[int, str, Tuple[str, str, str]]] = []
    q = (question or "").lower()
    for table_name in all_tables:
        if table_name == base_table_l:
            continue
        cols = _table_cols_lower(table_name)
        if not cols or not missing_metric_cols.issubset(cols):
            continue
        plan = _find_join_plan(table_name)
        if plan is None:
            continue
        score = 0
        if table_name in transaction_tables:
            score += 3
        for w in _entity_words_for_table(table_name):
            ww = (w or "").strip()
            if not ww:
                continue
            w_pat = re.escape(ww).replace(r"\ ", r"\s+")
            if re.search(rf"\b{w_pat}\b", q, flags=re.I):
                score += 1
                break
        if plan[0] == "metric_to_base":
            score += 1
        candidates.append((score, table_name, plan))

    if not candidates:
        return sql
    candidates.sort(key=lambda x: (-x[0], x[1]))
    if len(candidates) > 1 and candidates[0][0] == candidates[1][0]:
        return sql

    _score, metric_table, join_plan = candidates[0]
    used_aliases = {base_alias_l}
    metric_alias = _alias_for_table(metric_table, used_aliases)

    join_mode, lhs_col, rhs_col = join_plan
    if join_mode == "base_to_metric":
        on_clause = f"{base_alias}.{lhs_col} = {metric_alias}.{rhs_col}"
    elif join_mode == "metric_to_base":
        on_clause = f"{metric_alias}.{lhs_col} = {base_alias}.{rhs_col}"
    else:
        on_clause = f"{metric_alias}.{lhs_col} = {base_alias}.{rhs_col}"

    join_kw = "LEFT JOIN" if _question_wants_include_zero(question, ctx) else "JOIN"
    from_core_new = f"{from_core} {join_kw} {metric_table} AS {metric_alias} ON {on_clause}"

    missing_set = set(missing_metric_cols)

    def _qualify_item(item: str) -> str:
        def _repl(m_agg: re.Match) -> str:
            func = (m_agg.group("func") or "").upper()
            distinct_kw = m_agg.group("distinct") or ""
            qual_raw = (m_agg.group("alias") or "").strip()
            col_raw = m_agg.group("col") or ""
            col_l = str(col_raw).strip("`").lower()
            if qual_raw:
                qual_l = qual_raw.strip("`").lower()
                if qual_l not in {base_alias_l, base_table_l}:
                    return m_agg.group(0)
            if col_l not in missing_set:
                return m_agg.group(0)
            return f"{func}({distinct_kw}{metric_alias}.{col_raw.strip('`')})"

        return agg_ref_pat.sub(_repl, item)

    select_items_new = [_qualify_item(it) for it in select_items]
    if select_items_new == select_items:
        return sql

    rebuilt = f"SELECT {', '.join(select_items_new)} FROM {from_core_new}"
    if (parsed.get("where") or "").strip():
        rebuilt += f" {parsed['where'].strip()}"
    rebuilt += f" GROUP BY {parsed['groupby'].strip()}"
    if (parsed.get("tail") or "").strip():
        rebuilt += f" {parsed['tail'].strip()}"
    if sql.strip().endswith(";"):
        rebuilt += ";"
    return rebuilt


def _rewrite_missing_metric_join_for_unqualified_setop_rollup(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair top-level UNION/UNION ALL rollups where one or more branches
    aggregate an unqualified metric column that does not belong to the branch
    base table.

    Conservative scope:
    - top-level set operation only
    - each branch is a flat single-table SELECT ... FROM ... [WHERE ...]
    - no GROUP BY / HAVING / JOIN in branches
    """
    if not sql or "UNION" not in (sql or "").upper():
        return sql

    s = (sql or "").strip()
    trailing = ";" if s.endswith(";") else ""
    body = s[:-1].rstrip() if trailing else s

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        target = kw.upper()
        t_up = text.upper()
        depth = 0
        quote = ""
        i = start
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and t_up.startswith(target, i):
                prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                after = i + len(target)
                next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    def _split_union_chain(text: str) -> Tuple[List[str], List[str]]:
        branches: List[str] = []
        operators: List[str] = []
        depth = 0
        quote = ""
        start = 0
        i = 0
        t_up = text.upper()
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0:
                token = ""
                if t_up.startswith("UNION ALL", i):
                    token = "UNION ALL"
                elif t_up.startswith("UNION", i):
                    token = "UNION"
                if token:
                    prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                    after = i + len(token)
                    next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                    if prev_ok and next_ok:
                        branch = text[start:i].strip()
                        if not branch:
                            return [], []
                        branches.append(branch)
                        operators.append(token)
                        start = after
                        i = after
                        continue
            i += 1
        tail = text[start:].strip()
        if tail:
            branches.append(tail)
        return branches, operators

    def _rewrite_branch(branch_sql: str) -> str:
        branch = (branch_sql or "").strip()
        if not branch:
            return branch_sql
        if re.search(r"\b(?:GROUP\s+BY|HAVING|JOIN|INTERSECT|EXCEPT|UNION)\b", branch, flags=re.I):
            return branch_sql
        if re.search(r"\b(?:FROM|JOIN)\s*\(", branch, flags=re.I):
            return branch_sql
        if re.search(r"\bROW_NUMBER\s*\(", branch, flags=re.I):
            return branch_sql

        m_sel = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<after>.+?)\s*$", branch)
        if not m_sel:
            return branch_sql
        select_part = (m_sel.group("select") or "").strip()
        after_from = (m_sel.group("after") or "").strip()
        if not select_part or not after_from:
            return branch_sql

        where_match = re.search(r"\bWHERE\b", after_from, flags=re.I)
        if where_match:
            from_core = after_from[:where_match.start()].strip()
            where_part = after_from[where_match.start():].strip()
        else:
            from_core = after_from
            where_part = ""
        if not from_core or "join" in from_core.lower():
            return branch_sql

        reserved_alias_tokens = {
            "left", "right", "inner", "outer", "full", "cross", "join",
            "on", "where", "group", "order", "having", "limit",
        }
        source_pairs: List[Tuple[str, str]] = []
        seen_aliases: Set[str] = set()
        for m_tbl in re.finditer(
            r"""(?is)\bFROM\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?""",
            f"FROM {from_core}",
        ):
            raw_tbl = (m_tbl.group(1) or "").replace("`", "").strip()
            tbl = raw_tbl.split(".")[-1].lower()
            if not tbl:
                continue
            alias_raw = (m_tbl.group(2) or "").strip()
            if alias_raw.lower() in reserved_alias_tokens:
                alias_raw = ""
            alias = (alias_raw or tbl).strip()
            alias_l = alias.lower()
            if not alias_l or alias_l in seen_aliases:
                continue
            seen_aliases.add(alias_l)
            source_pairs.append((alias, tbl))

        if len(source_pairs) != 1:
            return branch_sql
        base_alias, base_table = source_pairs[0]
        base_alias_l = base_alias.lower()
        base_table_l = base_table.lower()

        try:
            analyzer = get_schema_analyzer()
        except Exception:
            analyzer = None
        allowed_identifiers = _parse_allowed_identifiers(ctx)

        def _table_cols_lower(table: str) -> Set[str]:
            table_l = str(table or "").lower().strip()
            if not table_l:
                return set()
            if analyzer is not None:
                try:
                    return {
                        str(c).strip("`").lower()
                        for c in analyzer.get_table_columns(table_l)
                    }
                except Exception:
                    pass
            for t, cols in (allowed_identifiers or {}).items():
                if str(t or "").lower().strip() != table_l:
                    continue
                return {
                    str(c).strip("`").lower()
                    for c in (cols or set())
                    if str(c or "").strip()
                }
            return set()

        base_cols = _table_cols_lower(base_table_l)
        if not base_cols:
            return branch_sql

        select_items = _split_top_level_commas(select_part)
        if not select_items:
            return branch_sql

        agg_ref_pat = re.compile(
            r"""(?is)\b(?P<func>SUM|AVG|MIN|MAX)\s*\(\s*(?P<distinct>DISTINCT\s+)?(?:(?P<alias>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<col>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)"""
        )

        missing_metric_cols: Set[str] = set()
        saw_candidate_agg = False
        for item in select_items:
            for m_agg in agg_ref_pat.finditer(item):
                saw_candidate_agg = True
                qual_alias = str(m_agg.group("alias") or "").strip("`").lower()
                col_name = str(m_agg.group("col") or "").strip("`").lower()
                if not col_name:
                    continue
                if qual_alias and qual_alias not in {base_alias_l, base_table_l}:
                    continue
                if col_name in base_cols:
                    continue
                missing_metric_cols.add(col_name)

        if not saw_candidate_agg or not missing_metric_cols:
            return branch_sql

        if analyzer is not None:
            try:
                all_tables = sorted(str(t).lower() for t in get_all_tables())
            except Exception:
                all_tables = []
        else:
            all_tables = sorted(str(t).lower() for t in (allowed_identifiers or {}).keys())
        if not all_tables:
            return branch_sql

        try:
            fk_map_raw = get_fk_relationships() or {}
        except Exception:
            fk_map_raw = {}
        fk_map: Dict[str, Dict[str, str]] = {}
        for src, mapping in fk_map_raw.items():
            src_l = str(src or "").lower().strip()
            if not src_l:
                continue
            fk_map[src_l] = {}
            for fk_col, tgt in (mapping or {}).items():
                fk_l = str(fk_col or "").lower().strip()
                tgt_l = str(tgt or "").lower().strip()
                if fk_l and tgt_l:
                    fk_map[src_l][fk_l] = tgt_l

        def _safe_id_col(table_name: str) -> str:
            try:
                return (get_id_column(table_name) or "").strip()
            except Exception:
                return ""

        def _find_join_plan(metric_table: str) -> Optional[Tuple[str, str, str]]:
            for fk_col, tgt in (fk_map.get(base_table_l, {}) or {}).items():
                if tgt == metric_table:
                    metric_key = (_safe_id_col(metric_table) or fk_col or "").strip()
                    if metric_key:
                        return ("base_to_metric", fk_col, metric_key)
            for fk_col, tgt in (fk_map.get(metric_table, {}) or {}).items():
                if tgt == base_table_l:
                    base_key = (_safe_id_col(base_table_l) or fk_col or "").strip()
                    if base_key:
                        return ("metric_to_base", fk_col, base_key)

            metric_cols = _table_cols_lower(metric_table)
            shared_key_cols = sorted(
                c for c in (metric_cols & base_cols)
                if c.endswith(("id", "number", "code", "key"))
            )
            if not shared_key_cols:
                return None
            best = shared_key_cols[0]
            metric_id = (_safe_id_col(metric_table) or "").lower()
            base_id = (_safe_id_col(base_table_l) or "").lower()
            if metric_id and metric_id in shared_key_cols:
                best = metric_id
            elif base_id and base_id in shared_key_cols:
                best = base_id
            return ("shared_key", best, best)

        try:
            transaction_tables = {str(t).lower() for t in get_transaction_tables()}
        except Exception:
            transaction_tables = set()

        candidates: List[Tuple[int, str, Tuple[str, str, str]]] = []
        q = (question or "").lower()
        for table_name in all_tables:
            if table_name == base_table_l:
                continue
            cols = _table_cols_lower(table_name)
            if not cols or not missing_metric_cols.issubset(cols):
                continue
            plan = _find_join_plan(table_name)
            if plan is None:
                continue
            score = 0
            if table_name in transaction_tables:
                score += 3
            for w in _entity_words_for_table(table_name):
                ww = (w or "").strip()
                if not ww:
                    continue
                w_pat = re.escape(ww).replace(r"\ ", r"\s+")
                if re.search(rf"\b{w_pat}\b", q, flags=re.I):
                    score += 1
                    break
            if plan[0] == "metric_to_base":
                score += 1
            candidates.append((score, table_name, plan))

        if not candidates:
            return branch_sql
        candidates.sort(key=lambda x: (-x[0], x[1]))
        if len(candidates) > 1 and candidates[0][0] == candidates[1][0]:
            return branch_sql

        _score, metric_table, join_plan = candidates[0]
        metric_cols = _table_cols_lower(metric_table)
        used_aliases = {base_alias_l}
        metric_alias = _alias_for_table(metric_table, used_aliases)

        join_mode, lhs_col, rhs_col = join_plan
        if join_mode == "base_to_metric":
            on_clause = f"{base_alias}.{lhs_col} = {metric_alias}.{rhs_col}"
        elif join_mode == "metric_to_base":
            on_clause = f"{metric_alias}.{lhs_col} = {base_alias}.{rhs_col}"
        else:
            on_clause = f"{metric_alias}.{lhs_col} = {base_alias}.{rhs_col}"

        join_kw = "LEFT JOIN" if _question_wants_include_zero(question, ctx) else "JOIN"
        from_core_new = f"{from_core} {join_kw} {metric_table} AS {metric_alias} ON {on_clause}"
        missing_set = set(missing_metric_cols)

        def _qualify_item(item: str) -> str:
            def _repl(m_agg: re.Match) -> str:
                func = (m_agg.group("func") or "").upper()
                distinct_kw = m_agg.group("distinct") or ""
                qual_raw = (m_agg.group("alias") or "").strip()
                col_raw = m_agg.group("col") or ""
                col_l = str(col_raw).strip("`").lower()
                if qual_raw:
                    qual_l = qual_raw.strip("`").lower()
                    if qual_l not in {base_alias_l, base_table_l}:
                        return m_agg.group(0)
                if col_l not in missing_set:
                    return m_agg.group(0)
                return f"{func}({distinct_kw}{metric_alias}.{col_raw.strip('`')})"

            return agg_ref_pat.sub(_repl, item)

        select_items_new = [_qualify_item(it) for it in select_items]

        # After JOIN injection, unqualified COUNT(DISTINCT col) can become
        # ambiguous when both tables share the same key-like column name.
        # Prefer explicit base qualification for stable entity counting.
        count_distinct_pat = re.compile(
            r"""(?is)\bCOUNT\s*\(\s*DISTINCT\s+(?:(?P<alias>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<col>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)"""
        )

        def _qualify_count_distinct_item(item: str) -> str:
            def _repl_count(m_cd: re.Match) -> str:
                qual_raw = (m_cd.group("alias") or "").strip()
                if qual_raw:
                    return m_cd.group(0)
                col_raw = m_cd.group("col") or ""
                col_name = str(col_raw).strip("`").lower()
                if not col_name:
                    return m_cd.group(0)
                # Only force base qualification when the column belongs to the
                # base table (typical entity id/key). This avoids changing
                # metric-side distinct semantics.
                if col_name not in base_cols:
                    return m_cd.group(0)
                # If metric table also has same name, qualification is needed
                # to avoid ambiguity; otherwise qualification is harmless.
                if col_name in metric_cols or col_name in base_cols:
                    return f"COUNT(DISTINCT {base_alias}.{col_raw.strip('`')})"
                return m_cd.group(0)

            return count_distinct_pat.sub(_repl_count, item)

        select_items_new = [_qualify_count_distinct_item(it) for it in select_items_new]
        if select_items_new == select_items:
            return branch_sql

        rebuilt = f"SELECT {', '.join(select_items_new)} FROM {from_core_new}"
        if where_part:
            rebuilt += f" {where_part}"
        return rebuilt

    order_pos = _find_top_level_kw(body, "ORDER BY")
    if order_pos >= 0:
        core = body[:order_pos].rstrip()
        order_clause = body[order_pos + len("ORDER BY"):].strip()
    else:
        core = body
        order_clause = ""

    branches, operators = _split_union_chain(core)
    if len(branches) < 2 or len(operators) != len(branches) - 1:
        return sql

    changed = False
    rewritten_branches: List[str] = []
    for b in branches:
        rb = _rewrite_branch(b)
        if rb != b:
            changed = True
        rewritten_branches.append(rb)

    if not changed:
        return sql

    rebuilt = rewritten_branches[0]
    for op, branch in zip(operators, rewritten_branches[1:]):
        rebuilt += f" {op} {branch}"
    if order_clause:
        rebuilt += f" ORDER BY {order_clause}"
    if trailing:
        rebuilt += ";"
    return rebuilt


def _rewrite_invalid_metric_bridge_rollup(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair grouped metric rollups where a metric fact table is joined directly
    to the base entity with an invalid key even though schema metadata implies
    a missing one-hop bridge table.

    Keeps scope intentionally narrow:
    - grouped query
    - no WHERE/HAVING
    - exactly two tables in FROM/JOIN
    - aggregate metric references only the joined metric table
    """
    if not sql or not question:
        return sql

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        return sql
    if (parsed.get("where") or "").strip():
        return sql
    if (parsed.get("having") or "").strip():
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if not from_core or "join" not in from_core.lower():
        return sql
    if re.search(r"\brow_number\s*\(", sql, flags=re.I):
        return sql

    reserved_alias_tokens = {
        "left", "right", "inner", "outer", "full", "cross", "join",
        "on", "where", "group", "order", "having", "limit",
    }
    source_pairs: List[Tuple[str, str]] = []
    seen_aliases: Set[str] = set()
    for m_tbl in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?""",
        f"FROM {from_core}",
    ):
        raw_tbl = (m_tbl.group(1) or "").replace("`", "").strip()
        tbl = raw_tbl.split(".")[-1].lower()
        if not tbl:
            continue
        alias_raw = (m_tbl.group(2) or "").strip()
        if alias_raw.lower() in reserved_alias_tokens:
            alias_raw = ""
        alias = (alias_raw or tbl).strip()
        alias_l = alias.lower()
        if not alias_l or alias_l in seen_aliases:
            continue
        seen_aliases.add(alias_l)
        source_pairs.append((alias, tbl))

    if len(source_pairs) != 2:
        return sql

    base_alias, base_table = source_pairs[0]
    metric_alias, metric_table = source_pairs[1]
    metric_alias_l = metric_alias.lower()
    base_alias_l = base_alias.lower()

    # Self-joins are valid for cumulative/running and intra-table comparative
    # shapes; they do not imply a missing bridge table.
    if base_table == metric_table:
        return sql

    def _split_expr_alias(item: str) -> tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m:
            return (item or "").strip(), None
        return (m.group(1) or "").strip(), (m.group(2) or "").strip()

    def _parse_simple_col(expr: str) -> Optional[Tuple[str, str]]:
        m = re.match(
            r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            (expr or "").strip(),
        )
        if not m:
            return None
        alias = str(m.group(1) or "").strip()
        col = str(m.group(2) or "").strip()
        if not alias or not col:
            return None
        return alias, col

    select_items = _split_top_level_commas(parsed.get("select", ""))
    if not select_items:
        return sql

    sum_pat = re.compile(r"(?is)\bSUM\s*\(\s*(.+?)\s*\)")
    sum_alias_refs: Set[str] = set()
    projected_simple_aliases: Set[str] = set()
    for raw_item in select_items:
        expr, _out_alias = _split_expr_alias(raw_item)
        if re.search(r"(?is)\b(?:count|avg|min|max|row_number|rank|dense_rank)\s*\(", expr):
            return sql
        for m_sum in sum_pat.finditer(expr):
            inner = (m_sum.group(1) or "").strip()
            refs = re.findall(
                r"(?is)\b`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?\b",
                inner,
            )
            sum_alias_refs.update(str(r).strip().lower() for r in refs if str(r).strip())
        if re.search(r"(?is)\bSUM\s*\(", expr):
            continue
        parsed_col = _parse_simple_col(expr)
        if not parsed_col:
            return sql
        projected_simple_aliases.add(parsed_col[0].lower())

    if sum_alias_refs != {metric_alias_l}:
        return sql
    if projected_simple_aliases != {base_alias_l}:
        return sql

    group_items = _split_top_level_commas(parsed.get("groupby", ""))
    if not group_items:
        return sql
    for raw_group in group_items:
        parsed_group = _parse_simple_col(raw_group)
        if not parsed_group or parsed_group[0].lower() != base_alias_l:
            return sql

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    if analyzer is None:
        return sql

    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, mapping in fk_map_raw.items():
        src_l = str(src or "").strip().lower()
        if not src_l:
            continue
        fk_map[src_l] = {}
        for fk_col, tgt in (mapping or {}).items():
            fk_s = str(fk_col or "").strip()
            tgt_l = str(tgt or "").strip().lower()
            if fk_s and tgt_l:
                fk_map[src_l][fk_s] = tgt_l

    def _safe_id_col(table_name: str) -> str:
        try:
            return str(get_id_column(table_name) or "").strip()
        except Exception:
            return ""

    def _direct_relation_exists(left_table: str, right_table: str) -> bool:
        for tgt in (fk_map.get(left_table.lower(), {}) or {}).values():
            if str(tgt).lower() == right_table.lower():
                return True
        for tgt in (fk_map.get(right_table.lower(), {}) or {}).values():
            if str(tgt).lower() == left_table.lower():
                return True
        return False

    if _direct_relation_exists(base_table, metric_table):
        return sql

    def _join_edge(left_table: str, right_table: str) -> Optional[Tuple[str, str, str]]:
        left_l = left_table.lower()
        right_l = right_table.lower()
        for fk_col, tgt in (fk_map.get(left_l, {}) or {}).items():
            if str(tgt).lower() == right_l:
                return ("left_child", str(fk_col).strip(), _safe_id_col(right_l) or str(fk_col).strip())
        for fk_col, tgt in (fk_map.get(right_l, {}) or {}).items():
            if str(tgt).lower() == left_l:
                return ("right_child", str(fk_col).strip(), _safe_id_col(left_l) or str(fk_col).strip())
        return None

    existing_tables = {t for _a, t in source_pairs}
    try:
        all_tables = [str(t).strip().lower() for t in get_all_tables() if str(t).strip()]
    except Exception:
        all_tables = []
    if not all_tables:
        return sql

    try:
        txn_tables = {str(t).strip().lower() for t in get_transaction_tables() if str(t).strip()}
    except Exception:
        txn_tables = set()
    q = (question or "").lower()
    bridge_candidates: List[Tuple[int, str, Tuple[str, str, str], Tuple[str, str, str]]] = []
    for bridge_table in all_tables:
        if bridge_table in existing_tables:
            continue
        edge_base_bridge = _join_edge(base_table, bridge_table)
        edge_bridge_metric = _join_edge(bridge_table, metric_table)
        if not edge_base_bridge or not edge_bridge_metric:
            continue
        score = 0
        if bridge_table in txn_tables:
            score += 2
        for word in _entity_words_for_table(bridge_table):
            ww = (word or "").strip().lower()
            if not ww:
                continue
            w_pat = re.escape(ww).replace(r"\ ", r"\s+")
            if re.search(rf"\b{w_pat}\b", q, flags=re.I):
                score += 4
                break
        bridge_candidates.append((score, bridge_table, edge_base_bridge, edge_bridge_metric))

    if not bridge_candidates:
        return sql
    bridge_candidates.sort(key=lambda x: (-x[0], x[1]))
    _score, bridge_table, edge_base_bridge, edge_bridge_metric = bridge_candidates[0]

    used_aliases = {a.lower() for a, _t in source_pairs}
    bridge_alias = _alias_for_table(bridge_table, used_aliases)

    def _edge_clause(left_alias: str, right_alias: str, edge: Tuple[str, str, str]) -> str:
        direction, fk_col, parent_id = edge
        if direction == "left_child":
            return f"{left_alias}.{fk_col} = {right_alias}.{parent_id}"
        return f"{right_alias}.{fk_col} = {left_alias}.{parent_id}"

    join_keyword = "LEFT JOIN" if _question_wants_include_zero(question, ctx) else "JOIN"
    rebuilt = (
        f"SELECT {parsed['select'].strip()} "
        f"FROM {base_table} AS {base_alias} "
        f"{join_keyword} {bridge_table} AS {bridge_alias} ON {_edge_clause(base_alias, bridge_alias, edge_base_bridge)} "
        f"{join_keyword} {metric_table} AS {metric_alias} ON {_edge_clause(bridge_alias, metric_alias, edge_bridge_metric)} "
        f"GROUP BY {parsed['groupby'].strip()}"
    )
    if (parsed.get("tail") or "").strip():
        rebuilt += f" {parsed['tail'].strip()}"
    if sql.strip().endswith(";"):
        rebuilt += ";"
    return rebuilt

def _rewrite_dual_fact_rollup_fanout(sql: str, question: str, ctx: str = "") -> str:
    """
    Rewrite a grouped dual-fact rollup query into a fanout-safe shape.

    Target pattern:
      - one base entity table in FROM
      - two different child fact tables joined to the base
      - one child contributes a COUNT(...)
      - another child contributes SUM(...) and optional CASE status on that SUM

    Output shape:
      base
      [LEFT] JOIN (count_fact aggregated by base key)
      LEFT/JOIN (metric_fact aggregated by base key)
    """
    if not sql or not question:
        return sql
    if not _question_wants_dual_fact_rollup(question):
        return sql
    exists_shape_fixed = _rewrite_dual_fact_rollup_exists_shape(sql, question, ctx)
    if exists_shape_fixed != sql:
        return exists_shape_fixed

    def _safe_sql_alias(name: Optional[str], fallback: str) -> str:
        raw = str(name or "").strip().strip("`'\"")
        if not raw:
            raw = fallback
        raw = re.sub(r"[^A-Za-z0-9_]+", "_", raw).strip("_")
        if not raw:
            raw = fallback
        if not re.match(r"[A-Za-z_]", raw):
            raw = f"a_{raw}"
        return raw

    def _outer_alias_sql(name: Optional[str], fallback: str) -> str:
        raw = str(name or "").strip().strip("`'\"")
        if not raw:
            raw = fallback
        return _smart_backtick(raw)

    def _sanitize_dual_fact_parse_input(sql_text: str) -> str:
        out = _fix_bad_backticks(sql_text or "")
        out = re.sub(r"`\s*\.\s*`", ".", out)
        out = re.sub(
            r"(?is)\b([A-Za-z_][A-Za-z0-9_]*)`\s*\.\s*`([A-Za-z_][A-Za-z0-9_]*)\b",
            r"\1.\2",
            out,
        )
        out = re.sub(r"(?is)\bAS(?=`?[A-Za-z_])", "AS ", out)
        out = re.sub(r"\s{2,}", " ", out).strip()
        return out

    sql_work = _sanitize_dual_fact_parse_input(sql)
    parsed = _parse_select_from_groupby(sql_work)
    if not parsed:
        return sql

    # Conservative: only rewrite straightforward grouped rollups.
    if (parsed.get("where") or "").strip():
        return sql
    if (parsed.get("having") or "").strip():
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if not from_core or "join" not in from_core.lower():
        return sql

    try:
        transaction_tables = {
            str(t).strip().lower()
            for t in (get_transaction_tables() or [])
            if str(t).strip()
        }
    except Exception:
        transaction_tables = set()

    reserved_alias_tokens = {
        "left", "right", "inner", "outer", "full", "cross", "join",
        "on", "where", "group", "order", "having", "limit",
    }

    alias_map_raw = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    alias_to_table: Dict[str, str] = {}
    for alias_raw, table_raw in alias_map_raw.items():
        alias_l = (alias_raw or "").strip().lower()
        table_l = (table_raw or "").strip().lower()
        if not alias_l or not table_l:
            continue
        alias_to_table.setdefault(alias_l, table_l)

    # Aliasless fallback: map table name -> table name from FROM/JOIN clauses.
    if not alias_to_table:
        for m_tbl in re.finditer(
            r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\b""",
            f"FROM {from_core}",
        ):
            raw_tbl = (m_tbl.group(1) or "").replace("`", "").strip()
            table_l = raw_tbl.split(".")[-1].lower()
            if table_l and table_l not in alias_to_table:
                alias_to_table[table_l] = table_l

    m_base = re.match(
        r"""(?is)^\s*(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)?""",
        from_core,
    )
    if not m_base:
        return sql

    base_table_expr = (m_base.group(1) or "").strip()
    base_table = base_table_expr.replace("`", "").split(".")[-1].strip()
    if not base_table:
        return sql
    base_alias_raw = (m_base.group(2) or "").strip()
    if base_alias_raw.lower() in reserved_alias_tokens:
        base_alias_raw = ""
    base_alias = (base_alias_raw or base_table).strip()
    base_alias_l = base_alias.lower()

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m:
            return (item or "").strip(), None
        return (m.group(1) or "").strip(), (m.group(2) or "").strip()

    def _parse_simple_col(expr: str) -> Optional[tuple]:
        m = re.match(
            r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            (expr or "").strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _extract_sum_inner(expr: str) -> Optional[tuple]:
        text = (expr or "").strip()
        patterns = [
            r"(?is)^SUM\s*\(\s*(.+?)\s*\)$",
            r"(?is)^COALESCE\s*\(\s*SUM\s*\(\s*(.+?)\s*\)\s*,\s*0(?:\.0+)?\s*\)$",
            r"(?is)^IFNULL\s*\(\s*SUM\s*\(\s*(.+?)\s*\)\s*,\s*0(?:\.0+)?\s*\)$",
        ]
        for idx, pattern in enumerate(patterns):
            m = re.match(pattern, text)
            if m:
                return (m.group(1) or "").strip(), bool(idx > 0)
        return None

    def _table_mentions(table_name: str) -> bool:
        for word in _entity_words_for_table(table_name):
            ww = (word or "").strip().lower()
            if not ww:
                continue
            pattern = re.escape(ww).replace(r"\ ", r"\s+")
            if re.search(rf"\b{pattern}\b", question, flags=re.I):
                return True
        return False

    def _count_request_mentions(table_name: str) -> bool:
        alts = []
        for word in _entity_words_for_table(table_name):
            ww = (word or "").strip().lower()
            if not ww:
                continue
            alts.append(re.escape(ww).replace(r"\ ", r"\s+"))
        if not alts:
            return False
        alt = "|".join(sorted(set(alts), key=len, reverse=True))
        return bool(
            re.search(
                rf"\b(?:total\s+number\s+of|number\s+of|count\s+of|count|how\s+many|jumlah)\s+(?:the\s+)?(?:{alt})\b",
                question,
                flags=re.I,
            )
        ) or bool(
            re.search(
                rf"\btotal[_\s-]+(?:{alt})\b",
                question,
                flags=re.I,
            )
        )

    join_kind_by_alias: Dict[str, str] = {}
    for m_join in re.finditer(
        r"""(?is)\b(?:(LEFT|RIGHT|FULL|INNER|CROSS)\s+)?JOIN\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?""",
        from_core,
    ):
        table_expr = (m_join.group(2) or "").replace("`", "").strip()
        table_name = table_expr.split(".")[-1].strip()
        alias_raw = (m_join.group(3) or "").strip()
        if alias_raw.lower() in reserved_alias_tokens:
            alias_raw = ""
        alias_name = (alias_raw or table_name).strip().lower()
        if not alias_name:
            continue
        join_kw = ((m_join.group(1) or "") + " JOIN").strip().upper()
        if join_kw == "CROSS JOIN":
            return sql
        join_kind_by_alias[alias_name] = "LEFT JOIN" if join_kw == "LEFT JOIN" else "JOIN"

    select_items = _split_top_level_commas(parsed["select"])
    if not select_items:
        return sql

    def _simple_projection_score(alias_name: str, col_name: str, out_alias: Optional[str]) -> int:
        alias_l = str(alias_name or "").strip().lower()
        col_l = str(col_name or "").strip().lower()
        table_l = alias_to_table.get(alias_l, alias_l)
        score = 0
        if table_l and table_l not in transaction_tables:
            score += 4
        if table_l and _table_mentions(table_l):
            score += 3
        try:
            id_col = str(get_id_column(table_l) or "").strip().lower()
        except Exception:
            id_col = ""
        try:
            name_col = str(get_name_column(table_l) or "").strip().lower()
        except Exception:
            name_col = ""
        if id_col and col_l == id_col:
            score += 4
        if name_col and col_l == name_col:
            score += 5
        alias_name_l = str(out_alias or "").strip("`'\"").lower()
        if alias_name_l.endswith("_id") or alias_name_l.endswith("_name"):
            score += 2
        return score

    projected_simple_by_alias: Dict[str, List[tuple[str, Optional[str]]]] = {}
    for raw_item in select_items:
        expr, out_alias = _split_expr_alias(raw_item)
        expr_l = expr.lower()
        if re.match(r"(?is)^count\s*\(", expr_l):
            continue
        if _extract_sum_inner(expr):
            continue
        if expr_l.startswith("case") and re.search(r"\bsum\s*\(", expr, flags=re.I):
            continue
        pcol = _parse_simple_col(expr)
        if not pcol or not pcol[0]:
            continue
        projected_simple_by_alias.setdefault(pcol[0].lower(), []).append((pcol[1], out_alias))

    current_base_score = 0
    for col_name, out_alias in projected_simple_by_alias.get(base_alias_l, []):
        current_base_score += _simple_projection_score(base_alias_l, col_name, out_alias)

    best_entity_alias = base_alias_l
    best_entity_score = current_base_score
    for alias_name, cols in projected_simple_by_alias.items():
        if alias_name == base_alias_l:
            continue
        table_l = alias_to_table.get(alias_name, alias_name)
        if not table_l or table_l in transaction_tables:
            continue
        alias_score = sum(_simple_projection_score(alias_name, col_name, out_alias) for col_name, out_alias in cols)
        if len(cols) >= 2:
            alias_score += 2
        if alias_score > best_entity_score:
            best_entity_alias = alias_name
            best_entity_score = alias_score

    if best_entity_alias != base_alias_l and best_entity_score >= max(6, current_base_score + 2):
        base_alias = best_entity_alias
        base_alias_l = best_entity_alias
        base_table = alias_to_table.get(best_entity_alias, base_table)
        base_table_expr = base_table

    base_select_items: List[str] = []
    count_alias_out: Optional[str] = None
    count_inner: Optional[str] = None
    count_distinct = False
    count_fact_alias: Optional[str] = None
    sum_alias_out: Optional[str] = None
    sum_inner: Optional[str] = None
    sum_fact_alias: Optional[str] = None
    sum_zero_fill = False
    status_alias_out: Optional[str] = None
    status_fact_alias: Optional[str] = None
    case_items: List[tuple] = []

    eq_pat = re.compile(
        r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
        flags=re.I,
    )

    def _map_simple_ref_to_base(qualifier: str, col_name: str) -> Optional[str]:
        q_l = str(qualifier or "").strip().lower()
        c_l = str(col_name or "").strip().lower()
        if not q_l or not c_l or q_l == base_alias_l:
            return None
        for m_eq in eq_pat.finditer(from_core):
            a1, c1, a2, c2 = m_eq.group(1).lower(), m_eq.group(2), m_eq.group(3).lower(), m_eq.group(4)
            if a1 == q_l and c1.lower() == c_l and a2 == base_alias_l:
                return c2
            if a2 == q_l and c2.lower() == c_l and a1 == base_alias_l:
                return c1
        return None

    count_pat = re.compile(r"(?is)^COUNT\s*\(\s*(DISTINCT\s+)?(.+?)\s*\)$")

    def _extract_boolean_sum_alias(expr: str) -> Optional[str]:
        text = (expr or "").strip()
        patterns = [
            r"""(?is)^SUM\s*\(\s*NOT\s+`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?\s+IS\s+NULL\s*\)$""",
            r"""(?is)^SUM\s*\(\s*`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?\s+IS\s+NOT\s+NULL\s*\)$""",
            r"""(?is)^SUM\s*\(\s*CASE\s+WHEN\s+`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?\s+IS\s+NOT\s+NULL\s+THEN\s+1\s+ELSE\s+0\s+END\s*\)$""",
            r"""(?is)^COUNT\s*\(\s*`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?\s*\)$""",
        ]
        for pattern in patterns:
            m = re.match(pattern, text)
            if m:
                alias_name = str(m.group("alias") or "").strip().lower()
                if alias_name:
                    return alias_name
        return None

    for raw_item in select_items:
        expr, out_alias = _split_expr_alias(raw_item)
        expr_l = expr.lower()

        m_count = count_pat.match(expr)
        if m_count:
            inner_expr = (m_count.group(2) or "").strip()
            ref = None if inner_expr == "*" else _parse_simple_col(inner_expr)
            count_inner = inner_expr
            count_distinct = bool((m_count.group(1) or "").strip())
            if ref and ref[0]:
                count_fact_alias = ref[0].lower()
            count_alias_out = (out_alias or "").strip("`'\"") or None
            continue

        sum_info = _extract_sum_inner(expr)
        if sum_info:
            inner_expr, zero_fill = sum_info
            ref = _parse_simple_col(inner_expr)
            if not ref or not ref[0]:
                bool_sum_alias = _extract_boolean_sum_alias(expr)
                if not bool_sum_alias:
                    return sql
                status_fact_alias = bool_sum_alias
                status_alias_out = (out_alias or "").strip("`'\"") or status_alias_out
                continue
            sum_inner = inner_expr
            sum_fact_alias = ref[0].lower()
            sum_alias_out = (out_alias or "").strip("`'\"") or None
            sum_zero_fill = sum_zero_fill or zero_fill
            continue

        if expr_l.startswith("case") and re.search(
            r"\bSUM\s*\(\s*(?:DISTINCT\s+)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.",
            expr,
            flags=re.I,
        ):
            case_items.append((expr, out_alias))
            continue

        pcol = _parse_simple_col(expr)
        if pcol:
            qualifier, col_name = pcol
            if qualifier and qualifier.lower() == base_alias_l:
                base_select_items.append(raw_item.strip())
                continue
            if qualifier:
                mapped_base_col = _map_simple_ref_to_base(qualifier, col_name)
                if mapped_base_col:
                    rewritten = f"{base_alias}.{mapped_base_col}"
                    if out_alias:
                        rewritten += f" AS {out_alias.strip()}"
                    base_select_items.append(rewritten)
                    continue
            if not qualifier:
                base_select_items.append(raw_item.strip())
                continue

        return sql

    if not sum_inner and status_fact_alias:
        inferred_sum_table = alias_to_table.get(status_fact_alias, status_fact_alias)
        inferred_metric_col = str(
            infer_best_aggregate_column(inferred_sum_table, question) or ""
        ).strip("`")
        if inferred_metric_col:
            sum_fact_alias = status_fact_alias
            sum_inner = f"{status_fact_alias}.{inferred_metric_col}"

    if not base_select_items or not count_inner or not sum_inner or not sum_fact_alias:
        return sql

    pairs_by_alias: Dict[str, List[tuple]] = {}
    for m_eq in eq_pat.finditer(from_core):
        a1, c1, a2, c2 = m_eq.group(1).lower(), m_eq.group(2), m_eq.group(3).lower(), m_eq.group(4)
        if {a1, a2} != {base_alias_l, a1 if a1 == a2 else a2}:
            pass
        if a1 == base_alias_l and a2 != base_alias_l:
            pairs_by_alias.setdefault(a2, []).append((c1, c2))
        elif a2 == base_alias_l and a1 != base_alias_l:
            pairs_by_alias.setdefault(a1, []).append((c2, c1))

    direct_child_aliases = {
        alias for alias in pairs_by_alias
        if alias in alias_to_table and alias != base_alias_l
    }
    if sum_fact_alias not in direct_child_aliases:
        return sql

    if not count_fact_alias:
        count_candidates = [alias for alias in sorted(direct_child_aliases) if alias != sum_fact_alias]
        if not count_candidates:
            return sql

        scored_candidates: List[tuple] = []
        for alias in count_candidates:
            table_name = alias_to_table.get(alias, alias)
            score = 0
            if table_name in transaction_tables:
                score += 3
            if _count_request_mentions(table_name):
                score += 3
            if _table_mentions(table_name):
                score += 1
            scored_candidates.append((score, alias))
        scored_candidates.sort(key=lambda item: (-item[0], item[1]))
        count_fact_alias = scored_candidates[0][1]
        if len(scored_candidates) > 1 and scored_candidates[0][0] == scored_candidates[1][0] == 0:
            return sql
    elif count_fact_alias not in direct_child_aliases:
        return sql

    if count_fact_alias == sum_fact_alias:
        return sql

    count_table = alias_to_table.get(count_fact_alias, count_fact_alias)
    sum_table = alias_to_table.get(sum_fact_alias, sum_fact_alias)
    if not count_table or not sum_table:
        return sql

    status_requested = bool(status_alias_out or _status_request_for_table_question(question, sum_table))

    if not count_alias_out:
        count_alias_out = f"total_{count_table}"
    if not sum_alias_out:
        sum_alias_out = f"total_{sum_table}"

    count_metric_alias = _safe_sql_alias(count_alias_out, f"total_{count_table}")
    sum_metric_alias = _safe_sql_alias(sum_alias_out, f"total_{sum_table}")
    count_outer_alias = _outer_alias_sql(count_alias_out, count_metric_alias)
    sum_outer_alias = _outer_alias_sql(sum_alias_out, sum_metric_alias)

    # Deduplicate base projection conservatively.
    dedup_base: List[str] = []
    seen_base_expr: Set[str] = set()
    for item in base_select_items:
        base_expr, item_alias = _split_expr_alias(item)
        expr_norm = re.sub(r"\s+", "", (base_expr or "").lower())
        alias_norm = (item_alias or "").strip("`'\"").lower()
        key = f"{expr_norm}__as__{alias_norm}" if alias_norm else expr_norm
        if not key or key in seen_base_expr:
            continue
        seen_base_expr.add(key)
        dedup_base.append(item)
    base_select_items = dedup_base

    normalized_group_items: List[str] = []
    for group_item in _split_top_level_commas(parsed.get("groupby", "")):
        parsed_group = _parse_simple_col(group_item)
        if parsed_group and parsed_group[0]:
            mapped_group_col = _map_simple_ref_to_base(parsed_group[0], parsed_group[1])
            if mapped_group_col:
                normalized_group_items.append(f"{base_alias}.{mapped_group_col}")
                continue
        normalized_group_items.append(group_item)

    for group_item in normalized_group_items:
        g0 = (group_item or "").strip().lower()
        if re.search(rf"\b{re.escape(count_fact_alias)}\s*\.", g0):
            return sql
        if re.search(rf"\b{re.escape(sum_fact_alias)}\s*\.", g0):
            return sql

    entity_words = _entity_words_for_table(base_table)
    if not entity_words:
        entity_words = [base_table, (base_table[:-1] if base_table.endswith("s") else base_table)]
    base_entity_terms = {
        tok
        for word in entity_words
        for tok in re.findall(
            r"[a-z0-9]+",
            re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(word or "")).replace("_", " ").lower(),
        )
        if len(tok) >= 3
    }
    base_id_for_score = str(get_id_column(base_table) or "").strip("`").lower()

    def _pick_pair(pairs: List[tuple]) -> Optional[tuple]:
        if not pairs:
            return None

        def _score(pair: tuple) -> int:
            base_col, fact_col = (pair[0] or "").lower(), (pair[1] or "").lower()
            score = 0
            for name in (base_col, fact_col):
                if name.endswith(("id", "number", "code", "key")):
                    score += 4
                name_terms = {
                    tok
                    for tok in re.findall(
                        r"[a-z0-9]+",
                        re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(name or "")).replace("_", " ").lower(),
                    )
                    if tok
                }
                name_compact = re.sub(r"[^a-z0-9]+", "", name)
                if base_entity_terms and (
                    name_terms.intersection(base_entity_terms)
                    or any(term in name_compact for term in base_entity_terms)
                ):
                    score += 3
                if base_id_for_score and name == base_id_for_score:
                    score += 3
            if base_col == fact_col:
                score += 2
            return score

        return sorted(pairs, key=_score, reverse=True)[0]

    count_pair = _pick_pair(pairs_by_alias.get(count_fact_alias, []))
    sum_pair = _pick_pair(pairs_by_alias.get(sum_fact_alias, []))
    if not count_pair or not sum_pair:
        return sql

    base_count_key, count_key = count_pair
    base_sum_key, sum_key = sum_pair

    q_low = (question or "").lower()
    q_low_output = re.split(r"\b(?:sort(?:ed)?\s+by|order\s+by)\b", q_low, maxsplit=1, flags=re.I)[0]
    def _mentions_entity_attr(attr: str) -> bool:
        for word in entity_words:
            ww = (word or "").strip().lower()
            if not ww:
                continue
            pattern = re.escape(ww).replace(r"\ ", r"\s+")
            if re.search(rf"\b{pattern}\s+{re.escape(attr)}\b", q_low_output):
                return True
        return False

    entity_slug = re.sub(r"[^a-z0-9_]+", "_", (get_singular_form(base_table) or base_table).lower()).strip("_")
    wants_entity_number = _mentions_entity_attr("number") or bool(re.search(rf"\b{re.escape(base_table.lower())}number\b", q_low_output))
    wants_entity_code = _mentions_entity_attr("code") or bool(re.search(rf"\b{re.escape(base_table.lower())}code\b", q_low_output))
    wants_entity_id = _mentions_entity_attr("id")
    wants_entity_name = _mentions_entity_attr("name")
    id_col = get_id_column(base_table) or base_count_key
    name_col = get_name_column(base_table)

    def _base_has_col(col_name: str) -> bool:
        for item in base_select_items:
            expr0, _alias0 = _split_expr_alias(item)
            parsed_col = _parse_simple_col(expr0)
            if not parsed_col:
                continue
            _qualifier, col0 = parsed_col
            if col0 and col0.lower() == col_name.lower():
                return True
        return False

    def _base_has_alias(alias_name: str) -> bool:
        for item in base_select_items:
            _expr0, alias0 = _split_expr_alias(item)
            if alias0 and alias0.strip("`'\"").lower() == alias_name.lower():
                return True
        return False

    if id_col and (wants_entity_number or wants_entity_code or wants_entity_id):
        if not _base_has_col(id_col):
            base_select_items.insert(0, f"{base_alias}.{id_col}")
        entity_id_alias = f"{entity_slug}_id" if entity_slug else "entity_id"
        if wants_entity_id and not _base_has_alias(entity_id_alias):
            base_select_items.append(f"{base_alias}.{id_col} AS {entity_id_alias}")

    if id_col:
        id_item_idxs: List[int] = []
        removed_aliases: List[str] = []
        for idx, item in enumerate(base_select_items):
            expr0, _alias0 = _split_expr_alias(item)
            parsed_col = _parse_simple_col(expr0)
            if not parsed_col:
                continue
            qualifier0, col0 = parsed_col
            if col0 and col0.lower() == id_col.lower() and (not qualifier0 or qualifier0.lower() == base_alias_l):
                id_item_idxs.append(idx)

        if len(id_item_idxs) > 1:
            wants_dual_identifier_slots = sum(int(flag) for flag in [wants_entity_id, wants_entity_number, wants_entity_code]) >= 2
            if not wants_dual_identifier_slots:
                def _alias_pref_score(idx: int) -> int:
                    _expr_i, alias_i = _split_expr_alias(base_select_items[idx])
                    alias_name = (alias_i or "").strip("`'\"").lower()
                    score = 0
                    if wants_entity_number and not wants_entity_id and not wants_entity_code:
                        if "number" in alias_name:
                            score += 6
                        if "id" in alias_name or "code" in alias_name:
                            score -= 2
                    elif wants_entity_code and not wants_entity_id and not wants_entity_number:
                        if "code" in alias_name:
                            score += 6
                        if "id" in alias_name or "number" in alias_name:
                            score -= 2
                    elif wants_entity_id and not wants_entity_number and not wants_entity_code:
                        if "id" in alias_name:
                            score += 6
                        if "number" in alias_name or "code" in alias_name:
                            score -= 2
                    if alias_name:
                        score += 1
                    score -= idx
                    return score

                keep_idx = max(id_item_idxs, key=_alias_pref_score)
                for drop_idx in reversed(id_item_idxs):
                    if drop_idx == keep_idx:
                        continue
                    _drop_expr, drop_alias = _split_expr_alias(base_select_items[drop_idx])
                    if drop_alias:
                        removed_aliases.append(drop_alias.strip("`'\""))
                    base_select_items.pop(drop_idx)

                if wants_entity_name and name_col and not _base_has_col(name_col):
                    name_alias: Optional[str] = None
                    for alias_name in removed_aliases:
                        if "name" in alias_name.lower():
                            name_alias = alias_name
                            break
                    name_item = f"{base_alias}.{name_col}"
                    if name_alias:
                        name_item += f" AS {name_alias}"
                    insert_at = min(keep_idx + 1, len(base_select_items))
                    base_select_items.insert(insert_at, name_item)

    if wants_entity_name and name_col and not _base_has_col(name_col):
        base_select_items.append(f"{base_alias}.{name_col}")

    used_aliases = {base_alias_l, count_fact_alias, sum_fact_alias, *alias_to_table.keys()}

    def _pick_alias(base_name: str) -> str:
        base_clean = re.sub(r"[^A-Za-z0-9_]", "", base_name) or "t"
        if not re.match(r"[A-Za-z_]", base_clean[0]):
            base_clean = f"t_{base_clean}"
        candidate = base_clean
        idx = 2
        while candidate.lower() in used_aliases:
            candidate = f"{base_clean}_{idx}"
            idx += 1
        used_aliases.add(candidate.lower())
        return candidate

    count_agg_alias = _pick_alias(f"{count_table}_agg")
    sum_agg_alias = _pick_alias(f"{sum_table}_agg")

    count_inner_clean = count_inner
    if count_inner_clean != "*":
        count_inner_clean = re.sub(
            rf"(?is)\b`?{re.escape(count_fact_alias)}`?\s*\.\s*",
            "",
            count_inner_clean,
        )
    count_expr = f"COUNT({'DISTINCT ' if count_distinct else ''}{count_inner_clean})"

    sum_inner_clean = re.sub(
        rf"(?is)\b`?{re.escape(sum_fact_alias)}`?\s*\.\s*",
        "",
        sum_inner,
    )

    include_zero_intent = _question_wants_include_zero(question, ctx)
    explicit_count_existence = bool(
        _question_wants_existence(question)
        and _table_mentions(count_table)
    )
    count_join_keyword = "LEFT JOIN" if (include_zero_intent or join_kind_by_alias.get(count_fact_alias) == "LEFT JOIN") else "JOIN"
    if explicit_count_existence:
        count_join_keyword = "JOIN"
    metric_join_keyword = "LEFT JOIN"
    if not (
        include_zero_intent
        or case_items
        or status_requested
        or sum_zero_fill
        or join_kind_by_alias.get(sum_fact_alias) == "LEFT JOIN"
    ):
        metric_join_keyword = "JOIN"

    projected_items: List[str] = []
    projected_items.extend(base_select_items)
    count_projection = f"{count_agg_alias}.{count_metric_alias} AS {count_outer_alias}"
    if count_join_keyword == "LEFT JOIN":
        count_projection = f"COALESCE({count_agg_alias}.{count_metric_alias}, 0) AS {count_outer_alias}"
    projected_items.append(count_projection)
    projected_items.append(f"COALESCE({sum_agg_alias}.{sum_metric_alias}, 0) AS {sum_outer_alias}")

    case_sum_pat = re.compile(
        rf"(?is)SUM\s*\(\s*(?:DISTINCT\s+)?`?{re.escape(sum_fact_alias)}`?\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?\s*\)"
    )
    for case_expr, case_alias in case_items:
        rewritten_case = case_sum_pat.sub(
            f"COALESCE({sum_agg_alias}.{sum_metric_alias}, 0)",
            case_expr,
        )
        if case_alias:
            projected_items.append(f"{rewritten_case} AS {case_alias}")
        else:
            projected_items.append(rewritten_case)

    if status_requested and status_alias_out and not case_items:
        status_literals = re.findall(r"""['"]([^'"]+)['"]""", question or "")
        status_positive = str(status_literals[0]).strip() if len(status_literals) >= 1 else "Yes"
        status_negative = str(status_literals[1]).strip() if len(status_literals) >= 2 else "No"
        projected_items.append(
            "CASE "
            f"WHEN COALESCE({sum_agg_alias}.{sum_metric_alias}, 0) > 0 THEN '{status_positive}' "
            f"ELSE '{status_negative}' END AS {_outer_alias_sql(status_alias_out, 'status_flag')}"
        )

    tail_clause = (parsed.get("tail") or "").strip()
    if tail_clause:
        count_inner_col = count_inner_clean.split(".")[-1] if count_inner_clean != "*" else "*"
        count_table_name = alias_to_table.get(count_fact_alias or "", count_fact_alias or "")
        sum_table_name = alias_to_table.get(sum_fact_alias or "", sum_fact_alias or "")

        def _literal_sql_pattern(text: str) -> str:
            return re.escape(text).replace(r"\ ", r"\s*").replace(r"\`", r"`?")

        count_patterns = []
        if count_fact_alias and count_inner_col != "*":
            count_patterns.append(
                rf"COUNT\s*\(\s*(?:DISTINCT\s+)?`?{re.escape(count_fact_alias)}`?\s*\.\s*`?{re.escape(count_inner_col)}`?\s*\)"
            )
        if count_table_name and count_inner_col != "*":
            count_patterns.append(
                rf"COUNT\s*\(\s*(?:DISTINCT\s+)?`?{re.escape(count_table_name)}`?\s*\.\s*`?{re.escape(count_inner_col)}`?\s*\)"
            )
        if count_alias_out:
            count_patterns.append(rf"\b{_literal_sql_pattern(count_alias_out)}\b")
        sum_inner_col = sum_inner_clean.split(".")[-1]
        sum_patterns = []
        if sum_fact_alias:
            sum_patterns.append(
                rf"SUM\s*\(\s*`?{re.escape(sum_fact_alias)}`?\s*\.\s*`?{re.escape(sum_inner_col)}`?\s*\)"
            )
        if sum_table_name:
            sum_patterns.append(
                rf"SUM\s*\(\s*`?{re.escape(sum_table_name)}`?\s*\.\s*`?{re.escape(sum_inner_col)}`?\s*\)"
            )
        if sum_alias_out:
            sum_patterns.append(rf"\b{_literal_sql_pattern(sum_alias_out)}\b")
        normalized_tail = tail_clause
        for pattern in count_patterns:
            normalized_tail = re.sub(pattern, count_metric_alias, normalized_tail, flags=re.I)
        for pattern in sum_patterns:
            normalized_tail = re.sub(pattern, sum_metric_alias, normalized_tail, flags=re.I)

        def _replace_nonbase_tail_ref(m: re.Match) -> str:
            qualifier = (m.group(1) or "").strip()
            col_name = (m.group(2) or "").strip()
            mapped = _map_simple_ref_to_base(qualifier, col_name)
            if mapped:
                return f"{base_alias}.{mapped}"
            return m.group(0)

        normalized_tail = re.sub(
            r"(?is)\b([A-Za-z_][A-Za-z0-9_]*)\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?",
            _replace_nonbase_tail_ref,
            normalized_tail,
        )
        tail_clause = normalized_tail
    entity_id_alias = f"{entity_slug}_id" if entity_slug else "entity_id"
    if tail_clause and id_col and re.search(rf"\b{re.escape(entity_id_alias)}\b", tail_clause, flags=re.I):
        has_entity_id_alias = any(
            (_split_expr_alias(item)[1] or "").strip("`'\"").lower() == entity_id_alias.lower()
            for item in projected_items
        )
        if not has_entity_id_alias:
            tail_clause = re.sub(
                rf"\b{re.escape(entity_id_alias)}\b",
                f"{base_alias}.{id_col}",
                tail_clause,
                flags=re.I,
            )

    tail_block = f"\n{tail_clause}" if tail_clause else ""
    select_block = ",\n  ".join(projected_items)

    fixed = (
        "SELECT\n"
        f"  {select_block}\n"
        f"FROM {base_table_expr} {base_alias}\n"
        f"{count_join_keyword} (\n"
        f"  SELECT {count_key}, {count_expr} AS {count_metric_alias}\n"
        f"  FROM {count_table}\n"
        f"  GROUP BY {count_key}\n"
        f") AS {count_agg_alias}\n"
        f"  ON {count_agg_alias}.{count_key} = {base_alias}.{base_count_key}\n"
        f"{metric_join_keyword} (\n"
        f"  SELECT {sum_key}, SUM({sum_inner_clean}) AS {sum_metric_alias}\n"
        f"  FROM {sum_table}\n"
        f"  GROUP BY {sum_key}\n"
        f") AS {sum_agg_alias}\n"
        f"  ON {sum_agg_alias}.{sum_key} = {base_alias}.{base_sum_key}"
        f"{tail_block};"
    )
    return fixed


def _question_wants_latest_year_scope_with_aggregate(question: str) -> bool:
    """
    Dynamic intent detector for:
      - latest/most-recent year
      - plus aggregate amount/total intent

    Intentionally avoids exact phrase dependency like "in that year" so
    paraphrases still trigger the same rewrite path.
    """
    q = (question or "").lower().strip()
    if not q:
        return False

    has_latest = bool(
        re.search(r"\b(?:latest|most\s+recent|newest|terbaru|terakhir)\b", q)
    )
    has_year = bool(re.search(r"\b(?:year|tahun)\b", q))
    has_aggregate_amount = bool(
        _semantic_question_tokens(q).intersection(_latest_year_metric_question_terms())
    )

    return has_latest and has_year and has_aggregate_amount


def _rewrite_latest_year_window_aggregate_misuse(sql: str, question: str, ctx: str = "") -> str:
    """
    Salvage malformed window-style drafts for:
      entity -> latest year -> aggregate in that same year

    This stays intentionally narrow:
    - flat SELECT/FROM query only
    - requires both MAX(YEAR/date) OVER(...) and SUM(metric) OVER(...)
    - requires a visible entity table joined to a metric table, plus an
      FK-consistent temporal table for the year dimension
    """
    if not sql or not question:
        return sql
    if not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    s = str(sql or "").strip().rstrip(";").strip()
    low = s.lower()
    if not s or "over" not in low or "sum(" not in low or "max(" not in low or "year" not in low:
        return sql
    if re.search(r"\b(?:from|join)\s*\(", s, flags=re.I):
        return sql

    parsed = _parse_select_from_groupby(s)
    if not parsed:
        m_flat = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<rest>.+?)\s*;?\s*$", s)
        if not m_flat:
            return sql
        select_part_fallback = str(m_flat.group("select") or "").strip()
        rest_fallback = str(m_flat.group("rest") or "").strip()
        if not select_part_fallback or not rest_fallback:
            return sql

        clause_positions: List[Tuple[int, str]] = []
        for kw in ("WHERE", "GROUP BY", "HAVING", "ORDER BY", "LIMIT"):
            pos = _find_top_level_clause(rest_fallback, kw.lower())
            if pos >= 0:
                clause_positions.append((pos, kw))
        clause_positions.sort(key=lambda item: item[0])

        if clause_positions:
            first_pos = clause_positions[0][0]
            from_core_fallback = rest_fallback[:first_pos].strip()
            trailing_fallback = rest_fallback[first_pos:].strip()
        else:
            from_core_fallback = rest_fallback
            trailing_fallback = ""

        where_fallback = ""
        tail_fallback = trailing_fallback
        if trailing_fallback:
            where_pos = _find_top_level_clause(trailing_fallback, "where")
            if where_pos >= 0:
                next_pos = len(trailing_fallback)
                for kw in ("GROUP BY", "HAVING", "ORDER BY", "LIMIT"):
                    pos = _find_top_level_clause(
                        trailing_fallback,
                        kw.lower(),
                        where_pos + len("where"),
                    )
                    if pos >= 0:
                        next_pos = min(next_pos, pos)
                where_fallback = trailing_fallback[where_pos:next_pos].strip()
                tail_fallback = trailing_fallback[next_pos:].strip()

        parsed = {
            "select": select_part_fallback,
            "from_core": from_core_fallback,
            "where": where_fallback,
            "groupby": "",
            "having": "",
            "tail": tail_fallback,
        }

    from_core = (parsed.get("from_core") or "").strip()
    select_part = (parsed.get("select") or "").strip()
    if not from_core or not select_part:
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}") or {}
    if not alias_to_table:
        return sql

    try:
        transaction_tables = {
            str(t).strip().lower()
            for t in (get_transaction_tables() or [])
            if str(t).strip()
        }
    except Exception:
        transaction_tables = set()

    select_items = _split_top_level_commas(select_part)
    if not select_items:
        return sql

    def _split_expr_alias(item: str) -> Tuple[str, str]:
        m = re.match(
            r"""(?is)^\s*(?P<expr>.*?)\s+AS\s+(?P<alias>`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            str(item or "").strip(),
        )
        if not m:
            return str(item or "").strip(), ""
        return (m.group("expr") or "").strip(), (m.group("alias") or "").strip()

    def _parse_simple_col(expr: str) -> Optional[Tuple[str, str]]:
        m = re.match(
            r"""(?is)^\s*`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            str(expr or "").strip(),
        )
        if not m:
            return None
        return str(m.group("alias") or "").strip(), str(m.group("col") or "").strip()

    def _extract_window_year_ref(expr: str) -> Optional[Tuple[str, str]]:
        patterns = [
            r"""(?is)\bMAX\s*\(\s*YEAR\s*\(\s*`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)\s*OVER\s*\(""",
            r"""(?is)\bMAX\s*\(\s*`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*YEAR\s*\(\s*`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)\s*OVER\s*\(""",
        ]
        for pattern in patterns:
            m = re.search(pattern, expr or "")
            if m:
                alias_name = str(m.group("alias") or "").strip()
                col_name = str(m.group("col") or "").strip()
                if alias_name and col_name:
                    return alias_name, col_name
        return None

    def _extract_window_sum_ref(expr: str) -> Optional[Tuple[str, str]]:
        m = re.search(
            r"""(?is)\bSUM\s*\(\s*`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*OVER\s*\(""",
            expr or "",
        )
        if not m:
            return None
        alias_name = str(m.group("alias") or "").strip()
        col_name = str(m.group("col") or "").strip()
        if not alias_name or not col_name:
            return None
        return alias_name, col_name

    simple_items: List[Tuple[str, str, str]] = []
    year_alias_out = "latest_year"
    sum_alias_out = "total_in_latest_year"
    date_alias = ""
    date_col = ""
    metric_alias = ""
    metric_col = ""
    for raw_item in select_items:
        expr, out_alias = _split_expr_alias(raw_item)
        simple_ref = _parse_simple_col(expr)
        if simple_ref:
            simple_items.append((raw_item.strip(), simple_ref[0], simple_ref[1]))
            continue
        sum_ref = _extract_window_sum_ref(expr)
        if sum_ref:
            metric_alias, metric_col = sum_ref
            sum_alias_out = (out_alias or sum_alias_out).strip("`'\"")
            continue
        year_ref = _extract_window_year_ref(expr)
        if year_ref:
            date_alias, date_col = year_ref
            year_alias_out = (out_alias or year_alias_out).strip("`'\"")
            continue

    if not simple_items or not date_alias or not date_col or not metric_alias or not metric_col:
        return sql

    metric_table = str(alias_to_table.get(metric_alias.lower()) or "").strip().lower()
    date_table = str(alias_to_table.get(date_alias.lower()) or "").strip().lower()
    if not metric_table or not date_table:
        return sql

    candidate_entity_aliases: List[str] = []
    for _raw_item, alias_name, _col_name in simple_items:
        alias_l = alias_name.lower()
        table_l = str(alias_to_table.get(alias_l) or "").strip().lower()
        if not table_l:
            continue
        if alias_l == metric_alias.lower():
            continue
        if table_l == date_table:
            continue
        if table_l in transaction_tables:
            continue
        if alias_l not in candidate_entity_aliases:
            candidate_entity_aliases.append(alias_l)
    if not candidate_entity_aliases:
        return sql
    entity_alias = candidate_entity_aliases[0]
    entity_table = str(alias_to_table.get(entity_alias) or "").strip().lower()
    if not entity_table or entity_alias == metric_alias.lower():
        return sql

    eq_pairs: List[Tuple[str, str, str, str]] = []
    for m_eq in re.finditer(
        r"""(?is)`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
        from_core,
    ):
        eq_pairs.append(
            (
                str(m_eq.group(1) or "").strip().lower(),
                str(m_eq.group(2) or "").strip(),
                str(m_eq.group(3) or "").strip().lower(),
                str(m_eq.group(4) or "").strip(),
            )
        )

    def _best_entity_metric_pair() -> Optional[Tuple[str, str]]:
        candidates: List[Tuple[int, str, str]] = []
        entity_id_col = str(get_id_column(entity_table) or "").strip().lower()
        metric_id_col = str(get_id_column(metric_table) or "").strip().lower()
        for a1, c1, a2, c2 in eq_pairs:
            if a1 == entity_alias and a2 == metric_alias.lower():
                score = 0
                if entity_id_col and c1.lower() == entity_id_col:
                    score += 4
                if metric_id_col and c2.lower() == metric_id_col:
                    score += 2
                if c1.lower().endswith(("id", "number", "code", "key")):
                    score += 2
                if c2.lower().endswith(("id", "number", "code", "key")):
                    score += 1
                candidates.append((score, c1, c2))
            elif a2 == entity_alias and a1 == metric_alias.lower():
                score = 0
                if entity_id_col and c2.lower() == entity_id_col:
                    score += 4
                if metric_id_col and c1.lower() == metric_id_col:
                    score += 2
                if c2.lower().endswith(("id", "number", "code", "key")):
                    score += 2
                if c1.lower().endswith(("id", "number", "code", "key")):
                    score += 1
                candidates.append((score, c2, c1))
        if not candidates:
            return None
        candidates.sort(key=lambda item: (-item[0], item[1], item[2]))
        return candidates[0][1], candidates[0][2]

    entity_metric_pair = _best_entity_metric_pair()
    if not entity_metric_pair:
        return sql
    entity_key_col, metric_entity_fk_col = entity_metric_pair

    metric_date_pair: Optional[Tuple[str, str]] = None
    if metric_alias.lower() == date_alias.lower():
        metric_date_pair = None
    else:
        for a1, c1, a2, c2 in eq_pairs:
            if a1 == metric_alias.lower() and a2 == date_alias.lower():
                metric_date_pair = (c1, c2)
                break
            if a2 == metric_alias.lower() and a1 == date_alias.lower():
                metric_date_pair = (c2, c1)
                break
        if not metric_date_pair:
            return sql

    where_body = re.sub(r"(?is)^\s*WHERE\s+", "", str(parsed.get("where") or "").strip()).strip()
    remaining_conds: List[str] = []
    if where_body and not _has_top_level_or(where_body):
        tautology_pat = re.compile(
            rf"""(?is)^\s*`?{re.escape(metric_alias)}`?\s*\.\s*`?{re.escape(metric_entity_fk_col)}`?\s+IN\s*\(\s*
                SELECT\s+`?{re.escape(metric_entity_fk_col)}`?\s+FROM\s+`?{re.escape(metric_table)}`?
                \s+GROUP\s+BY\s+`?{re.escape(metric_entity_fk_col)}`?\s+HAVING\s+COUNT\s*\(\s*\*\s*\)\s*>\s*0
                \s*\)\s*$""",
            re.X,
        )
        for cond in _split_top_level_and(where_body):
            cond_s = str(cond or "").strip()
            if not cond_s:
                continue
            if tautology_pat.match(cond_s):
                continue
            remaining_conds.append(cond_s)

    used_aliases = set(alias_to_table.keys())

    def _pick_alias(base: str) -> str:
        seed = re.sub(r"[^A-Za-z0-9_]+", "_", str(base or "")).strip("_") or "t"
        if not re.match(r"[A-Za-z_]", seed[0]):
            seed = f"t_{seed}"
        cand = seed
        idx = 2
        while cand.lower() in used_aliases:
            cand = f"{seed}_{idx}"
            idx += 1
        used_aliases.add(cand.lower())
        return cand

    ly_alias = _pick_alias("latest_years")
    metric_ly_alias = _pick_alias(f"{metric_table}_ly")
    date_ly_alias = _pick_alias(f"{date_table}_ly")
    group_items = [item for item, _alias, _col in simple_items]
    group_items.append(f"{ly_alias}.latest_year")

    inner_join_sql = ""
    outer_date_join_sql = ""
    date_ref_outer = f"{date_alias}.{date_col}"
    date_ref_inner = f"{metric_ly_alias}.{date_col}"
    if metric_date_pair is not None:
        metric_date_fk_col, date_pk_col = metric_date_pair
        inner_join_sql = (
            f"\n    JOIN {date_table} AS {date_ly_alias}\n"
            f"      ON {date_ly_alias}.{date_pk_col} = {metric_ly_alias}.{metric_date_fk_col}"
        )
        outer_date_join_sql = (
            f"\nJOIN {date_table} AS {date_alias}\n"
            f"  ON {date_alias}.{date_pk_col} = {metric_alias}.{metric_date_fk_col}"
        )
        date_ref_outer = f"{date_alias}.{date_col}"
        date_ref_inner = f"{date_ly_alias}.{date_col}"

    where_clauses = [f"YEAR({date_ref_outer}) = {ly_alias}.latest_year"]
    where_clauses.extend(remaining_conds)
    where_sql = "\nWHERE " + "\n  AND ".join(where_clauses) if where_clauses else ""

    limit_tail = ""
    tail_text = str(parsed.get("tail") or "").strip()
    if tail_text:
        m_limit = re.search(r"(?is)\bLIMIT\b.+$", tail_text)
        if m_limit:
            limit_tail = "\n" + m_limit.group(0).strip()

    fixed = (
        "SELECT\n  "
        + ",\n  ".join(group_items[:-1] + [f"{ly_alias}.latest_year AS {year_alias_out}", f"SUM({metric_alias}.{metric_col}) AS {sum_alias_out}"])
        + f"\nFROM {entity_table} AS {entity_alias}\n"
        + "JOIN (\n"
        + f"  SELECT {metric_ly_alias}.{metric_entity_fk_col} AS {metric_entity_fk_col},\n"
        + f"    MAX(YEAR({date_ref_inner})) AS latest_year\n"
        + f"  FROM {metric_table} AS {metric_ly_alias}"
        + inner_join_sql
        + f"\n  GROUP BY {metric_ly_alias}.{metric_entity_fk_col}\n"
        + f") AS {ly_alias}\n"
        + f"  ON {ly_alias}.{metric_entity_fk_col} = {entity_alias}.{entity_key_col}\n"
        + f"JOIN {metric_table} AS {metric_alias}\n"
        + f"  ON {metric_alias}.{metric_entity_fk_col} = {entity_alias}.{entity_key_col}"
        + outer_date_join_sql
        + where_sql
        + "\nGROUP BY\n  "
        + ",\n  ".join(group_items)
        + limit_tail
        + ";"
    )
    return fixed


def _rewrite_latest_year_same_year_aggregate(sql: str, question: str, ctx: str = "") -> str:
    """
    Fix aggregate anti-pattern for questions like:
      - "latest/most recent payment year"
      - "sum amount in that same year"

    Wrong pattern:
      SELECT key_cols, MAX(paymentDate), SUM(amount)
      FROM entity JOIN metric_table ...
      GROUP BY key_cols

    Also handles the paraphrased shape:
      SELECT key_cols, YEAR(orderDate) AS latest_year, SUM(metric)
      FROM ...
      GROUP BY key_cols, YEAR(orderDate)

    This sums across all years. Correct strategy:
      1) derive latest_year per entity from the metric table
      2) join/filter metric rows to that latest_year
      3) aggregate MAX(paymentDate) and SUM(amount) on filtered rows
    """
    if not sql:
        return sql

    # Keep trigger conservative but phrasing-agnostic.
    if not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    window_rescued = _rewrite_latest_year_window_aggregate_misuse(sql, question, ctx)
    if window_rescued != sql:
        return window_rescued

    low_sql = sql.lower()

    # Already handled pattern (alias-agnostic): keep as-is.
    # Accept any derived-table alias, not only a specific one.
    already_has_latest_year_pattern = (
        bool(re.search(r"\bmax\s*\(\s*year\s*\(", low_sql))
        and "latest_year" in low_sql
        and bool(re.search(r"=\s*[a-z_][a-z0-9_]*\.latest_year\b", low_sql))
    )
    if already_has_latest_year_pattern:
        return sql

    def _strip_tautological_same_table_latest_year_in_filter(sql_text: str) -> str:
        """
        Remove a malformed latest-year filter like:

          outer_id IN (
            SELECT id
            FROM (
              SELECT id, MAX(date_col) AS max_date
              FROM same_table
              GROUP BY id
            ) sub
            WHERE YEAR(max_date) = YEAR(outer_date)
          )

        This is tautological when the grouped key is the same table's unique ID.
        Stripping it allows the generic latest-year canonicalizer below to rebuild
        the correct "latest year per entity" join/filter shape.
        """
        s_text = (sql_text or "").strip()
        if not s_text:
            return sql_text

        where_pos = _find_top_level_clause(s_text, "where")
        group_pos = _find_top_level_clause(s_text, "group by", max(0, where_pos + len("where")))
        if where_pos < 0 or group_pos < 0:
            return sql_text

        from_pos = _find_top_level_clause(s_text, "from")
        if from_pos < 0 or from_pos > where_pos:
            return sql_text

        from_core_text = s_text[from_pos + len("from"):where_pos].strip()
        alias_map_local = _parse_from_join_aliases(f"SELECT 1 FROM {from_core_text}")
        where_body = s_text[where_pos + len("where"):group_pos].strip()
        if not where_body or _has_top_level_or(where_body):
            return sql_text

        try:
            analyzer_local = get_schema_analyzer()
        except Exception:
            analyzer_local = None

        def _plain_table_name_local(table_expr: str) -> str:
            return (table_expr or "").replace("`", "").split(".")[-1].strip()

        def _table_cols_local(table_name: str) -> Set[str]:
            t = _plain_table_name_local(table_name).lower()
            if not t:
                return set()
            if analyzer_local:
                try:
                    return {str(c).strip().lower() for c in analyzer_local.get_table_columns(t)}
                except Exception:
                    return set()
            return set()

        pattern = re.compile(
            r"""(?isx)^\s*
                `?(?P<outer_key_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_key_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s+IN\s*\(\s*
                SELECT\s+`?(?P<select_key_col>[A-Za-z_][A-Za-z0-9_]*)`?\s+
                FROM\s*\(\s*
                    SELECT\s+`?(?P<group_key_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*,\s*
                    MAX\s*\(\s*`?(?P<inner_date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s+AS\s+`?(?P<max_date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s+
                    FROM\s+`?(?P<inner_table>[A-Za-z_][A-Za-z0-9_]*)`?
                    \s+GROUP\s+BY\s+`?(?P<group_by_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s*\)\s*(?:AS\s+)?`?(?P<sub_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s+
                WHERE\s+YEAR\s*\(\s*`?(?P<filter_max_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*
                      YEAR\s*\(\s*`?(?P<outer_date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                \s*\)\s*$""",
        )

        changed = False
        kept_conjuncts: List[str] = []
        for cond in _split_top_level_and(where_body):
            cond_s = (cond or "").strip()
            m = pattern.match(cond_s)
            if not m:
                kept_conjuncts.append(cond_s)
                continue

            outer_key_alias = str(m.group("outer_key_alias") or "").strip()
            outer_key_col = str(m.group("outer_key_col") or "").strip().lower()
            select_key_col = str(m.group("select_key_col") or "").strip().lower()
            group_key_col = str(m.group("group_key_col") or "").strip().lower()
            group_by_col = str(m.group("group_by_col") or "").strip().lower()
            inner_date_col = str(m.group("inner_date_col") or "").strip().lower()
            inner_table = str(m.group("inner_table") or "").strip()
            max_date_alias = str(m.group("max_date_alias") or "").strip().lower()
            filter_max_alias = str(m.group("filter_max_alias") or "").strip().lower()
            outer_date_alias = str(m.group("outer_date_alias") or "").strip()
            outer_date_col = str(m.group("outer_date_col") or "").strip().lower()

            if not all([
                outer_key_alias,
                outer_key_col,
                select_key_col,
                group_key_col,
                group_by_col,
                inner_date_col,
                inner_table,
                max_date_alias,
                filter_max_alias,
                outer_date_alias,
                outer_date_col,
            ]):
                kept_conjuncts.append(cond_s)
                continue

            if select_key_col != outer_key_col or group_key_col != outer_key_col or group_by_col != outer_key_col:
                kept_conjuncts.append(cond_s)
                continue
            if max_date_alias != filter_max_alias:
                kept_conjuncts.append(cond_s)
                continue

            outer_key_table = str(alias_map_local.get(outer_key_alias) or alias_map_local.get(outer_key_alias.lower()) or "").strip()
            outer_date_table = str(alias_map_local.get(outer_date_alias) or alias_map_local.get(outer_date_alias.lower()) or "").strip()
            inner_table_plain = _plain_table_name_local(inner_table)
            if not outer_key_table or not outer_date_table or not inner_table_plain:
                kept_conjuncts.append(cond_s)
                continue
            if _plain_table_name_local(outer_key_table).lower() != inner_table_plain.lower():
                kept_conjuncts.append(cond_s)
                continue
            if _plain_table_name_local(outer_date_table).lower() != inner_table_plain.lower():
                kept_conjuncts.append(cond_s)
                continue

            inner_cols = _table_cols_local(inner_table_plain)
            if inner_cols and (outer_key_col not in inner_cols or inner_date_col not in inner_cols or outer_date_col not in inner_cols):
                kept_conjuncts.append(cond_s)
                continue

            try:
                id_col = str(get_id_column(inner_table_plain) or "").strip().lower()
            except Exception:
                id_col = ""
            if not id_col or outer_key_col != id_col:
                kept_conjuncts.append(cond_s)
                continue

            changed = True

        if not changed:
            return sql_text

        prefix = s_text[:where_pos].rstrip()
        suffix = s_text[group_pos:]
        if kept_conjuncts:
            return f"{prefix} WHERE {' AND '.join(kept_conjuncts)} {suffix}".strip()
        return f"{prefix} {suffix}".strip()

    def _strip_tautological_latest_year_having(sql_text: str) -> str:
        """
        Remove tautological HAVING predicates like:
          HAVING YEAR(MAX(p.paymentDate)) = YEAR(MAX(p.paymentDate))
        which can break parser-based rewrites while adding no filtering value.
        """
        m = re.search(
            r"""(?is)\bHAVING\s+YEAR\s*\(\s*MAX\s*\(\s*(.+?)\s*\)\s*\)\s*=\s*YEAR\s*\(\s*MAX\s*\(\s*(.+?)\s*\)\s*\)\s*""",
            sql_text,
        )
        if not m:
            return sql_text
        lhs = re.sub(r"[\s`]+", "", (m.group(1) or "").lower())
        rhs = re.sub(r"[\s`]+", "", (m.group(2) or "").lower())
        if not lhs or lhs != rhs:
            return sql_text
        return (sql_text[: m.start()] + " " + sql_text[m.end() :]).strip()

    def _strip_tautological_same_table_grouped_in_filter(sql_text: str) -> str:
        s_text = (sql_text or "").strip()
        if not s_text:
            return sql_text
        where_pos = _find_top_level_clause(s_text, "where")
        group_pos = _find_top_level_clause(s_text, "group by", max(0, where_pos + len("where")))
        if where_pos < 0 or group_pos < 0:
            return sql_text

        from_pos = _find_top_level_clause(s_text, "from")
        if from_pos < 0 or from_pos > where_pos:
            return sql_text

        from_core_text = s_text[from_pos + len("from"):where_pos].strip()
        alias_map_local = _parse_from_join_aliases(f"SELECT 1 FROM {from_core_text}")
        where_body = s_text[where_pos + len("where"):group_pos].strip()
        if not where_body or _has_top_level_or(where_body):
            return sql_text

        conjuncts = _split_top_level_and(where_body)
        if not conjuncts:
            return sql_text

        pattern = re.compile(
            r"""(?is)^\s*
                `?(?P<outer_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_col>[A-Za-z_][A-Za-z0-9_]*)`?\s+
                IN\s*\(\s*
                SELECT\s+`?(?P<inner_col>[A-Za-z_][A-Za-z0-9_]*)`?\s+
                FROM\s+`?(?P<inner_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?(?P<inner_alias>[A-Za-z_][A-Za-z0-9_]*)`?)?
                \s+GROUP\s+BY\s+`?(?P<group_col>[A-Za-z_][A-Za-z0-9_]*)`?\s+
                HAVING\s+COUNT\s*\(\s*\*\s*\)\s*>\s*0
                \s*\)\s*$""",
            re.X,
        )

        changed = False
        kept_conjuncts: List[str] = []
        for cond in conjuncts:
            cond_s = (cond or "").strip()
            m = pattern.match(cond_s)
            if not m:
                kept_conjuncts.append(cond_s)
                continue

            outer_alias = str(m.group("outer_alias") or "").strip()
            outer_col = str(m.group("outer_col") or "").strip().lower()
            inner_table = str(m.group("inner_table") or "").strip().lower()
            inner_col = str(m.group("inner_col") or "").strip().lower()
            group_col = str(m.group("group_col") or "").strip().lower()
            outer_table = str(alias_map_local.get(outer_alias) or alias_map_local.get(outer_alias.lower()) or "").strip().lower()

            if not outer_table:
                kept_conjuncts.append(cond_s)
                continue
            if outer_table != inner_table or outer_col != inner_col or inner_col != group_col:
                kept_conjuncts.append(cond_s)
                continue

            changed = True

        if not changed:
            return sql_text

        prefix = s_text[:where_pos].rstrip()
        suffix = s_text[group_pos:]
        if kept_conjuncts:
            return f"{prefix} WHERE {' AND '.join(kept_conjuncts)} {suffix}".strip()
        return f"{prefix} {suffix}".strip()

    sql_sanitized = _strip_tautological_same_table_latest_year_in_filter(sql)
    if sql_sanitized != sql:
        sql = sql_sanitized
        low_sql = sql.lower()

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        sql_sanitized = _strip_tautological_latest_year_having(sql)
        if sql_sanitized != sql:
            parsed = _parse_select_from_groupby(sql_sanitized)
            if parsed:
                sql = sql_sanitized
                low_sql = sql.lower()
    if not parsed:
        sql_sanitized = _strip_tautological_same_table_grouped_in_filter(sql)
        if sql_sanitized != sql:
            parsed = _parse_select_from_groupby(sql_sanitized)
            if parsed:
                sql = sql_sanitized
                low_sql = sql.lower()
    if not parsed:
        return sql

    from_core = parsed["from_core"].strip()
    if not from_core:
        return sql

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_qualified_col(expr: str) -> Optional[tuple]:
        """
        Parse simple column reference:
          p.paymentDate  -> ("p", "paymentDate")
          paymentDate    -> (None, "paymentDate")
        """
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _extract_alias_refs(expr: str) -> List[str]:
        refs = re.findall(r"`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.", expr or "", flags=re.I)
        # keep order, dedup case-insensitively
        out: List[str] = []
        seen = set()
        for r in refs:
            k = r.lower()
            if k in seen:
                continue
            seen.add(k)
            out.append(r)
        return out

    def _pick_best_key(candidates: List[str], avoid_cols: Set[str]) -> Optional[str]:
        if not candidates:
            return None
        uniq = []
        seen = set()
        for c in candidates:
            k = c.lower()
            if k in seen:
                continue
            seen.add(k)
            uniq.append(c)

        def score(col: str) -> int:
            c = col.lower()
            s = 0
            if c in avoid_cols:
                s -= 10
            if c.endswith("id") or c.endswith("number") or c.endswith("code"):
                s += 5
            if "id" in c or "number" in c or "code" in c:
                s += 2
            return s

        return sorted(uniq, key=score, reverse=True)[0]

    select_items = _split_top_level_commas(parsed["select"])
    if len(select_items) < 3:
        return sql

    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    date_expr_raw: Optional[str] = None
    sum_expr_raw: Optional[str] = None
    name_projection_rewrites: Dict[str, str] = {}
    where_clause_text = str(parsed.get("where") or "").strip()
    allow_explicit_year_projection = (
        not bool(where_clause_text)
        or not re.search(r"\b(?:year|date|time|timestamp)\b", where_clause_text, flags=re.I)
    )

    def _clean_alias_token(alias_value: Optional[str]) -> str:
        if not alias_value:
            return ""
        a = alias_value.strip()
        if (
            (a.startswith("`") and a.endswith("`"))
            or (a.startswith("'") and a.endswith("'"))
            or (a.startswith('"') and a.endswith('"'))
        ):
            a = a[1:-1]
        return a.strip().lower()

    def _repair_requested_name_projection(item: str) -> str:
        if not re.search(r"\bname\b", question or "", flags=re.I):
            return item
        expr, alias = _split_expr_alias(item)
        alias_clean = _clean_alias_token(alias)
        if "name" not in alias_clean:
            return item
        ref = _parse_qualified_col(expr)
        if not ref or not ref[0]:
            return item
        ref_alias, ref_col = ref
        entity_table = alias_map.get(ref_alias) or alias_map.get(ref_alias.lower()) or ref_alias
        try:
            name_col = str(get_name_column(entity_table) or "").strip()
        except Exception:
            name_col = ""
        if not name_col or ref_col.lower() == name_col.lower():
            return item
        name_projection_rewrites[_normalize_sql_expr_for_match(expr)] = f"{ref_alias}.{name_col}"
        if alias:
            return f"{ref_alias}.{name_col} AS {alias}"
        return f"{ref_alias}.{name_col}"

    for it in select_items:
        it = _repair_requested_name_projection(it)
        expr, _alias = _split_expr_alias(it)

        m_max = re.match(r"(?is)^MAX\s*\(\s*(.+?)\s*\)$", expr)
        if m_max and date_expr_raw is None:
            max_inner = m_max.group(1).strip()
            # Accept both:
            #   MAX(o.orderDate)
            #   MAX(YEAR(o.orderDate))
            year_wrap = re.match(r"(?is)^YEAR\s*\(\s*(.+?)\s*\)$", max_inner)
            max_inner_col = year_wrap.group(1).strip() if year_wrap else max_inner
            parsed_col = _parse_qualified_col(max_inner_col)
            if parsed_col:
                _, col_name = parsed_col
                if ("date" in col_name.lower()) or ("time" in col_name.lower()):
                    date_expr_raw = max_inner_col
                    continue

        m_year = re.match(r"(?is)^YEAR\s*\(\s*(.+?)\s*\)$", expr)
        if allow_explicit_year_projection and m_year and date_expr_raw is None:
            year_inner = m_year.group(1).strip()
            parsed_col = _parse_qualified_col(year_inner)
            if parsed_col:
                _, col_name = parsed_col
                alias_l = _clean_alias_token(_alias)
                # Keep this narrow: only treat explicit YEAR(date) projection as
                # the target latest-year output when the alias is year-like.
                if (
                    (("date" in col_name.lower()) or ("time" in col_name.lower()))
                    and alias_l
                    and (("year" in alias_l) or ("tahun" in alias_l))
                ):
                    date_expr_raw = year_inner
                    continue

        m_sum = re.match(r"(?is)^SUM\s*\(\s*(.+?)\s*\)$", expr)
        if m_sum and sum_expr_raw is None:
            sum_expr_raw = m_sum.group(1).strip()
            continue

    if not date_expr_raw or not sum_expr_raw:
        return sql

    date_col = _parse_qualified_col(date_expr_raw)
    if not date_col:
        return sql
    date_alias, date_col_name = date_col

    sum_alias_refs = _extract_alias_refs(sum_expr_raw)
    date_owner_alias: Optional[str] = date_alias
    measure_alias: Optional[str] = None
    if date_alias:
        if not sum_alias_refs:
            measure_alias = date_alias
        elif all(a.lower() == date_alias.lower() for a in sum_alias_refs):
            measure_alias = date_alias
        elif len(sum_alias_refs) == 1:
            # Cross-alias pattern:
            # SUM on bridge/fact alias (e.g., od.quantityOrdered),
            # DATE on joined temporal alias (e.g., o.orderDate).
            measure_alias = sum_alias_refs[0]
        else:
            return sql
    else:
        if len(sum_alias_refs) == 1:
            measure_alias = sum_alias_refs[0]
            date_owner_alias = measure_alias
        else:
            return sql

    if not measure_alias:
        return sql
    if not date_owner_alias:
        date_owner_alias = measure_alias

    def _resolve_table_from_alias(alias_name: Optional[str]) -> Optional[str]:
        if not alias_name:
            return None
        tbl = alias_map.get(alias_name) or alias_map.get(alias_name.lower())
        return tbl or alias_name

    measure_table = _resolve_table_from_alias(measure_alias)
    date_owner_table = _resolve_table_from_alias(date_owner_alias)
    if not measure_table or not date_owner_table:
        return sql

    # Schema-aware column checks.
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    allowed_cols: Dict[str, Set[str]] = {}
    if not analyzer and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(t).strip().lower(): {str(c).strip().lower() for c in cols}
                for t, cols in (allowed or {}).items()
            }
        except Exception:
            allowed_cols = {}

    def _table_cols(table_name: str) -> Set[str]:
        t = (table_name or "").replace("`", "").split(".")[-1].strip().lower()
        if not t:
            return set()
        if analyzer:
            try:
                return {c.lower() for c in analyzer.get_table_columns(t)}
            except Exception:
                return set()
        return set(allowed_cols.get(t, set()))

    date_owner_cols = _table_cols(date_owner_table)
    if date_owner_cols and date_col_name.lower() not in date_owner_cols:
        return sql

    existing_aliases = {k.lower() for k in alias_map.keys() if k and not k.startswith("__")}

    # Find join keys connected to metric alias via ON predicates.
    eq_pat = re.compile(
        r"`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*"
        r"`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?",
        flags=re.I,
    )
    key_candidates: List[str] = []
    measure_date_links: List[Tuple[str, str]] = []
    for m in eq_pat.finditer(from_core):
        a1, c1, a2, c2 = m.group(1), m.group(2), m.group(3), m.group(4)
        if a1.lower() == measure_alias.lower():
            key_candidates.append(c1)
        if a2.lower() == measure_alias.lower():
            key_candidates.append(c2)
        if a1.lower() == measure_alias.lower() and a2.lower() == date_owner_alias.lower():
            measure_date_links.append((c1, c2))
        elif a2.lower() == measure_alias.lower() and a1.lower() == date_owner_alias.lower():
            measure_date_links.append((c2, c1))

    # Fallback: metric alias appears in GROUP BY.
    if not key_candidates:
        for g in _split_top_level_commas(parsed["groupby"]):
            gm = _parse_qualified_col(g)
            if not gm:
                continue
            g_alias, g_col = gm
            if g_alias and g_alias.lower() == measure_alias.lower():
                key_candidates.append(g_col)

    measure_date_key_col: Optional[str] = None
    date_join_col: Optional[str] = None
    if date_owner_alias.lower() != measure_alias.lower():
        if not measure_date_links:
            return sql
        # Prefer symmetric key names (e.g., orderNumber=orderNumber), then id/code-like.
        scored = []
        for mk, dk in measure_date_links:
            s = 0
            if mk.lower() == dk.lower():
                s += 5
            mk_l = mk.lower()
            if mk_l.endswith("id") or mk_l.endswith("number") or mk_l.endswith("code"):
                s += 3
            elif ("id" in mk_l) or ("number" in mk_l) or ("code" in mk_l):
                s += 1
            scored.append((s, mk, dk))
        scored.sort(key=lambda x: x[0], reverse=True)
        measure_date_key_col, date_join_col = scored[0][1], scored[0][2]

    avoid_cols = {date_col_name.lower()}
    if measure_date_key_col:
        avoid_cols.add(measure_date_key_col.lower())
    measure_key_col = _pick_best_key(key_candidates, avoid_cols=avoid_cols)
    if not measure_key_col:
        return sql

    # If query already has this year filter, do nothing (alias-agnostic).
    date_ref = (
        f"{date_owner_alias}.{date_col_name}"
        if date_owner_alias
        else f"{date_col_name}"
    )
    if date_owner_alias:
        year_filter_pat = re.compile(
            rf"\bYEAR\s*\(\s*`?{re.escape(date_owner_alias)}`?\s*\.\s*`?{re.escape(date_col_name)}`?\s*\)\s*=\s*[A-Za-z_][A-Za-z0-9_]*\.latest_year",
            flags=re.I,
        )
    else:
        year_filter_pat = re.compile(
            rf"\bYEAR\s*\(\s*`?{re.escape(date_col_name)}`?\s*\)\s*=\s*[A-Za-z_][A-Za-z0-9_]*\.latest_year",
            flags=re.I,
        )
    if year_filter_pat.search(sql):
        return sql

    def _pick_subquery_alias(preferred: str = "latest_years") -> str:
        base = re.sub(r"[^A-Za-z0-9_]", "", preferred) or "latest_years"
        if not re.match(r"[A-Za-z_]", base[0]):
            base = f"y_{base}"
        cand = base
        i = 2
        while cand.lower() in existing_aliases:
            cand = f"{base}_{i}"
            i += 1
        existing_aliases.add(cand.lower())
        return cand

    year_alias = _pick_subquery_alias(f"{measure_alias}_latest_years")

    if date_owner_alias.lower() == measure_alias.lower():
        ly_join = (
            "JOIN (\n"
            "  SELECT\n"
            f"    {measure_key_col},\n"
            f"    MAX(YEAR({date_col_name})) AS latest_year\n"
            f"  FROM {measure_table}\n"
            f"  GROUP BY {measure_key_col}\n"
            f") AS {year_alias}\n"
            f"  ON {year_alias}.{measure_key_col} = {measure_alias}.{measure_key_col}"
        )
    else:
        if not measure_date_key_col or not date_join_col:
            return sql
        ly_measure_alias = _pick_subquery_alias(f"{measure_alias}_ly")
        ly_date_alias = _pick_subquery_alias(f"{date_owner_alias}_ly")
        ly_join = (
            "JOIN (\n"
            "  SELECT\n"
            f"    {ly_measure_alias}.{measure_key_col},\n"
            f"    MAX(YEAR({ly_date_alias}.{date_col_name})) AS latest_year\n"
            f"  FROM {measure_table} AS {ly_measure_alias}\n"
            f"  JOIN {date_owner_table} AS {ly_date_alias}\n"
            f"    ON {ly_date_alias}.{date_join_col} = {ly_measure_alias}.{measure_date_key_col}\n"
            f"  GROUP BY {ly_measure_alias}.{measure_key_col}\n"
            f") AS {year_alias}\n"
            f"  ON {year_alias}.{measure_key_col} = {measure_alias}.{measure_key_col}"
        )

    from_with_ly = f"{from_core}\n{ly_join}"
    year_cond = f"YEAR({date_ref}) = {year_alias}.latest_year"

    where_clause = parsed["where"].strip()
    if where_clause:
        # Preserve original boolean precedence (especially OR chains).
        existing_pred = re.sub(r"^\s*WHERE\s+", "", where_clause, flags=re.I).strip()
        # Remove stale correlated MAX(date) predicate when present.
        # Keeping it would incorrectly reduce SUM(amount) to only max-date rows.
        if existing_pred and not _has_top_level_or(existing_pred):
            kept_predicates: List[str] = []
            for cond in _split_top_level_and(existing_pred):
                c0 = (cond or "").strip()
                low_c0 = c0.lower()
                norm_c0 = re.sub(r"[\s`]+", "", low_c0)
                is_correlated_max_date = bool(
                    re.search(r"\b(?:in|=)\s*\(\s*select\s+max\s*\(", low_c0)
                    and "year(" in low_c0
                    and date_col_name.lower() in low_c0
                )
                date_alias_forms = {
                    a.lower()
                    for a in [measure_alias, date_owner_alias]
                    if a
                }
                self_max_forms = {
                    f"year({date_col_name.lower()})=year(max({date_col_name.lower()}))",
                    f"year(max({date_col_name.lower()}))=year({date_col_name.lower()})",
                }
                for da in date_alias_forms:
                    self_max_forms.add(
                        f"year({da}.{date_col_name.lower()})=year(max({da}.{date_col_name.lower()}))"
                    )
                    self_max_forms.add(
                        f"year(max({da}.{date_col_name.lower()}))=year({da}.{date_col_name.lower()})"
                    )
                is_self_max_year_pred = norm_c0 in self_max_forms
                if is_correlated_max_date or is_self_max_year_pred:
                    continue
                kept_predicates.append(c0)
            existing_pred = " AND ".join(p for p in kept_predicates if p)

        if existing_pred:
            where_clause = f"WHERE ({existing_pred}) AND {year_cond}"
        else:
            where_clause = f"WHERE {year_cond}"
    else:
        where_clause = f"WHERE {year_cond}"

    tail_clause = f"\n{parsed['tail'].strip()}" if parsed["tail"].strip() else ""
    rebuilt_select_items = [
        _repair_requested_name_projection(item)
        for item in _split_top_level_commas(parsed["select"])
    ]
    rebuilt_group_items: List[str] = []
    for item in _split_top_level_commas(parsed["groupby"]):
        item_s = (item or "").strip()
        item_norm = _normalize_sql_expr_for_match(item_s)
        rebuilt_group_items.append(name_projection_rewrites.get(item_norm, item_s))
    fixed = (
        f"SELECT {', '.join(rebuilt_select_items)}\n"
        f"FROM {from_with_ly}\n"
        f"{where_clause}\n"
        f"GROUP BY {', '.join(rebuilt_group_items)}"
        f"{tail_clause};"
    )
    return fixed

def _rewrite_latest_year_correlated_maxdate_misuse(sql: str, question: str, ctx: str = "") -> str:
    """
    Fix correlated-subquery anti-pattern such as:

      WHERE p.paymentDate IN (
        SELECT MAX(paymentDate)
        FROM payments p2
        WHERE YEAR(p2.paymentDate) = YEAR(p.paymentDate)
          AND p2.customerNumber = p.customerNumber
      )

    combined with SUM(amount) + GROUP BY customer/year.

    Strategy:
      1) Canonicalize into: SELECT entity_cols, MAX(date), SUM(amount) ... GROUP BY entity_cols
      2) Reuse latest-year rewrite to enforce "sum in the most recent year".
    """
    if not sql:
        return sql

    if not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    s = sql.strip().rstrip(";").strip()
    if not s:
        return sql

    # Already-correct latest-year shape: skip.
    low = s.lower()
    if "latest_year" in low and re.search(r"=\s*[a-z_][a-z0-9_]*\.latest_year\b", low):
        return sql

    parsed = _parse_select_from_groupby(s)
    if not parsed:
        return sql
    if not parsed.get("where"):
        return sql

    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {parsed['from_core'].strip()}")
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None
    allowed_cols: Dict[str, Set[str]] = {}
    if not analyzer and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                t.lower(): {c.lower() for c in cols}
                for t, cols in allowed.items()
            }
        except Exception:
            allowed_cols = {}

    where_raw = re.sub(r"^\s*WHERE\s+", "", parsed["where"].strip(), flags=re.I).strip()
    if not where_raw:
        return sql
    # Target only correlated max-date subquery shape.
    if not re.search(r"\b(?:IN|=)\s*\(\s*SELECT\s+MAX\s*\(", where_raw, flags=re.I):
        return sql
    if "year(" not in where_raw.lower():
        return sql

    # Keep rewrite conservative on OR expressions.
    if _has_top_level_or(where_raw):
        return sql

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_qualified_col(expr: str) -> Optional[tuple]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _strip_as(item: str) -> str:
        return re.sub(
            r"""(?is)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            "",
            item.strip(),
        ).strip()

    def _safe_alias(a: Optional[str], default_name: str) -> str:
        if not a:
            return default_name
        x = a.strip()
        if (x.startswith("`") and x.endswith("`")) or (x.startswith("'") and x.endswith("'")) or (x.startswith('"') and x.endswith('"')):
            x = x[1:-1]
        x = re.sub(r"\s+", "_", x)
        x = re.sub(r"[^A-Za-z0-9_]", "", x)
        if not x:
            return default_name
        if not re.match(r"[A-Za-z_]", x[0]):
            return default_name
        return x

    def _table_cols(tbl: str) -> Set[str]:
        if not tbl:
            return set()
        t_l = tbl.lower()
        if analyzer:
            try:
                return {x.lower() for x in analyzer.get_table_columns(t_l)}
            except Exception:
                return set()
        return set(allowed_cols.get(t_l, set()))

    def _repair_date_expr_if_needed(expr_raw: str) -> str:
        """
        If <alias>.<date_col> points to a table that does not own <date_col>,
        and exactly one other visible alias owns it, rewrite to that alias.
        """
        parsed_col = _parse_qualified_col(expr_raw)
        if not parsed_col:
            return expr_raw
        a, c = parsed_col
        if not a:
            return expr_raw

        src_table = alias_map.get(a) or alias_map.get(a.lower())
        if not src_table:
            return expr_raw
        src_cols = _table_cols(src_table)
        if not src_cols:
            return expr_raw
        if c.lower() in src_cols:
            return expr_raw

        candidates = []
        seen_tables = set()
        for al, tbl in alias_map.items():
            al_l = (al or "").lower()
            if not al_l or al_l in seen_tables:
                continue
            # skip duplicate convenience key entries from alias parser
            seen_tables.add(al_l)
            cols = _table_cols(tbl)
            if c.lower() in cols and al_l != a.lower():
                candidates.append(al)

        # unique repair only
        uniq = []
        seen = set()
        for x in candidates:
            xl = x.lower()
            if xl in seen:
                continue
            seen.add(xl)
            uniq.append(x)
        if len(uniq) != 1:
            return expr_raw
        return f"{uniq[0]}.{c}"

    select_items = _split_top_level_commas(parsed["select"])
    if not select_items:
        return sql

    entity_items: List[str] = []
    date_expr_raw: Optional[str] = None
    date_alias_raw: Optional[str] = None
    sum_expr_inner: Optional[str] = None
    sum_alias_raw: Optional[str] = None
    measure_alias: Optional[str] = None
    date_col_name: Optional[str] = None

    for it in select_items:
        expr, alias = _split_expr_alias(it)

        m_sum = re.match(r"(?is)^SUM\s*\(\s*(.+?)\s*\)$", expr)
        if m_sum and sum_expr_inner is None:
            sum_expr_inner = m_sum.group(1).strip()
            sum_alias_raw = alias
            refs = re.findall(r"`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.", sum_expr_inner, flags=re.I)
            if len(refs) == 1:
                measure_alias = refs[0]
            continue

        # Date may be raw (p.paymentDate) or already aggregated.
        m_max = re.match(r"(?is)^MAX\s*\(\s*(.+?)\s*\)$", expr)
        candidate = m_max.group(1).strip() if m_max else expr
        parsed_col = _parse_qualified_col(candidate)
        if parsed_col:
            a, c = parsed_col
            if ("date" in c.lower()) or ("time" in c.lower()):
                if date_expr_raw is None:
                    date_expr_raw = _repair_date_expr_if_needed(candidate)
                    date_alias_raw = alias
                    repaired_col = _parse_qualified_col(date_expr_raw)
                    if repaired_col:
                        ra, rc = repaired_col
                        date_col_name = rc
                        if ra:
                            measure_alias = ra
                    else:
                        date_col_name = c
                        if a:
                            measure_alias = a
                    continue

        # Keep non-aggregate entity columns.
        if not re.search(r"\b(SUM|COUNT|AVG|MIN|MAX)\s*\(", expr, flags=re.I):
            entity_items.append(it.strip())

    if not date_expr_raw or not sum_expr_inner:
        return sql

    if not measure_alias:
        refs = re.findall(r"`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.", date_expr_raw, flags=re.I)
        if len(refs) == 1:
            measure_alias = refs[0]
    if not measure_alias or not date_col_name:
        return sql

    # Remove correlated MAX(date) predicate from WHERE, keep unrelated filters.
    conjuncts = _split_top_level_and(where_raw)
    keep_conj: List[str] = []
    for c in conjuncts:
        c0 = c.strip()
        low_c0 = c0.lower()
        if ("select" in low_c0) and ("max(" in low_c0) and ("year(" in low_c0):
            continue
        keep_conj.append(c0)

    # Build canonical GROUP BY from non-aggregate entity columns.
    group_items: List[str] = []
    seen_g = set()
    for it in entity_items:
        g = _strip_as(it)
        k = g.lower()
        if k in seen_g:
            continue
        seen_g.add(k)
        group_items.append(g)

    if not group_items:
        # fallback from original GROUP BY: drop YEAR(...) and aggregates
        for g in _split_top_level_commas(parsed.get("groupby", "")):
            g0 = g.strip()
            if not g0:
                continue
            low_g = g0.lower()
            if ("year(" in low_g) or re.search(r"\b(SUM|COUNT|AVG|MIN|MAX)\s*\(", low_g, flags=re.I):
                continue
            k = g0.lower()
            if k in seen_g:
                continue
            seen_g.add(k)
            group_items.append(g0)

    if not group_items:
        return sql

    # Qualify SUM expression to metric alias if expression is bare column.
    sum_expr_final = sum_expr_inner.strip()
    if re.fullmatch(r"`?[A-Za-z_][A-Za-z0-9_]*`?", sum_expr_final):
        sum_expr_final = f"{measure_alias}.{sum_expr_final.strip('`')}"

    date_alias_out = _safe_alias(date_alias_raw, f"latest_{date_col_name}")
    sum_alias_out = _safe_alias(sum_alias_raw, "total_amount")

    # Preserve requested ORDER BY direction, but make it aggregate-safe.
    order_clause = ""
    limit_clause = ""
    tail = (parsed.get("tail") or "").strip()
    if tail:
        m_limit = re.search(r"\bLIMIT\b.+$", tail, flags=re.I)
        if m_limit:
            limit_clause = " " + m_limit.group(0).strip()
        if re.search(r"\bORDER\s+BY\b", tail, flags=re.I):
            if re.search(r"\bDESC\b", tail, flags=re.I):
                direction = "DESC"
            elif re.search(r"\bASC\b", tail, flags=re.I):
                direction = "ASC"
            else:
                direction = "DESC"
            order_clause = f"ORDER BY MAX({date_expr_raw}) {direction}"

    canonical_lines = []
    canonical_lines.append("SELECT")
    select_out = []
    select_out.extend(entity_items)
    select_out.append(f"MAX({date_expr_raw}) AS {date_alias_out}")
    select_out.append(f"SUM({sum_expr_final}) AS {sum_alias_out}")
    canonical_lines.append("  " + ",\n  ".join(select_out))
    canonical_lines.append(f"FROM {parsed['from_core'].strip()}")
    if keep_conj:
        canonical_lines.append("WHERE " + " AND ".join(keep_conj))
    canonical_lines.append("GROUP BY " + ", ".join(group_items))
    if order_clause:
        canonical_lines.append(order_clause + limit_clause)
    elif limit_clause:
        canonical_lines.append(limit_clause.strip())
    canonical_sql = "\n".join(canonical_lines).strip() + ";"

    # Reuse the existing latest-year rewrite.
    fixed = _rewrite_latest_year_same_year_aggregate(canonical_sql, question, ctx)
    return fixed if fixed else canonical_sql

def _move_latest_year_filter_where_to_inner_on(sql: str) -> str:
    """
    Canonicalize style:
      WHERE YEAR(p.paymentDate) = ly.latest_year
    ->
      JOIN payments p ON ... AND YEAR(p.paymentDate) = ly.latest_year

    Safety rules:
    - only for queries parseable as SELECT...FROM...GROUP BY...
    - only when all joins are INNER/JOIN (no LEFT/RIGHT/FULL)
    - only top-level AND predicates (skip OR)
    - only predicates matching YEAR(<alias>.<col>) = <alias>.latest_year (or reversed)
    """
    if not sql:
        return sql
    if "latest_year" not in (sql or "").lower():
        return sql

    def _is_word_boundary(text: str, i: int, n: int) -> bool:
        left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
        right_ok = (i + n) >= len(text) or not (text[i + n].isalnum() or text[i + n] == "_")
        return left_ok and right_ok

    def _scan_top_level_word_positions(text: str, word: str) -> List[int]:
        out: List[int] = []
        w = word.lower()
        n = len(w)
        depth = 0
        in_sq = False
        in_dq = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i + n <= len(text) and text[i:i + n].lower() == w and _is_word_boundary(text, i, n):
                out.append(i)
            i += 1
        return out

    def _first_top_level_word_pos(text: str, word: str, start: int = 0) -> int:
        for p in _scan_top_level_word_positions(text, word):
            if p >= start:
                return p
        return -1

    def _first_top_level_group_by_pos(text: str, start: int = 0) -> int:
        for p in _scan_top_level_word_positions(text, "group"):
            if p < start:
                continue
            j = p + len("group")
            while j < len(text) and text[j].isspace():
                j += 1
            if j + 2 <= len(text) and text[j:j + 2].lower() == "by" and _is_word_boundary(text, j, 2):
                return p
        return -1

    def _first_top_level_order_by_pos(text: str, start: int = 0) -> int:
        for p in _scan_top_level_word_positions(text, "order"):
            if p < start:
                continue
            j = p + len("order")
            while j < len(text) and text[j].isspace():
                j += 1
            if j + 2 <= len(text) and text[j:j + 2].lower() == "by" and _is_word_boundary(text, j, 2):
                return p
        return -1

    s0 = sql.strip().rstrip(";").strip()
    if not s0:
        return sql

    from_pos = _first_top_level_word_pos(s0, "from", start=0)
    if from_pos < 0:
        return sql

    where_pos = _first_top_level_word_pos(s0, "where", start=from_pos + 4)
    group_pos = _first_top_level_group_by_pos(s0, start=from_pos + 4)
    having_pos = _first_top_level_word_pos(s0, "having", start=from_pos + 4)
    order_pos = _first_top_level_order_by_pos(s0, start=from_pos + 4)
    limit_pos = _first_top_level_word_pos(s0, "limit", start=from_pos + 4)

    def _next_pos_after(start_pos: int, candidates: List[int]) -> int:
        vals = [p for p in candidates if p >= 0 and p > start_pos]
        return min(vals) if vals else -1

    # FROM core ends at first top-level clause after FROM.
    from_end = _next_pos_after(
        from_pos,
        [p for p in [where_pos, group_pos, having_pos, order_pos, limit_pos] if p >= 0],
    )
    if from_end < 0:
        from_end = len(s0)

    from_core = s0[from_pos + 4:from_end].strip()
    if not from_core:
        return sql
    if not re.search(r"\bjoin\b", from_core, flags=re.I):
        return sql
    if re.search(r"\b(left|right|full)\s+join\b", from_core, flags=re.I):
        return sql

    if where_pos < 0:
        return sql
    where_end = _next_pos_after(
        where_pos,
        [p for p in [group_pos, having_pos, order_pos, limit_pos] if p >= 0],
    )
    if where_end < 0:
        where_end = len(s0)
    where_body = s0[where_pos + 5:where_end].strip()
    if not where_body:
        return sql
    if _has_top_level_or(where_body):
        return sql

    select_prefix = s0[:from_pos].strip()
    rest_after_where = s0[where_end:].strip() if where_end < len(s0) else ""

    def _strip_wrapping_parens(expr: str) -> str:
        s = (expr or "").strip()
        changed = True
        while changed and s.startswith("(") and s.endswith(")"):
            changed = False
            depth = 0
            ok = True
            for i, ch in enumerate(s):
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth < 0:
                        ok = False
                        break
                    if depth == 0 and i != len(s) - 1:
                        ok = False
                        break
            if ok and depth == 0:
                s = s[1:-1].strip()
                changed = True
        return s

    def _extract_latest_year_alias_pair(cond: str) -> Optional[tuple]:
        c = _strip_wrapping_parens(cond)
        p1 = re.match(
            r"""(?is)^\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?latest_year`?\s*$""",
            c,
        )
        if p1:
            return p1.group(1), p1.group(3)
        p2 = re.match(
            r"""(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?latest_year`?\s*=\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*$""",
            c,
        )
        if p2:
            return p2.group(2), p2.group(1)
        return None

    def _rhs_alias_from_join_pre(pre: str) -> Optional[str]:
        p = pre.strip()
        # Derived table join: JOIN ( ... ) AS alias
        m_sub = re.search(r"\)\s*(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*$", p, flags=re.I)
        if m_sub:
            return m_sub.group(1)
        # Regular table join: JOIN table [AS] alias?
        m_tbl = re.search(
            r"""\b(?:INNER\s+JOIN|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?\s*$""",
            p,
            flags=re.I,
        )
        if not m_tbl:
            return None
        alias = (m_tbl.group(2) or "").strip()
        if alias:
            return alias
        tbl = (m_tbl.group(1) or "").replace("`", "").split(".")[-1]
        return tbl or None

    def _base_aliases_from_from_core_base(base: str) -> Set[str]:
        """
        Parse base FROM part before first JOIN.
        Examples:
          customers AS c  -> {"c", "customers"}
          `db`.`customers` c -> {"c", "customers"}
          customers -> {"customers"}
        """
        b = (base or "").strip()
        out: Set[str] = set()
        m = re.match(
            r"""(?is)^(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?\s*$""",
            b,
        )
        if not m:
            return out
        tbl = (m.group(1) or "").replace("`", "").split(".")[-1].strip()
        alias = (m.group(2) or "").strip()
        if tbl:
            out.add(tbl.lower())
        if alias:
            out.add(alias.lower())
        return out

    # Build join segments at top level.
    raw_join_positions = _scan_top_level_word_positions(from_core, "join")
    if not raw_join_positions:
        return sql
    join_positions: List[int] = []
    for p in raw_join_positions:
        start = p
        prefix = from_core[:p]
        m_inner = re.search(r"\bINNER\s*$", prefix, flags=re.I)
        if m_inner:
            start = m_inner.start()
        if not join_positions or join_positions[-1] != start:
            join_positions.append(start)

    segments = []
    for i, start in enumerate(join_positions):
        end = join_positions[i + 1] if i + 1 < len(join_positions) else len(from_core)
        seg = from_core[start:end]
        on_rel = _first_top_level_word_pos(seg, "on", start=0)
        if on_rel < 0:
            continue
        pre = seg[:on_rel].rstrip()
        on_expr = seg[on_rel + 2:].strip()
        rhs_alias = _rhs_alias_from_join_pre(pre)
        segments.append(
            {
                "start": start,
                "end": end,
                "pre": pre,
                "on": on_expr,
                "rhs_alias": (rhs_alias or "").strip(),
                "moved": [],
                "avail": set(),
            }
        )

    if not segments:
        return sql

    # Compute alias scope available at each JOIN ON clause.
    base_aliases = _base_aliases_from_from_core_base(from_core[:join_positions[0]])
    running_aliases: Set[str] = set(base_aliases)
    for seg in segments:
        rhs = (seg.get("rhs_alias") or "").lower()
        if rhs:
            running_aliases.add(rhs)
        seg["avail"] = set(running_aliases)

    # Extract movable predicates from WHERE.
    conjuncts = _split_top_level_and(where_body)
    keep_conj: List[str] = []
    moved_any = False

    for cond in conjuncts:
        c0 = cond.strip()
        pair = _extract_latest_year_alias_pair(c0)
        if not pair:
            keep_conj.append(c0)
            continue

        date_alias, year_alias = pair[0], pair[1]
        date_alias_l = date_alias.lower()
        year_alias_l = year_alias.lower()

        # Prefer the rightmost JOIN where BOTH aliases are already in scope.
        # This guarantees the ON clause can legally reference both sides.
        target_idx = -1
        for j in range(len(segments) - 1, -1, -1):
            avail = {a.lower() for a in (segments[j].get("avail") or set())}
            if date_alias_l in avail and year_alias_l in avail:
                target_idx = j
                break
        # Fallback: attach to a JOIN introducing one of the aliases.
        if target_idx < 0:
            for j in range(len(segments) - 1, -1, -1):
                rhs = (segments[j]["rhs_alias"] or "").lower()
                if rhs in {date_alias_l, year_alias_l}:
                    target_idx = j
                    break

        if target_idx < 0:
            keep_conj.append(c0)
            continue

        segments[target_idx]["moved"].append(c0)
        moved_any = True

    if not moved_any:
        return sql

    # Reconstruct FROM/JOIN with predicates moved into target ON clauses.
    base = from_core[:join_positions[0]].strip()
    rebuilt_parts: List[str] = [base] if base else []
    for seg in segments:
        on_new = seg["on"]
        for p in seg["moved"]:
            on_new = f"({on_new}) AND ({p})"
        rebuilt_parts.append(f"{seg['pre']} ON {on_new}")
    from_new = "\n".join(p for p in rebuilt_parts if p and p.strip())

    out_lines = []
    out_lines.append(select_prefix)
    out_lines.append(f"FROM {from_new}")
    if keep_conj:
        out_lines.append("WHERE " + " AND ".join(keep_conj))
    if rest_after_where:
        out_lines.append(rest_after_where)

    fixed = "\n".join(x for x in out_lines if x and x.strip()).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed

def _rewrite_latest_year_derived_subquery_misuse(sql: str, question: str, ctx: str = "") -> str:
    """
    Handle malformed pattern:

      SELECT entity_cols, sub.paymentDate, sub.amount
      FROM entity e
      JOIN (
        SELECT key, MAX(date) AS latest_date, SUM(amount) AS total_amount
        FROM metric
        GROUP BY key
      ) sub ON e.key = sub.key
      [WHERE ...]

    This pattern is both semantically wrong for "same year sum" and can reference
    non-existent columns from derived subquery aliases.
    """
    if not sql:
        return sql

    if not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    s = sql.strip().rstrip(";").strip()
    if not s:
        return sql

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if not analyzer and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(t).strip().lower(): {str(c).strip().lower() for c in cols}
                for t, cols in (allowed or {}).items()
            }
        except Exception:
            allowed_cols = {}

    def _plain_table_name(table_expr: str) -> str:
        return (table_expr or "").replace("`", "").split(".")[-1].strip()

    def _table_cols(table_name: str) -> Set[str]:
        table_lower = _plain_table_name(table_name).lower()
        if not table_lower:
            return set()
        if analyzer:
            try:
                return {str(c).strip("`").lower() for c in analyzer.get_table_columns(table_lower)}
            except Exception:
                return set()
        return set(allowed_cols.get(table_lower, set()))

    def _column_role(table_name: str, col_name: str) -> str:
        table_lower = _plain_table_name(table_name).lower()
        col_lower = str(col_name or "").strip("`").lower()
        if not analyzer or not table_lower or not col_lower:
            return ""
        try:
            return str((analyzer._column_roles.get(table_lower, {}) or {}).get(col_lower, "")).strip().lower()
        except Exception:
            return ""

    def _is_temporal_column(table_name: str, col_name: str) -> bool:
        col_lower = str(col_name or "").strip("`").lower()
        if not col_lower:
            return False
        role = _column_role(table_name, col_name)
        if role in {"date", "datetime", "timestamp", "time"}:
            return True
        return (
            "date" in col_lower
            or "time" in col_lower
            or col_lower.endswith("at")
            or col_lower in HELPERS_TEMPORAL_EVENT_COLUMN_TERMS
        )

    try:
        transaction_tables = {str(t).strip().lower() for t in (get_transaction_tables() or []) if str(t).strip()}
    except Exception:
        transaction_tables = set()

    def _fallback_rewrite_latest_year_entity_metric(raw: str) -> Optional[str]:
        """
        Salvage malformed latest-year derived-subquery SQL into a generic:
          entity -> latest_year(metric) -> filtered metric rows
        pattern without assuming specific table or column names.

        This fallback is intentionally limited to the safer single-metric-table
        shape where the metric table owns both the date column and the aggregated
        measure expression.
        """
        low_raw = (raw or "").lower()
        if "year(" not in low_raw and "latest_year" not in low_raw:
            return None
        if "sum(" not in low_raw or "max(" not in low_raw:
            return None
        if "join (" not in low_raw and "join(" not in low_raw:
            return None

        def _safe_alias(a: Optional[str], default_name: str) -> str:
            if not a:
                return default_name
            x = a.strip()
            if (x.startswith("`") and x.endswith("`")) or (x.startswith("'") and x.endswith("'")) or (x.startswith('"') and x.endswith('"')):
                x = x[1:-1]
            x = re.sub(r"\s+", "_", x)
            x = re.sub(r"[^A-Za-z0-9_]", "", x)
            if not x or not re.match(r"[A-Za-z_]", x[0]):
                return default_name
            return x

        def _extract_table_alias_map(sql_text: str) -> Dict[str, str]:
            alias_map: Dict[str, str] = {}
            for m in re.finditer(
                r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?""",
                sql_text,
            ):
                table_expr = (m.group(1) or "").strip()
                if not table_expr or table_expr.startswith("("):
                    continue
                table_plain = _plain_table_name(table_expr)
                alias = (m.group(2) or "").strip() or table_plain
                if alias.lower() in _SQL_KEYWORDS:
                    alias = table_plain
                alias_map[alias.lower()] = table_plain
                alias_map[table_plain.lower()] = table_plain
            return alias_map

        def _extract_identifier_tokens(expr: str) -> List[str]:
            if not expr:
                return []
            tokens = re.findall(r"`?([A-Za-z_][A-Za-z0-9_]*)`?", expr, flags=re.I)
            out: List[str] = []
            seen = set()
            for tok in tokens:
                tl = tok.lower()
                if tl in _SQL_KEYWORDS:
                    continue
                if tl in {
                    "year", "month", "day", "case", "when", "then", "else",
                    "end", "distinct", "null", "coalesce", "ifnull",
                }:
                    continue
                if tl in seen:
                    continue
                seen.add(tl)
                out.append(tok)
            return out

        def _date_alias_preference(alias_name: Optional[str], col_name: str) -> int:
            alias_lower = str(alias_name or "").strip().lower()
            col_lower = str(col_name or "").strip().lower()
            score = 0
            if alias_lower:
                if "date" in alias_lower or "time" in alias_lower:
                    score += 3
                if "year" in alias_lower and "date" not in alias_lower and "time" not in alias_lower:
                    score -= 3
            if "date" in col_lower or "time" in col_lower:
                score += 1
            return score

        m_join_sub = re.search(r"\bJOIN\s*\(\s*SELECT\b", raw, flags=re.I)
        if not m_join_sub:
            return None

        open_idx = raw.find("(", m_join_sub.start())
        if open_idx == -1:
            return None

        depth = 0
        close_idx = -1
        in_sq = False
        in_dq = False
        i = open_idx
        while i < len(raw):
            ch = raw[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(raw) and raw[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    close_idx = i
                    break
            i += 1
        if close_idx == -1:
            return None

        before = raw[:m_join_sub.start()].strip()
        after = raw[close_idx + 1:].strip()
        before = re.sub(r"\b(?:INNER|LEFT|RIGHT|FULL|CROSS)\s*$", "", before, flags=re.I).strip()

        m_after = re.match(
            r"(?is)^(?:AS\s+)?(?P<sub>[A-Za-z_][A-Za-z0-9_]*)\s+ON\s+(?P<on>.+?)(?P<tail>\s+(?:WHERE|GROUP\s+BY|HAVING|ORDER\s+BY|LIMIT)\b.*)?$",
            after,
        )
        if not m_after:
            return None

        sub_alias = m_after.group("sub").strip()
        on_clause = (m_after.group("on") or "").strip()

        m_before = re.match(
            r"(?is)^SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<t>`?[A-Za-z_][A-Za-z0-9_]*`?)(?:\s+(?:AS\s+)?(?P<a>[A-Za-z_][A-Za-z0-9_]*))?\s*$",
            before,
        )
        if not m_before:
            return None

        outer_select = m_before.group("select").strip()
        entity_table = m_before.group("t").strip()
        entity_table_plain = _plain_table_name(entity_table)
        entity_alias = (m_before.group("a") or "").strip()
        if not entity_alias:
            outer_alias_refs = [
                a for a in re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\.", outer_select, flags=re.I)
                if a.lower() != sub_alias.lower()
            ]
            uniq_refs: List[str] = []
            seen_refs = set()
            for alias in outer_alias_refs:
                al = alias.lower()
                if al in seen_refs:
                    continue
                seen_refs.add(al)
                uniq_refs.append(alias)
            entity_alias = uniq_refs[0] if len(uniq_refs) == 1 else entity_table_plain

        eq1 = re.search(
            rf"`?{re.escape(entity_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?{re.escape(sub_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?",
            on_clause,
            flags=re.I,
        )
        eq2 = re.search(
            rf"`?{re.escape(sub_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?{re.escape(entity_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?",
            on_clause,
            flags=re.I,
        )
        entity_key_col = None
        metric_key_col = None
        if eq1:
            entity_key_col = eq1.group(1)
            metric_key_col = eq1.group(2)
        elif eq2:
            metric_key_col = eq2.group(1)
            entity_key_col = eq2.group(2)
        if not entity_key_col or not metric_key_col:
            return None

        max_candidates: List[Tuple[Optional[str], str, Optional[str]]] = []
        for m in re.finditer(
            r"(?is)\bMAX\s*\(\s*(?:YEAR\s*\(\s*)?(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)?\s*\)(?:\s+AS\s+([A-Za-z_][A-Za-z0-9_]*))?",
            raw,
        ):
            alias_hint = (m.group(1) or "").strip() or None
            col_name = (m.group(2) or "").strip()
            if not col_name:
                continue
            max_candidates.append((alias_hint, col_name, m.group(3)))
        if not max_candidates:
            return None

        m_sum = re.search(
            r"(?is)\bSUM\s*\(\s*(.+?)\s*\)(?:\s+AS\s+([A-Za-z_][A-Za-z0-9_]*))?",
            raw,
        )
        if not m_sum:
            return None
        sum_expr = (m_sum.group(1) or "").strip()
        if not sum_expr:
            return None
        sum_out_alias = m_sum.group(2)

        raw_alias_map = _extract_table_alias_map(raw)
        qualified_sum_refs = re.findall(
            r"`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?",
            sum_expr,
            flags=re.I,
        )
        sum_alias_refs: List[str] = []
        sum_cols: List[str] = []
        for alias_ref, col_ref in qualified_sum_refs:
            if alias_ref.lower() == sub_alias.lower():
                continue
            if alias_ref.lower() not in {a.lower() for a in sum_alias_refs}:
                sum_alias_refs.append(alias_ref)
            if col_ref.lower() not in {c.lower() for c in sum_cols}:
                sum_cols.append(col_ref)
        if len(sum_alias_refs) > 1:
            return None

        if not sum_cols:
            sum_cols = _extract_identifier_tokens(sum_expr)
        if not sum_cols:
            return None

        metric_table: Optional[str] = None
        alias_hint_tables: Set[str] = set()
        date_alias_hint_tables: Set[str] = set()
        for alias_hint, _col_name, _alias_out in max_candidates:
            if alias_hint and raw_alias_map.get(alias_hint.lower()):
                date_alias_hint_tables.add(raw_alias_map[alias_hint.lower()])
        if len(sum_alias_refs) == 1 and raw_alias_map.get(sum_alias_refs[0].lower()):
            alias_hint_tables.add(raw_alias_map[sum_alias_refs[0].lower()])
        if len(date_alias_hint_tables) > 1 or len(alias_hint_tables) > 1:
            return None
        if date_alias_hint_tables and alias_hint_tables and date_alias_hint_tables != alias_hint_tables:
            return None
        alias_hint_tables.update(date_alias_hint_tables)
        if alias_hint_tables:
            metric_table = next(iter(alias_hint_tables))

        candidate_tables: List[str] = []
        seen_tables = set()
        for table_plain in raw_alias_map.values():
            tl = table_plain.lower()
            if tl == entity_table_plain.lower() or tl in seen_tables:
                continue
            seen_tables.add(tl)
            candidate_tables.append(table_plain)

        date_col = None
        date_out_alias = None
        if metric_table is None:
            scored_candidates: List[Tuple[int, str, str, Optional[str]]] = []
            for table_name in candidate_tables:
                cols = _table_cols(table_name)
                if not cols:
                    continue
                if metric_key_col.lower() not in cols:
                    continue
                if any(col.lower() not in cols for col in sum_cols):
                    continue
                temporal_rows: List[Tuple[str, Optional[str], str]] = []
                hint_cols: List[str] = []
                col_case_by_lower: Dict[str, str] = {}
                for alias_hint, candidate_date_col, candidate_date_alias in max_candidates:
                    if candidate_date_col.lower() not in cols:
                        continue
                    if alias_hint and raw_alias_map.get(alias_hint.lower()) != table_name:
                        continue
                    if not _is_temporal_column(table_name, candidate_date_col):
                        continue
                    c_l = candidate_date_col.lower()
                    if c_l not in col_case_by_lower:
                        col_case_by_lower[c_l] = candidate_date_col
                    hint_cols.append(candidate_date_col)
                    temporal_rows.append((candidate_date_col, candidate_date_alias, c_l))

                if not temporal_rows:
                    continue

                chosen_temporal_l = _choose_preferred_temporal_column(
                    table_name,
                    [row[0] for row in temporal_rows],
                    hint_columns=hint_cols,
                    question=question,
                )
                if not chosen_temporal_l:
                    continue

                chosen_temporal_col = col_case_by_lower.get(chosen_temporal_l, chosen_temporal_l)
                best_alias: Optional[str] = None
                best_alias_score = -10**9
                for cand_col, cand_alias, cand_col_l in temporal_rows:
                    if cand_col_l != chosen_temporal_l:
                        continue
                    a_score = _date_alias_preference(cand_alias, cand_col)
                    if a_score > best_alias_score:
                        best_alias_score = a_score
                        best_alias = cand_alias

                score = 0
                if table_name.lower() in transaction_tables:
                    score += 3
                table_id_col = get_id_column(table_name)
                if table_id_col and table_id_col.lower() == metric_key_col.lower():
                    score += 2
                if len(candidate_tables) == 1:
                    score += 2
                score += len(sum_cols)
                score += _date_alias_preference(best_alias, chosen_temporal_col)
                scored_candidates.append((score, table_name, chosen_temporal_col, best_alias))
            if not scored_candidates:
                return None
            scored_candidates.sort(key=lambda item: item[0], reverse=True)
            if len(scored_candidates) > 1 and scored_candidates[0][0] == scored_candidates[1][0]:
                return None
            metric_table = scored_candidates[0][1]
            date_col = scored_candidates[0][2]
            date_out_alias = scored_candidates[0][3]
        else:
            metric_cols = _table_cols(metric_table)
            temporal_rows: List[Tuple[str, Optional[str], str]] = []
            hint_cols: List[str] = []
            col_case_by_lower: Dict[str, str] = {}
            for alias_hint, candidate_date_col, candidate_date_alias in max_candidates:
                if candidate_date_col.lower() not in metric_cols:
                    continue
                if alias_hint and raw_alias_map.get(alias_hint.lower()) != metric_table:
                    continue
                if not _is_temporal_column(metric_table, candidate_date_col):
                    continue
                c_l = candidate_date_col.lower()
                if c_l not in col_case_by_lower:
                    col_case_by_lower[c_l] = candidate_date_col
                hint_cols.append(candidate_date_col)
                temporal_rows.append((candidate_date_col, candidate_date_alias, c_l))

            if not temporal_rows:
                return None

            chosen_temporal_l = _choose_preferred_temporal_column(
                metric_table,
                [row[0] for row in temporal_rows],
                hint_columns=hint_cols,
                question=question,
            )
            if not chosen_temporal_l:
                return None

            date_col = col_case_by_lower.get(chosen_temporal_l, chosen_temporal_l)
            best_alias: Optional[str] = None
            best_alias_score = -10**9
            for cand_col, cand_alias, cand_col_l in temporal_rows:
                if cand_col_l != chosen_temporal_l:
                    continue
                a_score = _date_alias_preference(cand_alias, cand_col)
                if a_score > best_alias_score:
                    best_alias_score = a_score
                    best_alias = cand_alias
            date_out_alias = best_alias

        metric_table_plain = _plain_table_name(metric_table)
        metric_cols = _table_cols(metric_table_plain)
        if not metric_cols:
            return None
        if date_col.lower() not in metric_cols or metric_key_col.lower() not in metric_cols:
            return None
        if any(col.lower() not in metric_cols for col in sum_cols):
            return None

        outer_items = _split_top_level_commas(outer_select)
        entity_items = []
        for item in outer_items:
            if re.search(rf"\b{re.escape(sub_alias)}\s*\.", item, flags=re.I):
                continue
            entity_items.append(item.strip())
        if not entity_items:
            entity_items = [f"{entity_alias}.{entity_key_col}"]

        def _strip_as(item: str) -> str:
            return re.sub(
                r"""(?is)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
                "",
                item.strip(),
            ).strip()

        group_items = []
        seen_group = set()
        for item in entity_items:
            base = _strip_as(item)
            bl = base.lower()
            if bl in seen_group:
                continue
            seen_group.add(bl)
            group_items.append(base)

        existing_aliases = {entity_alias.lower(), sub_alias.lower(), metric_table_plain.lower()}
        existing_aliases.update(k.lower() for k in raw_alias_map.keys())

        def _pick_alias(base: str) -> str:
            stem = re.sub(r"[^A-Za-z0-9_]", "", base) or "t"
            if not re.match(r"[A-Za-z_]", stem[0]):
                stem = f"t_{stem}"
            cand = stem
            idx = 2
            while cand.lower() in existing_aliases:
                cand = f"{stem}_{idx}"
                idx += 1
            existing_aliases.add(cand.lower())
            return cand

        year_alias = _pick_alias(f"{sub_alias}_latest_years")
        metric_alias = _pick_alias(f"{metric_table_plain}_rows")

        sum_metric_expr = sum_expr
        for alias_ref in sum_alias_refs:
            sum_metric_expr = re.sub(
                rf"\b(?:{re.escape(alias_ref)}|{re.escape(raw_alias_map.get(alias_ref.lower(), alias_ref))})\s*\.",
                f"{metric_alias}.",
                sum_metric_expr,
                flags=re.I,
            )
        if not sum_alias_refs:
            for col_name in sorted(sum_cols, key=len, reverse=True):
                sum_metric_expr = re.sub(
                    rf"(?<!\.)\b{re.escape(col_name)}\b",
                    f"{metric_alias}.{col_name}",
                    sum_metric_expr,
                    flags=re.I,
                )

        date_alias_out = _safe_alias(date_out_alias, f"latest_{date_col}")
        sum_alias_out = _safe_alias(sum_out_alias, "total_amount")

        select_lines = list(entity_items)
        select_lines.append(f"MAX({metric_alias}.{date_col}) AS {date_alias_out}")
        select_lines.append(f"SUM({sum_metric_expr}) AS {sum_alias_out}")
        select_block = ",\n  ".join(select_lines)

        order_by_clause = ""
        m_order = re.search(r"(?is)\bORDER\s+BY\s+(.+?)\s*$", raw)
        if m_order:
            order_body = (m_order.group(1) or "").strip().rstrip(";")
            order_body = re.sub(
                rf"\b{re.escape(sub_alias)}\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?",
                r"\1",
                order_body,
                flags=re.I,
            )
            if order_body:
                order_by_clause = f"\nORDER BY {order_body}"
        elif re.search(r"\b(?:latest|most\s+recent|newest|terbaru|terakhir)\b", question or "", flags=re.I):
            order_by_clause = f"\nORDER BY {date_alias_out} DESC"

        return (
            "SELECT\n"
            f"  {select_block}\n"
            f"FROM {entity_table} {entity_alias}\n"
            "JOIN (\n"
            "  SELECT\n"
            f"    {metric_key_col},\n"
            f"    MAX(YEAR({date_col})) AS latest_year\n"
            f"  FROM {metric_table}\n"
            f"  GROUP BY {metric_key_col}\n"
            f") AS {year_alias}\n"
            f"  ON {year_alias}.{metric_key_col} = {entity_alias}.{entity_key_col}\n"
            f"JOIN {metric_table} AS {metric_alias}\n"
            f"  ON {metric_alias}.{metric_key_col} = {entity_alias}.{entity_key_col}\n"
            f" AND YEAR({metric_alias}.{date_col}) = {year_alias}.latest_year\n"
            f"GROUP BY {', '.join(group_items)}"
            f"{order_by_clause};"
        )

    # If already using latest_year pattern and SQL is parseable, keep as-is.
    low = s.lower()
    has_nested_join_inside_derived_subquery = bool(
        re.search(r"(?is)\bJOIN\s*\(\s*SELECT\b[\s\S]*\bFROM\s+[A-Za-z_][A-Za-z0-9_]*\b\s+JOIN\s*\(", s)
    )
    if has_nested_join_inside_derived_subquery:
        rescued = _fallback_rewrite_latest_year_entity_metric(s)
        if rescued:
            return rescued

    if "latest_year" in low and re.search(r"=\s*[a-z_][a-z0-9_]*\.latest_year\b", low):
        has_nested_join_subquery = bool(
            re.search(r"(?is)\bJOIN\s*\(\s*SELECT\b[\s\S]*\bJOIN\s*\(\s*SELECT\b", s)
        )
        if _parse_select_from_groupby(s) and not has_nested_join_subquery:
            return sql

    m_join_sub = re.search(r"\bJOIN\s*\(\s*SELECT\b", s, flags=re.I)
    if not m_join_sub:
        return sql

    open_idx = s.find("(", m_join_sub.start())
    if open_idx == -1:
        return sql

    # Find matching ')' for JOIN ( ... )
    depth = 0
    close_idx = -1
    in_sq = False
    in_dq = False
    i = open_idx
    while i < len(s):
        ch = s[i]
        if ch == "'" and not in_dq:
            if in_sq and i + 1 < len(s) and s[i + 1] == "'":
                i += 2
                continue
            in_sq = not in_sq
            i += 1
            continue
        if ch == '"' and not in_sq:
            in_dq = not in_dq
            i += 1
            continue
        if in_sq or in_dq:
            i += 1
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth == 0:
                close_idx = i
                break
        i += 1

    if close_idx == -1:
        return sql

    before = s[:m_join_sub.start()].strip()
    inner_sql = s[open_idx + 1:close_idx].strip()
    after = s[close_idx + 1:].strip()

    # before ends with join type token (e.g., "... FROM customers AS cust INNER")
    before = re.sub(r"\b(?:INNER|LEFT|RIGHT|FULL|CROSS)\s*$", "", before, flags=re.I).strip()

    m_after = re.match(
        r"(?is)^(?:AS\s+)?(?P<sub>[A-Za-z_][A-Za-z0-9_]*)\s+ON\s+(?P<on>.+?)(?:\s+WHERE\s+(?P<where>.+))?$",
        after,
    )
    if not m_after:
        return sql

    sub_alias = m_after.group("sub").strip()
    on_clause = (m_after.group("on") or "").strip()

    m_before = re.match(
        r"(?is)^SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<t>`?[A-Za-z_][A-Za-z0-9_]*`?)(?:\s+(?:AS\s+)?(?P<a>[A-Za-z_][A-Za-z0-9_]*))?\s*$",
        before,
    )
    if not m_before:
        return sql

    outer_select = m_before.group("select").strip()
    entity_table = m_before.group("t").strip()
    entity_alias = (m_before.group("a") or "").strip()
    if not entity_alias:
        # Recover dropped base-table alias from SELECT qualifiers.
        outer_alias_refs = [
            a for a in re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)\s*\.", outer_select, flags=re.I)
            if a.lower() != sub_alias.lower()
        ]
        uniq_refs = []
        seen_refs = set()
        for a in outer_alias_refs:
            k = a.lower()
            if k in seen_refs:
                continue
            seen_refs.add(k)
            uniq_refs.append(a)
        if len(uniq_refs) == 1:
            entity_alias = uniq_refs[0]
        else:
            # Fallback deterministic alias from table name.
            entity_alias = entity_table.strip("`")

    inner_parsed = _parse_select_from_groupby(inner_sql)
    if not inner_parsed:
        rescued = _fallback_rewrite_latest_year_entity_metric(s)
        if rescued:
            return rescued
        return sql
    if inner_parsed.get("where"):
        # Conservative: skip if inner query already has filters.
        return sql

    m_inner_from = re.match(
        r"(?is)^(`?[A-Za-z_][A-Za-z0-9_]*`?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?$",
        inner_parsed["from_core"].strip(),
    )
    if not m_inner_from:
        rescued = _fallback_rewrite_latest_year_entity_metric(s)
        if rescued:
            return rescued
        return sql

    metric_table = m_inner_from.group(1).strip()
    metric_table_plain = metric_table.strip("`")
    metric_inner_alias = (m_inner_from.group(2) or metric_table_plain).strip()

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_simple_col(expr: str) -> Optional[tuple]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _safe_alias(a: Optional[str], default_name: str) -> str:
        if not a:
            return default_name
        x = a.strip()
        if (x.startswith("`") and x.endswith("`")) or (x.startswith("'") and x.endswith("'")) or (x.startswith('"') and x.endswith('"')):
            x = x[1:-1]
        x = re.sub(r"\s+", "_", x)
        x = re.sub(r"[^A-Za-z0-9_]", "", x)
        if not x:
            return default_name
        if not re.match(r"[A-Za-z_]", x[0]):
            return default_name
        return x

    inner_select_items = _split_top_level_commas(inner_parsed["select"])
    inner_group_items = _split_top_level_commas(inner_parsed["groupby"])
    if not inner_group_items:
        return sql

    key_col = None
    first_group = _parse_simple_col(inner_group_items[0])
    if first_group:
        key_col = first_group[1]
    if not key_col:
        return sql

    date_col = None
    date_alias = None
    sum_expr = None
    sum_alias = None

    for item in inner_select_items:
        expr, alias = _split_expr_alias(item)
        m_max = re.match(r"(?is)^MAX\s*\(\s*(.+?)\s*\)$", expr)
        if m_max and date_col is None:
            parsed_col = _parse_simple_col(m_max.group(1).strip())
            if parsed_col:
                _qa, c = parsed_col
                if ("date" in c.lower()) or ("time" in c.lower()):
                    date_col = c
                    date_alias = alias
                    continue

        m_sum = re.match(r"(?is)^SUM\s*\(\s*(.+?)\s*\)$", expr)
        if m_sum and sum_expr is None:
            sum_expr = m_sum.group(1).strip()
            sum_alias = alias
            continue

    if not date_col or not sum_expr:
        return sql

    # Safety: derived metric table must actually own the date column.
    metric_cols = _table_cols(metric_table_plain)
    if metric_cols and date_col.lower() not in metric_cols:
        return sql

    # Parse entity/sub key mapping from ON
    eq1 = re.search(
        rf"`?{re.escape(entity_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?{re.escape(sub_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?",
        on_clause,
        flags=re.I,
    )
    eq2 = re.search(
        rf"`?{re.escape(sub_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?{re.escape(entity_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?",
        on_clause,
        flags=re.I,
    )
    entity_key_col = None
    sub_key_col = None
    if eq1:
        entity_key_col = eq1.group(1)
        sub_key_col = eq1.group(2)
    elif eq2:
        sub_key_col = eq2.group(1)
        entity_key_col = eq2.group(2)
    if not entity_key_col:
        return sql
    if sub_key_col and sub_key_col.lower() != key_col.lower():
        # Conservative: inconsistent key naming in derived table projection.
        return sql

    outer_items = _split_top_level_commas(outer_select)
    entity_items = []
    for it in outer_items:
        if re.search(rf"\b{re.escape(sub_alias)}\s*\.", it, flags=re.I):
            continue
        entity_items.append(it.strip())
    if not entity_items:
        entity_items = [f"{entity_alias}.{entity_key_col}"]

    def _strip_as(item: str) -> str:
        return re.sub(
            r"""(?is)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            "",
            item.strip(),
        ).strip()

    group_items = []
    seen = set()
    for it in entity_items:
        base = _strip_as(it)
        k = base.lower()
        if k in seen:
            continue
        seen.add(k)
        group_items.append(base)

    existing_aliases = {entity_alias.lower(), sub_alias.lower(), metric_inner_alias.lower()}

    def _pick_alias(base: str) -> str:
        b = re.sub(r"[^A-Za-z0-9_]", "", base) or "t"
        if not re.match(r"[A-Za-z_]", b[0]):
            b = f"t_{b}"
        cand = b
        n = 2
        while cand.lower() in existing_aliases:
            cand = f"{b}_{n}"
            n += 1
        existing_aliases.add(cand.lower())
        return cand

    year_alias = _pick_alias(f"{sub_alias}_latest_years")
    metric_alias = _pick_alias(f"{metric_table_plain}_rows")

    # Qualify SUM expression against metric alias.
    sum_metric_expr = re.sub(
        rf"\b(?:{re.escape(metric_inner_alias)}|{re.escape(metric_table_plain)})\s*\.",
        f"{metric_alias}.",
        sum_expr,
        flags=re.I,
    ).strip()
    if re.fullmatch(r"`?[A-Za-z_][A-Za-z0-9_]*`?", sum_metric_expr):
        sum_metric_expr = f"{metric_alias}.{sum_metric_expr.strip('`')}"

    date_alias_out = _safe_alias(date_alias, f"latest_{date_col}")
    sum_alias_out = _safe_alias(sum_alias, "total_amount")

    select_lines = []
    for it in entity_items:
        select_lines.append(it)
    select_lines.append(f"MAX({metric_alias}.{date_col}) AS {date_alias_out}")
    select_lines.append(f"SUM({sum_metric_expr}) AS {sum_alias_out}")
    select_block = ",\n  ".join(select_lines)

    fixed = (
        "SELECT\n"
        f"  {select_block}\n"
        f"FROM {entity_table} {entity_alias}\n"
        "JOIN (\n"
        "  SELECT\n"
        f"    {key_col},\n"
        f"    MAX(YEAR({date_col})) AS latest_year\n"
        f"  FROM {metric_table}\n"
        f"  GROUP BY {key_col}\n"
        f") AS {year_alias}\n"
        f"  ON {year_alias}.{key_col} = {entity_alias}.{entity_key_col}\n"
        f"JOIN {metric_table} AS {metric_alias}\n"
        f"  ON {metric_alias}.{key_col} = {entity_alias}.{entity_key_col}\n"
        f" AND YEAR({metric_alias}.{date_col}) = {year_alias}.latest_year\n"
        f"GROUP BY {', '.join(group_items)};"
    )
    return fixed


def _canonicalize_latest_year_same_year_pattern(sql: str, question: str, ctx: str = "") -> str:
    """
    Canonicalize correlated latest-year filters into a derived-table pattern.

    Target shape (example):
      WHERE YEAR(o.orderDate) = (
        SELECT MAX(YEAR(orderDate))
        FROM orders
        WHERE orderNumber IN (
          SELECT orderNumber
          FROM orderdetails
          WHERE productCode = p.productCode
        )
      )

    Canonicalized:
      JOIN (
        SELECT bridge.entity_key AS latest_key, MAX(YEAR(date_table.date_col)) AS latest_year
        FROM bridge_table bridge
        JOIN date_table date_table ON ...
        GROUP BY bridge.entity_key
      ) AS ly ON ly.latest_key = outer.entity_key
      WHERE YEAR(outer.date_col) = ly.latest_year
    """
    if not sql:
        return sql
    if not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    low_sql = sql.lower()
    if "latest_year" in low_sql and re.search(r"=\s*[a-z_][a-z0-9_]*\.latest_year\b", low_sql):
        return sql

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        return sql
    if not parsed.get("where"):
        return sql

    from_core = parsed["from_core"].strip()
    if not from_core:
        return sql

    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    existing_aliases = {a.lower() for a in alias_map.keys() if a}

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if not analyzer and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {t.lower(): {c.lower() for c in cols} for t, cols in allowed.items()}
        except Exception:
            allowed_cols = {}

    def _plain_table_name(table_expr: str) -> str:
        return (table_expr or "").replace("`", "").split(".")[-1].strip()

    def _table_cols(table_name: str) -> Set[str]:
        t = _plain_table_name(table_name).lower()
        if not t:
            return set()
        if analyzer:
            try:
                return {c.lower() for c in analyzer.get_table_columns(t)}
            except Exception:
                return set()
        return set(allowed_cols.get(t, set()))

    def _pick_alias(base: str, used: Set[str]) -> str:
        b = re.sub(r"[^A-Za-z0-9_]", "", base) or "t"
        if not re.match(r"[A-Za-z_]", b[0]):
            b = f"t_{b}"
        cand = b
        i = 2
        while cand.lower() in used:
            cand = f"{b}_{i}"
            i += 1
        used.add(cand.lower())
        return cand

    def _split_qualified_ref(expr: str) -> Optional[tuple]:
        m = re.match(
            r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            (expr or "").strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _parse_year_eq_subquery(cond: str) -> Optional[tuple]:
        c = (cond or "").strip()
        m1 = re.match(
            r"""(?is)^YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*\((SELECT.+)\)\s*$""",
            c,
        )
        if m1:
            return m1.group(1), m1.group(2), m1.group(3).strip()
        m2 = re.match(
            r"""(?is)^\((SELECT.+)\)\s*=\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*$""",
            c,
        )
        if m2:
            return m2.group(2), m2.group(3), m2.group(1).strip()
        return None

    groupby_aliases: Set[str] = set()
    for g in _split_top_level_commas(parsed.get("groupby", "")):
        q = _split_qualified_ref(g)
        if q and q[0]:
            groupby_aliases.add(q[0].lower())

    def _infer_bridge_entity_link(
        bridge_alias: str,
        avoid_aliases: Set[str],
    ) -> Optional[tuple]:
        """
        Infer outer-entity join link from FROM/JOIN ON predicates.
        Returns: (outer_entity_alias, outer_entity_col, bridge_entity_col)
        """
        b = (bridge_alias or "").lower().strip()
        if not b:
            return None

        eq_iter = re.finditer(
            r"`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*"
            r"`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?",
            from_core,
            flags=re.I,
        )

        candidates: List[tuple] = []
        for m in eq_iter:
            a1, c1, a2, c2 = m.group(1), m.group(2), m.group(3), m.group(4)
            a1l, a2l = a1.lower(), a2.lower()
            if a1l == b and a2l in alias_map and a2l not in avoid_aliases:
                candidates.append((a2, c2, c1))
            elif a2l == b and a1l in alias_map and a1l not in avoid_aliases:
                candidates.append((a1, c1, c2))

        if not candidates:
            return None

        # Prefer aliases explicitly present in GROUP BY (typical entity key owner).
        for outer_alias, outer_col, bridge_col in candidates:
            if groupby_aliases and outer_alias.lower() in groupby_aliases:
                return outer_alias, outer_col, bridge_col

        # Fallback: first viable candidate.
        return candidates[0]

    where_body = re.sub(r"^\s*WHERE\s+", "", parsed["where"].strip(), flags=re.I).strip()
    if not where_body or _has_top_level_or(where_body):
        return sql

    conjuncts = _split_top_level_and(where_body)
    if not conjuncts:
        return sql

    target_idx = -1
    parsed_target = None

    for i, cond in enumerate(conjuncts):
        y = _parse_year_eq_subquery(cond)
        if not y:
            continue
        outer_date_alias, outer_date_col, sub1 = y

        m_sub1 = re.match(
            r"""(?is)^\s*SELECT\s+MAX\s*\(\s*YEAR\s*\(\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)\s+FROM\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?\s+WHERE\s+(.+?)\s*$""",
            sub1,
        )
        if not m_sub1:
            continue

        inner_date_qual = (m_sub1.group(1) or "").strip()
        inner_date_col = m_sub1.group(2).strip()
        inner_date_table = m_sub1.group(3).strip()
        inner_date_alias = (m_sub1.group(4) or "").strip() or _plain_table_name(inner_date_table)
        inner_where = (m_sub1.group(5) or "").strip()
        if not inner_where or _has_top_level_or(inner_where):
            continue
        inner_conj = _split_top_level_and(inner_where)
        if len(inner_conj) != 1:
            continue

        inner_pred = inner_conj[0].strip()
        inner_join_col = ""
        bridge_link_col = ""
        bridge_table = ""
        bridge_alias = ""
        outer_entity_alias = None
        outer_entity_col = None
        bridge_entity_col = None

        m_in = re.match(
            r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s+IN\s*\((SELECT.+)\)\s*$""",
            inner_pred,
        )

        if m_in:
            inner_join_qual = (m_in.group(1) or "").strip()
            inner_join_col = m_in.group(2).strip()
            sub2 = (m_in.group(3) or "").strip()
            if inner_join_qual and inner_join_qual.lower() not in {inner_date_alias.lower(), _plain_table_name(inner_date_table).lower()}:
                continue

            m_sub2 = re.match(
                r"""(?is)^\s*SELECT\s+(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s+FROM\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?\s+WHERE\s+(.+?)\s*$""",
                sub2,
            )
            if not m_sub2:
                continue

            bridge_link_qual = (m_sub2.group(1) or "").strip()
            bridge_link_col = m_sub2.group(2).strip()
            bridge_table = m_sub2.group(3).strip()
            bridge_alias = (m_sub2.group(4) or "").strip() or _plain_table_name(bridge_table)
            bridge_where = (m_sub2.group(5) or "").strip()
            if not bridge_where or _has_top_level_or(bridge_where):
                continue
            bridge_conj = _split_top_level_and(bridge_where)
            if len(bridge_conj) != 1:
                continue

            m_eq = re.match(
                r"""(?is)^\s*(.+?)\s*=\s*(.+?)\s*$""",
                bridge_conj[0].strip(),
            )
            if not m_eq:
                continue
            left_ref = _split_qualified_ref(m_eq.group(1))
            right_ref = _split_qualified_ref(m_eq.group(2))
            if not left_ref or not right_ref:
                continue

            lq, lc = left_ref
            rq, rc = right_ref
            bridge_aliases = {bridge_alias.lower(), _plain_table_name(bridge_table).lower()}

            if rq and rq.lower() in alias_map and (not lq or lq.lower() in bridge_aliases):
                outer_entity_alias = rq
                outer_entity_col = rc
                bridge_entity_col = lc
            elif lq and lq.lower() in alias_map and (not rq or rq.lower() in bridge_aliases):
                outer_entity_alias = lq
                outer_entity_col = lc
                bridge_entity_col = rc
            else:
                continue

            if bridge_link_qual and bridge_link_qual.lower() not in bridge_aliases:
                continue
            if inner_date_qual and inner_date_qual.lower() not in {inner_date_alias.lower(), _plain_table_name(inner_date_table).lower()}:
                continue

        else:
            # Also support direct equality correlation:
            #   WHERE YEAR(o.dateCol) = (
            #     SELECT MAX(YEAR(dateCol))
            #     FROM date_table
            #     WHERE joinCol = outer_bridge.joinCol
            #   )
            # This is a common malformed pattern for latest-year-per-entity.
            m_eq_direct = re.match(
                r"""(?is)^\s*(.+?)\s*=\s*(.+?)\s*$""",
                inner_pred,
            )
            if not m_eq_direct:
                continue
            left_ref = _split_qualified_ref(m_eq_direct.group(1))
            right_ref = _split_qualified_ref(m_eq_direct.group(2))
            if not left_ref or not right_ref:
                continue

            lq, lc = left_ref
            rq, rc = right_ref
            inner_date_aliases = {inner_date_alias.lower(), _plain_table_name(inner_date_table).lower()}

            outer_bridge_alias = None
            if lq and lq.lower() in alias_map and lq.lower() != outer_date_alias.lower() and ((not rq) or (rq.lower() in inner_date_aliases)):
                outer_bridge_alias = lq
                bridge_link_col = lc
                inner_join_col = rc
            elif rq and rq.lower() in alias_map and rq.lower() != outer_date_alias.lower() and ((not lq) or (lq.lower() in inner_date_aliases)):
                outer_bridge_alias = rq
                bridge_link_col = rc
                inner_join_col = lc
            else:
                continue

            if not inner_join_col or not bridge_link_col:
                continue

            bridge_alias = outer_bridge_alias
            bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower()) or bridge_alias
            inferred = _infer_bridge_entity_link(
                bridge_alias,
                avoid_aliases={outer_date_alias.lower(), bridge_alias.lower()},
            )
            if not inferred:
                continue
            outer_entity_alias, outer_entity_col, bridge_entity_col = inferred

        parsed_target = {
            "outer_date_alias": outer_date_alias,
            "outer_date_col": outer_date_col,
            "inner_date_table": inner_date_table,
            "inner_date_alias": inner_date_alias,
            "inner_date_col": inner_date_col,
            "inner_join_col": inner_join_col,
            "bridge_table": bridge_table,
            "bridge_alias": bridge_alias,
            "bridge_link_col": bridge_link_col,
            "bridge_entity_col": bridge_entity_col,
            "outer_entity_alias": outer_entity_alias,
            "outer_entity_col": outer_entity_col,
        }
        target_idx = i
        break

    if target_idx < 0 or not parsed_target:
        return sql

    outer_date_alias = parsed_target["outer_date_alias"]
    outer_date_col = parsed_target["outer_date_col"]
    inner_date_table = parsed_target["inner_date_table"]
    inner_date_col = parsed_target["inner_date_col"]
    inner_join_col = parsed_target["inner_join_col"]
    bridge_table = parsed_target["bridge_table"]
    bridge_link_col = parsed_target["bridge_link_col"]
    bridge_entity_col = parsed_target["bridge_entity_col"]
    outer_entity_alias = parsed_target["outer_entity_alias"]
    outer_entity_col = parsed_target["outer_entity_col"]

    if outer_date_alias.lower() not in alias_map:
        return sql
    if outer_entity_alias.lower() not in alias_map:
        return sql

    outer_date_table = alias_map.get(outer_date_alias) or alias_map.get(outer_date_alias.lower()) or outer_date_alias
    outer_entity_table = alias_map.get(outer_entity_alias) or alias_map.get(outer_entity_alias.lower()) or outer_entity_alias
    outer_date_cols = _table_cols(outer_date_table)
    outer_entity_cols = _table_cols(outer_entity_table)
    inner_date_cols = _table_cols(inner_date_table)
    bridge_cols = _table_cols(bridge_table)

    if outer_date_cols and outer_date_col.lower() not in outer_date_cols:
        return sql
    if outer_entity_cols and outer_entity_col.lower() not in outer_entity_cols:
        return sql
    if inner_date_cols and (
        inner_date_col.lower() not in inner_date_cols
        or inner_join_col.lower() not in inner_date_cols
    ):
        return sql
    if bridge_cols and (
        bridge_link_col.lower() not in bridge_cols
        or bridge_entity_col.lower() not in bridge_cols
    ):
        return sql

    used = set(existing_aliases)
    ly_alias = _pick_alias("latest_years", used)
    src_alias = "ly_src"
    dt_alias = "ly_dt"

    ly_join = (
        "JOIN (\n"
        "  SELECT\n"
        f"    {src_alias}.{bridge_entity_col} AS latest_key,\n"
        f"    MAX(YEAR({dt_alias}.{inner_date_col})) AS latest_year\n"
        f"  FROM {bridge_table} AS {src_alias}\n"
        f"  JOIN {inner_date_table} AS {dt_alias}\n"
        f"    ON {dt_alias}.{inner_join_col} = {src_alias}.{bridge_link_col}\n"
        f"  GROUP BY {src_alias}.{bridge_entity_col}\n"
        f") AS {ly_alias}\n"
        f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}"
    )

    from_with_ly = f"{from_core}\n{ly_join}"
    year_cond = f"YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year"

    keep_conj = [c.strip() for idx, c in enumerate(conjuncts) if idx != target_idx and c.strip()]
    where_final = " AND ".join(keep_conj + [year_cond])

    tail_clause = f"\n{parsed['tail'].strip()}" if parsed["tail"].strip() else ""
    fixed = (
        f"SELECT {parsed['select'].strip()}\n"
        f"FROM {from_with_ly}\n"
        f"WHERE {where_final}\n"
        f"GROUP BY {parsed['groupby'].strip()}"
        f"{tail_clause};"
    )
    return fixed


def _rewrite_bridge_subquery_latest_year_tuple_filter(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair malformed latest-year tuple filters where the subquery reads from a
    bridge/fact table but the date column actually lives on a joined temporal
    table in the outer query.

    Generic shape:
      WHERE (YEAR(t.date_col), e.entity_key) IN (
        SELECT YEAR(MAX(date_col)), entity_key
        FROM bridge_table
        GROUP BY entity_key
      )

    Rewrites to a derived latest-year-per-entity join built from the observed
    FK path between entity -> bridge -> temporal table. No schema names are
    hardcoded; all aliases/keys come from the SQL and schema metadata.
    """
    if not sql or not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    s0 = (sql or "").strip().rstrip(";").strip()
    if not s0 or " in (select" not in s0.lower() or "year(" not in s0.lower():
        return sql
    if re.search(r"\b(?:from|join)\s*\(", s0, flags=re.I):
        return sql

    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    group_pos = _find_top_level_clause(s0, "group by", max(0, from_pos + len("from")))
    if sel_pos != 0 or from_pos < 0 or group_pos < 0:
        return sql

    having_pos = _find_top_level_clause(s0, "having", group_pos + len("group by"))
    order_pos = _find_top_level_clause(s0, "order by", group_pos + len("group by"))
    limit_pos = _find_top_level_clause(s0, "limit", group_pos + len("group by"))
    tail_positions = [p for p in (having_pos, order_pos, limit_pos) if p >= 0]
    group_end = min(tail_positions) if tail_positions else len(s0)

    select_part = s0[sel_pos + len("select"):from_pos].strip()
    from_where_part = s0[from_pos + len("from"):group_pos].strip()
    group_part = s0[group_pos + len("group by"):group_end].strip()
    tail_part = s0[group_end:].strip() if group_end < len(s0) else ""
    if not select_part or not from_where_part or not group_part:
        return sql

    where_pos = _find_top_level_clause(from_where_part, "where")
    if where_pos < 0:
        return sql
    from_core = from_where_part[:where_pos].strip()
    where_body = from_where_part[where_pos + len("where"):].strip()
    if not from_core or not where_body or _has_top_level_or(where_body):
        return sql

    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if len(alias_map) < 3:
        return sql

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {str(t).lower(): {str(c).lower() for c in cols} for t, cols in allowed.items()}
        except Exception:
            allowed_cols = {}

    def _plain_table(table_expr: str) -> str:
        return (table_expr or "").replace("`", "").split(".")[-1].strip()

    def _table_cols(table_expr: str) -> Set[str]:
        table_name = _plain_table(table_expr)
        if not table_name:
            return set()
        if analyzer is not None:
            try:
                return {str(c).lower() for c in analyzer.get_table_columns(table_name)}
            except Exception:
                pass
        return set(allowed_cols.get(table_name.lower(), set()))

    def _split_expr_alias(item: str) -> Tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m:
            return (item or "").strip(), None
        return (m.group(1) or "").strip(), (m.group(2) or "").strip().strip("`'\"")

    def _pick_alias(base: str, used: Set[str]) -> str:
        b = re.sub(r"[^A-Za-z0-9_]", "", base or "") or "t"
        if not re.match(r"[A-Za-z_]", b[0]):
            b = f"t_{b}"
        cand = b
        idx = 2
        while cand.lower() in used:
            cand = f"{b}_{idx}"
            idx += 1
        used.add(cand.lower())
        return cand

    eq_pairs = list(
        re.finditer(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            from_core,
            flags=re.I,
        )
    )
    if not eq_pairs:
        return sql

    def _replace_year_ref(text: str, date_alias: str, date_col: str, replacement: str) -> str:
        return re.sub(
            rf"(?is)YEAR\s*\(\s*`?{re.escape(date_alias)}`?\s*\.\s*`?{re.escape(date_col)}`?\s*\)",
            replacement,
            text or "",
        )

    def _year_aliases_for(date_alias: str, date_col: str) -> Set[str]:
        aliases: Set[str] = set()
        for item in _split_top_level_commas(select_part):
            expr, alias = _split_expr_alias(item)
            if not alias:
                continue
            if _replace_year_ref(expr, date_alias, date_col, "__YEAR__") != expr:
                aliases.add(alias.lower())
        return aliases

    conjuncts = _split_top_level_and(where_body)
    if not conjuncts:
        return sql

    used_aliases = {str(a).lower() for a in alias_map.keys()}
    used_aliases.update(_plain_table(t).lower() for t in alias_map.values())

    for cond_idx, cond in enumerate(conjuncts):
        m = re.match(
            r"""(?isx)^\s*
                \(\s*YEAR\s*\(\s*`?(?P<date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                \s*,\s*`?(?P<entity_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<entity_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                \s+IN\s*\(\s*SELECT\s+
                (?:
                    MAX\s*\(\s*YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                  |
                    YEAR\s*\(\s*MAX\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                )
                \s*,\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_key_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s+FROM\s+`?(?P<sub_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?!GROUP\b|WHERE\b|ORDER\b|HAVING\b|LIMIT\b)`?[A-Za-z_][A-Za-z0-9_]*`?)?
                \s+GROUP\s+BY\s+(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<group_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s*\)\s*$""",
            cond.strip(),
        )
        if not m:
            continue

        date_alias = m.group("date_alias")
        date_col = m.group("date_col")
        entity_alias = m.group("entity_alias")
        entity_col = m.group("entity_col")
        sub_date_col = (m.group("sub_date_col_1") or m.group("sub_date_col_2") or "").strip()
        sub_key_col = (m.group("sub_key_col") or "").strip()
        group_col = (m.group("group_col") or "").strip()
        sub_table = (m.group("sub_table") or "").strip()
        if not all([date_alias, date_col, entity_alias, entity_col, sub_date_col, sub_key_col, group_col, sub_table]):
            continue
        if sub_key_col.lower() != entity_col.lower() or group_col.lower() != entity_col.lower():
            continue

        date_table = alias_map.get(date_alias) or alias_map.get(date_alias.lower())
        entity_table = alias_map.get(entity_alias) or alias_map.get(entity_alias.lower())
        if not date_table or not entity_table:
            continue

        date_cols = _table_cols(date_table)
        entity_cols = _table_cols(entity_table)
        if date_cols and date_col.lower() not in date_cols:
            continue
        if entity_cols and entity_col.lower() not in entity_cols:
            continue

        bridge_candidates: List[Tuple[int, str, str, str, str]] = []
        for m_date in eq_pairs:
            a1, c1, a2, c2 = m_date.group(1), m_date.group(2), m_date.group(3), m_date.group(4)
            a1l, a2l = a1.lower(), a2.lower()
            if a1l == date_alias.lower() and a2l in alias_map:
                bridge_alias, date_join_col, bridge_date_fk = a2, c1, c2
            elif a2l == date_alias.lower() and a1l in alias_map:
                bridge_alias, date_join_col, bridge_date_fk = a1, c2, c1
            else:
                continue
            if bridge_alias.lower() == date_alias.lower():
                continue

            bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower()) or bridge_alias
            bridge_cols = _table_cols(bridge_table)
            if bridge_cols and bridge_date_fk.lower() not in bridge_cols:
                continue

            bridge_entity_col = ""
            for m_entity in eq_pairs:
                b1, d1, b2, d2 = m_entity.group(1), m_entity.group(2), m_entity.group(3), m_entity.group(4)
                b1l, b2l = b1.lower(), b2.lower()
                if b1l == bridge_alias.lower() and b2l == entity_alias.lower() and d2.lower() == entity_col.lower():
                    bridge_entity_col = d1
                    break
                if b2l == bridge_alias.lower() and b1l == entity_alias.lower() and d1.lower() == entity_col.lower():
                    bridge_entity_col = d2
                    break
            if not bridge_entity_col:
                continue
            if bridge_cols and bridge_entity_col.lower() not in bridge_cols:
                continue

            sub_norm = _plain_table(sub_table).lower()
            bridge_norm = _plain_table(bridge_table).lower()
            date_norm = _plain_table(date_table).lower()
            if sub_norm not in {bridge_norm, date_norm}:
                continue

            score = 0
            if sub_norm == bridge_norm:
                score += 4
            if bridge_entity_col.lower() == entity_col.lower():
                score += 2
            bridge_candidates.append((score, bridge_alias, bridge_table, date_join_col, bridge_date_fk))

        if len(bridge_candidates) != 1:
            bridge_candidates.sort(key=lambda item: item[0], reverse=True)
            if not bridge_candidates or (len(bridge_candidates) > 1 and bridge_candidates[0][0] == bridge_candidates[1][0]):
                continue

        _score, bridge_alias, bridge_table, date_join_col, bridge_date_fk = bridge_candidates[0]
        bridge_entity_col = ""
        for m_entity in eq_pairs:
            b1, d1, b2, d2 = m_entity.group(1), m_entity.group(2), m_entity.group(3), m_entity.group(4)
            b1l, b2l = b1.lower(), b2.lower()
            if b1l == bridge_alias.lower() and b2l == entity_alias.lower() and d2.lower() == entity_col.lower():
                bridge_entity_col = d1
                break
            if b2l == bridge_alias.lower() and b1l == entity_alias.lower() and d1.lower() == entity_col.lower():
                bridge_entity_col = d2
                break
        if not bridge_entity_col:
            continue

        ly_alias = _pick_alias("latest_years", used_aliases)
        src_alias = _pick_alias("ly_src", used_aliases)
        dt_alias = _pick_alias("ly_dt", used_aliases)

        year_aliases = _year_aliases_for(date_alias, date_col)
        rebuilt_select = _replace_year_ref(select_part, date_alias, date_col, f"{ly_alias}.latest_year")
        rebuilt_group_items: List[str] = []
        seen_group: Set[str] = set()
        for item in _split_top_level_commas(group_part):
            item_clean = item.strip()
            if item_clean.lower() in year_aliases:
                item_clean = f"{ly_alias}.latest_year"
            else:
                item_clean = _replace_year_ref(item_clean, date_alias, date_col, f"{ly_alias}.latest_year").strip()
            if not item_clean:
                continue
            item_key = re.sub(r"\s+", " ", item_clean).lower()
            if item_key in seen_group:
                continue
            seen_group.add(item_key)
            rebuilt_group_items.append(item_clean)
        if not rebuilt_group_items:
            continue

        remaining = [c.strip() for i, c in enumerate(conjuncts) if i != cond_idx and c.strip()]
        remaining.append(f"YEAR({date_alias}.{date_col}) = {ly_alias}.latest_year")

        ly_join = (
            "JOIN (\n"
            "  SELECT\n"
            f"    {src_alias}.{bridge_entity_col} AS latest_key,\n"
            f"    MAX(YEAR({dt_alias}.{date_col})) AS latest_year\n"
            f"  FROM {bridge_table} AS {src_alias}\n"
            f"  JOIN {date_table} AS {dt_alias}\n"
            f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_date_fk}\n"
            f"  GROUP BY {src_alias}.{bridge_entity_col}\n"
            f") AS {ly_alias}\n"
            f"  ON {ly_alias}.latest_key = {entity_alias}.{entity_col}"
        )

        tail_clause = f"\n{tail_part}" if tail_part else ""
        return (
            f"SELECT {rebuilt_select}\n"
            f"FROM {from_core}\n"
            f"{ly_join}\n"
            f"WHERE {' AND '.join(remaining)}\n"
            f"GROUP BY {', '.join(rebuilt_group_items)}"
            f"{tail_clause};"
        )

    return sql


def _rewrite_latest_year_tuple_in_filter(sql: str, question: str, ctx: str = "") -> str:
    """
    Rewrite tuple-IN latest-year filters into a stable derived latest-year join.

    Example near-miss:
      WHERE (YEAR(o.orderDate), p.productCode) IN (
        SELECT YEAR(MAX(o2.orderDate)), p2.productCode
        FROM ...
        GROUP BY p2.productCode
      )
    """
    if not sql:
        return sql
    if not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    # Ultra-early fast path for malformed tuple-IN latest-year filters:
    #   WHERE (YEAR(o.date_col), e.entity_key) IN (
    #     SELECT MAX(YEAR(date_col)), entity_key
    #     FROM temporal_table
    #     GROUP BY entity_key
    #   )
    # when the grouped entity key actually lives on a bridge table between the
    # outer temporal alias and the requested entity alias.
    low_sql = sql.lower()
    if " in (select max(year(" in low_sql or " in (select year(max(" in low_sql:
        s0 = sql.strip().rstrip(";").strip()

        def _fast_find_kw(text: str, keyword: str, start: int = 0) -> int:
            w = keyword.lower()
            n = len(w)
            depth = 0
            in_sq = in_dq = in_bt = False
            i = 0
            while i < len(text):
                ch = text[i]
                if ch == "'" and not in_dq and not in_bt:
                    in_sq = not in_sq
                    i += 1
                    continue
                if ch == '"' and not in_sq and not in_bt:
                    in_dq = not in_dq
                    i += 1
                    continue
                if ch == "`" and not in_sq and not in_dq:
                    in_bt = not in_bt
                    i += 1
                    continue
                if in_sq or in_dq or in_bt:
                    i += 1
                    continue
                if ch == "(":
                    depth += 1
                    i += 1
                    continue
                if ch == ")":
                    depth = max(0, depth - 1)
                    i += 1
                    continue
                if depth == 0 and i >= start and i + n <= len(text):
                    left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
                    right_ok = (i + n) >= len(text) or not (text[i + n].isalnum() or text[i + n] == "_")
                    if left_ok and right_ok and text[i:i + n].lower() == w:
                        return i
                i += 1
            return -1

        sel_pos = _fast_find_kw(s0, "select", 0)
        from_pos = _fast_find_kw(s0, "from", max(0, sel_pos + len("select")))
        group_pos = _fast_find_kw(s0, "group by", max(0, from_pos + len("from")))
        order_pos = _fast_find_kw(s0, "order by", max(0, group_pos + len("group by")))
        if sel_pos >= 0 and from_pos >= 0 and group_pos >= 0:
            select_part = s0[sel_pos + len("select"):from_pos].strip()
            from_part = s0[from_pos + len("from"):group_pos].strip()
            group_part = s0[group_pos + len("group by"):order_pos if order_pos >= 0 else len(s0)].strip()
            tail_part = s0[order_pos:].strip() if order_pos >= 0 else ""
            where_pos = _fast_find_kw(from_part, "where", 0)
            if where_pos >= 0:
                from_core_early = from_part[:where_pos].strip()
                where_body_early = re.sub(r"^\s*where\s+", "", from_part[where_pos:].strip(), flags=re.I).strip()
                tuple_pat = re.compile(
                    r"""(?is)^\s*
                        \(\s*YEAR\s*\(\s*`?(?P<outer_date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                        \s*,\s*`?(?P<outer_entity_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_entity_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                        \s+IN\s*\(\s*SELECT\s+(?:MAX\s*\(\s*YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)|YEAR\s*\(\s*MAX\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\))
                        \s*,\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_key_col>[A-Za-z_][A-Za-z0-9_]*)`?
                        \s+FROM\s+`?(?P<sub_date_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?[A-Za-z_][A-Za-z0-9_]*`?)?
                        \s+GROUP\s+BY\s+(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<group_col>[A-Za-z_][A-Za-z0-9_]*)`?
                        \s*\)\s*$""",
                )
                m_early = tuple_pat.match(where_body_early)
                if m_early:
                    outer_date_alias = m_early.group("outer_date_alias")
                    outer_date_col = m_early.group("outer_date_col")
                    outer_entity_alias = m_early.group("outer_entity_alias")
                    outer_entity_col = m_early.group("outer_entity_col")
                    sub_key_col = (m_early.group("sub_key_col") or "").strip()
                    group_col = (m_early.group("group_col") or "").strip()
                    if sub_key_col.lower() == outer_entity_col.lower() and group_col.lower() == outer_entity_col.lower():
                        alias_map_early = _parse_from_join_aliases(f"SELECT 1 FROM {from_core_early}")
                        eq_pairs_early = list(
                            re.finditer(
                                r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
                                from_core_early,
                                flags=re.I,
                            )
                        )
                        bridge_matches_early: List[Tuple[str, str, str]] = []
                        for m_eq_date in eq_pairs_early:
                            a1, c1, a2, c2 = m_eq_date.group(1), m_eq_date.group(2), m_eq_date.group(3), m_eq_date.group(4)
                            a1l, a2l = a1.lower(), a2.lower()
                            if a1l == outer_date_alias.lower() and a2l in alias_map_early and a2l != outer_date_alias.lower():
                                bridge_alias, date_join_col, bridge_fk_col = a2, c1, c2
                            elif a2l == outer_date_alias.lower() and a1l in alias_map_early and a1l != outer_date_alias.lower():
                                bridge_alias, date_join_col, bridge_fk_col = a1, c2, c1
                            else:
                                continue
                            entity_join_ok = False
                            for m_eq_entity in eq_pairs_early:
                                b1, d1, b2, d2 = m_eq_entity.group(1), m_eq_entity.group(2), m_eq_entity.group(3), m_eq_entity.group(4)
                                b1l, b2l = b1.lower(), b2.lower()
                                if b1l == bridge_alias.lower() and b2l == outer_entity_alias.lower() and d1.lower() == outer_entity_col.lower() and d2.lower() == outer_entity_col.lower():
                                    entity_join_ok = True
                                    break
                                if b2l == bridge_alias.lower() and b1l == outer_entity_alias.lower() and d2.lower() == outer_entity_col.lower() and d1.lower() == outer_entity_col.lower():
                                    entity_join_ok = True
                                    break
                            if entity_join_ok:
                                bridge_matches_early.append((bridge_alias, date_join_col, bridge_fk_col))
                        if len(bridge_matches_early) == 1:
                            bridge_alias, date_join_col, bridge_fk_col = bridge_matches_early[0]
                            bridge_table = alias_map_early.get(bridge_alias) or bridge_alias
                            date_table = alias_map_early.get(outer_date_alias) or outer_date_alias
                            ly_alias = "latest_years"
                            src_alias = "ly_src"
                            dt_alias = "ly_dt"
                            select_part = re.sub(
                                rf"(?is)YEAR\s*\(\s*`?{re.escape(outer_date_alias)}`?\s*\.\s*`?{re.escape(outer_date_col)}`?\s*\)",
                                f"{ly_alias}.latest_year",
                                select_part,
                            )
                            group_items = []
                            seen_group = set()
                            for item in _split_top_level_commas(group_part):
                                replaced = re.sub(
                                    rf"(?is)YEAR\s*\(\s*`?{re.escape(outer_date_alias)}`?\s*\.\s*`?{re.escape(outer_date_col)}`?\s*\)",
                                    f"{ly_alias}.latest_year",
                                    item.strip(),
                                ).strip()
                                if not replaced or replaced.lower() in seen_group:
                                    continue
                                seen_group.add(replaced.lower())
                                group_items.append(replaced)
                            if group_items:
                                tail_clause = f"\n{tail_part}" if tail_part else ""
                                return (
                                    f"SELECT {select_part}\n"
                                    f"FROM {from_core_early}\n"
                                    "JOIN (\n"
                                    "  SELECT\n"
                                    f"    {src_alias}.{outer_entity_col} AS latest_key,\n"
                                    f"    MAX(YEAR({dt_alias}.{outer_date_col})) AS latest_year\n"
                                    f"  FROM {bridge_table} AS {src_alias}\n"
                                    f"  JOIN {date_table} AS {dt_alias}\n"
                                    f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_fk_col}\n"
                                    f"  GROUP BY {src_alias}.{outer_entity_col}\n"
                                    f") AS {ly_alias}\n"
                                    f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}\n"
                                    f"WHERE YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year\n"
                                    f"GROUP BY {', '.join(group_items)}"
                                    f"{tail_clause};"
                                )

    def _find_top_level_kw(text: str, keyword: str, start: int = 0) -> int:
        def _is_word_boundary_local(src: str, pos: int, length: int) -> bool:
            left_ok = pos == 0 or not (src[pos - 1].isalnum() or src[pos - 1] == "_")
            right_ok = (pos + length) >= len(src) or not (
                src[pos + length].isalnum() or src[pos + length] == "_"
            )
            return left_ok and right_ok

        w = keyword.lower()
        n = len(w)
        depth = 0
        in_sq = False
        in_dq = False
        in_bt = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i >= start and i + n <= len(text):
                if text[i:i + n].lower() == w and _is_word_boundary_local(text, i, n):
                    return i
            i += 1
        return -1

    def _parse_flat_select_with_nested_where_groups(raw_sql: str) -> Optional[dict]:
        s = (raw_sql or "").strip().rstrip(";").strip()
        if not s:
            return None
        if re.match(r"^\s*with\b", s, flags=re.I):
            return None
        # Keep this rewrite scoped to flat outer queries.
        if re.search(r"\b(?:from|join)\s*\(", s, flags=re.I):
            return None

        sel_pos = _find_top_level_kw(s, "select", 0)
        from_pos = _find_top_level_kw(s, "from", max(0, sel_pos + len("select")))
        group_pos = _find_top_level_kw(s, "group by", max(0, from_pos + len("from")))
        if sel_pos < 0 or from_pos < 0 or group_pos < 0:
            return None

        having_pos = _find_top_level_kw(s, "having", group_pos + len("group by"))
        order_pos = _find_top_level_kw(s, "order by", group_pos + len("group by"))
        limit_pos = _find_top_level_kw(s, "limit", group_pos + len("group by"))
        tail_pos_candidates = [p for p in [having_pos, order_pos, limit_pos] if p >= 0]
        group_end = min(tail_pos_candidates) if tail_pos_candidates else len(s)

        select_part = s[sel_pos + len("select"):from_pos].strip()
        from_part = s[from_pos + len("from"):group_pos].strip()
        groupby_part = s[group_pos + len("group by"):group_end].strip()
        tail_part = s[group_end:].strip() if group_end < len(s) else ""
        if not select_part or not from_part or not groupby_part:
            return None

        where_pos = _find_top_level_kw(from_part, "where", 0)
        if where_pos >= 0:
            from_core = from_part[:where_pos].strip()
            where_clause = from_part[where_pos:].strip()
        else:
            from_core = from_part
            where_clause = ""

        return {
            "select": select_part,
            "from_core": from_core,
            "where": where_clause,
            "groupby": groupby_part,
            "tail": tail_part,
        }

    parsed = _parse_flat_select_with_nested_where_groups(sql)
    if not parsed or not parsed.get("where"):
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if not from_core:
        return sql

    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if not alias_map:
        return sql

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if not analyzer and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {t.lower(): {c.lower() for c in cols} for t, cols in allowed.items()}
        except Exception:
            allowed_cols = {}

    def _plain_table_name(table_expr: str) -> str:
        return (table_expr or "").replace("`", "").split(".")[-1].strip()

    def _table_cols(table_name: str) -> Set[str]:
        t = _plain_table_name(table_name).lower()
        if not t:
            return set()
        if analyzer:
            try:
                return {c.lower() for c in analyzer.get_table_columns(t)}
            except Exception:
                return set()
        return set(allowed_cols.get(t, set()))

    def _pick_alias(base: str, used: Set[str]) -> str:
        b = re.sub(r"[^A-Za-z0-9_]", "", base) or "t"
        if not re.match(r"[A-Za-z_]", b[0]):
            b = f"t_{b}"
        cand = b
        idx = 2
        while cand.lower() in used:
            cand = f"{b}_{idx}"
            idx += 1
        used.add(cand.lower())
        return cand

    def _split_expr_alias(item: str) -> tuple[str, Optional[str]]:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            (item or "").strip(),
        )
        if not m:
            return (item or "").strip(), None
        return (m.group(1) or "").strip(), (m.group(2) or "").strip().strip("`'\"")

    def _parse_simple_col(expr: str) -> Optional[tuple]:
        m = re.match(
            r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            (expr or "").strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _replace_year_projection(text: str, ly_alias: str, date_alias: str, date_col: str) -> str:
        out = re.sub(
            rf"(?is)YEAR\s*\(\s*`?{re.escape(date_alias)}`?\s*\.\s*`?{re.escape(date_col)}`?\s*\)",
            f"{ly_alias}.latest_year",
            text,
        )
        return out

    def _ensure_requested_entity_name(
        select_text: str,
        group_items_in: List[str],
        entity_alias: str,
        entity_table: str,
    ) -> Tuple[str, List[str]]:
        if not re.search(r"\bname\b", question or "", flags=re.I):
            return select_text, list(group_items_in)

        try:
            name_col = str(get_name_column(entity_table) or "").strip()
        except Exception:
            name_col = ""
        if not name_col:
            return select_text, list(group_items_in)

        select_items = _split_top_level_commas(select_text or "")
        if any(
            (ref := _parse_simple_col((_split_expr_alias(item)[0] or "").strip()))
            and str(ref[0] or "").lower() == entity_alias.lower()
            and str(ref[1] or "").lower() == name_col.lower()
            for item in select_items
        ):
            return select_text, list(group_items_in)

        updated_select_items = list(select_items)
        insert_idx = -1
        for idx, item in enumerate(select_items):
            expr, _alias = _split_expr_alias(item)
            ref = _parse_simple_col(expr)
            if ref and str(ref[0] or "").lower() == entity_alias.lower():
                insert_idx = idx + 1
        name_expr = f"{entity_alias}.{name_col}"
        if insert_idx >= 0:
            updated_select_items.insert(insert_idx, name_expr)
        else:
            updated_select_items.append(name_expr)

        updated_group_items = list(group_items_in)
        if not any(
            (ref := _parse_simple_col(item))
            and str(ref[0] or "").lower() == entity_alias.lower()
            and str(ref[1] or "").lower() == name_col.lower()
            for item in updated_group_items
        ):
            updated_group_items.append(name_expr)

        return ", ".join(updated_select_items), updated_group_items

    def _extract_requested_order(select_part: str, question_text: str) -> str:
        q = (question_text or "").strip()
        if not q:
            return ""

        def _normalize_words(text: str) -> List[str]:
            raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", (text or "").replace("_", " "))
            tokens = re.findall(r"[A-Za-z0-9]+", raw.lower())
            stop = {
                "the", "a", "an", "of", "in", "on", "for", "to", "by", "with",
                "that", "this", "those", "these", "then", "and", "or", "if",
                "there", "is", "are", "be", "as", "at", "from", "into",
                "results", "result", "rows", "row", "output",
            }
            return [tok for tok in tokens if tok and tok not in stop]

        def _extract_sort_clause(text: str) -> str:
            patterns = [
                r"\b(?:sort(?:ed)?\s+by|arrange\s+by|order\s+by)\b",
                r"\border\s+the\s+(?:result|results|output|rows?)\s+by\b",
                r"\bordered\s+by\b",
            ]
            for pat in patterns:
                m = re.search(pat, text, flags=re.I)
                if not m:
                    continue
                tail = text[m.end():]
                stop = re.search(r"[.;!?]", tail)
                if stop:
                    tail = tail[:stop.start()]
                return tail.strip()
            return ""

        def _split_csv(text: str) -> List[str]:
            parts: List[str] = []
            cur: List[str] = []
            depth = 0
            quote = ""
            for i, ch in enumerate(text):
                if quote:
                    cur.append(ch)
                    if ch == quote and (i == 0 or text[i - 1] != "\\"):
                        quote = ""
                    continue
                if ch in {"'", '"', "`"}:
                    quote = ch
                    cur.append(ch)
                    continue
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth = max(0, depth - 1)
                if ch == "," and depth == 0:
                    part = "".join(cur).strip()
                    if part:
                        parts.append(part)
                    cur = []
                    continue
                cur.append(ch)
            tail = "".join(cur).strip()
            if tail:
                parts.append(tail)
            return parts

        sort_clause = _extract_sort_clause(q)
        if not sort_clause:
            return ""

        candidates = []
        for item in _split_top_level_commas(select_part or ""):
            expr, alias = _split_expr_alias(item)
            order_expr = (alias or "").strip()
            simple_ref = _parse_simple_col(expr)
            label_parts: List[str] = []
            if alias:
                label_parts.append(alias)
            if simple_ref:
                ref_alias, ref_col = simple_ref
                order_expr = order_expr or (f"{ref_alias}.{ref_col}" if ref_alias else ref_col)
                label_parts.append(ref_col)
            else:
                order_expr = order_expr or expr.strip()
                label_parts.append(expr)
            if not order_expr:
                continue
            tokens = _normalize_words(" ".join(label_parts))
            if not tokens:
                continue
            candidates.append(
                {
                    "order_expr": order_expr,
                    "tokens": set(tokens),
                    "is_agg": bool(re.search(r"(?is)\b(?:sum|count|avg|average|min|max)\s*\(", expr)),
                }
            )
        if not candidates:
            return ""

        aggregate_words = _winner_row_metric_terms() | {
            "minimum", "maximum", "min", "max",
        }

        chosen: List[str] = []
        used_exprs: Set[str] = set()
        segments = re.split(r"\bthen\b|\band\b", sort_clause, flags=re.I)
        for seg in segments:
            for part in _split_csv(seg):
                seg_text = part.strip()
                if not seg_text:
                    continue
                seg_tokens = set(_normalize_words(seg_text))
                if not seg_tokens:
                    continue
                direction = ""
                if re.search(r"\b(?:descending|desc|z\s+to\s+a|reverse\s+alphabetical|reversed\s+alphabetical|reverse)\b", seg_text, flags=re.I):
                    direction = "DESC"
                elif re.search(r"\b(?:ascending|asc|alphabetical|alphabetically|a\s+to\s+z)\b", seg_text, flags=re.I):
                    direction = "ASC"
                wants_agg = bool(seg_tokens & aggregate_words)

                best_score = -1
                best_expr = ""
                for cand in candidates:
                    overlap = len(seg_tokens & cand["tokens"])
                    if overlap <= 0:
                        continue
                    score = overlap * 4
                    if wants_agg and cand["is_agg"]:
                        score += 5
                    if "quantity" in seg_tokens and "quantity" in cand["tokens"]:
                        score += 2
                    if "amount" in seg_tokens and "amount" in cand["tokens"]:
                        score += 2
                    if "code" in seg_tokens and "code" in cand["tokens"]:
                        score += 2
                    if "name" in seg_tokens and "name" in cand["tokens"]:
                        score += 2
                    if "year" in seg_tokens and "year" in cand["tokens"] and not wants_agg:
                        score += 1
                    cand_expr = str(cand["order_expr"])
                    if cand_expr.lower() in used_exprs:
                        score -= 2
                    if score > best_score:
                        best_score = score
                        best_expr = cand_expr

                if best_score < 4 or not best_expr:
                    continue

                used_exprs.add(best_expr.lower())
                chosen.append(f"{best_expr} {direction}".strip())

        return ", ".join(chosen)

    def _replace_top_level_order_in_tail(tail_text: str, new_order: str) -> str:
        tail = (tail_text or "").strip()
        if not new_order:
            return tail
        if not tail:
            return f"ORDER BY {new_order}"

        order_pos = _find_top_level_kw(tail, "order by", 0)
        if order_pos < 0:
            return f"{tail}\nORDER BY {new_order}"

        limit_pos = _find_top_level_kw(tail, "limit", order_pos + len("order by"))
        before = tail[:order_pos].strip()
        after = tail[limit_pos:].strip() if limit_pos >= 0 else ""

        parts: List[str] = []
        if before:
            parts.append(before)
        parts.append(f"ORDER BY {new_order}")
        if after:
            parts.append(after)
        return "\n".join(parts)

    where_body = re.sub(r"^\s*WHERE\s+", "", parsed["where"].strip(), flags=re.I).strip()
    if not where_body or _has_top_level_or(where_body):
        return sql

    conjuncts = _split_top_level_and(where_body)
    if not conjuncts:
        return sql

    used_aliases = {a.lower() for a in alias_map.keys() if a}
    used_aliases.update(_plain_table_name(t).lower() for t in alias_map.values())

    eq_pairs = list(
        re.finditer(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            from_core,
            flags=re.I,
        )
    )

    # Direct fallback for bare-key tuple-IN latest-year patterns where the
    # temporal table in the subquery does not own the grouped entity key.
    for idx, cond in enumerate(conjuncts):
        m_direct = re.match(
            r"""(?is)^\s*
                \(\s*YEAR\s*\(\s*`?(?P<outer_date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                \s*,\s*`?(?P<outer_entity_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_entity_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                \s+IN\s*\(\s*SELECT\s+
                (?:
                    MAX\s*\(\s*YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                  |
                    YEAR\s*\(\s*MAX\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                )
                \s*,\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_key_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s+FROM\s+`?(?P<sub_date_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?[A-Za-z_][A-Za-z0-9_]*`?)?
                \s+GROUP\s+BY\s+(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<group_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s*\)\s*$""",
            cond.strip(),
        )
        if not m_direct:
            continue

        outer_date_alias = m_direct.group("outer_date_alias")
        outer_date_col = m_direct.group("outer_date_col")
        outer_entity_alias = m_direct.group("outer_entity_alias")
        outer_entity_col = m_direct.group("outer_entity_col")
        sub_date_col = (m_direct.group("sub_date_col_1") or m_direct.group("sub_date_col_2") or "").strip()
        sub_key_col = (m_direct.group("sub_key_col") or "").strip()
        group_col = (m_direct.group("group_col") or "").strip()
        sub_date_table = (m_direct.group("sub_date_table") or "").strip()
        if not sub_date_col or not sub_key_col or not group_col or not sub_date_table:
            continue
        if sub_key_col.lower() != outer_entity_col.lower() or group_col.lower() != outer_entity_col.lower():
            continue

        outer_date_table = alias_map.get(outer_date_alias) or alias_map.get(outer_date_alias.lower())
        outer_entity_table = alias_map.get(outer_entity_alias) or alias_map.get(outer_entity_alias.lower())
        if not outer_date_table or not outer_entity_table:
            continue
        sub_date_table_norm = _plain_table_name(sub_date_table).lower()
        outer_date_table_norm = _plain_table_name(outer_date_table).lower()

        outer_date_cols = _table_cols(outer_date_table)
        outer_entity_cols = _table_cols(outer_entity_table)
        if outer_date_cols and outer_date_col.lower() not in outer_date_cols:
            continue
        if outer_entity_cols and outer_entity_col.lower() not in outer_entity_cols:
            continue
        if outer_date_cols and outer_entity_col.lower() in outer_date_cols:
            continue

        direct_candidates: List[Tuple[str, str, str]] = []
        for m_eq_date in eq_pairs:
            a1, c1, a2, c2 = m_eq_date.group(1), m_eq_date.group(2), m_eq_date.group(3), m_eq_date.group(4)
            a1l, a2l = a1.lower(), a2.lower()
            if a1l == outer_date_alias.lower() and a2l in alias_map and a2l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_link_col = a2, c1, c2
            elif a2l == outer_date_alias.lower() and a1l in alias_map and a1l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_link_col = a1, c2, c1
            else:
                continue

            bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower()) or bridge_alias
            bridge_cols = _table_cols(bridge_table)
            if bridge_cols and bridge_link_col.lower() not in bridge_cols:
                continue
            if bridge_cols and outer_entity_col.lower() not in bridge_cols:
                continue

            entity_connected = False
            for m_eq_entity in eq_pairs:
                b1, d1, b2, d2 = m_eq_entity.group(1), m_eq_entity.group(2), m_eq_entity.group(3), m_eq_entity.group(4)
                b1l, b2l = b1.lower(), b2.lower()
                if b1l == bridge_alias.lower() and b2l == outer_entity_alias.lower() and d1.lower() == outer_entity_col.lower() and d2.lower() == outer_entity_col.lower():
                    entity_connected = True
                    break
                if b2l == bridge_alias.lower() and b1l == outer_entity_alias.lower() and d2.lower() == outer_entity_col.lower() and d1.lower() == outer_entity_col.lower():
                    entity_connected = True
                    break
            if not entity_connected:
                continue
            direct_candidates.append((bridge_alias, date_join_col, bridge_link_col))

        if len(direct_candidates) != 1:
            continue

        bridge_alias, date_join_col, bridge_link_col = direct_candidates[0]
        bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower()) or bridge_alias
        bridge_table_norm = _plain_table_name(bridge_table).lower()
        if sub_date_table_norm not in {outer_date_table_norm, bridge_table_norm}:
            continue
        ly_alias = _pick_alias("latest_years", used_aliases)
        src_alias = _pick_alias("ly_src", used_aliases)
        dt_alias = _pick_alias("ly_dt", used_aliases)

        ly_join = (
            "JOIN (\n"
            "  SELECT\n"
            f"    {src_alias}.{outer_entity_col} AS latest_key,\n"
            f"    MAX(YEAR({dt_alias}.{outer_date_col})) AS latest_year\n"
            f"  FROM {bridge_table} AS {src_alias}\n"
            f"  JOIN {outer_date_table} AS {dt_alias}\n"
            f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_link_col}\n"
            f"  GROUP BY {src_alias}.{outer_entity_col}\n"
            f") AS {ly_alias}\n"
            f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}"
        )

        rebuilt_select = _replace_year_projection(parsed["select"].strip(), ly_alias, outer_date_alias, outer_date_col)
        rebuilt_group_items: List[str] = []
        seen_group: Set[str] = set()
        for item in _split_top_level_commas(parsed.get("groupby", "")):
            replaced = _replace_year_projection(item, ly_alias, outer_date_alias, outer_date_col).strip()
            if not replaced:
                continue
            key = replaced.lower()
            if key in seen_group:
                continue
            seen_group.add(key)
            rebuilt_group_items.append(replaced)
        if not rebuilt_group_items:
            continue

        rebuilt_select, rebuilt_group_items = _ensure_requested_entity_name(
            rebuilt_select,
            rebuilt_group_items,
            outer_entity_alias,
            outer_entity_table,
        )
        remaining_conds = [c.strip() for j, c in enumerate(conjuncts) if j != idx and c.strip()]
        remaining_conds.append(f"YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year")

        requested_order = _extract_requested_order(rebuilt_select, question)
        rebuilt_tail = _replace_top_level_order_in_tail(parsed.get("tail", ""), requested_order)
        tail_clause = f"\n{rebuilt_tail}" if rebuilt_tail else ""
        fixed = (
            f"SELECT {rebuilt_select}\n"
            f"FROM {from_core}\n{ly_join}\n"
            f"WHERE {' AND '.join(remaining_conds)}\n"
            f"GROUP BY {', '.join(rebuilt_group_items)}"
            f"{tail_clause};"
        )
        return fixed

    grouped_refs: List[tuple[str, str, int]] = []
    seen_grouped_refs: Set[tuple[str, str]] = set()
    for weight, part in ((4, parsed.get("groupby", "")), (2, parsed.get("select", ""))):
        for item in _split_top_level_commas(part or ""):
            expr, _alias = _split_expr_alias(item)
            ref = _parse_simple_col(expr)
            if not ref or not ref[0]:
                continue
            alias_name, col_name = ref
            alias_key = alias_name.lower()
            ref_key = (alias_key, col_name.lower())
            if alias_key not in alias_map or ref_key in seen_grouped_refs:
                continue
            seen_grouped_refs.add(ref_key)
            grouped_refs.append((alias_name, col_name, weight))

    def _bridge_col_for_target(
        bridge_alias: str,
        target_alias: str,
        target_col: str,
    ) -> Optional[str]:
        b = (bridge_alias or "").lower()
        t = (target_alias or "").lower()
        c = (target_col or "").lower()
        for m_eq in eq_pairs:
            a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
            a1l, a2l = a1.lower(), a2.lower()
            if a1l == b and a2l == t and c2.lower() == c:
                return c1
            if a2l == b and a1l == t and c1.lower() == c:
                return c2
        return None

    def _infer_grouped_entity_target(
        bridge_alias: str,
        bridge_table: str,
        outer_date_alias: str,
        current_outer_alias: str,
        current_outer_col: str,
        bridge_link_col: str,
    ) -> Optional[tuple[str, str, str]]:
        bridge_cols = _table_cols(bridge_table)
        best: Optional[tuple[int, str, str, str]] = None

        for alias_name, col_name, weight in grouped_refs:
            alias_lower = alias_name.lower()
            col_lower = col_name.lower()
            if alias_lower == outer_date_alias.lower():
                continue

            bridge_group_col = ""
            score = weight
            if alias_lower == bridge_alias.lower():
                if bridge_cols and col_lower not in bridge_cols:
                    continue
                bridge_group_col = col_name
                if col_lower != bridge_link_col.lower():
                    score += 3
            else:
                mapped_bridge_col = _bridge_col_for_target(bridge_alias, alias_name, col_name)
                if not mapped_bridge_col:
                    continue
                bridge_group_col = mapped_bridge_col
                score += 2
                if mapped_bridge_col.lower() != bridge_link_col.lower():
                    score += 3

            table_name = alias_map.get(alias_name) or alias_map.get(alias_name.lower()) or alias_name
            try:
                id_col = get_id_column(table_name) or ""
            except Exception:
                id_col = ""
            if id_col and col_lower == id_col.lower():
                score += 2
            if re.search(r"(?:id|code|number)$", col_lower):
                score += 1
            if col_lower in {"name", "title", "status", "city", "country", "state", "territory"}:
                score -= 2
            if alias_lower == current_outer_alias.lower() and col_lower == current_outer_col.lower():
                score -= 1

            if best is None or score > best[0]:
                best = (score, alias_name, col_name, bridge_group_col)

        if not best:
            return None
        return best[1], best[2], best[3]

    # Fast path for malformed tuple-IN latest-year filters where the inner
    # subquery groups only on a bridge-owned entity key while reading from the
    # temporal table alone, e.g.:
    #   WHERE (YEAR(o.orderDate), p.productCode) IN (
    #     SELECT MAX(YEAR(orderDate)), productCode FROM orders GROUP BY productCode
    #   )
    # The temporal table typically does not own `productCode`, so we rebuild the
    # canonical bridge -> temporal latest-year derived join deterministically.
    for idx, cond in enumerate(conjuncts):
        m_fast = re.match(
            r"""(?is)^\s*
                \(\s*YEAR\s*\(\s*`?(?P<outer_date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                \s*,\s*`?(?P<outer_entity_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_entity_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                \s+IN\s*\(\s*
                SELECT\s+
                (?:
                    MAX\s*\(\s*YEAR\s*\(\s*(?:`?(?P<sub_date_alias_1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?(?P<sub_date_col_1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                  |
                    YEAR\s*\(\s*MAX\s*\(\s*(?:`?(?P<sub_date_alias_2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?(?P<sub_date_col_2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                )
                \s*,\s*(?:`?(?P<sub_key_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?(?P<sub_key_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s+FROM\s+`?(?P<sub_date_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?(?P<sub_table_alias>[A-Za-z_][A-Za-z0-9_]*)`?)?
                \s+GROUP\s+BY\s+(?:`?(?P<group_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?(?P<group_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s*\)\s*$""",
            cond.strip(),
        )
        if not m_fast:
            continue

        outer_date_alias = m_fast.group("outer_date_alias")
        outer_date_col = m_fast.group("outer_date_col")
        outer_entity_alias = m_fast.group("outer_entity_alias")
        outer_entity_col = m_fast.group("outer_entity_col")
        sub_date_table = (m_fast.group("sub_date_table") or "").strip()
        sub_date_col = (
            m_fast.group("sub_date_col_1")
            or m_fast.group("sub_date_col_2")
            or ""
        ).strip()
        sub_key_col = (m_fast.group("sub_key_col") or "").strip()
        group_col = (m_fast.group("group_col") or "").strip()
        if not outer_date_alias or not outer_date_col or not outer_entity_alias or not outer_entity_col:
            continue
        if not sub_date_table or not sub_date_col or not sub_key_col or not group_col:
            continue
        if sub_key_col.lower() != outer_entity_col.lower() or group_col.lower() != outer_entity_col.lower():
            continue

        outer_date_table = alias_map.get(outer_date_alias) or alias_map.get(outer_date_alias.lower())
        outer_entity_table = alias_map.get(outer_entity_alias) or alias_map.get(outer_entity_alias.lower())
        if not outer_date_table or not outer_entity_table:
            continue
        if _plain_table_name(outer_date_table).lower() != _plain_table_name(sub_date_table).lower():
            continue

        outer_date_cols = _table_cols(outer_date_table)
        outer_entity_cols = _table_cols(outer_entity_table)
        # Only trigger when the temporal table owns the date column but does not
        # own the grouped entity key, i.e. a bridge table is required.
        if outer_date_cols and outer_date_col.lower() not in outer_date_cols:
            continue
        if outer_entity_cols and outer_entity_col.lower() not in outer_entity_cols:
            continue
        if outer_date_cols and outer_entity_col.lower() in outer_date_cols:
            continue

        bridge_candidates: List[tuple[int, tuple[str, str, str, str]]] = []
        for m_eq in eq_pairs:
            a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
            a1l, a2l = a1.lower(), a2.lower()

            if a1l == outer_date_alias.lower() and a2l in alias_map and a2l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_link_col = a2, c1, c2
            elif a2l == outer_date_alias.lower() and a1l in alias_map and a1l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_link_col = a1, c2, c1
            else:
                continue

            bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower())
            bridge_cols = _table_cols(bridge_table)
            if bridge_cols and bridge_link_col.lower() not in bridge_cols:
                continue
            if bridge_cols and outer_entity_col.lower() not in bridge_cols:
                mapped_bridge_col = _bridge_col_for_target(bridge_alias, outer_entity_alias, outer_entity_col)
                if not mapped_bridge_col:
                    continue
            score = 0
            mapped_bridge_col = _bridge_col_for_target(bridge_alias, outer_entity_alias, outer_entity_col) or ""
            if mapped_bridge_col:
                score += 4
            if bridge_alias.lower() == outer_entity_alias.lower():
                score += 2
            bridge_candidates.append((score, (bridge_alias, bridge_table, date_join_col, bridge_link_col)))

        if not bridge_candidates:
            continue

        bridge_candidates.sort(key=lambda item: item[0], reverse=True)
        bridge_alias, bridge_table, date_join_col, bridge_link_col = bridge_candidates[0][1]
        if bridge_alias.lower() == outer_entity_alias.lower():
            bridge_group_col = outer_entity_col
        else:
            bridge_group_col = _bridge_col_for_target(bridge_alias, outer_entity_alias, outer_entity_col) or ""
        if not bridge_group_col:
            continue

        ly_alias = _pick_alias("latest_years", used_aliases)
        src_alias = _pick_alias("ly_src", used_aliases)
        dt_alias = _pick_alias("ly_dt", used_aliases)

        ly_join = (
            "JOIN (\n"
            "  SELECT\n"
            f"    {src_alias}.{bridge_group_col} AS latest_key,\n"
            f"    MAX(YEAR({dt_alias}.{outer_date_col})) AS latest_year\n"
            f"  FROM {bridge_table} AS {src_alias}\n"
            f"  JOIN {outer_date_table} AS {dt_alias}\n"
            f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_link_col}\n"
            f"  GROUP BY {src_alias}.{bridge_group_col}\n"
            f") AS {ly_alias}\n"
            f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}"
        )

        rebuilt_select = _replace_year_projection(parsed["select"].strip(), ly_alias, outer_date_alias, outer_date_col)
        rebuilt_group_items: List[str] = []
        seen_group: Set[str] = set()
        for item in _split_top_level_commas(parsed.get("groupby", "")):
            replaced = _replace_year_projection(item, ly_alias, outer_date_alias, outer_date_col).strip()
            if not replaced:
                continue
            key = replaced.lower()
            if key in seen_group:
                continue
            seen_group.add(key)
            rebuilt_group_items.append(replaced)
        if not rebuilt_group_items:
            continue

        rebuilt_select, rebuilt_group_items = _ensure_requested_entity_name(
            rebuilt_select,
            rebuilt_group_items,
            outer_entity_alias,
            outer_entity_table,
        )
        remaining_conds = [c.strip() for j, c in enumerate(conjuncts) if j != idx and c.strip()]
        remaining_conds.append(f"YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year")

        requested_order = _extract_requested_order(rebuilt_select, question)
        rebuilt_tail = _replace_top_level_order_in_tail(parsed.get("tail", ""), requested_order)
        tail_clause = f"\n{rebuilt_tail}" if rebuilt_tail else ""
        fixed = (
            f"SELECT {rebuilt_select}\n"
            f"FROM {from_core}\n{ly_join}\n"
            f"WHERE {' AND '.join(remaining_conds)}\n"
            f"GROUP BY {', '.join(rebuilt_group_items)}"
            f"{tail_clause};"
        )
        return fixed

    for idx, cond in enumerate(conjuncts):
        malformed_tuple_match = re.match(
            r"""(?is)^\s*\(\s*(?P<outer_tuple>.+?)\s*\)\s+IN\s*\(\s*(?P<subquery>SELECT.+)\s*\)\s*$""",
            cond.strip(),
        )
        if malformed_tuple_match:
            outer_tuple_items = _split_top_level_commas(malformed_tuple_match.group("outer_tuple") or "")
            if outer_tuple_items:
                first_outer = (outer_tuple_items[0] or "").strip()
                second_outer_ref = _parse_simple_col(outer_tuple_items[1]) if len(outer_tuple_items) >= 2 else None
                outer_year = re.match(
                    r"""(?is)^YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*$""",
                    first_outer,
                )
                if outer_year:
                    outer_date_alias = outer_year.group(1)
                    outer_date_col = outer_year.group(2)
                    sub_sql = (malformed_tuple_match.group("subquery") or "").strip()
                    sub_parsed = _parse_flat_select_with_nested_where_groups(sub_sql)
                    if sub_parsed:
                        sub_group_items = _split_top_level_commas(sub_parsed.get("groupby", ""))
                        if len(sub_group_items) >= 2:
                            sub_year_group = next(
                                (
                                    g.strip()
                                    for g in sub_group_items
                                    if re.match(
                                        r"""(?is)^YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?\s*\)\s*$""",
                                        g.strip(),
                                    )
                                ),
                                "",
                            )
                            non_year_group_refs = [
                                _parse_simple_col(g)
                                for g in sub_group_items
                                if g.strip() != sub_year_group
                            ]
                            non_year_group_refs = [ref for ref in non_year_group_refs if ref]
                            if sub_year_group and non_year_group_refs:
                                key_like_groups = [
                                    ref for ref in non_year_group_refs
                                    if any(tok in (ref[1] or "").lower() for tok in ["id", "code", "number", "key"])
                                ]
                                target_group_ref = key_like_groups[0] if key_like_groups else non_year_group_refs[0]
                                target_group_col = (target_group_ref[1] or "").strip()
                                target_outer_ref = next(
                                    (
                                        (alias_name, col_name)
                                        for alias_name, col_name, _weight in grouped_refs
                                        if str(col_name or "").strip().lower() == target_group_col.lower()
                                    ),
                                    None,
                                )
                                if not target_outer_ref and second_outer_ref:
                                    current_outer_alias, current_outer_col = second_outer_ref
                                    outer_date_table = alias_map.get(outer_date_alias) or alias_map.get(outer_date_alias.lower())
                                    if outer_date_table:
                                        bridge_candidates_for_inference: List[tuple[int, tuple[str, str, str, str]]] = []
                                        for m_eq in eq_pairs:
                                            a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
                                            a1l, a2l = a1.lower(), a2.lower()

                                            if a1l == outer_date_alias.lower() and a2l in alias_map and a2l != outer_date_alias.lower():
                                                bridge_alias, date_join_col, bridge_link_col = a2, c1, c2
                                            elif a2l == outer_date_alias.lower() and a1l in alias_map and a1l != outer_date_alias.lower():
                                                bridge_alias, date_join_col, bridge_link_col = a1, c2, c1
                                            else:
                                                continue

                                            if bridge_alias.lower() != str(current_outer_alias or "").lower():
                                                continue
                                            if bridge_link_col.lower() != str(current_outer_col or "").lower():
                                                continue

                                            bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower())
                                            bridge_cols = _table_cols(bridge_table)
                                            if bridge_cols and bridge_link_col.lower() not in bridge_cols:
                                                continue
                                            date_cols = _table_cols(outer_date_table)
                                            if date_cols and date_join_col.lower() not in date_cols:
                                                continue

                                            bridge_candidates_for_inference.append(
                                                (2, (bridge_alias, bridge_table, date_join_col, bridge_link_col))
                                            )

                                        if bridge_candidates_for_inference:
                                            bridge_candidates_for_inference.sort(key=lambda item: item[0], reverse=True)
                                            bridge_alias, bridge_table, _date_join_col, bridge_link_col = bridge_candidates_for_inference[0][1]
                                            inferred_target = _infer_grouped_entity_target(
                                                bridge_alias,
                                                bridge_table,
                                                outer_date_alias,
                                                current_outer_alias,
                                                current_outer_col,
                                                bridge_link_col,
                                            )
                                            if inferred_target:
                                                target_outer_ref = (inferred_target[0], inferred_target[1])
                                if target_outer_ref:
                                    outer_entity_alias, outer_entity_col = target_outer_ref
                                    outer_date_table = alias_map.get(outer_date_alias) or alias_map.get(outer_date_alias.lower())
                                    outer_entity_table = alias_map.get(outer_entity_alias) or alias_map.get(outer_entity_alias.lower())
                                    if outer_date_table and outer_entity_table:
                                        outer_date_cols = _table_cols(outer_date_table)
                                        outer_entity_cols = _table_cols(outer_entity_table)
                                        if (
                                            (not outer_date_cols or outer_date_col.lower() in outer_date_cols)
                                            and (not outer_entity_cols or outer_entity_col.lower() in outer_entity_cols)
                                        ):
                                            bridge_candidates: List[tuple[int, tuple[str, str, str, str]]] = []
                                            for m_eq in eq_pairs:
                                                a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
                                                a1l, a2l = a1.lower(), a2.lower()

                                                if a1l == outer_date_alias.lower() and a2l in alias_map and a2l != outer_date_alias.lower():
                                                    bridge_alias, date_join_col, bridge_link_col = a2, c1, c2
                                                elif a2l == outer_date_alias.lower() and a1l in alias_map and a1l != outer_date_alias.lower():
                                                    bridge_alias, date_join_col, bridge_link_col = a1, c2, c1
                                                else:
                                                    continue

                                                bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower())
                                                bridge_cols = _table_cols(bridge_table)
                                                if bridge_cols and bridge_link_col.lower() not in bridge_cols:
                                                    continue
                                                date_cols = _table_cols(outer_date_table)
                                                if date_cols and date_join_col.lower() not in date_cols:
                                                    continue

                                                score = 0
                                                mapped_bridge_col = _bridge_col_for_target(bridge_alias, outer_entity_alias, outer_entity_col)
                                                if mapped_bridge_col:
                                                    score += 4
                                                if bridge_alias.lower() == outer_entity_alias.lower():
                                                    score += 2
                                                bridge_candidates.append(
                                                    (score, (bridge_alias, bridge_table, date_join_col, bridge_link_col))
                                                )

                                            if bridge_candidates:
                                                bridge_candidates.sort(key=lambda item: item[0], reverse=True)
                                                bridge_alias, bridge_table, date_join_col, bridge_link_col = bridge_candidates[0][1]
                                                if outer_entity_alias.lower() == bridge_alias.lower():
                                                    bridge_group_col = outer_entity_col
                                                else:
                                                    bridge_group_col = _bridge_col_for_target(bridge_alias, outer_entity_alias, outer_entity_col) or ""
                                                if bridge_group_col:
                                                    ly_alias = _pick_alias("latest_years", used_aliases)
                                                    src_alias = _pick_alias("ly_src", used_aliases)
                                                    dt_alias = _pick_alias("ly_dt", used_aliases)

                                                    ly_join = (
                                                        "JOIN (\n"
                                                        "  SELECT\n"
                                                        f"    {src_alias}.{bridge_group_col} AS latest_key,\n"
                                                        f"    MAX(YEAR({dt_alias}.{outer_date_col})) AS latest_year\n"
                                                        f"  FROM {bridge_table} AS {src_alias}\n"
                                                        f"  JOIN {outer_date_table} AS {dt_alias}\n"
                                                        f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_link_col}\n"
                                                        f"  GROUP BY {src_alias}.{bridge_group_col}\n"
                                                        f") AS {ly_alias}\n"
                                                        f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}"
                                                    )

                                                    rebuilt_select = _replace_year_projection(parsed["select"].strip(), ly_alias, outer_date_alias, outer_date_col)

                                                    rebuilt_group_items: List[str] = []
                                                    seen_group: Set[str] = set()
                                                    for item in _split_top_level_commas(parsed.get("groupby", "")):
                                                        replaced = _replace_year_projection(item, ly_alias, outer_date_alias, outer_date_col).strip()
                                                        if not replaced:
                                                            continue
                                                        key = replaced.lower()
                                                        if key in seen_group:
                                                            continue
                                                        seen_group.add(key)
                                                        rebuilt_group_items.append(replaced)
                                                    if rebuilt_group_items:
                                                        rebuilt_select, rebuilt_group_items = _ensure_requested_entity_name(
                                                            rebuilt_select,
                                                            rebuilt_group_items,
                                                            outer_entity_alias,
                                                            outer_entity_table,
                                                        )
                                                        remaining_conds = [c.strip() for j, c in enumerate(conjuncts) if j != idx and c.strip()]
                                                        remaining_conds.append(f"YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year")

                                                        requested_order = _extract_requested_order(rebuilt_select, question)
                                                        rebuilt_tail = _replace_top_level_order_in_tail(parsed.get("tail", ""), requested_order)
                                                        tail_clause = f"\n{rebuilt_tail}" if rebuilt_tail else ""
                                                        fixed = (
                                                            f"SELECT {rebuilt_select}\n"
                                                            f"FROM {from_core}\n{ly_join}\n"
                                                            f"WHERE {' AND '.join(remaining_conds)}\n"
                                                            f"GROUP BY {', '.join(rebuilt_group_items)}"
                                                            f"{tail_clause};"
                                                        )
                                                        return fixed

        m_tuple = re.match(
            r"""(?is)^\s*\(\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*,\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s+IN\s*\((SELECT.+)\)\s*$""",
            cond.strip(),
        )
        if not m_tuple:
            continue

        outer_date_alias, outer_date_col = m_tuple.group(1), m_tuple.group(2)
        outer_entity_alias, outer_entity_col = m_tuple.group(3), m_tuple.group(4)
        sub_sql = (m_tuple.group(5) or "").strip()

        sub_parsed = _parse_flat_select_with_nested_where_groups(sub_sql)
        if not sub_parsed:
            continue
        sub_select_items = _split_top_level_commas(sub_parsed.get("select", ""))
        sub_group_items = _split_top_level_commas(sub_parsed.get("groupby", ""))
        if len(sub_select_items) != 2 or len(sub_group_items) != 1:
            continue

        sub_year_expr, _ = _split_expr_alias(sub_select_items[0])
        sub_key_expr, _ = _split_expr_alias(sub_select_items[1])
        key_ref = _parse_simple_col(sub_key_expr)
        group_ref = _parse_simple_col(sub_group_items[0])
        if not key_ref or not group_ref:
            continue
        if (key_ref[1] or "").lower() != outer_entity_col.lower():
            continue
        if (group_ref[1] or "").lower() != outer_entity_col.lower():
            continue

        m_sub_year = re.match(
            r"""(?is)^\s*(?:MAX\s*\(\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)|YEAR\s*\(\s*MAX\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\))\s*$""",
            sub_year_expr,
        )
        if not m_sub_year:
            continue
        sub_date_alias = m_sub_year.group(1) or m_sub_year.group(3) or ""
        sub_date_col = m_sub_year.group(2) or m_sub_year.group(4) or ""
        if not sub_date_col:
            continue

        outer_date_table = alias_map.get(outer_date_alias) or alias_map.get(outer_date_alias.lower())
        outer_entity_table = alias_map.get(outer_entity_alias) or alias_map.get(outer_entity_alias.lower())
        if not outer_date_table or not outer_entity_table:
            continue

        outer_date_cols = _table_cols(outer_date_table)
        outer_entity_cols = _table_cols(outer_entity_table)
        if outer_date_cols and outer_date_col.lower() not in outer_date_cols:
            continue
        if outer_entity_cols and outer_entity_col.lower() not in outer_entity_cols:
            continue

        bridge_candidates: List[tuple[int, tuple[str, str, str, str]]] = []
        for m_eq in eq_pairs:
            a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
            a1l, a2l = a1.lower(), a2.lower()

            if a1l == outer_date_alias.lower() and a2l in alias_map and a2l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_link_col = a2, c1, c2
            elif a2l == outer_date_alias.lower() and a1l in alias_map and a1l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_link_col = a1, c2, c1
            else:
                continue

            bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower())
            bridge_cols = _table_cols(bridge_table)
            if bridge_cols and outer_entity_col.lower() not in bridge_cols:
                continue
            if bridge_cols and bridge_link_col.lower() not in bridge_cols:
                continue

            date_cols = _table_cols(outer_date_table)
            if date_cols and date_join_col.lower() not in date_cols:
                continue

            score = 0
            # Prefer the visible entity alias when it also acts as the bridge.
            if bridge_alias.lower() == outer_entity_alias.lower():
                score += 4
            # Prefer aliases that directly expose the grouped entity key.
            if bridge_link_col.lower() == outer_entity_col.lower():
                score += 1
            bridge_candidates.append(
                (score, (bridge_alias, bridge_table, date_join_col, bridge_link_col))
            )

        if not bridge_candidates:
            continue

        bridge_candidates.sort(key=lambda item: item[0], reverse=True)
        bridge_choice = bridge_candidates[0][1]
        bridge_alias, bridge_table, date_join_col, bridge_link_col = bridge_choice
        bridge_group_col = outer_entity_col
        if outer_entity_alias.lower() == bridge_alias.lower():
            bridge_group_col = outer_entity_col
            if outer_entity_col.lower() == bridge_link_col.lower():
                inferred_target = _infer_grouped_entity_target(
                    bridge_alias,
                    bridge_table,
                    outer_date_alias,
                    outer_entity_alias,
                    outer_entity_col,
                    bridge_link_col,
                )
                if inferred_target:
                    outer_entity_alias, outer_entity_col, bridge_group_col = inferred_target
        else:
            mapped_bridge_col = _bridge_col_for_target(bridge_alias, outer_entity_alias, outer_entity_col)
            if not mapped_bridge_col:
                continue
            bridge_group_col = mapped_bridge_col

        ly_alias = _pick_alias("latest_years", used_aliases)
        src_alias = _pick_alias("ly_src", used_aliases)
        dt_alias = _pick_alias("ly_dt", used_aliases)

        ly_join = (
            "JOIN (\n"
            "  SELECT\n"
            f"    {src_alias}.{bridge_group_col} AS latest_key,\n"
            f"    MAX(YEAR({dt_alias}.{outer_date_col})) AS latest_year\n"
            f"  FROM {bridge_table} AS {src_alias}\n"
            f"  JOIN {outer_date_table} AS {dt_alias}\n"
            f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_link_col}\n"
            f"  GROUP BY {src_alias}.{bridge_group_col}\n"
            f") AS {ly_alias}\n"
            f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}"
        )

        rebuilt_select = _replace_year_projection(parsed["select"].strip(), ly_alias, outer_date_alias, outer_date_col)

        rebuilt_group_items: List[str] = []
        seen_group: Set[str] = set()
        for item in _split_top_level_commas(parsed.get("groupby", "")):
            replaced = _replace_year_projection(item, ly_alias, outer_date_alias, outer_date_col).strip()
            if not replaced:
                continue
            key = replaced.lower()
            if key in seen_group:
                continue
            seen_group.add(key)
            rebuilt_group_items.append(replaced)
        if not rebuilt_group_items:
            continue

        rebuilt_select, rebuilt_group_items = _ensure_requested_entity_name(
            rebuilt_select,
            rebuilt_group_items,
            outer_entity_alias,
            outer_entity_table,
            )

        remaining_conds = [c.strip() for j, c in enumerate(conjuncts) if j != idx and c.strip()]
        remaining_conds.append(f"YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year")

        requested_order = _extract_requested_order(rebuilt_select, question)
        rebuilt_tail = _replace_top_level_order_in_tail(parsed.get("tail", ""), requested_order)
        tail_clause = f"\n{rebuilt_tail}" if rebuilt_tail else ""
        fixed = (
            f"SELECT {rebuilt_select}\n"
            f"FROM {from_core}\n{ly_join}\n"
            f"WHERE {' AND '.join(remaining_conds)}\n"
            f"GROUP BY {', '.join(rebuilt_group_items)}"
            f"{tail_clause};"
        )
        return fixed

    return sql


def _rewrite_bridge_latest_year_tuple_filter_fast(sql: str, question: str) -> str:
    """
    Small, deterministic rewrite for bridge-backed latest-year tuple filters.
    Kept intentionally narrow to avoid touching unrelated latest-year logic.
    """
    if not sql:
        return sql
    if not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    s0 = (sql or "").strip().rstrip(";").strip()
    if " in (select max(year(" not in s0.lower():
        return sql
    if not re.search(r"(?is)\bwhere\s*\(\s*year\s*\(", s0):
        return sql
    if re.search(r"\b(?:from|join)\s*\(", s0, flags=re.I):
        return sql

    def _find_top_level_kw(text: str, keyword: str, start: int = 0) -> int:
        w = keyword.lower()
        n = len(w)
        depth = 0
        in_sq = in_dq = in_bt = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i >= start and i + n <= len(text):
                left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
                right_ok = (i + n) >= len(text) or not (text[i + n].isalnum() or text[i + n] == "_")
                if left_ok and right_ok and text[i:i + n].lower() == w:
                    return i
            i += 1
        return -1

    sel_pos = _find_top_level_kw(s0, "select", 0)
    from_pos = _find_top_level_kw(s0, "from", max(0, sel_pos + len("select")))
    group_pos = _find_top_level_kw(s0, "group by", max(0, from_pos + len("from")))
    if sel_pos < 0 or from_pos < 0 or group_pos < 0:
        return sql

    order_pos = _find_top_level_kw(s0, "order by", group_pos + len("group by"))
    limit_pos = _find_top_level_kw(s0, "limit", group_pos + len("group by"))
    tail_pos_candidates = [p for p in [order_pos, limit_pos] if p >= 0]
    group_end = min(tail_pos_candidates) if tail_pos_candidates else len(s0)

    select_part = s0[sel_pos + len("select"):from_pos].strip()
    from_part = s0[from_pos + len("from"):group_pos].strip()
    group_part = s0[group_pos + len("group by"):group_end].strip()
    tail_part = s0[group_end:].strip() if group_end < len(s0) else ""

    where_pos = _find_top_level_kw(from_part, "where", 0)
    if where_pos < 0:
        return sql
    from_core = from_part[:where_pos].strip()
    where_body = re.sub(r"^\s*where\s+", "", from_part[where_pos:].strip(), flags=re.I).strip()
    if not from_core or not where_body or _has_top_level_or(where_body):
        return sql

    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if not alias_map:
        return sql

    conjuncts = _split_top_level_and(where_body)
    if not conjuncts:
        return sql

    eq_pairs = list(
        re.finditer(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            from_core,
            flags=re.I,
        )
    )

    tuple_pat = re.compile(
        r"""(?is)^\s*
            \(\s*YEAR\s*\(\s*`?(?P<outer_date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
            \s*,\s*`?(?P<outer_entity_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_entity_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
            \s+IN\s*\(\s*SELECT\s+
            (?:
                MAX\s*\(\s*YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
              |
                YEAR\s*\(\s*MAX\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
            )
            \s*,\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_key_col>[A-Za-z_][A-Za-z0-9_]*)`?
            \s+FROM\s+`?(?P<sub_date_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?[A-Za-z_][A-Za-z0-9_]*`?)?
            \s+GROUP\s+BY\s+(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<group_col>[A-Za-z_][A-Za-z0-9_]*)`?
            \s*\)\s*$""",
    )

    for idx, cond in enumerate(conjuncts):
        m = tuple_pat.match((cond or "").strip())
        if not m:
            continue

        outer_date_alias = m.group("outer_date_alias")
        outer_date_col = m.group("outer_date_col")
        outer_entity_alias = m.group("outer_entity_alias")
        outer_entity_col = m.group("outer_entity_col")
        sub_key_col = (m.group("sub_key_col") or "").strip()
        group_col = (m.group("group_col") or "").strip()
        sub_date_table = (m.group("sub_date_table") or "").strip()
        if sub_key_col.lower() != outer_entity_col.lower() or group_col.lower() != outer_entity_col.lower():
            continue

        outer_date_table = alias_map.get(outer_date_alias) or alias_map.get(outer_date_alias.lower())
        if not outer_date_table:
            continue
        if str(outer_date_table).replace("`", "").split(".")[-1].strip().lower() != sub_date_table.lower():
            continue

        bridge_matches: List[Tuple[str, str, str]] = []
        for m_eq_date in eq_pairs:
            a1, c1, a2, c2 = m_eq_date.group(1), m_eq_date.group(2), m_eq_date.group(3), m_eq_date.group(4)
            a1l, a2l = a1.lower(), a2.lower()
            if a1l == outer_date_alias.lower() and a2l in alias_map and a2l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_fk_col = a2, c1, c2
            elif a2l == outer_date_alias.lower() and a1l in alias_map and a1l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_fk_col = a1, c2, c1
            else:
                continue

            entity_join_ok = False
            for m_eq_entity in eq_pairs:
                b1, d1, b2, d2 = m_eq_entity.group(1), m_eq_entity.group(2), m_eq_entity.group(3), m_eq_entity.group(4)
                b1l, b2l = b1.lower(), b2.lower()
                if b1l == bridge_alias.lower() and b2l == outer_entity_alias.lower() and d1.lower() == outer_entity_col.lower() and d2.lower() == outer_entity_col.lower():
                    entity_join_ok = True
                    break
                if b2l == bridge_alias.lower() and b1l == outer_entity_alias.lower() and d2.lower() == outer_entity_col.lower() and d1.lower() == outer_entity_col.lower():
                    entity_join_ok = True
                    break
            if entity_join_ok:
                bridge_matches.append((bridge_alias, date_join_col, bridge_fk_col))

        if len(bridge_matches) != 1:
            continue

        bridge_alias, date_join_col, bridge_fk_col = bridge_matches[0]
        bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower()) or bridge_alias

        used_aliases = {a.lower() for a in alias_map.keys() if a}
        used_aliases.update(str(t or "").replace("`", "").split(".")[-1].strip().lower() for t in alias_map.values())

        def _pick_alias(base: str) -> str:
            seed = re.sub(r"[^A-Za-z0-9_]+", "_", (base or "")).strip("_") or "t"
            if not re.match(r"[A-Za-z_]", seed[0]):
                seed = f"t_{seed}"
            cand = seed
            n = 2
            while cand.lower() in used_aliases:
                cand = f"{seed}_{n}"
                n += 1
            used_aliases.add(cand.lower())
            return cand

        ly_alias = _pick_alias("latest_years")
        src_alias = _pick_alias("ly_src")
        dt_alias = _pick_alias("ly_dt")

        def _replace_year_projection(text: str) -> str:
            return re.sub(
                rf"(?is)YEAR\s*\(\s*`?{re.escape(outer_date_alias)}`?\s*\.\s*`?{re.escape(outer_date_col)}`?\s*\)",
                f"{ly_alias}.latest_year",
                text,
            )

        select_rebuilt = _replace_year_projection(select_part)
        group_items: List[str] = []
        seen_group: Set[str] = set()
        for item in _split_top_level_commas(group_part):
            replaced = _replace_year_projection((item or "").strip()).strip()
            if not replaced:
                continue
            key = replaced.lower()
            if key in seen_group:
                continue
            seen_group.add(key)
            group_items.append(replaced)
        if not group_items:
            continue

        ly_join = (
            "JOIN (\n"
            "  SELECT\n"
            f"    {src_alias}.{outer_entity_col} AS latest_key,\n"
            f"    MAX(YEAR({dt_alias}.{outer_date_col})) AS latest_year\n"
            f"  FROM {bridge_table} AS {src_alias}\n"
            f"  JOIN {outer_date_table} AS {dt_alias}\n"
            f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_fk_col}\n"
            f"  GROUP BY {src_alias}.{outer_entity_col}\n"
            f") AS {ly_alias}\n"
            f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}"
        )

        remaining = [c.strip() for j, c in enumerate(conjuncts) if j != idx and c.strip()]
        remaining.append(f"YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year")
        where_rebuilt = " AND ".join(remaining)
        tail_clause = f"\n{tail_part}" if tail_part else ""
        return (
            f"SELECT {select_rebuilt}\n"
            f"FROM {from_core}\n{ly_join}\n"
            f"WHERE {where_rebuilt}\n"
            f"GROUP BY {', '.join(group_items)}"
            f"{tail_clause};"
        )

    return sql


def _rewrite_bridge_latest_year_tuple_filter_minimal(sql: str, question: str) -> str:
    """
    Minimal bridge latest-year rewrite used as a last deterministic fallback.
    Built to stay narrow: flat grouped query, tuple-IN latest-year predicate,
    and a unique bridge path between the temporal table and entity table.
    """
    if not sql or not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    s0 = (sql or "").strip().rstrip(";").strip()
    if " in (select max(year(" not in s0.lower():
        return sql

    def _find_kw(text: str, keyword: str, start: int = 0) -> int:
        w = keyword.lower()
        n = len(w)
        depth = 0
        in_sq = in_dq = in_bt = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i >= start and i + n <= len(text):
                left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
                right_ok = (i + n) >= len(text) or not (text[i + n].isalnum() or text[i + n] == "_")
                if left_ok and right_ok and text[i:i + n].lower() == w:
                    return i
            i += 1
        return -1

    sel = _find_kw(s0, "select", 0)
    frm = _find_kw(s0, "from", sel + 6)
    grp = _find_kw(s0, "group by", frm + 4)
    if sel < 0 or frm < 0 or grp < 0:
        return sql
    ordp = _find_kw(s0, "order by", grp + 8)
    limitp = _find_kw(s0, "limit", grp + 8)
    tail_pos = min([p for p in [ordp, limitp] if p >= 0], default=len(s0))

    select_part = s0[sel + 6:frm].strip()
    from_part = s0[frm + 4:grp].strip()
    group_part = s0[grp + 8:tail_pos].strip()
    tail_part = s0[tail_pos:].strip() if tail_pos < len(s0) else ""

    where_pos = _find_kw(from_part, "where", 0)
    if where_pos < 0:
        return sql
    from_core = from_part[:where_pos].strip()
    where_body = re.sub(r"^\s*where\s+", "", from_part[where_pos:].strip(), flags=re.I).strip()
    if not from_core or not where_body or _has_top_level_or(where_body):
        return sql

    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if not alias_map:
        return sql
    conjuncts = _split_top_level_and(where_body)
    if not conjuncts:
        return sql

    eq_pairs = list(
        re.finditer(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            from_core,
            flags=re.I,
        )
    )

    tuple_pat = re.compile(
        r"""(?is)^\s*\(\s*YEAR\s*\(\s*`?(?P<outer_date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*,\s*`?(?P<outer_entity_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_entity_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s+IN\s*\(\s*SELECT\s+(?:MAX\s*\(\s*YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)|YEAR\s*\(\s*MAX\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\))\s*,\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_key_col>[A-Za-z_][A-Za-z0-9_]*)`?\s+FROM\s+`?(?P<sub_date_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?[A-Za-z_][A-Za-z0-9_]*`?)?\s+GROUP\s+BY\s+(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<group_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*$""",
    )

    for idx, cond in enumerate(conjuncts):
        m = tuple_pat.match((cond or "").strip())
        if not m:
            continue

        outer_date_alias = m.group("outer_date_alias")
        outer_date_col = m.group("outer_date_col")
        outer_entity_alias = m.group("outer_entity_alias")
        outer_entity_col = m.group("outer_entity_col")

        bridge_matches: List[Tuple[str, str, str]] = []
        for m_eq_date in eq_pairs:
            a1, c1, a2, c2 = m_eq_date.group(1), m_eq_date.group(2), m_eq_date.group(3), m_eq_date.group(4)
            a1l, a2l = a1.lower(), a2.lower()
            if a1l == outer_date_alias.lower() and a2l in alias_map and a2l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_fk_col = a2, c1, c2
            elif a2l == outer_date_alias.lower() and a1l in alias_map and a1l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_fk_col = a1, c2, c1
            else:
                continue

            entity_join_ok = False
            for m_eq_entity in eq_pairs:
                b1, d1, b2, d2 = m_eq_entity.group(1), m_eq_entity.group(2), m_eq_entity.group(3), m_eq_entity.group(4)
                b1l, b2l = b1.lower(), b2.lower()
                if b1l == bridge_alias.lower() and b2l == outer_entity_alias.lower() and d1.lower() == outer_entity_col.lower() and d2.lower() == outer_entity_col.lower():
                    entity_join_ok = True
                    break
                if b2l == bridge_alias.lower() and b1l == outer_entity_alias.lower() and d2.lower() == outer_entity_col.lower() and d1.lower() == outer_entity_col.lower():
                    entity_join_ok = True
                    break
            if entity_join_ok:
                bridge_matches.append((bridge_alias, date_join_col, bridge_fk_col))

        if len(bridge_matches) != 1:
            continue

        bridge_alias, date_join_col, bridge_fk_col = bridge_matches[0]
        bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower()) or bridge_alias
        outer_date_table = alias_map.get(outer_date_alias) or alias_map.get(outer_date_alias.lower()) or outer_date_alias

        used_aliases = {a.lower() for a in alias_map.keys() if a}
        used_aliases.update(str(t or "").replace("`", "").split(".")[-1].strip().lower() for t in alias_map.values())

        def _pick_alias(base: str) -> str:
            seed = re.sub(r"[^A-Za-z0-9_]+", "_", (base or "")).strip("_") or "t"
            if not re.match(r"[A-Za-z_]", seed[0]):
                seed = f"t_{seed}"
            cand = seed
            n = 2
            while cand.lower() in used_aliases:
                cand = f"{seed}_{n}"
                n += 1
            used_aliases.add(cand.lower())
            return cand

        ly_alias = _pick_alias("latest_years")
        src_alias = _pick_alias("ly_src")
        dt_alias = _pick_alias("ly_dt")

        def _replace_year(text: str) -> str:
            return re.sub(
                rf"(?is)YEAR\s*\(\s*`?{re.escape(outer_date_alias)}`?\s*\.\s*`?{re.escape(outer_date_col)}`?\s*\)",
                f"{ly_alias}.latest_year",
                text,
            )

        select_rebuilt = _replace_year(select_part)
        group_items: List[str] = []
        seen_group: Set[str] = set()
        for item in _split_top_level_commas(group_part):
            replaced = _replace_year((item or "").strip()).strip()
            if not replaced:
                continue
            key = replaced.lower()
            if key in seen_group:
                continue
            seen_group.add(key)
            group_items.append(replaced)
        if not group_items:
            continue

        ly_join = (
            "JOIN (\n"
            "  SELECT\n"
            f"    {src_alias}.{outer_entity_col} AS latest_key,\n"
            f"    MAX(YEAR({dt_alias}.{outer_date_col})) AS latest_year\n"
            f"  FROM {bridge_table} AS {src_alias}\n"
            f"  JOIN {outer_date_table} AS {dt_alias}\n"
            f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_fk_col}\n"
            f"  GROUP BY {src_alias}.{outer_entity_col}\n"
            f") AS {ly_alias}\n"
            f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}"
        )

        remaining = [c.strip() for j, c in enumerate(conjuncts) if j != idx and c.strip()]
        remaining.append(f"YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year")
        tail_clause = f"\n{tail_part}" if tail_part else ""
        return (
            f"SELECT {select_rebuilt}\n"
            f"FROM {from_core}\n{ly_join}\n"
            f"WHERE {' AND '.join(remaining)}\n"
            f"GROUP BY {', '.join(group_items)}"
            f"{tail_clause};"
        )

    return sql


def _rewrite_bridge_latest_year_tuple_filter(sql: str, question: str, ctx: str = "") -> str:
    """
    Conservative fallback for malformed latest-year tuple-IN filters where the
    inner subquery incorrectly groups an entity key from the temporal table
    instead of the bridge table that actually owns that key.
    """
    if not sql:
        return sql
    if not _question_wants_latest_year_scope_with_aggregate(question):
        return sql

    minimal = _rewrite_bridge_latest_year_tuple_filter_minimal(sql, question)
    if minimal != sql:
        return minimal

    fast = _rewrite_bridge_latest_year_tuple_filter_fast(sql, question)
    if fast != sql:
        return fast

    # Fast path for bridge-backed latest-year tuple filters such as:
    #   WHERE (YEAR(o.orderDate), p.productCode) IN (
    #     SELECT MAX(YEAR(orderDate)), productCode FROM orders GROUP BY productCode
    #   )
    # when the grouped key actually lives on a bridge table joined between the
    # temporal table and the requested entity table.
    s0 = (sql or "").strip().rstrip(";").strip()
    if (
        " in (select max(year(" in s0.lower()
        and re.search(r"(?is)\bwhere\s*\(\s*year\s*\(", s0)
        and not re.search(r"\b(?:from|join)\s*\(", s0, flags=re.I)
    ):
        def _fast_find_kw(text: str, keyword: str, start: int = 0) -> int:
            w = keyword.lower()
            n = len(w)
            depth = 0
            in_sq = in_dq = in_bt = False
            i = 0
            while i < len(text):
                ch = text[i]
                if ch == "'" and not in_dq and not in_bt:
                    if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                        i += 2
                        continue
                    in_sq = not in_sq
                    i += 1
                    continue
                if ch == '"' and not in_sq and not in_bt:
                    in_dq = not in_dq
                    i += 1
                    continue
                if ch == "`" and not in_sq and not in_dq:
                    in_bt = not in_bt
                    i += 1
                    continue
                if in_sq or in_dq or in_bt:
                    i += 1
                    continue
                if ch == "(":
                    depth += 1
                    i += 1
                    continue
                if ch == ")":
                    depth = max(0, depth - 1)
                    i += 1
                    continue
                if depth == 0 and i >= start and i + n <= len(text):
                    left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
                    right_ok = (i + n) >= len(text) or not (text[i + n].isalnum() or text[i + n] == "_")
                    if left_ok and right_ok and text[i:i + n].lower() == w:
                        return i
                i += 1
            return -1

        sel_pos = _fast_find_kw(s0, "select", 0)
        from_pos = _fast_find_kw(s0, "from", max(0, sel_pos + len("select")))
        group_pos = _fast_find_kw(s0, "group by", max(0, from_pos + len("from")))
        if sel_pos >= 0 and from_pos >= 0 and group_pos >= 0:
            order_pos = _fast_find_kw(s0, "order by", group_pos + len("group by"))
            limit_pos = _fast_find_kw(s0, "limit", group_pos + len("group by"))
            tail_pos_candidates = [p for p in [order_pos, limit_pos] if p >= 0]
            group_end = min(tail_pos_candidates) if tail_pos_candidates else len(s0)

            select_part = s0[sel_pos + len("select"):from_pos].strip()
            from_part = s0[from_pos + len("from"):group_pos].strip()
            group_part = s0[group_pos + len("group by"):group_end].strip()
            tail_part = s0[group_end:].strip() if group_end < len(s0) else ""

            where_pos = _fast_find_kw(from_part, "where", 0)
            if where_pos >= 0:
                from_core_early = from_part[:where_pos].strip()
                where_body_early = re.sub(r"^\s*where\s+", "", from_part[where_pos:].strip(), flags=re.I).strip()
                if from_core_early and where_body_early and not _has_top_level_or(where_body_early):
                    alias_map_early = _parse_from_join_aliases(f"SELECT 1 FROM {from_core_early}")
                    conjuncts_early = _split_top_level_and(where_body_early)
                    eq_pairs_early = list(
                        re.finditer(
                            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
                            from_core_early,
                            flags=re.I,
                        )
                    )
                    tuple_pat = re.compile(
                        r"""(?is)^\s*
                            \(\s*YEAR\s*\(\s*`?(?P<outer_date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                            \s*,\s*`?(?P<outer_entity_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_entity_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                            \s+IN\s*\(\s*SELECT\s+
                            (?:
                                MAX\s*\(\s*YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                              |
                                YEAR\s*\(\s*MAX\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                            )
                            \s*,\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_key_col>[A-Za-z_][A-Za-z0-9_]*)`?
                            \s+FROM\s+`?(?P<sub_date_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?[A-Za-z_][A-Za-z0-9_]*`?)?
                            \s+GROUP\s+BY\s+(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<group_col>[A-Za-z_][A-Za-z0-9_]*)`?
                            \s*\)\s*$""",
                    )
                    for idx, cond in enumerate(conjuncts_early):
                        m_early = tuple_pat.match((cond or "").strip())
                        if not m_early:
                            continue
                        outer_date_alias = m_early.group("outer_date_alias")
                        outer_date_col = m_early.group("outer_date_col")
                        outer_entity_alias = m_early.group("outer_entity_alias")
                        outer_entity_col = m_early.group("outer_entity_col")
                        sub_key_col = (m_early.group("sub_key_col") or "").strip()
                        group_col = (m_early.group("group_col") or "").strip()
                        sub_date_table = (m_early.group("sub_date_table") or "").strip()
                        if sub_key_col.lower() != outer_entity_col.lower() or group_col.lower() != outer_entity_col.lower():
                            continue
                        outer_date_table = alias_map_early.get(outer_date_alias) or alias_map_early.get(outer_date_alias.lower())
                        if not outer_date_table:
                            continue
                        if str(outer_date_table).replace("`", "").split(".")[-1].strip().lower() != sub_date_table.lower():
                            continue

                        bridge_matches_early: List[Tuple[str, str, str]] = []
                        for m_eq_date in eq_pairs_early:
                            a1, c1, a2, c2 = m_eq_date.group(1), m_eq_date.group(2), m_eq_date.group(3), m_eq_date.group(4)
                            a1l, a2l = a1.lower(), a2.lower()
                            if a1l == outer_date_alias.lower() and a2l in alias_map_early and a2l != outer_date_alias.lower():
                                bridge_alias, date_join_col, bridge_fk_col = a2, c1, c2
                            elif a2l == outer_date_alias.lower() and a1l in alias_map_early and a1l != outer_date_alias.lower():
                                bridge_alias, date_join_col, bridge_fk_col = a1, c2, c1
                            else:
                                continue
                            entity_join_ok = False
                            for m_eq_entity in eq_pairs_early:
                                b1, d1, b2, d2 = m_eq_entity.group(1), m_eq_entity.group(2), m_eq_entity.group(3), m_eq_entity.group(4)
                                b1l, b2l = b1.lower(), b2.lower()
                                if b1l == bridge_alias.lower() and b2l == outer_entity_alias.lower() and d1.lower() == outer_entity_col.lower() and d2.lower() == outer_entity_col.lower():
                                    entity_join_ok = True
                                    break
                                if b2l == bridge_alias.lower() and b1l == outer_entity_alias.lower() and d2.lower() == outer_entity_col.lower() and d1.lower() == outer_entity_col.lower():
                                    entity_join_ok = True
                                    break
                            if entity_join_ok:
                                bridge_matches_early.append((bridge_alias, date_join_col, bridge_fk_col))
                        if len(bridge_matches_early) != 1:
                            continue

                        bridge_alias, date_join_col, bridge_fk_col = bridge_matches_early[0]
                        bridge_table = alias_map_early.get(bridge_alias) or alias_map_early.get(bridge_alias.lower()) or bridge_alias
                        used_aliases_early = {a.lower() for a in alias_map_early.keys() if a}
                        used_aliases_early.update(str(t or "").replace("`", "").split(".")[-1].strip().lower() for t in alias_map_early.values())

                        def _pick_alias_early(base: str) -> str:
                            seed = re.sub(r"[^A-Za-z0-9_]+", "_", (base or "")).strip("_") or "t"
                            if not re.match(r"[A-Za-z_]", seed[0]):
                                seed = f"t_{seed}"
                            cand = seed
                            n = 2
                            while cand.lower() in used_aliases_early:
                                cand = f"{seed}_{n}"
                                n += 1
                            used_aliases_early.add(cand.lower())
                            return cand

                        ly_alias = _pick_alias_early("latest_years")
                        src_alias = _pick_alias_early("ly_src")
                        dt_alias = _pick_alias_early("ly_dt")

                        def _replace_year_projection_early(text: str) -> str:
                            return re.sub(
                                rf"(?is)YEAR\s*\(\s*`?{re.escape(outer_date_alias)}`?\s*\.\s*`?{re.escape(outer_date_col)}`?\s*\)",
                                f"{ly_alias}.latest_year",
                                text,
                            )

                        select_rebuilt = _replace_year_projection_early(select_part)
                        group_items_early: List[str] = []
                        seen_group_early: Set[str] = set()
                        for item in _split_top_level_commas(group_part):
                            replaced = _replace_year_projection_early((item or "").strip()).strip()
                            if not replaced:
                                continue
                            key = replaced.lower()
                            if key in seen_group_early:
                                continue
                            seen_group_early.add(key)
                            group_items_early.append(replaced)
                        if not group_items_early:
                            continue

                        ly_join = (
                            "JOIN (\n"
                            "  SELECT\n"
                            f"    {src_alias}.{outer_entity_col} AS latest_key,\n"
                            f"    MAX(YEAR({dt_alias}.{outer_date_col})) AS latest_year\n"
                            f"  FROM {bridge_table} AS {src_alias}\n"
                            f"  JOIN {outer_date_table} AS {dt_alias}\n"
                            f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_fk_col}\n"
                            f"  GROUP BY {src_alias}.{outer_entity_col}\n"
                            f") AS {ly_alias}\n"
                            f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}"
                        )

                        remaining_early = [c.strip() for j, c in enumerate(conjuncts_early) if j != idx and c.strip()]
                        remaining_early.append(f"YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year")
                        where_rebuilt = " AND ".join(remaining_early)
                        tail_clause = f"\n{tail_part}" if tail_part else ""
                        return (
                            f"SELECT {select_rebuilt}\n"
                            f"FROM {from_core_early}\n{ly_join}\n"
                            f"WHERE {where_rebuilt}\n"
                            f"GROUP BY {', '.join(group_items_early)}"
                            f"{tail_clause};"
                        )

    def _find_top_level_kw(text: str, keyword: str, start: int = 0) -> int:
        def _is_word_boundary(src: str, pos: int, length: int) -> bool:
            left_ok = pos == 0 or not (src[pos - 1].isalnum() or src[pos - 1] == "_")
            right_ok = (pos + length) >= len(src) or not (src[pos + length].isalnum() or src[pos + length] == "_")
            return left_ok and right_ok

        w = keyword.lower()
        n = len(w)
        depth = 0
        in_sq = False
        in_dq = False
        in_bt = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq and not in_bt:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq and not in_bt:
                in_dq = not in_dq
                i += 1
                continue
            if ch == "`" and not in_sq and not in_dq:
                in_bt = not in_bt
                i += 1
                continue
            if in_sq or in_dq or in_bt:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i >= start and i + n <= len(text):
                if text[i:i + n].lower() == w and _is_word_boundary(text, i, n):
                    return i
            i += 1
        return -1

    def _parse_flat_outer(raw_sql: str) -> Optional[dict]:
        s = (raw_sql or "").strip().rstrip(";").strip()
        if not s or re.match(r"^\s*with\b", s, flags=re.I):
            return None
        if re.search(r"\b(?:from|join)\s*\(", s, flags=re.I):
            return None
        sel_pos = _find_top_level_kw(s, "select", 0)
        from_pos = _find_top_level_kw(s, "from", max(0, sel_pos + len("select")))
        group_pos = _find_top_level_kw(s, "group by", max(0, from_pos + len("from")))
        if sel_pos < 0 or from_pos < 0 or group_pos < 0:
            return None
        order_pos = _find_top_level_kw(s, "order by", group_pos + len("group by"))
        limit_pos = _find_top_level_kw(s, "limit", group_pos + len("group by"))
        tail_pos_candidates = [p for p in [order_pos, limit_pos] if p >= 0]
        group_end = min(tail_pos_candidates) if tail_pos_candidates else len(s)
        select_part = s[sel_pos + len("select"):from_pos].strip()
        from_part = s[from_pos + len("from"):group_pos].strip()
        groupby_part = s[group_pos + len("group by"):group_end].strip()
        tail_part = s[group_end:].strip() if group_end < len(s) else ""
        if not select_part or not from_part or not groupby_part:
            return None
        where_pos = _find_top_level_kw(from_part, "where", 0)
        if where_pos >= 0:
            from_core = from_part[:where_pos].strip()
            where_clause = from_part[where_pos:].strip()
        else:
            from_core = from_part
            where_clause = ""
        return {
            "select": select_part,
            "from_core": from_core,
            "where": where_clause,
            "groupby": groupby_part,
            "tail": tail_part,
        }

    parsed = _parse_flat_outer(sql)
    if not parsed or not parsed.get("where"):
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    if not alias_map:
        return sql

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if not analyzer and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(t or "").lower(): {str(c or "").lower() for c in (cols or set())}
                for t, cols in (allowed or {}).items()
                if str(t or "").strip()
            }
        except Exception:
            allowed_cols = {}

    def _plain_table_name(table_expr: str) -> str:
        return (table_expr or "").replace("`", "").split(".")[-1].strip()

    def _table_cols(table_name: str) -> Set[str]:
        t = _plain_table_name(table_name).lower()
        if not t:
            return set()
        cols = set(allowed_cols.get(t, set()))
        if analyzer is not None:
            try:
                cols.update(str(c or "").lower() for c in analyzer.get_table_columns(t))
            except Exception:
                pass
        return cols

    where_body = re.sub(r"^\s*WHERE\s+", "", parsed["where"].strip(), flags=re.I).strip()
    if not where_body or _has_top_level_or(where_body):
        return sql
    conjuncts = _split_top_level_and(where_body)
    if not conjuncts:
        return sql

    eq_pairs = list(
        re.finditer(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            from_core,
            flags=re.I,
        )
    )

    used_aliases = {a.lower() for a in alias_map.keys() if a}
    used_aliases.update(_plain_table_name(t).lower() for t in alias_map.values())

    def _pick_alias(base: str) -> str:
        seed = re.sub(r"[^A-Za-z0-9_]+", "_", (base or "")).strip("_") or "t"
        if not re.match(r"[A-Za-z_]", seed[0]):
            seed = f"t_{seed}"
        cand = seed
        idx = 2
        while cand.lower() in used_aliases:
            cand = f"{seed}_{idx}"
            idx += 1
        used_aliases.add(cand.lower())
        return cand

    def _replace_year_projection(text: str, ly_alias: str, date_alias: str, date_col: str) -> str:
        return re.sub(
            rf"(?is)YEAR\s*\(\s*`?{re.escape(date_alias)}`?\s*\.\s*`?{re.escape(date_col)}`?\s*\)",
            f"{ly_alias}.latest_year",
            text,
        )

    for idx, cond in enumerate(conjuncts):
        m = re.match(
            r"""(?is)^\s*
                \(\s*YEAR\s*\(\s*`?(?P<outer_date_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_date_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                \s*,\s*`?(?P<outer_entity_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<outer_entity_col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)
                \s+IN\s*\(\s*SELECT\s+
                (?:
                    MAX\s*\(\s*YEAR\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                  |
                    YEAR\s*\(\s*MAX\s*\(\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_date_col_2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*\)
                )
                \s*,\s*(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<sub_key_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s+FROM\s+`?(?P<sub_date_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?[A-Za-z_][A-Za-z0-9_]*`?)?
                \s+GROUP\s+BY\s+(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<group_col>[A-Za-z_][A-Za-z0-9_]*)`?
                \s*\)\s*$""",
            cond.strip(),
        )
        if not m:
            continue

        outer_date_alias = m.group("outer_date_alias")
        outer_date_col = m.group("outer_date_col")
        outer_entity_alias = m.group("outer_entity_alias")
        outer_entity_col = m.group("outer_entity_col")
        sub_date_col = (m.group("sub_date_col_1") or m.group("sub_date_col_2") or "").strip()
        sub_key_col = (m.group("sub_key_col") or "").strip()
        group_col = (m.group("group_col") or "").strip()
        sub_date_table = (m.group("sub_date_table") or "").strip()
        if not sub_date_col or not sub_key_col or not group_col or not sub_date_table:
            continue
        if sub_key_col.lower() != outer_entity_col.lower() or group_col.lower() != outer_entity_col.lower():
            continue

        outer_date_table = alias_map.get(outer_date_alias) or alias_map.get(outer_date_alias.lower())
        outer_entity_table = alias_map.get(outer_entity_alias) or alias_map.get(outer_entity_alias.lower())
        if not outer_date_table or not outer_entity_table:
            continue
        if _plain_table_name(outer_date_table).lower() != _plain_table_name(sub_date_table).lower():
            continue

        bridge_matches: List[Tuple[str, str, str]] = []
        for m_eq_date in eq_pairs:
            a1, c1, a2, c2 = m_eq_date.group(1), m_eq_date.group(2), m_eq_date.group(3), m_eq_date.group(4)
            a1l, a2l = a1.lower(), a2.lower()
            if a1l == outer_date_alias.lower() and a2l in alias_map and a2l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_fk_col = a2, c1, c2
            elif a2l == outer_date_alias.lower() and a1l in alias_map and a1l != outer_date_alias.lower():
                bridge_alias, date_join_col, bridge_fk_col = a1, c2, c1
            else:
                continue

            bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower()) or bridge_alias
            entity_join_ok = False
            for m_eq_entity in eq_pairs:
                b1, d1, b2, d2 = m_eq_entity.group(1), m_eq_entity.group(2), m_eq_entity.group(3), m_eq_entity.group(4)
                b1l, b2l = b1.lower(), b2.lower()
                if b1l == bridge_alias.lower() and b2l == outer_entity_alias.lower() and d1.lower() == outer_entity_col.lower() and d2.lower() == outer_entity_col.lower():
                    entity_join_ok = True
                    break
                if b2l == bridge_alias.lower() and b1l == outer_entity_alias.lower() and d2.lower() == outer_entity_col.lower() and d1.lower() == outer_entity_col.lower():
                    entity_join_ok = True
                    break
            if entity_join_ok:
                bridge_matches.append((bridge_alias, date_join_col, bridge_fk_col))

        if len(bridge_matches) != 1:
            continue

        bridge_alias, date_join_col, bridge_fk_col = bridge_matches[0]
        bridge_table = alias_map.get(bridge_alias) or alias_map.get(bridge_alias.lower()) or bridge_alias
        ly_alias = _pick_alias("latest_years")
        src_alias = _pick_alias("ly_src")
        dt_alias = _pick_alias("ly_dt")

        select_part = _replace_year_projection(parsed["select"].strip(), ly_alias, outer_date_alias, outer_date_col)
        group_items: List[str] = []
        seen_group: Set[str] = set()
        for item in _split_top_level_commas(parsed.get("groupby", "")):
            replaced = _replace_year_projection(item.strip(), ly_alias, outer_date_alias, outer_date_col).strip()
            if not replaced:
                continue
            key = replaced.lower()
            if key in seen_group:
                continue
            seen_group.add(key)
            group_items.append(replaced)
        if not group_items:
            continue

        ly_join = (
            "JOIN (\n"
            "  SELECT\n"
            f"    {src_alias}.{outer_entity_col} AS latest_key,\n"
            f"    MAX(YEAR({dt_alias}.{outer_date_col})) AS latest_year\n"
            f"  FROM {bridge_table} AS {src_alias}\n"
            f"  JOIN {outer_date_table} AS {dt_alias}\n"
            f"    ON {dt_alias}.{date_join_col} = {src_alias}.{bridge_fk_col}\n"
            f"  GROUP BY {src_alias}.{outer_entity_col}\n"
            f") AS {ly_alias}\n"
            f"  ON {ly_alias}.latest_key = {outer_entity_alias}.{outer_entity_col}"
        )

        remaining = [c.strip() for j, c in enumerate(conjuncts) if j != idx and c.strip()]
        remaining.append(f"YEAR({outer_date_alias}.{outer_date_col}) = {ly_alias}.latest_year")
        tail_clause = f"\n{parsed['tail'].strip()}" if parsed["tail"].strip() else ""
        fixed = (
            f"SELECT {select_part}\n"
            f"FROM {from_core}\n{ly_join}\n"
            f"WHERE {' AND '.join(remaining)}\n"
            f"GROUP BY {', '.join(group_items)}"
            f"{tail_clause};"
        )
        return fixed

    return sql


def _repair_unbalanced_not_exists_order_by(sql: str) -> str:
    """
    Close malformed NOT EXISTS subqueries when the model accidentally swallows
    the top-level ORDER BY into the subquery and leaves one unmatched "(".

    Example family:
      ... AND NOT EXISTS (SELECT 1 FROM ... WHERE ...)
      ORDER BY metric DESC

    emitted as:
      ... AND NOT EXISTS (SELECT 1 FROM ... WHERE ... ORDER BY metric DESC;

    Safety:
    - only when query contains NOT EXISTS and ORDER BY,
    - only when there is exactly one unmatched opening parenthesis,
    - only when the NOT EXISTS subquery has no closing ")" before the final
      ORDER BY candidate.
    """
    if not sql:
        return sql

    s = (sql or "").strip()
    if not s:
        return sql

    has_semicolon = s.endswith(";")
    body = s[:-1].rstrip() if has_semicolon else s
    low = body.lower()

    if "not exists" not in low or "order by" not in low:
        return sql
    if body.count("(") - body.count(")") != 1:
        return sql
    if not re.search(r"\b(?:group\s+by|having)\b", low, flags=re.I):
        return sql

    order_match = None
    for m in re.finditer(r"\border\s+by\b", low, flags=re.I):
        order_match = m
    if not order_match:
        return sql
    order_idx = order_match.start()

    not_exists_match = None
    for m in re.finditer(r"\bnot\s+exists\s*\(", low, flags=re.I):
        if m.start() < order_idx:
            not_exists_match = m
    if not not_exists_match:
        return sql

    open_idx = body.find("(", not_exists_match.start())
    if open_idx < 0 or open_idx >= order_idx:
        return sql

    depth = 0
    in_sq = False
    in_dq = False
    in_bt = False
    closed_before_order = False
    i = open_idx
    while i < order_idx:
        ch = body[i]
        if ch == "'" and not in_dq and not in_bt:
            if in_sq and i + 1 < order_idx and body[i + 1] == "'":
                i += 2
                continue
            in_sq = not in_sq
            i += 1
            continue
        if ch == '"' and not in_sq and not in_bt:
            if in_dq and i + 1 < order_idx and body[i + 1] == '"':
                i += 2
                continue
            in_dq = not in_dq
            i += 1
            continue
        if ch == "`" and not in_sq and not in_dq:
            in_bt = not in_bt
            i += 1
            continue
        if in_sq or in_dq or in_bt:
            i += 1
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth = max(0, depth - 1)
            if depth == 0:
                closed_before_order = True
                break
        i += 1

    if closed_before_order or depth != 1:
        return sql

    fixed = f"{body[:order_idx].rstrip()}) {body[order_idx:].lstrip()}"
    if has_semicolon:
        fixed += ";"
    return fixed


def _choose_preferred_temporal_column(
    table_name: str,
    temporal_cols: List[str],
    hint_columns: Optional[List[str]] = None,
    question: str = "",
) -> str:
    """
    Pick a temporal column conservatively and schema-driven.

    Strategy:
    - honor explicit hint columns when they directly match
    - if only one temporal column exists, use it
    - otherwise score using lexical overlap (hints/question/metadata) and
      return only when there is a unique strongest candidate
    """
    table_l = str(table_name or "").replace("`", "").split(".")[-1].strip().lower()
    raw_cols = [str(c or "").strip().lower() for c in (temporal_cols or []) if str(c or "").strip()]
    if not raw_cols:
        return ""

    cols: List[str] = []
    seen_cols: Set[str] = set()
    for c in raw_cols:
        if c in seen_cols:
            continue
        seen_cols.add(c)
        cols.append(c)
    if not cols:
        return ""

    hints = [str(h or "").strip().lower() for h in (hint_columns or []) if str(h or "").strip()]
    for h in hints:
        if h in seen_cols:
            return h

    if len(cols) == 1:
        return cols[0]

    def _tokens(text: str) -> Set[str]:
        raw = str(text or "").strip()
        if not raw:
            return set()
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ").lower()
        return {tok for tok in re.findall(r"[a-z0-9]+", raw) if tok}

    cue_tokens: Set[str] = set()
    for h in hints:
        cue_tokens.update(_tokens(h))
    cue_tokens.update(_tokens(question or ""))
    cue_tokens -= HELPERS_TEMPORAL_FALLBACK_STOP_TOKENS

    scored: List[Tuple[int, str]] = []
    for col in cols:
        tokens = set(_tokens(col))
        meta_tokens: Set[str] = set()

        if table_l:
            try:
                role_l = str(get_column_role(table_l, col) or "").strip().lower()
            except Exception:
                role_l = ""
            if role_l:
                meta_tokens.update(_tokens(role_l))
            try:
                desc_txt = str(get_column_description(table_l, col) or "").strip()
            except Exception:
                desc_txt = ""
            if desc_txt:
                meta_tokens.update(_tokens(desc_txt))

        overlap = len((tokens | meta_tokens) & cue_tokens)
        score = HELPERS_TEMPORAL_FALLBACK_OVERLAP_WEIGHT * overlap

        # Mild generic bias: date-like fields are typically safer targets for YEAR(...).
        if "date" in tokens:
            score += HELPERS_TEMPORAL_FALLBACK_DATE_BIAS
        if "timestamp" in tokens or "time" in tokens:
            score += HELPERS_TEMPORAL_FALLBACK_TIME_BIAS
        if HELPERS_TEMPORAL_FALLBACK_META_TOKENS & meta_tokens:
            score += HELPERS_TEMPORAL_FALLBACK_META_BIAS

        scored.append((score, col))

    scored.sort(key=lambda x: x[0], reverse=True)
    if not scored:
        return ""
    if scored[0][0] <= 0:
        return ""
    if len(scored) > 1 and scored[0][0] == scored[1][0]:
        return ""
    return scored[0][1]


def _rewrite_temporal_year_exclusion_antijoin(sql: str, question: str, ctx: str = "") -> str:
    """
    Canonicalize exclusion-by-year anti-joins when an aggregate query uses a
    bridge table plus a missing temporal table, e.g.:

      WHERE YEAR(p.orderDate) = 2004
        AND NOT p.productCode IN (
          SELECT productCode
          FROM orderdetails
          WHERE YEAR(orderNumber) = 2005
        )

    into a bridge-aware outer temporal join plus correlated NOT EXISTS.

    Safety:
    - only runs on flat grouped queries,
    - requires explicit exclusion wording and two distinct years,
    - requires a unique FK path from the bridge fact table to a temporal table,
    - preserves existing non-temporal predicates/tail/grouping.
    """
    if not sql or not question:
        return sql

    q = (question or "").lower()
    if not re.search(r"\b(?:never|without|exclude|excluding|not\b)", q):
        return sql

    year_tokens = [m.group(0) for m in re.finditer(r"\b(?:19|20)\d{2}\b", question or "")]
    ordered_years: List[str] = []
    seen_years: Set[str] = set()
    for y in year_tokens:
        if y not in seen_years:
            seen_years.add(y)
            ordered_years.append(y)
    if len(ordered_years) < 2:
        return sql

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        # Relaxed fallback for flat GROUP BY queries with HAVING.
        # We intentionally ignore HAVING in the rewrite output because this
        # repair's job is to rebuild the temporal bridge and anti-existence
        # shape; malformed HAVING content is usually part of the corruption.
        s = (sql or "").strip().rstrip(";").strip()
        if not re.search(r"\bGROUP\s+BY\b", s, flags=re.I):
            return sql
        if re.search(r"\b(?:FROM|JOIN)\s*\(", s, flags=re.I):
            return sql

        m_sel = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<after>.+)$", s)
        if not m_sel:
            return sql
        select_part = (m_sel.group("select") or "").strip()
        after_from = (m_sel.group("after") or "").strip()

        gb_matches = list(re.finditer(r"\bGROUP\s+BY\b", after_from, flags=re.I))
        if not gb_matches:
            return sql
        gb_m = gb_matches[-1]
        from_and_maybe_where = after_from[:gb_m.start()].strip()
        after_gb = after_from[gb_m.end():].strip()
        if not from_and_maybe_where or not after_gb:
            return sql

        next_kw = re.search(r"\b(HAVING|ORDER\s+BY|LIMIT)\b", after_gb, flags=re.I)
        if next_kw:
            groupby_part = after_gb[:next_kw.start()].strip()
            rem = after_gb[next_kw.start():].strip()
        else:
            groupby_part = after_gb.strip()
            rem = ""
        if not groupby_part:
            return sql

        having_part = ""
        tail_part = ""
        if rem:
            if re.match(r"(?is)^HAVING\b", rem):
                h_body = re.sub(r"(?is)^HAVING\s+", "", rem).strip()
                h_next = re.search(r"\b(ORDER\s+BY|LIMIT)\b", h_body, flags=re.I)
                if h_next:
                    having_part = h_body[:h_next.start()].strip()
                    tail_part = h_body[h_next.start():].strip()
                else:
                    having_part = h_body
            else:
                tail_part = rem

        where_match = re.search(r"\bWHERE\b", from_and_maybe_where, flags=re.I)
        if where_match:
            from_core = from_and_maybe_where[:where_match.start()].strip()
            where_part = from_and_maybe_where[where_match.start():].strip()
        else:
            from_core = from_and_maybe_where
            where_part = ""

        parsed = {
            "select": select_part,
            "from_core": from_core,
            "where": where_part,
            "groupby": groupby_part,
            "having": having_part,
            "tail": tail_part,
        }

    if not parsed or not parsed.get("where"):
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if not from_core:
        return sql

    alias_map = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}")
    explicit_aliases: Dict[str, str] = {}
    for m in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?""",
        f"FROM {from_core}",
    ):
        table_expr = (m.group(1) or "").strip()
        if not table_expr or table_expr.startswith("("):
            continue
        table_plain = str(table_expr).replace("`", "").split(".")[-1].strip()
        alias_name = (m.group(2) or "").strip() or table_plain
        explicit_aliases[alias_name.lower()] = table_plain

    if not explicit_aliases:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if not analyzer and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(t or "").lower(): {str(c or "").lower() for c in (cols or set())}
                for t, cols in (allowed or {}).items()
                if str(t or "").strip()
            }
        except Exception:
            allowed_cols = {}

    fk_map_raw = {}
    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}

    fk_map: Dict[str, Dict[str, str]] = {}
    for src, rels in fk_map_raw.items():
        src_l = str(src or "").lower().strip()
        if not src_l:
            continue
        fk_map.setdefault(src_l, {})
        for fk_col, tgt in (rels or {}).items():
            fk_l = str(fk_col or "").lower().strip()
            tgt_l = str(tgt or "").lower().strip()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    def _plain_table_name(table_expr: str) -> str:
        return (table_expr or "").replace("`", "").split(".")[-1].strip()

    def _table_cols(table_name: str) -> Set[str]:
        tbl_l = _plain_table_name(table_name).lower()
        if not tbl_l:
            return set()
        cols = set(allowed_cols.get(tbl_l, set()))
        if analyzer is not None:
            try:
                cols.update(str(c or "").lower() for c in analyzer.get_table_columns(tbl_l))
            except Exception:
                pass
        return cols

    def _temporal_cols_for_table(table_name: str) -> List[str]:
        cols = []
        for col in sorted(_table_cols(table_name)):
            if any(k in col for k in ("date", "time", "timestamp")):
                cols.append(col)
        return cols

    def _pick_alias(base: str, used: Set[str]) -> str:
        seed = re.sub(r"[^A-Za-z0-9_]+", "_", (base or "")).strip("_") or "t"
        if not re.match(r"[A-Za-z_]", seed[0]):
            seed = f"t_{seed}"
        cand = seed
        idx = 2
        while cand.lower() in used:
            cand = f"{seed}_{idx}"
            idx += 1
        used.add(cand.lower())
        return cand

    def _parse_simple_ref(expr: str) -> Optional[Tuple[Optional[str], str]]:
        m = re.match(
            r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
            (expr or "").strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    eq_pairs = list(
        re.finditer(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            from_core,
            flags=re.I,
        )
    )

    where_raw = re.sub(r"^\s*WHERE\s+", "", (parsed.get("where") or "").strip(), flags=re.I).strip()
    if not where_raw or _has_top_level_or(where_raw):
        return sql
    conjuncts = _split_top_level_and(where_raw)
    if not conjuncts:
        return sql

    outer_year_idx = -1
    outer_year_value = ""
    outer_missing_alias = ""
    outer_missing_col = ""
    for idx, cond in enumerate(conjuncts):
        m_outer = re.match(
            r"""(?is)^\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*((?:19|20)\d{2})\s*$""",
            cond.strip(),
        )
        if not m_outer:
            continue
        alias_name, col_name, yr = m_outer.group(1), m_outer.group(2), m_outer.group(3)
        table_name = explicit_aliases.get(alias_name.lower()) or alias_map.get(alias_name.lower()) or ""
        if table_name and col_name.lower() in _table_cols(table_name):
            continue
        outer_year_idx = idx
        outer_year_value = yr
        outer_missing_alias = alias_name
        outer_missing_col = col_name
        break

    anti_idx = -1
    outer_entity_ref: Optional[Tuple[Optional[str], str]] = None
    inner_table = ""
    inner_key_col = ""
    inner_year_value = ""
    for idx, cond in enumerate(conjuncts):
        txt = cond.strip()
        m_anti = re.match(
            r"""(?is)^\s*(?:NOT\s+)?(?P<outer_ref>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+(?:NOT\s+)?IN\s*\(\s*SELECT\s+(?P<inner_key>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+FROM\s+`?(?P<inner_table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?`?(?P<inner_alias>[A-Za-z_][A-Za-z0-9_]*)`?)?\s+WHERE\s+(?P<inner_where>.+)\)\s*$""",
            txt,
        )
        if not m_anti:
            continue
        inner_where = (m_anti.group("inner_where") or "").strip()
        if _has_top_level_or(inner_where):
            continue
        inner_conj = _split_top_level_and(inner_where)
        yr_match = None
        for inner_cond in inner_conj:
            yr_match = re.match(
                r"""(?is)^\s*YEAR\s*\(\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*((?:19|20)\d{2})\s*$""",
                inner_cond.strip(),
            )
            if yr_match:
                break
        if not yr_match:
            continue
        anti_idx = idx
        outer_entity_ref = _parse_simple_ref(m_anti.group("outer_ref"))
        inner_key_ref = _parse_simple_ref(m_anti.group("inner_key"))
        if not outer_entity_ref or not inner_key_ref:
            anti_idx = -1
            continue
        inner_table = (m_anti.group("inner_table") or "").strip()
        inner_key_col = inner_key_ref[1]
        inner_year_value = yr_match.group(3)
        break

    if outer_year_idx < 0 or anti_idx < 0 or not outer_entity_ref or not inner_table or not inner_key_col:
        return sql

    outer_entity_alias, outer_entity_col = outer_entity_ref
    if not outer_entity_alias:
        return sql

    # Prefer the visible alias whose table matches the anti-join bridge table and
    # is directly equated to the outer entity key.
    bridge_candidates: List[Tuple[int, str, str, str, str]] = []
    for alias_name, table_name in explicit_aliases.items():
        if _plain_table_name(table_name).lower() != _plain_table_name(inner_table).lower():
            continue
        for fk_col, tgt_table in fk_map.get(_plain_table_name(table_name).lower(), {}).items():
            temporal_cols = _temporal_cols_for_table(tgt_table)
            if not temporal_cols:
                continue
            mapped_bridge_col = ""
            for m_eq in eq_pairs:
                a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
                a1l, a2l = a1.lower(), a2.lower()
                if a1l == alias_name.lower() and a2l == outer_entity_alias.lower() and c2.lower() == outer_entity_col.lower():
                    mapped_bridge_col = c1
                    break
                if a2l == alias_name.lower() and a1l == outer_entity_alias.lower() and c1.lower() == outer_entity_col.lower():
                    mapped_bridge_col = c2
                    break
            if not mapped_bridge_col or mapped_bridge_col.lower() != inner_key_col.lower():
                continue
            preferred_temporal_col = _choose_preferred_temporal_column(
                tgt_table,
                temporal_cols,
                hint_columns=[outer_missing_col] if outer_missing_col else [],
                question=question,
            )
            if not preferred_temporal_col:
                continue
            target_pk = (get_id_column(tgt_table) or "").strip()
            if not target_pk or target_pk.lower() not in _table_cols(tgt_table):
                if fk_col.lower() in _table_cols(tgt_table):
                    target_pk = fk_col
                else:
                    continue
            score = 0
            if outer_year_value == ordered_years[0]:
                score += 1
            bridge_candidates.append((score, alias_name, table_name, fk_col, tgt_table, preferred_temporal_col, target_pk))

    if len(bridge_candidates) != 1:
        return sql

    _score, bridge_alias, bridge_table, bridge_fk_col, temporal_table, temporal_col, temporal_pk = bridge_candidates[0]
    used_aliases = set(explicit_aliases.keys())
    outer_temporal_alias = next((a for a, t in explicit_aliases.items() if _plain_table_name(t).lower() == _plain_table_name(temporal_table).lower()), "")
    join_to_add = ""
    if not outer_temporal_alias:
        outer_temporal_alias = _pick_alias(f"{_plain_table_name(temporal_table)}_outer", used_aliases)
        join_to_add = (
            f"\nJOIN {temporal_table} AS {outer_temporal_alias} "
            f"ON {outer_temporal_alias}.{temporal_pk} = {bridge_alias}.{bridge_fk_col}"
        )

    anti_bridge_alias = _pick_alias("anti_src", used_aliases)
    anti_temporal_alias = _pick_alias("anti_dt", used_aliases)
    anti_not_exists = (
        "NOT EXISTS (\n"
        "  SELECT 1\n"
        f"  FROM {bridge_table} AS {anti_bridge_alias}\n"
        f"  JOIN {temporal_table} AS {anti_temporal_alias}\n"
        f"    ON {anti_temporal_alias}.{temporal_pk} = {anti_bridge_alias}.{bridge_fk_col}\n"
        f"  WHERE {anti_bridge_alias}.{inner_key_col} = {outer_entity_alias}.{outer_entity_col}\n"
        f"    AND YEAR({anti_temporal_alias}.{temporal_col}) = {inner_year_value}\n"
        ")"
    )

    remaining_conds = [c.strip() for j, c in enumerate(conjuncts) if j not in {outer_year_idx, anti_idx} and c.strip()]
    remaining_conds.insert(0, f"YEAR({outer_temporal_alias}.{temporal_col}) = {outer_year_value or ordered_years[0]}")
    remaining_conds.append(anti_not_exists)

    tail_clause = f"\n{parsed['tail'].strip()}" if parsed["tail"].strip() else ""
    fixed = (
        f"SELECT {parsed['select'].strip()}\n"
        f"FROM {from_core}{join_to_add}\n"
        f"WHERE {' AND '.join(remaining_conds)}\n"
        f"GROUP BY {parsed['groupby'].strip()}"
        f"{tail_clause};"
    )
    return fixed


def _rewrite_two_table_grouped_temporal_exclusion(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair grouped two-table exclusion queries that aggregate on an entity +
    bridge fact table but apply year filters on non-temporal columns and/or
    embed malformed anti-existence logic in HAVING/WHERE.

    Canonical family:
      SELECT entity_id, entity_name, SUM(metric)
      FROM entity e
      JOIN bridge b ON ...
      WHERE YEAR(e.orderDate) = 2004 AND YEAR(b.orderNumber) = 2004
      GROUP BY ...
      HAVING ... AND NOT EXISTS (...)
      ORDER BY ...

    Rewritten to:
      SELECT ...
      FROM entity e
      JOIN bridge b ON ...
      JOIN temporal t ON t.pk = b.fk
      WHERE YEAR(t.date_col) = 2004
        AND NOT EXISTS (
          SELECT 1
          FROM bridge anti_src
          JOIN temporal anti_dt ON anti_dt.pk = anti_src.fk
          WHERE anti_src.entity_fk = e.entity_id
            AND YEAR(anti_dt.date_col) = 2005
        )
      GROUP BY ...
      ORDER BY ...

    Safety:
    - only for flat grouped queries,
    - only when question contains explicit exclusion wording and 2 distinct years,
    - only when FROM has exactly two base tables with a unique bridge->temporal FK,
    - preserves non-temporal predicates and top-level ORDER BY/LIMIT tail.
    """
    if not sql or not question:
        return sql

    q = (question or "").lower()
    if not re.search(r"\b(?:never|without|exclude|excluding|not\b)\b", q):
        return sql

    year_tokens = [m.group(0) for m in re.finditer(r"\b(?:19|20)\d{2}\b", question or "")]
    ordered_years: List[str] = []
    seen_years: Set[str] = set()
    for y in year_tokens:
        if y not in seen_years:
            seen_years.add(y)
            ordered_years.append(y)
    if len(ordered_years) < 2:
        return sql

    s = _repair_unbalanced_not_exists_order_by(sql)
    body = s.strip().rstrip(";").strip()
    if not re.search(r"\bGROUP\s+BY\b", body, flags=re.I):
        return sql
    if re.search(r"\b(?:FROM|JOIN)\s*\(", body, flags=re.I):
        return sql

    m_sel = re.match(r"(?is)^\s*SELECT\s+(?P<select>.+?)\s+FROM\s+(?P<after>.+)$", body)
    if not m_sel:
        return sql
    select_part = (m_sel.group("select") or "").strip()
    after_from = (m_sel.group("after") or "").strip()

    gb_matches = list(re.finditer(r"\bGROUP\s+BY\b", after_from, flags=re.I))
    if not gb_matches:
        return sql
    gb_m = gb_matches[-1]
    from_and_maybe_where = after_from[:gb_m.start()].strip()
    after_gb = after_from[gb_m.end():].strip()
    if not from_and_maybe_where or not after_gb:
        return sql

    next_kw = re.search(r"\b(HAVING|ORDER\s+BY|LIMIT)\b", after_gb, flags=re.I)
    if next_kw:
        groupby_part = after_gb[:next_kw.start()].strip()
        rem = after_gb[next_kw.start():].strip()
    else:
        groupby_part = after_gb.strip()
        rem = ""
    if not groupby_part:
        return sql

    tail_part = ""
    if rem:
        if re.match(r"(?is)^HAVING\b", rem):
            h_body = re.sub(r"(?is)^HAVING\s+", "", rem).strip()
            h_next = re.search(r"\b(ORDER\s+BY|LIMIT)\b", h_body, flags=re.I)
            if h_next:
                tail_part = h_body[h_next.start():].strip()
        else:
            tail_part = rem

    where_match = re.search(r"\bWHERE\b", from_and_maybe_where, flags=re.I)
    if where_match:
        from_core = from_and_maybe_where[:where_match.start()].strip()
        where_part = from_and_maybe_where[where_match.start():].strip()
    else:
        from_core = from_and_maybe_where
        where_part = ""
    if not where_part:
        return sql

    ordered_aliases: List[Tuple[str, str]] = []
    explicit_aliases: Dict[str, str] = {}
    for m in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?""",
        f"FROM {from_core}",
    ):
        table_expr = (m.group(1) or "").strip()
        if not table_expr or table_expr.startswith("("):
            continue
        table_plain = table_expr.replace("`", "").split(".")[-1].strip()
        alias_name = (m.group(2) or "").strip() or table_plain
        if not alias_name:
            continue
        ordered_aliases.append((alias_name, table_plain))
        explicit_aliases[alias_name.lower()] = table_plain
    if len(ordered_aliases) != 2:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(t or "").lower(): {str(c or "").lower() for c in (cols or set())}
                for t, cols in (allowed or {}).items()
                if str(t or "").strip()
            }
        except Exception:
            allowed_cols = {}

    def _table_cols(table_name: str) -> Set[str]:
        tbl_l = str(table_name or "").replace("`", "").split(".")[-1].lower().strip()
        if not tbl_l:
            return set()
        cols = set(allowed_cols.get(tbl_l, set()))
        if analyzer is not None:
            try:
                cols.update(str(c or "").lower() for c in analyzer.get_table_columns(tbl_l))
            except Exception:
                pass
        return cols

    def _temporal_cols_for_table(table_name: str) -> List[str]:
        return [
            c for c in sorted(_table_cols(table_name))
            if any(k in c for k in ("date", "time", "timestamp"))
        ]

    fk_map_raw = {}
    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, rels in fk_map_raw.items():
        src_l = str(src or "").lower().strip()
        if not src_l:
            continue
        fk_map.setdefault(src_l, {})
        for fk_col, tgt in (rels or {}).items():
            fk_l = str(fk_col or "").lower().strip()
            tgt_l = str(tgt or "").lower().strip()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    outer_alias, outer_table = ordered_aliases[0]
    bridge_alias, bridge_table = ordered_aliases[1]
    outer_cols = _table_cols(outer_table)
    outer_id_col = ""
    try:
        outer_id_col = (get_id_column(outer_table) or "").strip()
    except Exception:
        outer_id_col = ""
    if not outer_id_col or outer_id_col.lower() not in outer_cols:
        for item in _split_top_level_commas(groupby_part):
            m_outer = re.match(
                rf"""(?is)^\s*`?{re.escape(outer_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
                (item or "").strip(),
            )
            if not m_outer:
                continue
            cand = (m_outer.group(1) or "").strip()
            cand_l = cand.lower()
            if cand_l in outer_cols and (
                cand_l.endswith("id")
                or cand_l.endswith("number")
                or cand_l.endswith("code")
                or cand_l.endswith("key")
            ):
                outer_id_col = cand
                break
    if not outer_id_col or outer_id_col.lower() not in outer_cols:
        return sql

    eq_pairs = list(
        re.finditer(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            from_core,
            flags=re.I,
        )
    )
    bridge_outer_col = ""
    for m_eq in eq_pairs:
        a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
        if a1.lower() == outer_alias.lower() and a2.lower() == bridge_alias.lower() and c1.lower() == outer_id_col.lower():
            bridge_outer_col = c2
            break
        if a2.lower() == outer_alias.lower() and a1.lower() == bridge_alias.lower() and c2.lower() == outer_id_col.lower():
            bridge_outer_col = c1
            break
    if not bridge_outer_col:
        return sql

    year_refs = re.findall(
        r"""(?is)YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*((?:19|20)\d{2})""",
        where_part,
    )

    temporal_bridge_candidates: List[Tuple[str, str, str, str]] = []
    for fk_col, tgt_table in fk_map.get(bridge_table.lower(), {}).items():
        temporal_cols = _temporal_cols_for_table(tgt_table)
        if not temporal_cols:
            continue
        hint_cols: List[str] = []
        for alias_name, col_name, _yr in year_refs:
            if alias_name.lower() not in {outer_alias.lower(), bridge_alias.lower()}:
                continue
            hint_cols.append(col_name)
        preferred_temporal_col = _choose_preferred_temporal_column(
            tgt_table,
            temporal_cols,
            hint_columns=hint_cols,
            question=question,
        )
        if not preferred_temporal_col:
            continue
        try:
            temporal_pk = (get_id_column(tgt_table) or "").strip()
        except Exception:
            temporal_pk = ""
        target_cols = _table_cols(tgt_table)
        if not temporal_pk or temporal_pk.lower() not in target_cols:
            if fk_col.lower() in target_cols:
                temporal_pk = fk_col
            else:
                continue
        temporal_bridge_candidates.append((fk_col, tgt_table, preferred_temporal_col, temporal_pk))

    temporal_bridge_candidates = list(dict.fromkeys(temporal_bridge_candidates))
    if len(temporal_bridge_candidates) != 1:
        return sql

    bridge_fk_col, temporal_table, temporal_col, temporal_pk = temporal_bridge_candidates[0]
    include_year = ordered_years[0]
    exclude_year = ordered_years[1]

    def _pick_alias(base: str, used: Set[str]) -> str:
        seed = re.sub(r"[^A-Za-z0-9_]+", "_", (base or "")).strip("_") or "t"
        if not re.match(r"[A-Za-z_]", seed[0]):
            seed = f"t_{seed}"
        cand = seed
        idx = 2
        while cand.lower() in used:
            cand = f"{seed}_{idx}"
            idx += 1
        used.add(cand.lower())
        return cand

    used_aliases = {a.lower() for a in explicit_aliases.keys()}
    temporal_alias = _pick_alias(f"{temporal_table}_outer", used_aliases)
    anti_bridge_alias = _pick_alias("anti_src", used_aliases)
    anti_temporal_alias = _pick_alias("anti_dt", used_aliases)

    where_body = re.sub(r"^\s*WHERE\s+", "", where_part.strip(), flags=re.I).strip()
    if not where_body or _has_top_level_or(where_body):
        return sql
    conjuncts = _split_top_level_and(where_body)
    if not conjuncts:
        return sql

    remaining: List[str] = []
    for cond in conjuncts:
        cond_s = (cond or "").strip()
        if not cond_s:
            continue
        if re.match(
            r"""(?is)^\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*((?:19|20)\d{2})\s*$""",
            cond_s,
        ):
            continue
        if re.search(r"\bNOT\s+EXISTS\b|\bNOT\b\s+.+\bIN\s*\(", cond_s, flags=re.I):
            continue
        remaining.append(cond_s)

    remaining.insert(0, f"YEAR({temporal_alias}.{temporal_col}) = {include_year}")
    remaining.append(
        "NOT EXISTS (\n"
        "  SELECT 1\n"
        f"  FROM {bridge_table} AS {anti_bridge_alias}\n"
        f"  JOIN {temporal_table} AS {anti_temporal_alias}\n"
        f"    ON {anti_temporal_alias}.{temporal_pk} = {anti_bridge_alias}.{bridge_fk_col}\n"
        f"  WHERE {anti_bridge_alias}.{bridge_outer_col} = {outer_alias}.{outer_id_col}\n"
        f"    AND YEAR({anti_temporal_alias}.{temporal_col}) = {exclude_year}\n"
        ")"
    )

    tail_clause = f"\n{tail_part}" if tail_part else ""
    fixed = (
        f"SELECT {select_part}\n"
        f"FROM {from_core}\n"
        f"JOIN {temporal_table} AS {temporal_alias} "
        f"ON {temporal_alias}.{temporal_pk} = {bridge_alias}.{bridge_fk_col}\n"
        f"WHERE {' AND '.join(remaining)}\n"
        f"GROUP BY {groupby_part}"
        f"{tail_clause};"
    )
    return fixed


def _rewrite_missing_temporal_bridge_exclusion(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair exclusion-by-year aggregate queries when the SQL applies YEAR(...)
    filters to non-temporal aliases and omits the temporal bridge entirely.

    Canonical near-miss:
      SELECT entity_id, ..., SUM(bridge.metric)
      FROM entity e
      JOIN bridge b ON ...
      WHERE YEAR(e.orderDate) = 2004 AND YEAR(b.orderDate) = 2004
      GROUP BY ...

    Rewritten to:
      ... JOIN temporal_table t ON ...
      WHERE YEAR(t.date_col) = 2004
        AND NOT EXISTS (... YEAR(t2.date_col) = 2005 ...)

    Safety:
    - only for grouped flat queries
    - only when question explicitly contains exclusion wording and two years
    - only when malformed YEAR(alias.col)=year points to aliases whose tables do
      not own that temporal column
    - only when there is a unique bridge->temporal FK path and a direct bridge
      correlation back to the grouped entity
    """
    if not sql or not question:
        return sql

    q = (question or "").lower()
    if not re.search(r"\b(?:not|without|exclude|excluding|never)\b", q):
        return sql

    year_tokens = [m.group(0) for m in re.finditer(r"\b(?:19|20)\d{2}\b", question or "")]
    ordered_years: List[str] = []
    seen_years: Set[str] = set()
    for y in year_tokens:
        if y not in seen_years:
            seen_years.add(y)
            ordered_years.append(y)
    if len(ordered_years) < 2:
        return sql

    parsed = _parse_select_from_groupby(sql)
    if not parsed or not parsed.get("where"):
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if not from_core or re.search(r"\bNOT\s+EXISTS\b|\bNOT\s+IN\s*\(", from_core, flags=re.I):
        return sql

    explicit_aliases: Dict[str, str] = {}
    ordered_aliases: List[Tuple[str, str]] = []
    for m in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?""",
        f"FROM {from_core}",
    ):
        table_expr = (m.group(1) or "").strip()
        if not table_expr or table_expr.startswith("("):
            continue
        table_plain = table_expr.replace("`", "").split(".")[-1].strip()
        alias_name = (m.group(2) or "").strip() or table_plain
        if not alias_name:
            continue
        explicit_aliases[alias_name.lower()] = table_plain
        ordered_aliases.append((alias_name, table_plain))
    if not ordered_aliases:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if not analyzer and ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(t or "").lower(): {str(c or "").lower() for c in (cols or set())}
                for t, cols in (allowed or {}).items()
                if str(t or "").strip()
            }
        except Exception:
            allowed_cols = {}

    fk_map_raw = {}
    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, rels in fk_map_raw.items():
        src_l = str(src or "").lower().strip()
        if not src_l:
            continue
        fk_map.setdefault(src_l, {})
        for fk_col, tgt in (rels or {}).items():
            fk_l = str(fk_col or "").lower().strip()
            tgt_l = str(tgt or "").lower().strip()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    def _plain_table_name(table_expr: str) -> str:
        return (table_expr or "").replace("`", "").split(".")[-1].strip()

    def _table_cols(table_name: str) -> Set[str]:
        tbl_l = _plain_table_name(table_name).lower()
        cols = set(allowed_cols.get(tbl_l, set()))
        if analyzer is not None:
            try:
                cols.update(str(c or "").lower() for c in analyzer.get_table_columns(tbl_l))
            except Exception:
                pass
        return cols

    def _temporal_cols_for_table(table_name: str) -> List[str]:
        return [
            c for c in sorted(_table_cols(table_name))
            if any(k in c for k in ("date", "time", "timestamp"))
        ]

    def _looks_temporal_col(table_name: str, col_name: str) -> bool:
        col_l = str(col_name or "").lower().strip()
        if not col_l:
            return False
        if any(k in col_l for k in ("date", "time", "timestamp", "year", "month", "day")):
            return True
        try:
            role = str(get_column_role(table_name, col_name) or "").lower().strip()
        except Exception:
            role = ""
        if not role:
            return False
        return any(k in role for k in ("date", "time", "timestamp", "temporal", "year", "month", "day"))

    def _pick_alias(base: str, used: Set[str]) -> str:
        seed = re.sub(r"[^A-Za-z0-9_]+", "_", (base or "")).strip("_") or "t"
        if not re.match(r"[A-Za-z_]", seed[0]):
            seed = f"t_{seed}"
        cand = seed
        idx = 2
        while cand.lower() in used:
            cand = f"{seed}_{idx}"
            idx += 1
        used.add(cand.lower())
        return cand

    where_raw = re.sub(r"^\s*WHERE\s+", "", (parsed.get("where") or "").strip(), flags=re.I).strip()
    if not where_raw or _has_top_level_or(where_raw):
        return sql
    conjuncts = _split_top_level_and(where_raw)
    if not conjuncts:
        return sql

    invalid_year_conds: List[Tuple[int, str, str, str, str]] = []
    valid_temporal_year_conds: List[Tuple[int, str, str, str, str]] = []
    for idx, cond in enumerate(conjuncts):
        m_year = re.match(
            r"""(?is)^\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*((?:19|20)\d{2})\s*$""",
            cond.strip(),
        )
        if not m_year:
            continue
        alias_name, col_name, yr = m_year.group(1), m_year.group(2), m_year.group(3)
        table_name = explicit_aliases.get(alias_name.lower(), "")
        if not table_name:
            continue
        table_cols = _table_cols(table_name)
        if col_name.lower() in table_cols and _looks_temporal_col(table_name, col_name):
            valid_temporal_year_conds.append((idx, alias_name, table_name, col_name, yr))
            continue
        invalid_year_conds.append((idx, alias_name, table_name, col_name, yr))

    if not invalid_year_conds:
        # Fallback: exclusion questions occasionally degrade into two positive
        # YEAR(...) predicates (e.g., include-year + exclude-year) without any
        # anti-existence shape. Treat this as malformed exclusion and route it
        # through the same schema-driven bridge rewrite below.
        if re.search(r"\bNOT\s+EXISTS\b|\bNOT\s+IN\s*\(", where_raw, flags=re.I):
            return sql

        target_years = list(dict.fromkeys(ordered_years[:2]))
        if len(target_years) < 2:
            return sql

        valid_by_target_year = [
            item for item in valid_temporal_year_conds
            if item[4] in set(target_years)
        ]
        seen_valid_years = {item[4] for item in valid_by_target_year}
        if len(seen_valid_years) < 2:
            return sql

        include_year_target = target_years[0]
        invalid_year_conds = sorted(
            valid_by_target_year,
            key=lambda item: (item[4] != include_year_target, item[0]),
        )
        if not invalid_year_conds:
            return sql

    include_year = invalid_year_conds[0][4]
    exclude_year = next((y for y in ordered_years if y != include_year), "")
    if not exclude_year:
        return sql

    groupby_part = (parsed.get("groupby") or "").strip()

    # Fast path: two-table entity + bridge aggregate with malformed temporal
    # YEAR filters but no temporal table joined yet.
    if len(ordered_aliases) == 2:
        outer_alias, outer_table = ordered_aliases[0]
        bridge_alias, bridge_table = ordered_aliases[1]
        outer_cols = _table_cols(outer_table)
        outer_id_col = ""
        try:
            outer_id_col = (get_id_column(outer_table) or "").strip()
        except Exception:
            outer_id_col = ""
        if not outer_id_col or outer_id_col.lower() not in outer_cols:
            for item in _split_top_level_commas(groupby_part):
                m_outer = re.match(
                    rf"""(?is)^\s*`?{re.escape(outer_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
                    (item or "").strip(),
                )
                if not m_outer:
                    continue
                cand = (m_outer.group(1) or "").strip()
                cand_l = cand.lower()
                if cand_l in outer_cols and (
                    cand_l.endswith("id")
                    or cand_l.endswith("number")
                    or cand_l.endswith("code")
                    or cand_l.endswith("key")
                ):
                    outer_id_col = cand
                    break

        eq_pairs = list(
            re.finditer(
                r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
                from_core,
                flags=re.I,
            )
        )

        bridge_outer_col = ""
        for m_eq in eq_pairs:
            a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
            if a1.lower() == outer_alias.lower() and a2.lower() == bridge_alias.lower() and c1.lower() == outer_id_col.lower():
                bridge_outer_col = c2
                break
            if a2.lower() == outer_alias.lower() and a1.lower() == bridge_alias.lower() and c2.lower() == outer_id_col.lower():
                bridge_outer_col = c1
                break

        rels = fk_map.get(_plain_table_name(bridge_table).lower(), {})
        temporal_bridge_candidate = None
        for fk_col, tgt_table in rels.items():
            temporal_cols = _temporal_cols_for_table(tgt_table)
            if not temporal_cols:
                continue
            hint_cols: List[str] = []
            for _idx, _bad_alias, _bad_table, bad_col, _yr in invalid_year_conds:
                hint_cols.append(bad_col)
            preferred_temporal_col = _choose_preferred_temporal_column(
                tgt_table,
                temporal_cols,
                hint_columns=hint_cols,
                question=question,
            )
            if not preferred_temporal_col:
                continue
            try:
                target_pk = (get_id_column(tgt_table) or "").strip()
            except Exception:
                target_pk = ""
            target_cols = _table_cols(tgt_table)
            if not target_pk or target_pk.lower() not in target_cols:
                if fk_col.lower() in target_cols:
                    target_pk = fk_col
                else:
                    continue
            temporal_bridge_candidate = (fk_col, tgt_table, preferred_temporal_col, target_pk)
            break

        if outer_id_col and bridge_outer_col and temporal_bridge_candidate is not None:
            bridge_fk_col, temporal_table, temporal_col, temporal_pk = temporal_bridge_candidate
            used_aliases = {a.lower() for a in explicit_aliases.keys()}
            temporal_alias = _pick_alias(f"{_plain_table_name(temporal_table)}_outer", used_aliases)
            anti_bridge_alias = _pick_alias("anti_src", used_aliases)
            anti_temporal_alias = _pick_alias("anti_dt", used_aliases)
            anti_not_exists = (
                "NOT EXISTS (\n"
                "  SELECT 1\n"
                f"  FROM {bridge_table} AS {anti_bridge_alias}\n"
                f"  JOIN {temporal_table} AS {anti_temporal_alias}\n"
                f"    ON {anti_temporal_alias}.{temporal_pk} = {anti_bridge_alias}.{bridge_fk_col}\n"
                f"  WHERE {anti_bridge_alias}.{bridge_outer_col} = {outer_alias}.{outer_id_col}\n"
                f"    AND YEAR({anti_temporal_alias}.{temporal_col}) = {exclude_year}\n"
                ")"
            )
            remaining = [
                c.strip()
                for idx, c in enumerate(conjuncts)
                if idx not in {item[0] for item in invalid_year_conds} and c.strip()
            ]
            remaining.insert(0, f"YEAR({temporal_alias}.{temporal_col}) = {include_year}")
            remaining.append(anti_not_exists)
            tail_clause = f"\n{parsed['tail'].strip()}" if parsed["tail"].strip() else ""
            fixed = (
                f"SELECT {parsed['select'].strip()}\n"
                f"FROM {from_core}\n"
                f"JOIN {temporal_table} AS {temporal_alias} "
                f"ON {temporal_alias}.{temporal_pk} = {bridge_alias}.{bridge_fk_col}\n"
                f"WHERE {' AND '.join(remaining)}\n"
                f"GROUP BY {groupby_part}"
                f"{tail_clause};"
            )
            return fixed

    outer_alias, outer_table = ordered_aliases[0]
    outer_id_col = ""
    try:
        outer_id_col = (get_id_column(outer_table) or "").strip()
    except Exception:
        outer_id_col = ""
    outer_cols = _table_cols(outer_table)
    if not outer_id_col or outer_id_col.lower() not in outer_cols:
        for item in _split_top_level_commas(groupby_part):
            m_outer = re.match(
                rf"""(?is)^\s*`?{re.escape(outer_alias)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""",
                (item or "").strip(),
            )
            if not m_outer:
                continue
            cand = (m_outer.group(1) or "").strip()
            cand_l = cand.lower()
            if cand_l in outer_cols and (
                cand_l.endswith("id")
                or cand_l.endswith("number")
                or cand_l.endswith("code")
                or cand_l.endswith("key")
            ):
                outer_id_col = cand
                break
    if not outer_id_col or outer_id_col.lower() not in outer_cols:
        return sql
    if not re.search(
        rf"""(?is)\b`?{re.escape(outer_alias)}`?\s*\.\s*`?{re.escape(outer_id_col)}`?\b""",
        groupby_part,
    ):
        return sql

    eq_pairs = list(
        re.finditer(
            r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
            from_core,
            flags=re.I,
        )
    )

    bridge_candidates: List[Tuple[str, str, str, str, str, str]] = []
    for alias_name, table_name in ordered_aliases[1:]:
        table_l = _plain_table_name(table_name).lower()
        rels = fk_map.get(table_l, {})
        if not rels:
            continue

        outer_bridge_col = ""
        for m_eq in eq_pairs:
            a1, c1, a2, c2 = m_eq.group(1), m_eq.group(2), m_eq.group(3), m_eq.group(4)
            if a1.lower() == alias_name.lower() and a2.lower() == outer_alias.lower() and c2.lower() == outer_id_col.lower():
                outer_bridge_col = c1
                break
            if a2.lower() == alias_name.lower() and a1.lower() == outer_alias.lower() and c1.lower() == outer_id_col.lower():
                outer_bridge_col = c2
                break
        if not outer_bridge_col:
            continue

        for fk_col, tgt_table in rels.items():
            temporal_cols = _temporal_cols_for_table(tgt_table)
            if not temporal_cols:
                continue
            hint_cols: List[str] = []
            for _idx, bad_alias, _bad_table, bad_col, _yr in invalid_year_conds:
                hint_cols.append(bad_col)
            preferred_temporal_col = _choose_preferred_temporal_column(
                tgt_table,
                temporal_cols,
                hint_columns=hint_cols,
                question=question,
            )
            if not preferred_temporal_col:
                continue

            try:
                target_pk = (get_id_column(tgt_table) or "").strip()
            except Exception:
                target_pk = ""
            target_cols = _table_cols(tgt_table)
            if not target_pk or target_pk.lower() not in target_cols:
                if fk_col.lower() in target_cols:
                    target_pk = fk_col
                else:
                    continue

            bridge_candidates.append(
                (
                    alias_name,
                    table_name,
                    outer_bridge_col,
                    fk_col,
                    tgt_table,
                    preferred_temporal_col,
                    target_pk,
                )
            )

    if len(bridge_candidates) != 1:
        return sql

    bridge_alias, bridge_table, outer_bridge_col, bridge_fk_col, temporal_table, temporal_col, temporal_pk = bridge_candidates[0]

    used_aliases = {a.lower() for a in explicit_aliases.keys()}
    outer_temporal_alias = next(
        (
            alias_name
            for alias_name, table_name in ordered_aliases
            if _plain_table_name(table_name).lower() == _plain_table_name(temporal_table).lower()
        ),
        "",
    )
    join_to_add = ""
    if not outer_temporal_alias:
        outer_temporal_alias = _pick_alias(f"{_plain_table_name(temporal_table)}_outer", used_aliases)
        join_to_add = (
            f"\nJOIN {temporal_table} AS {outer_temporal_alias} "
            f"ON {outer_temporal_alias}.{temporal_pk} = {bridge_alias}.{bridge_fk_col}"
        )

    anti_bridge_alias = _pick_alias("anti_src", used_aliases)
    anti_temporal_alias = _pick_alias("anti_dt", used_aliases)
    anti_not_exists = (
        "NOT EXISTS (\n"
        "  SELECT 1\n"
        f"  FROM {bridge_table} AS {anti_bridge_alias}\n"
        f"  JOIN {temporal_table} AS {anti_temporal_alias}\n"
        f"    ON {anti_temporal_alias}.{temporal_pk} = {anti_bridge_alias}.{bridge_fk_col}\n"
        f"  WHERE {anti_bridge_alias}.{outer_bridge_col} = {outer_alias}.{outer_id_col}\n"
        f"    AND YEAR({anti_temporal_alias}.{temporal_col}) = {exclude_year}\n"
        ")"
    )

    remaining = [
        c.strip()
        for idx, c in enumerate(conjuncts)
        if idx not in {item[0] for item in invalid_year_conds} and c.strip()
    ]
    remaining.insert(0, f"YEAR({outer_temporal_alias}.{temporal_col}) = {include_year}")
    remaining.append(anti_not_exists)

    tail_clause = f"\n{parsed['tail'].strip()}" if parsed["tail"].strip() else ""
    fixed = (
        f"SELECT {parsed['select'].strip()}\n"
        f"FROM {from_core}{join_to_add}\n"
        f"WHERE {' AND '.join(remaining)}\n"
        f"GROUP BY {parsed['groupby'].strip()}"
        f"{tail_clause};"
    )
    return fixed


def _rewrite_latest_year_projection_to_year(sql: str, question: str) -> str:
    """
    Convert date aggregate projection to year projection when output alias
    explicitly asks for year-like value.

    Example:
      MAX(o.orderDate) AS latest_order_year
    -> MAX(YEAR(o.orderDate)) AS latest_order_year

    Safety:
    - Trigger only when question mentions year/tahun.
    - Trigger only for aliases containing year/tahun.
    - Trigger only for MAX(date/time-like column), skip if already YEAR(...).
    """
    if not sql:
        return sql

    q = (question or "").lower()
    if not re.search(r"\b(?:year|tahun)\b", q):
        return sql

    parsed = _parse_select_from_groupby(sql)
    fallback_rest: Optional[str] = None

    if parsed:
        select_part = parsed["select"]
    else:
        # Fallback for derived-table shapes where conservative parser aborts.
        # We only need to rewrite top-level SELECT projection.
        s = (sql or "").strip().rstrip(";").strip()
        if not re.match(r"(?is)^\s*select\b", s):
            return sql

        def _find_top_level_from(text: str) -> int:
            i = 0
            depth = 0
            in_sq = False
            in_dq = False
            in_bt = False
            low = text.lower()
            while i < len(text):
                ch = text[i]
                if ch == "'" and not in_dq and not in_bt:
                    if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                        i += 2
                        continue
                    in_sq = not in_sq
                    i += 1
                    continue
                if ch == '"' and not in_sq and not in_bt:
                    if in_dq and i + 1 < len(text) and text[i + 1] == '"':
                        i += 2
                        continue
                    in_dq = not in_dq
                    i += 1
                    continue
                if ch == "`" and not in_sq and not in_dq:
                    in_bt = not in_bt
                    i += 1
                    continue
                if in_sq or in_dq or in_bt:
                    i += 1
                    continue
                if ch == "(":
                    depth += 1
                    i += 1
                    continue
                if ch == ")":
                    depth = max(0, depth - 1)
                    i += 1
                    continue
                if depth == 0 and low[i:i + 4] == "from":
                    left_ok = (i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_"))
                    right_ok = (i + 4 >= len(text) or not (text[i + 4].isalnum() or text[i + 4] == "_"))
                    if left_ok and right_ok:
                        return i
                i += 1
            return -1

        from_idx = _find_top_level_from(s)
        if from_idx < 0:
            return sql
        select_part = s[len("SELECT"):from_idx].strip()
        fallback_rest = s[from_idx:].strip()

    select_items = _split_top_level_commas(select_part)
    if not select_items:
        return sql

    changed = False
    rebuilt: List[str] = []
    alias_to_table: Dict[str, str] = {}
    cols_cache: Dict[str, Set[str]] = {}
    analyzer = None

    try:
        alias_to_table = {
            str(alias or "").strip("`").lower(): str(table or "").strip("`").lower()
            for alias, table in (_parse_from_join_aliases(sql) or {}).items()
            if str(alias or "").strip() and str(table or "").strip()
        }
    except Exception:
        alias_to_table = {}
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    def _table_cols(table_name: str) -> Set[str]:
        table_l = str(table_name or "").strip("`").lower()
        if not table_l:
            return set()
        if table_l in cols_cache:
            return cols_cache[table_l]
        cols: Set[str] = set()
        if analyzer is not None:
            try:
                cols.update(str(c or "").strip("`").lower() for c in analyzer.get_table_columns(table_l))
            except Exception:
                pass
        cols_cache[table_l] = cols
        return cols

    def _is_temporal_column(table_name: str, col_name: str) -> bool:
        table_l = str(table_name or "").strip("`").lower()
        col_l = str(col_name or "").strip("`").lower()
        if not table_l or not col_l:
            return False
        try:
            role = str(get_column_role(table_l, col_l) or "").lower()
        except Exception:
            role = ""
        try:
            datatype = str(get_column_datatype(table_l, col_l) or "").lower()
        except Exception:
            datatype = ""
        return (
            any(token in col_l for token in ("date", "time", "timestamp"))
            or any(token in role for token in ("date", "time", "timestamp", "temporal"))
            or any(token in datatype for token in ("date", "time", "timestamp"))
        )

    def _split_expr_alias(item: str) -> tuple:
        m = re.match(
            r"""(?is)^\s*(.*?)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            item.strip(),
        )
        if not m:
            return item.strip(), None
        return m.group(1).strip(), m.group(2).strip()

    def _parse_qualified_col(expr: str) -> Optional[tuple]:
        m = re.match(
            r"(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$",
            expr.strip(),
        )
        if not m:
            return None
        return m.group(1), m.group(2)

    def _year_projection_source(alias_name: Optional[str], pseudo_col: str) -> Optional[str]:
        alias_l = str(alias_name or "").strip("`").lower()
        pseudo_l = str(pseudo_col or "").strip("`").lower()
        if not alias_l or pseudo_l not in {str(t).lower() for t in temporal_year_column_terms()}:
            return None
        table_name = alias_to_table.get(alias_l, "")
        table_cols = _table_cols(table_name)
        if pseudo_l in table_cols:
            return None

        year_expr_pat = re.compile(
            rf"""(?is)\bYEAR\s*\(\s*`?{re.escape(alias_l)}`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)"""
        )
        query_temporal_cols: List[str] = []
        for m_year in year_expr_pat.finditer(sql):
            cand = str(m_year.group(1) or "").strip("`")
            if cand and cand.lower() != pseudo_l and _is_temporal_column(table_name, cand):
                query_temporal_cols.append(cand)
        query_temporal_cols = list(dict.fromkeys(query_temporal_cols))
        if len(query_temporal_cols) == 1:
            return f"{alias_name}.{query_temporal_cols[0]}"

        schema_temporal_cols = [
            c for c in sorted(table_cols)
            if _is_temporal_column(table_name, c)
        ]
        if len(schema_temporal_cols) == 1:
            return f"{alias_name}.{schema_temporal_cols[0]}"
        return None

    for item in select_items:
        expr, alias = _split_expr_alias(item)
        if not alias:
            rebuilt.append(item.strip())
            continue

        alias_clean = alias.strip()
        if (
            (alias_clean.startswith("`") and alias_clean.endswith("`"))
            or (alias_clean.startswith("'") and alias_clean.endswith("'"))
            or (alias_clean.startswith('"') and alias_clean.endswith('"'))
        ):
            alias_clean = alias_clean[1:-1]
        alias_l = alias_clean.lower()

        # Only rewrite explicit year-like output alias.
        if ("year" not in alias_l) and ("tahun" not in alias_l):
            rebuilt.append(item.strip())
            continue
        # If alias explicitly asks for date/time too, keep date projection.
        # Example: latest_payment_date_in_latest_year should remain MAX(date).
        if ("date" in alias_l) or ("time" in alias_l) or ("tanggal" in alias_l):
            rebuilt.append(item.strip())
            continue

        m_max = re.match(r"(?is)^MAX\s*\(\s*(.+?)\s*\)$", expr)
        if not m_max:
            rebuilt.append(item.strip())
            continue

        inner = m_max.group(1).strip()
        if re.search(r"(?is)^\s*YEAR\s*\(", inner):
            rebuilt.append(item.strip())
            continue

        parsed_col = _parse_qualified_col(inner)
        if not parsed_col:
            rebuilt.append(item.strip())
            continue
        _a, c = parsed_col
        c_l = (c or "").lower()
        pseudo_year_source = _year_projection_source(_a, c)
        if pseudo_year_source:
            rebuilt.append(f"MAX(YEAR({pseudo_year_source})) AS {alias}")
            changed = True
            continue
        if ("date" not in c_l) and ("time" not in c_l):
            rebuilt.append(item.strip())
            continue

        rebuilt.append(f"MAX(YEAR({inner})) AS {alias}")
        changed = True

    if not changed:
        return sql

    if parsed:
        where_block = f"\n{parsed['where'].strip()}" if parsed["where"].strip() else ""
        tail_block = f"\n{parsed['tail'].strip()}" if parsed["tail"].strip() else ""
        fixed = (
            f"SELECT {', '.join(rebuilt)}\n"
            f"FROM {parsed['from_core'].strip()}"
            f"{where_block}\n"
            f"GROUP BY {parsed['groupby'].strip()}"
            f"{tail_block};"
        )
        return fixed

    # Fallback rebuild: preserve original FROM... tail as-is.
    fixed_fb = f"SELECT {', '.join(rebuilt)}\n{fallback_rest or ''}".strip()
    if fixed_fb and not fixed_fb.endswith(";"):
        fixed_fb += ";"
    return fixed_fb


def _rewrite_row_level_nonnull_to_group_existence(sql: str, question: str) -> str:
    """
    For grouped aggregate queries where question asks existence semantics
    ("at least one ... NOT NULL"), avoid row-level WHERE filtering that
    shrinks aggregate totals.

    Example rewrite:
      ... WHERE e.reportsTo IS NOT NULL GROUP BY ...
    ->
      ... GROUP BY ... HAVING SUM(CASE WHEN e.reportsTo IS NOT NULL THEN 1 ELSE 0 END) > 0
    """
    if not sql:
        return sql

    q = (question or "").lower()
    has_exist_intent = bool(re.search(r"\b(?:at\s+least\s+one|any|one\s+or\s+more)\b", q))
    has_nonnull_intent = bool(re.search(r"\b(?:not\s+null|non[-\s]?null)\b", q))
    if not (has_exist_intent and has_nonnull_intent):
        return sql

    s = sql.strip().rstrip(";").strip()
    if not s:
        return sql
    if not re.search(r"\bGROUP\s+BY\b", s, flags=re.I):
        return sql

    m = re.match(
        r"(?is)^(?P<head>.*?\bFROM\b.*?)(?P<tail>\s+(?:WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b.*)$",
        s,
    )
    if not m:
        return sql

    head = (m.group("head") or "").strip()
    tail = (m.group("tail") or "").strip()
    where_body, rest_after_where = _split_where_and_rest(" " + tail)
    if not where_body:
        return sql
    if _has_top_level_or(where_body):
        return sql

    conds = _split_top_level_and(where_body)
    if not conds:
        return sql

    nonnull_conds: List[str] = []
    keep_conds: List[str] = []

    colref = r"`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?"
    nonnull_pat = re.compile(
        rf"""(?is)^\s*\(?\s*(?P<col>{colref})\s+IS\s+NOT\s+NULL\s*\)?\s*$"""
    )
    not_isnull_pat = re.compile(
        rf"""(?is)^\s*\(?\s*NOT\s+(?P<col>{colref})\s+IS\s+NULL\s*\)?\s*$"""
    )
    not_null_or_empty_pat = re.compile(
        rf"""(?is)^\s*\(?\s*NOT\s*\(\s*(?P<c1>{colref})\s+IS\s+NULL\s+OR\s*(?P<c2>{colref})\s*=\s*''\s*\)\s*\)?\s*$"""
    )

    def _norm_colref(ref: str) -> str:
        return re.sub(r"[\s`]+", "", str(ref or "")).lower()

    def _extract_nonnull_condition(cond: str) -> Optional[str]:
        c = (cond or "").strip()
        if not c:
            return None

        m1 = nonnull_pat.match(c)
        if m1:
            return f"{m1.group('col').strip()} IS NOT NULL"

        m2 = not_isnull_pat.match(c)
        if m2:
            return f"{m2.group('col').strip()} IS NOT NULL"

        m3 = not_null_or_empty_pat.match(c)
        if m3:
            c1 = (m3.group("c1") or "").strip()
            c2 = (m3.group("c2") or "").strip()
            if c1 and c2 and _norm_colref(c1) == _norm_colref(c2):
                return f"NOT ({c1} IS NULL OR {c1} = '')"

        return None

    for c in conds:
        c0 = c.strip()
        if not c0:
            continue
        nonnull_expr = _extract_nonnull_condition(c0)
        if nonnull_expr:
            nonnull_conds.append(nonnull_expr)
        else:
            keep_conds.append(c0)

    if not nonnull_conds:
        return sql

    existence_parts = [
        f"SUM(CASE WHEN {c} THEN 1 ELSE 0 END) > 0" for c in nonnull_conds
    ]
    existence_expr = " AND ".join(existence_parts)

    rest = (rest_after_where or "").strip()
    if not rest:
        return sql
    if not re.search(r"\bGROUP\s+BY\b", rest, flags=re.I):
        return sql

    if re.search(r"\bHAVING\b", rest, flags=re.I):
        rest = re.sub(
            r"(?is)\bHAVING\b\s*(?P<h>.*?)(?=(\bORDER\s+BY\b|\bLIMIT\b|$))",
            lambda m_h: f"HAVING ({m_h.group('h').strip()}) AND ({existence_expr})",
            rest,
            count=1,
        )
    else:
        m_tail = re.search(r"\b(ORDER\s+BY|LIMIT)\b", rest, flags=re.I)
        if m_tail:
            rest = (
                rest[:m_tail.start()].rstrip()
                + f" HAVING {existence_expr} "
                + rest[m_tail.start():].lstrip()
            )
        else:
            rest = rest.rstrip() + f" HAVING {existence_expr}"

    where_part = f" WHERE {' AND '.join(keep_conds)}" if keep_conds else ""
    fixed = f"{head}{where_part} {rest}".strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _rewrite_grouped_self_fk_exists_to_group_having(sql: str, question: str, ctx: str = "") -> str:
    """
    Move malformed row-level self-FK EXISTS filters to group-level HAVING.

    This covers grouped parent/child aggregates where a draft interprets
    "at least one child with a parent/manager" as:
      WHERE EXISTS (... same_child.self_fk = child.id ...)
    which filters child rows before COUNT/SUM. The group-safe form is:
      HAVING SUM(CASE WHEN child.self_fk IS NOT NULL THEN 1 ELSE 0 END) > 0

    If the EXISTS also contains a role-label condition, only separate it when
    the question explicitly says that condition is independent (YAML-driven
    cues such as "not necessarily").
    """
    if not sql or not question:
        return sql
    if not re.search(r"\bGROUP\s+BY\b", sql, flags=re.I) or not re.search(r"\bWHERE\b.+\bEXISTS\s*\(", sql, flags=re.I | re.S):
        return sql

    q = str(question or "").strip().lower()
    has_independence_cue = any_phrase_in_text(q, grouped_self_fk_independence_cues())

    s = sql.strip()
    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    where_pos = _find_top_level_clause(s0, "where")
    group_pos = _find_top_level_clause(s0, "group by", max(0, where_pos + len("where")))
    if where_pos < 0 or group_pos < 0:
        return sql

    clause_after_where = [
        p for p in [
            group_pos,
            _find_top_level_clause(s0, "having", where_pos + len("where")),
            _find_top_level_clause(s0, "order by", where_pos + len("where")),
            _find_top_level_clause(s0, "limit", where_pos + len("where")),
        ]
        if p >= 0
    ]
    where_end = min(clause_after_where) if clause_after_where else len(s0)
    where_body = s0[where_pos + len("where"):where_end].strip()
    if not where_body or _has_top_level_or(where_body):
        return sql

    alias_to_table_raw = _parse_from_join_aliases(s0) or {}
    alias_to_table = {
        str(alias or "").strip("`").lower(): str(table or "").strip("`").lower()
        for alias, table in alias_to_table_raw.items()
        if str(alias or "").strip() and str(table or "").strip()
    }
    if not alias_to_table:
        return sql

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    def _case_col(table_l: str, col_l: str) -> str:
        table_l = str(table_l or "").strip("`").lower()
        col_l = str(col_l or "").strip("`").lower()
        if analyzer is not None:
            try:
                return str(getattr(analyzer, "_column_original_case", {}).get(f"{table_l}.{col_l}", col_l))
            except Exception:
                pass
        return col_l

    self_fk_by_table = _self_fk_columns_by_table(ctx)
    if not self_fk_by_table:
        return sql

    select_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, select_pos + len("select")))
    if select_pos != 0 or from_pos < 0:
        return sql
    select_part = s0[select_pos + len("select"):from_pos].strip()

    def _norm_expr(expr: str) -> str:
        return re.sub(r"[\s`]+", "", str(expr or "").lower())

    conditional_sums: List[Tuple[str, str]] = []
    for item in _split_top_level_commas(select_part):
        expr, _alias = _split_select_expr_alias(item)
        m_cond = re.match(
            r"(?is)^\s*(SUM\s*\(\s*CASE\s+WHEN\s+(?P<cond>.*?)\s+THEN\s+1\s+ELSE\s+0\s+END\s*\))\s*$",
            expr or "",
        )
        if m_cond:
            conditional_sums.append((m_cond.group(1).strip(), (m_cond.group("cond") or "").strip()))

    def _matching_conditional_having(outer_alias: str, sub_alias: str, cond: str) -> Optional[str]:
        rewritten_cond = re.sub(
            rf"(?is)\b{re.escape(sub_alias)}\s*\.",
            f"{outer_alias}.",
            cond.strip(),
        )
        rewritten_norm = _norm_expr(rewritten_cond)
        for sum_expr, sum_cond in conditional_sums:
            if _norm_expr(sum_cond) == rewritten_norm:
                return f"{sum_expr} > 0"
        return None

    exists_pat = re.compile(
        r"""(?is)^\s*EXISTS\s*\(\s*SELECT\s+1\s+FROM\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)\s+WHERE\s+(?P<body>.*?)\s*\)\s*$"""
    )
    eq_pat = re.compile(
        r"""(?is)^\s*`?(?P<a1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<c1>[A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?(?P<a2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<c2>[A-Za-z_][A-Za-z0-9_]*)`?\s*$"""
    )

    keep_conds: List[str] = []
    having_exprs: List[str] = []
    changed = False

    for cond in _split_top_level_and(where_body):
        cond_s = cond.strip()
        if not cond_s:
            continue
        m_exists = exists_pat.match(cond_s)
        if not m_exists:
            keep_conds.append(cond_s)
            continue

        sub_table = str(m_exists.group("table") or "").strip("`").lower()
        sub_alias = str(m_exists.group("alias") or "").strip("`")
        sub_alias_l = sub_alias.lower()
        inner_conds = [c.strip() for c in _split_top_level_and(m_exists.group("body") or "") if c.strip()]
        if not sub_table or not sub_alias or not inner_conds:
            keep_conds.append(cond_s)
            continue

        self_match: Optional[Tuple[int, str, str, str]] = None
        for idx, inner in enumerate(inner_conds):
            m_eq = eq_pat.match(inner)
            if not m_eq:
                continue
            sides = [
                (m_eq.group("a1"), m_eq.group("c1"), m_eq.group("a2"), m_eq.group("c2")),
                (m_eq.group("a2"), m_eq.group("c2"), m_eq.group("a1"), m_eq.group("c1")),
            ]
            for sub_a, sub_c, outer_a, outer_c in sides:
                if str(sub_a or "").strip("`").lower() != sub_alias_l:
                    continue
                outer_alias_l = str(outer_a or "").strip("`").lower()
                outer_table = alias_to_table.get(outer_alias_l, "")
                if outer_table != sub_table:
                    continue
                sub_col_l = str(sub_c or "").strip("`").lower()
                outer_col_l = str(outer_c or "").strip("`").lower()
                for fk_col_l, id_col_l in self_fk_by_table.get(sub_table, []):
                    if sub_col_l == str(fk_col_l).lower() and outer_col_l == str(id_col_l).lower():
                        self_match = (idx, str(outer_a).strip("`"), str(fk_col_l).lower(), str(id_col_l).lower())
                        break
                if self_match:
                    break
            if self_match:
                break

        if not self_match:
            keep_conds.append(cond_s)
            continue

        self_idx, outer_alias, self_fk_col_l, _id_col_l = self_match
        extra_conds = [c for i, c in enumerate(inner_conds) if i != self_idx]
        if extra_conds and not has_independence_cue:
            keep_conds.append(cond_s)
            continue

        outer_table = alias_to_table.get(outer_alias.lower(), sub_table)
        self_fk_case = _case_col(outer_table, self_fk_col_l)
        self_having = f"SUM(CASE WHEN {outer_alias}.{self_fk_case} IS NOT NULL THEN 1 ELSE 0 END) > 0"
        having_exprs.append(self_having)

        for extra in extra_conds:
            role_having = _matching_conditional_having(outer_alias, sub_alias, extra)
            if role_having:
                having_exprs.append(role_having)

        changed = True

    if not changed or not having_exprs:
        return sql

    having_exprs = list(dict.fromkeys(having_exprs))
    before_where = s0[:where_pos].rstrip()
    rest = s0[where_end:].lstrip()
    where_sql = f" WHERE {' AND '.join(keep_conds)}" if keep_conds else ""
    fixed = f"{before_where}{where_sql} {rest}".strip()

    having_expr = " AND ".join(f"({expr})" for expr in having_exprs)
    having_pos = _find_top_level_clause(fixed, "having")
    if having_pos >= 0:
        order_pos = _find_top_level_clause(fixed, "order by", having_pos + len("having"))
        limit_pos = _find_top_level_clause(fixed, "limit", having_pos + len("having"))
        having_end_candidates = [p for p in (order_pos, limit_pos) if p >= 0]
        having_end = min(having_end_candidates) if having_end_candidates else len(fixed)
        existing = fixed[having_pos + len("having"):having_end].strip()
        fixed = (
            fixed[:having_pos + len("having")]
            + f" ({existing}) AND {having_expr} "
            + fixed[having_end:].lstrip()
        ).strip()
    else:
        order_pos = _find_top_level_clause(fixed, "order by")
        limit_pos = _find_top_level_clause(fixed, "limit")
        insert_candidates = [p for p in (order_pos, limit_pos) if p >= 0]
        insert_pos = min(insert_candidates) if insert_candidates else len(fixed)
        fixed = (
            fixed[:insert_pos].rstrip()
            + f" HAVING {having_expr}"
            + (" " + fixed[insert_pos:].lstrip() if insert_pos < len(fixed) else "")
        ).strip()

    return fixed.rstrip() + trailing


def _rewrite_role_label_count_semantics(sql: str, question: str) -> str:
    """
    Repair grouped role-label counts where a role-specific count from the
    question is approximated using a non-null field count.

    Conservative trigger:
    - question asks for `number/count of <role>`
    - SQL contains a non-null aggregate count in SELECT
    - the same table alias has a schema-backed text column that looks like a
      role/title/position label
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not re.search(r"\b(?:number|count)\s+of\s+\b", q, flags=re.I):
        return sql

    s = sql.strip().rstrip(";").strip()
    if not s:
        return sql

    role_match = re.search(
        r"\b(?:number|count)\s+of\s+(?P<role>[a-z][a-z\s-]{1,40}?)(?=\s*(?:[.,;]|(?:\s+(?:and|keep|with|where|sort|order|return)\b)|$))",
        q,
        flags=re.I,
    )
    if not role_match:
        return sql

    role_phrase = re.sub(r"\s+", " ", (role_match.group("role") or "").strip().lower())
    if not role_phrase:
        return sql

    role_parts = role_phrase.split()
    if role_parts:
        last = role_parts[-1]
        if last.endswith("ies") and len(last) > 3:
            role_parts[-1] = last[:-3] + "y"
        elif last.endswith("s") and len(last) > 3:
            role_parts[-1] = last[:-1]
    role_phrase = " ".join(role_parts).strip()
    if not role_phrase:
        return sql

    # Skip entity-level phrases dynamically (schema/table-driven), so this
    # role-label repair only applies to role/title-like labels.
    entity_terms: Set[str] = set()
    for tbl in re.findall(
        r"""(?is)\b(?:FROM|JOIN)\s+`?([A-Za-z_][A-Za-z0-9_]*)`?\b""",
        s,
    ):
        table_name = str(tbl or "").strip().lower()
        if not table_name:
            continue
        entity_terms.add(table_name)
        singular = str(get_singular_form(table_name) or "").strip().lower()
        if singular:
            entity_terms.add(singular)
    if role_phrase in entity_terms:
        return sql

    select_match = re.match(r"(?is)^\s*SELECT\s+(?P<select>.*?)\s+FROM\s+(?P<rest>.*)$", s)
    if not select_match:
        return sql
    select_part = (select_match.group("select") or "").strip()
    rest = (select_match.group("rest") or "").strip()
    if not select_part or not rest:
        return sql

    select_items = _split_top_level_commas(select_part)
    if not select_items:
        return sql

    alias_to_table: Dict[str, str] = {}
    for tbl, alias in re.findall(
        r"""(?is)\b(?:FROM|JOIN)\s+`?([A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?)?([A-Za-z_][A-Za-z0-9_]*)?\b""",
        s,
    ):
        table_name = str(tbl or "").strip()
        alias_name = str(alias or "").strip()
        if table_name:
            alias_to_table[table_name] = table_name
        if table_name and alias_name:
            alias_to_table[alias_name] = table_name

    changed = False
    rebuilt_items: List[str] = []
    role_having_expr = ""
    nonnull_count_pat = re.compile(
        r"""(?is)^\s*(?:COUNT|SUM)\s*\(\s*CASE\s+WHEN\s+(?:
            NOT\s+(?P<alias1>[A-Za-z_][A-Za-z0-9_]*)\s*\.\s*(?P<col1>[A-Za-z_][A-Za-z0-9_]*)\s+IS\s+NULL
            |
            (?P<alias2>[A-Za-z_][A-Za-z0-9_]*)\s*\.\s*(?P<col2>[A-Za-z_][A-Za-z0-9_]*)\s+IS\s+NOT\s+NULL
        ).*?\)\s*(?:AS\s+(?P<alias_name>`[^`]+`|[A-Za-z_][A-Za-z0-9_]*))?\s*$""",
        re.I | re.S | re.X,
    )
    for item in select_items:
        item_clean = (item or "").strip()
        if not item_clean:
            continue
        m_role = nonnull_count_pat.match(item_clean)
        if not m_role:
            rebuilt_items.append(item_clean)
            continue

        counted_alias = ((m_role.group("alias1") or m_role.group("alias2") or "")).strip()
        counted_table = alias_to_table.get(counted_alias, counted_alias)
        if not counted_table:
            rebuilt_items.append(item_clean)
            continue

        try:
            text_cols = [str(c or "").strip() for c in get_columns_by_role(counted_table, "text")]
        except Exception:
            text_cols = []
        role_col = ""
        for cand in text_cols:
            cand_l = cand.lower()
            if any(tok in cand_l for tok in ("role", "title", "position", "designation", "type")):
                role_col = cand
                break
        if not role_col:
            rebuilt_items.append(item_clean)
            continue

        role_expr = f"SUM(CASE WHEN LOWER({counted_alias}.{role_col}) = '{role_phrase}' THEN 1 ELSE 0 END)"
        alias_sql = (m_role.group("alias_name") or "").strip()
        rebuilt_items.append(f"{role_expr}" + (f" AS {alias_sql}" if alias_sql else ""))
        role_having_expr = role_expr
        changed = True

    if not changed:
        return sql

    rebuilt_sql = f"SELECT {', '.join(rebuilt_items)} FROM {rest}"
    wants_role_existence = bool(
        re.search(
            rf"\bat\s+least\s+one\s+{re.escape(role_phrase)}\b",
            q,
            flags=re.I,
        )
    )
    if wants_role_existence and role_having_expr:
        role_having = f"{role_having_expr} > 0"
        def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
            t = str(text or "")
            low = t.lower()
            kw_low = kw.lower()
            depth = 0
            in_sq = False
            in_dq = False
            i = start
            while i < len(t):
                ch = t[i]
                if ch == "'" and not in_dq:
                    if in_sq and i + 1 < len(t) and t[i + 1] == "'":
                        i += 2
                        continue
                    in_sq = not in_sq
                    i += 1
                    continue
                if ch == '"' and not in_sq:
                    in_dq = not in_dq
                    i += 1
                    continue
                if in_sq or in_dq:
                    i += 1
                    continue
                if ch == "(":
                    depth += 1
                    i += 1
                    continue
                if ch == ")":
                    depth = max(0, depth - 1)
                    i += 1
                    continue
                if depth == 0 and low.startswith(kw_low, i):
                    left_ok = i == 0 or not low[i - 1].isalnum()
                    right_idx = i + len(kw_low)
                    right_ok = right_idx >= len(low) or not low[right_idx].isalnum()
                    if left_ok and right_ok:
                        return i
                i += 1
            return -1

        group_pos = _find_top_level_kw(rebuilt_sql, "group by", 0)
        having_pos = _find_top_level_kw(rebuilt_sql, "having", max(group_pos, 0))
        order_pos = _find_top_level_kw(rebuilt_sql, "order by", max(group_pos, 0))
        limit_pos = _find_top_level_kw(rebuilt_sql, "limit", max(group_pos, 0))

        if having_pos >= 0:
            tail_candidates = [p for p in (order_pos, limit_pos) if p >= 0 and p > having_pos]
            having_end = min(tail_candidates) if tail_candidates else len(rebuilt_sql)
            existing_having = rebuilt_sql[having_pos + len("having"):having_end].strip()
            rebuilt_sql = (
                rebuilt_sql[:having_pos]
                + f"HAVING {existing_having} AND {role_having} "
                + rebuilt_sql[having_end:]
            )
        else:
            insert_pos_candidates = [p for p in (order_pos, limit_pos) if p >= 0]
            insert_pos = min(insert_pos_candidates) if insert_pos_candidates else len(rebuilt_sql)
            rebuilt_sql = (
                rebuilt_sql[:insert_pos].rstrip()
                + f" HAVING {role_having} "
                + rebuilt_sql[insert_pos:].lstrip()
            )

    rebuilt_sql = re.sub(r"\s{2,}", " ", rebuilt_sql).strip()
    if rebuilt_sql and not rebuilt_sql.endswith(";"):
        rebuilt_sql += ";"
    return rebuilt_sql or sql


def _drop_unrequested_exists_filters(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop EXISTS predicates that reference tables not mentioned in the question.

    This is a conservative guardrail against hallucinated relationship filters such as:
      WHERE EXISTS (SELECT 1 FROM customers c WHERE ...)
    when the prompt never asks about customers.
    """
    if not sql:
        return sql

    q = (question or "").lower().strip()
    if not q:
        return sql
    if "exists" not in sql.lower():
        return sql

    s = sql.strip().rstrip(";").strip()
    if not s:
        return sql

    m = re.match(
        r"(?is)^(?P<head>.*?\bFROM\b.*?)(?P<tail>\s+(?:WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT)\b.*)$",
        s,
    )
    if not m:
        return sql

    head = (m.group("head") or "").strip()
    tail = (m.group("tail") or "").strip()
    where_body, rest_after_where = _split_where_and_rest(" " + tail)
    if not where_body:
        return sql
    if _has_top_level_or(where_body):
        return sql

    def _table_mentioned_in_question(tbl: str) -> bool:
        t = (tbl or "").lower().strip()
        if not t:
            return False
        variants = {t}
        singular = get_singular_form(t)
        if singular:
            variants.add(singular.lower())
        if "_" in t:
            variants.add(t.replace("_", " "))
        if singular and "_" in singular:
            variants.add(singular.replace("_", " "))
        try:
            for syn in get_table_synonyms(t):
                s0 = (syn or "").lower().strip()
                if s0:
                    variants.add(s0)
        except Exception:
            pass
        for v in variants:
            if not v:
                continue
            pat = re.escape(v).replace(r"\ ", r"\s+")
            if re.search(rf"\b{pat}\b", q, flags=re.I):
                return True
        return False

    exists_table_pat = re.compile(
        r"""(?is)^\s*EXISTS\s*\(\s*SELECT\b.*?\bFROM\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)\b.*\)\s*$"""
    )

    conds = _split_top_level_and(where_body)
    if not conds:
        return sql

    keep: List[str] = []
    removed_any = False
    for c in conds:
        c0 = c.strip()
        if not c0:
            continue
        m_exists = exists_table_pat.match(c0)
        if not m_exists:
            keep.append(c0)
            continue

        tbl_expr = (m_exists.group(1) or "").replace("`", "")
        tbl = tbl_expr.split(".")[-1].lower().strip()
        if _table_mentioned_in_question(tbl):
            keep.append(c0)
            continue

        removed_any = True

    if not removed_any:
        return sql

    if keep:
        where_part = f" WHERE {' AND '.join(keep)}"
    else:
        where_part = ""

    rest = (rest_after_where or "").strip()
    fixed = f"{head}{where_part} {rest}".strip() if rest else f"{head}{where_part}".strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _parse_flat_groupby_clauses(sql: str) -> Optional[dict]:
    """Parse flat grouped SELECT clauses using top-level keyword positions."""
    if not sql:
        return None
    s = str(sql or "").strip().rstrip(";").strip()
    if not s:
        return None
    if re.match(r"(?is)^\s*WITH\b", s):
        return None
    if re.search(r"(?is)\b(?:FROM|JOIN)\s*\(\s*SELECT\b", s):
        return None

    sel_pos = _find_top_level_clause(s, "select")
    from_pos = _find_top_level_clause(s, "from", max(0, sel_pos + len("select")))
    group_pos = _find_top_level_clause(s, "group by", max(0, from_pos + len("from")))
    if sel_pos != 0 or from_pos < 0 or group_pos < 0:
        return None

    where_pos = _find_top_level_clause(s, "where", from_pos + len("from"))
    having_pos = _find_top_level_clause(s, "having", group_pos + len("group by"))
    order_pos = _find_top_level_clause(s, "order by", group_pos + len("group by"))
    limit_pos = _find_top_level_clause(s, "limit", group_pos + len("group by"))

    from_end_candidates = [group_pos]
    if where_pos >= 0 and where_pos < group_pos:
        from_end_candidates.append(where_pos)
    from_end = min(from_end_candidates)
    where_clause = ""
    if where_pos >= 0 and where_pos < group_pos:
        where_clause = s[where_pos:group_pos].strip()

    group_end_candidates = [
        pos for pos in [having_pos, order_pos, limit_pos]
        if pos >= 0 and pos > group_pos
    ]
    group_end = min(group_end_candidates) if group_end_candidates else len(s)

    having_clause = ""
    if having_pos >= 0:
        having_end_candidates = [
            pos for pos in [order_pos, limit_pos]
            if pos >= 0 and pos > having_pos
        ]
        having_end = min(having_end_candidates) if having_end_candidates else len(s)
        having_clause = s[having_pos:having_end].strip()

    tail_start_candidates = [
        pos for pos in [order_pos, limit_pos]
        if pos >= 0 and pos > group_pos
    ]
    tail_start = min(tail_start_candidates) if tail_start_candidates else -1
    tail = s[tail_start:].strip() if tail_start >= 0 else ""

    return {
        "select": s[sel_pos + len("select"):from_pos].strip(),
        "from_core": s[from_pos + len("from"):from_end].strip(),
        "where": where_clause,
        "groupby": s[group_pos + len("group by"):group_end].strip(),
        "having": having_clause,
        "tail": tail,
    }


def _drop_unrequested_missing_value_subset_filters(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop row-level missing-value subset filters from grouped single-table
    queries when the SELECT already computes both:
    - a total row count, and
    - a conditional missing-value count for the same column.

    This prevents COUNT(*) totals from shrinking down to only the missing-value
    subset when the draft leaks `WHERE col IS NULL OR col = ''`.
    """
    if not sql or not question:
        return sql

    parsed = _parse_select_from_groupby(sql) or _parse_flat_groupby_clauses(sql)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    if not from_core or re.search(r"(?is)\bjoin\b", from_core) or "(" in from_core:
        return sql

    where_clause = str(parsed.get("where") or "").strip()
    if not where_clause or not where_clause.lower().startswith("where "):
        return sql
    where_body = where_clause[6:].strip()
    if not where_body:
        return sql

    select_items = _split_top_level_commas(parsed.get("select") or "")
    if not select_items:
        return sql

    has_total_count = any(
        re.match(
            r"(?is)^\s*COUNT\s*\(\s*(?:\*|1)\s*\)\s*$",
            (_split_select_expr_alias(item)[0] or "").strip(),
        )
        for item in select_items
    )
    if not has_total_count:
        return sql

    colref = r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?"
    empty_lit = r"(?:''|\"\")"
    null_or_empty_pat = re.compile(
        rf"""(?is)^\s*\(?\s*
            (?:
                \(?\s*(?P<n1>{colref})\s+IS\s+NULL\s*\)?\s+OR\s+\(?\s*(?P<e1>{colref})\s*=\s*{empty_lit}\s*\)?
                |
                \(?\s*(?P<e2>{colref})\s*=\s*{empty_lit}\s*\)?\s+OR\s+\(?\s*(?P<n2>{colref})\s+IS\s+NULL\s*\)?
            )
            \s*\)?\s*$""",
        flags=re.X,
    )

    def _norm_ref(ref: str) -> str:
        return re.sub(r"[\s`]+", "", str(ref or "")).lower()

    def _bare_col(ref: str) -> str:
        cleaned = str(ref or "").replace("`", "")
        if "." in cleaned:
            cleaned = cleaned.split(".")[-1]
        return cleaned.strip().lower()

    def _select_has_missing_metric_for(ref: str) -> bool:
        bare_col = _bare_col(ref)
        if not bare_col:
            return False
        col_pat = re.escape(bare_col)
        null_pat = re.compile(
            rf"""(?is)(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?{col_pat}`?\s+IS\s+NULL"""
        )
        empty_pat = re.compile(
            rf"""(?is)(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?{col_pat}`?\s*=\s*{empty_lit}"""
        )
        for item in select_items:
            expr = (_split_select_expr_alias(item)[0] or "").strip()
            if not re.search(r"\bCASE\s+WHEN\b", expr, flags=re.I):
                continue
            if null_pat.search(expr) or empty_pat.search(expr):
                return True
        return False

    conds = _split_top_level_and(where_body)
    if not conds:
        conds = [where_body]

    keep_conds: List[str] = []
    removed_any = False
    for cond in conds:
        c0 = str(cond or "").strip()
        if not c0:
            continue

        m_missing = null_or_empty_pat.match(c0)
        if not m_missing:
            keep_conds.append(c0)
            continue

        null_ref = (m_missing.group("n1") or m_missing.group("n2") or "").strip()
        empty_ref = (m_missing.group("e1") or m_missing.group("e2") or "").strip()
        if not null_ref or not empty_ref:
            keep_conds.append(c0)
            continue
        if _norm_ref(null_ref) != _norm_ref(empty_ref):
            keep_conds.append(c0)
            continue
        if not _select_has_missing_metric_for(null_ref):
            keep_conds.append(c0)
            continue

        removed_any = True

    if not removed_any:
        return sql

    out_lines = [
        f"SELECT {parsed['select'].strip()}",
        f"FROM {from_core}",
    ]
    if keep_conds:
        out_lines.append(f"WHERE {' AND '.join(keep_conds)}")
    out_lines.append(f"GROUP BY {parsed['groupby'].strip()}")
    if parsed.get("having"):
        out_lines.append(parsed["having"].strip())
    if parsed.get("tail"):
        out_lines.append(parsed["tail"].strip())

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_group_key_filters(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop hallucinated literal filters on the same column used as a GROUP BY key.

    Conservative scope:
    - flat grouped queries only (via `_parse_select_from_groupby`)
    - top-level AND-only WHERE clause
    - only removes simple `col = literal` / `col IN (literal, ...)` predicates
      when `col` is also a simple GROUP BY column
    - keeps predicates whose literal values are explicitly mentioned in the question
    """
    if not sql:
        return sql

    q = (question or "").strip().lower()
    if not q:
        return sql

    parsed = _parse_select_from_groupby(sql) or _parse_flat_groupby_clauses(sql)
    if not parsed:
        return sql

    where_clause = (parsed.get("where") or "").strip()
    if not where_clause or not where_clause.lower().startswith("where "):
        return sql

    where_body = where_clause[6:].strip()
    if not where_body or _has_top_level_or(where_body):
        return sql

    group_items = _split_top_level_commas(parsed.get("groupby") or "")
    if not group_items:
        return sql

    simple_col_pat = re.compile(
        r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$"""
    )

    grouped_cols: Set[str] = set()
    for item in group_items:
        m_group = simple_col_pat.match(str(item or "").strip())
        if not m_group:
            continue
        grouped_cols.add((m_group.group(2) or "").strip().lower())
    if not grouped_cols:
        return sql

    literal_pat = r"""(?:'[^']*'|"[^"]*"|-?\d+(?:\.\d+)?)"""
    eq_pat = re.compile(
        rf"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*=\s*(?P<lit>{literal_pat})\s*$"""
    )
    eq_rev_pat = re.compile(
        rf"""(?is)^\s*(?P<lit>{literal_pat})\s*=\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*$"""
    )
    in_pat = re.compile(
        rf"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+IN\s*\(\s*(?P<items>{literal_pat}(?:\s*,\s*{literal_pat})*)\s*\)\s*$"""
    )
    regexp_like_pat = re.compile(
        rf"""(?is)^\s*REGEXP_LIKE\s*\(\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*,\s*(?P<lit>{literal_pat})\s*\)\s*$"""
    )
    regexp_pat = re.compile(
        rf"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+(?:REGEXP|RLIKE)\s+(?P<lit>{literal_pat})\s*$"""
    )
    is_not_null_pat = re.compile(
        r"""(?is)^\s*(?:
            (?P<not_prefix>NOT\s+)(?P<not_col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+IS\s+NULL
            |
            (?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+IS\s+NOT\s+NULL
        )\s*$""",
        flags=re.X,
    )

    def _col_name(expr: str) -> str:
        m = simple_col_pat.match(str(expr or "").strip())
        if not m:
            return ""
        return (m.group(2) or "").strip().lower()

    def _literal_text(token: str) -> str:
        raw = str(token or "").strip()
        if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {"'", '"'}:
            raw = raw[1:-1]
        return raw.strip().lower()

    def _question_mentions_literal(token: str) -> bool:
        lit = _literal_text(token)
        if not lit:
            return False
        if re.fullmatch(r"-?\d+(?:\.\d+)?", lit):
            return re.search(rf"\b{re.escape(lit)}\b", q, flags=re.I) is not None
        phrase = re.escape(lit).replace(r"\ ", r"\s+")
        return re.search(rf"\b{phrase}\b", q, flags=re.I) is not None

    def _question_targets_regex_col(col_name: str) -> bool:
        phrase = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_name or ""))
        phrase = re.sub(r"[_\W]+", " ", phrase).strip().lower()
        if not phrase:
            return False
        phrase_pat = re.escape(phrase).replace(r"\ ", r"\s+")
        for m_col in re.finditer(rf"\b{phrase_pat}\b", q, flags=re.I):
            window = q[m_col.start():m_col.end() + 96]
            if re.search(
                r"\b(?:looks?\s+like|matches?|matching|regexp|regex|pattern|starts?\s+with|ends?\s+with|contains?|followed\s+by|exactly)\b",
                window,
                flags=re.I,
            ):
                return True
        return False

    conds = _split_top_level_and(where_body)
    if not conds:
        return sql

    keep_conds: List[str] = []
    removed_any = False
    for cond in conds:
        c0 = str(cond or "").strip()
        if not c0:
            continue

        match = eq_pat.match(c0) or eq_rev_pat.match(c0)
        if match:
            col_l = _col_name(match.group("col") or "")
            lit = match.group("lit") or ""
            if col_l in grouped_cols and not _question_mentions_literal(lit):
                removed_any = True
                continue
            keep_conds.append(c0)
            continue

        in_match = in_pat.match(c0)
        if in_match:
            col_l = _col_name(in_match.group("col") or "")
            items = str(in_match.group("items") or "")
            lit_tokens = [x.strip() for x in items.split(",") if x.strip()]
            if (
                col_l in grouped_cols
                and lit_tokens
                and not any(_question_mentions_literal(tok) for tok in lit_tokens)
            ):
                removed_any = True
                continue
            keep_conds.append(c0)
            continue

        regex_match = regexp_like_pat.match(c0) or regexp_pat.match(c0)
        if regex_match:
            col_l = _col_name(regex_match.group("col") or "")
            lit = regex_match.group("lit") or ""
            if (
                col_l in grouped_cols
                and not _question_targets_regex_col(col_l)
                and not _question_mentions_literal(lit)
            ):
                removed_any = True
                continue
            keep_conds.append(c0)
            continue

        nn_match = is_not_null_pat.match(c0)
        if nn_match:
            col_l = _col_name(nn_match.group("not_col") or nn_match.group("col") or "")
            if col_l in grouped_cols and not re.search(r"\b(?:non\s*null|not\s+null|null|missing|present|known|unknown|empty|blank)\b", q, flags=re.I):
                removed_any = True
                continue
            keep_conds.append(c0)
            continue

        keep_conds.append(c0)

    if not removed_any:
        return sql

    out_lines = [
        f"SELECT {parsed['select'].strip()}",
        f"FROM {parsed['from_core'].strip()}",
    ]
    if keep_conds:
        out_lines.append(f"WHERE {' AND '.join(keep_conds)}")
    out_lines.append(f"GROUP BY {parsed['groupby'].strip()}")
    if parsed.get("having"):
        out_lines.append(parsed["having"].strip())
    if parsed.get("tail"):
        out_lines.append(parsed["tail"].strip())

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_group_key_having_filters(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop tautological HAVING non-null filters on the same grouped key when the
    question never asked for null/missing filtering.

    Conservative scope:
    - flat grouped query only
    - top-level AND-only HAVING
    - only removes `expr IS NOT NULL` / `NOT expr IS NULL` when `expr` is also
      a GROUP BY key expression
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql
    if re.search(r"\b(?:non\s*null|not\s+null|null|missing|present|known|unknown|empty|blank)\b", q, flags=re.I):
        return sql

    parsed = _parse_select_from_groupby(sql) or _parse_flat_groupby_clauses(sql)
    if not parsed:
        return sql

    having_clause = str(parsed.get("having") or "").strip()
    if not having_clause or not having_clause.lower().startswith("having "):
        return sql
    having_body = having_clause[7:].strip()
    if not having_body or _has_top_level_or(having_body):
        return sql

    group_items = [
        str(item or "").strip()
        for item in _split_top_level_commas(parsed.get("groupby") or "")
        if str(item or "").strip()
    ]
    if not group_items:
        return sql

    def _norm_expr(text: str) -> str:
        return re.sub(r"[\s`]+", "", str(text or "").lower())

    grouped_exprs = {_norm_expr(item) for item in group_items if _norm_expr(item)}
    if not grouped_exprs:
        return sql

    nonnull_pat = re.compile(
        r"""(?is)^\s*(?:
            (?P<expr1>.+?)\s+IS\s+NOT\s+NULL
            |
            NOT\s+(?P<expr2>.+?)\s+IS\s+NULL
        )\s*$""",
        flags=re.X,
    )

    full_match = nonnull_pat.match(having_body)
    if full_match:
        expr = str(full_match.group("expr1") or full_match.group("expr2") or "").strip()
        if _norm_expr(expr) in grouped_exprs:
            out_lines = [
                f"SELECT {str(parsed.get('select') or '').strip()}",
                f"FROM {str(parsed.get('from_core') or '').strip()}",
            ]
            if str(parsed.get("where") or "").strip():
                out_lines.append(str(parsed.get("where") or "").strip())
            out_lines.append(f"GROUP BY {str(parsed.get('groupby') or '').strip()}")
            if str(parsed.get("tail") or "").strip():
                out_lines.append(str(parsed.get("tail") or "").strip())
            fixed = "\n".join(out_lines).strip()
            if str(sql).strip().endswith(";") and not fixed.endswith(";"):
                fixed += ";"
            return fixed

    kept_having: List[str] = []
    removed_any = False
    for cond in _split_top_level_and(having_body):
        cond_s = str(cond or "").strip()
        if not cond_s:
            continue
        m_nonnull = nonnull_pat.match(cond_s)
        if not m_nonnull:
            kept_having.append(cond_s)
            continue
        expr = str(m_nonnull.group("expr1") or m_nonnull.group("expr2") or "").strip()
        if _norm_expr(expr) in grouped_exprs:
            removed_any = True
            continue
        kept_having.append(cond_s)

    if not removed_any:
        return sql

    out_lines = [
        f"SELECT {str(parsed.get('select') or '').strip()}",
        f"FROM {str(parsed.get('from_core') or '').strip()}",
    ]
    if str(parsed.get("where") or "").strip():
        out_lines.append(str(parsed.get("where") or "").strip())
    out_lines.append(f"GROUP BY {str(parsed.get('groupby') or '').strip()}")
    if kept_having:
        out_lines.append("HAVING " + " AND ".join(kept_having))
    if str(parsed.get("tail") or "").strip():
        out_lines.append(str(parsed.get("tail") or "").strip())

    fixed = "\n".join(out_lines).strip()
    if str(sql).strip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _add_missing_grouped_extrema_date_metric(sql: str, question: str, ctx: str = "") -> str:
    """
    Add a missing MIN/MAX date metric to a flat grouped single-table query when
    the question explicitly asks to show the earliest/latest date per group.

    Conservative scope:
    - flat grouped single-table queries only
    - question must explicitly ask to show/return/include an earliest/latest
      date-like value
    - only adds the metric when no date extrema aggregate is already projected
    - picks a candidate date column from schema metadata using lexical overlap
      with the question/alias text
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql
    if not re.search(r"\b(?:show|return|include|display|give|list)\b", q, flags=re.I):
        return sql

    want_min = re.search(r"\b(?:earliest|oldest|first|minimum|min)\b", q, flags=re.I) is not None
    want_max = re.search(r"\b(?:latest|newest|last|maximum|max|most\s+recent)\b", q, flags=re.I) is not None
    if want_min == want_max:
        return sql
    if not re.search(r"\b(?:date|time|timestamp|datetime)\b", q, flags=re.I):
        return sql
    if re.search(
        r"\b(?:on|for|from)\s+the\s+(?:latest|newest|most\s+recent|earliest|oldest|first)\b",
        q,
        flags=re.I,
    ):
        return sql

    parsed = _parse_select_from_groupby(sql) or _parse_flat_groupby_clauses(sql)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    if not from_core or re.search(r"[,(]|\bJOIN\b", from_core, flags=re.I):
        return sql

    m_from = re.match(
        r"""(?is)^\s*`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?\s*$""",
        from_core,
    )
    if not m_from:
        return sql

    table_name = str(m_from.group("table") or "").strip("`")
    table_alias = str(m_from.group("alias") or "").strip()
    qualifier = table_alias or table_name
    if not table_name:
        return sql

    try:
        analyzer = get_schema_analyzer()
        table_cols = [str(c or "").strip("`") for c in analyzer.get_table_columns(table_name)]
    except Exception:
        table_cols = []
    if not table_cols:
        return sql

    date_cols: List[str] = []
    for col in table_cols:
        dtype = str(get_column_datatype(table_name, col) or "").strip().lower()
        if any(tok in dtype for tok in ("date", "time", "timestamp", "datetime")):
            date_cols.append(col)
    if not date_cols:
        return sql

    select_items = [
        str(item or "").strip()
        for item in _split_top_level_commas(parsed.get("select") or "")
        if str(item or "").strip()
    ]
    if not select_items:
        return sql

    def _tokenize(text: str) -> Set[str]:
        text = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or ""))
        text = re.sub(r"[^a-z0-9]+", " ", text.lower())
        return {
            tok for tok in text.split()
            if tok and tok not in {
                "the", "a", "an", "by", "for", "of", "that", "this", "those",
                "these", "show", "return", "include", "display", "give", "list",
                "per", "each", "every", "status", "total", "number",
            }
        }

    def _norm_expr(text: str) -> str:
        return re.sub(r"[\s`]+", "", str(text or "").lower())

    aggregate_pat = re.compile(r"\b(?:COUNT|SUM|AVG|MIN|MAX)\s*\(", flags=re.I)
    target_func = "MIN" if want_min else "MAX"
    metric_signal_tokens = _tokenize(q)

    best_col = ""
    best_score = -1
    for col in date_cols:
        col_tokens = _tokenize(col)
        desc_tokens = _tokenize(get_column_description(table_name, col) or "")
        score = 0
        score += 5 * len(metric_signal_tokens & col_tokens)
        score += 2 * len(metric_signal_tokens & desc_tokens)
        if "date" in col_tokens and "date" in metric_signal_tokens:
            score += 3
        if "time" in col_tokens and "time" in metric_signal_tokens:
            score += 3
        if score > best_score:
            best_score = score
            best_col = col
    if not best_col:
        return sql
    if len(date_cols) > 1 and best_score <= 0:
        return sql

    best_col_l = best_col.lower()
    target_present = False
    for item in select_items:
        expr_part, alias_part = _split_select_expr_alias(item)
        expr_l = str(expr_part or "").lower()
        if re.search(rf"\b{target_func}\s*\(", expr_l, flags=re.I):
            if re.search(rf"\b{re.escape(best_col_l)}\b", expr_l, flags=re.I):
                target_present = True
                break
        if aggregate_pat.search(expr_l) and re.search(rf"\b{re.escape(best_col_l)}\b", expr_l, flags=re.I):
            target_present = True
            break
        alias_l = str(alias_part or "").strip().lower()
        if alias_l and re.search(r"\b(?:earliest|oldest|latest|newest|most\s+recent|minimum|maximum)\b", alias_l, flags=re.I):
            if re.search(r"\b(?:date|time|timestamp|datetime)\b", alias_l, flags=re.I):
                target_present = True
                break
    if target_present:
        return sql

    group_items = [
        str(item or "").strip()
        for item in _split_top_level_commas(parsed.get("groupby") or "")
        if str(item or "").strip()
    ]
    if not group_items:
        return sql
    group_norms = {_norm_expr(item) for item in group_items if _norm_expr(item)}

    simple_group_projection_count = 0
    aggregate_projection_count = 0
    for item in select_items:
        expr_part, _alias_part = _split_select_expr_alias(item)
        expr_norm = _norm_expr(expr_part)
        if expr_norm in group_norms:
            simple_group_projection_count += 1
            continue
        if aggregate_pat.search(expr_part or ""):
            aggregate_projection_count += 1
    if simple_group_projection_count == 0 or aggregate_projection_count == 0:
        return sql

    projected_date_raw = any(
        re.search(rf"\b{re.escape(best_col_l)}\b", str(_split_select_expr_alias(item)[0] or ""), flags=re.I)
        and not aggregate_pat.search(str(_split_select_expr_alias(item)[0] or ""))
        for item in select_items
    )
    if projected_date_raw:
        return sql

    metric_expr = f"{target_func}({qualifier}.{best_col})"
    rebuilt_select = ", ".join(select_items + [metric_expr])

    out_lines = [
        f"SELECT {rebuilt_select}",
        f"FROM {from_core}",
    ]
    where_clause = str(parsed.get("where") or "").strip()
    if where_clause:
        out_lines.append(where_clause)
    out_lines.append(f"GROUP BY {str(parsed.get('groupby') or '').strip()}")
    having_clause = str(parsed.get("having") or "").strip()
    if having_clause:
        if having_clause.lower().startswith("having "):
            out_lines.append(having_clause)
        else:
            out_lines.append(f"HAVING {having_clause}")
    tail = str(parsed.get("tail") or "").strip()
    if tail:
        out_lines.append(tail)

    fixed = "\n".join(part for part in out_lines if part).strip()
    if str(sql).strip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_positive_row_filters(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop hallucinated row-level positive numeric filters in grouped queries.

    Conservative scope:
    - grouped flat query only
    - top-level AND-only WHERE
    - only simple `col > 0` / `col >= 1` predicates
    - never drops when question explicitly asks positivity/availability intent
      (e.g. "in stock", "available", "non-zero", "greater than 0")
    - keeps predicates when the filtered column is explicitly mentioned
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql

    parsed = _parse_select_from_groupby(sql) or _parse_flat_groupby_clauses(sql)
    if not parsed:
        return sql

    where_clause = (parsed.get("where") or "").strip()
    if not where_clause or not where_clause.lower().startswith("where "):
        return sql
    where_body = where_clause[6:].strip()
    if not where_body or _has_top_level_or(where_body):
        return sql

    # Do not touch questions that explicitly ask for positive/availability semantics.
    if any_phrase_in_text(q, positive_row_filter_keep_phrases()):
        return sql

    group_items = _split_top_level_commas(parsed.get("groupby") or "")
    if not group_items:
        return sql

    simple_col_pat = re.compile(
        r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$"""
    )
    grouped_cols: Set[str] = set()
    for item in group_items:
        m_group = simple_col_pat.match(str(item or "").strip())
        if not m_group:
            continue
        grouped_cols.add((m_group.group(2) or "").strip().lower())

    positive_pat = re.compile(
        r"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*(?P<op>>|>=)\s*(?P<num>\d+(?:\.\d+)?)\s*$"""
    )

    def _col_name(expr: str) -> str:
        m = simple_col_pat.match(str(expr or "").strip())
        if not m:
            return ""
        return (m.group(2) or "").strip().lower()

    q_tokens = set(re.findall(r"[a-z0-9]+", q))

    def _column_mentioned(col_name: str) -> bool:
        if not col_name:
            return False
        col_phrase = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_name or ""))
        col_phrase = re.sub(r"[_\W]+", " ", col_phrase).strip().lower()
        if not col_phrase:
            return False
        phrase_pat = re.escape(col_phrase).replace(r"\ ", r"\s+")
        if re.search(rf"\b{phrase_pat}\b", q, flags=re.I):
            return True
        col_tokens = [t for t in re.findall(r"[a-z0-9]+", col_phrase) if len(t) >= 3]
        if not col_tokens:
            return False
        overlap = {t for t in col_tokens if t in q_tokens}
        if len(col_tokens) == 1:
            return bool(overlap)
        return len(overlap) >= 2

    def _strip_outer_parens(text: str) -> str:
        s0 = str(text or "").strip()
        while s0.startswith("(") and s0.endswith(")"):
            inner = s0[1:-1].strip()
            if not inner:
                break
            depth = 0
            balanced = True
            for idx, ch in enumerate(s0):
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth < 0:
                        balanced = False
                        break
                    if depth == 0 and idx != len(s0) - 1:
                        balanced = False
                        break
            if not balanced or depth != 0:
                break
            s0 = inner
        return s0

    conds = _split_top_level_and(where_body)
    if not conds:
        return sql

    keep_conds: List[str] = []
    removed_any = False
    for cond in conds:
        c0 = str(cond or "").strip()
        if not c0:
            continue
        c_norm = _strip_outer_parens(c0)
        m_pos = positive_pat.match(c_norm)
        if not m_pos:
            keep_conds.append(c0)
            continue

        col_l = _col_name(m_pos.group("col") or "")
        op = str(m_pos.group("op") or "").strip()
        try:
            num = float(m_pos.group("num") or "0")
        except Exception:
            num = -1.0

        # Restrict to the common hallucinated positivity shapes.
        is_positive_shape = (op == ">" and abs(num - 0.0) < 1e-9) or (op == ">=" and abs(num - 1.0) < 1e-9)
        if (
            is_positive_shape
            and col_l
            and col_l not in grouped_cols
            and not _column_mentioned(col_l)
        ):
            removed_any = True
            continue

        keep_conds.append(c0)

    if not removed_any:
        return sql

    out_lines = [
        f"SELECT {parsed['select'].strip()}",
        f"FROM {parsed['from_core'].strip()}",
    ]
    if keep_conds:
        out_lines.append(f"WHERE {' AND '.join(keep_conds)}")
    out_lines.append(f"GROUP BY {parsed['groupby'].strip()}")
    if parsed.get("having"):
        out_lines.append(parsed["having"].strip())
    if parsed.get("tail"):
        out_lines.append(parsed["tail"].strip())

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_literal_row_filters(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop hallucinated string-literal row filters in grouped single-table queries.

    Conservative scope:
    - grouped flat query only
    - single-table FROM (no JOIN / derived table)
    - top-level AND-only WHERE
    - only simple `col = 'literal'` / `col IN ('a', 'b', ...)` predicates
    - never drops when the question explicitly mentions the filtered column
      or any of the literal values
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql

    parsed = _parse_select_from_groupby(sql) or _parse_flat_groupby_clauses(sql)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    if not from_core or re.search(r"(?is)\bjoin\b", from_core) or "(" in from_core:
        return sql

    where_clause = (parsed.get("where") or "").strip()
    if not where_clause or not where_clause.lower().startswith("where "):
        return sql
    where_body = where_clause[6:].strip()
    if not where_body or _has_top_level_or(where_body):
        return sql

    group_items = _split_top_level_commas(parsed.get("groupby") or "")
    if not group_items:
        return sql

    simple_col_pat = re.compile(
        r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$"""
    )
    grouped_cols: Set[str] = set()
    for item in group_items:
        m_group = simple_col_pat.match(str(item or "").strip())
        if not m_group:
            continue
        grouped_cols.add((m_group.group(2) or "").strip().lower())

    string_lit_pat = r"""(?:'[^']*'|"[^"]*")"""
    eq_pat = re.compile(
        rf"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*=\s*(?P<lit>{string_lit_pat})\s*$"""
    )
    eq_rev_pat = re.compile(
        rf"""(?is)^\s*(?P<lit>{string_lit_pat})\s*=\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*$"""
    )
    neq_pat = re.compile(
        rf"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*(?:!=|<>)\s*(?P<lit>{string_lit_pat})\s*$"""
    )
    neq_rev_pat = re.compile(
        rf"""(?is)^\s*(?P<lit>{string_lit_pat})\s*(?:!=|<>)\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*$"""
    )
    in_pat = re.compile(
        rf"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+IN\s*\(\s*(?P<items>{string_lit_pat}(?:\s*,\s*{string_lit_pat})*)\s*\)\s*$"""
    )
    not_in_pat = re.compile(
        rf"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s+NOT\s+IN\s*\(\s*(?P<items>{string_lit_pat}(?:\s*,\s*{string_lit_pat})*)\s*\)\s*$"""
    )

    def _col_name(expr: str) -> str:
        m = simple_col_pat.match(str(expr or "").strip())
        if not m:
            return ""
        return (m.group(2) or "").strip().lower()

    q_tokens = set(re.findall(r"[a-z0-9]+", q))

    def _column_mentioned(col_name: str) -> bool:
        if not col_name:
            return False
        col_phrase = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_name or ""))
        col_phrase = re.sub(r"[_\W]+", " ", col_phrase).strip().lower()
        if not col_phrase:
            return False
        phrase_pat = re.escape(col_phrase).replace(r"\ ", r"\s+")
        if re.search(rf"\b{phrase_pat}\b", q, flags=re.I):
            return True
        col_tokens = [t for t in re.findall(r"[a-z0-9]+", col_phrase) if len(t) >= 3]
        if not col_tokens:
            return False
        overlap = {t for t in col_tokens if t in q_tokens}
        if len(col_tokens) == 1:
            return bool(overlap)
        return len(overlap) >= 2

    def _literal_text(token: str) -> str:
        raw = str(token or "").strip()
        if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {"'", '"'}:
            raw = raw[1:-1]
        return raw.strip().lower()

    def _literal_mentioned(token: str) -> bool:
        lit = _literal_text(token)
        if not lit:
            return False
        lit_pat = re.escape(lit).replace(r"\ ", r"\s+")
        return re.search(rf"\b{lit_pat}\b", q, flags=re.I) is not None

    def _strip_outer_parens(text: str) -> str:
        s0 = str(text or "").strip()
        while s0.startswith("(") and s0.endswith(")"):
            inner = s0[1:-1].strip()
            if not inner:
                break
            depth = 0
            balanced = True
            for idx, ch in enumerate(s0):
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth < 0:
                        balanced = False
                        break
                    if depth == 0 and idx != len(s0) - 1:
                        balanced = False
                        break
            if not balanced or depth != 0:
                break
            s0 = inner
        return s0

    conds = _split_top_level_and(where_body)
    if not conds:
        return sql

    keep_conds: List[str] = []
    removed_any = False
    for cond in conds:
        c0 = str(cond or "").strip()
        if not c0:
            continue
        c_norm = _strip_outer_parens(c0)

        match = eq_pat.match(c_norm) or eq_rev_pat.match(c_norm) or neq_pat.match(c_norm) or neq_rev_pat.match(c_norm)
        if match:
            col_l = _col_name(match.group("col") or "")
            lit = match.group("lit") or ""
            if (
                col_l
                and col_l not in grouped_cols
                and not _column_mentioned(col_l)
                and not _literal_mentioned(lit)
            ):
                removed_any = True
                continue
            keep_conds.append(c0)
            continue

        in_match = in_pat.match(c_norm) or not_in_pat.match(c_norm)
        if in_match:
            col_l = _col_name(in_match.group("col") or "")
            lit_tokens = [
                tok.strip()
                for tok in str(in_match.group("items") or "").split(",")
                if tok.strip()
            ]
            if (
                col_l
                and col_l not in grouped_cols
                and lit_tokens
                and not _column_mentioned(col_l)
                and not any(_literal_mentioned(tok) for tok in lit_tokens)
            ):
                removed_any = True
                continue
            keep_conds.append(c0)
            continue

        keep_conds.append(c0)

    if not removed_any:
        return sql

    out_lines = [
        f"SELECT {parsed['select'].strip()}",
        f"FROM {from_core}",
    ]
    if keep_conds:
        out_lines.append(f"WHERE {' AND '.join(keep_conds)}")
    out_lines.append(f"GROUP BY {parsed['groupby'].strip()}")
    if parsed.get("having"):
        out_lines.append(parsed["having"].strip())
    if parsed.get("tail"):
        out_lines.append(parsed["tail"].strip())

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_joined_identifier_literal_filters(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop hallucinated identifier-like literal row filters in grouped JOIN queries.

    Conservative scope:
    - top-level grouped query
    - at least one visible JOIN in FROM
    - top-level AND-only WHERE
    - only simple equality predicates to a literal
    - only when the filtered column looks like a PK/FK/sequence identifier,
      is not projected/grouped/ordered, and is not mentioned in the question
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql

    def _parse_grouped_query_clauses_allowing_derived(text: str) -> Optional[dict]:
        s0 = str(text or "").strip().rstrip(";").strip()
        if not s0:
            return None
        if re.match(r"(?is)^\s*WITH\b", s0):
            return None

        sel_pos = _find_top_level_clause(s0, "select")
        from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
        group_pos = _find_top_level_clause(s0, "group by", max(0, from_pos + len("from")))
        if sel_pos != 0 or from_pos < 0 or group_pos < 0:
            return None

        where_pos = _find_top_level_clause(s0, "where", from_pos + len("from"))
        having_pos = _find_top_level_clause(s0, "having", group_pos + len("group by"))
        order_pos = _find_top_level_clause(s0, "order by", group_pos + len("group by"))
        limit_pos = _find_top_level_clause(s0, "limit", group_pos + len("group by"))

        from_end_candidates = [group_pos]
        if where_pos >= 0 and where_pos < group_pos:
            from_end_candidates.append(where_pos)
        from_end = min(from_end_candidates)
        where_clause = s0[where_pos:group_pos].strip() if where_pos >= 0 and where_pos < group_pos else ""

        group_end_candidates = [
            pos for pos in (having_pos, order_pos, limit_pos)
            if pos >= 0 and pos > group_pos
        ]
        group_end = min(group_end_candidates) if group_end_candidates else len(s0)

        having_clause = ""
        if having_pos >= 0:
            having_end_candidates = [
                pos for pos in (order_pos, limit_pos)
                if pos >= 0 and pos > having_pos
            ]
            having_end = min(having_end_candidates) if having_end_candidates else len(s0)
            having_clause = s0[having_pos:having_end].strip()

        tail_start_candidates = [
            pos for pos in (order_pos, limit_pos)
            if pos >= 0 and pos > group_pos
        ]
        tail_start = min(tail_start_candidates) if tail_start_candidates else -1
        tail = s0[tail_start:].strip() if tail_start >= 0 else ""

        return {
            "select": s0[sel_pos + len("select"):from_pos].strip(),
            "from_core": s0[from_pos + len("from"):from_end].strip(),
            "where": where_clause,
            "groupby": s0[group_pos + len("group by"):group_end].strip(),
            "having": having_clause,
            "tail": tail,
        }

    parsed = _parse_select_from_groupby(sql) or _parse_flat_groupby_clauses(sql)
    if not parsed:
        parsed = _parse_grouped_query_clauses_allowing_derived(sql)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    if not from_core or not re.search(r"(?is)\bjoin\b", from_core):
        return sql

    where_clause = str(parsed.get("where") or "").strip()
    if not where_clause or not where_clause.lower().startswith("where "):
        return sql
    where_body = where_clause[6:].strip()
    if not where_body or _has_top_level_or(where_body):
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}") or {}
    alias_to_table_l = {
        str(alias or "").strip("`").lower(): str(table or "").strip("`").lower()
        for alias, table in alias_to_table.items()
        if str(alias or "").strip() and str(table or "").strip()
    }
    if not alias_to_table_l:
        return sql

    simple_col_pat = re.compile(
        r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$"""
    )
    literal_pat = r"""(?:'[^']*'|"[^"]*"|-?\d+(?:\.\d+)?)"""
    eq_pat = re.compile(
        rf"""(?is)^\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*=\s*(?P<lit>{literal_pat})\s*$"""
    )
    eq_rev_pat = re.compile(
        rf"""(?is)^\s*(?P<lit>{literal_pat})\s*=\s*(?P<col>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*$"""
    )

    select_text = " ".join(
        part
        for part in (
            str(parsed.get("select") or "").strip(),
            str(parsed.get("groupby") or "").strip(),
            str(parsed.get("having") or "").strip(),
            str(parsed.get("tail") or "").strip(),
        )
        if part
    ).lower()
    q_tokens = set(re.findall(r"[a-z0-9]+", q))

    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}

    def _split_col_ref(expr: str) -> Tuple[str, str]:
        m = simple_col_pat.match(str(expr or "").strip())
        if not m:
            return ("", "")
        return (
            str(m.group(1) or "").strip("`").lower(),
            str(m.group(2) or "").strip("`"),
        )

    def _column_mentioned(col_name: str) -> bool:
        col_phrase = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(col_name or ""))
        col_phrase = re.sub(r"[_\W]+", " ", col_phrase).strip().lower()
        if not col_phrase:
            return False
        phrase_pat = re.escape(col_phrase).replace(r"\ ", r"\s+")
        if re.search(rf"\b{phrase_pat}\b", q, flags=re.I):
            return True
        col_tokens = [tok for tok in re.findall(r"[a-z0-9]+", col_phrase) if len(tok) >= 3]
        if not col_tokens:
            return False
        overlap = {tok for tok in col_tokens if tok in q_tokens}
        if len(col_tokens) == 1:
            return bool(overlap)
        return len(overlap) >= 2

    def _literal_mentioned(token: str) -> bool:
        raw = str(token or "").strip()
        if len(raw) >= 2 and raw[0] == raw[-1] and raw[0] in {"'", '"'}:
            raw = raw[1:-1]
        lit = raw.strip().lower()
        if not lit:
            return False
        if re.fullmatch(r"-?\d+(?:\.\d+)?", lit):
            return re.search(rf"\b{re.escape(lit)}\b", q, flags=re.I) is not None
        lit_pat = re.escape(lit).replace(r"\ ", r"\s+")
        return re.search(rf"\b{lit_pat}\b", q, flags=re.I) is not None

    def _looks_like_identifier_filter(alias_l: str, col_l: str) -> bool:
        table_l = alias_to_table_l.get(alias_l, "")
        col_raw = str(col_l or "").strip("`")
        col_norm = col_raw.lower()
        if not table_l or not col_norm:
            return False
        try:
            id_col = str(get_id_column(table_l) or "").strip("`").lower()
        except Exception:
            id_col = ""
        if id_col and col_norm == id_col:
            return True

        if col_norm in {
            str(fk_col or "").strip("`").lower()
            for fk_col in (fk_raw.get(table_l, {}) or {})
            if str(fk_col or "").strip()
        }:
            return True

        try:
            role_l = str(get_column_role(table_l, col_raw) or get_column_role(table_l, col_norm) or "").strip().lower()
        except Exception:
            role_l = ""
        if role_l in {"pk", "fk", "id", "identifier"}:
            return True

        tokens = re.findall(
            r"[a-z0-9]+",
            re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", col_raw).replace("_", " ").lower(),
        )
        if any(tok in {"line", "sequence", "position", "row"} for tok in tokens):
            return True
        return bool(tokens) and tokens[-1] in {"id", "code", "number", "key"}

    def _strip_outer_parens(text: str) -> str:
        s0 = str(text or "").strip()
        while s0.startswith("(") and s0.endswith(")"):
            inner = s0[1:-1].strip()
            if not inner:
                break
            depth = 0
            balanced = True
            for idx, ch in enumerate(s0):
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth < 0:
                        balanced = False
                        break
                    if depth == 0 and idx != len(s0) - 1:
                        balanced = False
                        break
            if not balanced or depth != 0:
                break
            s0 = inner
        return s0

    conds = _split_top_level_and(where_body)
    if not conds:
        return sql

    keep_conds: List[str] = []
    removed_any = False
    for cond in conds:
        c0 = str(cond or "").strip()
        if not c0:
            continue
        c_norm = _strip_outer_parens(c0)

        match = eq_pat.match(c_norm) or eq_rev_pat.match(c_norm)
        if not match:
            keep_conds.append(c0)
            continue

        alias_l, col_l = _split_col_ref(match.group("col") or "")
        lit = match.group("lit") or ""
        if not alias_l or not col_l:
            keep_conds.append(c0)
            continue
        if _column_mentioned(col_l) or _literal_mentioned(lit):
            keep_conds.append(c0)
            continue
        if re.search(
            rf"(?<![A-Za-z0-9_]){re.escape(alias_l)}\s*\.\s*`?{re.escape(col_l)}(?![A-Za-z0-9_])",
            select_text,
            flags=re.I,
        ):
            keep_conds.append(c0)
            continue
        if not _looks_like_identifier_filter(alias_l, col_l):
            keep_conds.append(c0)
            continue
        removed_any = True

    if not removed_any:
        return sql

    out_lines = [
        f"SELECT {str(parsed.get('select') or '').strip()}",
        f"FROM {from_core}",
    ]
    if keep_conds:
        out_lines.append(f"WHERE {' AND '.join(keep_conds)}")
    out_lines.append(f"GROUP BY {str(parsed.get('groupby') or '').strip()}")
    if str(parsed.get("having") or "").strip():
        out_lines.append(str(parsed.get("having") or "").strip())
    if str(parsed.get("tail") or "").strip():
        out_lines.append(str(parsed.get("tail") or "").strip())

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_metric_operand_group_keys(sql: str, question: str, ctx: str = "") -> str:
    """
    Drop leaked raw group keys that are only serving as aggregate operand columns.

    Conservative scope:
    - flat single-table grouped query only
    - no JOIN / window / derived-table / set-op SQL
    - question must expose one clear grouping span ("By ...", "for each ...", etc.)
    - only removes simple raw column dimensions that:
      1) are not the primary requested grouping dimension
      2) appear in both SELECT and GROUP BY
      3) are referenced inside aggregate metrics
      4) are not referenced by HAVING / ORDER BY
    """
    if not sql or not question:
        return sql

    s = str(sql or "").strip()
    q = str(question or "").strip()
    if not s or not q:
        return sql
    if re.search(r"(?is)\b(?:join|union|intersect|except|with)\b", s):
        return sql
    if re.search(r"(?is)\bOVER\s*\(", s):
        return sql
    if re.search(r"(?is)\b(?:FROM|JOIN)\s*\(\s*SELECT\b", s):
        return sql

    parsed = _parse_flat_groupby_clauses(sql) or _parse_select_from_groupby(sql)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    if not from_core or re.search(r"(?is)\bjoin\b", from_core):
        return sql

    select_items = [str(it).strip() for it in _split_top_level_commas(parsed.get("select") or "") if str(it or "").strip()]
    group_items = [str(it).strip() for it in _split_top_level_commas(parsed.get("groupby") or "") if str(it or "").strip()]
    if len(select_items) < 3 or len(group_items) < 2:
        return sql

    def _extract_grouping_span(text: str) -> str:
        q0 = str(text or "").strip()
        patterns = [
            r"(?is)^\s*by\s+(?P<span>.+?)(?:\s*,\s*(?:return|show|list|find|give|include)\b|[.?!]|$)",
            r"(?is)\bgroup(?:ed)?(?:\s+\w+)?\s+by\s+(?P<span>.+?)(?:\s*,\s*(?:return|show|list|find|give|include)\b|\s+(?:return|show|list|find|give|include|sort|order)\b|[.?!]|$)",
            r"(?is)\bfor\s+each\s+(?P<span>.+?)(?:\s*,\s*(?:return|show|list|find|give|include)\b|\s+(?:return|show|list|find|give|include|sort|order)\b|[.?!]|$)",
            r"(?is)\bper\s+(?P<span>.+?)(?:\s*,\s*(?:return|show|list|find|give|include)\b|\s+(?:return|show|list|find|give|include|sort|order)\b|[.?!]|$)",
            r"(?is)\beach\s+(?P<span>.+?)(?:\s*,\s*(?:return|show|list|find|give|include)\b|\s+(?:return|show|list|find|give|include|sort|order)\b|[.?!]|$)",
        ]
        for pat in patterns:
            m = re.search(pat, q0, flags=re.I)
            if m:
                return str(m.group("span") or "").strip()
        return ""

    grouping_span = _extract_grouping_span(q)
    if not grouping_span:
        return sql

    def _tokenize(text: str) -> Set[str]:
        expanded = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or "").replace("_", " "))
        return {
            tok for tok in re.findall(r"[a-z0-9]+", expanded.lower())
            if tok
        }

    span_tokens = _tokenize(grouping_span)
    if not span_tokens:
        return sql

    def _is_metric_expr(expr: str) -> bool:
        e = str(expr or "").strip()
        if not e:
            return False
        return bool(
            re.search(r"\b(?:COUNT|SUM|AVG|MIN|MAX|STDDEV|VARIANCE|GROUP_CONCAT)\s*\(", e, flags=re.I)
            or re.search(r"\bOVER\s*\(", e, flags=re.I)
        )

    simple_col_pat = re.compile(
        r"""(?is)^\s*(?:`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$"""
    )

    def _simple_col_name(expr: str) -> str:
        m = simple_col_pat.match(str(expr or "").strip())
        if not m:
            return ""
        return (m.group(2) or "").strip().lower()

    dim_candidates: List[Dict[str, Any]] = []
    metric_exprs: List[str] = []
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        if not expr:
            continue
        if _is_metric_expr(expr):
            metric_exprs.append(expr)
            continue
        dim_tokens = _tokenize(expr)
        if alias:
            dim_tokens.update(_tokenize(alias))
        score = len(dim_tokens & span_tokens)
        expr_text = " ".join(sorted(dim_tokens))
        span_text = " ".join(sorted(span_tokens))
        if expr_text and span_text and (expr_text in span_text or span_text in expr_text):
            score += 2
        dim_candidates.append(
            {
                "item": item,
                "expr": expr,
                "alias": alias,
                "tokens": dim_tokens,
                "score": score,
                "simple_col": _simple_col_name(expr),
            }
        )

    if len(dim_candidates) < 2 or not metric_exprs:
        return sql

    ranked = sorted(dim_candidates, key=lambda d: int(d.get("score") or 0), reverse=True)
    if int(ranked[0].get("score") or 0) <= 0:
        return sql
    if len(ranked) > 1 and int(ranked[0].get("score") or 0) == int(ranked[1].get("score") or 0):
        return sql

    primary_expr_norm = _normalize_sql_expr_for_match(str(ranked[0].get("expr") or ""))
    tail_text = " ".join(
        p for p in [str(parsed.get("having") or "").strip(), str(parsed.get("tail") or "").strip()]
        if p
    ).lower()

    drop_cols: Set[str] = set()
    for cand in dim_candidates:
        col_name = str(cand.get("simple_col") or "").strip().lower()
        expr_norm = _normalize_sql_expr_for_match(str(cand.get("expr") or ""))
        if not col_name or expr_norm == primary_expr_norm:
            continue
        if not any(col_name in _referenced_column_tokens(metric) for metric in metric_exprs):
            continue
        if re.search(rf"(?<![A-Za-z0-9_]){re.escape(col_name)}(?![A-Za-z0-9_])", tail_text, flags=re.I):
            continue
        drop_cols.add(col_name)

    if not drop_cols:
        return sql

    def _matches_dropped_group_item(item: str) -> bool:
        col_name = _simple_col_name(item)
        if col_name and col_name in drop_cols:
            return True
        return False

    new_select_items: List[str] = []
    removed_any = False
    for item in select_items:
        expr, _alias = _split_select_expr_alias(item)
        col_name = _simple_col_name(expr)
        if col_name and col_name in drop_cols:
            removed_any = True
            continue
        new_select_items.append(item)

    new_group_items = [item for item in group_items if not _matches_dropped_group_item(item)]
    if not removed_any or len(new_group_items) == len(group_items) or not new_group_items:
        return sql

    out_lines = [
        f"SELECT {', '.join(new_select_items)}",
        f"FROM {from_core}",
    ]
    if parsed.get("where"):
        out_lines.append(str(parsed["where"]).strip())
    out_lines.append(f"GROUP BY {', '.join(new_group_items)}")
    if parsed.get("having"):
        out_lines.append(str(parsed["having"]).strip())
    if parsed.get("tail"):
        out_lines.append(str(parsed["tail"]).strip())

    fixed = "\n".join(out_lines).strip()
    if not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_tautological_positive_count_having(sql: str, question: str = "", ctx: str = "") -> str:
    """
    Drop HAVING predicates that only assert a positive COUNT over an already
    required grouped rowset.

    In an INNER-JOIN grouped query, every emitted group necessarily has at
    least one joined row after WHERE filtering, so COUNT(non-null-key) > 0 and
    COUNT(*) > 0 do not add semantics. LEFT/RIGHT/FULL joins are excluded
    because those predicates can intentionally remove preserved zero-match
    groups.
    """
    if not sql or "having" not in sql.lower():
        return sql
    parsed = _parse_select_from_groupby(sql) or _parse_flat_groupby_clauses(sql)
    if not parsed:
        return sql

    from_core = (parsed.get("from_core") or "").strip()
    if re.search(r"\b(?:LEFT|RIGHT|FULL)\s+JOIN\b", from_core, flags=re.I):
        return sql

    having_clause = (parsed.get("having") or "").strip()
    if not having_clause.lower().startswith("having "):
        return sql
    having_body = having_clause[7:].strip()
    if not having_body or _has_top_level_or(having_body):
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}") or {}
    alias_to_table_l = {
        str(alias or "").strip("`").lower(): str(table or "").strip("`").lower()
        for alias, table in alias_to_table.items()
        if str(alias or "").strip() and str(table or "").strip()
    }

    def _is_nonnull_key(alias: str, col: str) -> bool:
        alias_l = str(alias or "").strip("`").lower()
        col_l = str(col or "").strip("`").lower()
        table_l = alias_to_table_l.get(alias_l, "")
        if not table_l or not col_l:
            return False
        try:
            id_col = str(get_id_column(table_l) or "").strip("`").lower()
        except Exception:
            id_col = ""
        if id_col and col_l == id_col:
            return True
        try:
            fk_raw = get_fk_relationships() or {}
        except Exception:
            fk_raw = {}
        return col_l in {
            str(fk_col or "").strip("`").lower()
            for fk_col in (fk_raw.get(table_l, {}) or {})
            if str(fk_col or "").strip()
        }

    count_positive_pat = re.compile(
        r"""(?is)^\s*COUNT\s*\(\s*(?:DISTINCT\s+)?(?:
                \*
                |
                `?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?
            )\s*\)\s*(?:>\s*0|>=\s*1)\s*$""",
        flags=re.X,
    )

    keep: List[str] = []
    removed = False
    for cond in _split_top_level_and(having_body):
        c0 = str(cond or "").strip()
        if not c0:
            continue
        m = count_positive_pat.match(c0)
        if m and (not m.group("alias") or _is_nonnull_key(m.group("alias") or "", m.group("col") or "")):
            removed = True
            continue
        keep.append(c0)

    if not removed:
        return sql

    out_lines = [
        f"SELECT {parsed['select'].strip()}",
        f"FROM {from_core}",
    ]
    if (parsed.get("where") or "").strip():
        out_lines.append(parsed["where"].strip())
    out_lines.append(f"GROUP BY {parsed['groupby'].strip()}")
    if keep:
        out_lines.append("HAVING " + " AND ".join(keep))
    if (parsed.get("tail") or "").strip():
        out_lines.append(parsed["tail"].strip())

    fixed = "\n".join(out_lines).strip()
    if sql.strip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _dedupe_top_level_having_conjuncts(sql: str) -> str:
    """
    Drop duplicated top-level HAVING conjuncts after repair rewrites.

    Conservative scope:
    - GROUP BY query with a top-level HAVING clause
    - top-level AND-only HAVING body
    - only removes semantically identical conjuncts after lightweight
      normalization; preserves original order of the first occurrence
    """
    if not sql or "having" not in sql.lower():
        return sql

    parsed = _parse_select_from_groupby(sql) or _parse_flat_groupby_clauses(sql)
    if not parsed:
        return sql

    having_clause = str(parsed.get("having") or "").strip()
    if not having_clause.lower().startswith("having "):
        return sql
    having_body = having_clause[7:].strip()
    if not having_body or _has_top_level_or(having_body):
        return sql

    def _strip_outer_parens(text: str) -> str:
        s0 = str(text or "").strip()
        while s0.startswith("(") and s0.endswith(")"):
            inner = s0[1:-1].strip()
            if not inner:
                break
            depth = 0
            balanced = True
            for idx, ch in enumerate(s0):
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth < 0:
                        balanced = False
                        break
                    if depth == 0 and idx != len(s0) - 1:
                        balanced = False
                        break
            if not balanced or depth != 0:
                break
            s0 = inner
        return s0

    keep: List[str] = []
    seen: Set[str] = set()
    removed = False
    for cond in _split_top_level_and(having_body):
        c0 = str(cond or "").strip()
        if not c0:
            continue
        norm = _normalize_sql_expr_for_match(_strip_outer_parens(c0))
        if norm and norm in seen:
            removed = True
            continue
        if norm:
            seen.add(norm)
        keep.append(c0)

    if not removed:
        return sql

    out_lines = [
        f"SELECT {parsed['select'].strip()}",
        f"FROM {str(parsed.get('from_core') or '').strip()}",
    ]
    if (parsed.get("where") or "").strip():
        out_lines.append(str(parsed["where"]).strip())
    out_lines.append(f"GROUP BY {str(parsed.get('groupby') or '').strip()}")
    if keep:
        out_lines.append("HAVING " + " AND ".join(keep))
    if (parsed.get("tail") or "").strip():
        out_lines.append(str(parsed["tail"]).strip())

    fixed = "\n".join(out_lines).strip()
    if sql.strip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _drop_unrequested_temporal_filters(sql: str, question: str, ctx: str = "") -> str:
    """
    Remove hallucinated temporal WHERE predicates when question has no temporal intent.

    Scope is intentionally conservative:
    - only runs for winner-row/ranking shaped SQL (ROW_NUMBER / RANK),
    - skips questions that explicitly mention temporal constraints.
    """
    if not sql:
        return sql

    q = (question or "").lower().strip()
    if not q:
        return sql

    low_sql = sql.lower()
    if "row_number(" not in low_sql and "rank(" not in low_sql and "dense_rank(" not in low_sql:
        return sql

    ordinal_row_context = bool(
        re.search(
            r"\b(?:first|second|third|fourth|fifth|1st|2nd|3rd|4th|5th)\b"
            r"(?:\s+\w+){0,8}\s+\b(?:row|record|entry)\b",
            q,
            flags=re.I,
        )
        and re.search(
            r"\b(?:sort(?:ed|ing)?|order(?:ed|ing)?)\b(?:\s+\w+){0,8}\s+by\b",
            q,
            flags=re.I,
        )
    )
    if ordinal_row_context:
        return sql

    # Keep temporal predicates when question clearly asks for temporal scope/filter.
    temporal_terms = (
        "latest", "most recent", "newest", "earliest", "oldest", "recent",
        "year", "month", "day", "date", "time", "today", "yesterday",
        "current", "tahun", "bulan", "hari", "tanggal", "waktu",
    )
    has_temporal_intent = any(t in q for t in temporal_terms) or bool(
        re.search(r"\b(?:19|20)\d{2}\b", q) or
        re.search(r"\b\d{4}-\d{2}-\d{2}\b", q)
    )
    if has_temporal_intent:
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    def _flatten_and(expr_node):
        if isinstance(expr_node, exp.And):
            return _flatten_and(expr_node.this) + _flatten_and(expr_node.expression)
        return [expr_node]

    def _combine_and(exprs):
        if not exprs:
            return None
        cur = exprs[0]
        for nxt in exprs[1:]:
            cur = exp.And(this=cur, expression=nxt)
        return cur

    def _is_temporal_predicate(expr_node) -> bool:
        if expr_node is None:
            return False

        expr_sql = expr_node.sql(dialect="mysql").lower()
        if (
            "row_number(" in expr_sql
            or "rank(" in expr_sql
            or "dense_rank(" in expr_sql
            or re.search(r"\brn\s*=\s*\d+\b", expr_sql)
            or "select" in expr_sql
        ):
            return False

        s = expr_sql
        # Date literals or explicit temporal functions
        if re.search(r"'(?:19|20)\d{2}-\d{2}-\d{2}'", s):
            return True
        if re.search(r"\b(?:year|month|day|date|timestamp|curdate|current_date|now)\s*\(", s):
            return True

        # Date/time-like column references
        for col in expr_node.find_all(exp.Column):
            col_name = (col.name or "").lower()
            if any(k in col_name for k in ("date", "time", "year", "month", "day")):
                return True
        return False

    try:
        parsed = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    removed_any = False
    for where in list(parsed.find_all(exp.Where)):
        cond = where.this
        if cond is None:
            continue
        # Keep conservative behavior when OR is present.
        if any(isinstance(n, exp.Or) for n in cond.walk()):
            continue

        conjuncts = _flatten_and(cond)
        keep = []
        removed_local = False
        for c in conjuncts:
            if _is_temporal_predicate(c):
                removed_local = True
            else:
                keep.append(c)

        if not removed_local:
            continue

        removed_any = True
        if keep:
            new_cond = _combine_and(keep)
            where.set("this", new_cond)
        else:
            parent = where.parent
            if parent is not None:
                for key, val in list(parent.args.items()):
                    if val is where:
                        parent.set(key, None)
                        break

    if not removed_any:
        return sql

    fixed = parsed.sql(dialect="mysql")
    if sql.strip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _rewrite_missing_temporal_exclusion_from_null_filter(sql: str, question: str, ctx: str = "") -> str:
    """
    Synthesize a correlated NOT EXISTS filter for grouped exclusion questions
    when the draft uses a temporal NULL shortcut instead of true anti-existence.

    Canonical near-miss:
      WHERE YEAR(t.orderDate) = 2004
        AND YEAR(t.shippedDate) IS NULL

    Rewritten to:
      WHERE YEAR(t.orderDate) = 2004
        AND NOT EXISTS (
          SELECT 1
          FROM bridge anti_src
          JOIN temporal anti_dt ON ...
          WHERE anti_src.entity_fk = outer.entity_id
            AND YEAR(anti_dt.orderDate) = 2005
        )

    Safety:
    - only for explicit exclusion wording with two distinct years,
    - only for flat grouped queries that already expose an entity -> bridge ->
      temporal join path,
    - only when the positive year predicate already identifies the temporal
      column to reuse for the exclusion year.
    """
    if not sql or not question:
        return sql

    q = (question or "").lower()
    if not re.search(r"\b(?:never|without|exclude|excluding|not)\b", q):
        return sql

    low_sql = (sql or "").lower()
    if "not exists" in low_sql or re.search(r"\bNOT\s+IN\s*\(", sql, flags=re.I):
        return sql

    year_tokens = [m.group(0) for m in re.finditer(r"\b(?:19|20)\d{2}\b", question or "")]
    ordered_years: List[str] = []
    seen_years: Set[str] = set()
    for token in year_tokens:
        if token in seen_years:
            continue
        seen_years.add(token)
        ordered_years.append(token)
    if len(ordered_years) < 2:
        return sql
    include_year, exclude_year = ordered_years[0], ordered_years[1]

    parsed = _parse_select_from_groupby(sql)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    where_part = str(parsed.get("where") or "").strip()
    groupby_part = str(parsed.get("groupby") or "").strip()
    if not from_core or not where_part or not groupby_part:
        return sql
    if re.search(r"\b(?:FROM|JOIN)\s*\(", from_core, flags=re.I):
        return sql

    explicit_aliases: Dict[str, str] = {}
    ordered_aliases: List[Tuple[str, str]] = []
    for match in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)(?:\s+(?:AS\s+)?([A-Za-z_][A-Za-z0-9_]*))?""",
        f"FROM {from_core}",
    ):
        table_expr = str(match.group(1) or "").strip()
        if not table_expr or table_expr.startswith("("):
            continue
        table_plain = table_expr.replace("`", "").split(".")[-1].strip()
        alias_name = str(match.group(2) or "").strip() or table_plain
        if not alias_name:
            continue
        explicit_aliases[alias_name.lower()] = table_plain
        ordered_aliases.append((alias_name, table_plain))
    if len(ordered_aliases) < 3:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(table or "").lower(): {str(col or "").lower() for col in (cols or set())}
                for table, cols in (allowed or {}).items()
                if str(table or "").strip()
            }
        except Exception:
            allowed_cols = {}

    def _plain_table_name(table_name: str) -> str:
        return str(table_name or "").replace("`", "").split(".")[-1].strip()

    def _table_cols(table_name: str) -> Set[str]:
        table_l = _plain_table_name(table_name).lower()
        if not table_l:
            return set()
        cols = set(allowed_cols.get(table_l, set()))
        if analyzer is not None:
            try:
                cols.update(str(col or "").lower() for col in analyzer.get_table_columns(table_l))
            except Exception:
                pass
        return cols

    def _is_temporal_column(table_name: str, col_name: str) -> bool:
        table_l = _plain_table_name(table_name).lower()
        col_l = str(col_name or "").lower().strip()
        if not table_l or not col_l or col_l not in _table_cols(table_name):
            return False
        if analyzer is not None:
            try:
                if analyzer.is_date_column(table_l, col_l):
                    return True
            except Exception:
                pass
        return any(token in col_l for token in ("date", "time", "timestamp"))

    fk_map_raw = {}
    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, rels in fk_map_raw.items():
        src_l = str(src or "").lower().strip()
        if not src_l:
            continue
        fk_map.setdefault(src_l, {})
        for fk_col, tgt in (rels or {}).items():
            fk_l = str(fk_col or "").lower().strip()
            tgt_l = str(tgt or "").lower().strip()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    try:
        transaction_tables = {
            str(table or "").strip().lower()
            for table in (get_transaction_tables() or [])
            if str(table or "").strip()
        }
    except Exception:
        transaction_tables = set()

    where_body = re.sub(r"^\s*WHERE\s+", "", where_part, flags=re.I).strip()
    if not where_body or _has_top_level_or(where_body):
        return sql
    conjuncts = _split_top_level_and(where_body)
    if not conjuncts:
        return sql

    include_idx = -1
    temporal_alias = ""
    temporal_col = ""
    for idx, cond in enumerate(conjuncts):
        match = re.match(
            r"""(?is)^\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*((?:19|20)\d{2})\s*$""",
            str(cond or "").strip(),
        )
        if not match:
            continue
        alias_name, col_name, year_value = match.group(1), match.group(2), match.group(3)
        if year_value != include_year:
            continue
        table_name = explicit_aliases.get(alias_name.lower()) or ""
        if not table_name or not _is_temporal_column(table_name, col_name):
            continue
        include_idx = idx
        temporal_alias = alias_name
        temporal_col = col_name
        break
    if include_idx < 0 or not temporal_alias or not temporal_col:
        return sql

    null_idx = -1
    for idx, cond in enumerate(conjuncts):
        if idx == include_idx:
            continue
        cond_s = str(cond or "").strip()
        year_null = re.match(
            r"""(?is)^\s*YEAR\s*\(\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s+IS\s+NULL\s*$""",
            cond_s,
        )
        direct_null = re.match(
            r"""(?is)^\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s+IS\s+NULL\s*$""",
            cond_s,
        )
        match = year_null or direct_null
        if not match:
            continue
        alias_name, col_name = match.group(1), match.group(2)
        if alias_name.lower() != temporal_alias.lower():
            continue
        table_name = explicit_aliases.get(alias_name.lower()) or ""
        if not table_name or not _is_temporal_column(table_name, col_name):
            continue
        null_idx = idx
        break
    if null_idx < 0:
        return sql

    eq_pairs: List[Tuple[str, str, str, str]] = []
    for match in re.finditer(
        r"""(?is)`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
        from_core,
    ):
        eq_pairs.append(
            (
                str(match.group(1) or "").strip().lower(),
                str(match.group(2) or "").strip(),
                str(match.group(3) or "").strip().lower(),
                str(match.group(4) or "").strip(),
            )
        )

    def _join_pairs(left_alias: str, right_alias: str) -> List[Tuple[str, str]]:
        out: List[Tuple[str, str]] = []
        left_l = str(left_alias or "").lower().strip()
        right_l = str(right_alias or "").lower().strip()
        for a1, c1, a2, c2 in eq_pairs:
            if a1 == left_l and a2 == right_l:
                out.append((c1, c2))
            elif a2 == left_l and a1 == right_l:
                out.append((c2, c1))
        return out

    temporal_table = explicit_aliases.get(temporal_alias.lower()) or ""
    if not temporal_table:
        return sql

    temporal_pk_hint = str(get_id_column(temporal_table) or "").strip()
    bridge_candidates: List[Tuple[int, str, str, str, str]] = []
    for alias_name, table_name in ordered_aliases:
        alias_l = alias_name.lower()
        table_l = _plain_table_name(table_name).lower()
        if alias_l == temporal_alias.lower():
            continue
        bridge_pairs = _join_pairs(alias_name, temporal_alias)
        if not bridge_pairs:
            continue
        for fk_col, target_table in fk_map.get(table_l, {}).items():
            if _plain_table_name(target_table).lower() != _plain_table_name(temporal_table).lower():
                continue
            matched_temporal_pk = ""
            for bridge_col, temporal_join_col in bridge_pairs:
                if bridge_col.lower() != fk_col.lower():
                    continue
                if temporal_pk_hint and temporal_join_col.lower() == temporal_pk_hint.lower():
                    matched_temporal_pk = temporal_join_col
                    break
                if not matched_temporal_pk:
                    matched_temporal_pk = temporal_join_col
            if not matched_temporal_pk:
                continue
            score = 0
            if table_l in transaction_tables:
                score += 2
            if temporal_pk_hint and matched_temporal_pk.lower() == temporal_pk_hint.lower():
                score += 3
            bridge_candidates.append((score, alias_name, table_name, fk_col, matched_temporal_pk))
    if not bridge_candidates:
        return sql
    bridge_candidates.sort(key=lambda item: (-item[0], item[1], item[2], item[3], item[4]))
    best_bridge_score = bridge_candidates[0][0]
    best_bridges = [item for item in bridge_candidates if item[0] == best_bridge_score]
    if len(best_bridges) != 1:
        return sql
    _bridge_score, bridge_alias, bridge_table, bridge_temporal_fk_col, temporal_pk_col = best_bridges[0]

    groupby_text = str(groupby_part or "")
    entity_candidates: List[Tuple[int, str, str, str, str]] = []
    for alias_name, table_name in ordered_aliases:
        alias_l = alias_name.lower()
        table_l = _plain_table_name(table_name).lower()
        if alias_l in {temporal_alias.lower(), bridge_alias.lower()}:
            continue
        join_pairs = _join_pairs(alias_name, bridge_alias)
        if not join_pairs:
            continue
        entity_id_hint = str(get_id_column(table_name) or "").strip()
        best_pair_score = -1
        best_pair: Optional[Tuple[str, str]] = None
        for entity_col, bridge_col in join_pairs:
            score = 0
            if entity_id_hint and entity_col.lower() == entity_id_hint.lower():
                score += 4
            if entity_col.lower().endswith(("id", "number", "code", "key")):
                score += 2
            if bridge_col.lower().endswith(("id", "number", "code", "key")):
                score += 1
            if score > best_pair_score:
                best_pair_score = score
                best_pair = (entity_col, bridge_col)
        if not best_pair:
            continue
        score = best_pair_score
        if table_l not in transaction_tables:
            score += 4
        if re.search(rf"""(?is)\b`?{re.escape(alias_name)}`?\s*\.""", groupby_text):
            score += 3
        entity_candidates.append((score, alias_name, table_name, best_pair[0], best_pair[1]))
    if not entity_candidates:
        return sql
    entity_candidates.sort(key=lambda item: (-item[0], item[1], item[2], item[3], item[4]))
    best_entity_score = entity_candidates[0][0]
    best_entities = [item for item in entity_candidates if item[0] == best_entity_score]
    if len(best_entities) != 1:
        return sql
    _entity_score, entity_alias, _entity_table, entity_key_col, bridge_entity_fk_col = best_entities[0]

    used_aliases = {alias.lower() for alias in explicit_aliases.keys()}

    def _pick_alias(base: str) -> str:
        seed = re.sub(r"[^A-Za-z0-9_]+", "_", str(base or "")).strip("_") or "t"
        if not re.match(r"[A-Za-z_]", seed[0]):
            seed = f"t_{seed}"
        candidate = seed
        idx = 2
        while candidate.lower() in used_aliases:
            candidate = f"{seed}_{idx}"
            idx += 1
        used_aliases.add(candidate.lower())
        return candidate

    anti_bridge_alias = _pick_alias("anti_src")
    anti_temporal_alias = _pick_alias("anti_dt")
    anti_not_exists = (
        "NOT EXISTS (\n"
        "  SELECT 1\n"
        f"  FROM {bridge_table} AS {anti_bridge_alias}\n"
        f"  JOIN {temporal_table} AS {anti_temporal_alias}\n"
        f"    ON {anti_temporal_alias}.{temporal_pk_col} = {anti_bridge_alias}.{bridge_temporal_fk_col}\n"
        f"  WHERE {anti_bridge_alias}.{bridge_entity_fk_col} = {entity_alias}.{entity_key_col}\n"
        f"    AND YEAR({anti_temporal_alias}.{temporal_col}) = {exclude_year}\n"
        ")"
    )

    remaining_conds = [
        str(cond or "").strip()
        for idx, cond in enumerate(conjuncts)
        if idx != null_idx and str(cond or "").strip()
    ]
    if not remaining_conds:
        return sql
    remaining_conds.append(anti_not_exists)

    having_clause = f"\nHAVING {str(parsed.get('having') or '').strip()}" if str(parsed.get("having") or "").strip() else ""
    tail_clause = f"\n{str(parsed.get('tail') or '').strip()}" if str(parsed.get("tail") or "").strip() else ""
    fixed = (
        f"SELECT {str(parsed.get('select') or '').strip()}\n"
        f"FROM {from_core}\n"
        f"WHERE {' AND '.join(remaining_conds)}\n"
        f"GROUP BY {groupby_part}"
        f"{having_clause}"
        f"{tail_clause};"
    )
    return fixed


def _prefer_not_exists_for_simple_exclusion(sql: str, question: str, ctx: str = "") -> str:
    """
    Canonicalize simple `NOT IN (SELECT key FROM table ...)` anti-joins into
    correlated `NOT EXISTS (...)` for better NULL-safety.

    This is intentionally conservative:
    - only runs when the question has clear exclusion wording,
    - only rewrites simple subquery forms,
    - skips grouped/distinct/limited/ordered subqueries.
    """
    if not sql:
        return sql

    low_sql = sql.lower()
    if not re.search(r"\bnot\b[\s`\"A-Za-z0-9_.]*\bin\s*\(", low_sql, flags=re.I):
        return sql

    q = (question or "").lower()
    if not q:
        return sql

    has_exclusion_intent = bool(
        re.search(
            r"\b(?:no|without(?:\s+any)?|never|have\s+never|has\s+never)\b",
            q,
            flags=re.I,
        )
    )
    if not has_exclusion_intent:
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        parsed = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    changed = False

    def _transform(node):
        nonlocal changed

        if not isinstance(node, exp.Not):
            return node

        in_node = node.this
        if not isinstance(in_node, exp.In):
            return node

        lhs = in_node.this
        subq = in_node.args.get("query")

        if not isinstance(lhs, exp.Column):
            return node
        if not isinstance(subq, exp.Subquery):
            return node
        if not isinstance(subq.this, exp.Select):
            return node

        sel = subq.this

        # Only rewrite simple anti-join subqueries.
        if len(sel.expressions or []) != 1:
            return node
        if sel.args.get("group") or sel.args.get("having") or sel.args.get("distinct"):
            return node
        if sel.args.get("limit") or sel.args.get("order") or sel.args.get("union"):
            return node

        rhs_expr = sel.expressions[0]
        rhs_base = rhs_expr.this if isinstance(rhs_expr, exp.Alias) else rhs_expr
        if not isinstance(rhs_base, exp.Column):
            return node

        new_sel = sel.copy()
        new_sel.set("expressions", [exp.Literal.number(1)])

        corr_eq = exp.EQ(this=rhs_base.copy(), expression=lhs.copy())
        existing_where = new_sel.args.get("where")
        if isinstance(existing_where, exp.Where) and existing_where.this is not None:
            new_where_cond = exp.And(this=existing_where.this.copy(), expression=corr_eq)
        else:
            new_where_cond = corr_eq
        new_sel.set("where", exp.Where(this=new_where_cond))

        changed = True
        return exp.Not(this=exp.Exists(this=new_sel))

    rewritten = parsed.transform(_transform)
    if not changed:
        return sql

    fixed = rewritten.sql(dialect="mysql")
    if sql.strip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _repair_exclusion_subject_fk_correlation(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair simple exclusion anti-joins that correlate an excluded child table
    through another child/support table's identifier instead of the subject FK.

    Example family:
      FROM customers c
      JOIN payments p ...
      WHERE NOT EXISTS (
        SELECT 1 FROM orders o WHERE o.orderNumber = p.checkNumber
      )

    becomes:
      WHERE NOT EXISTS (
        SELECT 1 FROM orders o WHERE o.customerNumber = c.customerNumber
      )

    Safety:
    - only flat top-level WHERE filters,
    - only simple NOT EXISTS subqueries over one real table,
    - only when the excluded table has exactly one FK to the outer subject table,
    - only when the question expresses exclusion intent.
    """
    s = str(sql or "").strip()
    q = str(question or "").strip().lower()
    if not s or not re.search(r"\bNOT\s+EXISTS\b", s, flags=re.I):
        return sql
    if not re.search(r"\b(?:no|without(?:\s+any)?|never|have\s+never|has\s+never|exclude|excluding|not)\b", q, flags=re.I):
        return sql

    parsed = _parse_select_from_groupby(s) or _parse_flat_groupby_clauses(s)
    if not parsed:
        return sql

    from_core = str(parsed.get("from_core") or "").strip()
    where_clause = str(parsed.get("where") or "").strip()
    if not from_core or not where_clause.lower().startswith("where "):
        return sql

    outer_from_match = re.match(
        r"""(?is)^\s*`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?""",
        from_core,
    )
    if not outer_from_match:
        return sql

    subject_table = str(outer_from_match.group("table") or "").strip("`").lower()
    subject_alias = str(outer_from_match.group("alias") or "").strip() or subject_table
    if not subject_table or not subject_alias:
        return sql

    alias_to_table = _parse_from_join_aliases(f"SELECT 1 FROM {from_core}") or {}
    alias_to_table_l = {
        str(alias or "").strip("`").lower(): str(table or "").strip("`").lower()
        for alias, table in alias_to_table.items()
        if str(alias or "").strip() and str(table or "").strip()
    }
    if subject_alias.lower() not in alias_to_table_l:
        alias_to_table_l[subject_alias.lower()] = subject_table

    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}

    not_exists_pat = re.compile(
        r"""(?is)NOT\s+EXISTS\s*\(\s*SELECT\s+1\s+FROM\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?\s+WHERE\s+(?P<body>.+?)\s*\)"""
    )
    corr_eq_pat = re.compile(
        r"""(?is)`?(?P<a1>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<c1>[A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?(?P<a2>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<c2>[A-Za-z_][A-Za-z0-9_]*)`?"""
    )

    changed = False

    def _question_mentions_table(table_name: str) -> bool:
        for term in _entity_words_for_table(table_name):
            term_l = str(term or "").strip().lower()
            if not term_l:
                continue
            pat = re.escape(term_l).replace(r"\ ", r"\s+")
            if re.search(rf"\b{pat}\b", q, flags=re.I):
                return True
        return False

    def _rewrite_not_exists(m: re.Match) -> str:
        nonlocal changed

        inner_table = str(m.group("table") or "").strip("`").lower()
        inner_alias = str(m.group("alias") or "").strip() or inner_table
        inner_body = str(m.group("body") or "").strip()
        if not inner_table or not inner_alias or not inner_body:
            return m.group(0)
        if _has_top_level_or(inner_body):
            return m.group(0)
        if not _question_mentions_table(inner_table):
            return m.group(0)

        fk_candidates = [
            str(fk_col or "").strip("`")
            for fk_col, tgt in (fk_raw.get(inner_table, {}) or {}).items()
            if str(tgt or "").strip("`").lower() == subject_table
        ]
        if len(fk_candidates) != 1:
            return m.group(0)

        subject_fk_col = fk_candidates[0]
        subject_key_col = str(get_fk_target_column(inner_table, subject_fk_col) or "").strip("`")
        if not subject_key_col:
            subject_key_col = str(get_id_column(subject_table) or "").strip("`")
        if not subject_key_col:
            return m.group(0)

        corr_matches = []
        for eq_match in corr_eq_pat.finditer(inner_body):
            a1 = str(eq_match.group("a1") or "").strip().lower()
            c1 = str(eq_match.group("c1") or "").strip()
            a2 = str(eq_match.group("a2") or "").strip().lower()
            c2 = str(eq_match.group("c2") or "").strip()
            if a1 == inner_alias.lower() and a2 in alias_to_table_l:
                corr_matches.append((eq_match, c1, a2, c2))
            elif a2 == inner_alias.lower() and a1 in alias_to_table_l:
                corr_matches.append((eq_match, c2, a1, c1))

        if len(corr_matches) != 1:
            return m.group(0)

        eq_match, inner_col, outer_alias_l, outer_col = corr_matches[0]
        if (
            outer_alias_l == subject_alias.lower()
            and inner_col.lower() == subject_fk_col.lower()
            and outer_col.lower() == subject_key_col.lower()
        ):
            return m.group(0)

        replacement = f"{inner_alias}.{subject_fk_col} = {subject_alias}.{subject_key_col}"
        new_body = f"{inner_body[:eq_match.start()]}{replacement}{inner_body[eq_match.end():]}"
        if new_body == inner_body:
            return m.group(0)

        changed = True
        alias_sql = f" AS {inner_alias}" if inner_alias.lower() != inner_table else ""
        return f"NOT EXISTS(SELECT 1 FROM {inner_table}{alias_sql} WHERE {new_body})"

    fixed = not_exists_pat.sub(_rewrite_not_exists, s)
    if not changed:
        return sql
    if s.endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _repair_temporal_not_exists_scope(sql: str, ctx: str = "") -> str:
    """
    Repair NOT EXISTS subqueries that apply temporal predicates through a
    non-temporal fact table, by adding the unique FK-connected temporal table.

    Example family this fixes generically:
      NOT EXISTS (
        SELECT 1
        FROM line_items li
        WHERE YEAR(orderDate) = 2005
          AND li.item_id = outer.item_id
      )
    ->
      NOT EXISTS (
        SELECT 1
        FROM line_items li
        JOIN orders ord ON ord.orderNumber = li.orderNumber
        WHERE YEAR(ord.orderDate) = 2005
          AND li.item_id = outer.item_id
      )

    Safety:
    - Only touches NOT EXISTS subqueries.
    - Only when a temporal column used in the subquery is missing from all
      inner tables.
    - Only when there is exactly one FK-connected target table that exposes
      that temporal column.
    - No question-ID or schema-name hardcoding.
    """
    if not sql or "not exists" not in (sql or "").lower():
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        parsed = sqlglot.parse_one(sql, read="mysql")
    except Exception:
        return sql

    outer_explicit_alias_to_table: Dict[str, str] = {}

    def _register_outer_src(src_expr) -> None:
        if not isinstance(src_expr, exp.Table):
            return
        table_name = str(src_expr.name or "").strip("`").lower()
        if not table_name:
            return
        alias_name = str(src_expr.alias_or_name or table_name).strip("`").lower()
        if alias_name:
            outer_explicit_alias_to_table[alias_name] = table_name

    outer_from_arg = parsed.args.get("from") or parsed.args.get("from_")
    if outer_from_arg is not None:
        _register_outer_src(getattr(outer_from_arg, "this", None))
    for outer_join_expr in parsed.args.get("joins") or []:
        _register_outer_src(getattr(outer_join_expr, "this", None))

    def _flatten_and_conditions(node):
        if node is None:
            return []
        if isinstance(node, exp.And):
            return _flatten_and_conditions(node.left) + _flatten_and_conditions(node.right)
        return [node]

    def _rebuild_and_conditions(conds: List["exp.Expression"]):
        if not conds:
            return None
        expr_out = conds[0]
        for cond in conds[1:]:
            expr_out = exp.and_(expr_out, cond)
        return expr_out

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(t or "").lower(): {str(c or "").lower() for c in (cols or set())}
                for t, cols in (allowed or {}).items()
                if str(t or "").strip()
            }
        except Exception:
            allowed_cols = {}

    fk_map_raw = {}
    try:
        fk_map_raw = get_fk_relationships() or {}
    except Exception:
        fk_map_raw = {}

    fk_map: Dict[str, Dict[str, str]] = {}
    for src, rels in fk_map_raw.items():
        src_l = str(src or "").lower().strip()
        if not src_l:
            continue
        fk_map.setdefault(src_l, {})
        for fk_col, tgt in (rels or {}).items():
            fk_l = str(fk_col or "").lower().strip()
            tgt_l = str(tgt or "").lower().strip()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    def _cols_for_table(table_name: str) -> Set[str]:
        tbl_l = str(table_name or "").lower().strip()
        if not tbl_l:
            return set()
        cols = set(allowed_cols.get(tbl_l, set()))
        if analyzer is not None:
            try:
                cols.update(str(c or "").lower() for c in analyzer.get_table_columns(tbl_l))
            except Exception:
                pass
        return cols

    def _is_temporal_col(col_name: str) -> bool:
        c = str(col_name or "").lower()
        return any(k in c for k in ("date", "time", "timestamp", "year", "month", "day"))

    def _make_unique_alias(base: str, used_aliases: Set[str]) -> str:
        seed = re.sub(r"[^a-z0-9_]+", "_", (base or "").lower()).strip("_") or "t"
        candidate = seed
        idx = 2
        while candidate in used_aliases:
            candidate = f"{seed}_{idx}"
            idx += 1
        return candidate

    def _build_join_node(target_table: str, target_alias: str, source_alias: str, fk_col: str):
        target_pk = (get_id_column(target_table) or "").strip()
        target_cols = _cols_for_table(target_table)
        if not target_pk or target_pk.lower() not in target_cols:
            if fk_col.lower() in target_cols:
                target_pk = fk_col
            else:
                return None
        join_sql = (
            f"SELECT 1 FROM dummy d "
            f"INNER JOIN {target_table} AS {target_alias} "
            f"ON {target_alias}.{target_pk} = {source_alias}.{fk_col}"
        )
        try:
            join_parsed = sqlglot.parse_one(join_sql, read="mysql")
            joins = join_parsed.args.get("joins") or []
            return joins[0] if joins else None
        except Exception:
            return None

    changed = False

    for not_node in list(parsed.find_all(exp.Not)):
        exists_node = not_node.this
        if not isinstance(exists_node, exp.Exists):
            continue
        inner = exists_node.this
        if not isinstance(inner, exp.Select):
            continue

        alias_to_table: Dict[str, str] = {}
        explicit_alias_to_table: Dict[str, str] = {}

        def _register_src(src_expr) -> None:
            if not isinstance(src_expr, exp.Table):
                return
            table_name = str(src_expr.name or "").strip("`").lower()
            if not table_name:
                return
            alias_name = str(src_expr.alias_or_name or table_name).strip("`").lower()
            if alias_name:
                explicit_alias_to_table[alias_name] = table_name
                alias_to_table[alias_name] = table_name
            alias_to_table.setdefault(table_name, table_name)

        from_arg = inner.args.get("from") or inner.args.get("from_")
        if from_arg is not None:
            _register_src(getattr(from_arg, "this", None))
        for join_expr in inner.args.get("joins") or []:
            _register_src(getattr(join_expr, "this", None))

        if not explicit_alias_to_table:
            continue

        used_aliases = set(explicit_alias_to_table.keys())
        all_inner_tables = set(explicit_alias_to_table.values())
        where_expr = inner.args.get("where")
        if not isinstance(where_expr, exp.Where) or where_expr.this is None:
            continue

        def _is_current_select_column(col_expr) -> bool:
            anc = getattr(col_expr, "parent", None)
            while anc is not None:
                if isinstance(anc, exp.Select):
                    return anc is inner
                anc = getattr(anc, "parent", None)
            return False

        replacement_alias_by_col: Dict[str, str] = {}
        joins_to_add = []

        for col_expr in list(where_expr.find_all(exp.Column)):
            if not _is_current_select_column(col_expr):
                continue
            col_name = str(col_expr.name or "").strip("`").lower()
            if not _is_temporal_col(col_name):
                continue

            qual = str(col_expr.table or "").strip("`").lower()
            if qual:
                src_table = explicit_alias_to_table.get(qual) or alias_to_table.get(qual)
                if not src_table:
                    continue
                if col_name in _cols_for_table(src_table):
                    continue
                source_aliases = [qual] if qual in explicit_alias_to_table else []
            else:
                if any(col_name in _cols_for_table(tbl) for tbl in all_inner_tables):
                    continue
                source_aliases = list(explicit_alias_to_table.keys())

            candidates: List[Tuple[str, str, str]] = []
            for src_alias in source_aliases:
                src_table = explicit_alias_to_table.get(src_alias)
                if not src_table:
                    continue
                for fk_col, tgt_table in fk_map.get(src_table, {}).items():
                    if col_name not in _cols_for_table(tgt_table):
                        continue
                    candidates.append((src_alias, fk_col, tgt_table))

            candidates = list(dict.fromkeys(candidates))
            if len(candidates) != 1:
                continue

            src_alias, fk_col, tgt_table = candidates[0]

            existing_target_alias = next(
                (a for a, t in explicit_alias_to_table.items() if t == tgt_table and col_name in _cols_for_table(t)),
                "",
            )
            if existing_target_alias:
                replacement_alias_by_col[col_name] = existing_target_alias
                continue

            new_alias = _make_unique_alias(f"{tgt_table}_anti", used_aliases)
            join_node = _build_join_node(tgt_table, new_alias, src_alias, fk_col)
            if join_node is None:
                continue

            joins_to_add.append(join_node)
            explicit_alias_to_table[new_alias] = tgt_table
            alias_to_table[new_alias] = tgt_table
            used_aliases.add(new_alias)
            all_inner_tables.add(tgt_table)
            replacement_alias_by_col[col_name] = new_alias

        if replacement_alias_by_col:
            if joins_to_add:
                existing_joins = list(inner.args.get("joins") or [])
                existing_joins.extend(joins_to_add)
                inner.set("joins", existing_joins)

            def _rewrite_col(node):
                if not isinstance(node, exp.Column):
                    return node
                if not _is_current_select_column(node):
                    return node
                col_name = str(node.name or "").strip("`").lower()
                target_alias = replacement_alias_by_col.get(col_name, "")
                if not target_alias:
                    return node

                qual = str(node.table or "").strip("`").lower()
                if qual:
                    src_table = explicit_alias_to_table.get(qual) or alias_to_table.get(qual)
                    if src_table and col_name in _cols_for_table(src_table):
                        return node
                else:
                    if any(col_name in _cols_for_table(tbl) for tbl in all_inner_tables if tbl != explicit_alias_to_table.get(target_alias)):
                        # Still ambiguous in inner scope; skip rewrite.
                        return node

                changed_local = exp.column(col_name, table=target_alias)
                return changed_local

            inner = inner.transform(_rewrite_col)
            exists_node.set("this", inner)
            changed = True

        temporal_fk_cols_by_alias: Dict[str, Set[str]] = {}
        for inner_alias, inner_table in explicit_alias_to_table.items():
            target_tables = {
                tgt_table
                for _fk_col, tgt_table in (fk_map.get(inner_table, {}) or {}).items()
                if tgt_table in all_inner_tables
            }
            if not target_tables:
                continue
            for fk_col, tgt_table in (fk_map.get(inner_table, {}) or {}).items():
                if tgt_table not in target_tables:
                    continue
                target_cols = _cols_for_table(tgt_table)
                if any(_is_temporal_col(col_name) for col_name in target_cols):
                    temporal_fk_cols_by_alias.setdefault(inner_alias, set()).add(fk_col.lower())

        inner_where = inner.args.get("where")
        if isinstance(inner_where, exp.Where) and inner_where.this is not None and temporal_fk_cols_by_alias:
            predicates = _flatten_and_conditions(inner_where.this)
            removable_idxs: Set[int] = set()
            correlations_by_inner_alias: Dict[str, List[Tuple[int, str, str, str, str]]] = {}

            for idx, predicate in enumerate(predicates):
                if not isinstance(predicate, exp.EQ):
                    continue
                left = getattr(predicate, "left", None)
                right = getattr(predicate, "right", None)
                if not isinstance(left, exp.Column) or not isinstance(right, exp.Column):
                    continue

                left_alias = str(left.table or "").strip("`").lower()
                right_alias = str(right.table or "").strip("`").lower()
                left_col = str(left.name or "").strip("`").lower()
                right_col = str(right.name or "").strip("`").lower()
                if not left_alias or not right_alias or not left_col or not right_col:
                    continue

                if left_alias in explicit_alias_to_table and right_alias not in explicit_alias_to_table and right_alias in outer_explicit_alias_to_table:
                    correlations_by_inner_alias.setdefault(left_alias, []).append(
                        (idx, left_col, right_alias, right_col, explicit_alias_to_table[left_alias])
                    )
                elif right_alias in explicit_alias_to_table and left_alias not in explicit_alias_to_table and left_alias in outer_explicit_alias_to_table:
                    correlations_by_inner_alias.setdefault(right_alias, []).append(
                        (idx, right_col, left_alias, left_col, explicit_alias_to_table[right_alias])
                    )

            for inner_alias, corr_items in correlations_by_inner_alias.items():
                temporal_fk_cols = temporal_fk_cols_by_alias.get(inner_alias, set())
                if len(corr_items) < 2 or not temporal_fk_cols:
                    continue
                has_non_temporal_corr = any(col_name not in temporal_fk_cols for _idx, col_name, _oa, _oc, _tbl in corr_items)
                if not has_non_temporal_corr:
                    continue
                for pred_idx, col_name, _outer_alias, _outer_col, _inner_table in corr_items:
                    if col_name in temporal_fk_cols:
                        removable_idxs.add(pred_idx)

            if removable_idxs:
                kept_preds = [
                    pred.copy()
                    for idx, pred in enumerate(predicates)
                    if idx not in removable_idxs
                ]
                rebuilt_where = _rebuild_and_conditions(kept_preds)
                if rebuilt_where is not None:
                    inner.set("where", exp.Where(this=rebuilt_where))
                    exists_node.set("this", inner)
                    changed = True

    if not changed:
        return sql

    fixed = parsed.sql(dialect="mysql")
    if sql.strip().endswith(";") and not fixed.endswith(";"):
        fixed += ";"
    return fixed


def _ast_validate_exclusion_logic(sql: str, question: str = "", ctx: str = "") -> Tuple[str, Dict[str, Any]]:
    """
    AST-first validation/routing for exclusion and anti-join repairs.

    Scope for this batch:
    - parseable top-level SELECT queries that already contain one of:
      - NOT EXISTS
      - NOT IN (SELECT ...)
      - LEFT JOIN ... WHERE rhs_col IS NULL anti-join patterns
    - reuse the existing conservative exclusion repair helpers, but only after
      AST has confirmed the query is in the exclusion family

    Guardrails:
    - no rewrite when the AST does not show an exclusion shape
    - every candidate rewrite must remain sqlglot-parseable
    - keep regex/text fallback available when AST does not own the scope
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
        "scope_kinds": [],
    }
    s = str(sql or "").strip()
    if not s:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(s, read=SQL_PARSE_DIALECT or "mysql")
    except Exception as e:
        meta["error"] = f"parse_failed:{type(e).__name__}:{e}"
        return sql, meta

    meta["parse_ok"] = True
    sel = ast if isinstance(ast, exp.Select) else ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        meta["warnings"].append("unsupported_root")
        return sql, meta

    def _join_side(join_expr: "exp.Join") -> str:
        side = join_expr.args.get("side")
        return str(side or "").strip().upper()

    def _left_join_aliases() -> Set[str]:
        left_join_aliases: Set[str] = set()
        for join_expr in sel.args.get("joins") or []:
            if not isinstance(join_expr, exp.Join):
                continue
            if "LEFT" not in _join_side(join_expr):
                continue
            table_expr = getattr(join_expr, "this", None)
            if not isinstance(table_expr, exp.Table):
                continue
            alias_name = str(table_expr.alias_or_name or table_expr.name or "").strip("`").lower()
            table_name = str(table_expr.name or "").strip("`").lower()
            if alias_name:
                left_join_aliases.add(alias_name)
            if table_name:
                left_join_aliases.add(table_name)
        return left_join_aliases

    def _is_null_check_on_left_join_alias(where_expr: Optional["exp.Where"]) -> bool:
        if not isinstance(where_expr, exp.Where) or where_expr.this is None:
            return False

        left_join_aliases = _left_join_aliases()
        if not left_join_aliases:
            return False

        def _column_hits_left_alias(col_expr: Optional["exp.Expression"]) -> bool:
            if not isinstance(col_expr, exp.Column):
                return False
            table_name = str(col_expr.table or "").strip("`").lower()
            return bool(table_name and table_name in left_join_aliases)

        for is_expr in where_expr.find_all(exp.Is):
            left = getattr(is_expr, "this", None)
            right = getattr(is_expr, "expression", None)
            if isinstance(left, exp.Null) and _column_hits_left_alias(right):
                return True
            if isinstance(right, exp.Null) and _column_hits_left_alias(left):
                return True
        return False

    scope_kinds: List[str] = []
    for not_node in sel.find_all(exp.Not):
        inner = not_node.this
        if isinstance(inner, exp.Exists) and "not_exists" not in scope_kinds:
            scope_kinds.append("not_exists")
        elif (
            isinstance(inner, exp.In)
            and isinstance(inner.args.get("query"), (exp.Subquery, exp.Select))
            and "not_in_subquery" not in scope_kinds
        ):
            scope_kinds.append("not_in_subquery")

    if _is_null_check_on_left_join_alias(sel.args.get("where")):
        scope_kinds.append("left_anti_join")

    if not scope_kinds:
        return sql, meta

    meta["handled_scope"] = True
    meta["scope_kinds"] = list(dict.fromkeys(scope_kinds))

    def _validate_candidate(candidate_sql: str, fix_name: str) -> Optional[str]:
        candidate = str(candidate_sql or "").strip()
        if not candidate or candidate == s:
            return None
        parse_target = re.sub(r";+\s*$", "", candidate).strip()
        try:
            sqlglot.parse_one(parse_target, read=SQL_PARSE_DIALECT or "mysql")
        except Exception:
            meta["warnings"].append(f"{fix_name}_parse_rejected")
            return None
        if s.endswith(";") and not candidate.endswith(";"):
            candidate = parse_target + ";"
        return candidate

    current_sql = s

    def _flatten_top_and(expr_in: Optional["exp.Expression"]) -> List["exp.Expression"]:
        if expr_in is None:
            return []
        if isinstance(expr_in, exp.And):
            return _flatten_top_and(expr_in.this) + _flatten_top_and(expr_in.expression)
        return [expr_in]

    def _build_and(exprs: List["exp.Expression"]) -> Optional["exp.Expression"]:
        cleaned = [e for e in exprs if e is not None]
        if not cleaned:
            return None
        out = cleaned[0]
        for nxt in cleaned[1:]:
            out = exp.And(this=out, expression=nxt)
        return out

    def _condition_references_left_join_alias(
        cond: Optional["exp.Expression"],
        left_join_aliases: Set[str],
    ) -> bool:
        if cond is None or not left_join_aliases:
            return False
        for col_expr in cond.find_all(exp.Column):
            table_name = str(getattr(col_expr, "table", "") or "").strip("`").lower()
            if table_name and table_name in left_join_aliases:
                return True
        return False

    if "left_anti_join" in meta["scope_kinds"]:
        group_arg = sel.args.get("group")
        where_arg = sel.args.get("where")
        left_join_aliases = _left_join_aliases()
        if isinstance(group_arg, exp.Group) and isinstance(where_arg, exp.Where) and left_join_aliases:
            where_cond = where_arg.this
            conjuncts = _flatten_top_and(where_cond)
            anti_null_checks: List[Tuple["exp.Expression", "exp.Column"]] = []
            keep_in_where: List["exp.Expression"] = []

            for cond in conjuncts:
                matched_col: Optional["exp.Column"] = None
                if isinstance(cond, exp.Is):
                    left = getattr(cond, "this", None)
                    right = getattr(cond, "expression", None)
                    if isinstance(left, exp.Column) and isinstance(right, exp.Null):
                        matched_col = left
                    elif isinstance(right, exp.Column) and isinstance(left, exp.Null):
                        matched_col = right
                if (
                    matched_col is not None
                    and str(getattr(matched_col, "table", "") or "").strip("`").lower() in left_join_aliases
                ):
                    anti_null_checks.append((cond, matched_col.copy()))
                else:
                    keep_in_where.append(cond.copy())

            mixed_left_join_where = any(
                _condition_references_left_join_alias(cond, left_join_aliases)
                for cond in keep_in_where
            )

            if mixed_left_join_where:
                meta["warnings"].append("mixed_left_join_filters_skipped")
            elif len(anti_null_checks) == 1:
                _anti_cond, anti_col = anti_null_checks[0]
                count_zero = exp.EQ(
                    this=exp.Count(this=anti_col.copy()),
                    expression=exp.Literal.number("0"),
                )
                existing_having = sel.args.get("having")
                existing_having_cond = existing_having.this.copy() if isinstance(existing_having, exp.Having) and existing_having.this is not None else None
                merged_having = _build_and(
                    ([existing_having_cond] if existing_having_cond is not None else [])
                    + [count_zero]
                )
                if merged_having is not None:
                    new_where = _build_and(keep_in_where)
                    if new_where is None:
                        sel.set("where", None)
                    else:
                        sel.set("where", exp.Where(this=new_where))
                    sel.set("having", exp.Having(this=merged_having))
                    rendered = ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
                    if s.endswith(";"):
                        rendered = rendered.rstrip(";") + ";"
                    validated = _validate_candidate(rendered, "grouped_left_anti_join_having_ast")
                    if validated:
                        current_sql = validated
                        meta["fixes"].append("grouped_left_anti_join_having_ast")

    if "left_anti_join" in meta["scope_kinds"] and not meta["fixes"]:
        joins = [j for j in (sel.args.get("joins") or []) if isinstance(j, exp.Join)]
        group_arg = sel.args.get("group")
        where_arg = sel.args.get("where")
        if len(joins) == 1 and group_arg is None and isinstance(where_arg, exp.Where):
            only_join = joins[0]
            join_aliases = _left_join_aliases()
            join_table_expr = getattr(only_join, "this", None)
            join_on_expr = only_join.args.get("on")
            if (
                "LEFT" in _join_side(only_join)
                and isinstance(join_table_expr, exp.Table)
                and join_on_expr is not None
                and join_aliases
            ):
                where_cond = where_arg.this
                conjuncts = _flatten_top_and(where_cond)
                anti_null_checks: List[Tuple["exp.Expression", "exp.Column"]] = []
                keep_in_where: List["exp.Expression"] = []

                for cond in conjuncts:
                    matched_col: Optional["exp.Column"] = None
                    if isinstance(cond, exp.Is):
                        left = getattr(cond, "this", None)
                        right = getattr(cond, "expression", None)
                        if isinstance(left, exp.Column) and isinstance(right, exp.Null):
                            matched_col = left
                        elif isinstance(right, exp.Column) and isinstance(left, exp.Null):
                            matched_col = right
                    if (
                        matched_col is not None
                        and str(getattr(matched_col, "table", "") or "").strip("`").lower() in join_aliases
                    ):
                        anti_null_checks.append((cond, matched_col.copy()))
                    else:
                        keep_in_where.append(cond.copy())

                mixed_join_filters = any(
                    _condition_references_left_join_alias(cond, join_aliases)
                    for cond in keep_in_where
                )

                def _expr_references_join_alias(expr_in: Optional["exp.Expression"]) -> bool:
                    return _condition_references_left_join_alias(expr_in, join_aliases)

                other_join_refs = False
                for select_expr in sel.expressions or []:
                    if _expr_references_join_alias(select_expr):
                        other_join_refs = True
                        break
                if not other_join_refs:
                    for order_expr in ((sel.args.get("order") or exp.Order()).expressions or []):
                        if _expr_references_join_alias(order_expr):
                            other_join_refs = True
                            break
                if not other_join_refs:
                    having_expr = sel.args.get("having")
                    having_cond = having_expr.this if isinstance(having_expr, exp.Having) else None
                    other_join_refs = _expr_references_join_alias(having_cond)

                if mixed_join_filters:
                    meta["warnings"].append("simple_left_anti_join_mixed_filters_skipped")
                elif other_join_refs:
                    meta["warnings"].append("simple_left_anti_join_rhs_refs_skipped")
                elif len(anti_null_checks) == 1:
                    subquery_where_parts = [join_on_expr.copy()]
                    not_exists_where = _build_and(subquery_where_parts)
                    if not_exists_where is not None:
                        anti_subquery = exp.Select()
                        anti_subquery.set("expressions", [exp.Literal.number(1)])
                        anti_subquery.set("from_", exp.From(this=join_table_expr.copy()))
                        anti_subquery.set("where", exp.Where(this=not_exists_where))
                        not_exists_expr = exp.Not(this=exp.Exists(this=anti_subquery))

                        new_where_parts = keep_in_where + [not_exists_expr]
                        new_where = _build_and(new_where_parts)
                        if new_where is not None:
                            sel.set("joins", [])
                            sel.set("where", exp.Where(this=new_where))
                            rendered = ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
                            if s.endswith(";"):
                                rendered = rendered.rstrip(";") + ";"
                            validated = _validate_candidate(rendered, "simple_left_anti_join_not_exists_ast")
                            if validated:
                                current_sql = validated
                                meta["fixes"].append("simple_left_anti_join_not_exists_ast")

    rewrite_steps = [
        ("grouped_temporal_exclusion_bridge_ast", lambda text: _rewrite_two_table_grouped_temporal_exclusion(text, question, ctx)),
        ("missing_temporal_bridge_exclusion_ast", lambda text: _rewrite_missing_temporal_bridge_exclusion(text, question, ctx)),
        ("temporal_year_exclusion_antijoin_ast", lambda text: _rewrite_temporal_year_exclusion_antijoin(text, question, ctx)),
        ("prefer_not_exists_for_simple_exclusion_ast", lambda text: _prefer_not_exists_for_simple_exclusion(text, question, ctx)),
        ("repair_exclusion_subject_fk_correlation_ast", lambda text: _repair_exclusion_subject_fk_correlation(text, question, ctx)),
        ("repair_temporal_not_exists_scope_ast", lambda text: _repair_temporal_not_exists_scope(text, ctx)),
    ]

    for fix_name, fixer in rewrite_steps:
        try:
            candidate = fixer(current_sql)
        except Exception:
            meta["warnings"].append(f"{fix_name}_error")
            continue
        if not candidate or candidate == current_sql:
            continue
        validated = _validate_candidate(candidate, fix_name)
        if not validated:
            continue
        current_sql = validated
        meta["fixes"].append(fix_name)

    meta["warnings"] = list(dict.fromkeys(meta["warnings"]))
    if meta["fixes"]:
        return current_sql, meta
    return sql, meta


def _repair_invalid_year_filter_via_fk_bridge(sql: str, ctx: str = "") -> str:
    """
    Repair invalid YEAR(alias.col)=YYYY predicates when `col` does not exist on
    the aliased table but exists on exactly one FK-connected parent table.

    Generic rewrite shape:
      YEAR(child_alias.missing_date_col) = 2004
    ->
      child_alias.fk_col IN (
          SELECT parent_key_col
          FROM parent_table
          WHERE YEAR(missing_date_col) = 2004
      )

    Safety:
    - only YEAR(...) predicates
    - only when alias table lacks the referenced column
    - only when exactly one FK bridge target is available
    - no hardcoded table/column names
    """
    if not sql or not re.search(r"\bYEAR\s*\(", sql, flags=re.I):
        return sql

    alias_map_raw = _parse_from_join_aliases(sql) or {}
    alias_to_table = {
        str(k or "").strip().replace("`", "").lower(): str(v or "").strip().replace("`", "").lower()
        for k, v in alias_map_raw.items()
        if str(k or "").strip() and str(v or "").strip()
    }
    if not alias_to_table:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed_cols: Dict[str, Set[str]] = {}
    if ctx:
        try:
            allowed = _parse_allowed_identifiers(ctx)
            allowed_cols = {
                str(t or "").strip().lower(): {str(c or "").strip().lower() for c in (cols or set())}
                for t, cols in (allowed or {}).items()
                if str(t or "").strip()
            }
        except Exception:
            allowed_cols = {}

    cols_cache: Dict[str, Set[str]] = {}

    def _cols_for_table(table_name: str) -> Set[str]:
        tbl_l = str(table_name or "").strip().lower()
        if not tbl_l:
            return set()
        if tbl_l in cols_cache:
            return cols_cache[tbl_l]
        cols = set(allowed_cols.get(tbl_l, set()))
        if analyzer is not None:
            try:
                cols.update(str(c or "").strip().lower() for c in analyzer.get_table_columns(tbl_l))
            except Exception:
                pass
        cols_cache[tbl_l] = cols
        return cols

    fk_raw = {}
    try:
        fk_raw = get_fk_relationships() or {}
    except Exception:
        fk_raw = {}
    fk_map: Dict[str, Dict[str, str]] = {}
    for src, rels in fk_raw.items():
        src_l = str(src or "").strip().replace("`", "").lower()
        if not src_l:
            continue
        fk_map.setdefault(src_l, {})
        for fk_col, tgt in (rels or {}).items():
            fk_l = str(fk_col or "").strip().replace("`", "").lower()
            tgt_l = str(tgt or "").strip().replace("`", "").lower()
            if fk_l and tgt_l:
                fk_map[src_l][fk_l] = tgt_l

    year_pat = re.compile(
        r"(?is)\bYEAR\s*\(\s*`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s*=\s*(?P<year>\d{4})\b"
    )

    changed = False

    def _repl_year(m: re.Match) -> str:
        nonlocal changed
        alias = str(m.group("alias") or "").strip().lower()
        col = str(m.group("col") or "").strip().lower()
        year_txt = str(m.group("year") or "").strip()
        if not alias or not col or not year_txt:
            return m.group(0)

        src_table = alias_to_table.get(alias, "")
        if not src_table:
            return m.group(0)

        if col in _cols_for_table(src_table):
            return m.group(0)

        candidates: List[Tuple[str, str, str]] = []
        for fk_col, tgt_table in fk_map.get(src_table, {}).items():
            if not fk_col:
                continue
            src_cols = _cols_for_table(src_table)
            if fk_col not in src_cols:
                continue
            tgt_cols = _cols_for_table(tgt_table)
            if col not in tgt_cols:
                continue
            select_col = fk_col if fk_col in tgt_cols else ""
            if not select_col:
                tgt_id = str(get_id_column(tgt_table) or "").strip().lower()
                if tgt_id and tgt_id in tgt_cols:
                    select_col = tgt_id
            if not select_col:
                continue
            candidates.append((fk_col, tgt_table, select_col))

        candidates = list(dict.fromkeys(candidates))
        if len(candidates) != 1:
            return m.group(0)

        fk_col, tgt_table, select_col = candidates[0]
        changed = True
        return (
            f"{alias}.{fk_col} IN (SELECT {select_col} "
            f"FROM {tgt_table} WHERE YEAR({col}) = {year_txt})"
        )

    # Avoid rewriting inside quoted string literals.
    parts = re.split(r"('(?:''|[^'])*'|\"(?:\"\"|[^\"])*\")", sql)
    for i in range(0, len(parts), 2):
        parts[i] = year_pat.sub(_repl_year, parts[i])
    out = "".join(parts)

    return out if changed else sql
# =======================================================================
# ========= Phase 5 — Pattern, REGEXP, and Predicate Normalization ======
# ========================= Guardrail for Regex =========================
# =======================================================================
# - guardrail_fix_like_regex_anchors
# - question_requires_word_boundary_regex
# - question_requires_regex
# - should_prefer_like_over_regexp
# - rewrite_simple_regexp_to_like
# - rewrite_regexp_literal_to_posix_if_needed
# - guardrail_fix_mysql_regexp_literals

def _guardrail_fix_like_regex_anchors(sql: str, question: str) -> str:
    """
    Fix kesalahan umum LLM: memasukkan anchor regex (^, $) ke LIKE.
    Contoh salah:
      LIKE '^196'   (harusnya starts with -> LIKE '196%')
      LIKE '196$'   (harusnya ends with   -> LIKE '%196')
    """
    if not sql:
        return sql

    q = (question or "").lower()

    starts = any(k in q for k in [
        "starts with", "start with",
        "begins with", "begin with",
        "diawali", "awalan", "awal", "prefix"
    ])
    ends = any(k in q for k in [
        "ends with", "end with",
        "diakhiri", "akhir", "suffix"
    ])
    contains = any(k in q for k in [
        "contains", "contain",
        "mengandung"
    ])

    # Rewrite LIKE '^X' -> LIKE 'X%'
    def repl_starts(m: re.Match) -> str:
        col = m.group(1)
        val = m.group(2)
        return f"{col}LIKE '{val}%'"

    # Rewrite LIKE 'X$' -> LIKE '%X'
    def repl_ends(m: re.Match) -> str:
        col = m.group(1)
        val = m.group(2)
        return f"{col}LIKE '%{val}'"

    if starts:
        sql = re.sub(
            r"(\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s+)LIKE\s+'\^([^']*)'",
            repl_starts,
            sql,
            flags=re.IGNORECASE,
        )

    if ends:
        sql = re.sub(
            r"(\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s+)LIKE\s+'([^']*)\$'",
            repl_ends,
            sql,
            flags=re.IGNORECASE,
        )

    if contains:
        sql = re.sub(
            r"(\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s+)LIKE\s+'\^([^']*)\$'",
            lambda m: f"{m.group(1)}LIKE '%{m.group(2)}%'",
            sql,
            flags=re.IGNORECASE,
        )
        sql = re.sub(
            r"(\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s+)LIKE\s+'\^([^']*)'",
            lambda m: f"{m.group(1)}LIKE '{m.group(2)}%'",
            sql,
            flags=re.IGNORECASE,
        )

    return sql

def _question_requires_word_boundary_regex(question: str) -> bool:
    q = (question or "").lower()

    # strong boundary intent signals
    boundary_phrases = [
        "contain a word that starts with",
        "contains a word that starts with",
        "a word that starts with",
        "word starts with",
        "kata yang diawali",
        "kata yang dimulai",
        "awal kata",
        "whole word",
        "kata utuh",
        "word boundary",
        "batas kata",
        "token",
    ]
    return any(p in q for p in boundary_phrases)


def _extract_whole_word_target(question: str) -> Optional[str]:
    q = question or ""
    patterns = [
        r'whole\s+word\s+["\']([^"\']+)["\']',
        r'word\s+boundary\s+["\']([^"\']+)["\']',
        r'token\s+["\']([^"\']+)["\']',
        r'kata\s+utuh\s+["\']([^"\']+)["\']',
    ]
    for pat in patterns:
        m = re.search(pat, q, flags=re.I)
        if not m:
            continue
        token = (m.group(1) or "").strip()
        if token:
            return token
    return None


def _question_requires_structural_regex(question: str) -> bool:
    q = (question or "").lower()

    structural_patterns = [
        r"\bconsists?\s+of\s+(?:exactly\s+)?(\d+|one|two|three|four|five)\s+words?\b",
        r"\bhas\s+(?:exactly\s+)?(\d+|one|two|three|four|five)\s+words?\b",
        r"\b(?:single|one|two|three|four|five)\s+words?\b(?:\s+separated\s+by\s+(?:a\s+)?space)?",
        r"\bseparated\s+by\s+(?:a\s+)?space\b",
        r"\bword\s+count\b",
    ]
    return any(re.search(pat, q, flags=re.I) for pat in structural_patterns)


def _question_requires_two_word_space_pattern(question: str) -> bool:
    q = (question or "").lower()
    patterns = [
        r"\bconsists?\s+of\s+(?:exactly\s+)?two\s+words?\b",
        r"\bmade\s+up\s+of\s+(?:exactly\s+)?two\s+words?\b",
        r"\bhas\s+(?:exactly\s+)?two\s+words?\b",
        r"\bexactly\s+two\s+words?\b",
        r"\btwo\s+words?\b(?:\s+separated\s+by\s+(?:a\s+)?space)?",
    ]
    return any(re.search(pat, q, flags=re.I) for pat in patterns)


def _extract_structural_word_count(question: str) -> Optional[int]:
    q = (question or "").lower()
    word_to_num = {
        "single": 1,
        "one": 1,
        "two": 2,
        "three": 3,
        "four": 4,
        "five": 5,
    }
    patterns = [
        r"\bconsists?\s+of\s+(?:exactly\s+)?(?P<count>\d+|single|one|two|three|four|five)\s+words?\b",
        r"\bmade\s+up\s+of\s+(?:exactly\s+)?(?P<count>\d+|single|one|two|three|four|five)\s+words?\b",
        r"\bhas\s+(?:exactly\s+)?(?P<count>\d+|single|one|two|three|four|five)\s+words?\b",
        r"\bexactly\s+(?P<count>\d+|single|one|two|three|four|five)\s+words?\b",
        r"\b(?P<count>single|one|two|three|four|five)\s+words?\b(?:\s+separated\s+by\s+(?:a\s+)?space)?",
    ]
    for pat in patterns:
        m = re.search(pat, q, flags=re.I)
        if not m:
            continue
        raw = (m.group("count") or "").strip().lower()
        if raw.isdigit():
            n = int(raw)
            if 1 <= n <= 5:
                return n
            return None
        return word_to_num.get(raw)
    return None


def _extract_followed_by_character_class_regex(question: str) -> Optional[str]:
    """Return a canonical anchored regex for "N letters followed by M digits" shapes."""
    q = (question or "").lower()
    if not q or "followed by" not in q:
        return None

    word_to_num = {
        "one": 1,
        "two": 2,
        "three": 3,
        "four": 4,
        "five": 5,
        "six": 6,
        "seven": 7,
        "eight": 8,
        "nine": 9,
        "ten": 10,
        "eleven": 11,
        "twelve": 12,
    }

    def _count(raw: str) -> Optional[int]:
        raw = (raw or "").strip().lower()
        if raw.isdigit():
            n = int(raw)
            return n if 1 <= n <= 64 else None
        return word_to_num.get(raw)

    def _cls(unit: str) -> Optional[str]:
        u = (unit or "").strip().lower()
        if u.startswith("letter"):
            return "[A-Z]"
        if u.startswith("digit") or u in {"number", "numbers"}:
            return "[0-9]"
        if u.startswith("character") or u.startswith("char"):
            return "."
        return None

    pattern = re.compile(
        r"\b(?:exactly\s+)?(?P<n1>\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\s+"
        r"(?P<u1>letters?|digits?|numbers?|characters?|chars?)\s+"
        r"followed\s+by\s+(?:exactly\s+)?"
        r"(?P<n2>\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\s+"
        r"(?P<u2>letters?|digits?|numbers?|characters?|chars?)\b",
        flags=re.I,
    )
    m = pattern.search(q)
    if not m:
        return None

    n1 = _count(m.group("n1"))
    n2 = _count(m.group("n2"))
    c1 = _cls(m.group("u1"))
    c2 = _cls(m.group("u2"))
    if not n1 or not n2 or not c1 or not c2:
        return None
    return f"^{c1}{{{n1}}}{c2}{{{n2}}}$"


def _question_requires_regex(question: str) -> bool:
    q = (question or "").strip().lower()

    # 1. Deteksi eksplisit (sudah ada di code Anda)
    if any(k in q for k in ["regex", "regexp", "regexp_like", "regular expression"]):
        return True

    # 2. Deteksi jumlah digit yang spesifik (Start Small: Fokus di sini)
    # Ini akan menangkap "3 digits", "three digits", "exactly 4 characters", dll.
    if re.search(r"\b\d+\s+(digit|character|angka|huruf)\b", q):
        return True
    if re.search(r"\b(one|two|three|four|five)\s+(digit|character|angka|huruf)\b", q):
        return True

    # 3. Deteksi pola "followed by" (kasus spesifik Anda)
    if "followed by" in q or "diikuti oleh" in q:
        return True

    # 4. Structural text patterns that need anchored REGEXP, e.g. "exactly two words"
    if _question_requires_structural_regex(question):
        return True

    return False

def _should_prefer_like_over_regexp(question: str) -> bool:
    q = (question or "").lower()

    # kalau boundary atau strict structure → jangan rewrite
    if _question_requires_word_boundary_regex(question):
        return False
    if _question_requires_regex(question):
        return False

    # prefix/suffix/contains sederhana → LIKE ok
    simple_signals = [
        "starts with", "start with", "begins with", "begin with", "diawali", "awalan", "prefix",
        "ends with", "end with", "diakhiri", "suffix",
        "contains", "contain", "mengandung",
    ]
    return any(s in q for s in simple_signals)

def _rewrite_simple_regexp_to_like(sql: str, question: str) -> str:
    """
    Jika pertanyaan hanya butuh LIKE, tapi LLM menghasilkan:
      col REGEXP '^X'  -> col LIKE 'X%'
      col REGEXP 'X$'  -> col LIKE '%X'
    Hanya rewrite untuk pattern sederhana tanpa metachar kompleks.
    """
    if not sql or not _should_prefer_like_over_regexp(question):
        return sql

    # REGEXP '^196' di atas: replace("REGEXP","LIKE") belum terjadi karena r"\1" literal.
    # Jadi kita lakukan rewrite yang lebih eksplisit agar tidak ambigu:
    sql = re.sub(
        r"(\bWHERE\b.*?\b)((?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*)\s+REGEXP\s+'\^([A-Za-z0-9 _-]+)'",
        r"\1\2 LIKE '\3%",
        sql,
        flags=re.IGNORECASE | re.DOTALL,
    )

    # REGEXP '196$' => LIKE '%196'
    sql = re.sub(
        r"(\bWHERE\b.*?\b)((?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*)\s+REGEXP\s+'([A-Za-z0-9 _-]+)\$'",
        r"\1\2 LIKE '%\3'",
        sql,
        flags=re.IGNORECASE | re.DOTALL,
    )

    return sql


def _canonicalize_structural_regex(sql: str, question: str) -> str:
    """
    Canonicalize narrow structural-regex families that are semantically clear but
    easy for the LLM to express incorrectly.

    Current supported family:
      - exactly N words separated by a single space (N = 1..5)
    """
    if not sql:
        return sql
    followed_by_regex = _extract_followed_by_character_class_regex(question)
    if followed_by_regex:
        out = sql
        out = re.sub(
            r"(?is)(REGEXP_LIKE\s*\(\s*[^,]+,\s*)(N?'(?:''|[^'])*'|\"(?:[^\"\\\\]|\\\\.)*\")(\s*\))",
            lambda m: f"{m.group(1)}'{followed_by_regex}'{m.group(3)}",
            out,
        )
        out = re.sub(
            r"(?is)(\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s+\b(?:REGEXP|RLIKE)\b\s*)(N?'(?:''|[^'])*'|\"(?:[^\"\\\\]|\\\\.)*\")",
            lambda m: f"{m.group(1)}'{followed_by_regex}'",
            out,
        )
        return out

    word_count = _extract_structural_word_count(question)
    if not word_count:
        return sql

    canonical = "^" + " ".join(["[^ ]+"] * word_count) + "$"
    out = sql

    # REGEXP_LIKE(col, '...')
    out = re.sub(
        r"(?is)(REGEXP_LIKE\s*\(\s*[^,]+,\s*)(N?'(?:''|[^'])*'|\"(?:[^\"\\\\]|\\\\.)*\")(\s*\))",
        lambda m: f"{m.group(1)}'{canonical}'{m.group(3)}",
        out,
    )

    # col REGEXP '...' / col RLIKE '...'
    out = re.sub(
        r"(?is)(\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s+\b(?:REGEXP|RLIKE)\b\s*)(N?'(?:''|[^'])*'|\"(?:[^\"\\\\]|\\\\.)*\")",
        lambda m: f"{m.group(1)}'{canonical}'",
        out,
    )

    # If the model weakens this to a simple "contains a space" LIKE pattern,
    # strengthen it to the canonical REGEXP instead.
    if word_count == 2:
        out = re.sub(
            r"(?is)(\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s+)LIKE\s+'% %'",
            lambda m: f"{m.group(1)}REGEXP '{canonical}'",
            out,
        )

    return out


def _canonicalize_boundary_regex(sql: str, question: str) -> str:
    """
    Canonicalize narrow word-boundary regex family:
      - contains the whole word "X"

    Rewrites any existing regex/rlike literal (or weak LIKE substring) to the
    canonical MySQL-safe boundary pattern:
      (^|[^[:alnum:]_])X([^[:alnum:]_]|$)
    """
    if not sql or not _question_requires_word_boundary_regex(question):
        return sql
    target = _extract_whole_word_target(question)
    if not target:
        return sql

    canonical = f"(^|[^[:alnum:]_]){re.escape(target)}([^[:alnum:]_]|$)"
    out = sql

    # REGEXP_LIKE(col, '...')
    out = re.sub(
        r"(?is)(REGEXP_LIKE\s*\(\s*[^,]+,\s*)(N?'(?:''|[^'])*'|\"(?:[^\"\\\\]|\\\\.)*\")(\s*\))",
        lambda m: f"{m.group(1)}'{canonical}'{m.group(3)}",
        out,
    )

    # col REGEXP '...' / col RLIKE '...'
    out = re.sub(
        r"(?is)(\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s+\b(?:REGEXP|RLIKE)\b\s*)(N?'(?:''|[^'])*'|\"(?:[^\"\\\\]|\\\\.)*\")",
        lambda m: f"{m.group(1)}'{canonical}'",
        out,
    )

    # Upgrade weak substring LIKE to boundary regex for whole-word intent.
    like_pat = rf"(?is)(\b(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s+)LIKE\s+'%{re.escape(target)}%'"
    out = re.sub(
        like_pat,
        lambda m: f"{m.group(1)}REGEXP '{canonical}'",
        out,
    )

    return out

def _rewrite_regexp_literal_to_posix_if_needed(lit: str) -> str:
    r"""
    Input: isi string literal untuk REGEXP (tanpa quote luar), mis: r"\bCo\w*"
    Output: versi aman untuk MySQL:
      - \b atau \\b -> (^|[^[:alnum:]_])
      - \w atau \\w -> [[:alnum:]_]
      - (opsional) \d/\s
    Lalu double-backslash untuk sisa backslash single (mis: \. -> \\.)
    Catatan: ini mengasumsikan MySQL default (backslash escapes aktif).
    """
    if not lit:
        return lit

    # Trigger jika ada \b/\w/\d/\s baik single maupun double.
    # Pattern ini match: \x atau \\x (jumlah backslash 1 atau 2)
    has_b = re.search(r"(?:\\\\|\\)b", lit) is not None
    has_w = re.search(r"(?:\\\\|\\)w", lit) is not None
    has_d = re.search(r"(?:\\\\|\\)d", lit) is not None
    has_s = re.search(r"(?:\\\\|\\)s", lit) is not None

    # Kalau tidak ada indikasi, jangan sentuh (biar tidak mengubah regex valid)
    if not (has_b or has_w or has_d or has_s):
        return lit

    out = lit

    # 1) Rewrite boundary + wordchar (handle 1 atau 2 backslash)
    out = re.sub(r"(?:\\\\|\\)b", r"(^|[^[:alnum:]_])", out)
    out = re.sub(r"(?:\\\\|\\)w", r"[[:alnum:]_]", out)

    # Common shorthand classes that are often produced by LLMs.
    out = re.sub(r"(?:\\\\|\\)d", r"[0-9]", out)
    out = re.sub(r"(?:\\\\|\\)s", r"[[:space:]]", out)

    # 2) Sisa backslash tunggal → jadikan double
    # Contoh: \. \- \( dll agar lolos parsing string MySQL dan sampai ke regex engine.
    # Jangan ubah yang sudah double.
    out = re.sub(r"(?<!\\)\\(?!\\)", r"\\\\", out)

    return out

def _guardrail_fix_mysql_regexp_literals(sql: str) -> str:
    r"""
    Repair literal untuk REGEXP/RLIKE yang mengandung \b/\w ala PCRE.
    Support single-quote literal (dan optional double-quote jika kamu aktifkan pattern kedua).
    Preserves doubled single-quotes inside literal.
    """
    if not sql:
        return sql

    # Single-quoted: REGEXP '...'
    pat_sq = re.compile(
        r"(\b(?:REGEXP|RLIKE)\b\s*)(N?')((?:''|[^'])*)(')",
        flags=re.IGNORECASE,
    )

    def _repl_sq(m: re.Match) -> str:
        prefix = m.group(1)
        qopen  = m.group(2)  # "'" or "N'"
        body   = m.group(3)  # content
        qclose = m.group(4)

        new_body = _rewrite_regexp_literal_to_posix_if_needed(body)
        return f"{prefix}{qopen}{new_body}{qclose}"

    out = pat_sq.sub(_repl_sq, sql)

    # (Opsional) Double-quoted: REGEXP "..."
    # Kalau kamu yakin LLM selalu pakai single quote, blok ini boleh dihapus.
    pat_dq = re.compile(
        r'(\b(?:REGEXP|RLIKE)\b\s*)(")((?:[^"\\]|\\.)*)(")',
        flags=re.IGNORECASE,
    )

    def _repl_dq(m: re.Match) -> str:
        prefix = m.group(1)
        qopen  = m.group(2)
        body   = m.group(3)
        qclose = m.group(4)

        new_body = _rewrite_regexp_literal_to_posix_if_needed(body)
        return f"{prefix}{qopen}{new_body}{qclose}"

    out = pat_dq.sub(_repl_dq, out)

    return out


def _rewrite_regex_filter_to_case_bucket(sql: str, question: str, ctx: str = "") -> str:
    """
    Repair match-vs-rest bucket aggregations when the draft incorrectly turns
    the regex bucket condition into a WHERE filter and projects only one label.

    Applies only to explicit two-label questions such as:
      Use 'X' for rows that match and 'Y' for the rest.
    """
    s = (sql or "").strip()
    q = str(question or "")
    if not s or not q:
        return sql
    if not re.search(r"\b(?:group|summari[sz]e)\b[^.]{0,120}\bby\s+whether\b", q, flags=re.I):
        return sql
    if not re.search(r"\b(?:match(?:es|ing)?|pattern|regex|regexp|followed\s+by)\b", q, flags=re.I):
        return sql

    label_match = re.search(
        r"""(?is)\buse\s+(['"])(?P<match>.+?)\1\s+for\s+(?:rows?|records?)\s+that\s+match(?:es)?\s+
            (?:and|,)\s+(['"])(?P<rest>.+?)\3\s+for\s+(?:the\s+)?(?:rest|others?|remaining|non[-\s]?matches?)\b""",
        q,
        flags=re.X,
    )
    if not label_match:
        return sql
    match_label = (label_match.group("match") or "").strip()
    rest_label = (label_match.group("rest") or "").strip()
    if not match_label or not rest_label or match_label.lower() == rest_label.lower():
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    where_pos = _find_top_level_clause(s0, "where", max(0, from_pos + len("from")))
    group_pos = _find_top_level_clause(s0, "group by", max(0, where_pos + len("where")))
    if sel_pos != 0 or from_pos < 0 or where_pos < 0 or group_pos < 0:
        return sql
    if re.search(r"\bJOIN\b", s0[from_pos:where_pos], flags=re.I):
        return sql

    having_pos = _find_top_level_clause(s0, "having", group_pos + len("group by"))
    order_pos = _find_top_level_clause(s0, "order by", group_pos + len("group by"))
    limit_pos = _find_top_level_clause(s0, "limit", group_pos + len("group by"))
    where_end = group_pos
    group_end = min([p for p in (having_pos, order_pos, limit_pos, len(s0)) if p >= 0])

    where_body = s0[where_pos + len("where"):where_end].strip()
    if not where_body or _has_top_level_or(where_body):
        return sql
    where_parts = _split_top_level_and(where_body)
    if len(where_parts) != 1:
        return sql
    regex_condition = where_parts[0].strip()
    if not re.search(r"\b(?:REGEXP_LIKE|REGEXP|RLIKE)\b", regex_condition, flags=re.I):
        return sql
    if re.search(r"\bNOT\s+(?:REGEXP_LIKE|REGEXP|RLIKE)\b|\bNOT\s*\(", regex_condition, flags=re.I):
        return sql

    def _normalize_predicate(expr: str) -> str:
        text = (expr or "").strip()
        while text.startswith("(") and text.endswith(")"):
            inner = text[1:-1].strip()
            if not inner:
                break
            depth = 0
            quote = ""
            balanced_outer = True
            for idx, ch in enumerate(text):
                if quote:
                    if ch == quote and (idx == 0 or text[idx - 1] != "\\"):
                        quote = ""
                    continue
                if ch in {"'", '"', "`"}:
                    quote = ch
                    continue
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0 and idx != len(text) - 1:
                        balanced_outer = False
                        break
            if not balanced_outer:
                break
            text = inner
        return re.sub(r"\s+", " ", text).strip().lower()

    select_body = s0[sel_pos + len("select"):from_pos].strip()
    where_norm = _normalize_predicate(regex_condition)
    for case_match in re.finditer(
        r"""(?is)\bCASE\s+WHEN\s+(?P<cond>.*?)\s+THEN\s+(['"])(?P<match>.*?)\2\s+
            ELSE\s+(['"])(?P<rest>.*?)\4\s+END\b""",
        select_body,
        flags=re.X,
    ):
        case_cond = (case_match.group("cond") or "").strip()
        case_match_label = (case_match.group("match") or "").strip()
        case_rest_label = (case_match.group("rest") or "").strip()
        if case_match_label.lower() != match_label.lower():
            continue
        if case_rest_label.lower() != rest_label.lower():
            continue
        if _normalize_predicate(case_cond) != where_norm:
            continue

        from_part = s0[from_pos:where_pos].strip()
        suffix = s0[group_pos:].lstrip()
        rebuilt = (
            "SELECT "
            + select_body
            + " "
            + from_part
        )
        if suffix:
            rebuilt += " " + suffix
        return rebuilt.rstrip() + trailing

    select_items = _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip())
    if len(select_items) < 2:
        return sql

    def _unquote_sql_string(expr: str) -> Optional[str]:
        raw = (expr or "").strip()
        m_sq = re.fullmatch(r"'((?:''|[^'])*)'", raw, flags=re.S)
        if m_sq:
            return (m_sq.group(1) or "").replace("''", "'")
        m_dq = re.fullmatch(r'"((?:""|[^"])*)"', raw, flags=re.S)
        if m_dq:
            return (m_dq.group(1) or "").replace('""', '"')
        return None

    def _quote_sql_string(value: str) -> str:
        return "'" + str(value or "").replace("'", "''") + "'"

    def _alias_sql(alias: str) -> str:
        a = str(alias or "").strip()
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", a):
            return a
        return "`" + a.replace("`", "``") + "`"

    label_index = -1
    label_alias = ""
    for idx, item in enumerate(select_items):
        expr, alias = _split_select_expr_alias(item)
        literal = _unquote_sql_string(expr)
        if literal is None or not alias:
            continue
        if literal.strip().lower() != match_label.lower():
            continue
        label_index = idx
        label_alias = alias
        break
    if label_index < 0 or not label_alias:
        return sql

    case_expr = (
        f"CASE WHEN {regex_condition} THEN {_quote_sql_string(match_label)} "
        f"ELSE {_quote_sql_string(rest_label)} END"
    )
    rebuilt_items = list(select_items)
    rebuilt_items[label_index] = f"{case_expr} AS {_alias_sql(label_alias)}"

    from_part = s0[from_pos:where_pos].strip()
    suffix = s0[group_end:].lstrip()
    rebuilt = (
        "SELECT "
        + ", ".join(item.strip() for item in rebuilt_items)
        + " "
        + from_part
        + " GROUP BY "
        + case_expr
    )
    if suffix:
        rebuilt += " " + suffix
    return rebuilt.rstrip() + trailing


def _rewrite_half_open_between_bounds(sql: str, question: str) -> str:
    """
    Repair numeric range predicates when the question makes the upper bound
    exclusive, e.g. "between 50 and less than 100".

    SQL BETWEEN is inclusive, so the equivalent predicate is:
      col >= lower AND col < upper
    """
    s = str(sql or "")
    q = str(question or "")
    if not s or not q or "BETWEEN" not in s.upper():
        return sql

    ranges: List[Tuple[str, str]] = []
    for pattern in AGENT_HALF_OPEN_UPPER_RANGE_PATTERNS:
        if not pattern:
            continue
        try:
            matches = re.finditer(pattern, q, flags=re.I)
        except re.error:
            continue
        for m in matches:
            if len(m.groups()) < 2:
                continue
            low = (m.group(1) or "").strip()
            high = (m.group(2) or "").strip()
            if low and high:
                ranges.append((low, high))
    if not ranges:
        return sql

    def _same_number(left: str, right: str) -> bool:
        try:
            return Decimal(str(left).strip()) == Decimal(str(right).strip())
        except (InvalidOperation, ValueError):
            return str(left).strip() == str(right).strip()

    def _is_integer_successor_minus_one(sql_high: str, question_high: str) -> bool:
        """
        Accept the common LLM near-miss where an exclusive upper bound `X`
        becomes `BETWEEN low AND X-1`, which is only correct for integers.
        For decimal-valued columns this must still be rewritten to `< X`.
        """
        try:
            high_sql = Decimal(str(sql_high).strip())
            high_q = Decimal(str(question_high).strip())
        except (InvalidOperation, ValueError):
            return False
        if high_sql != high_sql.to_integral_value() or high_q != high_q.to_integral_value():
            return False
        return high_sql + Decimal("1") == high_q

    try:
        between_re = re.compile(AGENT_SQL_NUMERIC_BETWEEN_PATTERN, flags=re.I)
    except re.error:
        return sql

    def _replace(m: re.Match) -> str:
        expr = (m.group("expr") or "").strip()
        sql_low = (m.group("low") or "").strip()
        sql_high = (m.group("high") or "").strip()
        if not expr or not sql_low or not sql_high:
            return m.group(0)
        for q_low, q_high in ranges:
            if not _same_number(sql_low, q_low):
                continue
            if _same_number(sql_high, q_high):
                return f"({expr} >= {sql_low} AND {expr} < {q_high})"
            if _is_integer_successor_minus_one(sql_high, q_high):
                return f"({expr} >= {sql_low} AND {expr} < {q_high})"
        return m.group(0)

    return between_re.sub(_replace, s)
# =======================================================================
# ======= Phase 6 — NULL / DISTINCT / Result Cardinality Policies =======
# ============== Heuristic for Missing Values and Distinct ==============
# =======================================================================
# - question_wants_missing_value
# - expand_missing_null_to_null_or_empty
# - wants_distinct_from_question
# - has_distinct
# - add_distinct
# - remove_distinct
# - ensure_reasonable_distinct
# - question_wants_count_distinct
# - ensure_reasonable_count_distinct
# - parse_from_join_aliases
# - strip_unneeded_count_distinct
# - strip_redundant_distinct_in_in_not_in_subqueries

def _question_wants_union_distinct_set_operation(question: str) -> bool:
    """
    True when the question explicitly asks a set operation to remove/deduplicate
    rows. This is intentionally lexical and domain-agnostic; callers should use
    it together with a set-operation cue.
    """
    q = (question or "").lower()
    if not q:
        return False
    duplicate_obj_alt = _regex_alt_from_terms(set_operation_duplicate_object_terms(), r"$^")
    preserve_verb_alt = _regex_alt_from_terms(set_operation_duplicate_preserve_verbs(), r"$^")
    no_remove_alt = _regex_alt_from_terms(set_operation_duplicate_no_remove_phrases(), r"$^")

    if (
        duplicate_obj_alt != r"$^"
        and preserve_verb_alt != r"$^"
        and re.search(
            rf"\b(?:{preserve_verb_alt})\b\s+(?:the\s+)?(?:{duplicate_obj_alt})\b",
            q,
            flags=re.I,
        )
    ):
        return False

    if (
        duplicate_obj_alt != r"$^"
        and no_remove_alt != r"$^"
        and re.search(
            rf"\b(?:{no_remove_alt})\b\s+(?:the\s+)?(?:{duplicate_obj_alt})\b",
            q,
            flags=re.I,
        )
    ):
        return False

    return any_phrase_in_text(q, set_operation_distinct_union_cues())


def _question_wants_union_all_set_operation(question: str) -> bool:
    """
    True when the question explicitly asks to preserve duplicates across set
    operation branches. This distinguishes UNION ALL intent from a simple OR
    filter, because rows matching multiple branches must remain duplicated.
    """
    q = (question or "").lower()
    if not q:
        return False

    duplicate_obj_alt = _regex_alt_from_terms(set_operation_duplicate_object_terms(), r"$^")
    preserve_verb_alt = _regex_alt_from_terms(set_operation_duplicate_preserve_verbs(), r"$^")
    passive_verb_alt = _regex_alt_from_terms(set_operation_duplicate_passive_verbs(), r"$^")
    no_remove_alt = _regex_alt_from_terms(set_operation_duplicate_no_remove_phrases(), r"$^")

    if any_phrase_in_text(q, set_operation_union_all_terms()):
        return True

    if (
        duplicate_obj_alt != r"$^"
        and preserve_verb_alt != r"$^"
        and re.search(
            rf"\b(?:{preserve_verb_alt})\b\s+(?:the\s+)?(?:{duplicate_obj_alt})\b",
            q,
            flags=re.I,
        )
    ):
        return True

    if (
        duplicate_obj_alt != r"$^"
        and passive_verb_alt != r"$^"
        and re.search(
            rf"\b(?:{duplicate_obj_alt})\b\s+(?:are\s+)?(?:{passive_verb_alt})\b",
            q,
            flags=re.I,
        )
    ):
        return True

    return bool(
        duplicate_obj_alt != r"$^"
        and no_remove_alt != r"$^"
        and re.search(
            rf"\b(?:{no_remove_alt})\b\s+(?:the\s+)?(?:{duplicate_obj_alt})\b",
            q,
            flags=re.I,
        )
    )


def _enforce_set_operation_operator_from_question(sql: str, question: str) -> str:
    """
    Align top-level set-operation operators with explicit duplicate semantics:
    - remove/deduplicate rows  -> UNION
    - keep/preserve duplicates -> UNION ALL

    This avoids unsafe hybrids such as SELECT DISTINCT in one branch combined
    with UNION ALL for the full result set.
    """
    s = (sql or "").strip()
    if not s or "UNION" not in s.upper() or not _question_has_set_operation_intent(question):
        return sql

    wants_union_all = _question_wants_union_all_set_operation(question)
    wants_union_distinct = _question_wants_union_distinct_set_operation(question)
    if wants_union_all:
        target = "UNION ALL"
    elif wants_union_distinct:
        target = "UNION"
    else:
        return sql

    trailing = ";" if s.endswith(";") else ""
    body = s[:-1].rstrip() if trailing else s
    upper = body.upper()
    out: List[str] = []
    depth = 0
    quote = ""
    last = 0
    i = 0
    changed = False

    while i < len(body):
        ch = body[i]
        if quote:
            if ch == quote and (i == 0 or body[i - 1] != "\\"):
                quote = ""
            i += 1
            continue
        if ch in {"'", '"', "`"}:
            quote = ch
            i += 1
            continue
        if ch == "(":
            depth += 1
            i += 1
            continue
        if ch == ")":
            depth = max(0, depth - 1)
            i += 1
            continue
        if depth == 0 and upper.startswith("UNION", i):
            prev_ok = i == 0 or not (upper[i - 1].isalnum() or upper[i - 1] == "_")
            next_idx = i + len("UNION")
            next_ok = next_idx >= len(upper) or not (upper[next_idx].isalnum() or upper[next_idx] == "_")
            if prev_ok and next_ok:
                op_end = next_idx
                m_all = re.match(r"\s+ALL\b", body[op_end:], flags=re.I)
                if m_all:
                    op_end += m_all.end()
                old_op = body[i:op_end]
                out.append(body[last:i])
                out.append(target)
                last = op_end
                changed = changed or old_op.upper() != target
                i = op_end
                continue
        i += 1

    if not changed:
        return sql
    out.append(body[last:])
    return "".join(out).rstrip() + trailing


def _question_has_set_operation_intent(question: str) -> bool:
    """
    Detect explicit set-operation intent without tying the logic to a schema or
    benchmark. We require a set-operation cue plus either branch labels, dedupe
    intent, or duplicate-preservation intent. Explicit UNION/UNION ALL wording
    is also accepted unless the user is explicitly forbidding UNION.
    """
    q = (question or "").lower()
    if not q:
        return False

    if any_phrase_in_text(q, set_operation_forbid_union_phrases()):
        return False

    action_terms = {
        str(term).strip().lower()
        for term in set_operation_action_terms()
        if str(term).strip()
    }
    set_action = _regex_alt_from_terms(action_terms, r"$^")
    set_keywords = set_operation_keywords()
    explicit_union = any_phrase_in_text(q, set_operation_explicit_union_terms())
    combined_result_phrases = set_operation_combined_result_phrases()
    result_noun_terms = {
        str(term).strip().lower()
        for term in set_operation_result_noun_terms()
        if str(term).strip()
    }
    result_noun_alt = _regex_alt_from_terms(result_noun_terms, r"$^")
    quoted_literals = re.findall(r"""["'“”]([^"'“”]+)["'“”]""", question or "")
    branch_label_hints = set_operation_branch_label_hints()
    has_set_operation_cue = bool(
        explicit_union
        or any_phrase_in_text(q, set_keywords)
        or (set_action != r"$^" and re.search(rf"\b{set_action}\b", q, flags=re.I))
        or any_phrase_in_text(q, combined_result_phrases)
    )
    has_result_set_append_shape = bool(
        set_action != r"$^"
        and result_noun_alt != r"$^"
        and re.search(
            rf"\b{set_action}\b"
            rf"[^.]{{0,80}}\b{result_noun_alt}\b",
            q,
            flags=re.I | re.S,
        )
    )
    has_set_labeling_shape = bool(
        len(quoted_literals) >= 2
        and (
            any_phrase_in_text(q, branch_label_hints)
            or any_phrase_in_text(q, set_operation_branch_label_connector_terms())
        )
    )
    has_dedupe_request = _question_wants_union_distinct_set_operation(question)
    has_duplicate_preserve_request = _question_wants_union_all_set_operation(question)

    return bool(
        explicit_union
        or has_result_set_append_shape
        or (
            has_set_operation_cue
            and (has_set_labeling_shape or has_dedupe_request or has_duplicate_preserve_request)
        )
    )


def _question_wants_missing_value(question: str) -> bool:
    q = (question or "").lower()
    return any_phrase_in_text(q, missing_value_phrases())

def _question_wants_present_value(question: str) -> bool:
    q = (question or "").lower()
    if not q or _question_wants_missing_value(q):
        return False
    return any_phrase_in_text(q, present_value_phrases())

def _expand_missing_null_to_null_or_empty(sql: str, question: str) -> str:
    """
    Policy: untuk pertanyaan yang bermakna 'missing', treat sebagai:
      col IS NULL  -> (col IS NULL OR col = '')
    Tanpa TRIM, sesuai benchmark.
    Sangat konservatif: jalan hanya jika memang ada predicate 'IS NULL'
    dan belum ada '= ''' untuk kolom tsb.
    """
    if not sql or not _question_wants_missing_value(question):
        return sql

    # Jangan ganggu query yang sudah eksplisit handle empty-string
    if re.search(r"=\s*''", sql):
        return sql

    # Split only on SQL string literals (single/double quotes).
    # Do NOT split backticked identifiers, because missing-value predicates
    # may legitimately use them (e.g. `html description` IS NULL).
    parts = re.split(r"('(?:''|[^'])*'|\"(?:\"\"|[^\"])*\")", sql)

    for i in range(0, len(parts), 2):
        seg = parts[i]

        # Rewrite generic column refs (quoted/unquoted, qualified/unqualified):
        # col IS NULL -> (col IS NULL OR col = '')
        col_ref = (
            r"(?:`[^`]+`|[A-Za-z_][A-Za-z0-9_]*)"
            r"(?:\s*\.\s*(?:`[^`]+`|[A-Za-z_][A-Za-z0-9_]*))?"
        )
        seg = re.sub(
            rf"(?is)(?P<col>{col_ref})\s+IS\s+NULL\b",
            r"(\g<col> IS NULL OR \g<col> = '')",
            seg,
            flags=re.I,
        )

        parts[i] = seg

    return "".join(parts)

def _expand_present_not_null_to_not_empty(sql: str, question: str, ctx: str = "") -> str:
    """
    Symmetric policy for questions that explicitly ask for rows that HAVE some
    text/value present.

    For string-like columns in simple single-table queries:
      col IS NOT NULL  -> (col IS NOT NULL AND col <> '')

    The correct negation of (col IS NULL OR col = '') is NOT
    (col IS NULL OR col = ''), which is equivalent to:
      col IS NOT NULL AND col <> ''

    Conservative guardrails:
    - only when the question has clear "present value" wording
    - only for string-like columns
    - only for simple single-table drafts
    - skips columns already handling empty-string explicitly
    """
    if not sql or not _question_wants_present_value(question):
        return sql
    if has_join(sql) or re.search(r"\bfrom\s*\(", sql, flags=re.I):
        return sql

    m_from = re.search(
        r"""
        \bFROM\s+
        (?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)
        (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
        """,
        sql,
        flags=re.I | re.X,
    )
    if not m_from:
        return sql

    table_raw = (m_from.group("table") or "").replace("`", "")
    base_table = table_raw.split(".")[-1].strip().lower()
    alias = (m_from.group("alias") or "").strip()
    if alias and alias.lower() in _RESERVED_ALIASES:
        alias = ""
    if not base_table:
        return sql

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    allowed = _parse_allowed_identifiers(ctx)
    allowed_cols = {str(c).strip("`").lower() for c in (allowed.get(base_table, set()) or set()) if str(c).strip()}

    def _resolve_base_column(ref: str) -> Optional[str]:
        raw = str(ref or "").strip()
        if not raw:
            return None
        cleaned = raw.replace("`", "")
        if "." in cleaned:
            lhs, rhs = [p.strip() for p in cleaned.split(".", 1)]
            if lhs.lower() not in {base_table, alias.lower() if alias else ""}:
                return None
            cleaned = rhs
        col_l = cleaned.lower()
        if allowed_cols and col_l not in allowed_cols:
            return None
        return cleaned

    def _is_string_like_column(col: str) -> bool:
        dtype = get_column_datatype(base_table, col)
        dtype_up = str(dtype or "").upper()
        if any(tok in dtype_up for tok in ("CHAR", "TEXT", "CLOB")):
            return True
        if analyzer is not None:
            try:
                role = analyzer.get_column_role(base_table, col)
            except Exception:
                role = ""
            if str(role or "").strip().lower() in {"text", "name", "description"}:
                return True
        return False

    stop_tokens = {"the", "a", "an", "of", "for", "to", "with", "that", "who", "which"}

    def _mention_phrases(col: str) -> Set[str]:
        phrases: Set[str] = set()
        raw_candidates: List[str] = [str(col or "")]
        if analyzer is not None:
            try:
                raw_candidates.extend(analyzer.get_column_synonyms(base_table, col) or [])
            except Exception:
                pass
        for text in raw_candidates:
            raw = str(text or "").strip()
            if not raw:
                continue
            split_camel = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
            normalized = re.sub(r"[_\s]+", " ", split_camel).strip().lower()
            if normalized:
                phrases.add(normalized)
            filtered_tokens = [tok for tok in re.findall(r"[a-z0-9]+", normalized) if tok and tok not in stop_tokens]
            if filtered_tokens:
                phrases.add(" ".join(filtered_tokens))
        return {p for p in phrases if p}

    q_low = (question or "").lower()

    def _question_mentions_present_value(col: str) -> bool:
        phrases = _mention_phrases(col)
        if not phrases:
            return False
        explicit_present = bool(re.search(r"\b(?:not\s+empty|non[- ]empty|filled|provided)\b", q_low, flags=re.I))
        for phrase in phrases:
            pattern = re.escape(phrase).replace(r"\ ", r"\s+")
            if explicit_present and re.search(rf"\b{pattern}\b", q_low, flags=re.I):
                return True
            if re.search(rf"\b(?:has|have|with)\b(?:[^.?!]{{0,40}})\b{pattern}\b", q_low, flags=re.I):
                return True
            if re.search(rf"\b{pattern}\b(?:[^.?!]{{0,24}})\b(?:provided|filled|available)\b", q_low, flags=re.I):
                return True
        return False

    parts = re.split(r"('(?:''|[^'])*'|\"(?:\"\"|[^\"])*\"|`[^`]*`)", sql)
    qualified = r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?"

    not_null_pat = re.compile(
        rf"""(?is)\b(?P<col>{qualified})\s+IS\s+NOT\s+NULL\b"""
    )
    not_isnull_pat = re.compile(
        rf"""(?is)\bNOT\s+(?P<col>{qualified})\s+IS\s+NULL\b"""
    )
    for i in range(0, len(parts), 2):
        seg = parts[i]

        def _repl_not_null(m: re.Match) -> str:
            ref = (m.group("col") or "").strip()
            base_col = _resolve_base_column(ref)
            if not base_col or not _is_string_like_column(base_col):
                return m.group(0)
            if not _question_mentions_present_value(base_col):
                return m.group(0)
            ref_pat = re.escape(ref).replace(r"\ ", r"\s*")
            if re.search(rf"(?is){ref_pat}\s*(?:<>|!=)\s*''", seg):
                return m.group(0)
            return f"({ref} IS NOT NULL AND {ref} <> '')"

        seg = not_null_pat.sub(_repl_not_null, seg)
        seg = not_isnull_pat.sub(_repl_not_null, seg)
        parts[i] = seg

    return "".join(parts)

def _wants_distinct_from_question(question: str) -> bool:
    q = (question or "").lower()
    hard_signals = [
        "distinct",
        "no duplicate",
        "without duplicates",
        "tanpa duplikat",
        "tanpa duplicate",
        "hanya yang unik",
        "dedup",
        "de-dup",
    ]
    if any(s in q for s in hard_signals):
        return True
    if "unique" in q and any(tok in q for tok in ("row", "rows", "record", "records", "result", "results", "value", "values")):
        return True
    implicit_patterns = (
        r"\bone\s+(?:row|record|result)\s+(?:per|for\s+each)\b",
        r"\beach\s+[a-z0-9_]+\s+only\s+once\b",
        r"\bonly\s+once\s+per\b",
    )
    if any(re.search(pat, q, flags=re.I) for pat in implicit_patterns):
        return True
    return False

def _has_distinct(sql: str) -> bool:
    return bool(re.search(r"^\s*select\s+distinct\b", sql, flags=re.I))

def _add_distinct(sql: str) -> str:
    if _has_distinct(sql):
        return sql
    return re.sub(r"^\s*select\s+", "SELECT DISTINCT ", sql, flags=re.I)

def _remove_distinct(sql: str) -> str:
    return re.sub(r"^\s*select\s+distinct\s+", "SELECT ", sql, flags=re.I)

def _ensure_reasonable_distinct(sql: str, question: str) -> str:
    """
    Ensure DISTINCT is used when question implies deduplication.
    
    Guards (schema-agnostic):
    - Skip if aggregates present (COUNT/SUM/AVG already dedupe via GROUP BY)
    - Skip if multiple JOINs (DISTINCT may be legitimately needed or not)
    - For window functions, keep DISTINCT only when the question asks dedup
    """
    if not sql:
        return sql
    
    s_up = sql.upper()

    # Set operations encode deduplication at the operator level. Adding
    # SELECT DISTINCT to only one branch can create unsafe hybrids such as
    # SELECT DISTINCT ... UNION ALL ..., so leave this to the set-op operator
    # normalizer.
    if re.search(r"\bUNION(?:\s+ALL)?\b", s_up):
        return _remove_distinct(sql) if _question_has_set_operation_intent(question) else sql
    
    # Guard 1: Window functions have row-level semantics.
    # Unless the question explicitly asks for deduplication, keep row identity
    # and strip accidental DISTINCT to avoid silent row collapse.
    if re.search(r"\bOVER\s*\(", s_up) or re.search(r"\b(ROW_NUMBER|RANK|DENSE_RANK|LAG|LEAD|NTILE)\s*\(", s_up):
        if _question_wants_count_distinct(question):
            return _remove_distinct(sql)
        if _wants_distinct_from_question(question):
            return _add_distinct(sql)
        return _remove_distinct(sql)

    # Guard 2: Aggregates already handle deduplication via GROUP BY
    if any(agg in s_up for agg in ("COUNT(", "SUM(", "AVG(", "MIN(", "MAX(")):
        return sql
    
    # Guard 3: Multiple JOINs - DISTINCT decision is ambiguous
    if join_count(sql) > 1:
        return sql
    
    # Guard 4: GROUP BY already provides deduplication semantics
    # Exception: if SELECT projects only the GROUP BY columns (no aggregates),
    # adding DISTINCT is safe and satisfies explicit dedup intent.
    if "GROUP BY" in s_up:
        if _question_wants_count_distinct(question):
            return _remove_distinct(sql)

        def _split_top_level(expr: str) -> list[str]:
            parts: list[str] = []
            buf: list[str] = []
            depth = 0
            for ch in expr:
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth = max(0, depth - 1)
                if ch == "," and depth == 0:
                    part = "".join(buf).strip()
                    if part:
                        parts.append(part)
                    buf = []
                    continue
                buf.append(ch)
            tail = "".join(buf).strip()
            if tail:
                parts.append(tail)
            return parts

        def _strip_alias(col: str) -> str:
            raw = re.sub(r"\s+AS\s+`?[A-Za-z_][A-Za-z0-9_]*`?\s*$", "", col, flags=re.I)
            raw = re.sub(r"\s+`?[A-Za-z_][A-Za-z0-9_]*`?\s*$", "", raw)
            return raw.strip()

        select_match = re.search(r"^\s*select\s+(.*?)\s+from\s", sql, flags=re.I | re.S)
        group_match = re.search(r"\bgroup\s+by\s+(.+?)(?:\border\s+by\b|\blimit\b|;|$)", sql, flags=re.I | re.S)
        if select_match and group_match:
            select_cols = _split_top_level(select_match.group(1))
            group_cols = _split_top_level(group_match.group(1))
            if select_cols and group_cols:
                norm_select = {re.sub(r"[`\s]+", "", _strip_alias(c)).lower() for c in select_cols}
                norm_group = {re.sub(r"[`\s]+", "", _strip_alias(c)).lower() for c in group_cols}
                if "*" not in norm_select and norm_select == norm_group:
                    if _wants_distinct_from_question(question):
                        return _add_distinct(sql)
                    return _remove_distinct(sql)
        return sql
    
    if _question_wants_count_distinct(question):
        return _remove_distinct(sql)
    if _wants_distinct_from_question(question):
        return _add_distinct(sql)
    return _remove_distinct(sql)


def _question_wants_count_distinct(question: str) -> bool:
    q = (question or "").lower()
    if not q:
        return False
    if not re.search(r"\b(how\s+many|number\s+of|count|total\s+number)\b", q):
        return False
    if any_phrase_in_text(q, aggregation_count_distinct_phrases()):
        return True
    return any_phrase_in_text(q, aggregation_count_distinct_keywords())


def _ensure_reasonable_count_distinct(sql: str, question: str) -> str:
    """
    Repair a common grouped-aggregate mistake for questions that ask for
    COUNT(DISTINCT ...), where the model instead groups by the distinct target
    column and uses plain COUNT(...).

    Example bad shape:
      SELECT YEAR(orderDate) AS year, status, COUNT(orderNumber)
      FROM orders
      GROUP BY YEAR(orderDate), status

    Rewrites to:
      SELECT YEAR(orderDate) AS year, COUNT(DISTINCT status)
      FROM orders
      GROUP BY YEAR(orderDate)
    """
    s = (sql or "").strip()
    q = (question or "").lower()
    if not s or not _question_wants_count_distinct(q):
        return sql
    if re.search(r"\bCOUNT\s*\(\s*DISTINCT\b", s, flags=re.I):
        return sql
    if "GROUP BY" not in s.upper() or "COUNT(" not in s.upper():
        return sql

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        target = kw.upper()
        t_up = text.upper()
        depth = 0
        quote = ""
        i = start
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and t_up.startswith(target, i):
                prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                after = i + len(target)
                next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    def _split_top_level_csv(text: str) -> List[str]:
        parts: List[str] = []
        cur: List[str] = []
        depth = 0
        quote = ""
        for i, ch in enumerate(text):
            if quote:
                cur.append(ch)
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                cur.append(ch)
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            if ch == "," and depth == 0:
                part = "".join(cur).strip()
                if part:
                    parts.append(part)
                cur = []
                continue
            cur.append(ch)
        tail = "".join(cur).strip()
        if tail:
            parts.append(tail)
        return parts

    def _strip_alias(item: str) -> str:
        return re.split(r"\s+AS\s+", item, maxsplit=1, flags=re.I)[0].strip()

    def _get_alias(item: str) -> str:
        parts = re.split(r"\s+AS\s+", item, maxsplit=1, flags=re.I)
        if len(parts) == 2:
            return parts[1].strip().strip("`")
        return ""

    def _norm(text: str) -> str:
        rendered = text.replace("`", "")
        rendered = re.sub(r"\s+", "", rendered).lower()
        return rendered

    def _tokenize_expr(item: str) -> Set[str]:
        base = _strip_alias(item)
        alias = _get_alias(item)
        raw = f"{base} {alias}".lower()
        tokens = {t for t in re.findall(r"[a-z0-9]+", raw) if t}
        for piece in re.findall(r"[A-Za-z][A-Za-z0-9_]*", f"{base} {alias}"):
            tokens.update(t.lower() for t in re.findall(r"[A-Z]?[a-z]+|[A-Z]+(?=[A-Z]|$)|\d+", piece) if t)
        expanded = set(tokens)
        for t in list(tokens):
            if t.endswith("ies") and len(t) > 3:
                expanded.add(t[:-3] + "y")
            elif t.endswith("es") and len(t) > 2:
                expanded.add(t[:-2])
            elif t.endswith("s") and len(t) > 1 and not t.endswith(("ss", "us")):
                expanded.add(t[:-1])
        return expanded

    select_match = re.match(r"^\s*SELECT\s+(DISTINCT\s+)?", s, flags=re.I)
    if not select_match:
        return sql
    has_select_distinct = bool(select_match.group(1))

    from_pos = _find_top_level_kw(s, "FROM", select_match.end())
    group_pos = _find_top_level_kw(s, "GROUP BY", max(select_match.end(), from_pos))
    if from_pos < 0 or group_pos < 0:
        return sql

    having_pos = _find_top_level_kw(s, "HAVING", group_pos + len("GROUP BY"))
    order_pos = _find_top_level_kw(s, "ORDER BY", group_pos + len("GROUP BY"))
    limit_pos = _find_top_level_kw(s, "LIMIT", group_pos + len("GROUP BY"))

    group_end_candidates = [p for p in (having_pos, order_pos, limit_pos) if p >= 0]
    group_end = min(group_end_candidates) if group_end_candidates else len(s)

    select_part = s[select_match.end():from_pos].strip()
    from_clause = s[from_pos:group_pos].strip()
    group_part = s[group_pos + len("GROUP BY"):group_end].strip()
    suffix = s[group_end:].strip()

    select_items = _split_top_level_csv(select_part)
    group_items = _split_top_level_csv(group_part)
    if len(select_items) < 2 or not group_items:
        return sql

    agg_pat = re.compile(r"\b(?:COUNT|SUM|AVG|MIN|MAX)\s*\(", flags=re.I)
    window_pat = re.compile(r"\bOVER\s*\(", flags=re.I)

    count_idx = -1
    count_indices: List[int] = []
    for idx, item in enumerate(select_items):
        if re.search(r"\bCOUNT\s*\(", item, flags=re.I) and not window_pat.search(item):
            count_indices.append(idx)
            if count_idx < 0:
                count_idx = idx
    if count_idx < 0:
        return sql

    hint_tokens: Set[str] = set()
    m_hint = re.search(
        r"\b(?:how\s+many|number\s+of|count|total\s+number(?:\s+of)?)\s+"
        r"(?:distinct|unique|different)\s+([a-z][a-z0-9_ ]{1,40})\b",
        q,
        flags=re.I,
    )
    if m_hint:
        hint_tokens = {t for t in re.findall(r"[a-z0-9]+", m_hint.group(1).lower()) if t}
        expanded = set(hint_tokens)
        for t in list(hint_tokens):
            if t.endswith("ies") and len(t) > 3:
                expanded.add(t[:-3] + "y")
            elif t.endswith("es") and len(t) > 2:
                expanded.add(t[:-2])
            elif t.endswith("s") and len(t) > 1 and not t.endswith(("ss", "us")):
                expanded.add(t[:-1])
        hint_tokens = expanded

    def _plain_count_inner(item: str) -> str:
        m_count = re.search(
            r"\bCOUNT\s*\(\s*(?!DISTINCT\b)(?P<inner>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\)",
            item,
            flags=re.I,
        )
        return (m_count.group("inner") if m_count else "").strip()

    def _expr_matches_hint(expr: str) -> bool:
        if not hint_tokens:
            return False
        return bool(_tokenize_expr(expr).intersection(hint_tokens))

    # If the draft already has the intended metric column in COUNT(col), keep
    # the query shape and only add DISTINCT to that aggregate. This covers
    # joined threshold queries without mistaking displayed dimensions for the
    # distinct-count target.
    if len(count_indices) == 1:
        count_item = select_items[count_idx]
        count_inner = _plain_count_inner(count_item)
        if count_inner and _expr_matches_hint(count_inner):
            inner_pat = re.escape(count_inner).replace(r"\ ", r"\s*")
            fixed = re.sub(
                rf"\bCOUNT\s*\(\s*(?!DISTINCT\b){inner_pat}\s*\)",
                f"COUNT(DISTINCT {count_inner})",
                s,
                flags=re.I,
            )
            if fixed != s:
                return fixed

    non_agg_indices = [
        idx for idx, item in enumerate(select_items)
        if not agg_pat.search(item) and not window_pat.search(item)
    ]
    if len(non_agg_indices) < 2:
        return sql

    candidate_idx = -1
    best_score = 0
    for idx in non_agg_indices:
        score = 0
        if hint_tokens:
            score = len(_tokenize_expr(select_items[idx]).intersection(hint_tokens))
        if score > best_score or (score == best_score and score > 0 and idx > candidate_idx):
            best_score = score
            candidate_idx = idx
    if candidate_idx < 0:
        candidate_idx = non_agg_indices[-1]

    candidate_item = select_items[candidate_idx]
    candidate_base = _strip_alias(candidate_item)
    candidate_alias = _get_alias(candidate_item)
    candidate_norm = _norm(candidate_base)
    group_norms = [_norm(item) for item in group_items]
    if candidate_norm not in group_norms:
        return sql

    if order_pos >= 0:
        order_end = limit_pos if limit_pos > order_pos else len(s)
        order_clause = s[order_pos + len("ORDER BY"):order_end].strip()
        order_norm = _norm(order_clause)
        if candidate_alias and re.search(rf"\b{re.escape(candidate_alias.lower())}\b", order_clause.lower()):
            return sql
        if candidate_norm and candidate_norm in order_norm:
            return sql

    count_item = select_items[count_idx]
    count_alias = ""
    count_alias_match = re.search(r"\s+AS\s+(`?[A-Za-z_][A-Za-z0-9_]*`?)\s*$", count_item, flags=re.I)
    if count_alias_match:
        count_alias = count_alias_match.group(1)
    new_count_item = f"COUNT(DISTINCT {candidate_base})"
    if count_alias:
        new_count_item += f" AS {count_alias}"

    new_select_items: List[str] = []
    for idx, item in enumerate(select_items):
        if idx == candidate_idx:
            continue
        if idx == count_idx:
            new_select_items.append(new_count_item)
        else:
            new_select_items.append(item)

    new_group_items = [item for item in group_items if _norm(item) != candidate_norm]
    if not new_select_items or not new_group_items:
        return sql

    select_keyword = "SELECT DISTINCT" if has_select_distinct else "SELECT"
    out = f"{select_keyword} " + ", ".join(new_select_items) + f" {from_clause} GROUP BY " + ", ".join(new_group_items)
    if suffix:
        out += " " + suffix
    return out


def _drop_redundant_group_by_for_distinct_lookup(sql: str) -> str:
    """
    Drop top-level GROUP BY when it is only acting as a dedupe mechanism for a
    SELECT DISTINCT lookup query.

    Conservative guardrails:
    - top-level SELECT must already be DISTINCT
    - no HAVING, no aggregate functions, no window functions
    - GROUP BY expressions must match the visible SELECT expressions
    """
    s = (sql or "").strip()
    if not s or "GROUP BY" not in s.upper() or "SELECT DISTINCT" not in s.upper():
        return sql

    s_up = s.upper()
    if " HAVING " in f" {s_up} " or " OVER " in f" {s_up} ":
        return sql

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        target = kw.upper()
        t_up = text.upper()
        depth = 0
        quote = ""
        i = start
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and text[i - 1] != "\\":
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and t_up.startswith(target, i):
                prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                after = i + len(target)
                next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    def _split_top_level_csv(text: str) -> List[str]:
        parts: List[str] = []
        cur: List[str] = []
        depth = 0
        quote = ""
        for i, ch in enumerate(text):
            if quote:
                cur.append(ch)
                if ch == quote and text[i - 1] != "\\":
                    quote = ""
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                cur.append(ch)
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            if ch == "," and depth == 0:
                part = "".join(cur).strip()
                if part:
                    parts.append(part)
                cur = []
                continue
            cur.append(ch)
        tail = "".join(cur).strip()
        if tail:
            parts.append(tail)
        return parts

    select_match = re.match(r"^\s*SELECT\s+DISTINCT\s+", s, flags=re.I)
    if not select_match:
        return sql

    from_pos = _find_top_level_kw(s, "FROM", select_match.end())
    group_pos = _find_top_level_kw(s, "GROUP BY", max(select_match.end(), from_pos))
    if from_pos < 0 or group_pos < 0:
        return sql

    next_positions = [
        pos for pos in (
            _find_top_level_kw(s, "HAVING", group_pos + 8),
            _find_top_level_kw(s, "ORDER BY", group_pos + 8),
            _find_top_level_kw(s, "LIMIT", group_pos + 8),
        )
        if pos >= 0
    ]
    group_end = min(next_positions) if next_positions else len(s)

    select_items = _split_top_level_csv(s[select_match.end():from_pos].strip())
    group_items = _split_top_level_csv(s[group_pos + len("GROUP BY"):group_end].strip())
    if not select_items or len(select_items) != len(group_items):
        return sql

    if any(re.search(r"\b(count|sum|avg|min|max)\s*\(", item, flags=re.I) for item in select_items):
        return sql

    def _strip_select_alias(item: str) -> str:
        return re.split(r"\s+AS\s+", item, maxsplit=1, flags=re.I)[0].strip()

    def _norm(text: str) -> str:
        rendered = text.replace("`", "")
        rendered = re.sub(r"\s+", "", rendered).lower()
        return rendered

    select_norms = sorted(_norm(_strip_select_alias(item)) for item in select_items)
    group_norms = sorted(_norm(item) for item in group_items)
    if select_norms != group_norms:
        return sql

    prefix = s[:group_pos].rstrip()
    suffix = s[group_end:].lstrip()
    if not suffix:
        return prefix
    sep = "\n" if "\n" in prefix or "\n" in suffix else " "
    return prefix + sep + suffix


def _strip_redundant_distinct_in_in_not_in_subqueries(sql: str) -> str:
    """
    Remove redundant DISTINCT in IN / NOT IN membership subqueries.

    DISTINCT does not change membership semantics for IN/NOT IN because
    duplicates in the candidate set are ignored by membership checks.

    Conservative guardrails:
    - only subqueries that start with SELECT DISTINCT
    - only one projected expression
    - no GROUP BY / HAVING / ORDER BY / LIMIT / set-operation keywords
    """
    s = str(sql or "")
    if not s or "DISTINCT" not in s.upper() or "SELECT" not in s.upper():
        return sql

    def _is_ident_char(ch: str) -> bool:
        return bool(ch) and (ch.isalnum() or ch == "_")

    def _find_matching_paren(text: str, open_idx: int) -> int:
        if open_idx < 0 or open_idx >= len(text) or text[open_idx] != "(":
            return -1
        depth = 0
        quote = ""
        i = open_idx
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return -1

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        t = str(text or "")
        target = str(kw or "").upper()
        if not t or not target:
            return -1
        up = t.upper()
        depth = 0
        quote = ""
        i = max(0, int(start))
        while i < len(t):
            ch = t[i]
            if quote:
                if ch == quote and (i == 0 or t[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and up.startswith(target, i):
                prev_ok = i == 0 or not _is_ident_char(up[i - 1])
                after = i + len(target)
                next_ok = after >= len(up) or not _is_ident_char(up[after])
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    def _eligible_subquery(body: str) -> bool:
        b = str(body or "").strip()
        m = re.match(r"(?is)^SELECT\s+DISTINCT\s+", b)
        if not m:
            return False
        from_pos = _find_top_level_kw(b, "FROM", m.end())
        if from_pos < 0:
            return False
        select_part = b[m.end():from_pos].strip()
        if len(_split_top_level_commas(select_part)) != 1:
            return False
        tail_start = from_pos + len("FROM")
        for kw in ("GROUP BY", "HAVING", "ORDER BY", "LIMIT", "UNION", "INTERSECT", "EXCEPT"):
            if _find_top_level_kw(b, kw, tail_start) >= 0:
                return False
        return True

    replacements: List[Tuple[int, int, str]] = []
    quote = ""
    i = 0
    while i < len(s):
        ch = s[i]
        if quote:
            if ch == quote and (i == 0 or s[i - 1] != "\\"):
                quote = ""
            i += 1
            continue
        if ch in {"'", '"', "`"}:
            quote = ch
            i += 1
            continue
        if s[i:i + 2].upper() == "IN":
            prev_ok = i == 0 or not _is_ident_char(s[i - 1])
            next_ok = i + 2 >= len(s) or not _is_ident_char(s[i + 2])
            if prev_ok and next_ok:
                j = i + 2
                while j < len(s) and s[j].isspace():
                    j += 1
                if j < len(s) and s[j] == "(":
                    close_idx = _find_matching_paren(s, j)
                    if close_idx > j:
                        subquery_body = s[j + 1:close_idx]
                        if _eligible_subquery(subquery_body):
                            rewritten_body = re.sub(
                                r"(?is)^(\s*SELECT)\s+DISTINCT\b",
                                r"\1",
                                subquery_body,
                                count=1,
                            )
                            if rewritten_body != subquery_body:
                                replacements.append((j + 1, close_idx, rewritten_body))
                        i = close_idx + 1
                        continue
        i += 1

    if not replacements:
        return sql

    out = s
    for start, end, replacement in reversed(replacements):
        out = out[:start] + replacement + out[end:]
    return out


def _normalize_simple_set_operation_branches(sql: str, question: str) -> str:
    """
    Normalize simple UNION / UNION ALL chains where each branch returns an
    identifier plus a label column.

    Supported branch families:
    - SELECT id, 'label' AS label_alias FROM table WHERE ...
    - SELECT CONCAT('label-', id) AS bad_alias FROM table WHERE ...

    This is intentionally conservative:
    - only top-level UNION / UNION ALL chains
    - only simple single-table branches
    - all branches must project the same identifier expression

    It supports 2+ branches and canonicalizes the output to:
      SELECT id, 'label' AS label_alias FROM table WHERE ...
      UNION [ALL] ...
      ORDER BY label_alias <dir>, id <dir>
    """
    s = (sql or "").strip()
    q = (question or "").lower()
    if not s or "UNION" not in s.upper():
        return sql

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        target = kw.upper()
        t_up = text.upper()
        depth = 0
        quote = ""
        i = start
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and t_up.startswith(target, i):
                prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                after = i + len(target)
                next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    def _split_top_level_csv(text: str) -> List[str]:
        parts: List[str] = []
        cur: List[str] = []
        depth = 0
        quote = ""
        for i, ch in enumerate(text):
            if quote:
                cur.append(ch)
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                cur.append(ch)
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            if ch == "," and depth == 0:
                part = "".join(cur).strip()
                if part:
                    parts.append(part)
                cur = []
                continue
            cur.append(ch)
        tail = "".join(cur).strip()
        if tail:
            parts.append(tail)
        return parts

    def _split_union_chain(text: str) -> Tuple[List[str], List[str]]:
        branches: List[str] = []
        operators: List[str] = []
        depth = 0
        quote = ""
        start = 0
        i = 0
        t_up = text.upper()
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0:
                token = ""
                if t_up.startswith("UNION ALL", i):
                    token = "UNION ALL"
                elif t_up.startswith("UNION", i):
                    token = "UNION"
                if token:
                    prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                    after = i + len(token)
                    next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                    if prev_ok and next_ok:
                        branch = text[start:i].strip()
                        if not branch:
                            return [], []
                        branches.append(branch)
                        operators.append(token)
                        start = after
                        i = after
                        continue
            i += 1
        tail = text[start:].strip()
        if tail:
            branches.append(tail)
        return branches, operators

    def _segment_dir(text: str, target_pat: str, default: str = "ASC") -> str:
        if not text:
            return default
        if re.search(rf"{target_pat}.*\bdescending\b", text, flags=re.I) or re.search(
            rf"\bdescending\b.*{target_pat}", text, flags=re.I
        ):
            return "DESC"
        if re.search(rf"{target_pat}.*\bascending\b", text, flags=re.I) or re.search(
            rf"\bascending\b.*{target_pat}", text, flags=re.I
        ):
            return "ASC"
        return default

    body = s[:-1].rstrip() if s.endswith(";") else s
    order_pos = _find_top_level_kw(body, "ORDER BY")
    if order_pos >= 0:
        order_clause = body[order_pos + len("ORDER BY"):].strip()
        core = body[:order_pos].rstrip()
    else:
        order_clause = ""
        core = body

    branches, operators = _split_union_chain(core)
    if len(branches) < 2 or len(operators) != len(branches) - 1:
        return sql

    direct_re = re.compile(
        r"""
        ^\s*SELECT\s+
        (?P<idcol>(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*)\s*,\s*
        '(?P<label>[^']+)'\s+AS\s+`?(?P<label_alias>[A-Za-z_][A-Za-z0-9_]*|\d{4})`?\s+
        FROM\s+(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?)
        (?:\s+WHERE\s+(?P<where>.+?))?\s*$
        """,
        flags=re.I | re.S | re.X,
    )
    concat_re = re.compile(
        r"""
        ^\s*SELECT\s+
        CONCAT\(\s*'(?P<label>[^']+)'\s*,\s*(?P<idcol>(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*)\s*\)\s+
        AS\s+`?(?P<bad_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s+
        FROM\s+(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?)
        (?:\s+WHERE\s+(?P<where>.+?))?\s*$
        """,
        flags=re.I | re.S | re.X,
    )

    branch_infos: List[Dict[str, str]] = []
    for branch in branches:
        parsed: Optional[Dict[str, str]] = None
        m = direct_re.match(branch)
        if m:
            parsed = {
                "idcol": m.group("idcol"),
                "label": m.group("label"),
                "label_alias": m.group("label_alias"),
                "table": m.group("table"),
                "where": (m.group("where") or "").strip(),
            }
        else:
            m = concat_re.match(branch)
            if m:
                label = m.group("label")
                clean_label = label.rstrip("-: ").strip() or label
                parsed = {
                    "idcol": m.group("idcol"),
                    "label": clean_label,
                    "label_alias": "",
                    "table": m.group("table"),
                    "where": (m.group("where") or "").strip(),
                }
        if not parsed:
            return sql
        branch_infos.append(parsed)

    def _norm_ident(text: str) -> str:
        return re.sub(r"\s+", "", (text or "").strip()).lower()

    if any(_norm_ident(info["idcol"]) != _norm_ident(branch_infos[0]["idcol"]) for info in branch_infos[1:]):
        return sql

    alias_candidates = [info["label_alias"] for info in branch_infos if info["label_alias"]]
    label_alias = alias_candidates[0] if alias_candidates else ("year_label" if "year label" in q else "label")

    prefer_union_all = _question_wants_union_all_set_operation(question)
    prefer_union = (
        _question_wants_union_distinct_set_operation(question)
        and not prefer_union_all
    )
    if prefer_union:
        out_ops = ["UNION"] * len(operators)
    elif prefer_union_all:
        out_ops = ["UNION ALL"] * len(operators)
    else:
        out_ops = [op.upper() for op in operators]

    label_dir = "ASC"
    id_dir = "ASC"
    if order_clause:
        order_items = _split_top_level_csv(order_clause)
        if order_items:
            label_dir = "DESC" if re.search(r"\bDESC\b", order_items[0], flags=re.I) else "ASC"
        if len(order_items) >= 2:
            id_dir = "DESC" if re.search(r"\bDESC\b", order_items[1], flags=re.I) else "ASC"
    else:
        label_dir = _segment_dir(q, r"\b(?:year\s+label|label)\b", "ASC")
        id_leaf = branch_infos[0]["idcol"].split(".")[-1]
        id_words = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", id_leaf.replace("_", " ")).lower()
        id_dir = _segment_dir(q, rf"\b{re.escape(id_words)}\b", "ASC")

    branch_sqls: List[str] = []
    for info in branch_infos:
        part = f"SELECT {info['idcol']}, '{info['label']}' AS {label_alias} FROM {info['table']}"
        if info["where"]:
            part += f" WHERE {info['where']}"
        branch_sqls.append(part)

    out = branch_sqls[0]
    for op, branch_sql in zip(out_ops, branch_sqls[1:]):
        out += f" {op} {branch_sql}"

    if order_clause or re.search(r"\b(?:order|sort|sorted)\b", q, flags=re.I):
        out += f" ORDER BY {label_alias} {label_dir}, {branch_infos[0]['idcol']} {id_dir}"
    if s.endswith(";"):
        out += ";"
    return out


def _rewrite_concat_label_union(sql: str, question: str) -> str:
    """
    Repair a common bad set-operation draft where the model packs a label and an
    identifier into one CONCAT(...) column instead of returning two columns.

    Example bad shape:
      SELECT CONCAT('2003-', orderNumber) AS year_orderNumber ...
      UNION
      SELECT CONCAT('2004-', orderNumber) AS year_orderNumber ...

    Rewrites to:
      SELECT orderNumber, '2003' AS year_label ...
      UNION
      SELECT orderNumber, '2004' AS year_label ...
      ORDER BY year_label ASC, orderNumber ASC
    """
    s = (sql or "").strip()
    q = (question or "").lower()
    if not s or "UNION" not in s.upper():
        return sql
    if "label" not in q:
        return sql

    ident = r"(?:[A-Za-z_][A-Za-z0-9_]*\.)?([A-Za-z_][A-Za-z0-9_]*)"
    tbl = r"(`?[A-Za-z_][A-Za-z0-9_]*`?)"
    pat = re.compile(
        rf"""
        ^\s*SELECT\s+CONCAT\(\s*'(?P<label1>[^']+)'\s*,\s*{ident}\s*\)\s+AS\s+`?(?P<bad_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s+
        FROM\s+{tbl}\s+
        WHERE\s+YEAR\(\s*{ident}\s*\)\s*=\s*(?P<year1>\d{{4}})\s+
        UNION\s+
        SELECT\s+CONCAT\(\s*'(?P<label2>[^']+)'\s*,\s*{ident}\s*\)\s+AS\s+`?(?P=bad_alias)`?\s+
        FROM\s+{tbl}\s+
        WHERE\s+YEAR\(\s*{ident}\s*\)\s*=\s*(?P<year2>\d{{4}})\s*
        (?:ORDER\s+BY\s+`?(?P<order_alias>[A-Za-z_][A-Za-z0-9_]*)`?\s+(?P<order_dir>ASC|DESC)\s*)?
        ;?\s*$
        """,
        flags=re.I | re.S | re.X,
    )
    m = pat.match(s)
    if not m:
        return sql

    groups = m.groups()
    # Group layout from repeated unnamed captures:
    # label1, id1, bad_alias, table1, date1, year1, label2, id2, table2, date2, year2, order_alias, order_dir
    label1 = m.group("label1")
    label2 = m.group("label2")
    bad_alias = m.group("bad_alias")
    year1 = m.group("year1")
    year2 = m.group("year2")
    order_alias = m.group("order_alias") or ""
    order_dir = (m.group("order_dir") or "ASC").upper()
    # Positional unnamed capture groups for repeated identifier/table parts.
    # 1=id1, 2=table1, 3=date1, 4=id2, 5=table2, 6=date2
    id1 = groups[1]
    table1 = groups[3]
    date1 = groups[4]
    id2 = groups[7]
    table2 = groups[8]
    date2 = groups[9]

    if not all((id1, id2, table1, table2, date1, date2)):
        return sql
    if id1.lower() != id2.lower():
        return sql
    if table1.replace("`", "").lower() != table2.replace("`", "").lower():
        return sql
    if date1.lower() != date2.lower():
        return sql
    if order_alias and order_alias.lower() != bad_alias.lower():
        return sql

    # Only unwrap the "label-prefix + id" misuse, not arbitrary CONCATs.
    if not label1.endswith("-") or not label2.endswith("-"):
        return sql

    clean_label1 = label1[:-1]
    clean_label2 = label2[:-1]
    label_alias = "year_label" if "year label" in q else "label"
    order_dir = "DESC" if order_dir == "DESC" else "ASC"

    out = (
        f"SELECT {id1}, '{clean_label1}' AS {label_alias} "
        f"FROM {table1} WHERE YEAR({date1}) = {year1} "
        "UNION "
        f"SELECT {id1}, '{clean_label2}' AS {label_alias} "
        f"FROM {table1} WHERE YEAR({date1}) = {year2} "
        f"ORDER BY {label_alias} {order_dir}, {id1} ASC"
    )
    if s.endswith(";"):
        out += ";"
    return out


def _rewrite_case_split_to_union(sql: str, question: str) -> str:
    """
    Repair a bad set-operation draft where the model emulates UNION with multiple
    CASE columns in a single SELECT.

    Example bad shape:
      SELECT
        CASE WHEN YEAR(orderDate)=2003 THEN orderNumber ELSE NULL END AS `2003`,
        CASE WHEN YEAR(orderDate)=2004 THEN orderNumber ELSE NULL END
      FROM orders
      WHERE YEAR(orderDate) IN (2003, 2004)

    Rewrites to row-wise set operation branches:
      SELECT orderNumber, '2003' AS year_label ...
      UNION
      SELECT orderNumber, '2004' AS year_label ...
    """
    s = (sql or "").strip()
    q = (question or "").lower()
    if not s or "CASE" not in s.upper() or "UNION" in s.upper():
        return sql
    if "label" not in q:
        return sql

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        target = kw.upper()
        t_up = text.upper()
        depth = 0
        quote = ""
        i = start
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and t_up.startswith(target, i):
                prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                after = i + len(target)
                next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    def _split_top_level_csv(text: str) -> List[str]:
        parts: List[str] = []
        cur: List[str] = []
        depth = 0
        quote = ""
        for i, ch in enumerate(text):
            if quote:
                cur.append(ch)
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                cur.append(ch)
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            if ch == "," and depth == 0:
                part = "".join(cur).strip()
                if part:
                    parts.append(part)
                cur = []
                continue
            cur.append(ch)
        tail = "".join(cur).strip()
        if tail:
            parts.append(tail)
        return parts

    select_pos = _find_top_level_kw(s, "SELECT")
    from_pos = _find_top_level_kw(s, "FROM", max(0, select_pos + 6))
    if select_pos < 0 or from_pos < 0:
        return sql
    where_pos = _find_top_level_kw(s, "WHERE", from_pos + 4)
    order_pos = _find_top_level_kw(s, "ORDER BY", from_pos + 4)
    limit_pos = _find_top_level_kw(s, "LIMIT", from_pos + 4)

    from_end_candidates = [p for p in (where_pos, order_pos, limit_pos) if p >= 0]
    from_end = min(from_end_candidates) if from_end_candidates else len(s)

    select_part = s[select_pos + len("SELECT"):from_pos].strip()
    from_part = s[from_pos + len("FROM"):from_end].strip()
    where_part = ""
    if where_pos >= 0:
        where_end_candidates = [p for p in (order_pos, limit_pos) if p > where_pos]
        where_end = min(where_end_candidates) if where_end_candidates else len(s)
        where_part = s[where_pos + len("WHERE"):where_end].strip()
    order_part = ""
    if order_pos >= 0:
        order_end = limit_pos if limit_pos > order_pos else len(s)
        order_part = s[order_pos + len("ORDER BY"):order_end].strip().rstrip(";")

    if not select_part or not from_part:
        return sql
    if any(tok in from_part.upper() for tok in (" JOIN ", ",")):
        return sql

    case_items = _split_top_level_csv(select_part)
    if len(case_items) < 2:
        return sql

    case_re = re.compile(
        r"""
        ^CASE\s+WHEN\s+YEAR\(\s*(?P<datecol>[A-Za-z_][A-Za-z0-9_]*)\s*\)\s*=\s*(?P<year>\d{4})\s+
        THEN\s+(?P<idcol>[A-Za-z_][A-Za-z0-9_]*)\s+ELSE\s+NULL\s+END
        (?:\s+AS\s+`?(?P<alias>[A-Za-z_][A-Za-z0-9_]*|\d{4})`?)?
        $""",
        flags=re.I | re.X,
    )

    branches: List[Tuple[str, str, str, str]] = []
    base_date = ""
    base_id = ""
    for item in case_items:
        m = case_re.match(item.strip())
        if not m:
            return sql
        datecol = m.group("datecol")
        year = m.group("year")
        idcol = m.group("idcol")
        alias = (m.group("alias") or year).strip("`")
        if not base_date:
            base_date = datecol
            base_id = idcol
        elif datecol.lower() != base_date.lower() or idcol.lower() != base_id.lower():
            return sql
        branches.append((year, alias, datecol, idcol))

    if not branches:
        return sql

    if where_part:
        years_in_where = {
            y for y in re.findall(r"\b(?:19|20)\d{2}\b", where_part)
        }
        branch_years = {y for y, _, _, _ in branches}
        if years_in_where and branch_years and not branch_years.issubset(years_in_where):
            return sql

    label_alias = "year_label" if "year label" in q else "label"
    use_union = (
        _question_wants_union_distinct_set_operation(question)
        and not _question_wants_union_all_set_operation(question)
    )
    union_kw = "UNION" if use_union else "UNION ALL"

    label_dir = "ASC"
    id_dir = "ASC"
    if order_part:
        order_items = _split_top_level_csv(order_part)
        if order_items:
            m1 = re.search(r"\b(DESC|ASC)\b", order_items[0], flags=re.I)
            if m1:
                label_dir = m1.group(1).upper()
        if len(order_items) >= 2:
            m2 = re.search(r"\b(DESC|ASC)\b", order_items[1], flags=re.I)
            if m2:
                id_dir = m2.group(1).upper()

    branch_sqls = [
        f"SELECT {base_id}, '{alias}' AS {label_alias} FROM {from_part} WHERE YEAR({base_date}) = {year}"
        for year, alias, _, _ in branches
    ]
    out = f" {union_kw} ".join(branch_sqls)
    if order_part or re.search(r"\b(?:order|sort|sorted)\b", q, flags=re.I):
        out += f" ORDER BY {label_alias} {label_dir}, {base_id} {id_dir}"
    if s.endswith(";"):
        out += ";"
    return out


def _rewrite_union_case_label_to_literal_branches(sql: str, question: str) -> str:
    """
    Repair a bad UNION draft where each branch still uses the same CASE expression
    to derive a label, instead of assigning a constant label per branch.

    Example bad shape:
      SELECT orderNumber,
             CASE WHEN YEAR(orderDate)=2003 THEN '2003' ELSE '2004' END AS year_label
      FROM orders
      WHERE YEAR(orderDate) IN (2003, 2004)
      UNION
      SELECT orderNumber,
             CASE WHEN YEAR(orderDate)=2003 THEN '2003' ELSE '2004' END AS year_label
      FROM orders
      WHERE YEAR(orderDate) IN (2003, 2004)
    """
    s = (sql or "").strip()
    q = (question or "").lower()
    if not s or "UNION" not in s.upper() or "CASE" not in s.upper():
        return sql
    if "label" not in q:
        return sql

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        target = kw.upper()
        t_up = text.upper()
        depth = 0
        quote = ""
        i = start
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and t_up.startswith(target, i):
                prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                after = i + len(target)
                next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    body = s[:-1].rstrip() if s.endswith(";") else s
    order_pos = _find_top_level_kw(body, "ORDER BY")
    if order_pos >= 0:
        order_clause = body[order_pos + len("ORDER BY"):].strip()
        core = body[:order_pos].rstrip()
    else:
        order_clause = ""
        core = body

    union_pos = _find_top_level_kw(core, "UNION ALL")
    union_kw_raw = "UNION ALL"
    if union_pos < 0:
        union_pos = _find_top_level_kw(core, "UNION")
        union_kw_raw = "UNION"
    if union_pos < 0:
        return sql

    branch1 = core[:union_pos].strip()
    branch2 = core[union_pos + len(union_kw_raw):].strip()
    if not branch1 or not branch2 or _find_top_level_kw(branch2, "UNION") >= 0:
        return sql

    branch_re = re.compile(
        r"""
        ^\s*SELECT\s+
        (?P<idcol>(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*)\s*,\s*
        CASE\s+WHEN\s+YEAR\(\s*(?P<datecol>(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*)\s*\)\s*=\s*(?P<year1>\d{4})\s+
        THEN\s+'(?P<label1>[^']+)'\s+ELSE\s+'(?P<label2>[^']+)'\s+END\s+AS\s+`?(?P<label_alias>[A-Za-z_][A-Za-z0-9_]*|\d{4})`?\s+
        FROM\s+(?P<table>`?[A-Za-z_][A-Za-z0-9_]*`?)\s+
        WHERE\s+YEAR\(\s*(?P=datecol)\s*\)\s+IN\s*\(\s*(?P<iny1>\d{4})\s*,\s*(?P<iny2>\d{4})\s*\)\s*$
        """,
        flags=re.I | re.S | re.X,
    )

    m1 = branch_re.match(branch1)
    m2 = branch_re.match(branch2)
    if not m1 or not m2:
        return sql

    def _norm_table(v: str) -> str:
        return (v or "").replace("`", "").strip().lower()

    def _norm_ident(v: str) -> str:
        return re.sub(r"\s+", "", (v or "").strip()).lower()

    for key in ("idcol", "datecol", "year1", "label1", "label2", "label_alias"):
        if _norm_ident(m1.group(key)) != _norm_ident(m2.group(key)):
            return sql
    if _norm_table(m1.group("table")) != _norm_table(m2.group("table")):
        return sql

    years_in = {m1.group("iny1"), m1.group("iny2")}
    if len(years_in) != 2 or m1.group("year1") not in years_in:
        return sql
    other_years = [y for y in years_in if y != m1.group("year1")]
    if len(other_years) != 1:
        return sql

    idcol = m1.group("idcol")
    datecol = m1.group("datecol")
    table = m1.group("table")
    year1 = m1.group("year1")
    year2 = other_years[0]
    label1 = m1.group("label1")
    label2 = m1.group("label2")
    label_alias = m1.group("label_alias")

    def _segment_dir(text: str, target_pat: str, default: str = "ASC") -> str:
        if not text:
            return default
        if re.search(rf"{target_pat}.*\bdescending\b", text, flags=re.I) or re.search(
            rf"\bdescending\b.*{target_pat}", text, flags=re.I
        ):
            return "DESC"
        if re.search(rf"{target_pat}.*\bascending\b", text, flags=re.I) or re.search(
            rf"\bascending\b.*{target_pat}", text, flags=re.I
        ):
            return "ASC"
        return default

    label_dir = "ASC"
    id_dir = "ASC"
    if order_clause:
        order_items = [x.strip() for x in order_clause.split(",") if x.strip()]
        if order_items:
            label_dir = "DESC" if re.search(r"\bDESC\b", order_items[0], flags=re.I) else "ASC"
        if len(order_items) >= 2:
            id_dir = "DESC" if re.search(r"\bDESC\b", order_items[1], flags=re.I) else "ASC"
    else:
        label_dir = _segment_dir(q, r"\byear\s+label\b", "ASC")
        id_words = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", idcol.replace("_", " ")).lower()
        id_dir = _segment_dir(q, rf"\b{re.escape(id_words)}\b", "ASC")

    wants_union_all = _question_wants_union_all_set_operation(question)
    if _question_wants_union_distinct_set_operation(question) and not wants_union_all:
        union_kw = "UNION"
    elif wants_union_all:
        union_kw = "UNION ALL"
    else:
        union_kw = union_kw_raw

    out = (
        f"SELECT {idcol}, '{label1}' AS {label_alias} "
        f"FROM {table} WHERE YEAR({datecol}) = {year1} "
        f"{union_kw} "
        f"SELECT {idcol}, '{label2}' AS {label_alias} "
        f"FROM {table} WHERE YEAR({datecol}) = {year2}"
    )
    if order_clause or re.search(r"\b(?:order|sort|sorted)\b", q, flags=re.I):
        out += f" ORDER BY {label_alias} {label_dir}, {idcol} {id_dir}"
    if s.endswith(";"):
        out += ";"
    return out

def _parse_from_join_aliases(sql: str) -> Dict[str, str]:
    """
    FROM `products` pr  -> {"pr": "products"}
    JOIN db.orders `or` -> {"or": "orders"}
    """
    if not sql:
        return {}

    pat = re.compile(
        r"\b(?:from|join)\s+"
        r"(?P<table>`?[A-Za-z_][\w]*`?(?:\.`?[A-Za-z_][\w]*`?)?)"
        r"\s+(?:as\s+)?(?P<alias>[A-Za-z_]\w*)\b",
        flags=re.I,
    )

    out: Dict[str, str] = {}
    for m in pat.finditer(sql):
        table_raw = m.group("table")
        alias = m.group("alias")
        # normalize: drop schema and backticks
        if alias and alias.lower() in _RESERVED_ALIASES:
            continue
        tbl = table_raw.replace("`", "")
        tbl = tbl.split(".")[-1]
        out[alias] = tbl
        out[alias.lower()] = tbl  # convenience
    return out


def _repair_misnested_offset_window_function(sql: str) -> str:
    """
    Repair LAG/LEAD calls where the OVER clause was accidentally nested inside
    the offset argument, e.g. LAG(x, 1 OVER (...)) OVER (...).
    """
    s = str(sql or "")
    if not s or not re.search(r"\b(?:LAG|LEAD)\s*\(", s, flags=re.I):
        return sql

    pat = re.compile(
        r"""(?is)\b(?P<fn>LAG|LEAD)\s*\(
            \s*(?P<arg>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\.)?`?[A-Za-z_][A-Za-z0-9_]*`?)\s*,
            \s*(?P<offset>\d+)\s+OVER\s*\((?P<body>[^()]*)\)\s*
            \)\s*OVER\s*\(\s*(?P=body)\s*\)""",
        re.X,
    )

    def _repl(m: re.Match) -> str:
        return f"{m.group('fn').upper()}({m.group('arg')}, {m.group('offset')}) OVER ({m.group('body').strip()})"

    repaired = pat.sub(_repl, s)
    repaired = re.sub(
        r"""(?is)(\(\s*[^,()]+?\s*[-+*/]\s*(?:LAG|LEAD)\s*\([^)]*\)\s*OVER\s*\([^)]*\))\s+AS\s+""",
        r"\1) AS ",
        repaired,
    )
    return repaired


def _repair_unbalanced_select_item_parentheses(sql: str) -> str:
    """
    If a SELECT item has an output alias but its expression is missing closing
    parentheses, close the expression before AS. This is intentionally limited
    to projection items so it does not mask broader SQL structure errors.
    """
    s = str(sql or "").strip()
    if not s or not re.match(r"(?is)^\s*SELECT\b", s):
        return sql
    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql

    def _paren_balance(text: str) -> int:
        quote = ""
        balance = 0
        i = 0
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote:
                    if quote == "'" and i + 1 < len(text) and text[i + 1] == "'":
                        i += 2
                        continue
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                balance += 1
            elif ch == ")":
                balance -= 1
            i += 1
        return balance

    changed = False
    rebuilt_items: List[str] = []
    for item in _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip()):
        expr, alias = _split_select_expr_alias(item)
        balance = _paren_balance(expr)
        if alias and balance > 0:
            expr = expr.rstrip() + (")" * balance)
            quote_alias = f"`{alias}`" if re.search(r"\W", alias) else alias
            rebuilt_items.append(f"{expr} AS {quote_alias}")
            changed = True
        else:
            rebuilt_items.append(item)
    if not changed:
        return sql
    return f"SELECT {', '.join(rebuilt_items)} FROM {s0[from_pos + len('from'):].lstrip()}{trailing}"


def _repair_single_table_friendly_column_names(sql: str, question: str = "", ctx: str = "") -> str:
    """
    Normalize friendly labels such as `product code`, `buy price`, or vendor to
    real schema columns for flat single-table SQL. Matching is schema-derived:
    column names, synonyms, and table-root-stripped column phrases are used.
    """
    s = str(sql or "").strip()
    if not s or has_join(s) or not re.match(r"(?is)^\s*SELECT\b", s):
        return sql
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql

    m_from = re.match(
        r"""(?is)^\s*\(?\s*`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)?(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?(?P<tail>.*)$""",
        s0[from_pos + len("from"):].lstrip(),
    )
    if not m_from:
        return sql
    table_l = (m_from.group("table") or "").strip().lower()
    alias = (m_from.group("alias") or "").strip()
    tail = (m_from.group("tail") or "").strip()
    friendly_reserved_alias_terms = {
        str(t).strip().lower()
        for t in rule_list(
            ("heuristic_repairs", "friendly_single_table", "reserved_alias_terms"),
            [],
        )
        if str(t).strip()
    }
    if alias.lower() in friendly_reserved_alias_terms:
        tail = f"{alias} {tail}".strip()
        alias = ""
    if not table_l:
        return sql
    try:
        table_cols = [str(c).strip() for c in analyzer.get_table_columns(table_l) if str(c).strip()]
    except Exception:
        return sql
    if not table_cols:
        return sql

    def _tokens(text: str) -> List[str]:
        expanded = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or "").replace("_", " "))
        return [tok for tok in re.findall(r"[a-z0-9]+", expanded.lower()) if tok]

    table_roots = set(_tokens(table_l))
    try:
        singular = get_singular_form(table_l)
        table_roots.update(_tokens(singular))
    except Exception:
        pass

    phrase_to_col: Dict[str, str] = {}
    ambiguous: Set[str] = set()

    def _add_phrase(phrase: str, col: str) -> None:
        key = " ".join(_tokens(phrase))
        if not key:
            return
        existing = phrase_to_col.get(key)
        if existing and existing.lower() != col.lower():
            ambiguous.add(key)
            return
        phrase_to_col[key] = col

    for col in table_cols:
        col_l = col.lower()
        original = str(getattr(analyzer, "_column_original_case", {}).get(f"{table_l}.{col_l}", col))
        col_tokens = _tokens(original)
        _add_phrase(original, original)
        if table_roots and col_tokens:
            stripped = [tok for tok in col_tokens if tok not in table_roots]
            if stripped and stripped != col_tokens:
                _add_phrase(" ".join(stripped), original)
        try:
            for syn in analyzer.get_column_synonyms(table_l, col_l) or []:
                _add_phrase(str(syn), original)
        except Exception:
            pass

    phrase_to_col = {k: v for k, v in phrase_to_col.items() if k not in ambiguous}
    if not phrase_to_col:
        return sql

    real_cols_l = {c.lower(): str(getattr(analyzer, "_column_original_case", {}).get(f"{table_l}.{c.lower()}", c)) for c in table_cols}

    def _canonical_ref(raw: str) -> Optional[str]:
        text = str(raw or "").strip().strip("`")
        key = " ".join(_tokens(text))
        if not key:
            return None
        if text.lower() in real_cols_l:
            return real_cols_l[text.lower()]
        return phrase_to_col.get(key)

    select_items: List[str] = []
    changed = False
    for item in _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip()):
        expr, out_alias = _split_select_expr_alias(item)
        expr_stripped = expr.strip()
        m_simple = re.fullmatch(
            r"""(?is)(?:(?P<qual>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?(?P<col>`?[^`(),+\-*/\s]+(?:\s+[^`(),+\-*/]+)?`?)""",
            expr_stripped,
        )
        if m_simple and not re.search(r"\b(?:COUNT|SUM|AVG|MIN|MAX|CASE|OVER)\b", expr_stripped, flags=re.I):
            replacement = _canonical_ref(m_simple.group("col"))
            if replacement and replacement != expr_stripped.strip("`"):
                qual = (m_simple.group("qual") or "").strip()
                expr = f"{qual}.{replacement}" if qual else replacement
                changed = True
        if out_alias:
            quote_alias = f"`{out_alias}`" if re.search(r"\W", out_alias) else out_alias
            select_items.append(f"{expr} AS {quote_alias}")
        else:
            select_items.append(expr)

    def _replace_quoted_phrase(m: re.Match) -> str:
        nonlocal changed
        replacement = _canonical_ref(m.group(1))
        if replacement:
            changed = True
            return replacement
        return m.group(0)

    tail2 = re.sub(r"`([^`]+)`", _replace_quoted_phrase, tail)
    for phrase, col in sorted(phrase_to_col.items(), key=lambda kv: len(kv[0]), reverse=True):
        if " " not in phrase:
            continue
        pat = re.compile(rf"(?<![.`A-Za-z0-9_]){re.escape(phrase)}(?![`A-Za-z0-9_])", flags=re.I)
        tail2, n = pat.subn(col, tail2)
        if n:
            changed = True

    if not changed:
        return sql
    from_part = table_l
    if alias and alias.lower() not in friendly_reserved_alias_terms:
        from_part += f" AS {alias}"
    rebuilt = f"SELECT {', '.join(select_items)} FROM {from_part}"
    if tail2:
        rebuilt += " " + tail2
    return rebuilt.rstrip() + trailing


def _rewrite_explicit_single_table_scope(sql: str, question: str, ctx: str = "") -> str:
    """
    Medium single-table prompts often say "in/using/from the <table> table".
    When a draft over-joins neighboring FK tables despite that explicit scope,
    collapse the flat outer query back to the mentioned table if all referenced
    columns can be satisfied by that table.
    """
    s = str(sql or "").strip()
    if not s or not question:
        return sql
    if not (has_join(s) or re.search(r"(?is)\bFROM\b(?:(?!\bJOIN\b).)*\bON\b", s)):
        return sql
    if re.search(r"(?is)^\s*WITH\b|\bUNION\b|\bINTERSECT\b|\bEXCEPT\b|\bFROM\s*\(\s*SELECT\b", s):
        return sql

    q = str(question or "").lower()
    try:
        all_tables = [str(t).strip().lower() for t in get_all_tables() if str(t).strip()]
        analyzer = get_schema_analyzer()
    except Exception:
        return sql

    def _table_terms(table_l: str) -> Set[str]:
        terms = {table_l, table_l.replace("_", " ")}
        try:
            singular = get_singular_form(table_l)
            if singular:
                terms.add(str(singular).lower())
        except Exception:
            pass
        try:
            terms.update(str(t).strip().lower() for t in (get_table_synonyms(table_l) or []) if str(t).strip())
        except Exception:
            pass
        return {t for t in terms if t}

    scope_prepositions = [
        str(t).strip().lower()
        for t in rule_list(
            ("heuristic_repairs", "explicit_single_table_scope", "scope_prepositions"),
            [],
        )
        if str(t).strip()
    ]
    table_noun_terms = [
        str(t).strip().lower()
        for t in rule_list(
            ("heuristic_repairs", "explicit_single_table_scope", "table_noun_terms"),
            [],
        )
        if str(t).strip()
    ]
    scope_alt = "|".join(re.escape(t) for t in scope_prepositions)
    table_noun_alt = "|".join(re.escape(t) for t in table_noun_terms)

    mentioned: List[str] = []
    for table_l in all_tables:
        alts = sorted(_table_terms(table_l), key=len, reverse=True)
        alt_pat = "|".join(re.escape(a).replace(r"\ ", r"\s+") for a in alts)
        if not alt_pat:
            continue
        if scope_alt and table_noun_alt and re.search(rf"\b(?:{scope_alt})\s+(?:the\s+)?(?:{alt_pat})\s+(?:{table_noun_alt})\b", q, flags=re.I):
            mentioned.append(table_l)
        elif table_noun_alt and re.search(rf"\b(?:{alt_pat})\s+(?:{table_noun_alt})\b", q, flags=re.I):
            mentioned.append(table_l)
        elif re.search(rf"\b{re.escape(table_l)}\b", q, flags=re.I):
            mentioned.append(table_l)
    mentioned = sorted(set(mentioned))
    if len(mentioned) != 1:
        return sql
    target_table = mentioned[0]

    try:
        target_cols = {str(c).strip("`").lower() for c in analyzer.get_table_columns(target_table) if str(c).strip()}
    except Exception:
        target_cols = set()
    if not target_cols:
        return sql

    def _case_col(col_l: str) -> str:
        return str(getattr(analyzer, "_column_original_case", {}).get(f"{target_table}.{col_l}", col_l))

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    if sel_pos != 0 or from_pos < 0:
        return sql

    clause_positions = [
        p for p in [
            _find_top_level_clause(s0, "where", from_pos + len("from")),
            _find_top_level_clause(s0, "group by", from_pos + len("from")),
            _find_top_level_clause(s0, "having", from_pos + len("from")),
            _find_top_level_clause(s0, "order by", from_pos + len("from")),
            _find_top_level_clause(s0, "limit", from_pos + len("from")),
        ]
        if p >= 0
    ]
    from_end = min(clause_positions) if clause_positions else len(s0)
    select_part = s0[sel_pos + len("select"):from_pos].strip()
    from_core = s0[from_pos + len("from"):from_end].strip()
    suffix = s0[from_end:].lstrip()
    if not select_part or not from_core:
        return sql

    scope_reserved_alias_terms = {
        str(t).strip().lower()
        for t in rule_list(
            ("heuristic_repairs", "explicit_single_table_scope", "reserved_alias_terms"),
            [],
        )
        if str(t).strip()
    }

    source_pairs: List[Tuple[str, str]] = []
    for m_src in re.finditer(
        r"""(?is)\b(?:FROM|JOIN)\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?\s*(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)?""",
        f"FROM {from_core}",
    ):
        table_l = (m_src.group("table") or "").strip().lower()
        alias = (m_src.group("alias") or "").strip()
        if alias.lower() in scope_reserved_alias_terms:
            alias = ""
        source_pairs.append((alias or table_l, table_l))
    if not source_pairs or target_table not in {t for _, t in source_pairs}:
        return sql

    target_alias = next((a for a, t in source_pairs if t == target_table and a), target_table)
    source_aliases = {a.lower() for a, _ in source_pairs if a}
    source_by_qualifier = {a.lower(): t for a, t in source_pairs if a}
    source_by_qualifier.update({t: t for _, t in source_pairs if t})

    # A single-table scope rewrite is only safe when every qualified reference
    # outside the target source can be satisfied by the target table. Metrics,
    # filters, or dates from a joined table mean the join is semantically needed.
    expression_scope = f"{select_part} {suffix}"
    for qualifier, col in re.findall(
        r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
        expression_scope,
        flags=re.I,
    ):
        qualifier_l = qualifier.lower()
        col_l = col.lower()
        source_table = source_by_qualifier.get(qualifier_l)
        if source_table and source_table != target_table and col_l not in target_cols:
            return sql
        if source_table is None and qualifier_l in set(all_tables) and qualifier_l != target_table:
            return sql

    # Unqualified columns can still require the joined table. If a bare column
    # token is not satisfiable by the target table but is present on a joined
    # source, keep the join rather than collapsing the scope.
    joined_only_cols: Set[str] = set()
    for _, table_l in source_pairs:
        if table_l == target_table:
            continue
        try:
            joined_only_cols.update(
                str(c).strip("`").lower()
                for c in analyzer.get_table_columns(table_l)
                if str(c).strip()
            )
        except Exception:
            continue
    joined_only_cols -= target_cols
    if joined_only_cols:
        unqualified_scope = re.sub(
            r"""`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?""",
            " ",
            expression_scope,
            flags=re.I,
        )
        for col_l in sorted(joined_only_cols, key=len, reverse=True):
            if re.search(rf"\b{re.escape(col_l)}\b", unqualified_scope, flags=re.I):
                return sql

    def _normalize_projection_item(item: str) -> str:
        expr, alias = _split_select_expr_alias(item)
        alias_l = str(alias or "").strip("`").lower()
        if alias_l in target_cols and re.match(
            r"""(?is)^\s*`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*`?[A-Za-z_][A-Za-z0-9_]*`?\s*$""",
            expr,
        ):
            expr = f"{target_alias}.{_case_col(alias_l)}"
            return f"{expr} AS {alias}" if alias else expr
        return item

    select_items = [_normalize_projection_item(it) for it in _split_top_level_commas(select_part)]
    rewritten = "SELECT " + ", ".join(select_items) + f" FROM {target_table} AS {target_alias}"
    if suffix:
        rewritten += " " + suffix

    def _requalify(m: re.Match) -> str:
        alias_l = (m.group(1) or "").lower()
        col_l = (m.group(2) or "").lower()
        if alias_l in source_aliases and col_l in target_cols:
            return f"{target_alias}.{_case_col(col_l)}"
        return m.group(0)

    rewritten = re.sub(
        r"""`?([A-Za-z_][A-Za-z0-9_]*)`?\s*\.\s*`?([A-Za-z_][A-Za-z0-9_]*)`?""",
        _requalify,
        rewritten,
    )

    leftover_alias_ref = re.search(
        rf"""(?is)\b(?:{'|'.join(re.escape(a) for a in sorted(source_aliases - {target_alias.lower()}))})\s*\.""",
        rewritten,
    ) if source_aliases - {target_alias.lower()} else None
    if leftover_alias_ref:
        return sql

    return rewritten.rstrip() + trailing


def _append_requested_secondary_order_key(sql: str, question: str) -> str:
    """
    If the prompt says "sort by X, then Y" and the SQL only orders by X,
    append the projected Y key. This keeps final ordering deterministic across
    shifted test databases without changing the primary sort.
    """
    s = str(sql or "").strip()
    if not s or not question or "order by" not in s.lower():
        return sql
    q = str(question or "")
    order_verbs = [
        str(t).strip().lower()
        for t in rule_list(
            ("heuristic_repairs", "final_order", "verbs"),
            [],
        )
        if str(t).strip()
    ]
    final_output_terms = [
        str(t).strip().lower()
        for t in rule_list(
            ("heuristic_repairs", "final_order", "final_output_terms"),
            [],
        )
        if str(t).strip()
    ]
    sequence_terms = [
        str(t).strip().lower()
        for t in rule_list(("heuristic_repairs", "final_order", "sequence_terms"), [])
        if str(t).strip()
    ]
    desc_terms = [
        str(t).strip().lower()
        for t in rule_list(
            ("heuristic_repairs", "final_order", "direction_desc_terms"),
            [],
        )
        if str(t).strip()
    ]
    asc_terms = [
        str(t).strip().lower()
        for t in rule_list(("heuristic_repairs", "final_order", "direction_asc_terms"), [])
        if str(t).strip()
    ]
    token_stopwords = {
        str(t).strip().lower()
        for t in rule_list(("heuristic_repairs", "final_order", "token_stopwords"), [])
        if str(t).strip()
    }
    if not order_verbs or not sequence_terms:
        return sql
    verb_alt = "|".join(re.escape(v) for v in order_verbs)
    final_output_alt = "|".join(re.escape(v).replace(r"\ ", r"\s+") for v in final_output_terms)
    sequence_alt = "|".join(re.escape(v).replace(r"\ ", r"\s+") for v in sequence_terms)
    desc_alt = "|".join(re.escape(v).replace(r"\ ", r"\s+") for v in desc_terms)
    direction_noise_config = {
        str(t).strip().lower()
        for t in rule_list(("heuristic_repairs", "final_order", "direction_noise_terms"), [])
        if str(t).strip()
    }
    direction_noise_terms = sorted(set(desc_terms) | set(asc_terms) | direction_noise_config, key=len, reverse=True)
    direction_noise_alt = "|".join(re.escape(v).replace(r"\ ", r"\s+") for v in direction_noise_terms)
    matches: List[Tuple[int, int, str]] = []
    order_patterns = [
        (2, rf"\b(?:{verb_alt})\s+(?:the\s+)?(?:{final_output_alt})\s+by\s+(?P<body>[^.]+)") if final_output_alt else None,
        (1, rf"\b(?:{verb_alt})\s+by\s+(?P<body>[^.]+)"),
    ]
    for item in order_patterns:
        if item is None:
            continue
        priority, pat = item
        for m in re.finditer(pat, q, flags=re.I):
            body = str(m.group("body") or "").strip()
            if body:
                matches.append((priority, m.start(), body))
    if not matches:
        return sql
    matches.sort(key=lambda item: (item[0], item[1]), reverse=True)
    order_body = matches[0][2]
    if not re.search(rf"\b(?:{sequence_alt})\b", order_body or "", flags=re.I):
        return sql

    parts = [p.strip(" ,;") for p in re.split(rf"\s*[;,]?\s+(?:{sequence_alt})\s+|\s*[;,]\s*", order_body, flags=re.I) if p.strip(" ,;")]
    if len(parts) < 2:
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    sel_pos = _find_top_level_clause(s0, "select")
    from_pos = _find_top_level_clause(s0, "from", max(0, sel_pos + len("select")))
    order_pos = _find_top_level_clause(s0, "order by", max(0, from_pos + len("from")))
    if sel_pos != 0 or from_pos < 0 or order_pos < 0:
        return sql

    limit_pos = _find_top_level_clause(s0, "limit", order_pos + len("order by"))
    order_end = limit_pos if limit_pos >= 0 else len(s0)
    order_items = _split_top_level_commas(s0[order_pos + len("order by"):order_end].strip())
    if not order_items:
        return sql

    def _term_tokens(text: str) -> Set[str]:
        cleaned = str(text or "")
        if direction_noise_alt:
            cleaned = re.sub(
                rf"\b(?:{direction_noise_alt})\b",
                " ",
                cleaned,
                flags=re.I,
            )
        cleaned = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", cleaned.replace("_", " "))
        return {tok for tok in re.findall(r"[a-z0-9]+", cleaned.lower()) if tok not in token_stopwords}

    candidates: List[Tuple[str, Set[str]]] = []
    for item in _split_top_level_commas(s0[sel_pos + len("select"):from_pos].strip()):
        expr, alias = _split_select_expr_alias(item)
        ref = alias or ""
        if not ref:
            m_col = re.search(r"""(?is)(?:^|\.)`?([A-Za-z_][A-Za-z0-9_]*)`?\s*$""", expr)
            ref = m_col.group(1) if m_col else expr
        tokens = _term_tokens(" ".join(x for x in [alias or "", ref, expr] if x))
        if ref and tokens:
            candidates.append((ref.strip("`"), tokens))

    def _order_ref(ref: str) -> str:
        raw = str(ref or "").strip().strip("`")
        if re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", raw):
            return raw
        return f"`{raw}`"

    mapped_items: List[str] = []
    for part in parts:
        wanted = _term_tokens(part)
        if not wanted:
            return sql
        scored = [
            (
                1 if toks == wanted else 0,
                len(wanted & toks),
                -len(toks - wanted),
                ref,
            )
            for ref, toks in candidates
            if wanted.issubset(toks)
        ]
        if not scored:
            return sql
        scored.sort(key=lambda x: (-x[0], -x[1], -x[2], x[3].lower()))
        direction = "DESC" if desc_alt and re.search(rf"\b(?:{desc_alt})\b", part, flags=re.I) else "ASC"
        mapped_items.append(f"{_order_ref(scored[0][3])} {direction}")

    # Treat the explicit request as authoritative for the top-level final
    # output ordering. Window ORDER BY clauses are untouched because we only
    # replace the top-level tail.
    if mapped_items == order_items:
        return sql

    rebuilt = s0[:order_pos].rstrip() + " ORDER BY " + ", ".join(mapped_items)
    if limit_pos >= 0:
        rebuilt += " " + s0[limit_pos:].lstrip()
    return rebuilt.rstrip() + trailing


def _restore_requested_temporal_group_order(sql: str, question: str) -> str:
    """
    Restore a missing top-level ORDER BY for grouped temporal rollups when the
    question explicitly requests chronological quarter/month/year ordering.

    Conservative behavior:
    - only applies when there is no existing top-level ORDER BY
    - only for top-level GROUP BY queries
    - only when the question clearly asks for chronological temporal ordering
    - orders by the grouped temporal expression itself, or MONTH(date) when the
      visible grouping key is a month-name expression
    """
    s = str(sql or "").strip()
    q = str(question or "").strip().lower()
    if not s or not q:
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s

    if _find_top_level_clause(s0, "order by") >= 0:
        return sql

    group_pos = _find_top_level_clause(s0, "group by")
    from_pos = _find_top_level_clause(s0, "from")
    if group_pos < 0 or from_pos < 0:
        return sql

    def _has_quarter_order_request(text: str) -> bool:
        return bool(
            re.search(r"\bq1\s+to\s+q4\b|\bquarter\s+1\s+to\s+(?:quarter\s+)?4\b", text, flags=re.I)
            or (
                re.search(r"\bquarter\b", text, flags=re.I)
                and re.search(
                    r"\b(?:chronological|chronologically|ascending|asc|earliest\s+to\s+latest|oldest\s+to\s+newest)\b",
                    text,
                    flags=re.I,
                )
            )
        )

    def _has_quarter_desc_request(text: str) -> bool:
        return bool(
            re.search(r"\bq4\s+to\s+q1\b|\bquarter\s+4\s+to\s+(?:quarter\s+)?1\b", text, flags=re.I)
            or (
                re.search(r"\bquarter\b", text, flags=re.I)
                and re.search(
                    r"\b(?:descending|desc|latest\s+to\s+earliest|newest\s+to\s+oldest)\b",
                    text,
                    flags=re.I,
                )
            )
        )

    def _has_month_order_request(text: str) -> bool:
        return bool(
            re.search(r"\bmonth(?:s)?\s+chronologically\b|\bchronological(?:ly)?\b", text, flags=re.I)
            or (
                re.search(r"\bmonth\b", text, flags=re.I)
                and re.search(
                    r"\b(?:ascending|asc|earliest\s+to\s+latest|oldest\s+to\s+newest)\b",
                    text,
                    flags=re.I,
                )
            )
        )

    def _has_month_desc_request(text: str) -> bool:
        return bool(
            re.search(r"\bmonth\b", text, flags=re.I)
            and re.search(
                r"\b(?:descending|desc|latest\s+to\s+earliest|newest\s+to\s+oldest)\b",
                text,
                flags=re.I,
            )
        )

    def _has_year_order_request(text: str) -> bool:
        return bool(
            re.search(r"\byear\b", text, flags=re.I)
            and re.search(
                r"\b(?:chronological|chronologically|ascending|asc|earliest\s+to\s+latest|oldest\s+to\s+newest)\b",
                text,
                flags=re.I,
            )
        )

    def _has_year_desc_request(text: str) -> bool:
        return bool(
            re.search(r"\byear\b", text, flags=re.I)
            and re.search(
                r"\b(?:descending|desc|latest\s+to\s+earliest|newest\s+to\s+oldest)\b",
                text,
                flags=re.I,
            )
        )

    temporal_kind = ""
    direction = "ASC"
    if _has_quarter_desc_request(q):
        temporal_kind = "quarter"
        direction = "DESC"
    elif _has_quarter_order_request(q):
        temporal_kind = "quarter"
        direction = "ASC"
    elif _has_month_desc_request(q):
        temporal_kind = "month"
        direction = "DESC"
    elif _has_month_order_request(q):
        temporal_kind = "month"
        direction = "ASC"
    elif _has_year_desc_request(q):
        temporal_kind = "year"
        direction = "DESC"
    elif _has_year_order_request(q):
        temporal_kind = "year"
        direction = "ASC"
    else:
        return sql

    stop_positions = [
        pos for pos in (
            _find_top_level_clause(s0, "having", group_pos + len("group by")),
            _find_top_level_clause(s0, "limit", group_pos + len("group by")),
        )
        if pos >= 0
    ]
    group_end = min(stop_positions) if stop_positions else len(s0)
    group_clause = s0[group_pos + len("group by"):group_end].strip()
    if not group_clause:
        return sql

    select_items = _split_top_level_commas(s0[len("select"):from_pos].strip()) if s0[:6].lower() == "select" else []
    alias_to_expr: Dict[str, str] = {}
    for item in select_items:
        expr, alias = _split_select_expr_alias(item)
        alias_l = str(alias or "").strip("` ").lower()
        expr_text = str(expr or "").strip()
        if alias_l and expr_text:
            alias_to_expr[alias_l] = expr_text

    def _month_order_expr(expr: str) -> Optional[str]:
        m = re.search(
            r"(?is)\bDATE_FORMAT\s*\(\s*([^,]+?)\s*,\s*(['\"])(%M|%b)\2\s*\)",
            expr,
        )
        if m:
            inner = str(m.group(1) or "").strip()
            if inner:
                return f"MONTH({inner})"
        return None

    def _temporal_order_expr(expr: str) -> Optional[str]:
        expr_text = str(expr or "").strip()
        if not expr_text:
            return None
        if temporal_kind == "quarter" and re.search(r"(?is)\bQUARTER\s*\(", expr_text):
            return expr_text
        if temporal_kind == "year" and re.search(r"(?is)\bYEAR\s*\(", expr_text):
            return expr_text
        if temporal_kind == "month":
            if re.search(r"(?is)\bMONTH\s*\(", expr_text):
                return expr_text
            return _month_order_expr(expr_text)
        return None

    order_expr = None
    for item in _split_top_level_commas(group_clause):
        group_expr = str(item or "").strip()
        if not group_expr:
            continue
        resolved_expr = alias_to_expr.get(group_expr.strip("` ").lower(), group_expr)
        order_expr = _temporal_order_expr(resolved_expr)
        if order_expr:
            break

    if not order_expr:
        return sql

    return s0.rstrip() + f" ORDER BY {order_expr} {direction}" + trailing


def _add_having_for_required_temporal_left_join(sql: str, question: str, ctx: str = "") -> str:
    """
    Preserve include-zero per-bucket aggregates while enforcing an explicit
    "at least one related row in <years>" requirement.

    This targets grouped LEFT JOIN rollups where the child rows are optional for
    year buckets, but the parent entity itself must have at least one child row
    in the requested temporal scope.
    """
    if not sql or not question:
        return sql
    if not re.search(r"\bGROUP\s+BY\b", sql, flags=re.I):
        return sql
    if not re.search(r"\bLEFT\s+JOIN\b", sql, flags=re.I):
        return sql
    if re.search(r"\bHAVING\b", sql, flags=re.I):
        return sql

    q = (question or "").strip().lower()
    if not re.search(r"\b(?:at\s+least\s+one|one\s+or\s+more|any)\b", q, flags=re.I):
        return sql

    years = sorted(dict.fromkeys(re.findall(r"\b(?:19|20)\d{2}\b", q)))
    if not years:
        return sql

    alias_to_table = _parse_from_join_aliases(sql)
    if not alias_to_table:
        return sql

    left_join_aliases: List[Tuple[str, str]] = []
    for m in re.finditer(
        r"\bLEFT\s+JOIN\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?"
        r"\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)\b",
        sql,
        flags=re.I,
    ):
        alias = (m.group("alias") or "").strip()
        table = (m.group("table") or "").strip().lower()
        if alias and table:
            left_join_aliases.append((alias, table))
    if not left_join_aliases:
        return sql

    def _table_terms(table_name: str) -> Set[str]:
        table_l = (table_name or "").strip().lower()
        terms = {table_l}
        try:
            singular = get_singular_form(table_l)
            if singular:
                terms.add(singular.lower())
        except Exception:
            pass
        try:
            terms.update(str(s).strip().lower() for s in (get_table_synonyms(table_l) or []) if str(s).strip())
        except Exception:
            pass
        return {t for t in terms if t}

    def _has_quantified_entity(table_name: str) -> bool:
        patterns = [
            re.escape(term).replace(r"\ ", r"\s+")
            for term in _table_terms(table_name)
        ]
        if not patterns:
            return False
        entity_alt = "|".join(sorted(patterns, key=len, reverse=True))
        return bool(
            re.search(
                rf"\b(?:at\s+least\s+one|one\s+or\s+more|any)\b"
                rf"(?:[\s,;:()'\"-]+\w+){{0,8}}[\s,;:()'\"-]+(?:{entity_alt})\b",
                q,
                flags=re.I,
            )
        )

    target_alias = ""
    target_table = ""
    for alias, table in left_join_aliases:
        if _has_quantified_entity(table):
            target_alias = alias
            target_table = table
            break
    if not target_alias or not target_table:
        return sql

    date_cols: List[str] = []
    try:
        analyzer = get_schema_analyzer()
        for col_l in analyzer.get_table_columns(target_table):
            datatype = (get_column_datatype(target_table, col_l) or "").lower()
            role = (get_column_role(target_table, col_l) or "").lower()
            if "date" in datatype or "time" in datatype or "temporal" in role:
                original = str(getattr(analyzer, "_column_original_case", {}).get(f"{target_table}.{col_l}", col_l))
                date_cols.append(original)
    except Exception:
        date_cols = []
    if not date_cols:
        return sql

    date_col = ""
    for col in date_cols:
        if re.search(rf"\b{re.escape(target_alias)}\s*\.\s*`?{re.escape(col)}`?\b", sql, flags=re.I):
            date_col = col
            break
    if not date_col:
        date_col = date_cols[0]

    years_sql = ", ".join(years)
    having = (
        f" HAVING SUM(CASE WHEN YEAR({target_alias}.{date_col}) "
        f"IN ({years_sql}) THEN 1 ELSE 0 END) > 0"
    )

    order_match = re.search(r"\s+ORDER\s+BY\s+", sql, flags=re.I)
    if order_match:
        return sql[:order_match.start()] + having + sql[order_match.start():]

    stripped = sql.rstrip()
    semi = ";" if stripped.endswith(";") else ""
    if semi:
        stripped = stripped[:-1].rstrip()
    return stripped + having + semi


def _ast_handle_aggregate_filters(sql: str, question: str = "") -> Tuple[str, Dict[str, Any]]:
    """
    AST-first ownership for aggregate-filter repairs on grouped queries.

    Scope:
    - aggregate predicates incorrectly placed in WHERE
    - raw grouped metric thresholds that belong in HAVING
    - missing COUNT(DISTINCT ...) threshold HAVING inferred from the question
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "handled_scope": False,
        "fixes": [],
        "warnings": [],
        "error": "",
    }
    if not sql:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(sql, read=SQL_PARSE_DIALECT or "mysql")
        meta["parse_ok"] = True
    except Exception as e:
        meta["error"] = f"parse_error:{e}"
        return sql, meta

    sel = ast.find(exp.Select)
    if sel is None:
        meta["warnings"].append("unsupported_root")
        return sql, meta

    def _flatten_top_and(expr_in: Optional["exp.Expression"]) -> List["exp.Expression"]:
        if expr_in is None:
            return []
        if isinstance(expr_in, exp.And):
            return _flatten_top_and(expr_in.this) + _flatten_top_and(expr_in.expression)
        return [expr_in]

    def _build_and(exprs: List["exp.Expression"]) -> Optional["exp.Expression"]:
        cleaned = [e for e in exprs if e is not None]
        if not cleaned:
            return None
        out = cleaned[0]
        for nxt in cleaned[1:]:
            out = exp.And(this=out, expression=nxt)
        return out

    def _parse_number_words(text: str) -> Optional[float]:
        ql = (text or "").strip().lower()
        if not ql:
            return None
        try:
            return float(ql.replace(",", ""))
        except Exception:
            pass

        units = {
            "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
            "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
            "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14,
            "fifteen": 15, "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19,
        }
        tens = {
            "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50,
            "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90,
        }
        tokens = [tok for tok in re.findall(r"[a-z]+", ql) if tok != "and"]
        if not tokens:
            return None

        total = 0
        current = 0
        seen = False
        for tok in tokens:
            if tok in units:
                current += units[tok]
                seen = True
            elif tok in tens:
                current += tens[tok]
                seen = True
            elif tok == "hundred":
                current = max(1, current) * 100
                seen = True
            elif tok == "thousand":
                current = max(1, current) * 1000
                total += current
                current = 0
                seen = True
            else:
                return None
        if not seen:
            return None
        return float(total + current)

    def _extract_count_distinct_threshold(q: str) -> Optional[Tuple[str, float]]:
        ql = (q or "").lower()
        if not ql or not _question_wants_count_distinct(q):
            return None

        num_pat = r"(\d+(?:\.\d+)?(?:,\d{3})*|[a-z]+(?:[\s-]+[a-z]+){0,3})"
        patterns = [
            (r"\bmore\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gt"),
            (r"\bover\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gt"),
            (r"\bgreater\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gt"),
            (r"\bat\s+least\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gte"),
            (r"\bno\s+fewer\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gte"),
            (r"\bless\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lt"),
            (r"\bfewer\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lt"),
            (r"\bunder\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lt"),
            (r"\bat\s+most\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lte"),
            (r"\bno\s+more\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lte"),
            (r"\bexactly\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "eq"),
        ]
        for pat, op in patterns:
            m = re.search(pat, ql, flags=re.I)
            if not m:
                continue
            parsed = _parse_number_words(m.group(1))
            if parsed is not None:
                return (op, parsed)
        return None

    def _question_has_agg_threshold(q: str) -> bool:
        ql = (q or "").lower()
        if not ql:
            return False
        if _extract_numeric_aggregate_threshold(q, require_filter_intent=True) is None:
            return False
        if re.search(r"\b(?:when|if)\b[^.]{0,96}\b(?:otherwise|else)\b", ql, flags=re.I):
            return False
        if re.search(r"\b(?:average|avg|mean|sum|maximum|minimum|max|min)\b", ql, flags=re.I):
            return True
        if not re.search(r"\btotal\b", ql, flags=re.I):
            return False

        entity_terms: Set[str] = {
            "row", "rows", "record", "records", "entry", "entries",
            "item", "items", "line", "lines", "group", "groups",
        }
        try:
            for table_name in get_all_tables() or []:
                table_l = str(table_name or "").strip().lower()
                if not table_l:
                    continue
                entity_terms.add(table_l)
                singular = str(get_singular_form(table_l) or "").strip().lower()
                if singular:
                    entity_terms.add(singular)
                for syn in get_table_synonyms(table_l) or []:
                    syn_l = str(syn or "").strip().lower()
                    if syn_l:
                        entity_terms.add(syn_l)
        except Exception:
            pass

        threshold_match = re.search(
            r"\b(?:more\s+than|over|greater\s+than|above|exceeds?|at\s+least|no\s+fewer\s+than|"
            r"less\s+than|fewer\s+than|under|below|at\s+most|no\s+more\s+than|exactly)\s+"
            r"(?:\d[\d,]*(?:\.\d+)?|[a-z]+(?:[\s-]+[a-z]+){0,4})\b(?P<tail>[^.;!?]{0,48})",
            ql,
            flags=re.I,
        )
        if not threshold_match:
            return True

        threshold_prefix = ql[max(0, threshold_match.start() - 56):threshold_match.start()]
        threshold_tail = str(threshold_match.group("tail") or "")
        for term in sorted(entity_terms, key=len, reverse=True):
            term_l = str(term or "").strip().lower()
            if not term_l:
                continue
            term_pat = re.escape(term_l).replace(r"\ ", r"\s+")
            if re.search(rf"\b(?:count|number\s+of|total)\s+(?:{term_pat})\b", threshold_prefix, flags=re.I):
                return False
            if re.search(rf"\b{term_pat}\b", threshold_tail, flags=re.I):
                return False
        return True

    def _expr_contains_agg(expr_in: Optional["exp.Expression"]) -> bool:
        if expr_in is None:
            return False

        def _has_agg_no_subquery(node: "exp.Expression") -> bool:
            if isinstance(node, exp.Subquery):
                return False
            if isinstance(node, exp.AggFunc):
                return True
            for child in node.iter_expressions():
                if _has_agg_no_subquery(child):
                    return True
            return False

        return _has_agg_no_subquery(expr_in)

    group_arg = sel.args.get("group")
    if group_arg is None:
        meta["warnings"].append("group_by_missing")
        return sql, meta

    handled_scope = False
    where_arg = sel.args.get("where")
    having_arg = sel.args.get("having")

    if isinstance(where_arg, exp.Where):
        where_cond = where_arg.this
        conds = _flatten_top_and(where_cond)
        move_to_having: List["exp.Expression"] = []
        keep_in_where: List["exp.Expression"] = []
        for c in conds:
            if c.find(exp.Subquery):
                keep_in_where.append(c.copy())
                continue
            if _expr_contains_agg(c):
                move_to_having.append(c.copy())
            else:
                keep_in_where.append(c.copy())

        if move_to_having:
            handled_scope = True
            new_where = _build_and(keep_in_where)
            if new_where is None:
                sel.set("where", None)
            else:
                sel.set("where", exp.Where(this=new_where))

            existing_having_cond = having_arg.this if isinstance(having_arg, exp.Having) else None
            merged_having = _build_and(
                ([existing_having_cond.copy()] if existing_having_cond is not None else [])
                + move_to_having
            )
            if merged_having is not None:
                sel.set("having", exp.Having(this=merged_having))
                meta["fixes"].append("agg_where_to_having_ast")

    where_arg = sel.args.get("where")
    if (
        isinstance(where_arg, exp.Where)
        and _question_has_agg_threshold(question)
    ):
        agg_map: Dict[str, "exp.Expression"] = {}
        for item in sel.expressions or []:
            base = item.this if isinstance(item, exp.Alias) else item
            if base is None:
                continue
            for agg in base.find_all(exp.AggFunc):
                cols = [c for c in agg.find_all(exp.Column)]
                if len(cols) != 1:
                    continue
                c0 = cols[0]
                key_name = str(c0.name or "").strip("`").lower()
                if key_name and key_name not in agg_map:
                    agg_map[key_name] = agg.copy()

        if agg_map:
            cmp_types = (exp.GT, exp.GTE, exp.LT, exp.LTE, exp.EQ, exp.NEQ)

            def _is_literalish(x: Optional["exp.Expression"]) -> bool:
                return isinstance(x, (exp.Literal, exp.Null))

            def _rewrite_cmp(expr_in: "exp.Expression") -> Optional["exp.Expression"]:
                if not isinstance(expr_in, cmp_types) or _expr_contains_agg(expr_in):
                    return None
                left = getattr(expr_in, "this", None)
                right = getattr(expr_in, "expression", None)
                if left is None or right is None:
                    return None
                if isinstance(left, exp.Column) and isinstance(right, exp.Column):
                    return None
                if not (_is_literalish(left) or _is_literalish(right)):
                    return None

                changed = False
                new_expr = expr_in.copy()
                new_left = getattr(new_expr, "this", None)
                new_right = getattr(new_expr, "expression", None)

                if isinstance(new_left, exp.Column):
                    agg_expr = agg_map.get(str(new_left.name or "").strip("`").lower())
                    if agg_expr is not None:
                        new_expr.set("this", agg_expr.copy())
                        changed = True
                if isinstance(new_right, exp.Column):
                    agg_expr = agg_map.get(str(new_right.name or "").strip("`").lower())
                    if agg_expr is not None:
                        new_expr.set("expression", agg_expr.copy())
                        changed = True
                return new_expr if changed else None

            conds = _flatten_top_and(where_arg.this)
            move_to_having = []
            keep_in_where = []
            for c in conds:
                rewritten = _rewrite_cmp(c)
                if rewritten is not None:
                    move_to_having.append(rewritten)
                else:
                    keep_in_where.append(c.copy())

            if move_to_having:
                handled_scope = True
                new_where = _build_and(keep_in_where)
                if new_where is None:
                    sel.set("where", None)
                else:
                    sel.set("where", exp.Where(this=new_where))

                having_arg = sel.args.get("having")
                existing_having_cond = having_arg.this if isinstance(having_arg, exp.Having) else None
                merged_having = _build_and(
                    ([existing_having_cond.copy()] if existing_having_cond is not None else [])
                    + move_to_having
                )
                if merged_having is not None:
                    sel.set("having", exp.Having(this=merged_having))
                    meta["fixes"].append("raw_metric_where_to_having_ast")

    having_arg = sel.args.get("having")
    threshold_spec = _extract_count_distinct_threshold(question)
    if threshold_spec is not None and not isinstance(having_arg, exp.Having):
        def _is_count_distinct_expr(expr_in: Optional["exp.Expression"]) -> bool:
            if not isinstance(expr_in, exp.Count):
                return False
            if bool(expr_in.args.get("distinct")):
                return True
            this_expr = getattr(expr_in, "this", None)
            if isinstance(this_expr, exp.Distinct):
                return True
            try:
                return any(True for _ in expr_in.find_all(exp.Distinct))
            except Exception:
                return False

        count_distinct_agg = None
        for item in sel.expressions or []:
            base = item.this if isinstance(item, exp.Alias) else item
            if _is_count_distinct_expr(base) and not base.find(exp.Window):
                count_distinct_agg = base.copy()
                break

        if count_distinct_agg is not None:
            handled_scope = True
            op, threshold_val = threshold_spec
            literal = exp.Literal.number(
                str(int(threshold_val)) if float(threshold_val).is_integer() else str(threshold_val)
            )
            cmp_map = {
                "gt": exp.GT,
                "gte": exp.GTE,
                "lt": exp.LT,
                "lte": exp.LTE,
                "eq": exp.EQ,
            }
            cmp_cls = cmp_map.get(op)
            if cmp_cls is not None:
                sel.set("having", exp.Having(this=cmp_cls(this=count_distinct_agg, expression=literal)))
                meta["fixes"].append("count_distinct_threshold_having_ast")

    meta["handled_scope"] = handled_scope
    meta["warnings"] = list(dict.fromkeys(meta["warnings"]))
    if not meta["fixes"]:
        return sql, meta

    out_sql = ast.sql(dialect=SQL_PARSE_DIALECT or "mysql")
    if sql.strip().endswith(";"):
        out_sql = out_sql.rstrip(";") + ";"
    return out_sql, meta


def _ast_guardrails(sql: str, ctx: str = "", question: str = "") -> Tuple[str, Dict[str, Any]]:
    """
    SQL AST guardrails (sqlglot-first).

    Goals:
    - Resolve easy alias/reference issues safely.
    - Auto-qualify ambiguous ORDER BY columns when a deterministic target exists.
    - Surface join-key sanity warnings without destructive rewrites.

    Returns:
      (possibly_rewritten_sql, meta)
      meta = {
        "parse_ok": bool,
        "fixes": List[str],
        "warnings": List[str],
        "error": str,
      }
    """
    meta: Dict[str, Any] = {"parse_ok": False, "fixes": [], "warnings": [], "error": ""}
    if not sql:
        return sql, meta

    try:
        import sqlglot
        from sqlglot import exp
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    try:
        ast = sqlglot.parse_one(sql, read="mysql")
        meta["parse_ok"] = True
    except Exception as e:
        meta["error"] = f"parse_error:{e}"
        return sql, meta

    sel = ast.find(exp.Select)
    if sel is None:
        return sql, meta

    def _flatten_top_and(expr_in: Optional["exp.Expression"]) -> List["exp.Expression"]:
        if expr_in is None:
            return []
        if isinstance(expr_in, exp.And):
            return _flatten_top_and(expr_in.this) + _flatten_top_and(expr_in.expression)
        return [expr_in]

    def _build_and(exprs: List["exp.Expression"]) -> Optional["exp.Expression"]:
        cleaned = [e for e in exprs if e is not None]
        if not cleaned:
            return None
        out = cleaned[0]
        for nxt in cleaned[1:]:
            out = exp.And(this=out, expression=nxt)
        return out

    def _question_has_agg_threshold(q: str) -> bool:
        ql = (q or "").lower()
        if not ql:
            return False
        if _extract_numeric_aggregate_threshold(q, require_filter_intent=True) is None:
            return False
        if re.search(r"\b(?:when|if)\b[^.]{0,96}\b(?:otherwise|else)\b", ql, flags=re.I):
            return False
        if re.search(r"\b(?:average|avg|mean|sum|maximum|minimum|max|min)\b", ql, flags=re.I):
            return True
        if not re.search(r"\btotal\b", ql, flags=re.I):
            return False

        entity_terms: Set[str] = {
            "row", "rows", "record", "records", "entry", "entries",
            "item", "items", "line", "lines", "group", "groups",
        }
        try:
            for table_name in get_all_tables() or []:
                table_l = str(table_name or "").strip().lower()
                if not table_l:
                    continue
                entity_terms.add(table_l)
                singular = str(get_singular_form(table_l) or "").strip().lower()
                if singular:
                    entity_terms.add(singular)
                for syn in get_table_synonyms(table_l) or []:
                    syn_l = str(syn or "").strip().lower()
                    if syn_l:
                        entity_terms.add(syn_l)
        except Exception:
            pass

        threshold_match = re.search(
            r"\b(?:more\s+than|over|greater\s+than|above|exceeds?|at\s+least|no\s+fewer\s+than|"
            r"less\s+than|fewer\s+than|under|below|at\s+most|no\s+more\s+than|exactly)\s+"
            r"(?:\d[\d,]*(?:\.\d+)?|[a-z]+(?:[\s-]+[a-z]+){0,4})\b(?P<tail>[^.;!?]{0,48})",
            ql,
            flags=re.I,
        )
        if not threshold_match:
            return True

        threshold_prefix = ql[max(0, threshold_match.start() - 56):threshold_match.start()]
        threshold_tail = str(threshold_match.group("tail") or "")
        for term in sorted(entity_terms, key=len, reverse=True):
            term_l = str(term or "").strip().lower()
            if not term_l:
                continue
            term_pat = re.escape(term_l).replace(r"\ ", r"\s+")
            if re.search(rf"\b(?:count|number\s+of|total)\s+(?:{term_pat})\b", threshold_prefix, flags=re.I):
                return False
            if re.search(rf"\b{term_pat}\b", threshold_tail, flags=re.I):
                return False
        return True

    def _parse_number_words(text: str) -> Optional[float]:
        ql = (text or "").strip().lower()
        if not ql:
            return None
        try:
            return float(ql.replace(",", ""))
        except Exception:
            pass

        units = {
            "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
            "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
            "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14,
            "fifteen": 15, "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19,
        }
        tens = {
            "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50,
            "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90,
        }
        tokens = [tok for tok in re.findall(r"[a-z]+", ql) if tok != "and"]
        if not tokens:
            return None

        total = 0
        current = 0
        seen = False
        for tok in tokens:
            if tok in units:
                current += units[tok]
                seen = True
            elif tok in tens:
                current += tens[tok]
                seen = True
            elif tok == "hundred":
                current = max(1, current) * 100
                seen = True
            elif tok == "thousand":
                current = max(1, current) * 1000
                total += current
                current = 0
                seen = True
            else:
                return None
        if not seen:
            return None
        return float(total + current)

    def _extract_count_distinct_threshold(q: str) -> Optional[Tuple[str, float]]:
        ql = (q or "").lower()
        if not ql or not _question_wants_count_distinct(q):
            return None

        num_pat = r"(\d+(?:\.\d+)?(?:,\d{3})*|[a-z]+(?:[\s-]+[a-z]+){0,3})"
        patterns = [
            (r"\bmore\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gt"),
            (r"\bover\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gt"),
            (r"\bgreater\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gt"),
            (r"\bat\s+least\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gte"),
            (r"\bno\s+fewer\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "gte"),
            (r"\bless\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lt"),
            (r"\bfewer\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lt"),
            (r"\bunder\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lt"),
            (r"\bat\s+most\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lte"),
            (r"\bno\s+more\s+than\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "lte"),
            (r"\bexactly\s+" + num_pat + r"\s+(?:distinct|unique|different)\b", "eq"),
        ]
        for pat, op in patterns:
            m = re.search(pat, ql, flags=re.I)
            if not m:
                continue
            parsed = _parse_number_words(m.group(1))
            if parsed is not None:
                return (op, parsed)
        return None

    def _expr_contains_agg(expr_in: Optional["exp.Expression"]) -> bool:
        """
        Detect aggregate functions only in the current expression scope.
        Aggregates inside scalar subqueries (e.g. col > (SELECT AVG(...))) must
        not trigger WHERE->HAVING rewrites, because those predicates are valid
        row-level filters pre-grouping.
        """
        if expr_in is None:
            return False

        def _has_agg_no_subquery(node: "exp.Expression") -> bool:
            if isinstance(node, exp.Subquery):
                return False
            if isinstance(node, exp.AggFunc):
                return True
            for child in node.iter_expressions():
                if _has_agg_no_subquery(child):
                    return True
            return False

        return _has_agg_no_subquery(expr_in)

    # -----------------------------
    # 0) AST-first semantic rewrites (conservative)
    # -----------------------------
    # 0a) GROUP BY query: move aggregate predicates from WHERE -> HAVING.
    group_arg = sel.args.get("group")
    where_arg = sel.args.get("where")
    if group_arg is not None and isinstance(where_arg, exp.Where):
        where_cond = where_arg.this
        conds = _flatten_top_and(where_cond)
        move_to_having: List["exp.Expression"] = []
        keep_in_where: List["exp.Expression"] = []
        for c in conds:
            # Keep scalar-subquery predicates in WHERE; moving them to HAVING
            # can break semantics and MySQL grouping validity.
            if c.find(exp.Subquery):
                keep_in_where.append(c.copy())
                continue
            if _expr_contains_agg(c):
                move_to_having.append(c.copy())
            else:
                keep_in_where.append(c.copy())

        if move_to_having:
            new_where = _build_and(keep_in_where)
            if new_where is None:
                sel.set("where", None)
            else:
                sel.set("where", exp.Where(this=new_where))

            existing_having = sel.args.get("having")
            existing_having_cond = None
            if isinstance(existing_having, exp.Having):
                existing_having_cond = existing_having.this
            merged_having = _build_and(
                ([existing_having_cond.copy()] if existing_having_cond is not None else [])
                + move_to_having
            )
            if merged_having is not None:
                sel.set("having", exp.Having(this=merged_having))
                meta["fixes"].append("agg_where_to_having_ast")

    # 0b) Aggregate-threshold intent: raw metric comparisons in WHERE -> HAVING.
    # Example:
    #   WHERE amount > 50000 with SELECT AVG(amount) ... GROUP BY ...
    # becomes:
    #   HAVING AVG(amount) > 50000
    group_arg = sel.args.get("group")
    where_arg = sel.args.get("where")
    if (
        group_arg is not None
        and isinstance(where_arg, exp.Where)
        and _question_has_agg_threshold(question)
    ):
        agg_map: Dict[str, "exp.Expression"] = {}
        for item in sel.expressions or []:
            base = item.this if isinstance(item, exp.Alias) else item
            if base is None:
                continue
            for agg in base.find_all(exp.AggFunc):
                cols = [c for c in agg.find_all(exp.Column)]
                if len(cols) != 1:
                    continue
                c0 = cols[0]
                key_name = str(c0.name or "").strip("`").lower()
                if not key_name:
                    continue
                if key_name not in agg_map:
                    agg_map[key_name] = agg.copy()

        if agg_map:
            cmp_types = (exp.GT, exp.GTE, exp.LT, exp.LTE, exp.EQ, exp.NEQ)

            def _is_literalish(x: Optional["exp.Expression"]) -> bool:
                return isinstance(x, (exp.Literal, exp.Null))

            def _rewrite_cmp(expr_in: "exp.Expression") -> Optional["exp.Expression"]:
                if not isinstance(expr_in, cmp_types):
                    return None
                if _expr_contains_agg(expr_in):
                    return None

                left = getattr(expr_in, "this", None)
                right = getattr(expr_in, "expression", None)
                if left is None or right is None:
                    return None

                # Avoid moving joins/column-vs-column predicates.
                if isinstance(left, exp.Column) and isinstance(right, exp.Column):
                    return None
                if not (_is_literalish(left) or _is_literalish(right)):
                    return None

                changed = False
                new_expr = expr_in.copy()
                new_left = getattr(new_expr, "this", None)
                new_right = getattr(new_expr, "expression", None)

                if isinstance(new_left, exp.Column):
                    lk = str(new_left.name or "").strip("`").lower()
                    agg_expr = agg_map.get(lk)
                    if agg_expr is not None:
                        new_expr.set("this", agg_expr.copy())
                        changed = True

                if isinstance(new_right, exp.Column):
                    rk = str(new_right.name or "").strip("`").lower()
                    agg_expr = agg_map.get(rk)
                    if agg_expr is not None:
                        new_expr.set("expression", agg_expr.copy())
                        changed = True

                return new_expr if changed else None

            where_cond = where_arg.this
            conds = _flatten_top_and(where_cond)
            move_to_having: List["exp.Expression"] = []
            keep_in_where: List["exp.Expression"] = []
            for c in conds:
                rewritten = _rewrite_cmp(c)
                if rewritten is not None:
                    move_to_having.append(rewritten)
                else:
                    keep_in_where.append(c.copy())

            if move_to_having:
                new_where = _build_and(keep_in_where)
                if new_where is None:
                    sel.set("where", None)
                else:
                    sel.set("where", exp.Where(this=new_where))

                existing_having = sel.args.get("having")
                existing_having_cond = None
                if isinstance(existing_having, exp.Having):
                    existing_having_cond = existing_having.this
                merged_having = _build_and(
                    ([existing_having_cond.copy()] if existing_having_cond is not None else [])
                    + move_to_having
                )
                if merged_having is not None:
                    sel.set("having", exp.Having(this=merged_having))
                    meta["fixes"].append("raw_metric_where_to_having_ast")

    # 0c) COUNT(DISTINCT ...) threshold intent: if the question asks for a
    # grouped count-distinct threshold and the SQL already has the right grouped
    # metric but is missing HAVING, add the aggregate threshold conservatively.
    group_arg = sel.args.get("group")
    having_arg = sel.args.get("having")
    if group_arg is not None and not isinstance(having_arg, exp.Having):
        threshold_spec = _extract_count_distinct_threshold(question)
        if threshold_spec is not None:
            def _is_count_distinct_expr(expr_in: Optional["exp.Expression"]) -> bool:
                if not isinstance(expr_in, exp.Count):
                    return False
                if bool(expr_in.args.get("distinct")):
                    return True
                this_expr = getattr(expr_in, "this", None)
                if isinstance(this_expr, exp.Distinct):
                    return True
                try:
                    return any(True for _ in expr_in.find_all(exp.Distinct))
                except Exception:
                    return False

            count_distinct_agg = None
            for item in sel.expressions or []:
                base = item.this if isinstance(item, exp.Alias) else item
                if not _is_count_distinct_expr(base):
                    continue
                if base.find(exp.Window):
                    continue
                count_distinct_agg = base.copy()
                break

            if count_distinct_agg is not None:
                op, threshold_val = threshold_spec
                literal = exp.Literal.number(
                    str(int(threshold_val)) if float(threshold_val).is_integer() else str(threshold_val)
                )
                cmp_map = {
                    "gt": exp.GT,
                    "gte": exp.GTE,
                    "lt": exp.LT,
                    "lte": exp.LTE,
                    "eq": exp.EQ,
                }
                cmp_cls = cmp_map.get(op)
                if cmp_cls is not None:
                    sel.set("having", exp.Having(this=cmp_cls(this=count_distinct_agg, expression=literal)))
                    meta["fixes"].append("count_distinct_threshold_having_ast")

    # -----------------------------
    # Top-level alias -> table map
    # -----------------------------
    alias_to_table: Dict[str, str] = {}
    alias_order: List[str] = []

    def _register_source(src: "exp.Expression") -> None:
        # Base table source
        if isinstance(src, exp.Table):
            table_name = (src.name or "").strip("`")
            if not table_name:
                return
            table_l = table_name.lower()
            alias_raw = (src.alias_or_name or table_name).strip("`")
            alias_l = alias_raw.lower()
            if alias_l and alias_l not in alias_to_table:
                alias_to_table[alias_l] = table_l
                alias_order.append(alias_l)
            if table_l and table_l not in alias_to_table:
                # Allow table-name qualifiers as valid references.
                alias_to_table[table_l] = table_l
            return

        # Derived table source: keep alias as known qualifier, but never try to
        # map its columns to base schema columns in this pass.
        if isinstance(src, exp.Subquery):
            alias_raw = (src.alias_or_name or "").strip("`")
            alias_l = alias_raw.lower()
            if alias_l and alias_l not in alias_to_table:
                alias_to_table[alias_l] = f"__derived__:{alias_l}"
                alias_order.append(alias_l)
            return

    from_arg = sel.args.get("from") or sel.args.get("from_")
    if from_arg is not None and getattr(from_arg, "this", None) is not None:
        _register_source(from_arg.this)
    for j in sel.args.get("joins") or []:
        _register_source(getattr(j, "this", None))

    # Fallback when top-level extraction misses cases.
    if not alias_to_table:
        alias_raw = _parse_from_join_aliases(sql)
        for a, t in alias_raw.items():
            al = str(a or "").strip().lower()
            tl = str(t or "").strip().lower()
            if not al or not tl:
                continue
            if al not in alias_to_table:
                alias_to_table[al] = tl
                alias_order.append(al)
            if tl not in alias_to_table:
                alias_to_table[tl] = tl

    if not alias_to_table:
        return sql, meta

    # -----------------------------
    # Build table column map (ctx + schema fallback)
    # -----------------------------
    allowed = _parse_allowed_identifiers(ctx or "")
    allowed_l: Dict[str, Set[str]] = {}
    for t, cols in (allowed or {}).items():
        tl = str(t or "").strip("`").lower()
        if not tl:
            continue
        allowed_l.setdefault(tl, set()).update(
            str(c or "").strip("`").lower() for c in (cols or set()) if str(c or "").strip()
        )

    analyzer = None
    try:
        analyzer = get_schema_analyzer()
    except Exception:
        analyzer = None

    alias_cols: Dict[str, Set[str]] = {}
    for alias, table in alias_to_table.items():
        if str(table).startswith("__derived__:"):
            alias_cols[alias] = set()
            continue
        cols = set(allowed_l.get(table, set()))
        if analyzer is not None:
            try:
                cols.update(str(c).strip("`").lower() for c in analyzer.get_table_columns(table))
            except Exception:
                pass
        alias_cols[alias] = cols

    # Map: column_name -> aliases that contain it
    col_to_aliases: Dict[str, List[str]] = {}
    for alias, cols in alias_cols.items():
        for c in cols:
            col_to_aliases.setdefault(c, []).append(alias)

    # Prefer dimension-like aliases over transaction aliases for ambiguous refs.
    try:
        txn_tables = {str(t or "").strip().lower() for t in (get_transaction_tables() or [])}
    except Exception:
        txn_tables = set()

    def _preferred_alias(col_name: str, candidates: List[str]) -> Optional[str]:
        uniq = []
        seen = set()
        for c in candidates:
            cl = str(c or "").strip().lower()
            if cl and cl not in seen:
                uniq.append(cl)
                seen.add(cl)
        if not uniq:
            return None
        if len(uniq) == 1:
            return uniq[0]

        non_tx = [a for a in uniq if alias_to_table.get(a, "") not in txn_tables]
        if len(non_tx) == 1:
            return non_tx[0]

        for a in alias_order:
            if a in uniq:
                return a
        return uniq[0]

    # -----------------------------
    # Projection map for ORDER BY disambiguation
    # -----------------------------
    projection_aliases: Set[str] = {
        str(item.alias or "").strip("`").lower()
        for item in (sel.expressions or [])
        if isinstance(item, exp.Alias) and str(item.alias or "").strip()
    }

    group_arg = sel.args.get("group")
    group_expr_norms: Set[str] = set()
    if isinstance(group_arg, exp.Group):
        for group_expr in group_arg.expressions or []:
            try:
                group_norm = _normalize_sql_expr_for_match(group_expr.sql(dialect="mysql"))
            except Exception:
                group_norm = ""
            if group_norm:
                group_expr_norms.add(group_norm)

    projection_col_map: Dict[str, List["exp.Column"]] = {}
    projection_expr_alias_map: Dict[str, List[str]] = {}
    grouped_projection_aliases_by_token: Dict[str, List[str]] = {}
    for item in sel.expressions or []:
        base = item.this if isinstance(item, exp.Alias) else item
        explicit_alias = str(item.alias or "").strip("`") if isinstance(item, exp.Alias) else ""
        explicit_alias_low = explicit_alias.lower()
        base_norm = ""
        try:
            base_norm = _normalize_sql_expr_for_match(base.sql(dialect="mysql"))
        except Exception:
            base_norm = ""

        if explicit_alias_low and base_norm:
            projection_expr_alias_map.setdefault(base_norm, []).append(explicit_alias)
            if base_norm in group_expr_norms:
                for token in _referenced_column_tokens(base.sql(dialect="mysql")):
                    grouped_projection_aliases_by_token.setdefault(token, []).append(explicit_alias)

        out_name_low = str(item.alias_or_name or "").strip("`").lower()
        if not isinstance(base, exp.Column):
            continue
        if out_name_low:
            projection_col_map.setdefault(out_name_low, []).append(base.copy())
        base_name = str(base.name or "").strip("`").lower()
        if base_name:
            projection_col_map.setdefault(base_name, []).append(base.copy())

    def _is_nested_subquery_column(col_expr: "exp.Column") -> bool:
        """
        Return True when a column does not belong to the current top-level SELECT.

        Important: nested SELECT inside EXISTS/IN may not be wrapped by exp.Subquery.
        So we identify scope by the nearest ancestor exp.Select:
        - nearest Select == current `sel`  -> top-level column (safe)
        - nearest Select != current `sel`  -> nested subquery column (must skip)
        """
        anc = getattr(col_expr, "parent", None)
        while anc is not None:
            if isinstance(anc, exp.Select):
                return anc is not sel
            anc = getattr(anc, "parent", None)
        return False

    # -----------------------------
    # 0d) Self-referential FK role filters
    # -----------------------------
    # Example, schema-agnostic:
    #   table.id is the entity primary key and table.parent_id is a self-FK.
    #   Question asks for rows whose "manager/parent/supervisor id/number is X",
    #   but the draft filters table.id = X. Rewrite only that predicate to
    #   table.parent_id = X. The role cue is taken from schema synonyms/column
    #   names first, with small generic hierarchy terms as a fallback.
    def _schema_column_case(table_name: str, col_lower: str) -> str:
        tl = str(table_name or "").strip("`").lower()
        cl = str(col_lower or "").strip("`").lower()
        if cl:
            for token in re.findall(r"`?([A-Za-z_][A-Za-z0-9_]*)`?", sql or ""):
                raw = str(token or "").strip("`")
                if raw.lower() == cl:
                    return raw
        try:
            allowed_raw = _parse_allowed_identifiers(ctx or "")
        except Exception:
            allowed_raw = {}
        for raw_table, raw_cols in (allowed_raw or {}).items():
            if str(raw_table or "").strip("`").lower() != tl:
                continue
            for raw_col in raw_cols or set():
                raw = str(raw_col or "").strip("`")
                if raw.lower() == cl:
                    return raw
        if analyzer is not None and tl and cl:
            try:
                for raw_col in analyzer.get_table_columns(tl) or []:
                    raw = str(raw_col or "").strip("`")
                    if raw.lower() == cl:
                        return raw
            except Exception:
                pass
        return col_lower

    def _identifier_word_list(text: str) -> List[str]:
        split = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or ""))
        return [
            tok
            for tok in re.findall(r"[a-z0-9]+", split.replace("_", " ").replace("-", " ").lower())
            if tok
        ]

    def _self_fk_role_terms(table_name: str, fk_col: str) -> Set[str]:
        table_tokens = set(_identifier_word_list(table_name))
        table_tokens.update(_to_singular(tok) for tok in list(table_tokens))
        id_like = {"id", "ids", "identifier", "identifiers", "number", "numbers", "code", "codes", "key", "keys"}
        noise = table_tokens | id_like | {"direct", "assigned", "main", "primary", "foreign", "to"}

        raw_texts = [fk_col]
        if analyzer is not None:
            try:
                raw_texts.extend(analyzer.get_column_synonyms(table_name, fk_col) or [])
            except Exception:
                pass

        terms: Set[str] = set()
        for raw in raw_texts:
            tokens = _identifier_word_list(str(raw or ""))
            if not tokens:
                continue
            full_phrase = " ".join(tokens).strip()
            if full_phrase and len(full_phrase) >= 3:
                terms.add(full_phrase)
            role_tokens = [tok for tok in tokens if tok not in noise]
            if role_tokens:
                phrase = " ".join(role_tokens).strip()
                if phrase and len(phrase) >= 3:
                    terms.add(phrase)
                for tok in role_tokens:
                    if len(tok) >= 3:
                        terms.add(tok)

        # Generic hierarchy vocabulary only acts as a fallback for self-FK columns.
        # It is not tied to any schema name or question ID.
        terms.update({"manager", "supervisor", "parent", "leader", "reports to", "report to", "reporting to"})
        return terms

    def _role_literal_requested(question_text: str, literal_text: str, role_terms: Set[str]) -> bool:
        q_norm = re.sub(r"\s+", " ", str(question_text or "").strip().lower())
        lit = str(literal_text or "").strip().strip("'\"`")
        if not q_norm or not lit:
            return False

        lit_pat = re.escape(lit.lower())
        positions = [m.start() for m in re.finditer(rf"(?<![a-z0-9_]){lit_pat}(?![a-z0-9_])", q_norm)]
        if not positions:
            return False

        term_patterns = []
        for term in sorted((t for t in role_terms if t), key=len, reverse=True):
            pat = re.escape(term.lower()).replace(r"\ ", r"\s+")
            term_patterns.append(pat)
        if not term_patterns:
            return False
        role_pat = rf"(?:{'|'.join(term_patterns)})"
        id_pat = r"\b(?:id|identifier|number|code|key)\b"
        reports_to_pat = r"\breports?\s+to\b|\breporting\s+to\b"

        for pos in positions:
            prefix = q_norm[max(0, pos - 120):pos]
            if not re.search(rf"\b{role_pat}\b", prefix, flags=re.I):
                continue
            if re.search(id_pat, prefix, flags=re.I) or re.search(reports_to_pat, prefix, flags=re.I):
                return True
        return False

    def _literal_sql_text(expr_in: Optional["exp.Expression"]) -> str:
        if isinstance(expr_in, exp.Literal):
            return str(expr_in.this or "").strip()
        return ""

    def _datatype_family(dtype: str) -> str:
        d = str(dtype or "").upper()
        if any(tok in d for tok in ("INT", "DECIMAL", "NUMERIC", "FLOAT", "DOUBLE", "REAL")):
            return "numeric"
        if any(tok in d for tok in ("CHAR", "TEXT", "CLOB", "STRING")):
            return "text"
        if any(tok in d for tok in ("DATE", "TIME", "YEAR")):
            return "temporal"
        return d.strip().lower()

    def _compatible_identifier_datatype(table_name: str, left_col: str, right_col: str) -> bool:
        try:
            left_family = _datatype_family(get_column_datatype(table_name, left_col))
            right_family = _datatype_family(get_column_datatype(table_name, right_col))
        except Exception:
            return False
        return bool(left_family and right_family and left_family == right_family)

    def _fk_column_has_relationship_semantics(table_name: str, fk_col: str) -> bool:
        raw_texts = [fk_col]
        if analyzer is not None:
            try:
                raw_texts.extend(analyzer.get_column_synonyms(table_name, fk_col) or [])
            except Exception:
                pass
        joined = " ".join(" ".join(_identifier_word_list(text)) for text in raw_texts).strip().lower()
        return bool(
            re.search(
                r"\b(?:manager|supervisor|parent|leader|reports?|reporting)\b",
                joined,
                flags=re.I,
            )
        )

    def _resolve_top_level_column(col_expr: "exp.Column") -> Tuple[str, str]:
        if _is_nested_subquery_column(col_expr):
            return "", ""
        col_name = str(col_expr.name or "").strip("`").lower()
        table_q = str(col_expr.table or "").strip("`").lower()
        if not col_name:
            return "", ""
        if table_q:
            table_name = alias_to_table.get(table_q, "")
            if table_name and not str(table_name).startswith("__derived__:"):
                return table_q, str(table_name).lower()
            return "", ""

        owners = [
            a for a in col_to_aliases.get(col_name, [])
            if alias_to_table.get(a, "") and not str(alias_to_table.get(a, "")).startswith("__derived__:")
        ]
        uniq: List[str] = []
        seen_aliases: Set[str] = set()
        for a in owners:
            al = str(a or "").lower()
            if al and al not in seen_aliases:
                uniq.append(al)
                seen_aliases.add(al)
        if len(uniq) != 1:
            return "", ""
        return uniq[0], str(alias_to_table.get(uniq[0], "")).lower()

    def _rewrite_self_fk_role_filter_ast() -> bool:
        where_arg = sel.args.get("where")
        if not isinstance(where_arg, exp.Where):
            return False

        try:
            fk_raw = get_fk_relationships() or {}
        except Exception:
            fk_raw = {}

        self_fk_by_table: Dict[str, List[Tuple[str, str]]] = {}
        for src_table, rels in (fk_raw or {}).items():
            src_l = str(src_table or "").strip("`").lower()
            for fk_col, target_table in (rels or {}).items():
                fk_l = str(fk_col or "").strip("`").lower()
                target_l = str(target_table or "").strip("`").lower()
                if src_l and fk_l and target_l == src_l:
                    target_id = str(get_id_column(src_l) or "").strip("`").lower()
                    if target_id:
                        self_fk_by_table.setdefault(src_l, []).append((fk_l, target_id))

        # Some metadata profiles mark a column as "Foreign Key" and provide
        # role synonyms, but omit the FK target. Keep the fallback conservative:
        # same-table ID datatype compatibility + FK hint + hierarchy/relationship
        # semantics from the column metadata. This covers self manager/parent
        # columns without encoding any table or column name.
        if analyzer is not None:
            candidate_tables = {
                str(t or "").strip("`").lower()
                for t in alias_to_table.values()
                if t and not str(t).startswith("__derived__:")
            }
            for table_l in candidate_tables:
                target_id = str(get_id_column(table_l) or "").strip("`").lower()
                if not target_id:
                    continue
                try:
                    columns = [str(c or "").strip("`").lower() for c in analyzer.get_table_columns(table_l) or []]
                except Exception:
                    columns = []
                for col_l in columns:
                    if not col_l or col_l == target_id:
                        continue
                    key = f"{table_l}.{col_l}"
                    fk_hinted = bool(
                        getattr(analyzer, "_column_foreign_key_hints", {}).get(key)
                        or col_l in (fk_raw.get(table_l, {}) or {})
                    )
                    if not fk_hinted:
                        continue
                    if not _fk_column_has_relationship_semantics(table_l, col_l):
                        continue
                    if not _compatible_identifier_datatype(table_l, col_l, target_id):
                        continue
                    bucket = self_fk_by_table.setdefault(table_l, [])
                    if (col_l, target_id) not in bucket:
                        bucket.append((col_l, target_id))
        if not self_fk_by_table:
            return False

        changed = False
        cmp_types = (exp.EQ,)
        for cmp_expr in list(where_arg.this.find_all(*cmp_types)):
            left = getattr(cmp_expr, "this", None)
            right = getattr(cmp_expr, "expression", None)
            pairs = []
            if isinstance(left, exp.Column):
                pairs.append(("left", left, right))
            if isinstance(right, exp.Column):
                pairs.append(("right", right, left))

            for side, col_expr, other_expr in pairs:
                literal = _literal_sql_text(other_expr)
                if not literal:
                    continue
                col_name = str(col_expr.name or "").strip("`").lower()
                alias_name, table_name = _resolve_top_level_column(col_expr)
                if not table_name:
                    continue

                for fk_col_l, target_id_l in self_fk_by_table.get(table_name, []):
                    if col_name != target_id_l:
                        continue
                    role_terms = _self_fk_role_terms(table_name, fk_col_l)
                    if not _role_literal_requested(question, literal, role_terms):
                        continue

                    fk_case = _schema_column_case(table_name, fk_col_l)
                    original_table = str(col_expr.table or "").strip("`")
                    replacement = exp.column(fk_case, table=original_table or None)
                    if side == "left":
                        cmp_expr.set("this", replacement)
                    else:
                        cmp_expr.set("expression", replacement)
                    meta["fixes"].append(f"self_fk_role_filter:{table_name}.{target_id_l}->{fk_col_l}")
                    changed = True
                    break
                if changed:
                    break
        return changed

    _rewrite_self_fk_role_filter_ast()

    # -----------------------------
    # 1) Unknown qualifier fix/warn
    # -----------------------------
    known_qualifiers = set(alias_to_table.keys())
    for col in sel.find_all(exp.Column):
        if _is_nested_subquery_column(col):
            # Never rewrite nested scopes in this pass.
            continue
        table_q = str(col.table or "").strip("`").lower()
        col_name = str(col.name or "").strip("`").lower()
        if not table_q:
            continue
        if table_q in known_qualifiers:
            continue

        owners = col_to_aliases.get(col_name, [])
        best = _preferred_alias(col_name, owners)
        if best:
            col.set("table", exp.to_identifier(best))
            meta["fixes"].append(f"unknown_qualifier_fixed:{table_q}->{best}.{col_name}")
        else:
            meta["warnings"].append(f"unknown_qualifier:{table_q}.{col_name}")

    # -----------------------------
    # 1b) Ambiguous unqualified column disambiguation
    # -----------------------------
    def _is_projection_alias_reference(col_expr: "exp.Column") -> bool:
        c_low = str(col_expr.name or "").strip("`").lower()
        if not c_low or c_low not in projection_aliases:
            return False
        anc = getattr(col_expr, "parent", None)
        while anc is not None:
            if anc is sel:
                return False
            if isinstance(anc, (exp.Ordered, exp.Having, exp.Group)):
                return True
            anc = getattr(anc, "parent", None)
        return False

    for col in sel.find_all(exp.Column):
        if _is_nested_subquery_column(col):
            continue
        if str(col.table or "").strip():
            continue

        c_name = str(col.name or "").strip("`")
        c_low = c_name.lower()
        if not c_low:
            continue
        if _is_projection_alias_reference(col):
            continue

        owners = [
            a
            for a in col_to_aliases.get(c_low, [])
            if alias_to_table.get(a, "") and not str(alias_to_table.get(a, "")).startswith("__derived__:")
        ]
        uniq: List[str] = []
        seen_aliases: Set[str] = set()
        for owner in owners:
            owner_l = str(owner or "").strip().lower()
            if owner_l and owner_l not in seen_aliases:
                uniq.append(owner_l)
                seen_aliases.add(owner_l)
        if len(uniq) <= 1:
            continue

        best = _preferred_alias(c_low, uniq)
        if best:
            col.set("table", exp.to_identifier(best))
            meta["fixes"].append(f"ambiguous_unqualified_qualified:{best}.{c_low}")
        else:
            meta["warnings"].append(f"ambiguous_unqualified_unresolved:{c_low}")

    # -----------------------------
    # 2) Ambiguous ORDER BY disambiguation
    # -----------------------------
    def _unique_alias_name(candidates: List[str]) -> Optional[str]:
        uniq: List[str] = []
        seen_aliases: Set[str] = set()
        for cand in candidates or []:
            cand_name = str(cand or "").strip("`")
            cand_low = cand_name.lower()
            if not cand_low or cand_low in seen_aliases:
                continue
            seen_aliases.add(cand_low)
            uniq.append(cand_name)
        if len(uniq) == 1:
            return uniq[0]
        return None

    order = sel.args.get("order")
    if order is not None:
        for ord_item in order.expressions or []:
            this_expr = getattr(ord_item, "this", None)
            if this_expr is None:
                continue

            replacement = None
            expr_norm = ""
            try:
                expr_norm = _normalize_sql_expr_for_match(this_expr.sql(dialect="mysql"))
            except Exception:
                expr_norm = ""

            # Prefer the exact projected alias when ORDER BY repeats a projected
            # expression such as COUNT(*) / SUM(...) / DATE_FORMAT(...).
            exact_alias = _unique_alias_name(projection_expr_alias_map.get(expr_norm, []))
            if exact_alias:
                exact_alias_low = exact_alias.lower()
                if not (
                    isinstance(this_expr, exp.Column)
                    and not str(this_expr.table or "").strip()
                    and str(this_expr.name or "").strip("`").lower() == exact_alias_low
                ):
                    replacement = exp.column(exact_alias)
                    meta["fixes"].append(f"order_by_expr_aligned:{exact_alias_low}")

            c_name = str(getattr(this_expr, "name", "") or "").strip("`")
            c_low = c_name.lower()
            table_q = str(getattr(this_expr, "table", "") or "").strip("`")
            if replacement is None and isinstance(this_expr, exp.Column) and c_low:
                proj_candidates = projection_col_map.get(c_low, [])
                proj_norm = {}
                for p in proj_candidates:
                    key = p.sql(dialect="mysql")
                    proj_norm[key] = p

                # For grouped outputs, align raw source ordering like
                # ORDER BY orderDate to a unique grouped projection alias like
                # quarter_number when that grouped alias is the only projected
                # grouping expression sourced from that column.
                grouped_alias = _unique_alias_name(grouped_projection_aliases_by_token.get(c_low, []))
                if grouped_alias and c_low not in projection_aliases:
                    grouped_alias_low = grouped_alias.lower()
                    if not (
                        not table_q and c_low == grouped_alias_low
                    ):
                        replacement = exp.column(grouped_alias)
                        meta["fixes"].append(f"order_by_group_alias_aligned:{c_low}->{grouped_alias_low}")

                if replacement is None and not table_q:
                    if len(proj_norm) == 1:
                        replacement = list(proj_norm.values())[0].copy()
                        meta["fixes"].append(f"order_by_qualified_from_projection:{c_low}")
                    else:
                        owners = col_to_aliases.get(c_low, [])
                        if owners:
                            best = _preferred_alias(c_low, owners)
                            if best:
                                replacement = exp.column(c_name, table=best)
                                if len(set(owners)) > 1:
                                    meta["fixes"].append(f"order_by_ambiguous_qualified:{best}.{c_low}")
                        elif len(set(proj_norm.keys())) > 1:
                            meta["warnings"].append(f"order_by_projection_ambiguous:{c_low}")

            if replacement is not None:
                ord_item.set("this", replacement)

    # -----------------------------
    # 3) Join key sanity warning
    # -----------------------------
    fk_map = {}
    try:
        fk_map = get_fk_relationships() or {}
    except Exception:
        fk_map = {}

    joins = sel.args.get("joins") or []
    for j in joins:
        on_expr = j.args.get("on")
        if on_expr is None:
            continue
        for eq in on_expr.find_all(exp.EQ):
            left = getattr(eq, "left", None)
            right = getattr(eq, "right", None)
            if not isinstance(left, exp.Column) or not isinstance(right, exp.Column):
                continue
            lt_alias = str(left.table or "").strip("`").lower()
            rt_alias = str(right.table or "").strip("`").lower()
            lc = str(left.name or "").strip("`").lower()
            rc = str(right.name or "").strip("`").lower()
            if not lt_alias or not rt_alias or not lc or not rc:
                continue

            lt = alias_to_table.get(lt_alias, lt_alias)
            rt = alias_to_table.get(rt_alias, rt_alias)

            # Skip derived-table aliases in FK sanity checks.
            if str(lt).startswith("__derived__:") or str(rt).startswith("__derived__:"):
                continue

            plausible = False
            # direct fk metadata check
            if lt in fk_map and lc in {str(k).lower() for k in (fk_map.get(lt) or {}).keys()}:
                for fk_col, tgt in (fk_map.get(lt) or {}).items():
                    if str(fk_col).lower() == lc and str(tgt).lower() == rt:
                        plausible = True
                        break
            if not plausible and rt in fk_map and rc in {str(k).lower() for k in (fk_map.get(rt) or {}).keys()}:
                for fk_col, tgt in (fk_map.get(rt) or {}).items():
                    if str(fk_col).lower() == rc and str(tgt).lower() == lt:
                        plausible = True
                        break

            # fallback heuristic for shared id-like fields
            if not plausible and lc == rc and (lc.endswith("id") or lc.endswith("number") or lc.endswith("code")):
                plausible = True

            if not plausible:
                meta["warnings"].append(f"suspicious_join_key:{lt_alias}.{lc}={rt_alias}.{rc}")

    # Return rewritten SQL only when we made deterministic fixes.
    if not meta["fixes"]:
        return sql, meta

    out_sql = ast.sql(dialect="mysql")
    if sql.strip().endswith(";"):
        out_sql = out_sql.rstrip(";").strip() + ";"
    return out_sql, meta

def _strip_unneeded_count_distinct(sql: str, question: str = "") -> str:
    """
    Remove unnecessary DISTINCT in COUNT(DISTINCT id_col) when the question asks
    for a plain row/entity count.

    Schema-driven guardrails:
    - preserve DISTINCT when the question asks for distinct/unique/different
    - preserve conditional COUNT(DISTINCT CASE WHEN ...)
    - single table: COUNT(DISTINCT table_id) -> COUNT(*)
    - single join: COUNT(DISTINCT joined_alias.table_id) -> COUNT(joined_alias.table_id)
    """
    if not sql:
        return sql
    # If the question explicitly asks for distinct counting, preserve the
    # semantics as written. Let the semantic contract layer reason about it,
    # but do not erase DISTINCT pre-emptively.
    if question and _question_wants_count_distinct(question):
        return sql
    # Preserve DISTINCT when the query already uses conditional distinct entity
    # counting. In that shape, the companion COUNT(DISTINCT entity_id) often
    # de-fanouts the same base grain and is not redundant.
    if re.search(r"\bCOUNT\s*\(\s*DISTINCT\s+CASE\s+WHEN\b", sql, flags=re.I):
        return sql

    join_n = join_count(sql)

    if join_n == 0:
        from_pos = _find_top_level_clause(sql, "from")
        if from_pos < 0:
            return sql
        after_from = sql[from_pos + len("from"):]
        m_from = re.match(
            r"""\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?
                (?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?
            """,
            after_from,
            flags=re.I | re.X,
        )
        if not m_from:
            return sql
        table = str(m_from.group("table") or "").strip()
        alias = str(m_from.group("alias") or "").strip()
        if alias and alias.lower() in _RESERVED_ALIASES:
            alias = ""
        id_col = get_id_column(table)
        if not table or not id_col:
            return sql
        valid_qualifiers = {table.lower()}
        if alias:
            valid_qualifiers.add(alias.lower())

        pat_single = re.compile(
            r"""COUNT\s*\(\s*DISTINCT\s+
                (?:(?P<qual>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*\.\s*)?
                (?P<col>`?[A-Za-z_][A-Za-z0-9_]*`?)\s*
                \)
            """,
            flags=re.I | re.X,
        )

        def _repl_single(m: re.Match) -> str:
            qual = str(m.group("qual") or "").strip("`").lower()
            col = str(m.group("col") or "").strip("`")
            if qual and qual not in valid_qualifiers:
                return m.group(0)
            if col.lower() != str(id_col).lower():
                return m.group(0)
            return "COUNT(*)"

        return pat_single.sub(_repl_single, sql)

    if join_n != 1:
        return sql

    alias_to_table = _parse_from_join_aliases(sql)
    # Also support non-aliased FROM/JOIN forms where qualifiers use raw table
    # names (e.g., COUNT(DISTINCT orders.orderNumber)).
    for m_tbl in re.finditer(
        r"\b(?:from|join)\s+(`?[A-Za-z_][A-Za-z0-9_]*`?(?:\.`?[A-Za-z_][A-Za-z0-9_]*`?)?)",
        sql or "",
        flags=re.I,
    ):
        raw = str(m_tbl.group(1) or "").replace("`", "")
        tbl = raw.split(".")[-1].strip()
        if not tbl:
            continue
        alias_to_table.setdefault(tbl, tbl)
        alias_to_table.setdefault(tbl.lower(), tbl)

    if not alias_to_table:
        return sql

    pat = re.compile(
        r"COUNT\s*\(\s*DISTINCT\s+([A-Za-z_][A-Za-z0-9_]*)\.([A-Za-z_][A-Za-z0-9_]*)\s*\)",
        flags=re.I,
    )

    def _repl(m: re.Match) -> str:
        alias = m.group(1)
        col = m.group(2)
        table = alias_to_table.get(alias) or alias_to_table.get(alias.lower())
        if not table:
            return m.group(0)

        id_col = get_id_column(table)
        if not id_col:
            return m.group(0)

        if col.lower() != id_col.lower():
            return m.group(0)

        return f"COUNT({alias}.{col})"

    return pat.sub(_repl, sql)
# =======================================================================
# ========== Phase 7 — Ordering, Limits, and Output Formatting ==========
# ============== UI and execution-safety adjustments only ===============
# =======================================================================
# - question_requests_ordering
# - enforce_window_sequence_direction
# - enforce_requested_order_direction
# - remove_top_level_order_by_if_not_requested
# - explicit_limit_from_question
# - maybe_add_limit
# - collapse_spaces_outside_quotes

def _question_requests_ordering(question: str) -> bool:
    """
    Detect if user explicitly wants final result ordering.
    
    IMPORTANT: "descending/ascending order" in context of RANK/ROW_NUMBER 
    refers to window function ordering, NOT final result ORDER BY.
    """
    q = (question or "").lower().strip()
    if not q:
        return False

    def _phrase_in_question(phrase: str) -> bool:
        p = str(phrase or "").strip().lower()
        if not p:
            return False
        pat = re.escape(p).replace(r"\ ", r"\s+")
        return re.search(rf"\b{pat}\b", q, flags=re.I) is not None

    def _window_ordering_context() -> bool:
        window_context_patterns = [
            str(p).strip()
            for p in ordering_window_context_regex_patterns()
            if str(p).strip()
        ]
        sequence_window_patterns = [
            rf"\b{sequence_term_pattern}\b.*\b(?:sorted|ordered)\s+by\b",
            rf"\b(?:sorted|ordered)\s+by\b.*\b{sequence_term_pattern}\b",
        ]
        return any(re.search(pat, q, flags=re.I) for pat in window_context_patterns) or any(
            re.search(pat, q, flags=re.I) for pat in sequence_window_patterns
        )

    ordinal_token_pattern = r"(?:second|third|fourth|fifth|\d+(?:st|nd|rd|th))"
    row_container_pattern = _regex_alt_from_terms(
        {str(term).strip().lower() for term in HELPERS_ORDERING_ROW_CONTAINER_TERMS if str(term).strip()},
        r"(?:row|rows|record|records|entry|entries|result|results|item|items|tuple|tuples)",
    )
    sequence_term_pattern = _regex_alt_from_terms(
        {str(term).strip().lower() for term in HELPERS_ORDERING_SEQUENCE_TERMS if str(term).strip()},
        r"(?:previous|next|prior|following|lag|lead)",
    )
    
    # --- Pattern 1: Window function context (NOT final ORDER BY) ---
    # If "ascending/descending order" appears with ranking context, skip it
    # E.g., "rank employees ... based on employee number in descending order"
    # E.g., "cumulative payment amount ... ordered by payment date"
    has_window_context = _window_ordering_context()
    ordinal_row_context = bool(
        re.search(rf"\b{ordinal_token_pattern}\b", q, flags=re.I)
        and (
            re.search(rf"\b{row_container_pattern}\b", q, flags=re.I)
            or re.search(r"\b(?:sorted|ordered)\s+by\b", q, flags=re.I)
        )
    )

    final_output_sort_patterns = [
        str(p).strip()
        for p in ordering_final_output_sort_regex_patterns()
        if str(p).strip()
    ]
    if any(re.search(pat, q, flags=re.I) for pat in final_output_sort_patterns):
        return True

    # Strong imperative final-sort cue. This should win even when another
    # sentence contains window-sequence wording like "... ordered by date".
    explicit_sort_command_patterns = [
        str(p).strip()
        for p in ordering_explicit_sort_command_regex_patterns()
        if str(p).strip()
    ]
    if any(re.search(pat, q, flags=re.I) for pat in explicit_sort_command_patterns):
        return True
    
    # --- Pattern 2: Explicit final ordering keywords ---
    # These strongly indicate user wants final ORDER BY
    # NOTE: "ordered by" only counts if NOT in window context
    explicit_sort_keywords = rule_list(
        ("ordering_intent", "explicit_sort_keywords"),
        [
            "order by",
            "arrange by",
            "urut berdasarkan",
            "urutkan berdasarkan",
            "diurutkan berdasarkan",
        ],
    )
    ambiguous_sort_markers = {"sort by", "sorted by", "ordered by"}
    for kw in explicit_sort_keywords:
        kw_l = str(kw or "").strip().lower()
        if not kw_l:
            continue
        if kw_l in ambiguous_sort_markers:
            if _phrase_in_question(kw_l) and not has_window_context and not ordinal_row_context:
                return True
            continue
        if _phrase_in_question(kw_l):
            return True

    # Fallback for ambiguous sort phrases, even if config changes.
    if (
        not has_window_context
        and not ordinal_row_context
        and any(_phrase_in_question(k) for k in ambiguous_sort_markers)
    ):
        return True

    winner_like_context = _question_wants_winner_row(question) or ordinal_row_context
    
    # --- Pattern 3: Superlative / ranking output (implies ORDER BY + LIMIT) ---
    # Keep this conservative. Bare "first"/"last" is too ambiguous because it
    # often appears in projection phrases like "first names" / "last names".
    # Treat "first"/"last" as ordering only in bounded row-selection shapes.
    superlative_keywords = ordering_superlative_keywords()

    first_last_row_selection_patterns = [
        str(p).strip()
        for p in ordering_first_last_row_selection_regex_patterns()
        if str(p).strip()
    ]
    has_first_last_row_selection = any(re.search(pat, q) for pat in first_last_row_selection_patterns)

    has_superlative = any(_phrase_in_question(k) for k in superlative_keywords)
    has_numeric_selection = bool(
        re.search(r"\b(?:top|bottom)\s+\d+\b", q, flags=re.I)
        or re.search(r"\b(?:first|last)\s+\d+\b", q, flags=re.I)
        or re.search(r"\b\d+\b(?:[\w\s]{0,24})\b(?:highest|lowest|largest|smallest|newest|latest|earliest|oldest|most|least|top|bottom)\b", q, flags=re.I)
    )
    if (
        not winner_like_context
        and not has_window_context
        and has_superlative
        and (has_numeric_selection or has_first_last_row_selection)
    ):
        return True

    if has_first_last_row_selection and not winner_like_context:
        return True
    
    # --- Pattern 4: Explicit sort direction (only if NOT in window context) ---
    # "ascending", "descending" without window function context
    asc_terms = rule_list(
        ("ordering_intent", "direction_keywords", "asc"),
        ["ascending", "asc", "menaik"],
    )
    desc_terms = rule_list(
        ("ordering_intent", "direction_keywords", "desc"),
        ["descending", "desc", "menurun"],
    )
    alphabetic_terms = [
        str(term).strip().lower()
        for term in HELPERS_ORDERING_ALPHABETIC_TERMS
        if str(term).strip()
    ]
    sort_direction_keywords = sorted(set(asc_terms + desc_terms + alphabetic_terms))
    
    if (
        not winner_like_context
        and not has_window_context
        and any(_phrase_in_question(k) for k in sort_direction_keywords)
    ):
        return True
    
    # --- Pattern 5: Phrase-based ordering intent ---
    # "from highest to lowest", "from latest", "from A to Z"
    ordering_phrases = [
        str(p).strip()
        for p in ordering_phrase_regex_patterns()
        if str(p).strip()
    ]
    
    if not has_window_context and not winner_like_context and any(re.search(pat, q) for pat in ordering_phrases):
        return True
    
    return False


def _enforce_window_sequence_direction(sql: str, question: str) -> str:
    """
    Fix LAG/LEAD window ORDER BY direction for sequence-style questions.

    For natural questions like:
      "previous payment amount ... ordered by payment date"
    the sequence should be chronological ascending unless the question
    explicitly says descending.

    Only rewrites ORDER BY inside LAG/LEAD OVER(...), never top-level ORDER BY.
    """
    s = (sql or "").strip()
    q = (question or "").lower()
    if not s or not re.search(r"\b(?:LAG|LEAD)\s*\(", s, flags=re.I):
        return sql
    if not re.search(r"\b(?:previous|prior|next|following)\b", q, flags=re.I):
        return sql
    sequence_cue = re.search(
        r"\bordered\s+by\b|\bbased\s+on\b[^.]{0,80}\border\b|\b(?:date|time|timestamp)[-\s]+order\b",
        q,
        flags=re.I,
    )
    ordered_tail = ""
    if sequence_cue:
        ordered_idx = sequence_cue.start()
        ordered_tail = q[ordered_idx:] if ordered_idx >= 0 else q
        stop_positions: List[int] = []
        for pat in (
            r"[.;!?]",
            r",",
            r"\band\s+(?:sort|order|arrange)\b",
            r"\bthen\s+(?:sort|order|arrange)\b",
            r"\b(?:sort|order|arrange)\s+the\s+(?:final\s+)?(?:result|results|output|rows?)\s+by\b",
        ):
            m = re.search(pat, ordered_tail, flags=re.I)
            if m:
                stop_positions.append(m.start())
        if stop_positions:
            ordered_tail = ordered_tail[:min(stop_positions)]

    if re.search(r"\b(?:descending|desc|reverse)\b", ordered_tail, flags=re.I):
        desired_dir = "DESC"
    elif re.search(r"\b(?:ascending|asc|chronological|earliest\s+first|oldest\s+first)\b", ordered_tail, flags=re.I):
        desired_dir = "ASC"
    else:
        desired_dir = "ASC"

    laglead_pat = re.compile(
        r"""
        (?P<prefix>\b(?:LAG|LEAD)\s*\([^)]*\)\s+OVER\s*\()
        (?P<body>[^)]*?)
        (?P<suffix>\))
        """,
        flags=re.I | re.S | re.X,
    )

    def _rewrite_body(body: str) -> str:
        m = re.search(r"\bORDER\s+BY\b", body, flags=re.I)
        if not m:
            return body
        before = body[:m.end()]
        after = body[m.end():]
        order_items = [x.strip() for x in after.split(",") if x.strip()]
        if not order_items:
            return body
        first = order_items[0]
        rewritten_first = re.sub(r"\s+\b(?:ASC|DESC)\b\s*$", "", first, flags=re.I).rstrip()
        rewritten_first = f"{rewritten_first} {desired_dir}"
        if rewritten_first == first:
            return body
        order_items[0] = rewritten_first
        return before + " " + ", ".join(order_items)

    changed = False

    def _repl(m: re.Match) -> str:
        nonlocal changed
        body = m.group("body") or ""
        new_body = _rewrite_body(body)
        if new_body != body:
            changed = True
        return f"{m.group('prefix')}{new_body}{m.group('suffix')}"

    out = laglead_pat.sub(_repl, s)
    return out if changed else sql


def _repair_offset_window_projection_shape(sql: str, question: str) -> str:
    """
    Repair single-table LAG/LEAD queries that omit the base row context columns.

    Generic rule:
    - only applies to offset-window questions (`previous/prior/next/following`)
    - only for simple single-table SELECTs with one LAG/LEAD window expression
    - ensures row-context columns are visible in output:
      partition keys, window order keys, and the source metric expression
    """
    s = (sql or "").strip()
    q = (question or "").lower()
    if not s or not re.search(r"\b(?:LAG|LEAD)\s*\(", s, flags=re.I):
        return sql
    if not re.search(r"\b(?:previous|prior|next|following)\b", q, flags=re.I):
        return sql
    if not re.search(r"\bfor\s+(?:each|every)\b", q, flags=re.I):
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(s, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql
    if sel.args.get("joins"):
        return sql

    from_expr = sel.args.get("from") or sel.args.get("from_")
    base_src = getattr(from_expr, "this", None) if from_expr is not None else None
    if not isinstance(base_src, exp.Table):
        return sql

    window_expr = None
    for item in sel.expressions:
        base = item.this if isinstance(item, exp.Alias) else item
        found = base if isinstance(base, exp.Window) else base.find(exp.Window)
        if isinstance(found, exp.Window) and isinstance(getattr(found, "this", None), (exp.Lag, exp.Lead)):
            window_expr = found
            break
    if not isinstance(window_expr, exp.Window):
        return sql

    def _window_partition_exprs(win: "exp.Window") -> List["exp.Expression"]:
        raw = win.args.get("partition_by")
        if raw is None:
            raw = win.args.get("partition")
        if raw is None:
            return []
        if isinstance(raw, list):
            return [x for x in raw if isinstance(x, exp.Expression)]
        if isinstance(raw, exp.Partition):
            return [x for x in (raw.expressions or []) if isinstance(x, exp.Expression)]
        if isinstance(raw, exp.Expression):
            exprs = getattr(raw, "expressions", None)
            if isinstance(exprs, list) and exprs:
                return [x for x in exprs if isinstance(x, exp.Expression)]
            return [raw]
        return []

    def _expr_norm(e: "exp.Expression") -> str:
        try:
            return re.sub(r"[\s`]+", "", e.sql(dialect="mysql").lower())
        except Exception:
            return ""

    partition_exprs = [expr.copy() for expr in _window_partition_exprs(window_expr)]
    order_expr = window_expr.args.get("order")
    order_base_exprs: List["exp.Expression"] = []
    if isinstance(order_expr, exp.Order):
        for ordered in order_expr.expressions or []:
            base = getattr(ordered, "this", None)
            if isinstance(base, exp.Expression):
                order_base_exprs.append(base.copy())

    laglead_call = getattr(window_expr, "this", None)
    source_metric_expr = None
    if isinstance(laglead_call, (exp.Lag, exp.Lead)):
        source_metric_expr = getattr(laglead_call, "this", None)
        if isinstance(source_metric_expr, exp.Tuple):
            source_metric_expr = None
        if source_metric_expr is not None:
            source_metric_expr = source_metric_expr.copy()

    required_exprs: List["exp.Expression"] = []
    seen_required: Set[str] = set()
    for expr in partition_exprs + order_base_exprs + ([source_metric_expr] if isinstance(source_metric_expr, exp.Expression) else []):
        if not isinstance(expr, exp.Expression):
            continue
        norm = _expr_norm(expr)
        if not norm or norm in seen_required:
            continue
        seen_required.add(norm)
        required_exprs.append(expr)

    if not required_exprs:
        return sql

    existing_norms: Set[str] = set()
    for item in sel.expressions:
        base = item.this if isinstance(item, exp.Alias) else item
        existing_norms.add(_expr_norm(base))

    missing_required = [expr for expr in required_exprs if _expr_norm(expr) not in existing_norms]
    if not missing_required:
        return sql

    window_items: List["exp.Expression"] = []
    other_items: List["exp.Expression"] = []
    for item in sel.expressions:
        base = item.this if isinstance(item, exp.Alias) else item
        if isinstance(base, exp.Window) and isinstance(getattr(base, "this", None), (exp.Lag, exp.Lead)):
            window_items.append(item.copy())
        else:
            other_items.append(item.copy())

    new_exprs: List["exp.Expression"] = []
    added_norms: Set[str] = set()
    for expr in required_exprs:
        norm = _expr_norm(expr)
        if norm and norm not in added_norms:
            new_exprs.append(expr.copy())
            added_norms.add(norm)
    for item in other_items:
        base = item.this if isinstance(item, exp.Alias) else item
        norm = _expr_norm(base)
        if norm and norm in added_norms:
            continue
        new_exprs.append(item)
        if norm:
            added_norms.add(norm)
    for item in window_items:
        new_exprs.append(item)

    sel.set("expressions", new_exprs)
    try:
        return ast.sql(dialect="mysql")
    except Exception:
        return sql


def _preserve_requested_base_columns_in_running_self_join(sql: str, question: str) -> str:
    """
    Preserve explicitly requested base-row columns for cumulative/running
    self-join aggregates.

    Typical near-miss:
      SELECT p.customerNumber, p.paymentDate, SUM(pp.amount) AS running_total
      FROM payments p JOIN payments pp ...
      GROUP BY p.customerNumber, p.paymentDate

    If the question explicitly asked for a base metric column such as
    `amount`, keep it in the projection and extend GROUP BY conservatively.

    Guardrails:
    - only for running/cumulative intent
    - only when the top-level query has GROUP BY + aggregate
    - only when the same base table is joined to itself
    - only add base-table simple columns explicitly requested before the
      running/cumulative phrase in the question
    """
    s = (sql or "").strip()
    q = (question or "").strip()
    if not s or not q:
        return sql

    q_low = q.lower()
    m_running = re.search(r"\b(?:running|cumulative|kumulatif|akumulatif)\b", q_low, flags=re.I)
    if not m_running:
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(s, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql

    grp = sel.args.get("group")
    if not grp or not getattr(grp, "expressions", None):
        return sql

    if not any(
        isinstance(item.this if isinstance(item, exp.Alias) else item, exp.AggFunc)
        or any(True for _ in (item.this if isinstance(item, exp.Alias) else item).find_all(exp.AggFunc))
        for item in sel.expressions or []
    ):
        return sql

    from_expr = sel.args.get("from") or sel.args.get("from_")
    base_src = getattr(from_expr, "this", None) if from_expr is not None else None
    if not isinstance(base_src, exp.Table):
        return sql

    base_table = str(base_src.name or "").strip()
    base_alias = str(base_src.alias_or_name or base_table).strip()
    if not base_table or not base_alias:
        return sql
    base_table_l = base_table.lower()
    base_alias_l = base_alias.lower()

    same_table_join_aliases: Set[str] = set()
    for join in sel.args.get("joins") or []:
        join_tbl = getattr(join, "this", None)
        if isinstance(join_tbl, exp.Table) and str(join_tbl.name or "").strip().lower() == base_table.lower():
            same_table_join_aliases.add(str(join_tbl.alias_or_name or join_tbl.name or "").strip())
    if not same_table_join_aliases:
        return sql

    def _identifier_parts(text: str) -> List[str]:
        raw = str(text or "").strip()
        if not raw:
            return []
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ").replace("-", " ")
        return [tok for tok in re.findall(r"[a-z0-9]+", raw.lower()) if tok]

    def _identifier_variants(parts: List[str]) -> Set[str]:
        if not parts:
            return set()
        variants: Set[str] = {" ".join(parts)}
        suffix_terms = {str(x or "").strip().lower() for x in identifier_id_like_terms() if str(x or "").strip()}
        if len(parts) >= 2 and parts[-1] in suffix_terms:
            prefix = parts[:-1]
            for suffix in sorted(suffix_terms):
                variants.add(" ".join(prefix + [suffix]))
        return {v.strip() for v in variants if v.strip()}

    try:
        analyzer = get_schema_analyzer()
        table_cols = [
            str(c).strip("`")
            for c in analyzer.get_table_columns(base_table)
            if str(c).strip()
        ]
    except Exception:
        table_cols = []
    if not table_cols:
        return sql

    question_prefix = q_low[:m_running.start()]
    requested_hits: List[Tuple[int, str]] = []
    for col in table_cols:
        col_l = str(col or "").strip().lower()
        if not col_l:
            continue
        best_pos: Optional[int] = None
        for phrase in _identifier_variants(_identifier_parts(col)):
            phrase_regex = re.escape(phrase).replace(r"\ ", r"\s+")
            m_phrase = re.search(rf"\b{phrase_regex}\b", question_prefix, flags=re.I)
            if m_phrase:
                pos = m_phrase.start()
                if best_pos is None or pos < best_pos:
                    best_pos = pos
        if best_pos is not None:
            requested_hits.append((best_pos, col_l))
    if not requested_hits:
        return sql

    selected_base_cols: Set[str] = set()
    agg_index = len(sel.expressions or [])
    for idx, item in enumerate(sel.expressions or []):
        base = item.this if isinstance(item, exp.Alias) else item
        if isinstance(base, exp.Column):
            tbl = str(base.table or "").strip().lower()
            col = str(base.name or "").strip().lower()
            if tbl == base_alias.lower() and col:
                selected_base_cols.add(col)
        contains_agg = isinstance(base, exp.AggFunc) or any(True for _ in base.find_all(exp.AggFunc))
        if contains_agg:
            agg_index = min(agg_index, idx)

    missing_cols: List[str] = []
    for _, col_l in sorted(requested_hits, key=lambda x: (x[0], x[1])):
        if col_l not in selected_base_cols and col_l not in missing_cols:
            missing_cols.append(col_l)
    if not missing_cols:
        return sql

    new_exprs = list(sel.expressions or [])
    group_exprs = list(grp.expressions or [])
    existing_group_norms: Set[str] = set()

    def _norm_expr(e: "exp.Expression") -> str:
        try:
            return re.sub(r"[\s`]+", "", e.sql(dialect="mysql").lower())
        except Exception:
            return ""

    for g in group_exprs:
        existing_group_norms.add(_norm_expr(g))

    insert_at = agg_index
    added_any = False
    for col_l in missing_cols:
        col_expr = exp.column(col_l, table=base_alias)
        col_norm = _norm_expr(col_expr)
        if col_norm and col_norm in {_norm_expr(e.this if isinstance(e, exp.Alias) else e) for e in new_exprs}:
            continue
        new_exprs.insert(insert_at, col_expr)
        insert_at += 1
        if col_norm and col_norm not in existing_group_norms:
            group_exprs.append(col_expr.copy())
            existing_group_norms.add(col_norm)
        added_any = True

    if not added_any:
        return sql

    sel.set("expressions", new_exprs)
    sel.set("group", exp.Group(expressions=group_exprs))
    try:
        return ast.sql(dialect="mysql")
    except Exception:
        return sql


def _enforce_requested_base_projection_in_single_table_window(sql: str, question: str) -> str:
    """
    Preserve explicitly requested base-row columns in single-table window
    queries and allow helper partition/order columns to be dropped when they
    replace requested output columns.

    Typical near-miss:
      SELECT officeCode, jobTitle, COUNT(employeeNumber) OVER (PARTITION BY officeCode)
      FROM employees

    when the question requested:
      employee number, job title, and how many employees work in that same office

    Safety:
    - only single-table, no-join top-level SELECTs
    - requires at least one top-level window expression
    - only simple base-table columns are adjusted
    - only drops unrequested helper columns when a requested base column is
      missing and the helper column is used inside the window partition/order
    """
    s = (sql or "").strip()
    q = (question or "").strip()
    if not s or not q or "over" not in s.lower():
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(s, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql
    if sel.args.get("joins") or sel.args.get("group") or sel.args.get("having") or sel.args.get("distinct"):
        return sql

    from_expr = sel.args.get("from") or sel.args.get("from_")
    base_src = getattr(from_expr, "this", None) if from_expr is not None else None
    if not isinstance(base_src, exp.Table):
        return sql

    base_table = str(base_src.name or "").strip()
    base_alias = str(base_src.alias_or_name or base_table).strip()
    if not base_table or not base_alias:
        return sql
    base_table_l = base_table.lower()
    base_alias_l = base_alias.lower()

    window_exprs = list(sel.find_all(exp.Window))
    if not window_exprs:
        return sql

    requested_segment = _extract_requested_output_segment(q)
    if not requested_segment:
        return sql
    projection_segment = requested_segment
    metric_clause_match = re.search(
        r"(?is)\b(?:and|plus|with)\b\s+(?:the\s+)?"
        r"(?:gap|difference|delta|avg|average|mean|sum|total|count|number|"
        r"percentage|percent|ratio|share|rank|dense\s+rank|row\s+number|"
        r"running\s+total|cumulative|lag|lead|how\s+many|how\s+much|what\s+percentage)\b",
        projection_segment,
    )
    if metric_clause_match:
        projection_segment = projection_segment[:metric_clause_match.start()].strip(" ,.;")
    if projection_segment:
        requested_segment = projection_segment

    try:
        analyzer = get_schema_analyzer()
        table_cols = [
            str(c).strip("`")
            for c in analyzer.get_table_columns(base_table)
            if str(c).strip()
        ]
    except Exception:
        table_cols = []
        analyzer = None
    if not table_cols:
        return sql

    def _identifier_parts(text: str) -> List[str]:
        raw = str(text or "").strip()
        if not raw:
            return []
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", raw)
        raw = raw.replace("_", " ").replace("-", " ")
        return [tok for tok in re.findall(r"[a-z0-9]+", raw.lower()) if tok]

    def _identifier_variants(parts: List[str]) -> Set[str]:
        if not parts:
            return set()
        variants: Set[str] = {" ".join(parts)}
        suffix_terms = {str(x or "").strip().lower() for x in identifier_id_like_terms() if str(x or "").strip()}
        if len(parts) >= 2 and parts[-1] in suffix_terms:
            prefix = parts[:-1]
            for suffix in sorted(suffix_terms):
                variants.add(" ".join(prefix + [suffix]))
        return {v.strip() for v in variants if v.strip()}

    requested_hits: List[Tuple[int, str]] = []
    requested_segment_l = requested_segment.lower()
    requested_token_positions: List[Tuple[int, str]] = [
        (m.start(), m.group(0).lower())
        for m in re.finditer(r"[a-z0-9]+", requested_segment_l)
    ]
    for col in table_cols:
        col_l = str(col or "").strip().lower()
        if not col_l:
            continue
        candidate_texts = [col]
        if analyzer is not None:
            try:
                candidate_texts.extend(analyzer.get_column_synonyms(base_table, col_l) or [])
            except Exception:
                pass
        best_pos: Optional[int] = None
        for text in candidate_texts:
            for phrase in _identifier_variants(_identifier_parts(text)):
                phrase_regex = re.escape(phrase).replace(r"\ ", r"\s+")
                m_phrase = re.search(rf"\b{phrase_regex}\b", requested_segment_l, flags=re.I)
                if m_phrase:
                    pos = m_phrase.start()
                    if best_pos is None or pos < best_pos:
                        best_pos = pos
            if best_pos is None:
                compact = re.sub(r"[^a-z0-9]+", "", str(text or "").lower())
                compact_hits = [
                    (pos, tok) for pos, tok in requested_token_positions
                    if len(tok) >= 3 and tok in compact
                ]
                distinct_hit_roots = {_to_singular(tok) for _pos, tok in compact_hits if tok}
                if len(distinct_hit_roots) >= 2:
                    pos = min(pos for pos, _tok in compact_hits)
                    if best_pos is None or pos < best_pos:
                        best_pos = pos
        if best_pos is not None:
            requested_hits.append((best_pos, col_l))
    if not requested_hits:
        return sql

    requested_cols = [col_l for _pos, col_l in sorted(requested_hits, key=lambda x: (x[0], x[1]))]

    def _norm_expr(e: "exp.Expression") -> str:
        try:
            return re.sub(r"[\s`]+", "", e.sql(dialect="mysql").lower())
        except Exception:
            return ""

    def _is_base_scope(alias_l: str) -> bool:
        alias_l = str(alias_l or "").strip().lower()
        return not alias_l or alias_l == base_alias_l or alias_l == base_table_l

    helper_cols: Set[str] = set()
    for win in window_exprs:
        partition = win.args.get("partition_by")
        part_exprs = []
        if isinstance(partition, exp.Partition):
            part_exprs = list(partition.expressions or [])
        elif isinstance(partition, list):
            part_exprs = list(partition)
        for expr_item in part_exprs:
            if isinstance(expr_item, exp.Column):
                alias_l = str(expr_item.table or "").strip().lower()
                col_l = str(expr_item.name or "").strip().lower()
                if _is_base_scope(alias_l) and col_l:
                    helper_cols.add(col_l)
        order = win.args.get("order")
        if isinstance(order, exp.Order):
            for ordered in order.expressions or []:
                expr_item = ordered.this if isinstance(ordered, exp.Ordered) else ordered
                if isinstance(expr_item, exp.Column):
                    alias_l = str(expr_item.table or "").strip().lower()
                    col_l = str(expr_item.name or "").strip().lower()
                    if _is_base_scope(alias_l) and col_l:
                        helper_cols.add(col_l)

    new_exprs: List["exp.Expression"] = []
    projected_base_cols: List[str] = []
    seen_projected_norms: Set[str] = set()
    window_insert_idx = len(sel.expressions or [])

    for idx, item in enumerate(sel.expressions or []):
        base = item.this if isinstance(item, exp.Alias) else item
        if isinstance(base, exp.Window):
            window_insert_idx = min(window_insert_idx, idx)
        if isinstance(base, exp.Column):
            alias_l = str(base.table or "").strip().lower()
            col_l = str(base.name or "").strip().lower()
            if _is_base_scope(alias_l) and col_l:
                projected_base_cols.append(col_l)
        norm = _norm_expr(base)
        if norm:
            seen_projected_norms.add(norm)
        new_exprs.append(item.copy())

    missing_cols = [col_l for col_l in requested_cols if col_l not in projected_base_cols]
    if not missing_cols:
        return sql

    removable_helper_cols = [
        col_l for col_l in projected_base_cols
        if col_l not in requested_cols and col_l in helper_cols
    ]
    if not removable_helper_cols and not missing_cols:
        return sql

    filtered_exprs: List["exp.Expression"] = []
    removed_helpers: Set[str] = set()
    removable_budget = min(len(removable_helper_cols), len(missing_cols))
    for item in new_exprs:
        base = item.this if isinstance(item, exp.Alias) else item
        if (
            removable_budget > 0
            and isinstance(base, exp.Column)
            and _is_base_scope(str(base.table or "").strip().lower())
        ):
            col_l = str(base.name or "").strip().lower()
            if col_l in removable_helper_cols and col_l not in removed_helpers:
                removed_helpers.add(col_l)
                removable_budget -= 1
                continue
        filtered_exprs.append(item)

    existing_norms = {
        _norm_expr(expr_item.this if isinstance(expr_item, exp.Alias) else expr_item)
        for expr_item in filtered_exprs
    }
    insert_at = min(window_insert_idx, len(filtered_exprs))
    added_any = False
    for col_l in missing_cols:
        col_expr = exp.column(col_l, table=base_alias)
        col_norm = _norm_expr(col_expr)
        if col_norm and col_norm in existing_norms:
            continue
        filtered_exprs.insert(insert_at, col_expr)
        insert_at += 1
        if col_norm:
            existing_norms.add(col_norm)
        added_any = True

    if not added_any and not removed_helpers:
        return sql

    sel.set("expressions", filtered_exprs)
    try:
        return ast.sql(dialect="mysql")
    except Exception:
        return sql


def _rewrite_same_table_group_count_self_join_to_window(sql: str, question: str) -> str:
    """
    Rewrite same-table grouped self-join COUNT rollups into a window count.

    Typical near-miss:
      SELECT e.id, e.role, COUNT(e2.id) AS office_count
      FROM employees e
      JOIN employees e2 ON e.officeCode = e2.officeCode
      WHERE e.id IS NOT NULL
      GROUP BY e.id, e.role

    ->
      SELECT e.id, e.role,
             COUNT(*) OVER (PARTITION BY e.officeCode) AS office_count
      FROM employees e
      WHERE e.id IS NOT NULL

    Guardrails:
    - exactly one self-join on the same base table
    - exactly one COUNT aggregate and no other aggregate/window expression
    - join predicate consists only of left/right equality predicates
    - all non-aggregate projected/grouped columns come from the left alias only
    - WHERE clause must not reference the right alias
    """
    s = (sql or "").strip()
    if not s or re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(s, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql
    if sel.args.get("having") is not None or sel.args.get("distinct") is not None:
        return sql

    joins = sel.args.get("joins") or []
    if len(joins) != 1:
        return sql
    join_obj = joins[0]
    join_kind = str(join_obj.args.get("kind") or "").strip().upper()
    if join_kind in {"RIGHT", "FULL", "CROSS"}:
        return sql

    from_expr = sel.args.get("from") or sel.args.get("from_")
    left_tbl = getattr(from_expr, "this", None) if from_expr is not None else None
    right_tbl = getattr(join_obj, "this", None)
    if not isinstance(left_tbl, exp.Table) or not isinstance(right_tbl, exp.Table):
        return sql
    if str(left_tbl.name or "").strip().lower() != str(right_tbl.name or "").strip().lower():
        return sql

    left_alias = str(left_tbl.alias_or_name or left_tbl.name or "").strip()
    right_alias = str(right_tbl.alias_or_name or right_tbl.name or "").strip()
    if not left_alias or not right_alias or left_alias.lower() == right_alias.lower():
        return sql

    def _flatten_and(expr: "exp.Expression") -> List["exp.Expression"]:
        if isinstance(expr, exp.And):
            return _flatten_and(expr.left) + _flatten_and(expr.right)
        return [expr]

    def _col_side(expr: "exp.Expression") -> Optional[Tuple[str, str]]:
        if not isinstance(expr, exp.Column):
            return None
        alias = str(expr.table or "").strip()
        col = str(expr.name or "").strip()
        if not alias or not col:
            return None
        return alias, col

    on_expr = join_obj.args.get("on")
    if not isinstance(on_expr, exp.Expression):
        return sql

    partition_exprs: List["exp.Expression"] = []
    seen_partition_norms: Set[str] = set()

    def _expr_norm(e: "exp.Expression") -> str:
        try:
            return re.sub(r"[\s`]+", "", e.sql(dialect="mysql").lower())
        except Exception:
            return ""

    for cond in _flatten_and(on_expr):
        if not isinstance(cond, exp.EQ):
            return sql
        lhs = _col_side(cond.left)
        rhs = _col_side(cond.right)
        if not lhs or not rhs:
            return sql
        if lhs[0].lower() == left_alias.lower() and rhs[0].lower() == right_alias.lower():
            left_col, right_col = lhs[1], rhs[1]
        elif rhs[0].lower() == left_alias.lower() and lhs[0].lower() == right_alias.lower():
            left_col, right_col = rhs[1], lhs[1]
        else:
            return sql
        if left_col.lower() != right_col.lower():
            return sql
        part_expr = exp.column(left_col, table=left_alias)
        norm = _expr_norm(part_expr)
        if norm and norm not in seen_partition_norms:
            partition_exprs.append(part_expr)
            seen_partition_norms.add(norm)
    if not partition_exprs:
        return sql

    where_expr = sel.args.get("where")
    if isinstance(where_expr, exp.Expression):
        for col in where_expr.find_all(exp.Column):
            alias = str(col.table or "").strip().lower()
            if alias == right_alias.lower():
                return sql

    def _unwrap_count(expr: "exp.Expression") -> Optional["exp.Count"]:
        if isinstance(expr, exp.Count):
            return expr
        if isinstance(expr, exp.Coalesce):
            counts = list(expr.find_all(exp.Count))
            if len(counts) == 1:
                return counts[0]
        return None

    nonagg_items: List["exp.Expression"] = []
    count_alias = "group_count"
    count_metric_expr: Optional["exp.Expression"] = None
    seen_count = False

    for item in sel.expressions or []:
        base = item.this if isinstance(item, exp.Alias) else item
        if any(True for _ in base.find_all(exp.Window)):
            return sql
        count_node = _unwrap_count(base)
        if count_node is not None:
            if seen_count:
                return sql
            seen_count = True
            if isinstance(item, exp.Alias) and item.alias:
                count_alias = str(item.alias).strip()
            count_arg = getattr(count_node, "this", None)
            if count_arg is None:
                count_metric_expr = exp.Star()
            elif isinstance(count_arg, exp.Star):
                count_metric_expr = exp.Star()
            elif isinstance(count_arg, exp.Column):
                if str(count_arg.table or "").strip().lower() != right_alias.lower():
                    return sql
                count_metric_expr = exp.column(str(count_arg.name or "").strip(), table=left_alias)
            else:
                return sql
            continue

        if isinstance(base, exp.AggFunc) or any(True for _ in base.find_all(exp.AggFunc)):
            return sql
        if not isinstance(base, exp.Column):
            return sql
        if str(base.table or "").strip().lower() != left_alias.lower():
            return sql
        nonagg_items.append(item.copy())

    if not seen_count or count_metric_expr is None or not nonagg_items:
        return sql

    grp = sel.args.get("group")
    if not grp or not getattr(grp, "expressions", None):
        return sql
    group_norms: Set[str] = set()
    for g in grp.expressions or []:
        if not isinstance(g, exp.Column):
            return sql
        if str(g.table or "").strip().lower() != left_alias.lower():
            return sql
        group_norms.add(_expr_norm(g))
    for item in nonagg_items:
        base = item.this if isinstance(item, exp.Alias) else item
        if _expr_norm(base) not in group_norms:
            return sql

    if isinstance(count_metric_expr, exp.Star):
        window_count_this: "exp.Expression" = exp.Star()
    else:
        window_count_this = count_metric_expr.copy()

    window_expr = exp.alias_(
        exp.Window(
            this=exp.Count(this=window_count_this),
            partition_by=exp.Partition(expressions=[e.copy() for e in partition_exprs]),
        ),
        count_alias,
        quoted=False,
    )

    new_select = exp.Select(
        expressions=[item.copy() for item in nonagg_items] + [window_expr]
    ).from_(
        exp.Table(
            this=exp.to_identifier(str(left_tbl.name or "").strip()),
            alias=exp.TableAlias(this=exp.to_identifier(left_alias)),
        )
    )
    if isinstance(where_expr, exp.Expression):
        new_select.set("where", where_expr.copy())
    order_expr = sel.args.get("order")
    if isinstance(order_expr, exp.Order):
        new_select.set("order", order_expr.copy())
    limit_expr = sel.args.get("limit")
    if isinstance(limit_expr, exp.Limit):
        new_select.set("limit", limit_expr.copy())

    try:
        return new_select.sql(dialect="mysql") + ";"
    except Exception:
        return sql


def _rewrite_running_self_join_aggregate_to_window(sql: str, question: str) -> str:
    """
    Rewrite cumulative/running self-join aggregates into a single-table window.

    Typical near-miss:
      SELECT p.k, p.d, p.amount, SUM(pp.amount) AS running_total
      FROM payments p
      JOIN payments pp
        ON p.k = pp.k AND p.d >= pp.d
      GROUP BY p.k, p.d, p.amount

    ->
      SELECT p.k, p.d, p.amount,
             SUM(p.amount) OVER (PARTITION BY p.k ORDER BY p.d) AS running_total
      FROM payments p

    Conservative guardrails:
    - running/cumulative intent only
    - top-level grouped aggregate, no existing window
    - exactly one self-join on the same table
    - non-aggregate projection must come from the left/base alias only
    - join predicate must contain at least one equality partition key and one
      monotonic inequality on left-vs-right columns
    """
    s = (sql or "").strip()
    q = (question or "").lower()
    if not s or not q:
        return sql
    if not any(t in q for t in ["running", "cumulative", "kumulatif", "akumulatif"]):
        return sql
    if re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql

    # Preserve explicitly requested base-row columns (for example `amount`)
    # before collapsing the self-join aggregate into a window query.
    s = _preserve_requested_base_columns_in_running_self_join(s, question)

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(s, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql
    if sel.args.get("where") is not None or sel.args.get("having") is not None:
        return sql

    grp = sel.args.get("group")
    if not grp or not getattr(grp, "expressions", None):
        return sql

    joins = sel.args.get("joins") or []
    if len(joins) != 1:
        return sql

    from_expr = sel.args.get("from") or sel.args.get("from_")
    left_tbl = getattr(from_expr, "this", None) if from_expr is not None else None
    join_tbl = getattr(joins[0], "this", None)
    if not isinstance(left_tbl, exp.Table) or not isinstance(join_tbl, exp.Table):
        return sql
    if str(left_tbl.name or "").strip().lower() != str(join_tbl.name or "").strip().lower():
        return sql

    left_alias = str(left_tbl.alias_or_name or left_tbl.name or "").strip()
    right_alias = str(join_tbl.alias_or_name or join_tbl.name or "").strip()
    if not left_alias or not right_alias or left_alias.lower() == right_alias.lower():
        return sql

    base_table_name = str(left_tbl.name or "").strip()
    exact_col_map: Dict[str, str] = {}
    compact_col_map: Dict[str, List[str]] = {}
    try:
        analyzer = get_schema_analyzer()
        for col in analyzer.get_table_columns(base_table_name):
            col_text = str(col).strip("`").strip()
            if not col_text:
                continue
            exact_col_map[col_text.lower()] = col_text
            compact = re.sub(r"[^a-z0-9]+", "", col_text.lower())
            if compact:
                compact_col_map.setdefault(compact, []).append(col_text)
    except Exception:
        pass

    def _canonical_col_name(raw_col: str) -> str:
        raw = str(raw_col or "").strip().strip("`")
        if not raw:
            return raw
        lower = raw.lower()
        if lower in exact_col_map:
            return exact_col_map[lower]
        compact = re.sub(r"[^a-z0-9]+", "", lower)
        matches = compact_col_map.get(compact, [])
        if len(matches) == 1:
            return matches[0]
        return raw

    def _flatten_and(expr: "exp.Expression") -> List["exp.Expression"]:
        if isinstance(expr, exp.And):
            return _flatten_and(expr.left) + _flatten_and(expr.right)
        return [expr]

    def _col_side(expr: "exp.Expression") -> Optional[Tuple[str, str]]:
        if not isinstance(expr, exp.Column):
            return None
        alias = str(expr.table or "").strip()
        col = str(expr.name or "").strip()
        if not alias or not col:
            return None
        return alias, col

    on_expr = joins[0].args.get("on")
    if not isinstance(on_expr, exp.Expression):
        return sql

    partition_exprs: List["exp.Expression"] = []
    seen_partitions: Set[str] = set()
    order_expr: Optional["exp.Expression"] = None
    order_desc = False

    def _norm_expr(e: "exp.Expression") -> str:
        try:
            return re.sub(r"[\s`]+", "", e.sql(dialect="mysql").lower())
        except Exception:
            return ""

    for cond in _flatten_and(on_expr):
        if isinstance(cond, exp.EQ):
            lhs = _col_side(cond.left)
            rhs = _col_side(cond.right)
            if not lhs or not rhs:
                continue
            if lhs[0].lower() == left_alias.lower() and rhs[0].lower() == right_alias.lower() and lhs[1].lower() == rhs[1].lower():
                part_expr = exp.column(_canonical_col_name(lhs[1]), table=left_alias)
            elif rhs[0].lower() == left_alias.lower() and lhs[0].lower() == right_alias.lower() and lhs[1].lower() == rhs[1].lower():
                part_expr = exp.column(_canonical_col_name(rhs[1]), table=left_alias)
            else:
                continue
            part_norm = _norm_expr(part_expr)
            if part_norm and part_norm not in seen_partitions:
                partition_exprs.append(part_expr)
                seen_partitions.add(part_norm)
            continue

        if isinstance(cond, (exp.GTE, exp.GT, exp.LTE, exp.LT)):
            lhs = _col_side(cond.left)
            rhs = _col_side(cond.right)
            if not lhs or not rhs:
                continue
            if lhs[1].lower() != rhs[1].lower():
                continue
            if lhs[0].lower() == left_alias.lower() and rhs[0].lower() == right_alias.lower():
                order_expr = exp.column(_canonical_col_name(lhs[1]), table=left_alias)
                order_desc = isinstance(cond, (exp.LTE, exp.LT))
            elif rhs[0].lower() == left_alias.lower() and lhs[0].lower() == right_alias.lower():
                order_expr = exp.column(_canonical_col_name(rhs[1]), table=left_alias)
                order_desc = isinstance(cond, (exp.GTE, exp.GT))

    if not partition_exprs or not isinstance(order_expr, exp.Expression):
        return sql

    nonagg_items: List["exp.Expression"] = []
    agg_item: Optional["exp.Expression"] = None
    agg_alias = "running_total"
    metric_base_expr: Optional["exp.Expression"] = None

    for item in sel.expressions or []:
        base = item.this if isinstance(item, exp.Alias) else item
        contains_agg = isinstance(base, exp.AggFunc) or any(True for _ in base.find_all(exp.AggFunc))
        if contains_agg:
            if agg_item is not None:
                return sql
            agg_item = item
            if isinstance(item, exp.Alias) and item.alias:
                agg_alias = str(item.alias).strip()
            agg_func = base
            if isinstance(base, exp.Coalesce):
                agg_candidates = list(base.find_all(exp.AggFunc))
                if len(agg_candidates) != 1:
                    return sql
                agg_func = agg_candidates[0]
            if not isinstance(agg_func, exp.Sum):
                return sql
            metric_expr = getattr(agg_func, "this", None)
            if not isinstance(metric_expr, exp.Column):
                return sql
            if str(metric_expr.table or "").strip().lower() != right_alias.lower():
                return sql
            metric_base_expr = exp.column(_canonical_col_name(str(metric_expr.name or "").strip()), table=left_alias)
        else:
            if not isinstance(base, exp.Column):
                return sql
            if str(base.table or "").strip().lower() != left_alias.lower():
                return sql
            nonagg_items.append(item.copy())

    if agg_item is None or metric_base_expr is None or not nonagg_items:
        return sql

    group_norms = {_norm_expr(g) for g in grp.expressions or [] if isinstance(g, exp.Expression)}
    for item in nonagg_items:
        base = item.this if isinstance(item, exp.Alias) else item
        if _norm_expr(base) not in group_norms:
            return sql

    window_expr = exp.alias_(
        exp.Window(
            this=exp.Sum(this=metric_base_expr.copy()),
            partition_by=exp.Partition(expressions=[e.copy() for e in partition_exprs]),
            order=exp.Order(expressions=[exp.Ordered(this=order_expr.copy(), desc=order_desc)]),
        ),
        agg_alias,
        quoted=False,
    )

    new_select = exp.Select(expressions=[item.copy() for item in nonagg_items] + [window_expr]).from_(
        exp.Table(this=exp.to_identifier(str(left_tbl.name or "").strip()), alias=exp.TableAlias(this=exp.to_identifier(left_alias)))
    )
    try:
        return new_select.sql(dialect="mysql") + ";"
    except Exception:
        return sql


def _rewrite_correlated_offset_subquery_to_window(sql: str, question: str) -> str:
    """
    Rewrite simple correlated previous/next-row scalar subqueries into
    deterministic LAG/LEAD windows for single-table sequence questions.
    """
    s = (sql or "").strip()
    q = (question or "").lower()
    if not s or re.search(r"\b(?:LAG|LEAD)\s*\(", s, flags=re.I):
        return sql
    if not re.search(r"\b(?:previous|prior|next|following)\b", q, flags=re.I):
        return sql
    if not re.search(r"\bSELECT\s+MAX\s*\(|\bSELECT\s+MIN\s*\(", s, flags=re.I):
        return sql

    compact = re.sub(r"\s+", " ", s).strip().rstrip(";")
    outer_pat = re.compile(
        r"""(?is)^
        SELECT\s+(?P<select>.+?)\s+
        FROM\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?
        (?:\s+(?:AS\s+)?(?P<outer_alias>[A-Za-z_][A-Za-z0-9_]*))?
        \s+WHERE\s+(?P<where>.+?)
        (?:\s+ORDER\s+BY\s+(?P<order>.+))?
        $""",
        flags=re.I | re.S | re.X,
    )
    m_outer = outer_pat.match(compact)
    if not m_outer:
        return sql

    table = str(m_outer.group("table") or "").strip()
    outer_alias = str(m_outer.group("outer_alias") or table).strip()
    where_sql = str(m_outer.group("where") or "").strip()
    final_order_sql = str(m_outer.group("order") or "").strip()

    scalar_pat = re.compile(
        rf"""(?is)^
        `?{re.escape(outer_alias)}`?\.`?(?P<outer_order>[A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*
        \(\s*SELECT\s+(?P<agg>MAX|MIN)\s*\(\s*`?(?P<inner_order>[A-Za-z_][A-Za-z0-9_]*)`?\s*\)\s+
        FROM\s+`?(?P<table2>[A-Za-z_][A-Za-z0-9_]*)`?
        (?:\s+(?:AS\s+)?(?P<inner_alias>[A-Za-z_][A-Za-z0-9_]*))?\s+
        WHERE\s+(?P<inner_where>.+)\)\s*$
        """,
        flags=re.I | re.S | re.X,
    )
    m_scalar = scalar_pat.match(where_sql)
    if not m_scalar:
        return sql
    if str(m_scalar.group("table2") or "").strip().lower() != table.lower():
        return sql

    inner_alias = str(m_scalar.group("inner_alias") or table).strip()
    outer_order_col = str(m_scalar.group("outer_order") or "").strip()
    inner_order_col = str(m_scalar.group("inner_order") or "").strip()
    if not outer_order_col or inner_order_col.lower() != outer_order_col.lower():
        return sql

    inner_where = str(m_scalar.group("inner_where") or "").strip()
    conds = [c.strip() for c in re.split(r"\bAND\b", inner_where, flags=re.I) if c.strip()]
    partition_col = ""
    cmp_direction = ""
    for cond in conds:
        m_eq = re.match(
            rf"(?is)^`?{re.escape(inner_alias)}`?\.`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?\s*=\s*`?{re.escape(outer_alias)}`?\.`?(?P<outer_col>[A-Za-z_][A-Za-z0-9_]*)`?$",
            cond,
        )
        if m_eq and str(m_eq.group("col") or "").lower() == str(m_eq.group("outer_col") or "").lower():
            partition_col = str(m_eq.group("col") or "").strip()
            continue
        m_cmp = re.match(
            rf"(?is)^`?{re.escape(inner_alias)}`?\.`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?\s*(?P<op><|>)\s*`?{re.escape(outer_alias)}`?\.`?(?P<outer_col>[A-Za-z_][A-Za-z0-9_]*)`?$",
            cond,
        )
        if m_cmp and str(m_cmp.group("col") or "").lower() == outer_order_col.lower() and str(m_cmp.group("outer_col") or "").lower() == outer_order_col.lower():
            cmp_direction = str(m_cmp.group("op") or "").strip()

    if not partition_col or not cmp_direction:
        return sql

    wants_previous = bool(re.search(r"\b(?:previous|prior)\b", q, flags=re.I))
    wants_next = bool(re.search(r"\b(?:next|following)\b", q, flags=re.I))
    if wants_previous and cmp_direction != "<":
        return sql
    if wants_next and cmp_direction != ">":
        return sql

    select_items = [x.strip() for x in re.split(r",(?![^()]*\))", str(m_outer.group("select") or "")) if x.strip()]
    metric_expr = ""
    for item in select_items:
        base = re.sub(
            r"""(?is)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            "",
            item,
        ).strip()
        m_col = re.match(
            rf"(?is)^`?{re.escape(outer_alias)}`?\.`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?$",
            base,
        )
        if not m_col:
            continue
        col_name = str(m_col.group("col") or "").strip()
        if col_name.lower() in {partition_col.lower(), outer_order_col.lower()}:
            continue
        metric_expr = base
        break

    if not metric_expr:
        return sql

    partition_expr = f"{outer_alias}.{partition_col}"
    order_expr = f"{outer_alias}.{outer_order_col}"
    offset_func = "LAG" if wants_previous or not wants_next else "LEAD"
    alias_suffix = re.sub(r"[^A-Za-z0-9_]", "_", metric_expr.split(".")[-1].strip("`")) or "value"
    offset_alias = f"{'previous' if offset_func == 'LAG' else 'next'}_{alias_suffix}"

    output_exprs = [
        partition_expr,
        order_expr,
        metric_expr,
        f"{offset_func}({metric_expr}) OVER (PARTITION BY {partition_expr} ORDER BY {order_expr} ASC) AS {offset_alias}",
    ]
    final_order_clause = f" ORDER BY {final_order_sql}" if final_order_sql else ""
    return f"SELECT {', '.join(output_exprs)} FROM {table} AS {outer_alias}{final_order_clause};"


def _rewrite_single_table_case_band_derived_subquery(sql: str, question: str) -> str:
    """
    Flatten single-table CASE-banding derived subqueries into a single SELECT.
    This avoids unnecessary identifier drift on synthetic derived aliases.
    """
    s = (sql or "").strip()
    if not s or "CASE" not in s.upper() or "FROM (" not in s.upper():
        return sql

    try:
        import sqlglot
        from sqlglot import exp
    except Exception:
        return sql

    try:
        ast = sqlglot.parse_one(s, read="mysql")
    except Exception:
        return sql

    sel = ast.find(exp.Select)
    if not isinstance(sel, exp.Select):
        return sql
    if sel.args.get("joins"):
        return sql

    from_expr = sel.args.get("from") or sel.args.get("from_")
    subq = getattr(from_expr, "this", None) if from_expr is not None else None
    if not isinstance(subq, exp.Subquery):
        return sql

    inner_sel = subq.this if isinstance(subq.this, exp.Select) else None
    if not isinstance(inner_sel, exp.Select):
        return sql
    if inner_sel.args.get("joins") or inner_sel.args.get("where") or inner_sel.args.get("group"):
        return sql
    if len(inner_sel.expressions or []) != 1:
        return sql

    inner_item = inner_sel.expressions[0]
    inner_alias_name = inner_item.alias_or_name if isinstance(inner_item, exp.Alias) else ""
    case_expr = inner_item.this if isinstance(inner_item, exp.Alias) else inner_item
    if not inner_alias_name or not isinstance(case_expr, exp.Case):
        return sql

    inner_from = inner_sel.args.get("from") or inner_sel.args.get("from_")
    base_src = getattr(inner_from, "this", None) if inner_from is not None else None
    if not isinstance(base_src, exp.Table):
        return sql

    def _replace_alias_ref(expr_in: "exp.Expression") -> "exp.Expression":
        if isinstance(expr_in, exp.Column) and not expr_in.table and str(expr_in.name or "").lower() == inner_alias_name.lower():
            return case_expr.copy()
        return expr_in.copy()

    new_exprs: List["exp.Expression"] = []
    replaced_select = False
    for item in sel.expressions or []:
        base = item.this if isinstance(item, exp.Alias) else item
        if isinstance(base, exp.Column) and not base.table and str(base.name or "").lower() == inner_alias_name.lower():
            new_exprs.append(inner_item.copy())
            replaced_select = True
        else:
            new_exprs.append(item.copy())
    if not replaced_select:
        return sql

    group_expr = sel.args.get("group")
    if group_expr is None:
        return sql
    group_items = []
    for expr_item in group_expr.expressions or []:
        group_items.append(_replace_alias_ref(expr_item))
    if not group_items:
        return sql

    if sel.args.get("from") is not None:
        sel.set("from", inner_from.copy())
    else:
        sel.set("from_", inner_from.copy())
    sel.set("expressions", new_exprs)
    try:
        sel.set("group", exp.Group(expressions=group_items))
    except Exception:
        return sql

    try:
        return ast.sql(dialect="mysql")
    except Exception:
        return sql


def _enforce_requested_order_direction(sql: str, question: str) -> str:
    """
    Enforce explicit final ORDER BY directions from the question on the
    top-level ORDER BY clause.

    Conservative behavior:
    - only applies when the question explicitly says ascending/descending
      (or alphabetical/alphabetically)
    - only rewrites top-level ORDER BY, never window ORDER BY inside OVER(...)
    - preserves columns/expressions; only fixes direction tokens
    - supports multiple ORDER BY items by position when the question provides
      multiple ordered segments (split by ',' and 'then')
    """
    if not sql:
        return sql

    q = (question or "").lower()
    if not q:
        return sql

    supplemental_window_patterns = [
        r"\brank\b[^.]{0,96}\bby\b[^.]{0,64}\b(?:ascending|descending|asc|desc)\b",
        r"\brow[_\s]?number\b[^.]{0,96}\bby\b[^.]{0,64}\b(?:ascending|descending|asc|desc)\b",
        r"\bdense[_\s]?rank\b[^.]{0,96}\bby\b[^.]{0,64}\b(?:ascending|descending|asc|desc)\b",
        r"\bwithin\s+(?:each|the\s+same)\b[^.]{0,96}\bby\b[^.]{0,64}\b(?:ascending|descending|asc|desc)\b",
        r"\brank\b[^.]{0,96}\bordered\s+by\b",
        r"\brow[_\s]?number\b[^.]{0,96}\bordered\s+by\b",
        r"\bdense[_\s]?rank\b[^.]{0,96}\bordered\s+by\b",
    ]
    configured_window_patterns = [
        str(p).strip()
        for p in rule_list(("ordering_intent", "window_context_regex"), [])
        if str(p).strip()
    ]
    has_window_context = any(
        re.search(pat, q, flags=re.I)
        for pat in list(dict.fromkeys(configured_window_patterns + supplemental_window_patterns))
    )

    def _extract_sort_clause(text: str) -> str:
        patterns = [
            r"\b(?:sort(?:ed)?\s+by|arrange\s+by|order\s+by)\b",
            r"\b(?:sort|arrange|order)\s+so\s+(?P<body>.+)",
            r"\b(?:sort(?:ed)?|arrange|order(?:ed)?)\s+(?:the\s+)?(?:final\s+)?(?:result|results|output|rows?)\s+by\b",
            r"\border\s+the\s+(?:result|results|output|rows?)\s+by\b",
            r"\bordered\s+by\b",
        ]
        for pat in patterns:
            m = re.search(pat, text, flags=re.I)
            if not m:
                continue
            if "ordered by" in m.group(0).lower() and has_window_context:
                continue
            if "body" in m.re.groupindex:
                tail = m.group("body") or ""
            else:
                tail = text[m.end():]
            end = len(tail)
            stop = re.search(r"[.;!?]", tail)
            if stop:
                end = stop.start()
            return tail[:end].strip()
        return ""

    def _split_top_level_csv(text: str) -> List[str]:
        parts: List[str] = []
        cur: List[str] = []
        depth = 0
        quote = ""
        for i, ch in enumerate(text):
            if quote:
                cur.append(ch)
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                cur.append(ch)
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            if ch == "," and depth == 0:
                part = "".join(cur).strip()
                if part:
                    parts.append(part)
                cur = []
                continue
            cur.append(ch)
        tail = "".join(cur).strip()
        if tail:
            parts.append(tail)
        return parts

    sort_clause = _extract_sort_clause(q)
    explicit_dirs: List[str] = []
    sort_parts: List[str] = []
    if sort_clause:
        segments = re.split(r"\bthen\b|\band\b", sort_clause, flags=re.I)
        for seg in segments:
            for part in _split_top_level_csv(seg):
                s = part.strip().lower()
                if not s:
                    continue
                sort_parts.append(s)
                if re.search(r"\b(?:descending|desc|z\s+to\s+a|reverse\s+alphabetical|reversed\s+alphabetical|reverse)\b", s):
                    explicit_dirs.append("DESC")
                elif re.search(r"\b(?:more|higher|larger|greater|bigger|most)\b.*\bfirst\b", s):
                    explicit_dirs.append("DESC")
                elif re.search(r"\b(?:ascending|asc|alphabetical|alphabetically|alphabetized|alphabetize|a\s+to\s+z)\b", s):
                    explicit_dirs.append("ASC")
                elif re.search(r"\b(?:less|fewer|lower|smaller|least)\b.*\bfirst\b", s):
                    explicit_dirs.append("ASC")
                else:
                    explicit_dirs.append("")

    if re.search(r"\b(?:more|higher|larger|greater|bigger|most)\b.*\bfirst\b", q, flags=re.I):
        if not explicit_dirs:
            explicit_dirs = ["DESC"]
        elif not explicit_dirs[0]:
            explicit_dirs[0] = "DESC"
    elif re.search(r"\b(?:less|fewer|lower|smaller|least)\b.*\bfirst\b", q, flags=re.I):
        if not explicit_dirs:
            explicit_dirs = ["ASC"]
        elif not explicit_dirs[0]:
            explicit_dirs[0] = "ASC"

    if not explicit_dirs:
        if has_window_context:
            return sql
        has_asc = bool(re.search(r"\b(?:ascending|asc|alphabetical|alphabetically|alphabetized|alphabetize|chronological|chronologically)\b", q))
        has_desc = bool(re.search(r"\b(?:descending|desc|reverse\s+alphabetical|reversed\s+alphabetical|reverse)\b", q))
        # If both directions appear but we failed to parse a concrete sort clause,
        # do not guess a single direction by fallback.
        if has_asc and has_desc:
            return sql
        if has_asc:
            explicit_dirs = ["ASC"]
        elif has_desc:
            explicit_dirs = ["DESC"]
        else:
            return sql

    def _is_position_like_ordering(text: str) -> bool:
        return bool(
            re.search(
                r"\b(?:position|rank|row[_\s]?number|rn|sequence|seq|ordinal)\b",
                (text or ""),
                flags=re.I,
            )
        )

    # Narrow fallback:
    # If question asks final sorting by position/rank but omits direction,
    # default that position-like ORDER item to ASC (standard ranking output order).
    no_desc_requested_in_sort = not any(d == "DESC" for d in explicit_dirs)
    question_requests_position_like_sort = any(_is_position_like_ordering(p) for p in sort_parts)

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        target = kw.upper()
        t_up = text.upper()
        depth = 0
        quote = ""
        i = start
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and t_up.startswith(target, i):
                prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                after = i + len(target)
                next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    s = sql
    order_pos = _find_top_level_kw(s, "ORDER BY")
    if order_pos < 0:
        return sql

    limit_pos = _find_top_level_kw(s, "LIMIT", order_pos + len("ORDER BY"))
    semi_pos = s.rfind(";")
    order_end_candidates = [p for p in (limit_pos, semi_pos) if p >= 0 and p > order_pos]
    order_end = min(order_end_candidates) if order_end_candidates else len(s)

    order_prefix = s[:order_pos + len("ORDER BY")]
    order_clause = s[order_pos + len("ORDER BY"):order_end].strip()
    order_suffix = s[order_end:]
    if not order_clause:
        return sql

    order_items = _split_top_level_csv(order_clause)
    if not order_items:
        return sql

    new_items: List[str] = []
    changed = False
    for idx, item in enumerate(order_items):
        requested = explicit_dirs[idx] if idx < len(explicit_dirs) else ""
        if (
            not requested
            and sort_clause
            and no_desc_requested_in_sort
            and question_requests_position_like_sort
            and _is_position_like_ordering(item)
        ):
            requested = "ASC"
        if not requested and sort_clause:
            requested = "ASC"
        if not requested:
            new_items.append(item)
            continue
        trimmed = item.strip()
        rewritten = re.sub(r"\s+\b(?:ASC|DESC)\b\s*$", "", trimmed, flags=re.I).rstrip()
        rewritten = f"{rewritten} {requested}"
        if rewritten != trimmed:
            changed = True
        new_items.append(rewritten)

    if not changed:
        return sql

    sep = "\n" if "\n" in order_clause else " "
    return f"{order_prefix}{sep}{', '.join(new_items)}{order_suffix}"

def _simplify_default_window_frame(sql: str, question: str = "") -> str:
    """
    Style normalization for cumulative/running window queries:
    Collapse explicit default frame into compact form.

    Example:
      SUM(x) OVER (PARTITION BY k ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
    ->
      SUM(x) OVER (PARTITION BY k ORDER BY d)

    We only apply this for cumulative/running intent to avoid changing unrelated
    window queries where explicit frame text may be intentionally kept.
    """
    if not sql:
        return sql

    q = (question or "").lower()
    has_running_intent = any(t in q for t in ["cumulative", "running", "kumulatif", "akumulatif"])
    if not has_running_intent:
        return sql

    frame_pat = re.compile(
        r"\s+\b(?:ROWS|RANGE)\s+BETWEEN\s+UNBOUNDED\s+PRECEDING\s+AND\s+CURRENT\s+ROW\b",
        flags=re.IGNORECASE,
    )
    out = frame_pat.sub("", sql)
    return out


def _repair_running_window_missing_partition(sql: str, question: str = "") -> str:
    """
    Add a missing PARTITION BY to running/cumulative aggregate windows when the
    question explicitly scopes the running value to an entity group.

    Conservative trigger:
    - running/cumulative intent only
    - simple single-table SELECT
    - aggregate window already has ORDER BY and no PARTITION BY
    - a partition entity phrase resolves to exactly one non-metric, non-order
      selected column
    """
    s = (sql or "").strip()
    q = (question or "").strip().lower()
    if not s or not q:
        return sql

    running_terms = rule_list(
        ("agent_semantics", "running_window_sequence", "running_terms"),
        ["running", "cumulative", "kumulatif", "akumulatif"],
    )
    if not any_phrase_in_text(q, running_terms):
        return sql
    if not re.search(r"\b(?:SUM|COUNT)\s*\(", s, flags=re.I) or not re.search(r"\bOVER\s*\(", s, flags=re.I):
        return sql
    if re.search(r"\bJOIN\b|\bGROUP\s+BY\b|\bHAVING\b", s, flags=re.I):
        return sql

    entity_patterns = rule_list(
        ("agent_semantics", "running_window_sequence", "partition_reference_regex"),
        [
            r"\bfor\s+that\s+(?P<entity>[a-z][a-z0-9_ ]{1,40}?)(?=\s+(?:in|by|on|ordered|sorted|order|date|time|when|where|and|then|,|\.|$))",
            r"\bfor\s+(?:each|every)\s+(?P<entity>[a-z][a-z0-9_ ]{1,40}?)(?=\s+(?:in|by|on|with|ordered|sorted|order|date|time|when|where|and|then|,|\.|$))",
            r"\bper\s+(?P<entity>[a-z][a-z0-9_ ]{1,40}?)(?=\s+(?:in|by|on|with|ordered|sorted|order|date|time|when|where|and|then|,|\.|$))",
            r"\bwithin\s+(?:each|the\s+same)\s+(?P<entity>[a-z][a-z0-9_ ]{1,40}?)(?=\s+(?:in|by|on|with|ordered|sorted|order|date|time|when|where|and|then|,|\.|$))",
        ],
    )
    stop_terms = {
        _to_singular(str(term or "").strip().lower())
        for term in rule_list(
            ("agent_semantics", "running_window_sequence", "partition_entity_stop_terms"),
            ["record", "row", "entry", "item", "result"],
        )
        if str(term or "").strip()
    }

    def _identifier_tokens(text: str) -> List[str]:
        raw = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", str(text or ""))
        raw = raw.replace("_", " ").replace("-", " ")
        return [tok for tok in re.findall(r"[a-z0-9]+", raw.lower()) if tok]

    entity_token_sets: List[Set[str]] = []
    for pattern in entity_patterns:
        pat = str(pattern or "").strip()
        if not pat:
            continue
        try:
            matches = list(re.finditer(pat, q, flags=re.I))
        except re.error:
            continue
        for match in matches:
            if "entity" in match.re.groupindex:
                entity_text = match.group("entity") or ""
            elif match.groups():
                entity_text = match.group(1) or ""
            else:
                entity_text = ""
            tokens = {
                _to_singular(tok)
                for tok in _identifier_tokens(entity_text)
                if _to_singular(tok) not in stop_terms
            }
            if tokens:
                entity_token_sets.append(tokens)
    if not entity_token_sets:
        return sql

    def _strip_identifier(raw: str) -> str:
        return str(raw or "").strip().strip("`")

    window_pat = re.compile(
        r"""(?is)
        (?P<func>\b(?:SUM|COUNT)\s*\()
        (?P<metric>[^()]*(?:\([^()]*\)[^()]*)?)
        (?P<func_close>\)\s*OVER\s*\()
        (?P<body>[^()]*)
        (?P<window_close>\))
        """,
        flags=re.X,
    )

    metric_cols: Set[str] = set()
    order_cols: Set[str] = set()
    needs_repair = False
    for match in window_pat.finditer(s):
        body = str(match.group("body") or "")
        if re.search(r"\bPARTITION\s+BY\b", body, flags=re.I):
            continue
        if not re.search(r"\bORDER\s+BY\b", body, flags=re.I):
            continue
        needs_repair = True
        metric_refs = re.findall(
            r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?",
            str(match.group("metric") or ""),
            flags=re.I,
        )
        metric_cols.update(_strip_identifier(col).lower() for col in metric_refs if _strip_identifier(col))
        order_part = re.split(r"\bORDER\s+BY\b", body, maxsplit=1, flags=re.I)[-1]
        order_refs = re.findall(
            r"(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?([A-Za-z_][A-Za-z0-9_]*)`?",
            order_part,
            flags=re.I,
        )
        order_cols.update(_strip_identifier(col).lower() for col in order_refs if _strip_identifier(col))
    if not needs_repair:
        return sql

    select_match = re.search(
        r"""(?is)^\s*SELECT\s+(?P<select>.*?)\s+FROM\s+`?(?P<table>[A-Za-z_][A-Za-z0-9_]*)`?(?:\s+(?:AS\s+)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?""",
        s,
    )
    if not select_match:
        return sql
    select_part = str(select_match.group("select") or "").strip()
    table_name = _strip_identifier(select_match.group("table") or "")
    alias_name = _strip_identifier(select_match.group("alias") or table_name)
    if not select_part or not table_name:
        return sql

    selected_refs: Dict[str, Tuple[str, str]] = {}
    for item in _split_top_level_commas(select_part):
        raw = str(item or "").strip()
        if not raw or re.search(r"\bOVER\s*\(|\b(?:SUM|COUNT|AVG|MIN|MAX)\s*\(", raw, flags=re.I):
            continue
        expr = re.sub(
            r"""(?is)\s+AS\s+(`[^`]+`|'[^']+'|"[^"]+"|[A-Za-z_][A-Za-z0-9_]*)\s*$""",
            "",
            raw,
        ).strip()
        m_col = re.fullmatch(
            r"""(?is)(?P<ref>(?:`?[A-Za-z_][A-Za-z0-9_]*`?\s*\.\s*)?`?(?P<col>[A-Za-z_][A-Za-z0-9_]*)`?)""",
            expr,
        )
        if not m_col:
            continue
        col_name = _strip_identifier(m_col.group("col") or "")
        ref_sql = re.sub(r"\s+", "", str(m_col.group("ref") or "").strip())
        if col_name:
            selected_refs[col_name.lower()] = (col_name, ref_sql or col_name)
    if not selected_refs:
        return sql

    id_like_terms = {_to_singular(str(term or "").strip().lower()) for term in identifier_id_like_terms()}
    id_like_terms.update({"id", "number", "code", "key"})

    def _entity_match_score(col_name: str) -> int:
        col_tokens = [_to_singular(tok) for tok in _identifier_tokens(col_name)]
        core_tokens = {tok for tok in col_tokens if tok not in id_like_terms}
        if not core_tokens:
            core_tokens = set(col_tokens)
        best = 0
        for entity_tokens in entity_token_sets:
            overlap = core_tokens.intersection(entity_tokens)
            if not overlap:
                continue
            score = 100 + (10 * len(overlap))
            if core_tokens.issubset(entity_tokens) or entity_tokens.issubset(core_tokens):
                score += 30
            if col_tokens and col_tokens[-1] in id_like_terms:
                score += 15
            best = max(best, score)
        return best

    candidates: List[Tuple[int, str, str]] = []
    excluded_cols = metric_cols.union(order_cols)
    for col_lower, (col_name, ref_sql) in selected_refs.items():
        if col_lower in excluded_cols:
            continue
        score = _entity_match_score(col_name)
        if score <= 0:
            continue
        try:
            role = get_column_role(table_name, col_lower)
        except Exception:
            role = ""
        if role in {"id", "identifier", "pk", "primary_key", "primary key", "foreign_key", "fk"}:
            score += 10
        candidates.append((score, col_lower, ref_sql))
    if not candidates:
        return sql

    candidates.sort(key=lambda item: (-item[0], item[1]))
    if len(candidates) > 1 and candidates[0][0] == candidates[1][0]:
        return sql
    partition_ref = candidates[0][2]
    if "." not in partition_ref and alias_name:
        partition_ref = f"{alias_name}.{partition_ref}"

    changed = False

    def _rewrite_window(match: re.Match) -> str:
        nonlocal changed
        body = str(match.group("body") or "").strip()
        if re.search(r"\bPARTITION\s+BY\b", body, flags=re.I):
            return match.group(0)
        if not re.search(r"\bORDER\s+BY\b", body, flags=re.I):
            return match.group(0)
        changed = True
        return (
            f"{match.group('func')}{match.group('metric')}{match.group('func_close')}"
            f"PARTITION BY {partition_ref} {body}{match.group('window_close')}"
        )

    out = window_pat.sub(_rewrite_window, s)
    return out if changed else sql


def _rewrite_same_group_avg_gap_window_to_partition_only(sql: str, question: str = "") -> str:
    """
    For "gap/difference from the same-group average" questions, a running AVG
    window is semantically wrong. Rewrite:

      AVG(x) OVER (PARTITION BY k ORDER BY seq [ROWS ...])

    to:

      AVG(x) OVER (PARTITION BY k)

    This is intentionally narrow:
    - question must mention average + same-group semantics
    - question must include a short gap/difference cue
    - running/cumulative questions are excluded
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    if not q:
        return sql
    if any(t in q for t in ("running", "cumulative", "kumulatif", "akumulatif")):
        return sql
    if not any(re.search(pat, q, flags=re.I) for pat in HELPERS_AVERAGE_INTENT_PATTERNS):
        return sql
    if not any(re.search(pat, q, flags=re.I) for pat in HELPERS_SAME_GROUP_INTENT_PATTERNS):
        return sql
    if not any_phrase_in_text(q, group_average_difference_window_phrases()):
        return sql
    if not re.search(r"\bAVG\s*\(", sql, flags=re.I):
        return sql

    def _find_matching_paren(text: str, open_idx: int) -> int:
        depth = 0
        quote = ""
        i = open_idx
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return -1

    def _find_top_level_order_by(text: str) -> int:
        target = "ORDER BY"
        t_up = text.upper()
        depth = 0
        quote = ""
        i = 0
        while i < len(text):
            ch = text[i]
            if quote:
                if ch == quote and (i == 0 or text[i - 1] != "\\"):
                    quote = ""
                i += 1
                continue
            if ch in {"'", '"', "`"}:
                quote = ch
                i += 1
                continue
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth = max(0, depth - 1)
            elif depth == 0 and t_up.startswith(target, i):
                prev_ok = i == 0 or not (t_up[i - 1].isalnum() or t_up[i - 1] == "_")
                after = i + len(target)
                next_ok = after >= len(t_up) or not (t_up[after].isalnum() or t_up[after] == "_")
                if prev_ok and next_ok:
                    return i
            i += 1
        return -1

    s = str(sql)
    parts: list[str] = []
    cursor = 0
    changed = False
    for m in re.finditer(r"\bAVG\s*\(", s, flags=re.I):
        avg_start = m.start()
        expr_open = s.find("(", m.start())
        if expr_open < 0:
            continue
        expr_close = _find_matching_paren(s, expr_open)
        if expr_close < 0:
            continue
        after_expr = s[expr_close + 1:]
        over_match = re.match(r"\s*OVER\s*\(", after_expr, flags=re.I)
        if not over_match:
            continue
        over_open = expr_close + 1 + over_match.group(0).rfind("(")
        over_close = _find_matching_paren(s, over_open)
        if over_close < 0:
            continue

        over_body = s[over_open + 1:over_close].strip()
        if not re.match(r"(?is)^PARTITION\s+BY\b", over_body):
            continue
        order_pos = _find_top_level_order_by(over_body)
        if order_pos < 0:
            continue

        partition_body = over_body[:order_pos].strip()
        if not partition_body:
            continue

        replacement = f"AVG({s[expr_open + 1:expr_close].strip()}) OVER ({partition_body})"
        parts.append(s[cursor:avg_start])
        parts.append(replacement)
        cursor = over_close + 1
        changed = True

    if not changed:
        return sql

    parts.append(s[cursor:])
    return "".join(parts)

def _remove_top_level_order_by_if_not_requested(sql: str, question: str) -> str:
    """
    Versi Regex Barbar: Memangkas ORDER BY jika user tidak meminta.
    Lebih kuat daripada SQLGlot karena tidak peduli validitas syntax SQL keseluruhan.
    """
    if not sql:
        return sql
        
    q = (question or "").lower()
    explicit_final_order_request = bool(
        re.search(r"\b(?:sort|sorted|arrange)\s+(?:the\s+)?(?:final\s+)?(?:result|results|output|rows?)\s+by\b", q, flags=re.I)
        or re.search(r"\border\s+the\s+(?:final\s+)?(?:result|results|output|rows?)\s+by\b", q, flags=re.I)
        or re.search(r"\bsort\s+by\b", q, flags=re.I)
    )
    window_only_ordering_context = bool(
        re.search(r"\b(?:rank|row[_\s]?number|dense[_\s]?rank)\b", q, flags=re.I)
        and re.search(r"\b(?:within\s+(?:each|the\s+same)|partition\s+by|based\s+on|ordered\s+in)\b", q, flags=re.I)
    )
    # Preserve ORDER BY for global top-N / superlative retrieval asks.
    # These queries rely on ORDER BY + LIMIT semantics even when the user does
    # not explicitly say "sort by ...".
    has_top_n_superlative_intent = bool(
        re.search(r"\b(?:top|bottom)\s+\d+\b", q, flags=re.I)
        or re.search(
            r"\b\d+\s+(?:[a-z][a-z0-9_]*\s+){0,4}"
            r"(?:highest|lowest|largest|smallest|newest|latest|earliest|oldest|most|least)\b",
            q,
            flags=re.I,
        )
        or (
            bool(re.search(r"\b\d+\b", q, flags=re.I))
            and bool(
                re.search(
                    r"\b(?:most\s+expensive|cheapest|highest|lowest|largest|smallest|newest|latest|earliest|oldest)\b",
                    q,
                    flags=re.I,
                )
            )
        )
    )
    has_top_level_limit = bool(re.search(r"(?is)\bLIMIT\s+\d+\b", sql or ""))

    # 1. Cek Intent: Kalau user minta final sort, biarkan.
    if _question_requests_ordering(question) and not (window_only_ordering_context and not explicit_final_order_request):
        return sql
    if has_top_level_limit and has_top_n_superlative_intent and not window_only_ordering_context:
        return sql

    # 2. Hapus ORDER BY
    # Logic: Cari "ORDER BY <apa saja>" sampai ketemu "LIMIT", ";", atau habis string.
    # Pattern penjelasan:
    # \s+ORDER\s+BY\s+  -> Cari kata ORDER BY (case insensitive)
    # .*?               -> Ambil semua karakter setelahnya (non-greedy)
    # (?=...)           -> Berhenti (Lookahead) jika ketemu...
    #   (?:\s+LIMIT\b|;|$) -> Kata LIMIT, titik koma, atau akhir string.
    
    # IMPORTANT: Only remove TOP-LEVEL ORDER BY, not ORDER BY inside OVER(...)
    # Strategy: Find the last ORDER BY that is NOT inside parentheses
    
    def find_top_level_order_by(s: str) -> Optional[int]:
        """
        Find position of top-level ORDER BY (not inside parentheses).
        Returns start index or None if not found.
        """
        depth = 0
        i = 0
        s_upper = s.upper()
        while i < len(s):
            if s[i] == '(':
                depth += 1
            elif s[i] == ')':
                depth -= 1
            elif depth == 0 and s_upper[i:i+8] == 'ORDER BY':
                # Check it's a word boundary
                if (i == 0 or not s[i-1].isalnum()) and (i+8 >= len(s) or not s[i+8].isalnum()):
                    return i
            i += 1
        return None
    
    order_pos = find_top_level_order_by(sql)
    if order_pos is None:
        return sql  # No top-level ORDER BY found
    
    # Find where ORDER BY clause ends (at LIMIT, ;, or end of string)
    rest = sql[order_pos:]
    # Match ORDER BY ... until LIMIT or ; or end
    m = re.match(r"ORDER\s+BY\s+.*?(?=\s+LIMIT\b|;|$)", rest, flags=re.IGNORECASE | re.DOTALL)
    if not m:
        return sql
    
    # Remove the matched ORDER BY clause
    cleaned = sql[:order_pos].rstrip() + sql[order_pos + m.end():]
    
    if cleaned != sql:
        print("[Logic] Removed unrequested ORDER BY (Regex Force).")
        
    return cleaned


def _strip_empty_string_comparison_on_non_text(sql: str) -> str:
    """
    Remove `col = ''` or `col = ""` comparisons when the column type
    is not text-like (DATE, INT, DECIMAL, etc.).

    MySQL rejects comparisons like `shippedDate = ''` (Incorrect DATE value).
    Only text types (VARCHAR, CHAR, TEXT) should allow empty string comparisons.

    Example:
      WHERE shippedDate IS NULL OR shippedDate = ''
    -> WHERE shippedDate IS NULL
    """
    if not sql or "''" not in sql and '""' not in sql:
        return sql

    m_table = re.search(
        r"\bFROM\s+`?([A-Za-z_][A-Za-z0-9_]*)`?",
        sql,
        flags=re.I,
    )
    if not m_table:
        return sql
    base_table = m_table.group(1).strip().lower()

    alias_to_table = _parse_from_join_aliases(sql)
    alias_to_table_l = {
        str(k or "").strip().lower(): str(v or "").strip().lower()
        for k, v in (alias_to_table or {}).items()
        if str(k or "").strip() and str(v or "").strip()
    }

    def _resolve_table_for_column_ref(col_ref: str) -> str:
        ref = str(col_ref or "").strip().replace("`", "")
        if "." in ref:
            lhs = ref.split(".", 1)[0].strip().lower()
            if lhs in alias_to_table_l:
                return alias_to_table_l[lhs]
            return lhs or base_table
        return base_table

    def _is_confirmed_non_text(col: str, table: str) -> bool:
        """
        Return True only when schema metadata explicitly confirms non-text.
        Unknown/ambiguous types should NOT be treated as non-text.
        """
        t = str(table or "").strip().lower()
        c = str(col or "").strip().lower()
        if not t or not c:
            return False

        dtype = ""
        try:
            dtype = str(get_column_datatype(t, c) or "").upper().strip()
        except Exception:
            dtype = ""

        if dtype:
            if any(tok in dtype for tok in ("CHAR", "TEXT", "CLOB", "STRING")):
                return False
            if any(
                tok in dtype
                for tok in (
                    "INT", "DECIMAL", "NUMERIC", "FLOAT", "DOUBLE", "REAL",
                    "DATE", "TIME", "YEAR", "BOOL", "BIT", "BLOB", "BINARY",
                )
            ):
                return True
            # Unknown dtype token: keep comparison for safety.
            return False

        role = ""
        try:
            role = str(get_column_role(t, c) or "").strip().lower()
        except Exception:
            role = ""
        if role in {"text", "name", "description"}:
            return False
        if role in {"metric", "measure", "amount", "quantity", "date", "time", "id", "key", "code"}:
            return True

        # Unknown metadata => do not strip.
        return False

    def _repl(m: re.Match) -> str:
        prefix = m.group(1) or ""
        col = m.group(2) or ""
        col_clean = str(col).strip().replace("`", "")
        col_stripped = col_clean.split(".")[-1].strip().lower()
        table_for_col = _resolve_table_for_column_ref(col_clean)
        if _is_confirmed_non_text(col_stripped, table_for_col):
            return ""
        return m.group(0)

    col_ref = (
        r"(?:`[^`]+`|[A-Za-z_][A-Za-z0-9_]*)"
        r"(?:\s*\.\s*(?:`[^`]+`|[A-Za-z_][A-Za-z0-9_]*))?"
    )
    s = re.sub(
        r"(\s+OR\s+)" + rf"({col_ref})\s*=\s*''",
        _repl, sql, flags=re.I,
    )
    s = re.sub(
        r"(\s+OR\s+)" + rf'({col_ref})\s*=\s*""',
        _repl, s, flags=re.I,
    )

    # Clean up dangling parentheses: (X OR ) -> (X)
    s = re.sub(r"\(\s*([^()]+?)\s+OR\s*\)", r"(\1)", s, flags=re.I)
    s = re.sub(r"\(\s*([^()]+?)\s+OR\s+\)", r"(\1)", s, flags=re.I)
    # Clean up double spaces
    s = re.sub(r"\s{2,}", " ", s)
    return s


def _repair_explicit_iso_date_filter_from_question(sql: str, question: str) -> str:
    """
    Conservative safety net:
    if the question asks for a direct ISO-date boundary (before/after/on or before/on or after)
    but the SQL expands it into YEAR/MONTH/DAY logic on a single date column,
    collapse it back to a direct date comparison.
    """
    if not sql or not question:
        return sql
    if has_join(sql):
        return sql

    q = str(question or "").strip().lower()
    m_date = re.search(r"\b((?:19|20)\d{2}-\d{2}-\d{2})\b", q)
    if not m_date:
        return sql

    op = None
    prefix = q[:m_date.start()]
    if re.search(r"\bon\s+or\s+after\b", prefix):
        op = ">="
    elif re.search(r"\bon\s+or\s+before\b", prefix):
        op = "<="
    elif re.search(r"\b(?:after|later\s+than)\b", prefix):
        op = ">"
    elif re.search(r"\b(?:before|earlier\s+than)\b", prefix):
        op = "<"
    if not op:
        return sql

    m_where = re.search(
        r"(?is)\bWHERE\b\s+(?P<body>.*?)(?=\bGROUP\s+BY\b|\bHAVING\b|\bORDER\s+BY\b|\bLIMIT\b|;|$)",
        sql,
    )
    if not m_where:
        return sql

    where_body = str(m_where.group("body") or "").strip()
    func_cols = re.findall(
        r"\b(?:YEAR|MONTH|DAY|DAYOFMONTH)\s*\(\s*(?:[A-Za-z_][A-Za-z0-9_]*\.)?([A-Za-z_][A-Za-z0-9_]*)\s*\)",
        where_body,
        flags=re.I,
    )
    func_cols = list(dict.fromkeys(c.lower() for c in func_cols if c))
    if len(func_cols) != 1:
        return sql

    date_col = func_cols[0]
    remainder = re.sub(
        r"\b(?:YEAR|MONTH|DAY|DAYOFMONTH)\s*\(\s*(?:[A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\s*\)\s*"
        r"(?:=|<|<=|>|>=)\s*\d+\b",
        "",
        where_body,
        flags=re.I,
    )
    remainder = re.sub(r"[\s()]+", " ", remainder)
    remainder = re.sub(r"\b(?:and|or)\b", " ", remainder, flags=re.I)
    if re.sub(r"\s+", "", remainder):
        return sql

    rebuilt = f"{date_col} {op} '{m_date.group(1)}'"
    suffix = sql[m_where.end("body"):]
    if suffix and not suffix[:1].isspace():
        suffix = " " + suffix
    return sql[:m_where.start("body")] + rebuilt + suffix


def _repair_enum_process_proxy_filter_from_question(sql: str, question: str) -> str:
    """
    Conservative safety net for negated process-state phrasing.
    Uses schema descriptions to find:
    - a proxy column described like "NULL if not yet <process>"
    - an enum-like descriptive column with enumerated values
    Then canonicalizes narrow or inconsistent filters into:
      enum_col IN (<non-final values>) OR proxy_col IS NULL
    """
    if not sql or not question:
        return sql

    q = str(question or "").strip().lower()
    process_terms: Set[str] = set()
    for pat in (
        r"\b(?:haven['’]t|have\s+not|hasn['’]t|has\s+not|not)\s+been\s+([a-z][a-z\s-]{1,24}?)(?:\s+yet)?\b",
        r"\bnot\s+([a-z][a-z\s-]{1,24}?)\s+yet\b",
        r"\bpending\s+([a-z][a-z\s-]{1,24})\b",
    ):
        m_proc = re.search(pat, q, flags=re.I)
        if not m_proc:
            continue
        for tok in re.findall(r"[a-z]+", str(m_proc.group(1) or "").lower()):
            if len(tok) <= 2:
                continue
            base = tok
            for suffix in ("ing", "ed", "ment", "tion", "s"):
                if base.endswith(suffix) and len(base) > len(suffix) + 2:
                    base = base[: -len(suffix)]
                    break
            process_terms.add(base)
        if process_terms:
            break
    if not process_terms:
        return sql

    m_table = re.search(r"\bFROM\s+`?([A-Za-z_][A-Za-z0-9_]*)`?", sql, flags=re.I)
    if not m_table:
        return sql
    table = m_table.group(1).strip().lower()

    analyzer = get_schema_analyzer()
    table_cols = [str(c or "").strip() for c in analyzer.get_table_columns(table) if str(c or "").strip()]
    if not table_cols:
        return sql

    def _normalize_terms(text: str) -> Set[str]:
        out: Set[str] = set()
        for tok in re.findall(r"[a-z]+", str(text or "").lower()):
            if len(tok) <= 2:
                continue
            base = tok
            for suffix in ("ing", "ed", "ment", "tion", "s"):
                if base.endswith(suffix) and len(base) > len(suffix) + 2:
                    base = base[: -len(suffix)]
                    break
            out.add(base)
        return out

    def _extract_enum_values(desc_text: str) -> List[str]:
        desc_text = str(desc_text or "").strip()
        if not desc_text:
            return []
        for pat in (
            r"\(\s*e\.g\.,?\s*([^)]+?)\s*\)",
            r"\be\.g\.,?\s*([^.;]+)",
            r"\bi\.e\.,?\s*([^.;]+)",
        ):
            m = re.search(pat, desc_text, flags=re.I)
            if not m:
                continue
            parts = [p.strip(" '\"") for p in str(m.group(1) or "").split(",")]
            vals = [re.sub(r"\s+", " ", p).strip() for p in parts if re.sub(r"\s+", " ", p).strip()]
            if vals:
                return vals
        return []

    def _question_mentions_enum_values(values: Sequence[str]) -> bool:
        q_text = str(question or "").strip()
        if not q_text:
            return False
        for value in values or []:
            clean = re.sub(r"\s+", " ", str(value or "").strip())
            if not clean:
                continue
            pat = r"\b" + r"\s+".join(re.escape(part) for part in clean.split()) + r"\b"
            if re.search(pat, q_text, flags=re.I):
                return True
        return False

    proxy_col = ""
    proxy_score = 0
    enum_col = ""
    enum_values: List[str] = []
    enum_score = 0

    for col in table_cols:
        desc = str(get_column_description(table, col) or "").strip()
        if not desc:
            continue
        desc_l = desc.lower()
        if re.search(r"\bnull\s+if\s+not\s+yet\b", desc_l):
            m_proxy = re.search(r"\bnull\s+if\s+not\s+yet\s+([^.;]+)", desc, flags=re.I)
            proxy_terms = _normalize_terms(m_proxy.group(1) if m_proxy else desc)
            score = len(process_terms.intersection(proxy_terms))
            if score > proxy_score:
                proxy_score = score
                proxy_col = col
        vals = _extract_enum_values(desc)
        if len(vals) >= 2:
            score = len(vals)
            if any(term in desc_l for term in ("status", "state", "phase", "condition")):
                score += 5
            if score > enum_score:
                enum_score = score
                enum_col = col
                enum_values = vals

    if not proxy_col or proxy_score <= 0 or not enum_col or len(enum_values) < 2:
        return sql

    excluded_terms = {
        "shipped",
        "resolved",
        "complete",
        "completed",
        "delivered",
        "closed",
        "fulfilled",
        "finalized",
        "finalised",
    }
    candidate_values = [v for v in enum_values if not any(term in v.lower() for term in excluded_terms)]
    if len(candidate_values) < 2:
        return sql
    explicit_enum_mention = _question_mentions_enum_values(candidate_values)

    alias_to_table = _parse_from_join_aliases(sql)
    use_qualified = False
    base_alias = table
    for alias, alias_table in (alias_to_table or {}).items():
        if str(alias_table or "").strip().lower() == table and alias and alias.lower() != table:
            if re.search(rf"\b{re.escape(alias)}\s*\.", sql, flags=re.I):
                use_qualified = True
                base_alias = alias
                break
    enum_ref = f"{base_alias}.{enum_col}" if use_qualified else enum_col
    proxy_ref = f"{base_alias}.{proxy_col}" if use_qualified else proxy_col

    in_list = ", ".join("'" + v.replace("'", "''") + "'" for v in candidate_values)
    col_pat = rf"((?:[A-Za-z_][A-Za-z0-9_]*\.)?`?{re.escape(enum_col)}`?)\s*(?:=|LIKE)\s*'[^']+'"

    m_where = re.search(
        r"(?is)\bWHERE\b\s+(?P<body>.*?)(?=\bGROUP\s+BY\b|\bHAVING\b|\bORDER\s+BY\b|\bLIMIT\b|;|$)",
        sql,
    )
    if m_where:
        where_body = str(m_where.group("body") or "").strip()
        enum_pred_pat = (
            rf"(?is)\(*\s*(?:[A-Za-z_][A-Za-z0-9_]*\.)?`?{re.escape(enum_col)}`?\s*"
            rf"(?:IN\s*\([^)]*\)|=\s*'[^']+'|LIKE\s*'[^']+')\s*\)*"
        )
        proxy_null_pat = (
            rf"(?is)\(*\s*(?:[A-Za-z_][A-Za-z0-9_]*\.)?`?{re.escape(proxy_col)}`?\s+IS\s+NULL\s*\)*"
        )
        reduced = re.sub(enum_pred_pat, " ", where_body, flags=re.I)
        reduced = re.sub(proxy_null_pat, " ", reduced, flags=re.I)
        reduced = re.sub(r"\b(?:and|or)\b", " ", reduced, flags=re.I)
        reduced = re.sub(r"[\s()]+", " ", reduced).strip()
        has_enum_pred = bool(re.search(enum_pred_pat, where_body, flags=re.I))
        has_proxy_null = bool(re.search(proxy_null_pat, where_body, flags=re.I))
        if (
            not reduced
            and (has_enum_pred or has_proxy_null)
            and (has_enum_pred or explicit_enum_mention)
        ):
            canonical = f"{enum_ref} IN ({in_list})"
            canonical = f"({canonical}) OR {proxy_ref} IS NULL"
            suffix = sql[m_where.end('body'):]
            if suffix and not suffix[:1].isspace():
                suffix = " " + suffix
            return sql[:m_where.start('body')] + canonical + suffix

    if not explicit_enum_mention and not re.search(col_pat, sql, flags=re.I):
        return sql
    if not re.search(col_pat, sql, flags=re.I):
        return sql
    return re.sub(col_pat, rf"\1 IN ({in_list})", sql, count=1, flags=re.I)


def _explicit_limit_from_question(question: str) -> Optional[int]:
    q = (question or "").lower()
    m = re.search(r"\blimit\s+(\d{1,4})\b", q)
    if m: return max(1, min(int(m.group(1)), 1_000_000))
    m = re.search(r"\btop\s+(\d{1,4})\b", q)
    if m: return max(1, min(int(m.group(1)), 1_000_000))
    m = re.search(r"\bbottom\s+(\d{1,4})\b", q)
    if m: return max(1, min(int(m.group(1)), 1_000_000))
    m = re.search(
        r"\b(show|first|tampilkan|ambil)\s+(\d{1,4})\b"
        r"(?!\s+(?:characters?|chars?|letters?|digits?|bytes?|positions?|tokens?|words?)\b)",
        q,
    )
    if m: return max(1, min(int(m.group(2)), 1_000_000))
    superlative_alt = "|".join(
        re.escape(term).replace(r"\ ", r"\s+")
        for term in sorted(ordering_superlative_keywords(), key=len, reverse=True)
        if str(term or "").strip()
    )
    if superlative_alt:
        m = re.search(rf"\b(\d{{1,4}})\s+(?:[a-z][a-z0-9_]*\s+){{0,3}}?(?:{superlative_alt})\b", q)
        if m:
            return max(1, min(int(m.group(1)), 1_000_000))
    return None

def _maybe_add_limit(question: str, sql: str) -> str:
    if re.search(r"\blimit\s+\d+\b", sql, flags=re.I):
        return sql
    n = _explicit_limit_from_question(question)
    if n is None:
        return sql
    s = sql.rstrip().rstrip(";")
    return s + f" LIMIT {n};"


def _drop_raw_column_covered_by_function(sql: str, question: str) -> str:
    """
    Drop a raw column from SELECT when a function call on that same column
    is also present and the question does not explicitly request the raw column.

    Example:
      SELECT productLine, textDescription, LEFT(textDescription, 50) AS teaser
    -> SELECT productLine, LEFT(textDescription, 50) AS teaser
    (when question only asks for "leading 50 characters", not full description)
    """
    if not sql:
        return sql

    # Quick check: must have a function call in SELECT
    if not re.search(r"\b(?:LEFT|RIGHT|SUBSTRING|SUBSTR|MID)\s*\(", sql, flags=re.I):
        return sql

    m_sel = re.search(r"(?is)\bSELECT\b\s+(.*?)\s+\bFROM\b", sql)
    if not m_sel:
        return sql
    select_clause = m_sel.group(1).strip()

    items = _split_top_level_commas(select_clause)
    if len(items) < 2:
        return sql

    # Build map: normalized raw column name -> list of SELECT item indices
    raw_col_indices: Dict[str, List[int]] = {}
    func_cols: Dict[str, List[int]] = {}  # column used inside function -> indices

    func_col_pat = re.compile(
        r"(?is)\b(?:LEFT|RIGHT|SUBSTRING|SUBSTR|MID)\s*\(\s*"
        r"(?:[A-Za-z_][A-Za-z0-9_]*\.)?"
        r"([A-Za-z_][A-Za-z0-9_]*)\s*[,)]",
    )

    for idx, item in enumerate(items):
        stripped = item.strip()
        # Check if this is a function call on a column
        m_func = func_col_pat.search(stripped)
        if m_func:
            func_col = m_func.group(1).strip("`").lower()
            func_cols.setdefault(func_col, []).append(idx)
        else:
            # Check if this is a plain column (no function, no expression)
            m_plain = re.match(
                r"^(?:[A-Za-z_][A-Za-z0-9_]*\.)?`?([A-Za-z_][A-Za-z0-9_]*)`?"
                r"(?:\s+AS\s+.+)?$",
                stripped, flags=re.I,
            )
            if m_plain:
                raw_col = m_plain.group(1).strip("`").lower()
                raw_col_indices.setdefault(raw_col, []).append(idx)

    # Find raw columns that are also used inside functions
    to_drop: Set[int] = set()
    for col, indices in raw_col_indices.items():
        if col in func_cols:
            for idx in indices:
                to_drop.add(idx)

    if not to_drop:
        return sql

    # Check if question explicitly mentions the raw column name
    q = (question or "").lower()
    kept_items = []
    for idx, item in enumerate(items):
        if idx in to_drop:
            # Extract column name
            m_plain = re.match(
                r"^(?:[A-Za-z_][A-Za-z0-9_]*\.)?`?([A-Za-z_][A-Za-z0-9_]*)`?",
                item.strip(), flags=re.I,
            )
            if m_plain:
                col_name = m_plain.group(1).strip("`").lower()
                # Keep if question explicitly asks for this column
                if re.search(rf"\b{re.escape(col_name)}\b", q, flags=re.I):
                    kept_items.append(item)
                    continue
            # Drop this item
            continue
        kept_items.append(item)

    if len(kept_items) == len(items):
        return sql

    new_select = ", ".join(kept_items)
    before = sql[:m_sel.start(1)]
    after = sql[m_sel.end(1):]
    return before + new_select + after
    if re.search(r"\blimit\s+\d+\b", sql, flags=re.I):
        return sql
    n = _explicit_limit_from_question(question)
    if n is None:
        return sql
    s = sql.rstrip().rstrip(";")
    return s + f" LIMIT {n};"


def _drop_unrequested_grouped_limit(sql: str, question: str) -> str:
    """
    Remove a top-level LIMIT from grouped summaries when the question does not
    ask for a row limit. Numeric transformation phrases such as "first 2
    characters" should not constrain the number of result groups.
    """
    s = (sql or "").strip()
    if not s or "limit" not in s.lower() or "group by" not in s.lower():
        return sql

    q = (question or "").lower()
    if _explicit_limit_from_question(question) is not None:
        return sql
    if re.search(
        r"\b(?:top|bottom)\s+\d+\b"
        r"|\b\d+\s+(?:highest|lowest|largest|smallest|most|least|newest|latest|earliest|oldest)\b",
        q,
        flags=re.I,
    ):
        return sql
    if not re.search(r"\b(?:group|summari[sz]e|for\s+each|per|by|bucket|band)\b", q, flags=re.I):
        return sql

    trailing = ";" if s.endswith(";") else ""
    s0 = s[:-1].rstrip() if trailing else s
    limit_pos = _find_top_level_clause(s0, "limit")
    if limit_pos < 0:
        return sql
    limit_tail = s0[limit_pos:]
    if not re.match(r"(?is)^LIMIT\s+\d+(?:\s*,\s*\d+|\s+OFFSET\s+\d+)?\s*$", limit_tail.strip()):
        return sql
    return s0[:limit_pos].rstrip() + trailing

def _collapse_spaces_outside_quotes(s: str) -> str:
    parts = re.split(r"('(?:''|[^'])*')", s)
    for i in range(len(parts)):
        if i % 2 == 0:
            parts[i] = re.sub(r"[ \t]{2,}", " ", parts[i])
    return "".join(parts)


def _minimal_sqlglot_parse_cleanup(sql: str) -> str:
    """
    Apply only syntax-shape cleanup that is safe before AST routing.

    Keep this intentionally narrow:
    - spacing / backtick cleanup
    - malformed offset-window nesting rescue
    - illegal top-level GROUP BY direction tokens

    No semantic rewrite should happen here.
    """
    s = str(sql or "").strip()
    if not s:
        return s

    had_semicolon = bool(re.search(r";\s*$", s))
    s = re.sub(r";+\s*$", "", s).strip()
    s = _fix_bad_backticks(s)
    s = _repair_misnested_offset_window_function(s)
    s = re.sub(
        r"([A-Za-z0-9_`.)])"
        r"(SELECT|FROM|WHERE|GROUP\s+BY|ORDER\s+BY|HAVING|LIMIT|JOIN|INNER\s+JOIN|LEFT\s+JOIN|RIGHT\s+JOIN)(?=\s|\()",
        r"\1 \2",
        s,
        flags=re.I,
    )
    group_pos = _find_top_level_clause(s, "group by")
    if group_pos >= 0:
        group_end_candidates = [
            pos for pos in (
                _find_top_level_clause(s, "having", group_pos + len("group by")),
                _find_top_level_clause(s, "order by", group_pos + len("group by")),
                _find_top_level_clause(s, "limit", group_pos + len("group by")),
                len(s),
            )
            if pos >= 0
        ]
        group_end = min(group_end_candidates) if group_end_candidates else len(s)
        group_body = s[group_pos + len("group by"):group_end].strip()
        if group_body:
            group_items = [item.strip() for item in _split_top_level_commas(group_body) if item.strip()]
            cleaned_items = [
                re.sub(r"\s+\b(?:ASC|DESC)\b\s*$", "", item, flags=re.I).strip()
                for item in group_items
            ]
            rebuilt_group = ", ".join(item for item in cleaned_items if item)
            if rebuilt_group and rebuilt_group != group_body:
                s = s[:group_pos + len("group by")] + " " + rebuilt_group + s[group_end:]
    s = _collapse_spaces_outside_quotes(s)
    s = re.sub(r"\s+", " ", s).strip()
    if had_semicolon and s:
        s += ";"
    return s


def _sqlglot_parse_gate(sql: str) -> Tuple[str, Dict[str, Any]]:
    """
    AST parse gate for post-draft routing.

    Flow:
    - Try parsing the incoming SQL directly.
    - If parsing fails, apply minimal cleanup and retry once.
    - If it still fails, preserve the original SQL and route to regex fallback.
    """
    meta: Dict[str, Any] = {
        "parse_ok": False,
        "route": "regex_fallback",
        "attempt": "initial",
        "cleanup_applied": False,
        "error": "",
    }
    if not sql:
        return sql, meta

    try:
        import sqlglot
    except Exception as e:
        meta["error"] = f"sqlglot_unavailable:{e}"
        return sql, meta

    candidate = str(sql or "").strip()
    if not candidate:
        return candidate, meta

    parse_target = re.sub(r";+\s*$", "", candidate).strip()
    try:
        sqlglot.parse_one(parse_target, read=SQL_PARSE_DIALECT)
        meta["parse_ok"] = True
        meta["route"] = "ast_first"
        return candidate, meta
    except Exception as e:
        meta["error"] = f"parse_error:{e}"

    cleaned = _minimal_sqlglot_parse_cleanup(candidate)
    if not cleaned or cleaned == candidate:
        return sql, meta

    cleaned_parse_target = re.sub(r";+\s*$", "", cleaned).strip()
    try:
        sqlglot.parse_one(cleaned_parse_target, read=SQL_PARSE_DIALECT)
        meta["parse_ok"] = True
        meta["route"] = "ast_first"
        meta["attempt"] = "cleanup_retry"
        meta["cleanup_applied"] = True
        meta["error"] = ""
        return cleaned, meta
    except Exception as e:
        meta["attempt"] = "cleanup_retry"
        meta["cleanup_applied"] = True
        meta["error"] = f"cleanup_parse_error:{e}"
        return sql, meta
# ======================================================================
# ======= Phase 4b — Aggregate in WHERE Fix (MySQL Error 1111) =========
# ======================================================================

def _fix_aggregate_in_where(sql: str) -> str:
    """
    Fix invalid SQL where aggregate functions are used in WHERE clause.
    MySQL Error 1111: Invalid use of group function
    
    WRONG:  SELECT ... FROM ... WHERE AVG(amount) > 50000 GROUP BY ...
    RIGHT:  SELECT ... FROM ... GROUP BY ... HAVING AVG(amount) > 50000
    
    Handles:
    - Simple: WHERE AVG(x) > 50000
    - With other conditions: WHERE status = 'Active' AND AVG(x) > 50000
    """
    if not sql:
        return sql
    
    sql_up = sql.upper()
    
    # Skip jika tidak ada GROUP BY
    if "GROUP BY" not in sql_up:
        return sql
    
    # Skip jika tidak ada WHERE
    if "WHERE" not in sql_up:
        return sql
    
    # Pattern untuk mendeteksi aggregate di WHERE
    agg_funcs = r"(?:AVG|SUM|COUNT|MIN|MAX)"
    
    # Cari WHERE clause (sebelum GROUP BY)
    where_match = re.search(
        r"\bWHERE\s+(.*?)(?=\s+GROUP\s+BY\b)",
        sql,
        flags=re.IGNORECASE | re.DOTALL
    )
    
    if not where_match:
        return sql
    
    where_body = where_match.group(1).strip()

    # Conservative safety: do not rewrite WHERE that contains subqueries.
    # Naive AND-splitting below is unsafe for correlated subqueries and can corrupt SQL.
    if re.search(r"\bSELECT\b", where_body, flags=re.IGNORECASE):
        return sql
    
    # Cari semua aggregate conditions di WHERE
    agg_conditions = []
    non_agg_conditions = []
    
    # Split by AND (simple approach)
    conditions = re.split(r'\s+AND\s+', where_body, flags=re.IGNORECASE)
    
    for cond in conditions:
        cond = cond.strip()
        if not cond:
            continue
        
        # Check if this condition contains an aggregate function
        if re.search(rf"\b{agg_funcs}\s*\(", cond, flags=re.IGNORECASE):
            agg_conditions.append(cond)
        else:
            non_agg_conditions.append(cond)
    
    # Jika tidak ada aggregate di WHERE, return as-is
    if not agg_conditions:
        return sql
    
    print(f"[FIX_AGG_WHERE] Found aggregate in WHERE: {agg_conditions}")
    
    # Build new WHERE clause (tanpa aggregate conditions)
    if non_agg_conditions:
        new_where = "WHERE " + " AND ".join(non_agg_conditions)
    else:
        new_where = ""
    
    # Find GROUP BY dan apa yang setelahnya
    group_match = re.search(
        r"(\bGROUP\s+BY\s+[\w\s,\.`]+?)(\s+HAVING\s+|\s+ORDER\s+BY\s+|\s+LIMIT\s+|\s*;|\s*$)",
        sql,
        flags=re.IGNORECASE
    )
    
    if not group_match:
        return sql
    
    group_clause = group_match.group(1).strip()
    after_group = group_match.group(2)
    
    # Build HAVING clause
    having_conditions = " AND ".join(agg_conditions)
    
    # Check if HAVING already exists
    if re.search(r"\bHAVING\b", after_group, flags=re.IGNORECASE):
        # Prepend to existing HAVING
        new_having = re.sub(
            r"(\bHAVING\s+)",
            rf"\1{having_conditions} AND ",
            after_group,
            flags=re.IGNORECASE
        )
    else:
        # Add new HAVING before ORDER BY/LIMIT/end
        new_having = f" HAVING {having_conditions}{after_group}"
    
    # Get prefix (SELECT ... FROM ... ) - before WHERE
    prefix_match = re.search(r"^(.*?)\bWHERE\b", sql, flags=re.IGNORECASE | re.DOTALL)
    if not prefix_match:
        return sql
    prefix = prefix_match.group(1).strip()
    
    # Get suffix (after GROUP BY clause) 
    suffix_start = group_match.end()
    suffix = sql[suffix_start:].strip()
    
    # Build final SQL
    if new_where:
        result = f"{prefix} {new_where} {group_clause}{new_having}"
    else:
        result = f"{prefix} {group_clause}{new_having}"
    
    # Add remaining suffix if any
    if suffix and not suffix.startswith(";") and suffix not in new_having:
        result = f"{result} {suffix}"
    
    # Clean up multiple spaces
    result = re.sub(r"\s{2,}", " ", result)
    result = result.strip()
    
    # Ensure semicolon
    if not result.endswith(";"):
        result += ";"
    
    print(f"[FIX_AGG_WHERE] Fixed: {result}")

    return result


# ===== Phase 4c — Fix Raw Column WHERE → HAVING for Aggregate Questions =====
# ======================================================================
def _fix_raw_column_where_to_having(sql: str, question: str = "") -> str:
    """
    Fix semantic error: raw column in WHERE should be aggregate in HAVING.

    Pattern:
    - Question asks: "average/sum/total above/below/equal X"
    - SQL has: WHERE <column> > <value> GROUP BY ...
    - Should be: WHERE (maybe other filters) GROUP BY ... HAVING AVG(<column>) > <value>

    Example:
    WRONG: SELECT customer, AVG(amount) FROM payments WHERE amount > 50000 GROUP BY customer
    RIGHT: SELECT customer, AVG(amount) FROM payments GROUP BY customer HAVING AVG(amount) > 50000
    """
    if not sql or not question:
        return sql

    sql_up = sql.upper()

    # Skip jika tidak ada GROUP BY
    if "GROUP BY" not in sql_up:
        return sql

    # Skip jika tidak ada WHERE
    if "WHERE" not in sql_up:
        return sql

    # Conservative gate:
    # - if query already has HAVING, avoid risky surgery.
    # - this fixer is intended for simple WHERE-only aggregate thresholds.
    if "HAVING" in sql_up:
        return sql

    # Detect aggregate intent in question
    question_lower = question.lower()
    agg_intent_patterns = [
        # Pattern: "average/sum/total ... above/below X" (allows words in between)
        r"(?:average|avg|sum|total|count|maximum|minimum|max|min).{0,20}(?:above|below|greater|less|over|under|more|than?|exceeds?|>\s*\d+)",
        # Reverse pattern: "above/below X ... average/sum/total"
        r"(?:above|below|greater|less|over|under|more|than?|exceeds?|>\s*\d+).{0,20}(?:average|avg|sum|total)",
        # Direct pattern with operator: "avg > 50000"
        r"(?:avg|average|sum|total|count|max|min)\s+[><=]",
    ]

    has_agg_intent = any(re.search(p, question_lower) for p in agg_intent_patterns)
    if not has_agg_intent:
        return sql

    # Extract WHERE clause
    where_match = re.search(
        r"\bWHERE\s+(.*?)(?=\s+GROUP\s+BY\b)",
        sql,
        flags=re.IGNORECASE | re.DOTALL
    )

    if not where_match:
        return sql

    where_body = where_match.group(1).strip()

    # Guard against complex WHERE (subquery / OR) that naive split cannot handle safely.
    if re.search(r"\bSELECT\b", where_body, flags=re.IGNORECASE):
        return sql
    if _has_top_level_or(where_body):
        return sql

    # Get columns used in aggregate functions in SELECT
    select_match = re.search(r"\bSELECT\b(.*?)\bFROM\b", sql, flags=re.IGNORECASE | re.DOTALL)
    if not select_match:
        return sql

    select_clause = select_match.group(1)

    # Find aggregate functions and their columns in SELECT
    agg_in_select = {}
    for m in re.finditer(r"(AVG|SUM|COUNT|MIN|MAX)\s*\(\s*([^)]+)\s*\)", select_clause, flags=re.IGNORECASE):
        func = m.group(1).upper()
        col = m.group(2).strip()
        agg_in_select[col.lower()] = func

    if not agg_in_select:
        return sql

    # Find WHERE conditions that use these columns WITHOUT aggregate wrapper
    conditions_to_move = []
    conditions_to_keep = []

    # Split by AND/OR (simple approach)
    separators = r'\s+(AND|OR)\s+'
    parts = re.split(f'({separators})', where_body, flags=re.IGNORECASE)

    i = 0
    while i < len(parts):
        part = parts[i].strip()
        if not part:
            i += 1
            continue

        if part.upper() in ("AND", "OR"):
            conditions_to_keep.append(part)
            i += 1
            continue

        # Check if this condition uses a column that's aggregated in SELECT
        # Pattern: column operator value
        cond_match = re.match(r"^([a-zA-Z_][a-zA-Z0-9_.]*)\s*(=|!=|<>|>=?|<=?|>)\s*(.+)$", part, flags=re.IGNORECASE)
        if cond_match:
            col = cond_match.group(1).lower()
            operator = cond_match.group(2)
            value = cond_match.group(3).strip()

            if col in agg_in_select:
                # This condition should be in HAVING with aggregate wrapper
                agg_func = agg_in_select[col]
                conditions_to_move.append(f"{agg_func}({col}) {operator} {value}")
            else:
                conditions_to_keep.append(part)
        else:
            # Complex condition, keep in WHERE
            conditions_to_keep.append(part)

        i += 1

    if not conditions_to_move:
        return sql

    print(f"[FIX_RAW_WHERE] Moving conditions to HAVING: {conditions_to_move}")

    # Build new SQL
    # Get prefix (before WHERE)
    prefix_match = re.search(r"^(.*?)\bWHERE\b", sql, flags=re.IGNORECASE | re.DOTALL)
    if not prefix_match:
        return sql
    prefix = prefix_match.group(1).strip()

    # Build new WHERE (if anything left)
    new_where = ""
    if conditions_to_keep:
        new_where = "WHERE " + " ".join(conditions_to_keep)

    # Build GROUP BY + HAVING
    group_match = re.search(
        r"\bGROUP\s+BY\s+.*?(?=\s*(?:HAVING|ORDER\s+BY|LIMIT|;|$))",
        sql,
        flags=re.IGNORECASE | re.DOTALL
    )
    if not group_match:
        return sql

    group_clause = group_match.group(0)

    # Build HAVING
    having_clause = " HAVING " + " AND ".join(conditions_to_move)

    # Find what comes after GROUP BY (before HAVING if exists, or ORDER BY/LIMIT)
    after_group_match = re.search(
        r"\bGROUP\s+BY\s+.*?(\s+(?:HAVING|ORDER\s+BY|LIMIT|;|$))",
        sql,
        flags=re.IGNORECASE | re.DOTALL
    )

    if after_group_match:
        after_group = after_group_match.group(1).strip()
        if after_group.upper().startswith("HAVING"):
            # Merge with existing HAVING
            existing_having = re.search(r"\bHAVING\s+(.*?)(?:\s+(?:ORDER\s+BY|LIMIT|;|$))", sql, flags=re.IGNORECASE | re.DOTALL)
            if existing_having:
                existing_cond = existing_having.group(1).strip()
                having_clause = f" HAVING ({' AND '.join(conditions_to_move)}) AND ({existing_cond})"
                # Remove old HAVING position
                after_group = re.sub(r"\bHAVING\s+.*?(?=\s+(?:ORDER\s+BY|LIMIT|;|$))", "", after_group, flags=re.IGNORECASE | re.DOTALL).strip()

        result = f"{prefix} {new_where} {group_clause}{having_clause} {after_group}".strip()
    else:
        result = f"{prefix} {new_where} {group_clause}{having_clause};".strip()

    # Clean up multiple spaces
    result = re.sub(r"\s{2,}", " ", result)
    result = result.strip()
    if not result.endswith(";"):
        result += ";"

    print(f"[FIX_RAW_WHERE] Fixed: {result}")
    return result


# ===== Phase 4d — Add Missing COUNT(*) for GROUP BY Aggregates =====
# ======================================================================
def _add_missing_count_for_group_by(sql: str, question: str = "") -> str:
    """
    Safely add COUNT(*) to SELECT when question asks for count/total in GROUP BY query.

    Guardrails:
    1. Must have GROUP BY (simple aggregate, not window function)
    2. NOT a ranking/comparison query (e.g., "top 3", "more than 5")
    3. Has GROUP BY intent indicators
    4. Question asks for count/total number
    5. COUNT not already in SELECT

    Examples:
    - "For each status, show total number of orders" → Add COUNT(*)
    - "Count orders per status" → Add COUNT(*)
    - "Customers with more than 5 orders" → Skip (needs HAVING/window)
    - "Top 3 customers by count" → Skip (needs ROW_NUMBER)
    """
    if not sql or not question:
        return sql

    def _is_word_boundary(text: str, i: int, n: int) -> bool:
        left_ok = i == 0 or not (text[i - 1].isalnum() or text[i - 1] == "_")
        right_ok = i + n >= len(text) or not (text[i + n].isalnum() or text[i + n] == "_")
        return left_ok and right_ok

    def _find_top_level_kw(text: str, kw: str, start: int = 0) -> int:
        kw_l = kw.lower()
        n = len(kw_l)
        depth = 0
        in_sq = False
        in_dq = False
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "'" and not in_dq:
                if in_sq and i + 1 < len(text) and text[i + 1] == "'":
                    i += 2
                    continue
                in_sq = not in_sq
                i += 1
                continue
            if ch == '"' and not in_sq:
                in_dq = not in_dq
                i += 1
                continue
            if in_sq or in_dq:
                i += 1
                continue
            if ch == "(":
                depth += 1
                i += 1
                continue
            if ch == ")":
                depth = max(0, depth - 1)
                i += 1
                continue
            if depth == 0 and i >= start and i + n <= len(text):
                if text[i:i + n].lower() == kw_l and _is_word_boundary(text, i, n):
                    return i
            i += 1
        return -1

    s = sql.strip()
    select_pos = _find_top_level_kw(s, "select", 0)
    from_pos = _find_top_level_kw(s, "from", max(0, select_pos + 6))
    group_pos = _find_top_level_kw(s, "group by", max(0, from_pos + 4))
    if select_pos < 0 or from_pos < 0 or group_pos < 0:
        return sql

    sql_up = sql.upper()
    question_lower = question.lower()
    select_clause_raw = s[select_pos + len("select"):from_pos].strip()
    counted_entity_terms: Set[str] = set()
    for table_name in re.findall(r"\b(?:FROM|JOIN)\s+`?([A-Za-z_][A-Za-z0-9_]*)`?", s, flags=re.I):
        table_l = str(table_name or "").strip().lower()
        if not table_l:
            continue
        counted_entity_terms.update(_table_object_terms(table_l))

    # GUARDRAIL 1: Must have GROUP BY
    if "GROUP BY" not in sql_up:
        return sql

    def _explicit_count_output_alias() -> str:
        stop_clause_terms = [
            str(t).strip().lower()
            for t in rule_list(
                ("heuristic_repairs", "grouped_count_output", "stop_clause_terms"),
                [],
            )
            if str(t).strip()
        ]
        alias_stop_terms = {
            str(t).strip().lower()
            for t in rule_list(
                ("heuristic_repairs", "grouped_count_output", "alias_stop_terms"),
                [],
            )
            if str(t).strip()
        }
        fallback_alias = str(
            rule_value(("heuristic_repairs", "grouped_count_output", "fallback_alias"), "")
            or ""
        ).strip()
        stop_clause_alt = "|".join(re.escape(t).replace(r"\ ", r"\s+") for t in stop_clause_terms)
        output_part = (
            re.split(
                rf"\b(?:{stop_clause_alt})\b",
                question_lower,
                maxsplit=1,
                flags=re.I,
            )[0]
            if stop_clause_alt
            else question_lower
        )
        def _explicit_total_entity_alias() -> str:
            if not output_part or not counted_entity_terms:
                return ""
            for term in sorted(counted_entity_terms, key=len, reverse=True):
                term_l = str(term or "").strip().lower()
                if not term_l:
                    continue
                term_pat = re.escape(term_l).replace(r"\ ", r"\s+")
                m_total = re.search(
                    rf"\btotal\s+(?:number\s+of\s+)?(?P<entity>{term_pat})\b(?=\s*(?:,|and\b|or\b|$))",
                    output_part,
                    flags=re.I,
                )
                if not m_total:
                    continue
                entity_phrase = str(m_total.group("entity") or "").strip().lower()
                entity_slug = re.sub(r"[^a-z0-9]+", "_", entity_phrase).strip("_")
                if entity_slug:
                    return f"total_{entity_slug}"
            return ""

        total_entity_alias = _explicit_total_entity_alias()
        if not _question_has_count_intent(output_part):
            return total_entity_alias
        m_count = re.search(
            r"\b(?P<phrase>[a-z][a-z0-9_\s-]{0,40}?)\s+(?:row\s+)?count\b",
            output_part,
            flags=re.I,
        )
        if not m_count:
            return total_entity_alias or fallback_alias
        phrase = str(m_count.group("phrase") or "")
        tokens = [
            tok
            for tok in re.findall(r"[a-z0-9]+", phrase.lower())
            if tok not in alias_stop_terms
        ]
        if not tokens:
            return fallback_alias
        return re.sub(r"[^A-Za-z0-9_]+", "_", "_".join(tokens[-3:] + ["count"])).strip("_") or fallback_alias

    explicit_count_alias = _explicit_count_output_alias()

    # GUARDRAIL 2: NOT a ranking/comparison query (needs window function or HAVING)
    comparison_patterns = [
        r"more than\s+\d+",
        r"above\s+\d+",
        r"below\s+\d+",
        r"exceeds?\s+\d+",
        r"greater than\s+\d+",
        r"less than\s+\d+",
        r"top\s+\d+",
        r"bottom\s+\d+",
        r"highest\s+\d+",
        r"lowest\s+\d+",
        r"\d+\s+or more",
        r"\d+\s+or less",
        r"at least\s+\d+",
        r"at most\s+\d+",
    ]
    if not explicit_count_alias and any(re.search(p, question, re.IGNORECASE) for p in comparison_patterns):
        # Likely needs window function, HAVING, or subquery - skip
        return sql

    # GUARDRAIL 3: Shared grouped/iterative intent cues.
    if not _question_has_grouping_intent(question):
        return sql

    # GUARDRAIL 4: Count requests only; generic metric words like "total"
    # should not trigger COUNT(*) rewrites on their own.
    if not explicit_count_alias and not _question_has_count_intent(question_lower):
        return sql

    # GUARDRAIL 5: COUNT not already in SELECT
    select_clause = select_clause_raw.upper()
    if re.search(r"\bOVER\s*\(", select_clause, flags=re.IGNORECASE):
        return sql
    if "COUNT" in select_clause:
        return sql  # COUNT already present

    if explicit_count_alias:
        select_items = _split_top_level_commas(select_clause_raw)
        if not select_items:
            return sql
        select_items.insert(1 if len(select_items) > 1 else len(select_items), f"COUNT(*) AS {explicit_count_alias}")
        result = s[:select_pos + len("select")] + " " + ", ".join(select_items) + " " + s[from_pos:]
        result = re.sub(r"\s{2,}", " ", result).strip()
        if not result.endswith(";"):
            result += ";"
        return result

    # All guardrails passed - safe to add COUNT(*)
    print(f"[ADD_COUNT] Adding COUNT(*) for GROUP BY aggregate")
    result = re.sub(
        r"(SELECT\s+)",
        r"\1COUNT(*) AS total_count, ",
        sql,
        count=1,
        flags=re.IGNORECASE
    )

    # Clean up multiple spaces
    result = re.sub(r"\s{2,}", " ", result)
    result = result.strip()
    if not result.endswith(";"):
        result += ";"

    print(f"[ADD_COUNT] Fixed: {result}")
    return result
